        for name, expected, result in r:
            with self.subTest(name=name):
                self.assertIn(expected[CONCEPT][NAMESPACE], SYNONYM_TO_KEY)
                _process_concept(concept=result[CONCEPT], node=result)
                self.assertEqual(expected, result)
