import os
from typing import List
from typing import Tuple
from macuitest.lib.operating_system.env import env
class CrashReporter:
    def __init__(self, executor):
        self.executor = executor
    def publish_reports(self, logger, crash_reports: List[str]):
        for report in crash_reports:
            self.__publish_crash_report(logger, report)
    def __publish_crash_report(self, logger, report: str):
        name = os.path.basename(report)
        self.executor.sudo(f'chmod 755 "{report}"')
        with open(report) as rep:
            logger.error(
                name,
                extra=dict(
                    attachment={
                        "name": name,
                        "data": rep.read(),
                        "mime": "application/octet-stream",
                    }
                ),
            )
    def archive_crash_reports(self, search_patterns: Tuple[str], where: str):
        for report in self.collect_reports(search_patterns):
            self.executor.execute(f'cp "{report}" "{where}"')
            self.executor.sudo(f'rm "{report}"')
    @staticmethod
    def collect_reports(search_patterns: Tuple[str, ...]) -> List[str]:
        """Collect crash reports grouped by a glob search pattern."""
        crash_reports = []
        for directory in (env.user_diag_reports, env.system_diag_reports):
            for search_pattern in search_patterns:
                for report in glob.glob(f"{directory}/{search_pattern}"):
                    crash_reports.append(report)
        return crash_reports

from __future__ import absolute_import, division, unicode_literals
import re
def is_listy(obj:'Any')->bool:
    """is `obj` 'list'-like"""
    return isinstance(obj, (tuple, list, set))
def level_filter(
        record_stream:'Iterable[record]',
        level:'Union[int, Sequence[int]]')->'Iterable[record]':
    """filter record by level"""
    levels = level if is_listy(level) else (level, )
    levels = list(map(int, levels))
    return filter(lambda record: record.level in levels, record_stream)
def thread_filter(
        record_stream:'Iterable[record]',
        thread:'Union[int, Sequence[int]]')->'Iterable[record]':
    """filter record by thread_id"""
    thread_ids = thread if is_listy(thread) else (thread, )
    thread_ids = list(map(int, thread_ids))
    return filter(lambda record: record.thread_id in thread_ids, record_stream)
def filename_filter(
        record_stream:'Iterable[record]', filename_pattern:str)->'Iterable[record]':
    """filter record by filename pattern"""
    regex = re.compile(filename_pattern)
    return filter(lambda record: regex.fullmatch(record.filename), record_stream)

from __future__ import absolute_import  # NOQA
"""This module implements modifier plugin of filter."""
import re
import click
from swak.plugin import Modifier
def make_effective_patterns(ptrns):
    """Merge & compile patterns, then return them."""
    merged = {}
    for key, regex in ptrns:
        merged[key] = regex
    result = {}
    for key, regex in merged.items():
        result[key] = re.compile(regex)
    return result
class Filter(Modifier):
    """Filter class."""
    def __init__(self, includes, excludes=[]):
        """Init.
        Args:
            includes (list): Regular expressions to include
            excludes (list): Regular expressions to exclude
        """
        self.includes = make_effective_patterns(includes)
        self.excludes = make_effective_patterns(excludes)
    def modify(self, tag, utime, record):
        """Modify data by filtering.
        To exclude, one true condition is enough.
        To include, all inclusive conditions must be true,
        Exclusive conditions override inclusive conditions.
        Args:
            tag (str): data tag
            utime (float): Evnt time stamp.
            record (dict): data record
        Returns:
            If included
                float: Original time
                record: Original record
            If excluded
                None
        """
        if not self.includes and not self.excludes:
            return utime, record
        for key, regexp in self.excludes.items():
            if key in record:
                if regexp.search(record[key]) is not None:
                    return None
        for key, regexp in self.includes.items():
            if key not in record:
                return None
            if regexp.search(record[key]) is None:
                return None
        return utime, record
@click.command(help="Filter data by regular expression.")
@click.option('-i', '--include', nargs=2, type=str, multiple=True,
              help="Key and RegExp to include.")
@click.option('-x', '--exclude', nargs=2, type=str, multiple=True,
              help="Key and RegExp to exclude.")
@click.pass_context
def main(ctx, include, exclude):
    """Plugin entry."""
    return Filter(include, exclude)
if __name__ == '__main__':
    main()

