    with open(f"{files_path}_invite_values.yaml", "w") as yaml_file:
        print(f"Wrote chain invitation constants to {files_path}_invite_values.yaml")
        yaml.dump(invitation_constants, yaml_file)
if __name__ == "__main__":
    main()

