            root / "Cargo.toml",
            root / "Cargo.lock",
            root / "changes" / f"{version}.md",
            root / "CHANGELOG.md",
            root / "changes" / "unreleased",
        ],
    )
    git_run("add", *file_list)
    git_run("commit", "-m", f"Release v{version}")
