import libnacl
PUB_XFER_TXN_ID = "10001"
def check_fs(is_dir: bool, fs_name: str):
    pp = os.path.expanduser(fs_name)
    rights = os.W_OK if is_dir else os.R_OK
    chk_func = os.path.isdir if is_dir else os.path.isfile
    size_check = True if is_dir else os.path.getsize(pp) > 0
    if chk_func(pp) and os.access(pp, rights) and size_check:
        return pp
    raise argparse.ArgumentTypeError("{} not found or access error or file empty".format(pp))
def check_seed(seed: str):
    if len(seed) == 32:
        return seed
    raise argparse.ArgumentTypeError("Seed must be 32 characters long but provided {}".format(len(seed)))
def ensure_is_reply(resp):
    if isinstance(resp, str):
        resp = json.loads(resp)
    if "op" not in resp or resp["op"] != "REPLY":
        raise Exception("Response is not a successful reply: {}".format(resp))
def divide_sequence_into_chunks(seq: Sequence, chunk_size: int):
    return (seq[shift:shift + chunk_size] for shift in range(0, len(seq), chunk_size))
# Copied from Plenum
def rawToFriendly(raw):
    return base58.b58encode(raw).decode("utf-8")
# Copied from Plenum
def random_string(sz: int) -> str:
    assert (sz > 0), "Expected random string size cannot be less than 1"
    rv = libnacl.randombytes(sz // 2).hex()
    return rv if sz % 2 == 0 else rv + hex(libnacl.randombytes_uniform(15))[-1]
def get_txn_field(txn_dict):
    tmp = txn_dict or {}
    return tmp.get('result', {}).get('txn', {}) or tmp.get('txn', {})
def get_type_field(txn_dict):
    return get_txn_field(txn_dict).get('type', None)
def get_txnid_field(txn_dict):
    tmp = txn_dict or {}
    return (tmp.get('result', {}).get('txnMetadata', {}) or tmp.get('txnMetadata', {})).get('txnId', None)
def request_get_type(req):
    if isinstance(req, dict):
        dict_req = req
    elif isinstance(req, str):
        dict_req = json.loads(req)
    else:
        raise RuntimeError("Request of unsupported type")
    txn_type = dict_req.get("operation", {}).get("type", "")
    return txn_type
def gen_input_output(addr_txos, val):
    for address in addr_txos:
        inputs = []
        outputs = []
        total_amount = 0
        tmp_txo = []
        while addr_txos[address] and total_amount < val:
            (source, amount) = addr_txos[address].pop()
            if amount > 0:
                inputs.append(source)
                total_amount += amount
                tmp_txo.append((source, amount))
        if total_amount >= val:
            out_val = total_amount - val
            if out_val > 0:
                outputs = [{"recipient": address, "amount": out_val}]
            return {address: tmp_txo}, inputs, outputs
        else:
            for s_a in tmp_txo:
                addr_txos[address].append(s_a)
    return None, None, None

import collections
from typing import Iterable, Optional, Sequence
from absl import logging
class Vocabulary:
  """Represents a vocabulary that can be built from a dataset."""
  def __init__(self,
               vocab_path: Optional[str] = None,
               tokenized_sequences: Optional[Iterable[Sequence[bytes]]] = None,
               min_freq: int = 1,
               pad_token: bytes = b'<pad>',
               unk_token: bytes = b'<unk>',
               bos_token: bytes = b'<s>',
               eos_token: bytes = b'</s>'):
    """Loads the vocab from disk (if `vocab_path` is given) or builds it from `tokenized_sequences`."""
    self.pad_token = pad_token
    self.unk_token = unk_token
    self.bos_token = bos_token
    self.eos_token = eos_token
    self.special_tokens = (pad_token, unk_token, bos_token, eos_token)
    if vocab_path:
      self.load(vocab_path)
    elif tokenized_sequences is not None:
      self.build(tokenized_sequences, min_freq=min_freq)
    else:
      raise ValueError(
          ('Vocabulary needs either `vocab_path` or `tokenized_sequences` to '
           'be provided, got %r and %r.') % (vocab_path, tokenized_sequences))
  def build(self,
            tokenized_sequences: Iterable[Sequence[bytes]],
            min_freq: int = 1):
    """Builds a vocabulary over tokens with optional minimum frequency.
    Args:
      tokenized_sequences: Iterable of token sequences to build the vocabulary.
      min_freq: The minimum frequency of each token to be included. Default: 1.
    """
    # Count all the tokens.
    counter = collections.Counter()
    for token_sequence in tokenized_sequences:
      counter.update(token_sequence)
    # Add special tokens to the start of vocab.
    vocab = collections.OrderedDict()
    for token in self.special_tokens:
      vocab[token] = len(vocab)
    # Add all other tokens to the vocab if their frequency is >= min_freq.
    for token, freq in sorted(
        # Sort by frequency (from high to low), and then by token string.
        # This makes sure high frequency tokens get a low token ID.
        counter.items(),
        key=lambda token_freq: (-token_freq[1], token_freq[0])):
      if freq >= min_freq:
        vocab[token] = len(vocab)
    logging.info('Number of unfiltered tokens: %d', len(counter))
    logging.info('Vocabulary size: %d', len(vocab))
    self.vocab = vocab
  def _getitem__(self, key: str):
    return self.vocab[key]
  def keys(self):
    return self.vocab.keys()
  def values(self):
    return self.vocab.values()
  def __len__(self):
    return len(self.vocab)
  @property
  def pad_idx(self):
    """The index of the padding token."""
    return self.vocab[self.pad_token]
  @property
  def unk_idx(self):
    """The index of the unknown word token."""
    return self.vocab[self.unk_token]
  @property
  def bos_idx(self):
    """The index of the beginning-of-sequence token."""
    return self.vocab[self.bos_token]
  @property
  def eos_idx(self):
    """The index of the end-of-sequence token."""
    return self.vocab[self.eos_token]
  def load(self, path: str) -> None:
    """Loads a vocabulary (one token per line) from disk."""
    vocab = collections.OrderedDict()
    with open(path, 'rb') as f:
      for i, token in enumerate(f):
        assert isinstance(token, bytes), 'Expected byte tokens.'
        vocab[token.rstrip()] = i
    logging.info('Loaded vocabulary, size: %d', len(vocab))
    self.vocab = vocab
  def save(self, path: str) -> None:
    """Saves the vocabulary to disk."""
    with open(path, 'wb') as f:
      for token in self.vocab:
        assert isinstance(token, bytes), 'Expected byte tokens.'
        f.write(token + b'\n')
    logging.info('Saved vocabulary to %s.', path)

import time
import sublime
import sublime_plugin
from .builtintypes import builtintypes
from ..logger import Logger
from ..helpers import get_settings, is_js_source, FLOWTYPE
logger = Logger()
FLOW_SUGGESTIONS = []
class FlowTypeListener(sublime_plugin.EventListener):
    """Abstracts the plugin listeners."""
    def on_query_completions(self, view, prefix, locations):
        """Suggest a list of types for a variable."""
        if is_js_source(view):
            if get_settings("show_type_completion", True):
                loc = locations[0]
                if not view.match_selector(loc, "source.js"):
                    return []
                logger.logger.debug("Running autocompletion")
                trigger_start = loc - len(prefix)
                line = sublime.Region(
                    view.line(trigger_start).begin(), trigger_start
                )
                if (
                    view.substr(line)
                    .strip()
                    .endswith((":", ".", "(", "{", "[", ","))
                ):
                    if get_settings("complete_with_builtintypes", True):
                        # TODO: only built-in starting with prefix
                        return FLOW_SUGGESTIONS + builtintypes
                    return FLOW_SUGGESTIONS
    def on_selection_modified_async(self, view):
        """Erase highlighted regions and status when modifying selection."""
        if is_js_source(view):
            if get_settings("suggest_autocomplete_on_edit", True):
                # TODO: only run autocomplete if word ends with : and .
                view.run_command("flowtype_autocomplete")
            if get_settings("check_contents_on_edit", False):
                if time.time() - FLOWTYPE["LAST_ERROR_CHECK"] >= 1:
                    view.run_command("flowtype_check_contents")
    def on_post_save_async(self, view):
        """Erase highlighted regions and status when saving file."""
        if is_js_source(view):
            view.erase_regions("flow_type_highlights")
            view.erase_status("flow_type")
            if get_settings("check_contents_on_save", False):
                view.run_command("flowtype_check_contents")

