from __future__ import absolute_import, print_function, unicode_literals
import sys
import traceback
from functools import wraps
from wolframclient.language import wl
from wolframclient.language.exceptions import WolframLanguageException
from wolframclient.serializers import DEFAULT_FORMAT, export
from wolframclient.utils.encoding import force_text, safe_force_text
DEFAULT_UNKNOWN_FAILURE = {
    "wxf": b"8:f\x02s\x07FailureS\x0dPythonFailureA\x01-S\x0fMessageTemplateS\x1aUnexpected error occurred.",
    "wl": b'Failure["PythonFailure", <|"MessageTemplate" -> "Unexpected error occurred."|>]',
}
def safe_wl_execute(function, args=(), opts={}, export_opts={}, exception_class=None):
    __traceback_hidden_variables__ = True
    try:
        return export(function(*args, **opts), **export_opts)
    except Exception as export_exception:
        try:
            try:
                # The user can provide an exception class, and it can be broken, in which case we are running another
                # try / except to return errors that are happening during class serialization
                if isinstance(export_exception, WolframLanguageException):
                    try:
                        export_exception.set_traceback(*sys.exc_info())
                        return export(export_exception, **export_opts)
                    except Exception:
                        pass
                if not exception_class or exception_class is WolframLanguageException:
                    return export(
                        WolframLanguageException(export_exception, exec_info=sys.exc_info()),
                        **export_opts
                    )
                # A custom error class might fail, if this is happening then we can try to use the built in one
                return export(
                    exception_class(export_exception, exec_info=sys.exc_info()), **export_opts
                )
            except Exception as exception_export_err:
                return export(
                    WolframLanguageException(exception_export_err, exec_info=sys.exc_info()),
                    target_format=export_opts.get("target_format", DEFAULT_FORMAT),
                    encoder="wolframclient.serializers.encoders.builtin.encoder",
                )
        except Exception as unknown_exception:
            # This is the last resort.
            # Everything went wrong, including the code that was supposed to return a traceback, or the custom
            # normalizer is doing something it should not. This should never happen.
            try:
                return export(
                    wl.Failure(
                        "PythonFailure",
                        {
                            "MessageTemplate": safe_force_text(unknown_exception),
                            "MessageParameters": {},
                            "FailureCode": safe_force_text(
                                unknown_exception.__class__.__name__
                            ),
                            "Traceback": force_text(traceback.format_exc()),
                        },
                    ),
                    target_format=export_opts.get("target_format", DEFAULT_FORMAT),
                    encoder="wolframclient.serializers.encoders.builtin.encoder",
                )
            except Exception:
                # Something went worst.
                # this might happen with import errors / syntax errors in third party pluging that are loading the
                # exporter and doing some real damage to the dispatcher we are using.
                return DEFAULT_UNKNOWN_FAILURE[
                    export_opts.get("target_format", DEFAULT_FORMAT)
                ]
def to_wl(exception_class=None, **export_opts):
    def outer(function):
        @wraps(function)
        def inner(*args, **opts):
            return safe_wl_execute(
                function=function,
                args=args,
                opts=opts,
                export_opts=export_opts,
                exception_class=exception_class,
            )
        return inner
    return outer

import logging
import time
from functools import wraps
from typing import Any, List
from dispatch.metrics import provider as metrics_provider
from .extensions import sentry_sdk, configure_extensions
from .database import SessionLocal
log = logging.getLogger(__name__)
def fullname(o):
    module = inspect.getmodule(o)
    return f"{module.__name__}.{o.__qualname__}"
def background_task(func):
    """Decorator that sets up the a background task function
    with a database session and exception tracking.
    As background tasks run in their own threads, it does not attempt
    to propagate errors.
    """
    @wraps(func)
    def wrapper(*args, **kwargs):
        background = False
        if not kwargs.get("db_session"):
            db_session = SessionLocal()
            background = True
            kwargs["db_session"] = db_session
        try:
            metrics_provider.counter("function.call.counter", tags={"function": fullname(func)})
            start = time.perf_counter()
            result = func(*args, **kwargs)
            elapsed_time = time.perf_counter() - start
            metrics_provider.timer(
                "function.elapsed.time", value=elapsed_time, tags={"function": fullname(func)}
            )
            return result
        except Exception as e:
            log.exception(e)
        finally:
            if background:
                kwargs["db_session"].close()
    return wrapper
def timer(func: Any):
    """Timing decorator that sends a timing metric."""
    @wraps(func)
    def wrapper(*args, **kwargs):
        start = time.perf_counter()
        result = func(*args, **kwargs)
        elapsed_time = time.perf_counter() - start
        metrics_provider.timer(
            "function.elapsed.time", value=elapsed_time, tags={"function": fullname(func)}
        )
        return result
    return wrapper
def counter(func: Any):
    """Counting decorator that sends a counting metric."""
    @wraps(func)
    def wrapper(*args, **kwargs):
        metrics_provider.counter("function.call.counter", tags={"function": fullname(func)})
        return func(*args, **kwargs)
    return wrapper
def apply(decorator: Any, exclude: List[str] = None):
    """Class decorator that applies specified decorator to all class methods."""
    if not exclude:
        exclude = []
    def decorate(cls):
        for attr in cls.__dict__:
            if callable(getattr(cls, attr)) and attr not in exclude:
                setattr(cls, attr, decorator(getattr(cls, attr)))
        return cls
    return decorate

from dexp.cli.parsing import _parse_channels, _parse_slicing
from dexp.datasets.open_dataset import glob_datasets
from dexp.datasets.operations.histogram import dataset_histogram
@click.command()
@click.argument("input-paths", nargs=-1)
@click.option("--output-directory", "-o", default="histogram", show_default=True, type=str)
@click.option("--channels", "-c", default=None, help="list of channels, all channels when ommited.")
@click.option(
    "--slicing",
    "-s",
    default=None,
    help="dataset slice (TZYX), e.g. [0:5] (first five stacks) [:,0:100] (cropping in z) ",
)
@click.option("--device", "-d", type=int, default=0, show_default=True)
@click.option(
    "--minimum-count",
    "-m",
    default=5,
    show_default=True,
    type=int,
    help="Minimum count on the histogram used to select upper limit, values lower than this are not considered.",
)
@click.option(
    "--maximum-count",
    "-M",
    default=None,
    show_default=True,
    type=float,
    help="Maximum count to clip histogram and improve visualization.",
)
def histogram(input_paths, output_directory, channels, slicing, device, minimum_count, maximum_count):
    input_dataset, input_paths = glob_datasets(input_paths)
    channels = _parse_channels(input_dataset, channels)
    slicing = _parse_slicing(slicing)
    if slicing is not None:
        input_dataset.set_slicing(slicing)
    dataset_histogram(
        dataset=input_dataset,
        output_dir=output_directory,
        channels=channels,
        device=device,
        minimum_count=minimum_count,
        maximum_count=maximum_count,
    )

from typing import Tuple, Union, Optional, TYPE_CHECKING, List, Any, Dict, Sequence
from fairscale.nn import FullyShardedDataParallel as FS_FSDP
from fairscale.nn.wrap import enable_wrap, wrap
from fairscale.nn.misc import FlattenParamsWrapper
from fairscale.optim.grad_scaler import GradScaler
import torch
from torch.cuda import amp
from allennlp.nn.parallel.sharded_module_mixin import ShardedModuleMixin
from allennlp.nn.parallel.ddp_accelerator import (
    DdpAccelerator,
    DdpWrappedModel,
    StateDictType,
    LoadStateDictReturnType,
)
if TYPE_CHECKING:
    # To prevent circular imports
    from allennlp.models import Model
class _FSDP(FS_FSDP, ShardedModuleMixin):
    """
    Same as FairScale's [`FullyShardedDataParallel`]
    (https://fairscale.readthedocs.io/en/latest/api/nn/fsdp.html) but also implements
    the mixin methods from :class:`allennlp.nn.parallel.sharded_module_mixin.ShardedModuleMixin`.
    """
    def get_original_module(self) -> torch.nn.Module:
        module = self.module
        if isinstance(module, FlattenParamsWrapper):
            module = module.module
        return module
class FairScaleFsdpWrappedModel(DdpWrappedModel):
    """
    The wrapped model type returned from [`FairScaleFsdpWrappedModel.wrap_model`](#wrap_model).
    """
    @staticmethod
    def consolidate_sharded_state(
        sharded_state_files: Sequence[Union[str, os.PathLike]]
    ) -> StateDictType:
        shard_weights: List[StateDictType] = []
        shard_metadata: List[Dict[str, Any]] = []
        for path in sharded_state_files:
            shard_state = torch.load(path, map_location="cpu")
            shard_weights.append(shard_state["weights"])
            shard_metadata.append(shard_state["metadata"])
        return _FSDP.consolidate_shard_weights(shard_weights, shard_metadata)
    def load_state_dict(
        self, state_dict: StateDictType, strict: bool = True
    ) -> LoadStateDictReturnType:
        return self.model.load_local_state_dict(state_dict["weights"], strict=strict)  # type: ignore[operator]
    def state_dict(self, *args, **kwargs) -> StateDictType:
        weights = self.model.local_state_dict(*args, **kwargs)  # type: ignore[operator]
        metadata = self.model.local_metadata_dict()
        return {"weights": weights, "metadata": metadata}
    def clip_grad_norm_(self, max_norm: Union[float, int]) -> torch.Tensor:
        return self.model.clip_grad_norm_(max_norm)  # type: ignore[operator]
    def init_grad_scaler(self) -> amp.GradScaler:
        return GradScaler()
@DdpAccelerator.register("fairscale_fsdp")
class FairScaleFsdpAccelerator(DdpAccelerator):
    """
    A :class:`allennlp.nn.parallel.ddp_accelerator.DdpAccelerator` for FairScale's [`FullyShardedDataParallel`]
    (https://fairscale.readthedocs.io/en/latest/api/nn/fsdp.html).
    To save memory while initializing a model, you should call [`.wrap_module()`](#wrap_module) on submodules
    as they're created.
    See the :class:`allennlp.modules.transformer.t5.T5` class for an example of how to use this.
    """
    def __init__(
        self,
        *,
        mixed_precision: bool = False,
        reshard_after_forward: bool = True,
        flatten_parameters: bool = True,
        local_rank: Optional[int] = None,
        world_size: Optional[int] = None,
        cuda_device: Union[torch.device, int] = -1,
    ) -> None:
        super().__init__(local_rank=local_rank, world_size=world_size, cuda_device=cuda_device)
        self._fsdp_kwargs = {
            "compute_device": self.cuda_device,
            "mixed_precision": mixed_precision,
            "reshard_after_forward": reshard_after_forward,
            "flatten_parameters": flatten_parameters,
        }
        if mixed_precision:
            self._fsdp_kwargs["move_params_to_cpu"] = True
            self._fsdp_kwargs["clear_autocast_cache"] = True
    def wrap_model(self, model: "Model") -> Tuple["Model", DdpWrappedModel]:
        wrapped_model = _FSDP(
            model,
            **self._fsdp_kwargs,
        )
        if not self._fsdp_kwargs["mixed_precision"] and self.cuda_device != torch.device("cpu"):
            wrapped_model = wrapped_model.cuda()
        # `_FSDP._lazy_init()` may have been called already on submodules that were wrapped
        # (through `wrap_module()`), leading those submodules to think they are root submodules.
        # So we need to call `_FSDP._reset_lazy_init()` on any of these now.
        for module in wrapped_model.modules():
            if isinstance(module, _FSDP):
                module._reset_lazy_init()
        return model, FairScaleFsdpWrappedModel(
            wrapped_model,
            local_rank=self.local_rank,
            world_size=self.world_size,
        )
    def wrap_module(self, module: torch.nn.Module) -> torch.nn.Module:
        with enable_wrap(wrapper_cls=_FSDP, **self._fsdp_kwargs):
            wrapped_module = wrap(module)
        return wrapped_module

from . import tensor_shape
from . import errors
from typing import Tuple, Optional
import numpy as np
class TensorBuffer:
  def __init__(self, data=None, array_offset=0, order="C"):
    self._data = data
    self._array_offset = array_offset
    self._order = order
  def data(self):
    return self._data
  def array_offset(self):
    return self._array_offset
  def order(self):
    return self._order
class Tensor:
  def __init__(self,
               type: types_pb2.DataType = types_pb2.DT_FLOAT,
               shape: tensor_shape.TensorShape = None,
               buf: TensorBuffer = None):
    if shape is None:
      shape = tensor_shape.TensorShape()
    shape.set_data_type(type)
    self._shape = shape
    self._buf = buf
  def __repr__(self):
    return f"Tensor(is_initialized={self.is_initialized()}, shape={self.shape()!r})"
  def shape(self) -> tensor_shape.TensorShape:
    return self._shape
  def dtype(self) -> types_pb2.DataType:
    return self._shape.data_type()
  def dims(self) -> int:
    return self.shape().dims()
  def dim_size(self, d: int) -> int:
    return self.shape().dim_size(d)
  def num_elements(self) -> int:
    return self.shape().num_elements()
  def is_initialized(self) -> bool:
    """If necessary, has this Tensor been initialized?
    Zero-element Tensors are always considered initialized, even if they
    have never been assigned to and do not have any memory allocated."""
    return (self._buf is not None and self._buf.data() is not None) or self.num_elements() == 0
  def set_data(self, buf: TensorBuffer):
    self._buf = buf
  def to_py(self) -> Tuple[errors.Status, Optional[np.ndarray]]:
    if not self.is_initialized():
      return errors.FailedPrecondition("Not initialized"), None
    shape = self.shape()
    dtype = shape.dtype()
    if dtype is None:
      return errors.Unimplemented("Data type ", shape.data_type(), " not supported"), None
    if self.num_elements() != 0:
      arr = np.ndarray.__new__(np.ndarray,
                               shape=shape.to_list(),
                               dtype=dtype,
                               buffer=self._buf.data(),
                               offset=self._buf.array_offset(),
                               order=self._buf.order())
      # a = np.frombuffer(self._buf.data(), dtype, shape.num_elements())
      # a = a.reshape(shape.to_list())
    else:
      arr = np.zeros(shape.to_list(), dtype)
    return errors.Status.OK(), arr

from bisect import bisect_left, insort_right
from collections import defaultdict
from datetime import MAXYEAR, datetime, timedelta, timezone
from functools import partial
from typing import Any, Iterable, Optional
from uuid import UUID
import attr
from ..abc import DataStore, EventBroker, EventSource, Job, Schedule
from ..enums import ConflictPolicy
from ..eventbrokers.local import LocalEventBroker
from ..events import (
    JobAcquired, JobAdded, JobReleased, ScheduleAdded, ScheduleRemoved, ScheduleUpdated, TaskAdded,
    TaskRemoved, TaskUpdated)
from ..exceptions import ConflictingIdError, TaskLookupError
from ..structures import JobResult, Task
from ..util import reentrant
max_datetime = datetime(MAXYEAR, 12, 31, 23, 59, 59, 999999, tzinfo=timezone.utc)
@attr.define
class TaskState:
    task: Task
    running_jobs: int = 0
    saved_state: Any = None
    def __eq__(self, other):
        return self.task.id == other.task.id
@attr.define
class ScheduleState:
    schedule: Schedule
    next_fire_time: Optional[datetime] = attr.field(init=False, eq=False)
    acquired_by: Optional[str] = attr.field(init=False, eq=False, default=None)
    acquired_until: Optional[datetime] = attr.field(init=False, eq=False, default=None)
    def __attrs_post_init__(self):
        self.next_fire_time = self.schedule.next_fire_time
    def __eq__(self, other):
        return self.schedule.id == other.schedule.id
    def __lt__(self, other):
        if self.next_fire_time is None:
            return False
        elif other.next_fire_time is None:
            return self.next_fire_time is not None
        else:
            return self.next_fire_time < other.next_fire_time
    def __hash__(self):
        return hash(self.schedule.id)
@attr.define(order=True)
class JobState:
    job: Job = attr.field(order=False)
    created_at: datetime = attr.field(init=False, factory=partial(datetime.now, timezone.utc))
    acquired_by: Optional[str] = attr.field(eq=False, order=False, default=None)
    acquired_until: Optional[datetime] = attr.field(eq=False, order=False, default=None)
    def __eq__(self, other):
        return self.job.id == other.job.id
    def __hash__(self):
        return hash(self.job.id)
@reentrant
@attr.define(eq=False)
class MemoryDataStore(DataStore):
    lock_expiration_delay: float = 30
    _events: EventBroker = attr.Factory(LocalEventBroker)
    _tasks: dict[str, TaskState] = attr.Factory(dict)
    _schedules: list[ScheduleState] = attr.Factory(list)
    _schedules_by_id: dict[str, ScheduleState] = attr.Factory(dict)
    _schedules_by_task_id: dict[str, set[ScheduleState]] = attr.Factory(partial(defaultdict, set))
    _jobs: list[JobState] = attr.Factory(list)
    _jobs_by_id: dict[UUID, JobState] = attr.Factory(dict)
    _jobs_by_task_id: dict[str, set[JobState]] = attr.Factory(partial(defaultdict, set))
    _job_results: dict[UUID, JobResult] = attr.Factory(dict)
    def _find_schedule_index(self, state: ScheduleState) -> Optional[int]:
        left_index = bisect_left(self._schedules, state)
        right_index = bisect_left(self._schedules, state)
        return self._schedules.index(state, left_index, right_index + 1)
    def _find_job_index(self, state: JobState) -> Optional[int]:
        left_index = bisect_left(self._jobs, state)
        right_index = bisect_left(self._jobs, state)
        return self._jobs.index(state, left_index, right_index + 1)
    def __enter__(self):
        self._events.__enter__()
        return self
    def __exit__(self, exc_type, exc_val, exc_tb):
        self._events.__exit__(exc_type, exc_val, exc_tb)
    @property
    def events(self) -> EventSource:
        return self._events
    def get_schedules(self, ids: Optional[set[str]] = None) -> list[Schedule]:
        return [state.schedule for state in self._schedules
                if ids is None or state.schedule.id in ids]
    def add_task(self, task: Task) -> None:
        task_exists = task.id in self._tasks
        self._tasks[task.id] = TaskState(task)
        if task_exists:
            self._events.publish(TaskUpdated(task_id=task.id))
        else:
            self._events.publish(TaskAdded(task_id=task.id))
    def remove_task(self, task_id: str) -> None:
        try:
            del self._tasks[task_id]
        except KeyError:
            raise TaskLookupError(task_id) from None
        self._events.publish(TaskRemoved(task_id=task_id))
    def get_task(self, task_id: str) -> Task:
        try:
            return self._tasks[task_id].task
        except KeyError:
            raise TaskLookupError(task_id) from None
    def get_tasks(self) -> list[Task]:
        return sorted((state.task for state in self._tasks.values()), key=lambda task: task.id)
    def add_schedule(self, schedule: Schedule, conflict_policy: ConflictPolicy) -> None:
        old_state = self._schedules_by_id.get(schedule.id)
        if old_state is not None:
            if conflict_policy is ConflictPolicy.do_nothing:
                return
            elif conflict_policy is ConflictPolicy.exception:
                raise ConflictingIdError(schedule.id)
            index = self._find_schedule_index(old_state)
            del self._schedules[index]
            self._schedules_by_task_id[old_state.schedule.task_id].remove(old_state)
        state = ScheduleState(schedule)
        self._schedules_by_id[schedule.id] = state
        self._schedules_by_task_id[schedule.task_id].add(state)
        insort_right(self._schedules, state)
        if old_state is not None:
            event = ScheduleUpdated(schedule_id=schedule.id,
                                    next_fire_time=schedule.next_fire_time)
        else:
            event = ScheduleAdded(schedule_id=schedule.id,
                                  next_fire_time=schedule.next_fire_time)
        self._events.publish(event)
    def remove_schedules(self, ids: Iterable[str]) -> None:
        for schedule_id in ids:
            state = self._schedules_by_id.pop(schedule_id, None)
            if state:
                self._schedules.remove(state)
                event = ScheduleRemoved(schedule_id=state.schedule.id)
                self._events.publish(event)
    def acquire_schedules(self, scheduler_id: str, limit: int) -> list[Schedule]:
        now = datetime.now(timezone.utc)
        schedules: list[Schedule] = []
        for state in self._schedules:
            if state.next_fire_time is None or state.next_fire_time > now:
                # The schedule is either paused or not yet due
                break
            elif state.acquired_by is not None:
                if state.acquired_by != scheduler_id and now <= state.acquired_until:
                    # The schedule has been acquired by another scheduler and the timeout has not
                    # expired yet
                    continue
            schedules.append(state.schedule)
            state.acquired_by = scheduler_id
            state.acquired_until = now + timedelta(seconds=self.lock_expiration_delay)
            if len(schedules) == limit:
                break
        return schedules
    def release_schedules(self, scheduler_id: str, schedules: list[Schedule]) -> None:
        # Send update events for schedules that have a next time
        finished_schedule_ids: list[str] = []
        for s in schedules:
            if s.next_fire_time is not None:
                # Remove the schedule
                schedule_state = self._schedules_by_id.get(s.id)
                index = self._find_schedule_index(schedule_state)
                del self._schedules[index]
                # Readd the schedule to its new position
                schedule_state.next_fire_time = s.next_fire_time
                schedule_state.acquired_by = None
                schedule_state.acquired_until = None
                insort_right(self._schedules, schedule_state)
                event = ScheduleUpdated(schedule_id=s.id, next_fire_time=s.next_fire_time)
                self._events.publish(event)
            else:
                finished_schedule_ids.append(s.id)
        # Remove schedules that didn't get a new next fire time
        self.remove_schedules(finished_schedule_ids)
    def get_next_schedule_run_time(self) -> Optional[datetime]:
        return self._schedules[0].next_fire_time if self._schedules else None
    def add_job(self, job: Job) -> None:
        state = JobState(job)
        self._jobs.append(state)
        self._jobs_by_id[job.id] = state
        self._jobs_by_task_id[job.task_id].add(state)
        event = JobAdded(job_id=job.id, task_id=job.task_id, schedule_id=job.schedule_id,
                         tags=job.tags)
        self._events.publish(event)
    def get_jobs(self, ids: Optional[Iterable[UUID]] = None) -> list[Job]:
        if ids is not None:
            ids = frozenset(ids)
        return [state.job for state in self._jobs if ids is None or state.job.id in ids]
    def acquire_jobs(self, worker_id: str, limit: Optional[int] = None) -> list[Job]:
        now = datetime.now(timezone.utc)
        jobs: list[Job] = []
        for index, job_state in enumerate(self._jobs):
            task_state = self._tasks[job_state.job.task_id]
            # Skip already acquired jobs (unless the acquisition lock has expired)
            if job_state.acquired_by is not None:
                if job_state.acquired_until >= now:
                    continue
                else:
                    task_state.running_jobs -= 1
            # Check if the task allows one more job to be started
            if (task_state.task.max_running_jobs is not None
                    and task_state.running_jobs >= task_state.task.max_running_jobs):
                continue
            # Mark the job as acquired by this worker
            jobs.append(job_state.job)
            job_state.acquired_by = worker_id
            job_state.acquired_until = now + timedelta(seconds=self.lock_expiration_delay)
            # Increment the number of running jobs for this task
            task_state.running_jobs += 1
            # Exit the loop if enough jobs have been acquired
            if len(jobs) == limit:
                break
        # Publish the appropriate events
        for job in jobs:
            self._events.publish(JobAcquired(job_id=job.id, worker_id=worker_id))
        return jobs
    def release_job(self, worker_id: str, task_id: str, result: JobResult) -> None:
        # Delete the job
        job_state = self._jobs_by_id.pop(result.job_id)
        self._jobs_by_task_id[task_id].remove(job_state)
        index = self._find_job_index(job_state)
        del self._jobs[index]
        # Decrement the number of running jobs for this task
        task_state = self._tasks.get(task_id)
        if task_state is not None:
            task_state.running_jobs -= 1
        # Record the result
        self._job_results[result.job_id] = result
        # Publish the event
        self._events.publish(
            JobReleased(job_id=result.job_id, worker_id=worker_id, outcome=result.outcome)
        )
    def get_job_result(self, job_id: UUID) -> Optional[JobResult]:
        return self._job_results.pop(job_id, None)

def longestPalindrome(self, s: str) -> str:

    # panlindrome check
    def expand(left: int, right: int) -> str:
        while left >=0 and right <= len(s) and s[left] == s[right-1]:
            left -= 1
            right += 1
        return s[left +1: right -1]

    # skip in case of exception
    if len(s) < 2 or s == s[::-1]:
        return s

    result = ''

    # O(n) * expand O(n) = O(n2)
    for i in range (len(s) -1):
        result = max(result, expand(i, i+1), expand(i, i+2), key=len)

    return result

