class GitHubProcessor:
    """Handles data processing and transformation of GitHub API responses."""
    def __init__(self, owner: str, repo: str):
        self.owner = owner
        self.repo = repo
        self.sia = SentimentIntensityAnalyzer()
    def process_pulse_feed(self, events: List[Dict[str, Any]], limit: int = 15) -> List[Dict[str, Any]]:
        """Process raw GitHub events into formatted pulse feed items."""
        if not events:
            return []
        processed_events = []
        for event in events[:limit]:
            processed_event = self._process_single_event(event)
            if processed_event:
                processed_events.append(processed_event)
        return processed_events
    def _process_single_event(self, event: Dict[str, Any]) -> Optional[Dict[str, Any]]:
        """Process a single GitHub event."""
        event_type = event.get('type')
        payload = event.get('payload', {})
        repo = event.get('repo', {})
        actor = event.get('actor', {})
        if event_type == 'PushEvent':
            count = len(payload.get('commits', []))
            ref = payload.get('ref', '').split('/')[-1]
            action = f"pushed {count} commit{'s' if count != 1 else ''} to {ref}"
        elif event_type == 'PullRequestEvent':
            action = payload.get('action', 'interacted with')
            pr = payload.get('pull_request', {})
            action = f"{action} pull request #{pr.get('number')}"
        elif event_type == 'IssuesEvent':
            action = payload.get('action', 'interacted with')
            issue = payload.get('issue', {})
            action = f"{action} issue #{issue.get('number')}"
        elif event_type == 'IssueCommentEvent':
            action = "commented on issue"
            issue = payload.get('issue', {})
            if issue:
                action = f"{action} #{issue.get('number')}"
        elif event_type == 'PullRequestReviewCommentEvent':
            action = "reviewed pull request"
            pr = payload.get('pull_request', {})
            if pr:
                action = f"{action} #{pr.get('number')}"
        elif event_type == 'CreateEvent':
            ref_type = payload.get('ref_type')
            ref = payload.get('ref')
            action = f"created {ref_type} {ref or ''}"
        elif event_type == 'DeleteEvent':
            ref_type = payload.get('ref_type')
            ref = payload.get('ref')
            action = f"deleted {ref_type} {ref or ''}"
        elif event_type == 'ForkEvent':
            action = "forked the repository"
        elif event_type == 'WatchEvent':
            action = "starred the repository"
        else:
            return None
        return {
            "id": event.get('id'),
            "type": event_type,
            "actor": {
                "login": actor.get('login'),
                "avatar": actor.get('avatar_url')
            },
            "repo": {
                "name": repo.get('name'),
                "url": f"https://github.com/{repo.get('name')}"
            },
            "action": action,
            "created_at": event.get('created_at')
        }
    def process_repo_stats(self, data: Dict[str, Any]) -> Dict[str, Any]:
        """Process repository data into stats format."""
        if not data:
            return {}
        return {
            "name": data.get('name'),
            "full_name": data.get('full_name'),
            "description": data.get('description'),
            "stars": data.get('stargazers_count', 0),
            "forks": data.get('forks_count', 0),
            "watchers": data.get('watchers_count', 0),
            "language": data.get('language'),
            "created_at": data.get('created_at'),
            "updated_at": data.get('updated_at'),
            "size": data.get('size'),
            "open_issues": data.get('open_issues_count', 0)
        }
    def process_recent_prs(self, prs: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        """Process pull requests data."""
        if not prs:
            return []
        processed_prs = []
        for pr in prs:
            processed_prs.append({
                "number": pr.get('number'),
                "title": pr.get('title'),
                "state": pr.get('state'),
                "created_at": pr.get('created_at'),
                "updated_at": pr.get('updated_at'),
                "merged_at": pr.get('merged_at'),
                "user": {
                    "login": pr.get('user', {}).get('login'),
                    "avatar": pr.get('user', {}).get('avatar_url')
                },
                "labels": [label.get('name') for label in pr.get('labels', [])]
            })
        return processed_prs
    def process_contributors(self, contributors: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        """Process contributors data."""
        if not contributors:
            return []
        processed_contributors = []
        for contributor in contributors:
            processed_contributors.append({
                "login": contributor.get('login'),
                "avatar": contributor.get('avatar_url'),
                "contributions": contributor.get("contributions"),
                "type": contributor.get('type')
            })
        return processed_contributors
    def process_activity(self, activity_data: List[Dict[str, Any]], commits: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        """Process commit activity data with fallback to manual aggregation."""
        if activity_data and len(activity_data) > 0:
            return [
                {
                    "week": item.get('week'),
                    "total": item.get('total'),
                    "days": item.get('days', [])
                }
                for item in activity_data
            ]
        elif commits:
            activity_map = {}
            for c in commits:
                if not c.get('commit', {}).get('author', {}).get('date'):
                    continue
                date_str = c['commit']['author']['date']
                try:
                    dt = datetime.fromisoformat(date_str.replace('Z', '+00:00'))
                    week_start = dt.replace(hour=0, minute=0, second=0, microsecond=0)
                    week_start = week_start - timedelta(days=dt.weekday())
                    week_key = int(week_start.timestamp())
                    if week_key not in activity_map:
                        activity_map[week_key] = {"week": week_key, "total": 0, "days": [0] * 7}
                    day_index = dt.weekday()
                    activity_map[week_key]["days"][day_index] += 1
                    activity_map[week_key]["total"] += 1
                except Exception:
                    continue
            return list(activity_map.values())
        return []
    def calculate_total_commits(self, contributors: List[Dict[str, Any]]) -> int:
        """Calculate total commits from contributors data."""
        if not contributors:
            return 0
        return sum(c.get('contributions', 0) for c in contributors)
    def process_contribution_mix(self, total_commits: int, total_prs: int, total_issues: int, total_reviews: int) -> List[Dict[str, Any]]:
        """Process contribution statistics into mix format."""
        return [
            {
                "name": "Core Features",
                "value": 45,
                "count": total_commits,
                "unit": "Commits",
                "color": "#3B82F6",
                "description": "Functional code changes & features"
            },
            {
                "name": "Infrastructure",
                "value": 25,
                "count": total_prs,
                "unit": "Pull Requests",
                "color": "#10B981",
                "description": "PR merges and branch management"
            },
            {
                "name": "Issue Triage",
                "value": 20,
                "count": total_issues,
                "unit": "Total Issues",
                "color": "#C2410C",
                "description": "Issue resolution & bug tracking"
            },
            {
                "name": "Mentorship",
                "value": 10,
                "count": total_reviews,
                "unit": "Review Comments",
                "color": "#8B5CF6",
                "description": "Peer code reviews & guidance"
            },
        ]
    def process_reviewer_stats(self, comments: List[Dict[str, Any]], reviews: List[Dict[str, Any]]) -> Dict[str, Any]:
        """Process reviewer statistics with sentiment analysis."""
        reviewers = {}
        total_sentiment = 0.0
        details_count = 0
        BOTS = {"copilot", "github-copilot", "github-copilot[bot]", "actions-user", "github-actions[bot]"}
        def process_entry(entry: Dict[str, Any], is_review: bool = False):
            nonlocal total_sentiment, details_count
            user = entry.get('user', {}).get('login')
            if not user or '[bot]' in user.lower() or user.endswith('-bot') or user.lower() in BOTS:
                return
            if user not in reviewers:
                reviewers[user] = {
                    "name": user,
                    "avatar": entry.get('user', {}).get('avatar_url'),
                    "count": 0,
                    "is_maintainer": user == self.owner
                }
            reviewers[user]["count"] += 1
            body = entry.get('body', '')
            if body and len(body.strip()) > 3:
                try:
                    score = self.sia.polarity_scores(body)['compound']
                    total_sentiment += score
                    details_count += 1
                except Exception:
                    pass
        for comment in comments:
            process_entry(comment, is_review=False)
        for review in reviews:
            process_entry(review, is_review=True)
        avg_sentiment = total_sentiment / details_count if details_count > 0 else 0
        return {
            "reviewers": list(reviewers.values()),
            "total_reviews": len(reviews),
            "total_comments": len(comments),
            "sentiment_score": avg_sentiment,
            "sentiment_label": "Positive" if avg_sentiment >= 0.05 else "Negative" if avg_sentiment <= -0.05 else "Neutral"
        }

import importlib.util
import paddle
from pathlib import Path
import sys
import os
import numpy as np
import random
import platform
import traceback
import subprocess
import re
from graph_net.paddle import utils
from graph_net_bench import path_utils
from graph_net_bench import test_compiler_util
from graph_net import model_path_util
from graph_net.paddle.backend.graph_compiler_backend import GraphCompilerBackend
from graph_net.paddle.backend.cinn_backend import CinnBackend
from graph_net.paddle.backend.nope_backend import NopeBackend
registry_backend = {
    "cinn": CinnBackend(),
    "nope": NopeBackend(),
}
def get_compiler_backend(args) -> GraphCompilerBackend:
    assert args.compiler in registry_backend, f"Unknown compiler: {args.compiler}"
    return registry_backend[args.compiler]
def set_seed(random_seed):
    paddle.seed(random_seed)
    random.seed(random_seed)
    np.random.seed(random_seed)
def init_env(args):
    if test_compiler_util.is_gpu_device(args.device):
        paddle.set_flags({"FLAGS_cudnn_exhaustive_search": 1})
def get_hardward_name(args):
    hardware = "unknown"
    if test_compiler_util.is_gpu_device(args.device):
        hardware = paddle.device.cuda.get_device_name(0)
    elif args.device == "xpu":
        try:
            output = subprocess.check_output(["xpu-smi", "-L"], text=True)
            hardware = next(
                match.group(2)
                for line in output.splitlines()
                if (
                    match := re.match(
                        r"XPU\s+(\d+):\s+(.+?)\s+\(UUID:\s*([^)]+)\)", line
                    )
                )
            )
        except Exception:
            pass
    elif args.device == "cpu":
        hardware = platform.processor()
    return hardware
def get_compile_framework_version(args):
    if args.compiler in ["cinn", "nope"]:
        return paddle.__version__
    return "unknown"
def load_class_from_file(file_path: str, class_name: str):
    file = Path(file_path).resolve()
    module_name = file.stem
    with open(file_path, "r", encoding="utf-8") as f:
        original_code = f.read()
    import_stmt = "import paddle"
    modified_code = f"{import_stmt}\n{original_code}"
    spec = importlib.util.spec_from_loader(module_name, loader=None)
    module = importlib.util.module_from_spec(spec)
    sys.modules[module_name] = module
    compiled_code = compile(modified_code, filename=file, mode="exec")
    exec(compiled_code, module.__dict__)
    model_class = getattr(module, class_name, None)
    return model_class
def get_model(model_path):
    model_class = load_class_from_file(
        f"{model_path}/model.py", class_name="GraphModule"
    )
    return model_class()
def get_input_dict(model_path):
    inputs_params = utils.load_converted_from_text(f"{model_path}")
    params = inputs_params["weight_info"]
    inputs = inputs_params["input_info"]
    params.update(inputs)
    state_dict = {k: utils.replay_tensor(v) for k, v in params.items()}
    return state_dict
def get_input_spec(model_path):
    inputs_params_list = utils.load_converted_list_from_text(f"{model_path}")
    input_spec = [None] * len(inputs_params_list)
    for i, v in enumerate(inputs_params_list):
        dtype = v["info"]["dtype"]
        shape = v["info"]["shape"]
        input_spec[i] = paddle.static.InputSpec(shape, dtype)
    return input_spec
def get_static_model(args, model):
    static_model = paddle.jit.to_static(
        model,
        input_spec=get_input_spec(args.model_path),
        full_graph=True,
        backend=None,
    )
    static_model.eval()
    program = static_model.forward.concrete_program.main_program  # noqa
    return static_model
def measure_performance(model_call, args, compiler, profile=False):
    runtime_seed = 1024
    stats = {}
    paddle.seed(runtime_seed)
    outs = model_call()
    # Warmup runs
    warmup_e2e_times = []
    for _ in range(args.warmup):
        duration_box = test_compiler_util.DurationBox(-1)
        with test_compiler_util.naive_timer(duration_box, compiler.synchronize):
            model_call()
        warmup_e2e_times.append(duration_box.value)
    compiler.synchronize()
    # Ensure the measuring time is not less than 100ms.
    min_trials = int(100 / np.mean(warmup_e2e_times[1:]))
    trials = max(args.trials, min_trials)
    hardware_name = get_hardward_name(args)
    print(
        f"[Profiling] Using device: {args.device} {hardware_name}, warm up {args.warmup}, trials {trials}",
        file=sys.stderr,
        flush=True,
    )
    if profile:
        import paddle.profiler as profiler
        p = profiler.Profiler()
        p.start()
    if test_compiler_util.is_gpu_device(args.device):
        """
        Acknowledgement: We evaluate the performance on both end-to-end and GPU-only timings,
        With reference to methods only based on CUDA events from KernelBench in https://github.com/ScalingIntelligence/KernelBench
        """
        e2e_times = []
        gpu_times = []
        for i in range(trials):
            # End-to-end timing (naive_timer)
            duration_box = test_compiler_util.DurationBox(-1)
            with test_compiler_util.naive_timer(duration_box, compiler.synchronize):
                # GPU-only timing (CUDA Events)
                start_event = paddle.device.Event(enable_timing=True)
                end_event = paddle.device.Event(enable_timing=True)
                start_event.record()
                model_call()
                end_event.record()
            if profile:
                p.step()
            gpu_time_ms = start_event.elapsed_time(end_event)
            e2e_times.append(duration_box.value)
            gpu_times.append(gpu_time_ms)
            print(
                f"Trial {i + 1}: e2e={duration_box.value:.5f} ms, gpu={gpu_time_ms:.5f} ms",
                file=sys.stderr,
                flush=True,
            )
        stats["e2e"] = test_compiler_util.get_timing_stats(e2e_times)
        stats["gpu"] = test_compiler_util.get_timing_stats(gpu_times)
    else:  # CPU or other devices
        e2e_times = []
        for i in range(trials):
            duration_box = test_compiler_util.DurationBox(-1)
            with test_compiler_util.naive_timer(duration_box, compiler.synchronize):
                model_call()
            if profile:
                p.step()
            e2e_times.append(duration_box.value)
            print(
                f"Trial {i + 1}: e2e={duration_box.value:.4f} ms",
                file=sys.stderr,
                flush=True,
            )
        stats["e2e"] = test_compiler_util.get_timing_stats(e2e_times)
    if profile:
        p.stop()
        p.summary()
    return outs, stats
def check_outputs(args, expected_out, compiled_out):
    def _flatten_outputs_to_list(outs):
        flattened_outs = outs
        if isinstance(outs, paddle.Tensor):
            flattened_outs = [outs]
        else:
            flattened_outs = [
                x
                for out in outs
                for x in (out if isinstance(out, (tuple, list)) else (out,))
            ]
        return flattened_outs
    expected_out = _flatten_outputs_to_list(expected_out)
    compiled_out = _flatten_outputs_to_list(compiled_out)
    def _get_output_dtypes(outs):
        dtypes = [
            str(tensor.dtype).replace("paddle.", "")
            if isinstance(tensor, paddle.Tensor)
            else None
            for i, tensor in enumerate(outs)
        ]
        return dtypes
    eager_dtypes = _get_output_dtypes(expected_out)
    compiled_dtypes = _get_output_dtypes(compiled_out)
    type_match = test_compiler_util.check_output_datatype(
        args, eager_dtypes, compiled_dtypes
    )
    def _get_output_shapes(outs):
        shapes = [
            tensor.shape if isinstance(tensor, paddle.Tensor) else None
            for i, tensor in enumerate(outs)
        ]
        return shapes
    eager_shapes = _get_output_shapes(expected_out)
    compiled_shapes = _get_output_shapes(compiled_out)
    shape_match = test_compiler_util.check_output_shape(
        args, eager_shapes, compiled_shapes
    )
    def _transfer_to_float(origin_outputs):
        outputs = []
        for item in origin_outputs:
            if isinstance(item, paddle.Tensor) and item.dtype not in [
                paddle.float32,
                paddle.float64,
            ]:
                item = item.astype("float32")
            outputs.append(item)
        return outputs
    if type_match and shape_match:
        test_compiler_util.check_equal(
            args,
            expected_out,
            compiled_out,
            cmp_equal_func=get_cmp_equal,
        )
        expected_out_fp32 = _transfer_to_float(expected_out)
        compiled_out_fp32 = _transfer_to_float(compiled_out)
        test_compiler_util.check_allclose(
            args,
            expected_out_fp32,
            compiled_out_fp32,
            cmp_all_close_func=get_cmp_all_close,
            cmp_max_diff_func=get_cmp_max_diff,
            cmp_mean_diff_func=get_cmp_mean_diff,
            cmp_max_relative_diff_func=get_cmp_max_relative_diff,
            cmp_mean_relative_diff_func=get_cmp_mean_relative_diff,
        )
def check_and_print_gpu_utilization(compiler):
    if paddle.device.is_compiled_with_cuda():
        device_id = int(paddle.device.get_device().split(":")[-1])
        device_count = paddle.device.cuda.device_count()
        gpu_util, mem_util = test_compiler_util.get_device_utilization(
