import base64
import json
from typing import Optional, Tuple, List
from urllib.parse import unquote, urlparse
class ConfigValidator:
    @staticmethod
    def is_base64(s: str) -> bool:
        try:
            s = s.rstrip('=')
            return bool(re.match(r'^[A-Za-z0-9+/\-_]*$', s))
        except:
            return False
    @staticmethod
    def decode_base64_url(s: str) -> Optional[bytes]:
        try:
            s = s.replace('-', '+').replace('_', '/')
            padding = 4 - (len(s) % 4)
            if padding != 4:
                s += '=' * padding
            return base64.b64decode(s)
        except:
            return None
    @staticmethod
    def decode_base64_text(text: str) -> Optional[str]:
        try:
            if ConfigValidator.is_base64(text):
                decoded = ConfigValidator.decode_base64_url(text)
                if decoded:
                    return decoded.decode('utf-8')
            return None
        except:
            return None
    @staticmethod
    def clean_vmess_config(config: str) -> str:
        if "vmess://" in config:
            base64_part = config[8:]
            base64_clean = re.split(r'[^A-Za-z0-9+/=_-]', base64_part)[0]
            return f"vmess://{base64_clean}"
        return config
    @staticmethod
    def normalize_hysteria2_protocol(config: str) -> str:
        if config.startswith('hy2://'):
            return config.replace('hy2://', 'hysteria2://', 1)
        return config
    @staticmethod
    def is_vmess_config(config: str) -> bool:
        try:
            if not config.startswith('vmess://'):
                return False
            base64_part = config[8:]
            decoded = ConfigValidator.decode_base64_url(base64_part)
            if decoded:
                json.loads(decoded)
                return True
            return False
        except:
            return False
    @staticmethod
    def is_tuic_config(config: str) -> bool:
        try:
            if config.startswith('tuic://'):
                parsed = urlparse(config)
                return bool(parsed.netloc and ':' in parsed.netloc)
            return False
        except:
            return False
    @staticmethod
    def convert_ssconf_to_https(url: str) -> str:
        if url.startswith('ssconf://'):
            return url.replace('ssconf://', 'https://', 1)
        return url
    @staticmethod
    def is_base64_config(config: str) -> Tuple[bool, str]:
        protocols = ['vmess://', 'vless://', 'ss://', 'tuic://']
        for protocol in protocols:
            if config.startswith(protocol):
                base64_part = config[len(protocol):]
                decoded_url = unquote(base64_part)
                if (ConfigValidator.is_base64(decoded_url) or 
                    ConfigValidator.is_base64(base64_part)):
                    return True, protocol[:-3]
        return False, ''
    @staticmethod
    def check_base64_content(text: str) -> Optional[str]:
        try:
            decoded_text = ConfigValidator.decode_base64_text(text)
            if decoded_text:
                protocols = ['vmess://', 'vless://', 'ss://', 'trojan://', 'hysteria2://', 'hy2://', 'wireguard://', 'tuic://', 'ssconf://']
                for protocol in protocols:
                    if protocol in decoded_text:
                        return decoded_text
            return None
        except:
            return None
    @staticmethod
    def split_configs(text: str) -> List[str]:
        configs = []
        lines = text.split('\n')

        for line in lines:
            line = line.strip()
            if not line:
                continue

            if ConfigValidator.is_base64(line):
                decoded_content = ConfigValidator.check_base64_content(line)
                if decoded_content:
                    text = decoded_content

            protocols = ['vmess://', 'vless://', 'ss://', 'trojan://', 'hysteria2://', 'hy2://', 'wireguard://', 'tuic://', 'ssconf://']
            current_pos = 0
            text_length = len(text)

            while current_pos < text_length:
                next_config_start = text_length
                matching_protocol = None

                for protocol in protocols:
                    protocol_pos = text.find(protocol, current_pos)
                    if protocol_pos != -1 and protocol_pos < next_config_start:
                        next_config_start = protocol_pos
                        matching_protocol = protocol

                if matching_protocol:
                    if current_pos < next_config_start and configs:
                        current_config = text[current_pos:next_config_start].strip()
                        if ConfigValidator.is_valid_config(current_config):
                            configs.append(current_config)

                    current_pos = next_config_start
                    next_protocol_pos = text_length

                    for protocol in protocols:
                        pos = text.find(protocol, next_config_start + len(matching_protocol))
                        if pos != -1 and pos < next_protocol_pos:
                            next_protocol_pos = pos

                    current_config = text[next_config_start:next_protocol_pos].strip()
                    if matching_protocol == "vmess://":
                        current_config = ConfigValidator.clean_vmess_config(current_config)
                    elif matching_protocol == "hy2://":
                        current_config = ConfigValidator.normalize_hysteria2_protocol(current_config)
                    if ConfigValidator.is_valid_config(current_config):
                        configs.append(current_config)

                    current_pos = next_protocol_pos
                else:
                    break

        return configs
    @staticmethod
    def clean_config(config: str) -> str:
        config = re.sub(r'[\U0001F300-\U0001F9FF]', '', config)
        config = re.sub(r'[\x00-\x08\x0B-\x1F\x7F-\x9F]', '', config)
        config = re.sub(r'[^\S\r\n]+', ' ', config)
        config = config.strip()
        return config
    @staticmethod
    def is_valid_config(config: str) -> bool:
        if not config:
            return False

        protocols = ['vmess://', 'vless://', 'ss://', 'trojan://', 'hysteria2://', 'hy2://', 'wireguard://', 'tuic://', 'ssconf://']
        return any(config.startswith(p) for p in protocols)
    @classmethod
    def validate_protocol_config(cls, config: str, protocol: str) -> bool:
        try:
            if protocol in ['vmess://', 'vless://', 'ss://', 'tuic://']:
                if protocol == 'vmess://':
                    return cls.is_vmess_config(config)
                if protocol == 'tuic://':
                    return cls.is_tuic_config(config)
                base64_part = config[len(protocol):]
                decoded_url = unquote(base64_part)
                if cls.is_base64(decoded_url) or cls.is_base64(base64_part):
                    return True
                if cls.decode_base64_url(base64_part) or cls.decode_base64_url(decoded_url):
                    return True
            elif protocol in ['trojan://', 'hysteria2://', 'hy2://', 'wireguard://']:
                parsed = urlparse(config)
                return bool(parsed.netloc and '@' in parsed.netloc)
            elif protocol == 'ssconf://':
                return True
            return False
        except:
            return False

Layout Tools - Automatic node positioning.
Provides auto_layout tool for arranging nodes in various layouts.
"""
import json
from typing import Dict, List
from langchain.tools import tool
from pydantic import BaseModel, Field
from app.core.copilot.tools.context import get_current_graph_context
class AutoLayoutInput(BaseModel):
    """Input schema for auto_layout tool."""
    layout_type: str = Field(
        default="horizontal",
        description="Layout type: 'horizontal' (left-to-right), 'vertical' (top-to-bottom), 'tree' (hierarchical), 'grid' (grid arrangement)",
    )
    node_spacing_x: float = Field(default=300, description="Horizontal spacing between nodes")
    node_spacing_y: float = Field(default=150, description="Vertical spacing between nodes")
    start_x: float = Field(default=100, description="Starting X position")
    start_y: float = Field(default=100, description="Starting Y position")
    reasoning: str = Field(description="Explanation for why auto layout is needed")
@tool(
    args_schema=AutoLayoutInput,
    description="Automatically rearrange nodes for better visualization. Layout types: horizontal, vertical, tree, grid.",
)
def auto_layout(
    reasoning: str,
    layout_type: str = "horizontal",
    node_spacing_x: float = 300,
    node_spacing_y: float = 150,
    start_x: float = 100,
    start_y: float = 100,
) -> str:
    """
    Automatically rearrange nodes for better visualization.
    Args:
        reasoning: Why auto layout is needed
        layout_type: 'horizontal' (default), 'vertical', 'tree', 'grid'
        node_spacing_x: Horizontal spacing (default: 300)
        node_spacing_y: Vertical spacing (default: 150)
        start_x: Starting X position (default: 100)
        start_y: Starting Y position (default: 100)
    Returns:
        JSON with UPDATE_POSITION actions for all nodes.
    """
    graph_context = get_current_graph_context()
    nodes = graph_context.get("nodes", [])
    edges = graph_context.get("edges", [])
    if not nodes:
        return json.dumps(
            {
                "error": "No nodes in the current graph to layout",
                "suggestion": "Create some nodes first before applying auto layout",
            },
            ensure_ascii=False,
        )
    actions = []
    # Build adjacency list for topology analysis
    outgoing: Dict[str, List[str]] = {n.get("id"): [] for n in nodes}
    incoming: Dict[str, List[str]] = {n.get("id"): [] for n in nodes}
    for edge in edges:
        src = edge.get("source")
        tgt = edge.get("target")
        if src in outgoing and tgt in incoming:
            outgoing[src].append(tgt)
            incoming[tgt].append(src)
    # Find root nodes (no incoming edges)
    root_nodes = [n for n in nodes if not incoming.get(n.get("id"), [])]
    if layout_type == "horizontal":
        # BFS from root nodes, assign columns
        visited = set()
        columns: Dict[str, int] = {}
        queue = [(n.get("id"), 0) for n in root_nodes]
        while queue:
            node_id, col = queue.pop(0)
            if node_id in visited:
                continue
            visited.add(node_id)
            columns[node_id] = col
            for child in outgoing.get(node_id, []):
                if child not in visited:
                    queue.append((child, col + 1))
        # Assign positions by column
        col_counts: Dict[int, int] = {}
        for node in nodes:
            node_id = node.get("id")
            col = columns.get(node_id, 0)
            row = col_counts.get(col, 0)
            col_counts[col] = row + 1
            new_x = start_x + col * node_spacing_x
            new_y = start_y + row * node_spacing_y
            actions.append(
                {
                    "type": "UPDATE_POSITION",
                    "payload": {"id": node_id, "position": {"x": new_x, "y": new_y}},
                    "reasoning": f"Auto-layout: placing node in column {col}, row {row}",
                }
            )
    elif layout_type == "vertical":
        # Similar to horizontal but swap x and y
        visited = set()
        rows: Dict[str, int] = {}
        queue = [(n.get("id"), 0) for n in root_nodes]
        while queue:
            node_id, row = queue.pop(0)
            if node_id in visited:
                continue
            visited.add(node_id)
            rows[node_id] = row
            for child in outgoing.get(node_id, []):
                if child not in visited:
                    queue.append((child, row + 1))
        row_counts: Dict[int, int] = {}
        for node in nodes:
            node_id = node.get("id")
            row = rows.get(node_id, 0)
            col = row_counts.get(row, 0)
            row_counts[row] = col + 1
            new_x = start_x + col * node_spacing_x
            new_y = start_y + row * node_spacing_y
            actions.append(
                {
                    "type": "UPDATE_POSITION",
                    "payload": {"id": node_id, "position": {"x": new_x, "y": new_y}},
                    "reasoning": f"Auto-layout (vertical): placing node in row {row}, column {col}",
                }
            )
    elif layout_type == "tree":
        # Tree layout with root at top
        visited = set()
        levels: Dict[str, int] = {}
        level_nodes: Dict[int, List[str]] = {}
        queue = [(n.get("id"), 0) for n in root_nodes]
        while queue:
            node_id, level = queue.pop(0)
            if node_id in visited:
                continue
            visited.add(node_id)
            levels[node_id] = level
            if level not in level_nodes:
                level_nodes[level] = []
            level_nodes[level].append(node_id)
            for child in outgoing.get(node_id, []):
                if child not in visited:
                    queue.append((child, level + 1))
        # Position nodes centered in each level
        for level, node_list in level_nodes.items():
            count = len(node_list)
            total_width = (count - 1) * node_spacing_x
            start_offset = -total_width / 2
            for i, node_id in enumerate(node_list):
                new_x = start_x + 400 + start_offset + i * node_spacing_x  # Center around 400
                new_y = start_y + level * node_spacing_y
                actions.append(
                    {
                        "type": "UPDATE_POSITION",
                        "payload": {"id": node_id, "position": {"x": new_x, "y": new_y}},
                        "reasoning": f"Auto-layout (tree): level {level}, position {i + 1}/{count}",
                    }
                )
    elif layout_type == "grid":
        # Simple grid arrangement
        cols = max(3, int(len(nodes) ** 0.5))
        for i, node in enumerate(nodes):
            row = i // cols
            col = i % cols
            new_x = start_x + col * node_spacing_x
            new_y = start_y + row * node_spacing_y
            actions.append(
                {
                    "type": "UPDATE_POSITION",
                    "payload": {"id": node.get("id"), "position": {"x": new_x, "y": new_y}},
                    "reasoning": f"Auto-layout (grid): row {row}, col {col}",
                }
            )
    return json.dumps(
        {
            "layout_type": layout_type,
            "nodes_repositioned": len(actions),
            "actions": actions,
            "reasoning": reasoning,
        },
        ensure_ascii=False,
        indent=2,
    )

from __future__ import annotations
import base64
import binascii
from typing import Final, Literal
QrPayloadCodec = Literal["raw", "base64"]
QR_PAYLOAD_CODEC_RAW: Final[QrPayloadCodec] = "raw"
QR_PAYLOAD_CODEC_BASE64: Final[QrPayloadCodec] = "base64"
def encode_qr_payload(
    data: bytes,
    *,
    codec: QrPayloadCodec = QR_PAYLOAD_CODEC_BASE64,
) -> bytes | str:
    """Encode frame bytes for QR transport."""
    if codec == QR_PAYLOAD_CODEC_RAW:
        return data
    if codec != QR_PAYLOAD_CODEC_BASE64:
        raise ValueError(f"unsupported QR payload codec: {codec}")
    encoded = base64.b64encode(data).decode("ascii")
    return encoded.rstrip("=")
def decode_qr_payload(
    payload: bytes | str,
    *,
    codec: QrPayloadCodec = QR_PAYLOAD_CODEC_BASE64,
) -> bytes:
    """Decode frame bytes from QR transport payload."""
    if codec == QR_PAYLOAD_CODEC_RAW:
        if isinstance(payload, bytes):
            return payload
        raise ValueError("invalid raw QR payload")
    if codec != QR_PAYLOAD_CODEC_BASE64:
        raise ValueError(f"unsupported QR payload codec: {codec}")
    return _decode_base64_qr_payload(payload)
def _decode_base64_qr_payload(payload: bytes | str) -> bytes:
    """Decode unpadded base64 QR payload text."""
    if isinstance(payload, bytes):
        try:
            text = payload.decode("ascii")
        except UnicodeDecodeError as exc:
            raise ValueError("invalid base64 QR payload") from exc
    else:
        text = payload
    cleaned = "".join(text.split())
    if "=" in cleaned:
        raise ValueError("invalid base64 QR payload")
    try:
        decoded = base64.b64decode(_pad_unpadded_base64(cleaned), validate=True)
    except (binascii.Error, ValueError) as exc:
        raise ValueError("invalid base64 QR payload") from exc
    canonical = base64.b64encode(decoded).decode("ascii").rstrip("=")
    if canonical != cleaned:
        raise ValueError("invalid base64 QR payload")
    return decoded
def _pad_unpadded_base64(text: str) -> str:
    """Add required padding to unpadded base64 text."""
    padding = (-len(text)) % 4
    return text + ("=" * padding)
__all__ = [
    "QR_PAYLOAD_CODEC_BASE64",
    "QR_PAYLOAD_CODEC_RAW",
    "QrPayloadCodec",
    "decode_qr_payload",
    "encode_qr_payload",
]

from megatron.core.transformer import TransformerConfig
from megatron.core.transformer.pipeline_parallel_layer_layout import (
    PipelineParallelLayerLayout,
)
from transformers import PretrainedConfig
from areal.api.alloc_mode import MegatronParallelStrategy
from areal.utils import logging
logger = logging.getLogger("MCoreParallel")
def configure_pipeline_layer_splits(
    parallel_strategy: MegatronParallelStrategy,
    hf_config: PretrainedConfig,
    tf_config: TransformerConfig,
) -> TransformerConfig:
    pp_size = parallel_strategy.pipeline_parallel_size
    vpp_size = parallel_strategy.virtual_pipeline_parallel_size
    if pp_size <= 1:
        return tf_config
    total_stages = pp_size * vpp_size
    total_layers = getattr(tf_config, "num_layers", None)
    if not isinstance(total_layers, int) or total_layers <= 0:
        return tf_config
    layer_param_weights, embedding_params, output_params = (
        estimate_stage_parameter_buckets(hf_config, tf_config)
    )
    if not layer_param_weights or all(weight <= 0 for weight in layer_param_weights):
        return tf_config
    if len(layer_param_weights) != total_layers:
        total_layers = min(total_layers, len(layer_param_weights))
        layer_param_weights = layer_param_weights[:total_layers]
    stage_lengths = _compute_stage_layer_lengths(
        layer_param_weights,
        embedding_params,
        output_params,
        total_stages,
    )
    if not stage_lengths:
        logger.warning(
            "Falling back to default pipeline layout; unable to find valid stage partition."
        )
        return tf_config
    layout: list[list[str]] = []
    for idx, length in enumerate(stage_lengths):
        stage_layers: list[str] = []
        if idx == 0:
            stage_layers.append("embedding")
        stage_layers.extend(["decoder"] * length)
        if idx == total_stages - 1:
            stage_layers.append("loss")
        layout.append(stage_layers)
    layout = PipelineParallelLayerLayout(
        layout=layout,
        pipeline_model_parallel_size=pp_size,
    )
    setattr(tf_config, "pipeline_model_parallel_layout", layout)
    if hasattr(tf_config, "num_layers_in_first_pipeline_stage"):
        setattr(tf_config, "num_layers_in_first_pipeline_stage", None)
    if hasattr(tf_config, "num_layers_in_last_pipeline_stage"):
        setattr(tf_config, "num_layers_in_last_pipeline_stage", None)
    if hasattr(tf_config, "account_for_embedding_in_pipeline_split"):
        setattr(tf_config, "account_for_embedding_in_pipeline_split", False)
    if hasattr(tf_config, "account_for_loss_in_pipeline_split"):
        setattr(tf_config, "account_for_loss_in_pipeline_split", False)
    stage_loads: list[float] = []
    cursor = 0
    for idx, length in enumerate(stage_lengths):
        load = 0.0
        if idx == 0:
            load += embedding_params
        stage_end = min(cursor + length, len(layer_param_weights))
        if stage_end > cursor:
            load += sum(layer_param_weights[cursor:stage_end])
        cursor = stage_end
        if idx == total_stages - 1:
            load += output_params
        stage_loads.append(load)
    logger.info(
        "Configured pipeline layout (per-stage decoder counts / params): %s / %s (pp=%s, vpp=%s)",
        stage_lengths,
        [f"{value / 1e6:.2f}M" for value in stage_loads],
        pp_size,
        vpp_size,
    )
    return tf_config
def _compute_stage_layer_lengths(
    layer_param_weights: list[float],
    embedding_params: float,
    output_params: float,
    pp_size: int,
) -> list[int]:
    total_layers = len(layer_param_weights)
    if total_layers == 0 or pp_size <= 0:
        return []
    prefix_sums = [0.0]
    for value in layer_param_weights:
        prefix_sums.append(prefix_sums[-1] + float(value))
    def segment_sum(start: int, end: int) -> float:
        return prefix_sums[end] - prefix_sums[start]
    stages = pp_size
    dp = [[math.inf] * (total_layers + 1) for _ in range(stages + 1)]
    choice = [[-1] * (total_layers + 1) for _ in range(stages + 1)]
    dp[0][0] = 0.0
    for stage in range(1, stages + 1):
        base = 0.0
        if stage == 1:
            base = embedding_params
        elif stage == stages:
            base = output_params
        for end in range(0, total_layers + 1):
            for start in range(0, end + 1):
                prev = dp[stage - 1][start]
                if not math.isfinite(prev):
                    continue
                if stage not in (1, stages) and start == end:
                    continue
                load = base + segment_sum(start, end)
                candidate = max(prev, load)
                if candidate < dp[stage][end]:
                    dp[stage][end] = candidate
                    choice[stage][end] = start
    if not math.isfinite(dp[stages][total_layers]):
        return []
    lengths = [0] * stages
    idx = total_layers
    for stage in range(stages, 0, -1):
        split = choice[stage][idx]
        if split < 0:
            return []
        lengths[stage - 1] = idx - split
        idx = split
    return lengths
def estimate_stage_parameter_buckets(
    hf_conf: PretrainedConfig, tf_conf: TransformerConfig
) -> tuple[list[float], float, float]:
    total_layers = getattr(tf_conf, "num_layers", None)
    if not isinstance(total_layers, int) or total_layers <= 0:
        total_layers = getattr(hf_conf, "num_hidden_layers", 0)
    if not isinstance(total_layers, int) or total_layers <= 0:
        return ([], 0.0, 0.0)
    hidden_size = getattr(hf_conf, "hidden_size", None)
    if hidden_size is None:
        hidden_size = getattr(tf_conf, "hidden_size", None)
    if hidden_size is None or hidden_size <= 0:
        return ([], 0.0, 0.0)
    intermediate_size = getattr(
        hf_conf,
        "intermediate_size",
        getattr(tf_conf, "ffn_hidden_size", hidden_size * 4),
    )
    num_heads = getattr(
        hf_conf, "num_attention_heads", getattr(tf_conf, "num_attention_heads", 1)
    )
    num_kv_heads = getattr(
        hf_conf,
        "num_key_value_heads",
        getattr(tf_conf, "num_query_groups", num_heads),
    )
    head_dim = getattr(hf_conf, "head_dim", None)
    if head_dim is None:
        kv_channels = getattr(tf_conf, "kv_channels", None)
        if kv_channels:
            head_dim = kv_channels
        else:
            head_dim = hidden_size // max(num_heads, 1)
    attention_bias = bool(
        getattr(hf_conf, "attention_bias", False)
        or getattr(tf_conf, "add_bias_linear", False)
    )
    add_bias_linear = bool(getattr(tf_conf, "add_bias_linear", False))
    gated_linear_unit = bool(getattr(tf_conf, "gated_linear_unit", False))
    def mlp_params(intermediate: int | None) -> float:
        if not intermediate or intermediate <= 0:
            return 0.0
        proj = hidden_size * intermediate
        gate = hidden_size * intermediate if gated_linear_unit else 0.0
        down = intermediate * hidden_size
        bias = 0.0
        if add_bias_linear:
            bias = (2 if gated_linear_unit else 1) * intermediate + hidden_size
        return float(proj + gate + down + bias)
    q_params = hidden_size * (num_heads * head_dim)
    kv_proj = num_kv_heads * head_dim
    k_params = hidden_size * kv_proj
    v_params = hidden_size * kv_proj
    o_params = hidden_size * hidden_size
    attn_bias_params = 0.0
    if attention_bias:
        attn_bias_params = (num_heads * head_dim) + (2 * kv_proj) + hidden_size
    attn_and_norm = (
        q_params
        + k_params
        + v_params
        + o_params
        + attn_bias_params
        + (2.0 * hidden_size)
    )
    dense_mlp = mlp_params(int(intermediate_size))
    dense_layer_params = float(attn_and_norm + dense_mlp)
    vocab_size = getattr(hf_conf, "vocab_size", 0)
    embedding_params = float(vocab_size * hidden_size)
    if getattr(hf_conf, "embedding_bias", False):
        embedding_params += float(vocab_size)
    output_params = float(vocab_size * hidden_size)
    if getattr(hf_conf, "tie_word_embeddings", False):
        output_params = embedding_params
    layer_weights: list[float] = [dense_layer_params] * total_layers
    num_moe_experts = getattr(tf_conf, "num_moe_experts", None)
    if num_moe_experts:
        moe_hidden_size = getattr(tf_conf, "moe_ffn_hidden_size", None)
        if moe_hidden_size is None:
            moe_hidden_size = getattr(hf_conf, "moe_intermediate_size", None)
        if moe_hidden_size is None:
            moe_hidden_size = intermediate_size
        expert_parallel_size = getattr(tf_conf, "expert_model_parallel_size", 1) or 1
        num_local_experts = math.ceil(num_moe_experts / max(expert_parallel_size, 1))
        router_params = hidden_size * num_moe_experts
        if getattr(tf_conf, "moe_router_enable_expert_bias", False):
            router_params += num_moe_experts
        expert_params = mlp_params(int(moe_hidden_size)) * num_local_experts
        shared_size = getattr(tf_conf, "moe_shared_expert_intermediate_size", None)
        shared_params = mlp_params(int(shared_size)) if shared_size else 0.0
        moe_layer_params = float(
            attn_and_norm + router_params + expert_params + shared_params
        )
        moe_layer_indices: set[int] = set()
        freq = getattr(tf_conf, "moe_layer_freq", 1)
        if isinstance(freq, int):
            step = abs(freq)
            assert step >= 1
            for idx in range(step - 1, total_layers, step):
                moe_layer_indices.add(idx)
        elif isinstance(freq, list) or isinstance(freq, tuple):
            assert len(freq) == total_layers
            for idx, is_moe in enumerate(freq):
                if is_moe:
                    moe_layer_indices.add(idx)
        for idx in moe_layer_indices:
            layer_weights[idx] = moe_layer_params
    return (layer_weights, embedding_params, output_params)

from typing import IO, Dict, List, Mapping, Optional, Tuple, Union, cast
# File typing inspired by the flexibility of types within the httpx library
# https://github.com/encode/httpx/blob/master/httpx/_types.py
FileContent = Union[IO[bytes], bytes, str]
File = Union[
    # file (or bytes)
    FileContent,
    # (filename, file (or bytes))
    Tuple[Optional[str], FileContent],
    # (filename, file (or bytes), content_type)
    Tuple[Optional[str], FileContent, Optional[str]],
    # (filename, file (or bytes), content_type, headers)
    Tuple[
        Optional[str],
        FileContent,
        Optional[str],
        Mapping[str, str],
    ],
]
def convert_file_dict_to_httpx_tuples(
    d: Dict[str, Union[File, List[File]]],
) -> List[Tuple[str, File]]:
    """
    The format we use is a list of tuples, where the first element is the
    name of the file and the second is the file object. Typically HTTPX wants
    a dict, but to be able to send lists of files, you have to use the list
    approach (which also works for non-lists)
    https://github.com/encode/httpx/pull/1032
    """
    httpx_tuples = []
    for key, file_like in d.items():
        if isinstance(file_like, list):
            for file_like_item in file_like:
                httpx_tuples.append((key, file_like_item))
        else:
            httpx_tuples.append((key, file_like))
    return httpx_tuples
def with_content_type(*, file: File, default_content_type: str) -> File:
    """
    This function resolves to the file's content type, if provided, and defaults
    to the default_content_type value if not.
    """
    if isinstance(file, tuple):
        if len(file) == 2:
            filename, content = cast(Tuple[Optional[str], FileContent], file)  # type: ignore
            return (filename, content, default_content_type)
        elif len(file) == 3:
            filename, content, file_content_type = cast(Tuple[Optional[str], FileContent, Optional[str]], file)  # type: ignore
            out_content_type = file_content_type or default_content_type
            return (filename, content, out_content_type)
        elif len(file) == 4:
            filename, content, file_content_type, headers = cast(  # type: ignore
                Tuple[Optional[str], FileContent, Optional[str], Mapping[str, str]], file
            )
            out_content_type = file_content_type or default_content_type
            return (filename, content, out_content_type, headers)
        else:
            raise ValueError(f"Unexpected tuple length: {len(file)}")
    return (None, file, default_content_type)

import os
from ...utils import logging
from .utils import DataProcessor, InputExample
logger = logging.get_logger(__name__)
class XnliProcessor(DataProcessor):
    """
    Processor for the XNLI dataset. Adapted from
    https://github.com/google-research/bert/blob/f39e881b169b9d53bea03d2d341b31707a6c052b/run_classifier.py#L207
    """
    def __init__(self, language, train_language=None):
        self.language = language
        self.train_language = train_language
    def get_train_examples(self, data_dir):
        """See base class."""
        lg = self.language if self.train_language is None else self.train_language
        lines = self._read_tsv(os.path.join(data_dir, f"XNLI-MT-1.0/multinli/multinli.train.{lg}.tsv"))
        examples = []
        for i, line in enumerate(lines):
            if i == 0:
                continue
            guid = f"train-{i}"
            text_a = line[0]
            text_b = line[1]
            label = "contradiction" if line[2] == "contradictory" else line[2]
            if not isinstance(text_a, str):
                raise TypeError(f"Training input {text_a} is not a string")
            if not isinstance(text_b, str):
                raise TypeError(f"Training input {text_b} is not a string")
            if not isinstance(label, str):
                raise TypeError(f"Training label {label} is not a string")
            examples.append(InputExample(guid=guid, text_a=text_a, text_b=text_b, label=label))
        return examples
    def get_test_examples(self, data_dir):
        """See base class."""
        lines = self._read_tsv(os.path.join(data_dir, "XNLI-1.0/xnli.test.tsv"))
        examples = []
        for i, line in enumerate(lines):
            if i == 0:
                continue
            language = line[0]
            if language != self.language:
                continue
            guid = f"test-{i}"
            text_a = line[6]
            text_b = line[7]
            label = line[1]
            if not isinstance(text_a, str):
                raise TypeError(f"Training input {text_a} is not a string")
            if not isinstance(text_b, str):
                raise TypeError(f"Training input {text_b} is not a string")
            if not isinstance(label, str):
                raise TypeError(f"Training label {label} is not a string")
            examples.append(InputExample(guid=guid, text_a=text_a, text_b=text_b, label=label))
        return examples
    def get_labels(self):
        """See base class."""
        return ["contradiction", "entailment", "neutral"]
xnli_processors = {
    "xnli": XnliProcessor,
}
xnli_output_modes = {
    "xnli": "classification",
}
xnli_tasks_num_labels = {
    "xnli": 3,
}

import types
import importlib
def test_plugin_with_none_plugin_class(monkeypatch):
    reg = get_cortex_registry()
    fake_mod = types.SimpleNamespace(PLUGIN_CLASS=None)
    real_import = importlib.import_module
    def fake_import(name):
        # Accept both new and legacy import paths
        if name in (
            "cortex.llm_provider.invalid_none",
            "cortex.llm_engine.invalid_none",
        ):
            return fake_mod
        return real_import(name)
    monkeypatch.setattr(importlib, "import_module", fake_import)
    reg.register_engine_module(
        "invalid_none",
        "cortex.llm_provider.invalid_none",
        cortex="llm_provider",
    )
    try:
        reg.load_engine("invalid_none")
        assert False, "Expected ValueError for invalid PLUGIN_CLASS"
    except ValueError as e:
        assert "PLUGIN_CLASS" in str(e) and "None" in str(e)

import sys, json, argparse
from pathlib import Path
from typing import Set, List, Dict
from config_manager import ConfigManager
from obsidian_utils import extract_links_recursive, extract_tags
def simple_read(path):
    try:
        return Path(path).read_text(encoding='utf-8')
    except Exception:
        return ""
def write_json(path, data):
    Path(path).write_text(json.dumps(data, indent=2), encoding='utf-8')
def find_tag_similar_docs(
    seed_tags: Set[str],
    zettel_dir: Path,
    seed_path: Path,
    max_similar: int = 5
) -> List[str]:
    """
    Find notes with overlapping tags.
    Returns list of paths: ['/path/to/doc1.md']
    """
    similar = []
    for note_path in zettel_dir.rglob("*.md"):
        if note_path.resolve() == seed_path.resolve():
            continue
        try:
            content = note_path.read_text(encoding='utf-8')
            note_tags = extract_tags(content)
            overlap = len(seed_tags & note_tags)
            if overlap > 0:
                similar.append({
                    'path': str(note_path.resolve()),
                    'overlap': overlap
                })
        except Exception as e:
            continue
    # Sort by overlap descending, take top max_similar
    similar.sort(key=lambda x: x['overlap'], reverse=True)
    return [s['path'] for s in similar[:max_similar]]
def find_links(args):
    # Load configuration
    config = ConfigManager.load()
    if args.zettel_dir:
        zettel_dir = Path(args.zettel_dir).expanduser()
    else:
        zettel_dir_str = config.get('zettel_dir')
        if not zettel_dir_str:
             print("Error: zettel_dir not configured.", file=sys.stderr)
             sys.exit(1)
        zettel_dir = Path(zettel_dir_str).expanduser()
    link_depth = config.get('link_depth', 2)
    max_links = config.get('max_links', 10)
    seed_path = Path(args.input).expanduser().resolve()
    if not seed_path.exists():
        print(f"Error: Input note not found: {seed_path}", file=sys.stderr)
        sys.exit(1)
    text = simple_read(seed_path)
    # Extract wikilinked documents
    linked_paths = set()
    if zettel_dir.exists():
        # extract_links_recursive returns dict {path: {level, content}}
        raw_linked_docs = extract_links_recursive(seed_path, zettel_dir, link_depth, max_links)
        for path in raw_linked_docs.keys():
             linked_paths.add(str(path))
        print(f"Extracted {len(linked_paths)} linked documents (depth={link_depth}, max={max_links})", file=sys.stderr)
    else:
        print(f"Warning: Zettelkasten directory not found: {zettel_dir}", file=sys.stderr)
    # Extract tag-similar documents
    tag_similar_paths = []
    if zettel_dir.exists():
        seed_tags = extract_tags(text)
        if seed_tags:
            tag_similar_paths = find_tag_similar_docs(seed_tags, zettel_dir, seed_path, max_similar=5)
            print(f"Found {len(tag_similar_paths)} tag-similar documents (seed tags: {sorted(seed_tags)})", file=sys.stderr)
    # Combine all paths, keeping seed note out (it's implicit context)
    all_paths = set(linked_paths)
    for p in tag_similar_paths:
        all_paths.add(p)
    # Ensure seed path is not in the list (if it somehow got linked)
    if str(seed_path) in all_paths:
        all_paths.remove(str(seed_path))
    # Output as JSON list
    output_list = list(all_paths)
    write_json(args.output, output_list)
    print(f'Wrote {len(output_list)} paths to {args.output}', file=sys.stderr)
if __name__ == '__main__':
    p = argparse.ArgumentParser()
    p.add_argument('--input', required=True, help='Input note path')
    p.add_argument('--output', required=True, help='Output JSON path')
    p.add_argument('--zettel-dir', help='Override Zettelkasten directory')
    args = p.parse_args()
    find_links(args)

