class GSM8kDataPacker(DataPacker):
    """
    This is a demo data packer that wraps the underlying data packer of the selected model.
    This is meaningless for this example, but useful for explaining:
        - how dataset data is processed and collated into a mini-batch for rollout engine;
        - how rollout output is processed and collated into a mini-batch for policy model;
    """
    def __init__(self, tool_agent: Optional[ToolAgent] = None, *args, **kwargs):
        super().__init__(tool_agent=tool_agent, *args, **kwargs)
        # Check source code of DecoderOnlyLLMDataPacker to see how it's implemented
        self.underlying_data_packer = DecoderOnlyLLMDataPacker(tool_agent=tool_agent)
    def setup(
        self,
        config: CosmosConfig,
        *args,
        tool_agent: Optional[ToolAgent] = None,
        **kwargs,
    ):
        """
        This method is optional and get called by launcher after being mounted
        `config`: config;
        """
        super().setup(config, *args, tool_agent=tool_agent, **kwargs)
        self.underlying_data_packer.setup(
            config, *args, tool_agent=tool_agent, **kwargs
        )
    def get_rollout_input(self, item: Any) -> Any:
        """
        Convert dataset item into what rollout engine (e.g. vllm) expects
        """
        return self.underlying_data_packer.get_rollout_input(item)
    def rollout_collate_fn(self, items: List[Any]) -> Any:
        """
        Collate the rollout inputs into a mini-batch for rollout engine
        """
        return self.underlying_data_packer.rollout_collate_fn(items)
    def get_policy_input(
        self,
        item: Any,
        rollout_output: Union[str, List[int]],
        n_ignore_prefix_tokens: int = 0,
    ) -> Any:
        """
        Process samples & rollout output before collating them into a mini-batch
        """
        return self.underlying_data_packer.get_policy_input(
            item, rollout_output, n_ignore_prefix_tokens
        )
    def policy_compute_max_len(self, processed_samples: List[Any]) -> int:
        """
        Compute the maximum sequence length of the mini-batch
        """
        return self.underlying_data_packer.policy_compute_max_len(processed_samples)
    def policy_collate_fn(
        self, processed_samples: List[Any], computed_max_len: int
    ) -> Dict[str, Any]:
        """
        Collate the mini-batch into the kwargs required by the policy model
        """
        return self.underlying_data_packer.policy_collate_fn(
            processed_samples, computed_max_len
        )
    def extend_conversation(
        self,
        conversation: ConversationType,
        responses: List[str],
        ground_truth: Optional[str] = None,
    ) -> ConversationType:
        """
        Extend the conversation by models response.
        """
        assert self.tool_agent is not None, "Tool agent is not set"
        real_response = ""
        for response in responses:
            if response:
                real_response = response
                break
        if real_response == "":
            return conversation
        # 1. add real_response as assistant
        conversation = add_assistant_message(conversation, real_response)
        # 2. check if the response contains tool call instruction
        tool_responses = self.tool_agent.call_tools(real_response, ground_truth)
        if tool_responses:
            for tr in tool_responses:
                conversation = add_tool_response_messages(conversation, tr.text)
        return conversation
if __name__ == "__main__":
    def get_dataset(config: CosmosConfig) -> Dataset:
        return GSM8kDataset()
    def get_val_dataset(config: CosmosConfig) -> Dataset:
        return GSM8kValDataset()
    # build the tool agent for multi-turn conversation
    tool_agent = ToolAgent(HermesToolParser(), [GSM8kTool()])
    # It is best practice to pass the dataset as a factory function
    launch_worker(
        dataset=get_dataset,
        val_dataset=get_val_dataset,
        # Override the reward functions defined in toml
        reward_fns=[custom_reward_fn],
        # Optional: if not provided, the default data packer of the selected model will be used
        data_packer=GSM8kDataPacker(tool_agent=tool_agent),
        val_data_packer=GSM8kDataPacker(tool_agent=tool_agent),
        custom_logger_fns=[custom_logger_fn],
    )

import unittest
from noether.core.schedules import ScheduleBase, SequentialStepSchedule, SequentialStepScheduleConfig
class DummySchedule(ScheduleBase):
    def __init__(self, step_to_value=None, **kwargs):
        super().__init__(**kwargs)
        self.step_to_value = step_to_value
    def _get_value(self, step: int, total_steps: int) -> float:
        if self.step_to_value is None:
            return 0.0
        return self.step_to_value[step]
class TestSequentialStepSchedule(unittest.TestCase):
    def test_propagate_singleconfig(self):
        sched = SequentialStepSchedule(
            [
                SequentialStepScheduleConfig(schedule=DummySchedule()),
            ]
        )
        self.assertEqual(0, sched.schedule_configs[0].start_step)
        self.assertIsNone(sched.schedule_configs[0].end_step)
    def test_propagate_forward(self):
        sched = SequentialStepSchedule(
            [
                SequentialStepScheduleConfig(end_step=10, schedule=DummySchedule()),
                SequentialStepScheduleConfig(schedule=DummySchedule()),
            ]
        )
        self.assertEqual(0, sched.schedule_configs[0].start_step)
        self.assertEqual(10, sched.schedule_configs[0].end_step)
        self.assertEqual(10, sched.schedule_configs[1].start_step)
        self.assertIsNone(sched.schedule_configs[1].end_step)
    def test_propagate_backward(self):
        sched = SequentialStepSchedule(
            [
                SequentialStepScheduleConfig(schedule=DummySchedule()),
                SequentialStepScheduleConfig(start_step=10, schedule=DummySchedule()),
            ]
        )
        self.assertEqual(0, sched.schedule_configs[0].start_step)
        self.assertEqual(10, sched.schedule_configs[0].end_step)
        self.assertEqual(10, sched.schedule_configs[1].start_step)
        self.assertIsNone(sched.schedule_configs[1].end_step)
    def test_propagate_gap(self):
        sched = SequentialStepSchedule(
            [
                SequentialStepScheduleConfig(end_step=10, schedule=DummySchedule()),
                SequentialStepScheduleConfig(start_step=15, schedule=DummySchedule()),
            ]
        )
        self.assertEqual(0, sched.schedule_configs[0].start_step)
        self.assertEqual(10, sched.schedule_configs[0].end_step)
        self.assertEqual(15, sched.schedule_configs[1].start_step)
        self.assertIsNone(sched.schedule_configs[1].end_step)
    def test_propagate_middle(self):
        sched = SequentialStepSchedule(
            [
                SequentialStepScheduleConfig(end_step=10, schedule=DummySchedule()),
                SequentialStepScheduleConfig(schedule=DummySchedule()),
                SequentialStepScheduleConfig(start_step=15, schedule=DummySchedule()),
            ]
        )
        self.assertEqual(0, sched.schedule_configs[0].start_step)
        self.assertEqual(10, sched.schedule_configs[0].end_step)
        self.assertEqual(10, sched.schedule_configs[1].start_step)
        self.assertEqual(15, sched.schedule_configs[1].end_step)
        self.assertEqual(15, sched.schedule_configs[2].start_step)
        self.assertIsNone(sched.schedule_configs[2].end_step)
    def test_propagate_noneinbetween(self):
        with self.assertRaises(ValueError):
            SequentialStepSchedule(
                [
                    SequentialStepScheduleConfig(end_step=10, schedule=DummySchedule()),
                    SequentialStepScheduleConfig(schedule=DummySchedule()),
                    SequentialStepScheduleConfig(schedule=DummySchedule()),
                ]
            )
    def test_check_singleconfig(self):
        with self.assertRaises(ValueError):
            SequentialStepSchedule(
                [
                    SequentialStepScheduleConfig(start_step=5, end_step=3, schedule=DummySchedule()),
                ]
            )
    def test_check_propagatedendstep(self):
        with self.assertRaises(ValueError):
            SequentialStepSchedule(
                [
                    SequentialStepScheduleConfig(end_step=10, schedule=DummySchedule()),
                    SequentialStepScheduleConfig(start_step=5, schedule=DummySchedule()),
                ]
            )
    def test_get_sequential_schedule_config_zeroduration(self):
        sched = SequentialStepSchedule(
            [
                SequentialStepScheduleConfig(end_step=0, schedule=DummySchedule()),
                SequentialStepScheduleConfig(schedule=DummySchedule()),
            ]
        )
        self.assertEqual(sched.schedule_configs[1], sched.get_sequential_schedule_config(0))
    def test_get_sequential_schedule_config(self):
        sched = SequentialStepSchedule(
            [
                SequentialStepScheduleConfig(start_step=5, end_step=10, schedule=DummySchedule()),
                SequentialStepScheduleConfig(end_step=15, schedule=DummySchedule()),
                SequentialStepScheduleConfig(schedule=DummySchedule()),
            ]
        )
        for i in range(5):
            self.assertIsNone(sched.get_sequential_schedule_config(i))
        for i in range(5, 10):
            self.assertEqual(sched.schedule_configs[0], sched.get_sequential_schedule_config(i))
        for i in range(10, 15):
            self.assertEqual(sched.schedule_configs[1], sched.get_sequential_schedule_config(i))
        for i in range(15, 30):
            self.assertEqual(sched.schedule_configs[2], sched.get_sequential_schedule_config(i))
    def test_get_sequential_schedule_config_gap(self):
        sched = SequentialStepSchedule(
            [
                SequentialStepScheduleConfig(start_step=5, end_step=10, schedule=DummySchedule()),
                SequentialStepScheduleConfig(start_step=15, end_step=20, schedule=DummySchedule()),
                SequentialStepScheduleConfig(schedule=DummySchedule()),
            ]
        )
        for i in range(5):
            self.assertIsNone(sched.get_sequential_schedule_config(i))
        for i in range(5, 10):
            self.assertEqual(sched.schedule_configs[0], sched.get_sequential_schedule_config(i))
        # gap returns previous schedule
        for i in range(10, 15):
            self.assertEqual(sched.schedule_configs[0], sched.get_sequential_schedule_config(i))
        for i in range(15, 20):
            self.assertEqual(sched.schedule_configs[1], sched.get_sequential_schedule_config(i))
        for i in range(20, 30):
            self.assertEqual(sched.schedule_configs[2], sched.get_sequential_schedule_config(i))
    def test_get_value_before_first_schedule(self):
        sched = SequentialStepSchedule(
            [
                SequentialStepScheduleConfig(start_step=5, schedule=DummySchedule(step_to_value={0: 0.5})),
            ]
        )
        for i in range(5):
            self.assertEqual(0.5, sched.get_value(i, 10))
    def test_get_value_after_last_schedule(self):
        sched = SequentialStepSchedule(
            [
                SequentialStepScheduleConfig(
                    start_step=3,
                    end_step=5,
                    schedule=DummySchedule(step_to_value={0: 0.1, 1: 0.2}),
                ),
            ]
        )
        for i in range(4):
            self.assertEqual(0.1, sched.get_value(i, 11))
        self.assertEqual(0.2, sched.get_value(4, 11))
        for i in range(5, 11):
            self.assertEqual(0.2, sched.get_value(i, 11))
    def test_tostring(self):
        sched = SequentialStepSchedule(
            [
                SequentialStepScheduleConfig(
                    start_step=3,
                    end_step=5,
                    schedule=DummySchedule(step_to_value={0: 0.1, 1: 0.2}),
                ),
            ]
        )
        lines = str(sched).split("\n")
        self.assertEqual(3, len(lines))
        self.assertEqual(SequentialStepSchedule.__name__, lines[0])
        self.assertEqual("  (0): 3 - 5 DummySchedule", lines[1])
        self.assertEqual(")", lines[2])

from dataclasses import dataclass, field
from datetime import datetime
from typing import cast
from rich.text import Text
from epstein_files.documents.document import CLOSE_PROPERTIES_CHAR, Document
from epstein_files.documents.documents.doc_cfg import CommunicationCfg
from epstein_files.output.highlight_config import HIGHLIGHTED_CONTACTS, get_style_for_name, styled_name
from epstein_files.output.rich import styled_key_value
from epstein_files.people.names import UNKNOWN, Name
from epstein_files.util.helpers.data_helpers import uniquify
from epstein_files.util.helpers.rich_helpers import no_bold
TIMESTAMP_SECONDS_REGEX = re.compile(r":\d{2}$")
@dataclass
class Communication(Document):
    """
    Superclass for `Email` and `MessengerLog`.
    Attributes:
        recipients (list[Name]): People to whom this email was sent.
    """
    extracted_recipients: list[Name] = field(default_factory=list)
    def __post_init__(self):
        super().__post_init__()
        self.extracted_recipients = [] if self.config and self.config.recipients else self._extract_recipients()
    @property
    def author_or_unknown(self) -> str:
        return self.author or UNKNOWN
    @property
    def author_style(self) -> str:
        return get_style_for_name(self.author)
    @property
    def author_txt(self) -> Text:
        return styled_name(self.author)
    @property
    def border_style(self) -> str:
        return no_bold(self.author_style)
    @property
    def people(self) -> list[str]:
        """Names of people who either sent/received this email or are mentioned in it."""
        if self.config and self.config.people:
            return self.config.people
        people = super().people + [p for p in self.participants if p]
        return sorted(uniquify(people))
    @property
    def config(self) -> CommunicationCfg | None:
        """Configured timestamp, if any."""
        cfg = super().config
        if cfg and not isinstance(cfg, CommunicationCfg):
            self.warn(f"Found config that's the wrong type! {repr(cfg)}")
            cfg = cast(CommunicationCfg, cfg)
        return cfg
    @property
    def has_unknown_participant(self) -> bool:
        return None in self.participants
    @property
    def has_unknown_recipient(self) -> bool:
        return None in (self.recipients or [None])
    @property
    def is_recipient_uncertain(self) -> bool:
        return bool(self.config and self.config.recipient_uncertain)
    @property
    def participants(self) -> set[Name]:
        """Author + recipients including a `None` if `self.recipients` is empty."""
        return set([self.author] + (self.recipients or [None]))
    @property
    def recipients(self) -> list[Name]:
        if self.config and self.config.recipients:
            return self.config.recipients
        else:
            return self.extracted_recipients
    @property
    def recipient_style(self) -> str:
        return get_style_for_name((self.recipients or [self.author])[0])
    @property
    def timestamp_without_seconds(self) -> str:
        return TIMESTAMP_SECONDS_REGEX.sub('', str(self.timestamp))
    @property
    def _summary(self) -> Text:
        """One line summary mostly for logging."""
        return self._summary_with_author.append(CLOSE_PROPERTIES_CHAR)
    @property
    def _summary_with_author(self) -> Text:
        """Append author information to `super().summary`, bracket is left open."""
        author_str = styled_key_value('author', Text(f"'{self.author_or_unknown}'", style=self.author_style))
        return super()._summary.append(', ').append(author_str)
    def colored_external_links(self) -> Text:
        """Overrides super() method to apply `self.author_style`."""
        return self.file_info.build_external_links(self.recipient_style, with_alt_links=True)
    def _extract_recipients(self) -> list[Name]:
        """Overload in subclasses"""
        return []
    @classmethod
    def default_category(cls) -> str:
        return cls.__name__.lower()

