        side = 'sell'
        needed = self.needed['take_profit']
        order = utils.build_order_info(price, side, size, symbol, 'take_profit')
        response = self.calls.submit_order(symbol,
                                           side=side,
                                           type='limit',
                                           time_in_force='gtc',
