import sys
import importlib.resources
from typing import Optional
import click
from rich import print as rprint
# ----------------------------------------------------------------------
# Dynamically determine PDD_PATH at runtime.
# ----------------------------------------------------------------------
def get_local_pdd_path() -> str:
    """
    Return the PDD_PATH directory.
    First check the environment variable. If not set, attempt to
    deduce it via importlib.resources. If that fails, abort.
    """
    if "PDD_PATH" in os.environ:
        return os.environ["PDD_PATH"]
    else:
        try:
            p = importlib.resources.files("pdd").joinpath("cli.py")
            fallback_path = str(p.parent)
            # Also set it back into the environment for consistency
            os.environ["PDD_PATH"] = fallback_path
            return fallback_path
        except ImportError:
            rprint(
                "[red]Error: Could not determine the path to the 'pdd' package. "
                "Please set the PDD_PATH environment variable manually.[/red]"
            )
            sys.exit(1)
# ----------------------------------------------------------------------
# Simplified shell RC path logic
# ----------------------------------------------------------------------
def get_shell_rc_path(shell: str) -> Optional[str]:
    """Return the default RC file path for a given shell name."""
    home = os.path.expanduser("~")
    if shell == "bash":
        return os.path.join(home, ".bashrc")
    elif shell == "zsh":
        return os.path.join(home, ".zshrc")
    elif shell == "fish":
        return os.path.join(home, ".config", "fish", "config.fish")
    return None
def get_current_shell() -> Optional[str]:
    """Determine the currently running shell more reliably."""
    if not os.environ.get('PYTEST_CURRENT_TEST'):
        # Method 1: Check process name using 'ps'
        try:
            import subprocess
            result = subprocess.run(['ps', '-p', str(os.getppid()), '-o', 'comm='], 
                                capture_output=True, text=True)
            if result.returncode == 0:
                # Strip whitespace and get basename without path
                shell = os.path.basename(result.stdout.strip())
                # Remove leading dash if present (login shell)
                return shell.lstrip('-')
        except (subprocess.SubprocessError, FileNotFoundError):
            pass
        # Method 2: Check $0 special parameter
        try:
            result = subprocess.run(['sh', '-c', 'echo "$0"'], 
                                capture_output=True, text=True)
            if result.returncode == 0:
                shell = os.path.basename(result.stdout.strip())
                return shell.lstrip('-')
        except (subprocess.SubprocessError, FileNotFoundError):
            pass
    # Fallback to SHELL env var if all else fails
    return os.path.basename(os.environ.get("SHELL", ""))
def get_completion_script_extension(shell: str) -> str:
    """Get the appropriate file extension for shell completion scripts."""
    mapping = {
        "bash": "sh",
        "zsh": "zsh",
        "fish": "fish"
    }
    return mapping.get(shell, shell)
def install_completion(quiet: bool = False):
    """
    Install shell completion for the PDD CLI by detecting the user's shell,
    copying the relevant completion script, and appending a source command
    to the user's shell RC file if not already present.
    """
    shell = get_current_shell()
    rc_file = get_shell_rc_path(shell)
    if not rc_file:
        if not quiet:
            rprint(f"[red]Unsupported shell: {shell}[/red]")
        raise click.Abort()
    ext = get_completion_script_extension(shell)
    # Dynamically look up the local path at runtime:
    local_pdd_path = get_local_pdd_path()
    completion_script_path = os.path.join(local_pdd_path, f"pdd_completion.{ext}")
    if not os.path.exists(completion_script_path):
        if not quiet:
            rprint(f"[red]Completion script not found: {completion_script_path}[/red]")
        raise click.Abort()
    source_command = f"source {completion_script_path}"
    try:
        # Ensure the RC file exists (create if missing).
        if not os.path.exists(rc_file):
            # Create parent directories if they don't exist
            rc_dir = os.path.dirname(rc_file)
            if rc_dir: # Ensure rc_dir is not an empty string (e.g. if rc_file is in current dir)
                 os.makedirs(rc_dir, exist_ok=True)
            with open(rc_file, "w", encoding="utf-8") as cf:
                cf.write("") # Create an empty file
        # Read existing content
        with open(rc_file, "r", encoding="utf-8") as cf:
            content = cf.read()
        if source_command not in content:
            with open(rc_file, "a", encoding="utf-8") as rf:
                rf.write(f"\n# PDD CLI completion\n{source_command}\n")

            if not quiet:
                rprint(f"[green]Shell completion installed for {shell}.[/green]")
                rprint(f"Please restart your shell or run 'source {rc_file}' to enable completion.")
        else:
            if not quiet:
                rprint(f"[yellow]Shell completion already installed for {shell}.[/yellow]")
    except OSError as exc:
        if not quiet:
            rprint(f"[red]Failed to install shell completion: {exc}[/red]")
        raise click.Abort()

import os
import sys
import json
import argparse
import requests
# Base Configuration
BASE_URL = "https://echodecks.com/api/apps/68bc0769be6e58e1c8385b2b/functions/externalApi"
def get_api_key():
    api_key = os.environ.get("ECHODECKS_API_KEY")
    if not api_key:
        print(json.dumps({"error": "Missing ECHODECKS_API_KEY environment variable."}))
        sys.exit(1)
    return api_key
def make_request(method, resource, action=None, params=None, data=None):
    headers = {
        "X-API-KEY": get_api_key(),
        "Content-Type": "application/json"
    }

    url = f"{BASE_URL}?resource={resource}"
    if action:
        url += f"&action={action}"

    # Merge extra params into URL if provided (e.g. deck_id for GET requests)
    if params:
        for key, value in params.items():
            if value is not None:
                url += f"&{key}={value}"
    try:
        if method == "GET":
            response = requests.get(url, headers=headers)
        elif method == "POST":
            response = requests.post(url, headers=headers, json=data)
        elif method == "PUT":
            response = requests.put(url, headers=headers, json=data)
        elif method == "DELETE":
            response = requests.delete(url, headers=headers)
        else:
            return {"error": f"Unsupported method: {method}"}

        response.raise_for_status()

        # Try parsing JSON, fallback to text if empty or not JSON
        try:
            return response.json()
        except json.JSONDecodeError:
            return {"status": "success", "message": response.text}

    except requests.exceptions.RequestException as e:
        error_msg = str(e)
        if hasattr(e.response, 'text') and e.response.text:
             try:
                 api_err = json.loads(e.response.text)
                 error_msg = api_err.get('message', error_msg)
             except:
                 error_msg = e.response.text
        return {"error": error_msg}
# --- Command Handlers ---
def handle_list_decks(args):
    return make_request("GET", "decks", params={"id": args.id})
def handle_create_deck(args):
    return make_request("POST", "decks", data={"title": args.title, "description": args.description})
def handle_list_cards(args):
    return make_request("GET", "cards", params={"deck_id": args.deck_id, "id": args.card_id})
def handle_get_due_cards(args):
    return make_request("GET", "study", action="due", params={"deck_id": args.deck_id})
def handle_submit_review(args):
    return make_request("POST", "study", action="submit", data={
        "card_id": args.card_id,
        "quality": args.quality
    })
def handle_generate_cards(args):
    data = {"deck_id": args.deck_id}
    if args.topic:
        data["topic"] = args.topic
    if args.text:
        data["text"] = args.text
    return make_request("POST", "generate", action="cards", data=data)
def handle_generate_podcast(args):
    return make_request("POST", "podcasts", action="generate", data={
        "deck_id": args.deck_id,
        "style": args.style
    })
def handle_list_podcasts(args):
    return make_request("GET", "podcasts", params={"deck_id": args.deck_id, "id": args.id})
def handle_get_user(args):
    return make_request("GET", "user")
def handle_get_podcast_status(args):
    return make_request("GET", "podcasts", action="status", params={"id": args.id})
# --- Main CLI ---
def main():
    parser = argparse.ArgumentParser(description="EchoDecks API Client")
    subparsers = parser.add_subparsers(dest="command", required=True)
    # ... (existing subparsers) ...
    p_pod_status = subparsers.add_parser("podcast-status", help="Check podcast status")
    p_pod_status.add_argument("--id", required=True)
    # Decks
    p_decks = subparsers.add_parser("list-decks", help="List decks or get a specific deck")
    p_decks.add_argument("--id", help="Specific Deck ID")

    p_create_deck = subparsers.add_parser("create-deck", help="Create a new deck")
    p_create_deck.add_argument("--title", required=True)
    p_create_deck.add_argument("--description")
    # Cards
    p_cards = subparsers.add_parser("list-cards", help="List cards in a deck")
    p_cards.add_argument("--deck-id", required=True)
    p_cards.add_argument("--card-id", help="Specific Card ID")
    # Study
    p_due = subparsers.add_parser("get-due", help="Get due cards")
    p_due.add_argument("--deck-id", help="Filter by Deck ID")
    p_review = subparsers.add_parser("submit-review", help="Submit a card review")
    p_review.add_argument("--card-id", required=True)
    p_review.add_argument("--quality", type=int, required=True, choices=[0, 1, 2, 3], help="0=Again, 1=Hard, 2=Good, 3=Easy")
    # Generate
    p_gen_cards = subparsers.add_parser("generate-cards", help="AI Generate cards")
    p_gen_cards.add_argument("--topic")
    p_gen_cards.add_argument("--text")
    p_gen_cards.add_argument("--deck-id", required=True)
    p_gen_pod = subparsers.add_parser("generate-podcast", help="AI Generate podcast")
    p_gen_pod.add_argument("--deck-id", required=True)
    p_gen_pod.add_argument("--style", default="summary", help="Podcast style (e.g., summary, conversation)")
    # Podcasts
    p_pods = subparsers.add_parser("list-podcasts", help="List podcasts")
    p_pods.add_argument("--deck-id")
    p_pods.add_argument("--id")
    # User
    subparsers.add_parser("get-user", help="Get user info")
    args = parser.parse_args()
    commands = {
        "list-decks": handle_list_decks,
        "create-deck": handle_create_deck,
        "list-cards": handle_list_cards,
        "get-due": handle_get_due_cards,
        "submit-review": handle_submit_review,
        "generate-cards": handle_generate_cards,
        "generate-podcast": handle_generate_podcast,
        "list-podcasts": handle_list_podcasts,
        "podcast-status": handle_get_podcast_status,
        "get-user": handle_get_user
    }
    if args.command in commands:
        result = commands[args.command](args)
        print(json.dumps(result, indent=2))
    else:
        print(json.dumps({"error": "Unknown command"}))
if __name__ == "__main__":
    main()

from os import environ
from pathlib import Path
from epstein_files.util.logging import exit_with_error, logger
def get_env_dir(env_var_name: str, must_exist: bool = True) -> Path | None:
    if (dir := environ.get(env_var_name)):
        dir = Path(dir)
        error_msg = f"env var {env_var_name} set to '{dir}' but that's not a directory"
        if dir.is_dir():
            return dir
        elif must_exist:
            exit_with_error(f"Required {error_msg}.\n")
        else:
            logger.warning(f"Optional {error_msg}. Some features will be unavailable.")
            return None
    else:
        logger.warning(f"Optional env var {env_var_name} not set. Some features will be unavailable.")

import os
import torch.distributed as dist
__all__ = [
    "DistributedConfig",
    "set_config",
    "is_managed",
    "get_local_rank",
    "get_world_size",
    "get_rank",
    "get_num_nodes",
    "get_managed_world_size",
    "get_managed_rank",
    "is_distributed",
    "is_rank0",
    "is_data_rank0",
    "is_local_rank0",
    "barrier",
]
class DistributedConfig:
    @staticmethod
    def is_managed() -> bool:
        return "SLURM_PROCID" in os.environ
    def get_local_rank(self) -> int:
        if "SLURM_LOCALID" in os.environ:
            return int(os.environ["SLURM_LOCALID"])
        return self.get_rank()
    def get_num_nodes(self) -> int:
        if "SLURM_JOB_NUM_NODES" in os.environ:
            return int(os.environ["SLURM_JOB_NUM_NODES"])
        return 1
    def get_managed_world_size(self) -> int:
        return self.get_num_nodes() * int(os.environ.get("SLURM_NTASKS_PER_NODE", 1))
    def get_managed_rank(self) -> int:
        if "SLURM_PROCID" in os.environ:
            return int(os.environ["SLURM_PROCID"])
        raise RuntimeError("SLURM_PROCID not found in environment, cannot determine managed rank")
    @staticmethod
    def is_distributed() -> bool:
        return dist.is_available() and dist.is_initialized()
    def get_rank(self) -> int:
        if self.is_distributed():
            return dist.get_rank()
        return 0
    def get_world_size(self) -> int:
        if self.is_distributed():
            return dist.get_world_size()
        return 1
    def is_data_rank0(self) -> bool:
        # data has to be copied in 2 cases
        # - is_local_rank0: single-gpu, multi-gpu, multi-gpu SLURM
        #   - process with is_local_rank0 copies the data
        #   - other processes have to wait for the copying to finish via barrier
        # - get_world_size == 1: SLURM runs that are not using multi-gpu require every process to copy data
        #   - no guarantee that the processes use the same dataset
        #   - avoid race conditions
        return self.is_local_rank0() or self.get_world_size() == 1
    def is_rank0(self) -> bool:
        return self.get_rank() == 0
    def is_local_rank0(self) -> bool:
        return self.get_local_rank() == 0
    def barrier(self) -> None:
        if self.is_distributed():
            dist.barrier()
_config: DistributedConfig = DistributedConfig()
def set_config(new_config: DistributedConfig):
    global _config
    _config = new_config
def is_managed():
    return _config.is_managed()
def get_local_rank():
    return _config.get_local_rank()
def get_num_nodes():
    return _config.get_num_nodes()
def get_managed_world_size():
    return _config.get_managed_world_size()
def get_managed_rank():
    return _config.get_managed_rank()
def is_distributed():
    return _config.is_distributed()
def get_rank():
    return _config.get_rank()
def get_world_size():
    return _config.get_world_size()
def is_data_rank0():
    return _config.is_data_rank0()
def is_rank0():
    return _config.is_rank0()
def is_local_rank0():
    return _config.is_local_rank0()
def barrier():
    return _config.barrier()

