    sys.stderr.write("\n");
    sys.stderr.write("    Regularity is loosely defined as contiguous port numbering,\n");
    sys.stderr.write("order matching between ports and indices, etc.\n");
    sys.stderr.write("\n");
    sys.stderr.write("\n");
    sys.stderr.write("\n");
