# Default limit value
default_limit = ""

def is_valid_limit(s: str) -> bool:
    # Check if the input string (case-insensitive) is valid
    return s.lower() in {"", "random"}

def get_limit(s: str, size: int) -> typing.Optional[int]:
    # Convert input to lowercase for comparison
    ls = s.lower()

    # Return appropriate value based on the lowercase string
    if ls == "":
        return None
    elif ls == "random":
        return randrange(size)
    else:
        # Default case: return None
        return None

