def Tree(app):
    class Tree(Resource):
        # Define fields
        parent_id = ravel.Id(lambda: Tree, nullable=True, default=lambda: None)
        root_id = ravel.Id(lambda: Tree, nullable=True, default=lambda: None)
        name = ravel.String(nullable=False, required=True)

