CAPACITY_RGB = 1
CAPACITY_TEMPERATURE = 2
CAPACITY_LUMINANCE = 4
CAPACITY_RGB_LUMINANCE = 5
CAPACITY_TEMPERATURE_LUMINANCE = 6


async def async_setup_entry(hass: object, config_entry: object, async_add_devices):
