def _rgb_to_int(rgb: Union[tuple, dict, int]) -> int:  # pylint: disable=unsubscriptable-object
    """Convert RGB value (tuple, dict, or int) to integer representation."""
    if isinstance(rgb, int):
        return rgb
    elif isinstance(rgb, tuple):
        red, green, blue = rgb
    elif isinstance(rgb, dict):
        red = rgb['red']
        green = rgb['green']
        blue = rgb['blue']
    else:
        raise ValueError("Invalid value for RGB!")
    return (red << 16) + (green << 8) + blue


def _int_to_rgb(rgb: int) -> Tuple[int, int, int]:
    """Convert integer RGB representation to tuple of (red, green, blue)."""
    return (rgb & 16711680) >> 16, (rgb & 65280) >> 8, (rgb & 255)


def _sat_1_100(value) -> int:
    """Saturate value to range [1, 100]."""
    if value > 100:
        return 100
    elif value < 1:
        return 1
    else:
        return int(value)


class MerossLanLight(_MerossToggle, LightEntity):
    """Representation of a Meross LAN light device."""

    PLATFORM = PLATFORM_LIGHT

    def __init__(self, device: MerossDevice, id: object, p_togglex):
        """Initialize the Meross light."""
        # Determine whether to use togglex or toggle for control
        self._usetogglex = False
        if isinstance(p_togglex, list):
            for t in p_togglex:
                if t.get(mc.KEY_CHANNEL) == id:
                    self._usetogglex = True
                    break
        elif isinstance(p_togglex, dict):
            self._usetogglex = (p_togglex.get(mc.KEY_CHANNEL) == id)

        # Initialize parent with appropriate namespace/key
        super().__init__(
            device, id, None,
            mc.NS_APPLIANCE_CONTROL_TOGGLEX if self._usetogglex else mc.NS_APPLIANCE_CONTROL_TOGGLE,
            mc.KEY_TOGGLEX if self._usetogglex else mc.KEY_TOGGLE
        )

        # Initialize light state dictionary
        self._light = dict()

        # Initialize color/temperature/brightness attributes
        self._color_temp = None
        self._hs_color = None
        self._brightness = None

        # Determine device capabilities from descriptor
        self._capacity = device.descriptor.ability.get(
            mc.NS_APPLIANCE_CONTROL_LIGHT, {}).get(
                mc.KEY_CAPACITY, CAPACITY_LUMINANCE)

        # Set supported features based on capacity flags
        self._supported_features = (
            (SUPPORT_COLOR if self._capacity & CAPACITY_RGB else 0) |
            (SUPPORT_COLOR_TEMP if self._capacity & CAPACITY_TEMPERATURE else 0) |
            (SUPPORT_BRIGHTNESS if self._capacity & CAPACITY_LUMINANCE else 0)
        )

    @property
    def supported_features(self):
        """Return the supported features for this light."""
        return self._supported_features

    @property
    def brightness(self):
        """Return the brightness of this light between 0..255."""
        return self._brightness

    @property
    def hs_color(self):
        """Return the hue and saturation color value."""
        return self._hs_color

    @property
    def color_temp(self):
        """Return the color temperature in mireds."""
        return self._color_temp

    @property
    def white_value(self):
        """Return the white value of this light between 0..255."""
        return None

    @property
    def effect_list(self):
        """Return the list of supported effects."""
        return None

    @property
    def effect(self):
        """Return the current effect."""
        return None

    async def async_turn_on(self, **kwargs) -> None:
        """Turn the light on with optional parameters."""
        capacity = 0

        # Handle color setting - only one of HS color or color temp at a time
        if ATTR_HS_COLOR in kwargs:
            h, s = kwargs[ATTR_HS_COLOR]
            self._light[mc.KEY_RGB] = _rgb_to_int(color_hs_to_RGB(h, s))
            self._light.pop(mc.KEY_TEMPERATURE, None)
            capacity |= CAPACITY_RGB
        elif ATTR_COLOR_TEMP in kwargs:
            # Map mireds to meross temperature range (1-100)
            mired = kwargs[ATTR_COLOR_TEMP]
            norm_value = (mired - self.min_mireds) / (self.max_mireds - self.min_mireds)
            temperature = 100 - (norm_value * 99)
            self._light[mc.KEY_TEMPERATURE] = _sat_1_100(temperature)
            self._light.pop(mc.KEY_RGB, None)
            capacity |= CAPACITY_TEMPERATURE

        # Handle luminance/brightness
        if self._capacity & CAPACITY_LUMINANCE:
            capacity |= CAPACITY_LUMINANCE
            if ATTR_BRIGHTNESS in kwargs:
                self._light[mc.KEY_LUMINANCE] = _sat_1_100(kwargs[ATTR_BRIGHTNESS] * 100 // 255)
            else:
                # Keep existing brightness if not specified
                if mc.KEY_LUMINANCE not in self._light:
                    self._light[mc.KEY_LUMINANCE] = 100

        self._light[mc.KEY_CAPACITY] = capacity

        # Send command to device
        if self._usetogglex:
            # Only send turn_on command if currently off
            if not self.is_on:
                await super().async_turn_on(**kwargs)
        else:
            self._light[mc.KEY_ONOFF] = 1

        self._device.request(
            namespace=mc.NS_APPLIANCE_CONTROL_LIGHT,
            method=mc.METHOD_SET,
            payload={mc.KEY_LIGHT: self._light}
        )

    async def async_turn_off(self, **kwargs) -> None:
        """Turn the light off."""
        if self._usetogglex:
            await super().async_turn_off(**kwargs)
        else:
            self._light[mc.KEY_ONOFF] = 0
            self._device.request(
                namespace=mc.NS_APPLIANCE_CONTROL_LIGHT,
                method=mc.METHOD_SET,
                payload={mc.KEY_LIGHT: self._light}
            )

    def _set_light(self, light: dict) -> None:
        """Update internal state from device payload."""
        if self._light != light:
            self._light = light
            capacity = light.get(mc.KEY_CAPACITY, 0)

            # Update brightness
            if capacity & CAPACITY_LUMINANCE:
                self._brightness = light.get(mc.KEY_LUMINANCE, 0) * 255 // 100
            else:
                self._brightness = None

            # Update color temperature
            if capacity & CAPACITY_TEMPERATURE:
                self._color_temp = ((100 - light.get(mc.KEY_TEMPERATURE, 0)) / 99) * \
                    (self.max_mireds - self.min_mireds) + self.min_mireds
            else:
                self._color_temp = None

            # Update HS color
            if capacity & CAPACITY_RGB:
                r, g, b = _int_to_rgb(light.get(mc.KEY_RGB, 0))
                self._hs_color = color_RGB_to_hs(r, g, b)
            else:
                self._hs_color = None

            # Update state
            onoff = light.get(mc.KEY_ONOFF)
            if onoff is not None:
                self._state = STATE_ON if onoff else STATE_OFF

            # Write state to HA if enabled and state changed
            if self.hass and self.enabled and ((onoff is not None) or (self._state is STATE_ON)):
                self.async_write_ha_state()

