def phase_java_wrapper_repl(ctx, p):
    # Prepare arguments for REPL wrapper
    args = struct(
        args = " ".join(ctx.attr.scalacopts),
        wrapper_preamble = """
# save stty like in bin/scala
saved_stty=$(stty -g 2>/dev/null)
if [[ ! $? ]]; then
  saved_stty=""
fi

function finish() {
  if [[ "$saved_stty" != "" ]]; then
    stty $saved_stty
    saved_stty=""
  fi
}

trap finish EXIT
""",
    )

    return _phase_java_wrapper_default(ctx, p, args)


def phase_java_wrapper_common(ctx, p):
    # Use default Java wrapper without additional preamble
    return _phase_java_wrapper_default(ctx, p)


def _phase_java_wrapper_default(ctx, p, _args = struct()):
    # Extract args and preamble from _args if available
    args_val = _args.args if hasattr(_args, "args") else ""
    preamble_val = _args.wrapper_preamble if hasattr(_args, "wrapper_preamble") else ""

    return _phase_java_wrapper(ctx, args_val, preamble_val)


def _phase_java_wrapper(ctx, args, wrapper_preamble):
    """This creates a wrapper that sets up the correct path
       to stand in for the java command."""

    exec_str = ""
    if wrapper_preamble == "":
        exec_str = "exec "

    # Declare wrapper script file
    wrapper = ctx.actions.declare_file(ctx.label.name + "_wrapper.sh")

    # Write the wrapper script content
    ctx.actions.write(
        output = wrapper,
        content = """#!/usr/bin/env bash
{preamble}
DEFAULT_JAVABIN={javabin}
JAVA_EXEC_TO_USE=${{REAL_EXTERNAL_JAVA_BIN:-$DEFAULT_JAVABIN}}
{exec_str}$JAVA_EXEC_TO_USE "$@" {args}
""".format(
            preamble = wrapper_preamble,
            exec_str = exec_str,
            javabin = _java_bin(ctx),
            args = args,
        ),
        is_executable = True,
    )

    return wrapper

