from drheader import report, utils
from drheader.validators import base

# Define delimiter type constant
_DELIMITER_TYPE = 'item_delimiter'


class CookieValidator(base.ValidatorBase):
    """Validator class for validating cookies.

    Attributes:
        cookies (CaseInsensitiveDict): The cookies to analyse.
    """

    def __init__(self, cookies):
        """Initialises a CookieValidator instance with cookies."""
        self.cookies = cookies

    def validate_exists(self, config, header, directive=None, cookie=None):
        """See base class."""
        if cookie not in self.cookies:
            severity = config.get('severity', 'high')
            error_type = report.ErrorType.REQUIRED
            return report.ReportItem(severity, error_type, header, cookie=cookie)

    def validate_not_exists(self, config, header, directive=None, cookie=None):
        """See base class."""
        if cookie in self.cookies:
            severity = config.get('severity', 'high')
            error_type = report.ErrorType.DISALLOWED
            return report.ReportItem(severity, error_type, header, cookie=cookie)

    def validate_value(self, config, header, directive=None):
        """Method not supported.

        Raises:
            UnsupportedValidationError: If the method is called.
        """
        raise base.UnsupportedValidationError("'Value' validations are not supported for cookies")

    def validate_value_any_of(self, config, header, directive=None):
        """Method not supported.

        Raises:
            UnsupportedValidationError: If the method is called.
        """
        raise base.UnsupportedValidationError("'Value-Any-Of' validations are not supported for cookies")

    def validate_value_one_of(self, config, header, directive=None):
        """Method not supported.

        Raises:
            UnsupportedValidationError: If the method is called.
        """
        raise base.UnsupportedValidationError("'Value-One-Of' validations are not supported for cookies")

    def validate_must_avoid(self, config, header, directive=None, cookie=None):
        """See base class."""
        delimiter = base.get_delimiter(config, _DELIMITER_TYPE)
        disallowed = base.get_expected_values(config, 'must-avoid', delimiter)
        cookie_value = self.cookies[cookie]
        cookie_items = utils.parse_policy(cookie_value, **config['delimiters'], keys_only=True)
        cookie_items = {str(item).lower() for item in cookie_items}
        anomalies = []
        for avoid in disallowed:
            if avoid.lower() in cookie_items:
                anomalies.append(avoid)
        if anomalies:
            severity = config.get('severity', 'high')
            error_type = report.ErrorType.AVOID
            return report.ReportItem(
                severity, error_type, header, cookie=cookie, value=cookie_value,
                avoid=disallowed, anomalies=anomalies
            )

    def validate_must_contain(self, config, header, directive=None, cookie=None):
        """See base class."""
        delimiter = base.get_delimiter(config, _DELIMITER_TYPE)
        expected = base.get_expected_values(config, 'must-contain', delimiter)
        cookie_value = self.cookies[cookie]
        cookie_items = utils.parse_policy(cookie_value, **config['delimiters'], keys_only=True)
        cookie_items = {str(item).lower() for item in cookie_items}
        anomalies = []
        for contain in expected:
            if contain.lower() not in cookie_items:
                anomalies.append(contain)
        if anomalies:
            severity = config.get('severity', 'high')
            error_type = report.ErrorType.CONTAIN
            return report.ReportItem(
                severity, error_type, header, cookie=cookie, value=cookie_value,
                expected=expected, anomalies=anomalies, delimiter=delimiter
            )

    def validate_must_contain_one(self, config, header, directive=None, cookie=None):
        """See base class."""
        delimiter = base.get_delimiter(config, _DELIMITER_TYPE)
        expected = base.get_expected_values(config, 'must-contain-one', delimiter)
        cookie_value = self.cookies[cookie]
        cookie_items = utils.parse_policy(cookie_value, **config['delimiters'], keys_only=True)
        cookie_items = {str(item).lower() for item in cookie_items}
        if not any(contain.lower() in cookie_items for contain in expected):
            severity = config.get('severity', 'high')
            error_type = report.ErrorType.CONTAIN_ONE
            return report.ReportItem(
                severity, error_type, header, cookie=cookie, value=cookie_value, expected=expected
            )

# Profile activation module for relaxed-poetry
import importlib.util
from functools import reduce
from io import UnsupportedOperation
from pathlib import Path
from typing import List, Dict, Any
from dataclasses import dataclass

from poetry.core.pyproject.tables import PROPERTIES_TABLE, DEPENDENCIES_TABLE
from poetry.core.utils import toml

# Profile table path components
PROFILE_TABLE = "tool.relaxed-poetry.profile".split(".")

@dataclass
class ProfilesActivationRequest:
    """Represents a request to activate specific profiles."""
    requested_profiles: Dict[str, bool]
    command_name: str

    @classmethod
    def from_commandline(cls, command: str, profiles: List[str]) -> "ProfilesActivationRequest":
        """Create a request from command-line arguments."""
        requested_profiles = {}
        for profile in profiles:
            if profile.startswith("!"):
                requested_profiles[profile[1:]] = False
            else:
                requested_profiles[profile] = True
        return cls(requested_profiles, command)


class _Properties:
    """Wrapper for properties dictionary with convenient access methods."""
    def __init__(self, props: Dict[str, Any]):
        self._props = props

    def __getitem__(self, item: str):
        return self._props[item]

    def __setitem__(self, key: str, value):
        self._props[key] = value

    def update(self, props: Dict[str, Any]):
        self._props.update(props)


class _Dependencies:
    """Wrapper for managing dependencies."""
    def __init__(self, new_deps: Dict[str, Any]):
        self.new_deps: Dict[str, Any] = new_deps

    def add(self, name: str, specification: Any):
        self.new_deps[name] = specification


class _Execution:
    """Encapsulates execution context for profile activation."""
    def __init__(self, activation: ProfilesActivationRequest):
        self._activation = activation

    @property
    def command_name(self):
        return self._activation.command_name


def _should_activate(activate_spec: Any, exec: _Execution) -> bool:
    """Determine if a profile should be activated based on spec and execution context."""
    if isinstance(activate_spec, bool):
        return activate_spec
    elif isinstance(activate_spec, dict):
        if 'commands' in activate_spec:
            commands: List[str] = activate_spec['commands']
            if isinstance(commands, str):
                commands = [commands]
            default_accept = '*' in commands
            for command in commands:
                accept = default_accept
                if command == '*':
                    continue
                if command.startswith('!'):
                    accept = False
                    command = command[1:]
                if exec.command_name == command:
                    return accept
            return False
    raise UnsupportedOperation(f"unsupported profile activation spec: {activate_spec}")


def _activate_static_profile(
    profile_path: Path, 
    props: _Properties, 
    deps: _Dependencies, 
    exec: _Execution
):
    """Activate a static (TOML) profile."""
    profile_data, _ = toml.load(profile_path)
    profile_def = _lookup(profile_data, PROFILE_TABLE) or {}

    # Check activation conditions
    activate_spec = profile_def.get('activate', False)
    if not _should_activate(activate_spec, exec):
        return

    print(f"Activating Static Profile: {profile_path.stem}")

    # Apply property overrides
    props_overrides = _lookup(profile_data, PROPERTIES_TABLE) or {}
    props.update(props_overrides)

    # Add new dependencies
    new_deps = _lookup(profile_data, DEPENDENCIES_TABLE) or {}
    for name, spec in new_deps.items():
        deps.add(name, spec)


def _activate_dynamic_profile(
    profile_path: Path, 
    props: _Properties, 
    dependencies: _Dependencies, 
    exec: _Execution
):
    """Activate a dynamic (Python) profile."""
    print(f"Activating Dynamic Profile: {profile_path.stem}")
    try:
        spec = importlib.util.spec_from_file_location("__PROFILE__", profile_path)
        module = importlib.util.module_from_spec(spec)
        module.props = props
        module.execution = exec
        module.deps = dependencies
        spec.loader.exec_module(module)
    except Exception as e:
        raise RuntimeError(f"Error while evaluating profile: {profile_path.stem}") from e


def apply_profiles(
    properties: Dict[str, Any],
    new_deps: Dict[str, Any],
    profiles_dirs: List[Path],
    activation_data: ProfilesActivationRequest
):
    """Apply all requested profiles to the given properties and dependencies."""
    dependencies = _Dependencies(new_deps)
    properties = _Properties(properties)
    execution = _Execution(activation_data)

    # Activate automatic profiles
    for profiles_dir in profiles_dirs:
        if profiles_dir.exists():
            for profile in profiles_dir.iterdir():
                if activation_data.requested_profiles.get(profile.stem, True):
                    if profile.name.endswith(".py"):
                        _activate_dynamic_profile(profile, properties, dependencies, execution)
                    elif profile.name.endswith(".toml"):
                        _activate_static_profile(profile, properties, dependencies, execution)


def _lookup(d: Dict, path: List[str]) -> Any:
    """Safely look up nested dictionary values using a path list."""
    try:
        return reduce(lambda m, k: m[k], path, d)
    except KeyError:
        return None

import discord
from discord.ext import commands
from k2 import helpers

class Information:
    """Additional informational commands."""

    @commands.command(aliases=["rlist"])
    @commands.guild_only()
    @commands.cooldown(6, 12, commands.BucketType.channel)
    async def roles(self, ctx):
        """Display a list of the guild's roles."""
        embed = discord.Embed(title=f"Roles: {len(ctx.guild.roles)}")
        embed.description = ", ".join([f"{r.name}" for r in ctx.guild.roles])
        await ctx.send(embed=embed)

    @commands.command()
    @commands.guild_only()
    @commands.cooldown(6, 12, commands.BucketType.channel)
    async def whohas(self, ctx, *, role: str):
        """Display who has a given role.
        * role - The role to check for.
        """
        role = await helpers.role_by_substring(ctx, role)
        members_with_role = []

        for member in ctx.guild.members:
            if role in member.roles:
                members_with_role.append(member.mention)

        if not members_with_role:
            await ctx.send("Nobody has that role. :<")
        else:
            embed = discord.Embed(title=f"Members with {role.name}: {len(members_with_role)}")
            embed.description = ", ".join(members_with_role[:30])

            if len(members_with_role) > 30:
                embed.set_footer(text=f"...and {len(members_with_role)-30} others.")

            await ctx.send(embed=embed)

    @commands.command(brief="Display role info.", aliases=["rinfo"])
    @commands.guild_only()
    @commands.cooldown(6, 12, commands.BucketType.channel)
    async def roleinfo(self, ctx, *, role: str):
        """Display information about a role.
        * role - The role to display information about."""
        role = await helpers.role_by_substring(ctx, role)
        embed = discord.Embed(title=role.name)
        embed.colour = role.color
        embed.description = f"{role.id} | Members: {len(role.members)}"
        embed.add_field(name="Color", value=f"{role.color}", inline=False)

        if role.permissions.administrator:
            embed.add_field(name="Administrator", value=True)
        else:
            paginator = commands.Paginator(prefix="", suffix="")

            for permission, value in role.permissions:
                if value:
                    paginator.add_line(str(permission).capitalize().replace("_", " "))

            for page in paginator.pages:
                embed.add_field(name="Permissions", value=page)

        await ctx.send(embed=embed)

    @commands.command(aliases=["elist"])
    @commands.guild_only()
    @commands.cooldown(6, 12, commands.BucketType.channel)
    async def emojis(self, ctx):
        """Display a list of the guild's custom emojis."""
        embed = discord.Embed(title=f"Custom emojis for {ctx.guild.name}")
        emoji_list = []

        for emoji in ctx.guild.emojis:
            emoji_list.append(str(emoji))

        embed.description = " ".join(emoji_list)
        await ctx.send(embed=embed)

    @commands.command(brief="Display custom emoji info.",
                      aliases=["emojiinfo", "einfo", "ceinfo"])
    @commands.guild_only()
    @commands.cooldown(6, 12, commands.BucketType.channel)
    async def customemojiinfo(self, ctx, *, emoji: discord.Emoji):
        """Display information for a custom emoji.
        * emoji - The emoji to get information about."""
        embed = discord.Embed(title=emoji.name)
        embed.description = f"{emoji.id} | [Full image]({emoji.url})"
        embed.add_field(name="Guild", value=f"{emoji.guild.name} ({emoji.guild.id})")
        embed.add_field(name="Managed", value=emoji.managed)
        embed.add_field(name="Created at", value=emoji.created_at.ctime())
        embed.set_thumbnail(url=emoji.url)
