    more contrasts, and study-level metadata.
    '''

    def __init__(self, contrasts=None, **kwargs):
        self.contrasts = contrasts or []

    def add_contrasts(self, contrasts):
        self.contrasts.extend(listify(contrasts))

    @classmethod
    def merge(cls, studies):
