                        WolframLanguageException(export_exception, exec_info=sys.exc_info()),
                        **export_opts
                    )

                # Try custom exception class
                return export(
                    exception_class(export_exception, exec_info=sys.exc_info()), 
                    **export_opts
                )

            except Exception as exception_export_err:
                # Fallback to built-in WolframLanguageException with encoder specification
                return export(
                    WolframLanguageException(exception_export_err, exec_info=sys.exc_info()),
                    target_format=export_opts.get("target_format", DEFAULT_FORMAT),
                    encoder="wolframclient.serializers.encoders.builtin.encoder",
                )

        except Exception as unknown_exception:
            # Last resort: construct a Failure expression with detailed info
            try:
                return export(
                    wl.Failure(
                        "PythonFailure",
                        {
                            "MessageTemplate": safe_force_text(unknown_exception),
                            "MessageParameters": {},
                            "FailureCode": safe_force_text(
                                unknown_exception.__class__.__name__
                            ),
                            "Traceback": force_text(traceback.format_exc()),
                        },
                    ),
                    target_format=export_opts.get("target_format", DEFAULT_FORMAT),
                    encoder="wolframclient.serializers.encoders.builtin.encoder",
                )
            except Exception:
                # Worst case scenario - return hardcoded default failure
                return DEFAULT_UNKNOWN_FAILURE[
                    export_opts.get("target_format", DEFAULT_FORMAT)
                ]


def to_wl(exception_class=None, **export_opts):
    """Decorator to wrap functions for safe Wolfram Language export."""
    def outer(function):
        @wraps(function)
        def inner(*args, **opts):
            return safe_wl_execute(
                function=function,
                args=args,
                opts=opts,
                export_opts=export_opts,
                exception_class=exception_class,
            )
        return inner
    return outer

