@attr.define
class TaskState:
    task: Task
    running_jobs: int = 0
    saved_state: Any = None

    def __eq__(self, other):
        return self.task.id == other.task.id


@attr.define
class ScheduleState:
    schedule: Schedule
    next_fire_time: Optional[datetime] = attr.field(init=False, eq=False)
    acquired_by: Optional[str] = attr.field(init=False, eq=False, default=None)
    acquired_until: Optional[datetime] = attr.field(init=False, eq=False, default=None)

    def __attrs_post_init__(self):
        self.next_fire_time = self.schedule.next_fire_time

    def __eq__(self, other):
        return self.schedule.id == other.schedule.id

    def __lt__(self, other):
        if self.next_fire_time is None:
            return False
        elif other.next_fire_time is None:
            return self.next_fire_time is not None
        else:
            return self.next_fire_time < other.next_fire_time

    def __hash__(self):
        return hash(self.schedule.id)


@attr.define(order=True)
class JobState:
    job: Job = attr.field(order=False)
    created_at: datetime = attr.field(init=False, factory=partial(datetime.now, timezone.utc))
    acquired_by: Optional[str] = attr.field(eq=False, order=False, default=None)
    acquired_until: Optional[datetime] = attr.field(eq=False, order=False, default=None)

    def __eq__(self, other):
        return self.job.id == other.job.id

    def __hash__(self):
        return hash(self.job.id)


@reentrant
@attr.define(eq=False)
class MemoryDataStore(DataStore):
    lock_expiration_delay: float = 30
    _events: EventBroker = attr.Factory(LocalEventBroker)
    _tasks: dict[str, TaskState] = attr.Factory(dict)
    _schedules: list[ScheduleState] = attr.Factory(list)
    _schedules_by_id: dict[str, ScheduleState] = attr.Factory(dict)
    _schedules_by_task_id: dict[str, set[ScheduleState]] = attr.Factory(partial(defaultdict, set))
    _jobs: list[JobState] = attr.Factory(list)
    _jobs_by_id: dict[UUID, JobState] = attr.Factory(dict)
    _jobs_by_task_id: dict[str, set[JobState]] = attr.Factory(partial(defaultdict, set))
    _job_results: dict[UUID, JobResult] = attr.Factory(dict)

    def _find_schedule_index(self, state: ScheduleState) -> Optional[int]:
        left_index = bisect_left(self._schedules, state)
        right_index = bisect_left(self._schedules, state)
        return self._schedules.index(state, left_index, right_index + 1)

    def _find_job_index(self, state: JobState) -> Optional[int]:
        left_index = bisect_left(self._jobs, state)
        right_index = bisect_left(self._jobs, state)
        return self._jobs.index(state, left_index, right_index + 1)

    def __enter__(self):
        self._events.__enter__()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self._events.__exit__(exc_type, exc_val, exc_tb)

    @property
    def events(self) -> EventSource:
        return self._events

    def get_schedules(self, ids: Optional[set[str]] = None) -> list[Schedule]:
        return [state.schedule for state in self._schedules
                if ids is None or state.schedule.id in ids]

    def add_task(self, task: Task) -> None:
        task_exists = task.id in self._tasks
        self._tasks[task.id] = TaskState(task)
        if task_exists:
            self._events.publish(TaskUpdated(task_id=task.id))
        else:
            self._events.publish(TaskAdded(task_id=task.id))

    def remove_task(self, task_id: str) -> None:
        try:
            del self._tasks[task_id]
        except KeyError:
            raise TaskLookupError(task_id) from None
        self._events.publish(TaskRemoved(task_id=task_id))

    def get_task(self, task_id: str) -> Task:
        try:
            return self._tasks[task_id].task
        except KeyError:
            raise TaskLookupError(task_id) from None

    def get_tasks(self) -> list[Task]:
        return sorted((state.task for state in self._tasks.values()), key=lambda task: task.id)

    def add_schedule(self, schedule: Schedule, conflict_policy: ConflictPolicy) -> None:
        old_state = self._schedules_by_id.get(schedule.id)
        if old_state is not None:
            if conflict_policy is ConflictPolicy.do_nothing:
                return
            elif conflict_policy is ConflictPolicy.exception:
                raise ConflictingIdError(schedule.id)
            index = self._find_schedule_index(old_state)
            del self._schedules[index]
            self._schedules_by_task_id[old_state.schedule.task_id].remove(old_state)

        state = ScheduleState(schedule)
        self._schedules_by_id[schedule.id] = state
        self._schedules_by_task_id[schedule.task_id].add(state)
        insort_right(self._schedules, state)

        if old_state is not None:
            event = ScheduleUpdated(schedule_id=schedule.id,
                                    next_fire_time=schedule.next_fire_time)
        else:
            event = ScheduleAdded(schedule_id=schedule.id,
                                  next_fire_time=schedule.next_fire_time)
        self._events.publish(event)

    def remove_schedules(self, ids: Iterable[str]) -> None:
        for schedule_id in ids:
            state = self._schedules_by_id.pop(schedule_id, None)
            if state:
                self._schedules.remove(state)
                event = ScheduleRemoved(schedule_id=state.schedule.id)
                self._events.publish(event)

    def acquire_schedules(self, scheduler_id: str, limit: int) -> list[Schedule]:
        now = datetime.now(timezone.utc)
        schedules: list[Schedule] = []
        for state in self._schedules:
            if state.next_fire_time is None or state.next_fire_time > now:
                # The schedule is either paused or not yet due
                break
            elif state.acquired_by is not None:
                if state.acquired_by != scheduler_id and now <= state.acquired_until:
                    # The schedule has been acquired by another scheduler and the timeout has not
                    # expired yet
                    continue
            schedules.append(state.schedule)
            state.acquired_by = scheduler_id
            state.acquired_until = now + timedelta(seconds=self.lock_expiration_delay)
            if len(schedules) == limit:
                break
        return schedules

    def release_schedules(self, scheduler_id: str, schedules: list[Schedule]) -> None:
        # Send update events for schedules that have a next time
        finished_schedule_ids: list[str] = []
        for s in schedules:
            if s.next_fire_time is not None:
                # Remove the schedule
                schedule_state = self._schedules_by_id.get(s.id)
                index = self._find_schedule_index(schedule_state)
                del self._schedules[index]
                # Readd the schedule to its new position
                schedule_state.next_fire_time = s.next_fire_time
                schedule_state.acquired_by = None
                schedule_state.acquired_until = None
                insort_right(self._schedules, schedule_state)
                event = ScheduleUpdated(schedule_id=s.id, next_fire_time=s.next_fire_time)
                self._events.publish(event)
            else:
                finished_schedule_ids.append(s.id)
        # Remove schedules that didn't get a new next fire time
        self.remove_schedules(finished_schedule_ids)

    def get_next_schedule_run_time(self) -> Optional[datetime]:
        return self._schedules[0].next_fire_time if self._schedules else None

    def add_job(self, job: Job) -> None:
        state = JobState(job)
        self._jobs.append(state)
        self._jobs_by_id[job.id] = state
        self._jobs_by_task_id[job.task_id].add(state)
        event = JobAdded(job_id=job.id, task_id=job.task_id, schedule_id=job.schedule_id,
                         tags=job.tags)
        self._events.publish(event)

    def get_jobs(self, ids: Optional[Iterable[UUID]] = None) -> list[Job]:
        if ids is not None:
            ids = frozenset(ids)
        return [state.job for state in self._jobs if ids is None or state.job.id in ids]

    def acquire_jobs(self, worker_id: str, limit: Optional[int] = None) -> list[Job]:
        now = datetime.now(timezone.utc)
        jobs: list[Job] = []
        for index, job_state in enumerate(self._jobs):
            task_state = self._tasks[job_state.job.task_id]
            # Skip already acquired jobs (unless the acquisition lock has expired)
            if job_state.acquired_by is not None:
                if job_state.acquired_until >= now:
                    continue
                else:
                    task_state.running_jobs -= 1
            # Check if the task allows one more job to be started
            if (task_state.task.max_running_jobs is not None
                    and task_state.running_jobs >= task_state.task.max_running_jobs):
                continue
            # Mark the job as acquired by this worker
            jobs.append(job_state.job)
            job_state.acquired_by = worker_id
            job_state.acquired_until = now + timedelta(seconds=self.lock_expiration_delay)
            # Increment the number of running jobs for this task
            task_state.running_jobs += 1
            # Exit the loop if enough jobs have been acquired
            if len(jobs) == limit:
                break
        # Publish the appropriate events
        for job in jobs:
            self._events.publish(JobAcquired(job_id=job.id, worker_id=worker_id))
        return jobs

    def release_job(self, worker_id: str, task_id: str, result: JobResult) -> None:
        # Delete the job
        job_state = self._jobs_by_id.pop(result.job_id)
        self._jobs_by_task_id[task_id].remove(job_state)
        index = self._find_job_index(job_state)
        del self._jobs[index]
        # Decrement the number of running jobs for this task
        task_state = self._tasks.get(task_id)
        if task_state is not None:
            task_state.running_jobs -= 1
        # Record the result
        self._job_results[result.job_id] = result
        # Publish the event
        self._events.publish(
            JobReleased(job_id=result.job_id, worker_id=worker_id, outcome=result.outcome)
        )

    def get_job_result(self, job_id: UUID) -> Optional[JobResult]:
        return self._job_results.pop(job_id, None)

# Solution class for unique paths problem
class Solution:
    def uniquePaths(self, m: int, n: int) -> int:
        # Memoization dictionary to store computed results
        memo = {}

        # Helper function with memoization
        def _uniquePaths(i: int, j: int) -> int:
            # Check if result is already computed
            if (i, j) in memo:
                return memo[(i, j)]

            # Base case: reached boundary
            if j >= m - 1 or i >= n - 1:
                return 1

            # Recursive calculation with memoization
            c = _uniquePaths(i + 1, j) + _uniquePaths(i, j + 1)
            memo[(i, j)] = c
            return c

        # Start from top-left corner
        return _uniquePaths(0, 0)

# Uptime Robot configuration flow for Home Assistant
from __future__ import annotations

from pyuptimerobot import UptimeRobot
import voluptuous as vol

from homeassistant import config_entries
from homeassistant.const import CONF_API_KEY
from homeassistant.core import HomeAssistant
from homeassistant.data_entry_flow import FlowResult
from homeassistant.exceptions import HomeAssistantError
from homeassistant.helpers.typing import ConfigType

from .const import API_ATTR_OK, API_ATTR_STAT, DOMAIN, LOGGER

# Validation schema for user input
STEP_USER_DATA_SCHEMA = vol.Schema({vol.Required(CONF_API_KEY): str})


async def validate_input(hass: HomeAssistant, data: ConfigType) -> None:
    """Validate the user input allows us to connect."""
    uptime_robot_api = UptimeRobot()

    # Execute API call in executor to avoid blocking
    monitors = await hass.async_add_executor_job(
        uptime_robot_api.getMonitors, data[CONF_API_KEY]
    )

    # Check if response is valid
    if not monitors or monitors.get(API_ATTR_STAT) != API_ATTR_OK:
        raise CannotConnect("Error communicating with Uptime Robot API")


class ConfigFlow(config_entries.ConfigFlow, domain=DOMAIN):
    """Handle a config flow for Uptime Robot."""

    VERSION = 1

    async def async_step_user(self, user_input: ConfigType | None = None) -> FlowResult:
        """Handle the initial step."""
        errors: dict[str, str] = {}

        # Show form if no input provided
        if user_input is None:
            return self.async_show_form(
                step_id="user", data_schema=STEP_USER_DATA_SCHEMA, errors=errors
            )

        try:
            # Validate input and attempt connection
            await validate_input(self.hass, user_input)
        except CannotConnect:
            errors["base"] = "cannot_connect"
        except Exception:  # pylint: disable=broad-except
            LOGGER.exception("Unexpected exception")
            errors["base"] = "unknown"
        else:
            # Success - create entry
            return self.async_create_entry(title="", data=user_input)

        # Re-show form with errors on failure
        return self.async_show_form(
            step_id="user", data_schema=STEP_USER_DATA_SCHEMA, errors=errors
        )

    async def async_step_import(self, import_config: ConfigType) -> FlowResult:
        """Import a config entry from configuration.yaml."""
        # Check for duplicate configurations
        for entry in self._async_current_entries():
            if entry.data[CONF_API_KEY] == import_config[CONF_API_KEY]:
                LOGGER.warning(
                    "Already configured. This YAML configuration has already been imported. Please remove it"
                )
                return self.async_abort(reason="already_configured")

        # Create new entry from imported config
        return self.async_create_entry(
            title="", data={CONF_API_KEY: import_config[CONF_API_KEY]}
        )


class CannotConnect(HomeAssistantError):
    """Error to indicate we cannot connect."""

from typing import Tuple
from pyisc.dhcpd.nodes import (CustomOption, DhcpClass, Event, EventSet, Group,
                               Hardware, Host, Include, Key, Failover, Option,
                               OptionExpression, Pool4, Prefix6, Range4,
                               Range6, ServerDuidEN, ServerDuidLL, SubClass,
                               Subnet4, Subnet6, SharedNetwork, Zone)


class TokenProcessor:
    """A processor class for tokens.

    This class takes a token and uses the lowercase token name to match a
    method. If a method is found it proceeds to run that method an return
    the value or object and the method to add it to the current working node.
    """

    def switch(self, token) -> Tuple:
        """
        Returns a tuple of value/object and metod.

        Args:
            token (pyisc.dhcpd.parsing.Token): A supplied token instance.

        Returns:
            tuple: Tuple containing value or object in first position
                and method in second position.

        Examples:
            >>> token = Token(type='OPTION',
            ...               value='option domain-name "example.org";',
            ...               line=8, column=0)
            >>> processor = TokenProcessor()
            >>> declaration, method = processor.switch(token)
            >>> declaration
            Option(name="domain_name", value=""example.org"")
            >>> method
            'add_option'
        """
        self.token = token
        return getattr(self, str(token.type).lower(), self.not_found)()

    def not_found(self):
        raise AttributeError(
            f'Token {self.token.type} does not have a associated method.')

    def authoritative(self) -> Tuple:
        """Returns tuple for the authoritative command."""
        if 'not' in self.token.value:
            return (False, 'authoritative')
        return (True, 'authoritative')

    def hardware(self) -> Tuple:
        """Returns tuple for the hardware command."""
        _, hardware_type, hardware_address = self.token.value[:-1].split()
        node_hardware = Hardware(type=hardware_type, address=hardware_address)
        return (node_hardware, 'hardware')

    def primary(self) -> Tuple:
        """Returns tuple for the zone primary command."""
        _, primary = self.token.value[:-1].split()
        return (primary, 'primary')

    def failover_role(self) -> Tuple:
        """Returns tuple for the failover role."""
        role = self.token.value[:-1]
        return (role, 'role')

    def include(self) -> Tuple:
        """Returns tuple for the include declaration."""
        _, file_name = self.token.value[:-1].split()
        declaration = Include(filename=file_name)
        return (declaration, 'add_include')

    def general_parameter(self) -> Tuple:
        """Returns tuple for the all other parameters."""
        key, value = self.token.value[:-1].rsplit(' ', 1)
        if value.isdigit():
            value = int(value)
        attr_key = key.replace('-', '_').replace(' ', '_')
        return (value, attr_key)

    def allow_member(self) -> Tuple:
        """Returns tuple for the allow member of statement."""
        _, value = self.token.value[:-1].rsplit(' ', 1)
        return (value, 'add_allowed_member')

    def deny_member(self) -> Tuple:
        """Returns tuple for the deny member of statement."""
        _, value = self.token.value[:-1].rsplit(' ', 1)
        return (value, 'add_denied_member')

    def allow_general(self) -> Tuple:
        """Returns tuple for the allow statement."""
        _, key = self.token.value[:-1].split()
        key = key.replace('-', '_')
        return ('allow', key)

    def deny_general(self) -> Tuple:
        """Returns tuple for the deny statement."""
        _, key = self.token.value[:-1].split()
        key = key.replace('-', '_')
        return ('deny', key)

    def ignore_general(self) -> Tuple:
        """Returns tuple for the ignore statement."""
        _, key = self.token.value[:-1].split()
        key = key.replace('-', '_')
        return ('ignore', key)

    def class_statement(self) -> Tuple:
        """Returns tuple for the match statement of the class declaration."""
        _, statement = self.token.value[:-1].split(' ', 1)
        return (statement, 'match')

    def spawn_class(self) -> Tuple:
        """Returns tuple for the spawn statement of the class declaration."""
        _, statement = self.token.value[:-1].split(' ', 1)
        return (statement, 'spawn')

    def range4(self) -> Tuple:
        """Returns tuple for the range statement for ipv4 configuration."""
        cleaned_token = self.token.value[:-1].strip()
        range_list = [data.strip() for data in cleaned_token.split()]
        if 'dynamic-bootp' in cleaned_token:
            dynamic_bootp = True
            range_list.remove('dynamic-bootp')
        else:
            dynamic_bootp = False
        while len(range_list) < 3:
            range_list += [None]
        _, range_start, range_end = range_list
        subnet_range = Range4(
            start=range_start, end=range_end, dynamic_bootp=dynamic_bootp)
        return (subnet_range, 'add_range')

    def range6(self) -> Tuple:
        """Returns tuple for the range statement for ipv6 configuration."""
        cleaned_token = self.token.value[:-1].strip()
        range_list = [data.strip() for data in cleaned_token.split()]
        if 'temporary' in cleaned_token:
            temporary = True
            range_list.remove('temporary')
        else:
            temporary = False
        while len(range_list) < 3:
            range_list += [None]
        _, range_start, range_end = range_list
        subnet_range = Range6(
            start=range_start, end=range_end, temporary=temporary)
        return (subnet_range, 'add_range')

    def option(self) -> Tuple:
        """Returns tuple for the option command."""
        if self.token.value.count(' ') == 1:
            _, option = self.token.value[:-1].split()
            value = True
        else:
            _, option, value = self.token.value[:-1].split(' ', 2)
        if option.isdigit():
            node_option = Option(number=option, value=value)
        else:
            option = option.replace('-', '_')
            node_option = Option(name=option, value=value)
        return (node_option, 'add_option')

    def custom_option(self) -> Tuple:
        """Returns tuple for the custom option command."""
        _, option_name, _, code, _, value = self.token.value[:-1].split(' ', 5)
        return (CustomOption(name=option_name, code=code, definition=value),
                'add_custom_option')

    def prefix6(self) -> Tuple:
        _, start, end, bits = self.token.value[:-1].split()
        return (Prefix6(start=start, end=end, bits=bits), 'prefix6')

    def option_expression(self) -> Tuple:
        _, option_name, _, value = self.token.value[:-1].split(' ', 3)
        return (OptionExpression(name=option_name, value=value),
                'add_option_expression')

    def server_duid_ll(self) -> Tuple:
        cleaned_token = self.token.value[:-1].strip()
        if 'LLT' in cleaned_token:
            *_, hardware_type, timestamp, hardware_address = cleaned_token.split()
        else:
            *_, hardware_type, hardware_address, timestamp = cleaned_token.split() + [None]
        return (ServerDuidLL(hardware_type=hardware_type,
                             hardware_address=hardware_address,
                             timestamp=timestamp), 'server_duid')

    def server_duid_en(self) -> Tuple:
        *_, enterprise_number, enterprise_id = self.token.value[:-1].split(' ', 3)
        return (ServerDuidEN(enterprise_number=enterprise_number,
                             enterprise_id=enterprise_id), 'server_duid')

    def key(self) -> Tuple:
        """Returns tuple for the key declaration."""
        _, name = self.token.value[:-1].split()
        if self.token.value[-1] == '{':
            method = 'add_key'
        else:
            method = 'key'
        return (Key(name=name), method)

    def failover(self) -> Tuple:
        """Returns tuple for the failover declaration and parameter."""
        *_, peer = self.token.value[:-1].split()
        return (Failover(name=peer), 'failover')

    def subnet4(self) -> Tuple:
        """Returns tuple for the ipv4 subnet declaration."""
        _, subnet, _, netmask = self.token.value[:-1].split()
        return (Subnet4(network=f'{subnet}/{netmask}'), 'add_subnet')

    def subnet6(self) -> Tuple:
        """Returns tuple for the ipv4 subnet declaration."""
        _, subnet_cidr = self.token.value[:-1].split()
        return (Subnet6(network=f'{subnet_cidr}'), 'add_subnet')

    def shared_network(self) -> Tuple:
        """Returns tuple for the shared network declaration."""
        _, name = self.token.value[:-1].split()
        return (SharedNetwork(name=name), 'add_shared_network')

    def pool(self) -> Tuple:
        """Returns tuple for the ipv4 pool declaration."""
        return (Pool4(), 'add_pool')

    def group(self) -> Tuple:
        """Returns tuple for the group declaration."""
        return (Group(), 'add_group')

    def host(self) -> Tuple:
        """Returns tuple for the host declaration."""
        _, name = self.token.value[:-1].split()
        return (Host(name=name), 'add_host')

    def dhcp_class(self) -> Tuple:
        """Returns tuple for the class declaration."""
        _, name = self.token.value[:-1].split()
        return (DhcpClass(name=name), 'add_class')

    def subclass(self) -> Tuple:
        """Returns tuple for the class declaration and parameter."""
        cleaned_token = self.token.value[:-1].strip()
        _, name, match_value = cleaned_token.split(' ', 2)
        return (SubClass(name=name, match_value=match_value), 'add_subclass')

    def zone(self) -> Tuple:
        """Returns tuple for the zone declaration."""
        _, name = self.token.value[:-1].split()
        return (Zone(name=name), 'add_zone')

    def event(self) -> Tuple:
        """Returns tuple for the event declaration."""
        _, event_type = self.token.value[:-1].split()
        return (Event(event_type=event_type), 'add_event')

    def event_set(self) -> Tuple:
        """Returns tuple for the event set expression."""
        key, value = [
            data.strip() for data in self.token.value[:-1].split('=')]
        _, attr_key = key.split()
        return (EventSet(key=attr_key, value=value), 'add_event_set')

    def event_log(self) -> Tuple:
        """Returns tuple for the event log directive."""
        value = self.token.value[:-1].replace('log', '')
        return (value, 'log')

    def event_execute(self) -> Tuple:
        """Returns tuple for the event execute directive."""
        value = self.token.value[:-1].replace('execute', '')
        return (value, 'execute')

