from collections.abc import Coroutine
from .log import logger


class _ContextManager(Coroutine):
    __slots__ = ('_coro', '_obj')

    def __init__(self, coro):
        self._coro = coro
        self._obj = None

    def send(self, value):
        return self._coro.send(value)

    def throw(self, typ, val=None, tb=None):
        if val is None:
            return self._coro.throw(typ)
        elif tb is None:
            return self._coro.throw(typ, val)
        else:
            return self._coro.throw(typ, val, tb)

    def close(self):
        return self._coro.close()

    @property
    def gi_frame(self):
        return self._coro.gi_frame

    @property
    def gi_running(self):
        return self._coro.gi_running

    @property
    def gi_code(self):
        return self._coro.gi_code

    def __next__(self):
        return self.send(None)

    def __iter__(self):
        return self._coro.__await__()

    def __await__(self):
        return self._coro.__await__()

    async def __aenter__(self):
        self._obj = await self._coro
        return self._obj

    async def __aexit__(self, exc_type, exc, tb):
        await self._obj.close()
        self._obj = None


class _ConnectionContextManager(_ContextManager):
    async def __aexit__(self, exc_type, exc, tb):
        if exc_type is not None:
            self._obj.close()
        else:
            await self._obj.ensure_closed()
        self._obj = None


class _PoolContextManager(_ContextManager):
    async def __aexit__(self, exc_type, exc, tb):
        self._obj.close()
        await self._obj.wait_closed()
        self._obj = None


class _SAConnectionContextManager(_ContextManager):
    async def __aiter__(self):
        result = await self._coro
        return result


class _TransactionContextManager(_ContextManager):
    async def __aexit__(self, exc_type, exc, tb):
        if exc_type:
            await self._obj.rollback()
        else:
            if self._obj.is_active:
                await self._obj.commit()
        self._obj = None


class _PoolAcquireContextManager(_ContextManager):
    __slots__ = ('_coro', '_conn', '_pool')

    def __init__(self, coro, pool):
        self._coro = coro
        self._conn = None
        self._pool = pool

    async def __aenter__(self):
        self._conn = await self._coro
        return self._conn

    async def __aexit__(self, exc_type, exc, tb):
        try:
            await self._pool.release(self._conn)
        finally:
            self._pool = None
            self._conn = None


class _PoolConnectionContextManager:
    """Context manager.
    This enables the following idiom for acquiring and releasing a
    connection around a block:
        with (yield from pool) as conn:
            cur = yield from conn.cursor()
    while failing loudly when accidentally using:
        with pool:
            <block>
    """
    __slots__ = ('_pool', '_conn')

    def __init__(self, pool, conn):
        self._pool = pool
        self._conn = conn

    def __enter__(self):
        assert self._conn
        return self._conn

    def __exit__(self, exc_type, exc_val, exc_tb):
        try:
            self._pool.release(self._conn)
        finally:
            self._pool = None
            self._conn = None

    async def __aenter__(self):
        assert not self._conn
        self._conn = await self._pool.acquire()
        return self._conn

    async def __aexit__(self, exc_type, exc_val, exc_tb):
        try:
            await self._pool.release(self._conn)
        finally:
            self._pool = None
            self._conn = None


class TaskTransactionContextManager:
    __task_storage = dict()
    __slots__ = (
        '_coro',
        '_conn',
        '_pool',
        '_counter',
        '_callback_list',
        '__connection_transaction_begin',
        '__connection_committed',
        '__connection_rollbacked'
    )

    def __init__(self, coro, pool):
        self._coro = coro
        self._conn = None
        self._pool = pool
        self._counter = 0
        self._callback_list = list()

        task = asyncio.Task.current_task()
        if task in self.__task_storage:
            raise Exception('task already in task_storage')
        self.__task_storage[task] = self

        self.__connection_transaction_begin = False
        self.__connection_committed = False
        self.__connection_rollbacked = False

    @classmethod
    def create(cls, coro, pool) -> 'TaskTransactionContextManager':
        task = asyncio.Task.current_task()
        if task in cls.__task_storage:
            return cls.__task_storage[task]
        return TaskTransactionContextManager(coro, pool)

    @classmethod
    def get_transaction_context_manager(cls, task=None) -> 'TaskTransactionContextManager':
        if not task:
            task = asyncio.Task.current_task()
        return cls.__task_storage.get(task)

    def add_callback_on_commit(self, callback_func, **kwargs):
        self._callback_list.append((callback_func, kwargs))

    async def connection_begin(self):
        if not self.__connection_transaction_begin:
            await self._conn.begin()
            self.__connection_transaction_begin = True

    async def connection_commit(self):
        if self._counter <= 1:
            await self._conn.commit()
            for callback_func, kwargs in self._callback_list:
                try:
                    if asyncio.iscoroutine(callback_func):
                        await callback_func(**kwargs)
                    else:
                        callback_func(**kwargs)
                except Exception as e:
                    logger.exception(e)
            self._callback_list.clear()
            self.__connection_committed = True

    async def connection_rollback(self):
        await self._conn.rollback()
        self._callback_list.clear()
        self.__connection_rollbacked = True

    async def __aenter__(self):
        self._counter += 1
        if not self._conn:
            self._conn = await self._coro
        return TransactionConnection(self._conn)

    async def __aexit__(self, exc_type, exc, tb):
        self._counter -= 1
        if self._counter <= 0:
            if self.__connection_transaction_begin and not self.__connection_committed and not self.__connection_rollbacked:
                if not exc_type:
                    logger.warning('sql operation was not committed. Try to commit by TaskTransactionContextManager')
                    await self.connection_commit()
            self.__task_storage.pop(asyncio.Task.current_task(), None)
            try:
                await self._pool.release(self._conn)
            finally:
                self._pool = None
                self._conn = None
                self.__connection_transaction_begin = False
                self.__connection_committed = False
                self.__connection_rollbacked = False


class TransactionConnection:
    def __init__(self, conn):
        self.__conn = conn

    def __str__(self):
        return 'TransactionConnection ' + str(self.__conn)

    async def begin(self):
        """Begin transaction."""
        if TaskTransactionContextManager.get_transaction_context_manager():
            await TaskTransactionContextManager.get_transaction_context_manager().connection_begin()
        else:
            await self.__conn.begin()

    async def commit(self):
        """Commit changes to stable storage."""
        if TaskTransactionContextManager.get_transaction_context_manager():
            await TaskTransactionContextManager.get_transaction_context_manager().connection_commit()
        else:
            await self.__conn.commit()

    async def rollback(self):
        """Roll back the current transaction."""
        if TaskTransactionContextManager.get_transaction_context_manager():
            await TaskTransactionContextManager.get_transaction_context_manager().connection_rollback()
        else:
            await self.__conn.rollback()

    def __getattr__(self, item):
        return getattr(self.__conn, item)

    @property
    def conn(self):
        return self.__conn

# Import necessary modules
import re
from typing import Any, Dict, List, NoReturn, Optional, Tuple, Type, TypeVar

import sqlalchemy as sa
from sqlalchemy.exc import IntegrityError
from sqlalchemy.ext.asyncio import AsyncSession
from sqlalchemy.orm import selectinload

from app.db.base import Base
from app.db.deps import get_db
from app.db.exceptions import DatabaseValidationError
from app.db.utils import operators_map
from app.utils.datetime import utcnow

logger = logging.getLogger(__name__)

TBase = TypeVar("TBase", bound="BaseModel")


class EmptyBaseModel(Base):
    """Clean Base without fields and methods"""
    __abstract__ = True


class BaseModel(Base):
    __abstract__ = True

    id = sa.Column(sa.Integer, primary_key=True)
    created_at = sa.Column(sa.DateTime(timezone=True), default=utcnow, nullable=False)
    updated_at = sa.Column(sa.DateTime(timezone=True), default=utcnow, onupdate=utcnow, nullable=False)

    def __str__(self):
        return f"<{type(self).__name__}({self.id=})>"

    @classmethod
    def _raise_validation_exception(cls, e: IntegrityError) -> NoReturn:
        info = e.orig.args[0] if e.orig.args else ""

        # Check for unique constraint violation
        if (match := re.findall(r"Key \((.*)\)=\(.*\) already exists|$", info)) and match[0]:
            raise DatabaseValidationError(f"Unique constraint violated for {cls.__name__}", match[0]) from e

        # Check for range overlap
        if (match := re.findall(r"Key \((.*)\)=\(.*\) conflicts with existing key|$", info)) and match[0]:
            field_name = match[0].split(",", 1)[0]
            raise DatabaseValidationError(f"Range overlapped for {cls.__name__}", field_name) from e

        # Check for foreign key violation
        if (match := re.findall(r"Key \((.*)\)=\(.*\) is not present in table|$", info)) and match[0]:
            raise DatabaseValidationError(f"Foreign key constraint violated for {cls.__name__}", match[0]) from e

        logger.error("Integrity error for %s: %s", cls.__name__, e)
        raise e

    @classmethod
    def _get_query(cls, prefetch: Optional[Tuple[str, ...]] = None, options: Optional[List[Any]] = None) -> Any:
        query = sa.select(cls)

        if prefetch:
            if not options:
                options = []

            options.extend(selectinload(getattr(cls, x)) for x in prefetch)
            query = query.options(*options).execution_options(populate_existing=True)

        return query

    @classmethod
    async def all(cls: Type[TBase], prefetch: Optional[Tuple[str, ...]] = None) -> List[TBase]:
        query = cls._get_query(prefetch)
        db = get_db()
        db_execute = await db.execute(query)
        return db_execute.scalars().all()

    @classmethod
    async def get_by_id(cls: Type[TBase], obj_id: int, prefetch: Optional[Tuple[str, ...]] = None) -> Optional[TBase]:
        query = cls._get_query(prefetch).where(cls.id == obj_id)
        db = get_db()
        db_execute = await db.execute(query)
        instance = db_execute.scalars().first()
        return instance

    @classmethod
    async def filter(
        cls: Type[TBase],
        filters: Dict[str, Any],
        sorting: Optional[Dict[str, str]] = None,
        prefetch: Optional[Tuple[str, ...]] = None,
    ) -> List[TBase]:
        query = cls._get_query(prefetch)
        db = get_db()

        if sorting is not None:
            query = query.order_by(*cls._build_sorting(sorting))

        db_execute = await db.execute(query.where(sa.and_(True, *cls._build_filters(filters))))
        return db_execute.scalars().all()

    @classmethod
    def _build_sorting(cls, sorting: Dict[str, str]) -> List[Any]:
        """Build list of ORDER_BY clauses"""
        result = []
        for field_name, direction in sorting.items():
            field = getattr(cls, field_name)
            result.append(getattr(field, direction)())
        return result

    @classmethod
    def _build_filters(cls, filters: Dict[str, Any]) -> List[Any]:
        """Build list of WHERE conditions"""
        result = []
        for expression, value in filters.items():
            parts = expression.split("__")
            op_name = parts[1] if len(parts) > 1 else "exact"

            if op_name not in operators_map:
                raise KeyError(f"Expression {expression} has incorrect operator {op_name}")

            operator = operators_map[op_name]
            column = getattr(cls, parts[0])
            result.append(operator(column, value))
        return result

    @classmethod
    async def bulk_create(cls: Type[TBase], objects: List[TBase]) -> List[TBase]:
        db: AsyncSession = get_db()
        try:
            db.add_all(objects)
            await db.flush()
        except IntegrityError as e:
            cls._raise_validation_exception(e)
        return objects

    @classmethod
    async def bulk_update(cls: Type[TBase], objects: List[TBase]) -> List[TBase]:
        db: AsyncSession = get_db()
        try:
            ids = [x.id for x in objects if x.id]
            await db.execute(sa.select(cls).where(cls.id.in_(ids)))

            for item in objects:
                try:
                    await db.merge(item)
                except IntegrityError as e:
                    cls._raise_validation_exception(e)

            await db.flush()
        except IntegrityError as e:
            cls._raise_validation_exception(e)
        return objects

    async def save(self, commit: bool = True) -> None:
        db: AsyncSession = get_db()
        db.add(self)
        try:
            if commit:
                await db.commit()
            else:
                await db.flush()
        except IntegrityError as e:
            self._raise_validation_exception(e)

    async def update_attrs(self, **kwargs: Any) -> None:
        for k, v in kwargs.items():
            setattr(self, k, v)

# BotAccess Cog for Red-DiscordBot
import typing
import asyncio
from datetime import datetime, timedelta
import discord
from redbot.core import commands, Config
from redbot.core.utils import AsyncIter
from redbot.core.utils.chat_formatting import humanize_list, pagify

# Default messages
NOT_SUPPORTING = "You do not have BotAccess privileges!"
THANKS = "Thank you for supporting my server! Here is my invite link: <{invite}>. You can add a BotAccess server with `[p]botaccess servers add <server ID>`."
EXPIRE = "Unfortunately, your BotAccess servers have expired as you are no longer a supporter."


class BotAccess(commands.Cog):
    """
    Allow Special Roles Access to Bot

    Allow users with the Server Booster, Patreon, etc. roles to invite the bot 
    to a (few) server(s) of their choice.
    """

    def __init__(self, bot):
        self.bot = bot
        self.config = Config.get_conf(self, identifier=14000605, force_registration=True)

        # Define default configuration values
        default_global = {
            "allowed": [],
            "main_servers": {},
            "messages": {
                "thanks": {
                    "toggle": True,
                    "content": ""
                },
                "expire": {
                    "toggle": True,
                    "content": ""
                }
            },
            "not_supporting": "",
            "limit": 1,
            "auto_leave": {
                "toggle": True,
                "delay": 24
            },
        }

        default_user = {
            "servers": [],
            "supporting_in": [],
            "end_timestamp": None
        }

        # Register configuration scopes
        self.config.register_global(**default_global)
        self.config.register_user(**default_user)

        # Start background task for expiration handling
        self.expire_handler_task = self.bot.loop.create_task(self._expire_handler())

    def cog_unload(self):
        """Cancel the background task when cog is unloaded."""
        self.expire_handler_task.cancel()

    @commands.Cog.listener("on_guild_join")
    async def _guild_join(self, guild: discord.Guild):
        """Handle new guild join events and enforce BotAccess restrictions."""
        # Skip if bot owns the guild
        if guild.owner and guild.owner == guild.me:
            return

        # Skip if bot owner owns the guild
        if guild.owner_id in self.bot.owner_ids:
            return

        # Skip if this is an allowed server
        if guild.id in await self.config.allowed():
            return

        # Skip if this is a main server
        if str(guild.id) in (await self.config.main_servers()).keys():
            return

        # Skip if this is a BotAccess server
        for data in (await self.config.all_users()).values():
            if guild.id in data["servers"]:
                return

        # Find who invited the bot
        inviter = None
        if guild.me.guild_permissions.view_audit_log:
            async for entry in guild.audit_logs(limit=3, action=discord.AuditLogAction.bot_add):
                if entry.target == guild.me:
                    inviter = entry.user
                    break

        # DM the inviter if found
        if inviter:
            try:
                await inviter.send(await self.config.not_supporting() or NOT_SUPPORTING)
            except discord.HTTPException:
                pass
        else:
            # Send message to first available text channel
            for channel in guild.text_channels:
                if channel.permissions_for(guild.me).send_messages:
                    await channel.send(await self.config.not_supporting() or NOT_SUPPORTING)
                    break

        # Leave the guild
        await guild.leave()

    @commands.Cog.listener("on_member_remove")
    async def _member_remove(self, member: discord.Member):
        """Handle member removal from guilds."""
        auto_leave = False

        async with self.config.user(member).all() as user_settings:
            # Remove guild from supporting list
            if member.guild.id in user_settings["supporting_in"]:
                user_settings["supporting_in"].remove(member.guild.id)

            # Check if should trigger auto-leave
            if not user_settings["supporting_in"] and not user_settings["end_timestamp"]:
                auto_leave = True

        if auto_leave:
            await self._initiate_autoleave(member.id)

    @commands.Cog.listener("on_member_update")
    async def _member_update(self, before: discord.Member, after: discord.Member):
        """Handle role changes to update BotAccess status."""
        main_servers = await self.config.main_servers()
        server_roles = main_servers.get(str(after.guild.id))

        # Skip if member is a bot, cog disabled, no role change, or not in main server
        if (
                after.bot or
                await self.bot.cog_disabled_in_guild(self, after.guild) or
                before.roles == after.roles or
                not server_roles
        ):
            return

        messages = await self.config.messages()
        to_send: str = ""
        auto_leave = False

        before_support = await self._role_overlap(server_roles, before)
        after_support = await self._role_overlap(server_roles, after)

        # New server supporter
        if not before_support and after_support:
            async with self.config.user(after).all() as user_settings:
                if not user_settings["supporting_in"]:
                    to_send = await self._send_thanks(messages["thanks"])

                if user_settings["end_timestamp"]:
                    user_settings["end_timestamp"] = None

                if after.guild.id not in user_settings["supporting_in"]:
                    user_settings["supporting_in"].append(after.guild.id)

        # Member stopped supporting server
        elif before_support and not after_support:
            async with self.config.user(after).all() as user_settings:
                if after.guild.id in user_settings["supporting_in"]:
                    user_settings["supporting_in"].remove(after.guild.id)

                if not user_settings["supporting_in"] and not user_settings["end_timestamp"]:
                    to_send = await self._send_expire(messages["expire"])
                    auto_leave = True

        # Try sending DM
        if to_send:
            try:
                await after.send(to_send)
            except discord.HTTPException:
                pass

        if auto_leave:
            await self._initiate_autoleave(after.id)

    @staticmethod
    async def _role_overlap(supporting_roles: list, member: discord.Member):
        """Check if member has any of the supporting roles."""
        return bool(list(set(supporting_roles) & set(r.id for r in member.roles)))

    async def _fill_template(self, template: str):
        """Replace {invite} placeholder with actual bot invite URL."""
        invite_url = await self.bot.get_cog("Core")._invite_url()
        return template.replace(
            "{invite}", f"{invite_url}"
        )

    async def _send_thanks(self, message: dict):
        """Send thank you message if enabled."""
        if message["toggle"]:
            if not message["content"]:
                to_send = THANKS
            else:
                to_send = message["content"]
            return await self._fill_template(to_send)
        return None

    @staticmethod
    async def _send_expire(message: dict):
        """Send expiration message if enabled."""
        if message["toggle"]:
            if not message["content"]:
                return EXPIRE
            else:
                return message["content"]
        return None

    @commands.group(name="botaccess")
    async def _bot_access(self, ctx: commands.Context):
        """BotAccess Settings"""
        pass

    @_bot_access.group(name="servers", invoke_without_command=True)
    async def _servers(self, ctx: commands.Context):
        """View and modify your current BotAccess server(s)."""
        user_settings = await self.config.user(ctx.author).all()

        if user_settings["supporting_in"]:
            # Build embed with server names and IDs
            server_names = []
            for g in user_settings['servers']:
                gu = self.bot.get_guild(g)
                if gu:
                    server_names.append(f'`{gu.name}` (`{g}`)')
                else:
