    async def _initiate_autoleave(self, user_id: int, start_timer: bool = True):
        """Start the auto-leave process for a user."""
        auto_leave = await self.config.auto_leave()
        if not auto_leave["toggle"]:
            return

        end_timestamp = (datetime.now()+timedelta(hours=auto_leave["delay"])).timestamp()
        await self.config.user_from_id(user_id).end_timestamp.set(end_timestamp)

        if start_timer:
            await self._expire_timer(user_id, end_timestamp)

    async def _refresh_supporters(self):
        """Refresh all BotAccess supporters based on current roles."""
        main_server_settings = await self.config.main_servers()
        main_servers_list: list[discord.Guild] = []

        for g in main_server_settings.keys():
            if gu := self.bot.get_guild(int(g)):
                main_servers_list.append(gu)

        original_settings = await self.config.all_users()
        original_users = [u for u in original_settings.keys()]

        # Clear existing user data
        await self.config.clear_all_users()

        refreshed_settings = {}
        new_users: list[discord.Member] = []
        new_user_ids: list[int] = []

        # Refresh settings
        for guild in main_servers_list:
            for r in main_server_settings[str(guild.id)]:
                if role := guild.get_role(r):
                    async for member in AsyncIter(role.members, steps=100):
                        if cur := refreshed_settings.get(str(member.id)):
                            cur["supporting_in"].append(guild.id)
                            refreshed_settings[str(member.id)] = {
                                "supporting_in": cur["supporting_in"],
                                "servers": cur["servers"],
                                "end_timestamp": cur["end_timestamp"]
                            }
                        elif orig := original_settings.get(member.id):
                            if member.id in original_users:
                                original_users.remove(member.id)
                            refreshed_settings[str(member.id)] = {
                                "supporting_in": [guild.id],
                                "servers": orig["servers"],
                                "end_timestamp": orig["end_timestamp"]
                            }
                        else:
                            new_users.append(member)
                            new_user_ids.append(member.id)
                            refreshed_settings[str(member.id)] = {
                                "supporting_in": [guild.id],
                                "servers": [],
                                "end_timestamp": None
                            }

        # Store to config
        async for user, settings in AsyncIter(refreshed_settings.items(), steps=50):
            async with self.config.user_from_id(int(user)).all() as cur_settings:
                cur_settings["supporting_in"] = settings["supporting_in"]
                cur_settings["servers"] = settings["servers"]
                cur_settings["end_timestamp"] = settings["end_timestamp"]

        messages = await self.config.messages()
        thanks = await self._send_thanks(messages["thanks"])
        expire = await self._send_expire(messages["expire"])

        # New users
        if thanks:
            async for user in AsyncIter(new_users, steps=100):
                try:
                    await user.send(thanks)
                except discord.HTTPException:
                    pass

        # Expired users
        async for user_id in AsyncIter(original_users, steps=100):
            try:
                user = await self.bot.get_or_fetch_user(user_id)
                if not original_settings.get(user_id)["end_timestamp"]:
                    if expire:
                        await user.send(expire)
                    await self._initiate_autoleave(user_id, start_timer=False)
            except discord.HTTPException:
                pass

    async def _expire_handler(self):
        """Background task to handle expirations."""
        await self.bot.wait_until_red_ready()
        await self._refresh_supporters()

        try:
            expire_coros = []
            for user, data in (await self.config.all_users()).items():
                if not data["servers"] and not data["supporting_in"] and not data["end_timestamp"]:
                    await self.config.user_from_id(int(user)).clear()
                    continue

                if data["supporting_in"] or not data["end_timestamp"]:
                    continue

                expire_coros.append(self._expire_timer(int(user), data["end_timestamp"]))

            await asyncio.gather(*expire_coros)
        except Exception:
            pass

    async def _expire_timer(self, user_id: int, end_timestamp: float):
        """Wait until expiration time and then process."""
        seconds_left = (datetime.fromtimestamp(end_timestamp) - datetime.now()).total_seconds()
        if seconds_left > 0:
            await asyncio.sleep(seconds_left)
        await self._expire_leave(user_id)

    async def _expire_leave(self, user_id: int):
        """Process leaving servers when user expires."""
        user_settings = await self.config.user_from_id(user_id).all()
        main_servers = await self.config.main_servers()
        allowed = await self.config.allowed()

        if user_settings["end_timestamp"] and not user_settings["supporting_in"]:
            if datetime.fromtimestamp(user_settings["end_timestamp"]) <= datetime.now():
                for guild in user_settings["servers"]:
                    if g := self.bot.get_guild(guild):
                        if g.id not in allowed and str(g.id) not in main_servers.keys():
                            await g.leave()
                await self.config.user_from_id(user_id).clear()
            else:
                await self._expire_timer(user_id, user_settings["end_timestamp"])

# Task registry module for Celery tasks with metadata and ordering support
from __future__ import annotations

from dataclasses import dataclass
from typing import TYPE_CHECKING, Any, Callable, Dict

from .dashboardbuild import build_dashboard
from .editionrebuild import mock_rebuild_edition, rebuild_edition
from .renameedition import mock_rename_edition, rename_edition

if TYPE_CHECKING:
    import celery.app.task.Task

__all__ = ["TaskRegistry", "task_registry", "RegisteredTask"]


@dataclass
class RegisteredTask:
    """A celery task with associated metadata."""

    name: str
    """The task's identifier."""

    task: celery.app.task.Task
    """The task function."""

    order: int
    """The sorting order of the task; tasks with smaller sort orders run first."""

    test_mock: Callable
    """A function that performs the DB actions of a task without its other side-effects."""

    def __lt__(self, other: Any) -> bool:
        if isinstance(other, RegisteredTask):
            return self.order < other.order
        else:
            raise ValueError

    def __le__(self, other: Any) -> bool:
        if isinstance(other, RegisteredTask):
            return self.order <= other.order
        else:
            raise ValueError

    def __ge__(self, other: Any) -> bool:
        if isinstance(other, RegisteredTask):
            return self.order >= other.order
        else:
            raise ValueError

    def __gt__(self, other: Any) -> bool:
        if isinstance(other, RegisteredTask):
            return self.order > other.order
        else:
            raise ValueError


class TaskRegistry:
    """A registry that associates task command names with their Celery callable functions."""

    def __init__(self) -> None:
        self._tasks: Dict[str, RegisteredTask] = {}

    def __getitem__(self, name: str) -> RegisteredTask:
        return self._tasks[name]

    def add(
        self,
        *,
        name: str,
        task: celery.app.task.Task,
        order: int,
        test_mock: Callable,
    ) -> None:
        """Add a task to the registry."""
        self._tasks[name] = RegisteredTask(
            name=name,
            task=task,
            order=order,
            test_mock=test_mock,
        )


# Global task registry instance
task_registry = TaskRegistry()

# Register tasks in order of execution priority
task_registry.add(
    name="rename_editon",
    task=rename_edition,
    order=9,
    test_mock=mock_rename_edition,
)

task_registry.add(
    name="rebuild_edition",
    task=rebuild_edition,
    order=10,
    test_mock=mock_rebuild_edition,
)

task_registry.add(
    name="build_dashboard",
    task=build_dashboard,
    order=20,
    test_mock=lambda product_id: None,
)

# Import necessary modules
from torch import nn
import torch.nn.functional as F

def take_middle_of_img(x, image_size):  # assumes square images
    width = x.shape[-1]
    start_index = (width - image_size) // 2
    return x[:, :, start_index: start_index + image_size, start_index: start_index + image_size]

class default_decoder(nn.Module):
    def __init__(self, args):
        super(default_decoder, self).__init__()
        self.image_size = args.image_shape[0]

        self.conv1 = nn.ConvTranspose2d(
            args.dict_nbatoms, 300, kernel_size=4, stride=2, padding=0, bias=True
        )
        self.conv2 = nn.ConvTranspose2d(
            300, 100, kernel_size=3, stride=1, padding=0, bias=True
        )
        self.conv3 = nn.ConvTranspose2d(
            100, 3, kernel_size=3, stride=1, padding=0, bias=True
        )

    def forward(self, x):
        out = F.relu(self.conv1(x))
        out = F.relu(self.conv2(out))
        out = F.relu(self.conv3(out))
        out = take_middle_of_img(out, self.image_size)
        return out.clamp(0.0, 1.0)

class small_decoder(nn.Module):
    def __init__(self, args):
        super(small_decoder, self).__init__()
        self.image_size = args.image_shape[0]

        self.conv1 = nn.ConvTranspose2d(
            args.dict_nbatoms, 30, kernel_size=4, stride=2, padding=0, bias=True
        )
        self.conv2 = nn.ConvTranspose2d(
            30, 10, kernel_size=3, stride=1, padding=0, bias=True
        )
        self.conv3 = nn.ConvTranspose2d(
            10, 3, kernel_size=3, stride=1, padding=0, bias=True
        )

    def forward(self, x):
        out = F.relu(self.conv1(x))
        out = F.relu(self.conv2(out))
        out = F.relu(self.conv3(out))
        out = take_middle_of_img(out, self.image_size)
        return out.clamp(0.0, 1.0)

class deep_decoder(nn.Module):
    def __init__(self, args):
        super(deep_decoder, self).__init__()
        self.image_size = args.image_shape[0]

        self.conv1 = nn.ConvTranspose2d(
            args.dict_nbatoms, 300, kernel_size=4, stride=2, padding=0, bias=True
        )
        self.conv2 = nn.ConvTranspose2d(
            300, 100, kernel_size=3, stride=1, padding=0, bias=True
        )
        self.conv3 = nn.ConvTranspose2d(
            100, 30, kernel_size=3, stride=1, padding=0, bias=True
        )
        self.conv4 = nn.ConvTranspose2d(
            30, 10, kernel_size=3, stride=1, padding=0, bias=True
        )
        self.conv5 = nn.ConvTranspose2d(
            10, 3, kernel_size=3, stride=1, padding=0, bias=True
        )

    def forward(self, x):
        out = F.relu(self.conv1(x))
        out = F.relu(self.conv2(out))
        out = F.relu(self.conv3(out))
        out = F.interpolate(out, size=(self.image_size+2), mode="bicubic")
        out = F.relu(self.conv4(out))
        out = F.relu(self.conv5(out))
        out = take_middle_of_img(out, self.image_size)
        return out.clamp(0.0, 1.0)

class resize_decoder(nn.Module):
    def __init__(self, args):
        super(resize_decoder, self).__init__()
        self.image_size = args.image_shape[0]

        self.conv1 = nn.ConvTranspose2d(
            args.dict_nbatoms, 300, kernel_size=3, stride=1, padding=0, bias=True
        )
        self.conv2 = nn.ConvTranspose2d(
            300, 100, kernel_size=3, stride=1, padding=0, bias=True
        )
        self.conv3 = nn.ConvTranspose2d(
            100, 3, kernel_size=3, stride=1, padding=0, bias=True
        )

    def forward(self, x):
        out = F.relu(self.conv1(x))
        out = F.interpolate(out, size=(self.image_size+2), mode="bicubic")
        out = F.relu(self.conv2(out))
        out = F.relu(self.conv3(out))
        out = take_middle_of_img(out, self.image_size)
        return out.clamp(0.0, 1.0)

decoder_dict = {
    "default_decoder": default_decoder,
    "resize_decoder": resize_decoder,
    "deep_decoder": deep_decoder,
    "small_decoder": small_decoder
}

