    @utils.order_protection
    def stop_loss_order(self, symbol: str, price: float, size: float) -> StopLossOrder:
        side = 'sell'
        needed = self.needed['stop_loss']
        order = utils.build_order_info(price, side, size, symbol, 'stop_loss')

