from mindspeed_mm.models.common.module_spec.qwen2vl_layer_spec import get_qwen2vl_llm_layer_spec, get_qwen2_5_vit_layer_spec
from mindspeed_mm.models.common.module_spec.qwen3vl_layer_spec import get_qwen3vl_layer_spec
from mindspeed_mm.models.common.module_spec.qwen2_5omni_layer_spec import get_qwen_omni_audio_layer_spec
from mindspeed_mm.models.common.module_spec.internvl_layer_spec import get_language_layer_spec, get_vit_layer_spec
from mindspeed_mm.models.common.module_spec.deepseekvl_layer_spec import get_deepseekvl_model_spec
from mindspeed_mm.models.common.module_spec.qwen3vl_layer_spec import get_qwen3vl_llm_layer_local_spec
from mindspeed_mm.models.common.module_spec.glm4v_layer_spec import get_glm4v_layer_spec, get_glm4v_vit_layer_spec
from mindspeed_mm.models.common.module_spec.videoalign_layer_spec import get_videoalign_layer_spec, get_videoalign_llm_layer_spec

# Define dictionaries mapping model IDs to their respective layer specification functions
audio_layer_specs = {
    'qwen_omni': get_qwen_omni_audio_layer_spec
}

vit_layer_specs = {
    'qwen2vit': get_qwen2vl_layer_spec,
    'qwen3vit': get_qwen3vl_layer_spec,
    'qwen2_5_vit': get_qwen2_5_vit_layer_spec,
    'InternViT': get_vit_layer_spec,
    'glm4v_vit': get_glm4v_vit_layer_spec,
    'videoalign_vit': get_videoalign_layer_spec
}

llm_layer_specs = {
    'qwen2lm': get_qwen2vl_llm_layer_spec,
    'qwen2_5_lm': get_qwen2vl_llm_layer_spec,
    'qwen2_5_omni_thinker': get_qwen2vl_llm_layer_spec,
    'internllm': get_language_layer_spec,
    'deepseek': get_deepseekvl_model_spec,
    "qwen3_lm": get_qwen3vl_llm_layer_local_spec,
    "glm4v_lm": get_glm4v_layer_spec,
    "videoalign_lm": get_videoalign_llm_layer_spec
}

projector_layer_specs = {
    'lnmlp': get_mlp_module_spec,
    'mlp': get_mlp_module_spec
}


def get_vit_layer_spec(config, *args, **kwargs):
    """
    Retrieve the ViT (Vision Transformer) layer specification based on config.model_id.
    Returns None if no matching specification is found.
    """
    if getattr(config, 'model_id', None) is not None:
        if config.model_id in vit_layer_specs:
            return vit_layer_specs[config.model_id](config, is_vit=True)
    return None


def get_audio_layer_spec(config, *args, **kwargs):
    """
    Retrieve the audio layer specification based on config.model_id.
    Returns None if no matching specification is found.
    """
    if getattr(config, 'model_id', None) is not None:
        if config.model_id in audio_layer_specs:
            return audio_layer_specs[config.model_id](config, is_vit=True)
    return None


def get_llm_layer_spec(config, *args, **kwargs):
    """
    Retrieve the LLM (Large Language Model) layer specification based on config.model_id.
    Returns None if no matching specification is found.
    """
    if getattr(config, 'model_id', None) is not None:
        if config.model_id in llm_layer_specs:
            return llm_layer_specs[config.model_id](config, is_vit=False)
    return None


def get_projector_layer_spec(config, *args, **kwargs):
    """
    Retrieve the projector layer specification based on config.model_id.
    Returns the submodules of the projector spec or None if not found.
    """
    if getattr(config, 'model_id', None) is not None:
        if config.model_id in projector_layer_specs:
            return projector_layer_specs[config.model_id](config, use_te=False).submodules
    return None

# SteamUsers module for interacting with Steam user-related functionality
from enum import Enum
import steamworks.util 		as util
from steamworks.enums 		import *
from steamworks.structs 	import *
from steamworks.exceptions 	import *

class SteamUsers(object):
    def __init__(self, steam: object):
        self.steam = steam
        if not self.steam.loaded():
            raise SteamNotLoadedException('STEAMWORKS not yet loaded')

    def GetSteamID(self) -> int:
        """Get user's Steam ID.
        :return: int
        """
        return self.steam.GetSteamID()

    def LoggedOn(self) -> bool:
        """Check, true/false, if user is logged into Steam currently
        :return: bool
        """
        return self.steam.LoggedOn()

    def GetPlayerSteamLevel(self) -> int:
        """Get the user's Steam level.
        :return: int
        """
        return self.steam.GetPlayerSteamLevel()

    def GetGameBadgeLevel(self, series: int, foil: int) -> int:
        """Trading Card badges data access, if you only have one set of cards, the series will be 1.
        # The user has can have two different badges for a series; the regular (max level 5) and the foil (max level 1).
        :param series: int
        :param foil: int
        :return: int
        """
        return self.steam.GetGameBadgeLevel(series, foil)

    def GetAuthSessionTicket(self) -> str:
        """Retrieves an authentication ticket. Immediately usable in AuthenticateUserTicket.

		:return: str
		"""
        buffer = create_string_buffer(1024)
        length = self.steam.GetAuthSessionTicket(buffer)
        return buffer[0:length].hex().upper()

