def ceil_div(x, y):
    """Ceiling division: returns the smallest integer >= x/y."""
    return (x + y - 1) // y


def align(x, n_cols, aligned_bytes):
    """
    Aligns the number of columns to a multiple of aligned_bytes.
    """
    aligned_bytes = ceil_div(x.element_size() * n_cols, aligned_bytes) * aligned_bytes
    return aligned_bytes // x.element_size()


@triton.jit
def load_with_pred_1d(ptr, skip_boundary_check: tl.constexpr, mask: tl.tensor, other=0):
    """
    Load from memory with optional boundary check.
    """
    if not skip_boundary_check:
        return tl.load(ptr, mask, other=other)
    else:
        return tl.load(ptr)


@triton.jit
def store_with_pred_1d(ptr, value, skip_boundary_check: tl.constexpr, mask: tl.tensor):
    """
    Store to memory with optional boundary check.
    """
    if not skip_boundary_check:
        tl.store(ptr, value, mask)
    else:
        tl.store(ptr, value)


def tensor_cache(fn: Callable[..., torch.Tensor]) -> Callable[..., torch.Tensor]:
    """
    A decorator that caches the most recent result of a function with tensor inputs.

    This decorator stores the output for the most recent set of input tensors.
    If called again with identical tensor references, it returns the cached result.

    Args:
        fn (Callable[..., torch.Tensor]):
            The function to be decorated. It should take tensor inputs and return tensor outputs.

    Returns:
        Callable[..., torch.Tensor]:
            A wrapped version of the input function with single-entry caching.
    """
    last_args: Optional[Tuple] = None
    last_kwargs: Optional[Dict] = None
    last_result: Any = None

    @functools.wraps(fn)
    def wrapper(*args: Any, **kwargs: Any) -> Any:
        nonlocal last_args, last_kwargs, last_result

        # Check if we can reuse the cached result
        if last_args is not None and last_kwargs is not None:
            if len(args) == len(last_args) and len(kwargs) == len(last_kwargs):
                if all(a is b for a, b in zip(args, last_args)) and all(
                    k in last_kwargs and v is last_kwargs[k] for k, v in kwargs.items()
                ):
                    return last_result

        # Compute and cache new result
        result = fn(*args, **kwargs)
        last_args, last_kwargs, last_result = args, kwargs, result
        return result

    return wrapper


def input_guard(
    *,
    make_contiguous: bool = True,
    auto_to_device: bool = True,
) -> Callable[[Callable[..., torch.Tensor]], Callable[..., torch.Tensor]]:
    """
    A decorator to optionally:
      1. make all input tensors contiguous
      2. set device context based on input tensors
    """
    def decorator(fn: Callable[..., torch.Tensor]) -> Callable[..., torch.Tensor]:
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            # Make tensors contiguous if requested
            if make_contiguous:
                new_args = tuple(
                    a.contiguous() if isinstance(a, torch.Tensor) else a for a in args
                )
                new_kwargs = {
                    k: (v.contiguous() if isinstance(v, torch.Tensor) else v)
                    for k, v in kwargs.items()
                }
            else:
                new_args = args
                new_kwargs = kwargs

            # Find first tensor to determine device
            tensor = None
            for a in new_args:
                if isinstance(a, torch.Tensor):
                    tensor = a
                    break
            if tensor is None:
                for v in new_kwargs.values():
                    if isinstance(v, torch.Tensor):
                        tensor = v
                        break

            # Set device context if needed
            if auto_to_device and tensor is not None:
                ctx = custom_device_ctx(tensor.device.index)
            else:
                ctx = contextlib.nullcontext()

            with ctx:
                return fn(*new_args, **new_kwargs)

        return wrapper

    return decorator


# TODO(liuyuan): remove the following statements when triton-npu supports checking whether an address is device-valid.
# See https://github.com/triton-lang/triton/blob/571d07b84ffbaee4b873c2918208e2c640057768/third_party/nvidia/backend/driver.py#L415
def tensor_device_guard_for_triton_kernel(path, name, device="npu"):
    """
    Adds runtime checks to ensure no CPU tensors are passed to Triton kernels.
    Can be disabled via MOJO_DISABLE_TENSOR_GUARD environment variable.
    """
    from mojo_opset.utils.misc import get_bool_env
    disable = get_bool_env("MOJO_DISABLE_TENSOR_GUARD", True)
    if disable:
        return

    import pkgutil
    import importlib
    from inspect import getmembers
    import torch.utils._pytree as pytree
    from triton.runtime.jit import JITFunction, KernelInterface

    def device_guard(*args, **kwargs):
        if not pytree.tree_all_only(
            torch.Tensor, lambda x: x.device.type == device, (args, kwargs)
        ):
            raise TypeError("Found cpu tensor(s) which should not be passed to the triton kernel.")

    for _, name, _ in pkgutil.walk_packages(path, prefix=f"{name}."):
        module = importlib.import_module(name)
        for obj_name, obj in getmembers(module):
            if not isinstance(obj, KernelInterface):
                continue
            # NOTE(liuyuan): for autotuners.
            while not isinstance(obj, JITFunction):
                obj = obj.fn
            obj.add_pre_run_hook(device_guard)


