@tensor_cache
def prepare_lens(cu_seqlens: torch.LongTensor) -> torch.LongTensor:
    """Compute sequence lengths from cumulative sequence lengths."""
    return cu_seqlens[1:] - cu_seqlens[:-1]


@tensor_cache
def prepare_chunk_indices(cu_seqlens: torch.LongTensor, chunk_size: int) -> torch.LongTensor:
    """
    Prepare indices for chunked attention processing.

    Returns a tensor of shape [total_chunks, 2], where each row contains:
    [chunk_id_in_sequence, global_chunk_index]
    """
    lens = triton.cdiv(prepare_lens(cu_seqlens), chunk_size)
    total = lens.sum()
    flat = torch.arange(total, device=cu_seqlens.device)
    seq_ids = torch.repeat_interleave(
        torch.arange(lens.numel(), device=cu_seqlens.device), lens
    )
    offsets = torch.cumsum(lens, 0) - lens
    indices = flat - offsets[seq_ids]
    return torch.stack([indices.eq(0).cumsum(0) - 1, indices], dim=1)

