@bp.route('/api/v2/users/<int:user_id>/mtls/certificates', methods=['POST'])
@require_auth(['admin:users'])
def create_user_mtls_certificate(user_id):
    """Generate or import an mTLS certificate for a user (admin only)."""
    from models import Certificate, CA, SystemConfig
    from models.auth_certificate import AuthCertificate
    from services.cert_service import CertificateService

    target_user = User.query.get(user_id)
    if not target_user:
        return error_response('User not found', 404)

    data = request.get_json() or {}
    mode = data.get('mode', 'generate')  # 'generate' or 'import'

    if mode == 'import':
        pem_text = data.get('pem', '').strip()
        name = data.get('name', '').strip()

        if not pem_text:
            return error_response('PEM certificate data is required', 400)

        try:
            if not pem_text.startswith('-----BEGIN'):
                try:
                    pem_text = base64.b64decode(pem_text).decode('utf-8')
                except Exception:
                    return error_response('Invalid certificate format', 400)

            pem_bytes = pem_text.encode('utf-8')
            cert_obj = cx509.load_pem_x509_certificate(pem_bytes, default_backend())
        except Exception as e:
            return error_response('Invalid PEM certificate data', 400)

        serial = str(cert_obj.serial_number)
        subject_dn = cert_obj.subject.rfc4514_string()
        issuer_dn = cert_obj.issuer.rfc4514_string()
        fingerprint = hashlib.sha256(cert_obj.public_bytes(serialization.Encoding.DER)).hexdigest().upper()

        valid_from = cert_obj.not_valid_before_utc if hasattr(cert_obj, 'not_valid_before_utc') else cert_obj.not_valid_before
        valid_until = cert_obj.not_valid_after_utc if hasattr(cert_obj, 'not_valid_after_utc') else cert_obj.not_valid_after

        existing = AuthCertificate.query.filter_by(cert_serial=serial).first()
        if existing:
            return error_response('This certificate is already enrolled', 409)

        cn = ''
        for attr in cert_obj.subject:
            if attr.oid == cx509.oid.NameOID.COMMON_NAME:
                cn = attr.value
                break

        cert_name = name or cn or f"Imported {serial[:8]}"

        # Create Certificate record if not exists
        existing_cert = Certificate.query.filter_by(serial_number=serial).first()
        if not existing_cert:
            issuer_ca = CA.query.filter(CA.subject == issuer_dn).first()
            existing_cert = Certificate(
                refid=str(uuid.uuid4()),
                descr=cert_name,
                caref=issuer_ca.refid if issuer_ca else None,
                crt=base64.b64encode(pem_bytes).decode('utf-8'),
                cert_type='usr_cert',
                subject=subject_dn,
                subject_cn=cn,
                issuer=issuer_dn,
                serial_number=serial,
                valid_from=valid_from,
                valid_to=valid_until,
                created_by=target_user.username,
            )
            db.session.add(existing_cert)
            db.session.flush()

        auth_cert = AuthCertificate(
            user_id=user_id,
            cert_serial=serial,
            cert_subject=subject_dn,
            cert_issuer=issuer_dn,
            cert_fingerprint=fingerprint,
            cert_pem=pem_bytes,
            name=cert_name,
            valid_from=valid_from,
            valid_until=valid_until,
            enabled=True,
        )
        db.session.add(auth_cert)
        db.session.commit()

        AuditService.log_action(
            action='admin_mtls_import',
            resource_type='certificate',
            resource_name=auth_cert.name,
            details=f'Admin imported mTLS cert for user {target_user.username}',
            success=True,
        )
        return created_response(data=auth_cert.to_dict(), message='Certificate imported')

    else:
        # Generate mode
        name = data.get('name', '').strip() or f"{target_user.username}@mtls"
        ca_id = data.get('ca_id')
        validity_days = data.get('validity_days', 365)

        # Find CA
        ca = None
        if ca_id:
            ca = CA.query.filter((CA.refid == ca_id) | (CA.id == ca_id)).first()

        if not ca:
            config = SystemConfig.query.filter_by(key='mtls_trusted_ca').first()
            if config:
                ca = CA.query.filter_by(refid=config.value).first()

        if not ca:
            return error_response('No CA available for mTLS certificate generation', 400)

        try:
            result = CertificateService.create_user_certificate(
                ca_refid=ca.refid,
                common_name=name,
                validity_days=int(validity_days),
                key_type='RSA',
                key_size=2048,
                username=target_user.username,
            )

            cert_pem = base64.b64decode(result.crt) if result.crt else b''
            cert_obj = cx509.load_pem_x509_certificate(cert_pem, default_backend())

            serial = str(cert_obj.serial_number)
            subject_dn = cert_obj.subject.rfc4514_string()
            issuer_dn = cert_obj.issuer.rfc4514_string()
            fingerprint = hashlib.sha256(cert_obj.public_bytes(serialization.Encoding.DER)).hexdigest().upper()

            valid_from = cert_obj.not_valid_before_utc if hasattr(cert_obj, 'not_valid_before_utc') else cert_obj.not_valid_before
            valid_until = cert_obj.not_valid_after_utc if hasattr(cert_obj, 'not_valid_after_utc') else cert_obj.not_valid_after

            auth_cert = AuthCertificate(
                user_id=user_id,
                cert_serial=serial,
                cert_subject=subject_dn,
                cert_issuer=issuer_dn,
                cert_fingerprint=fingerprint,
                cert_pem=cert_pem,
                name=name,
                valid_from=valid_from,
                valid_until=valid_until,
                enabled=True,
            )
            db.session.add(auth_cert)
            db.session.commit()

            key_pem = base64.b64decode(result.prv).decode('utf-8') if result.prv else ''

            AuditService.log_action(
                action='admin_mtls_generate',
                resource_type='certificate',
                resource_name=name,
                details=f'Admin generated mTLS cert for user {target_user.username}',
                success=True,
            )

            resp = auth_cert.to_dict()
            resp['certificate'] = cert_pem.decode('utf-8')
            resp['private_key'] = key_pem
            resp['cert_id'] = result.id

            return created_response(data=resp, message='Certificate generated')

        except Exception as e:
            import logging
            logging.getLogger(__name__).error(f"Failed to generate mTLS cert for user {user_id}: {e}")
            return error_response('Failed to generate certificate', 500)

@bp.route('/api/v2/users/<int:user_id>/mtls/certificates/<int:cert_id>', methods=['DELETE'])
@require_auth(['admin:users'])
def delete_user_mtls_certificate(user_id, cert_id):
    """Delete an mTLS certificate for a user (admin only)."""
    from models.auth_certificate import AuthCertificate

    target_user = User.query.get(user_id)
    if not target_user:
        return error_response('User not found', 404)

    auth_cert = AuthCertificate.query.get(cert_id)
    if not auth_cert or auth_cert.user_id != user_id:
        return error_response('Certificate not found', 404)

    cert_name = auth_cert.name or f'Certificate #{cert_id}'
    db.session.delete(auth_cert)
    db.session.commit()

    AuditService.log_action(
        action='admin_mtls_delete',
        resource_type='certificate',
        resource_id=str(cert_id),
        resource_name=cert_name,
        details=f'Admin deleted mTLS cert {cert_name} for user {target_user.username}',
        success=True,
    )
    return no_content_response()

# Import necessary modules for logging and inspection
import inspect
import logging
from loguru import logger


class InterceptHandler(logging.Handler):
    """
    Intercepts standard logging calls and forwards them to loguru.
    Preserves the original caller information so that log messages show the
    correct source file and line number rather than the handler itself.
    """

    def emit(self, record: logging.LogRecord) -> None:
        # Get corresponding Loguru level if it exists.
        level: str | int

        try:
            level = logger.level(record.levelname).name
        except ValueError:
            level = record.levelno

        # Find caller from where originated the logged message.
        frame, depth = inspect.currentframe(), 0

        while frame and (depth == 0 or frame.f_code.co_filename == logging.__file__):
            frame = frame.f_back
            depth += 1

        # Log using loguru with preserved context
        logger.opt(depth=depth, exception=record.exc_info).log(level, record.getMessage())


class LoggerStdoutWriter:
    """Wrapper for redirecting stdout to logger."""

    @staticmethod
    def write(msg: str) -> None:
        # Remove trailing newline and log non-empty messages
        msg = msg.rstrip("\n")
        if msg:
            logger.info(msg)

    @staticmethod
    def flush() -> None:
        # No-op flush method for compatibility with stdout interface
        pass

# OpenCastor Hardware Test -- wiggle each motor/servo one at a time.
# Loads an RCAN config, initializes the driver, and tests each
# actuator individually with user confirmation per step.

"""
Usage:
    castor test-hardware --config robot.rcan.yaml
"""

import logging
import time
import yaml

logger = logging.getLogger("OpenCastor.TestHardware")


def _load_config(config_path: str) -> dict:
    """Load and return the RCAN config."""
    with open(config_path) as f:
        return yaml.safe_load(f)


def _get_test_sequence(config: dict) -> list:
    """Build a list of test steps based on driver config.
    Each step is a dict: ``{"name": str, "action": dict, "duration": float}``.
    """
    steps = []
    drivers = config.get("drivers", [])

    if not drivers:
        return steps

    driver = drivers[0]
    protocol = driver.get("protocol", "")

    if "pca9685_rc" in protocol:
        # RC car: test steering left, center, right, then throttle
        steps = [
            {
                "name": "Steering LEFT",
                "action": {"type": "move", "linear": 0.0, "angular": -0.5},
                "duration": 1.0,
            },
            {
                "name": "Steering CENTER",
                "action": {"type": "move", "linear": 0.0, "angular": 0.0},
                "duration": 0.5,
            },
            {
                "name": "Steering RIGHT",
                "action": {"type": "move", "linear": 0.0, "angular": 0.5},
                "duration": 1.0,
            },
            {
                "name": "Steering CENTER",
                "action": {"type": "move", "linear": 0.0, "angular": 0.0},
                "duration": 0.5,
            },
            {
                "name": "Throttle FORWARD (slow)",
                "action": {"type": "move", "linear": 0.15, "angular": 0.0},
                "duration": 1.0,
            },
            {"name": "Throttle STOP", "action": {"type": "stop"}, "duration": 0.5},
            {
                "name": "Throttle REVERSE (slow)",
                "action": {"type": "move", "linear": -0.15, "angular": 0.0},
                "duration": 1.0,
            },
            {"name": "Throttle STOP", "action": {"type": "stop"}, "duration": 0.5},
        ]

    elif "pca9685" in protocol:
        # Differential drive: test each side
        steps = [
            {
                "name": "Left motors FORWARD",
                "action": {"type": "move", "linear": 0.2, "angular": -0.3},
                "duration": 1.0,
            },
            {"name": "STOP", "action": {"type": "stop"}, "duration": 0.5},
            {
                "name": "Right motors FORWARD",
                "action": {"type": "move", "linear": 0.2, "angular": 0.3},
                "duration": 1.0,
            },
            {"name": "STOP", "action": {"type": "stop"}, "duration": 0.5},
            {
                "name": "Both motors FORWARD",
                "action": {"type": "move", "linear": 0.2, "angular": 0.0},
                "duration": 1.0,
            },
            {"name": "STOP", "action": {"type": "stop"}, "duration": 0.5},
        ]

    elif "dynamixel" in protocol:
        # Dynamixel: test each servo position
        steps = [
            {
                "name": "Servo sweep FORWARD",
                "action": {"type": "move", "linear": 0.1, "angular": 0.0},
                "duration": 1.5,
            },
            {"name": "STOP", "action": {"type": "stop"}, "duration": 0.5},
            {
                "name": "Servo sweep LEFT",
                "action": {"type": "move", "linear": 0.0, "angular": -0.3},
                "duration": 1.5,
            },
            {"name": "STOP", "action": {"type": "stop"}, "duration": 0.5},
            {
                "name": "Servo sweep RIGHT",
                "action": {"type": "move", "linear": 0.0, "angular": 0.3},
                "duration": 1.5,
            },
            {"name": "STOP", "action": {"type": "stop"}, "duration": 0.5},
        ]

    else:
        # Generic: basic forward/stop
        steps = [
            {
                "name": "FORWARD (slow)",
                "action": {"type": "move", "linear": 0.15, "angular": 0.0},
                "duration": 1.0,
            },
            {"name": "STOP", "action": {"type": "stop"}, "duration": 0.5},
            {
                "name": "TURN LEFT",
                "action": {"type": "move", "linear": 0.0, "angular": -0.3},
                "duration": 1.0,
            },
            {"name": "STOP", "action": {"type": "stop"}, "duration": 0.5},
        ]

    return steps


def run_test(config_path: str, skip_confirm: bool = False):
    """Run the interactive hardware test.
    Args:
        config_path: Path to the RCAN config file.
        skip_confirm: If True, run all steps without prompting.
    """
    try:
        from rich.console import Console
        from rich.panel import Panel
        console = Console()
        has_rich = True
    except ImportError:
        has_rich = False

    config = _load_config(config_path)
    robot_name = config.get("metadata", {}).get("robot_name", "Robot")

    if has_rich:
        console.print()
        console.print(
            Panel.fit(
                f"[bold cyan]Hardware Test: {robot_name}[/]\n"
                "Each motor/servo will be tested individually.\n"
                "Keep hands clear of moving parts!",
                border_style="yellow",
            )
        )
    else:
        print(f"\n  Hardware Test: {robot_name}")
        print("  Each motor/servo will be tested individually.")
        print("  Keep hands clear of moving parts!\n")

    # Initialize driver
    from castor.main import get_driver
    driver = get_driver(config)

    if driver is None:
        msg = "No hardware driver could be initialized. Check your wiring and config."
        if has_rich:
            console.print(f"\n[bold red]{msg}[/]\n")
        else:
            print(f"\n  ERROR: {msg}\n")
        return False

    steps = _get_test_sequence(config)

    if not steps:
        msg = "No test sequence available for this driver configuration."
        if has_rich:
            console.print(f"\n[bold yellow]{msg}[/]\n")
        else:
            print(f"\n  {msg}\n")
        return False

    passed = 0
    failed = 0

    try:
        for i, step in enumerate(steps, 1):
            if has_rich:
                console.print(f"\n  [bold]Step {i}/{len(steps)}:[/] {step['name']}")
            else:
                print(f"\n  Step {i}/{len(steps)}: {step['name']}")

            if not skip_confirm:
                response = (
                    input("  Press Enter to execute (or 's' to skip, 'q' to quit): ")
                    .strip()
                    .lower()
                )
                if response == "q":
                    print("  Test aborted by user.")
                    break
                if response == "s":
                    print("  Skipped.")
                    continue

            # Execute the action
            action = step["action"]
            try:
                if action["type"] == "move":
                    driver.move(action.get("linear", 0.0), action.get("angular", 0.0))
                elif action["type"] == "stop":
                    driver.stop()

                time.sleep(step["duration"])
                driver.stop()

                if has_rich:
                    console.print(f"  [green]OK[/] -- {step['name']} completed")
                else:
                    print(f"  [OK] {step['name']} completed")

                passed += 1
            except Exception as exc:
                if has_rich:
                    console.print(f"  [red]FAIL[/] -- {exc}")
                else:
                    print(f"  [FAIL] {exc}")
                failed += 1
    finally:
        driver.stop()
        driver.close()

    # Summary
    if has_rich:
        status = (
            "[green]All tests passed!"
            if failed == 0
            else f"[yellow]{passed} passed, {failed} failed"
        )
        console.print(f"\n  {status}[/]\n")
    else:
        print(f"\n  {passed} passed, {failed} failed\n")

    return failed == 0

# Gmail API email fetcher
import os
import sys
import json
import argparse
import base64
from pathlib import Path

# Try importing required Google API packages
try:
    from google.auth.transport.requests import Request
    from google.oauth2.credentials import Credentials
    from google_auth_oauthlib.flow import InstalledAppFlow
    from googleapiclient.discovery import build
    from googleapiclient.errors import HttpError
except ImportError:
    print(json.dumps({
        "error": "Required packages not installed",
        "message": "Please install: pip install google-auth google-auth-oauthlib google-auth-httplib2 google-api-python-client"
    }))
    sys.exit(1)

# Gmail API scopes - read-only access
SCOPES = ['https://www.googleapis.com/auth/gmail.readonly']

def get_credentials():
    """Authenticate and return Gmail API credentials."""
    creds = None
    credentials_path = os.getenv('GMAIL_CREDENTIALS_PATH')

    if not credentials_path:
        return None, "Environment variable GMAIL_CREDENTIALS_PATH not set"

    credentials_path = Path(credentials_path).expanduser()
    token_path = credentials_path.parent / 'token.json'

    # Token file stores user's access and refresh tokens
    if token_path.exists():
        creds = Credentials.from_authorized_user_file(str(token_path), SCOPES)

    # If there are no valid credentials, let the user log in
    if not creds or not creds.valid:
        if creds and creds.expired and creds.refresh_token:
            creds.refresh(Request())
        else:
            if not credentials_path.exists():
                return None, f"Credentials file not found at {credentials_path}"

            flow = InstalledAppFlow.from_client_secrets_file(
                str(credentials_path), SCOPES)
            creds = flow.run_local_server(port=0)

        # Save the credentials for the next run
        with open(token_path, 'w') as token:
            token.write(creds.to_json())

    return creds, None

def decode_email_body(payload):
    """Extract and decode email body from message payload."""
    body = ""

    if 'parts' in payload:
        for part in payload['parts']:
            if part['mimeType'] == 'text/plain':
                if 'data' in part['body']:
                    body = base64.urlsafe_b64decode(part['body']['data']).decode('utf-8')
                    break
            elif part['mimeType'] == 'text/html' and not body:
                if 'data' in part['body']:
                    body = base64.urlsafe_b64decode(part['body']['data']).decode('utf-8')
    else:
        if 'body' in payload and 'data' in payload['body']:
            body = base64.urlsafe_b64decode(payload['body']['data']).decode('utf-8')

    return body

def get_header_value(headers, name):
    """Get header value by name."""
    for header in headers:
        if header['name'].lower() == name.lower():
            return header['value']
    return ''

def fetch_emails(count=10, fetch_all=False):
    """Fetch emails from Gmail."""
    creds, error = get_credentials()

    if error:
        return {"error": error}

    try:
        service = build('gmail', 'v1', credentials=creds)

        # Fetch unread messages
        query = 'is:unread'

        if fetch_all:
            results = service.users().messages().list(
                userId='me', q=query).execute()
        else:
            results = service.users().messages().list(
                userId='me', q=query, maxResults=count).execute()

        messages = results.get('messages', [])

        if not messages:
            return {"emails": [], "message": "No unread emails found"}

        emails = []

        for msg in messages:
            # Get full message details
            message = service.users().messages().get(
                userId='me', id=msg['id'], format='full').execute()

            headers = message['payload']['headers']
            subject = get_header_value(headers, 'Subject')
            sender = get_header_value(headers, 'From')
            date = get_header_value(headers, 'Date')
            body = decode_email_body(message['payload'])

            # Truncate body to reasonable length (first 1000 chars)
            if len(body) > 1000:
                body = body[:1000] + "..."

            emails.append({
                "id": msg['id'],
                "subject": subject,
                "from": sender,
                "date": date,
                "body": body,
                "snippet": message.get('snippet', '')
            })

        return {"emails": emails, "count": len(emails)}

    except HttpError as error:
        return {"error": f"Gmail API error: {error}"}
    except Exception as e:
        return {"error": f"Unexpected error: {str(e)}"}

def main():
    parser = argparse.ArgumentParser(description='Fetch emails from Gmail')
    parser.add_argument('--count', type=int, default=10,
                        help='Number of emails to fetch (default: 10)')
    parser.add_argument('--all', action='store_true',
                        help='Fetch all unread emails')
    args = parser.parse_args()

    result = fetch_emails(count=args.count, fetch_all=args.all)
    print(json.dumps(result, indent=2, ensure_ascii=False))

if __name__ == '__main__':
    main()

