from cosmos_rl.utils.constant import CACHE_DIR
from cosmos_rl.utils.logging import logger

# Define dataset URLs for DiffusionNFT datasets
DIFFUSION_NFT_DATASET_URL = {
    "pickscore": {
        "train": "https://raw.githubusercontent.com/NVlabs/DiffusionNFT/refs/heads/main/dataset/pickscore/train.txt",
        "test": "https://raw.githubusercontent.com/NVlabs/DiffusionNFT/refs/heads/main/dataset/pickscore/test.txt",
    },
    "ocr": {
        "train": "https://raw.githubusercontent.com/NVlabs/DiffusionNFT/refs/heads/main/dataset/ocr/train.txt",
        "test": "https://raw.githubusercontent.com/NVlabs/DiffusionNFT/refs/heads/main/dataset/ocr/test.txt",
    },
    "geneval": {
        "train": "https://raw.githubusercontent.com/NVlabs/DiffusionNFT/refs/heads/main/dataset/geneval/train_metadata.jsonl",
        "test": "https://raw.githubusercontent.com/NVlabs/DiffusionNFT/refs/heads/main/dataset/geneval/test_metadata.jsonl",
    },
    "dance_grpo_t2v": {
        "train": "https://raw.githubusercontent.com/XueZeyue/DanceGRPO/refs/heads/main/assets/video_prompts.txt",
        "test": "https://raw.githubusercontent.com/XueZeyue/DanceGRPO/refs/heads/main/assets/video_prompts.txt",  # No test set for dance_grpo_t2v dataset, using the same file as train
    },
}


class TextPromptDataset(Dataset):
    def __init__(self, dataset, split="train"):
        self.file_path = os.path.join(
            CACHE_DIR, "diffusion_nft", dataset, f"{split}.txt"
        )
        with open(self.file_path, "r") as f:
            self.prompts = [line.strip() for line in f.readlines()]

    def __len__(self):
        return len(self.prompts)

    def __getitem__(self, idx):
        return {"prompt": self.prompts[idx], "metadata": {}}


class GenevalPromptDataset(Dataset):
    def __init__(self, dataset, split="train"):
        self.file_path = os.path.join(
            CACHE_DIR, "diffusion_nft", dataset, f"{split}_metadata.jsonl"
        )
        with open(self.file_path, "r", encoding="utf-8") as f:
            self.metadatas = [json.loads(line) for line in f]
            self.prompts = [item["prompt"] for item in self.metadatas]

    def __len__(self):
        return len(self.prompts)

    def __getitem__(self, idx):
        return {"prompt": self.prompts[idx], "metadata": self.metadatas[idx]}


class DiffusionNFTDataPacker(BaseDataPacker):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)

    def setup(self, config: CosmosConfig, *args, **kwargs):
        super().setup(config, *args, **kwargs)

    def policy_compute_max_len(self, processed_samples: List[Any]) -> int:
        """
        Compute the maximum sequence length of the mini-batch
        """
        pass

    def policy_collate_fn(
        self, processed_samples: List[Any], computed_max_len: int
    ) -> Dict[str, Any]:
        """
        Collate the mini-batch into the kwargs required by the policy model
        """
        pass

    def get_rollout_input(
        self,
        completions: List[Any] = None,
        completed_conversations: List[Any] = None,
        logprobs: List[Any] = None,
        token_ids: List[Any] = None,
        payload: RLPayload = None,
        n_generation: int = 8,
    ):
        assert payload is not None, "Payload cannot be None."
        prompts = [payload.prompt["prompt"]] * n_generation
        metadatas = [payload.prompt["metadata"]] * n_generation
        return prompts, metadatas

    def get_policy_input(
        self,
        sample: List[Rollout],
        device: torch.device,
        rollout_output: Union[str, List[int]] = None,
        n_ignore_prefix_tokens: int = 0,
    ):
        # Batching the list of rollouts into a single input for the policy
        # Only extra_info is needed for diffusion NFT
        for s in sample:
            s.extra_info["advantages"] = torch.tensor(s.advantage, device=device)
            s.extra_info["rewards"] = torch.tensor(s.reward, device=device)
            s.extra_info["prompts"] = s.prompt
            s.extra_info["completions"] = s.completion

        inputs_list = [rollout.extra_info for rollout in sample]
        collated_samples = {}

        for k in inputs_list[0].keys():
            if isinstance(inputs_list[0][k], str):
                collated_samples[k] = [s[k] for s in inputs_list]
            elif isinstance(inputs_list[0][k], dict):
                if "prompt" in inputs_list[0][k].keys():
                    collated_samples[k] = [s[k]["prompt"] for s in inputs_list]
                else:  # metadata dict
                    collated_samples[k] = {
                        sk: torch.stack([s[k][sk] for s in inputs_list], dim=0)
                        for sk in inputs_list[0][k]
                    }
            elif inputs_list[0][k] is None:
                collated_samples[k] = None
            else:
                collated_samples[k] = torch.stack([s[k] for s in inputs_list], dim=0)

        if collated_samples["advantages"].ndim == 1:
            collated_samples["advantages"] = collated_samples["advantages"][:, None]

        return collated_samples


def get_dataset(dataset_config: DatasetConfig) -> Dataset:
    assert dataset_config.name in [
        "pickscore",
        "ocr",
        "geneval",
        "dance_grpo_t2v",
    ], f"Unknown dataset name: {dataset_config.name}"

    dataset_dir = os.path.join(CACHE_DIR, "diffusion_nft", dataset_config.name)
    os.makedirs(dataset_dir, exist_ok=True)

    local_path = os.path.join(
        dataset_dir,
        f"{dataset_config.split[0]}.txt"
        if dataset_config.name != "geneval"
        else f"{dataset_config.split[0]}_metadata.jsonl",
    )

    logger.info(f"Checking dataset at {local_path}...")

    if not os.path.exists(local_path):
        logger.info(f"Downloading dataset {dataset_config.name}...")
        url = DIFFUSION_NFT_DATASET_URL[dataset_config.name][
            "train" if dataset_config.split[0] == "train" else "test"
        ]
        os.system(f"wget {url} -O {local_path}")

    prompt_fn = "geneval" if dataset_config.name == "geneval" else "general_ocr"

    if prompt_fn == "general_ocr":
        dataset = TextPromptDataset(dataset_config.name, split=dataset_config.split[0])
    elif prompt_fn == "geneval":
        dataset = GenevalPromptDataset(
            dataset_config.name, split=dataset_config.split[0]
        )
    else:
        raise ValueError(f"Unknown dataset name: {dataset_config.name}")

    return dataset


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--config", type=str, required=True)
    args = parser.parse_known_args()[0]

    with open(args.config, "r") as f:
        config = toml.load(f)

    config = CosmosConfig.from_dict(config)

    train_dataset = get_dataset(config.train.train_policy.dataset)
    val_dataset = get_dataset(config.validation.dataset)

    launch_worker(
        dataset=train_dataset,
        val_dataset=val_dataset,
        data_packer=DiffusionNFTDataPacker(),
        val_data_packer=DiffusionNFTDataPacker(),
    )

# py2x checker script
from __future__ import annotations

import argparse
import json
import re
import subprocess
import sys
import tempfile
from dataclasses import dataclass
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
PY2X = ROOT / "src" / "py2x.py"
PROFILE_PATH = ROOT / "tools" / "check_py2x_profiles.json"

USER_ERROR_RE = re.compile(r"__PYTRA_USER_ERROR__\|([^|]+)\|([^\r\n]+)")
STAGE2_REMOVED_FRAGMENT = "--east-stage 2 is no longer supported; use EAST3 (default)."

PHP_SAMPLE18_REL = "sample/py/18_mini_language_interpreter.py"
PHP_SAMPLE18_REQUIRED_FRAGMENTS = [
    '$single_char_token_tags = ["+" => 1',
    "array_key_exists($node->name, $env)",
    "public function __construct($kind, $text, $pos, $number_value)",
    "public function __construct($kind, $value, $name, $op, $left, $right, $kind_tag, $op_tag)",
    "public function __construct($kind, $name, $expr_index, $kind_tag)",
    "function __pytra_entry_main(): void {",
    "__pytra_entry_main();",
]


@dataclass(frozen=True)
class RunResult:
    ok: bool
    message: str
    raw: str
    category: str


def _to_str(v: object) -> str:
    return v if isinstance(v, str) else ""


def _extract_user_error_category(text: str) -> str:
    m = USER_ERROR_RE.search(text)
    if m is None:
        return ""
    return m.group(1).strip()


def _extract_failure_headline(text: str) -> str:
    lines = [line.strip() for line in text.splitlines() if line.strip() != ""]
    if len(lines) == 0:
        return "unknown error"

    for line in lines:
        m = USER_ERROR_RE.search(line)
        if m is not None:
            return m.group(1) + ": " + m.group(2)

    for line in lines:
        if line.startswith("RuntimeError:"):
            return line

    return lines[0]


def _run_one(*, src: Path, out: Path, target: str) -> RunResult:
    cp = subprocess.run(
        ["python3", str(PY2X), str(src), "--target", target, "-o", str(out)],
        cwd=ROOT,
        capture_output=True,
        text=True,
    )

    compat_warning = "warning: --east-stage 2 is compatibility mode; default is 3."
    if cp.returncode == 0 and compat_warning in cp.stderr:
        return RunResult(False, "unexpected stage2 compatibility warning in default run", cp.stderr, "")

    if cp.returncode == 0:
        return RunResult(True, "", "", "")

    raw = (cp.stderr or "").strip() or (cp.stdout or "").strip()
    return RunResult(False, _extract_failure_headline(raw), raw, _extract_user_error_category(raw))


def _run_one_multifile(*, src: Path, out_dir: Path, target: str) -> RunResult:
    cp = subprocess.run(
        [
            "python3",
            str(PY2X),
            str(src),
            "--target",
            target,
            "--multi-file",
            "--output-dir",
            str(out_dir),
        ],
        cwd=ROOT,
        capture_output=True,
        text=True,
    )

    compat_warning = "warning: --east-stage 2 is compatibility mode; default is 3."
    if cp.returncode == 0 and compat_warning in cp.stderr:
        return RunResult(False, "unexpected stage2 compatibility warning in default run", cp.stderr, "")

    if cp.returncode == 0:
        return RunResult(True, "", "", "")

    raw = (cp.stderr or "").strip() or (cp.stdout or "").strip()
    return RunResult(False, _extract_failure_headline(raw), raw, _extract_user_error_category(raw))


def _run_stage2_probe(*, src: Path, out: Path, target: str, expected_fragment: str) -> tuple[bool, str]:
    cp = subprocess.run(
        ["python3", str(PY2X), str(src), "--target", target, "--east-stage", "2", "-o", str(out)],
        cwd=ROOT,
        capture_output=True,
        text=True,
    )

    if cp.returncode == 0:
        return False, "unexpected success for --east-stage 2"

    stderr = cp.stderr.strip()
    needle = expected_fragment if expected_fragment != "" else STAGE2_REMOVED_FRAGMENT

    if needle in stderr:
        return True, ""

    first = stderr.splitlines()[0] if stderr else "missing stderr message"
    return False, "unexpected stage2 error message: " + first


def _run_quality_hook(hook: str, rel: str, out: Path) -> str:
    if hook == "scala_sample01":
        if rel != "sample/py/01_mandelbrot.py":
            return ""

        text = out.read_text(encoding="utf-8")

        if "boundary:" in text or "__breakLabel_" in text or "__continueLabel_" in text:
            return "sample/01 quality regression: boundary labels reintroduced"

        if "__pytra_int(0L)" in text:
            return "sample/01 quality regression: identity int cast reintroduced"

        if "__pytra_int(height)" in text or "__pytra_int(width)" in text or "__pytra_int(max_iter)" in text:
            return "sample/01 quality regression: typed range bound cast reintroduced"

        return ""

    if hook == "php_sample18":
        if rel != PHP_SAMPLE18_REL:
            return ""

        text = out.read_text(encoding="utf-8")
        i = 0

        while i < len(PHP_SAMPLE18_REQUIRED_FRAGMENTS):
            frag = PHP_SAMPLE18_REQUIRED_FRAGMENTS[i]
            if frag not in text:
                return "sample18 missing fragment: " + frag
            i += 1

        return ""

    if hook == "":
        return ""

    return "unknown quality hook: " + hook


def _load_profiles(profile_path: Path) -> dict[str, dict[str, object]]:
    doc = json.loads(profile_path.read_text(encoding="utf-8"))
    profiles_any = doc.get("profiles")

    if not isinstance(profiles_any, dict):
        raise RuntimeError("profiles must be an object")

    out: dict[str, dict[str, object]] = {}

    for key, value in profiles_any.items():
        if isinstance(key, str) and isinstance(value, dict):
            out[key] = value

    return out


def _has_import_statement(src: Path) -> bool:
    text = src.read_text(encoding="utf-8")
    for line in text.splitlines():
        s = line.strip()
        if s.startswith("import ") or s.startswith("from "):
            return True
    return False


def _collect_yanesdk_smoke_files() -> list[Path]:
    out: list[Path] = []

    lib = ROOT / "Yanesdk" / "yanesdk" / "yanesdk.py"
    if lib.exists():
        out.append(lib)

    docs_root = ROOT / "Yanesdk" / "docs"
    if docs_root.exists():
        docs_games: list[Path] = []
        for p in sorted(docs_root.rglob("*.py")):
            if p.name == "yanesdk.py":
                continue
            docs_games.append(p)

        if len(docs_games) > 0:
            out.append(docs_games[0])

    return out


def _profile_cases(profile: dict[str, object]) -> list[str]:
    mode = _to_str(profile.get("case_mode"))

    if mode == "all":
        fixture_files = sorted((ROOT / "test" / "fixtures").rglob("*.py"))
        sample_files = sorted((ROOT / "sample" / "py").glob("*.py"))
        rels = [str(p.relative_to(ROOT)).replace("\\", "/") for p in fixture_files + sample_files]
        return rels

    if mode == "explicit":
        cases_any = profile.get("cases")
        cases = cases_any if isinstance(cases_any, list) else []
        out: list[str] = []
        i = 0

        while i < len(cases):
            rel = _to_str(cases[i])
            if rel != "":
                out.append(rel)
            i += 1

        return out

    raise RuntimeError("unsupported case_mode: " + mode)


def _expected_map(profile: dict[str, object]) -> dict[str, dict[str, str]]:
    out: dict[str, dict[str, str]] = {}
    obj_any = profile.get("expected_failures")
    obj = obj_any if isinstance(obj_any, dict) else {}

    for rel, spec_any in obj.items():
        if not isinstance(rel, str) or not isinstance(spec_any, dict):
            continue

        category = _to_str(spec_any.get("category"))
        contains = _to_str(spec_any.get("contains"))
        out[rel] = {"category": category, "contains": contains}

    return out


def _validate_runtime_side_files(profile: dict[str, object], out: Path) -> str:
    required_any = profile.get("required_runtime_files")
    required = required_any if isinstance(required_any, list) else []

    i = 0
    while i < len(required):
        rel = _to_str(required[i])
        if rel != "" and not (out.parent / rel).exists():
            return "missing runtime file: " + rel
        i += 1

    return ""


def _validate_runtime_side_file_contains(profile: dict[str, object], out: Path) -> str:
    required_any = profile.get("required_runtime_file_contains")
    required = required_any if isinstance(required_any, dict) else {}

    for rel, fragments_any in required.items():
        if not isinstance(rel, str):
            continue

        fragments = fragments_any if isinstance(fragments_any, list) else []
        side = out.parent / rel

        if not side.exists():
            return "missing runtime file for contains-check: " + rel

        text = side.read_text(encoding="utf-8")
        i = 0

        while i < len(fragments):
            frag = _to_str(fragments[i])
            if frag != "" and frag not in text:
                return "runtime file missing fragment: " + rel + " :: " + frag
            i += 1

    return ""


def _validate_forbid_fragments(profile: dict[str, object], out: Path) -> str:
    frags_any = profile.get("forbid_generated_contains")
    frags = frags_any if isinstance(frags_any, list) else []

    if len(frags) == 0:
        return ""

    text = out.read_text(encoding="utf-8")
    i = 0

    while i < len(frags):
        frag = _to_str(frags[i])
        if frag != "" and frag in text:
            return "forbidden fragment detected: " + frag
        i += 1

    return ""


def _run_preflight_hook(hook: str) -> str:
    if hook == "cpp_emitter_separation":
        cpp_cli = ROOT / "src" / "backends" / "cpp" / "cli.py"
        text = cpp_cli.read_text(encoding="utf-8")

        if "class CppEmitter" in text:
            return "class CppEmitter must not be implemented in src/backends/cpp/cli.py"

        if "from backends.cpp.emitter import CppEmitter" not in text:
            return "missing import from backends.cpp.emitter import CppEmitter"

        return ""

    if hook == "":
        return ""

    return "unknown preflight hook: " + hook


def _run_preflight_hooks(profile: dict[str, object]) -> tuple[bool, str]:
    hooks_any = profile.get("preflight_hooks")
    hooks = hooks_any if isinstance(hooks_any, list) else []

    i = 0
    while i < len(hooks):
        hook = _to_str(hooks[i])
        msg = _run_preflight_hook(hook)

        if msg != "":
            return False, msg

        i += 1

    return True, ""


def _run_east3_contract_preflight(profile: dict[str, object], *, skip: bool) -> tuple[bool, str]:
    if skip:
        return True, ""

    flags_any = profile.get("flags")
    flags = flags_any if isinstance(flags_any, dict) else {}

    if bool(flags.get("skip_east3_contract_tests", False)):
        return True, ""

    checks = [
        [
            "python3",
            "-m",
            "unittest",
            "discover",
            "-s",
            "test/unit",
            "-p",
            "test_east2_to_east3_lowering.py",
        ],
        [
            "python3",
            "-m",
            "unittest",
            "discover",
            "-s",
            "test/unit",
            "-p",
            "test_east3_cpp_bridge.py",
        ],
    ]

    i = 0
    while i < len(checks):
        cp = subprocess.run(
            checks[i],
            cwd=ROOT,
            capture_output=True,
            text=True,
        )

        if cp.returncode != 0:
            msg = cp.stderr.strip() or cp.stdout.strip() or "east3 contract preflight failed"
            first = msg.splitlines()[0] if msg else "unknown error"
            return False, first

        i += 1

    return True, ""


def main() -> int:
    ap = argparse.ArgumentParser(description="check py2x transpile success by target profile")
    ap.add_argument("--target", required=True, help="target language id")
    ap.add_argument("--profiles", default=str(PROFILE_PATH), help="profile json path")
    ap.add_argument("--include-expected-failures", action="store_true", help="do not skip expected-fail cases (skip-mode only)")
    ap.add_argument("--cases", default="", help="comma separated relative source paths (override profile cases)")
    ap.add_argument(
        "--skip-east3-contract-tests",
        action="store_true",
        help="skip EAST3 contract preflight regardless of profile flag",
    )
    ap.add_argument(
        "--check-multi-file-imports",
        action="store_true",
        help="also run --multi-file check for sample files that contain import/from (cpp only)",
    )
    ap.add_argument(
        "--check-yanesdk-smoke",
        action="store_true",
        help="also run reduced Yanesdk smoke cases (cpp only)",
    )
    ap.add_argument("--verbose", action="store_true", help="print passing files")
    args = ap.parse_args()

    profile_path = Path(args.profiles)
    profiles = _load_profiles(profile_path)
    target = args.target
    profile = profiles.get(target)

    if not isinstance(profile, dict):
        print("[FAIL] target profile not found: " + target)
        return 1

    if target != "cpp" and (args.check_multi_file_imports or args.check_yanesdk_smoke):
        print("[FAIL] --check-multi-file-imports / --check-yanesdk-smoke are supported only for --target cpp")
        return 1

    ok_preflight, preflight_msg = _run_preflight_hooks(profile)
    if not ok_preflight:
        print("[FAIL] " + preflight_msg)
        return 1

    ok_preflight, preflight_msg = _run_east3_contract_preflight(profile, skip=args.skip_east3_contract_tests)
    if not ok_preflight:
        print("[FAIL] " + preflight_msg)
        return 1

    cases = _profile_cases(profile)
    if args.cases.strip() != "":
        cases = [c.strip() for c in args.cases.split(",") if c.strip() != ""]

    expected = _expected_map(profile)
    expected_mode = _to_str(profile.get("expected_mode"))

    quality_any = profile.get("quality_hooks")
    quality_hooks = quality_any if isinstance(quality_any, list) else []

    flags_any = profile.get("flags")
    flags = flags_any if isinstance(flags_any, dict) else {}

    check_multi_file = args.check_multi_file_imports or bool(flags.get("check_multi_file", False))
    check_yanesdk = args.check_yanesdk_smoke or bool(flags.get("check_yanesdk_smoke", False))

    fails: list[tuple[str, str]] = []
    ok = 0
    total = 0
    skipped = 0
    expected_checked = 0
    expected_ok = 0

    sample_files = sorted((ROOT / "sample" / "py").glob("*.py"))

    with tempfile.TemporaryDirectory() as tmpdir:
        out = Path(tmpdir) / ("out." + target)

        i = 0
        while i < len(cases):
            rel = cases[i]
            src = ROOT / rel

            if not src.exists():
                fails.append((rel, "source not found"))
                i += 1
                continue

            spec = expected.get(rel)

            if expected_mode != "validate" and spec is not None and not args.include_expected_failures:
                skipped += 1
                i += 1
                continue

            total += 1
            result = _run_one(src=src, out=out, target=target)

            if expected_mode == "validate" and spec is not None:
                expected_checked += 1

                if result.ok:
                    fails.append((rel, "unexpected pass (expected failure)"))
                    i += 1
                    continue

                category = _to_str(spec.get("category"))
                contains = _to_str(spec.get("contains"))
                got = result.category if result.category != "" else "<none>"

                if category != "" and got != category:
                    fails.append((rel, "unexpected error category: expected=" + category + " got=" + got + " msg=" + result.message))
                    i += 1
                    continue

                if contains != "" and contains not in result.raw:
                    fails.append((rel, "unexpected error detail: expected fragment='" + contains + "'"))
                    i += 1
                    continue

                expected_ok += 1
                ok += 1

                if args.verbose:
                    print("OK_EXPECTED_FAIL", rel)

                i += 1
                continue

            if not result.ok:
                fails.append((rel, result.message))
                i += 1
                continue

            rt_err = _validate_runtime_side_files(profile, out)
            if rt_err != "":
                fails.append((rel, rt_err))
                i += 1
                continue

            rt_contains_err = _validate_runtime_side_file_contains(profile, out)
            if rt_contains_err != "":
                fails.append((rel, rt_contains_err))
                i += 1
                continue

            frag_err = _validate_forbid_fragments(profile, out)
            if frag_err != "":
                fails.append((rel, frag_err))
                i += 1
                continue

            q = 0
            quality_error = ""

            while q < len(quality_hooks):
                hook_name = _to_str(quality_hooks[q])
                err = _run_quality_hook(hook_name, rel, out)

                if err != "":
                    quality_error = err
                    break

                q += 1

            if quality_error != "":
                fails.append((rel, quality_error))
                i += 1
                continue

            ok += 1

            if args.verbose:
                print("OK", rel)

            i += 1

        if target == "cpp" and check_yanesdk:
            yanesdk_files = _collect_yanesdk_smoke_files()
            y = 0

            while y < len(yanesdk_files):
                src = yanesdk_files[y]
                rel = str(src.relative_to(ROOT)).replace("\\", "/")
                total += 1
                result = _run_one(src=src, out=out, target=target)

                if result.ok:
                    ok += 1
                    if args.verbose:
                        print("OK", rel, "[yanesdk]")
                else:
                    fails.append((rel + " [yanesdk]", result.message))

                y += 1

        if target == "cpp" and check_multi_file:
            m = 0
            while m < len(sample_files):
                src = sample_files[m]
                rel = str(src.relative_to(ROOT)).replace("\\", "/")

                if _has_import_statement(src):
                    total += 1
                    out_dir = Path(tmpdir) / "multi_out"
                    result = _run_one_multifile(src=src, out_dir=out_dir, target=target)

                    if result.ok:
                        ok += 1
                        if args.verbose:
                            print("OK", rel, "[multi-file]")
                    else:
                        fails.append((rel + " [multi-file]", result.message))

                m += 1

        stage2_any = profile.get("stage2_probe")
        stage2 = stage2_any if isinstance(stage2_any, dict) else {}

        if bool(stage2.get("enabled", False)):
            probe_rel = _to_str(stage2.get("source"))

            if probe_rel == "" and len(cases) > 0:
                probe_rel = cases[0]

            if probe_rel != "":
                total += 1
                expected_fragment = _to_str(stage2.get("expected_fragment"))

                good, msg = _run_stage2_probe(
                    src=ROOT / probe_rel,
                    out=out,
                    target=target,
                    expected_fragment=expected_fragment,
                )

                if good:
                    ok += 1
                    if args.verbose:
                        print("OK", probe_rel, "[stage2 rejected]")
                else:
                    fails.append((probe_rel + " [stage2 rejected]", msg))

    summary = (
        "checked=" + str(total)
        + " ok=" + str(ok)
        + " fail=" + str(len(fails))
        + " skipped=" + str(skipped)
        + " expected_fail_checked=" + str(expected_checked)
        + " expected_fail_ok=" + str(expected_ok)
    )
    print(summary)

    if len(fails) > 0:
        for rel, msg in fails:
            print("FAIL " + rel + ": " + msg)
        return 1

    return 0


if __name__ == "__main__":
    raise SystemExit(main())

from time import perf_counter

# Tokens for lexical analysis.
@dataclass
class Token:
    kind: str
    text: str
    pos: int
    number_value: int


# Expression node. `kind` identifies the concrete variant.
@dataclass
class ExprNode:
    kind: str        # "lit" | "var" | "bin" | "neg"
    value: int       # value for `lit`
    name: str        # name for `var`
    op: str          # operator for `bin`
    left: int        # child node index
    right: int       # child node index
    kind_tag: int    # EXPR_KIND_*
    op_tag: int      # OP_TAG_*


# Statement node. `kind` identifies the concrete variant.
@dataclass
class StmtNode:
    kind: str        # "let" | "assign" | "print"
    name: str        # variable name (unused for `print`)
    expr_index: int  # expression node index
    kind_tag: int    # STMT_KIND_*


def tokenize(lines: list[str]) -> list[Token]:
    single_char_token_tags: dict[str, int] = {
        "+": 1,
        "-": 2,
        "*": 3,
        "/": 4,
        "(": 5,
        ")": 6,
        "=": 7,
    }

    single_char_token_kinds: list[str] = [
        "PLUS",
        "MINUS",
        "STAR",
        "SLASH",
        "LPAREN",
        "RPAREN",
        "EQUAL",
    ]

    tokens: list[Token] = []

    for line_index, source in enumerate(lines):
        i: int = 0
        n: int = len(source)

        while i < n:
            ch: str = source[i]

            if ch == " ":
                i += 1
                continue

            single_tag: int = single_char_token_tags.get(ch, 0)

            if single_tag > 0:
                tokens.append(Token(single_char_token_kinds[single_tag - 1], ch, i, 0))
                i += 1
                continue

            if ch.isdigit():
                start: int = i
                while i < n and source[i].isdigit():
                    i += 1
                text: str = source[start:i]
                tokens.append(Token("NUMBER", text, start, int(text)))
                continue

            if ch.isalpha() or ch == "_":
                start = i
                while i < n and ((source[i].isalpha() or source[i] == "_") or source[i].isdigit()):
                    i += 1
                text = source[start:i]

                if text == "let":
                    tokens.append(Token("LET", text, start, 0))
                elif text == "print":
                    tokens.append(Token("PRINT", text, start, 0))
                else:
                    tokens.append(Token("IDENT", text, start, 0))

                continue

            raise RuntimeError("tokenize error at line=" + str(line_index) + " pos=" + str(i) + " ch=" + ch)

        tokens.append(Token("NEWLINE", "", n, 0))

    tokens.append(Token("EOF", "", len(lines), 0))
    return tokens


class Parser:
    def new_expr_nodes(self) -> list[ExprNode]:
        return []

    def __init__(self, tokens: list[Token]) -> None:
        self.tokens: list[Token] = tokens
        self.pos: int = 0
        self.expr_nodes: list[ExprNode] = self.new_expr_nodes()

    def current_token(self) -> Token:
        return self.tokens[self.pos]

    def previous_token(self) -> Token:
        return self.tokens[self.pos - 1]

    def peek_kind(self) -> str:
        return self.current_token().kind

    def match(self, kind: str) -> bool:
        if self.peek_kind() == kind:
            self.pos += 1
            return True
        return False

    def expect(self, kind: str) -> Token:
        token: Token = self.current_token()
        if token.kind != kind:
            raise RuntimeError("parse error at pos=" + str(token.pos) + ", expected=" + kind + ", got=" + token.kind)
        self.pos += 1
        return token

    def skip_newlines(self) -> None:
        while self.match("NEWLINE"):
            pass

    def add_expr(self, node: ExprNode) -> int:
        self.expr_nodes.append(node)
        return len(self.expr_nodes) - 1

    def parse_program(self) -> list[StmtNode]:
        stmts: list[StmtNode] = []
        self.skip_newlines()

        while self.peek_kind() != "EOF":
            stmt: StmtNode = self.parse_stmt()
            stmts.append(stmt)
            self.skip_newlines()

        return stmts

    def parse_stmt(self) -> StmtNode:
        if self.match("LET"):
            let_name: str = self.expect("IDENT").text
            self.expect("EQUAL")
            let_expr_index: int = self.parse_expr()
            return StmtNode("let", let_name, let_expr_index, 1)

        if self.match("PRINT"):
            print_expr_index: int = self.parse_expr()
            return StmtNode("print", "", print_expr_index, 3)

        assign_name: str = self.expect("IDENT").text
        self.expect("EQUAL")
        assign_expr_index: int = self.parse_expr()
        return StmtNode("assign", assign_name, assign_expr_index, 2)

    def parse_expr(self) -> int:
        return self.parse_add()

    def parse_add(self) -> int:
        left: int = self.parse_mul()

        while True:
            if self.match("PLUS"):
                right: int = self.parse_mul()
                left = self.add_expr(ExprNode("bin", 0, "", "+", left, right, 3, 1))
                continue

            if self.match("MINUS"):
                right = self.parse_mul()
                left = self.add_expr(ExprNode("bin", 0, "", "-", left, right, 3, 2))
                continue

            break

        return left

    def parse_mul(self) -> int:
        left: int = self.parse_unary()

        while True:
            if self.match("STAR"):
                right: int = self.parse_unary()
                left = self.add_expr(ExprNode("bin", 0, "", "*", left, right, 3, 3))
                continue

            if self.match("SLASH"):
                right = self.parse_unary()
                left = self.add_expr(ExprNode("bin", 0, "", "/", left, right, 3, 4))
                continue

            break

        return left

    def parse_unary(self) -> int:
        if self.match("MINUS"):
            child: int = self.parse_unary()
            return self.add_expr(ExprNode("neg", 0, "", "", child, -1, 4, 0))

        return self.parse_primary()

    def parse_primary(self) -> int:
        if self.match("NUMBER"):
            token_num: Token = self.previous_token()
            return self.add_expr(ExprNode("lit", token_num.number_value, "", "", -1, -1, 1, 0))

        if self.match("IDENT"):
            token_ident: Token = self.previous_token()
            return self.add_expr(ExprNode("var", 0, token_ident.text, "", -1, -1, 2, 0))

        if self.match("LPAREN"):
            expr_index: int = self.parse_expr()
            self.expect("RPAREN")
            return expr_index

        t = self.current_token()
        raise RuntimeError("primary parse error at pos=" + str(t.pos) + " got=" + t.kind)


def eval_expr(expr_index: int, expr_nodes: list[ExprNode], env: dict[str, int]) -> int:
    node: ExprNode = expr_nodes[expr_index]

    if node.kind_tag == 1:
        return node.value

    if node.kind_tag == 2:
        if not (node.name in env):
            raise RuntimeError("undefined variable: " + node.name)
        return env[node.name]

    if node.kind_tag == 4:
        return -eval_expr(node.left, expr_nodes, env)

    if node.kind_tag == 3:
        lhs: int = eval_expr(node.left, expr_nodes, env)
        rhs: int = eval_expr(node.right, expr_nodes, env)

        if node.op_tag == 1:
            return lhs + rhs
        if node.op_tag == 2:
            return lhs - rhs
        if node.op_tag == 3:
            return lhs * rhs
        if node.op_tag == 4:
            if rhs == 0:
                raise RuntimeError("division by zero")
            # The mini-language uses integer division.
            return lhs // rhs

        raise RuntimeError("unknown operator: " + node.op)

    raise RuntimeError("unknown node kind: " + node.kind)


def execute(stmts: list[StmtNode], expr_nodes: list[ExprNode], trace: bool) -> int:
    env: dict[str, int] = {}
    checksum: int = 0
    printed: int = 0

    for stmt in stmts:
        if stmt.kind_tag == 1:
            env[stmt.name] = eval_expr(stmt.expr_index, expr_nodes, env)
            continue

        if stmt.kind_tag == 2:
            if not (stmt.name in env):
                raise RuntimeError("assign to undefined variable: " + stmt.name)
            env[stmt.name] = eval_expr(stmt.expr_index, expr_nodes, env)
            continue

        value: int = eval_expr(stmt.expr_index, expr_nodes, env)

        if trace:
            print(value)

        norm: int = value % 1000000007
        if norm < 0:
            norm += 1000000007
        checksum = (checksum * 131 + norm) % 1000000007
        printed += 1

    if trace:
        print("printed:", printed)

    return checksum


def build_benchmark_source(var_count: int, loops: int) -> list[str]:
    lines: list[str] = []

    # Declare initial variables.
    for i in range(var_count):
        lines.append("let v" + str(i) + " = " + str(i + 1))

    # Force evaluation of many arithmetic expressions.
    for i in range(loops):
        x: int = i % var_count
        y: int = (i + 3) % var_count
        c1: int = (i % 7) + 1
        c2: int = (i % 11) + 2

        lines.append(
            "v" + str(x) + " = (v" + str(x) + " * " + str(c1) + " + v" + str(y) + " + 10000) / " + str(c2)
        )

        if i % 97 == 0:
            lines.append("print v" + str(x))

    # Print final values together.
    lines.append("print (v0 + v1 + v2 + v3)")
    return lines


def run_demo() -> None:
    demo_lines: list[str] = []
    demo_lines.append("let a = 10")
    demo_lines.append("let b = 3")
    demo_lines.append("a = (a + b) * 2")
    demo_lines.append("print a")
    demo_lines.append("print a / b")

    tokens: list[Token] = tokenize(demo_lines)
    parser: Parser = Parser(tokens)
    stmts: list[StmtNode] = parser.parse_program()
    checksum: int = execute(stmts, parser.expr_nodes, True)
    print("demo_checksum:", checksum)


def run_benchmark() -> None:
    source_lines: list[str] = build_benchmark_source(32, 120000)

    start: float = perf_counter()
    tokens: list[Token] = tokenize(source_lines)
    parser: Parser = Parser(tokens)
    stmts: list[StmtNode] = parser.parse_program()
    checksum: int = execute(stmts, parser.expr_nodes, False)
    elapsed: float = perf_counter() - start

    print("token_count:", len(tokens))
    print("expr_count:", len(parser.expr_nodes))
    print("stmt_count:", len(stmts))
    print("checksum:", checksum)
    print("elapsed_sec:", elapsed)


def main() -> None:
    run_demo()
    run_benchmark()


if __name__ == "__main__":
    main()

# File model definition for database schema
from datetime import datetime
from typing import Any, Dict, Optional

from sqlalchemy import Column, Integer, String, DateTime, ForeignKey, UUID, JSON
from .base import BaseSchema
from sqlalchemy.orm import relationship

# Association table for many-to-many relationship between files and reports
from app.models.report_file_association import report_file_association


class File(BaseSchema):
    __tablename__ = "files"

    filename = Column(String, index=True)
    path = Column(String, index=True)
    content_type = Column(String, index=True)

    # Raw preview data (no LLM) - stores sheet names, raw cells, text preview, etc.
    preview = Column(JSON, nullable=True)

    user_id = Column(String(36), ForeignKey("users.id"), nullable=False)
    user = relationship("User", back_populates="files")

    organization_id = Column(String(36), ForeignKey("organizations.id"), nullable=False)
    organization = relationship("Organization", back_populates="files")

    reports = relationship(
        "Report",
        secondary=report_file_association,
        back_populates="files"
    )
    file_tags = relationship("FileTag", back_populates="file", lazy="selectin")
    sheet_schemas = relationship("SheetSchema", back_populates="file", lazy="selectin")

    def prompt_schema(self):
        """Legacy method - returns description for backward compatibility."""
        return self.description

    @property
    def description(self) -> str:
        """
        Render file description for LLM/coder context.

        Uses raw preview if available, falls back to legacy schema/tags.
        """
        # Use new preview-based description if preview exists
        if self.preview:
            return self._render_preview_description()

        # Legacy fallback: use sheet_schemas or file_tags
        return self._render_legacy_description()

    def _render_preview_description(self) -> str:
        """Render description from raw preview data."""
        from app.services.file_preview import render_file_description
        return render_file_description(self.preview, self.path)

    def _render_legacy_description(self) -> str:
        """Legacy description using LLM-extracted schema/tags (for backward compat)."""
        if self.content_type == "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet":
            description = f"Excel File: {self.filename}\nPath: {self.path}\n\nSheet Schemas:\n"
            for sheet_schema in self.sheet_schemas:
                description += f"Sheet Name: {sheet_schema.sheet_name}\n"
                description += f"Sheet index: {sheet_schema.sheet_index}\n"
                if sheet_schema.schema:
                    description += f"Schema: {sheet_schema.schema}\n"

        elif self.content_type == "application/vnd.ms-excel":
            description = f"Excel File: {self.filename}\nPath: {self.path}\n\nSheet Schemas:\n"
            for sheet_schema in self.sheet_schemas:
                description += f"Sheet Name: {sheet_schema.sheet_name}\n"
                description += f"Sheet index: {sheet_schema.sheet_index}\n"

        elif self.content_type == "application/pdf":
            description = f"PDF File: {self.filename}\nPath: {self.path}\n\nFile Tags:\n"
            for file_tag in self.file_tags:
                description += f"{file_tag.key}: {file_tag.value}\n"

        elif self.content_type in ["text/csv", "application/csv"]:
            description = f"CSV File: {self.filename}\nPath: {self.path}\n"

        else:
            description = f"File: {self.filename}\nPath: {self.path}\nType: {self.content_type}\n"
            for file_tag in self.file_tags:
                description += f"{file_tag.key}: {file_tag.value}\n"

        return description

