# Tool registry implementation for StatGPT
from collections.abc import MutableMapping
from typing import Annotated, Any, Generic, Literal, TypeVar
from langchain_core.tools import BaseTool, InjectedToolArg
from pydantic import BaseModel, Field
from statgpt.app.schemas import ToolArtifact
from statgpt.common.schemas import BaseToolConfig, ChannelConfig, ToolTypes

class ToolRegistry(MutableMapping):
    def __init__(self) -> None:
        self._mapping: dict[ToolTypes, type[StatGptTool]] = {}

    def __setitem__(self, tool_type: ToolTypes, factory: type['StatGptTool']) -> None:
        # Validate that factory is a subclass of StatGptTool
        if not issubclass(factory, StatGptTool):
            raise ValueError(f"{factory=} must be a subclass of {StatGptTool}")

        # Check for duplicate registration
        if tool_type in self._mapping:
            raise ValueError(
                f"Cant register {factory} factory:"
                f" {tool_type=} already registered with {self._mapping[tool_type]}"
            )

        self._mapping[tool_type] = factory

    def __delitem__(self, tool_type: ToolTypes, /):
        del self._mapping[tool_type]

    def __getitem__(self, key: ToolTypes) -> type['StatGptTool']:
        if key not in self._mapping:
            raise KeyError(
                f"Factory has not been registered for {key} agent."
                f" Please ensure that the factory is imported in the global space."
                f"\nAvailable agents: {list(self._mapping.keys())}"
            )
        return self._mapping[key]

    def __iter__(self):
        return iter(self._mapping)

    def __len__(self):
        return len(self._mapping)

# Global tool registry instance
_TOOL_IMPLEMENTATIONS = ToolRegistry()

class ToolArgs(BaseModel):
    # injected tool argument. set in the code, not by the LLM.
    # LLM can't set this field because it's not added to the tool schema shown to LLM.
    # `inputs` is used to pass execution context from Supreme Agent to the tool.
    inputs: Annotated[dict, InjectedToolArg] = Field()

ToolConfigType = TypeVar('ToolConfigType', bound=BaseToolConfig)

class StatGptTool(BaseTool, ABC, Generic[ToolConfigType]):
    response_format: Literal['content', 'content_and_artifact'] = "content_and_artifact"
    tool_type: ToolTypes  # Set dynamically in __init_subclass__

    def __init_subclass__(cls, **kwargs):
        tool_type = kwargs.pop('tool_type', None)
        super().__init_subclass__(**kwargs)

        # Skip registration for the base class itself
        if StatGptTool in cls.__bases__:
            return

        # Validate tool_type specification
        if tool_type is None:
            raise ValueError(f"Subclass {cls.__name__} must specify a 'tool_type' parameter")

        if not isinstance(tool_type, ToolTypes):
            raise ValueError(f"{tool_type=} must be an instance of {ToolTypes}")

        # Register the tool implementation
        cls.tool_type = tool_type
        _TOOL_IMPLEMENTATIONS[tool_type] = cls

    def __init__(self, tool_config: ToolConfigType, channel_config: ChannelConfig, **kwargs):
        super().__init__(**kwargs)
        self._tool_config = tool_config
        self._channel_config = channel_config

    @property
    def stage_name(self) -> str:
        """Return the stage name of calling this tool."""
        if name := self._tool_config.details.stages_config.tool_call_name:
            return name
        tool_name = self.name.replace('_', ' ')
        return f"Calling {tool_name} tool"

    @property
    def result_stage_name(self) -> str:
        """Return the stage name of showing the result of this tool."""
        if name := self._tool_config.details.stages_config.tool_result_name:
            return name
        tool_name = self.name.replace('_', ' ')
        return f"Result from {tool_name} tool"

    def _run(self, *args: Any, **kwargs: Any) -> Any:
        """This method is implemented to satisfy the BaseTool interface.
        But it raises an error since we don't want to use it."""
        raise NotImplementedError("This method should not be called. Use async version instead.")

    @abstractmethod
    async def _arun(self, *args: Any, **kwargs: Any) -> tuple[str, ToolArtifact]:
        pass

    @classmethod
    def get_args_schema(cls, tool_config: ToolConfigType) -> type[ToolArgs]:
        """Return the schema for the arguments that this tool accepts."""
        return ToolArgs

    @staticmethod
    def from_config(tool_config: ToolConfigType, channel_config: ChannelConfig) -> 'StatGptTool':
        cls = _TOOL_IMPLEMENTATIONS[tool_config.type]
        return cls(
            tool_config=tool_config,
            channel_config=channel_config,
            name=tool_config.name,
            description=tool_config.description,
            args_schema=cls.get_args_schema(tool_config),
        )

# Workspace management endpoints for uploading and downloading the working directory as zip archives
from __future__ import annotations

import io
import shutil
import tempfile
import zipfile
from datetime import datetime, timezone
from pathlib import Path

from fastapi import APIRouter, HTTPException, UploadFile, File
from fastapi.responses import StreamingResponse

from ...constant import WORKING_DIR

router = APIRouter(prefix="/workspace", tags=["workspace"])


def _dir_stats(root: Path) -> tuple[int, int]:
    """Return (file_count, total_size) for *root* recursively."""
    count = 0
    size = 0
    if root.is_dir():
        for p in root.rglob("*"):
            if p.is_file():
                count += 1
                size += p.stat().st_size
    return count, size


def _zip_directory(root: Path) -> io.BytesIO:
    """Create an in-memory zip archive of *root* and return the buffer.
    All files **and** directories (including empty ones) are included.
    """
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as zf:
        for entry in sorted(root.rglob("*")):
            arcname = entry.relative_to(root).as_posix()
            if entry.is_file():
                zf.write(entry, arcname)
            elif entry.is_dir():
                # Zip spec: directory entries end with '/'
                zf.write(entry, arcname + "/")
    buf.seek(0)
    return buf


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------
def _validate_zip_data(data: bytes) -> None:
    """Ensure *data* is a valid zip without path-traversal entries."""
    if not zipfile.is_zipfile(io.BytesIO(data)):
        raise HTTPException(
            status_code=400,
            detail="Uploaded file is not a valid zip archive",
        )
    with zipfile.ZipFile(io.BytesIO(data)) as zf:
        for name in zf.namelist():
            resolved = (WORKING_DIR / name).resolve()
            if not str(resolved).startswith(str(WORKING_DIR)):
                raise HTTPException(
                    status_code=400,
                    detail=f"Zip contains unsafe path: {name}",
                )


# ---------------------------------------------------------------------------
# Endpoints
# ---------------------------------------------------------------------------
@router.get(
    "/download",
    summary="Download workspace as zip",
    description=(
        "Package the entire WORKING_DIR into a zip archive and stream it "
        "back as a downloadable file."
    ),
    responses={
        200: {
            "content": {"application/zip": {}},
            "description": "Zip archive of WORKING_DIR",
        },
    },
)
async def download_workspace():
    """Stream WORKING_DIR as a zip file."""
    if not WORKING_DIR.is_dir():
        raise HTTPException(
            status_code=404,
            detail=f"WORKING_DIR does not exist: {WORKING_DIR}",
        )

    buf = _zip_directory(WORKING_DIR)
    timestamp = datetime.now(timezone.utc).strftime("%Y%m%d_%H%M%S")
    filename = f"copaw_workspace_{timestamp}.zip"

    return StreamingResponse(
        buf,
        media_type="application/zip",
        headers={
            "Content-Disposition": f'attachment; filename="{filename}"',
        },
    )


@router.post(
    "/upload",
    response_model=dict,
    summary="Upload zip and merge into workspace",
    description=(
        "Upload a zip archive.  Paths present in the zip are merged into "
        "WORKING_DIR (files overwritten, dirs merged).  Paths not in the zip "
        "are left unchanged (e.g. copaw.db, runtime dirs).  Download packs "
        "the entire WORKING_DIR; upload only overwrites/merges zip contents."
    ),
)
async def upload_workspace(  # pylint: disable=too-many-branches
    file: UploadFile = File(
        ...,
        description="Zip archive to merge into WORKING_DIR",
    ),
) -> dict:
    """
    Merge uploaded zip contents into WORKING_DIR (overwrite, do not clear).
    """
    # --- validate uploaded file ---
    if file.content_type and file.content_type not in (
        "application/zip",
        "application/x-zip-compressed",
        "application/octet-stream",
    ):
        raise HTTPException(
            status_code=400,
            detail=(
                f"Expected a zip file, got content-type: {file.content_type}"
            ),
        )

    data = await file.read()
    _validate_zip_data(data)

    tmp_dir = None
    try:
        tmp_dir = Path(tempfile.mkdtemp(prefix="copaw_upload_"))

        with zipfile.ZipFile(io.BytesIO(data)) as zf:
            zf.extractall(tmp_dir)

        # If the zip contains a single top-level directory, use its contents
        top_entries = list(tmp_dir.iterdir())
        extract_root = tmp_dir

        if len(top_entries) == 1 and top_entries[0].is_dir():
            extract_root = top_entries[0]

        WORKING_DIR.mkdir(parents=True, exist_ok=True)

        # Merge: overwrite paths present in zip; leave others untouched
        for item in extract_root.iterdir():
            dest = WORKING_DIR / item.name

            if item.is_file():
                shutil.copy2(item, dest)
            else:
                if dest.exists() and dest.is_file():
                    dest.unlink()
                shutil.copytree(item, dest, dirs_exist_ok=True)

        return {
            "success": True,
        }
    except HTTPException:
        raise
    except Exception as exc:
        raise HTTPException(
            status_code=500,
            detail=f"Failed to merge workspace: {exc}",
        ) from exc
    finally:
        if tmp_dir and tmp_dir.is_dir():
            shutil.rmtree(tmp_dir, ignore_errors=True)

# Type transformer and operator implementations for workflow engine

import re
from abc import ABC
from typing import Union, Type, NoReturn, Any
from app.core.workflow.engine.variable_pool import VariablePool
from app.core.workflow.nodes.enums import ValueInputType
from app.core.workflow.variable.base_variable import VariableType


class TypeTransformer:
    @classmethod
    def _fail(cls, value, target) -> NoReturn:
        raise TypeError(f"Cannot convert {value!r} to {target} type")

    @classmethod
    def _json_load(cls, value, target):
        try:
            return json.loads(value)
        except Exception:
            cls._fail(value, target)

    @classmethod
    def transform(cls, variable_literal: str | bool, target_type: VariableType):
        match target_type:
            case VariableType.STRING:
                return str(variable_literal)
            case VariableType.NUMBER:
                for caster in (int, float):
                    try:
                        return caster(variable_literal)
                    except Exception:
                        pass
                cls._fail(variable_literal, target_type)
            case VariableType.BOOLEAN:
                if isinstance(variable_literal, bool):
                    return variable_literal
                cls._fail(variable_literal, target_type)
            case VariableType.OBJECT:
                obj = cls._json_load(variable_literal, target_type)
                if isinstance(obj, dict):
                    return obj
                cls._fail(variable_literal, target_type)
            case VariableType.ARRAY_BOOLEAN:
                return cls._parse_list(variable_literal, bool, target_type)
            case VariableType.ARRAY_NUMBER:
                return cls._parse_list(variable_literal, (int, float), target_type)
            case VariableType.ARRAY_STRING:
                return cls._parse_list(variable_literal, str, target_type)
            case VariableType.ARRAY_OBJECT:
                return cls._parse_list(variable_literal, dict, target_type)
            case _:
                raise TypeError("Invalid type")

    @classmethod
    def _parse_list(cls, value, item_type, target):
        arr = cls._json_load(value, target)
        if isinstance(arr, list) and all(isinstance(i, item_type) for i in arr):
            return arr
        cls._fail(value, target)


class OperatorBase(ABC):
    def __init__(self, pool: VariablePool, left_selector: str, right: Any):
        self.pool = pool
        self.left_selector = left_selector
        self.right = right
        self.type_limit: type[str, int, dict, list] = None

    def check(self, no_right=False):
        left = self.pool.get_value(self.left_selector)
        if not isinstance(left, self.type_limit):
            raise TypeError(f"The variable to be operated on must be of {self.type_limit} type")
        if not no_right and not isinstance(self.right, self.type_limit):
            raise TypeError(
                f"The value assigned must be of {self.type_limit} type"
            )


class StringOperator(OperatorBase):
    def __init__(self, pool: VariablePool, left_selector, right):
        super().__init__(pool, left_selector, right)
        self.type_limit = str

    async def assign(self) -> None:
        self.check()
        await self.pool.set(self.left_selector, self.right)

    async def clear(self) -> None:
        self.check(no_right=True)
        await self.pool.set(self.left_selector, '')


class NumberOperator(OperatorBase):
    def __init__(self, pool: VariablePool, left_selector, right):
        super().__init__(pool, left_selector, right)
        self.type_limit = (float, int)

    async def assign(self) -> None:
        self.check()
        await self.pool.set(self.left_selector, self.right)

    async def clear(self) -> None:
        self.check(no_right=True)
        await self.pool.set(self.left_selector, 0)

    async def add(self) -> None:
        self.check()
        origin = self.pool.get_value(self.left_selector)
        await self.pool.set(self.left_selector, origin + self.right)

    async def subtract(self) -> None:
        self.check()
        origin = self.pool.get_value(self.left_selector)
        await self.pool.set(self.left_selector, origin - self.right)

    async def multiply(self) -> None:
        self.check()
        origin = self.pool.get_value(self.left_selector)
        await self.pool.set(self.left_selector, origin * self.right)

    async def divide(self) -> None:
        self.check()
        origin = self.pool.get_value(self.left_selector)
        await self.pool.set(self.left_selector, origin / self.right)


class BooleanOperator(OperatorBase):
    def __init__(self, pool: VariablePool, left_selector, right):
        super().__init__(pool, left_selector, right)
        self.type_limit = bool

    async def assign(self) -> None:
        self.check()
        await self.pool.set(self.left_selector, self.right)

    async def clear(self) -> None:
        self.check(no_right=True)
        await self.pool.set(self.left_selector, False)


class ArrayOperator(OperatorBase):
    def __init__(self, pool: VariablePool, left_selector, right):
        super().__init__(pool, left_selector, right)
        self.type_limit = list

    async def assign(self) -> None:
        self.check()
        await self.pool.set(self.left_selector, self.right)

    async def clear(self) -> None:
        self.check(no_right=True)
        await self.pool.set(self.left_selector, list())

    async def append(self) -> None:
        self.check(no_right=True)
        origin = self.pool.get_value(self.left_selector)
        origin.append(self.right)
        await self.pool.set(self.left_selector, origin)

    async def extend(self) -> None:
        self.check(no_right=True)
        origin = self.pool.get_value(self.left_selector)
        origin.extend(self.right)
        await self.pool.set(self.left_selector, origin)

    async def remove_last(self) -> None:
        self.check(no_right=True)
        origin = self.pool.get_value(self.left_selector)
        origin.pop()
        await self.pool.set(self.left_selector, origin)

    async def remove_first(self) -> None:
        self.check(no_right=True)
        origin = self.pool.get_value(self.left_selector)
        origin.pop(0)
        await self.pool.set(self.left_selector, origin)


class ObjectOperator(OperatorBase):
    def __init__(self, pool: VariablePool, left_selector, right):
        super().__init__(pool, left_selector, right)
        self.type_limit = dict

    async def assign(self) -> None:
        self.check()
        await self.pool.set(self.left_selector, self.right)

    async def clear(self) -> None:
        self.check(no_right=True)
        await self.pool.set(self.left_selector, dict())


class AssignmentOperatorResolver:
    OPERATOR_MAP = {
        str: StringOperator,
        bool: BooleanOperator,
        int: NumberOperator,
        float: NumberOperator,
        list: ArrayOperator,
        dict: ObjectOperator,
    }

    @classmethod
    def resolve_by_value(cls, value):
        for t, op in cls.OPERATOR_MAP.items():
            if isinstance(value, t):
                return op
        raise TypeError(f"Unsupported variable type: {type(value)}")


AssignmentOperatorInstance = Union[
    StringOperator,
    NumberOperator,
    BooleanOperator,
    ArrayOperator,
    ObjectOperator
]
AssignmentOperatorType = Type[AssignmentOperatorInstance]


class ConditionBase(ABC):
    type_limit: type[str, int, dict, list] = None

    def __init__(
            self,
            pool: VariablePool,
            left_selector,
            right_selector: str,
            input_type: ValueInputType
    ):
        self.pool = pool
        self.left_selector = left_selector
        self.right_selector = right_selector
        self.input_type = input_type
        self.left_value = self.pool.get_value(self.left_selector)
        self.right_value = self.resolve_right_literal_value()
        self.type_limit = getattr(self, "type_limit", None)

    def resolve_right_literal_value(self):
        if self.input_type == ValueInputType.VARIABLE:
            pattern = r"\{\{\s*(.*?)\s*\}\}"
            right_expression = re.sub(pattern, r"\1", self.right_selector).strip()
            return self.pool.get_value(right_expression)
        elif self.input_type == ValueInputType.CONSTANT:
            return self.right_selector
        raise RuntimeError("Unsupported variable type")

    def check(self, no_right=False):
        if not isinstance(self.left_value, self.type_limit):
            raise TypeError(f"The variable to be compared on must be of {self.type_limit} type")
        if not no_right:
            right = self.resolve_right_literal_value()
            if not isinstance(right, self.type_limit):
                raise TypeError(
                    f"The compared variable must be of {self.type_limit} type"
                )


class StringComparisonOperator(ConditionBase):
    type_limit = str

    def __init__(self, pool: VariablePool, left_selector, right_selector, input_type):
        super().__init__(pool, left_selector, right_selector, input_type)

    def empty(self):
        self.check(no_right=True)
        return self.left_value == ""

    def not_empty(self):
        return not self.empty()

    def contains(self):
        self.check()
        return self.right_value in self.left_value

    def not_contains(self):
        return self.right_value not in self.left_value

    def startswith(self):
        self.check()
        return self.left_value.startswith(self.right_value)

    def endswith(self):
        return self.left_value.endswith(self.right_value)

    def eq(self):
        return self.left_value == self.right_value

    def ne(self):
        return self.left_value != self.right_value


class NumberComparisonOperator(ConditionBase):
    type_limit = (int, float)

    def __init__(self, pool: VariablePool, left_selector, right_selector, input_type):
        super().__init__(pool, left_selector, right_selector, input_type)

    def empty(self):
        return self.left_value == 0

    def not_empty(self):
        return self.left_value != 0

    def eq(self):
        return self.left_value == self.right_value

    def ne(self):
        return self.left_value != self.right_value

    def lt(self):
        return self.left_value < self.right_value

    def le(self):
        return self.left_value <= self.right_value

    def gt(self):
        return self.left_value > self.right_value

    def ge(self):
        return self.left_value >= self.right_value


class BooleanComparisonOperator(ConditionBase):
    type_limit = bool

    def __init__(self, pool: VariablePool, left_selector, right_selector, input_type):
        super().__init__(pool, left_selector, right_selector, input_type)

    def eq(self):
        return self.left_value == self.right_value

    def ne(self):
        return self.left_value != self.right_value


class ObjectComparisonOperator(ConditionBase):
    type_limit = dict

    def __init__(self, pool: VariablePool, left_selector, right_selector, input_type):
        super().__init__(pool, left_selector, right_selector, input_type)

    def eq(self):
        return self.left_value == self.right_value

    def ne(self):
        return self.left_value != self.right_value

    def empty(self):
        return not self.left_value

    def not_empty(self):
        return bool(self.left_value)


class ArrayComparisonOperator(ConditionBase):
    type_limit = list

    def __init__(self, pool: VariablePool, left_selector, right_selector, input_type):
        super().__init__(pool, left_selector, right_selector, input_type)

    def empty(self):
        return not self.left_value

    def not_empty(self):
        return bool(self.left_value)

    def contains(self):
        return self.right_value in self.left_value

    def not_contains(self):
        return self.right_value not in self.left_value


class NoneObjectComparisonOperator:
    def __init__(self, *arg, **kwargs):
        pass

    def __getattr__(self, name):
        return lambda *args, **kwargs: False


CompareOperatorInstance = Union[
    StringComparisonOperator,
    NumberComparisonOperator,
    BooleanComparisonOperator,
    ArrayComparisonOperator,
    ObjectComparisonOperator
]
CompareOperatorType = Type[CompareOperatorInstance]


class ConditionExpressionResolver:
    CONDITION_OPERATOR_MAP = {
        str: StringComparisonOperator,
        bool: BooleanComparisonOperator,
        int: NumberComparisonOperator,
        float: NumberComparisonOperator,
        list: ArrayComparisonOperator,
        dict: ObjectComparisonOperator,
        type(None): NoneObjectComparisonOperator
    }

    @classmethod
    def resolve_by_value(cls, value) -> CompareOperatorType:
        for t, op in cls.CONDITION_OPERATOR_MAP.items():
            if isinstance(value, t):
                return op
        raise TypeError(f"Unsupported variable type: {type(value)}")

# Import necessary modules
from typing import Callable, Generic
from uuid import UUID
from celery import Task
from celery.utils.log import get_task_logger
from common.celery_app import BaseTask
from common.dependencies import get_celery_app, get_root_task_information_repository
from common.models.base_repository import REPOSITORY_INSTANCES, BaseRepository
from common.task_object.task_object import (
    RepositoryTaskObjectT,
    SecondaryRepositoryTaskObjectT,
)
from worker.settings import settings
from worker.utils.persister_base import PersistingException
from worker.utils.task_info_persister import TaskInfoPersister

# Constants and logger setup
PERSIST_MAX_RETRIES = 15
logger = get_task_logger(__name__)
app = get_celery_app()


class ProcessingTask(
    BaseTask, ABC, Generic[RepositoryTaskObjectT, SecondaryRepositoryTaskObjectT]
):
    """
    A base task for all processing tasks.
    It keeps track of the status of task and subtask.
    """

    # pylint does not consider metaclass:
    # https://stackoverflow.com/questions/22186843/pylint-w0223-method-is-abstract-in-class-but-is-not-overridden
    # pylint: disable=abstract-method

    @property
    @abstractmethod
    def _repository(
        self,
    ) -> (
        BaseRepository[RepositoryTaskObjectT]
        | BaseRepository[SecondaryRepositoryTaskObjectT]
    ):
        pass

    @staticmethod
    def _persist_fail(task_id: UUID, task_info_persister: TaskInfoPersister):
        task_info_persister.update_state("failed")
        task_info_persister.add_failed_task(task_id)

    @staticmethod
    def _persist_retry(task_id: UUID, task_info_persister: TaskInfoPersister):
        task_info_persister.add_retried_task(task_id)

    @staticmethod
    def _persist_success(task_id: UUID, task_info_persister: TaskInfoPersister):
        task_info_persister.add_success_task(task_id)

    def on_failure(
        self, exc, task_id, args, kwargs, einfo
    ):  # pylint: disable=too-many-arguments, too-many-positional-arguments
        _persist_task_status_task.delay(
            type(self._repository), UUID(task_id), ProcessingTask._persist_fail
        ).forget()
        return super().on_failure(exc, task_id, args, kwargs, einfo)

    def on_retry(
        self, exc, task_id, args, kwargs, einfo
    ):  # pylint: disable=too-many-arguments, too-many-positional-arguments
        if settings.persist_retry_tasks:
            _persist_task_status_task.delay(
                type(self._repository), UUID(task_id), ProcessingTask._persist_retry
            ).forget()
        return super().on_retry(exc, task_id, args, kwargs, einfo)

    def on_success(self, retval, task_id, args, kwargs):
        if settings.persist_success_tasks:
            _persist_task_status_task.delay(
                type(self._repository), UUID(task_id), ProcessingTask._persist_success
            ).forget()
        return super().on_success(retval, task_id, args, kwargs)


@app.task(
    bind=True,
    autoretry_for=tuple([PersistingException]),
    max_retries=PERSIST_MAX_RETRIES,
    retry_backoff=True,
)
def _persist_task_status_task(
    task: Task,
    repository_type: type[BaseRepository],
    task_id: UUID,
    persist_callback: Callable[[UUID, TaskInfoPersister], None],
):
    object_id = _get_object_id_from_task(task)

    class RepoBoundTaskInfoPersister(TaskInfoPersister[RepositoryTaskObjectT]):
        @classmethod
        def get_repository(cls) -> BaseRepository[RepositoryTaskObjectT]:
            repository = REPOSITORY_INSTANCES.get(repository_type)
            assert repository is not None
            return repository

    with RepoBoundTaskInfoPersister(object_id) as persister:
        persist_callback(task_id, persister)


def _get_object_id_from_task(task: Task) -> UUID:
    root_task_id = UUID(task.request.root_id)
    repository = get_root_task_information_repository()
    root_task_information = repository.get_by_root_task_id(root_task_id)
    return root_task_information.object_id

from typing import Any, Optional
import logging
import sys
import time

# --- OS-Specific Imports with error handling ---
if sys.platform == 'win32':
    try:
        import win32gui
        import win32con
        import win32process
        import ctypes
    except ImportError:
        print("Please run 'pip install pywin32' for Windows-specific functionality.")
        sys.exit(1)

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
offscreen_position = [0, 3000]

# --- OS-Specific Helper Code ---
def is_admin() -> bool:
    """Checks for Administrator privileges on Windows."""
    if sys.platform == 'win32':
        try:
            return ctypes.windll.shell32.IsUserAnAdmin() != 0
        except Exception:
            return False
    return False


def _find_hwnd_for_pid(target_pid: int) -> Optional[int]:
    """Iterate through windows to find the one matching the target PID."""
    found_hwnd = None

    def callback(hwnd, _):
        nonlocal found_hwnd
        # Skip invisible windows and child windows
        if not win32gui.IsWindowVisible(hwnd) or win32gui.GetParent(hwnd) != 0:
            return True

        _, process_id = win32process.GetWindowThreadProcessId(hwnd)
        if process_id == target_pid:
            found_hwnd = hwnd
            return False
        return True

    win32gui.EnumWindows(callback, None)
    return found_hwnd


class ManageWindowVisibilityByPID:
    """
    Context manager to robustly manage a window's visibility for GUI automation using its PID.
    """
    def __init__(self, pid: int):
        if sys.platform != 'win32':
            # this is not an error, just an informational message
            logging.info("Window visibility management is only implemented for Windows.")

        self.pid = pid
        self.hwnd = None
        self.original_placement = None

    def __enter__(self):
        if sys.platform != 'win32':
            return self  # do nothing on non-windows systems

        logging.info(f"Attempting to manage visibility for window with PID: {self.pid}")
        self.hwnd = _find_hwnd_for_pid(self.pid)

        if not self.hwnd:
            logging.warning(f"Could not find window for PID {self.pid}. Cannot manage visibility.")
            return self

        logging.info(f"Found window handle (HWND): {self.hwnd}.")

        try:
            self.original_placement = win32gui.GetWindowPlacement(self.hwnd)

            logging.info("Temporarily moving window on-screen to (0,0) for interaction.")
            win32gui.SetWindowPlacement(
                self.hwnd, 
                (0, 1, (-1, -1), (-1, -1), (0, 0, 800, 600))
            )
            win32gui.SetForegroundWindow(self.hwnd)
            time.sleep(0.4)
        except win32gui.error as e:
            logging.error(f"Error managing window: {e}. It might have been closed.")
            self.hwnd = None

        return self

    def __exit__(self, exc_type, exc_value, exc_tb):
        if sys.platform != 'win32':
            return  # do nothing on non-windows systems

        if self.hwnd and self.original_placement:
            logging.info("Restoring window to its original position...")
            try:
                move_offscreen(self.pid)
            except win32gui.error:
                logging.warning(f"Could not restore window position for HWND {self.hwnd}, it may no longer exist.")


def move_offscreen(pid: int):
    """Moves the browser window off-screen using its PID (Windows-only)."""
    if sys.platform == 'win32':
        hwnd = _find_hwnd_for_pid(pid)
        if hwnd:
            logging.info(f"Found window handle (HWND): {hwnd}. Moving it off-screen.")
            win32gui.ShowWindow(hwnd, win32con.SW_RESTORE)
            win32gui.SetWindowPos(
                hwnd, 
                0, 
                offscreen_position[0], 
                offscreen_position[1], 
                0, 
                0,
                win32con.SWP_NOSIZE | win32con.SWP_NOZORDER | win32con.SWP_NOOWNERZORDER
            )
        else:
            logging.warning(f"Could not find window handle for PID {pid}. Window will not be moved.")
    else:
        logging.info("Off-screen window positioning is currently only implemented for Windows.")

