    pin = porttableentry['pin']
    pin = Pin(pin, Pin.OUT)
    if value > 0.5:
        pin.on()
    else:
        pin.off()

def setDigital(port, value, push=False):
    if port in DigitalPortTable and 'func' in DigitalPortTable[port]:
