                },
            ],
        }
        lines = _capture_annotations(result)
        assert "::warning" in lines[0]
        assert "::notice" in lines[1]

    def test_dead_code_annotations(self):
        result = {
            "unused_functions": [
                {"name": "old_func", "file": "app.py", "line": 42},
            ],
            "unused_imports": [
                {"name": "os", "file": "app.py", "line": 1},
            ],
        }
        lines = _capture_annotations(result)
        assert len(lines) == 2
        assert "::warning" in lines[0]
        assert "Unused function: old_func" in lines[0]
        assert "Unused import: os" in lines[1]

    def test_empty_result(self):
        result = {}
        lines = _capture_annotations(result)
        assert lines == [""] or lines == []

    def test_mixed_categories(self):
        result = {
            "danger": [
                {
                    "rule_id": "SKY-D201",
                    "severity": "CRITICAL",
                    "file": "x.py",
                    "line": 1,
                    "message": "eval",
                },
            ],
            "secrets": [
                {
                    "rule_id": "SKY-S101",
                    "severity": "HIGH",
                    "file": "y.py",
                    "line": 2,
                    "message": "API key",
                },
            ],
            "unused_classes": [
                {"name": "OldClass", "file": "z.py", "line": 3},
            ],
        }
        lines = _capture_annotations(result)
        assert len(lines) == 3
        # CRITICAL maps to error
        assert lines[0].startswith("::error")
        assert lines[1].startswith("::error")  # HIGH -> error
        assert "Unused class: OldClass" in lines[2]

import torch
from vllm.distributed import get_pcp_group
from vllm_ascend.platform import ModelConfig
from vllm_ascend.utils import singleton


def _generate_attn_mask(max_seq_len, dtype):
    # Construct lower triangle matrix.
    mask_flag = torch.ones((max_seq_len, max_seq_len), dtype=torch.bool).tril_()

    # Create upper triangle matrix used to mark mask positions.
    mask_flag = ~mask_flag

    # Currently for fp16 dtype, the mask value should be set to -inf.
    # TODO: Eliminate this part in the future.
    mask_value = float("-inf") if dtype == torch.float16 else 1

    attn_mask = torch.zeros(size=(max_seq_len, max_seq_len), dtype=dtype).masked_fill_(mask_flag, mask_value)
    return attn_mask


@singleton
class AttentionMaskBuilder:
    def __init__(self, device: torch.device):
        self.attn_mask_cache = None
        self._seq_len_cached = 0
        self.device = device

        self.mla_mask = None
        self.chunked_prefill_attn_mask = None
        self.pcp_mla_mask = None
        self.swa_mask = None

    def get_attn_mask(self, max_seq_len: int, dtype: torch.dtype):
        if self.attn_mask_cache is None or max_seq_len > self._seq_len_cached:
            self.attn_mask_cache = _generate_attn_mask(max_seq_len, dtype)
            self._seq_len_cached = max_seq_len

        assert self.attn_mask_cache is not None, "Something is wrong in generate_attn_mask."

        if self.attn_mask_cache.dtype != dtype:
            self.attn_mask_cache = self.attn_mask_cache.to(dtype)

        return self.attn_mask_cache[:max_seq_len, :max_seq_len].contiguous().to(self.device, non_blocking=True)

    def get_splitfuse_attn_mask(self) -> torch.Tensor:
        if self.chunked_prefill_attn_mask is None:
            self.chunked_prefill_attn_mask = (
                torch.triu(torch.ones(2048, 2048), diagonal=1).to(torch.int8).to(self.device)
            )
        return self.chunked_prefill_attn_mask

    def get_mla_mask(self, dtype: torch.dtype) -> torch.Tensor:
        if self.mla_mask is None or self.mla_mask.dtype != dtype:
            if dtype == torch.float16:
                mask_value = torch.finfo(torch.float32).min
            else:
                mask_value = 1

            prefill_mask = torch.triu(torch.ones(512, 512, device=self.device, dtype=dtype), 1)
            self.mla_mask = torch.where(prefill_mask == 1, mask_value, 0).to(dtype)

        return self.mla_mask

    def get_pcp_mla_mask(self, dtype: torch.dtype):
        if self.pcp_mla_mask is None or self.pcp_mla_mask.dtype != dtype:
            self.pcp_mla_mask = torch.triu(torch.ones(512, 512, device=self.device, dtype=dtype), 1)
        return self.pcp_mla_mask

    def get_swa_mask(self, dtype: torch.dtype, sliding_window):
        if self.swa_mask is None or self.swa_mask.dtype != dtype:
            if sliding_window is not None:
                mask = torch.ones(2048, 2048, dtype=torch.bool)
                triu_mask = torch.triu(mask, diagonal=1).to(self.device)
                tril_mask = torch.tril(mask, -sliding_window).to(self.device)
                self.swa_mask = triu_mask + tril_mask
        return self.swa_mask

    def get_attention_mask(self, model_config: ModelConfig):
        if model_config.runner_type == "pooling":
            return self.get_attn_mask(2048, torch.bool)
        return self.get_splitfuse_attn_mask()

    def get_final_mla_mask(self, model_config: ModelConfig):
        if get_pcp_group().world_size > 1:
            return self.get_pcp_mla_mask(model_config.dtype)
        # Prefill stages use 512x512 mask with appropriate dtype
        return self.get_mla_mask(model_config.dtype)

# Provides a global threading.Event that any tool can check to determine
# if the user has requested an interrupt. The agent's interrupt() method
# sets this event, and tools poll it during long-running operations.
# Usage in tools:
#     from tools.interrupt import is_interrupted
#     if is_interrupted():
#         return {"output": "[interrupted]", "returncode": 130}

import threading

# Global interrupt event
_interrupt_event = threading.Event()


def set_interrupt(active: bool) -> None:
    """Called by the agent to signal or clear the interrupt."""
    if active:
        _interrupt_event.set()
    else:
        _interrupt_event.clear()


def is_interrupted() -> bool:
    """Check if an interrupt has been requested. Safe to call from any thread."""
    return _interrupt_event.is_set()

# IDNA (Internationalizing Domain Names in Applications) implementation
import bisect
import unicodedata
import re
from typing import Union, Optional

from .intranges import intranges_contain

_virama_combining_class = 9
_alabel_prefix = b'xn--'
_unicode_dots_re = re.compile('[\u002e\u3002\uff0e\uff61]')

class IDNAError(UnicodeError):
    """ Base exception for all IDNA-encoding related problems """
    pass

class IDNABidiError(IDNAError):
    """ Exception when bidirectional requirements are not satisfied """
    pass

class InvalidCodepoint(IDNAError):
    """ Exception when a disallowed or unallocated codepoint is used """
    pass

class InvalidCodepointContext(IDNAError):
    """ Exception when the codepoint is not valid in the context it is used """
    pass

def _combining_class(cp: int) -> int:
    v = unicodedata.combining(chr(cp))
    if v == 0:
        if not unicodedata.name(chr(cp)):
            raise ValueError('Unknown character in unicodedata')
    return v

def _is_script(cp: str, script: str) -> bool:
    return intranges_contain(ord(cp), idnadata.scripts[script])

def _punycode(s: str) -> bytes:
    return s.encode('punycode')

def _unot(s: int) -> str:
    return 'U+{:04X}'.format(s)

def valid_label_length(label: Union[bytes, str]) -> bool:
    if len(label) > 63:
        return False
    return True

def valid_string_length(label: Union[bytes, str], trailing_dot: bool) -> bool:
    if len(label) > (254 if trailing_dot else 253):
        return False
    return True

def check_bidi(label: str, check_ltr: bool = False) -> bool:
    # Bidi rules should only be applied if string contains RTL characters
    bidi_label = False
    for (idx, cp) in enumerate(label, 1):
        direction = unicodedata.bidirectional(cp)
        if direction == '':
            # String likely comes from a newer version of Unicode
            raise IDNABidiError('Unknown directionality in label {} at position {}'.format(repr(label), idx))
        if direction in ['R', 'AL', 'AN']:
            bidi_label = True
    if not bidi_label and not check_ltr:
        return True

    # Bidi rule 1
    direction = unicodedata.bidirectional(label[0])
    if direction in ['R', 'AL']:
        rtl = True
    elif direction == 'L':
        rtl = False
    else:
        raise IDNABidiError('First codepoint in label {} must be directionality L, R or AL'.format(repr(label)))

    valid_ending = False
    number_type = None  # type: Optional[str]

    for (idx, cp) in enumerate(label, 1):
        direction = unicodedata.bidirectional(cp)
        if rtl:
            # Bidi rule 2
            if not direction in ['R', 'AL', 'AN', 'EN', 'ES', 'CS', 'ET', 'ON', 'BN', 'NSM']:
                raise IDNABidiError('Invalid direction for codepoint at position {} in a right-to-left label'.format(idx))
            # Bidi rule 3
            if direction in ['R', 'AL', 'EN', 'AN']:
                valid_ending = True
            elif direction != 'NSM':
                valid_ending = False
            # Bidi rule 4
            if direction in ['AN', 'EN']:
                if not number_type:
                    number_type = direction
                else:
                    if number_type != direction:
                        raise IDNABidiError('Can not mix numeral types in a right-to-left label')
        else:
            # Bidi rule 5
            if not direction in ['L', 'EN', 'ES', 'CS', 'ET', 'ON', 'BN', 'NSM']:
                raise IDNABidiError('Invalid direction for codepoint at position {} in a left-to-right label'.format(idx))
            # Bidi rule 6
            if direction in ['L', 'EN']:
                valid_ending = True
            elif direction != 'NSM':
                valid_ending = False

    if not valid_ending:
        raise IDNABidiError('Label ends with illegal codepoint directionality')
    return True

def check_initial_combiner(label: str) -> bool:
    if unicodedata.category(label[0])[0] == 'M':
        raise IDNAError('Label begins with an illegal combining character')
    return True

def check_hyphen_ok(label: str) -> bool:
    if label[2:4] == '--':
        raise IDNAError('Label has disallowed hyphens in 3rd and 4th position')
    if label[0] == '-' or label[-1] == '-':
        raise IDNAError('Label must not start or end with a hyphen')
    return True

def check_nfc(label: str) -> None:
    if unicodedata.normalize('NFC', label) != label:
        raise IDNAError('Label must be in Normalization Form C')

def valid_contextj(label: str, pos: int) -> bool:
    cp_value = ord(label[pos])
    if cp_value == 0x200c:
        if pos > 0:
            if _combining_class(ord(label[pos - 1])) == _virama_combining_class:
                return True

        ok = False
        for i in range(pos-1, -1, -1):
            joining_type = idnadata.joining_types.get(ord(label[i]))
            if joining_type == ord('T'):
                continue
            if joining_type in [ord('L'), ord('D')]:
                ok = True
                break
        if not ok:
            return False

        ok = False
        for i in range(pos+1, len(label)):
            joining_type = idnadata.joining_types.get(ord(label[i]))
            if joining_type == ord('T'):
                continue
            if joining_type in [ord('R'), ord('D')]:
                ok = True
                break
        return ok

    if cp_value == 0x200d:
        if pos > 0:
            if _combining_class(ord(label[pos - 1])) == _virama_combining_class:
                return True
        return False
    else:
        return False

def valid_contexto(label: str, pos: int, exception: bool = False) -> bool:
    cp_value = ord(label[pos])
    if cp_value == 0x00b7:
        if 0 < pos < len(label)-1:
            if ord(label[pos - 1]) == 0x006c and ord(label[pos + 1]) == 0x006c:
                return True
        return False
    elif cp_value == 0x0375:
        if pos < len(label)-1 and len(label) > 1:
            return _is_script(label[pos + 1], 'Greek')
        return False
    elif cp_value == 0x05f3 or cp_value == 0x05f4:
        if pos > 0:
            return _is_script(label[pos - 1], 'Hebrew')
        return False
    elif cp_value == 0x30fb:
        for cp in label:
            if cp == '\u30fb':
                continue
            if _is_script(cp, 'Hiragana') or _is_script(cp, 'Katakana') or _is_script(cp, 'Han'):
                return True
        return False
    elif 0x660 <= cp_value <= 0x669:
        for cp in label:
            if 0x6f0 <= ord(cp) <= 0x06f9:
                return False
        return True
    elif 0x6f0 <= cp_value <= 0x6f9:
        for cp in label:
            if 0x660 <= ord(cp) <= 0x0669:
                return False
        return True
    return False

def check_label(label: Union[str, bytes, bytearray]) -> None:
    if isinstance(label, (bytes, bytearray)):
        label = label.decode('utf-8')

    if len(label) == 0:
        raise IDNAError('Empty Label')

    check_nfc(label)
    check_hyphen_ok(label)
    check_initial_combiner(label)

    for (pos, cp) in enumerate(label):
        cp_value = ord(cp)
        if intranges_contain(cp_value, idnadata.codepoint_classes['PVALID']):
            continue
        elif intranges_contain(cp_value, idnadata.codepoint_classes['CONTEXTJ']):
            try:
                if not valid_contextj(label, pos):
                    raise InvalidCodepointContext('Joiner {} not allowed at position {} in {}'.format(
                        _unot(cp_value), pos+1, repr(label)))
            except ValueError:
                raise IDNAError('Unknown codepoint adjacent to joiner {} at position {} in {}'.format(
                    _unot(cp_value), pos+1, repr(label)))
        elif intranges_contain(cp_value, idnadata.codepoint_classes['CONTEXTO']):
            if not valid_contexto(label, pos):
                raise InvalidCodepointContext('Codepoint {} not allowed at position {} in {}'.format(_unot(cp_value), pos+1, repr(label)))
        else:
            raise InvalidCodepoint('Codepoint {} at position {} of {} not allowed'.format(_unot(cp_value), pos+1, repr(label)))

    check_bidi(label)

def alabel(label: str) -> bytes:
    try:
        label_bytes = label.encode('ascii')
        ulabel(label_bytes)
        if not valid_label_length(label_bytes):
            raise IDNAError('Label too long')
        return label_bytes
    except UnicodeEncodeError:
        pass

    if not label:
        raise IDNAError('No Input')

    label = str(label)
    check_label(label)
    label_bytes = _punycode(label)
    label_bytes = _alabel_prefix + label_bytes

    if not valid_label_length(label_bytes):
        raise IDNAError('Label too long')
    return label_bytes

def ulabel(label: Union[str, bytes, bytearray]) -> str:
    if not isinstance(label, (bytes, bytearray)):
        try:
            label_bytes = label.encode('ascii')
        except UnicodeEncodeError:
            check_label(label)
            return label
    else:
        label_bytes = label

    label_bytes = label_bytes.lower()

    if label_bytes.startswith(_alabel_prefix):
        label_bytes = label_bytes[len(_alabel_prefix):]
        if not label_bytes:
            raise IDNAError('Malformed A-label, no Punycode eligible content found')
        if label_bytes.decode('ascii')[-1] == '-':
            raise IDNAError('A-label must not end with a hyphen')
    else:
        check_label(label_bytes)
        return label_bytes.decode('ascii')

    try:
        label = label_bytes.decode('punycode')
    except UnicodeError:
        raise IDNAError('Invalid A-label')

    check_label(label)
    return label

def uts46_remap(domain: str, std3_rules: bool = True, transitional: bool = False) -> str:
    """Re-map the characters in the string according to UTS46 processing."""
    from .uts46data import uts46data

    output = ''
    for pos, char in enumerate(domain):
        code_point = ord(char)
        try:
            uts46row = uts46data[code_point if code_point < 256 else
                bisect.bisect_left(uts46data, (code_point, 'Z')) - 1]
            status = uts46row[1]
            replacement = None  # type: Optional[str]
            if len(uts46row) == 3:
                replacement = uts46row[2]  # type: ignore

            if (status == 'V' or
                    (status == 'D' and not transitional) or
                    (status == '3' and not std3_rules and replacement is None)):
                output += char
            elif replacement is not None and (status == 'M' or
                    (status == '3' and not std3_rules) or
                    (status == 'D' and transitional)):
                output += replacement
            elif status != 'I':
                raise IndexError()
        except IndexError:
            raise InvalidCodepoint(
                'Codepoint {} not allowed at position {} in {}'.format(
                _unot(code_point), pos + 1, repr(domain)))

    return unicodedata.normalize('NFC', output)

def encode(s: Union[str, bytes, bytearray], strict: bool = False, uts46: bool = False, std3_rules: bool = False, transitional: bool = False) -> bytes:
    if isinstance(s, (bytes, bytearray)):
        try:
            s = s.decode('ascii')
        except UnicodeDecodeError:
            raise IDNAError('should pass a unicode string to the function rather than a byte string.')

    if uts46:
        s = uts46_remap(s, std3_rules, transitional)

    trailing_dot = False
    result = []

    if strict:
        labels = s.split('.')
    else:
        labels = _unicode_dots_re.split(s)

    if not labels or labels == ['']:
        raise IDNAError('Empty domain')

    if labels[-1] == '':
        del labels[-1]
        trailing_dot = True

    for label in labels:
        s = alabel(label)
        if s:
            result.append(s)
        else:
            raise IDNAError('Empty label')

    if trailing_dot:
        result.append(b'')

    s = b'.'.join(result)

    if not valid_string_length(s, trailing_dot):
        raise IDNAError('Domain too long')

    return s

def decode(s: Union[str, bytes, bytearray], strict: bool = False, uts46: bool = False, std3_rules: bool = False) -> str:
    try:
        if isinstance(s, (bytes, bytearray)):
            s = s.decode('ascii')
    except UnicodeDecodeError:
        raise IDNAError('Invalid ASCII in A-label')

    if uts46:
        s = uts46_remap(s, std3_rules, False)

    trailing_dot = False
    result = []

    if not strict:
        labels = _unicode_dots_re.split(s)
    else:
        labels = s.split('.')

    if not labels or labels == ['']:
        raise IDNAError('Empty domain')

    if not labels[-1]:
        del labels[-1]
        trailing_dot = True

    for label in labels:
        s = ulabel(label)
        if s:
            result.append(s)
        else:
            raise IDNAError('Empty label')

    if trailing_dot:
        result.append('')

    return '.'.join(result)

# Import necessary modules for token usage handling
from statgpt.common.schemas.token_usage import TokenUsageItem, TokenUsagePricedItem


class TokenUsageCostCalculator:
    def __init__(self, model_to_pricing_map: dict) -> None:
        # Store the mapping from model names to their pricing information
        self._model_to_pricing_map = model_to_pricing_map

    def get_token_usage_with_costs(
        self, token_usage: list[TokenUsageItem]
    ) -> list[TokenUsagePricedItem]:
        """Convert raw token usage data into priced token usage items."""
        return [
            TokenUsagePricedItem(
                deployment=item.deployment,
                model=item.model,
                prompt_tokens=item.prompt_tokens,
                completion_tokens=item.completion_tokens,
                costs=self._calculate_usage_cost(item),
            )
            for item in token_usage
        ]

    def _calculate_usage_cost(self, item: TokenUsageItem) -> float | None:
        """Calculate the cost of the token usage based on model pricing."""
        if model_pricing := self._model_to_pricing_map.get(item.model):
            # Compute total cost: (prompt tokens * prompt price) + (completion tokens * completion price)
            return (
                item.prompt_tokens * model_pricing.prompt
                + item.completion_tokens * model_pricing.completion
            )
        return None


class TokenUsageDisplayer:
    # Column name mappings for display purposes
    PRETTY_COLUMN_NAMES = {
        "deployment": "Deployment",
        "model": "Model",
        "prompt_tokens": "Prompt Tokens",
        "completion_tokens": "Completion Tokens",
        "total_tokens": "Total Tokens",
        "costs": "Total Price, $",
    }
    NA_REPLACEMENT = "-"

    @classmethod
    def as_markdown_table(cls, token_usage: list[TokenUsagePricedItem]) -> str:
        """Convert token usage statistics to a Markdown table string."""
        import pandas as pd  # Local import to avoid unnecessary dependency

        df = pd.DataFrame(
            [item.model_dump(by_alias=True) for item in token_usage],
            columns=list(cls.PRETTY_COLUMN_NAMES.keys()),
        )
        total_row = cls._get_total_row(df)
        df = pd.concat([df, total_row], ignore_index=True)
        df.rename(columns=cls.PRETTY_COLUMN_NAMES, inplace=True)
        df.fillna(cls.NA_REPLACEMENT, inplace=True)
        return df.to_markdown(index=False)

    @staticmethod
    def _get_total_row(df: pd.DataFrame) -> pd.DataFrame:
        """Generate a row with totals for numeric columns."""
        totals = df.sum(numeric_only=True)
        return pd.DataFrame(
            {
                "deployment": "",
                "model": "TOTAL:",
                "prompt_tokens": totals.get("prompt_tokens"),
                "completion_tokens": totals.get("completion_tokens"),
                "total_tokens": totals.get("total_tokens"),
                "costs": totals.get("costs"),
            },
            index=[0],
        )

    @staticmethod
    def calculate_total_cost(token_usage: list[TokenUsagePricedItem]) -> float:
        """Calculate the sum of all costs in the token usage list."""
        if not token_usage:
            return 0.0
        return sum(item.costs for item in token_usage if item.costs)

    @staticmethod
    def total_cost_str(token_usage: list[TokenUsagePricedItem]) -> str:
        """Return formatted total cost as a string with 3 decimal places."""
        total_cost = TokenUsageDisplayer.calculate_total_cost(token_usage)
        return f"{total_cost:.3f}"

    @classmethod
    def as_string_list(cls, token_usage: list[TokenUsagePricedItem]) -> str:
        """Convert token usage statistics to a human-readable Markdown list format."""
        res = ""
        for item in token_usage:
            res += f"### {item.model}\n"
            res += f"* Prompt Tokens: {item.prompt_tokens}\n"
            res += f"* Completion Tokens: {item.completion_tokens}\n"
            res += f"* Total Tokens: {item.total_tokens}\n"
            if item.costs is None:
                res += "* Total Price: <NO DATA>\n\n"
            else:
                res += f"* Total Price, $: {item.costs:.3f}\n\n"

        # Aggregate totals across all items
        total_prompt_tokens = sum(item.prompt_tokens for item in token_usage if item.prompt_tokens)
        total_completion_tokens = sum(
            item.completion_tokens for item in token_usage if item.completion_tokens
        )
        total_total_tokens = sum(item.total_tokens for item in token_usage if item.total_tokens)
        total_costs_str = cls.total_cost_str(token_usage)

        # Append summary section
        res += "-" * 15 + "\n"
        res += "## TOTAL:\n"
        res += f"* Prompt Tokens: {total_prompt_tokens}\n"
        res += f"* Completion Tokens: {total_completion_tokens}\n"
        res += f"* Total Tokens: {total_total_tokens}\n"
        res += f"* Total Price, $: {total_costs_str}\n"
        return res

# Import necessary modules
from __future__ import annotations
from inspect import getfullargspec
import json
import pprint
import re  # noqa: F401
from datetime import datetime
from pydantic import BaseModel, ConfigDict, Field, StrictStr, ValidationError, field_validator
from typing import Optional
from typing import Union, Any, List, Set, TYPE_CHECKING, Dict
from typing_extensions import Literal, Self

# Re-import Field (though already imported above)
from pydantic import Field

# Constants for schema types
TIMESTAMP_ANY_OF_SCHEMAS = ["datetime", "str"]

class Timestamp(BaseModel):
    """
    When the content occurred. Accepts an ISO 8601 datetime string (e.g. '2024-01-15T10:30:00Z'), 
    null/omitted (defaults to now), or the special string 'unset' to explicitly store without 
    any timestamp (use this for timeless content such as fictional documents or static reference material).
    """

    # data type: datetime
    anyof_schema_1_validator: Optional[datetime] = None

    # data type: str
    anyof_schema_2_validator: Optional[StrictStr] = None

    if TYPE_CHECKING:
        actual_instance: Optional[Union[datetime, str]] = None
    else:
        actual_instance: Any = None

    any_of_schemas: Set[str] = { "datetime", "str" }

    model_config = {
        "validate_assignment": True,
        "protected_namespaces": (),
    }

    def __init__(self, *args, **kwargs) -> None:
        if args:
            if len(args) > 1:
                raise ValueError("If a position argument is used, only 1 is allowed to set `actual_instance`")
            if kwargs:
                raise ValueError("If a position argument is used, keyword arguments cannot be used.")
            super().__init__(actual_instance=args[0])
        else:
            super().__init__(**kwargs)

    @field_validator('actual_instance')
    def actual_instance_must_validate_anyof(cls, v):
        if v is None:
            return v

        instance = Timestamp.model_construct()
        error_messages = []

        # validate data type: datetime
        try:
            instance.anyof_schema_1_validator = v
            return v
        except (ValidationError, ValueError) as e:
            error_messages.append(str(e))

        # validate data type: str
        try:
            instance.anyof_schema_2_validator = v
            return v
        except (ValidationError, ValueError) as e:
            error_messages.append(str(e))

        if error_messages:
