# Import necessary modules
import narwhals as nw
import polars as pl
from narwhals.typing import DataFrameT, Frame, FrameT, LazyFrameT
from typing import Any


def collect_to_polars(frame: Frame) -> pl.DataFrame:
    """Helper to convert a Narwhals frame into an eager Polars DataFrame."""
    return frame.lazy().collect().to_polars()


def lazy_frame_to_polars(frame: nw.LazyFrame[Any]) -> pl.LazyFrame:
    """
    Helper to convert a Narwhals lazy frame into a Polars lazy frame.
    If the Narwhals LazyFrame is already backed by Polars, this is a no-op.
    """
    if frame.implementation == nw.Implementation.POLARS:
        return frame.to_native()

    # Convert via eager Polars DataFrame then back to lazy
    return frame.collect().to_polars().lazy()


@overload
def switch_implementation_to_polars(frame: DataFrameT) -> DataFrameT: ...


@overload
def switch_implementation_to_polars(frame: LazyFrameT) -> LazyFrameT: ...


def switch_implementation_to_polars(frame: FrameT) -> FrameT:
    """Switch implementation of a Narwhals frame to Polars if not already Polars-backed."""
    if frame.implementation == nw.Implementation.POLARS:
        return frame

    elif isinstance(frame, nw.DataFrame):
        # Convert eager Narwhals DataFrame to Polars DataFrame and wrap again
        return nw.from_native(frame.to_polars())

    elif isinstance(frame, nw.LazyFrame):
        # Convert lazy Narwhals frame to Polars lazy frame
        return nw.from_native(
            frame.collect().to_polars(),
        ).lazy()

    else:
        raise ValueError(f"Unsupported frame type: {type(frame)}")


__all__ = ["collect_to_polars"]

# Modified version with Type I clone transformations
from typing import Callable, List, Tuple, Literal
from starlette.routing import Route

OPERATOR_MAPPING = {
    "like": "like",
    "lt": "<",
    "lte": "<=",
}

def build_where_clause_from_query_params(params: dict) -> Tuple[str, dict]:
    condition_str: str = ""
    param_values: dict = {}

    for key, value in params.items():
        if value is None:
            continue

        segments: list = key.split("__")
        num_segments: int = len(segments)

        if num_segments == 1:
            column_name = segments[0]
            operator = "="
        elif num_segments == 2:
            column_name = segments[0]
            operator = OPERATOR_MAPPING[segments[1]]
        else:
            raise ValueError('Field name should contain at most one "__" separator')

        condition_str += f" and {column_name} {operator} :{column_name}"
        param_values[column_name] = value

    return condition_str, param_values

def create_crud_routes(
    base_path: str,
    handler: Callable,
    identifier_type: Literal["int", "uuid", "str"] = "int",
) -> List[Route]:
    assert not base_path.endswith("/"), "base_path must not end with '/'"

    return [
        Route(
            path=f"{base_path}/{{id:{identifier_type}}}",
            endpoint=handler,
            methods=["delete", "patch"],
        ),
        Route(
            path=base_path,
            endpoint=handler,
            methods=["get", "post"],
        ),
    ]

# Helper functions for location processing in OpenTrons protocols
from opentrons.protocol_api.labware import Well
from opentrons.types import Location
from typing import Union, Sequence, Any, List

CommandLocation = Union[Location, None, Sequence, Well]

def convert_to_list(loc_input: Any) -> List:
    if isinstance(loc_input, list):
        try:
            return convert_to_list(loc_input[0])
        except IndexError:
            return [loc_input]
    else:
        return [loc_input]

def format_location_string(loc: Union[Location, Well]) -> str:
    if isinstance(loc, Location):
        if loc.labware.is_empty:
            return str(loc.point)
        else:
            return repr(loc.labware)
    elif isinstance(loc, Well):
        return str(loc)
    else:
        raise TypeError(loc)

def get_location_string(location: CommandLocation) -> str:
    loc_str_list = [format_location_string(loc) for loc in convert_to_list(location)]
    return ", ".join(loc_str_list)

