# Generate HTML reports for resources
import os
from pathlib import Path
import markdown
from moonleap.render.render_resources import render_template
from moonleap.session import get_session

def _get_report_filename(resource, report_directory):
    resource_id = resource.id
    html_filename = resource_id + ".html"
    return os.path.join(report_directory, html_filename)

def generate_reports(resource_blocks):
    output_dir = ".moonleap/report"
    index_file = os.path.abspath(os.path.join(output_dir, "index.html"))

    if not os.path.exists(output_dir):
        os.makedirs(output_dir)

    for block in resource_blocks:
        owned_resources = [x for x in block.get_resource_by_term() if x[2]]
        for term, resource, is_owner in owned_resources:
            report_path = _get_report_filename(resource, output_dir)
            with open(report_path, "w") as file_handle:
                file_handle.write(build_resource_report(resource, term, index_file))

    with open(index_file, "w") as file_handle:
        file_handle.write(build_index_page(resource_blocks))

def build_resource_report(resource, term, index_path):
    template_path = Path(__file__).parent / "templates" / "resource.md.j2"
    content_body = render_template(
        template_path,
        term=term,
        settings=get_session().settings,
        props={},
        child_relations=resource.get_relations(),
        parent_relations=resource.get_inv_relations(),
        index_fn=index_path,
        res=resource,
    )
    return (
        "<html><body>"
        + f"""{markdown.markdown(content_body, extensions=['tables'])}"""
        + "</body></html>"
    )

def build_index_page(blocks):
    template_path = Path(__file__).parent / "templates" / "index.md.j2"
    term_resource_map = {}
    main_block = blocks[0]

    for block in main_block.get_blocks(include_children=True):
        for term, resource, is_owner in block.get_resource_by_term():
            if is_owner:
                term_resource_map[str(term)] = resource

    sorted_terms = sorted(
        list(term_resource_map.items()), key=lambda item: item[0]
    )

    content_body = render_template(
        template_path,
        settings=get_session().settings,
        resource_by_term_str=sorted_terms,
    )
    return (
        "<html><body>"
        + f"""{markdown.markdown(content_body, extensions=['tables'])}"""
        + "</body></html>"
    )

# Lambda handler with Honeycomb tracing and error handling
import time
import json
from entrypoint import beeline
from beeline.middleware.awslambda import beeline_wrapper

@beeline_wrapper
def lambda_handler(event, context):
    try:
        with beeline.tracer(name="lambda22"):
            beeline.add_context({
                'request_data': event,
            })
            time.sleep(2)
    except Exception as err:
        # Re-raise exception to trigger Lambda retry
        error_class = err.__class__.__name__
        error_msg = str(err)
        beeline.add_context({
            'error.class': error_class,
            'error.description': error_msg,
        })
        error_response = {
            "isError": True,
            "kind": error_class,
            "text": error_msg,
        }
        error_json = json.dumps(error_response)
        raise LambdaException(error_json)
    finally:
        beeline.get_beeline().client.flush()

class LambdaException(Exception):
    '''Custom exception class for cleaner error output in AWS Lambda'''

