# It enhances `datacube dataset add` and `datacube dataset update` in multiple aspects:
# - Automatically determines whether to Add or Update a dataset
# - Supports indexing STAC format
"""
import click
import logging
import yaml
from odc.stac.transform import stac_transform
import datacube
from datacube.index.hl import Doc2Dataset
from odc.apps.dc_tools.utils import (
    index_update_dataset,
    update_if_exists,
    allow_unsafe,
    transform_stac,
)
from typing import Generator, Optional
try:
