)

def setup_logging():
    logging.basicConfig(
        level=logging.WARNING,
        format="%(asctime)s: %(levelname)s: %(message)s",
        datefmt="%m/%d/%Y %I:%M:%S",
    )

def _locate_files(
    directory: str, pattern: Optional[str] = None, is_stac: Optional[bool] = False
) -> Generator[Path, None, None]:
    if pattern is None:
        pattern = "**/*.json" if is_stac else "**/*.yaml"

@click.command("fs-to-dc",
               help=__doc__)
@click.argument("INPUT_FILES", type=str, nargs=-1)
@update_if_exists
@allow_unsafe
@transform_stac
def cli(input_files, update_if_exists, allow_unsafe, stac):
    dc = datacube.Datacube()
    doc2ds = Doc2Dataset(dc.index)

    pattern = "**/*.json" if stac else "**/*.yaml"
    files_to_process = _locate_files(input_directory, pattern, is_stac=stac)

    success_count, error_count = 0, 0
    for file_path in input_files:
        with file_path.open() as f:
            try:
                if str(file_path).endswith(".yml") or str(file_path).endswith(".yaml"):
                    metadata = yaml.safe_load(f, Loader=Loader)
                else:
                    import json
                    metadata = json.load(f)

                # Apply STAC transformation if enabled
                if stac:
                    metadata = stac_transform(metadata)

                index_update_dataset(
                    metadata,
                    file_path.absolute().as_uri(),
                    dc=dc,
                    doc2ds=doc2ds,
                    update_if_exists=update_if_exists,
                    allow_unsafe=allow_unsafe,
                )
                success_count += 1
            except Exception as err:
                logging.exception(f"Failed to process dataset {file_path}: {err}")
                error_count += 1

    logging.info(f"Successfully added {success_count} datasets; {error_count} failed.")

if __name__ == "__main__":
    setup_logging()
    cli()

