# Custom Ansible lookup module for managing configuration files
__metaclass__ = type
from ansible.plugins.lookup import LookupBase
from ansible.errors import AnsibleError
import os

class LookupModule(LookupBase):
    def run(self, terms, variables=None, **kwargs):
        output_list = []
        desired_state = kwargs.pop('wantstate', None)
        primary_configs = self._flatten(terms[0])
        sapi_configs = terms[1]
        exclusive_configs = self._flatten(terms[2])
        config_directory = terms[3]

        base_item = {
            'state': 'present'
        }

        # Process exclusive configurations - mark them as absent
        for exclusive_config in exclusive_configs:
            entry = base_item.copy()
            entry.update({
                'file':  exclusive_config['path'],
                'state': 'absent'
            })
            output_list.append(entry)

        # Process primary configurations
        for primary_config in primary_configs:
            entries = []
            # Validate that config is a dictionary
            if not isinstance(primary_config, dict):
                raise AnsibleError('Configuration must be a dictionary')
            # Verify required 'file' key exists
            if 'file' not in primary_config:
                raise AnsibleError('Missing required "file" key in configuration')

            entry = base_item.copy()
            entry.update(primary_config)
            entry.update({
                'file': os.path.join(config_directory, entry['file']),
                'sapi': sapi_configs
            })
            entries.append(entry)

            # Merge entries by file path
            for new_entry in entries:
                found_match = False
                for idx, existing_entry in enumerate(output_list):
                    if existing_entry['file'] == new_entry['file']:
                        output_list[idx] = new_entry
                        found_match = True
                        break
                if not found_match:
                    output_list.append(new_entry)

        # Apply state filtering if specified
        if desired_state:
            output_list = [entry for entry in output_list if entry.get('state') == desired_state]

        return output_list

