async def main(start_port: int, show_timing: bool = False, interactive: bool = True, did=None):
    # check for extra args
    additional_args = {}
    if ADDITIONAL_ARGS:
        print("Got extra args:", ADDITIONAL_ARGS)
        additional_args = js.loads(ADDITIONAL_ARGS)
    # genesis = await default_genesis_txns()
    # if not genesis:
    #     print("Error retrieving ledger genesis transactions")
    #     sys.exit(1)
    agent = None
    try:
        agent = IndiLynxCloudAgentBackchannel(
            "indiLynx." + AGENT_LABEL,
            start_port + 1,
            start_port + 2,
            genesis_data="{}",
            extra_args=additional_args,
        )
        agent.did = did
        # start backchannel (common across all types of agents)
        await agent.listen_backchannel(start_port)
        #await agent.register_did()
        import asyncio
        asyncio.get_event_loop().create_task(agent.start_listener())
        asyncio.get_event_loop().create_task(agent.start_dummy_listener())
        agent.activate()
        # now wait ...
        interactive = False
        print(interactive)
        if interactive:
            async for option in prompt_loop("(X) Exit? [X] "):
                if option is None or option in "xX":
                    break
        else:
            print("Press Ctrl-C to exit ...")
            remaining_tasks = asyncio.Task.all_tasks()
            await asyncio.gather(*remaining_tasks)
    finally:
        terminated = True
        try:
            if agent:
                await agent.terminate()
        except Exception:
            log.exception("Error terminating agent:")
            terminated = False
    await asyncio.sleep(0.1)
    if not terminated:
        filesystem._exit(1)

def str2bool(v):
    if isinstance(v, bool):
        return v
    if v.lower() in ("yes", "true", "t", "y", "1"):
        return True
    elif v.lower() in ("no", "false", "f", "n", "0"):
        return False
    else:
        import argparse
        raise argparse.ArgumentTypeError("Boolean value expected.")

