# Modified version of PlayerState class with renamed variables and reordered statements
from dataclasses import field
from typing import List, Optional, Set, Dict
from pandemic.simulation.model import constants
from pandemic.simulation.model.city_id import Card, EventCard
from pandemic.simulation.model.constants import PLAYER_START
from collections import defaultdict

@dataclass
class PlayerState:
    current_city: int = PLAYER_START
    _city_card_set: Set[Card] = field(default_factory=set)
    _event_card_set: Set[EventCard] = field(default_factory=set)
    _reserve_contingency_planner_event: Optional[Card] = None
    _reserve_contingency_planner_city: Optional[Card] = None
    _operations_expert_charter_flight_available: bool = True
    _card_count: int = 0
    _virus_color_counts: Dict[Virus, int] = field(default_factory=lambda: defaultdict(int))

    @property
    def all_cards(self) -> Set[Card]:
        return self.city_card_set | self.event_card_set

    @property
    def virus_color_distribution(self) -> Dict[Virus, int]:
        return self._virus_color_counts

    @all_cards.setter
    def all_cards(self, new_cards: Set[Card]):
        self.discard_all_cards()
        self.receive_cards(list(new_cards))

    @property
    def city_card_set(self) -> Set[City]:
        if self._reserve_contingency_planner_city:
            return self._city_card_set | {self._reserve_contingency_planner_city}
        return self._city_card_set

    @property
    def event_card_set(self) -> Set[EventCard]:
        if self._reserve_contingency_planner_event:
            return self._event_card_set | {self._reserve_contingency_planner_event}
        return self._event_card_set

    @property
    def contingency_planner_storage(self) -> Optional[Card]:
        if self._reserve_contingency_planner_city is not None:
            return self._reserve_contingency_planner_city
        return self._reserve_contingency_planner_event

    @contingency_planner_storage.setter
    def contingency_planner_storage(self, card: Card):
        if Card.card_type(card) == Card.CITY:
            self._virus_color_counts[constants.CITY_COLORS[card]] += 1
            self._reserve_contingency_planner_city = card
            self._reserve_contingency_planner_event = None
        else:
            self._reserve_contingency_planner_city = None
            self._reserve_contingency_planner_event = card

    def receive_card(self, card: Card):
        if Card.card_type(card) == Card.EVENT:
            self._event_card_set.add(card)
            self._card_count += 1
        elif Card.card_type(card) == Card.CITY:
            self._virus_color_counts[constants.CITY_COLORS[card]] += 1
            self._city_card_set.add(card)
            self._card_count += 1

    def receive_cards(self, cards: List[Card]):
        for card in cards:
            self.receive_card(card)

    def discard_all_cards(self):
        self._card_count = 0
        self._virus_color_counts = defaultdict(int)
        self._reserve_contingency_planner_event: Optional[Card] = None
        self._reserve_contingency_planner_city: Optional[Card] = None
        self._event_card_set.clear()
        self._city_card_set.clear()

    def discard_card(self, card: Card) -> bool:
        if Card.card_type(card) == Card.CITY:
            try:
                self._city_card_set.remove(card)
                self._card_count -= 1
                self._virus_color_counts[constants.CITY_COLORS[card]] -= 1
                return True
            except KeyError:
                if card == self._reserve_contingency_planner_city:
                    self._reserve_contingency_planner_city = None
                    self._virus_color_counts[constants.CITY_COLORS[card]] -= 1
                    return False
        else:
            try:
                self._event_card_set.remove(card)
                self._card_count -= 1
                return True
            except KeyError:
                if card == self._reserve_contingency_planner_event:
                    self._reserve_contingency_planner_event = None
                    return False
                raise KeyError

    def get_card_count(self) -> int:
        return self._card_count

    def use_operations_expert_shuttle(self):
        self._operations_expert_charter_flight_available = False

    def end_turn(self):
        self._operations_expert_charter_flight_available = True

    def can_use_operations_expert_shuttle(self) -> bool:
        return self._operations_expert_charter_flight_available

    def cards_to_string(self) -> str:
        return " ".join(map(str, self.all_cards))

