            raise e.TypeError('`plateau_neighbors` should be an integer')
        if plateau_neighbors < 0:
            raise e.ValueError('`plateau_neighbors` should be >= 0')
        self._plateau_neighbors = plateau_neighbors
    @property
    def neighbors(self):
        """list: Adjacent nodes.
        """
        return self._neighbors
    @neighbors.setter
    def neighbors(self, neighbors):
        if not isinstance(neighbors, list):
            raise e.TypeError('`neighbors` should be a list')
        self._neighbors = neighbors
    @property
    def cluster_root(self):
        """int: Cluster's root node identifier.
        """
        return self._cluster_root
    @cluster_root.setter
    def cluster_root(self, cluster_root):
        if not isinstance(cluster_root, int):
            raise e.TypeError('`cluster_root` should be an integer')
        if cluster_root < 0:
            raise e.ValueError('`cluster_root` should be >= 0')
        self._cluster_root = cluster_root
    @property
    def node_status(self):
        """int: Whether the node is a prototype or not.
        """
        return self._node_status
    @node_status.setter
    def node_status(self, node_status):
        if node_status not in [c.STANDARD, c.PROTOTYPE]:
            raise e.TypeError('`node_status` should be `STANDARD` or `PROTOTYPE`')
        self._node_status = node_status
    @property
    def predecessor(self):
        """int: Identifier to the predecessor node.
        """
        return self._predecessor
    @predecessor.setter
    def predecessor(self, predecessor):
        if not isinstance(predecessor, int):
            raise e.TypeError('`predecessor` should be an integer')
        if predecessor < c.NIL:
            raise e.ValueError('`predecessor` should have a value larger than `NIL`, e.g., -1')
        self._predecessor = predecessor
    @property
    def is_relevant(self):
        """int: Whether the node is relevant or not.
        """
        return self._is_relevant
    @is_relevant.setter
    def is_relevant(self, is_relevant):
        if is_relevant not in [c.RELEVANT, c.IRRELEVANT]:
            raise e.TypeError('`is_relevant` should be `RELEVANT` or `IRRELEVANT`')
        self._is_relevant = is_relevant

