class ThreeQSDNIE(InfoExtractor):
    IE_NAME = '3qsdn'
    IE_DESC = '3Q SDN'
    _VALID_URL = r'https?://playout\.3qsdn\.com/(?P<id>[\da-f]{8}-[\da-f]{4}-[\da-f]{4}-[\da-f]{4}-[\da-f]{12})'
    _TESTS = [{
        # https://player.3qsdn.com/demo.html
        'url': 'https://playout.3qsdn.com/7201c779-6b3c-11e7-a40e-002590c750be',
        'md5': '64a57396b16fa011b15e0ea60edce918',
        'info_dict': {
            'id': '7201c779-6b3c-11e7-a40e-002590c750be',
            'ext': 'mp4',
            'title': 'Video Ads',
            'is_live': False,
            'description': 'Video Ads Demo',
            'timestamp': 1500334803,
            'upload_date': '20170717',
            'duration': 888.032,
            'subtitles': {
                'eng': 'count:1',
            },
        },
        'expected_warnings': ['Unknown MIME type application/mp4 in DASH manifest'],
    }, {
        # live video stream
        'url': 'https://playout.3qsdn.com/66e68995-11ca-11e8-9273-002590c750be',
        'info_dict': {
            'id': '66e68995-11ca-11e8-9273-002590c750be',
            'ext': 'mp4',
            'title': 're:^66e68995-11ca-11e8-9273-002590c750be [0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}$',
            'is_live': True,
        },
        'params': {
            'skip_download': True,  # m3u8 downloads
        },
    }, {
        # live audio stream
        'url': 'http://playout.3qsdn.com/9edf36e0-6bf2-11e2-a16a-9acf09e2db48',
        'only_matching': True,
    }, {
        # live audio stream with some 404 URLs
        'url': 'http://playout.3qsdn.com/ac5c3186-777a-11e2-9c30-9acf09e2db48',
        'only_matching': True,
    }, {
        # geo restricted with 'This content is not available in your country'
        'url': 'http://playout.3qsdn.com/d63a3ffe-75e8-11e2-9c30-9acf09e2db48',
        'only_matching': True,
    }, {
        # geo restricted with 'playout.3qsdn.com/forbidden'
        'url': 'http://playout.3qsdn.com/8e330f26-6ae2-11e2-a16a-9acf09e2db48',
        'only_matching': True,
    }, {
        # live video with rtmp link
        'url': 'https://playout.3qsdn.com/6092bb9e-8f72-11e4-a173-002590c750be',
        'only_matching': True,
    }, {
        # ondemand from http://www.philharmonie.tv/veranstaltung/26/
        'url': 'http://playout.3qsdn.com/0280d6b9-1215-11e6-b427-0cc47a188158?protocol=http',
        'only_matching': True,
    }, {
        # live video stream
        'url': 'https://playout.3qsdn.com/d755d94b-4ab9-11e3-9162-0025907ad44f?js=true',
        'only_matching': True,
    }]

    @staticmethod
    def _extract_url(webpage):
        pattern = r'<iframe[^>]+\b(?:data-)?src=(["\'])(?P<url>%s.*?)\1' % ThreeQSDNIE._VALID_URL
        match_obj = re.search(pattern, webpage)
        if match_obj:
            return match_obj.group('url')

    def _real_extract(self, url):
        video_id = self._match_id(url)
        try:
            config_data = self._download_json(
                url.replace('://playout.3qsdn.com/', '://playout.3qsdn.com/config/'), video_id)
        except ExtractorError as error:
            if isinstance(error.cause, compat_HTTPError) and error.cause.code == 401:
                self.raise_geo_restricted()
            raise

        is_live = config_data.get('streamContent') == 'live'
        aspect_ratio = float_or_none(config_data.get('aspect'))
        formats_list = []
        subtitles_map = {}

        for source_type, source_items in (config_data.get('sources') or {}).items():
            if not source_items:
                continue

            if source_type == 'dash':
                fmts, subs = self._extract_mpd_formats_and_subtitles(
                    source_items, video_id, mpd_id='mpd', fatal=False)
                formats_list.extend(fmts)
                subtitles_map = self._merge_subtitles(subtitles_map, subs)

            elif source_type == 'hls':
                fmts, subs = self._extract_m3u8_formats_and_subtitles(
                    source_items, video_id, 'mp4', 'm3u8' if is_live else 'm3u8_native',
                    m3u8_id='hls', fatal=False)
                formats_list.extend(fmts)
                subtitles_map = self._merge_subtitles(subtitles_map, subs)

            elif source_type == 'progressive':
                for item in source_items:
                    src_url = item.get('src')
                    if not (src_url and self._is_valid_url(src_url, video_id)):
                        continue
                    file_ext = determine_ext(src_url)
                    height_val = int_or_none(item.get('height'))
                    formats_list.append({
                        'ext': file_ext,
                        'format_id': join_nonempty('http', file_ext, height_val and '%dp' % height_val),
                        'height': height_val,
                        'source_preference': 0,
                        'url': src_url,
                        'vcodec': 'none' if height_val == 0 else None,
                        'width': int(height_val * aspect_ratio) if height_val and aspect_ratio else None,
                    })

        # It seems like this would be correctly handled by default
        # However, unless someone can confirm this, the old
        # behaviour is being kept as-is
        self._sort_formats(formats_list, ('res', 'source_preference'))

        for subtitle_item in (config_data.get('subtitles') or []):
            src_url = subtitle_item.get('src')
            if not src_url:
                continue
            label_text = subtitle_item.get('label') or 'eng'
            subtitles_map.setdefault(label_text, []).append({
                'url': src_url,
            })

        title_value = config_data.get('title') or video_id
        return {
            'id': video_id,
            'title': title_value,
            'thumbnail': config_data.get('poster') or None,
            'description': config_data.get('description') or None,
            'timestamp': parse_iso8601(config_data.get('upload_date')),
            'duration': float_or_none(config_data.get('vlength')) or None,
            'is_live': is_live,
            'formats': formats_list,
            'subtitles': subtitles_map,
        }

