class FakeHTTPResponse:
    def __init__(self, status_code, headers, body, hyperlinks=None, endpoint=None):
        self.status_code = status_code
        self.headers = headers
        self.body = body
        self.hyperlinks = hyperlinks or {}
        self.endpoint = endpoint or "http://endpoint/"

    @property
    def stream(self):
        from io import BytesIO
        return BytesIO(self.body)

class FakeHTTPClient:
    def __init__(self):
        self.responses_queue = []
        self.request_log = []

    def add_response(
        self, response_status, content_type="text/html", extra_headers=None,
        body='', hyperlinks=None, endpoint=None
    ):
        headers = {}
        if content_type:
            headers["Content-Type"] = content_type
        if extra_headers:
            for key, value in list(extra_headers.items()):
                headers[key.lower()] = value

        self.responses_queue.insert(
            0, FakeHTTPResponse(response_status, headers, body, hyperlinks, endpoint)
        )

    def perform_get(self, endpoint, headers=None, permitted_status_codes=None, **kwargs):
        self.request_log.append(endpoint)
        response = self.responses_queue.pop()

        if isinstance(response.status_code, Exception):
            raise response.status_code

        # Simulate the behavior of requests, where response.url contains
        # the final URL that responded to the request.
        response.endpoint = endpoint
        code = response.status_code
        category = "%sxx" % (code // 100)

        if (
            permitted_status_codes and (
                code not in permitted_status_codes
                and category not in permitted_status_codes
            )
        ):
            raise BadResponseException(endpoint, "Bad Response!", status_code=code)

        return response

