__all__ = ['command_example', 'get_example', 'static_example', 'wrap_example']

_random_generators = {}

# Functions for generating examples for built-in types and discord.py models
def _example(func):
    try:
        _random_generators[typing.get_type_hints(func)['return']] = func
    except KeyError:
        pass
    return func

@_example
