DEFAULT_TEXT = 'Lorem ipsum dolor sit amet.'
_arg_examples = {}

def _load_arg_examples():
    import json
    import logging
    try:
        with open('data/arg_examples.json', encoding='utf-8') as f:
            data = json.load(f)
    except Exception:  # muh pycodestyle
        logging.getLogger(__name__).error('Failed to load static examples')
    else:
        _arg_examples.update(data)

_load_arg_examples()

def _get_static_example(key, command=''):
    for key in (f'{command}.{key}', key):
        examples = _arg_examples.get(key)
        if not examples:
            continue
        if isinstance(examples, list):
            return random.choice(examples)
        return examples
    return DEFAULT_TEXT

def _actual_command(ctx):
    command = ctx.command
    return ctx.kwargs['command'] if command.name == 'help' else command

@_example
def _random_str(ctx) -> str:
    return _get_static_example(ctx._current_parameter.name, _actual_command(ctx))

def _get_name(obj):
    try:
        return obj.__name__
    except AttributeError:
        return obj.__class__.__name__

def _is_discord_ext_converter(converter):
    module = getattr(converter, '__module__', '')
    return module.startswith('discord') and module.endswith('converter')

def _aways_classy(obj):
    return obj if isinstance(obj, type) else type(obj)

# Skidded the inspect module
def _format_annotation(annotation, base_module=None):
    if getattr(annotation, '__module__', None) == 'typing':
        return repr(annotation).replace('typing.', '')
    if isinstance(annotation, type):
        if annotation.__module__ in ('builtins', base_module):
            return annotation.__qualname__
        return f'{annotation.__module__}.{annotation.__qualname__}'
    return repr(annotation)

_NoneType = type(None)

def get_example(converter, ctx):
    """Returns a random example based on the converter."""
    if hasattr(converter, 'random_example'):
        return converter.random_example(ctx)
    if getattr(converter, '__origin__', None) is typing.Union:
        converters = converter.__args__
        if len(converters) == 2 and converters[-1] is _NoneType:
            converter = converters[0]
        else:
            converter = random.choice(converters)
        return get_example(converter, ctx)
    if _is_discord_ext_converter(converter):
        if _aways_classy(converter) is commands.clean_content:
            converter = str
        else:
            converter = getattr(discord, _get_name(converter).replace('Converter', ''))
    try:
        func = _random_generators[converter]
    except KeyError as e:
        raise ValueError(f'Unable to get an example for {_format_annotation(converter)}') from e
    else:
        return func(ctx)

# Helper functions
def wrap_example(target):
    """Wraps a converter to use a function for example generation."""
    def decorator(func):
        target.random_example = func
        return func
    return decorator

def static_example(converter):
    """Marks a converter to use the static example generator (str)."""
    converter.random_example = _random_str
    return converter

# Example generation
_get_converter = functools.partial(commands.Command._get_converter, None)
_quote_pattern = '|'.join(map(re.escape, commands.view._all_quotes))
_quote_regex = re.compile(rf'\\(.)|({_quote_pattern})')
_escape_quotes = functools.partial(_quote_regex.sub, f'\\\1\2')

def _quote(string):
    string = _escape_quotes(string)
    if any(map(str.isspace, string)):
        string = f'"{string}"'
    return string

def _is_required_parameter(param):
    return param.default is param.empty and param.kind is not param.VAR_POSITIONAL

MAX_REPEATS_FOR_VARARGS = 4

def _parameter_examples(parameters, ctx, command=None):
    command = command or ctx.command

    def parameter_example(parameter):
        ctx._current_parameter = parameter
        example = str(get_example(_get_converter(parameter), ctx))
        if not (parameter.kind == parameter.KEYWORD_ONLY and not command.rest_is_raw or example.startswith(('#', '@'))):
            example = _quote(example)
        return example

    for parameter in parameters:
        yield parameter_example(parameter)
        if parameter.kind is parameter.VAR_POSITIONAL:
            for _ in range(random.randint(varpos.requires_var_positional(parameter), MAX_REPEATS_FOR_VARARGS)):
                yield parameter_example(parameter)

def _split_params(command):
    """Splits a command's parameters into required and optional parts."""
    params = command.clean_params.values()
    required = list(itertools.takewhile(_is_required_parameter, params))
    optional = []
    for param in itertools.dropwhile(_is_required_parameter, params):
        if param.kind is param.VAR_POSITIONAL:
            args = required if varpos.requires_var_positional(command) else optional
            args.append(param)
            break
        optional.append(param)
        if param.kind is param.KEYWORD_ONLY:
            break
    return required, optional

def command_example(command, ctx):
    """Generate a working example given a command.
    If a command has optional arguments, it will generate two examples,
    one with required arguments only and one with all arguments included.
    """
    qualified_names = list(all_qualified_names(command))
    required, optional = _split_params(command)

    def generate(parameters):
        resolved = ' '.join(_parameter_examples(parameters, ctx, command))
        return f'`{ctx.clean_prefix}{random.choice(qualified_names)} {resolved}`'

    usage = generate(required)
    if not optional:
        return usage
    joined = '\n'.join(generate(required + optional[:index+1]) for index in range(len(optional)))
    return f'{usage}\n{joined}'

# Peptide record (PEPREC) module
from typing import List, Optional
import pandas as pd

class PEPRECException(Exception):
    """Custom exception for invalid PEPREC files."""
    pass

class PeptideRecord:
    """Class representing a peptide record from a PEPREC file."""

    def __init__(
        self,
        filepath: Optional[str] = None,
        mode: str = "standard",
        additional_columns: Optional[List[str]] = None,
    ):
        """
        Initialize a PeptideRecord instance.

        Parameters
        ----------
        filepath : str, None
            Path to the PEPREC file. If provided, the file will be loaded automatically.
        mode : str
            Context mode for column validation. Supported values: "standard", "ms2rescore".
        additional_columns : List[str]
            Extra columns that should be considered during validation.
        """
        self.filepath = filepath
        self.mode = mode
        self.additional_columns = additional_columns
        self._dataframe = None

        if self.filepath is not None:
            self.load_from_csv(self.filepath)

    def __str__(self):
        """Return string representation of the underlying DataFrame."""
        return str(self._dataframe)

    @property
    def dataframe(self) -> Optional[pd.DataFrame]:
        """Access the internal DataFrame."""
        return self._dataframe

    @dataframe.setter
    def dataframe(self, df: Optional[pd.DataFrame]):
        """Set and validate the internal DataFrame."""
        if isinstance(df, pd.DataFrame):
            self._check_column_names(df)
        self._dataframe = df

    def load_from_csv(self, filepath: str, **kwargs):
        """Load PEPREC data from a CSV file."""
        self._validate_file_header(filepath)
        delimiter = self._detect_separator(filepath)
        self.dataframe = pd.read_csv(filepath, sep=delimiter, index_col=None, **kwargs)
        # Replace NaN in 'modifications' column with '-'
        self.dataframe["modifications"] = self.dataframe["modifications"].fillna("-")

    def save_to_csv(self, output_path: Optional[str] = None, **kwargs):
        """Save current DataFrame to a CSV file."""
        target_path = output_path or self.filepath
        if not target_path:
            raise ValueError("No output path specified and no stored filepath available.")

        self.dataframe.to_csv(
            target_path, 
            sep=" ", 
            index=False, 
            float_format="%.3f", 
            **kwargs
        )

    def reorder_fields(self):
        """Reorder DataFrame columns so canonical fields appear first."""
        current_cols = list(self.dataframe.columns)

        # Remove required columns from current list if present
        for field in self._mandatory_fields:
            if field in current_cols:
                current_cols.remove(field)
            else:
                self._mandatory_fields.remove(field)

        # Reconstruct column order: mandatory first, then others
        ordered_cols = self._mandatory_fields + current_cols
        self.dataframe = self.dataframe[ordered_cols]

    @property
    def _mandatory_fields(self):
        """Determine mandatory columns based on current mode."""
        mandatory = [
            "spec_id",
            "peptide",
            "modifications",
            "charge",
        ]

        if self.mode == "ms2rescore":
            mandatory.extend([
                "psm_score", 
                "observed_retention_time"
            ])
        elif self.mode == "retention_time":
            mandatory.remove("modifications")

        return mandatory

    def _validate_file_header(self, filepath: str):
        """Ensure the file header starts correctly."""
        with open(filepath, "r") as f:
            first_line = f.readline()
            if not first_line.startswith("spec_id"):
                raise PEPRECException("Invalid PEPREC header: must start with 'spec_id'")

    def _check_column_names(self, df: pd.DataFrame):
        """Verify all mandatory columns are present in the DataFrame."""
        for col in self._mandatory_fields:
            if col not in df.columns:
                raise PEPRECException(f"Missing required column: '{col}'")

    @classmethod
    def create_from_dataframe(cls, df: pd.DataFrame):
        """Create a PeptideRecord instance from an existing DataFrame."""
        instance = cls()
        instance.dataframe = df
        instance.reorder_fields()
        return instance

    @classmethod
    def load(cls, *args, **kwargs):
        """Alternative constructor to load from CSV file."""
        instance = cls()
        instance.load_from_csv(*args, **kwargs)
        return instance

    @staticmethod
    def _detect_separator(filepath: str) -> str:
        """Detect the separator used in the PEPREC file."""
        with open(filepath, "r") as f:
            first_line = f.readline()
            # Assuming 7th character is the separator after 'spec_id'
            return first_line[7] if len(first_line) > 7 else ","

