    The client provides all the transcription, usage, key management, and project management
    facilities. For example, to transcribe a pre-recorded file using the default API endpoint
    of api.deepgram.com:
    .. code-block::
        import asyncio
        import json
        import deepgram
        async def main():
            client = deepgram.Deepgram("your api key")
            with open ("path/to/file.wav", "rb") as audio:
                source = {"buffer": audio, "mimetype": "audio/wav"}
                options = {"punctuate": True}
                response = client.transcription.prerecorded(source, options)
                print(json.dumps(response, indent=4))
        asyncio.run(main())
    To use a self-hosted Deepgram API, specify the URL when then creating the client:
    .. code-block::
        client = deepgram.Deepgram({"api_key": "REDACTED_CREDENTIAL", "api_url": "https://your.endpoint.com/"})
    For details on transcription methods, refer to :class:`deepgram.transcription.Transcription`
    Args:
        options: The client configuration :class:`Options` or the Deepgram API key as a string.
    Raises:
        ValueError: If the Deepgram API URL is invalid or if the API key is missing.
    """
    def __init__(self, config: Union[str, Options]) -> None:
        if 'api_url' in config and not config.get('api_url'):
            raise ValueError("DG: API URL must be valid or omitted")
        t_config: Options = {'api_key': config} if isinstance(config, str) else config 
        if 'api_key' not in t_config:
            raise ValueError("DG: API key is required")
        self._config = t_config

    @property
    def keys(self) -> Keys:
        return Keys(self._config)

    @property
    def transcription(self) -> Transcription:
        return Transcription(self._config)

    @property
    def projects(self) -> Projects:
        return Projects(self._config)

    @property
    def usage(self) -> Usage:
        return Usage(self._config)

__all__ = [Deepgram]

# Seraphsix database interaction module
import logging
from datetime import timedelta
from seraphsix import constants
from seraphsix.tasks.parsing import member_hash
from seraphsix.models.database import (
    Member,
    Clan,
    ClanMember,
    GameMember,
    Game,
    ClanGame,
)
from urllib.parse import urlparse
from tortoise import Tortoise
from tortoise.exceptions import IntegrityError
from tortoise.functions import Lower
from tortoise.query_utils import Q
from tortoise import timezone

logger = logging.getLogger(__name__)

class DatabaseManager(object):
    def __init__(self, db_url, pool_size=constants.DB_MAX_CONNECTIONS):
        self.db_url = urlparse(db_url)
        self.pool_size = pool_size

    async def setup(self):
        await Tortoise.init(
            config={
                "connections": {
                    "default": {
                        "engine": "tortoise.backends.asyncpg",
                        "credentials": {
                            "host": self.db_url.hostname,
                            "port": self.db_url.port,
                            "user": self.db_url.username,
                            "password": <PASSWORD>,
                            "database": self.db_url.path[1:],
                            "max_size": self.pool_size,
                        },
                    }
                },
                "apps": {
                    "seraphsix": {
                        "models": ["seraphsix.models.database"],
                    }
                },
            }
        )

    async def find_member_by_platform(self, platform_member_id, platform_type):
        if platform_type == constants.PLATFORM_BUNGIE:
            query = Member.get_or_none(bungie_id=platform_member_id)
        elif platform_type == constants.PLATFORM_PSN:
            query = Member.get_or_none(psn_id=platform_member_id)
        elif platform_type == constants.PLATFORM_XBOX:
            query = Member.get_or_none(xbox_id=platform_member_id)
        elif platform_type == constants.PLATFORM_BLIZZARD:
            query = Member.get_or_none(blizzard_id=platform_member_id)
        elif platform_type == constants.PLATFORM_STEAM:
            query = Member.get_or_none(steam_id=platform_member_id)
        elif platform_type == constants.PLATFORM_STADIA:
            query = Member.get_or_none(stadia_id=platform_member_id)
        return await query

    async def find_member_by_username(self, username, include_clan_info=True):
        username = username.lower()
        if include_clan_info:
            member_db = (
                await ClanMember.annotate(
                    bungie_username_lo=Lower("member__bungie_username"),
                    xbox_username_lo=Lower("member__xbox_username"),
                    psn_username_lo=Lower("member__psn_username"),
                    blizzard_username_lo=Lower("member__blizzard_username"),
                    steam_username_lo=Lower("member__steam_username"),
                    stadia_username_lo=Lower("member__stadia_username"),
                )
                .get_or_none(
                    Q(bungie_username_lo=username)
                    | Q(xbox_username_lo=username)
                    | Q(psn_username_lo=username)
                    | Q(blizzard_username_lo=username)
                    | Q(steam_username_lo=username)
                    | Q(stadia_username_lo=username)
                )
                .prefetch_related("clan", "member")
            )
        else:
            member_db = await Member.annotate(
                bungie_username_lo=Lower("bungie_username"),
                xbox_username_lo=Lower("xbox_username"),
                psn_username_lo=Lower("psn_username"),
                blizzard_username_lo=Lower("blizzard_username"),
                steam_username_lo=Lower("steam_username"),
                stadia_username_lo=Lower("stadia_username"),
            ).get_or_none(
                Q(bungie_username_lo=username)
                | Q(xbox_username_lo=username)
                | Q(psn_username_lo=username)
                | Q(blizzard_username_lo=username)
                | Q(steam_username_lo=username)
                | Q(stadia_username_lo=username)
            )
        return member_db

    async def register_member_by_platform(self, display_name, membership_identifier, platform_type):
        # pylint: disable=assignment-from-no-return
        if platform_type == constants.PLATFORM_BUNGIE:
            member_query = Member.create(name=display_name, bungie_id=membership_identifier)
        elif platform_type == constants.PLATFORM_PSN:
            member_query = Member.create(name=display_name, psn_id=membership_identifier)
        elif platform_type == constants.PLATFORM_XBOX:
            member_query = Member.create(name=display_name, xbox_id=membership_identifier)
        elif platform_type == constants.PLATFORM_BLIZZARD:
            member_query = Member.create(name=display_name, blizzard_id=membership_identifier)
        elif platform_type == constants.PLATFORM_STEAM:
            member_query = Member.create(name=display_name, steam_id=membership_identifier)
        elif platform_type == constants.PLATFORM_STADIA:
            member_query = Member.create(name=display_name, stadia_id=membership_identifier)
        return await member_query

    async def find_member_by_platform_and_username(self, username, platform_type):
        username = username.lower()
        if platform_type == constants.PLATFORM_BUNGIE:
            username_field = "bungie_username"
        elif platform_type == constants.PLATFORM_PSN:
            username_field = "psn_username"
        elif platform_type == constants.PLATFORM_XBOX:
            username_field = "xbox_username"
        elif platform_type == constants.PLATFORM_BLIZZARD:
            username_field = "blizzard_username"
        elif platform_type == constants.PLATFORM_STEAM:
            username_field = "steam_username"
        elif platform_type == constants.PLATFORM_STADIA:
            username_field = "stadia_username"
        query = (
            await Member.annotate(name_lo=Lower(username_field))
            .get_or_none(name_lo=username)
            .prefetch_related("clans")
        )
        return query

    async def find_member_by_discord(self, discord_user_id, include_clan_info=True):
        if include_clan_info:
            query = ClanMember.get_or_none(
                member__discord_id=discord_user_id
            ).prefetch_related("member", "clan")
        else:
            query = Member.get_or_none(discord_id=discord_user_id)
        return await query

    async def fetch_clan_members(self, clan_identifiers):
        return await ClanMember.filter(clan__clan_id__in=clan_identifiers).prefetch_related(
            "member", "clan"
        )

    async def fetch_clan_members_by_server(self, server_id):
        return await ClanMember.filter(clan__guild__guild_id=server_id).prefetch_related(
            "member", "clan", "clan__guild"
        )

    async def find_clan_member_by_platform(self, platform_member_id, platform_type, clan_identifiers):
        if platform_type == constants.PLATFORM_PSN:
            query = ClanMember.get(clan_id__in=clan_identifiers, member__psn_id=platform_member_id)
        elif platform_type == constants.PLATFORM_XBOX:
            query = ClanMember.get(clan_id__in=clan_identifiers, member__xbox_id=platform_member_id)
        elif platform_type == constants.PLATFORM_BLIZZARD:
            query = ClanMember.get(clan_id__in=clan_identifiers, member__blizzard_id=platform_member_id)
        elif platform_type == constants.PLATFORM_STEAM:
            query = ClanMember.get(clan_id__in=clan_identifiers, member__steam_id=platform_member_id)
        elif platform_type == constants.PLATFORM_STADIA:
            query = ClanMember.get(clan_id__in=clan_identifiers, member__stadia_id=platform_member_id)
        return await query.prefetch_related("member")

    async def find_clans_by_server(self, server_id):
        return await Clan.filter(guild__guild_id=server_id).prefetch_related("guild")

    async def get_active_clan_members(self, clan_record, **time_kwargs):
        if not time_kwargs:
            time_kwargs = dict(hours=1)
        return await ClanMember.filter(
            last_active__gt=timezone.now() - timedelta(**time_kwargs), clan=clan_record
        ).prefetch_related("member")

    async def get_inactive_clan_members(self, clan_record, **time_kwargs):
        if not time_kwargs:
            time_kwargs = dict(days=30)
        return await ClanMember.filter(
            last_active__lt=timezone.now() - timedelta(**time_kwargs), clan=clan_record
        ).prefetch_related("member")

    async def store_game(self, game_data):
        result = None
        game_record, is_new = await Game.get_or_create(**vars(game_data))
        if is_new:
            logger.info(f"Game {game_data.instance_id} registered")
            result = game_record
        return result

    async def link_clan_to_game(self, game_record, game_data, clan_id):
        record_data = dict(clan_id=clan_id, game=game_record)
        _, is_new = await ClanGame.get_or_create(**record_data)
        if is_new:
            tasks = [
                self.register_player_in_game(player, game_record, clan_id)
                for player in game_data.clan_players
            ]
            await asyncio.gather(*tasks)

    async def register_player_in_game(self, player_data, game_record, clan_id, player_record=None):
        if not player_record:
            clanmember_record = await self.find_clan_member_by_platform(
                player_data.membership_id, player_data.membership_type, [clan_id]
            )
            player_record = clanmember_record.member
        try:
            # Register the game member
            await GameMember.create(
                member=player_record,
                game=game_record,
                completed=player_data.completed,
                time_played=player_data.time_played,
            )
        except IntegrityError:
            # Handle drop/re-join by updating existing record
            game_member_record = await GameMember.get(game=game_record, member=player_record)
            game_member_record.time_played += player_data.time_played
            if (
                not game_member_record.completed
                or game_member_record.completed != player_data.completed
            ):
                game_member_record.completed = player_data.completed
            await game_member_record.save()
        logger.info(
            f"Player {member_hash(player_data)} added to game id {game_record.instance_id}"
        )

    async def shutdown(self):
        await Tortoise.close_connections()

# Process JSON-LD data using resolution rules
from jsonlddb import JsonLDDatabase

def apply_resolution_rules(rules, database, tracked):
    for rule in rules:
        for item in database[rule['frame']]:
            if not tracked.get(rule['@id'], {}).get(item['@id'], False):
                database.insert(list(rule['function'](item)))
                if tracked.get(rule['@id']) is None:
                    tracked[rule['@id']] = {}
                tracked[rule['@id']][item['@id']] = True
    return database, tracked

def complete_jsonld_resolution(rules, data):
    database = JsonLDDatabase()
    database.insert(data)
    # Apply resolution iteratively until convergence
    tracked = {}
    prior_state = None
    while str(tracked) != prior_state:
        prior_state = str(tracked)
        database, tracked = apply_resolution_rules(rules, database, tracked)
    return database

