@app.route(const.INTERMEDIATE_API_AUTH0_USER_INFO_ENDPOINT, methods=["GET"])
@decorators.get_authentication
@decorators.endpoint_exception_handler
def retrieve_auth0_user_details(is_authenticated):
    """Retrieving user's permission details on initial access
    Simultaneously updating the users_permissions table to ensure
    the dashboard reflects current access rights.
    """
    if is_authenticated:
        app.logger.info(
            f"Received request at {const.INTERMEDIATE_API_AUTH0_USER_INFO_ENDPOINT}"
        )
        token = auth0.get_token_auth_header()
        unverified_claims = jwt.get_unverified_claims(token)
        user_identifier = unverified_claims["sub"].split("|")[1]
        access_permissions = unverified_claims["permissions"]
        # Refresh Users_Permissions table with latest data
        db.update_user_access_permission(user_identifier, access_permissions)
        return jsonify({"permissions": access_permissions, "id": user_identifier})
    raise auth0.AuthError()

