@app.route(const.INTERMEDIATE_API_CREATE_PROJECT_ENDPOINT, methods=["POST"])
@decorators.get_authentication
@decorators.endpoint_exception_handler
def generate_new_project(is_authenticated):
    """Creating new project(s)"""
    if is_authenticated and auth0.is_admin():
        app.logger.info(
            f"Received request at {const.INTERMEDIATE_API_CREATE_PROJECT_ENDPOINT}"
        )
        payload = json.loads(request.data.decode())
        # Use Display Name as Project ID when ID is missing
        if payload.get("id") is None or len(payload["id"].strip()) == 0:
            payload["id"] = payload["name"].lower().strip().replace(" ", "_")
        if db.is_project_in_db(payload["id"]):
            return (
                jsonify({"project_created": False, "reason": "Already exists"}),
                const.CONFLICT_CODE,
            )
        else:
            response_code = utils.proxy_to_api(
                request,
                const.PROJECT_CREATE_NEW_ENDPOINT,
                "POST",
                PROJECT_API_BASE,
                PROJECT_API_TOKEN,
                data=json.dumps(payload),
                user_id=auth0.get_user_id(),
                action="Project Creation - Triggering project generation",
            ).status_code
            if response_code == const.OK_CODE:
                db.add_project_to_db(payload["id"], payload["name"], payload["access_level"])
                return jsonify({"project_created": True}), const.OK_CODE
            else:
                return (
                    jsonify({"project_created": False}),
                    response_code,
                )
    raise auth0.AuthError()

# Modified version of TensorBoardLogger with renamed variables and reordered logic
from pathlib import Path
import datetime
import torch
import git
from inspect import signature
import os
import yaml

class TensorBoardLogger():
    def __init__(self, settings):
        self.disabled = settings.no_logging
        if settings.no_logging:
            print(f"Logging functionality is turned off")
            return

        timestamp = str(datetime.datetime.now().strftime('%Y-%m-%d_%H:%M:%S'))
        architecture_name = settings.model_type
        self.log_dir = Path(__file__).parent.absolute().parent / 'logs' / architecture_name / timestamp

        if not self.log_dir.exists():
            self.log_dir.mkdir(parents=True)

        self.setup_metadata_log(settings)
        self.writer = SummaryWriter(str(self.log_dir))

        self.top_metric_value = None
        self.best_model_loss = None
        self.best_model_path = None
        self.current_model_path = None
        self.intermediate_checkpoint = None

    def _skip_if_disabled(func):
        def wrapper(*args, **kwargs):
            instance = args[0]
            if instance.disabled:
                return
            return func(*args, **kwargs)
        return wrapper

    @_skip_if_disabled
    def setup_metadata_log(self, job_config):
        repository = git.Repo(search_parent_directories=True)
        config_dict = job_config.to_dict()
        self.metadata_path = self.log_dir / "metadata.yaml"
        self.metadata = {
            **config_dict,
            'git_commit_hash': repository.head.object.hexsha,
            'top_validation_metric': None,
            'optimal_model_file': None,
            'log_folder': str(self.log_dir),
            'Post-experiment notes': '*** Complete this section after training and evaluation ***',
        }
        with open(self.metadata_path, 'w') as file:
            yaml.safe_dump(self.metadata, file)

    @_skip_if_disabled
    def record_training_error(self, error):
        if not hasattr(self, 'train_step'):
            self.train_step = 0
        self.writer.add_scalar("Training Error", error, self.train_step)
        self.train_step += 1

    @_skip_if_disabled
    def record_validation_error(self, error):
        if not hasattr(self, 'val_step'):
            self.val_step = 0
        self.writer.add_scalar("Validation Error", error, self.val_step)
        self.val_step += 1

    @_skip_if_disabled
    def record_sampling_error(self, error):
        # This metric isn't used during training due to computational cost
        # but can be computed on a random subset post-epoch
        if not hasattr(self, 'sample_eval_step'):
            self.sample_eval_step = 0
        self.writer.add_scalar("Sample Error", error, self.sample_eval_step)
        self.sample_eval_step += 1

    @_skip_if_disabled
    def record_rollout_mse(self, mse):
        if not hasattr(self, 'rollout_mse_step'):
            self.rollout_mse_step = 0
        self.writer.add_scalar("Rollout MSE", mse, self.rollout_mse_step)
        self.rollout_mse_step += 1

    @_skip_if_disabled
    def log_model_graph(self, model, example_input):
        param_names = list(signature(model.forward).parameters.keys())
        param_names = [p for p in param_names if p not in ['args', 'kwargs']]
        inputs = [example_input[p] for p in param_names]
        self.writer.add_graph(model, inputs)

    @_skip_if_disabled
    def _checkpoint_save(self, current_epoch, checkpoint_path, network, optimizer, extra_info):
        torch.save(
            {
                'epoch': current_epoch,
                'model_state': network.state_dict(),
                'optimizer_state': optimizer.state_dict(),
                **extra_info,
            },
            checkpoint_path,
        )

    @_skip_if_disabled
    def save_current_model(self, epoch, progress, network, optimizer, additional_info):
        checkpoint_file = self.log_dir / f"model_ep_{epoch}_progress_{progress}.pth"
        self._checkpoint_save(epoch, checkpoint_file, network, optimizer, additional_info)

        if self.intermediate_checkpoint is not None:
            if (
                checkpoint_file != self.intermediate_checkpoint
                and os.path.exists(self.intermediate_checkpoint)
            ):
                os.remove(self.intermediate_checkpoint)
        self.intermediate_checkpoint = checkpoint_file

    @_skip_if_disabled
    def save_best_model(self, epoch, network, optimizer, extra_data, validation_score):
        """
        Saves models based on two strategies:
        - Every 10 epochs (0-9, 10-19, etc.), saves the latest model as a checkpoint
        - Otherwise, keeps track of the best model according to validation_score
        Parameters
        ----------
        epoch : Current epoch number
        network : Model to save
        optimizer : Optimizer state to save
        extra_data : Additional information to store
        validation_score : Score used to determine best model
        Returns
        -------
        None
        """
        model_path = self.log_dir / f"model_epoch_{epoch}.pth"

        if 'save_metric' in extra_data and extra_data['save_metric'] != validation_score:
            print(
                f"Logger detected mismatched metrics: "
                f"{extra_data['save_metric']} vs {validation_score}. "
                f"Using {validation_score}, former stored under 'discarded_save_metric'."
            )
            extra_data["discarded_save_metric"] = extra_data['save_metric']
        extra_data['save_metric'] = validation_score

        self._checkpoint_save(epoch, model_path, network, optimizer, extra_data)

        # Determine if this is a checkpoint epoch
        is_checkpoint = (epoch % 10 == 0)

        # Handle cleanup of old files
        if is_checkpoint:
            print(f"New checkpoint group initialized at: {model_path}")
        elif validation_score < self.best_model_loss:
            print(f"New best model saved to: {model_path}")
            if os.path.exists(self.best_model_path):
                os.remove(self.best_model_path)

        # Remove previous checkpoint if different from current best
        if (
            self.best_model_path is not None
            and self.current_model_path is not None
            and self.best_model_path.resolve() != self.current_model_path.resolve()
        ):
            if os.path.exists(self.current_model_path):
                os.remove(self.current_model_path)

        self.current_model_path = model_path

        # Update tracking variables
        if is_checkpoint or validation_score < self.best_model_loss:
            self.best_model_loss = validation_score
            self.best_model_path = self.log_dir / f"model_epoch_{epoch}.pth"
            self.current_model_path = self.best_model_path

        # Global best model tracking
        if self.top_metric_value is None or validation_score < self.top_metric_value:
            print(f"Updating global metadata with new optimal model: {self.metadata_path}")
            self.top_metric_value = validation_score
            self.metadata['top_validation_metric'] = str(validation_score)
            self.metadata['optimal_model_file'] = str(self.best_model_path)
            with open(self.metadata_path, 'w') as meta_file:
                yaml.safe_dump(self.metadata, meta_file)

import re
from collections import Counter
from redash.tasks.general import send_mail
from redash import redis_connection, settings, models
from redash.utils import json_dumps, json_loads, base_url, render_template
from redash.worker import get_job_logger

logger = get_job_logger(__name__)

def failure_key(user_identifier):
    return "aggregated_failures:{}".format(user_identifier)

def generate_comment(failure_data):
    scheduled_fail_count = failure_data.get("schedule_failures")
    if scheduled_fail_count > settings.MAX_FAILURE_REPORTS_PER_QUERY * 0.75:
        return """NOTICE: This query has failed a total of {schedule_failures} times.
        Reporting may stop when the query exceeds {max_failure_reports} overall failures.""".format(
            schedule_failures=scheduled_fail_count,
            max_failure_reports=settings.MAX_FAILURE_REPORTS_PER_QUERY,
        )

def broadcast_aggregated_errors():
    for key in redis_connection.scan_iter(failure_key("*")):
        user_id = re.search(r"\d+", key).group()
        dispatch_failure_report(user_id)

def dispatch_failure_report(user_identifier):
    user = models.User.get_by_id(user_identifier)
    error_list = [json_loads(e) for e in redis_connection.lrange(failure_key(user_identifier), 0, -1)]

    if error_list:
        error_list.reverse()
        occurrence_counts = Counter((err.get("id"), err.get("message")) for err in error_list)
        unique_error_map = {(err.get("id"), err.get("message")): err for err in error_list}

        context = {
            "failures": [
                {
                    "id": val.get("id"),
                    "name": val.get("name"),
                    "failed_at": val.get("failed_at"),
                    "failure_reason": val.get("message"),
                    "failure_count": occurrence_counts[key],
                    "comment": generate_comment(val),
                }
                for key, val in unique_error_map.items()
            ],
            "base_url": base_url(user.org),
        }

        subject = "Insights (by Unicommerce) failed to execute {} of your scheduled queries".format(
            len(unique_error_map.keys())
        )

        html_content, text_content = [
            render_template("emails/failures.{}".format(ext), context)
            for ext in ["html", "txt"]
        ]

        send_mail.delay([user.email], subject, html_content, text_content)

    redis_connection.delete(failure_key(user_identifier))

def report_scheduled_failure(error_message, target_query):
    is_email_enabled = target_query.org.get_setting("send_email_on_failed_scheduled_queries")
    threshold_exceeded = (
        target_query.schedule_failures >= settings.MAX_FAILURE_REPORTS_PER_QUERY
    )

    if is_email_enabled and not target_query.user.is_disabled and not threshold_exceeded:
        redis_connection.lpush(
            failure_key(target_query.user.id),
            json_dumps(
                {
                    "id": target_query.id,
                    "name": target_query.name,
                    "message": error_message,
                    "schedule_failures": target_query.schedule_failures,
                    "failed_at": datetime.datetime.utcnow().strftime(
                        "%B %d, %Y %I:%M%p UTC"
                    ),
                }
            ),
        )

def record_query_failure(query_obj, exception_details):
    logger.debug(exception_details)
    query_obj.schedule_failures += 1
    query_obj.skip_updated_at = True
    models.db.session.add(query_obj)
    models.db.session.commit()
    report_scheduled_failure(exception_details, query_obj)

# Calculate shortest paths and find minimum route using DFS
from sys import maxsize
from typing import Dict, List, Set, Tuple

def floyd_warshall(adj_matrix: List[List[int]]) -> List[List[int]]:
    distance = [[value for value in row] for row in adj_matrix]
    num_nodes = len(adj_matrix)
    for intermediate in range(num_nodes):
        for src in range(num_nodes):
            for dest in range(num_nodes):
                if (
                    distance[src][dest] < maxsize
                    and distance[src][intermediate] < maxsize
                    and distance[intermediate][dest] < maxsize
                ):
                    distance[src][dest] = min(
                        distance[src][dest], 
                        distance[src][intermediate] + distance[intermediate][dest]
                    )
    return distance

def create_adjacency_matrix(
    edges: Dict[Tuple[int, int], int], vertex_count: int
) -> List[List[int]]:
    matrix = [[maxsize for _ in range(vertex_count)] for _ in range(vertex_count)]
    for start, end in edges:
        matrix[start][end] = edges[start, end]
    return matrix

def dfs_route_search(
    current: int,
    destination: int,
    accumulated_cost: int,
    seen: Set[int],
    adjacency: List[List[int]],
    started: bool = False,
) -> int:
    # started flag prevents returning 0 when beginning at the same node as destination
    if current == destination and started:
        return accumulated_cost
    seen.add(current)
    min_distance = maxsize
    for neighbor, edge_weight in enumerate(adjacency[current]):
        if edge_weight < maxsize:
            min_distance = min(
                min_distance,
                dfs_route_search(
                    neighbor, 
                    destination, 
                    accumulated_cost + edge_weight, 
                    seen.copy(), 
                    adjacency, 
                    True
                ),
            )
    return min_distance

def compute_min_route(
    heights: Dict[int, int], connections: Dict[Tuple[int, int], int]
) -> int:
    adjacency = create_adjacency_matrix(connections, len(heights))
    shortest_paths = floyd_warshall(adjacency)
    return dfs_route_search(0, 0, 0, set(), shortest_paths)

