from typing import Callable, Iterable, Tuple
import pytest
from qemu_runner.argument import Argument
from qemu_runner.layer import Layer, GeneralSettings

# Define arguments for testing
ARG_A = Argument('device')
ARG_B = Argument('chardev')
ARG_C = Argument('chardev')

# Group of layer sets for equality testing
EQUAL_LAYER_GROUPS = [
    [lambda: Layer()],
    [lambda: Layer(general=GeneralSettings(engine='my-engine'))],
    [lambda: Layer(general=GeneralSettings(engine='my-engine2'))],
    [lambda: Layer(arguments=[Argument('device')])],
    [lambda: Layer(general=GeneralSettings(engine='my-engine'), arguments=[ARG_A])],
    [lambda: Layer(general=GeneralSettings(engine='my-engine'), arguments=[ARG_B])],
    [
        lambda: Layer(general=GeneralSettings(engine='my-engine'), arguments=[ARG_A, ARG_B]),
        lambda: Layer(general=GeneralSettings(engine='my-engine'), arguments=[ARG_B, ARG_A]),
    ],
    [
        lambda: Layer(general=GeneralSettings(engine='my-engine'), arguments=[ARG_A, ARG_B, ARG_C]),
        lambda: Layer(general=GeneralSettings(engine='my-engine'), arguments=[ARG_A, ARG_C, ARG_B]),
        lambda: Layer(general=GeneralSettings(engine='my-engine'), arguments=[ARG_C, ARG_A, ARG_B]),
    ],
]

LayerCreator = Callable[[], Layer]

def generate_equal_cases() -> Iterable[Tuple[LayerCreator, LayerCreator]]:
    for group in EQUAL_LAYER_GROUPS:
        group_len = len(group)
        if group_len == 1:
            yield group[0], group[0]
        elif group_len == 2:
            yield group[0], group[1]
        else:
            for first_idx in range(0, group_len):
                for second_idx in range(first_idx, group_len):
                    if first_idx != second_idx:
                        yield group[first_idx], group[second_idx]

def generate_unequal_cases() -> Iterable[Tuple[LayerCreator, LayerCreator]]:
    total_groups = len(EQUAL_LAYER_GROUPS)
    for idx_a in range(0, total_groups):
        for idx_b in range(idx_a + 1, total_groups):
            group_a = EQUAL_LAYER_GROUPS[idx_a]
            group_b = EQUAL_LAYER_GROUPS[idx_b]
            for creator_a in group_a:
                for creator_b in group_b:
                    yield creator_a, creator_b

@pytest.mark.parametrize(('layer_x', 'layer_y'), generate_equal_cases())
def test_layer_equality(layer_x: LayerCreator, layer_y: LayerCreator):
    instance_x = layer_x()
    instance_y = layer_y()
    assert id(instance_x) != id(instance_y)
    assert instance_x == instance_y
    assert instance_y == instance_x

@pytest.mark.parametrize(('layer_x', 'layer_y'), generate_unequal_cases())
def test_layer_inequality(layer_x: LayerCreator, layer_y: LayerCreator):
    instance_x = layer_x()
    instance_y = layer_y()
    assert id(instance_x) != id(instance_y)
    assert instance_x != instance_y
    assert instance_y != instance_x

