class Container:
    @staticmethod
    def from_dictionary(input_dict):
        instance = Container()
        instance.__dict__.update(input_dict)
        return instance

def fetch_default_value(data_obj, attribute_name, fallback_value):
    if hasattr(data_obj, attribute_name):
        value = getattr(data_obj, attribute_name)
        if value is not None:
            try:
                return type(fallback_value)(value)
            except Exception:
                return value
    return fallback_value

def extract_pagination_params(data_obj):
    if hasattr(data_obj, 'page') and (hasattr(data_obj, 'page_size') or hasattr(data_obj, 'pageSize')):
        current_page = int(getattr(data_obj, 'page') or 0)
        items_per_page = int(getattr(data_obj, 'page_size') or getattr(data_obj, 'pageSize') or 1)
        start_index = max(current_page - 1, 0) * items_per_page
        return start_index, items_per_page

    if hasattr(data_obj, 'offset') and hasattr(data_obj, 'limit'):
        start_offset = int(getattr(data_obj, 'offset') or 0)
        max_results = int(getattr(data_obj, 'limit') or 1)
        return start_offset, max_results

    elif hasattr(data_obj, 'limit'):
        max_results = int(getattr(data_obj, 'limit') or 1)
        return 0, max_results

    return 0, 1

