import torch
import torch.nn as nn
import torch.nn.functional as F
from typing import Union, List, Tuple, Optional, Callable
import math
from .padding import get_padding, pad_same, is_static_pad, get_same_padding

def conv2d_same_wrapper(
        input_tensor, 
        weight_matrix: torch.Tensor, 
        bias_vector: Optional[torch.Tensor] = None, 
        stride_size: Tuple[int, int] = (1, 1),
        padding_size: Tuple[int, int] = (0, 0), 
        dilation_rate: Tuple[int, int] = (1, 1), 
        num_groups: int = 1):
    input_tensor = pad_same(input_tensor, weight_matrix.shape[-2:], stride_size, dilation_rate)
    return F.conv2d(input_tensor, weight_matrix, bias_vector, stride_size, (0, 0), dilation_rate, num_groups)

class Convolution2DSame(nn.Conv2d):
    """ PyTorch implementation of TensorFlow's 'SAME' padding for 2D convolutions """

    def __init__(self, input_features, output_features, filter_size, 
                 step_size=1, pad_value=0, dilate_factor=1, 
                 group_count=1, use_bias=True):
        super(Convolution2DSame, self).__init__(
            input_features, output_features, filter_size, step_size, 0, dilate_factor, group_count, use_bias)
        self.is_initialized = False

    def forward(self, x):
        if not self.is_initialized:
            self.setup(x)
        x = self.padding_module(x)
        return self.conv2d_forward(x, self.weight)

    @torch.jit.unused
    def setup(self, x):
        # Assume module always receives same input dimensions
        height_in, width_in = x.size()[-2:]
        kernel_h, kernel_w = self.weight.shape[-2:]
        stride_h, stride_w = self.stride
        dilation_h, dilation_w = self.dilation

        pad_height = get_same_padding(height_in, kernel_h, stride_h, dilation_h)
        pad_width = get_same_padding(width_in, kernel_w, stride_w, dilation_w)

        self.padding_module = nn.ZeroPad2d((
            pad_width // 2, 
            pad_width - pad_width // 2, 
            pad_height // 2, 
            pad_height - pad_height // 2
        ))
        self.is_initialized = True

def calculate_padding(padding_mode, kernel_dim, **extra_kwargs) -> Tuple[Tuple, bool]:
    uses_dynamic_padding = False

    if isinstance(padding_mode, str):
        padding_mode = padding_mode.lower()

        if padding_mode == 'same':
            if is_static_pad(kernel_dim, **extra_kwargs):
                # Static padding case - no additional overhead
                calculated_padding = get_padding(kernel_dim, **extra_kwargs)
            else:
                # Dynamic 'SAME' padding requires runtime computation
                calculated_padding = 0
                uses_dynamic_padding = True

        elif padding_mode == 'valid':
            calculated_padding = 0

        else:
            # Default to symmetric padding similar to PyTorch's behavior
            calculated_padding = get_padding(kernel_dim, **extra_kwargs)

    else:
        calculated_padding = padding_mode

    return calculated_padding, uses_dynamic_padding

def make_conv2d_with_padding(input_channels, output_channels, kernel_dims, **config):
    padding_config = config.pop('padding', '')
    config.setdefault('bias', False)

    padding_value, uses_dynamic = calculate_padding(padding_config, kernel_dims, **config)

    if uses_dynamic:
        return Convolution2DSame(input_channels, output_channels, kernel_dims, **config)
    else:
        return nn.Conv2d(input_channels, output_channels, kernel_dims, padding=padding_value, **config)

