# Calculate top concepts based on value thresholds
@outputSchema("out: bag{t: tuple(cpt: int, val: int)}")
def top_concepts(concept_vector):
    mapping = dict((concept, float(value)) for (concept, value) in concept_vector)
    highest_value = max(mapping.values())
    cutoff = sum(mapping.values()) * 0.2
    result = [(concept, value) for (concept, value) in concept_vector if value == highest_value or float(value) > cutoff]
    return result

# Generate successive chunks of specified size from a list
def partition_list(items, chunk_size):
    for index in xrange(0, len(items), chunk_size):
        yield items[index:index+chunk_size]

@outputSchema("out: bag{t1: tuple(b: bag{ t2: tuple(cpt: int, val: int)})}")
def split_large_bag(input_bag, partition_size):
    result_bag = []
    for segment in partition_list(input_bag, partition_size):
        result_bag.append(list(segment))
    return result_bag

# Determine cosine similarity between a source NPI and each NPI in the target collection, returning those above threshold
@outputSchema("out: bag{t: tuple(npi: chararray) }")
def find_similar_npi(source_npi, source_cpts, target_collection, min_similarity):
    matching_npis = []
    source_dict = dict((cpt, float(val)) for (cpt, val) in source_cpts)
    source_magnitude = math.sqrt(sum(val*val for (_, val) in source_cpts))

    for (target_npi, target_cpts) in target_collection:
        if source_npi > target_npi:
            target_magnitude = math.sqrt(sum(val*val for (_, val) in target_cpts))
            common_dot = sum(source_dict[cpt]*val for (cpt, val) in target_cpts if cpt in source_dict)
            overlap_count = sum(1 for (cpt, val) in target_cpts if cpt in source_dict)
            similarity = common_dot / (source_magnitude * target_magnitude)

            if similarity > min_similarity and overlap_count >= 2:
                matching_npis.append((target_npi,))

    return matching_npis

