# MCTS implementation for Schnapsen game
import abc
import copy
import logging
import math
import pprint
import random
from typing import Dict, List, Optional, Generic, TypeVar, Type, Tuple
from model.game_state import GameState
from model.player_action import get_available_actions, PlayerAction
from model.player_id import PlayerId
from model.player_pair import PlayerPair

_TERMINAL_PLAYER = PlayerId.ONE

def ucb_value(node: "MctsNode", target_player: PlayerId):
    return node.ucb if node.current_player == target_player else -node.ucb

_StateType = TypeVar("_StateType")
_ActionType = TypeVar("_ActionType")

class MctsNode(abc.ABC, Generic[_StateType, _ActionType]):
    """Generic class representing a node in an MCTS tree."""

    def __init__(self, current_state: _StateType, parent_node: Optional["MctsNode"]):
        self.state = current_state
        self.parent = parent_node
        self.children_map: Optional[Dict[_ActionType, "MctsNode"]] = None
        self.available_moves: Optional[List[_ActionType]] = None
        self.total_value = 0
        self.visit_count = 0
        self.ucb = None
        self.exploration_bonus = 0
        self.is_complete = False

        if not self.is_terminal:
            possible_actions = self._list_possible_actions()
            self.children_map = {move: None for move in possible_actions}
            self.available_moves = possible_actions
        else:
            final_scores = self._compute_final_score()
            other_player = _TERMINAL_PLAYER.opponent()
            self.ucb = final_scores[_TERMINAL_PLAYER] - final_scores[other_player]
            self.is_complete = True

    @property
    @abc.abstractmethod
    def is_terminal(self) -> bool:
        """Returns True if this node represents a terminal game state."""

    @abc.abstractmethod
    def _list_possible_actions(self) -> List[_ActionType]:
        """
        This method must return the actions available to the current player in the
        game state represented by this node. It is only called for non-terminal
        nodes.
        """

    @abc.abstractmethod
    def _compute_final_score(self) -> PlayerPair[float]:
        """
        This method must return the score for each player. It is only called for
        terminal nodes.
        """

    @abc.abstractmethod
    def _get_active_player(self) -> PlayerId:
        """
        Returns the ID of the player that has to make a move in the game state
        represented by this node.
        """

    @property
    def current_player(self) -> PlayerId:
        if self.is_terminal:
            return _TERMINAL_PLAYER
        return self._get_active_player()

    @property
    def is_fully_expanded(self) -> bool:
        """Return True if all the children of this node were created."""
        return self.is_terminal or len(self.available_moves) == 0

    def expand_node(self) -> "MctsNode":
        """
        Expands the current node by adding a new child for one of the actions that
        were not already explored. It cannot be called for fully expanded nodes.
        It returns the newly created node.
        """
        assert not self.is_fully_expanded
        selected_move = random.choice(self.available_moves)
        next_state = self._apply_action(selected_move)
        child_node = self.__class__(next_state, self)
        self.children_map[selected_move] = child_node
        self.available_moves.remove(selected_move)
        return child_node

    @abc.abstractmethod
    def _apply_action(self, move: _ActionType) -> _StateType:
        """
        This method should return the state obtained by playing the given action in
        the game state represented by this node.
        """

    def update_ucb_values(self, exploration_constant: float):
        if self.children_map is None:
            return
        for child_node in self.children_map.values():
            if child_node is not None:
                child_node.update_ucb(exploration_constant)

    def update_ucb(self, exploration_constant: float):
        if self.is_terminal or self.is_complete:
            return
        active_children_count = len(
            [child for child in self.children_map.values() if
             child is None or not child.is_complete])
        if active_children_count > 0:
            self.ucb = self.total_value / self.visit_count
            self.exploration_bonus = exploration_constant * math.sqrt(
                2 * math.log(self.parent.visit_count) / self.visit_count)
        else:
            child_ucb_values = [ucb_value(child, self.current_player) for child in
                               self.children_map.values() if child is not None]
            self.ucb = max(child_ucb_values)
            self.is_complete = True

    def get_best_children(self) -> List[Tuple["MctsNode", _ActionType]]:
        children_with_ucbs = \
            [(ucb_value(child, self.current_player), child, action)
             for action, child in self.children_map.items() if child is not None]
        if len(children_with_ucbs) == 0:
            # TODO(mcts): Find out why this happens.
            logging.error("MctsAlgorithm: All children are None: %s",
                          pprint.pformat(self.children_map, indent=True))
            return [(child, action) for action, child in self.children_map.items()]
        highest_ucb = max([ucb for ucb, child, action in children_with_ucbs])
        return [(child, action) for ucb, child, action in children_with_ucbs if
                ucb == highest_ucb]

    def get_best_moves(self) -> List[_ActionType]:
        return [action for child, action in self.get_best_children()]

    def __repr__(self):
        return f"Value:{self.total_value}, Visits:{self.visit_count}, UCB({self.current_player}):{self.ucb} " + \
               f"Complete:{self.is_complete}"

class SchnapsenMctsNode(MctsNode[GameState, PlayerAction]):
    """Implementation of the MctsNode class for the game of Schnapsen."""

    @property
    def is_terminal(self) -> bool:
        return self.state.is_game_over

    def _list_possible_actions(self) -> List[PlayerAction]:
        assert not self.is_terminal
        return get_available_actions(self.state)

    def _compute_final_score(self) -> PlayerPair[float]:
        assert self.is_terminal
        points = self.state.game_points
        points.one /= 3
        points.two /= 3
        return points

    def _get_active_player(self) -> PlayerId:
        return self.state.next_player

    def _apply_action(self, move: PlayerAction) -> GameState:
        return move.execute(self.state)

def debug_tree(node: MctsNode, level: int = 1):
    if node is None:
        print("None")
        return
    print(f"{node.current_player.name}: {node}", end="")
    if node.children_map is None:
        print(f" [points: {node.state.trick_points} {node.state.game_points}]")
        return
    print()
    for move, child in node.children_map.items():
        print("\t" * level, end="")
        print(f"{move}", end="")
        debug_tree(child, level + 1)

class MctsAlgorithm(Generic[_StateType, _ActionType]):
    def __init__(self, agent_player: PlayerId,
                 node_type: Type[MctsNode[_StateType, _ActionType]] = SchnapsenMctsNode,
                 exploration_rate: float = 0):
        self._agent_id = agent_player
        self._node_type = node_type
        self._max_iterations = None
        self._exploration_rate = exploration_rate

    def construct_tree(self, initial_state: _StateType,
                       iteration_limit: Optional[int] = None,
                       choose_best_child: bool = False) -> MctsNode[
        _StateType, _ActionType]:
        assert iteration_limit is None or iteration_limit > 0, \
            "iteration_limit must be positive"
        if isinstance(initial_state, GameState):
            state_copy = initial_state.deep_copy()
        else:
            state_copy = copy.deepcopy(initial_state)
        root_node = self._node_type(state_copy, None)
        iterations = 0
        while True:
            iterations += 1
            if self.perform_one_iteration(root_node, choose_best_child):
                break
            if iteration_limit is not None and iterations >= iteration_limit:
                break
        logging.info("MctsAlgorithm: Run %s iterations", iterations)
        # if len(state.cards_in_hand.one) <= 2:
        #   debug_print(root_node, 0)
        return root_node

    def perform_one_iteration(self, root: MctsNode,
                              choose_best_child: bool = False) -> bool:
        """Returns True if the entire game tree is already constructed."""
        selected_node = MctsAlgorithm._select_node(root, choose_best_child)
        if selected_node is None:
            return True
        terminal_node = MctsAlgorithm._expand_to_leaf(selected_node)
        self._propagate_up(terminal_node, terminal_node.ucb)
        return False

    @staticmethod
    def _select_node(node: MctsNode, choose_best_child: bool) -> Optional[MctsNode]:
        while not node.is_terminal:
            if not node.is_fully_expanded:
                return node
            incomplete_children = [child for child in
                                   node.children_map.values() if
                                   not child.is_complete]
            if len(incomplete_children) == 0:
                # This can only happen once we expanded the whole game tree.
                return None
            if choose_best_child:
                children_with_scores = \
                    [(child, ucb_value(child, node.current_player) + child.exploration_bonus)
                     for child in incomplete_children]
                max_score = max(
                    score for _, score in children_with_scores)
                top_children = [child for child, score in children_with_scores
                                if score == max_score]
                node = random.choice(top_children)
            else:
                node = random.choice(incomplete_children)
        raise Exception("Should not reach this code")  # pragma: no cover

    @staticmethod
    def _expand_to_leaf(node: MctsNode) -> MctsNode:
        while not node.is_terminal:
            assert not node.is_fully_expanded
            node = node.expand_node()
        return node

    def _propagate_up(self, node: MctsNode, score: float):
        while node is not None:
            if not node.is_terminal:
                node.visit_count += 1
                node.total_value += score if node.current_player == _TERMINAL_PLAYER else -score
                node.update_ucb_values(self._exploration_rate)
            node = node.parent

