    Batch,
    resolver,
    relationship,
)

@pytest.fixture(scope='function')
def app():
    return ravel.Application().bootstrap()

@fixture(scope='function')
def TreeStructure(app):
    class TreeStructure(Resource):
        parent_id = ravel.Id(lambda: TreeStructure, nullable=True, default=lambda: None)
        root_id = ravel.Id(lambda: TreeStructure, nullable=True, default=lambda: None)
        name = ravel.String(nullable=False, required=True)

        @resolver(target=lambda: TreeStructure.Batch)
        def children(self, request) -> 'TreeStructure.Batch':
            return Query(request=request).where(
                TreeStructure.parent_id == self._id
            ).execute()

        @resolver(target=lambda: TreeStructure)
        def parent(self, request) -> 'TreeStructure':
            return Query(request=request).where(
                TreeStructure._id == self.parent_id
            ).execute(first=True)

        @resolver(target=lambda: TreeStructure)
        def root_node(self, request) -> 'TreeStructure':
            return Query(request=request).where(
                TreeStructure._id == self.root_id
            ).execute(first=True)

        @classmethod
        def balanced_tree_factory(cls, levels=0) -> 'TreeStructure':
            def generate_subtree(parent, current_level):
                if current_level > 0:
                    offspring = cls.Batch.generate(
                        values={
                            'parent_id': parent._id,
                            'root_id': parent.root_id,
                        },
                        count=2,
                    ).save()
                    for subtree in offspring:
                        generate_subtree(subtree, current_level - 1)

            base = cls(name='root', parent_id=None)
            base.root_id = base._id
            base.save()
            generate_subtree(base, max(0, levels))
            return base

    app.bind(TreeStructure)
    return TreeStructure

