        part1.set_content_disposition(
            "attachment", name="data-graph-file", filename=data_file
        )
        part2 = writer.append(open(shapes_file, "rb"))
        part2.set_content_disposition(
            "attachment", name="shapes-graph-file", filename=shapes_file
        )
        part3 = writer.append(open(ontology_file, "rb"))
        part3.set_content_disposition(
            "attachment", name="ontology-graph-file", filename=ontology_file
        )

    async with ClientSession() as session:
        async with session.post(service_url, data=writer) as response:
            response_body = await response.text()

    assert response.status == 200
    assert "text/turtle" in response.headers[hdrs.CONTENT_TYPE]

    # Expected validation report
    expected_report = """
    @prefix sh: <http://www.w3.org/ns/shacl#> .
    @prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
    [] a sh:ValidationReport ;
         sh:conforms true
         .
    """

    with open(data_file, "r") as f:
        input_text = f.read()

    # Construct graphs for comparison
    g_input = Graph().parse(data=input_text, format="text/turtle")
    g_expected = g_input + Graph().parse(data=expected_report, format="turtle")
    g_actual = Graph().parse(data=response_body, format="text/turtle")

    is_iso = isomorphic(g_expected, g_actual)
    if not is_iso:
        _dump_diff(g_expected, g_actual)
    assert is_iso, "results_graph is incorrect"


