async def test_validator_with_not_valid_file(http_service: Any) -> None:
    """Should return OK and unsuccessful validation."""
    service_url = f"{http_service}/validator"
    data_file = "tests/files/invalid_catalog.ttl"
    shapes_file = "tests/files/mock_dcat-ap-no-shacl_shapes_2.00.ttl"
    ontology_file = "tests/files/ontologies.ttl"

    with MultipartWriter("mixed") as writer:
        part1 = writer.append(open(data_file, "rb"))
        part1.set_content_disposition(
            "attachment", name="data-graph-file", filename=data_file
        )
        part2 = writer.append(open(shapes_file, "rb"))
        part2.set_content_disposition(
            "attachment", name="shapes-graph-file", filename=shapes_file
        )
        part3 = writer.append(open(ontology_file, "rb"))
        part3.set_content_disposition(
            "attachment", name="ontology-graph-file", filename=ontology_file
        )

    async with ClientSession() as session:
        async with session.post(service_url, data=writer) as response:
            response_body = await response.text()

    assert response.status == 200
    assert "text/turtle" in response.headers[hdrs.CONTENT_TYPE]

    expected_report = """
    @prefix sh: <http://www.w3.org/ns/shacl#> .
    @prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
    [] a sh:ValidationReport ;
        sh:conforms false ;
        sh:result [ a sh:ValidationResult ;
                sh:focusNode <http://dataset-publisher:8080/datasets/1> ;
                sh:resultMessage "Less than 1 values on <http://dataset-publisher:8080/datasets/1>->dcat:theme" ;
                sh:resultPath <http://www.w3.org/ns/dcat#theme> ;
                sh:resultSeverity sh:Violation ;
                sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
                sh:sourceShape [ sh:class <http://www.w3.org/2004/02/skos/core#Concept> ;
                        sh:minCount 1 ;
                        sh:path <http://www.w3.org/ns/dcat#theme> ;
                        sh:severity sh:Violation ] ],
            [ a sh:ValidationResult ;
                sh:focusNode <http://dataset-publisher:8080/datasets/1> ;
                sh:resultMessage "Less than 1 values on <http://dataset-publisher:8080/datasets/1>->dct:description" ;
                sh:resultPath <http://purl.org/dc/terms/description> ;
                sh:resultSeverity sh:Violation ;
                sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
                sh:sourceShape [ sh:minCount 1 ;
                        sh:nodeKind sh:Literal ;
                        sh:path <http://purl.org/dc/terms/description> ;
                        sh:severity sh:Violation ] ],
            [ a sh:ValidationResult ;
                sh:focusNode <http://dataset-publisher:8080/datasets/1> ;
                sh:resultMessage "Data-themes fra EU skal brukes for dcat:theme"@nb ;
                sh:resultPath <http://www.w3.org/ns/dcat#theme> ;
                sh:resultSeverity sh:Warning ;
                sh:sourceConstraintComponent sh:QualifiedMinCountConstraintComponent ;
                sh:sourceShape [ sh:message "Data-themes fra EU skal brukes for dcat:theme"@nb ;
                        sh:path <http://www.w3.org/ns/dcat#theme> ;
                        sh:qualifiedMinCount 1 ;
                        sh:qualifiedValueShape [ sh:node <https://data.norge.no/specification/dcat-ap-no/#DataThemeRestriction> ] ;
                        sh:severity sh:Warning ] ]
    .
    """

    with open(data_file, "r") as f:
        input_text = f.read()

    g_input = Graph().parse(data=input_text, format="text/turtle")
    g_expected = g_input + Graph().parse(data=expected_report, format="text/turtle")
    g_actual = Graph().parse(data=response_body, format="text/turtle")

    is_iso = isomorphic(g_expected, g_actual)
    if not is_iso:
        _dump_diff(g_expected, g_actual)
    assert is_iso, "results_graph is incorrect"


def _dump_diff(g1: Graph, g2: Graph) -> None:
    common, only_g1, only_g2 = graph_diff(g1, g2)
    print("\nin both:")
    _dump_turtle(common)
    print("\nonly in first:")
    _dump_turtle(only_g1)
    print("\nonly in second:")
    _dump_turtle(only_g2)


def _dump_turtle(graph: Graph) -> None:
    for line in graph.serialize(format="text/turtle").splitlines():
        if line.strip():
            print(line)

# Generate bytecode modules for benchmarks
import subprocess
import configuration

IREE_TRANSLATE_PATH = "build-host/iree/tools/iree-translate"

def execute() -> None:
  for benchmark in configuration.MODEL_BENCHMARKS:
    for device in benchmark.phones:
      for target_device in device.targets:
        module_filename = configuration.get_module_name(benchmark.name,
                                                        device.name, target_device.mako_tag)
        print(f"Creating {module_filename} ...")
        subprocess.run(args=[
            IREE_TRANSLATE_PATH, benchmark.model_path,
            "--iree-mlir-to-vm-bytecode-module",
            f"--iree-hal-target-backends={target_device.hal_target_backend}", "-o",
            module_filename
        ] + target_device.compilation_flags,
                       check=True)

if __name__ == "__main__":
  execute()

