# Import necessary modules for file operations and type hints
import os
import glob
from typing import List, Tuple
from macuitest.lib.operating_system.env import env

class CrashReporter:
    def __init__(self, command_runner):
        self.command_runner = command_runner

    def distribute_reports(self, log_handler, crash_files: List[str]):
        for file_path in crash_files:
            self.__handle_crash_file(log_handler, file_path)

    def __handle_crash_file(self, log_handler, file_path: str):
        filename = os.path.basename(file_path)
        self.command_runner.sudo(f'chmod 755 "{file_path}"')
        with open(file_path) as file_obj:
            log_handler.error(
                filename,
                extra=dict(
                    attachment={
                        "name": filename,
                        "data": file_obj.read(),
                        "mime": "application/octet-stream",
                    }
                ),
            )

    def store_and_remove_reports(self, patterns: Tuple[str], destination: str):
        for report in self.gather_reports(patterns):
            self.command_runner.execute(f'cp "{report}" "{destination}"')
            self.command_runner.sudo(f'rm "{report}"')

    @staticmethod
    def gather_reports(patterns: Tuple[str, ...]) -> List[str]:
        """Gather crash reports based on glob patterns across diagnostic directories."""
        collected_reports = []
        for directory in (env.user_diag_reports, env.system_diag_reports):
            for pattern in patterns:
                for report_path in glob.glob(f"{directory}/{pattern}"):
                    collected_reports.append(report_path)
        return collected_reports

