from __future__ import absolute_import, division, unicode_literals
import re

def is_sequence_like(obj:'Any')->bool:
    """check if `obj` behaves like a sequence"""
    return isinstance(obj, (tuple, list, set))

def level_filter(
        data_stream:'Iterable[record]',
        filter_level:'Union[int, Sequence[int]]')->'Iterable[record]':
    """filter records based on their level attribute"""
    selected_levels = filter_level if is_sequence_like(filter_level) else (filter_level, )
    selected_levels = list(map(int, selected_levels))
    return filter(lambda item: item.level in selected_levels, data_stream)

def thread_filter(
        data_stream:'Iterable[record]',
        filter_thread:'Union[int, Sequence[int]]')->'Iterable[record]':
    """filter records by their thread identifier"""
    selected_threads = filter_thread if is_sequence_like(filter_thread) else (filter_thread, )
    selected_threads = list(map(int, selected_threads))
    return filter(lambda item: item.thread_id in selected_threads, data_stream)

def filename_filter(
        data_stream:'Iterable[record]', pattern:str)->'Iterable[record]':
    """filter records by matching filename against a regex pattern"""
    compiled_regex = re.compile(pattern)
    return filter(lambda item: compiled_regex.fullmatch(item.filename), data_stream)

