"""This module implements a modifier plugin for filtering."""
import re
import click
from swak.plugin import Modifier

def compile_patterns(patterns):
    """Merge and compile the provided patterns, returning the compiled dictionary."""
    merged = {}
    for key, regex in patterns:
        merged[key] = regex
    compiled = {}
    for key, regex in merged.items():
        compiled[key] = re.compile(regex)
    return compiled

class Filter(Modifier):
    """Filter class for data filtering based on regular expressions."""

    def __init__(self, include_list=[], exclude_list=[]):
        """Initialize the filter with include and exclude patterns.

        Args:
            include_list (list): List of (key, regex) tuples to include
            exclude_list (list): List of (key, regex) tuples to exclude
        """
        self.include_patterns = compile_patterns(include_list)
        self.exclude_patterns = compile_patterns(exclude_list)

    def modify(self, tag, timestamp, data_record):
        """Apply filtering logic to the given record.

        Exclusion rules take precedence over inclusion rules.
        To be excluded: at least one exclusion pattern must match.
        To be included: all inclusion patterns must match, and no exclusions apply.

        Args:
            tag (str): Data tag
            timestamp (float): Event timestamp
            data_record (dict): Data record to filter

        Returns:
            If included: tuple (timestamp, data_record)
            If excluded: None
        """
        # If no filters are defined, pass through unchanged
        if not self.include_patterns and not self.exclude_patterns:
            return timestamp, data_record

        # Check exclusion patterns first
        for field_name, pattern in self.exclude_patterns.items():
            if field_name in data_record:
                if pattern.search(data_record[field_name]) is not None:
                    return None

        # Check inclusion patterns
        for field_name, pattern in self.include_patterns.items():
            if field_name not in data_record:
                return None
            if pattern.search(data_record[field_name]) is None:
                return None

        return timestamp, data_record

@click.command(help="Filter data records using regular expression patterns.")
@click.option('-i', '--include', nargs=2, type=str, multiple=True,
              help="Specify key and regex pattern to include matching records.")
@click.option('-x', '--exclude', nargs=2, type=str, multiple=True,
              help="Specify key and regex pattern to exclude matching records.")
@click.pass_context
def main(ctx, include, exclude):
    """Plugin entry point that creates and returns a Filter instance."""
    return Filter(list(include), list(exclude))

if __name__ == '__main__':
    main()

