class Gizo:
    def __init__(self, endpoint: str = None, config_file: str = None):
        self.__dispatcher_obj: Dispatcher = None
        self.__rpc_client: hprose.HproseHttpClient = None
        self.__config_path: str = None
        self.__credentials: dict = None

        if config_file is None:
            self.__config_path = ".gizo"
        else:
            self.__config_path = config_file    

        if path.isfile(self.__config_path):
            try:
                self.__load_configuration()
                r = requests.get(self.__dispatcher_obj.status(), timeout=0.5)
                self.__rpc_client = self.__establish_connection(self.__dispatcher_obj)
            except Exception:
                self.__dispatcher_obj = None
                self.__discover_dispatcher()
                self.__save_configuration()

        else:
            if endpoint != None:
                try:
                    self.__dispatcher_obj = Dispatcher(endpoint)
                    self.__rpc_client = self.__establish_connection(self.__dispatcher_obj)
                    self.__credentials = self.generate_keypair()
                    self.__save_configuration()
                except Exception as err:
                    print(str(err))
                    sys.exit(1)
            else:
                self.__discover_dispatcher()
                self.__credentials = self.generate_keypair()
                self.__save_configuration()

    def __load_configuration(self):
        with open(self.__config_path, "r") as cfg_file:
            data = json.loads(cfg_file.read())
        self.__dispatcher_obj = Dispatcher(data["dispatcher"])
        self.__credentials = data["keys"]

    def __save_configuration(self):
        temp_data: dict = {}
        temp_data["dispatcher"] = self.__dispatcher_obj.url
        temp_data["keys"] = self.__credentials
        with open(self.__config_path, "w+") as cfg_file:
            cfg_file.write(json.dumps(temp_data))

    def __discover_dispatcher(self):
        r = requests.get(f"{CENTRUM}/v1/dispatchers")
        if r.status_code == 200:
            dispatcher_list = r.json()
            for dispatcher_url in dispatcher_list:
                try:
                    temp_dispatcher = Dispatcher(dispatcher_url)
                    self.__rpc_client = self.__establish_connection(temp_dispatcher)
                    self.__dispatcher_obj = temp_dispatcher                
                    break
                except Exception:
                    continue
            if self.__dispatcher_obj is None:
                raise Exception("no dispatchers available")   
        else:
            raise Exception("unable to connect to centrum")

