# Authenticator module for OneLogin MFA operations
import time
from datetime import datetime, timedelta
from typing import List, Optional
from onelogin.api.models.user import User
from onelogin.api.models.otp_device import OTP_Device
from onelogin.api.models.factor_enrollment_response import FactorEnrollmentResponse
from onelogin.api.client import OneLoginClient
from .exceptions import FactorNotFound, OneLoginClientError, APIResponseError, UserNotFound, TimeOutError

class MFAAuthenticator:
    PUSH_POLL_INTERVAL = 5  # seconds
    PUSH_REQUEST_TIMEOUT = 60   # seconds

    def __init__(self, api_client_id: str, api_client_secret: str, region: str = "us", user_identifier: str = "username"):
        self._client_id = api_client_id
        self._client_secret = api_client_secret
        self._region = region
        self._user_attribute = user_identifier
        self._client = OneLoginClient(self._client_id, self._client_secret, self._region)
        self._validate_connection()

    def _validate_connection(self) -> None:
        if self._client.get_access_token() is None:
            raise OneLoginClientError(self._client.error_description)

    def _fetch_user(self, username: str) -> User:
        query_params = {self._user_attribute: username, "fields": "id"}
        users = self._client.get_users(query_params)
        if users is None:
            raise APIResponseError(self._client.error_description)
        elif len(users) > 1:
            raise APIResponseError(f"Multiple users found for user: {username} using attribute: {self._user_attribute}")
        elif len(users) < 1:
            raise UserNotFound(f"No user found for user: {username} using attribute: {self._user_attribute}")
        return users.pop()

    def _obtain_default_factor(self, username: str) -> OTP_Device:
        factors = self.get_enrolled_factors(username)
        default_factor = next((factor for factor in factors if factor.default), None)
        if default_factor is None:
            raise FactorNotFound("No default MFA factor configured")
        return default_factor

    def _enable_factor(self, user_id: int, factor_id: int, validity_period: Optional[int] = None) -> FactorEnrollmentResponse:
        response = self._client.activate_factor(user_id, factor_id, expires_in=validity_period)
        if response is None:
            raise APIResponseError(self._client.error_description)
        return response

    def get_enrolled_factors(self, username: str) -> List[OTP_Device]:
        user = self._fetch_user(username)
        factors = self._client.get_enrolled_factors(user.id)
        if factors is None:
            raise APIResponseError(self._client.error_description)
        return factors

    def otp_authenticate(self, username: str, one_time_password: str, factor_id: Optional[int] = None) -> bool:
        user = self._fetch_user(username)
        factor_id = factor_id or self._obtain_default_factor(username).id
        return self._client.verify_factor(user.id, factor_id, one_time_password)

    def push_authenticate(self, username: str, factor_id: Optional[int] = None) -> bool:
        user = self._fetch_user(username)
        factor_id = factor_id or self._obtain_default_factor(username).id
        activation = self._enable_factor(user.id, factor_id, validity_period=self.PUSH_REQUEST_TIMEOUT)
        expiration_time = datetime.now() + timedelta(seconds=self.PUSH_REQUEST_TIMEOUT)

        while expiration_time > datetime.now():
            response = self._client.verify_factor_poll(user.id, activation.id)
            if response.status == "pending":
                time.sleep(self.PUSH_POLL_INTERVAL)
                continue
            elif response.status == "accepted":
                return True
            elif response.status == "rejected":
                return False
            else:
                raise APIResponseError(f"Unknown push verification status: {response.status}")

        raise TimeOutError("Push authentication request expired")

