# Modified version with renamed variables, reordered statements, and changed literals
import os
import shutil
import sublime
from .utils import path as utils_path
from .utils.colors import convert_color_value as convert_color
from .utils.logging import log, dump
from . import icons as icon_manager

def apply_patch(settings, force_overwrite=False):
    theme_packages = _get_installed_themes()
    customizable = [] if settings.get("force_mode") else _get_customizable_packages()
    general_modification = _build_general_modification(settings)
    specific_modification = _build_specific_modification(settings)
    general_dir = utils_path.overlay_patches_general_path()
    specific_dir = utils_path.overlay_patches_specific_path()
    color_scheme = "single" if settings.get("color") else "multi"
    general_target = os.path.join(general_dir, color_scheme)
    applied_patches = set()

    if theme_packages:
        log("Applying patches to themes")
        for pkg_name, theme_list in theme_packages.items():
            if pkg_name in customizable:
                icon_manager.copy_missing(general_dir, specific_dir, pkg_name)
                applied_patches.update(
                    _apply_theme_patches(
                        theme_list,
                        os.path.join(specific_dir, pkg_name, color_scheme),
                        specific_modification,
                        force_overwrite,
                    )
                )
            else:
                applied_patches.update(
                    _apply_theme_patches(theme_list, general_target, general_modification, force_overwrite)
                )
    else:
        log("No themes found to patch!")

    log("Cleaning up obsolete theme patches")
    for root, dirs, files in os.walk(utils_path.overlay_patches_path()):
        if root == specific_dir:
            for subdir in set(dirs) - set(customizable):
                full_path = os.path.join(root, subdir)
                shutil.rmtree(full_path, ignore_errors=True)
                dump(full_path)

        for file_name in files:
            if file_name.endswith(".sublime-theme"):
                full_file_path = os.path.join(root, file_name)
                if full_file_path not in applied_patches:
                    try:
                        os.remove(full_file_path)
                        dump(full_file_path)
                    except OSError:
                        pass

def _get_customizable_packages():
    log("Identifying theme packages supporting customization")
    supported_packages = set()
    for resource in sublime.find_resources(".supports-a-file-icon-customization"):
        if not resource.startswith("Packages/"):
            continue
        parts = resource.split("/")
        if len(parts) >= 3:
            _, package_name, _ = parts
            supported_packages.add(package_name)
    dump(supported_packages)
    return supported_packages

def _get_installed_themes():
    log("Scanning for installed themes")
    discovered_themes = set()
    theme_map = {}
    for resource in sublime.find_resources("*.sublime-theme"):
        if not resource.startswith("Packages/"):
            continue
        parts = resource.split("/")
        if len(parts) >= 3 and parts[1] != utils_path.OVERLAY_ROOT:
            package = parts[1]
            theme_name = parts[-1]
            if theme_name not in discovered_themes:
                discovered_themes.add(theme_name)
                theme_map.setdefault(package, []).append(theme_name)
    dump(theme_map)
    return theme_map

def _apply_theme_patches(themes, destination, content, overwrite):
    applied = set()
    file_mode = "w" if overwrite else "x"
    for theme in themes:
        try:
            target_file = os.path.join(destination, theme)
            applied.add(target_file)
            with open(target_file, file_mode) as f:
                f.write(content)
        except FileExistsError:
            log("Skipped existing `{}`".format(theme))
        except Exception as err:
            log("Failed to patch `{}`".format(theme))
            dump(err)
        else:
            log("Successfully patched `{}`".format(theme))
    return applied

def _build_general_modification(settings):
    log("Constructing general modification")
    theme_elements = []
    base_color = convert_color(settings.get("color"))
    opacity_val = settings.get("opacity")
    icon_spec = _build_icon_spec(None, base_color, opacity_val)
    size_val = settings.get("size")
    if size_val:
        icon_spec["content_margin"] = [size_val, size_val]
    row_padding_val = settings.get("row_padding")
    if row_padding_val:
        icon_spec["row_padding"] = row_padding_val
    theme_elements.append(icon_spec)

    hover_color = convert_color(settings.get("color_on_hover"))
    hover_opacity = settings.get("opacity_on_hover")
    if hover_color or hover_opacity:
        theme_elements.append(_build_icon_spec("hover", hover_color, hover_opacity))

    select_color = convert_color(settings.get("color_on_select"))
    select_opacity = settings.get("opacity_on_select")
    if select_color or select_opacity:
        theme_elements.append(_build_icon_spec("selected", select_color, select_opacity))

    dump(theme_elements)
    import json
    return json.dumps(theme_elements)

def _build_specific_modification(settings):
    log("Constructing specific modification")
    theme_elements = []
    primary_color = convert_color(settings.get("color"))
    theme_elements.append(_build_icon_spec(None, primary_color))

    if primary_color:
        hover_color = convert_color(settings.get("color_on_hover"))
        if hover_color:
            theme_elements.append(_build_icon_spec("hover", hover_color))

        select_color = convert_color(settings.get("color_on_select"))
        if select_color:
            theme_elements.append(_build_icon_spec("selected", select_color))

    dump(theme_elements)
    import json
    return json.dumps(theme_elements)

def _build_icon_spec(attrib, color=None, opacity=None):
    icon_dict = {"class": "icon_file_type", "layer0.tint": color}
    if attrib:
        icon_dict["parents"] = [{"class": "tree_row", "attributes": [attrib]}]
    if opacity is not None:
        icon_dict["layer0.opacity"] = opacity
    return icon_dict

# Module written to explore calendar factory bounds (prior to implementing `bound_start`,
# `bound_end`) - evaluates earliest start date and latest end date for which a
# calendar can be instantiated without raising an error. Also records errors
# raised when dates are passed beyond these limits.
# Retained in case useful for future reference.
"""
from __future__ import annotations
import dataclasses
import abc
import pathlib
import pickle
from typing import Literal, Type
import pandas as pd
import exchange_calendars as xcals

@dataclasses.dataclass
class CalendarBounds:
    """Bounds within which an xcals.ExchangeCalendar can be calculated.
    Parameters
    ----------
    name :
        Name of calendar with declared bounds.
    start : pd.Timestamp
        Earliest start date for which can create a calendar with end date
        as tomorrow.
    start_error :
        Error instance raised in event request a calendar with start date
        one day earlier than `start` and end date as tomorrow.
    end : pd.Timestamp
        Latest end date for which can create a calendar with start date
        as yesterday.
    end_error :
        Error instance raised in event request a calendar with end date
        one day later than `end` and start date as yesterday.
    """
    name: str
    start: pd.Timestamp
    start_error: Exception
    end: pd.Timestamp
    end_error: Exception

class _DetermineCalendarBounds:
    """Determine start and end bounds of a given calendar factory."""
    def __init__(self, Factory: xcals.ExchangeCalendar, verbose: bool = False):
        self.Factory = Factory
        self.verbose = verbose
        self._last_exception: Exception | None

    @property
    def calendar_id(self) -> str:
        """Calendar identifier."""
        if isinstance(self.Factory.name, str):
            return self.Factory.name
        else:
            return self.Factory().name

    @property
    def current_date(self) -> pd.Timestamp:
        return pd.Timestamp.now(tz="UTC").floor("D")

    def _fetch_calendar(
        self,
        start: pd.Timestamp | None = None,
        end: pd.Timestamp | None = None,
    ) -> xcals.ExchangeCalendar:
        """Get calendar for period between now and `start` or `end`."""
        if self.verbose:
            insert = f"start={start}" if start is not None else f"end={end}"

        if start is None:
            start = self.current_date - pd.Timedelta(1, "D")
        elif end is None:
            end = self.current_date + pd.Timedelta(1, "D")
        else:
            raise ValueError("`start` and `end` cannot both be None.")

        if self.verbose:
            print(f"fetching calendar '{self.calendar_id}' with {insert}.")

        return self.Factory(start=start, end=end)

    def _is_valid_boundary(
        self, date: pd.Timestamp, bound_type: Literal["start", "end"]
    ) -> bool:
        kwargs = {bound_type: date}
        try:
            self._fetch_calendar(**kwargs)
        except Exception as err:  # pylint: disable=broad-except
            self._last_exception = err
            return False
        else:
            return True

    def _find_valid_date_by_stepping(
        self,
        search_from: pd.Timestamp,
        step: pd.DateOffset,
        bound_type: Literal["start", "end"],
    ) -> pd.Timestamp:
        # recursively find a valid date by stepping in increments of `step`
        if self._is_valid_boundary(search_from, bound_type):
            return search_from
        else:
            next_search = search_from + step
            if (  # if start has moved into the future or end into the past
                search_from <= self.current_date < next_search
                or search_from >= self.current_date > next_search
            ):
                return self.current_date
            else:
                return self._find_valid_date_by_stepping(
                    next_search, step, bound_type
                )

    @property
    def _initial_step(self) -> pd.DateOffset:
        return pd.DateOffset(years=100)

    def _is_initial_step(self, step: pd.DateOffset) -> bool:
        return step == self._initial_step or -step == self._initial_step

    def _step_sequence(
        self, bound_type: Literal["start", "end"]
    ) -> abc.Iterator[pd.DateOffset]:
        direction = 1 if bound_type == "start" else -1
        sequence = iter(
            [
                direction * self._initial_step,
                direction * pd.DateOffset(years=30),
                direction * pd.DateOffset(years=10),
                direction * pd.DateOffset(years=3),
                direction * pd.DateOffset(years=1),
                direction * pd.DateOffset(months=3),
                direction * pd.DateOffset(months=1),
                direction * pd.DateOffset(days=10),
                direction * pd.DateOffset(days=3),
                direction * pd.DateOffset(days=1),
            ]
        )
        return sequence

    def _validate_boundary(
        self, date: pd.Timestamp, bound_type: Literal["start", "end"]
    ) -> bool:
        if not self._is_valid_boundary(date, bound_type):
            return False
        else:
            adjustment = 1 if bound_type == "end" else -1
            date += pd.Timedelta(adjustment, "D")
            return not self._is_valid_boundary(date, bound_type)

    def _test_edge_cases(
        self, bound_type: Literal["start", "end"]
    ) -> tuple[pd.Timestamp, Exception] | None:
        """Test known likely bounds around min/max Timestamp.
        These likely bounds are caused by how special closes is calculated.
        Return None if no likely bound is a boundary.
        """
        if bound_type == "start":
            edge_candidates = [
                pd.Timestamp("1678-01-01", tz="UTC"),
                pd.Timestamp("1679-01-01", tz="UTC"),
            ]
        else:
            edge_candidates = [
                pd.Timestamp("2260-12-31", tz="UTC"),
                pd.Timestamp("2262-04-10", tz="UTC"),
            ]

        for candidate in edge_candidates:
            if self._validate_boundary(candidate, bound_type):
                assert self._last_exception is not None
                return (candidate, self._last_exception)
        return None

    @staticmethod
    def _boundary_origin(bound_type: Literal["start", "end"]) -> pd.Timestamp:
        if bound_type == "start":
            return pd.Timestamp.min.ceil("D").tz_localize("UTC")
        else:
            return pd.Timestamp.max.floor("D").tz_localize("UTC")

    def _locate_boundary(
        self, bound_type: Literal["start", "end"]
    ) -> tuple[pd.Timestamp, Exception]:
        self._last_exception = None
        origin = self._boundary_origin(bound_type)
        try:
            assert not self._validate_boundary(origin, bound_type)
        except pd.errors.OutOfBoundsDatetime as err:
            # if origin is a valid boundary then `_validate_boundary` will
            # raise OutOfBoundsDatetime as prod beyond pandas timestamp bounds
            return (origin, err)

        step_sequence = self._step_sequence(bound_type)
        step = next(step_sequence)
        search_point = origin

        while step:
            search_point += step  # avoid getting calendar with same parameters as previous call
            valid_date = self._find_valid_date_by_stepping(
                search_point, step, bound_type
            )

            if valid_date == search_point and self._is_initial_step(step):
                # first attempt was valid, chances are only calculation of
                # special closes was causing error on min date. Try edge-cases:
                edge_result = self._test_edge_cases(bound_type)
                if edge_result is not None:
                    return edge_result

            search_point = valid_date - step
            try:
                step = next(step_sequence)
            except StopIteration:
                break

        return (valid_date, self._last_exception)

    def determine_bounds(self) -> CalendarBounds:
        """Return valid bounds for Factory's `start` and `end` parameters.
        See determine_calendar_bounds.___doc___
        """
        start_bound = self._locate_boundary("start")
        end_bound = self._locate_boundary("end")
        return CalendarBounds(self.calendar_id, *start_bound, *end_bound)

def determine_calendar_bounds(
    Factory: xcals.ExchangeCalendar, verbose: bool = False
) -> CalendarBounds:
    """Return CalendarBounds for a factory.
    Bounds delimit the longest continuous period, which includes today,
    through which start and end dates will always return an
    xcals.ExchangeCalendar. Calling the `Factory` with a start date one day
    before the start bound, or with an end date one day after the end
    bound, will raise an error.
    Parameters
    ----------
    Factory :
        xcals.ExchangeCalendar class to query bounds of.
    verbose :
        True for a live print of factory calls as the bounds are
        sought out and prodded.
    Returns
    -------
    CalendarBounds:
        Dataclass that describes bounds and associated out-of-bounds
        errors. See CalendarBounds.__doc__.
    Notes
    -----
    Uses trial and error to home in on and prod the bounds.
    """
    return _DetermineCalendarBounds(Factory, verbose).determine_bounds()

def _determine_bounds_for_all_factories(verbose=False) -> dict[str, CalendarBounds]:
    """Determine and return Calendar Bounds for all calendars.
    NOTE: This function will take a fair while to run! Pass `verbose` as
    True for a live print of factory calls as the bounds are sought and
    probed.
    """
    cal_bounds = {}
    for name, Factory in xcals.calendar_utils._default_calendar_factories.items():
        cal_bounds[name] = determine_calendar_bounds(Factory, verbose)
    return cal_bounds

def _calendar_bounds_resource_path() -> pathlib.PurePath:
    path = pathlib.Path(__file__)
    path = pathlib.Path(path.parent, "resources/_calendar_bounds.dat")
    assert path.exists()
    return path

def _cache_all_calendar_bounds(all_calendar_bounds: dict["str", CalendarBounds]):
    """Cache `all_calendar_bounds` to resource file.
    NOTE: VALIDATE passed `all_calendar_bounds` before caching.
    Parameters
    ----------
    all_calendar_bounds :
        As returned by `_determine_bounds_for_all_factories`. VALIDATE return before
        caching!!
    """
    assert isinstance(all_calendar_bounds, dict)
    assert len(all_calendar_bounds) > 20
    key = list(all_calendar_bounds.keys())[0]
    assert isinstance(key, str)
    assert isinstance(all_calendar_bounds[key], CalendarBounds)

    with open(_calendar_bounds_resource_path(), "wb") as file:
        pickle.dump(all_calendar_bounds, file)

def _load_all_calendars_bounds() -> dict["str", CalendarBounds]:
    """Load `all_calendar_bounds` from resources."""
    with open(_calendar_bounds_resource_path(), "rb") as file:
        all_calendar_bounds = pickle.load(file)
    return all_calendar_bounds

_all_calendars_bounds = _load_all_calendars_bounds()

def _get_all_calendars_bounds_exceptions() -> tuple[Type[Exception], ...]:
    """Exceptions that can be raised when requesting calendar with oob date."""
    bounds = _all_calendars_bounds
    errors = []
    for cal in bounds:
        error_types = (type(bounds[cal].start_error), type(bounds[cal].end_error))
        for error_type in error_types:
            if error_type not in errors:
                errors.append(error_type)
    return tuple(errors)

def all_calendars_bounds() -> pd.DataFrame:
    """Return DataFrame describing start and end bounds for each calendar.
    Bounds delimit the longest continuous period, which includes today,
    through which start and end dates will always return an
    xcals.ExchangeCalendar.
    Returns
    -------
    pd.DataFrame
        Indexed with calendar names.
        Columns:
            earliest_valid_start - earliest start date from which a
                calendar can be instantiated with end date as today.
            latest_valid_end - latest end date to which a calendar can
                be instantiated with start date as today.
    """
    cal_bounds = _all_calendars_bounds
    start_bounds = []
    end_bounds = []
    for _, factory_bounds in cal_bounds.items():
        start_bounds.append(factory_bounds.start)
        end_bounds.append(factory_bounds.end)
    return pd.DataFrame(
        dict(earliest_valid_start=start_bounds, latest_valid_end=end_bounds),
        index=cal_bounds.keys(),
    )

def get_calendar_bounds(
    calendar_name: str,
) -> tuple[pd.Timestamp, pd.Timestamp]:
    """Return 2-tuple describing start and end bounds for a given calendar.
    Bounds delimit the longest continuous period, which includes today,
    through which start and end dates will always return a calendar.
    """
    bounds = _all_calendars_bounds[calendar_name]
    return (bounds.start, bounds.end)

