def execute_docker_command(container_image, entry_point, *cmd_args):
    command_str = "docker run --entrypoint %s --rm %s %s" % (entry_point, container_image, " ".join(cmd_args))
    return subprocess.check_output(
        command_str,
        stderr=subprocess.STDOUT,
        shell=True,
    )

def retrieve_key_from_output(key_lines, position: int) -> bytes:
    return key_lines[position].split(b":")[position].strip().decode("ascii")

def generate_keys(docker_image):
    output_lines = execute_docker_command(
        docker_image,
        "sh",
        "-c",
        "'/usr/local/bin/tezos-client --protocol PsDELPH1Kxsx gen keys mykey && /usr/local/bin/tezos-client --protocol PsDELPH1Kxsx show address mykey -S'",
    ).split(b"\n")

    return {
        "public": retrieve_key_from_output(output_lines, 1),
        "secret": retrieve_key_from_output(output_lines, 2)
    }

def derive_genesis_chain_id_vanity(length=16):
    random_seed = "".join(
        random.choice(string.ascii_uppercase + string.digits) for _ in range(length)
    )
    FLEXTESA_IMAGE = "registry.gitlab.com/tezos/flextesa:01e3f596-run"
    result = (
        execute_docker_command(
            FLEXTESA_IMAGE,
            "flextesa",
            "vani",
            '""',
            "--seed",
            random_seed,
            "--first",
            "--machine-readable",
            "csv",
        )
        .decode("utf-8")
        .split(",")[1]
    )
    return result

