CHAIN_PARAMETERS = {
    "number_of_nodes": {
        "help": "number of peers in the cluster",
        "default": 1,
        "type": int,
    },
    "number_of_bakers": {
        "help": "number of bakers in the cluster",
        "default": 1,
        "type": int,
    },
    "zerotier_network": {"help": "Zerotier network id for external chain access"},
    "zerotier_token": {"help": "Zerotier token for external chain access"},
    "bootstrap_peer": {"help": "peer ip to join"},
    "docker_image": {
        "help": "Version of the Tezos docker image",
        "default": "tezos/tezos:v8-release",
    },
    "rpc_auth": {
        "help": "Should spin up an RPC authentication server",
        "action": "store_true",
        "default": False,
    },
}

def parse_arguments():
    import argparse
    parser = argparse.ArgumentParser(
        description="Generate helm values for use with the tezos-chain helm chart"
    )
    parser.add_argument(
        "--version",
        action="version",
        version="%(prog)s {version}".format(version=__version__),
    )
    parser.add_argument("chain_name", action="store", help="Name of your chain")

    for param_name, param_config in CHAIN_PARAMETERS.items():
        parser.add_argument(*["--" + param_name.replace("_", "-")], **param_config)

    return parser.parse_args()

def main():
    options = parse_arguments()

    # Validate node count
    if options.number_of_nodes < 1:
        print(
            f"Invalid argument --number-of-nodes {options.number_of_nodes}, must be 1 or more"
        )
        exit(1)

    # Validate baker count
    if options.number_of_bakers < 1:
        print(
            f"Invalid argument --number-of-bakers {options.number_of_bakers}, must be 1 or more"
        )
        exit(1)

    # Prepare bootstrap accounts
    bootstrap_accounts = [f"baker{n}" for n in range(options.number_of_bakers)]

    # Base configuration structure
    base_config = {
        "chain_name": options.chain_name,
        "images": {
            "tezos": options.docker_image,
        },
        "genesis": {
            "genesis_chain_id": derive_genesis_chain_id_vanity(),
            "bootstrap_timestamp": datetime.utcnow()
            .replace(tzinfo=timezone.utc)
            .isoformat(),
        },
        "zerotier_in_use": bool(options.zerotier_network),
        "rpc_auth": options.rpc_auth,
        "zerotier_config": {
            "zerotier_network": options.zerotier_network,
            "zerotier_token": options.zerotier_token,
        },
    }

    # Generate account keys
    account_keys = {"secret": [], "public": []}
    for account_name in bootstrap_accounts:
        keys = generate_keys(options.docker_image)
        for key_category in keys:
            account_keys[key_category].append(
                {
                    "name": account_name,
                    "key": keys[key_category],
                    "type": key_category,
                }
            )

    # Configure nodes
    creation_nodes = [
        {"bake_for": f"baker{n}"} for n in range(options.number_of_bakers)
    ] + [{} for n in range(options.number_of_nodes - options.number_of_bakers)]

    invitation_nodes = [{}]
    peer_list = [options.bootstrap_peer] if options.bootstrap_peer else []

    # Create creation config
    creation_config = {
        **base_config,
        "accounts": account_keys["secret"],
        "is_invitation": False,
        "bootstrap_peers": peer_list,
        "nodes": creation_nodes,
    }

    # Create invitation config
    invitation_config = {
        **base_config,
        "accounts": account_keys["public"],
        "is_invitation": True,
        "bootstrap_peers": peer_list,
        "nodes": invitation_nodes,
    }

    # Remove rpc_auth from invitation config
    invitation_config.pop("rpc_auth", None)

    # Write YAML files
    output_dir = f"{os.getcwd()}/{options.chain_name}"

    with open(f"{output_dir}_values.yaml", "w") as yaml_file:
        yaml.dump(creation_config, yaml_file)
        print(f"Wrote chain creation constants to {output_dir}_values.yaml")

    with open(f"{output_dir}_invite_values.yaml", "w") as yaml_file:
        yaml.dump(invitation_config, yaml_file)
        print(f"Wrote chain invitation constants to {output_dir}_invite_values.yaml")

if __name__ == "__main__":
    main()

