def phase_java_wrapper_repl(ctx, p):
    config = struct(
        options = " ".join(ctx.attr.scalacopts),
        header_script = """
# preserve terminal settings as in bin/scala
original_stty=$(stty -g 2>/dev/null)
if [[ ! $? ]]; then
  original_stty=""
fi
function cleanup() {
  if [[ "$original_stty" != "" ]]; then
    stty $original_stty
    original_stty=""
  fi
}
trap cleanup EXIT
""",
    )
    return _phase_java_wrapper_default(ctx, p, config)
def phase_java_wrapper_common(ctx, p):
    return _phase_java_wrapper_default(ctx, p)
def _phase_java_wrapper_default(ctx, p, _config = struct()):
    return _phase_java_wrapper(
        ctx,
        _config.options if hasattr(_config, "options") else "",
        _config.header_script if hasattr(_config, "header_script") else "",
    )
def _phase_java_wrapper(
        ctx,
        options,
        header_script):
    """Generates a wrapper script that configures the correct path
         to act as a substitute for the java command."""
    exec_prefix = ""
    if header_script == "":
        exec_prefix = "exec "
    wrapper_script = ctx.actions.declare_file(ctx.label.name + "_wrapper.sh")
    ctx.actions.write(
        output = wrapper_script,
        content = """#!/usr/bin/env bash
{script_header}
DEFAULT_JAVABIN={javabin}
JAVA_EXEC_TO_USE=${{REAL_EXTERNAL_JAVA_BIN:-$DEFAULT_JAVABIN}}
{exec_prefix}$JAVA_EXEC_TO_USE "$@" {options}
""".format(
            preamble = header_script,
            exec_str = exec_prefix,
            javabin = _java_bin(ctx),
            args = options,
        ),
        is_executable = True,
    )
    return wrapper_script

import logging
from datetime import datetime, timedelta
from typing import Dict, Generator, Union
import requests
import util
from collector.endpoint import Endpoint
from collector.request import Request
from config import get_active_config

logger = logging.getLogger(__name__)
conf = get_active_config()

class Fetcher(object):
    time_delta = timedelta(days=1)
    epoch_time = datetime(year=1970, month=1, day=1)
    methods: Dict[str, str] = {}
    request_headers: Dict[str, str] = conf.api_params.get("headers")
    query_params: Dict[str, str] = {}
    api_base_url = conf.API_BASE_URL

    def __init__(
        self, target_endpoint: Endpoint, root_url: str = None, *args, **kwargs,
    ):
        self.api_base_url = root_url or self.api_base_url
        self.target = target_endpoint
        self.request_headers = kwargs.get("request_headers") or self.request_headers
        self.query_params = kwargs.get("query_params") or self.query_params
        self.methods = kwargs.get("methods") or self.methods
        self._active_session = None
        self.pending_requests: list = []
        self.received_responses: list = []

class HTTPFetcher(Fetcher):
    time_delta = timedelta(days=1)
    epoch_time = datetime(year=1970, month=1, day=1)
    methods: Dict[str, str] = {}
    request_headers: Dict[str, str] = {}
    query_params: Dict[str, str] = {}

    def __init__(
        self,
        root_url: str,
        target_endpoint: Endpoint,
        methods: dict = None,
        request_headers: dict = None,
        query_params: dict = None,
    ):
        super().__init__(
            root_url, target_endpoint, methods=methods, request_headers=request_headers, query_params=query_params
        )

    def __repr__(self):
        return f"({self.target.name})  {self.full_url} -> {self.data_model}"

    def __iter__(self) -> Generator:
        for req in self.pending_requests:
            yield req

    @property
    def full_url(self):
        return util.urljoin(self.api_base_url, self.route)

    @property
    def route(self):
        return self.target.path

    @property
    def data_model(self):
        """ Making requests on behalf of this model """
        return self.target.model

    @property
    def active_session(self):
        if self._active_session is None:
            self.active_session = requests.Session()
        return self._active_session

    @property
    def s(self):
        """ Alias for active_session """
        return self.active_session

    @active_session.setter  # type: ignore
    def active_session(self, value):
        self._active_session = value

    def apply_method(
        self,
        method_name: str,
        param_value: Union[int, str, float] = None,
        second_value: Union[int, str, float] = None,
        param_list: list = None,
    ) -> str:
        """Create a url fragment using the specified method
        Arguments:
            name {str} -- parameter name
            param_value {str} -- parameter value
            second_value {str} -- parameter value
            param_list {list} -- parameter value
        Returns:
            self
        """
        try:
            if not any([param_value, param_list]):
                raise ValueError
            if param_list:
                param_list = "".join(param_list)  # type: ignore
            return self.methods[method_name]["template"].format(  # type: ignore
                value=param_value, value2=second_value, values=param_list
            )
        except KeyError:
            raise KeyError(f"Method not found: {method_name}")
        except ValueError:
            raise ValueError("One of param_value or param_list must be specified")
        except Exception as e:
            raise Exception(f"Failed to add method: {method_name} -- {e}")

    def append_param(self, field: str, value: Union[int, str, float] = None) -> Fetcher:
        #! https://flask-restless.readthedocs.io/en/stable/searchformat.html
        try:
            self.query_params[field] = str(value)
        except Exception as e:
            raise Exception(f"Failed to add parameter: field={field} value={value}")
        return self

    def build(self, **kwargs) -> str:
        try:
            return self.full_url.format(**kwargs)
        except KeyError as ke:
            raise KeyError(f"Unable to format path ({self.route}) without {ke}")
        except Exception:
            raise

    def queue_request(self, headers: dict = None, params: dict = None, **kwargs) -> None:
        url = self.build(**kwargs)
        headers = headers or {}
        params = params or {}
        headers = {**self.request_headers, **headers}
        params = {**self.query_params, **params}
        r = Request("GET", url, headers=headers, params=params)
        self.pending_requests.append(r)
        logger.debug(f"Queued request: {r}")
        return r

    def fetch_all(self) -> Generator:
        for r in self:
            logger.info(f"Sending request: {r}")
            yield r.get()

import pytest
from ast_refactor.core import ASTMigrator, NotMatched
from ast_refactor import legacy_pandas

def execute_generic_validation(transformer: ASTMigrator):
    for source_code, anticipated in transformer.examples.items():
        verification = transformer.matches_code(source_code)
        if anticipated is NotMatched:
            assert verification is NotMatched
            continue
        else:
            assert verification
        modified = transformer.transform_code(source_code)
        if isinstance(anticipated, str):
            assert modified.strip().replace(
                "\n\n", "\n"
            ) == anticipated.strip().replace("\n\n", "\n")

@pytest.mark.parametrize(
    "transformer",
