from typing import Optional
import click
from gvar import load
from lsqfitgui import run_server
from lsqfitgui.util.function import parse_function

@click.command()
@click.argument("data-file", type=str)
@click.option("--model", "-m", help="Python module/function used for fitting.")
@click.option(
    "--address", help="Network address to serve the application.", default="localhost", type=str
)
@click.option("--port-number", help="Port number to serve the application.", default=8000, type=int)
def main(
    data_file: str,
    model: Optional[str] = None,
    address: str = "localhost",
    port_number: int = 8000,
):
    """Start lsqfitgui server by loading a serialized fit object.
    Arguments:
        data_file: Pickle file containing a fit object.
        model: Module/function specification string to use.
    """
    fit_data = load(data_file)
    if model is not None:
        model_func = parse_function(model)
        fit_data.fcn = model_func
    if not hasattr(fit_data, "fcn"):
        raise ValueError(
            "Fit function missing from pickle file."
            " Provide an external function via the option flag."
        )
    run_server(fit_data, host=address, port=port_number)

