# Compute determinants of matrices derived from power sets
import numpy as np
from itertools import chain, combinations

np.set_printoptions(threshold=np.nan)

def powerset(iterable):
    s = list(iterable)
    ps = chain.from_iterable(combinations(s, r) for r in range(len(s) + 1))
    ps = [list(x) for x in ps if len(x) > 0]  # exclude empty set and convert to lists
    return sorted(ps, key=lambda x: (len(x), *x))

def cartesian_self_product(a):
    return np.meshgrid(a, a)

def intersection_indicator(a, b):
    return (a & b) > 0

def encode_as_bitvector(subsets, n, dtype):
    bit_matrix = np.zeros((len(subsets), n), dtype=np.uint8)
    for idx, subset in enumerate(subsets):
        bit_matrix[idx, subset] = 1
    packed = np.packbits(bit_matrix, axis=-1)
    return packed.view(dtype)

def select_dtype(bit_count):
    if bit_count <= 8:
        return np.uint8
    elif bit_count <= 16:
        return np.uint16
    elif bit_count <= 32:
        return np.uint32
    elif bit_count <= 64:
        return np.uint64
    else:
        return None

# Main computation loop
for size in range(2, 14):
    data_type = select_dtype(size)
    all_subsets = powerset(range(size))
    encoded_subsets = encode_as_bitvector(all_subsets, size, data_type)

    grid_x, grid_y = cartesian_self_product(encoded_subsets)
    adjacency_matrix = intersection_indicator(grid_x, grid_y).astype(data_type)

    determinant_value = int(np.linalg.det(adjacency_matrix))

    print(f"n={size} determinant: {determinant_value}")

