import inspect
import os
import importlib.util
from pathlib import Path
from PySide6.QtCore import QDir, QSize
from PySide6.QtWidgets import QFileDialog, QListWidget, QTabWidget
from cilissa.images import Image
from cilissa.operations import Metric, Transformation
from cilissa_gui.decorators import PathInsert
from cilissa_gui.widgets import CQImageItem, CQInfoDialog, CQOperationItem

class Explorer(QTabWidget):
    IMAGE_EXTENSIONS = ["*.png", "*.jpg", "*.jpeg", "*.bmp", "*.tiff"]

    def __init__(self) -> None:
        super().__init__()
        self.images_tab = ImagesTab(self)
        self.metrics_tab = MetricsTab(self)
        self.transformations_tab = TransformationsTab(self)
        self.addTab(self.images_tab, "Images")
        self.addTab(self.metrics_tab, "Metrics")
        self.addTab(self.transformations_tab, "Transformations")
        self.currentChanged.connect(self.deselect_items_in_all_tabs)

    def deselect_items_in_all_tabs(self) -> None:
        for idx in range(self.count()):
            self.widget(idx).clearSelection()

    def open_image_dialog(self) -> None:
        # Returns tuple ([filenames], "filter"), only filenames needed
        filenames = QFileDialog.getOpenFileNames(
            self, "Select images...", "", f"Images ({' '.join([ext for ext in self.IMAGE_EXTENSIONS])})"
        )[0]
        for filepath in filenames:
            img = Image(filepath)
            cq_img = CQImageItem(img, width=128, height=128)
            self.images_tab.addItem(cq_img)

    def open_image_folder_dialog(self) -> None:
        folder_path = QFileDialog.getExistingDirectory(self, "Choose image folder...", "", QFileDialog.ShowDirsOnly)
        d = QDir(folder_path)
        if folder_path and not d.entryList(self.IMAGE_EXTENSIONS):
            dialog = CQInfoDialog("No images found in the selected directory", "No images found")
            dialog.exec()
            return
        for filename in d.entryList(self.IMAGE_EXTENSIONS):
            img = Image(Path(folder_path, filename))
            cq_img = CQImageItem(img, width=128, height=128)
            self.images_tab.addItem(cq_img)

    def load_plugin(self) -> None:
        filename = QFileDialog.getOpenFileName(self, "Open Python plugin", "", "Python files (*.py)")[0]
        with PathInsert(os.path.dirname(filename)):
            spec = importlib.util.spec_from_file_location(filename, filename)
            module = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(module)
            for name, value in inspect.getmembers(module):
                if not inspect.isclass(value):
                    continue
                if issubclass(value, Metric) and value != Metric:
                    self.metrics_tab.addItem(CQOperationItem(value))
                elif issubclass(value, Transformation) and value != Transformation:
                    self.transformations_tab.addItem(CQOperationItem(value))

class ExplorerTab(QListWidget):
    def __init__(self, parent: QTabWidget) -> None:
        super().__init__()
        self.setViewMode(QListWidget.IconMode)
        self.setIconSize(QSize(82, 82))
        self.setUniformItemSizes(True)
        self.setMovement(QListWidget.Static)
        self.setResizeMode(QListWidget.Adjust)
        self.setFrameStyle(QListWidget.NoFrame)
        self.setMaximumWidth(parent.width())

    def remove_selected(self) -> None:
        rows = [index.row() for index in self.selectedIndexes()]
        for row in reversed(rows):
            self.takeItem(row)

class ImagesTab(ExplorerTab):
    def __init__(self, parent: QTabWidget) -> None:
        super().__init__(parent)
        self.setSelectionMode(QListWidget.ExtendedSelection)

class MetricsTab(ExplorerTab):
    def __init__(self, parent: QTabWidget) -> None:
        super().__init__(parent)
        for metric_class in Metric.get_subclasses():
            self.addItem(CQOperationItem(metric_class))

class TransformationsTab(ExplorerTab):
    def __init__(self, parent: QTabWidget) -> None:
        super().__init__(parent)
        for transform_class in Transformation.get_subclasses():
            self.addItem(CQOperationItem(transform_class))

