# Configuration loader and manager for service settings
import os
import sys
import json
import requests

# Environment variable setup
environment = os.getenv('ENV')
if not environment:
    print("ENV not specified")
    sys.exit(1)

# Local settings file path configuration
SETTINGS_FILE_PATH = os.getenv('LOCAL_SETTINGS_FILE', '/app/_service_storage/settings.json')
if not os.path.exists(SETTINGS_FILE_PATH):
    print("LOCAL_SETTINGS_FILE not specified")
    sys.exit(1)

# Logging configuration
VERBOSITY_LEVEL = os.getenv('LOG_LEVEL', 'DEBUG')
MESSAGE_FORMAT = os.getenv('LOG_FORMAT', '[ %(levelname)5s ] - %(message)s')

# Server port configuration
SERVER_PORT = int(os.getenv('PORT', 5000))

def _get_current_module():
    return sys.modules[__name__]

def _load_local_configuration():
    with open(SETTINGS_FILE_PATH, 'r') as file:
        return json.loads(file.read())

def _save_local_configuration(**updates):
    current_config = _load_local_configuration()

    # Update configuration with new values
    for parameter in current_config:
        if parameter in updates:
            current_config[parameter] = updates[parameter]

    try:
        with open(SETTINGS_FILE_PATH, 'w') as output_file:
            json.dump(current_config, output_file, ensure_ascii=False, indent=4)
            print("[  INFO ] - Updated LOCAL_SETTINGS_FILE with new data")
    except Exception:
        print("[ ERROR ] - Impossible to update LOCAL_SETTINGS_FILE")

    return current_config

def _apply_module_attributes(data):
    data = convert_dict_keys_to_uppercase(data)
    current_module = _get_current_module()
    for key, value in data.items():
        setattr(current_module, key, value)

def convert_dict_keys_to_uppercase(input_dict):
    result = {}
    for key, value in input_dict.items():
        if isinstance(value, dict):
            value = convert_dict_keys_to_uppercase(value)
        result[key.upper()] = value
    return result

def convert_dict_keys_to_lowercase(input_dict):
    result = {}
