from dataclasses import dataclass, field
from functools import lru_cache
from typing import TYPE_CHECKING, Any, List, Optional, TypedDict, Union, no_type_check

class BaseNode:
    identifier: str
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs, identifier=self._get_identifier())

    @classmethod
    @lru_cache(maxsize=30)
    def _get_identifier(cls):
        return cls.__name__.lower()

class Leaf(BaseNode):
    ...

@dataclass
class DatabaseTable(Leaf):
    table_name: str
    schema_name: Optional[str]
    alias_name: Optional[str]

@dataclass
class Field(Leaf):
    column_name: str
    source_table: Optional[str]
    source_alias: Optional[str]
    rename_as: Optional[str]

@dataclass
class Wildcard(Field):
    column_name: str = field(default="*", init=False)
    source_table: Optional[str]
    source_alias: None
    rename_as: None

@dataclass
class FunctionCall(Leaf):
    func_name: str
    schema_ref: Optional[str]
    alias_ref: Optional[str]
    arguments: List[BaseNode]
    is_anonymous: bool

@dataclass
class LiteralValue(Leaf):
    data_value: Any

@dataclass
class Placeholder(Leaf):
    param_name: str

class Expression(BaseNode):
    expression_name: str
    components: List[BaseNode]

@dataclass
class SelectStatement(Expression):
    keyword: str = field(default="SELECT", init=False)
    components: List[Union["ReturnClause", "Subquery", "SetUnion", "SetUnionAll", "SetExcept"]]

    def extract_tables(self):
        return []

    def extract_columns(self):
        return []

@dataclass
class ReturnClause(Expression):
    keyword: str = field(default="RETURNING", init=False)
    components: List[Union["Expression", Leaf]]

    def convert_to_select(self):
        return SelectStatement(components=[self])

    def extract_columns(self):
        return []

@dataclass
class Subquery(Expression):
    keyword: str = field(default="QUERY", init=False)
    components: List[Union["FromClause", "Filter", "JoinOperation", "SortOrder", "RowLimit", "SkipOffset"]]

    def extract_tables(self):
        return []

    def convert_to_select(self):
        wildcard = Wildcard()
        return SelectStatement(components=[self, ReturnClause(components=[wildcard])])

@dataclass
class FromClause(Expression):
    keyword: str = field(default="FROM", init=False)
    components: List[Union["Expression", Leaf]]

    def convert_to_select(self):
        query = Subquery(components=[self])
        return query.convert_to_select()

    def extract_tables(self):
        return []

@dataclass
class JoinOperation(Expression):
    keyword: str = field(default="JOIN", init=False)
    components: List[Union["Expression", Leaf]]

    def extract_tables(self):
        return []

@dataclass
class Filter(Expression):
    keyword: str = field(default="WHERE", init=False)
    components: List[Union["Expression", Leaf]]

@dataclass
class SortOrder(Expression):
    keyword: str = field(default="ORDERBY", init=False)
    components: List[Union["Expression", Leaf]]

@dataclass
class RowLimit(Expression):
    keyword: str = field(default="LIMIT", init=False)
    components: List[Union["Expression", Leaf]]

@dataclass
class SkipOffset(Expression):
    keyword: str = field(default="OFFSET", init=False)
    components: List[Union["Expression", Leaf]]

@dataclass
class SetUnion(Expression):
    keyword: str = field(default="UNION", init=False)
    components: List["SelectStatement"]

@dataclass
class SetUnionAll(Expression):
    keyword: str = field(default="UNIONALL", init=False)
    components: List["SelectStatement"]

@dataclass
class SetExcept(Expression):
    keyword: str = field(default="EXCEPT", init=False)
    components: List["SelectStatement"]

@dataclass
class UnaryOperator(BaseNode):
    operation_name: str
    operator_symbol: str
    operands: List[BaseNode]

    def __str__(self):
        if not len(self.operands) == 1:
            raise ValueError("Unary operator must have exactly one operand")
        return f"{self.operator_symbol} {str(self.operands[0])}"

@dataclass
class BinaryOperator(BaseNode):
    operation_name: str
    operator_symbol: str
    operands: List[BaseNode]

    def __str__(self):
        if len(self.operands) > 2:
            raise ValueError("Binary operator cannot have more than two operands")
        if len(self.operands) == 2:
            return "(" + f" {self.operator_symbol} ".join((str(item) for item in self.operands)) + ")"
        else:
            return f"{self.operator_symbol} ".join((str(item) for item in self.operands))

import pyblish.api
import pype.api

class ValidateKnobs(pyblish.api.ContextPlugin):
    """Ensure knobs are consistent.
    Knobs to validate and their values come from the
    Example for presets in config:
    "presets/plugins/nuke/publish.json" preset, which needs this structure:
        "ValidateKnobs": {
            "enabled": true,
            "knobs": {
                "family": {
                    "knob_name": knob_value
                }
            }
        }
    """
    order = pyblish.api.ValidatorOrder
    label = "Validate Knobs"
    hosts = ["nuke"]
    actions = [pype.api.RepairContextAction]
    optional = True

    def process(self, context):
        nuke_settings = context.data.get("presets", {}).get("nuke")
        if not nuke_settings:
            return

        publish_config = nuke_settings.get("publish")
        if not publish_config:
            return

        plugin_config = publish_config.get("ValidateKnobs")
        if not plugin_config:
            return

        invalid_items = self.get_invalid(context, compute=True)
        if invalid_items:
            raise RuntimeError(
                "Found knobs with invalid values:\n{}".format(invalid_items)
            )

    @classmethod
    def get_invalid(cls, context, compute=False):
        stored_invalid = context.data.get("invalid_knobs", [])
        if compute:
            stored_invalid = cls.get_invalid_knobs(context)
        return stored_invalid

    @classmethod
    def get_invalid_knobs(cls, context):
        invalid_list = []
        publish_config = context.data["presets"]["nuke"]["publish"]
        knobs_config = publish_config["ValidateKnobs"]["knobs"]

        for instance in context:
            # Skip non-publishable instances
            if not instance.data.get("publish", False):
                continue

            # Collect families
            families = [instance.data["family"]]
            families.extend(instance.data.get("families", []))
            families = list(set(families) & set(knobs_config.keys()))

            if not families:
                continue

            # Build knob validation dictionary
            knob_rules = {}
            for family in families:
                for knob_rule in knobs_config[family]:
                    knob_rules.update({knob_rule: knobs_config[family][knob_rule]})

            # Collect all nodes including nested ones
            all_nodes = []
            for node in nuke.allNodes():
                all_nodes.append(node)
                if node.Class() == "Group":
                    node.begin()
                    all_nodes.extend(nuke.allNodes())
                    node.end()

            # Check knob values
            for node in all_nodes:
                for knob_name in node.knobs():
                    if knob_name not in knob_rules:
                        continue
                    expected_value = knob_rules[knob_name]
                    actual_value = node[knob_name].value()
                    if actual_value != expected_value:
                        invalid_list.append({
                            "knob": node[knob_name],
                            "name": node[knob_name].name(),
                            "label": node[knob_name].label(),
                            "expected": expected_value,
                            "current": actual_value
                        })

        context.data["invalid_knobs"] = invalid_list
        return invalid_list

    @classmethod
    def repair(cls, instance):
        invalid_data = cls.get_invalid(instance)
        for item in invalid_data:
            if isinstance(item["expected"], unicode):
                item["knob"].setValue(str(item["expected"]))
            else:
                item["knob"].setValue(item["expected"])

