import importlib.util
from functools import reduce
from io import UnsupportedOperation
from pathlib import Path
from typing import List, Dict, Any
from dataclasses import dataclass
from poetry.core.pyproject.tables import PROPERTIES_TABLE, DEPENDENCIES_TABLE
from poetry.core.utils import toml

# Custom profile table path
PROFILE_SECTION = "tool.relaxed-poetry.profile".split(".")

@dataclass
class ProfileActivationRequest:
    selected_profiles: Dict[str, bool]
    command_name: str

    @classmethod
    def parse_commandline(cls, cmd: str, profile_list: List[str]) -> "ProfileActivationRequest":
        selected_profiles = {}
        for profile in profile_list:
            if profile.startswith("!"):
                selected_profiles[profile[1:]] = False
            else:
                selected_profiles[profile] = True
        return cls(selected_profiles, cmd)

class _ConfigProperties:
    def __init__(self, config: Dict[str, Any]):
        self._config = config

    def __getitem__(self, key: str):
        return self._config[key]

    def __setitem__(self, key: str, value):
        self._config[key] = value

    def merge(self, updates: Dict[str, Any]):
        self._config.update(updates)

class _DependencyManager:
    def __init__(self, initial_deps: Dict[str, Any]):
        self.dependencies: Dict[str, Any] = initial_deps

    def include(self, name: str, version_spec: Any):
        self.dependencies[name] = version_spec

class _RuntimeContext:
    def __init__(self, activation: ProfileActivationRequest):
        self._activation = activation

    @property
    def command(self):
        return self._activation.command_name

def _evaluate_activation(activation_rule: Any, context: _RuntimeContext) -> bool:
    if isinstance(activation_rule, bool):
        return activation_rule
    elif isinstance(activation_rule, dict):
        if 'commands' in activation_rule:
            commands: List[str] = activation_rule['commands']
            if isinstance(commands, str):
                commands = [commands]
            default_allow = '*' in commands
            for cmd in commands:
                allow = default_allow
                if cmd == '*':
                    continue
                if cmd.startswith('!'):
                    allow = False
                    cmd = cmd[1:]
                if context.command == cmd:
                    return allow
            return False
    raise UnsupportedOperation(f"unsupported profile activation rule: {activation_rule}")

def _apply_static_profile(profile_path: Path, props: _ConfigProperties, deps: _DependencyManager, context: _RuntimeContext):
    profile_data, _ = toml.load(profile_path)
    profile_def = _resolve(profile_data, PROFILE_SECTION) or {}

    # Check activation condition
    activation_spec = profile_def.get('activate', False)
    if not _evaluate_activation(activation_spec, context):
        return

    print(f"Activating Static Profile: {profile_path.stem}")
    property_overrides = _resolve(profile_data, PROPERTIES_TABLE) or {}
    props.merge(property_overrides)
    additional_deps = _resolve(profile_data, DEPENDENCIES_TABLE) or {}
    for name, spec in additional_deps.items():
        deps.include(name, spec)

def _apply_dynamic_profile(profile_path: Path, props: _ConfigProperties, dependencies: _DependencyManager, context: _RuntimeContext):
    print(f"Activating Dynamic Profile: {profile_path.stem}")
    try:
        spec = importlib.util.spec_from_file_location("__PROFILE__", profile_path)
        module = importlib.util.module_from_spec(spec)
        module.props = props
        module.context = context
        module.deps = dependencies
        spec.loader.exec_module(module)
    except Exception as e:
        raise RuntimeError(f"Error while evaluating profile: {profile_path.stem}") from e

def apply_profiles(
        properties: Dict[str, Any],
        new_deps: Dict[str, Any],
        profiles_dirs: List[Path],
        activation_info: ProfileActivationRequest
):
    dependencies = _DependencyManager(new_deps)
    properties_obj = _ConfigProperties(properties)
    runtime_context = _RuntimeContext(activation_info)

    # Process automatic profiles
    for profiles_dir in profiles_dirs:
        if profiles_dir.exists():
            for profile in profiles_dir.iterdir():
                if activation_info.selected_profiles.get(profile.stem, True):
                    if profile.name.endswith(".py"):
                        _apply_dynamic_profile(profile, properties_obj, dependencies, runtime_context)
                    elif profile.name.endswith(".toml"):
                        _apply_static_profile(profile, properties_obj, dependencies, runtime_context)

def _resolve(d: Dict, path: List[str]) -> Any:
    try:
        return reduce(lambda m, k: m[k], path, d)
    except KeyError:
        return None

import discord
from discord.ext import commands
from k2 import helpers

class InfoModule:
    """Extra informational utilities."""

    @commands.command(aliases=["rlist"])
    @commands.guild_only()
    @commands.cooldown(6, 12, commands.BucketType.channel)
    async def roles(self, ctx):
        """Show all roles in the current server."""
        embed = discord.Embed(title=f"Roles: {len(ctx.guild.roles)}")
        embed.description = ", ".join([f"{role.name}" for role in ctx.guild.roles])
        await ctx.send(embed=embed)

    @commands.command()
    @commands.guild_only()
    @commands.cooldown(6, 12, commands.BucketType.channel)
    async def whohas(self, ctx, *, role_name: str):
        """Show members possessing a specific role.
        * role_name - The role to search for.
        """
        found_role = await helpers.role_by_substring(ctx, role_name)
        members_list = []
        for member in ctx.guild.members:
            if found_role in member.roles:
                members_list.append(member.mention)

        if not members_list:
            await ctx.send("No one has this role. :<")
        else:
            embed = discord.Embed(title=f"Users with {found_role.name}: {len(members_list)}")
            embed.description = ", ".join(members_list[:30])
            if len(members_list) > 30:
                embed.set_footer(text=f"...and {len(members_list)-30} more.")
            await ctx.send(embed=embed)

    @commands.command(brief="Show details about a role.", aliases=["rinfo"])
    @commands.guild_only()
    @commands.cooldown(6, 12, commands.BucketType.channel)
    async def roleinfo(self, ctx, *, role_input: str):
        """Provide detailed information on a specific role.
        * role_input - The role to inspect."""
        target_role = await helpers.role_by_substring(ctx, role_input)
        embed = discord.Embed(title=target_role.name)
        embed.colour = target_role.color
        embed.description = f"{target_role.id} | Members: {len(target_role.members)}"
        embed.add_field(name="Color", value=str(target_role.color), inline=False)

        if target_role.permissions.administrator:
            embed.add_field(name="Administrator", value=True)
        else:
            paginator = commands.Paginator(prefix="", suffix="")
            for perm_name, perm_value in target_role.permissions:
                if perm_value:
                    formatted_perm = str(perm_name).capitalize().replace("_", " ")
                    paginator.add_line(formatted_perm)

            for page_content in paginator.pages:
                embed.add_field(name="Permissions", value=page_content, inline=False)

        await ctx.send(embed=embed)

    @commands.command(aliases=["elist"])
    @commands.guild_only()
    @commands.cooldown(6, 12, commands.BucketType.channel)
    async def emojis(self, ctx):
        """List all custom emojis in the server."""
        embed = discord.Embed(title=f"Custom Emojis for {ctx.guild.name}")
        emoji_strings = []
        for emoji_obj in ctx.guild.emojis:
            emoji_strings.append(str(emoji_obj))
        embed.description = " ".join(emoji_strings)
        await ctx.send(embed=embed)

    @commands.command(brief="Display info for a custom emoji.",
                      aliases=["emojiinfo", "einfo", "ceinfo"])
    @commands.guild_only()
    @commands.cooldown(6, 12, commands.BucketType.channel)
    async def customemojiinfo(self, ctx, *, emoji_obj: discord.Emoji):
        """Show detailed info for a specific custom emoji.
        * emoji_obj - The emoji to analyze."""
        embed = discord.Embed(title=emoji_obj.name)
        embed.description = f"{emoji_obj.id} | [Full image]({emoji_obj.url})"
        embed.add_field(name="Server", value=f"{emoji_obj.guild.name} ({emoji_obj.guild.id})")
        embed.add_field(name="Managed by Bot", value=emoji_obj.managed)
        embed.add_field(name="Creation Time", value=emoji_obj.created_at.ctime())
        embed.set_thumbnail(url=emoji_obj.url)
        await ctx.send(embed=embed)

def setup(bot):
    """Initialize and register the InfoModule cog."""
    bot.add_cog(InfoModule())

