import os
import argparse
from collections import Sequence
import base58
import libnacl

TXN_TYPE_XFER = "10001"

def validate_path(is_directory: bool, path_name: str):
    full_path = os.path.expanduser(path_name)
    access_rights = os.W_OK if is_directory else os.R_OK
    check_func = os.path.isdir if is_directory else os.path.isfile
    validation_flag = True if is_directory else os.path.getsize(full_path) > 0

    if check_func(full_path) and os.access(full_path, access_rights) and validation_flag:
        return full_path
    raise argparse.ArgumentTypeError("{} does not exist or permission denied or file empty".format(full_path))

def verify_seed(seed_string: str):
    if len(seed_string) == 32:
        return seed_string
    raise argparse.ArgumentTypeError("Seed must be exactly 32 characters long but got {}".format(len(seed_string)))

def validate_reply(response):
    if isinstance(response, str):
        response = json.loads(response)
    if "op" not in response or response["op"] != "REPLY":
        raise Exception("Received non-successful reply: {}".format(response))

def split_sequence_into_batches(sequence_data: Sequence, batch_size: int):
    return (sequence_data[offset:offset + batch_size] for offset in range(0, len(sequence_data), batch_size))

# Copied from Plenum - adapted naming
def bytesToBase58(data_bytes):
    return base58.b58encode(data_bytes).decode("utf-8")

# Copied from Plenum - adapted naming
def generate_random_string(length: int) -> str:
    assert (length > 0), "Requested random string length cannot be zero or negative"
    result = libnacl.randombytes(length // 2).hex()
    return result if length % 2 == 0 else result + hex(libnacl.randombytes_uniform(15))[-1]

def extract_transaction_data(txn_dict):
    temp = txn_dict or {}
    return temp.get('result', {}).get('txn', {}) or temp.get('txn', {})

def extract_transaction_type(txn_dict):
    return extract_transaction_data(txn_dict).get('type', None)

def extract_transaction_id(txn_dict):
    temp = txn_dict or {}
    return (temp.get('result', {}).get('txnMetadata', {}) or temp.get('txnMetadata', {})).get('txnId', None)

def get_request_type(request_obj):
    if isinstance(request_obj, dict):
        dict_request = request_obj
    elif isinstance(request_obj, str):
        dict_request = json.loads(request_obj)
    else:
        raise RuntimeError("Request type not supported")
    txn_operation = dict_request.get("operation", {}).get("type", "")
    return txn_operation

def construct_inputs_outputs(address_balances, target_value):
    for account_address in address_balances:
        inputs_list = []
        outputs_list = []
        accumulated_amount = 0
        temporary_txo = []

        while address_balances[account_address] and accumulated_amount < target_value:
            (input_source, input_amount) = address_balances[account_address].pop()
            if input_amount > 0:
                inputs_list.append(input_source)
                accumulated_amount += input_amount
                temporary_txo.append((input_source, input_amount))

        if accumulated_amount >= target_value:
            change_amount = accumulated_amount - target_value
            if change_amount > 0:
                outputs_list = [{"recipient": account_address, "amount": change_amount}]
            return {account_address: temporary_txo}, inputs_list, outputs_list
        else:
            for s_a in temporary_txo:
                address_balances[account_address].append(s_a)
    return None, None, None

# Modified version of Vocabulary class with renamed variables and reordered logic
import collections
from typing import Iterable, Optional, Sequence
from absl import logging

class Vocabulary:
  """Represents a vocabulary that can be built from a dataset."""
  def __init__(self,
               vocab_file: Optional[str] = None,
               sequences: Optional[Iterable[Sequence[bytes]]] = None,
               min_count: int = 1,
               padding_token: bytes = b'<pad>',
               unknown_token: bytes = b'<unk>',
               start_token: bytes = b'<s>',
               end_token: bytes = b'</s>'):
    """Initializes the vocabulary either by loading from file or building from sequences."""
    self.padding_token = padding_token
    self.unknown_token = unknown_token
    self.start_token = start_token
    self.end_token = end_token
    self.special_tokens = (padding_token, unknown_token, start_token, end_token)

    if vocab_file is not None:
      self.load(vocab_file)
    elif sequences is not None:
      self.create(sequences, min_freq=min_count)
    else:
      raise ValueError(
          ('Vocabulary requires either `vocab_file` or `sequences` to be provided, '
           'got %r and %r.') % (vocab_file, sequences))

  def create(self,
             sequences: Iterable[Sequence[bytes]],
             min_freq: int = 1):
    """Constructs vocabulary from tokenized sequences with optional frequency threshold.
    Args:
      sequences: Iterable of token sequences for vocabulary construction.
      min_freq: Minimum occurrence count required for tokens to be included.
    """
    # Count all tokens in the sequences
    freq_counter = collections.Counter()
    for seq in sequences:
      freq_counter.update(seq)

    # Initialize vocabulary with special tokens first
    vocab_dict = collections.OrderedDict()
    for token in self.special_tokens:
      vocab_dict[token] = len(vocab_dict)

    # Add regular tokens sorted by frequency (descending) then lexicographically
    for token, count in sorted(
        freq_counter.items(),
        key=lambda item: (-item[1], item[0])):
      if count >= min_freq:
        vocab_dict[token] = len(vocab_dict)

    logging.info('Total unique tokens observed: %d', len(freq_counter))
    logging.info('Final vocabulary size after filtering: %d', len(vocab_dict))
    self.vocab = vocab_dict

  def __getitem__(self, token: str):
    return self.vocab[token]

  def get_all_tokens(self):
    return self.vocab.keys()

  def get_all_indices(self):
    return self.vocab.values()

  def __len__(self):
    return len(self.vocab)

  @property
  def pad_id(self):
    """Returns index of padding token."""
    return self.vocab[self.padding_token]

  @property
  def unk_id(self):
    """Returns index of unknown token."""
    return self.vocab[self.unknown_token]

  @property
  def bos_id(self):
    """Returns index of beginning-of-sequence token."""
    return self.vocab[self.start_token]

  @property
  def eos_id(self):
    """Returns index of end-of-sequence token."""
    return self.vocab[self.end_token]

  def load(self, filepath: str) -> None:
    """Loads vocabulary from file where each line contains one token."""
    vocab_dict = collections.OrderedDict()
    with open(filepath, 'rb') as file_handle:
      for idx, raw_token in enumerate(file_handle):
        token = raw_token.rstrip()
        assert isinstance(token, bytes), 'Tokens must be byte strings.'
        vocab_dict[token] = idx

    logging.info('Successfully loaded vocabulary, size: %d', len(vocab_dict))
    self.vocab = vocab_dict

  def save(self, filepath: str) -> None:
    """Saves vocabulary to file, one token per line."""
    with open(filepath, 'wb') as file_handle:
      for token in self.vocab:
        assert isinstance(token, bytes), 'Tokens must be byte strings.'
        file_handle.write(token + b'\n')
    logging.info('Vocabulary saved to %s.', filepath)

import time
import sublime
import sublime_plugin
from .builtintypes import builtintypes
from ..logger import Logger
from ..helpers import get_settings, is_js_source, FLOWTYPE

logger = Logger()
FLOW_SUGGESTIONS = []

class FlowTypeListener(sublime_plugin.EventListener):
    """Handles plugin events for Flow type suggestions."""

    def on_query_completions(self, view, prefix, locations):
        """Provide type completion suggestions for JavaScript variables."""
        if is_js_source(view):
            if get_settings("show_type_completion", True):
                pos = locations[0]
                if not view.match_selector(pos, "source.js"):
                    return []

                logger.logger.debug("Executing autocompletion")
                start_pos = pos - len(prefix)
                current_line = sublime.Region(
                    view.line(start_pos).begin(), start_pos
                )

                if (
                    view.substr(current_line)
                    .strip()
                    .endswith((":", ".", "(", "{", "[", ","))
                ):
                    if get_settings("complete_with_builtintypes", True):
                        # TODO: filter built-in types by prefix
                        return FLOW_SUGGESTIONS + builtintypes
                    return FLOW_SUGGESTIONS

        return []

    def on_selection_modified_async(self, view):
        """Handle selection changes: update autocomplete and check types."""
        if is_js_source(view):
            if get_settings("suggest_autocomplete_on_edit", True):
                # TODO: trigger only when word ends with ':' or '.'
                view.run_command("flowtype_autocomplete")

            if get_settings("check_contents_on_edit", False):
                if time.time() - FLOWTYPE["LAST_ERROR_CHECK"] >= 1:
                    view.run_command("flowtype_check_contents")

    def on_post_save_async(self, view):
        """Clean up highlights and status after saving file."""
        if is_js_source(view):
            view.erase_regions("flow_type_highlights")
            view.erase_status("flow_type")

            if get_settings("check_contents_on_save", False):
                view.run_command("flowtype_check_contents")

