class ExperimentalContrast(object):
    """Container for experimental contrasts (aka experiments or comparisons) nested within
    research studies.
    Should store an arbitrary number of ConnectivityMatrices, Images, and Surfaces,
    along with at most one CoordinateSet.
    """
    def __init__(self, images=None, connectivity_matrices=None, coordinates=None,
                 surfaces=None):
        # Add validation method instead of doing this here. That way it can be
        # applied to other objects. Should check things like name, min/max,
        self.images = {}
        self.coordinates = None
        self.connectivity_matrices = {}
        self.surfaces = {}

        if images:
            self.append_images(images)

        if not isinstance(coordinates, CoordinateSet) and coordinates is not None:
            raise ValueError('Input coordinates must be CoordinateSet or None')
        else:
            self.coordinates = coordinates

        if not isinstance(connectivity_matrices, list):
            connectivity_matrices = [connectivity_matrices]

        for conn_mat in connectivity_matrices:
            if not isinstance(conn_mat, ConnMatrix) and conn_mat is not None:
                raise ValueError('All connectivity_matrices inputs must be nimare ConnMatrices.')
            elif isinstance(conn_mat, ConnMatrix):
                self.connectivity_matrices[conn_mat.type] = conn_mat

        if surfaces:
            for surf in surfaces:
                if not isinstance(surf, Surface) and surf is not None:
                    raise ValueError('All surface inputs must be nimare Surfaces.')
                elif hasattr(surf, 'type') and surf.type in self.surfaces.keys():
                    self.surfaces[surf.type] = surf

    def append_images(self, images):
        ''' Add one or more images to the current collection. '''
        for image in listify(images):
            if not isinstance(image, Image) and image is not None:
                raise ValueError('All images inputs must be nimare Images.')
            elif hasattr(image, 'type') and image.type in self.images.keys():
                self.images[image.type] = image

    @classmethod
    def integrate(cls, contrasts):
        ''' Harmonizes/merges experimental contrasts extracted from different sources, based
        on common identifiers (e.g., DOIs / table numbers, etc.).
        '''
        pass

