# JSON Schema validation utility module
from collections import defaultdict
from lambda_handlers.errors import LambdaError
from lambda_handlers.validators.validator import Validator

try:
    import jsonschema
except ImportError:
    jsonschema = None

SchemaDefinition = Dict[str, Any]

class JSONSchemaValidator(Validator):
    def check(
        self,
        data,
        definition: SchemaDefinition,
    ) -> Tuple[Any, Union[Dict[str, Any], List[Any]]]:
        if not jsonschema:
            raise LambdaError('Missing required dependency: jsonschema.')

        validator = jsonschema.Draft7Validator(definition)
        issues = sorted(validator.iter_errors(data), key=lambda err: err.path)
        return data, issues

    def format_issues(self, issues) -> List[Dict[str, Any]]:
        path_messages: Dict[str, List[str]] = defaultdict(list)
        for issue in issues:
            path_messages[issue.path.pop()].append(issue.message)
        return [{path: msgs} for path, msgs in path_messages.items()]

