  int pidz = get_program_id(1);
  // create index ranges
  int rxm     = pidhm % BLOCK;
  int rbm     = pidhm / BLOCK;
  int rxn[TN] = (0 ... TN) % BLOCK;
  int rbn[TN] = (0 ... TN) / BLOCK;
  // extract information from look-up table
  int* header = LUT + rbm * 2;
  int size    = *(header + 0);
  int offset  = *(header + 1);
  bool check[TN] = rbn < size;
  int   rbmn[TN] = check ? rbn : size - 1;
  // block id and column id
  long blockid [TN]  = *(LUT + offset + rbmn*3 + 0);
  long columnid[TN]  = *(LUT + offset + rbmn*3 + 1);
  long rowid   [TN]  = *(LUT + offset + rbmn*3 + 2);
  // pointers to X
  TYPE* px[TN]  = X + pidz * stride_zx
                    + blockid * BLOCK * BLOCK 
                    + rxm * BLOCK 
                    + rxn;
#ifdef APPLY_RPE
  // pointers to relative position embedding
  TYPE* prpe[TN] = RPE + pidz * stride_zrpe
                            + blockid / num_blocks_per_head * stride_hrpe
                            + columnid * BLOCK
                            + rowid * BLOCK * stride_srpe
                            + rxm * stride_srpe
                            + rxn;
#endif
#ifdef APPLY_KP_MASK
  // pointers to key padding mask
  TYPE* pkp_m[TN]  = KP_M + pidz * stride_zkpm 
                          + columnid * BLOCK
                          + rxn;
#endif
#ifdef APPLY_ATTN_MASK
  // pointers to attention mask
  TYPE* pattn_m[TN] = ATTN_M + columnid * BLOCK 
                             + rowid * BLOCK * stride_zattnm
                             + rxm * stride_zattnm
                             + rxn;
#endif

  // load  input
  TYPE x[TN] =  check ? *px : -INFINITY;
#ifdef APPLY_RPE
  // load relative position embedding
  TYPE rpe[TN] = check ? *prpe : 0;
#endif
#ifdef APPLY_KP_MASK
  // load key-padding mask
  TYPE kp_m[TN] = check ? *pkp_m : -INFINITY;
#endif
#ifdef APPLY_ATTN_MASK
  // load attention mask
  TYPE attn_m[TN] = check ? *pattn_m : -INFINITY;
#endif
  // compute softmax in float
#ifdef APPLY_RPE
  float Frpe[TN] = rpe;
#endif
#ifdef APPLY_KP_MASK
  float Fkp_m[TN] = kp_m;
#endif
#ifdef APPLY_ATTN_MASK
  float Fattn_m[TN] = attn_m;
#endif
#ifdef KP_MASK_MUL
  Fkp_m = (Fkp_m == 0) ? (float[TN])-INFINITY : 0;
#endif
#ifdef ATTN_MASK_MUL
  Fattn_m = (Fattn_m == 0) ? (float[TN])-INFINITY : 0;
#endif
  float Fx[TN] = x;
#ifdef APPLY_SCALE
  Fx = Fx * scale; // apply scale
#endif
#ifdef APPLY_RPE
  Fx = Fx + Frpe; // apply relative position embedding
#endif
#ifdef APPLY_KP_MASK
  Fx = Fx + Fkp_m; // apply key padding mask
#endif
#ifdef APPLY_ATTN_MASK
  Fx = Fx + Fattn_m; // apply attention mask
#endif
  float Fxmax  = Fx[max];
  float Fy[TN] = exp(Fx - Fxmax);
  float Fysum = (check ? Fy : 0)[+];
  // write-back in half/float
  TYPE y[TN] = Fy;
  TYPE ysum = Fysum;
  *?(check)px = y / ysum;
}
'''
backward_kernels = dict()
backward_src = '''
__global__ void softmax_backward(TYPE * X __readonly __noalias __aligned(16), 
                                 float scale,
                                 TYPE* DX __readonly __noalias __aligned(16), 
                                 int* LUT,
                                 int sizemax, 
                                 long stride_zx __multipleof(BLOCK), 
                                 long stride_zdx __multipleof(BLOCK)) {
    int pidhm = get_program_id(0);
    int pidz = get_program_id(1);
    // create index ranges
    int rxm = pidhm % BLOCK;
    int rbm = pidhm / BLOCK;
    int rxn[TN] = (0 ... TN) % BLOCK;
    int rbn[TN] = (0 ... TN) / BLOCK;
    // extract information from look-up table
    int* header = LUT + rbm * 2;
    int size    = *(header + 0);
    int offset  = *(header + 1);
    // bounds checking on lut
    bool check[TN] = rbn < size;
    int rbmn[TN] = check ? rbn : size - 1;
    // initialize pointers to block-sparse input
    long blockid[TN] = *(LUT + offset + rbmn*3);
    TYPE* px[TN] = X + pidz * stride_zx
                         + blockid * BLOCK * BLOCK
                         + rxm * BLOCK
                         + rxn;
    TYPE* pdx[TN] = DX + pidz * stride_zdx
                           + blockid * BLOCK * BLOCK
                           + rxm * BLOCK
                           + rxn;
    // compute fused softmax backward
    TYPE x[TN] = check ? *px : 0;
    TYPE dx[TN] = check ? *pdx : 0;
    float Fdx[TN] = dx;
    float Fx[TN] = x;
    float Fxdx[TN] = Fdx*Fx;
    float Fxdxsum = Fxdx[+];
    float Fy[TN] = Fx * (Fdx - Fxdxsum) * scale;
    TYPE y[TN] = Fy;
    // write-back
    *? (check)pdx = y;
}
'''
class _sparse_softmax_torch(torch.autograd.Function):
    backward_kernels_dict = dict()
    @staticmethod
    def generate_lut(layout, block_size, device):
        _empty_tensor = torch.tensor([], dtype=torch.int64, device=layout.device)
        row_sizes = _empty_tensor.clone()
        # compute sizes along rows
        for head_idx in range(layout.shape[0]):
            row_sizes = torch.cat((row_sizes, layout[head_idx,:,:].sum(-1)))
        # compute offsets in block format
        offsets_arr = torch.zeros_like(row_sizes)
        offsets_arr[1:] = torch.cumsum(row_sizes[:-1], dim=0)
        # block indices
        idx_arr = torch.arange(layout.sum())
        row_indices = layout.nonzero()[:, 1]
        col_indices = layout.nonzero()[:, 2]
        core_data   = torch.stack((idx_arr, col_indices, row_indices), dim=1).view(-1)
        # construct look-up table
        offsets_arr = offsets_arr*3 + 2*row_sizes.numel()
        header_data = torch.stack((row_sizes, offsets_arr), dim=1).view(-1)
        lut_final = torch.cat((header_data, core_data)).type(torch.int32).to(device)
        return lut_final, int(row_sizes.max())
    @staticmethod
    def build_kernel(cache_dict, source_code, max_k, data_type, block_size, use_scale, use_rpe, use_kp_mask, use_attn_mask, kp_mask_strategy, attn_mask_strategy):
        if max_k >= 32768:
          raise NotImplementedError('Reductions larger than 32768 elements '\
                                    'are not yet implemented')
        num_warps = 4 if max_k < 512 else (8 if max_k < 2048 else 16)
        padding = num_warps * 32 * 2
        TN_val = (int(max_k) + padding-1)//padding * padding
        # just-in-time compile kernel
        key_val = (block_size, data_type, num_warps, TN_val, use_scale, use_rpe, use_kp_mask, use_attn_mask, kp_mask_strategy, attn_mask_strategy)
        if key_val not in cache_dict:
            defines_map = {'TM': [1], 'TN': [TN_val], 'TYPE': data_type, 'BLOCK': block_size,
                       'INFINITY': {torch.float32: 'F32_INFINITY',
                                    torch.float16: 'F16_INFINITY'}[data_type]}
            if use_scale:
                defines_map['APPLY_SCALE'] = True
            if use_rpe:
                defines_map['APPLY_RPE'] = True
            if use_kp_mask:
                defines_map['APPLY_KP_MASK'] = True
                if kp_mask_strategy == 'mul':
                    defines_map['KP_MASK_MUL'] = True
            if use_attn_mask:
                defines_map['APPLY_ATTN_MASK'] = True
                if attn_mask_strategy == 'mul':
                    defines_map['ATTN_MASK_MUL'] = True
            compiled_kernel  = triton.kernel(source_code, defines=defines_map, num_warps=[num_warps])
            cache_dict[key_val] = compiled_kernel
        return cache_dict[key_val]
    @staticmethod
    def execute_forward(ctx, input_tensor, scaling_factor, rpe_tensor, key_padding_mask, attention_mask, kp_mask_mode, attn_mask_mode,
                spatial_dims, block_dim, lookup_table, total_blocks, blocks_per_head, max_lookup, benchmark_mode, timing_info):
        use_scale = False if scaling_factor == 1.0 else True
        # handle None rpe
        if rpe_tensor is None:
            use_rpe = False
            stride_zrpe, stride_hrpe, stride_srpe = 0, 0, 0
            rpe_tensor = torch.empty(0, dtype=input_tensor.dtype, device=input_tensor.device)
        else:
            use_rpe = True
            stride_zrpe, stride_hrpe, stride_srpe = rpe_tensor.stride(0), rpe_tensor.stride(1), rpe_tensor.stride(2)
        # handle None key_padding_mask
        if key_padding_mask is None:
            use_kp_mask = False
            stride_zkpm = 0
            key_padding_mask = torch.empty(0, dtype=input_tensor.dtype, device=input_tensor.device)
        else:
            use_kp_mask = True
            stride_zkpm = key_padding_mask.stride(0)
        # handle None attention_mask
        if attention_mask is None:
            use_attn_mask = False
            stride_zattnm = 0
            attention_mask = torch.empty(0, dtype=input_tensor.dtype, device=input_tensor.device)
        else:
            use_attn_mask = True
            stride_zattnm = attention_mask.stride(0)
        # run kernel
        kernel_func = _sparse_softmax_torch.build_kernel(forward_kernels, forward_src, max_lookup*block_dim, input_tensor.dtype, block_dim,
                                            use_scale, use_rpe, use_kp_mask, use_attn_mask,
                                            kp_mask_mode, attn_mask_mode)
        batch_size = input_tensor.shape[0]
        grid_shape = lambda opt: [triton.cdiv(spatial_dims[0] * spatial_dims[1] * block_dim, opt.d('TM')), batch_size]
        # run kernel
        timing_info[0] = kernel_func(input_tensor, scaling_factor, lookup_table, rpe_tensor, key_padding_mask, attention_mask,\
                         total_blocks, blocks_per_head, max_lookup,\
                         input_tensor.stride(0),\
                         stride_zrpe, stride_hrpe, stride_srpe,\
                         stride_zkpm, stride_zattnm,\
                         grid=grid_shape, bench=benchmark_mode)
        # save to context
        ctx.mark_dirty(input_tensor)
        ctx.save_for_backward(input_tensor, lookup_table)
        ctx.spatial_dims = spatial_dims
        ctx.block_dim = block_dim
        ctx.max_lookup = max_lookup
        ctx.scaling_factor = scaling_factor
        ctx.use_scale = use_scale
        ctx.use_rpe = use_rpe
        ctx.use_kp_mask = use_kp_mask
        ctx.use_attn_mask = use_attn_mask
        ctx.kp_mask_mode = kp_mask_mode
        ctx.attn_mask_mode = attn_mask_mode
        return input_tensor

    @staticmethod
    def execute_backward(ctx, grad_output):
        # retrieve from context
        input_tensor, lookup_table = ctx.saved_tensors
        # run kernel
        kernel_func = _sparse_softmax_torch.build_kernel(backward_kernels, backward_src, ctx.max_lookup*ctx.block_dim, input_tensor.dtype, ctx.block_dim, 
                                            ctx.use_scale, ctx.use_rpe, ctx.use_kp_mask, ctx.use_attn_mask,
                                            ctx.kp_mask_mode, ctx.attn_mask_mode)
        batch_size = input_tensor.shape[0]
        grid_shape = lambda opt: [triton.cdiv(ctx.spatial_dims[0] * ctx.spatial_dims[1] * ctx.block_dim, opt.d('TM')), batch_size]
        kernel_func(input_tensor, ctx.scaling_factor, grad_output, lookup_table, ctx.max_lookup, input_tensor.stride(0), grad_output.stride(0), grid=grid_shape)
        return grad_output, None, None, None, None, None, None, None, None, None, None, None, None, None, None
class SparseSoftmax:

    sparse_softmax_op = _sparse_softmax_torch.apply
    def prepare_lut(self, device_target):
        key_val = (device_target, )
        if key_val not in self.lut_cache_dict:
          self.lut_cache_dict[key_val] = _sparse_softmax_torch.generate_lut(self.layout_matrix, self.block_size, device_target)
        return self.lut_cache_dict[key_val]
    def __init__(self, layout_matrix, block_size, benchmark_mode = False):
        self.total_blocks = layout_matrix.sum()
        self.blocks_per_head = self.total_blocks / layout_matrix.shape[0]
        self.spatial_dims = layout_matrix.shape
        self.layout_matrix = layout_matrix
        self.block_size = block_size
        self.benchmark_mode = benchmark_mode
        self.lut_cache_dict = dict()

    def __call__(self, input_tensor, scale_factor = 1., rpe_tensor = None, key_padding_mask = None, attention_mask = None,
            key_padding_mask_mode='add', attention_mask_mode='add'):
        time_y = [None]
        if rpe_tensor is not None and rpe_tensor.dtype != input_tensor.dtype:
            raise ValueError('relative position embedding must be %s' % input_tensor.dtype)
        if attention_mask is not None and attention_mask.dtype != input_tensor.dtype:
            raise ValueError('Attention mask must be %s' % input_tensor.dtype)
        if key_padding_mask is not None and key_padding_mask.dtype != input_tensor.dtype:
            raise ValueError('Key padding mask must be %s' % input_tensor.dtype)
        lut_final, maxlut_val = self.prepare_lut(input_tensor.device)
        output_tensor = SparseSoftmax.sparse_softmax_op(input_tensor, scale_factor, rpe_tensor, key_padding_mask, attention_mask,
                                  key_padding_mask_mode, attention_mask_mode,
                                  self.spatial_dims, self.block_size,
                                  lut_final, self.total_blocks, self.blocks_per_head,
                                  maxlut_val, self.benchmark_mode, time_y)
        self.time_y = time_y[0]
        return output_tensor
