# Custom exceptions for the iAqualink library
class BaseAqualinkError(Exception):
    """Base exception class for iAqualink-related errors."""

class InvalidParameterError(BaseAqualinkError):
    """Raised when an invalid parameter is provided."""

class ServiceError(BaseAqualinkError):
    """Raised when the iaqualink service encounters an error."""

class UnauthorizedAccessError(ServiceError):
    """Raised when access to the service is not authorized."""

class SystemOfflineError(ServiceError):
    """Raised when a system is currently offline."""

class UnsupportedSystemError(ServiceError):
    """Raised when a system is not supported by this library."""

import asyncio
import datetime
import inspect
import random
import textwrap
import time
import traceback
import os
import pkgutil
import aiohttp
import discord
from discord.ext import commands, tasks
from utils import checks
from utils.runtime import CoreMode
from utils.storage import RedisCollection

def reload_core(heleus_instance):
    heleus_instance.loop.create_task(heleus_instance.get_cog('Core').reload_self())

class Core(commands.Cog):
    def __init__(self, heleus_instance):
        self.heleus = heleus_instance
        self.ignore_database = False
        self.verbose_errors = False  # tracebacks?
        self.informative_errors = True  # info messages based on error
        self.config = RedisCollection(self.heleus.redis, 'settings')
        self.logger = self.heleus.logger
        self._post.start()
        self.global_preconditions = [self._ignore_preconditions]  # preconditions to message processing
        self.global_preconditions_overrides = [self._ignore_overrides]  # overrides to the preconditions
        self._evaluator = {}
        self.haste_url = os.environ.get('HELEUS_HASTE_URL', 'https://hastebin.com')
        self.cogs_loaded = False
        self.help_category = 'Core'
        self.help_image = 'https://i.imgur.com/jLP1NEW.png'
        for obj in dir(self):  # docstring formatting
            if obj.startswith('_'):
                continue
            obj = getattr(self, obj)
            if not isinstance(obj, commands.Command):
                continue
            if not obj.help:
                continue
            obj.help = obj.help.format(self.heleus.name)

    def __unload(self):
        self._maintenance_loop.cancel()
        self._owner_checks.cancel()

    @staticmethod
    def fetch_submodules(module):
        # Somewhat hacky but OH WELL
        if module.endswith('.*'):
            module = module[:-2]
        return [f'{module}.{x.name}' for x in pkgutil.iter_modules([module])]

    async def _cog_loop(self):
        cogs: list = await self.config.get('cogs', [])
        modified = False
        if self.heleus.autoload and not self.cogs_loaded:
            for module in self.heleus.autoload:
                if module.endswith('.*'):
                    submodules = self.fetch_submodules(module)
                    for submodule in submodules:
                        if submodule not in cogs:
                            cogs.append(submodule)
                            modified = True
                else:
                    if module not in cogs:
                        cogs.append(module)
                        modified = True
            self.cogs_loaded = True
        for cog in cogs:
            if cog not in list(self.heleus.extensions):
                # noinspection PyBroadException
                try:
                    await self.load_cog(cog)
                except Exception:
                    cogs.remove(cog)
                    modified = True
                    self.logger.warning(f'{repr(cog)} could not be loaded. This message will not be shown again.')
        if modified:
            await self.config.set('cogs', cogs)
        for cog in list(self.heleus.extensions):
            if cog == 'cogs.core':
                continue
            if cog not in cogs:
                self.heleus.unload_extension(cog)

    async def _get_guild_config(self, guild_id, attribute, default=None):
        guild = await self.config.get(f'guilds:{guild_id}', {})
        return guild.get(attribute, default)

    async def _set_guild_config(self, guild_id, attribute, value):
        guild = await self.config.get(f'guilds:{guild_id}', {})
        guild[attribute] = value
        await self.config.set(f'guilds:{guild_id}', guild)

    @tasks.loop(count=1)
    async def _post(self):
        """Power-on self test. Beep boop."""
        self.heleus.administrators = []
        # set prefixes
        prefix = str(random.randint(1, 2**8))
        prefixes = await self.config.get('prefixes')
        if prefixes is None:
            prefixes = [prefix]
            await self.config.set('prefixes', prefixes)
        self.heleus.command_prefix = prefixes
        self.logger.info(f'{self.heleus.name}\'s prefixes are: {", ".join(map(repr, prefixes))}')
        # Load cogs
        await self._cog_loop()
        # Mess with the instance's mode
        instance = await self.config.get(self.heleus.instance_id, {'mode': CoreMode.boot})
        if not self.heleus.initialized:
            if instance['mode'] == CoreMode.up:
                instance['mode'] = CoreMode.boot
                await self.config.set(self.heleus.instance_id, instance)
        await self.heleus.wait_until_ready()
        self.heleus.initialized = True
        if instance['mode'] == CoreMode.boot:
            instance['mode'] = CoreMode.up
            await self.config.set(self.heleus.instance_id, instance)
        # migration
        keys = await self.config.keys()
        if 'roles' in keys:
            roles = await self.config.get('roles')
            for guild in roles:
                await self._set_guild_config(
                    int(guild), 'roles', {k.rstrip('_role'): v for k, v in roles[guild].items()}
                )
            await self.config.delete('roles')
        if 'ignores' in keys:
            ignores = await self.config.get('ignores')
            for guild in ignores:
                entry = []
                [entry.append(int(x)) for x in ignores[guild]['ignored_channels']]
                if ignores[guild]['server_ignore']:
                    entry.append(int(guild))
                await self._set_guild_config(int(guild), 'ignores', entry)
            await self.config.delete('ignores')
        # start the loops
        self._maintenance_loop.start()
        self._owner_checks.start()

    @tasks.loop(seconds=15)
    async def _owner_checks(self):
        # Owner checks
        app_info = await self.heleus.application_info()
        administrators = await self.config.get('owners', [])
        administrators = list(map(int, administrators))
        if app_info.team:
            for member in app_info.team.members:
                if member.membership_state == discord.TeamMembershipState.accepted and member.id not in administrators:
                    administrators.append(member.id)
        else:
            if app_info.owner.id not in administrators:
                administrators.append(app_info.owner.id)
                await self.config.set('owners', administrators)
        self.heleus.administrators = administrators

    @tasks.loop(seconds=1)
    async def _maintenance_loop(self):
        if not self.ignore_database:
            # Loading cogs / Unloading cogs
            await self._cog_loop()
            # Prefix changing
            self.heleus.command_prefix = await self.config.get('prefixes')

    async def _ignore_overrides(self, message):
        if isinstance(message.author, discord.Member):
            if not self.heleus.intents.guilds:
                self.logger.warning('guilds intent is not available! Cannot check ignore_overrides.')
                return
            if message.guild.owner == message.author:
                return True
            try:
                roles = {x.name.lower() for x in message.author.roles}
                settings = await self._get_guild_config(message.guild.id, 'roles', {})
                admin = settings.get('admin')
                if admin in roles:
                    return True
            except KeyError or AttributeError:
                pass

    async def _ignore_preconditions(self, message):
        if isinstance(message.author, discord.Member):
            if not self.heleus.intents.guilds:
                self.logger.warning('guilds intent is not available! Cannot check ignore_preconditions.')
                return
            ignores = await self._get_guild_config(message.guild.id, 'ignores', [])
            if message.author.id in ignores:
                return False
            if message.channel.id in ignores:
                return False
            if message.guild.id in ignores:
                return False

    async def create_haste(self, content):
        async with aiohttp.ClientSession() as session:
            async with session.post(f'{self.haste_url}/documents', data=content) as response:
                return await response.json()

    @staticmethod
    def get_traceback(exception, limit=None, chain=True):
        return ''.join(traceback.format_exception(type(exception), exception, exception.__traceback__, limit=limit,
                                                  chain=chain))

    async def reload_self(self):
        self.heleus.unload_extension('cogs.core')
        await self.load_cog('cogs.core')

    # make IDEA stop acting like a baby
    # noinspection PyShadowingBuiltins
    async def load_cog(self, name):
        self.logger.debug(f'Attempting to load cog {name}')
        if name in self.heleus.extensions:
            return
        self.heleus.load_extension(name)
        cogs = await self.config.get('cogs', [])
        if name not in cogs:
            cogs.append(name)
            await self.config.set('cogs', cogs)
        self.logger.debug(f'Cog {name} loaded successfully')

    # noinspection PyArgumentList
    @commands.Cog.listener()
    async def on_message(self, message):
        instance = await self.config.get(self.heleus.instance_id, {})
        mode = instance.get('mode', CoreMode.down)
        if mode in (CoreMode.down, CoreMode.boot):
            return
        if message.author.id in self.heleus.administrators:  # *always* process owner commands
            await self.heleus.process_commands(message)
            return
        if mode == CoreMode.maintenance:
            return
        # Overrides start here (yay)
        for override in self.global_preconditions_overrides:
            # noinspection PyBroadException
            try:
                out = override(message)
                if inspect.isawaitable(out):
                    out = await out
                if out is True:
                    await self.heleus.process_commands(message)
                    return
            except Exception:
                self.logger.exception(f'Removed precondition override "{override.__name__}", it was malfunctioning.')
                self.global_preconditions_overrides.remove(override)
        # Preconditions
        for precondition in self.global_preconditions:
            # noinspection PyBroadException
            try:
                out = precondition(message)
                if inspect.isawaitable(out):
                    out = await out
                if out is False:
                    return
            except Exception:
                self.logger.exception(f'Removed precondition "{precondition.__name__}", it was malfunctioning.')
                self.global_preconditions.remove(precondition)
        await self.heleus.process_commands(message)

    @commands.Cog.listener()
    async def on_command_error(self, context, exception):
        try:
            if isinstance(exception, commands.CommandInvokeError):
                exception = exception.original
