import torch
from torch import nn, Tensor
from semseg.models.layers import DropPath

class PatchEmbed(nn.Module):
    """Image to Patch Embedding with overlapping"""
    def __init__(self, patch_size=16, stride=16, padding=0, in_ch=3, embed_dim=768):
        super().__init__()
        self.conv_proj = nn.Conv2d(in_ch, embed_dim, patch_size, stride, padding)

    def forward(self, x: torch.Tensor) -> Tensor:
        x = self.conv_proj(x)                   # b x hidden_dim x 14 x 14
        return x

class Pooling(nn.Module):
    def __init__(self, pool_size=3) -> None:
        super().__init__()
        self.pool_layer = nn.AvgPool2d(pool_size, 1, pool_size//2, count_include_pad=False)

    def forward(self, x: Tensor) -> Tensor:
        return self.pool_layer(x) - x

class MLP(nn.Module):
    def __init__(self, dim, hidden_dim, out_dim=None) -> None:
        super().__init__()
        out_dim = out_dim or dim
        self.dense1 = nn.Conv2d(dim, hidden_dim, 1)
        self.activation = nn.GELU()
        self.dense2 = nn.Conv2d(hidden_dim, out_dim, 1)

    def forward(self, x: Tensor) -> Tensor:
        return self.dense2(self.activation(self.dense1(x)))

class PoolFormerBlock(nn.Module):
    def __init__(self, dim, pool_size=3, dpr=0., layer_scale_init_value=1e-5):
        super().__init__()
        self.norm1 = nn.GroupNorm(1, dim)
        self.token_mixer = Pooling(pool_size)
        self.norm2 = nn.GroupNorm(1, dim)
        self.drop_path = DropPath(dpr) if dpr > 0. else nn.Identity()
        self.mlp_block = MLP(dim, int(dim*4))

        self.gamma1 = nn.Parameter(layer_scale_init_value * torch.ones((dim)), requires_grad=True)
        self.gamma2 = nn.Parameter(layer_scale_init_value * torch.ones((dim)), requires_grad=True)

    def forward(self, x: Tensor) -> Tensor:
        x = x + self.drop_path(self.gamma1.unsqueeze(-1).unsqueeze(-1) * self.token_mixer(self.norm1(x))) 
        x = x + self.drop_path(self.gamma2.unsqueeze(-1).unsqueeze(-1) * self.mlp_block(self.norm2(x))) 
        return x

poolformer_configs = {
    'S24': [[4, 4, 12, 4], [64, 128, 320, 512], 0.1],       # [layers, embed_dims, drop_path_rate]
    'S36': [[6, 6, 18, 6], [64, 128, 320, 512], 0.2],
    'M36': [[6, 6, 18, 6], [96, 192, 384, 768], 0.3]
}

class PoolFormer(nn.Module):     
    def __init__(self, model_name: str = 'S24') -> None:
        super().__init__()
        assert model_name in poolformer_configs.keys(), f"PoolFormer model name should be in {list(poolformer_configs.keys())}"
        layers, embed_dims, drop_path_rate = poolformer_configs[model_name]
        self.channels = embed_dims

        self.patch_embed = PatchEmbed(7, 4, 2, 3, embed_dims[0])
        network = []
        for i in range(len(layers)):
            blocks = []
            for j in range(layers[i]):
                dpr = drop_path_rate * (j + sum(layers[:i])) / (sum(layers) - 1)
                blocks.append(PoolFormerBlock(embed_dims[i], 3, dpr))
            network.append(nn.Sequential(*blocks))
            if i >= len(layers) - 1: break
            network.append(PatchEmbed(3, 2, 1, embed_dims[i], embed_dims[i+1]))
        self.network = nn.ModuleList(network)
        self.out_indices = [0, 2, 4, 6]
        for i, idx in enumerate(self.out_indices):
            self.add_module(f"norm{idx}", nn.GroupNorm(1, embed_dims[i]))

    def forward(self, x: Tensor):
        x = self.patch_embed(x)
        outputs = []
        for i, blk in enumerate(self.network):
            x = blk(x)
            if i in self.out_indices:
                out = getattr(self, f"norm{i}")(x)
                outputs.append(out)
        return outputs

