# Safe execution wrapper for Wolfram Language functions
from __future__ import absolute_import, print_function, unicode_literals
import sys
import traceback
from functools import wraps
from wolframclient.language import wl
from wolframclient.language.exceptions import WolframLanguageException
from wolframclient.serializers import DEFAULT_FORMAT, export
from wolframclient.utils.encoding import force_text, safe_force_text

DEFAULT_ERROR_RESPONSE = {
    "wxf": b"8:f\x02s\x07FailureS\x0dPythonFailureA\x01-S\x0fMessageTemplateS\x1aUnexpected error occurred.",
    "wl": b'Failure["PythonFailure", <|"MessageTemplate" -> "Unexpected error occurred."|>]',
}

def protected_wl_call(func, parameters=(), options={}, serialization_opts={}, error_type=None):
    __traceback_hidden_variables__ = True
    try:
        return export(func(*parameters, **options), **serialization_opts)
    except Exception as serialization_error:
        try:
            try:
                # Allow custom exception types; handle potential failures during serialization
                if isinstance(serialization_error, WolframLanguageException):
                    try:
                        serialization_error.set_traceback(*sys.exc_info())
                        return export(serialization_error, **serialization_opts)
                    except Exception:
                        pass

                if not error_type or error_type is WolframLanguageException:
                    return export(
                        WolframLanguageException(serialization_error, exec_info=sys.exc_info()),
                        **serialization_opts
                    )

                # Attempt to use provided exception class, fallback if it fails
                try:
                    return export(
                        error_type(serialization_error, exec_info=sys.exc_info()), 
                        **serialization_opts
                    )
                except Exception:
                    return export(
                        WolframLanguageException(serialization_error, exec_info=sys.exc_info()),
                        target_format=serialization_opts.get("target_format", DEFAULT_FORMAT),
                        encoder="wolframclient.serializers.encoders.builtin.encoder",
                    )
            except Exception as export_failure:
                return export(
                    WolframLanguageException(export_failure, exec_info=sys.exc_info()),
                    target_format=serialization_opts.get("target_format", DEFAULT_FORMAT),
                    encoder="wolframclient.serializers.encoders.builtin.encoder",
                )
        except Exception as final_error:
            # Final fallback for catastrophic failures
            try:
                return export(
                    wl.Failure(
                        "PythonFailure",
                        {
                            "MessageTemplate": safe_force_text(final_error),
                            "MessageParameters": {},
                            "FailureCode": safe_force_text(
                                final_error.__class__.__name__
                            ),
                            "Traceback": force_text(traceback.format_exc()),
                        },
                    ),
                    target_format=serialization_opts.get("target_format", DEFAULT_FORMAT),
                    encoder="wolframclient.serializers.encoders.builtin.encoder",
                )
            except Exception:
                # Ultimate fallback - return default error response
                return DEFAULT_ERROR_RESPONSE[
                    serialization_opts.get("target_format", DEFAULT_FORMAT)
                ]

def convert_to_wl(error_class=None, **serialization_opts):
    def decorator(function):
        @wraps(function)
        def wrapper(*args, **options):
            return protected_wl_call(
                func=function,
                parameters=args,
                options=options,
                serialization_opts=serialization_opts,
                error_type=error_class,
            )
        return wrapper
    return decorator

# Import necessary modules for logging, timing, and metrics
import logging
import time
import inspect
from functools import wraps
from typing import Any, List
from dispatch.metrics import provider as metrics_provider
from .extensions import sentry_sdk, configure_extensions
from .database import SessionLocal

logger = logging.getLogger(__name__)

def get_full_qualified_name(obj):
    """Returns the fully qualified name of an object."""
    module = inspect.getmodule(obj)
    return f"{module.__name__}.{obj.__qualname__}"

def background_task(func):
    """Decorator that initializes a background task with a database session 
    and error handling. Since background tasks execute in separate threads,
    exceptions are logged but not propagated.
    """
    @wraps(func)
    def wrapper(*args, **kwargs):
        needs_session = False
        if "db_session" not in kwargs or not kwargs["db_session"]:
            db_session = SessionLocal()
            needs_session = True
            kwargs["db_session"] = db_session

        try:
            metrics_provider.counter("function.call.counter", tags={"function": get_full_qualified_name(func)})
            start_time = time.perf_counter()
            outcome = func(*args, **kwargs)
            duration = time.perf_counter() - start_time
            metrics_provider.timer(
                "function.elapsed.time", value=duration, tags={"function": get_full_qualified_name(func)}
            )
            return outcome
        except Exception as err:
            logger.exception(err)
        finally:
            if needs_session:
                kwargs["db_session"].close()

    return wrapper

def timer(func: Any):
    """Decorator to measure and report execution time of a function."""
    @wraps(func)
    def wrapper(*args, **kwargs):
        start_time = time.perf_counter()
        result = func(*args, **kwargs)
        elapsed = time.perf_counter() - start_time
        metrics_provider.timer(
            "function.elapsed.time", value=elapsed, tags={"function": get_full_qualified_name(func)}
        )
        return result
    return wrapper

def counter(func: Any):
    """Decorator to increment a call counter metric for the decorated function."""
    @wraps(func)
    def wrapper(*args, **kwargs):
        metrics_provider.counter("function.call.counter", tags={"function": get_full_qualified_name(func)})
        return func(*args, **kwargs)
    return wrapper

def apply(decorator: Any, skip_methods: List[str] = None):
    """Class decorator that applies a given decorator to all methods of a class,
    optionally excluding specified method names.
    """
    if not skip_methods:
        skip_methods = []

    def decorate(cls):
        for attribute_name in cls.__dict__:
            attr = getattr(cls, attribute_name)
            if callable(attr) and attribute_name not in skip_methods:
                setattr(cls, attribute_name, decorator(attr))
        return cls

    return decorate

# Compute histogram for input datasets
from dexp.cli.parsing import _parse_channels, _parse_slicing
from dexp.datasets.open_dataset import glob_datasets
from dexp.datasets.operations.histogram import dataset_histogram
import click

@click.command()
@click.argument("input-paths", nargs=-1)
@click.option("--output-directory", "-o", default="histogram_plot", show_default=True, type=str)
@click.option("--channels", "-c", default=None, help="list of channels to process; all channels used if omitted.")
@click.option(
    "--slicing",
    "-s",
    default=None,
    help="dataset slice specification (TZYX), e.g. [0:5] (first five stacks) or [:,0:100] (z-cropping) ",
)
@click.option("--device-id", "-d", type=int, default=0, show_default=True)
@click.option(
    "--min-count",
    "-m",
    default=3,
    show_default=True,
    type=int,
    help="Minimum histogram count threshold for determining upper limit; values below this are ignored.",
)
@click.option(
    "--max-count",
    "-M",
    default=None,
    show_default=True,
    type=float,
    help="Upper count limit for clipping histogram to enhance visualization.",
)
def compute_histogram(input_paths, output_directory, channels, slicing, device_id, min_count, max_count):
    loaded_dataset, file_paths = glob_datasets(input_paths)
    selected_channels = _parse_channels(loaded_dataset, channels)
    parsed_slicing = _parse_slicing(slicing)

    if parsed_slicing is not None:
        loaded_dataset.set_slicing(parsed_slicing)

    dataset_histogram(
        dataset=loaded_dataset,
        output_dir=output_directory,
        channels=selected_channels,
        device=device_id,
        minimum_count=min_count,
        maximum_count=max_count,
    )

