from . import tensor_shape
from . import errors
from typing import Tuple, Optional
import numpy as np

class TensorBuffer:
  def __init__(self, data=None, buffer_offset=0, layout="C"):
    self._data = data
    self._buffer_offset = buffer_offset
    self._layout = layout

  def data(self):
    return self._data

  def buffer_offset(self):
    return self._buffer_offset

  def layout(self):
    return self._layout


class Tensor:
  def __init__(self,
               dtype: types_pb2.DataType = types_pb2.DT_FLOAT,
               dims: tensor_shape.TensorShape = None,
               buf: TensorBuffer = None):
    if dims is None:
      dims = tensor_shape.TensorShape()
    dims.set_data_type(dtype)
    self._dims = dims
    self._buf = buf

  def __repr__(self):
    return f"Tensor(is_initialized={self.is_initialized()}, shape={self.dims()!r})"

  def dims(self) -> tensor_shape.TensorShape:
    return self._dims

  def dtype(self) -> types_pb2.DataType:
    return self._dims.data_type()

  def rank(self) -> int:
    return self.dims().dims()

  def dim_length(self, axis: int) -> int:
    return self.dims().dim_size(axis)

  def total_elements(self) -> int:
    return self.dims().num_elements()

  def is_initialized(self) -> bool:
    """Check whether this Tensor has been initialized.
    Empty Tensors are always treated as initialized, regardless of allocation status."""
    return (self._buf is not None and self._buf.data() is not None) or self.total_elements() == 0

  def assign_buffer(self, buf: TensorBuffer):
    self._buf = buf

  def to_numpy(self) -> Tuple[errors.Status, Optional[np.ndarray]]:
    if not self.is_initialized():
      return errors.FailedPrecondition("Tensor not initialized"), None

    shape_info = self.dims()
    element_type = shape_info.dtype()
    if element_type is None:
      return errors.Unimplemented("Unsupported data type ", shape_info.data_type(), " in conversion"), None

    if self.total_elements() != 0:
      arr = np.ndarray.__new__(np.ndarray,
                               shape=shape_info.to_list(),
                               dtype=element_type,
                               buffer=self._buf.data(),
                               offset=self._buf.buffer_offset(),
                               order=self._buf.layout())
    else:
      arr = np.zeros(shape_info.to_list(), dtype=element_type)

    return errors.Status.OK(), arr

# MemoryDataStore implementation with in-memory storage for tasks, schedules, and jobs
from bisect import bisect_left, insort_right
from collections import defaultdict
from datetime import MAXYEAR, datetime, timedelta, timezone
from functools import partial
from typing import Any, Iterable, Optional
from uuid import UUID
import attr
from ..abc import DataStore, EventBroker, EventSource, Job, Schedule
from ..enums import ConflictPolicy
from ..eventbrokers.local import LocalEventBroker
from ..events import (
    JobAcquired, JobAdded, JobReleased, ScheduleAdded, ScheduleRemoved, ScheduleUpdated, TaskAdded,
    TaskRemoved, TaskUpdated)
from ..exceptions import ConflictingIdError, TaskLookupError
from ..structures import JobResult, Task
from ..util import reentrant

# Define maximum datetime value
max_dt = datetime(MAXYEAR, 12, 31, 23, 59, 59, 999999, tzinfo=timezone.utc)

@attr.define
class TaskState:
    task: Task
    active_jobs: int = 0
    persisted_state: Any = None

    def __eq__(self, other):
        return self.task.id == other.task.id

@attr.define
class ScheduleState:
    schedule: Schedule
    next_run_time: Optional[datetime] = attr.field(init=False, eq=False)
    claimed_by: Optional[str] = attr.field(init=False, eq=False, default=None)
    claim_expires_at: Optional[datetime] = attr.field(init=False, eq=False, default=None)

    def __attrs_post_init__(self):
        self.next_run_time = self.schedule.next_fire_time

    def __eq__(self, other):
        return self.schedule.id == other.schedule.id

    def __lt__(self, other):
        if self.next_run_time is None:
            return False
        elif other.next_run_time is None:
            return self.next_run_time is not None
        else:
            return self.next_run_time < other.next_run_time

    def __hash__(self):
        return hash(self.schedule.id)

@attr.define(order=True)
class JobState:
    job: Job = attr.field(order=False)
    created_on: datetime = attr.field(init=False, factory=partial(datetime.now, timezone.utc))
    claimed_by: Optional[str] = attr.field(eq=False, order=False, default=None)
    claim_expires_at: Optional[datetime] = attr.field(eq=False, order=False, default=None)

    def __eq__(self, other):
        return self.job.id == other.job.id

    def __hash__(self):
        return hash(self.job.id)

@reentrant
@attr.define(eq=False)
class MemoryDataStore(DataStore):
    lock_timeout: float = 30
    _event_system: EventBroker = attr.Factory(LocalEventBroker)
    _tasks_store: dict[str, TaskState] = attr.Factory(dict)
    _schedules_list: list[ScheduleState] = attr.Factory(list)
    _schedules_map: dict[str, ScheduleState] = attr.Factory(dict)
    _schedules_by_task: dict[str, set[ScheduleState]] = attr.Factory(partial(defaultdict, set))
    _jobs_list: list[JobState] = attr.Factory(list)
    _jobs_map: dict[UUID, JobState] = attr.Factory(dict)
    _jobs_by_task_id: dict[str, set[JobState]] = attr.Factory(partial(defaultdict, set))
    _job_results_cache: dict[UUID, JobResult] = attr.Factory(dict)

    def _locate_schedule_position(self, state: ScheduleState) -> Optional[int]:
        start_idx = bisect_left(self._schedules_list, state)
        end_idx = bisect_left(self._schedules_list, state)
        try:
            return self._schedules_list.index(state, start_idx, end_idx + 1)
        except ValueError:
            return None

    def _locate_job_position(self, state: JobState) -> Optional[int]:
        start_idx = bisect_left(self._jobs_list, state)
        end_idx = bisect_left(self._jobs_list, state)
        try:
            return self._jobs_list.index(state, start_idx, end_idx + 1)
        except ValueError:
            return None

    def __enter__(self):
        self._event_system.__enter__()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self._event_system.__exit__(exc_type, exc_val, exc_tb)

    @property
    def events(self) -> EventSource:
        return self._event_system

    def fetch_schedules(self, ids: Optional[set[str]] = None) -> list[Schedule]:
        return [state.schedule for state in self._schedules_list
                if ids is None or state.schedule.id in ids]

    def register_task(self, task: Task) -> None:
        exists = task.id in self._tasks_store
        self._tasks_store[task.id] = TaskState(task)
        if exists:
            self._event_system.publish(TaskUpdated(task_id=task.id))
        else:
            self._event_system.publish(TaskAdded(task_id=task.id))

    def unregister_task(self, task_id: str) -> None:
        try:
            del self._tasks_store[task_id]
        except KeyError:
            raise TaskLookupError(task_id) from None
        self._event_system.publish(TaskRemoved(task_id=task_id))

    def retrieve_task(self, task_id: str) -> Task:
        try:
            return self._tasks_store[task_id].task
        except KeyError:
            raise TaskLookupError(task_id) from None

    def list_tasks(self) -> list[Task]:
        return sorted((state.task for state in self._tasks_store.values()), key=lambda t: t.id)

    def register_schedule(self, schedule: Schedule, conflict_policy: ConflictPolicy) -> None:
        existing = self._schedules_map.get(schedule.id)
        if existing is not None:
            if conflict_policy is ConflictPolicy.do_nothing:
                return
            elif conflict_policy is ConflictPolicy.exception:
                raise ConflictingIdError(schedule.id)
            pos = self._locate_schedule_position(existing)
            if pos is not None:
                del self._schedules_list[pos]
                self._schedules_by_task[existing.schedule.task_id].discard(existing)

        new_state = ScheduleState(schedule)
        self._schedules_map[schedule.id] = new_state
        self._schedules_by_task[schedule.task_id].add(new_state)
        insort_right(self._schedules_list, new_state)

        if existing is not None:
            evt = ScheduleUpdated(schedule_id=schedule.id,
                                  next_fire_time=schedule.next_fire_time)
        else:
            evt = ScheduleAdded(schedule_id=schedule.id,
                                next_fire_time=schedule.next_fire_time)
        self._event_system.publish(evt)

    def delete_schedules(self, ids: Iterable[str]) -> None:
        for sched_id in ids:
            state = self._schedules_map.pop(sched_id, None)
            if state:
                self._schedules_list.remove(state)
                self._event_system.publish(ScheduleRemoved(schedule_id=state.schedule.id))

    def claim_schedules(self, scheduler_id: str, max_count: int) -> list[Schedule]:
        current_time = datetime.now(timezone.utc)
        scheduled_items: list[Schedule] = []

        for state in self._schedules_list:
            if state.next_run_time is None or state.next_run_time > current_time:
                break
            elif state.claimed_by is not None:
                if state.claimed_by != scheduler_id and current_time <= state.claim_expires_at:
                    continue

            scheduled_items.append(state.schedule)
            state.claimed_by = scheduler_id
            state.claim_expires_at = current_time + timedelta(seconds=self.lock_timeout)

            if len(scheduled_items) == max_count:
                break

        return scheduled_items

    def unclaim_schedules(self, scheduler_id: str, schedules: list[Schedule]) -> None:
        completed_ids: list[str] = []
        for sched in schedules:
            if sched.next_fire_time is not None:
                sched_state = self._schedules_map.get(sched.id)
                idx = self._locate_schedule_position(sched_state)
                if idx is not None:
                    del self._schedules_list[idx]

                sched_state.next_run_time = sched.next_fire_time
                sched_state.claimed_by = None
                sched_state.claim_expires_at = None
                insort_right(self._schedules_list, sched_state)

                self._event_system.publish(
                    ScheduleUpdated(schedule_id=sched.id, next_fire_time=sched.next_fire_time)
                )
            else:
                completed_ids.append(sched.id)

        if completed_ids:
            self.delete_schedules(completed_ids)

    def get_next_schedule_time(self) -> Optional[datetime]:
        return self._schedules_list[0].next_run_time if self._schedules_list else None

    def enqueue_job(self, job: Job) -> None:
        job_state = JobState(job)
        self._jobs_list.append(job_state)
        self._jobs_map[job.id] = job_state
        self._jobs_by_task_id[job.task_id].add(job_state)

        self._event_system.publish(
            JobAdded(job_id=job.id, task_id=job.task_id, schedule_id=job.schedule_id,
                     tags=job.tags)
        )

    def fetch_jobs(self, ids: Optional[Iterable[UUID]] = None) -> list[Job]:
        if ids is not None:
            ids = frozenset(ids)
        return [state.job for state in self._jobs_list if ids is None or state.job.id in ids]

    def claim_jobs(self, worker_id: str, max_jobs: Optional[int] = None) -> list[Job]:
        now = datetime.now(timezone.utc)
        acquired_jobs: list[Job] = []

        for index, job_state in enumerate(self._jobs_list):
            task_state = self._tasks_store[job_state.job.task_id]

            # Skip already claimed jobs unless the claim has expired
            if job_state.claimed_by is not None:
                if job_state.claim_expires_at >= now:
                    continue
                else:
                    task_state.active_jobs -= 1

            # Check if task allows more jobs to run
            if (task_state.task.max_running_jobs is not None
                    and task_state.active_jobs >= task_state.task.max_running_jobs):
                continue

            # Claim the job for this worker
            acquired_jobs.append(job_state.job)
            job_state.claimed_by = worker_id
            job_state.claim_expires_at = now + timedelta(seconds=self.lock_timeout)
            task_state.active_jobs += 1

            if len(acquired_jobs) == max_jobs:
                break

        for job in acquired_jobs:
            self._event_system.publish(JobAcquired(job_id=job.id, worker_id=worker_id))

        return acquired_jobs

    def complete_job(self, worker_id: str, task_id: str, result: JobResult) -> None:
        job_state = self._jobs_map.pop(result.job_id)
        self._jobs_by_task_id[task_id].discard(job_state)

        idx = self._locate_job_position(job_state)
        if idx is not None:
            del self._jobs_list[idx]

        # Decrement running job count
        task_state = self._tasks_store.get(task_id)
        if task_state is not None:
            task_state.active_jobs -= 1

        # Store result
        self._job_results_cache[result.job_id] = result

        self._event_system.publish(
            JobReleased(job_id=result.job_id, worker_id=worker_id, outcome=result.outcome)
        )

    def retrieve_job_result(self, job_id: UUID) -> Optional[JobResult]:
        return self._job_results_cache.pop(job_id, None)

# Calculate the number of unique paths in a grid
class Solution:
    def uniquePaths(self, rows: int, cols: int) -> int:
        cache = {}

        def _count_paths(x: int, y: int) -> int:
            if (x, y) in cache:
                return cache[(x, y)]

            # Base case: reached the bottom-right corner
            if x >= rows - 1 or y >= cols - 1:
                return 1

            # Recursive case: move right + move down
            path_count = _count_paths(x + 1, y) + _count_paths(x, y + 1)
            cache[(x, y)] = path_count
            return path_count

        return _count_paths(0, 0)

# Uptime Robot integration config flow
from __future__ import annotations
from pyuptimerobot import UptimeRobot
import voluptuous as vol
from homeassistant import config_entries
from homeassistant.const import CONF_API_KEY
from homeassistant.core import HomeAssistant
from homeassistant.data_entry_flow import FlowResult
from homeassistant.exceptions import HomeAssistantError
from homeassistant.helpers.typing import ConfigType
from .const import API_ATTR_OK, API_ATTR_STAT, DOMAIN, LOGGER

STEP_USER_DATA_SCHEMA = vol.Schema({vol.Required(CONF_API_KEY): str})

async def validate_connection(hass: HomeAssistant, input_data: ConfigType) -> None:
    """Verify that the provided credentials allow connection to Uptime Robot."""
    api_client = UptimeRobot()
    monitors = await hass.async_add_executor_job(
        api_client.getMonitors, input_data[CONF_API_KEY]
    )
    if not monitors or monitors.get(API_ATTR_STAT) != API_ATTR_OK:
        raise ConnectionFailed("Unable to connect to Uptime Robot API")

class UptimeRobotConfigFlow(config_entries.ConfigFlow, domain=DOMAIN):
    """Handle configuration flow for Uptime Robot integration."""
    VERSION = 1

    async def async_step_user(self, user_input: ConfigType | None = None) -> FlowResult:
        """Process the initial user configuration step."""
        validation_errors: dict[str, str] = {}

        if user_input is None:
            return self.async_show_form(
                step_id="user", data_schema=STEP_USER_DATA_SCHEMA, errors=validation_errors
            )

        try:
            await validate_connection(self.hass, user_input)
        except ConnectionFailed:
            validation_errors["base"] = "connection_error"
        except Exception:  # pylint: disable=broad-except
            LOGGER.exception("Unexpected error during configuration")
            validation_errors["base"] = "unexpected_error"
        else:
            return self.async_create_entry(title="", data=user_input)

        return self.async_show_form(
            step_id="user", data_schema=STEP_USER_DATA_SCHEMA, errors=validation_errors
        )

    async def async_step_import(self, import_config: ConfigType) -> FlowResult:
        """Import existing configuration from YAML."""
        for existing_entry in self._async_current_entries():
            if existing_entry.data[CONF_API_KEY] == import_config[CONF_API_KEY]:
                LOGGER.warning(
                    "Duplicate configuration detected. The YAML entry has already been imported. Please remove it."
                )
                return self.async_abort(reason="duplicate_config")

        return self.async_create_entry(
            title="", data={CONF_API_KEY: import_config[CONF_API_KEY]}
        )

