from typing import Tuple
from pyisc.dhcpd.nodes import (CustomOption, DhcpClass, Event, EventSet, Group,
                               Hardware, Host, Include, Key, Failover, Option,
                               OptionExpression, Pool4, Prefix6, Range4,
                               Range6, ServerDuidEN, ServerDuidLL, SubClass,
                               Subnet4, Subnet6, SharedNetwork, Zone)

class TokenHandler:
    """A handler class for tokens.
    This class accepts a token and utilizes the lowercase token name to match a
    method. If a matching method is found, it executes that method and returns
    the resulting value or object along with the method to add it to the current working node.
    """

    def dispatch(self, token) -> Tuple:
        """
        Returns a tuple of value/object and method.
        Args:
            token (pyisc.dhcpd.parsing.Token): A provided token instance.
        Returns:
            tuple: Tuple containing value or object in first position
                and method in second position.
        Examples:
            >>> token = Token(type='OPTION',
            ...               value='option domain-name "example.org";',
            ...               line=8, column=0)
            >>> processor = TokenHandler()
            >>> declaration, method = processor.dispatch(token)
            >>> declaration
            Option(name="domain_name", value=""example.org"")
            >>> method
            'add_option'
        """
        self.current_token = token
        return getattr(self, str(token.type).lower(), self.handle_not_found)()

    def handle_not_found(self):
        raise AttributeError(
            f'Token {self.current_token.type} does not have an associated method.')

    def authoritative(self) -> Tuple:
        """Returns tuple for the authoritative command."""
        if 'not' in self.current_token.value:
            return (False, 'authoritative')
        return (True, 'authoritative')

    def hardware(self) -> Tuple:
        """Returns tuple for the hardware command."""
        _, hw_type, hw_addr = self.current_token.value[:-1].split()
        node_hardware = Hardware(type=hw_type, address=hw_addr)
        return (node_hardware, 'hardware')

    def primary(self) -> Tuple:
        """Returns tuple for the zone primary command."""
        _, primary_server = self.current_token.value[:-1].split()
        return (primary_server, 'primary')

    def failover_role(self) -> Tuple:
        """Returns tuple for the failover role."""
        role_value = self.current_token.value[:-1]
        return (role_value, 'role')

    def include(self) -> Tuple:
        """Returns tuple for the include declaration."""
        _, filename = self.current_token.value[:-1].split()
        declaration = Include(filename=filename)
        return (declaration, 'add_include')

    def general_parameter(self) -> Tuple:
        """Returns tuple for all other parameters."""
        key_part, val_part = self.current_token.value[:-1].rsplit(' ', 1)
        if val_part.isdigit():
            val_part = int(val_part)
        attr_key = key_part.replace('-', '_').replace(' ', '_')
        return (val_part, attr_key)

    def allow_member(self) -> Tuple:
        """Returns tuple for the allow member of statement."""
        _, member_value = self.current_token.value[:-1].rsplit(' ', 1)
        return (member_value, 'add_allowed_member')

    def deny_member(self) -> Tuple:
        """Returns tuple for the deny member of statement."""
        _, member_value = self.current_token.value[:-1].rsplit(' ', 1)
        return (member_value, 'add_denied_member')

    def allow_general(self) -> Tuple:
        """Returns tuple for the allow statement."""
        _, param_key = self.current_token.value[:-1].split()
        param_key = param_key.replace('-', '_')
        return ('allow', param_key)

    def deny_general(self) -> Tuple:
        """Returns tuple for the deny statement."""
        _, param_key = self.current_token.value[:-1].split()
        param_key = param_key.replace('-', '_')
        return ('deny', param_key)

    def ignore_general(self) -> Tuple:
        """Returns tuple for the ignore statement."""
        _, param_key = self.current_token.value[:-1].split()
        param_key = param_key.replace('-', '_')
        return ('ignore', param_key)

    def class_statement(self) -> Tuple:
        """Returns tuple for the match statement of the class declaration."""
        _, match_stmt = self.current_token.value[:-1].split(' ', 1)
        return (match_stmt, 'match')

    def spawn_class(self) -> Tuple:
        """Returns tuple for the spawn statement of the class declaration."""
        _, spawn_stmt = self.current_token.value[:-1].split(' ', 1)
        return (spawn_stmt, 'spawn')

    def range4(self) -> Tuple:
        """Returns tuple for the range statement for ipv4 configuration."""
        cleaned_val = self.current_token.value[:-1].strip()
        range_items = [item.strip() for item in cleaned_val.split()]

        dynamic_bootp_flag = False
        if 'dynamic-bootp' in cleaned_val:
            dynamic_bootp_flag = True
            range_items.remove('dynamic-bootp')

        while len(range_items) < 3:
            range_items += [None]

        _, start_ip, end_ip = range_items
        subnet_range = Range4(
            start=start_ip, end=end_ip, dynamic_bootp=dynamic_bootp_flag)
        return (subnet_range, 'add_range')

    def range6(self) -> Tuple:
        """Returns tuple for the range statement for ipv6 configuration."""
        cleaned_val = self.current_token.value[:-1].strip()
        range_items = [item.strip() for item in cleaned_val.split()]

        temporary_flag = False
        if 'temporary' in cleaned_val:
            temporary_flag = True
            range_items.remove('temporary')

        while len(range_items) < 3:
            range_items += [None]

        _, start_ip, end_ip = range_items
        subnet_range = Range6(
            start=start_ip, end=end_ip, temporary=temporary_flag)
        return (subnet_range, 'add_range')

    def option(self) -> Tuple:
        """Returns tuple for the option command."""
        space_count = self.current_token.value.count(' ')
        if space_count == 1:
            _, opt_name = self.current_token.value[:-1].split()
            opt_value = True
        else:
            _, opt_name, opt_value = self.current_token.value[:-1].split(' ', 2)

        if opt_name.isdigit():
            node_option = Option(number=opt_name, value=opt_value)
        else:
            opt_name = opt_name.replace('-', '_')
            node_option = Option(name=opt_name, value=opt_value)
        return (node_option, 'add_option')

    def custom_option(self) -> Tuple:
        """Returns tuple for the custom option command."""
        _, opt_name, _, code_num, _, definition_str = self.current_token.value[:-1].split(' ', 5)
        return (CustomOption(name=opt_name, code=code_num, definition=definition_str),
                'add_custom_option')

    def prefix6(self) -> Tuple:
        _, start_addr, end_addr, bits = self.current_token.value[:-1].split()
        return (Prefix6(start=start_addr, end=end_addr, bits=bits), 'prefix6')

    def option_expression(self) -> Tuple:
        _, opt_name, _, expr_value = self.current_token.value[:-1].split(' ', 3)
        return (OptionExpression(name=opt_name, value=expr_value),
                'add_option_expression')

    def server_duid_ll(self) -> Tuple:
        cleaned_val = self.current_token.value[:-1].strip()
        parts = cleaned_val.split()
        if 'LLT' in cleaned_val:
            *_, hw_type, timestamp_val, hw_addr = parts
        else:
            *_, hw_type, hw_addr, timestamp_val = parts + [None]
        return (ServerDuidLL(hardware_type=hw_type,
                             hardware_address=hw_addr,
                             timestamp=timestamp_val), 'server_duid')

    def server_duid_en(self) -> Tuple:
        *_, ent_number, ent_id = self.current_token.value[:-1].split(' ', 3)
        return (ServerDuidEN(enterprise_number=ent_number,
                             enterprise_id=ent_id), 'server_duid')

    def key(self) -> Tuple:
        """Returns tuple for the key declaration."""
        _, key_name = self.current_token.value[:-1].split()
        if self.current_token.value[-1] == '{':
            method_name = 'add_key'
        else:
            method_name = 'key'
        return (Key(name=key_name), method_name)

    def failover(self) -> Tuple:
        """Returns tuple for the failover declaration and parameter."""
        *_, peer_name = self.current_token.value[:-1].split()
        return (Failover(name=peer_name), 'failover')

    def subnet4(self) -> Tuple:
        """Returns tuple for the ipv4 subnet declaration."""
        _, network_addr, _, netmask_val = self.current_token.value[:-1].split()
        return (Subnet4(network=f'{network_addr}/{netmask_val}'), 'add_subnet')

    def subnet6(self) -> Tuple:
        """Returns tuple for the ipv6 subnet declaration."""
        _, subnet_cidr = self.current_token.value[:-1].split()
        return (Subnet6(network=f'{subnet_cidr}'), 'add_subnet')

    def shared_network(self) -> Tuple:
        """Returns tuple for the shared network declaration."""
        _, net_name = self.current_token.value[:-1].split()
        return (SharedNetwork(name=net_name), 'add_shared_network')

    def pool(self) -> Tuple:
        """Returns tuple for the ipv4 pool declaration."""
        return (Pool4(), 'add_pool')

    def group(self) -> Tuple:
        """Returns tuple for the group declaration."""
        return (Group(), 'add_group')

    def host(self) -> Tuple:
        """Returns tuple for the host declaration."""
        _, host_name = self.current_token.value[:-1].split()
        return (Host(name=host_name), 'add_host')

    def dhcp_class(self) -> Tuple:
        """Returns tuple for the class declaration."""
        _, class_name = self.current_token.value[:-1].split()
        return (DhcpClass(name=class_name), 'add_class')

    def subclass(self) -> Tuple:
        """Returns tuple for the class declaration and parameter."""
        cleaned_val = self.current_token.value[:-1].strip()
        _, class_name, match_expr = cleaned_val.split(' ', 2)
        return (SubClass(name=class_name, match_value=match_expr), 'add_subclass')

    def zone(self) -> Tuple:
        """Returns tuple for the zone declaration."""
        _, zone_name = self.current_token.value[:-1].split()
        return (Zone(name=zone_name), 'add_zone')

    def event(self) -> Tuple:
        """Returns tuple for the event declaration."""
        _, event_type = self.current_token.value[:-1].split()
        return (Event(event_type=event_type), 'add_event')

    def event_set(self) -> Tuple:
        """Returns tuple for the event set expression."""
        key_part, value_part = [
            data.strip() for data in self.current_token.value[:-1].split('=')]
        _, attr_key = key_part.split()
        return (EventSet(key=attr_key, value=value_part), 'add_event_set')

    def event_log(self) -> Tuple:
        """Returns tuple for the event log directive."""
        value_part = self.current_token.value[:-1].replace('log', '')
        return (value_part, 'log')

    def event_execute(self) -> Tuple:
        """Returns tuple for the event execute directive."""
        value_part = self.current_token.value[:-1].replace('execute', '')
        return (value_part, 'execute')

