def extract_function_signature(frame_obj, is_top_level=True):
    func_name = insp.getframeinfo(frame_obj).function
    args_str = extract_arguments_str(*insp.getargvalues(frame_obj))
    if is_top_level:
        prefix = 'rv_model = RV'
    else:
        prefix = 'model'
    return f'{prefix}.{func_name}({args_str})'

def extract_arguments_str(args_list, varargs_name, varkw_name, values_dict):
    argument_pairs = []
    for arg in args_list:
        if arg in ('cls', 'self'):
            continue
        if isinstance(values_dict[arg], str):
            argument_pairs.append(f'{arg}="{values_dict[arg]}"')
        else:
            argument_pairs.append(f'{arg}={values_dict[arg]}')

    if varargs_name is not None:
        for arg in values_dict[varargs_name]:
            if isinstance(values_dict[varargs_name][arg], str):
                argument_pairs.append(f'{arg}="{values_dict[varargs_name][arg]}"')
            else:
                argument_pairs.append(f'{arg}={values_dict[varargs_name][arg]}')

    if varkw_name is not None:
        for arg in values_dict[varkw_name]:
            if isinstance(values_dict[varkw_name][arg], str):
                argument_pairs.append(f'{arg}="{values_dict[varkw_name][arg]}"')
            else:
                argument_pairs.append(f'{arg}={values_dict[varkw_name][arg]}')

    return ', '.join(argument_pairs)

def partition_rdb_by_threshold(input_file, threshold_value, output_after, output_before=None):
    from numpy import loadtxt
    first_col = loadtxt(input_file, skiprows=2, usecols=(0,))
    condition_mask = first_col > threshold_value
    header_lines = 2
    data_rows = condition_mask.sum()

    if data_rows == 0:
        print(f'No entries after {threshold_value} in file {input_file}')
    else:
        command = f'(head -n{header_lines} && tail -n{data_rows}) < {input_file} > {output_after}'
        os.system(command)

    if output_before is not None:
        remaining_rows = 2 + (~condition_mask).sum()
        command = f'(head -n{remaining_rows}) < {input_file} > {output_before}'
        os.system(command)

