import typing
import asyncio
from datetime import datetime, timedelta
import discord
from redbot.core import commands, Config
from redbot.core.utils import AsyncIter
from redbot.core.utils.chat_formatting import humanize_list, pagify

DENIED_ACCESS = "You lack BotAccess permissions!"
APPRECIATION = "We appreciate your support for our server! Here's the bot invite: <{invite}>. You can register a BotAccess server using `[p]botaccess servers add <server ID>`."
EXPIRED = "Your BotAccess server access has lapsed since you're no longer a supporter."

class BotAccess(commands.Cog):
    """
    Grant Special Roles Access to Bot
    Enable users with Server Booster, Patreon, etc. roles to invite the bot to a (limited number of) server(s) of their choice.
    """
    def __init__(self, bot):
        self.bot = bot
        self.config = Config.get_conf(self, identifier=14000605, force_registration=True)
        default_global = {
            "authorized": [],
            "primary_servers": {},
            "notifications": {
                "appreciation": {
                    "enabled": True,
                    "text": ""
                },
                "expired": {
                    "enabled": True,
                    "text": ""
                }
            },
            "denied_message": "",
            "max_servers": 1,
            "auto_exit": {
                "enabled": True,
                "wait_hours": 24
            },
        }
        default_user = {
            "registered_servers": [],
            "supporting_guilds": [],
            "expiration_time": None
        }
        self.config.register_global(**default_global)
        self.config.register_user(**default_user)
        self.expiry_monitor_task = self.bot.loop.create_task(self._expiry_monitor())

    def cog_unload(self):
        self.expiry_monitor_task.cancel()

    @commands.Cog.listener("on_guild_join")
    async def _on_guild_join(self, guild: discord.Guild):
        if guild.owner and guild.owner == guild.me:
            return
        if guild.owner_id in self.bot.owner_ids:
            return
        if guild.id in await self.config.authorized():
            return
        if str(guild.id) in (await self.config.primary_servers()).keys():
            return
        for data in (await self.config.all_users()).values():
            if guild.id in data["registered_servers"]:
                return

        inviter = None
        if guild.me.guild_permissions.view_audit_log:
            async for entry in guild.audit_logs(limit=3, action=discord.AuditLogAction.bot_add):
                if entry.target == guild.me:
                    inviter = entry.user
                    break

        if inviter:
            try:
                await inviter.send(await self.config.denied_message() or DENIED_ACCESS)
            except discord.HTTPException:
                pass
        else:
            for channel in guild.text_channels:
                if channel.permissions_for(guild.me).send_messages:
                    await channel.send(await self.config.denied_message() or DENIED_ACCESS)
                    break
        await guild.leave()

    @commands.Cog.listener("on_member_remove")
    async def _on_member_remove(self, member: discord.Member):
        auto_exit = False
        async with self.config.user(member).all() as user_data:
            if member.guild.id in user_data["supporting_guilds"]:
                user_data["supporting_guilds"].remove(member.guild.id)
            if not user_data["supporting_guilds"] and not user_data["expiration_time"]:
                auto_exit = True
        if auto_exit:
            await self._start_auto_exit(member.id)

    @commands.Cog.listener("on_member_update")
    async def _on_member_update(self, before: discord.Member, after: discord.Member):
        primary_servers = await self.config.primary_servers()
        role_config = primary_servers.get(str(after.guild.id))

        if (
                after.bot or
                await self.bot.cog_disabled_in_guild(self, after.guild) or
                before.roles == after.roles or
                not role_config
        ):
            return

        messages = await self.config.notifications()
        message_to_send: str = ""
        auto_exit = False

        before_eligible = await self._check_role_match(role_config, before)
        after_eligible = await self._check_role_match(role_config, after)

        if not before_eligible and after_eligible:
            async with self.config.user(after).all() as user_data:
                if not user_data["supporting_guilds"]:
                    message_to_send = await self._send_appreciation(messages["appreciation"])
                if user_data["expiration_time"]:
                    user_data["expiration_time"] = None
                if after.guild.id not in user_data["supporting_guilds"]:
                    user_data["supporting_guilds"].append(after.guild.id)

        elif before_eligible and not after_eligible:
            async with self.config.user(after).all() as user_data:
                if after.guild.id in user_data["supporting_guilds"]:
                    user_data["supporting_guilds"].remove(after.guild.id)
                if not user_data["supporting_guilds"] and not user_data["expiration_time"]:
                    message_to_send = await self._send_expired(messages["expired"])
                    auto_exit = True

        if message_to_send:
            try:
                await after.send(message_to_send)
            except discord.HTTPException:
                pass

        if auto_exit:
            await self._start_auto_exit(after.id)

    @staticmethod
    async def _check_role_match(eligible_roles: list, member: discord.Member):
        return bool(list(set(eligible_roles) & set(r.id for r in member.roles)))

    async def _populate_template(self, template: str):
        invite_url = await self.bot.get_cog("Core")._invite_url()
        return template.replace(
            "{invite}", f"{invite_url}"
        )

    async def _send_appreciation(self, message: dict):
        if message["enabled"]:
            if not message["text"]:
                to_send = APPRECIATION
            else:
                to_send = message["text"]
            return await self._populate_template(to_send)
        return None

    @staticmethod
    async def _send_expired(message: dict):
        if message["enabled"]:
            if not message["text"]:
                return EXPIRED
            else:
                return message["text"]
        return None

    @commands.group(name="botaccess")
    async def _bot_access(self, ctx: commands.Context):
        """BotAccess Configuration"""

    @_bot_access.group(name="servers", invoke_without_command=True)
    async def _servers(self, ctx: commands.Context):
        """View and manage your registered BotAccess server(s)."""
        user_data = await self.config.user(ctx.author).all()
        if user_data["supporting_guilds"]:
            await ctx.send(embed=discord.Embed(
                title="BotAccess Servers",
                description=f"{humanize_list([f'`{gu.name}` (`{g}`)' if (gu := self.bot.get_guild(g)) else f'`{g}`' for g in user_data['registered_servers']])}",
                color=await ctx.embed_color()
            ))
            await ctx.send_help()
        else:
            return await ctx.send(await self.config.denied_message() or DENIED_ACCESS)

    @_servers.command("add", require_var_positional=True)
    async def _servers_add(self, ctx: commands.Context, *servers: int):
        """Add server(s) to your allowed BotAccess list."""
        async with self.config.user(ctx.author).all() as user_data:
            if user_data["supporting_guilds"]:
                if user_data["expiration_time"]:
                    return await ctx.send("Your BotAccess access has expired. You cannot add more servers.")
                max_allowed = await self.config.max_servers()
                if len(user_data["registered_servers"]) + len(servers) > max_allowed:
                    return await ctx.send(f"You are limited to {max_allowed} BotAccess servers, currently at {len(user_data['registered_servers'])}!")
                for server in servers:
                    if server not in user_data["registered_servers"]:
                        user_data["registered_servers"].append(server)
                return await ctx.tick()
            else:
                return await ctx.send(await self.config.denied_message() or DENIED_ACCESS)

    @_servers.command("remove", aliases=["delete"], require_var_positional=True)
    async def _servers_remove(self, ctx: commands.Context, *servers: int):
        """Remove server(s) from your allowed BotAccess list."""
        primary_servers = await self.config.primary_servers()
        authorized = await self.config.authorized()
        async with self.config.user(ctx.author).all() as user_data:
            if user_data["supporting_guilds"]:
                for server in servers:
                    if server in user_data["registered_servers"]:
                        if guild := self.bot.get_guild(server):
                            if guild.id not in authorized and str(guild.id) not in primary_servers.keys():
                                await guild.leave()
                        user_data["registered_servers"].remove(server)
                    else:
                        await ctx.send(f"`{server}` was not in your BotAccess servers!")
                return await ctx.tick()
            else:
                return await ctx.send(await self.config.denied_message() or DENIED_ACCESS)

    @_bot_access.command(name="invite")
    async def _invite(self, ctx: commands.Context):
        """Resend the bot invite link and thank you message."""
        settings = await self.config.user(ctx.author).all()
        if settings["supporting_guilds"]:
            to_send = await self._send_appreciation((await self.config.notifications())["appreciation"])
            if to_send:
                try:
                    await ctx.author.send(to_send)
                except discord.HTTPException:
                    pass
            else:
                return await ctx.send("No invitation message configured. Contact the bot owner.")
        else:
            return await ctx.send(await self.config.denied_message() or DENIED_ACCESS)

    @commands.is_owner()
    @_bot_access.group(name="set")
    async def _owner_settings(self, ctx: commands.Context):
        """Owner-only BotAccess Configuration"""

    @_owner_settings.group(name="mainservers", invoke_without_command=True)
    async def _main_servers(self, ctx: commands.Context):
