    @_owner_settings.command(name="reset")
    async def _reset(self, ctx: commands.Context, user: typing.Optional[discord.User], leave_servers: bool, confirm: bool):
        """Reset BotAccess settings for a specific user or globally."""
        if not confirm:
            return await ctx.send("Please confirm by setting the last parameter to `true`.")

        async with ctx.typing():
            to_leave: list[discord.Guild] = []
            if user:
                if leave_servers:
                    servers = await self.config.user(user).registered_servers()
                    for sid in servers:
                        if sv := self.bot.get_guild(sid):
                            to_leave.append(sv)
                await self.config.user(user).clear()
                await ctx.send(f"BotAccess settings reset for {user.mention}.")
            else:
                if leave_servers:
                    all_users = await self.config.all_users()
                    for data in all_users.values():
                        for sid in data["registered_servers"]:
                            if sv := self.bot.get_guild(sid):
                                to_leave.append(sv)
                await self.config.clear_all()
                await self.config.clear_all_users()
                await ctx.send("All BotAccess settings have been reset.")

            primary_servers = await self.config.primary_servers()
            authorized = await self.config.authorized()
            if to_leave:
                for guild in to_leave:
                    if guild.id not in authorized and str(guild.id) not in primary_servers.keys():
                        await guild.leave()
                await ctx.send(f"Completed leaving {len(to_leave)} servers.")

    @commands.bot_has_permissions(embed_links=True)
    @_owner_settings.command(name="view")
    async def _view(self, ctx: commands.Context):
        """Display BotAccess configuration."""
        settings = await self.config.all()
        await ctx.send(embed=discord.Embed(
            title="BotAccess Settings",
            description=f"""
            **Auto-Leave:** {settings["auto_exit"]["enabled"]} ({settings["auto_exit"]["wait_hours"]}hrs)
            **Server Limit:** {settings["max_servers"]} servers per user
            **Allowlist:** See `{ctx.clean_prefix}botaccess set allowlist`
            **Primary Servers & Roles:** See `{ctx.clean_prefix}botaccess set mainservers`
            **Thanks Msg ({settings["notifications"]["appreciation"]["enabled"]}):** {settings["notifications"]["appreciation"]["text"] or APPRECIATION}
            **Expire Msg ({settings["notifications"]["expired"]["enabled"]}):** {settings["notifications"]["expired"]["text"] or EXPIRED}
            **Error Msg:** {settings["denied_message"] or DENIED_ACCESS}
            """,
            color=await ctx.embed_color()
        ))
        users_info = ""
        for uid, data in (await self.config.all_users()).items():
            try:
                usr = await self.bot.get_or_fetch_user(int(uid))
                usr_str = f"{usr.mention} ({usr.id})"
            except discord.HTTPException:
                usr_str = uid
            users_info += f"{usr_str}: {len(data['registered_servers'])} servers\n"
        for page in pagify(users_info):
            await ctx.maybe_send_embed(page)

    async def _start_auto_exit(self, user_id: int, schedule_timer: bool = True):
        auto_exit = await self.config.auto_exit()
        if not auto_exit["enabled"]:
            return
        expiration = (datetime.now() + timedelta(hours=auto_exit["wait_hours"])).timestamp()
        await self.config.user_from_id(user_id).expiration_time.set(expiration)
        if schedule_timer:
            await self._expiry_countdown(user_id, expiration)

    async def _refresh_supporters(self):
        primary_server_configs = await self.config.primary_servers()
        primary_guilds: list[discord.Guild] = []
        for gid in primary_server_configs.keys():
            if gu := self.bot.get_guild(int(gid)):
                primary_guilds.append(gu)

        original_data = await self.config.all_users()
        original_user_ids = list(original_data.keys())
        await self.config.clear_all_users()

        updated_data = {}
        new_members: list[discord.Member] = []
        new_member_ids: list[int] = []

        for guild in primary_guilds:
            for rid in primary_server_configs[str(guild.id)]:
                if role := guild.get_role(rid):
                    async for member in AsyncIter(role.members, steps=100):
                        if current := updated_data.get(str(member.id)):
                            current["supporting_guilds"].append(guild.id)
                            updated_data[str(member.id)] = {
                                "supporting_guilds": current["supporting_guilds"],
                                "registered_servers": current["registered_servers"],
                                "expiration_time": current["expiration_time"]
                            }
                        elif original := original_data.get(member.id):
                            if member.id in original_user_ids:
                                original_user_ids.remove(member.id)
                            updated_data[str(member.id)] = {
                                "supporting_guilds": [guild.id],
                                "registered_servers": original["registered_servers"],
                                "expiration_time": original["expiration_time"]
                            }
                        else:
                            new_members.append(member)
                            new_member_ids.append(member.id)
                            updated_data[str(member.id)] = {
                                "supporting_guilds": [guild.id],
                                "registered_servers": [],
                                "expiration_time": None
                            }

        for uid, data in updated_data.items():
            async with self.config.user_from_id(int(uid)).all() as cur:
                cur["supporting_guilds"] = data["supporting_guilds"]
                cur["registered_servers"] = data["registered_servers"]
                cur["expiration_time"] = data["expiration_time"]

        messages = await self.config.notifications()
        thanks_msg = await self._send_appreciation(messages["appreciation"])
        expire_msg = await self._send_expired(messages["expired"])

        if thanks_msg:
            async for member in AsyncIter(new_members, steps=100):
                try:
                    await member.send(thanks_msg)
                except discord.HTTPException:
                    pass

        for uid in original_user_ids:
            try:
                usr = await self.bot.get_or_fetch_user(uid)
                if not original_data.get(uid)["expiration_time"]:
                    if expire_msg:
                        await usr.send(expire_msg)
                    await self._start_auto_exit(uid, schedule_timer=False)
            except discord.HTTPException:
                pass

    async def _expiry_monitor(self):
        await self.bot.wait_until_red_ready()
        await self._refresh_supporters()
        try:
            tasks = []
            for uid, data in (await self.config.all_users()).items():
                if not data["registered_servers"] and not data["supporting_guilds"] and not data["expiration_time"]:
                    await self.config.user_from_id(int(uid)).clear()
                    continue
                if data["supporting_guilds"] or not data["expiration_time"]:
                    continue
                tasks.append(self._expiry_countdown(int(uid), data["expiration_time"]))
            await asyncio.gather(*tasks)
        except Exception:
            pass

    async def _expiry_countdown(self, user_id: int, end_time: float):
        remaining = (datetime.fromtimestamp(end_time) - datetime.now()).total_seconds()
        if remaining > 0:
            await asyncio.sleep(remaining)
        await self._handle_expiry(user_id)

    async def _handle_expiry(self, user_id: int):
        user_data = await self.config.user_from_id(user_id).all()
        primary_servers = await self.config.primary_servers()
        authorized = await self.config.authorized()

        if user_data["expiration_time"] and not user_data["supporting_guilds"]:
            if datetime.fromtimestamp(user_data["expiration_time"]) <= datetime.now():
                for sid in user_data["registered_servers"]:
                    if gl := self.bot.get_guild(sid):
                        if gl.id not in authorized and str(gl.id) not in primary_servers.keys():
                            await gl.leave()
                await self.config.user_from_id(user_id).clear()
            else:
                await self._expiry_countdown(user_id, user_data["expiration_time"])

# Register Celery tasks with metadata and mocks for testing
from __future__ import annotations
from dataclasses import dataclass
from typing import TYPE_CHECKING, Any, Callable, Dict
from .dashboardbuild import build_dashboard
from .editionrebuild import mock_rebuild_edition, rebuild_edition
from .renameedition import mock_rename_edition, rename_edition

if TYPE_CHECKING:
    import celery.app.task.Task

__all__ = ["TaskRegistry", "task_registry", "RegisteredTask"]

@dataclass
class RegisteredTask:
    """A registered Celery task along with its metadata."""
    identifier: str
    """The unique name identifying the task."""
    function: celery.app.task.Task
    """The actual Celery task callable."""
    priority: int
    """Execution priority; lower values indicate higher precedence."""
    mock_function: Callable
    """A test helper that simulates the task's database operations."""

    def __lt__(self, other: Any) -> bool:
        if isinstance(other, RegisteredTask):
            return self.priority < other.priority
        else:
            raise ValueError("Comparison only valid between RegisteredTask instances")

    def __le__(self, other: Any) -> bool:
        if isinstance(other, RegisteredTask):
            return self.priority <= other.priority
        else:
            raise ValueError("Comparison only valid between RegisteredTask instances")

    def __ge__(self, other: Any) -> bool:
        if isinstance(other, RegisteredTask):
            return self.priority >= other.priority
        else:
            raise ValueError("Comparison only valid between RegisteredTask instances")

    def __gt__(self, other: Any) -> bool:
        if isinstance(other, RegisteredTask):
            return self.priority > other.priority
        else:
            raise ValueError("Comparison only valid between RegisteredTask instances")


class TaskRegistry:
    """Central registry mapping task names to their Celery implementations and metadata."""

    def __init__(self) -> None:
        self._registry: Dict[str, RegisteredTask] = {}

    def __getitem__(self, name: str) -> RegisteredTask:
        return self._registry[name]

    def register(
        self,
        *,
        name: str,
        task: celery.app.task.Task,
        priority: int,
        mock_function: Callable,
    ) -> None:
        """Register a new task in the registry."""
        self._registry[name] = RegisteredTask(
            identifier=name,
            function=task,
            priority=priority,
            mock_function=mock_function,
        )


task_registry = TaskRegistry()

