import torch.nn as nn
import torch.nn.functional as F

def extract_center_region(tensor, crop_size):  # assumes square inputs
    img_width = tensor.shape[-1]
    offset = (img_width - crop_size) // 2
    return tensor[:, :, offset: offset + crop_size, offset: offset + crop_size]

class base_generator(nn.Module):
    def __init__(self, config):
        super(base_generator, self).__init__()
        self.target_dim = config.image_shape[0]
        self.layer1 = nn.ConvTranspose2d(
            config.dict_nbatoms, 300, kernel_size=4, stride=2, padding=0, bias=True
        )
        self.layer2 = nn.ConvTranspose2d(
            300, 100, kernel_size=3, stride=1, padding=0, bias=True
        )
        self.layer3 = nn.ConvTranspose2d(
            100, 3, kernel_size=3, stride=1, padding=0, bias=True
        )

    def forward(self, input_tensor):
        intermediate = F.relu(self.layer1(input_tensor))
        intermediate = F.relu(self.layer2(intermediate))
        result = F.relu(self.layer3(intermediate))
        result = extract_center_region(result, self.target_dim)
        return result.clamp(min=0.0, max=1.0)

class compact_generator(nn.Module):
    def __init__(self, config):
        super(compact_generator, self).__init__()
        self.target_dim = config.image_shape[0]
        self.layer1 = nn.ConvTranspose2d(
            config.dict_nbatoms, 30, kernel_size=4, stride=2, padding=0, bias=True
        )
        self.layer2 = nn.ConvTranspose2d(
            30, 10, kernel_size=3, stride=1, padding=0, bias=True
        )
        self.layer3 = nn.ConvTranspose2d(
            10, 3, kernel_size=3, stride=1, padding=0, bias=True
        )

    def forward(self, input_tensor):
        intermediate = F.relu(self.layer1(input_tensor))
        intermediate = F.relu(self.layer2(intermediate))
        result = F.relu(self.layer3(intermediate))
        result = extract_center_region(result, self.target_dim)
        return result.clamp(min=0.0, max=1.0)

class extended_generator(nn.Module):
    def __init__(self, config):
        super(extended_generator, self).__init__()
        self.target_dim = config.image_shape[0]
        self.layer1 = nn.ConvTranspose2d(
            config.dict_nbatoms, 300, kernel_size=4, stride=2, padding=0, bias=True
        )
        self.layer2 = nn.ConvTranspose2d(
            300, 100, kernel_size=3, stride=1, padding=0, bias=True
        )
        self.layer3 = nn.ConvTranspose2d(
            100, 30, kernel_size=3, stride=1, padding=0, bias=True
        )
        self.layer4 = nn.ConvTranspose2d(
            30, 10, kernel_size=3, stride=1, padding=0, bias=True
        )
        self.layer5 = nn.ConvTranspose2d(
            10, 3, kernel_size=3, stride=1, padding=0, bias=True
        )

    def forward(self, input_tensor):
        intermediate = F.relu(self.layer1(input_tensor))
        intermediate = F.relu(self.layer2(intermediate))
        temp = F.relu(self.layer3(intermediate))
        temp = F.interpolate(temp, size=(self.target_dim+2), mode="bicubic")
        temp = F.relu(self.layer4(temp))
        final = F.relu(self.layer5(temp))
        final = extract_center_region(final, self.target_dim)
        return final.clamp(min=0.0, max=1.0)

class upsample_generator(nn.Module):
    def __init__(self, config):
        super(upsample_generator, self).__init__()
        self.target_dim = config.image_shape[0]
        self.layer1 = nn.ConvTranspose2d(
            config.dict_nbatoms, 300, kernel_size=3, stride=1, padding=0, bias=True
        )
        self.layer2 = nn.ConvTranspose2d(
            300, 100, kernel_size=3, stride=1, padding=0, bias=True
        )
        self.layer3 = nn.ConvTranspose2d(
            100, 3, kernel_size=3, stride=1, padding=0, bias=True
        )

    def forward(self, input_tensor):
        intermediate = F.relu(self.layer1(input_tensor))
        intermediate = F.interpolate(intermediate, size=(self.target_dim+2), mode="bicubic")
        temp = F.relu(self.layer2(intermediate))
        output = F.relu(self.layer3(temp))
        output = extract_center_region(output, self.target_dim)
        return output.clamp(min=0.0, max=1.0)

generator_registry = {
    "base_generator": base_generator,
    "upsample_generator": upsample_generator,
    "extended_generator": extended_generator,
    "compact_generator": compact_generator
}

