# Custom exception class for small failures
class MinorError(Exception):
    def __init__(self, description=None):
        self.description = "no description" if description is None else description
    def __str__(self) -> str:
        return f"MinorError: {self.description}"

try:
    raise MinorError()
except MinorError as error:
    print(error)  # MinorError: no description

try:
    raise MinorError("encountered a minor issue")
except MinorError as error:
    print(error)  # MinorError: encountered a minor issue

