# Utility functions for image and JSON handling with multiprocessing safety
import io
import json
import mimetypes
import os
from multiprocessing import Lock
import numpy as np
from PIL import Image

image_lock = Lock()

def convert_int64_keys(obj):
    result = {}
    for key, value in obj.items():
        if str(key).isdigit():
            key = np.int64(key)
        elif isinstance(value, dict):
            updated_value = {}
            for sub_key, sub_val in value.items():
                if str(sub_val).isdigit():
                    updated_value[sub_key] = int(sub_val)
                else:
                    updated_value[sub_key] = sub_val
            value = updated_value
        result[key] = value
    return result

def read_json_file(json_path):
    if not os.path.isfile(json_path):
        raise FileNotFoundError(f"Specified file does not exist: {json_path}")
    with open(json_path, 'r', encoding='utf-8') as file:
        content = json.load(file)
    return convert_int64_keys(content)

def write_json_file(data, output_path):
    if not isinstance(data, dict):
        raise TypeError("Input data must be a dictionary.")
    processed_data = {int(k) if isinstance(k, (np.integer, np.int64)) else k: v 
                      for k, v in data.items()}
    with open(output_path, 'w', encoding='utf-8') as f:
        json.dump(processed_data, f)

def check_image_integrity(image_file):
    if not os.path.exists(image_file):
        return False
    try:
        with Image.open(image_file) as img:
            w, h = img.size
        if w <= 0 or h <= 0:
            raise ValueError("Invalid image dimensions")
        return True
    except Exception as err:
        print(f"Failed to process image '{image_file}': {err}")
        return False

def analyze_file_path(path_str):
    if os.path.exists(path_str) and path_str != '.':
        if not os.path.isfile(path_str):
            raise ValueError(f"'{path_str}' is not a regular file")
        ext = os.path.splitext(path_str)[1].lower()
        content_type = mimetypes.types_map.get(ext, 'application/octet-stream')
        return (content_type, path_str)
    else:
        return (None, path_str)

def save_base64_as_image(base64_data, output_file, max_dimension=-1):
    with image_lock:
        pil_image = base64_to_pil_image(base64_data, target=max_dimension)
        pil_image.save(output_file)

def base64_to_pil_image(base64_string, target=-1):
    raw_bytes = base64.b64decode(base64_string)
    with Image.open(io.BytesIO(raw_bytes)) as img:
        if img.mode in ('RGBA', 'P'):
            img = img.convert('RGB')
        if target > 0:
            img.thumbnail((target, target))
        return img.copy()

