def establish_shortcut(path: str, shortcut_name: str, destination: dict, 
                       workspace_identifier: str, lakehouse_identifier: str, 
                       conflict_resolution: str = "Abort"):
    # Acquire authentication token
    auth_token = notebookutils.credentials.getToken("pbi")
    request_headers = {
        "Authorization": f"Bearer {auth_token}",
        "Content-Type": "application/json"
    }

    payload = {
        "path": path,           # e.g., "Files/raw" or "Tables"
        "name": shortcut_name,  # e.g., "sales_external"
        "target": destination   # target configuration dictionary
    }

    endpoint_url = f"https://api.fabric.microsoft.com/v1/workspaces/{workspace_identifier}/items/{lakehouse_identifier}/shortcuts"
    query_params = {"shortcutConflictPolicy": conflict_resolution}

    response = requests.post(endpoint_url, headers=request_headers, 
                             params=query_params, data=json.dumps(payload))

    if response.status_code in (200, 201):
        print(f"Shortcut '{shortcut_name}' created at '{path}'.")
        print("Location:", response.headers.get("Location", "<none>"))
    else:
        print("Creation failed:", response.status_code, response.text)

