import base64
import json
import re
from typing import Optional, Tuple, List
from urllib.parse import unquote, urlparse

class ConfigurationValidator:
    @staticmethod
    def is_base64_encoded(s: str) -> bool:
        try:
            s = s.rstrip('=')
            return bool(re.match(r'^[A-Za-z0-9+/\-_]*$', s))
        except:
            return False

    @staticmethod
    def decode_base64_url_safe(s: str) -> Optional[bytes]:
        try:
            s = s.replace('-', '+').replace('_', '/')
            padding_needed = 4 - (len(s) % 4)
            if padding_needed != 4:
                s += '=' * padding_needed
            return base64.b64decode(s)
        except:
            return None

    @staticmethod
    def decode_base64_to_text(text: str) -> Optional[str]:
        try:
            if ConfigurationValidator.is_base64_encoded(text):
                decoded_bytes = ConfigurationValidator.decode_base64_url_safe(text)
                if decoded_bytes:
                    return decoded_bytes.decode('utf-8')
            return None
        except:
            return None

    @staticmethod
    def sanitize_vmess_entry(entry: str) -> str:
        if "vmess://" in entry:
            base64_segment = entry[8:]
            base64_filtered = re.split(r'[^A-Za-z0-9+/=_-]', base64_segment)[0]
            return f"vmess://{base64_filtered}"
        return entry

    @staticmethod
    def standardize_hysteria2_scheme(url: str) -> str:
        if url.startswith('hy2://'):
            return url.replace('hy2://', 'hysteria2://', 1)
        return url

    @staticmethod
    def verify_vmess_structure(entry: str) -> bool:
        try:
            if not entry.startswith('vmess://'):
                return False
            base64_segment = entry[8:]
            decoded_data = ConfigurationValidator.decode_base64_url_safe(base64_segment)
            if decoded_data:
                json.loads(decoded_data)
                return True
            return False
        except:
            return False

    @staticmethod
    def verify_tuic_entry(entry: str) -> bool:
        try:
            if entry.startswith('tuic://'):
                parsed = urlparse(entry)
                return bool(parsed.netloc and ':' in parsed.netloc)
            return False
        except:
            return False

    @staticmethod
    def transform_ssconf_to_https(link: str) -> str:
        if link.startswith('ssconf://'):
            return link.replace('ssconf://', 'https://', 1)
        return link

    @staticmethod
    def has_base64_payload(payload: str) -> Tuple[bool, str]:
        schemes = ['vmess://', 'vless://', 'ss://', 'tuic://']
        for scheme in schemes:
            if payload.startswith(scheme):
                base64_segment = payload[len(scheme):]
                decoded_url = unquote(base64_segment)
                if (ConfigurationValidator.is_base64_encoded(decoded_url) or 
                    ConfigurationValidator.is_base64_encoded(base64_segment)):
                    return True, scheme[:-3]
        return False, ''

    @staticmethod
    def inspect_base64_payload(content: str) -> Optional[str]:
        try:
            decoded_content = ConfigurationValidator.decode_base64_to_text(content)
            if decoded_content:
                supported_protocols = ['vmess://', 'vless://', 'ss://', 'trojan://', 'hysteria2://', 'hy2://', 'wireguard://', 'tuic://', 'ssconf://']
                for protocol in supported_protocols:
                    if protocol in decoded_content:
                        return decoded_content
            return None
        except:
            return None

    @staticmethod
    def extract_entries(raw_text: str) -> List[str]:
        entries = []
        lines = raw_text.split('\n')

        for line in lines:
            line = line.strip()
            if not line:
                continue

            if ConfigurationValidator.is_base64_encoded(line):
                extracted_content = ConfigurationValidator.inspect_base64_payload(line)
                if extracted_content:
                    raw_text = extracted_content

        protocols = ['vmess://', 'vless://', 'ss://', 'trojan://', 'hysteria2://', 'hy2://', 'wireguard://', 'tuic://', 'ssconf://']
        current_index = 0
        text_size = len(raw_text)

        while current_index < text_size:
            next_entry_start = text_size
            matched_scheme = None

            for scheme in protocols:
                scheme_index = raw_text.find(scheme, current_index)
                if scheme_index != -1 and scheme_index < next_entry_start:
                    next_entry_start = scheme_index
                    matched_scheme = scheme

            if matched_scheme:
                if current_index < next_entry_start and entries:
                    segment = raw_text[current_index:next_entry_start].strip()
                    if ConfigurationValidator.is_valid_entry(segment):
                        entries.append(segment)

                current_index = next_entry_start
                next_scheme_index = text_size

                for scheme in protocols:
                    pos = raw_text.find(scheme, next_entry_start + len(matched_scheme))
                    if pos != -1 and pos < next_scheme_index:
                        next_scheme_index = pos

                segment = raw_text[next_entry_start:next_scheme_index].strip()
                if matched_scheme == "vmess://":
                    segment = ConfigurationValidator.sanitize_vmess_entry(segment)
                elif matched_scheme == "hy2://":
                    segment = ConfigurationValidator.standardize_hysteria2_scheme(segment)
                if ConfigurationValidator.is_valid_entry(segment):
                    entries.append(segment)

                current_index = next_scheme_index
            else:
                break

        return entries

    @staticmethod
    def clean_entry(entry: str) -> str:
        entry = re.sub(r'[\U0001F300-\U0001F9FF]', '', entry)
        entry = re.sub(r'[\x00-\x08\x0B-\x1F\x7F-\x9F]', '', entry)
        entry = re.sub(r'[^\S\r\n]+', ' ', entry)
        entry = entry.strip()
        return entry

    @staticmethod
    def is_valid_entry(entry: str) -> bool:
        if not entry:
            return False

        supported_schemes = ['vmess://', 'vless://', 'ss://', 'trojan://', 'hysteria2://', 'hy2://', 'wireguard://', 'tuic://', 'ssconf://']
        return any(entry.startswith(p) for p in supported_schemes)

    @classmethod
    def validate_scheme_entry(cls, entry: str, scheme: str) -> bool:
        try:
            if scheme in ['vmess://', 'vless://', 'ss://', 'tuic://']:
                if scheme == 'vmess://':
                    return cls.verify_vmess_structure(entry)
                if scheme == 'tuic://':
                    return cls.verify_tuic_entry(entry)
                base64_segment = entry[len(scheme):]
                decoded_url = unquote(base64_segment)
                if cls.is_base64_encoded(decoded_url) or cls.is_base64_encoded(base64_segment):
                    return True
                if cls.decode_base64_url_safe(base64_segment) or cls.decode_base64_url_safe(decoded_url):
                    return True
            elif scheme in ['trojan://', 'hysteria2://', 'hy2://', 'wireguard://']:
                parsed = urlparse(entry)
                return bool(parsed.netloc and '@' in parsed.netloc)
            elif scheme == 'ssconf://':
                return True
            return False
        except:
            return False

# Layout Tools - Automatic node positioning.
# Provides auto_arrange tool for organizing nodes in different configurations.
"""
import json
from typing import Dict, List
from langchain.tools import tool
from pydantic import BaseModel, Field
from app.core.copilot.tools.context import get_current_graph_context

class AutoArrangeInput(BaseModel):
    """Input schema for auto_arrange tool."""
    arrangement_type: str = Field(
        default="horizontal",
        description="Arrangement type: 'horizontal' (left-to-right), 'vertical' (top-to-bottom), 'tree' (hierarchical), 'grid' (grid layout)",
    )
    spacing_x: float = Field(default=300, description="Horizontal gap between nodes")
    spacing_y: float = Field(default=150, description="Vertical gap between nodes")
    origin_x: float = Field(default=100, description="Initial X coordinate")
    origin_y: float = Field(default=100, description="Initial Y coordinate")
    explanation: str = Field(description="Justification for applying automatic arrangement")
@tool(
    args_schema=AutoArrangeInput,
    description="Automatically reposition nodes to improve visualization. Options: horizontal, vertical, tree, grid.",
)
def auto_arrange(
    explanation: str,
    arrangement_type: str = "horizontal",
    spacing_x: float = 300,
    spacing_y: float = 150,
    origin_x: float = 100,
    origin_y: float = 100,
) -> str:
    """
    Automatically repositions nodes to enhance visual clarity.
    Args:
        explanation: Reason for using automatic arrangement
        arrangement_type: 'horizontal' (default), 'vertical', 'tree', 'grid'
        spacing_x: Horizontal separation (default: 300)
        spacing_y: Vertical separation (default: 150)
        origin_x: Starting X coordinate (default: 100)
        origin_y: Starting Y coordinate (default: 100)
    Returns:
        JSON with UPDATE_POSITION actions for all nodes.
    """
    graph_context = get_current_graph_context()
    elements = graph_context.get("nodes", [])
    connections = graph_context.get("edges", [])
    if not elements:
        return json.dumps(
            {
                "error": "No nodes present in the current graph to arrange",
                "suggestion": "Add some nodes before applying automatic arrangement",
            },
            ensure_ascii=False,
        )
    operations = []
    # Construct adjacency information for structural analysis
    successors: Dict[str, List[str]] = {e.get("id"): [] for e in elements}
    predecessors: Dict[str, List[str]] = {e.get("id"): [] for e in elements}
    for conn in connections:
        source = conn.get("source")
        target = conn.get("target")
        if source in successors and target in predecessors:
            successors[source].append(target)
            predecessors[target].append(source)
    # Identify starting points (nodes without incoming connections)
    entry_points = [e for e in elements if not predecessors.get(e.get("id"), [])]

    if arrangement_type == "horizontal":
        # BFS traversal from entry points, assign column indices
        seen = set()
        col_map: Dict[str, int] = {}
        queue = [(e.get("id"), 0) for e in entry_points]
        while queue:
            node_id, col = queue.pop(0)
            if node_id in seen:
                continue
            seen.add(node_id)
            col_map[node_id] = col
            for child in successors.get(node_id, []):
                if child not in seen:
                    queue.append((child, col + 1))
        # Assign coordinates based on column
        row_counter: Dict[int, int] = {}
        for elem in elements:
            node_id = elem.get("id")
            col = col_map.get(node_id, 0)
            row = row_counter.get(col, 0)
            row_counter[col] = row + 1
            new_x = origin_x + col * spacing_x
            new_y = origin_y + row * spacing_y
            operations.append(
                {
                    "type": "UPDATE_POSITION",
                    "payload": {"id": node_id, "position": {"x": new_x, "y": new_y}},
                    "explanation": f"Automatic arrangement: positioning node at column {col}, row {row}",
                }
            )
    elif arrangement_type == "vertical":
        # Analogous to horizontal but with axes swapped
        seen = set()
        row_map: Dict[str, int] = {}
        queue = [(e.get("id"), 0) for e in entry_points]
        while queue:
            node_id, row = queue.pop(0)
            if node_id in seen:
                continue
            seen.add(node_id)
            row_map[node_id] = row
            for child in successors.get(node_id, []):
                if child not in seen:
                    queue.append((child, row + 1))
        col_counter: Dict[int, int] = {}
        for elem in elements:
            node_id = elem.get("id")
            row = row_map.get(node_id, 0)
            col = col_counter.get(row, 0)
            col_counter[row] = col + 1
            new_x = origin_x + col * spacing_x
            new_y = origin_y + row * spacing_y
            operations.append(
                {
                    "type": "UPDATE_POSITION",
                    "payload": {"id": node_id, "position": {"x": new_x, "y": new_y}},
                    "explanation": f"Automatic arrangement (vertical): positioning node at row {row}, column {col}",
                }
            )
    elif arrangement_type == "tree":
        # Hierarchical tree layout with root at top
        seen = set()
        level_map: Dict[str, int] = {}
        level_groups: Dict[int, List[str]] = {}
        queue = [(e.get("id"), 0) for e in entry_points]
        while queue:
            node_id, level = queue.pop(0)
            if node_id in seen:
                continue
            seen.add(node_id)
            level_map[node_id] = level
            if level not in level_groups:
                level_groups[level] = []
            level_groups[level].append(node_id)
            for child in successors.get(node_id, []):
                if child not in seen:
                    queue.append((child, level + 1))
        # Center nodes within each level
        for level, node_list in level_groups.items():
            count = len(node_list)
            total_span = (count - 1) * spacing_x
            offset_start = -total_span / 2
            for idx, node_id in enumerate(node_list):
                new_x = origin_x + 400 + offset_start + idx * spacing_x  # Center around 400
                new_y = origin_y + level * spacing_y
                operations.append(
                    {
                        "type": "UPDATE_POSITION",
                        "payload": {"id": node_id, "position": {"x": new_x, "y": new_y}},
                        "explanation": f"Automatic arrangement (tree): level {level}, position {idx + 1}/{count}",
                    }
                )
    elif arrangement_type == "grid":
        # Simple grid-based layout
        cols = max(3, int(len(elements) ** 0.5))
        for idx, elem in enumerate(elements):
            row = idx // cols
            col = idx % cols
            new_x = origin_x + col * spacing_x
            new_y = origin_y + row * spacing_y
            operations.append(
                {
                    "type": "UPDATE_POSITION",
                    "payload": {"id": elem.get("id"), "position": {"x": new_x, "y": new_y}},
                    "explanation": f"Automatic arrangement (grid): row {row}, col {col}",
                }
            )
    return json.dumps(
        {
            "arrangement_type": arrangement_type,
            "nodes_repositioned": len(operations),
            "operations": operations,
            "explanation": explanation,
        },
        ensure_ascii=False,
        indent=2,
    )

# QR payload encoding/decoding utilities for transport
from __future__ import annotations
import base64
import binascii
from typing import Final, Literal

# Supported encoding methods for QR payloads
QrPayloadFormat = Literal["raw", "base64"]
QR_FORMAT_RAW: Final[QrPayloadFormat] = "raw"
QR_FORMAT_BASE64: Final[QrPayloadFormat] = "base64"

def encode_for_qr(
    data: bytes,
    *,
    format_type: QrPayloadFormat = QR_FORMAT_BASE64,
) -> bytes | str:
    """Encode binary data for inclusion in a QR code."""
    if format_type == QR_FORMAT_RAW:
        return data
    if format_type != QR_FORMAT_BASE64:
        raise ValueError(f"unsupported QR encoding format: {format_type}")
    encoded = base64.b64encode(data).decode("ascii")
    return encoded.rstrip("=")

def decode_from_qr(
    payload: bytes | str,
    *,
    format_type: QrPayloadFormat = QR_FORMAT_BASE64,
) -> bytes:
    """Decode binary data from a QR code payload."""
    if format_type == QR_FORMAT_RAW:
        if isinstance(payload, bytes):
            return payload
        raise ValueError("invalid raw QR payload")
    if format_type != QR_FORMAT_BASE64:
        raise ValueError(f"unsupported QR encoding format: {format_type}")
    return _decode_base64_qr_data(payload)

def _decode_base64_qr_data(payload: bytes | str) -> bytes:
    """Decode unpadded base64-encoded QR payload text."""
    if isinstance(payload, bytes):
        try:
            text = payload.decode("ascii")
        except UnicodeDecodeError as exc:
            raise ValueError("invalid base64 QR payload") from exc
    else:
        text = payload
    cleaned = "".join(text.split())
    if "=" in cleaned:
        raise ValueError("invalid base64 QR payload")
    try:
        decoded = base64.b64decode(_add_padding_to_base64(cleaned), validate=True)
    except (binascii.Error, ValueError) as exc:
        raise ValueError("invalid base64 QR payload") from exc
    canonical = base64.b64encode(decoded).decode("ascii").rstrip("=")
    if canonical != cleaned:
        raise ValueError("invalid base64 QR payload")
    return decoded

def _add_padding_to_base64(text: str) -> str:
    """Append required padding characters to unpadded base64 string."""
    padding_needed = (-len(text)) % 4
    return text + ("=" * padding_needed)

__all__ = [
    "QR_FORMAT_BASE64",
    "QR_FORMAT_RAW",
    "QrPayloadFormat",
    "decode_from_qr",
    "encode_for_qr",
]

# Calculate pipeline layer splits for model parallelism
from megatron.core.transformer import TransformerConfig
from megatron.core.transformer.pipeline_parallel_layer_layout import (
    PipelineParallelLayerLayout,
)
from transformers import PretrainedConfig
from areal.api.alloc_mode import MegatronParallelStrategy
from areal.utils import logging
import math

logger = logging.getLogger("MCoreParallel")

def setup_pipeline_layer_distribution(
    parallel_config: MegatronParallelStrategy,
    huggingface_config: PretrainedConfig,
    mcore_config: TransformerConfig,
) -> TransformerConfig:
    pp_world_size = parallel_config.pipeline_parallel_size
    vpp_degree = parallel_config.virtual_pipeline_parallel_size

    if pp_world_size <= 1:
        return mcore_config

    num_stages = pp_world_size * vpp_degree
    total_blocks = getattr(mcore_config, "num_layers", None)

    if not isinstance(total_blocks, int) or total_blocks <= 0:
        return mcore_config

    block_param_estimates, embed_params, final_params = (
        estimate_partition_parameter_counts(huggingface_config, mcore_config)
    )

    if not block_param_estimates or all(val <= 0 for val in block_param_estimates):
        return mcore_config

    if len(block_param_estimates) != total_blocks:
        total_blocks = min(total_blocks, len(block_param_estimates))
        block_param_estimates = block_param_estimates[:total_blocks]

    stage_sizes = _calculate_stage_block_distributions(
        block_param_estimates,
        embed_params,
        final_params,
        num_stages,
    )

    if not stage_sizes:
        logger.warning(
            "Switching to default pipeline layout; could not compute valid partition."
        )
        return mcore_config

    layout_structure: list[list[str]] = []
    for pos, size in enumerate(stage_sizes):
        stage_components: list[str] = []
        if pos == 0:
            stage_components.append("embed")
        stage_components.extend(["transformer"] * size)
        if pos == num_stages - 1:
            stage_components.append("output")
        layout_structure.append(stage_components)

    layout = PipelineParallelLayerLayout(
        layout=layout_structure,
        pipeline_model_parallel_size=pp_world_size,
    )

    setattr(mcore_config, "pipeline_model_parallel_layout", layout)

    # Reset specific attributes related to layer counts
    if hasattr(mcore_config, "num_layers_in_first_pipeline_stage"):
        setattr(mcore_config, "num_layers_in_first_pipeline_stage", None)
    if hasattr(mcore_config, "num_layers_in_last_pipeline_stage"):
        setattr(mcore_config, "num_layers_in_last_pipeline_stage", None)
    if hasattr(mcore_config, "account_for_embedding_in_pipeline_split"):
        setattr(mcore_config, "account_for_embedding_in_pipeline_split", False)
    if hasattr(mcore_config, "account_for_loss_in_pipeline_split"):
        setattr(mcore_config, "account_for_loss_in_pipeline_split", False)

    # Compute per-stage computational loads
    stage_workloads: list[float] = []
    position = 0
    for pos, size in enumerate(stage_sizes):
        workload = 0.0
        if pos == 0:
            workload += embed_params
        end_pos = min(position + size, len(block_param_estimates))
        if end_pos > position:
            workload += sum(block_param_estimates[position:end_pos])
        position = end_pos
        if pos == num_stages - 1:
            workload += final_params
        stage_workloads.append(workload)

    logger.info(
        "Pipeline layout configured (decoder blocks / params per stage): %s / %s (pp=%s, vpp=%s)",
        stage_sizes,
        [f"{val / 1e6:.2f}M" for val in stage_workloads],
        pp_world_size,
        vpp_degree,
    )

    return mcore_config

def _calculate_stage_block_distributions(
    block_weights: list[float],
    embedding_cost: float,
    output_cost: float,
    pipeline_parallelism: int,
) -> list[int]:
    num_blocks = len(block_weights)
    if num_blocks == 0 or pipeline_parallelism <= 0:
        return []

    cumulative_sums = [0.0]
    for weight in block_weights:
        cumulative_sums.append(cumulative_sums[-1] + float(weight))

    def range_sum(left: int, right: int) -> float:
        return cumulative_sums[right] - cumulative_sums[left]

    stages = pipeline_parallelism
    dp_table = [[math.inf] * (num_blocks + 1) for _ in range(stages + 1)]
    split_points = [[-1] * (num_blocks + 1) for _ in range(stages + 1)]

    dp_table[0][0] = 0.0

    for stage_num in range(1, stages + 1):
        base_load = 0.0
        if stage_num == 1:
            base_load = embedding_cost
        elif stage_num == stages:
            base_load = output_cost

        for end_idx in range(num_blocks + 1):
            for start_idx in range(end_idx + 1):
                previous_cost = dp_table[stage_num - 1][start_idx]
                if not math.isfinite(previous_cost):
                    continue

                if stage_num not in (1, stages) and start_idx == end_idx:
                    continue

                current_load = base_load + range_sum(start_idx, end_idx)
                new_max = max(previous_cost, current_load)

                if new_max < dp_table[stage_num][end_idx]:
                    dp_table[stage_num][end_idx] = new_max
                    split_points[stage_num][end_idx] = start_idx

    if not math.isfinite(dp_table[stages][num_blocks]):
        return []

    block_counts = [0] * stages
    current_idx = num_blocks

    for stage_num in range(stages, 0, -1):
        boundary = split_points[stage_num][current_idx]
        if boundary < 0:
            return []
        block_counts[stage_num - 1] = current_idx - boundary
        current_idx = boundary

    return block_counts

def estimate_partition_parameter_counts(
    hf_config: PretrainedConfig, mcore_config: TransformerConfig
) -> tuple[list[float], float, float]:
    total_blocks = getattr(mcore_config, "num_layers", None)
    if not isinstance(total_blocks, int) or total_blocks <= 0:
        total_blocks = getattr(hf_config, "num_hidden_layers", 0)

