        expert_weights = calculate_mlp_parameters(int(moe_hidden_dim)) * local_experts

        shared_dim = getattr(mcore_config, "moe_shared_expert_intermediate_size", None)
        shared_weights = calculate_mlp_parameters(int(shared_dim)) if shared_dim else 0.0

        moe_block_params = float(
            attention_and_norm + router_weights + expert_weights + shared_weights
        )

        moe_block_indices: set[int] = set()
        frequency = getattr(mcore_config, "moe_layer_freq", 1)
        if isinstance(frequency, int):
