        for idx in moe_block_indices:
            layer_estimates[idx] = moe_block_params

    return (layer_estimates, embedding_cost, output_cost)

from typing import IO, Dict, List, Mapping, Optional, Tuple, Union, cast

# File typing inspired by the flexibility of types within the httpx library
# https://github.com/encode/httpx/blob/master/httpx/_types.py
FileData = Union[IO[bytes], bytes, str]
FileParam = Union[
    # file (or bytes)
    FileData,
    # (filename, file (or bytes))
    Tuple[Optional[str], FileData],
    # (filename, file (or bytes), content_type)
    Tuple[Optional[str], FileData, Optional[str]],
    # (filename, file (or bytes), content_type, headers)
    Tuple[
        Optional[str],
        FileData,
        Optional[str],
        Mapping[str, str],
    ],
]

def transform_file_dict_to_httpx_format(
    data: Dict[str, Union[FileParam, List[FileParam]]],
) -> List[Tuple[str, FileParam]]:
    """
    The format we use is a list of tuples, where the first element is the
    name of the file and the second is the file object. Typically HTTPX wants
    a dict, but to be able to send lists of files, you have to use the list
    approach (which also works for non-lists)
    https://github.com/encode/httpx/pull/1032
    """
    result_tuples = []
    for field_name, file_obj in data.items():
        if isinstance(file_obj, list):
            for item in file_obj:
                result_tuples.append((field_name, item))
        else:
            result_tuples.append((field_name, file_obj))
    return result_tuples

def set_content_type(*, file: FileParam, fallback_content_type: str) -> FileParam:
    """
    This function resolves to the file's content type, if provided, and defaults
    to the fallback_content_type value if not.
    """
    if isinstance(file, tuple):
        if len(file) == 2:
            filename, content = cast(Tuple[Optional[str], FileData], file)  # type: ignore
            return (filename, content, fallback_content_type)
        elif len(file) == 3:
            filename, content, current_content_type = cast(Tuple[Optional[str], FileData, Optional[str]], file)  # type: ignore
            final_content_type = current_content_type or fallback_content_type
            return (filename, content, final_content_type)
        elif len(file) == 4:
            filename, content, current_content_type, headers = cast(  # type: ignore
                Tuple[Optional[str], FileData, Optional[str], Mapping[str, str]], file
            )
            final_content_type = current_content_type or fallback_content_type
            return (filename, content, final_content_type, headers)
        else:
            raise ValueError(f"Unexpected tuple length: {len(file)}")
    return (None, file, fallback_content_type)

