def matrix_product(rot1: torch.Tensor, rot2: torch.Tensor) -> torch.Tensor:
    """
    Computes the product of two rotation matrices. Optimized implementation to prevent 
    automatic mixed precision downcasting.
    Args:
        rot1: Left operand with shape [*, 3, 3]
        rot2: Right operand with shape [*, 3, 3]
    Returns:
        Matrix product of rot1 and rot2
    """
    def compute_row(idx: int) -> torch.Tensor:
        return torch.stack(
            [
                rot1[..., idx, 0] * rot2[..., 0, 0] + rot1[..., idx, 1] * rot2[..., 1, 0] + rot1[..., idx, 2] * rot2[..., 2, 0],
                rot1[..., idx, 0] * rot2[..., 0, 1] + rot1[..., idx, 1] * rot2[..., 1, 1] + rot1[..., idx, 2] * rot2[..., 2, 1],
                rot1[..., idx, 0] * rot2[..., 0, 2] + rot1[..., idx, 1] * rot2[..., 1, 2] + rot1[..., idx, 2] * rot2[..., 2, 2],
            ],
            dim=-1,
        )

    return torch.stack(
        [
            compute_row(0),
            compute_row(1),
            compute_row(2),
        ],
        dim=-2,
    )

def apply_rotation(matrix: torch.Tensor, vector: torch.Tensor) -> torch.Tensor:
    """
    Applies a rotation matrix to a 3D vector. Optimized implementation to avoid data transfers.
    Args:
        matrix: Rotation matrices with shape [*, 3, 3]
        vector: 3D vectors with shape [*, 3]
    Returns:
        Rotated vectors with shape [*, 3]
    """
    vx, vy, vz = torch.unbind(vector, dim=-1)
    return torch.stack(
        [
            matrix[..., 0, 0] * vx + matrix[..., 0, 1] * vy + matrix[..., 0, 2] * vz,
            matrix[..., 1, 0] * vx + matrix[..., 1, 1] * vy + matrix[..., 1, 2] * vz,
            matrix[..., 2, 0] * vx + matrix[..., 2, 1] * vy + matrix[..., 2, 2] * vz,
