def convert_rotation_to_quaternion(rot: torch.Tensor) -> torch.Tensor:
    if rot.shape[-2:] != (3, 3):
        raise ValueError("Input rotation matrix has incorrect shape")

    # Extract elements
    xx, xy, xz = rot[..., 0, 0], rot[..., 0, 1], rot[..., 0, 2]
    yx, yy, yz = rot[..., 1, 0], rot[..., 1, 1], rot[..., 1, 2]
    zx, zy, zz = rot[..., 2, 0], rot[..., 2, 1], rot[..., 2, 2]

    # Build symmetric matrix K
    k_matrix_elements = [
        [
            xx + yy + zz,
            zy - yz,
            xz - zx,
            yx - xy,
        ],
        [
            zy - yz,
            xx - yy - zz,
            xy + yx,
            xz + zx,
        ],
        [
            xz - zx,
            xy + yx,
            yy - xx - zz,
            yz + zy,
        ],
        [
            yx - xy,
            xz + zx,
            yz + zy,
            zz - xx - yy,
        ],
    ]

    # Stack into tensor
    k_tensor = torch.stack([torch.stack(row, dim=-1) for row in k_matrix_elements], dim=-2)

    # Compute eigenvalues and eigenvectors
    _, eigenvectors = torch.linalg.eigh((1.0 / 3.0) * k_tensor)

    # Return quaternion corresponding to largest eigenvalue
    return eigenvectors[..., -1]

