            normalize_quaternions=normalize,
        )

    def compose_with_rotation(self, other: "Rotation") -> "Rotation":
        """Compose with another rotation using rotation matrices."""
        r1 = self.get_rotation_matrices()
        r2 = other.get_rotation_matrices()
        combined = matrix_product(r1, r2)
        return Rotation(rot_mats=combined, quaternions=None)

    def compose_with_quaternion(self, other: "Rotation", normalize: bool = True) -> "Rotation":
        """Compose with another rotation using quaternions."""
        q1 = self.get_quaternions()
        q2 = other.get_quaternions()
        combined = multiply_quaternions(q1, q2)
        return Rotation(rot_mats=None, quaternions=combined, normalize_quaternions=normalize)

    def transform_points(self, points: torch.Tensor) -> torch.Tensor:
        """Apply rotation to 3D points."""
        rot_mats = self.get_rotation_matrices()
        return apply_rotation(rot_mats, points)

    def inverse_transform_points(self, points: torch.Tensor) -> torch.Tensor:
        """Apply inverse rotation to 3D points."""
        rot_mats = self.get_rotation_matrices()
        inv_mats = transpose_rotation(rot_mats)
        return apply_rotation(inv_mats, points)

    def inverse(self) -> "Rotation":
        """Compute the inverse rotation."""
        if self._rotation_matrices is not None:
            return Rotation(rot_mats=transpose_rotation(self._rotation_matrices), quaternions=None)
        elif self._quaternion_rep is not None:
            return Rotation(
                rot_mats=None,
                quaternions=invert_quaternion(self._quaternion_rep),
                normalize_quaternions=False,
            )
        else:
            raise ValueError("No valid rotation representation")

    def unsqueeze(self, dim: int) -> "Rotation":
        """Add a dimension to the rotation."""
        if dim >= len(self.shape):
            raise ValueError("Invalid dimension")

        if self._rotation_matrices is not None:
            expanded = self._rotation_matrices.unsqueeze(dim if dim >= 0 else dim - 2)
            return Rotation(rot_mats=expanded, quaternions=None)
        elif self._quaternion_rep is not None:
            expanded = self._quaternion_rep.unsqueeze(dim if dim >= 0 else dim - 1)
            return Rotation(rot_mats=None, quaternions=expanded, normalize_quaternions=False)
        else:
            raise ValueError("No valid rotation representation")

    @staticmethod
    def concatenate(rotations: Sequence["Rotation"], dim: int) -> "Rotation":
        """Concatenate multiple rotations along a dimension."""
        mats_list = [r.get_rotation_matrices() for r in rotations]
        concatenated = torch.cat(mats_list, dim=dim if dim >= 0 else dim - 2)
        return Rotation(rot_mats=concatenated, quaternions=None)

    def apply_function_to_tensors(self, func: Callable[[torch.Tensor], torch.Tensor]) -> "Rotation":
        """Apply a function to the underlying tensors."""
        if self._rotation_matrices is not None:
            flat = self._rotation_matrices.view(self._rotation_matrices.shape[:-2] + (9,))
            components = torch.stack(list(map(func, torch.unbind(flat, dim=-1))), dim=-1)
            reshaped = components.view(components.shape[:-1] + (3, 3))
            return Rotation(rot_mats=reshaped, quaternions=None)
        elif self._quaternion_rep is not None:
            components = torch.stack(list(map(func, torch.unbind(self._quaternion_rep, dim=-1))), dim=-1)
            return Rotation(rot_mats=None, quaternions=components, normalize_quaternions=False)
        else:
            raise ValueError("No valid rotation representation")

    def to_gpu(self) -> "Rotation":
        """Move rotation to GPU."""
        if self._rotation_matrices is not None:
            return Rotation(rot_mats=self._rotation_matrices.cuda(), quaternions=None)
        elif self._quaternion_rep is not None:
            return Rotation(rot_mats=None, quaternions=self._quaternion_rep.cuda(), normalize_quaternions=False)
        else:
            raise ValueError("No valid rotation representation")

    def to_device(self, device: Optional[torch.device], dtype: Optional[torch.dtype]) -> "Rotation":
        """Move rotation to specified device and dtype."""
        if self._rotation_matrices is not None:
            return Rotation(
                rot_mats=self._rotation_matrices.to(device=device, dtype=dtype),
                quaternions=None,
            )
        elif self._quaternion_rep is not None:
            return Rotation(
                rot_mats=None,
                quaternions=self._quaternion_rep.to(device=device, dtype=dtype),
                normalize_quaternions=False,
            )
        else:
            raise ValueError("No valid rotation representation")

    def detach(self) -> "Rotation":
        """Create a detached copy without gradient tracking."""
        if self._rotation_matrices is not None:
            return Rotation(rot_mats=self._rotation_matrices.detach(), quaternions=None)
        elif self._quaternion_rep is not None:
            return Rotation(
                rot_mats=None,
                quaternions=self._quaternion_rep.detach(),
                normalize_quaternions=False,
            )
        else:
            raise ValueError("No valid rotation representation")


class RigidTransformation:
    """
    Represents a rigid transformation combining rotation and translation.
    Behaves like a tensor of transformations with shared batch dimensions.
    """
    def __init__(self, rotations: Optional[Rotation], translations: Optional[torch.Tensor]):
        """
        Initialize a rigid transformation.
        Args:
            rotations: Rotation object
            translations: Translation tensor with shape [*, 3]
        """
        # Extract properties from inputs
        batch_dims, dtype, device, requires_grad = None, None, None, None

        if translations is not None:
            batch_dims = translations.shape[:-1]
            dtype = translations.dtype
            device = translations.device
            requires_grad = translations.requires_grad
        elif rotations is not None:
            batch_dims = rotations.shape
            dtype = rotations.dtype
            device = rotations.device
            requires_grad = rotations.requires_grad
        else:
            raise ValueError("At least one of rotations or translations must be specified")

        # Create defaults if missing
        if rotations is None:
            rotations = Rotation.identity(batch_dims, dtype, device, requires_grad)
        if translations is None:
            translations = generate_zero_translations(batch_dims, dtype, device, requires_grad)

        # Validate compatibility
        if rotations.shape != translations.shape[:-1] or rotations.device != translations.device:
            raise ValueError("Rotation and translation shapes/devices incompatible")

        # Ensure full precision
        translations = translations.to(dtype=torch.float32)

        self._rotation = rotations
        self._translation = translations

    @staticmethod
    def identity(
        shape: Tuple[int, ...],
        dtype: Optional[torch.dtype] = None,
        device: Optional[torch.device] = None,
        requires_grad: bool = True,
        representation: str = "quaternion",
    ) -> "RigidTransformation":
        """Create an identity rigid transformation."""
        return RigidTransformation(
            Rotation.identity(shape, dtype, device, requires_grad, representation),
            generate_zero_translations(shape, dtype, device, requires_grad),
        )

    def __getitem__(self, index: Any) -> "RigidTransformation":
        """Index the transformation."""
        if not isinstance(index, tuple):
            index = (index,)
        return RigidTransformation(
            self._rotation[index],
            self._translation[index + (slice(None),)],
        )

    def __mul__(self, scalar: torch.Tensor) -> "RigidTransformation":
        """Pointwise multiplication with a scalar."""
        if not isinstance(scalar, torch.Tensor):
            raise TypeError("Multiplicand must be a Tensor")

        new_rot = self._rotation * scalar
        new_trans = self._translation * scalar[..., None]
        return RigidTransformation(new_rot, new_trans)

    def __rmul__(self, scalar: torch.Tensor) -> "RigidTransformation":
        """Reverse multiplication."""
        return self.__mul__(scalar)

    @property
    def shape(self) -> torch.Size:
        """Return the batch shape."""
        return self._translation.shape[:-1]

    @property
    def device(self) -> torch.device:
        """Return the device."""
        return self._translation.device

    def get_rotation(self) -> Rotation:
        """Get the rotation component."""
        return self._rotation

    def get_translation(self) -> torch.Tensor:
        """Get the translation component."""
        return self._translation

    def compose_with_quaternion_update(self, update_vec: torch.Tensor) -> "RigidTransformation":
        """Compose with a quaternion update vector."""
        rot_update, trans_update = update_vec[..., :3], update_vec[..., 3:]
        new_rot = self._rotation.compose_with_quaternion_update(rot_update)
        transformed_update = self._rotation.transform_points(trans_update)
        new_trans = self._translation + transformed_update
        return RigidTransformation(new_rot, new_trans)

    def compose_with_rigid(self, other: "RigidTransformation") -> "RigidTransformation":
        """Compose with another rigid transformation."""
        combined_rot = self._rotation.compose_with_rotation(other._rotation)
        combined_trans = self._rotation.transform_points(other._translation) + self._translation
        return RigidTransformation(combined_rot, combined_trans)

    def transform_points(self, points: torch.Tensor) -> torch.Tensor:
        """Apply transformation to points."""
        rotated = self._rotation.transform_points(points)
        return rotated + self._translation

    def inverse_transform_points(self, points: torch.Tensor) -> torch.Tensor:
        """Apply inverse transformation to points."""
        centered = points - self._translation
        return self._rotation.inverse_transform_points(centered)

    def inverse(self) -> "RigidTransformation":
        """Compute the inverse transformation."""
        inv_rot = self._rotation.inverse()
        inv_trans = inv_rot.transform_points(self._translation)
        return RigidTransformation(inv_rot, -1 * inv_trans)

    def apply_function_to_tensors(self, func: Callable[[torch.Tensor], torch.Tensor]) -> "RigidTransformation":
        """Apply function to both rotation and translation."""
        new_rot = self._rotation.apply_function_to_tensors(func)
        new_trans = torch.stack(list(map(func, torch.unbind(self._translation, dim=-1))), dim=-1)
        return RigidTransformation(new_rot, new_trans)

    def to_homogeneous_matrix(self) -> torch.Tensor:
        """Convert to homogeneous transformation matrix [*, 4, 4]."""
        batch_shape = (*self.shape, 4, 4)
        tensor = self._translation.new_zeros(batch_shape)
        tensor[..., :3, :3] = self._rotation.get_rotation_matrices()
        tensor[..., :3, 3] = self._translation
        tensor[..., 3, 3] = 1
        return tensor

    @staticmethod
    def from_homogeneous_matrix(mat: torch.Tensor) -> "RigidTransformation":
        """Create from homogeneous transformation matrix."""
        if mat.shape[-2:] != (4, 4):
            raise ValueError("Incorrectly shaped input tensor")

        rot = Rotation(rot_mats=mat[..., :3, :3], quaternions=None)
        trans = mat[..., :3, 3]
        return RigidTransformation(rot, trans)

    def to_7d_tensor(self) -> torch.Tensor:
        """Convert to 7D tensor [*, 7] (quaternion + translation)."""
        batch_shape = (*self.shape, 7)
        tensor = self._translation.new_zeros(batch_shape)
        tensor[..., :4] = self._rotation.get_quaternions()
        tensor[..., 4:] = self._translation
        return tensor

    @staticmethod
    def from_7d_tensor(tensor: torch.Tensor, normalize_quaternions: bool = False) -> "RigidTransformation":
        """Create from 7D tensor."""
        if tensor.shape[-1] != 7:
            raise ValueError("Incorrectly shaped input tensor")

        quaternions, translations = tensor[..., :4], tensor[..., 4:]
        rot = Rotation(rot_mats=None, quaternions=quaternions, normalize_quaternions=normalize_quaternions)
        return RigidTransformation(rot, translations)

    @staticmethod
    def from_three_points(
        neg_x_axis: torch.Tensor, origin: torch.Tensor, xy_plane: torch.Tensor, eps: float = 1e-8
    ) -> "RigidTransformation":
        """Construct transformation from three points using Gram-Schmidt."""
        # Unbind coordinates
        neg_x_coords = list(torch.unbind(neg_x_axis, dim=-1))
        origin_coords = list(torch.unbind(origin, dim=-1))
        xy_coords = list(torch.unbind(xy_plane, dim=-1))

