        e0 = [o - n for o, n in zip(origin_coords, neg_x_coords)]
        e1 = [p - o for p, o in zip(xy_coords, origin_coords)]

        # Normalize e0
        denom = torch.sqrt(sum(c * c for c in e0) + eps * torch.ones_like(e0[0]))
        e0 = [c / denom for c in e0]

        # Orthogonalize e1
        dot = sum(c1 * c2 for c1, c2 in zip(e0, e1))
        e1 = [c2 - c1 * dot for c1, c2 in zip(e0, e1)]

        # Normalize e1
        denom = torch.sqrt(sum(c * c for c in e1) + eps * torch.ones_like(e1[0]))
        e1 = [c / denom for c in e1]

        # Compute e2 = e0 × e1
        e2 = [
            e0[1] * e1[2] - e0[2] * e1[1],
            e0[2] * e1[0] - e0[0] * e1[2],
            e0[0] * e1[1] - e0[1] * e1[0],
