import types
import importlib

def test_plugin_with_none_plugin_class(monkeypatch):
    registry = get_cortex_registry()
    dummy_module = types.SimpleNamespace(PLUGIN_CLASS=None)
    original_import = importlib.import_module

    def mock_import(module_name):
        # Support both current and legacy module paths
        if module_name in (
            "cortex.llm_provider.bad_none",
            "cortex.llm_engine.bad_none",
        ):
            return dummy_module
        return original_import(module_name)

    monkeypatch.setattr(importlib, "import_module", mock_import)
    registry.register_engine_module(
        "bad_none",
        "cortex.llm_provider.bad_none",
        cortex="llm_provider",
    )
    try:
        registry.load_engine("bad_none")
        assert False, "Should have raised ValueError for missing PLUGIN_CLASS"
    except ValueError as exc:
        assert "PLUGIN_CLASS" in str(exc) and "None" in str(exc)

