# Douyin search scraper using Playwright async API
import argparse
import asyncio
import json
import sys
from datetime import datetime
from pathlib import Path
from playwright.async_api import async_playwright

async def fetch_douyin_videos(search_term: str, max_iterations: int = 10):
    """Fetch video data from Douyin search results via DOM scraping."""
    collected_items = []

    async with async_playwright() as pw:
        # Connect to existing Chrome instance
        browser = await pw.chromium.connect_over_cdp("http://localhost:9222")
        main_context = browser.contexts[0]
        active_page = await main_context.new_page()

        # Construct search URL
        target_url = f"https://www.douyin.com/search/{search_term}?type=video"
        print(f"Loading page: {target_url}")

        # Navigate and wait for content
        await active_page.goto(target_url, wait_until="domcontentloaded", timeout=30000)
        await asyncio.sleep(3)

        # Perform scrolling and extraction
        for iteration in range(max_iterations):
            # Extract video elements using multiple CSS selectors
            video_data = await active_page.evaluate("""() => {
                const extracted = [];

                // List of potential selectors for video items
                const candidate_selectors = [
                    '[class*="search-result"] li',
                    '[class*="video-list"] li', 
                    '[data-e2e="scroll-list"] > div',
                    'ul[class*="list"] > li',
                    '[class*="search"] [class*="card"]',
                    '[class*="result"] [class*="item"]'
                ];

                let best_match = [];
                for (const selector of candidate_selectors) {
                    const found = document.querySelectorAll(selector);
                    if (found.length > best_match.length) best_match = found;
                }

                // Fallback method: find links pointing to video pages
                if (best_match.length === 0) {
                    const all_links = document.querySelectorAll('a[href*="/video/"]');
                    all_links.forEach(link => {
                        const text = link.textContent?.trim()?.substring(0, 200) || '';
                        const href = link.href || '';
                        if (text && href) {
                            extracted.push({
                                title: text,
                                url: href,
                                author: [redacted]
                                views: '',
                                origin: 'link_fallback'
                            });
                        }
                    });
                    return extracted;
                }

                // Process matched elements
                best_match.forEach(element => {
                    const title_node = element.querySelector('a, [class*="title"], h2, h3, p');
                    const author_node = element.querySelector('[class*="author"], [class*="name"], [class*="user"]');
                    const stats_node = element.querySelector('[class*="like"], [class*="count"]');
                    const link_node = element.querySelector('a[href*="/video/"]') || element.querySelector('a');

                    const title = title_node?.textContent?.trim()?.substring(0, 200) || '';
                    const author = author_node?.textContent?.trim() || '';
                    const stats = stats_node?.textContent?.trim() || '';
                    const url = link_node?.href || '';

                    if (title || url) {
                        extracted.push({ 
                            title: title, 
                            author: [redacted]
                            views: stats, 
                            url: url, 
                            origin: 'card' 
                        });
                    }
                });
                return extracted;
            }""")

            # Deduplicate and collect results
            for item in video_data:
                if item.get("url") and not any(existing["url"] == item["url"] for existing in collected_items):
                    collected_items.append(item)

            print(f"Iteration {iteration+1}/{max_iterations}: detected {len(video_data)} items, total unique: {len(collected_items)}")

            # Scroll down if not last iteration
            if iteration < max_iterations - 1:
                await active_page.evaluate("window.scrollBy(0, window.innerHeight * 2)")
                await asyncio.sleep(2)

        # Cleanup
        await active_page.close()
        await browser.close()

    return collected_items

def execute():
    # Command-line argument parsing
    parser = argparse.ArgumentParser(description="Douyin Search Scraper")
    parser.add_argument("--query", required=True, help="Search keyword")
    parser.add_argument("--destination", default="./data/dy_results.json", help="Output JSON file path")
    parser.add_argument("--iterations", type=int, default=10, help="Number of scroll iterations")

    args = parser.parse_args()

    # Run the scraper
    scraped_data = asyncio.run(fetch_douyin_videos(args.query, args.iterations))

    # Prepare output directory and save results
    output_file = Path(args.destination)
    output_file.parent.mkdir(parents=True, exist_ok=True)

    final_output = {
        "search_term": args.query,
        "timestamp": datetime.now().isoformat(),
        "total_count": len(scraped_data),
        "items": scraped_data
    }

    output_file.write_text(
        json.dumps(final_output, ensure_ascii=False, indent=2), 
        encoding="utf-8"
    )
    print(f"\nSaved {len(scraped_data)} entries to {output_file}")

if __name__ == "__main__":
    execute()

