import unittest
from noether.core.schedules import ScheduleBase, SequentialStepSchedule, SequentialStepScheduleConfig

class PlaceholderSchedule(ScheduleBase):
    def __init__(self, step_to_value=None, **kwargs):
        super().__init__(**kwargs)
        self.step_to_value = step_to_value

    def _get_value(self, step: int, total_steps: int) -> float:
        if self.step_to_value is None:
            return 0.0
        return self.step_to_value[step]

class TestSequentialStepSchedule(unittest.TestCase):
    def test_propagate_singleconfig(self):
        sched = SequentialStepSchedule(
            [
                SequentialStepScheduleConfig(schedule=PlaceholderSchedule()),
            ]
        )
        self.assertEqual(0, sched.schedule_configs[0].start_step)
        self.assertIsNone(sched.schedule_configs[0].end_step)

    def test_propagate_forward(self):
        sched = SequentialStepSchedule(
            [
                SequentialStepScheduleConfig(end_step=10, schedule=PlaceholderSchedule()),
                SequentialStepScheduleConfig(schedule=PlaceholderSchedule()),
            ]
        )
        self.assertEqual(0, sched.schedule_configs[0].start_step)
        self.assertEqual(10, sched.schedule_configs[0].end_step)
        self.assertEqual(10, sched.schedule_configs[1].start_step)
        self.assertIsNone(sched.schedule_configs[1].end_step)

    def test_propagate_backward(self):
        sched = SequentialStepSchedule(
            [
                SequentialStepScheduleConfig(schedule=PlaceholderSchedule()),
                SequentialStepScheduleConfig(start_step=10, schedule=PlaceholderSchedule()),
            ]
        )
        self.assertEqual(0, sched.schedule_configs[0].start_step)
        self.assertEqual(10, sched.schedule_configs[0].end_step)
        self.assertEqual(10, sched.schedule_configs[1].start_step)
        self.assertIsNone(sched.schedule_configs[1].end_step)

    def test_propagate_gap(self):
        sched = SequentialStepSchedule(
            [
                SequentialStepScheduleConfig(end_step=10, schedule=PlaceholderSchedule()),
                SequentialStepScheduleConfig(start_step=15, schedule=PlaceholderSchedule()),
            ]
        )
        self.assertEqual(0, sched.schedule_configs[0].start_step)
        self.assertEqual(10, sched.schedule_configs[0].end_step)
        self.assertEqual(15, sched.schedule_configs[1].start_step)
        self.assertIsNone(sched.schedule_configs[1].end_step)

    def test_propagate_middle(self):
        sched = SequentialStepSchedule(
            [
                SequentialStepScheduleConfig(end_step=10, schedule=PlaceholderSchedule()),
                SequentialStepScheduleConfig(schedule=PlaceholderSchedule()),
                SequentialStepScheduleConfig(start_step=15, schedule=PlaceholderSchedule()),
            ]
        )
        self.assertEqual(0, sched.schedule_configs[0].start_step)
        self.assertEqual(10, sched.schedule_configs[0].end_step)
        self.assertEqual(10, sched.schedule_configs[1].start_step)
        self.assertEqual(15, sched.schedule_configs[1].end_step)
        self.assertEqual(15, sched.schedule_configs[2].start_step)
        self.assertIsNone(sched.schedule_configs[2].end_step)

    def test_propagate_noneinbetween(self):
        with self.assertRaises(ValueError):
            SequentialStepSchedule(
                [
                    SequentialStepScheduleConfig(end_step=10, schedule=PlaceholderSchedule()),
                    SequentialStepScheduleConfig(schedule=PlaceholderSchedule()),
                    SequentialStepScheduleConfig(schedule=PlaceholderSchedule()),
                ]
            )

    def test_check_singleconfig(self):
        with self.assertRaises(ValueError):
            SequentialStepSchedule(
                [
                    SequentialStepScheduleConfig(start_step=5, end_step=3, schedule=PlaceholderSchedule()),
                ]
            )

    def test_check_propagatedendstep(self):
        with self.assertRaises(ValueError):
            SequentialStepSchedule(
                [
                    SequentialStepScheduleConfig(end_step=10, schedule=PlaceholderSchedule()),
                    SequentialStepScheduleConfig(start_step=5, schedule=PlaceholderSchedule()),
                ]
            )

    def test_get_sequential_schedule_config_zeroduration(self):
        sched = SequentialStepSchedule(
            [
                SequentialStepScheduleConfig(end_step=0, schedule=PlaceholderSchedule()),
                SequentialStepScheduleConfig(schedule=PlaceholderSchedule()),
            ]
        )
        self.assertEqual(sched.schedule_configs[1], sched.get_sequential_schedule_config(0))

    def test_get_sequential_schedule_config(self):
        sched = SequentialStepSchedule(
            [
                SequentialStepScheduleConfig(start_step=5, end_step=10, schedule=PlaceholderSchedule()),
                SequentialStepScheduleConfig(end_step=15, schedule=PlaceholderSchedule()),
                SequentialStepScheduleConfig(schedule=PlaceholderSchedule()),
            ]
        )
        for i in range(5):
            self.assertIsNone(sched.get_sequential_schedule_config(i))
        for i in range(5, 10):
            self.assertEqual(sched.schedule_configs[0], sched.get_sequential_schedule_config(i))
        for i in range(10, 15):
            self.assertEqual(sched.schedule_configs[1], sched.get_sequential_schedule_config(i))
        for i in range(15, 30):
            self.assertEqual(sched.schedule_configs[2], sched.get_sequential_schedule_config(i))

    def test_get_sequential_schedule_config_gap(self):
        sched = SequentialStepSchedule(
            [
                SequentialStepScheduleConfig(start_step=5, end_step=10, schedule=PlaceholderSchedule()),
                SequentialStepScheduleConfig(start_step=15, end_step=20, schedule=PlaceholderSchedule()),
                SequentialStepScheduleConfig(schedule=PlaceholderSchedule()),
            ]
        )
        for i in range(5):
            self.assertIsNone(sched.get_sequential_schedule_config(i))
        for i in range(5, 10):
            self.assertEqual(sched.schedule_configs[0], sched.get_sequential_schedule_config(i))
        # gap returns previous schedule
        for i in range(10, 15):
            self.assertEqual(sched.schedule_configs[0], sched.get_sequential_schedule_config(i))
        for i in range(15, 20):
            self.assertEqual(sched.schedule_configs[1], sched.get_sequential_schedule_config(i))
        for i in range(20, 30):
            self.assertEqual(sched.schedule_configs[2], sched.get_sequential_schedule_config(i))

    def test_get_value_before_first_schedule(self):
        sched = SequentialStepSchedule(
            [
                SequentialStepScheduleConfig(start_step=5, schedule=PlaceholderSchedule(step_to_value={0: 0.5})),
            ]
        )
        for i in range(5):
            self.assertEqual(0.5, sched.get_value(i, 10))

    def test_get_value_after_last_schedule(self):
        sched = SequentialStepSchedule(
            [
                SequentialStepScheduleConfig(
                    start_step=3,
                    end_step=5,
                    schedule=PlaceholderSchedule(step_to_value={0: 0.1, 1: 0.2}),
                ),
            ]
        )
        for i in range(4):
            self.assertEqual(0.1, sched.get_value(i, 11))
        self.assertEqual(0.2, sched.get_value(4, 11))
        for i in range(5, 11):
            self.assertEqual(0.2, sched.get_value(i, 11))

    def test_tostring(self):
        sched = SequentialStepSchedule(
            [
                SequentialStepScheduleConfig(
                    start_step=3,
                    end_step=5,
                    schedule=PlaceholderSchedule(step_to_value={0: 0.1, 1: 0.2}),
                ),
            ]
        )
        lines = str(sched).split("\n")
        self.assertEqual(3, len(lines))
        self.assertEqual(SequentialStepSchedule.__name__, lines[0])
        self.assertEqual("  (0): 3 - 5 PlaceholderSchedule", lines[1])
        self.assertEqual(")", lines[2])

# Modified version of Communication class with renamed variables, reordered statements, and minor structural changes
from dataclasses import dataclass, field
from datetime import datetime
import re
from typing import cast
from rich.text import Text
from epstein_files.documents.document import CLOSE_PROPERTIES_CHAR, Document
from epstein_files.documents.documents.doc_cfg import CommunicationCfg
from epstein_files.output.highlight_config import HIGHLIGHTED_CONTACTS, get_style_for_name, styled_name
from epstein_files.output.rich import styled_key_value
from epstein_files.people.names import UNKNOWN, Name
from epstein_files.util.helpers.data_helpers import uniquify
from epstein_files.util.helpers.rich_helpers import no_bold

# Regex to match seconds at the end of timestamp (e.g., ":59")
TIMESTAMP_SECONDS_PATTERN = re.compile(r":\d{2}$")

@dataclass
class Communication(Document):
    """
    Base class for `Email` and `MessengerLog`.
    Attributes:
        extracted_recipients (list[Name]): People extracted as recipients during parsing.
    """
    # Store recipients either from config or extracted during processing
    extracted_recipients: list[Name] = field(default_factory=list)

    def __post_init__(self):
        super().__post_init__()
        # Initialize extracted_recipients based on config or extraction method
        if self.config and self.config.recipients:
            self.extracted_recipients = []
        else:
            self.extracted_recipients = self._extract_recipients()

    @property
    def sender_or_unknown(self) -> str:
        """Return author name or UNKNOWN if missing."""
        return self.author or UNKNOWN

    @property
    def sender_style(self) -> str:
        """Get styling for the sender's name."""
        return get_style_for_name(self.author)

    @property
    def sender_txt(self) -> Text:
        """Return styled sender name as Rich Text."""
        return styled_name(self.author)

    @property
    def border_color_style(self) -> str:
        """Apply non-bold styling to border using sender style."""
        return no_bold(self.sender_style)

    @property
    def involved_people(self) -> list[str]:
        """List unique people involved in communication (sender, recipients, mentions)."""
        if self.config and self.config.people:
            return self.config.people
        base_people = super().people + [p for p in self.participants if p]
        return sorted(uniquify(base_people))

    @property
    def configuration(self) -> CommunicationCfg | None:
        """Retrieve communication-specific configuration."""
        cfg = super().config
        if cfg and not isinstance(cfg, CommunicationCfg):
            self.warn(f"Found config that's the wrong type! {repr(cfg)}")
            cfg = cast(CommunicationCfg, cfg)
        return cfg

    @property
    def contains_unknown_sender(self) -> bool:
        """Check if any participant is unknown (None)."""
        return None in self.participants

    @property
    def contains_unknown_recipient(self) -> bool:
        """Check if any recipient is unknown (None)."""
        return None in (self.recipients or [None])

    @property
    def recipient_confidence_low(self) -> bool:
        """Determine if recipient confidence is low per config."""
        return bool(self.configuration and self.configuration.recipient_uncertain)

    @property
    def participants(self) -> set[Name]:
        """Set of participants: author plus recipients (or [None] if empty)."""
        return set([self.author] + (self.recipients or [None]))

    @property
    def recipients(self) -> list[Name]:
        """Return configured recipients if available, otherwise extracted ones."""
        if self.configuration and self.configuration.recipients:
            return self.configuration.recipients
        else:
            return self.extracted_recipients

    @property
    def primary_recipient_style(self) -> str:
        """Style for the first recipient (or sender if no recipients)."""
        return get_style_for_name((self.recipients or [self.author])[0])

    @property
    def timestamp_cleaned(self) -> str:
        """Remove seconds from timestamp string."""
        return TIMESTAMP_SECONDS_PATTERN.sub('', str(self.timestamp))

    @property
    def _short_summary(self) -> Text:
        """One-line summary ending with close bracket character."""
        return self._summary_with_sender.append(CLOSE_PROPERTIES_CHAR)

    @property
    def _summary_with_sender(self) -> Text:
        """Append sender info to parent summary, leaving bracket open."""
        sender_str = styled_key_value('author', Text(f"'{self.sender_or_unknown}'", style=self.sender_style))
        return super()._summary.append(', ').append(sender_str)

    def colored_external_links(self) -> Text:
        """Override to use recipient style for external link coloring."""
        return self.file_info.build_external_links(self.primary_recipient_style, with_alt_links=True)

    def _extract_recipients(self) -> list[Name]:
        """To be implemented by subclasses."""
        return []

    @classmethod
    def default_category(cls) -> str:
        """Default category name derived from class name."""
        return cls.__name__.lower()

