def validate_arguments(args):
    assert args.untie_embeddings_and_output_weights == True, "Not supported for code cleanness"
    assert args.defer_embedding_wgrad_compute == False, "The original code seems incorrect"

    # Reordered conditions
    if (
        args.num_seq_splits > 1
        or args.interleave_group_size > 0
        or args.zb_v_schedule_enabled
        or args.zb_enabled
        or args.f1f1b_v_enabled
        or args.zb_runtime_enabled
    ):
        args.zb_runtime_enabled = True
        if not args.gradient_accumulation_fusion:
            raise RuntimeError("gradient-accumulation-fusion should be True for zb runtime.")

    if args.pre_comm_optimization_enabled:
        if not args.zb_runtime_enabled or not args.overlap_p2p_comm:
            raise RuntimeError(
                "pre-communication only works with --enable-zb-runtime and without --no-overlap-p2p-communication"
            )

    if args.zb_runtime_enabled and args.overlap_p2p_comm:
        cuda_device_max_conn = int(os.environ.get("CUDA_DEVICE_MAX_CONNECTIONS") or 8)
        if cuda_device_max_conn < 8:
            raise RuntimeError("Set CUDA_DEVICE_MAX_CONNECTIONS >= 8 for overlap-p2p-communication")

    if args.zb_v_schedule_enabled or args.f1f1b_v_enabled:
        assert (
            args.num_layers % args.transformer_pipeline_model_parallel_size == 0
        ), "number of layers should be divisible by the pipeline parallel size"

        num_layers_per_stage = args.num_layers // args.transformer_pipeline_model_parallel_size
        assert (
            num_layers_per_stage % 2 == 0
        ), "zero bubble v and 1f1b v schedule requires number of layers per pipeline stage to be even"

        assert (
            args.num_layers_per_virtual_pipeline_stage is None
        ), "num_layers_per_virtual_pipeline_stage should not be set with zero bubble v and 1f1b v schedule"

        args.virtual_pipeline_model_parallel_size = 2
        args.num_layers_per_virtual_pipeline_stage = num_layers_per_stage // 2

    if args.zb_v_schedule_enabled:
        args.zb_enabled = True
        assert args.zb_v_mem_setup in {"min", "half", "zb"}

    if args.f1f1b_v_enabled:
        assert args.pipeline_model_parallel_size > 1, "1f1b-v must be enabled with pipeline parallelism"
        assert not args.zb_enabled, "cannot enable zero bubble for 1f1b-v"
        assert not args.opt_post_validation_enabled, "cannot enable post validation for 1f1b-v"

    if args.zb_enabled:
        if args.use_distributed_optimizer:
            assert not args.overlap_param_gather, "the original code somehow doesn't work"
            assert not args.overlap_grad_reduce, "not supported yet because we didn't verify the correctness"

        assert args.pipeline_model_parallel_size > 1, "zero bubble must be enabled with pipeline parallelism"

        if args.opt_post_validation_enabled:
            assert args.fp16, "zero bubble post validation"

        if args.zb_max_backward_pending == "adaptive":
            assert args.zb_memory_limit_percentile > 0
        else:
            args.zb_max_backward_pending = int(args.zb_max_backward_pending)
    else:
        args.opt_post_validation_enabled = False

    if args.cpu_offload:
        if args.auto_offload_latency:
            args.offload_latency = get_offload_time(args.hidden_size, args.seq_length)
            logging.info(f"Auto-configured offload-latency: {args.offload_latency:.4f}")
        else:
            logging.info(f"Specified offload-latency: {args.offload_latency:.4f}")

def get_offload_time(hidden_size: int, seq_length: int):
    tflops, d2h_bandwidth_gbps = get_gpu_flops_and_offload_bandwidth()
    k = 10.0 / (3 * (6 * hidden_size + seq_length)) * tflops * 1000.0 / d2h_bandwidth_gbps
    return k / 2.0

def get_gpu_flops_and_offload_bandwidth():
    """Get GPU model name and other properties."""
    import torch
    assert torch.cuda.is_available(), "cuda not available"

    gpu_specs = {
        "A100": {
            "tflops": 220,  # Profiled TFLOPS during training
            "d2h_bandwidth_gbps": 15,  # Profiled H2D bandwidth
        },
        "H100": {
            "tflops": 220 * 2,
            "d2h_bandwidth_gbps": 21,
        },
    }

    gpu_name = torch.cuda.get_device_name(0)
    for name, specs in gpu_specs.items():
        if name in gpu_name:
            return specs["tflops"], specs["d2h_bandwidth_gbps"]

    default_spec = gpu_specs["A100"]
    return default_spec["tflops"], default_spec["d2h_bandwidth_gbps"]

class WeightGradStore:
    should_split_bw = False
    cache = []
    weight_grad_queue = None  # lazy init

    @classmethod
    def lazy_init(cls):
        if cls.weight_grad_queue is not None:
            return
        num_chunks = parallel_state.get_virtual_pipeline_model_parallel_world_size() or 1
        cls.weight_grad_queue = [
            [queue.Queue() for _ in range(get_args().num_seq_splits)] for _ in range(num_chunks)
        ]

    @classmethod
    def is_supported(cls):
        args = get_args()
        if args.pipeline_model_parallel_size <= 1:
            return False
        if args.overlap_grad_reduce:
            return False
        if not args.gradient_accumulation_fusion:
            return False
        return True

    @classmethod
    def split_bw(cls):
        if not cls.is_supported():
            return False
        return cls.should_split_bw

    @classmethod
    def enable_split_bw(cls):
        cls.should_split_bw = True

    @classmethod
    def disable_split_bw(cls):
        cls.should_split_bw = False

    @classmethod
    @contextmanager
    def set_split_bw(cls, enabled: bool):
        prev = cls.should_split_bw
        cls.should_split_bw = enabled
        try:
            yield
        finally:
            cls.should_split_bw = prev

    @classmethod
    def put(cls, weight, pre_func, func):
        assert cls.split_bw()
        cls.cache.append((weight, pre_func, func))
        return

    @classmethod
    def queue_size(cls, chunk=0, seq_split_idx=0):
        cls.lazy_init()
        return WeightGradStore.weight_grad_queue[chunk][seq_split_idx].qsize()

    @classmethod
    def flush(cls, chunk=0, seq_split_idx=0, num=None):
        cls.lazy_init()
        if not cls.split_bw():
            assert len(cls.cache) == 0
            return
        if num is not None and num < len(cls.cache):
            cls.weight_grad_queue[chunk][seq_split_idx].put(cls.cache[:num])
            cls.cache = cls.cache[num:]
        else:
            cls.weight_grad_queue[chunk][seq_split_idx].put(cls.cache)
            cls.cache = []

    @classmethod
    def pop(cls, chunk=0, seq_split_idx=0, clear=False):
        cls.lazy_init()
        def cal_stored_grad(stored_grads):
            for j in range(len(stored_grads)):
                weight, pre_func, func = stored_grads[j]
                func(*pre_func(async_op=False))
                if clear:
                    stored_grads[j] = None
        cal_stored_grad_func = cal_stored_grad
        if get_args().dump_pp_data:
            cal_stored_grad_func = fwd_bwd_wrapper(cal_stored_grad, "wgrad")
        if cls.weight_grad_queue[chunk][seq_split_idx].qsize() > 0:
            stored_grads = cls.weight_grad_queue[chunk][seq_split_idx].get()
            cal_stored_grad_func(stored_grads)
        else:
            rank = parallel_state.get_pipeline_model_parallel_rank()
            raise Exception(f"Pop empty queue. rank {rank}")

    @classmethod
    def assert_empty(cls):
        rank = parallel_state.get_pipeline_model_parallel_rank()
        assert len(cls.cache) == 0, f"cache is not empty. rank {rank}"
        if cls.weight_grad_queue is None:
            return
        for chunk, chunk_q in enumerate(cls.weight_grad_queue):
            for seq, seq_q in enumerate(chunk_q):
                assert (
                    seq_q.empty()
                ), f"Queue is not empty chunk {chunk} seq {seq} rank {rank}. len {seq_q.qsize()}"

    @classmethod
    def clear(cls, model, chunk=0, seq_split_idx=0):
        cls.lazy_init()
        while cls.weight_grad_queue[chunk][seq_split_idx].qsize() > 0:
            WeightGradStore.pop(chunk, seq_split_idx, clear=True)
        return

class RecomputeStore:
    cache = []
    recompute_queue = None
    recompute_flag = False

    @classmethod
    def lazy_init(cls):
        if cls.recompute_queue is not None:
            return
        num_chunks = parallel_state.get_virtual_pipeline_model_parallel_world_size() or 1
        cls.recompute_queue = [queue.Queue() for _ in range(num_chunks)]

    @classmethod
    @contextmanager
    def set_recompute_flag(cls, enabled: bool):
        prev = cls.recompute_flag
        cls.recompute_flag = enabled
        try:
            yield
        finally:
            cls.recompute_flag = prev

    @classmethod
    def should_recompute(cls):
        return cls.recompute_flag

    @classmethod
    def put(cls, func):
        assert cls.recompute_flag
        cls.lazy_init()
        cls.cache.append(func)

    @classmethod
    def flush(cls):
        if not cls.recompute_flag:
            assert len(cls.cache) == 0
            return
        cls.lazy_init()
        chunk = parallel_state.get_virtual_pipeline_model_parallel_rank()
        cls.recompute_queue[chunk].put(cls.cache)
        cls.cache = []

    @classmethod
    def pop(cls):
        cls.lazy_init()
        chunk = parallel_state.get_virtual_pipeline_model_parallel_rank()
        recompute_funcs = cls.recompute_queue[chunk].get()
        for func in recompute_funcs:
            func()

# Modified version of InternVLWeightMapper with renamed variables and reordered logic
from cosmos_rl.policy.model.base import WeightMapper
import torch
from cosmos_rl.utils import util
from transformers import AutoConfig
from typing import List, Tuple
import re

class InternVLWeightMapper(WeightMapper):
    def __init__(self, hf_config: AutoConfig):
        super().__init__(hf_config)
        # Compute ratio between query heads and key-value heads
        self.qk_head_ratio = (
            self.config.llm_config.num_attention_heads
            // self.config.llm_config.num_key_value_heads
        )
        # Calculate dimension per attention head
        self.head_size = (
            self.config.llm_config.hidden_size
            // self.config.llm_config.num_attention_heads
        )

    def rollout_map_local_key_to_hf_key(self, local_weight_name: str) -> str:
        if self.backend == "vllm":
            # Reuse policy mapping for vLLM backend
            return self.policy_map_local_key_to_hf_key(local_weight_name)
        elif self.backend == "trtllm":
            # Handle tensorrt-llm specific key transformations
            if local_weight_name.startswith("llm.model."):
                hf_name = local_weight_name.replace("llm.model.", "model.")
            elif local_weight_name.startswith("llm.lm_head."):
                hf_name = local_weight_name.replace("llm.lm_head.", "lm_head.")
            elif local_weight_name.startswith("mm_encoder."):
                hf_name = local_weight_name.replace(".", "visual.")
            else:
                hf_name = local_weight_name
            return hf_name
        else:
            raise ValueError(f"Unsupported backend: {self.backend}")

    def __rollout_split_qkv_weight(self, name: str, weight: torch.Tensor):
        # Visual model QKV splitting
        if "visual" in name:
            # Input shape: [3 * head_dim, hidden_dim]
            assert weight.shape[0] % 3 == 0, (
                "Weight dimensions incompatible for QKV split."
            )
            unit_size = weight.shape[0] // 3
            q_part = weight[:unit_size]
            k_part = weight[unit_size : unit_size * 2]
            v_part = weight[unit_size * 2 :]
            return q_part, k_part, v_part

        # Language model QKV splitting
        total_shares = self.qk_head_ratio + 2
        dim_0 = weight.shape[0]
        unit_size = dim_0 // total_shares

        q_part = weight[: unit_size * self.qk_head_ratio]
        k_part = weight[
            unit_size * self.qk_head_ratio : unit_size * (self.qk_head_ratio + 1)
        ]
        v_part = weight[unit_size * (self.qk_head_ratio + 1) :]
        return q_part, k_part, v_part

    def _split_gate_proj_weight(self, name: str, weight: torch.Tensor):
        # Split gate and up projections (already split in vLLM)
        dim_0 = weight.shape[0]
        gate_weight = weight[: dim_0 // 2]
        up_weight = weight[dim_0 // 2 :]
        return gate_weight, up_weight

    def rollout_split_local_key_n_param_to_hf_key_n_param(
        self, param_name: str, param: torch.Tensor
    ) -> List[Tuple[str, torch.Tensor]]:
        result_keys = []
        mapped_name = self.rollout_map_local_key_to_hf_key(param_name)

        if "qkv_proj" in mapped_name:
            q_w, k_w, v_w = self.__rollout_split_qkv_weight(mapped_name, param)
            q_key = mapped_name.replace("qkv_proj", "q_proj")
            k_key = mapped_name.replace("qkv_proj", "k_proj")
            v_key = mapped_name.replace("qkv_proj", "v_proj")
            result_keys.extend([
                (q_key, q_w),
                (k_key, k_w),
                (v_key, v_w)
            ])
        elif "gate_up_proj" in mapped_name:
            g_w, u_w = self._split_gate_proj_weight(mapped_name, param)
            g_key = mapped_name.replace("gate_up_proj", "gate_proj")
            u_key = mapped_name.replace("gate_up_proj", "up_proj")
            result_keys.extend([
                (g_key, g_w),
                (u_key, u_w)
            ])
        elif "qkv" in mapped_name and "visual" in mapped_name:
            q_w, k_w, v_w = self.__rollout_split_qkv_weight(mapped_name, param)
            q_v_key = mapped_name.replace("qkv", "q")
            k_v_key = mapped_name.replace("qkv", "k")
            v_v_key = mapped_name.replace("qkv", "v")
            result_keys.extend([
                (q_v_key, q_w),
                (k_v_key, k_w),
                (v_v_key, v_w)
            ])
        else:
            result_keys.append((mapped_name, param))

        return result_keys

    def policy_map_local_key_to_hf_key(self, name: str) -> str:
        clean_name = util.clear_weight_name(name)
        if clean_name.startswith("language_model."):
            clean_name = clean_name.replace("language_model.", "")
        if clean_name == "model.lm_head.weight":
            clean_name = "lm_head.weight"
        return clean_name

    def name_to_model_part_index(self, dest_name: str) -> int:
        if dest_name in ["lm_head.weight", "lm_head.bias"]:
            return 0
        elif dest_name.startswith("visual."):
            return 1
        elif dest_name.startswith("model."):
            return 0
        else:
            raise ValueError(f"Unsupported weight: {dest_name}")

    def policy_decompose_param_1_to_n_for_sync(self, name: str):
        # Check for visual blocks QKV pattern
        if match := re.search(  # noqa: F841
            r"visual\.blocks\.(\d+)\.attn\.qkv\.(weight|bias)",
            name,
        ):
            strategy_list = []

            # First component: Q projection
            strategy_list.append(
                (
                    name.replace("qkv", "q"),
                    {0: {"offset": 0, "total_size": 3, "length": 1}},
                )
            )

            # Second component: K projection
            strategy_list.append(
                (
                    name.replace("qkv", "k"),
                    {0: {"offset": 1, "total_size": 3, "length": 1}},
                )
            )

            # Third component: V projection
            strategy_list.append(
                (
                    name.replace("qkv", "v"),
                    {0: {"offset": 2, "total_size": 3, "length": 1}},
                )
            )

            return strategy_list

        return []

