# Health tracker CLI tool using garmer library
import json
import sys
from datetime import date

try:
    from garmer import GarminClient
    from garmer.auth import AuthenticationError
except ImportError:
    print("Error: garmer not installed. Run: pip install garmer", file=sys.stderr)
    sys.exit(1)

def get_garmin_client() -> GarminClient:
    """Establish and return authenticated Garmin client."""
    try:
        return GarminClient.from_saved_tokens()
    except AuthenticationError:
        print("Error: Not authenticated. Run 'garmer login' first.", file=sys.stderr)
        sys.exit(1)

def cmd_health_summary():
    """Display today's health summary."""
    client = get_garmin_client()
    summary = client.get_daily_summary()
    print(f"Date: {date.today()}")
    print(f"Steps: {summary.total_steps:,} / {summary.daily_step_goal:,}")
    print(f"Distance: {summary.total_distance_meters / 1000:.2f} km")
    print(f"Calories: {summary.total_kilocalories:,}")
    if summary.resting_heart_rate:
        print(f"Resting HR: {summary.resting_heart_rate} bpm")
    if summary.avg_stress_level:
        print(f"Avg Stress: {summary.avg_stress_level}")

def cmd_sleep_data():
    """Display sleep statistics."""
    client = get_garmin_client()
    sleep = client.get_sleep()
    if sleep:
        print(f"Total Sleep: {sleep.total_sleep_hours:.1f} hours")
        print(f"Deep Sleep: {sleep.deep_sleep_hours:.1f} hours")
        print(f"REM Sleep: {sleep.rem_sleep_hours:.1f} hours")
        if sleep.overall_score:
            print(f"Sleep Score: {sleep.overall_score}")
        if sleep.avg_hrv:
            print(f"HRV: {sleep.avg_hrv:.1f} ms")
    else:
        print("No sleep data available")

def cmd_recent_activities():
    """Display list of recent physical activities."""
    client = get_garmin_client()
    activities = client.get_recent_activities(limit=5)
    if activities:
        for activity in activities:
            print(f"- {activity.activity_name} ({activity.activity_type_key})")
            print(
                f"  Duration: {activity.duration_minutes:.0f} min, Distance: {activity.distance_km:.2f} km"
            )
    else:
        print("No recent activities")

def cmd_full_snapshot():
    """Print complete health snapshot in JSON format."""
    client = get_garmin_client()
    snapshot = client.get_health_snapshot()
    print(json.dumps(snapshot, indent=2, default=str))

def main():
    if len(sys.argv) < 2:
        print(__doc__)
        sys.exit(0)

    command = sys.argv[1].lower()
    commands_map = {
        "summary": cmd_health_summary,
        "sleep": cmd_sleep_data,
        "activities": cmd_recent_activities,
        "snapshot": cmd_full_snapshot,
    }

    if command in commands_map:
        commands_map[command]()
    else:
        print(f"Unknown command: {command}")
        print(__doc__)
        sys.exit(1)

if __name__ == "__main__":
    main()

import torch.nn as nn

class BottleneckResidual(nn.Module):
    def __init__(self, input_channels, output_channels, normalization="group", stride=1):
        super(BottleneckResidual, self).__init__()
        self.conv_layer1 = nn.Conv2d(input_channels, output_channels // 4, kernel_size=1, padding=0)
        self.conv_layer2 = nn.Conv2d(output_channels // 4, output_channels // 4, kernel_size=3, padding=1, stride=stride)
        self.conv_layer3 = nn.Conv2d(output_channels // 4, output_channels, kernel_size=1, padding=0)
        self.activation = nn.ReLU(inplace=True)
        group_count = output_channels // 8

        if normalization == "group":
            self.norm_layer1 = nn.GroupNorm(num_groups=group_count, num_channels=output_channels // 4)
            self.norm_layer2 = nn.GroupNorm(num_groups=group_count, num_channels=output_channels // 4)
            self.norm_layer3 = nn.GroupNorm(num_groups=group_count, num_channels=output_channels)
            if not stride == 1:
                self.norm_layer4 = nn.GroupNorm(num_groups=group_count, num_channels=output_channels)
        elif normalization == "batch":
            self.norm_layer1 = nn.BatchNorm2d(output_channels // 4)
            self.norm_layer2 = nn.BatchNorm2d(output_channels // 4)
            self.norm_layer3 = nn.BatchNorm2d(output_channels)
            if not stride == 1:
                self.norm_layer4 = nn.BatchNorm2d(output_channels)
        elif normalization == "instance":
            self.norm_layer1 = nn.InstanceNorm2d(output_channels // 4)
            self.norm_layer2 = nn.InstanceNorm2d(output_channels // 4)
            self.norm_layer3 = nn.InstanceNorm2d(output_channels)
            if not stride == 1:
                self.norm_layer4 = nn.InstanceNorm2d(output_channels)
        elif normalization == "none":
            self.norm_layer1 = nn.Sequential()
            self.norm_layer2 = nn.Sequential()
            self.norm_layer3 = nn.Sequential()
            if not stride == 1:
                self.norm_layer4 = nn.Sequential()

        if stride == 1:
            self.shortcut = None
        else:
            self.shortcut = nn.Sequential(
                nn.Conv2d(input_channels, output_channels, kernel_size=1, stride=stride), 
                self.norm_layer4
            )

    def forward(self, input_tensor):
        residual = input_tensor
        out = self.activation(self.norm_layer1(self.conv_layer1(residual)))
        out = self.activation(self.norm_layer2(self.conv_layer2(out)))
        out = self.activation(self.norm_layer3(self.conv_layer3(out)))

        if self.shortcut is not None:
            residual = self.shortcut(residual)

        return self.activation(residual + out)


class SimpleResidual(nn.Module):
    def __init__(self, input_channels, output_channels, normalization="group", stride=1):
        super(SimpleResidual, self).__init__()
        self.conv_first = nn.Conv2d(input_channels, output_channels, kernel_size=3, padding=1, stride=stride)
        self.conv_second = nn.Conv2d(output_channels, output_channels, kernel_size=3, padding=1)
        self.activation = nn.ReLU(inplace=True)
        group_count = output_channels // 8

        if normalization == "group":
            self.norm_first = nn.GroupNorm(num_groups=group_count, num_channels=output_channels)
            self.norm_second = nn.GroupNorm(num_groups=group_count, num_channels=output_channels)
            if not stride == 1:
                self.norm_third = nn.GroupNorm(num_groups=group_count, num_channels=output_channels)
        elif normalization == "batch":
            self.norm_first = nn.BatchNorm2d(output_channels)
            self.norm_second = nn.BatchNorm2d(output_channels)
            if not stride == 1:
                self.norm_third = nn.BatchNorm2d(output_channels)
        elif normalization == "instance":
            self.norm_first = nn.InstanceNorm2d(output_channels)
            self.norm_second = nn.InstanceNorm2d(output_channels)
            if not stride == 1:
                self.norm_third = nn.InstanceNorm2d(output_channels)
        elif normalization == "none":
            self.norm_first = nn.Sequential()
            self.norm_second = nn.Sequential()
            if not stride == 1:
                self.norm_third = nn.Sequential()

        if stride == 1:
            self.shortcut = None
        else:
            self.shortcut = nn.Sequential(
                nn.Conv2d(input_channels, output_channels, kernel_size=1, stride=stride), 
                self.norm_third
            )

    def forward(self, input_tensor):
        residual = input_tensor
        out = self.activation(self.norm_first(self.conv_first(residual)))
        out = self.activation(self.norm_second(self.conv_second(out)))

        if self.shortcut is not None:
            residual = self.shortcut(residual)

        return self.activation(residual + out)


class MiniEncoder(nn.Module):
    def __init__(self, feature_dim=128, normalization="batch", dropout_rate=0.0):
        super(MiniEncoder, self).__init__()
        self.normalization_type = normalization

        if self.normalization_type == "group":
            self.input_norm = nn.GroupNorm(num_groups=8, num_channels=32)
        elif self.normalization_type == "batch":
            self.input_norm = nn.BatchNorm2d(32)
        elif self.normalization_type == "instance":
            self.input_norm = nn.InstanceNorm2d(32)
        elif self.normalization_type == "none":
            self.input_norm = nn.Sequential()

        self.stem_conv = nn.Conv2d(3, 32, kernel_size=7, stride=2, padding=3)
        self.stem_activation = nn.ReLU(inplace=True)
        self.current_planes = 32

        self.stage1 = self._build_stage(32, stride=1)
        self.stage2 = self._build_stage(64, stride=2)
        self.stage3 = self._build_stage(96, stride=2)

        self.dropout_layer = None
        if dropout_rate > 0:
            self.dropout_layer = nn.Dropout2d(p=dropout_rate)

        self.final_conv = nn.Conv2d(96, feature_dim, kernel_size=1)

        # Weight initialization
        for module in self.modules():
            if isinstance(module, nn.Conv2d):
                nn.init.kaiming_normal_(module.weight, mode="fan_out", nonlinearity="relu")
            elif isinstance(module, (nn.BatchNorm2d, nn.InstanceNorm2d, nn.GroupNorm)):
                if module.weight is not None:
                    nn.init.constant_(module.weight, 1)
                if module.bias is not None:
                    nn.init.constant_(module.bias, 0)

    def _build_stage(self, planes, stride=1):
        block1 = BottleneckResidual(self.current_planes, planes, self.normalization_type, stride=stride)
        block2 = BottleneckResidual(planes, planes, self.normalization_type, stride=1)
        layers = (block1, block2)
        self.current_planes = planes
        return nn.Sequential(*layers)

    def forward(self, x):
        is_list_input = isinstance(x, tuple) or isinstance(x, list)
        if is_list_input:
            batch_size = x[0].shape[0]
            x = torch.cat(x, dim=0)

        x = self.stem_conv(x)
        x = self.input_norm(x)
        x = self.stem_activation(x)
        x = self.stage1(x)
        x = self.stage2(x)
        x = self.stage3(x)
        x = self.final_conv(x)

        if self.training and self.dropout_layer is not None:
            x = self.dropout_layer(x)

        if is_list_input:
            x = torch.split(x, [batch_size, batch_size], dim=0)

        return x


class StandardEncoder(nn.Module):
    def __init__(self, feature_dim=128, normalization="batch", dropout_rate=0.0):
        super(StandardEncoder, self).__init__()
        self.normalization_type = normalization

        if self.normalization_type == "group":
            self.input_norm = nn.GroupNorm(num_groups=8, num_channels=64)
        elif self.normalization_type == "batch":
            self.input_norm = nn.BatchNorm2d(64)
        elif self.normalization_type == "instance":
            self.input_norm = nn.InstanceNorm2d(64)
        elif self.normalization_type == "none":
            self.input_norm = nn.Sequential()

        self.stem_conv = nn.Conv2d(3, 64, kernel_size=7, stride=2, padding=3)
        self.stem_activation = nn.ReLU(inplace=True)
        self.current_planes = 64

        self.stage1 = self._build_stage(64, stride=1)
        self.stage2 = self._build_stage(72, stride=2)
        self.stage3 = self._build_stage(128, stride=2)

        self.output_conv = nn.Conv2d(128, feature_dim, kernel_size=1)

        self.dropout_layer = None
        if dropout_rate > 0:
            self.dropout_layer = nn.Dropout2d(p=dropout_rate)

        # Weight initialization
        for module in self.modules():
            if isinstance(module, nn.Conv2d):
                nn.init.kaiming_normal_(module.weight, mode="fan_out", nonlinearity="relu")
            elif isinstance(module, (nn.BatchNorm2d, nn.InstanceNorm2d, nn.GroupNorm)):
                if module.weight is not None:
                    nn.init.constant_(module.weight, 1)
                if module.bias is not None:
                    nn.init.constant_(module.bias, 0)

    def _build_stage(self, planes, stride=1):
        block1 = SimpleResidual(self.current_planes, planes, self.normalization_type, stride=stride)
        block2 = SimpleResidual(planes, planes, self.normalization_type, stride=1)
        layers = (block1, block2)
        self.current_planes = planes
        return nn.Sequential(*layers)

