# Customized filter set for KnowledgeGraph model
from django_filters import filters
from django_filters.rest_framework import FilterSet
from rest_framework.decorators import action
from apps.core.decorators.api_permission import HasPermission
from apps.core.utils.viewset_utils import MaintainerViewSet
from apps.opspilot.models import KnowledgeGraph
from apps.opspilot.serializers.knowledge_graph_serializers import KnowledgeGraphSerializer
from apps.opspilot.tasks import rebuild_graph_community_by_instance
from apps.opspilot.utils.graph_utils import GraphUtils

class KnowledgeGraphFilter(FilterSet):
    title = filters.CharFilter(field_name="name", lookup_expr="icontains")
    base_id = filters.NumberFilter(field_name="knowledge_base_id", lookup_expr="exact")

class KnowledgeGraphViewSet(MaintainerViewSet):
    queryset = KnowledgeGraph.objects.all()
    serializer_class = KnowledgeGraphSerializer
    filterset_class = KnowledgeGraphFilter
    ordering = ("-id",)

    @action(methods=["GET"], detail=False)
    @HasPermission("knowledge_document-View")
    def get_details(self, request):
        kb_id = request.query_params.get("knowledge_base_id")
        record = KnowledgeGraph.objects.filter(knowledge_base_id=kb_id).first()
        if not record:
            return JsonResponse({"result": True, "data": {"is_exists": False}})
        if record.status == "pending":
            return JsonResponse(
                {
                    "result": True,
                    "data": {
                        "graph": {},
                        "graph_id": record.id,
                        "is_exists": True,
                        "status": record.status,
                    },
                }
            )
        response_data = GraphUtils.get_graph(record.id)
        if not response_data["result"]:
            return JsonResponse(response_data)
        result_dict = {
            "graph": response_data["data"],
            "graph_id": record.id,
            "status": record.status,
            "is_exists": True,
        }
        return JsonResponse({"result": True, "data": result_dict})

    @action(methods=["POST"], detail=False)
    @HasPermission("knowledge_document-Delete")
    def delete_graph(self, request):
        instance = KnowledgeGraph.objects.get(knowledge_base_id=request.data.get("knowledge_base_id"))
        if instance.status == "training":
            return JsonResponse(
                {
                    "result": False,
                    "message": "Knowledge graph is training, cannot delete",
                }
            )
        try:
            GraphUtils.delete_graph(instance)
        except Exception as e:
            return JsonResponse({"result": False, "message": str(e)}, status=500)
        instance.delete()
        return JsonResponse({"result": True})

    @action(methods=["POST"], detail=False)
    @HasPermission("knowledge_document-Train, knowledge_document-Set")
    def rebuild_graph_community(self, request):
        kb_id = request.data.get("knowledge_base_id")
        graph_record = KnowledgeGraph.objects.filter(knowledge_base_id=kb_id).first()
        if graph_record.status != "completed":
            return JsonResponse({"result": False, "message": "Knowledge graph is not completed"})
        if not graph_record:
            return JsonResponse({"result": False, "message": "Knowledge graph not found"})
        try:
            rebuild_graph_community_by_instance.delay(graph_record.id)
            return JsonResponse({"result": True})
        except Exception as e:
            return JsonResponse({"result": False, "message": str(e)})

import logging
import pprint
import sys
from typing import Any

def create_logger(module_name: str) -> logging.Logger:
    """
    Retrieve or instantiate a logger with standardized formatting.
    Args:
        module_name: Logger identifier (commonly __name__ from the caller)
    Returns:
        Initialized logger object
    """
    log_instance = logging.getLogger(module_name)
    # Setup only if not previously configured
    if not log_instance.handlers:
        log_instance.setLevel(logging.DEBUG)
        # Initialize stdout handler
        console_handler = logging.StreamHandler(sys.stdout)
        console_handler.setLevel(logging.INFO)
        # Define log format
        log_format = logging.Formatter(
            fmt="(ComfyUI-vLLM-Omni) [%(levelname)s] %(asctime)s [%(filename)s:%(lineno)s] %(message)s",
            datefmt="%Y-%m-%d %H:%M:%S",
        )
        console_handler.setFormatter(log_format)
        # Attach handler to logger
        log_instance.addHandler(console_handler)
        # Disable upward propagation
        log_instance.propagate = False
    return log_instance

class SecurePrettyPrinter(pprint.PrettyPrinter):
    """
    Custom PrettyPrinter that masks sensitive fields like 'data' and 'url'
    by replacing their contents with placeholders when appropriate.
    """
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)

    def _format(self, obj: Any, stream, indent: int, allowance: int, context, level: int) -> None:
        # Process dictionaries for redaction
        if isinstance(obj, dict):
            secure_obj = {}
            for key, value in obj.items():
                if key in ("data", "url"):
                    if isinstance(value, str):
                        if value.startswith("data:"):
                            header = value.split(",", 1)[0]
                            secure_obj[key] = f"{header},***"
                        elif value.startswith(("http://", "https://")):
                            secure_obj[key] = value
                        elif len(value) > 10:
                            secure_obj[key] = f"{value[:10]}***"
                        else:
                            secure_obj[key] = value
                    else:
                        secure_obj[key] = value
                else:
                    secure_obj[key] = value
            obj = secure_obj
        # Let parent handle remaining types recursively
        super()._format(obj, stream, indent, allowance, context, level)

# Instantiate custom printer
