# Custom multiprocessing worker and vectorized environment for Robocasa
from multiprocessing import Pipe, connection
from multiprocessing.context import Process
from typing import Any, Callable, Optional, Union
import gymnasium as gym
import numpy as np
from rlinf.envs.venv import (
    BaseVectorEnv,
    CloudpickleWrapper,
    EnvWorker,
    ShArray,
    SubprocEnvWorker,
    SubprocVectorEnv,
    _setup_buf,
)

def _remote_worker(
    parent_conn: connection.Connection,
    child_conn: connection.Connection,
    env_factory: CloudpickleWrapper,
    shared_buffers: Optional[Union[dict, tuple, ShArray]] = None,
) -> None:
    """Multiprocess worker for handling robocasa environments.
    Derived from metaworld's approach, modified for robosuite compatibility.
    """
    def _store_observations(
        observation: Union[dict, tuple, np.ndarray], 
        memory_buffer: Union[dict, tuple, ShArray]
    ) -> None:
        if isinstance(observation, np.ndarray) and isinstance(memory_buffer, ShArray):
            memory_buffer.save(observation)
        elif isinstance(observation, tuple) and isinstance(memory_buffer, tuple):
            for obs_item, buf_item in zip(observation, memory_buffer):
                _store_observations(obs_item, buf_item)
        elif isinstance(observation, dict) and isinstance(memory_buffer, dict):
            for key in observation.keys():
                _store_observations(observation[key], memory_buffer[key])
        return None

    parent_conn.close()
    env = env_factory.data()
    try:
        while True:
            try:
                message_type, payload = child_conn.recv()
            except EOFError:
                child_conn.close()
                break

            if message_type == "step":
                result = env.step(payload)
                if shared_buffers is not None:
                    _store_observations(result[0], shared_buffers)
                    result = (None, *result[1:])
                child_conn.send(result)

            elif message_type == "reset":
                output = env.reset(**payload)
                has_info_output = (
                    isinstance(output, (tuple, list))
                    and len(output) == 2
                    and isinstance(output[1], dict)
                )
                if has_info_output:
                    obs_data, info_dict = output
                else:
                    obs_data = output

                if shared_buffers is not None:
                    _store_observations(obs_data, shared_buffers)
                    obs_data = None

                if has_info_output:
                    child_conn.send((obs_data, info_dict))
                else:
                    child_conn.send(obs_data)

            elif message_type == "close":
                child_conn.send(env.close())
                child_conn.close()
                break

            elif message_type == "render":
                child_conn.send(env.render(**payload) if hasattr(env, "render") else None)

            elif message_type == "seed":
                if hasattr(env, "seed"):
                    child_conn.send(env.seed(payload))
                else:
                    env.reset(seed=payload)
                    child_conn.send(None)

            elif message_type == "getattr":
                child_conn.send(getattr(env, payload) if hasattr(env, payload) else None)

            elif message_type == "setattr":
                setattr(env.unwrapped, payload["key"], payload["value"])

            else:
                child_conn.close()
                raise NotImplementedError(f"Unknown command received: {message_type}")

    except KeyboardInterrupt:
        child_conn.close()

class RobocasaSubprocWorker(SubprocEnvWorker):
    """Custom subprocess worker implementation for Robocasa environments.
    Based on metaworld's ReconfigureSubprocEnvWorker but without reconfiguration support.
    """
    def __init__(self, env_creator: Callable[[], gym.Env], use_shared_memory: bool = False):
        self.parent_pipe, self.child_pipe = Pipe()
        self.use_shared_memory = use_shared_memory
        self.memory_region: Optional[Union[dict, tuple, ShArray]] = None

        if self.use_shared_memory:
            test_env = env_creator()
            observation_space = test_env.observation_space
            test_env.close()
            del test_env
            self.memory_region = _setup_buf(observation_space)

        worker_args = (
            self.parent_pipe,
            self.child_pipe,
            CloudpickleWrapper(env_creator),
            self.memory_region,
        )

        # Launch process with custom worker function
        self.worker_process = Process(target=_remote_worker, args=worker_args, daemon=True)
        self.worker_process.start()
        self.child_pipe.close()
        EnvWorker.__init__(self, env_creator)

class RobocasaVectorizedEnv(SubprocVectorEnv):
    """Vectorized subprocess environment for Robocasa/Robosuite simulations.
    Implements subprocess isolation to prevent OpenGL context conflicts in MuJoCo.
    """
    def __init__(self, env_constructors: list[Callable[[], gym.Env]], **kwargs: Any) -> None:
        def create_worker(env_fn: Callable[[], gym.Env]) -> RobocasaSubprocWorker:
            # Instantiate worker with shared memory disabled by default
            # Dict observations perform better without shared memory
            return RobocasaSubprocWorker(env_fn, use_shared_memory=False)

        BaseVectorEnv.__init__(self, env_constructors, create_worker, **kwargs)

