    entry: Tuple[str, ...],
    info: Tuple[str, ...],
) -> str:
    """Convert a legacy installed-files.txt path into modern RECORD path."""
    while entry and entry[0] == "..":
        if not info or info[-1] == "..":
            info += ("..",)
