    ]

    for file_path in filtered_files:
        tester_classes = get_tester_classes(file_path)
        for cls in tester_classes:
            # Handle cases where tester classes don't accept `parent` parameter
            try:
                instance = cls(parent=None)
            except Exception:
                continue

            if hasattr(instance, "get_config"):
                config_obj = instance.get_config()
                config_dict = config_obj.to_dict()

                for key, value in config_dict.items():
                    if isinstance(value, int):
                        limit_value = None

