# Modified version of the original code with renamed variables, literals, and reordering
import logging
import optparse
import shutil
import sys
import textwrap
from contextlib import suppress
from typing import Any, Dict, Generator, List, Tuple
from pip._internal.cli.status_codes import UNKNOWN_ERROR
from pip._internal.configuration import Configuration, ConfigurationError
from pip._internal.utils.misc import redact_auth_from_url, strtobool

logger = logging.getLogger(__name__)

class PrettyHelpFormatter(optparse.IndentedHelpFormatter):
    """A prettier/less verbose help formatter for optparse."""

    def __init__(self, *args: Any, **kwargs: Any) -> None:
        # Align help position with parser description
        kwargs["max_help_position"] = 30
        kwargs["indent_increment"] = 1
        term_width, _ = shutil.get_terminal_size()
        kwargs["width"] = term_width - 2
        super().__init__(*args, **kwargs)

    def format_option_strings(self, option: optparse.Option) -> str:
        return self._format_option_strings(option)

    def _format_option_strings(
        self, option: optparse.Option, metavar_fmt: str = " <{}>", separator: str = ", "
    ) -> str:
        """
        Return a comma-separated list of option strings and metavars.
        :param option:  tuple of (short opt, long opt), e.g: ('-f', '--format')
        :param metavar_fmt: metavar format string
        :param separator:  separator
        """
        opts = []
        if option._short_opts:
            opts.append(option._short_opts[0])
        if option._long_opts:
            opts.append(option._long_opts[0])
        if len(opts) > 1:
            opts.insert(1, separator)
        if option.takes_value():
            assert option.dest is not None
            metavar = option.metavar or option.dest.lower()
            opts.append(metavar_fmt.format(metavar.lower()))
        return "".join(opts)

    def format_heading(self, heading: str) -> str:
        if heading == "Options":
            return ""
        return heading + ":\n"

    def format_usage(self, usage: str) -> str:
        """
        Ensure there is only one newline between usage and the first heading
        if there is no description.
        """
        msg = "\nUsage: {}\n".format(self.indent_lines(textwrap.dedent(usage), "  "))
        return msg

    def format_description(self, description: str) -> str:
        # leave full control over description to us
        if description:
            if hasattr(self.parser, "main"):
                label = "Commands"
            else:
                label = "Description"
            # some doc strings have initial newlines, some don't
            description = description.lstrip("\n")
            # some doc strings have final newlines and spaces, some don't
            description = description.rstrip()
            # dedent, then reindent
            description = self.indent_lines(textwrap.dedent(description), "  ")
            description = f"{label}:\n{description}\n"
            return description
        else:
            return ""

    def format_epilog(self, epilog: str) -> str:
        # leave full control over epilog to us
        if epilog:
            return epilog
        else:
            return ""

    def indent_lines(self, text: str, indent: str) -> str:
        lines_list = [indent + line for line in text.split("\n")]
        return "\n".join(lines_list)

class UpdatingDefaultsHelpFormatter(PrettyHelpFormatter):
    """Custom help formatter for use in ConfigOptionParser.
    This is updates the defaults before expanding them, allowing
    them to show up correctly in the help listing.
    Also redact auth from url type options
    """

    def expand_default(self, option: optparse.Option) -> str:
        default_vals = None
        if self.parser is not None:
            assert isinstance(self.parser, ConfigOptionParser)
            self.parser._update_defaults(self.parser.defaults)
            assert option.dest is not None
            default_vals = self.parser.defaults.get(option.dest)
        help_text = super().expand_default(option)
        if default_vals and option.metavar == "URL":
            if isinstance(default_vals, str):
                default_vals = [default_vals]
            # If its not a list, we should abort and just return the help text
            if not isinstance(default_vals, list):
                default_vals = []
            for val in default_vals:
                help_text = help_text.replace(val, redact_auth_from_url(val))
        return help_text

class CustomOptionParser(optparse.OptionParser):
    def insert_option_group(
        self, idx: int, *args: Any, **kwargs: Any
    ) -> optparse.OptionGroup:
        """Insert an OptionGroup at a given position."""
        group = self.add_option_group(*args, **kwargs)
        self.option_groups.pop()
        self.option_groups.insert(idx, group)
        return group

    @property
    def option_list_all(self) -> List[optparse.Option]:
        """Get a list of all options, including those in option groups."""
        res = self.option_list[:]
        for grp in self.option_groups:
            res.extend(grp.option_list)
        return res

class ConfigOptionParser(CustomOptionParser):
    """Custom option parser which updates its defaults by checking the
    configuration files and environmental variables"""

    def __init__(
        self,
        *args: Any,
        cmd_name: str,
        isolated: bool = False,
        **kwargs: Any,
    ) -> None:
        self.cmd_name = cmd_name
        self.config = Configuration(isolated)
        assert self.cmd_name
        super().__init__(*args, **kwargs)

    def check_default(self, option: optparse.Option, key: str, val: Any) -> Any:
        try:
            return option.check_value(key, val)
        except optparse.OptionValueError as exc:
            print(f"An error occurred during configuration: {exc}")
            sys.exit(3)

    def _get_ordered_configuration_items(
        self,
    ) -> Generator[Tuple[str, Any], None, None]:
        # Configuration gives keys in an unordered manner. Order them.
        priority_order = ["global", self.cmd_name, ":env:"]
        # Pool the options into different groups
        section_data: Dict[str, List[Tuple[str, Any]]] = {
            name: [] for name in priority_order
        }
        for section_key, val in self.config.items():
            # ignore empty values
            if not val:
                logger.debug(
                    "Ignoring configuration key '%s' as it's value is empty.",
                    section_key,
                )
                continue
            section, key = section_key.split(".", 1)
            if section in priority_order:
                section_data[section].append((key, val))
        # Yield each group in their priority order
        for section in priority_order:
            for key, val in section_data[section]:
                yield key, val

    def _update_defaults(self, defaults: Dict[str, Any]) -> Dict[str, Any]:
        """Updates the given defaults with values from the config files and
        the environ. Does a little special handling for certain types of
        options (lists)."""
        # Accumulate complex default state.
        self.values = optparse.Values(self.defaults)
        late_eval = set()
        # Then set the options with those values
        for key, val in self._get_ordered_configuration_items():
            # '--' because configuration supports only long names
            option = self.get_option("--" + key)
            # Ignore options not present in this parser. E.g. non-globals put
            # in [global] by users that want them to apply to all applicable
            # commands.
            if option is None:
                continue
            assert option.dest is not None
            if option.action in ("store_true", "store_false"):
                try:
                    val = strtobool(val)
                except ValueError:
                    self.error(
                        f"{val} is not a valid value for {key} option, "
                        "please specify a boolean value like yes/no, "
                        "true/false or 1/0 instead."
                    )
            elif option.action == "count":
                with suppress(ValueError):
                    val = strtobool(val)
                with suppress(ValueError):
                    val = int(val)
                if not isinstance(val, int) or val < 0:
                    self.error(
                        f"{val} is not a valid value for {key} option, "
                        "please instead specify either a non-negative integer "
                        "or a boolean value like yes/no or false/true "
                        "which is equivalent to 1/0."
                    )
            elif option.action == "append":
                val = val.split()
                val = [self.check_default(option, key, v) for v in val]
            elif option.action == "callback":
                assert option.callback is not None
                late_eval.add(option.dest)
                opt_str = option.get_opt_string()
                val = option.convert_value(opt_str, val)
                # From take_action
                args = option.callback_args or ()
                kwargs = option.callback_kwargs or {}
                option.callback(option, opt_str, val, self, *args, **kwargs)
            else:
                val = self.check_default(option, key, val)
            defaults[option.dest] = val
        for key in late_eval:
            defaults[key] = getattr(self.values, key)
        self.values = None
        return defaults

    def get_default_values(self) -> optparse.Values:
        """Overriding to make updating the defaults after instantiation of
        the option parser possible, _update_defaults() does the dirty work."""
        if not self.process_default_values:
            # Old, pre-Optik 1.5 behaviour.
            return optparse.Values(self.defaults)
        # Load the configuration, or error out in case of an error
        try:
            self.config.load()
        except ConfigurationError as err:
            self.exit(UNKNOWN_ERROR, str(err))
        defaults = self._update_defaults(self.defaults.copy())  # ours
        for option in self._get_all_options():
            assert option.dest is not None
            default_val = defaults.get(option.dest)
            if isinstance(default_val, str):
                opt_str = option.get_opt_string()
                defaults[option.dest] = option.check_value(opt_str, default_val)
        return optparse.Values(defaults)

    def error(self, msg: str) -> None:
        self.print_usage(sys.stderr)
        self.exit(UNKNOWN_ERROR, f"{msg}\n")

# Dynamically load provider clients based on protocol type
from __future__ import annotations
import importlib
from typing import Optional, TYPE_CHECKING, Type, cast
from ripperdoc.core.config import ProtocolType
from ripperdoc.core.providers.base import ProviderClient
from ripperdoc.utils.log import get_logger

if TYPE_CHECKING:  # pragma: no cover - type checking only
    from ripperdoc.core.providers.anthropic import AnthropicClient  # noqa: F401
    from ripperdoc.core.providers.gemini import GeminiClient  # noqa: F401
    from ripperdoc.core.providers.openai import OpenAIClient  # noqa: F401

logger = get_logger()

def _fetch_provider_client(module_name: str, class_name: str, extra_group: str) -> Type[ProviderClient]:
    """Dynamically import a provider client class, guiding users to install required extras."""
    try:
        module = importlib.import_module(f"ripperdoc.core.providers.{module_name}")
        client_class = cast(Type[ProviderClient], getattr(module, class_name, None))
        if client_class is None:
            raise ImportError(f"{class_name} not found in {module_name}")
        return client_class
    except ImportError as error:
        raise RuntimeError(
            f"{class_name} requires optional dependency group '{extra_group}'. "
            f"Install with `pip install ripperdoc[{extra_group}]`."
        ) from error

def get_client_for_protocol(protocol: ProtocolType) -> Optional[ProviderClient]:
    """Instantiate and return a provider client corresponding to the given protocol."""
    if protocol == ProtocolType.ANTHROPIC:
        return _fetch_provider_client("anthropic", "AnthropicClient", "anthropic")()
    if protocol == ProtocolType.OPENAI_COMPATIBLE:
        return _fetch_provider_client("openai", "OpenAIClient", "openai")()
    if protocol == ProtocolType.GEMINI:
        return _fetch_provider_client("gemini", "GeminiClient", "gemini")()
    if protocol == ProtocolType.OAUTH:
        return _fetch_provider_client("openai", "OpenAIClient", "openai")()

    logger.warning("[providers] Unsupported protocol", extra={"protocol": protocol})
    return None

__all__ = ["ProviderClient", "get_client_for_protocol"]

