from __future__ import annotations
import dataclasses
import torch
from weathergen.model.engines import LatentState

StreamID = str

@dataclasses.dataclass
class TargetAndAuxiliaryResult:
    """
    A dataclass to encapsulate the TargetAndAuxCalculator output and give a clear API.
    """
    selected_indices: list[int]
    physical_data: list[dict[StreamID, torch.Tensor]]
    latent_data: list[dict[str, torch.Tensor | LatentState]]
    auxiliary_results: dict[str, torch.Tensor]

    def __init__(self, num_targets: int, indices: list[int]) -> None:
        self.selected_indices = indices
        self.physical_data = [{} for _ in range(num_targets)]
        self.latent_data = [{} for _ in range(num_targets)]
        self.auxiliary_results = {}

    def append_physical_target(
        self, time_idx: int, stream_id: StreamID, value: torch.Tensor
    ) -> None:
        self.physical_data[time_idx][stream_id] = value

    def append_latent_target(self, time_idx: int, latent_key: str, value: torch.Tensor) -> None:
        self.latent_data[time_idx][latent_key] = value

    def retrieve_physical_target(
        self,
        time_idx: int,
        stream_id: StreamID | None = None,
        sample_id: int | None = None,
    ):
        pred = self.physical_data[time_idx]
        if stream_id is not None:
            pred = pred.get(stream_id, None)
            if sample_id is not None:
                assert sample_id < len(pred), "Invalid sample index."
                pred = pred[sample_id]
        return pred

    def retrieve_latent_target(self, time_idx: int):
        return self.latent_data[time_idx]


