    def update_state_post_opt_step(self, step_idx, batch_data, model_instance, **kwargs) -> None:
        pass

    def compute(self, step_idx, batch_data, *args, **kwargs) -> TargetAndAuxiliaryResult:
        pass

    def to_device(self, device) -> BaseTargetAndAuxiliaryModule:
