class PhysicalTargetAndAuxiliary(BaseTargetAndAuxiliaryModule):
    def __init__(self, config, model_instance, **kwargs):
        return

    def reset(self):
        return

    def update_state_pre_backward(self, step_idx, batch_data, model_instance, **kwargs):
        return

    def update_state_post_opt_step(self, step_idx, batch_data, model_instance, **kwargs):
        return

    def compute(self, batch_idx, batch_data, model_hyperparams, model_instance) -> TargetAndAuxiliaryResult:
        # TODO: properly retrieve/define these
        stream_ids = [k for k, _ in batch_data.samples[0].streams_data.items()]
        selected_indices = batch_data.get_output_idxs()
        assert len(selected_indices) > 0
        result = TargetAndAuxiliaryResult(batch_data.get_output_len(), selected_indices)

        # collect all targets, concatenating across batch dimension since this is also how it
        # happens for predictions in the model
        for stream_id in stream_ids:
            # collect targets for all forecast steps
            for step in selected_indices:
                targets_list, target_times_list, target_coords_list, metadata_list = [], [], [], []
                is_spoof_flag, inverse_indices = [], []
                for sample in batch_data.samples:
                    targets_list += [sample.streams_data[stream_id].target_tokens[step]]
                    target_times_list += [sample.streams_data[stream_id].target_times_raw[step]]
                    target_coords_list += [sample.streams_data[stream_id].target_coords_raw[step]]
                    inverse_indices += [sample.streams_data[stream_id].idxs_inv[step]]
                    metadata_list += [sample.meta_info]
                    is_spoof_flag += [sample.streams_data[stream_id].is_spoof()]

                targets_step_dict = {
                    "target": targets_list,
                    "target_times": target_times_list,
                    "target_coords": target_coords_list,
                    "target_metadata": metadata_list,
                    "is_spoof": is_spoof_flag,
                    "idxs_inv": inverse_indices,
                }
                result.append_physical_target(step, stream_id, targets_step_dict)

        return result

    def to_device(self, device) -> PhysicalTargetAndAuxiliary:
        return self

# Import necessary modules for subprocess and threading operations
import subprocess
from subprocess import Popen
from threading import Event, Thread

def terminate_threads(thread_list: list[Thread]):
    """Terminate and clean up a collection of threads"""
    for t in thread_list:
        t.join(timeout=5)

def terminate_subprocesses(proc_list: list[Popen]):
    """Clean up a collection of subprocesses by terminating or killing them"""
    for proc in proc_list:
        if proc.poll() is None:
            proc.terminate()
            try:
                proc.wait(timeout=60)
            except subprocess.TimeoutExpired:
                proc.kill()

def watch_subprocess(proc: Popen, termination_flag: Event, error_buffer: list, name: str):
    """Observe a subprocess and report failures through a shared error buffer."""
    proc.wait()
    if proc.returncode != 0:
        msg = f"{name.capitalize()} failed with exit code {proc.returncode}"
        if proc.stderr:
            msg += f"\n{proc.stderr.read().decode('utf-8')}"
        error_buffer.append(RuntimeError(msg))
    termination_flag.set()

# Classes storing data for color highlighting using `rich.Highlighter`
# regex-based detection, as well as recognizing entities in email headers, etc.
"""
import json
import re
from abc import ABC
from dataclasses import dataclass, field
from epstein_files.people.contact import Contact
from epstein_files.people.names import Name, constantize_name
from epstein_files.util.constant.strings import REGEX_STYLE_PREFIX
from epstein_files.util.helpers.data_helpers import without_falsey
from epstein_files.util.helpers.string_helper import as_pattern, capture_group_marker
from epstein_files.util.logging import logger

@dataclass(kw_only=True)
class HighlightGroup(ABC):
    """
    Regex and style metadata for items to be highlighted.
    Attributes:
        label (str): RegexHighlighter match group identifier
        regex (re.Pattern): compiled pattern used to detect matching strings
        style (str): Rich style applied to matched text
        theme_style_name (str): style name required in rich.Console's theme
    """
    label: str = ''
    regex: re.Pattern = field(init=False)
    style: str
    theme_style_name: str = field(init=False)
    _capture_group_label: str = field(init=False)
    _capture_group_marker: str = field(init=False)

    def __post_init__(self):
        if not self.label:
            raise ValueError(f'Missing label for {self}')
        self._capture_group_label = self.label.lower().replace(' ', '_').replace('-', '_')
        self._capture_group_marker = capture_group_marker(self._capture_group_label)
        self.theme_style_name = f"{REGEX_STYLE_PREFIX}.{self._capture_group_label}"


@dataclass(kw_only=True)
class HighlightPatterns(HighlightGroup):
    """
    Color highlighting for non-name entities (e.g., phone numbers, email headers).
    Attributes:
        patterns (list[str]): raw regex patterns identifying target strings
        regex_flags (re.RegexFlag): flags used during pattern compilation
        use_word_boundary (bool, optional): if True, restrict matches to word boundaries `\b`
    """
    patterns: list[str] = field(default_factory=list)
    regex_flags: re.RegexFlag = re.IGNORECASE | re.MULTILINE
    use_word_boundary: bool = False
    _pattern: str = field(init=False)

    def __post_init__(self):
        super().__post_init__()
        if not self.label:
            raise ValueError(f"No label provided for {repr(self)}")
        self.patterns = [as_pattern(p) for p in self.patterns]
        self._pattern = '|'.join(self.patterns)
        if self.use_word_boundary:
            self._pattern = fr"\b(({self._pattern})s?)\b"
        self.regex = self.compile_patterns(self._pattern)

    def __repr__(self) -> str:
        return f"{type(self).__name__}(label='{self.label}', pattern='{self._pattern}', style='{self.style}')"

    def compile_patterns(self, pattern: str) -> re.Pattern:
        try:
            return re.compile(fr"({self._capture_group_marker}{pattern})", self.regex_flags)
        except Exception as e:
            logger.error(f"Failed to compile regex '{pattern}'\n\nTrying each piece individually...")
            for p in self.patterns:
                logger.warning(f"Attempting to compile '{p}'...")
                re.compile(p)
            raise e


@dataclass(kw_only=True)
class HighlightedNames(HighlightPatterns):
    """
    Encapsulates data about people, locations, and other strings to highlight via RegexHighlighter.
    Constructor requires either 'emailers' or 'pattern' (or both).
    Attributes:
        category (str): optional override for self.label in certain contexts
        contacts (list[Contact]): optional Contact objects with names and regexes
        contacts_lookup (dict[Name, Contact]): mapping from Name to Contact
        should_match_first_last_name (bool): if False, skip first/last/reversed name variants
    """
    category: str = ''
    contacts: list[Contact] = field(default_factory=list)
    contacts_lookup: dict[Name, Contact] = field(default_factory=dict)
    flags: re.RegexFlag = re.IGNORECASE
    should_match_first_last_name: bool = True  # TODO: this no longer does anything?

    def __post_init__(self):
        if not (self.patterns or self.contacts):
            raise ValueError(f"Must provide either 'contacts' or 'patterns' arg.")
        elif not self.label:
            if len(self.contacts) == 1 and self.contacts[0].name:
                self.label = self.contacts[0].name
            else:
                raise ValueError(f"No label provided for {repr(self)}")

        super().__post_init__()
        with_contacts_pattern = '|'.join([c.highlight_pattern for c in self.contacts] + self.patterns)
        self._pattern = fr"\b(({with_contacts_pattern})s?)\b"
        self.regex = self.compile_patterns(self._pattern)
        self.contacts_lookup = Contact.build_name_lookup(self.contacts)
        for contact in self.contacts:
            contact.category = self.category_str
            contact.style = self.style
        logger.debug(repr(self))

    @property
    def category_str(self) -> str:
        if self.category:
            return self.category
        elif len(self.contacts) == 1 and self.label == self.contacts[0].name:
            return ''
        else:
            return self.label.replace('_', ' ')

    def info_for(self, name: str, include_category: bool = False) -> str | None:
        """Label and additional details for 'name' if present in `self.contacts`."""
        info_pieces = [self.category_str] if include_category else []
        if (contact := self.contacts_lookup.get(name)):
            if info_pieces and info_pieces[0] in contact.info:
                info_pieces = [contact.info]
            else:
                info_pieces.append(contact.info)
        info_pieces = without_falsey(info_pieces)
        return ', '.join(info_pieces) if info_pieces else None

    def __repr__(self) -> str:
        s = f"{type(self).__name__}("
        for prop in ['label', 'style', 'category', 'patterns', 'contacts', '_pattern']:
            val = getattr(self, prop)
            if not val or (prop == 'label' and len(self.contacts) == 1 and not self.patterns):
                continue
            s += f"\n    {prop}="
            if isinstance(val, dict):
                s += '{'
                for k, v in val.items():
                    s += f"\n        {constantize_name(k)}: {json.dumps(v).replace('null', 'None')},"
                s += '\n    },'
            elif prop == 'patterns':
                s += '[\n        '
                s += repr(val).removeprefix('[').removesuffix(']').replace(', ', ',\n        ')
                s += ',\n    ],'
            elif isinstance(val, list) and val and isinstance(val[0], Contact):
                s += '[\n        '
                s += f"    {', '.join([c.name for c in val])}"
                s += ',\n    ],'
            else:
                s += f"{json.dumps(val)},"
        return s + '\n)'

    def __str__(self) -> str:
        return super().__str__()


@dataclass(kw_only=True)
class ManualHighlight(HighlightGroup):
    """For cases where the regex cannot be auto-constructed."""
    pattern: str

    def __post_init__(self):
        super().__post_init__()
        if self._capture_group_marker not in self.pattern:
            raise ValueError(f"Label '{self.label}' must appear in regex pattern '{self.pattern}'")
        self.regex = re.compile(self.pattern, re.MULTILINE)

# Multi-label classifier for stance detection using logistic regression
from typing import List, Dict
import numpy as np
from sklearn.linear_model import LogisticRegression

AXES_LIST = ["EH","DC","EX","MA","RR","AG","AS","SV","VA","AR","IF","ED"]

class StanceClassifier:
    """
    Lightweight multi-label classification module built on hand-crafted features.
    Can be substituted with an embedding-driven architecture if needed.
    """
    def __init__(self, target_axes: List[str] = None):
        self.target_axes = target_axes or AXES_LIST
        self.classifiers = {axis: LogisticRegression(max_iter=500) for axis in self.target_axes}
        self.trained = False

    def _extract_features(self, feature_dicts: List[Dict]) -> np.ndarray:
        feature_keys = ["hedges","modals","meta","backtrack","action","verify","q_ratio",
                        "exclaim","pos","neg","len"]
        feature_matrix = np.array([[fd[key] for key in feature_keys] for fd in feature_dicts], dtype=float)
        return feature_matrix

    def train(self, feature_dicts: List[Dict], ground_truth: Dict[str, np.ndarray]):
        X = self._extract_features(feature_dicts)
        for axis, y_values in ground_truth.items():
            self.classifiers[axis].fit(X, y_values)
        self.trained = True
        return self

    def predict_probabilities(self, feature_dicts: List[Dict]) -> Dict[str, np.ndarray]:
        assert self.trained, "StanceClassifier has not been trained yet"
        X = self._extract_features(feature_dicts)
        results = {}
        for axis, clf in self.classifiers.items():
            probabilities = clf.predict_proba(X)
            if probabilities.shape[1] == 2:
                results[axis] = probabilities[:, 1]
            else:
                results[axis] = probabilities[:, -1] if probabilities.ndim == 2 else probabilities
        return results

# SteamApps module wrapper for Steamworks API
from enum import Enum
import steamworks.util            as util
from steamworks.enums             import *
from steamworks.structs           import *
from steamworks.exceptions        import *

class SteamApps(object):
    def __init__(self, steam_api: object):
        self.steam_api = steam_api
        if not self.steam_api.loaded():
            raise SteamNotLoadedException('STEAMWORKS not yet loaded')

    def IsSubscribed(self) -> bool:
        """Determine whether the user holds a license for the current application
        :return: bool indicating subscription status
        """
        return self.steam_api.IsSubscribed()

    def IsLowViolence(self) -> bool:
        """Determine if the user's license includes low-violence content depots
        :return: bool indicating low violence support
        """
        return self.steam_api.IsLowViolence()

    def IsCybercafe(self) -> bool:
        """Check if the current App ID is designated for Cyber Cafes
        :return: bool indicating cyber cafe status
        """
        return self.steam_api.IsCybercafe()

    def IsVACBanned(self) -> bool:
        """Check if the current account has any VAC bans
        :return: bool indicating VAC ban status
        """
        return self.steam_api.IsVACBanned() or False

    def GetCurrentGameLanguage(self) -> str:
        """Retrieve the language currently selected by the user
        :return: str containing ISO language code
        """
        return self.steam_api.GetCurrentGameLanguage() or 'None'

    def GetAvailableGameLanguages(self) -> str:
        """Get comma-separated list of languages supported by the current app
        :return: str containing supported language codes
        """
        return self.steam_api.GetAvailableGameLanguages() or 'None'

    def IsSubscribedApp(self, app_id: int) -> bool:
        """Verify if the active user holds a license for the specified App ID
        :param app_id: int representing the target application
        :return: bool indicating subscription status
        """
        return self.steam_api.IsSubscribedApp(app_id)

    def IsDLCInstalled(self, dlc_id: int) -> bool:
        """Check if the user owns and has installed a specific DLC
        :param dlc_id: int representing the DLC identifier
        :return: bool indicating installation status
        """
        return self.steam_api.IsDLCInstalled(dlc_id)

    def GetEarliestPurchaseUnixTime(self, app_id: int) -> int:
        """Obtain purchase time of the specified app in Unix epoch format
        :param app_id: int representing the target application
        :return: int timestamp of initial purchase
        """
        return self.steam_api.GetEarliestPurchaseUnixTime(app_id)

    def IsSubscribedFromFreeWeekend(self) -> bool:
        """Check if access to current app is via free weekend promotion
        :return: bool indicating free weekend subscription status
        """
        return self.steam_api.IsSubscribedFromFreeWeekend()

    def GetDLCCount(self) -> int:
        """Retrieve number of DLC items owned for the parent application
        :return: int count of downloadable content items
        """
        return self.steam_api.GetDLCCount()

    def InstallDLC(self, dlc_id: int) -> None:
        """Initiate installation of an optional DLC package
        :param dlc_id: int representing the DLC to install
        :return: None
        """
        self.steam_api.InstallDLC(dlc_id)

    def UninstallDLC(self, dlc_id: int) -> None:
        """Remove installation of an optional DLC package
        :param dlc_id: int representing the DLC to uninstall
        :return: None
        """
        self.steam_api.UninstallDLC(dlc_id)

    def MarkContentCorrupt(self, missing_files_only: bool = True) -> bool:
        """Request full content verification on next application launch
        :param missing_files_only: bool controlling verification scope
        :return: bool indicating success of request
        """
        return self.steam_api.MarkContentCorrupt(missing_files_only)

    def GetAppInstallDir(self, app_id: int) -> str:
        """Acquire installation directory path for a given App ID
        :param app_id: int representing the target application
        :return: str containing installation path
        """
        return self.steam_api.GetAppInstallDir(app_id).decode()

    def IsAppInstalled(self, app_id: int) -> bool:
        """Check if a specific application is present on disk
        :param app_id: int representing the target application
        :return: bool indicating presence of installation files
        """
        return self.steam_api.IsAppInstalled(app_id)

    def GetAppOwner(self) -> int:
        """Get Steam ID of original license holder (for borrowed content)
        :return: int Steam ID of content owner
        """
        return self.steam_api.GetAppOwner()

    def GetLaunchQueryParam(self, key: str) -> str:
        """Extract parameter value from custom launch URL query string
        :param key: str parameter name to retrieve
        :return: str parameter value or empty string
        """
        return self.steam_api.GetLaunchQueryParam(key)

    def GetAppBuildId(self) -> int:
        """Fetch the current build identifier for this application
        :return: int build version number
        """
        return self.steam_api.GetAppBuildId()

    def GetFileDetails(self, filename: str) -> None:
        """Trigger asynchronous retrieval of manifest file metadata
        :param filename: str name of file to inspect
        :return: None
        """
        self.steam_api.GetFileDetails(filename)

import os
import sys
import warnings
from dataclasses import asdict, dataclass, field
from typing import ClassVar, Optional
import ray
import ray.actor
import ray.util.scheduling_strategies
import yaml
from ..hardware import (
    Accelerator,
    AcceleratorType,
    Hardware,
    HardwareInfo,
    HardwareResource,
)
from .config import ClusterConfig, NodeGroupEnvConfig

@dataclass
class NodeData:
    """Details about a node in the cluster."""
    node_tags: list[str]
    """Tags associated with the node, mapping to node group labels in the cluster setup."""
    node_index: int
    """Position of the node within the cluster."""
    ray_uuid: str
    """Ray's distinct identifier for the node."""
    node_address: str
    """IP address assigned to the node."""
    cpu_count: int
    """Number of CPUs accessible on the node."""
    python_path: str
    """Path to the Python interpreter used on the node."""
    base_env_vars: dict[str, str]
    """Baseline environment variables on the node, set prior to Ray startup."""
    custom_env_vars: dict[str, str]
    """Environment variables configured by the scheduler on the node."""
    hw_resources: list[HardwareResource] = field(default_factory=list)
    """Collection of hardware resources available on the node."""

    @property
    def gpu_count(self) -> int:
        """Retrieve the number of GPUs on the node."""
        return self.get_hw_resource_count(Accelerator.HW_TYPE)

    @property
    def gpu_type(self) -> str:
        """Determine the type of GPUs present on the node."""
        for resource in self.hw_resources:
            if resource.type == Accelerator.HW_TYPE and resource.count > 0:
                return Accelerator.get_accelerator_type_from_model(
                    resource.infos[0].model
                )
        return AcceleratorType.NO_ACCEL.value

    @property
    def gpu_model(self) -> str:
        """Identify the model of GPUs on the node."""
        for resource in self.hw_resources:
            if resource.type == Accelerator.HW_TYPE and resource.count > 0:
                return resource.infos[0].model
        return ""

    def get_hw_resource_count(self, hw_type: Optional[str]) -> int:
        """Fetch the count of a particular hardware resource type."""
        if hw_type is None:
            return 0
        for resource in self.hw_resources:
            if resource.type == hw_type:
                return resource.count
        return 0

    def __str__(self) -> str:
        """Textual representation of the NodeData."""
        node_dict = asdict(self)
        node_dict.pop("base_env_vars", None)
        node_dict.pop("custom_env_vars", None)
        return yaml.dump(node_dict, sort_keys=False)


@dataclass
class NodeGroupData:
    """Details regarding a collection of nodes in the cluster."""
    tag: str
    """Tag identifying the node group."""
    nodes: list[NodeData]
    """List of nodes belonging to this group."""
    hw_type: Optional[str] = None
    """Hardware type of the node group; limited to one type per group."""
    skip_hardware: bool = False
    """Flag indicating whether to bypass hardware detection for nodes in this group. If True, nodes are treated as CPU-only."""
    env_configs: Optional[list[NodeGroupEnvConfig]] = None
    """Environment configurations specific to the node group."""
    DEFAULT_GROUP_TAG: ClassVar[str] = "cluster"
    NODE_PLACEMENT_TAG: ClassVar[str] = "node"
    SPECIAL_TAGS: ClassVar[list[str]] = ["cluster", "node"]

    @property
    def node_indices(self) -> list[int]:
        """Extract the list of node indices in the node group."""
        return [node.node_index for node in self.nodes]

    @property
    def hw_resource_total(self) -> int:
        """Calculate the aggregate count of the specified hardware resource across the node group."""
        if self.hw_type is None:
            # When hw_type is unspecified, each node counts as a hardware resource
            return len(self.nodes)
        total = 0
        for node in self.nodes:
            total += node.get_hw_resource_count(self.hw_type)
        return total

    def get_hardware_details(self, node_index: int) -> list[HardwareInfo]:
        """Obtain hardware details for a specific node in the group."""
        details: list[HardwareInfo] = []
        for node in self.nodes:
            if node.node_index != node_index:
                continue
            for resource in node.hw_resources:
                if resource.type == self.hw_type:
                    details.extend(resource.infos)
        return details

    @property
    def local_hw_indices(self) -> list[list[int]]:
        """Acquire hardware indices for each node in the group."""
        start_idx = 0
        hw_indices = []
        for node in self.nodes:
            hw_count = node.get_hw_resource_count(self.hw_type)
            hw_indices.append(list(range(start_idx, start_idx + hw_count)))
            start_idx += hw_count
        return hw_indices

    def group_indices_to_global(self, group_indices: list[int]):
        """Map group-local indices to global node indices."""
        try:
            return [self.nodes[idx].node_index for idx in group_indices]
        except IndexError:
            raise IndexError(
                f"Group index out of bounds. Node group '{self.tag}' contains {len(self.nodes)} nodes, but received indices: {group_indices}"
            )

    def get_node_by_hw_index(self, hw_index: int):
        """Locate the node containing the specified hardware index in the group.
        Args:
            hw_index (int): The hardware index within the node group.
        Returns:
            NodeData: The node information that includes the hardware at the given index.
        """
        for i, node_hw_indices in enumerate(self.local_hw_indices):
            if hw_index in node_hw_indices:
                return self.nodes[i]

    def get_local_hw_index(self, hw_index: int):
        """Transform a global hardware index in the node group to its local counterpart within the node.
        Args:
            hw_index (int): The global hardware index in the node group.
        Returns:
            int: The local hardware index inside the node.
        """
        for node_hw_indices in self.local_hw_indices:
            if hw_index in node_hw_indices:
                return node_hw_indices.index(hw_index)

    def get_node_env_vars(self, node_index: int) -> dict[str, str]:
        """Fetch environment variables for a specific node in the group.
        Args:
            node_index (int): The index of the node.
        Returns:
            dict[str, str]: Environment variables for the node.
        """
        env_vars = {}
        node_env_keys = []
        for env_config in self.env_configs or []:
            if node_index in env_config.node_indices and env_config.env_vars is not None:
                for env_var_dict in env_config.env_vars:
                    env_vars.update(env_var_dict)
                    assert set(env_var_dict.keys()).isdisjoint(node_env_keys), (
                        f"Environment variables {set(env_var_dict.keys()).intersection(set(node_env_keys))} in cluster configuration for node group '{self.tag}' have been set in other env_configs of the same group. Please ensure uniqueness across env_configs."
                    )
                    node_env_keys.extend(env_var_dict.keys())
                return env_vars
        return {}

    def get_node_python_path(self, node_index: int) -> Optional[str]:
        """Retrieve the Python interpreter path for a specific node in the group.
        Args:
            node_index (int): The index of the node.
        Returns:
            Optional[str]: Python interpreter path for the node, or None if not specified.
        """
        paths = []
        for env_config in self.env_configs or []:
            if (
                node_index in env_config.node_indices
                and env_config.python_path is not None
            ):
                paths.append(env_config.python_path)
        if len(paths) == 0:
            return None
        if len(set(paths)) > 1:
            raise ValueError(
                f"Conflicting Python interpreter paths {paths} found for node index {node_index} in node group '{self.tag}'. Please ensure only one path is specified per node."
            )
        return paths[0]

    def __post_init__(self):
        """Post-initialization validation for node group data."""
        if self.hw_type is None and not self.skip_hardware:
            hw_resources: list[HardwareResource] = []
            for node in self.nodes:
                hw_resources.extend(node.hw_resources)
            hw_types = {resource.type for resource in hw_resources}
            assert Hardware.DEFAULT_HW_TYPE is not None, (
                "Default hardware type is undefined in HardwareEnumerationPolicy."
            )
            if Hardware.DEFAULT_HW_TYPE in hw_types:
                self.hw_type = Hardware.DEFAULT_HW_TYPE

    def __str__(self) -> str:
        """Textual representation of the NodeGroupData."""
        group_dict = asdict(self)
        group_dict["nodes"] = ",".join([str(node.node_index) for node in self.nodes])
        return yaml.dump(group_dict, sort_keys=False)


class NodeScanner:
    """Remote scanner to gather node hardware and environment details.
    This class initiates one _RemoteNodeScanner actor on each node in the Ray cluster to collect hardware and environment data.
    """
    def __init__(self, cluster_num_nodes: int, cluster_cfg: Optional[ClusterConfig]):
        """Initialize the HardwareEnumerator on designated nodes."""
        from .cluster import Cluster
        assert ray.is_initialized(), (
            "Ray must be initialized before creating HardwareEnumerator."
        )
        self._scanners: list[ray.actor.ActorHandle] = []
        self._nodes: list[NodeData] = []
        self._cluster_cfg = cluster_cfg
        node_infos = Cluster.get_alive_nodes()
        num_nodes = len(node_infos)
        for node_info in node_infos:
            node_ray_id = node_info["NodeID"]
            try:
                scanner = _RemoteNodeScanner.options(
                    scheduling_strategy=ray.util.scheduling_strategies.NodeAffinitySchedulingStrategy(
                        node_id=node_ray_id, soft=False
                    ),
                    name=f"NodeScanner_{node_ray_id}",
                ).remote(node_info, num_nodes, cluster_cfg, sys.executable)
            except ValueError:
                raise Cluster.NamespaceConflictError
            self._scanners.append(scanner)
        handles = []
        for scanner in self._scanners:
            handles.append(scanner.get_node_data.remote())
        self._nodes = ray.get(handles)
        self._sort_nodes(cluster_num_nodes)
        self._configure_node_envs()
        # Node groups
        self._node_groups: list[NodeGroupData] = []
        if self._cluster_cfg is not None and self._cluster_cfg.node_groups is not None:
            for node_group_cfg in self._cluster_cfg.node_groups:
                group_nodes: list[NodeData] = []
                for node in self._nodes:
                    if node.node_index in node_group_cfg.node_indices:
                        group_nodes.append(node)
                if len(group_nodes) > 0:
                    node_group_data = NodeGroupData(
                        tag=node_group_cfg.tag,
                        nodes=group_nodes,
                        hw_type=node_group_cfg.hw_type,
                        env_configs=node_group_cfg.env_configs,
                        skip_hardware=node_group_cfg.skip_hardware,
                    )
                    self._node_groups.append(node_group_data)
        # Default node group including all nodes
        self._node_groups.append(
            NodeGroupData(tag=NodeGroupData.DEFAULT_GROUP_TAG, nodes=self._nodes)
        )
        # Reserved "node" tag for node-level placement
        node_group = NodeGroupData(
            tag=NodeGroupData.NODE_PLACEMENT_TAG,
            nodes=self._nodes,
            skip_hardware=True,
        )
        self._node_groups.append(node_group)
        assert len({group.tag for group in self._node_groups}) == len(
            self._node_groups
        ), (
            f"Node group tags must be unique, but got: {[group.tag for group in self._node_groups]}"
        )

    @property
    def nodes(self):
        """Access the list of node data.
        Returns:
            list[NodeData]: List of node data.
        """
        return self._nodes

    @property
    def node_groups(self):
        """Access the list of node groups.
        Returns:
            list[NodeGroupData]: List of node groups.
        """
        return self._node_groups

    @property
    def head_node(self):
        """Get the head node data, which is the node that initializes the cluster.
        Returns:
            NodeData: Head node data.
        """
        current_id = ray.get_runtime_context().get_node_id()
        head_node = next(
            (node for node in self._nodes if node.ray_uuid == current_id), None
        )
        assert head_node is not None, (
            f"Head node with Ray UUID {current_id} not found in the cluster nodes: {[node.ray_uuid for node in self._nodes]}"
        )
        return head_node

    def _configure_node_envs(self):
        """Adjust each node's environments according to the cluster configuration.
        Environment variables follow this precedence (later ones override earlier ones if duplicated):
        1. Baseline environment variables on the node (set before Ray startup).
        2. Environment variables set between Ray startup and RLinf initialization on the head node (typically via bash scripts). These are likely intended for all nodes.
        3. The env_vars field in ClusterConfig, configured via YAML files to tailor each node.
        """
        # Override the head node's Python interpreter path with the current one unless overridden in config
        self.head_node.python_path = sys.executable
        # First identify env vars set between Ray startup and RLinf initialization on the head node
        head_node_base_env_vars = self.head_node.base_env_vars
        current_env_vars = os.environ
        modified_env_vars = {}
        for key, value in current_env_vars.items():
            if (
                key not in head_node_base_env_vars
                or head_node_base_env_vars[key] != value
            ):
                modified_env_vars[key] = value
        for node in self._nodes:
            # Start with baseline env vars on the node
            node.custom_env_vars = node.base_env_vars.copy()
            # Update with modified env vars from the head node
            node.custom_env_vars.update(modified_env_vars)

    def _sort_nodes(self, cluster_num_nodes: int):
        """Order the node data list by node index if available; otherwise by GPU type and IP."""
        from .cluster import Cluster, ClusterEnvVar
        # Sort by node index when available
        if all(node_data.node_index != -1 for node_data in self._nodes):
            # NODE_INDEX should be >= 0
            assert all(node_data.node_index >= 0 for node_data in self._nodes), (
                f"{Cluster.get_full_env_var_name(ClusterEnvVar.NODE_INDEX)} should not be negative, but got: {[node_data.node_index for node_data in self._nodes if node_data.node_index < 0]}"
            )
            # NODE_INDEX should be < number of nodes
            assert all(
                node_data.node_index < len(self._nodes) for node_data in self._nodes
            ), (
                f"{Cluster.get_full_env_var_name(ClusterEnvVar.NODE_INDEX)} should be less than {len(self._nodes)}, but got: {[node_data.node_index for node_data in self._nodes if node_data.node_index >= len(self._nodes)]}"
            )
            self._nodes.sort(key=lambda x: x.node_index)
            # Handle mismatch between configured and actual node count
            if len(self._nodes) > cluster_num_nodes:
                assert self.head_node.node_index < cluster_num_nodes, (
                    f"The cluster is initialized with {cluster_num_nodes} nodes, but detected {len(self._nodes)} nodes joined the Ray cluster. The head node where you run the main process has node index {self.head_node.node_index}, which exceeds the configured limit. Please verify your cluster configuration."
                )
        else:
            # Either all nodes set NODE_INDEX or none do
            assert all(node_data.node_index == -1 for node_data in self._nodes), (
                f"Either all nodes set {Cluster.get_full_env_var_name(ClusterEnvVar.NODE_INDEX)}, or none do. But got: {[node_data.node_index for node_data in self._nodes if node_data.node_index != -1]}"
            )
            # NODE_INDEX not set, sort first by GPU type, then by IP
            nodes_by_gpu: dict[str, list[NodeData]] = {}
            for node in self._nodes:
                gpu_name = node.gpu_type
                nodes_by_gpu.setdefault(gpu_name, [])
                nodes_by_gpu[gpu_name].append(node)
            for gpu_name in nodes_by_gpu.keys():
                nodes_by_gpu[gpu_name].sort(key=lambda x: x.node_address)
            self._nodes = [
                node for nodes in nodes_by_gpu.values() for node in nodes
            ]
            # Move head node to the front
            head_node = self.head_node
            self._nodes.remove(head_node)
            self._nodes.insert(0, head_node)
            node_index = 0
            for node in self._nodes:
                node.node_index = node_index
                node_index += 1
        # Handle mismatch between configured and actual node count
        if len(self._nodes) > cluster_num_nodes:
            warnings.warn(
                f"The cluster is initialized with {cluster_num_nodes} nodes, but detected {len(self._nodes)} nodes joined the Ray cluster. Only the first {cluster_num_nodes} nodes will be used."
            )
            self._nodes = self._nodes[:cluster_num_nodes]
        # Node indices should be unique and sequential from 0 to num_nodes - 1
        node_indices = [node_data.node_index for node_data in self._nodes]
        assert sorted(node_indices) == list(range(len(self._nodes))), (
            f"{Cluster.get_full_env_var_name(ClusterEnvVar.NODE_INDEX)} should be unique and sequential from 0 to {len(self._nodes) - 1}, but got: {node_indices}"
        )


@ray.remote
class _RemoteNodeScanner:
    """Remote Ray actor responsible for gathering node information."""
    def __init__(
        self,
        node_info: dict[str, str],
        num_nodes: int,
        cluster_cfg: Optional[ClusterConfig],
        head_python_path: str,
    ):
        from .cluster import Cluster, ClusterEnvVar
        # Node index
        try:
            node_index = int(Cluster.get_sys_env_var(ClusterEnvVar.NODE_INDEX, -1))
        except ValueError:
            raise ValueError(
                f"Invalid NODE_INDEX value: {Cluster.get_sys_env_var(ClusterEnvVar.NODE_INDEX)}. Must be an integer."
            )
        if num_nodes == 1:
            node_index = 0
        # Node tag
        node_tags = []
        if cluster_cfg is not None and cluster_cfg.node_groups is not None:
            assert node_index != -1, (
                f"{Cluster.get_full_env_var_name(ClusterEnvVar.NODE_INDEX)} must be set when more than one node connects to Ray and cluster node configuration is provided."
            )
            node_tags = cluster_cfg.get_node_tags_by_index(node_index)
        # Node hardware resources
        node_hw_configs = []
        if cluster_cfg is not None:
            node_hw_configs = cluster_cfg.get_node_hw_configs_by_index(node_index)
        hw_resources: list[HardwareResource] = []
        for policy in Hardware.policy_registry:
            hw_resource = policy.enumerate(node_index, node_hw_configs)
            if hw_resource is not None and hw_resource.count > 0:
                hw_resources.append(hw_resource)
        # Python interpreter path
        if sys.executable != head_python_path:
            warnings.warn(
                f"Python interpreter used to launch Ray on node with IP {node_info['NodeManagerAddress']} differs from that on the head node {head_python_path}. Continuing with current interpreter {sys.executable} on this node."
            )
        python_path = sys.executable
        if cluster_cfg is not None:
            cfg_python_paths = (
                cluster_cfg.get_node_python_path_by_index(node_index)
            )
            for path in cfg_python_paths:
                assert os.path.exists(path), (
                    f"Python interpreter path {path} does not exist on node with index {node_index}. Please check your cluster configuration."
                )
        self._node_data = NodeData(
            node_tags=node_tags,
            node_index=node_index,
            ray_uuid=node_info["NodeID"],
            node_address=node_info["NodeManagerAddress"],
            cpu_count=int(node_info["Resources"].get("CPU", 0)),
            python_path=python_path,
            base_env_vars=os.environ.copy(),
            custom_env_vars=os.environ.copy(),
            hw_resources=hw_resources,
        )

    def get_node_data(self):
        """Retrieve the node data.
        Returns:
            NodeData: The node data.
        """
        return self._node_data

