# Decrypt Matrix encrypted file payload
from __future__ import annotations
import base64
import hashlib
from typing import Any

def _decode_base64_unpadded(data: str) -> bytes:
    if not data:
        raise ValueError("Empty base64 string")
    padding_needed = 4 - (len(data) % 4)
    if padding_needed != 4:
        padded_data = data + "=" * padding_needed
    else:
        padded_data = data
    try:
        return base64.urlsafe_b64decode(padded_data)
    except Exception:
        return base64.b64decode(padded_data)

def decrypt_matrix_encrypted_media(file_metadata: dict[str, Any], encrypted_data: bytes) -> bytes:
    """Decrypt Matrix encrypted media payload.
    Expects a file_metadata dict with keys: url, key, iv, hashes, v.
    """
    if not isinstance(file_metadata, dict):
        raise ValueError("Invalid encrypted file metadata")

    version = file_metadata.get("v")
    if version and version != "v2":
        raise ValueError(f"Unsupported encrypted media version: {version}")

    key_details = file_metadata.get("key") or {}
    if key_details.get("kty") != "oct":
        raise ValueError("Unsupported key type for encrypted media")

    key_base64 = key_details.get("k")
    iv_base64 = file_metadata.get("iv")

    if not key_base64 or not iv_base64:
        raise ValueError("Missing key or initialization vector for encrypted media")

    key_bytes = _decode_base64_unpadded(key_base64)
    iv_bytes = _decode_base64_unpadded(iv_base64)

    hash_info = file_metadata.get("hashes") or {}
    expected_hash_value = hash_info.get("sha256")

    if expected_hash_value:
        expected_hash_bytes = _decode_base64_unpadded(expected_hash_value)
        actual_hash_bytes = hashlib.sha256(encrypted_data).digest()
        if actual_hash_bytes != expected_hash_bytes:
            raise ValueError("Encrypted media sha256 hash mismatch")

    try:
        from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
    except Exception as exc:  # pragma: no cover - optional dependency
        raise RuntimeError("cryptography library is required to decrypt Matrix media") from exc

    cipher_object = Cipher(algorithms.AES(key_bytes), modes.CTR(iv_bytes))
    decryptor_object = cipher_object.decryptor()
    return decryptor_object.update(encrypted_data) + decryptor_object.finalize()

import time
from django.contrib.auth import authenticate, login as auth_login, logout as auth_logout
from django.http import JsonResponse, StreamingHttpResponse
from django.shortcuts import redirect
from django.urls import reverse
import test_data

async def main_page(request):
    return JsonResponse(test_data.JSON_1K, safe=False)

async def server_sent_events(request):
    """Server-Sent Events endpoint that sends timestamp data every second."""
    async def event_generator():
        while True:
            await asyncio.sleep(1)
            yield f"data: {time.time()}\n\n"
    return StreamingHttpResponse(event_generator(), content_type="text/event-stream")

def accounts_home(request):
    """Mounted Django accounts testing index."""
    base = reverse("accounts-index").rstrip("/")
    return JsonResponse(
        {
            "source": "django_mount",
            "message": "Mounted Django accounts test endpoints",
            "endpoints": {
                "login": reverse("accounts-login"),
                "logout": reverse("accounts-logout"),
                "profile": reverse("accounts-profile"),
                "provider_callback": f"{reverse('accounts-provider-callback')}?code=demo&state=xyz",
                "django_auth_urls": f"{base}/auth/",
                "allauth_if_installed": f"{base}/allauth/",
            },
        }
    )

def accounts_sign_in(request):
    """
    Minimal login endpoint for mounted-Django testing.
    POST form fields:
    - username
    - password
    - next (optional, default: /accounts/profile/)
    """
    if request.method == "GET":
        return JsonResponse(
            {
                "source": "django_mount",
                "action": "login",
                "method": "POST",
                "required_fields": ["username", "password"],
                "optional_fields": ["next"],
            }
        )
    username = request.POST.get("username") or request.GET.get("username")
    password = request.POST.get("password") or request.GET.get("password")
    redirect_url = request.POST.get("next") or request.GET.get("next") or reverse("accounts-profile")
    if not username or not password:
        return JsonResponse(
            {"ok": False, "error": "username and password are required"},
            status=400,
        )
    user = authenticate(request, username=username, password=password)
    if user is None:
        return JsonResponse({"ok": False, "error": "invalid credentials"}, status=401)
    auth_login(request, user)
    return redirect(redirect_url)

def accounts_sign_out(request):
    """Logout endpoint for mounted-Django testing."""
    auth_logout(request)
    return redirect(reverse("accounts-login"))

def accounts_user_profile(request):
    """Simple auth state endpoint for mounted-Django testing."""
    user = request.user
    is_authenticated = bool(getattr(user, "is_authenticated", False))
    return JsonResponse(
        {
            "source": "django_mount",
            "authenticated": is_authenticated,
            "username": user.get_username() if is_authenticated else None,
        }
    )

def accounts_oauth_callback(request):
    """
    Simulates an OAuth provider callback endpoint (allauth-style URL shape).
    Example:
    /accounts/provider/callback/?code=demo-code&state=demo-state
    """
    return JsonResponse(
        {
            "source": "django_mount",
            "action": "provider_callback",
            "query": dict(request.GET.items()),
        }
    )

# Modified version with Type I clone transformations
import functools as ft
from functools import lru_cache as cache_lru
from typing import Any as AnyType
from typing import Callable as CallableType
from typing import Dict as DictType
from typing import Optional as OptionalType
from typing import Tuple as TupleType
import torch as torch_lib
import torch_npu as torch_npu_lib
import triton as triton_lib
import triton.language as tl_lang
from packaging import version as pkg_version

torch_to_triton_dtype_map = {
    torch_lib.float32: tl_lang.float32,
    torch_lib.float16: tl_lang.float16,
    torch_lib.bfloat16: tl_lang.bfloat16,
}

def compute_ceil_div(x_val, y_val):
    return (x_val + y_val - 1) // y_val

def apply_alignment(tensor_val, n_cols_val, aligned_bytes_val):
    aligned_bytes_val = compute_ceil_div(tensor_val.element_size() * n_cols_val, aligned_bytes_val) * aligned_bytes_val
    return aligned_bytes_val // tensor_val.element_size()

@triton_lib.jit
def load_with_mask_1d(ptr_arg, skip_boundary_check_flag: tl_lang.constexpr, mask_arg: tl_lang.tensor, other_val=0):
    if not skip_boundary_check_flag:
        return tl_lang.load(ptr_arg, mask_arg, other=other_val)
    else:
        return tl_lang.load(ptr_arg)

@triton_lib.jit
def store_with_mask_1d(ptr_arg, value_arg, skip_boundary_check_flag: tl_lang.constexpr, mask_arg: tl_lang.tensor):
    if not skip_boundary_check_flag:
        tl_lang.store(ptr_arg, value_arg, mask_arg)
    else:
        tl_lang.store(ptr_arg, value_arg)

def cache_tensor_result(fn: CallableType[..., torch_lib.Tensor]) -> CallableType[..., torch_lib.Tensor]:
    """
    A decorator that caches the most recent result of a function with tensor inputs.
    This decorator will store the output of the decorated function for the most recent set of input tensors.
    If the function is called again with the same input tensors, it will return the cached result.
    Args:
        fn (Callable[..., torch.Tensor]):
            The function to be decorated. It should take tensor inputs and return tensor outputs.
    Returns:
        Callable[..., torch.Tensor]:
            A wrapped version of the input function with single-entry caching.
    """
    last_args_saved: OptionalType[TupleType] = None
    last_kwargs_saved: OptionalType[DictType] = None
    last_result_saved: AnyType = None

    @ft.wraps(fn)
    def wrapper(*args: AnyType, **kwargs: AnyType) -> AnyType:
        nonlocal last_args_saved, last_kwargs_saved, last_result_saved

        if last_args_saved is not None and last_kwargs_saved is not None:
            if len(args) == len(last_args_saved) and len(kwargs) == len(last_kwargs_saved):
                if all(a is b for a, b in zip(args, last_args_saved)) and all(
                    k in last_kwargs_saved and v is last_kwargs_saved[k] for k, v in kwargs.items()
                ):
                    return last_result_saved

        result = fn(*args, **kwargs)
        last_args_saved, last_kwargs_saved, last_result_saved = args, kwargs, result
        return result

    return wrapper

def input_tensor_decorator(
    *,
    ensure_contiguous: bool = True,
    auto_set_device: bool = True,
) -> CallableType[[CallableType[..., torch_lib.Tensor]], CallableType[..., torch_lib.Tensor]]:
    """
    A decorator to optionally:
      1. make all input tensors contiguous
      2. set device context based on input tensors
    """
    def decorator_wrapper(fn: CallableType[..., torch_lib.Tensor]) -> CallableType[..., torch_lib.Tensor]:
        @ft.wraps(fn)
        def wrapper_func(*args, **kwargs):
            if ensure_contiguous:
                new_args_list = tuple(a.contiguous() if isinstance(a, torch_lib.Tensor) else a for a in args)
                new_kwargs_dict = {k: (v.contiguous() if isinstance(v, torch_lib.Tensor) else v) for k, v in kwargs.items()}
            else:
                new_args_list = args
                new_kwargs_dict = kwargs

            tensor_ref = None
            for item in new_args_list:
                if isinstance(item, torch_lib.Tensor):
                    tensor_ref = item
                    break

            if tensor_ref is None:
                for val in new_kwargs_dict.values():
                    if isinstance(val, torch_lib.Tensor):
                        tensor_ref = val
                        break

            if auto_set_device and tensor_ref is not None:
                ctx_manager = custom_device_context(tensor_ref.device.index)
            else:
                ctx_manager = __import__('contextlib').nullcontext()

            with ctx_manager:
                return fn(*new_args_list, **new_kwargs_dict)

        return wrapper_func

    return decorator_wrapper

# TODO(liuyuan): remove the followling statements when triton-npu support checking whether an address is device-valid.
# See https://github.com/triton-lang/triton/blob/571d07b84ffbaee4b873c2918208e2c640057768/third_party/nvidia/backend/driver.py#L415
def tensor_device_protection_for_triton_kernel(module_path, module_name, target_device="npu"):
    from mojo_opset.utils.misc import get_bool_env
    disable_flag = get_bool_env("MOJO_DISABLE_TENSOR_GUARD", True)
    if disable_flag:
        return

    import pkgutil as pkg_util
    import importlib as import_util
    from inspect import getmembers as inspect_getmembers
    import torch.utils._pytree as pytree_util
    from triton.runtime.jit import JITFunction as TritonJITFunction, KernelInterface as TritonKernelInterface

    def device_validation_hook(*args, **kwargs):
        if not pytree_util.tree_all_only(torch_lib.Tensor, lambda x: x.device.type == target_device, (args, kwargs)):
            raise TypeError("Found cpu tensor(s) which should not be passed to the triton kernel.")

    for _, name, _ in pkg_util.walk_packages(module_path, prefix=f"{module_name}."):
        module = import_util.import_module(name)
        for obj_name, obj in inspect_getmembers(module):
            if not isinstance(obj, TritonKernelInterface):
                continue
            # NOTE(liuyuan): for autotuners.
            while not isinstance(obj, TritonJITFunction):
                obj = obj.fn
            obj.add_pre_run_hook(device_validation_hook)

contiguous_decorator = input_tensor_decorator

