@cache_tensor_result
def compute_sequence_lengths(cu_seqlens_input: torch_lib.LongTensor) -> torch_lib.LongTensor:
    return cu_seqlens_input[1:] - cu_seqlens_input[:-1]

@cache_tensor_result
def compute_chunk_positions(cu_seqlens_input: torch_lib.LongTensor, chunk_size_val: int) -> torch_lib.LongTensor:
    lens = triton_lib.cdiv(compute_sequence_lengths(cu_seqlens_input), chunk_size_val)
    total_count = lens.sum()
    flat_indices = torch_lib.arange(total_count, device=cu_seqlens_input.device)
    seq_ids = torch_lib.repeat_interleave(torch_lib.arange(lens.numel(), device=cu_seqlens_input.device), lens)
    offsets = torch_lib.cumsum(lens, 0) - lens
    relative_indices = flat_indices - offsets[seq_ids]
    return torch_lib.stack([relative_indices.eq(0).cumsum(0) - 1, relative_indices], dim=1)

