# Calculate file description for LLM/coder context using preview or legacy methods
from datetime import datetime
from typing import Any, Dict, Optional
from sqlalchemy import Column, Integer, String, DateTime, ForeignKey, UUID, JSON
from .base import BaseSchema
from sqlalchemy.orm import relationship
from app.models.report_file_association import report_file_association

class File(BaseSchema):
    __tablename__ = "files"
    filename = Column(String, index=True)
    filepath = Column(String, index=True)
    mime_type = Column(String, index=True)

    # Raw preview data (no LLM) - stores sheet names, raw cells, text preview, etc.
    preview_data = Column(JSON, nullable=True)
    owner_id = Column(String(36), ForeignKey("users.id"), nullable=False)
    owner = relationship("User", back_populates="files")
    org_id = Column(String(36), ForeignKey("organizations.id"), nullable=False)
    organization = relationship("Organization", back_populates="files")
    reports = relationship("Report", secondary=report_file_association, back_populates="files")
    tag_mappings = relationship("FileTag", back_populates="file", lazy="selectin")
    schema_definitions = relationship("SheetSchema", back_populates="file", lazy="selectin")

    def get_legacy_description(self):
        """Legacy method - returns description for backward compatibility."""
        return self.description

    @property
    def description(self) -> str:
        """
        Render file description for LLM/coder context.

        Uses raw preview if available, falls back to legacy schema/tags.
        """
        # Use new preview-based description if preview exists
        if self.preview_data:
            return self._generate_preview_description()

        # Legacy fallback: use schema_definitions or tag_mappings
        return self._generate_legacy_description()

    def _generate_preview_description(self) -> str:
        """Render description from raw preview data."""
        from app.services.file_preview import render_file_description
        return render_file_description(self.preview_data, self.filepath)

    def _generate_legacy_description(self) -> str:
        """Legacy description using LLM-extracted schema/tags (for backward compat)."""
        if self.mime_type == "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet":    
            desc = f"Excel File: {self.filename}\nPath: {self.filepath}\n\nSheet Schemas:\n"
            for schema_def in self.schema_definitions:
                desc += f"Sheet Name: {schema_def.sheet_name}\n"
                desc += f"Sheet index: {schema_def.sheet_index}\n"
                if schema_def.schema:
                    desc += f"Schema: {schema_def.schema}\n"
        elif self.mime_type == "application/vnd.ms-excel":
            desc = f"Excel File: {self.filename}\nPath: {self.filepath}\n\nSheet Schemas:\n"
            for schema_def in self.schema_definitions:
                desc += f"Sheet Name: {schema_def.sheet_name}\n"
                desc += f"Sheet index: {schema_def.sheet_index}\n"
        elif self.mime_type == "application/pdf":
            desc = f"PDF File: {self.filename}\nPath: {self.filepath}\n\nFile Tags:\n"
            for tag_map in self.tag_mappings:
                desc += f"{tag_map.key}: {tag_map.value}\n"
        elif self.mime_type in ["text/csv", "application/csv"]:
            desc = f"CSV File: {self.filename}\nPath: {self.filepath}\n"
        else:
            desc = f"File: {self.filename}\nPath: {self.filepath}\nType: {self.mime_type}\n"
            for tag_map in self.tag_mappings:
                desc += f"{tag_map.key}: {tag_map.value}\n"

        return desc

