# Import necessary modules
import math
import threading
from abc import ABC
from datetime import datetime
import torch
import torch.distributed as dist
from areal.infra.platforms import current_platform

# Define a large constant representing 1000 years in seconds
INFINITE_DURATION = 60 * 60 * 24 * 365 * 1000

class FrequencyControl:
    """A utility to control the execution of code based on time and/or step frequency."""
    def __init__(
        self,
        time_interval: int | None = None,
        step_interval: int | None = None,
        first_call_enabled: bool = False,
        process_group: dist.ProcessGroup | None = None,
    ):
        """Initialize the FrequencyControl instance.
        Args:
            time_interval: Minimum time gap (in seconds) between two triggers.
            step_interval: Minimum number of steps between two triggers.
            first_call_enabled: If True, the first call to check() returns True.
            process_group: Distributed process group for synchronization across processes.
        NOTE:
            - If both time_interval and step_interval are None, check() always returns False unless first_call_enabled is True.
            - If both are provided, both conditions must be satisfied for check() to return True.
            - If only one is provided, only that condition is checked.
        """
        self.time_interval = time_interval
        self.step_interval = step_interval
        self.process_group = process_group
        self.__start_time = datetime.now()
        self.__step_count = 0
        self.__last_trigger_time = datetime.now()
        self.__last_trigger_step = 0
        self.__elapsed_seconds = self.__elapsed_steps = None
        self.__first_call_enabled = first_call_enabled
        self.__lock = threading.Lock()

    def get_state(self):
        return dict(
            time_interval=self.time_interval,
            step_interval=self.step_interval,
            start_timestamp=self.__start_time.timestamp(),
            step_count=self.__step_count,
            last_trigger_timestamp=self.__last_trigger_time.timestamp(),
            last_trigger_step=self.__last_trigger_step,
            elapsed_steps=self.__elapsed_steps,
            elapsed_seconds=self.__elapsed_seconds,
            first_call_enabled=self.__first_call_enabled,
        )

    def set_state(self, state_dict):
        self.time_interval = state_dict["time_interval"]
        self.step_interval = state_dict["step_interval"]
        self.__start_time = datetime.fromtimestamp(state_dict["start_timestamp"])
        self.__step_count = state_dict["step_count"]
        self.__last_trigger_time = datetime.fromtimestamp(state_dict["last_trigger_timestamp"])
        self.__last_trigger_step = state_dict["last_trigger_step"]
        self.__elapsed_steps = state_dict["elapsed_steps"]
        self.__elapsed_seconds = state_dict["elapsed_seconds"]
        self.__first_call_enabled = state_dict["first_call_enabled"]

    @property
    def total_elapsed_seconds(self):
        current_time = datetime.now()
        return (current_time - self.__start_time).total_seconds()

    @property
    def total_completed_steps(self):
        return self.__step_count

    @property
    def recent_elapsed_seconds(self):
        return self.__elapsed_seconds

    @property
    def recent_elapsed_steps(self):
        return self.__elapsed_steps

    def should_trigger(self, increment_steps=1):
        """Determine whether the trigger condition is satisfied.
        Args:
            increment_steps: Number of steps to add since last check.
        Returns:
            True if conditions are met, False otherwise.
        """
        with self.__lock:
            current_time = datetime.now()
            self.__step_count += increment_steps

            # Handle initial call if enabled
            if self.__first_call_enabled:
                self.__last_trigger_time = current_time
                self.__last_trigger_step = self.__step_count
                self.__first_call_enabled = False
                return True

            # Update intervals
            self.__elapsed_seconds = (current_time - self.__last_trigger_time).total_seconds()
            self.__elapsed_steps = self.__step_count - self.__last_trigger_step

            # Return False if no constraints specified
            if self.time_interval is None and self.step_interval is None:
                return False

            # Check time constraint
            if self.time_interval is not None:
                if dist.is_initialized():
                    interval_tensor = torch.tensor(
                        self.__elapsed_seconds, device=current_platform.device_type
                    )
                    dist.all_reduce(
                        interval_tensor, op=dist.ReduceOp.MAX, group=self.process_group
                    )
                    self.__elapsed_seconds = interval_tensor.item()

                # Trigger if any process has exceeded the time interval
                if self.__elapsed_seconds < self.time_interval:
                    return False

            # Check step constraint
            if (
                self.step_interval is not None
                and self.__elapsed_steps < self.step_interval
            ):
                return False

            # Update trigger points
            self.__last_trigger_time = current_time
            self.__last_trigger_step = self.__step_count
            return True

    def reset_timer(self):
        self.__last_trigger_time = datetime.now()

@dataclasses.dataclass
class EpochStepTimeFreqCtl:
    epoch_freq: int | None
    step_freq: int | None
    time_freq: int | None
    group: dist.ProcessGroup | None = None

    def __post_init__(self):
        self.epoch_ctl = FrequencyControl(step_interval=self.epoch_freq)
        self.step_ctl = FrequencyControl(step_interval=self.step_freq)
        self.time_ctl = FrequencyControl(
            time_interval=self.time_freq, process_group=self.group
        )

    def check(self, epochs: int, steps: int):
        x = self.epoch_ctl.check(epochs)
        y = self.step_ctl.check(steps)
        z = self.time_ctl.check()
        return x or y or z

    def state_dict(self):
        return dict(
            epoch=self.epoch_ctl.get_state(),
            step=self.step_ctl.get_state(),
            time=self.time_ctl.get_state(),
        )

    def load_state_dict(self, state_dict):
        self.epoch_ctl.set_state(state_dict["epoch"])
        self.step_ctl.set_state(state_dict["step"])
        self.time_ctl.set_state(state_dict["time"])

@dataclasses.dataclass
class Scheduler(ABC):
    initial_value: float
    total_steps: int

    def __post_init__(self):
        if self.total_steps <= 0:
            raise ValueError("total_steps should be a positive number.")

    def evaluate(self, step: int) -> float:
        """Get the scheduled value at the current `step`."""
        if step < 0 or step > self.total_steps:
            raise ValueError(
                f"Scheduler step should be in the interval [0, {self.total_steps}]. Input {step}."
            )
        return self._evaluate(step)

    def _evaluate(self, step):
        raise NotImplementedError()

    @property
    def terminal_value(self):
        return self.evaluate(step=self.total_steps)

@dataclasses.dataclass
class ConstantScheduler(Scheduler):
    def _evaluate(self, *args, **kwargs) -> float:
        return self.initial_value

@dataclasses.dataclass
class LinearScheduler(Scheduler):
    final_value: float

    def _evaluate(self, step: int) -> float:
        return (
            self.final_value - self.initial_value
        ) / self.total_steps * step + self.initial_value

@dataclasses.dataclass
class ExponentialScheduler(Scheduler):
    decay_rate: float

    def _evaluate(self, step: int) -> float:
        return self.initial_value * self.decay_rate**step

@dataclasses.dataclass
class CosineDecayScheduler(Scheduler):
    final_value: float

    def __post_init__(self):
        super().__post_init__()
        if self.final_value >= self.initial_value:
            raise ValueError("final_value should be smaller than initial_value!")

    def _evaluate(self, step: int) -> float:
        amplitude = self.initial_value - self.final_value
        return (
            amplitude * 0.5 * (1 + math.cos(math.pi / self.total_steps * step))
            + self.final_value
        )

@dataclasses.dataclass
class ChainedScheduler:
    schedulers: list[Scheduler]

    @property
    def total_steps(self):
        return sum(x.total_steps for x in self.schedulers)

    @property
    def initial_value(self):
        return self.schedulers[0].initial_value

    @property
    def terminal_value(self):
        return self.schedulers[-1].terminal_value

    def __post_init__(self):
        for i in range(len(self.schedulers) - 1):
            # Account for floating point error tolerance
            if (
                abs(self.schedulers[i + 1].evaluate(0) - self.schedulers[i].terminal_value)
                > 1e-8
            ):
                raise ValueError(
                    f"Values should be consecutive between "
                    f"the {i}-th ({type(self.schedulers[i])}) and "
                    f"the {i + 1}-th {type(self.schedulers[i + 1])} schedulers! "
                    f"End value is {self.schedulers[i].terminal_value} and the "
                    f"next init value is {self.schedulers[i + 1].evaluate(0)}."
                )

    def evaluate(self, step: int) -> float:
        for scheduler in self.schedulers:
            if step > scheduler.total_steps:
                step -= scheduler.total_steps
            else:
                return scheduler.evaluate(step)

import grpc
from .proto import storage_pb2_grpc, storage_pb2
from .utils import init_logger
from ._checkpoint_store import (CheckpointStore, MemCopyChunk)

class StorageServicer(storage_pb2_grpc.StorageServicer):
    def __init__(
        self,
        storage_dir,
        memory_pool_capacity,
        thread_count,
        data_chunk_size,
        need_registration,
    ):
        """Initialize the storage servicer
        Args:
            storage_dir: The path to the storage directory
            memory_pool_capacity: The size of the memory pool
            thread_count: The number of threads to use
            data_chunk_size: The size of each chunk
            need_registration: Whether registration is required
        """
        self.logger = init_logger(__name__)
        self.storage_dir = storage_dir
        self.memory_pool_capacity = memory_pool_capacity
        self.thread_count = thread_count
        self.data_chunk_size = data_chunk_size
        self.need_registration = need_registration
        self.logger.info(
            f"StorageServicer: storage_dir={storage_dir}, "
            f"memory_pool_capacity={memory_pool_capacity}, thread_count={thread_count}, "
            f"data_chunk_size={data_chunk_size}, "
            f"need_registration={need_registration}"
        )
        if not CheckpointStore:
            raise ValueError("Unable to initialize CheckpointStore")
        self.storage = CheckpointStore(
            storage_dir, memory_pool_capacity, thread_count, data_chunk_size
        )
        return

    async def LoadModelAsync(self, request, context):
        model_path = request.model_path
        if not model_path:
            self.logger.error("model_path is empty")
            context.set_code(grpc.StatusCode.INVALID_ARGUMENT)
            return storage_pb2.LoadModelResponse()
        if not self.need_registration:
            model_size = self.storage.register_model_info(model_path)
            if model_size < 0:
                self.logger.error("RegisterModel failed")
                context.set_code(grpc.StatusCode.INTERNAL)
                return storage_pb2.LoadModelResponse()
        device_type = request.target_device_type
        if device_type == storage_pb2.DEVICE_TYPE_CPU:
            ret = self.storage.load_model_from_disk_async(model_path)
        elif device_type == storage_pb2.DEVICE_TYPE_GPU:
            replica_uuid = request.replica_uuid
            if not replica_uuid:
                self.logger.error("replica_uuid is empty")
                context.set_code(grpc.StatusCode.INVALID_ARGUMENT)
                return storage_pb2.LoadModelResponse()
            gpu_memory_handles = {
                device_uuid: [
                    handle.cuda_ipc_handle for handle in handle_list.handles
                ]
                for device_uuid, handle_list in request.handles.items()
            }
            def create_mem_copy_chunk(chunk):
                mem_copy_chunk = MemCopyChunk()
                mem_copy_chunk.src_offset = chunk.src_offset
                mem_copy_chunk.size = chunk.size
                mem_copy_chunk.dst_offset = chunk.dst_offset
                mem_copy_chunk.handle_idx = chunk.handle_idx
                return mem_copy_chunk
            mem_copy_chunks = {
                device_uuid: [
                    create_mem_copy_chunk(chunk) for chunk in chunk_list.chunks
                ]
                for device_uuid, chunk_list in request.chunks.items()
            }
            # self.logger.debug(
            #     f"LoadModelAsync: {model_path}, {replica_uuid}, "
            #     f"{gpu_memory_handles}, {mem_copy_chunks}"
            # )
            ret = self.storage.load_model_from_mem_async(
                model_path, replica_uuid, gpu_memory_handles, mem_copy_chunks
            )
        else:
            self.logger.error(f"Unsupported device type: {device_type}")
            context.set_code(grpc.StatusCode.UNIMPLEMENTED)
            return storage_pb2.LoadModelResponse()
        if ret != 0:
            self.logger.error("LoadModel failed")
            context.set_code(grpc.StatusCode.INTERNAL)
            return storage_pb2.LoadModelResponse()
        self.logger.info(
            f"LoadModel: success {model_path} with target {device_type}"
        )
        return storage_pb2.LoadModelResponse(model_path=model_path)

    async def ConfirmModel(self, request, context):
        model_path = request.model_path
        replica_uuid = request.replica_uuid
        device_type = request.target_device_type
        if not model_path:
            self.logger.error("model_path is empty")
            context.set_code(grpc.StatusCode.INVALID_ARGUMENT)
            return storage_pb2.ConfirmModelResponse()
        if device_type != storage_pb2.DEVICE_TYPE_GPU:
            self.logger.error(f"Unsupported device type: {device_type}")
            context.set_code(grpc.StatusCode.UNIMPLEMENTED)
            return storage_pb2.ConfirmModelResponse()
        for attempt in range(10):  # Increase retries for large models like PaliGemma
            try:
                ret = self.storage.wait_model_in_gpu(model_path, replica_uuid)
                if ret == 0:
                    self.logger.info(
                        f"Confirm model {model_path} replica {replica_uuid} success"
                    )
                    return storage_pb2.ConfirmModelResponse(model_path=model_path)
                elif ret == 1:
                    self.logger.warning(f"Model {model_path} replica {replica_uuid} is interrupted")
                    context.set_code(grpc.StatusCode.INTERNAL)
                    return storage_pb2.ConfirmModelResponse()
                else:
                    self.logger.warning(f"Confirm model failed with ret={ret}, retry {attempt + 1}")
            except Exception as e:
                self.logger.error(f"Exception in wait_model_in_gpu: {e}")
                if attempt == 19:  # Last retry
                    raise
            await asyncio.sleep(0.1)  # Longer sleep for stability
        self.logger.error(
            f"Confirm model {model_path} replica {replica_uuid} failed"
        )
        context.set_code(grpc.StatusCode.INTERNAL)
        return storage_pb2.ConfirmModelResponse()

    async def UnloadModel(self, request, context):
        model_path = request.model_path
        device_type = request.target_device_type
        if not model_path:
            self.logger.error("model_path is empty")
            context.set_code(grpc.StatusCode.INVALID_ARGUMENT)
            return storage_pb2.UnloadModelResponse()
        if device_type != storage_pb2.DEVICE_TYPE_CPU:
            self.logger.error(f"Unsupported device type: {device_type}")
            context.set_code(grpc.StatusCode.UNIMPLEMENTED)
            return storage_pb2.UnloadModelResponse()
        for attempt in range(5):
            ret = self.storage.unload_model_from_host(model_path)
            if ret == 0:
                self.logger.info(f"UnloadModel: success {model_path}")
                return storage_pb2.UnloadModelResponse(model_path=model_path)
            self.logger.info(f"UnloadModel failed, retry {attempt + 1}")
            await asyncio.sleep(0.01)
        self.logger.error(f"UnloadModel failed for model {model_path}")
        context.set_code(grpc.StatusCode.INTERNAL)
        return storage_pb2.UnloadModelResponse()

    async def ClearMem(self, request, context):
        ret = self.storage.clear_mem()
        if ret != 0:
            self.logger.error("ClearMem failed")
            context.set_code(grpc.StatusCode.INTERNAL)
        return storage_pb2.ClearMemResponse()

    async def RegisterModel(self, request, context):
        model_path = request.model_path
        if not model_path:
            self.logger.error("model_path is empty")
            context.set_code(grpc.StatusCode.INVALID_ARGUMENT)
            return storage_pb2.RegisterModelResponse()
        model_size = self.storage.register_model_info(model_path)
        if model_size < 0:
            self.logger.error("RegisterModel failed")
            context.set_code(grpc.StatusCode.INTERNAL)
            return storage_pb2.RegisterModelResponse()
        return storage_pb2.RegisterModelResponse(
            model_path=model_path, model_size=model_size
        )

    async def GetServerConfig(self, request, context):
        return storage_pb2.GetServerConfigResponse(
            mem_pool_size=self.storage.get_mem_pool_size(),
            chunk_size=self.storage.get_chunk_size(),
        )

