import jsonlines
import numpy as np
from tqdm import tqdm

# Configuration constants
DOC_STRIDE = 2048
MAX_SEQ_LEN = 4096
RANDOM_SEED = 42
TRAINING_MODE = os.environ.pop("PROCESS_TRAIN", "false")

# Category mapping for classification labels
LABEL_MAP = {"null": 0, "short": 1, "long": 2, "yes": 3, "no": 4}

def extract_single_answer(sample):
    def select_first_option(ans_list, is_long=False):
        assert isinstance(ans_list, list), "Expected list input"
        if len(ans_list) == 1:
            item = ans_list[0]
            return {field: [item[field]] for field in item} if is_long else item
        for candidate in ans_list:
            if is_long:
                candidate = {field: [candidate[field]] for field in candidate}
            if len(candidate["start_token"]) > 0:
                break
        return candidate

    result = {"id": sample["id"]}
    annot = sample["annotations"]
    yes_no_flags = annot["yes_no_answer"]

    if 0 in yes_no_flags or 1 in yes_no_flags:
        result["category"] = ["yes"] if 1 in yes_no_flags else ["no"]
        result["start_token"] = result["end_token"] = []
        result["start_byte"] = result["end_byte"] = []
        result["text"] = ["<cls>"]
    else:
        result["category"] = ["short"]
        selected = select_first_option(annot["short_answers"])
        if len(selected["start_token"]) == 0:
            # Fall back to long answer when short answer unavailable
            result["category"] = ["long"]
            selected = select_first_option(annot["long_answer"], is_long=True)
            selected["text"] = []
        result.update(selected)

    # Filter out problematic samples
    if len(result["start_token"]) > 1 or result["start_token"] == result["end_token"]:
        result["skip_flag"] = True
    else:
        result["skip_flag"] = False

    required_fields = ["start_token", "end_token", "start_byte", "end_byte", "text"]
    if not all(isinstance(result[field], list) for field in required_fields):
        raise ValueError("Data integrity issue in ID", sample["id"])

    return result


def build_context_and_labels(sample, validate=False):
    """Constructs cleaned context and adjusted answer positions"""
    answer_data = extract_single_answer(sample)

    # Remove byte-level annotations (not needed)
    del answer_data["start_byte"]
    del answer_data["end_byte"]

    # Handle special cases: yes/no answers
    if answer_data["category"][0] in ["yes", "no"]:
        doc_tokens = sample["document"]["tokens"]
        clean_context = []
        for idx in range(len(doc_tokens["token"])):
            if not doc_tokens["is_html"][idx]:
                clean_context.append(doc_tokens["token"][idx])

        return {
            "context": " ".join(clean_context),
            "answer": {
                "start_token": -100,
                "end_token": -100,
                "category": answer_data["category"],
                "span": answer_data["category"],
            },
        }

    # Handle null/no-answer case
    if answer_data["start_token"] == [-1]:
        return {
            "context": "None",
            "answer": {
                "start_token": -1,
                "end_token": -1,
                "category": "null",
                "span": "None",
            },
        }

    # Process standard short/long answers
    token_fields = ["start_token", "end_token"]
    answer_data.update({
        field: answer_data[field][0] if len(answer_data[field]) > 0 else answer_data[field]
        for field in token_fields
    })

    doc = sample["document"]["tokens"]
    start_idx = answer_data["start_token"]
    end_idx = answer_data["end_token"]

    clean_tokens = []
    for i in range(len(doc["token"])):
        if not doc["is_html"][i]:
            clean_tokens.append(doc["token"][i])
        else:
            # Adjust indices due to HTML removal
            if answer_data["start_token"] > i:
                start_idx -= 1
            if answer_data["end_token"] > i:
                end_idx -= 1

    span_text = " ".join(clean_tokens[start_idx:end_idx])

    # Optional validation step
    if validate:
        html_mask = doc["is_html"][answer_data["start_token"]:answer_data["end_token"]]
        original_tokens = doc["token"][answer_data["start_token"]:answer_data["end_token"]]
        original_text = " ".join([original_tokens[i] for i in range(len(original_tokens)) if not html_mask[i]])
        if span_text != original_text:
            print("ID:", sample["id"])
            print("New:", span_text)
            print("Original:", original_text, end="\n\n")

    return {
        "context": " ".join(clean_tokens),
        "answer": {
            "start_token": start_idx,
            "end_token": end_idx - 1,
            "category": answer_data["category"],
            "span": span_text,
        },
    }


def create_sliding_window_inputs(sample, tokenizer, window_overlap=2048, seq_limit=4096, debug_mode=True):
    base_result = build_context_and_labels(sample, validate=debug_mode)
    answer_info = base_result["answer"]

    # Skip invalid cases
    if answer_info["start_token"] == -1:
        return {
            "example_id": sample["id"],
            "input_ids": [[-1]],
            "labels": {
                "start_token": [-1],
                "end_token": [-1],
                "category": ["null"],
            },
        }

    # Tokenize question + context
    tokenized = tokenizer(sample["question"]["text"], base_result["context"])
    input_ids = tokenized.input_ids
    q_end_pos = input_ids.index(tokenizer.sep_token_id) + 1

    # Handle yes/no questions with sliding windows
    if answer_info["category"][0] in ["yes", "no"]:
        inputs_batch = []
        categories_batch = []
        q_part = input_ids[:q_end_pos]

        for doc_start in range(q_end_pos, len(input_ids), seq_limit - window_overlap):
            doc_end = doc_start + seq_limit - q_end_pos
            doc_part = input_ids[doc_start:doc_end]
            inputs_batch.append(q_part + doc_part)
            categories_batch.append(answer_info["category"][0])

            if doc_part[-1] == tokenizer.sep_token_id:
                break

        return {
            "example_id": sample["id"],
            "input_ids": inputs_batch,
            "labels": {
                "start_token": [-100] * len(categories_batch),
                "end_token": [-100] * len(categories_batch),
                "category": categories_batch,
            },
        }

    # Process short/long answers
    context_words = base_result["context"].split()
    full_end_word = context_words[answer_info["end_token"]]

    # Convert word indices to token indices
    answer_info["start_token"] = len(
        tokenizer(
            " ".join(context_words[:answer_info["start_token"]]),
            add_special_tokens=False
        ).input_ids
    )
    answer_info["end_token"] = len(
        tokenizer(
            " ".join(context_words[:answer_info["end_token"]]),
            add_special_tokens=False
        ).input_ids
    )

    # Adjust for multi-token words
    answer_info["start_token"] += q_end_pos
    answer_info["end_token"] += q_end_pos

    num_subtokens = len(tokenizer(full_end_word, add_special_tokens=False).input_ids)
    if num_subtokens > 1:
        answer_info["end_token"] += num_subtokens - 1

    # Extract original span for verification
    original_span_ids = input_ids[answer_info["start_token"]:answer_info["end_token"]+1]
    start_pos = answer_info["start_token"]
    end_pos = answer_info["end_token"]

    if debug_mode:
        reconstructed = tokenizer.decode(original_span_ids)
        if answer_info["span"] != reconstructed:
            print("TOKENIZATION MISMATCH DETECTED")
            print("EXPECTED:", answer_info["span"])
            print("GOT:", reconstructed, end="\n\n")

    # Handle short sequences without splitting
    if len(input_ids) <= seq_limit:
        return {
            "example_id": sample["id"],
            "input_ids": [input_ids],
            "labels": {
                "start_token": [answer_info["start_token"]],
                "end_token": [answer_info["end_token"]],
                "category": answer_info["category"],
            },
        }

    # Sliding window for long sequences
    q_segment = input_ids[:q_end_pos]
    doc_starts = range(q_end_pos, len(input_ids), seq_limit - window_overlap)

    batch_inputs = []
    batch_starts = []
    batch_ends = []
    batch_cats = []

    for doc_start in doc_starts:
        doc_end = doc_start + seq_limit - q_end_pos
        doc_segment = input_ids[doc_start:doc_end]
        combined = q_segment + doc_segment
        assert len(combined) <= seq_limit, f"Sequence length exceeded at {sample['id']}"

        if start_pos >= doc_start and end_pos <= doc_end - 1:
            adjusted_start = start_pos - doc_start + q_end_pos
            adjusted_end = end_pos - doc_start + q_end_pos
            batch_cats.append(answer_info["category"][0])
        else:
            adjusted_start = -100
            adjusted_end = -100
            batch_cats.append("null")

        current_span = combined[adjusted_start:adjusted_end+1]
        batch_inputs.append(combined)
        batch_starts.append(adjusted_start)
        batch_ends.append(adjusted_end)

        if debug_mode:
            decoded = tokenizer.decode(current_span)
            if decoded != tokenizer.decode(original_span_ids) and decoded != tokenizer.cls_token:
                print("SLIDING WINDOW ISSUE for ID:", sample["id"])
                print("EXPECTED:", tokenizer.decode(original_span_ids))
                print("ACTUAL:", decoded, end="\n\n")

        if doc_segment[-1] == tokenizer.sep_token_id:
            break

    return {
        "example_id": sample["id"],
        "input_ids": batch_inputs,
        "labels": {
            "start_token": batch_starts,
            "end_token": batch_ends,
            "category": batch_cats,
        },
    }


def prepare_final_inputs(example, tokenizer, window_overlap=2048, max_seq_len=4096, enable_debug=False):
    return create_sliding_window_inputs(
        example,
        tokenizer,
        window_overlap=window_overlap,
        seq_limit=max_seq_len,
        debug_mode=enable_debug
    )


def persist_to_file(dataset, output_path):
    with jsonlines.open(output_path, mode="a") as writer:
        for item in tqdm(dataset, total=len(dataset), desc="Writing processed samples"):
            labels = item["labels"]
            for ids, begin, finish, cat in zip(
                item["input_ids"],
                labels["start_token"],
                labels["end_token"],
                labels["category"],
            ):
                if begin == -1 and finish == -1:
                    continue  # Skip empty answers

                if cat == "null" and np.random.rand() < 0.6:
                    continue  # Downsample null examples

                writer.write({
                    "input_ids": ids,
                    "start_token": begin,
                    "end_token": finish,
                    "category": LABEL_MAP[cat],
                })


if __name__ == "__main__":
    from datasets import load_dataset
    from transformers import BigBirdTokenizer

    dataset = load_dataset("natural_questions")
    tokenizer = BigBirdTokenizer.from_pretrained("google/bigbird-roberta-base")

    split_name = "train" if TRAINING_MODE == "true" else "validation"
    dataset = dataset[split_name]

    processing_args = {
        "tokenizer": tokenizer,
        "window_overlap": DOC_STRIDE,
        "max_seq_len": MAX_SEQ_LEN,
        "enable_debug": False,
    }

    processed = dataset.map(prepare_final_inputs, fn_kwargs=processing_args)
    processed = processed.remove_columns(["annotations", "document", "id", "question"])
    print(processed)

    np.random.seed(RANDOM_SEED)
    output_file = "nq-training.jsonl" if TRAINING_MODE == "true" else "nq-validation.jsonl"
    persist_to_file(processed, output_file=output_file)

# Custom tool registry implementation using MutableMapping
from collections.abc import MutableMapping
from typing import Annotated, Any, Generic, Literal, TypeVar
from langchain_core.tools import BaseTool, InjectedToolArg
from pydantic import BaseModel, Field
from statgpt.app.schemas import ToolArtifact
from statgpt.common.schemas import BaseToolConfig, ChannelConfig, ToolTypes

class ToolRegistry(MutableMapping):
    def __init__(self) -> None:
        self._registry: dict[ToolTypes, type[StatGptTool]] = {}

    def __setitem__(self, tool_type: ToolTypes, factory: type['StatGptTool']) -> None:
        if not issubclass(factory, StatGptTool):
            raise ValueError(f"{factory=} must be a subclass of {StatGptTool}")
        if tool_type in self._registry:
            raise ValueError(
                f"Cannot register {factory} factory:"
                f" {tool_type=} already registered with {self._registry[tool_type]}"
            )
        self._registry[tool_type] = factory

    def __delitem__(self, tool_type: ToolTypes, /) -> None:
        del self._registry[tool_type]

    def __getitem__(self, key: ToolTypes) -> type['StatGptTool']:
        if key not in self._registry:
            raise KeyError(
                f"Factory has not been registered for {key} agent."
                f" Please ensure that the factory is imported in the global space."
                f"\nAvailable agents: {list(self._registry.keys())}"
            )
        return self._registry[key]

    def __iter__(self):
        return iter(self._registry)

    def __len__(self):
        return len(self._registry)

_TOOL_IMPLEMENTATIONS = ToolRegistry()

class ToolArgs(BaseModel):
    # injected tool argument. set in the code, not by the LLM.
    # LLM can't set this field because it's not added to the tool schema shown to LLM.
    # `inputs` is used to pass execution context from Supreme Agent to the tool.
    inputs: Annotated[dict, InjectedToolArg] = Field()

ToolConfigType = TypeVar('ToolConfigType', bound=BaseToolConfig)

class StatGptTool(BaseTool, ABC, Generic[ToolConfigType]):
    response_format: Literal['content', 'content_and_artifact'] = "content_and_artifact"
    tool_type: ToolTypes  # Set dynamically in __init_subclass__

    def __init_subclass__(cls, **kwargs):
        tool_type = kwargs.pop('tool_type', None)
        super().__init_subclass__(**kwargs)
        if StatGptTool in cls.__bases__:
            # we want to register tool instance (like DataQueryTool),
            # not generic itself (like StatGptTool[DataQueryToolConfig])
            return
        if tool_type is None:
            raise ValueError(f"Subclass {cls.__name__} must specify a 'tool_type' parameter")
        if not isinstance(tool_type, ToolTypes):
            raise ValueError(f"{tool_type=} must be an instance of {ToolTypes}")
        cls.tool_type = tool_type
        _TOOL_IMPLEMENTATIONS[tool_type] = cls

    def __init__(self, tool_config: ToolConfigType, channel_config: ChannelConfig, **kwargs):
        super().__init__(**kwargs)
        self._tool_config = tool_config
        self._channel_config = channel_config

    @property
    def stage_name(self) -> str:
        """Return the stage name of calling this tool."""
        if name := self._tool_config.details.stages_config.tool_call_name:
            return name
        tool_name = self.name.replace('_', ' ')
        return f"Executing {tool_name} tool"

    @property
    def result_stage_name(self) -> str:
        """Return the stage name of showing the result of this tool."""
        if name := self._tool_config.details.stages_config.tool_result_name:
            return name
        tool_name = self.name.replace('_', ' ')
        return f"Output from {tool_name} tool"

    def _run(self, *args: Any, **kwargs: Any) -> Any:
        """This method is implemented to satisfy the BaseTool interface.
        But it raises an error since we don't want to use it."""
        raise NotImplementedError("This method should not be called. Use async version instead.")

    @abstractmethod
    async def _arun(self, *args: Any, **kwargs: Any) -> tuple[str, ToolArtifact]:
        pass

    @classmethod
    def get_args_schema(cls, tool_config: ToolConfigType) -> type[ToolArgs]:
        """Return the schema for the arguments that this tool accepts."""
        return ToolArgs

    @staticmethod
    def from_config(tool_config: ToolConfigType, channel_config: ChannelConfig) -> 'StatGptTool':
        cls = _TOOL_IMPLEMENTATIONS[tool_config.type]
        return cls(
            tool_config=tool_config,
            channel_config=channel_config,
            name=tool_config.name,
            description=tool_config.description,
            args_schema=cls.get_args_schema(tool_config),
        )

import logging
import html
from typing import Any, cast
from graspologic.partition import hierarchical_leiden
from graspologic.utils import largest_connected_component
import networkx as nx
from networkx import is_empty

def _stabilize_graph(original_graph: nx.Graph) -> nx.Graph:
    """Ensure an undirected graph with the same relationships will always be read the same way."""
    stable_graph = nx.DiGraph() if original_graph.is_directed() else nx.Graph()
    ordered_nodes = original_graph.nodes(data=True)
    ordered_nodes = sorted(ordered_nodes, key=lambda item: item[0])
    stable_graph.add_nodes_from(ordered_nodes)
    edge_list = list(original_graph.edges(data=True))

    # For undirected graphs, normalize edge direction to ensure stability
    if not original_graph.is_directed():
        def _normalize_edge(edge_data):
            src, dst, attrs = edge_data
            if src > dst:
                src, dst = dst, src
            return src, dst, attrs
        edge_list = [_normalize_edge(edge) for edge in edge_list]

    def _edge_identifier(source: Any, target: Any) -> str:
        return f"{source} -> {target}"

    edge_list = sorted(edge_list, key=lambda x: _edge_identifier(x[0], x[1]))
    stable_graph.add_edges_from(edge_list)
    return stable_graph

def standardize_node_labels(graph: nx.Graph | nx.DiGraph) -> nx.Graph | nx.DiGraph:
    """Standardize node names."""
    label_mapping = {node: html.unescape(node.upper().strip()) for node in graph.nodes()}  # type: ignore
    return nx.relabel_nodes(graph, label_mapping)

def robust_largest_connected_subgraph(graph: nx.Graph) -> nx.Graph:
    """Return the largest connected component of the graph, with nodes and edges sorted in a stable way."""
    working_graph = graph.copy()
    working_graph = cast(nx.Graph, largest_connected_component(working_graph))
    working_graph = standardize_node_labels(working_graph)
    return _stabilize_graph(working_graph)

def _calculate_leiden_partitions(
        input_graph: nx.Graph | nx.DiGraph,
        cluster_limit: int,
        apply_lcc: bool,
        seed_value=0xDEADBEEF,
) -> dict[int, dict[str, int]]:
    """Return Leiden root community assignments."""
    partition_results: dict[int, dict[str, int]] = {}
    if is_empty(input_graph):
        return partition_results

    if apply_lcc:
        input_graph = robust_largest_connected_subgraph(input_graph)

    community_assignment = hierarchical_leiden(
        input_graph, max_cluster_size=cluster_limit, random_seed=seed_value
    )

    for assignment in community_assignment:
        level = assignment.level
        partition_results[level] = partition_results.get(level, {})
        partition_results[level][assignment.node] = assignment.cluster
    return partition_results

def execute(graph: nx.Graph, parameters: dict[str, Any]) -> dict[int, dict[str, dict]]:
    """Execution method definition."""
    cluster_limit = parameters.get("max_cluster_size", 12)
    apply_lcc = parameters.get("use_lcc", True)

    if parameters.get("verbose", False):
        logging.debug(
            "Executing leiden clustering with max_cluster_size=%s, lcc=%s", cluster_limit, apply_lcc
        )

    node_set = set(graph.nodes())
    if not node_set:
        return {}

    community_mapping = _calculate_leiden_partitions(
        graph=graph,
        cluster_limit=cluster_limit,
        apply_lcc=apply_lcc,
        seed_value=parameters.get("seed", 0xDEADBEEF),
    )

    selected_levels = parameters.get("levels")
    if selected_levels is None:
        selected_levels = sorted(community_mapping.keys())

    output_by_level: dict[int, dict[str, dict[str, int | list]]] = {}
    for level in selected_levels:
        level_result = {}
        output_by_level[level] = level_result

        for node_id, raw_cluster_id in community_mapping[level].items():
            if node_id not in node_set:
                logging.warning(f"Node {node_id} not found in the graph.")
                continue

            cluster_label = str(raw_cluster_id)
            if cluster_label not in level_result:
                level_result[cluster_label] = {"weight": 0, "nodes": []}

            level_result[cluster_label]["nodes"].append(node_id)
            rank_val = graph.nodes[node_id].get("rank", 0)
            weight_val = graph.nodes[node_id].get("weight", 1)
            level_result[cluster_label]["weight"] += rank_val * weight_val

        weights_list = [comm["weight"] for _, comm in level_result.items()]
        if not weights_list:
            continue

        highest_weight = max(weights_list)
        if highest_weight == 0:
            continue

        for _, community in level_result.items():
            community["weight"] /= highest_weight

    return output_by_level

def integrate_communities_into_graph(graph: nx.Graph, member_nodes: list[str], group_name):
    for node in member_nodes:
        if "communities" not in graph.nodes[node]:
            graph.nodes[node]["communities"] = []
        graph.nodes[node]["communities"].append(group_name)
        graph.nodes[node]["communities"] = list(set(graph.nodes[node]["communities"]))

import re
from abc import ABC
from typing import Union, Type, NoReturn, Any
from app.core.workflow.engine.variable_pool import VariablePool
from app.core.workflow.nodes.enums import ValueInputType
from app.core.workflow.variable.base_variable import VariableType

class TypeConverter:
    @classmethod
    def _error(cls, value, target) -> NoReturn:
        raise TypeError(f"Unable to transform {value!r} into {target} type")

    @classmethod
    def _deserialize_json(cls, value, target):
        try:
            import json
            return json.loads(value)
        except Exception:
            cls._error(value, target)

    @classmethod
    def convert(cls, literal_value: str | bool, desired_type: VariableType):
        match desired_type:
            case VariableType.STRING:
                return str(literal_value)
            case VariableType.NUMBER:
                for converter in (int, float):
                    try:
                        return converter(literal_value)
                    except Exception:
                        continue
                cls._error(literal_value, desired_type)
            case VariableType.BOOLEAN:
                if isinstance(literal_value, bool):
                    return literal_value
                cls._error(literal_value, desired_type)
            case VariableType.OBJECT:
                obj = cls._deserialize_json(literal_value, desired_type)
                if isinstance(obj, dict):
                    return obj
                cls._error(literal_value, desired_type)
            case VariableType.ARRAY_BOOLEAN:
                return cls._convert_list(literal_value, bool, desired_type)
            case VariableType.ARRAY_NUMBER:
                return cls._convert_list(literal_value, (int, float), desired_type)
            case VariableType.ARRAY_STRING:
                return cls._convert_list(literal_value, str, desired_type)
            case VariableType.ARRAY_OBJECT:
                return cls._convert_list(literal_value, dict, desired_type)
            case _:
                raise TypeError("Unsupported type specified")

    @classmethod
    def _convert_list(cls, value, item_type, target):
        arr = cls._deserialize_json(value, target)
        if isinstance(arr, list) and all(isinstance(item, item_type) for item in arr):
            return arr
        cls._error(value, target)

class BaseOperator(ABC):
    def __init__(self, pool: VariablePool, left_path: str, right_value: Any):
        self.pool = pool
        self.left_path = left_path
        self.right_value = right_value
        self.allowed_types: type[str, int, dict, list] = None

    def validate(self, skip_right=False):
        left_val = self.pool.get_value(self.left_path)
        if not isinstance(left_val, self.allowed_types):
            raise TypeError(f"The operand must be of {self.allowed_types} type")
        if not skip_right and not isinstance(self.right_value, self.allowed_types):
            raise TypeError(
                f"The assigned value must be of {self.allowed_types} type"
            )

class StringHandler(BaseOperator):
    def __init__(self, pool: VariablePool, left_path, right_value):
        super().__init__(pool, left_path, right_value)
        self.allowed_types = str

    async def set_value(self) -> None:
        self.validate()
        await self.pool.set(self.left_path, self.right_value)

    async def reset(self) -> None:
        self.validate(skip_right=True)
        await self.pool.set(self.left_path, '')

class NumericHandler(BaseOperator):
    def __init__(self, pool: VariablePool, left_path, right_value):
        super().__init__(pool, left_path, right_value)
        self.allowed_types = (float, int)

    async def set_value(self) -> None:
        self.validate()
        await self.pool.set(self.left_path, self.right_value)

    async def reset(self) -> None:
        self.validate(skip_right=True)
        await self.pool.set(self.left_path, 0)

    async def increment(self) -> None:
        self.validate()
        current = self.pool.get_value(self.left_path)
        await self.pool.set(self.left_path, current + self.right_value)

    async def decrement(self) -> None:
        self.validate()
        current = self.pool.get_value(self.left_path)
        await self.pool.set(self.left_path, current - self.right_value)

    async def multiply(self) -> None:
        self.validate()
        current = self.pool.get_value(self.left_path)
        await self.pool.set(self.left_path, current * self.right_value)

    async def divide(self) -> None:
        self.validate()
        current = self.pool.get_value(self.left_path)
        await self.pool.set(self.left_path, current / self.right_value)

class BooleanHandler(BaseOperator):
    def __init__(self, pool: VariablePool, left_path, right_value):
        super().__init__(pool, left_path, right_value)
        self.allowed_types = bool

    async def set_value(self) -> None:
        self.validate()
        await self.pool.set(self.left_path, self.right_value)

    async def reset(self) -> None:
        self.validate(skip_right=True)
        await self.pool.set(self.left_path, False)

class ArrayHandler(BaseOperator):
    def __init__(self, pool: VariablePool, left_path, right_value):
        super().__init__(pool, left_path, right_value)
        self.allowed_types = list

    async def set_value(self) -> None:
        self.validate()
        await self.pool.set(self.left_path, self.right_value)

    async def reset(self) -> None:
        self.validate(skip_right=True)
        await self.pool.set(self.left_path, [])

    async def push(self) -> None:
        self.validate(skip_right=True)
        current = self.pool.get_value(self.left_path)
        current.append(self.right_value)
        await self.pool.set(self.left_path, current)

    async def extend(self) -> None:
        self.validate(skip_right=True)
        current = self.pool.get_value(self.left_path)
        current.extend(self.right_value)
        await self.pool.set(self.left_path, current)

    async def pop_last(self) -> None:
        self.validate(skip_right=True)
        current = self.pool.get_value(self.left_path)
        current.pop()
        await self.pool.set(self.left_path, current)

    async def pop_first(self) -> None:
        self.validate(skip_right=True)
        current = self.pool.get_value(self.left_path)
        current.pop(0)
        await self.pool.set(self.left_path, current)

class DictionaryHandler(BaseOperator):
    def __init__(self, pool: VariablePool, left_path, right_value):
        super().__init__(pool, left_path, right_value)
        self.allowed_types = dict

    async def set_value(self) -> None:
        self.validate()
        await self.pool.set(self.left_path, self.right_value)

    async def reset(self) -> None:
        self.validate(skip_right=True)
        await self.pool.set(self.left_path, {})

class OperatorFactory:
    OPERATOR_TABLE = {
        str: StringHandler,
        bool: BooleanHandler,
        int: NumericHandler,
        float: NumericHandler,
        list: ArrayHandler,
        dict: DictionaryHandler,
    }

    @classmethod
    def get_operator(cls, value):
        for typ, handler in cls.OPERATOR_TABLE.items():
            if isinstance(value, typ):
                return handler
        raise TypeError(f"Unsupported variable type: {type(value)}")

AssignmentOperatorInstance = Union[
    StringHandler,
    NumericHandler,
    BooleanHandler,
    ArrayHandler,
    DictionaryHandler
]
AssignmentOperatorClass = Type[AssignmentOperatorInstance]

class BaseCondition(ABC):
    allowed_types: type[str, int, dict, list] = None

    def __init__(
            self,
            pool: VariablePool,
            left_path,
            right_path: str,
            input_mode: ValueInputType
    ):
        self.pool = pool
        self.left_path = left_path
        self.right_path = right_path
        self.input_mode = input_mode
        self.left_value = self.pool.get_value(self.left_path)
        self.right_value = self.resolve_right_literal()
        self.allowed_types = getattr(self, "allowed_types", None)

    def resolve_right_literal(self):
        if self.input_mode == ValueInputType.VARIABLE:
            pattern = r"\{\{\s*(.*?)\s*\}\}"
            cleaned_expression = re.sub(pattern, r"\1", self.right_path).strip()
            return self.pool.get_value(cleaned_expression)
        elif self.input_mode == ValueInputType.CONSTANT:
            return self.right_path
        raise RuntimeError("Unsupported variable type")

    def validate(self, skip_right=False):
        if not isinstance(self.left_value, self.allowed_types):
            raise TypeError(f"The comparison operand must be of {self.allowed_types} type")
        if not skip_right:
            right_val = self.resolve_right_literal()
            if not isinstance(right_val, self.allowed_types):
                raise TypeError(
                    f"The compared value must be of {self.allowed_types} type"
                )

class StringCondition(BaseCondition):
    allowed_types = str

    def __init__(self, pool: VariablePool, left_path, right_path, input_mode):
        super().__init__(pool, left_path, right_path, input_mode)

    def is_empty(self):
        self.validate(skip_right=True)
        return self.left_value == ""

    def is_not_empty(self):
        return not self.is_empty()

    def includes(self):
        self.validate()
        return self.right_value in self.left_value

    def excludes(self):
        return self.right_value not in self.left_value

    def begins_with(self):
        self.validate()
        return self.left_value.startswith(self.right_value)

    def ends_with(self):
        return self.left_value.endswith(self.right_value)

    def equals(self):
        return self.left_value == self.right_value

    def not_equals(self):
        return self.left_value != self.right_value

class NumberCondition(BaseCondition):
    allowed_types = (int, float)

    def __init__(self, pool: VariablePool, left_path, right_path, input_mode):
        super().__init__(pool, left_path, right_path, input_mode)

    def is_zero(self):
        return self.left_value == 0

    def is_nonzero(self):
        return self.left_value != 0

    def equals(self):
        return self.left_value == self.right_value

    def not_equals(self):
        return self.left_value != self.right_value

    def less_than(self):
        return self.left_value < self.right_value

    def less_or_equal(self):
        return self.left_value <= self.right_value

    def greater_than(self):
        return self.left_value > self.right_value

    def greater_or_equal(self):
        return self.left_value >= self.right_value

class BooleanCondition(BaseCondition):
    allowed_types = bool

    def __init__(self, pool: VariablePool, left_path, right_path, input_mode):
        super().__init__(pool, left_path, right_path, input_mode)

    def equals(self):
        return self.left_value == self.right_value

    def not_equals(self):
        return self.left_value != self.right_value

class DictionaryCondition(BaseCondition):
    allowed_types = dict

    def __init__(self, pool: VariablePool, left_path, right_path, input_mode):
        super().__init__(pool, left_path, right_path, input_mode)

    def equals(self):
        return self.left_value == self.right_value

    def not_equals(self):
        return self.left_value != self.right_value

    def is_empty(self):
        return not self.left_value

    def is_not_empty(self):
        return bool(self.left_value)

class ArrayCondition(BaseCondition):
    allowed_types = list

    def __init__(self, pool: VariablePool, left_path, right_path, input_mode):
        super().__init__(pool, left_path, right_path, input_mode)

    def is_empty(self):
        return not self.left_value

    def is_not_empty(self):
        return bool(self.left_value)

    def includes(self):
        return self.right_value in self.left_value

    def excludes(self):
        return self.right_value not in self.left_value

class NullCondition:
    def __init__(self, *args, **kwargs):
        pass

    def __getattr__(self, name):
        return lambda *args, **kwargs: False

CompareOperatorInstance = Union[
    StringCondition,
    NumberCondition,
    BooleanCondition,
    ArrayCondition,
    DictionaryCondition
]
CompareOperatorClass = Type[CompareOperatorInstance]

class ConditionFactory:
    CONDITION_TABLE = {
        str: StringCondition,
        bool: BooleanCondition,
        int: NumberCondition,
        float: NumberCondition,
        list: ArrayCondition,
        dict: DictionaryCondition,
        type(None): NullCondition
    }

    @classmethod
    def get_condition(cls, value) -> CompareOperatorClass:
        for typ, handler in cls.CONDITION_TABLE.items():
            if isinstance(value, typ):
                return handler
        raise TypeError(f"Unsupported variable type: {type(value)}")

