from typing import Any, Optional
import logging
import sys
import time

# --- OS-Specific Imports with error handling ---
if sys.platform == 'win32':
    try:
        import win32gui
        import win32con
        import win32process
        import ctypes
    except ImportError:
        print("Please run 'pip install pywin32' for Windows-specific functionality.")
        sys.exit(1)

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
hidden_offset = [0, 3000]

# --- OS-Specific Helper Code ---
def check_admin_privileges() -> bool:
    """Determines if the current process is running with Administrator rights (Windows only)."""
    if sys.platform == 'win32':
        try:
            return ctypes.windll.shell32.IsUserAnAdmin() != 0
        except Exception:
            return False
    return False

def _locate_window_by_process_id(target_pid: int) -> Optional[int]:
    """Search through all top-level windows to find one associated with the given PID."""
    matched_hwnd = None

    def window_enum_callback(hwnd, _):
        nonlocal matched_hwnd
        # Skip invisible windows and child windows
        if not win32gui.IsWindowVisible(hwnd) or win32gui.GetParent(hwnd) != 0:
            return True
        _, process_id = win32process.GetWindowThreadProcessId(hwnd)
        if process_id == target_pid:
            matched_hwnd = hwnd
            return False
        return True

    win32gui.EnumWindows(window_enum_callback, None)
    return matched_hwnd

class WindowVisibilityController:
    """
    Context manager to control window visibility for GUI automation by PID.
    Designed primarily for Windows environments.
    """
    def __init__(self, pid: int):
        if sys.platform != 'win32':
            logging.info("Window visibility control is only available on Windows.")
        self.process_id = pid
        self.window_handle = None
        self.previous_placement = None

    def __enter__(self):
        if sys.platform != 'win32':
            return self  # No-op on non-Windows platforms

        logging.info(f"Attempting to manage visibility for window with PID: {self.process_id}")
        self.window_handle = _locate_window_by_process_id(self.process_id)

        if not self.window_handle:
            logging.warning(f"Could not locate window for PID {self.process_id}. Visibility management skipped.")
            return self

        logging.info(f"Located window handle (HWND): {self.window_handle}.")
        try:
            self.previous_placement = win32gui.GetWindowPlacement(self.window_handle)

            logging.info("Temporarily repositioning window to (0,0) for interaction.")
            win32gui.SetWindowPlacement(self.window_handle, (0, 1, (-1, -1), (-1, -1), (0, 0, 800, 600)))
            win32gui.SetForegroundWindow(self.window_handle)
            time.sleep(0.4)
        except win32gui.error as e:
            logging.error(f"Error during window manipulation: {e}. The window may have been closed.")
            self.window_handle = None

        return self

    def __exit__(self, exc_type, exc_value, exc_tb):
        if sys.platform != 'win32':
            return  # No-op on non-Windows platforms

        if self.window_handle and self.previous_placement:
            logging.info("Restoring window to its original position...")
            try:
                hide_window_by_pid(self.process_id)
            except win32gui.error:
                logging.warning(f"Failed to restore window position for HWND {self.window_handle}, it may no longer exist.")

def hide_window_by_pid(pid: int):
    """Moves a window off-screen using its PID (Windows-only)."""
    if sys.platform == 'win32':
        hwnd = _locate_window_by_process_id(pid)
        if hwnd:
            logging.info(f"Located window handle (HWND): {hwnd}. Relocating off-screen.")
            win32gui.ShowWindow(hwnd, win32con.SW_RESTORE)
            win32gui.SetWindowPos(
                hwnd, 0, hidden_offset[0], hidden_offset[1], 0, 0,
