from rich import print as rprint

# ----------------------------------------------------------------------
# Dynamically determine PDD_PATH at runtime.
# ----------------------------------------------------------------------
def obtain_pdd_directory() -> str:
    """
    Locate and return the PDD_PATH directory.
    First checks the environment variable. If absent, tries to infer it
    using importlib.resources. If both fail, terminate execution.
    """
    if "PDD_PATH" in os.environ:
        return os.environ["PDD_PATH"]
    else:
        try:
            resource_path = importlib.resources.files("pdd").joinpath("cli.py")
            inferred_path = str(resource_path.parent)
            # Also store it in the environment for consistency
            os.environ["PDD_PATH"] = inferred_path
            return inferred_path
        except ImportError:
            rprint(
                "[red]Error: Unable to locate the 'pdd' package directory. "
                "Please manually set the PDD_PATH environment variable.[/red]"
            )
            sys.exit(1)

# ----------------------------------------------------------------------
# Simplified shell RC path logic
# ----------------------------------------------------------------------
def locate_shell_rc(shell_name: str) -> Optional[str]:
    """Determine the default RC file path based on the shell name."""
    user_home = os.path.expanduser("~")
    if shell_name == "bash":
        return os.path.join(user_home, ".bashrc")
    elif shell_name == "zsh":
        return os.path.join(user_home, ".zshrc")
    elif shell_name == "fish":
        return os.path.join(user_home, ".config", "fish", "config.fish")
    return None

def detect_current_shell() -> Optional[str]:
    """Identify the currently active shell with improved reliability."""
    if not os.environ.get('PYTEST_CURRENT_TEST'):
        # Method 1: Use 'ps' to get parent process name
        try:
            import subprocess
            proc_result = subprocess.run(['ps', '-p', str(os.getppid()), '-o', 'comm='], 
                                      capture_output=True, text=True)
            if proc_result.returncode == 0:
                # Extract basename and remove leading dash (login shells)
                shell_name = os.path.basename(proc_result.stdout.strip())
                return shell_name.lstrip('-')
        except (subprocess.SubprocessError, FileNotFoundError):
            pass

        # Method 2: Check $0 via shell echo
        try:
            shell_result = subprocess.run(['sh', '-c', 'echo "$0"'], 
                                        capture_output=True, text=True)
            if shell_result.returncode == 0:
                shell_name = os.path.basename(shell_result.stdout.strip())
                return shell_name.lstrip('-')
        except (subprocess.SubprocessError, FileNotFoundError):
            pass

    # Fallback: use SHELL environment variable
    return os.path.basename(os.environ.get("SHELL", ""))

def get_completion_file_extension(shell_name: str) -> str:
    """Map shell names to their completion script extensions."""
    extension_map = {
        "bash": "sh",
        "zsh": "zsh",
        "fish": "fish"
    }
    return extension_map.get(shell_name, shell_name)

def enable_completion(silent: bool = False):
    """
    Set up shell completion for the PDD CLI by detecting the user's shell,
    copying the appropriate completion script, and adding a source command
    to the user's shell RC file if needed.
    """
    current_shell = detect_current_shell()
    rc_filepath = locate_shell_rc(current_shell)

    if not rc_filepath:
        if not silent:
            rprint(f"[red]Unsupported shell: {current_shell}[/red]")
        raise click.Abort()

    ext = get_completion_file_extension(current_shell)
    # Resolve local PDD path dynamically at runtime:
    pdd_dir = obtain_pdd_directory()
    completion_script = os.path.join(pdd_dir, f"pdd_completion.{ext}")

    if not os.path.isfile(completion_script):
        if not silent:
            rprint(f"[red]Completion script missing: {completion_script}[/red]")
        raise click.Abort()

    source_line = f"source {completion_script}"

    try:
        # Ensure RC file exists (create if necessary)
        if not os.path.exists(rc_filepath):
            rc_directory = os.path.dirname(rc_filepath)
            if rc_directory:  # Skip if empty string (e.g., current directory)
                os.makedirs(rc_directory, exist_ok=True)
            with open(rc_filepath, "w", encoding="utf-8") as rc_file:
                rc_file.write("")  # Create empty file

        # Read existing content
        with open(rc_filepath, "r", encoding="utf-8") as rc_file:
            existing_content = rc_file.read()

        if source_line not in existing_content:
            with open(rc_filepath, "a", encoding="utf-8") as rc_file:
                rc_file.write(f"\n# PDD CLI completion\n{source_line}\n")

            if not silent:
                rprint(f"[green]Shell completion enabled for {current_shell}.[/green]")
                rprint(f"Restart your shell or run 'source {rc_filepath}' to activate.")
        else:
            if not silent:
                rprint(f"[yellow]Shell completion already configured for {current_shell}.[/yellow]")

    except OSError as error:
        if not silent:
            rprint(f"[red]Completion setup failed: {error}[/red]")
        raise click.Abort()

# EchoDecks API Client - Modified Version
import os
import sys
import json
import argparse
import requests

# Base Configuration
API_ENDPOINT = "https://echodecks.com/api/apps/68bc0769be6e58e1c8385b2b/functions/externalApi"

def fetch_api_key():
    key = os.environ.get("ECHODECKS_API_KEY")
    if not key:
        print(json.dumps({"error": "Missing ECHODECKS_API_KEY environment variable."}))
        sys.exit(1)
    return key

def execute_request(http_method, resource, action=None, query_params=None, payload=None):
    auth_headers = {
        "X-API-KEY": fetch_api_key(),
        "Content-Type": "application/json"
    }

    endpoint_url = f"{API_ENDPOINT}?resource={resource}"
    if action:
        endpoint_url += f"&action={action}"

    # Append additional query parameters if provided (e.g., deck_id for GET requests)
    if query_params:
        for param_key, param_value in query_params.items():
            if param_value is not None:
                endpoint_url += f"&{param_key}={param_value}"

    try:
        if http_method == "GET":
            api_response = requests.get(endpoint_url, headers=auth_headers)
        elif http_method == "POST":
            api_response = requests.post(endpoint_url, headers=auth_headers, json=payload)
        elif http_method == "PUT":
            api_response = requests.put(endpoint_url, headers=auth_headers, json=payload)
        elif http_method == "DELETE":
            api_response = requests.delete(endpoint_url, headers=auth_headers)
        else:
            return {"error": f"Unsupported method: {http_method}"}

        api_response.raise_for_status()

        # Attempt to parse JSON response; fallback to raw text if empty or invalid JSON
        try:
            return api_response.json()
        except json.JSONDecodeError:
            return {"status": "success", "message": api_response.text}

    except requests.exceptions.RequestException as exc:
        error_description = str(exc)
        if hasattr(exc, 'response') and exc.response is not None and exc.response.text:
             try:
                 server_error = json.loads(exc.response.text)
                 error_description = server_error.get('message', error_description)
             except:
                 error_description = exc.response.text
        return {"error": error_description}

# --- Command Handlers ---
def process_list_decks(args):
    return execute_request("GET", "decks", query_params={"id": args.id})

def process_create_deck(args):
    return execute_request("POST", "decks", payload={"title": args.title, "description": args.description})

def process_list_cards(args):
    return execute_request("GET", "cards", query_params={"deck_id": args.deck_id, "id": args.card_id})

def process_due_cards(args):
    return execute_request("GET", "study", action="due", query_params={"deck_id": args.deck_id})

def process_review_submission(args):
    return execute_request("POST", "study", action="submit", payload={
        "card_id": args.card_id,
        "quality": args.quality
    })

def process_card_generation(args):
    payload_data = {"deck_id": args.deck_id}
    if args.topic:
        payload_data["topic"] = args.topic
    if args.text:
        payload_data["text"] = args.text
    return execute_request("POST", "generate", action="cards", payload=payload_data)

def process_podcast_generation(args):
    return execute_request("POST", "podcasts", action="generate", payload={
        "deck_id": args.deck_id,
        "style": args.style
    })

def process_list_podcasts(args):
    return execute_request("GET", "podcasts", query_params={"deck_id": args.deck_id, "id": args.id})

def process_user_info(args):
    return execute_request("GET", "user")

def process_podcast_status(args):
    return execute_request("GET", "podcasts", action="status", query_params={"id": args.id})

# --- Main CLI ---
def main():
    cli_parser = argparse.ArgumentParser(description="EchoDecks API Client")
    subparsers_group = cli_parser.add_subparsers(dest="command", required=True)

    # Podcast status command
    p_pod_status = subparsers_group.add_parser("podcast-status", help="Check podcast status")
    p_pod_status.add_argument("--id", required=True)

    # Decks commands
    p_decks = subparsers_group.add_parser("list-decks", help="List decks or get a specific deck")
    p_decks.add_argument("--id", help="Specific Deck ID")

    p_create_deck = subparsers_group.add_parser("create-deck", help="Create a new deck")
    p_create_deck.add_argument("--title", required=True)
    p_create_deck.add_argument("--description")

    # Cards commands
    p_cards = subparsers_group.add_parser("list-cards", help="List cards in a deck")
    p_cards.add_argument("--deck-id", required=True)
    p_cards.add_argument("--card-id", help="Specific Card ID")

    # Study commands
    p_due = subparsers_group.add_parser("get-due", help="Get due cards")
    p_due.add_argument("--deck-id", help="Filter by Deck ID")

    p_review = subparsers_group.add_parser("submit-review", help="Submit a card review")
    p_review.add_argument("--card-id", required=True)
    p_review.add_argument("--quality", type=int, required=True, choices=[0, 1, 2, 3], help="0=Again, 1=Hard, 2=Good, 3=Easy")

    # Generate commands
    p_gen_cards = subparsers_group.add_parser("generate-cards", help="AI Generate cards")
    p_gen_cards.add_argument("--topic")
    p_gen_cards.add_argument("--text")
    p_gen_cards.add_argument("--deck-id", required=True)

    p_gen_pod = subparsers_group.add_parser("generate-podcast", help="AI Generate podcast")
    p_gen_pod.add_argument("--deck-id", required=True)
    p_gen_pod.add_argument("--style", default="summary", help="Podcast style (e.g., summary, conversation)")

    # Podcasts commands
    p_pods = subparsers_group.add_parser("list-podcasts", help="List podcasts")
    p_pods.add_argument("--deck-id")
    p_pods.add_argument("--id")

    # User command
    subparsers_group.add_parser("get-user", help="Get user info")

    parsed_args = cli_parser.parse_args()

    command_handlers = {
        "list-decks": process_list_decks,
        "create-deck": process_create_deck,
        "list-cards": process_list_cards,
        "get-due": process_due_cards,
        "submit-review": process_review_submission,
        "generate-cards": process_card_generation,
        "generate-podcast": process_podcast_generation,
        "list-podcasts": process_list_podcasts,
        "podcast-status": process_podcast_status,
        "get-user": process_user_info
    }

    if parsed_args.command in command_handlers:
        result = command_handlers[parsed_args.command](parsed_args)
        print(json.dumps(result, indent=2))
    else:
        print(json.dumps({"error": "Unknown command"}))

if __name__ == "__main__":
    main()

# Retrieve a directory path from an environment variable
from os import environ
from pathlib import Path
from epstein_files.util.logging import exit_with_error, logger

def fetch_env_directory(env_name: str, required: bool = True) -> Path | None:
    if (path := environ.get(env_name)):
        path = Path(path)
        error_message = f"environment variable {env_name} points to '{path}' but it's not a directory"
        if path.is_dir():
            return path
        elif required:
            exit_with_error(f"Required {error_message}.\n")
        else:
            logger.warning(f"Optional {error_message}. Some features will be unavailable.")
            return None
    else:
        logger.warning(f"Optional environment variable {env_name} not set. Some features will be unavailable.")

# Type I Clone: Renamed variables, reordered statements, changed literals, and modified comments
import enum
import inspect
from typing import TYPE_CHECKING, Iterable, List, Optional, Tuple, Union

if TYPE_CHECKING:
    from ..configuration_utils import PretrainedConfig


class BackboneFramework(enum.Enum):
    TIMM = "timm"
    TRANSFORMERS = "transformers"


def validate_output_configuration(
    output_features: Optional[Iterable[str]],
    output_indices: Optional[Iterable[int]],
    stage_names: Optional[Iterable[str]]
):
    """
    Confirm that output_indices and output_features are appropriate for the provided stage_names.
    """
    if stage_names is None:
        raise ValueError("Stage names must be specified for transformer-based backbones")

    if output_features is not None:
        if not isinstance(output_features, (list,)):
            raise ValueError(f"output_features must be a list, received {type(output_features)}")

        if any(feature not in stage_names for feature in output_features):
            raise ValueError(f"output_features must be a subset of stage_names: {stage_names}, got {output_features}")

        if len(output_features) != len(set(output_features)):
            raise ValueError(f"output_features must not contain duplicates, got {output_features}")

        expected_order = [feat for feat in stage_names if feat in output_features]
        if output_features != expected_order:
            raise ValueError(
                f"output_features must follow the same order as stage_names, expected {expected_order} but got {output_features}"
            )

    if output_indices is not None:
        if not isinstance(output_indices, list):
            raise ValueError(f"output_indices must be a list, got {type(output_indices)}")

        # Normalize negative indices to positive equivalents: [-1] → [len(stage_names)-1]
        normalized_indices = tuple(idx % len(stage_names) if idx < 0 else idx for idx in output_indices)

        if any(idx not in range(len(stage_names)) for idx in normalized_indices):
            raise ValueError(f"output_indices must be valid for stage_names {stage_names}, got {output_indices}")

        if len(normalized_indices) != len(set(normalized_indices)):
            msg = f"output_indices must not contain duplicates, got {output_indices}"
            msg += f"(equivalent to {normalized_indices}))" if normalized_indices != output_indices else ""
            raise ValueError(msg)

        if normalized_indices != tuple(sorted(normalized_indices)):
            sorted_list = [idx for _, idx in sorted(zip(normalized_indices, output_indices), key=lambda x: x[0])]
            raise ValueError(
                f"output_indices must follow the same order as stage_names, expected {sorted_list} but got {output_indices}"
            )

    if output_features is not None and output_indices is not None:
        if len(output_features) != len(output_indices):
            raise ValueError("output_features and output_indices must have equal length when both are provided")

        if output_features != [stage_names[idx] for idx in output_indices]:
            raise ValueError("output_features and output_indices must refer to the same stages when both are set")


def _match_output_features_and_indices(
    output_features: Optional[List[str]],
    output_indices: Optional[Union[List[int], Tuple[int]]],
    stage_names: List[str],
):
    """
    Derive matching `output_features` and `output_indices` based on `stage_names`.

    Strategy:
        - Neither set: assign last stage only
        - Only features set: derive corresponding indices
        - Only indices set: derive corresponding features
        - Both set: return as-is (after validation)
    """
    if output_indices is None and output_features is None:
        output_indices = [len(stage_names) - 1]
        output_features = [stage_names[-1]]
    elif output_indices is None and output_features is not None:
        output_indices = [stage_names.index(layer) for layer in output_features]
    elif output_features is None and output_indices is not None:
        output_features = [stage_names[idx] for idx in output_indices]

    return output_features, output_indices


def get_consistent_output_configuration(
    output_features: Optional[List[str]],
    output_indices: Optional[Union[List[int], Tuple[int]]],
    stage_names: List[str],
) -> Tuple[List[str], List[int]]:
    """
    Ensure consistent alignment between `output_features` and `output_indices`.

    Rules:
        - If only one is provided, infer the other
        - If neither is provided, default to final stage
        - If both are provided, verify consistency
    """
    output_indices = list(output_indices) if output_indices is not None else None

    # Validate initial configuration
    validate_output_configuration(
        output_features=output_features,
        output_indices=output_indices,
        stage_names=stage_names
    )

    # Align and retrieve matched pair
    aligned_features, aligned_indices = _match_output_features_and_indices(
        output_features=output_features,
        output_indices=output_indices,
        stage_names=stage_names
    )

    # Re-validate aligned configuration
    validate_output_configuration(
        output_features=aligned_features,
        output_indices=aligned_indices,
        stage_names=stage_names
    )

    return aligned_features, aligned_indices


class BackboneBaseMixin:
    backbone_framework: Optional[BackboneFramework] = None

    def _initialize_timm_backbone(self, config) -> None:
        """
        Initialize the backbone model using timm. Requires self._backbone to be already loaded.
        """
        if getattr(self, "_backbone", None) is None:
            raise ValueError("self._backbone must be assigned before calling _initialize_timm_backbone")

        # Extract stage info from timm's feature_info
        self.stage_names = [stage["module"] for stage in self._backbone.feature_info.info]
        self.num_channels = [stage["num_chs"] for stage in self._backbone.feature_info.info]

        # Handle out_indices and module names from timm
        out_indices = list(self._backbone.feature_info.out_indices)
        out_features = self._backbone.feature_info.module_name()

        # Validate against stage_names
        validate_output_configuration(
            output_features=out_features,
            output_indices=out_indices,
            stage_names=self.stage_names
        )

        self._output_features, self._output_indices = out_features, out_indices

    def _initialize_transformers_backbone(self, config) -> None:
        stage_names = getattr(config, "stage_names")
        output_features = getattr(config, "output_features", None)
        output_indices = getattr(config, "output_indices", None)

        self.stage_names = stage_names
        self._output_features, self._output_indices = get_consistent_output_configuration(
            output_features=output_features,
            output_indices=output_indices,
            stage_names=stage_names
        )

        # Channel dimensions will be set during transformer backbone initialization
        self.num_channels = None

    def _setup_backbone(self, config) -> None:
        """
        Initialize the backbone after pretrained weights are loaded.
        Called by base class constructor post-weight loading.
        """
        self.config = config
        self.use_timm_backbone = getattr(config, "use_timm_backbone", False)
        self.backbone_framework = BackboneFramework.TIMM if self.use_timm_backbone else BackboneFramework.TRANSFORMERS

        if self.backbone_framework == BackboneFramework.TIMM:
            self._initialize_timm_backbone(config)
        elif self.backbone_framework == BackboneFramework.TRANSFORMERS:
            self._initialize_transformers_backbone(config)
        else:
            raise ValueError(f"Unsupported backbone framework: {self.backbone_framework}")

    @property
    def output_features(self):
        return self._output_features

    @output_features.setter
    def output_features(self, new_output_features: List[str]):
        """
        Update output_features; automatically syncs output_indices accordingly.
        """
        self._output_features, self._output_indices = get_consistent_output_configuration(
            output_features=new_output_features,
            output_indices=None,
            stage_names=self.stage_names
        )

    @property
    def output_indices(self):
        return self._output_indices

    @output_indices.setter
    def output_indices(self, new_output_indices: Union[Tuple[int], List[int]]):
        """
        Update output_indices; automatically syncs output_features accordingly.
        """
        self._output_features, self._output_indices = get_consistent_output_configuration(
            output_features=None,
            output_indices=new_output_indices,
            stage_names=self.stage_names
        )

    @property
    def feature_channels(self):
        # Returns channel counts per stage, regardless of inclusion in output_features
        return {stage: self.num_channels[i] for i, stage in enumerate(self.stage_names)}

    @property
    def channels(self):
        return [self.feature_channels[name] for name in self.output_features]

    def forward_with_filtered_kwargs(self, *args, **kwargs):
        signature = dict(inspect.signature(self.forward).parameters)
        filtered_kwargs = {k: v for k, v in kwargs.items() if k in signature}
        return self(*args, **filtered_kwargs)

    def forward(
        self,
        pixel_values,
        output_hidden_states: Optional[bool] = None,
        output_attentions: Optional[bool] = None,
        return_dict: Optional[bool] = None,
    ):
        raise NotImplementedError("This method should be implemented by subclasses.")

    def to_dict(self):
        """
        Serialize instance to dictionary. Overrides default to include output configuration.
        """
        output = super().to_dict()
        output["output_features"] = output.pop("_output_features")
        output["output_indices"] = output.pop("_output_indices")
        return output


class BackboneConfigMixin:
    """
    A Mixin to manage `output_features` and `output_indices` attributes for backbone configurations.
    """

    @property
    def output_features(self):
        return self._output_features

    @output_features.setter
    def output_features(self, new_output_features: List[str]):
        """
        Set output_features; automatically update output_indices.
        """
        self._output_features, self._output_indices = get_consistent_output_configuration(
            output_features=new_output_features,
            output_indices=None,
            stage_names=self.stage_names
        )

    @property
    def output_indices(self):
        return self._output_indices

    @output_indices.setter
    def output_indices(self, new_output_indices: Union[Tuple[int], List[int]]):
        """
        Set output_indices; automatically update output_features.
        """
        self._output_features, self._output_indices = get_consistent_output_configuration(
            output_features=None,
            output_indices=new_output_indices,
            stage_names=self.stage_names
        )

    def to_dict(self):
        """
        Serialize configuration to dictionary, including output configuration fields.
        """
        output = super().to_dict()
        output["output_features"] = output.pop("_output_features")
        output["output_indices"] = output.pop("_output_indices")
        return output


def fetch_backbone_model(config):
    """
    Instantiate backbone model from configuration.

    Behavior depends on config type:
        - Backbone config alone → randomly initialized backbone
        - Parent model config with backbone → load pretrained or random weights as specified
    """
    from transformers import AutoBackbone, AutoConfig

    backbone_config = getattr(config, "backbone_config", None)
    use_timm_backbone = getattr(config, "use_timm_backbone", None)
    use_pretrained_backbone = getattr(config, "use_pretrained_backbone", None)
    backbone_checkpoint = getattr(config, "backbone", None)
    backbone_kwargs = getattr(config, "backbone_kwargs", None) or {}

    # Check conflicting arguments
    if backbone_kwargs and backbone_config is not None:
        raise ValueError("Cannot specify both 'backbone_kwargs' and 'backbone_config'.")

    if backbone_config is not None and backbone_checkpoint is not None and use_pretrained_backbone is not None:
        raise ValueError("Ambiguous configuration: cannot specify both 'backbone_config' and 'backbone' checkpoint.")

    # Case: config represents backbone itself
    if (
        backbone_config is None
        and use_timm_backbone is None
        and backbone_checkpoint is None
    ):
        return AutoBackbone.from_config(config=config, **backbone_kwargs)

    # Case: config represents parent model containing a backbone
    if use_timm_backbone:
        if backbone_checkpoint is None:
            raise ValueError("'config.backbone' must be set when 'use_timm_backbone=True'")
        backbone = AutoBackbone.from_pretrained(
            backbone_checkpoint,
            use_timm_backbone=use_timm_backbone,
            use_pretrained_backbone=use_pretrained_backbone,
            **backbone_kwargs,
        )
    elif use_pretrained_backbone:
        if backbone_checkpoint is None:
            raise ValueError("'config.backbone' must be set when 'use_pretrained_backbone=True'")
        backbone = AutoBackbone.from_pretrained(backbone_checkpoint, **backbone_kwargs)
    else:
        if backbone_config is None and backbone_checkpoint is None:
            raise ValueError("Either 'config.backbone_config' or 'config.backbone' must be set")
        if backbone_config is None:
            backbone_config = AutoConfig.from_pretrained(backbone_checkpoint, **backbone_kwargs)
        backbone = AutoBackbone.from_config(config=backbone_config)

    return backbone


def validate_backbone_setup_args(
    use_timm_backbone: bool,
    use_pretrained_backbone: bool,
    backbone_name: Optional[str],
    backbone_config: Optional[Union[dict, "PretrainedConfig"]],
    backbone_kwargs: Optional[dict],
):
    """
    Validate configuration arguments passed to load_backbone.
    """
    if backbone_config is not None and backbone_name is not None:
        raise ValueError("Cannot specify both 'backbone' and 'backbone_config'.")

