def wait_for_service(url: str, max_wait: float = 30.0, poll_delay: float = 0.5) -> bool:
    """Poll a service endpoint until it becomes available or timeout is reached.

    Args:
        url: Base URL of the service to check
        max_wait: Maximum duration to wait in seconds
        poll_delay: Interval between checks in seconds

    Returns:
        True if service responds successfully, False otherwise
    """
    health_check_url = f"{url}/.well-known/agent.json"
    start_timestamp = time.time()
    while time.time() - start_timestamp < max_wait:
        try:
            response = httpx.get(health_check_url, timeout=2.0)
            if response.status_code == 200:
                return True
        except (httpx.RequestError, httpx.TimeoutException):
            pass
        time.sleep(poll_delay)
    return False

