    """
    registered_cids = []
    def _register(record_path: str = "test/sample_agent/sample_agent_record.json") -> str:
        """Register a record with the directory service and return its CID."""
        result = subprocess.run(
            ["dirctl", "push", record_path],
            capture_output=True,
            text=True,
            timeout=30,
        )
        if result.returncode != 0:
            raise RuntimeError(
                f"Directory push failed: {result.stderr}\n"
                f"stdout: {result.stdout}"
            )

        # Extract CID from output
        combined_output = result.stdout + result.stderr
        match = re.search(r"CID:\s*(\S+)", combined_output)
        if not match:
            raise RuntimeError(
                f"Unable to extract CID from output: {combined_output}"
            )

        cid = match.group(1)
        registered_cids.append(cid)
        print(f"Registered agent record with CID: {cid}")
        return cid
    yield _register
    # Cleanup: remove all registered records
    for identifier in registered_cids:
        try:
            result = subprocess.run(
                ["dirctl", "delete", identifier],
                capture_output=True,
                text=True,
                timeout=30,
            )
            if result.returncode == 0:
                print(f"Removed agent record with CID: {identifier}")
            else:
                print(f"Warning: Could not delete record {identifier}: {result.stderr}")
        except subprocess.TimeoutExpired:
            print(f"Warning: Deletion timed out for record {identifier}")
        except FileNotFoundError:
            print("Warning: dirctl command not found; skipping cleanup")
            break

