    clear_pin.on() # No want clearing here
    # Cycle the digital state thru all the 74HC595 chips
    for i in range(len(_digitalCurrentState)):
        # Put the value on the data pin, msb first
        value = _digitalCurrentState[len(_digitalCurrentState) - i - 1]
        data_pin.value(value)
        shift_pin.on()
        shift_pin.off()
    # Clock all the bits to the outputs
    latch_pin.on()
    latch_pin.off()

def fast_shift_595_values(bytes_data, count):
    if _DataPin is None or _RclkPin is None or _ClockPin is None or _ClearPin is None: return
    # Define the pins
    data_pin = Pin(_DataPin, Pin.OUT)
    latch_pin = Pin(_RclkPin, Pin.OUT)
    shift_pin = Pin(_ClockPin, Pin.OUT)
    clear_pin = Pin(_ClearPin, Pin.OUT)
    clear_pin.on() # No want clearing here
    valuebits = int.from_bytes(bytes_data, 'little')
    # Cycle the digital state thru all the 74HC595 chips
    for i in range(count):
        # Put the value on the data pin, msb first (input value LSB is 595 MSB)
        data_pin.value(valuebits & 1)
        shift_pin.on()
        shift_pin.off()
        valuebits >>= 1
    # Clock all the bits to the outputs
    latch_pin.on()
    latch_pin.off()

def handle_74ls595(portinfo, val):
    if debug_mode: print('Executing handle_74ls595 with portinfo:', portinfo)
    if 'index' not in portinfo:
        if debug_mode: print('Error - Incorrect port info for handle_74ls595')
        return False
    index = portinfo['index']
    _digitalCurrentState[index] = val

def handle_gpio_digital(portinfo, val):
    if debug_mode: print('Executing handle_gpio_digital with portinfo:', portinfo)
    if 'pin' not in portinfo:
        if debug_mode: print('Error - Incorrect port info for handle_gpio_digital')
        return False
    pin_num = portinfo['pin']
    pin_obj = Pin(pin_num, Pin.OUT)
    if val > 0.5:
        pin_obj.on()
    else:
        pin_obj.off()

def set_digital_output(port, value, push=False):
