        DigitalPortTable[port]['func'](DigitalPortTable[port], value)
    if push: output_digital_state()

def clear_all_digital_outputs():
    # Set all digital pins to OFF (0)
    # Using clear pin for speed
    if _DataPin is None or _RclkPin is None or _ClockPin is None or _ClearPin is None: return
    # Define the pins
    data_pin = Pin(_DataPin, Pin.OUT)
    latch_pin = Pin(_RclkPin, Pin.OUT)
    shift_pin = Pin(_ClockPin, Pin.OUT)
    clear_pin = Pin(_ClearPin, Pin.OUT)
    # Clear all the registers
    clear_pin.on() # Make sure initially not clearing, then cycle bit
    clear_pin.off()
    clear_pin.on()
    # Clock all the cleared bits to the outputs
    latch_pin.off() # Make sure initially not outputting, then cycle bit
    latch_pin.on()
    latch_pin.off()
    # This quickly clears the 595 digital outputs but not GPIO digital outputs
    # So do the whole thing again to make sure everything is zero
    set_all_digital_outputs(0)

