from skylos.cli import _emit_github_annotations
import io
import sys

def _collect_annotations(output_data):
    previous = sys.stdout
    sys.stdout = buffer = io.StringIO()
    _emit_github_annotations(output_data)
    sys.stdout = previous
    return buffer.getvalue().strip().splitlines()

class TestGitHubAnnotationsOutput:
