                    "rule_id": "SKY-D211",
                    "severity": "HIGH",
                    "file": "app.py",
                    "line": 10,
                    "message": "SQL injection detected",
                }
            ],
        }
        lines = _collect_annotations(output_data)
        assert len(lines) == 1
        assert (
            lines[0]
            == "::error file=app.py,line=10,title=Skylos SKY-D211::SQL injection detected"
        )

