import json
import numpy as np
import torch
import torch.nn.functional as F
from lightx2v.models.networks.hunyuan_video.infer.offload.transformer_infer import HunyuanVideo15OffloadTransformerInfer
from lightx2v_platform.base.global_var import AI_DEVICE

class HunyuanVideo15TransformerInferMagCaching(HunyuanVideo15OffloadTransformerInfer):
    def __init__(self, config):
        super().__init__(config)
        self.magcache_threshold = config.get("magcache_thresh", 0.3)
        self.K = config.get("magcache_K", 7)
        self.retention_ratio = config.get("magcache_retention_ratio", 0.25)
        self.mag_ratios = np.array(config.get("magcache_ratios", []))
        self.enable_magcache_calibration = config.get("magcache_calibration", True)
        # {True: cond_param, False: uncond_param}
        self.err_sum = {True: 0.0, False: 0.0}
        self.skip_count = {True: 0, False: 0}
        self.ratio_product = {True: 1.0, False: 1.0}
        self.residual_cache = {True: None, False: None}
        self.residual_cache_txt = {True: None, False: None}
        # calibration args
        self.norm_mean = [[1.0], [1.0]]  # mean of magnitude ratio
        self.norm_std_dev = [[0.0], [0.0]]  # std of magnitude ratio
        self.cos_dist = [[0.0], [0.0]]  # cosine distance of residual features

    @torch.no_grad()
    def infer(self, weights, infer_module_out):
        should_skip = False
        current_step = self.scheduler.step_index
        is_conditional = self.scheduler.infer_condition

        if self.enable_magcache_calibration:
            should_skip = False
        else:
            if current_step >= int(self.config["infer_steps"] * self.retention_ratio):
                # conditional and unconditional in one list
                cur_mag_ratio = self.mag_ratios[0][current_step] if is_conditional else self.mag_ratios[1][current_step]
                # magnitude ratio between current step and the cached step
                self.ratio_product[is_conditional] *= cur_mag_ratio
                self.skip_count[is_conditional] += 1  # skip steps plus 1

                # skip error of current steps
                cur_err = np.abs(1 - self.ratio_product[is_conditional])
                # accumulated error of multiple steps
                self.err_sum[is_conditional] += cur_err

                if self.err_sum[is_conditional] < self.magcache_threshold and self.skip_count[is_conditional] <= self.K:
                    should_skip = True
                else:
                    self.err_sum[is_conditional] = 0
                    self.skip_count[is_conditional] = 0
                    self.ratio_product[is_conditional] = 1.0

        if not should_skip:
            self.infer_computing(weights, infer_module_out)
        else:
            self.infer_from_cache(infer_module_out)

        x = self.infer_final_layer(weights, infer_module_out)
        return x

    def infer_computing(self, weights, infer_module_out):
        current_step = self.scheduler.step_index
        is_conditional = self.scheduler.infer_condition
        original_img = infer_module_out.img.clone()
        original_txt = infer_module_out.txt.clone()

        self.infer_func(weights, infer_module_out)

        prev_residual = infer_module_out.img - original_img
        prev_residual_txt = infer_module_out.txt - original_txt

        if self.config["cpu_offload"]:
            prev_residual = prev_residual.cpu()
            prev_residual_txt = prev_residual_txt.cpu()

        if self.enable_magcache_calibration and current_step >= 1:
            ratio_norm = ((prev_residual.norm(dim=-1) / self.residual_cache[is_conditional].norm(dim=-1)).mean()).item()
            std_norm = (prev_residual.norm(dim=-1) / self.residual_cache[is_conditional].norm(dim=-1)).std().item()
            cos_dis_val = (1 - F.cosine_similarity(prev_residual, self.residual_cache[is_conditional], dim=-1, eps=1e-8)).mean().item()

            idx = int(not is_conditional)
            self.norm_mean[idx].append(round(ratio_norm, 5))
            self.norm_std_dev[idx].append(round(std_norm, 5))
            self.cos_dist[idx].append(round(cos_dis_val, 5))

            print(f"time: {current_step}, infer_condition: {is_conditional}, norm_ratio: {ratio_norm}, norm_std: {std_norm}, cos_dis: {cos_dis_val}")

        self.residual_cache[is_conditional] = prev_residual
        self.residual_cache_txt[is_conditional] = prev_residual_txt

        if self.config["cpu_offload"]:
            original_img = original_img.to("cpu")
            original_txt = original_txt.to("cpu")
            del original_img, original_txt
            torch.cuda.empty_cache()
            import gc
            gc.collect()

    def infer_from_cache(self, infer_module_out):
        residual_img = self.residual_cache[self.scheduler.infer_condition]
        residual_txt = self.residual_cache_txt[self.scheduler.infer_condition]
        infer_module_out.img.add_(residual_img.to(AI_DEVICE))
        infer_module_out.txt.add_(residual_txt.to(AI_DEVICE))

    def clear(self):
        self.err_sum = {True: 0.0, False: 0.0}
        self.skip_count = {True: 0, False: 0}
        self.ratio_product = {True: 1.0, False: 1.0}
        self.residual_cache = {True: None, False: None}
        self.residual_cache_txt = {True: None, False: None}

        if self.enable_magcache_calibration:
            print("norm ratio")
            print(self.norm_mean)
            print("norm std")
            print(self.norm_std_dev)
            print("cos_dis")
            print(self.cos_dist)

            def save_json_file(filename, data_list):
                with open(filename + ".json", "w") as f:
                    json.dump(data_list, f)

            save_json_file("mag_ratio", self.norm_mean)
