class HunyuanTransformerInferTeaCaching(HunyuanVideo15OffloadTransformerInfer):
    def __init__(self, config):
        super().__init__(config)
        self.teacache_threshold = self.config["teacache_thresh"]
        self.coefficients = self.config["coefficients"]
        self.accumulated_rel_l1_distance_odd = 0
        self.previous_modulated_input_odd = None
        self.previous_residual_odd = None
        self.accumulated_rel_l1_distance_even = 0
        self.previous_modulated_input_even = None
        self.previous_residual_even = None

    def calculate_should_calc(self, img, vec, block):
        inp = img.clone()
        vec_ = vec.clone()
        img_mod_layer = block.img_branch.img_mod

        if self.config["cpu_offload"]:
            img_mod_layer.to_cuda()

        img_mod1_shift, img_mod1_scale, _, _, _, _ = img_mod_layer.apply(vec_).chunk(6, dim=-1)
        inp = inp.squeeze(0)
        normed_inp = torch.nn.functional.layer_norm(inp, (inp.shape[1],), None, None, 1e-6)
        modulated_inp = normed_inp * (1 + img_mod1_scale) + img_mod1_shift

        del normed_inp, inp, vec_

        if self.scheduler.step_index == 0 or self.scheduler.step_index == self.scheduler.infer_steps - 1:
            should_calc = True
            if self.scheduler.infer_condition:
                self.accumulated_rel_l1_distance_odd = 0
                self.previous_modulated_input_odd = modulated_inp
            else:
                self.accumulated_rel_l1_distance_even = 0
                self.previous_modulated_input_even = modulated_inp
        else:
            rescale_func = np.poly1d(self.coefficients)
            if self.scheduler.infer_condition:
                self.accumulated_rel_l1_distance_odd += rescale_func(((modulated_inp - self.previous_modulated_input_odd).abs().mean() / self.previous_modulated_input_odd.abs().mean()).cpu().item())
                if self.accumulated_rel_l1_distance_odd < self.teacache_threshold:
                    should_calc = False
                else:
                    should_calc = True
                    self.accumulated_rel_l1_distance_odd = 0
                self.previous_modulated_input_odd = modulated_inp
            else:
                self.accumulated_rel_l1_distance_even += rescale_func(
                    ((modulated_inp - self.previous_modulated_input_even).abs().mean() / self.previous_modulated_input_even.abs().mean()).cpu().item()
                )
                if self.accumulated_rel_l1_distance_even < self.teacache_threshold:
                    should_calc = False
                else:
                    should_calc = True
                    self.accumulated_rel_l1_distance_even = 0
                self.previous_modulated_input_even = modulated_inp
            del modulated_inp

        return should_calc

    def infer(self, weights, infer_module_out):
        should_calc = self.calculate_should_calc(infer_module_out.img, infer_module_out.vec, weights.double_blocks[0])

        if not should_calc:
            if self.scheduler.infer_condition:
                infer_module_out.img += self.previous_residual_odd
            else:
                infer_module_out.img += self.previous_residual_even
        else:
            original_img = infer_module_out.img.clone()
            self.infer_func(weights, infer_module_out)

            if self.scheduler.infer_condition:
                self.previous_residual_odd = infer_module_out.img - original_img
            else:
                self.previous_residual_even = infer_module_out.img - original_img

        x = self.infer_final_layer(weights, infer_module_out)
        return x

    def clear(self):
        if self.previous_residual_odd is not None:
            self.previous_residual_odd = self.previous_residual_odd.cpu()
        if self.previous_modulated_input_odd is not None:
            self.previous_modulated_input_odd = self.previous_modulated_input_odd.cpu()
        if self.previous_residual_even is not None:
            self.previous_residual_even = self.previous_residual_even.cpu()
        if self.previous_modulated_input_even is not None:
            self.previous_modulated_input_even = self.previous_modulated_input_even.cpu()

        self.previous_modulated_input_odd = None
        self.previous_residual_odd = None
        self.previous_modulated_input_even = None
        self.previous_residual_even = None
        torch.cuda.empty_cache()

import torch
from vllm.distributed import get_pcp_group
from vllm_ascend.platform import ModelConfig
from vllm_ascend.utils import singleton

def _create_attention_mask(max_length, data_type):
    # Build lower triangular mask.
    lower_tri = torch.ones((max_length, max_length), dtype=torch.bool).tril_()
    # Invert to obtain upper triangle mask indicating positions to mask.
    upper_tri = ~lower_tri
    # For float16, use -inf as mask value; otherwise use 0 (or 1 depending on context).
    # TODO: Remove this special handling in future versions.
    mask_val = float("-inf") if data_type == torch.float16 else 0
    attn_mask = torch.zeros(size=(max_length, max_length), dtype=data_type).masked_fill_(upper_tri, mask_val)
    return attn_mask

@singleton
class AttentionMaskGenerator:
    def __init__(self, device: torch.device):
        self.mask_cache = None
        self._cached_max_len = 0
        self.target_device = device
        self.mla_pattern = None
        self.prefill_split_mask = None
        self.pcp_mla_pattern = None
        self.swa_pattern = None

    def get_attention_mask(self, max_seq_length: int, dtype: torch.dtype):
        if self.mask_cache is None or max_seq_length > self._cached_max_len:
            self.mask_cache = _create_attention_mask(max_seq_length, dtype)
            self._cached_max_len = max_seq_length
        assert self.mask_cache is not None, "Error occurred during attention mask generation."
        if self.mask_cache.dtype != dtype:
            self.mask_cache = self.mask_cache.to(dtype)
        return self.mask_cache[:max_seq_length, :max_seq_length].contiguous().to(self.target_device, non_blocking=True)

    def get_split_fuse_mask(self) -> torch.Tensor:
        if self.prefill_split_mask is None:
            self.prefill_split_mask = (
                torch.triu(torch.ones(2048, 2048), diagonal=1).to(torch.int8).to(self.target_device)
            )
        return self.prefill_split_mask

    def get_mla_pattern(self, dtype: torch.dtype) -> torch.Tensor:
        if self.mla_pattern is None or self.mla_pattern.dtype != dtype:
            if dtype == torch.float16:
                fill_value = torch.finfo(torch.float32).min
            else:
                fill_value = 0
            triu_pattern = torch.triu(torch.ones(512, 512, device=self.target_device, dtype=dtype), 1)
            self.mla_pattern = torch.where(triu_pattern == 1, fill_value, 0).to(dtype)
        return self.mla_pattern

    def get_pcp_mla_pattern(self, dtype: torch.dtype):
        if self.pcp_mla_pattern is None or self.pcp_mla_pattern.dtype != dtype:
            self.pcp_mla_pattern = torch.triu(torch.ones(512, 512, device=self.target_device, dtype=dtype), 1)
        return self.pcp_mla_pattern

    def get_sliding_window_mask(self, dtype: torch.dtype, window_size):
        if self.swa_pattern is None or self.swa_pattern.dtype != dtype:
            if window_size is not None:
                base_mask = torch.ones(2048, 2048, dtype=torch.bool)
                upper_tri = torch.triu(base_mask, diagonal=1).to(self.target_device)
                lower_tri = torch.tril(base_mask, -window_size).to(self.target_device)
                self.swa_pattern = upper_tri + lower_tri
        return self.swa_pattern

    def build_mask_for_model(self, model_config: ModelConfig):
        if model_config.runner_type == "pooling":
            return self.get_attention_mask(2048, torch.bool)
        return self.get_split_fuse_mask()

    def build_final_mla_mask(self, model_config: ModelConfig):
        if get_pcp_group().world_size > 1:
            return self.get_pcp_mla_pattern(model_config.dtype)
        # Use 512x512 MLA mask with correct dtype for prefill
        return self.get_mla_pattern(model_config.dtype)

