# Global event to signal user-initiated interruption across tools
# The agent's interrupt() method triggers this event, and long-running
# tool operations periodically check it to decide whether to abort.
# Example usage in a tool:
#     from tools.interrupt import check_interrupt
#     if check_interrupt():
#         return {"output": "[interrupted]", "returncode": 130}
import threading

_interrupt_flag = threading.Event()

def trigger_interrupt(state: bool) -> None:
    """Called by the agent to activate or deactivate the interrupt state."""
    if state:
        _interrupt_flag.set()
    else:
        _interrupt_flag.clear()

def check_interrupt() -> bool:
    """Determine if an interrupt has been requested. Thread-safe for use anywhere."""
    return _interrupt_flag.is_set()

# IDNA (Internationalizing Domain Names in Applications) implementation
import bisect
import unicodedata
import re
from typing import Union, Optional
from .intranges import intranges_contain

_virama_combining_class_value = 9
_alabel_prefix_str = b'xn--'
_unicode_dots_pattern = re.compile('[\u002e\u3002\uff0e\uff61]')

class IDNAException(UnicodeError):
    """ General exception for IDNA-related issues """
    pass

class BidirectionalConstraintViolation(IDNAException):
    """ Raised when bidirectional character rules are violated """
    pass

class InvalidCodepointValue(IDNAException):
    """ Raised when a disallowed or unallocated codepoint is encountered """
    pass

class InvalidContextualRule(IDNAException):
    """ Raised when a codepoint is used in an invalid context """
    pass

def _get_combining_class(code_point: int) -> int:
    class_value = unicodedata.combining(chr(code_point))
    if class_value == 0:
        if not unicodedata.name(chr(code_point)):
            raise ValueError('Character not recognized in Unicode database')
    return class_value

def _check_script(code_point: str, script_name: str) -> bool:
    return intranges_contain(ord(code_point), idnadata.scripts[script_name])

def _encode_punycode(text: str) -> bytes:
    return text.encode('punycode')

def _format_codepoint_string(code_point: int) -> str:
    return 'U+{:04X}'.format(code_point)

def is_valid_label_size(label: Union[bytes, str]) -> bool:
    if len(label) > 63:
        return False
    return True

def is_valid_total_size(label: Union[bytes, str], has_trailing_dot: bool) -> bool:
    max_length = 254 if has_trailing_dot else 253
    if len(label) > max_length:
        return False
    return True

def validate_bidirectional(label: str, enforce_ltr: bool = False) -> bool:
    contains_rtl = False
    for (index, char) in enumerate(label, 1):
        bidi_type = unicodedata.bidirectional(char)
        if bidi_type == '':
            raise BidirectionalConstraintViolation('Unknown directionality in label {} at position {}'.format(repr(label), index))
        if bidi_type in ['R', 'AL', 'AN']:
            contains_rtl = True
    if not contains_rtl and not enforce_ltr:
        return True

    first_char_dir = unicodedata.bidirectional(label[0])
    if first_char_dir in ['R', 'AL']:
        is_rtl = True
    elif first_char_dir == 'L':
        is_rtl = False
    else:
        raise BidirectionalConstraintViolation('First codepoint in label {} must be L, R or AL'.format(repr(label)))

    ends_validly = False
    numeral_type = None  # type: Optional[str]

    for (index, char) in enumerate(label, 1):
        current_dir = unicodedata.bidirectional(char)
        if is_rtl:
            if not current_dir in ['R', 'AL', 'AN', 'EN', 'ES', 'CS', 'ET', 'ON', 'BN', 'NSM']:
                raise BidirectionalConstraintViolation('Invalid direction for codepoint at position {} in right-to-left label'.format(index))
            if current_dir in ['R', 'AL', 'EN', 'AN']:
                ends_validly = True
            elif current_dir != 'NSM':
                ends_validly = False
            if current_dir in ['AN', 'EN']:
                if not numeral_type:
                    numeral_type = current_dir
                elif numeral_type != current_dir:
                    raise BidirectionalConstraintViolation('Mixed numeral types not allowed in right-to-left label')
        else:
            if not current_dir in ['L', 'EN', 'ES', 'CS', 'ET', 'ON', 'BN', 'NSM']:
                raise BidirectionalConstraintViolation('Invalid direction for codepoint at position {} in left-to-right label'.format(index))
            if current_dir in ['L', 'EN']:
                ends_validly = True
            elif current_dir != 'NSM':
                ends_validly = False

    if not ends_validly:
        raise BidirectionalConstraintViolation('Label ends with illegal directionality')
    return True

def validate_initial_combiner(label: str) -> bool:
    if unicodedata.category(label[0])[0] == 'M':
        raise IDNAException('Label cannot start with a combining character')
    return True

def validate_hyphen_usage(label: str) -> bool:
    if label[2:4] == '--':
        raise IDNAException('Hyphens not allowed in positions 3 and 4')
    if label[0] == '-' or label[-1] == '-':
        raise IDNAException('Label must not begin or end with a hyphen')
    return True

def ensure_nfc_compliance(label: str) -> None:
    if unicodedata.normalize('NFC', label) != label:
        raise IDNAException('Label must be in NFC normalization form')

def is_valid_context_j(label: str, position: int) -> bool:
    char_code = ord(label[position])
    if char_code == 0x200c:
        if position > 0:
            if _get_combining_class(ord(label[position - 1])) == _virama_combining_class_value:
                return True
        success_left = False
        for i in range(position-1, -1, -1):
            joining_val = idnadata.joining_types.get(ord(label[i]))
            if joining_val == ord('T'):
                continue
            if joining_val in [ord('L'), ord('D')]:
                success_left = True
                break
        if not success_left:
            return False
        success_right = False
        for i in range(position+1, len(label)):
            joining_val = idnadata.joining_types.get(ord(label[i]))
            if joining_val == ord('T'):
                continue
            if joining_val in [ord('R'), ord('D')]:
                success_right = True
                break
        return success_right
    if char_code == 0x200d:
        if position > 0:
            if _get_combining_class(ord(label[position - 1])) == _virama_combining_class_value:
                return True
        return False
    return False

def is_valid_context_o(label: str, position: int, is_exception: bool = False) -> bool:
    char_code = ord(label[position])
    if char_code == 0x00b7:
        if 0 < position < len(label)-1:
            if ord(label[position - 1]) == 0x006c and ord(label[position + 1]) == 0x006c:
                return True
        return False
    elif char_code == 0x0375:
        if position < len(label)-1 and len(label) > 1:
            return _check_script(label[position + 1], 'Greek')
        return False
    elif char_code == 0x05f3 or char_code == 0x05f4:
        if position > 0:
            return _check_script(label[position - 1], 'Hebrew')
        return False
    elif char_code == 0x30fb:
        for char in label:
            if char == '\u30fb':
                continue
            if _check_script(char, 'Hiragana') or _check_script(char, 'Katakana') or _check_script(char, 'Han'):
                return True
        return False
    elif 0x660 <= char_code <= 0x669:
        for char in label:
            if 0x6f0 <= ord(char) <= 0x06f9:
                return False
        return True
    elif 0x6f0 <= char_code <= 0x6f9:
        for char in label:
            if 0x660 <= ord(char) <= 0x0669:
                return False
        return True
    return False

def validate_single_label(label: Union[str, bytes, bytearray]) -> None:
    if isinstance(label, (bytes, bytearray)):
        label = label.decode('utf-8')
    if len(label) == 0:
        raise IDNAException('Empty label detected')
    ensure_nfc_compliance(label)
    validate_hyphen_usage(label)
    validate_initial_combiner(label)
    for (pos, char) in enumerate(label):
        char_code = ord(char)
        if intranges_contain(char_code, idnadata.codepoint_classes['PVALID']):
            continue
        elif intranges_contain(char_code, idnadata.codepoint_classes['CONTEXTJ']):
            try:
                if not is_valid_context_j(label, pos):
                    raise InvalidContextualRule('Joiner {} not permitted at position {} in {}'.format(
                        _format_codepoint_string(char_code), pos+1, repr(label)))
            except ValueError:
                raise IDNAException('Unknown codepoint adjacent to joiner {} at position {} in {}'.format(
                    _format_codepoint_string(char_code), pos+1, repr(label)))
        elif intranges_contain(char_code, idnadata.codepoint_classes['CONTEXTO']):
            if not is_valid_context_o(label, pos):
                raise InvalidContextualRule('Codepoint {} not permitted at position {} in {}'.format(
                    _format_codepoint_string(char_code), pos+1, repr(label)))
        else:
            raise InvalidCodepointValue('Codepoint {} at position {} of {} not permitted'.format(
                _format_codepoint_string(char_code), pos+1, repr(label)))
    validate_bidirectional(label)

def encode_to_ascii(label: str) -> bytes:
    try:
        ascii_bytes = label.encode('ascii')
        decode_from_ascii(ascii_bytes)
        if not is_valid_label_size(ascii_bytes):
            raise IDNAException('Label exceeds maximum length')
        return ascii_bytes
    except UnicodeEncodeError:
        pass
    if not label:
        raise IDNAException('No input provided')
    label = str(label)
    validate_single_label(label)
    ascii_bytes = _encode_punycode(label)
    ascii_bytes = _alabel_prefix_str + ascii_bytes
    if not is_valid_label_size(ascii_bytes):
        raise IDNAException('Label too long')
    return ascii_bytes

def decode_from_ascii(label: Union[str, bytes, bytearray]) -> str:
    if not isinstance(label, (bytes, bytearray)):
        try:
            ascii_bytes = label.encode('ascii')
        except UnicodeEncodeError:
            validate_single_label(label)
            return label
    else:
        ascii_bytes = label
    ascii_bytes = ascii_bytes.lower()
    if ascii_bytes.startswith(_alabel_prefix_str):
        ascii_bytes = ascii_bytes[len(_alabel_prefix_str):]
        if not ascii_bytes:
            raise IDNAException('Malformed A-label: no valid Punycode content found')
        if ascii_bytes.decode('ascii')[-1] == '-':
            raise IDNAException('A-label must not conclude with a hyphen')
    else:
        validate_single_label(ascii_bytes)
        return ascii_bytes.decode('ascii')
    try:
        decoded_text = ascii_bytes.decode('punycode')
    except UnicodeError:
        raise IDNAException('Invalid A-label encoding')
    validate_single_label(decoded_text)
    return decoded_text

def process_uts46(domain: str, apply_std3: bool = True, use_transitional: bool = False) -> str:
    """Process domain string according to UTS46 mapping rules."""
    from .uts46data import uts46data
    result = ''
    for idx, char in enumerate(domain):
        code_point = ord(char)
        try:
            row_index = code_point if code_point < 256 else \
                bisect.bisect_left(uts46data, (code_point, 'Z')) - 1
            uts46_row = uts46data[row_index]
            status_flag = uts46_row[1]
            replacement_char = None  # type: Optional[str]
            if len(uts46_row) == 3:
                replacement_char = uts46_row[2]  # type: ignore
            if (status_flag == 'V' or
                    (status_flag == 'D' and not use_transitional) or
                    (status_flag == '3' and not apply_std3 and replacement_char is None)):
                result += char
            elif replacement_char is not None and (status_flag == 'M' or
                    (status_flag == '3' and not apply_std3) or
                    (status_flag == 'D' and use_transitional)):
                result += replacement_char
            elif status_flag != 'I':
                raise IndexError()
        except IndexError:
            raise InvalidCodepointValue(
                'Codepoint {} not allowed at position {} in {}'.format(
                _format_codepoint_string(code_point), idx + 1, repr(domain)))
    return unicodedata.normalize('NFC', result)

def encode_domain(input_str: Union[str, bytes, bytearray], strict_mode: bool = False, 
                  uts46_process: bool = False, std3_enabled: bool = False, 
                  transitional_mode: bool = False) -> bytes:
    if isinstance(input_str, (bytes, bytearray)):
        try:
            input_str = input_str.decode('ascii')
        except UnicodeDecodeError:
            raise IDNAException('Byte string must be valid ASCII')
    if uts46_process:
        input_str = process_uts46(input_str, std3_enabled, transitional_mode)
    has_trailing_dot = False
    output_parts = []
    if strict_mode:
        parts = input_str.split('.')
    else:
        parts = _unicode_dots_pattern.split(input_str)
    if not parts or parts == ['']:
        raise IDNAException('Domain cannot be empty')
    if parts[-1] == '':
        parts.pop()
        has_trailing_dot = True
    for part in parts:
        encoded_part = encode_to_ascii(part)
        if encoded_part:
            output_parts.append(encoded_part)
        else:
            raise IDNAException('Empty label encountered')
    if has_trailing_dot:
        output_parts.append(b'')
    final_result = b'.'.join(output_parts)
    if not is_valid_total_size(final_result, has_trailing_dot):
        raise IDNAException('Domain name exceeds maximum length')
    return final_result

def decode_domain(input_str: Union[str, bytes, bytearray], strict_mode: bool = False,
                  uts46_process: bool = False, std3_enabled: bool = False) -> str:
    try:
        if isinstance(input_str, (bytes, bytearray)):
            input_str = input_str.decode('ascii')
    except UnicodeDecodeError:
        raise IDNAException('Invalid ASCII in A-label')
    if uts46_process:
        input_str = process_uts46(input_str, std3_enabled, False)
    has_trailing_dot = False
    output_parts = []
    if not strict_mode:
        parts = _unicode_dots_pattern.split(input_str)
    else:
        parts = input_str.split('.')
    if not parts or parts == ['']:
        raise IDNAException('Domain cannot be empty')
    if not parts[-1]:
        parts.pop()
        has_trailing_dot = True
    for part in parts:
        decoded_part = decode_from_ascii(part)
        if decoded_part:
            output_parts.append(decoded_part)
        else:
            raise IDNAException('Empty label found')
    if has_trailing_dot:
        output_parts.append('')
    return '.'.join(output_parts)

# Setup script for CUDA extension with fake int4 quantization
from setuptools import setup
from torch.utils.cpp_extension import BuildExtension, CUDAExtension
import torch
import os

# Collect supported CUDA architectures
supported_archs = []
if torch.cuda.is_available():
    for device_idx in range(torch.cuda.device_count()):
        major_ver, minor_ver = torch.cuda.get_device_capability(device_idx)
        supported_archs.append(f"{major_ver}.{minor_ver}")
    supported_archs = sorted(set(supported_archs))

# Fallback to environment variable or default architectures if no GPU detected
if not supported_archs:
    env_var = os.environ.get("TORCH_CUDA_ARCH_LIST", "")
    if env_var:
        # Parse TORCH_CUDA_ARCH_LIST: e.g., "7.0;7.5 8.0+PTX" -> ["7.0", "7.5", "8.0"]
        supported_archs = [
            arch.strip().replace("+PTX", "") 
            for arch in env_var.replace(";", " ").split() 
            if arch.strip()
        ]
    else:
        # Default common architectures (Volta, Turing, Ampere, Ada, Hopper)
        supported_archs = ["8.0", "8.6", "8.9", "9.0"]

setup(
    name="fake_int4_quant_cuda",
    ext_modules=[
        CUDAExtension(
            name="fake_int4_quant_cuda",
            sources=["fake_int4_quant_cuda.cu"],
            extra_compile_args={
                "cxx": [
                    "-O3",
                    "-std=c++17",
                ],
                "nvcc": [
                    "-O3",
                    "-std=c++17",
                    "--expt-relaxed-constexpr",
                    "-Xcompiler",
                    "-fPIC",
                ]
                + [
                    f'-gencode=arch=compute_{arch.replace(".", "")},code=sm_{arch.replace(".", "")}'
                    for arch in supported_archs
                ]
                + ["-gencode=arch=compute_90a,code=sm_90a"],
