)

# Calculate token usage costs and display statistics
from statgpt.common.schemas.token_usage import TokenUsageItem, TokenUsagePricedItem

class PricingCalculator:
    def __init__(self, pricing_map: dict) -> None:
        self._pricing_map = pricing_map

    def compute_priced_usage(
        self, usage_records: list[TokenUsageItem]
    ) -> list[TokenUsagePricedItem]:
        return [
            TokenUsagePricedItem(
                deployment=record.deployment,
                model=record.model,
                prompt_tokens=record.prompt_tokens,
                completion_tokens=record.completion_tokens,
                costs=self._compute_single_cost(record),
            )
            for record in usage_records
        ]

    def _compute_single_cost(self, record: TokenUsageItem) -> float | None:
        """Compute the cost for a single usage record."""
        if pricing_info := self._pricing_map.get(record.model):
            return (
                record.prompt_tokens * pricing_info.prompt
                + record.completion_tokens * pricing_info.completion
            )
        return None


class UsageReportGenerator:
    COLUMN_LABELS = {
        "deployment": "Deployment",
        "model": "Model",
        "prompt_tokens": "Prompt Tokens",
        "completion_tokens": "Completion Tokens",
        "total_tokens": "Total Tokens",
        "costs": "Total Price, $",
    }
    MISSING_VALUE = "-"

    @classmethod
    def to_markdown_table(cls, priced_usage: list[TokenUsagePricedItem]) -> str:
        """Transform token usage data into a Markdown table format."""
        import pandas as pd

        df = pd.DataFrame(
            [entry.model_dump(by_alias=True) for entry in priced_usage],
            columns=list(cls.COLUMN_LABELS.keys()),
        )
        summary_row = cls._generate_summary_row(df)
        df = pd.concat([df, summary_row], ignore_index=True)
        df.rename(columns=cls.COLUMN_LABELS, inplace=True)
        df.fillna(cls.MISSING_VALUE, inplace=True)
        return df.to_markdown(index=False)

    @staticmethod
    def _generate_summary_row(df: pd.DataFrame) -> pd.DataFrame:
        """Create a summary row with totals for numeric columns."""
        column_sums = df.sum(numeric_only=True)
        return pd.DataFrame(
            {
                "deployment": "",
                "model": "TOTAL:",
                "prompt_tokens": column_sums.get("prompt_tokens"),
                "completion_tokens": column_sums.get("completion_tokens"),
                "total_tokens": column_sums.get("total_tokens"),
                "costs": column_sums.get("costs"),
            },
            index=[0],
        )

    @staticmethod
    def sum_costs(priced_usage: list[TokenUsagePricedItem]) -> float:
        """Calculate total cost from priced usage records."""
        if not priced_usage:
            return 0.0
        return sum(entry.costs for entry in priced_usage if entry.costs)

    @staticmethod
    def format_total_cost(priced_usage: list[TokenUsagePricedItem]) -> str:
        """Format total cost as a string with three decimal places."""
        total = UsageReportGenerator.sum_costs(priced_usage)
        return f"{total:.3f}"

    @classmethod
    def to_list_format(cls, priced_usage: list[TokenUsagePricedItem]) -> str:
        """Convert token usage data into a formatted Markdown list."""
        output = ""
        for entry in priced_usage:
            output += f"### {entry.model}\n"
            output += f"* Prompt Tokens: {entry.prompt_tokens}\n"
            output += f"* Completion Tokens: {entry.completion_tokens}\n"
            output += f"* Total Tokens: {entry.total_tokens}\n"
            if entry.costs is None:
                output += "* Total Price: <NO DATA>\n\n"
            else:
                output += f"* Total Price, $: {entry.costs:.3f}\n\n"

        # Aggregate totals
        total_prompt = sum(item.prompt_tokens for item in priced_usage if item.prompt_tokens)
        total_completion = sum(
            item.completion_tokens for item in priced_usage if item.completion_tokens
        )
        total_tokens = sum(item.total_tokens for item in priced_usage if item.total_tokens)
        total_price_str = cls.format_total_cost(priced_usage)

        output += "-" * 15 + "\n"
        output += "## TOTAL:\n"
        output += f"* Prompt Tokens: {total_prompt}\n"
        output += f"* Completion Tokens: {total_completion}\n"
        output += f"* Total Tokens: {total_tokens}\n"
        output += f"* Total Price, $: {total_price_str}\n"
        return output

