from datetime import datetime
from pydantic import BaseModel, ConfigDict, Field, StrictStr, ValidationError, field_validator
from typing import Optional
from typing import Union, Any, List, Set, TYPE_CHECKING, Dict
from typing_extensions import Literal, Self
from pydantic import Field

TIMESTAMP_ANY_OF_SCHEMAS = ["datetime", "str"]

class Timestamp(BaseModel):
    """
    When the content occurred. Accepts an ISO 8601 datetime string (e.g. '2024-01-15T10:30:00Z'), null/omitted (defaults to now), or the special string 'unset' to explicitly store without any timestamp (use this for timeless content such as fictional documents or static reference material).
    """
    # data type: datetime
    anyof_schema_1_validator: Optional[datetime] = None
    # data type: str
    anyof_schema_2_validator: Optional[StrictStr] = None
    if TYPE_CHECKING:
        actual_instance: Optional[Union[datetime, str]] = None
    else:
        actual_instance: Any = None
    any_of_schemas: Set[str] = { "datetime", "str" }
    model_config = {
        "validate_assignment": True,
        "protected_namespaces": (),
    }

    def __init__(self, *args, **kwargs) -> None:
        if args:
            if len(args) > 1:
                raise ValueError("If a position argument is used, only 1 is allowed to set `actual_instance`")
            if kwargs:
                raise ValueError("If a position argument is used, keyword arguments cannot be used.")
            super().__init__(actual_instance=args[0])
        else:
            super().__init__(**kwargs)

    @field_validator('actual_instance')
    def actual_instance_must_validate_anyof(cls, v):
        if v is None:
            return v
        instance = Timestamp.model_construct()
        error_messages = []
        # validate data type: datetime
        try:
            instance.anyof_schema_1_validator = v
            return v
        except (ValidationError, ValueError) as e:
            error_messages.append(str(e))
        # validate data type: str
        try:
            instance.anyof_schema_2_validator = v
            return v
        except (ValidationError, ValueError) as e:
            error_messages.append(str(e))
        if error_messages:
            # no match
            raise ValueError("No match found when setting the actual_instance in Timestamp with anyOf schemas: datetime, str. Details: " + ", ".join(error_messages))
        else:
            return v

    @classmethod
    def from_dict(cls, obj: Dict[str, Any]) -> Self:
        return cls.from_json(json.dumps(obj))

    @classmethod
    def from_json(cls, json_str: str) -> Self:
        """Returns the object represented by the json string"""
        instance = cls.model_construct()
        if json_str is None:
            return instance
        error_messages = []
        # deserialize data into datetime
        try:
            # validation
            instance.anyof_schema_1_validator = json.loads(json_str)
            # assign value to actual_instance
            instance.actual_instance = instance.anyof_schema_1_validator
            return instance
        except (ValidationError, ValueError) as e:
            error_messages.append(str(e))
        # deserialize data into str
        try:
            # validation
            instance.anyof_schema_2_validator = json.loads(json_str)
            # assign value to actual_instance
            instance.actual_instance = instance.anyof_schema_2_validator
            return instance
        except (ValidationError, ValueError) as e:
            error_messages.append(str(e))
        if error_messages:
            # no match
            raise ValueError("No match found when deserializing the JSON string into Timestamp with anyOf schemas: datetime, str. Details: " + ", ".join(error_messages))
        else:
            return instance

    def to_json(self) -> str:
        """Returns the JSON representation of the actual instance"""
        if self.actual_instance is None:
            return "null"
        if hasattr(self.actual_instance, "to_json") and callable(self.actual_instance.to_json):
            return self.actual_instance.to_json()
        else:
            return json.dumps(self.actual_instance)

    def to_dict(self) -> Optional[Union[Dict[str, Any], datetime, str]]:
        """Returns the dict representation of the actual instance"""
        if self.actual_instance is None:
            return None
        if hasattr(self.actual_instance, "to_dict") and callable(self.actual_instance.to_dict):
            return self.actual_instance.to_dict()
        else:
            return self.actual_instance

    def to_str(self) -> str:
        """Returns the string representation of the actual instance"""
        return pprint.pformat(self.model_dump())

# Type I clone: Renamed variables, changed literals, reordered statements, modified comments
from typing import Callable, Iterator, List, Optional, Set, Tuple, Union
import torch
import torch.nn as nn
from torch.distributed.fsdp import (
    fully_shard,
)
SubtreeSpec = Union[Tuple[nn.Module, torch.dtype], Tuple[str, nn.Module, torch.dtype]]

def traverse_maximal_uniform_dtype_submodules(
    root_module: nn.Module,
    *,
    consider_buffers: bool = True,
    tensor_filter: Optional[Callable[[torch.Tensor], bool]] = None,
    include_paths: bool = False,
) -> Iterator[SubtreeSpec]:
    """
    Walk through `root_module` and produce maximal submodules where all tensors in the subtree share a single dtype.
    - consider_buffers: whether to incorporate buffers when checking dtype consistency.
    - tensor_filter: function to select which tensors to examine (default: all tensors).
                     Example: tensor_filter=torch.is_floating_point  (to focus only on floating-point tensors)
    - include_paths: if True, yields (qualified_name, submodule, dtype); otherwise (submodule, dtype).
    Notes:
    - Subtrees lacking any tensors matching `tensor_filter` are skipped.
    - Maximality guarantees no yielded submodule is nested inside another yielded one.
    """
    if tensor_filter is None:
        tensor_filter = lambda t: True

    def _collect_local_dtypes(submodule: nn.Module) -> Set[torch.dtype]:
        dtypes: Set[torch.dtype] = set()
        for param in submodule.parameters(recurse=False):
            if tensor_filter(param):
                dtypes.add(param.dtype)
        if consider_buffers:
            for buffer in submodule.buffers(recurse=False):
                if tensor_filter(buffer):
                    dtypes.add(buffer.dtype)
        return dtypes

    def _explore(module: nn.Module, path: Tuple[str, ...]) -> Tuple[Set[torch.dtype], List[SubtreeSpec]]:
        local_dtypes = _collect_local_dtypes(module)
        combined_dtypes: Set[torch.dtype] = set(local_dtypes)
        results: List[SubtreeSpec] = []

        # Explore child modules
        for child_name, child_module in module.named_children():
            child_dtypes, child_results = _explore(child_module, path + (child_name,))
            combined_dtypes |= child_dtypes
            results.extend(child_results)

        # If entire subtree has exactly one dtype (and not empty), this node is maximal
        if len(combined_dtypes) == 1:
            if combined_dtypes:
                dtype = next(iter(combined_dtypes))
                if include_paths:
                    full_path = ".".join(path)  # empty string at root
                    return combined_dtypes, [(full_path, module, dtype)]
                else:
                    return combined_dtypes, [(module, dtype)]
            # else: no tensors in subtree -> skip entirely
        # Non-uniform dtype -> inherit maximal sets from children
        return combined_dtypes, results

    _, subtrees = _explore(root_module, ())

    # Yield results sequentially
    for item in subtrees:
        yield item

def _partition_parameters_by_dtype(layer):
    result = {}
    for name, param in layer.named_parameters():
        if param.dtype not in result:
            result[param.dtype] = []
        result[param.dtype].append(param)
    return result

def _resolve_module_by_path(model, path_str):
    for segment in path_str.split("."):
        model = getattr(model, segment)
    return model

def _apply_fully_shard(module, mesh, mp_policy, offload_policy):
    if isinstance(module, nn.ModuleList):
        for sublayer in module:
            _apply_fully_shard(sublayer, mesh, mp_policy, offload_policy)
    else:
        fully_shard(module, mesh=mesh, mp_policy=mp_policy, offload_policy=offload_policy)

def fully_shard_by_precision(module, mesh, mp_policy, offload_policy):
    # Note: calling _partition_parameters_by_dtype here may cause double traversal,
    # but this path is not performance-critical.
    param_groups = _partition_parameters_by_dtype(module)
    if len(param_groups) == 0:
        return
    elif len(param_groups) == 1:
        _apply_fully_shard(module, mesh, mp_policy, offload_policy)
    else:
        smallest_group_dtype = min(param_groups.items(), key=lambda x: len(x[1]))[0]
        for path, mod, dtype in traverse_maximal_uniform_dtype_submodules(
            module,
            tensor_filter=torch.is_floating_point,
            include_paths=True,
        ):
            if (len(param_groups) == 2 and dtype == smallest_group_dtype) or len(param_groups) > 2:
                _apply_fully_shard(
                    _resolve_module_by_path(module, path),
                    mesh=mesh,
                    mp_policy=mp_policy,
                    offload_policy=offload_policy,
                )
        if len(param_groups) == 2:
            _apply_fully_shard(module, mesh=mesh, mp_policy=mp_policy, offload_policy=offload_policy)

