def retrieve_compliance_tags(rule_identifier):
    return COMPLIANCE_MAPPINGS.get(rule_identifier, [])

def add_compliance_info_to_finding(finding_data):
    rule_id = finding_data.get("rule_id", "")
    compliance_tags = retrieve_compliance_tags(rule_id)
    if compliance_tags:
        finding_data["compliance_tags"] = compliance_tags
        display_strings = []
        for tag in compliance_tags:
            framework_name = FRAMEWORK_DISPLAY_NAMES.get(tag["framework"], tag["framework"])
            display_strings.append(f"{framework_name} {tag['requirement']}")
        finding_data["compliance_display"] = display_strings
    return finding_data

def add_compliance_info_to_findings(findings_list):
    for item in findings_list:
        add_compliance_info_to_finding(item)
    return findings_list

