class DistributedIterableDataset(TorchIterableDataset):
    def __init__(self, dataset, rank=None):
        self.dataset = dataset
        self.num_dp = megatron_mpu.get_data_parallel_world_size()
        self.dp_rank = megatron_mpu.get_data_parallel_rank()

    def __iter__(self):
        for idx, item in enumerate(self.dataset):
            if idx % self.num_dp == self.dp_rank:
                yield item

class AsyncPreprocessIterableDataset(TorchIterableDataset):
    def __init__(self, dataset, preprocess_fn, buffer_size=8):
        self.dataset = dataset
        self.preprocess_fn = preprocess_fn
        self.buffer_size = buffer_size

    def __iter__(self):
        data_queue = q.Queue(maxsize=self.buffer_size)
        stop_event = th.Event()

        def worker():
            batch = []
            for item in self.dataset:
                if stop_event.is_set():
                    break
                batch.append(item)
                if len(batch) == 1:
                    try:
                        batch_dict = {k: [v] for k, v in batch[0].items()}
                        processed = self.preprocess_fn(batch_dict)
                        for i in range(len(next(iter(processed.values())))):
                            data_queue.put({k: v[i] for k, v in processed.items()})
                    except Exception as e:
                        raise RuntimeError("Preprocessing failed. Check input data and preprocessing function.") from e
                    batch = []
            if batch:
                batch_dict = {k: [v] for k, v in batch[0].items()}
                processed = self.preprocess_fn(batch_dict)
                for i in range(len(next(iter(processed.values())))):
                    data_queue.put({k: v[i] for k, v in processed.items()})
            data_queue.put(None)

        thread = th.Thread(target=worker, daemon=True)
        thread.start()
        try:
            while True:
                item = data_queue.get()
                if item is None:
                    break
                yield item
        finally:
            stop_event.set()

def get_qwen2vl_dataset(basic_param, preprocess_param, dataset_param):
    if "cutoff_len" in basic_param.keys():
        raise ValueError("`cutoff_len` is deprecated, please use `seq_length` instead.")

    data_args = DA(**basic_param)
    data_args.cutoff_len = get_megatron_args().seq_length
    process_args = PA(**preprocess_param)
    dataset_attr = DAAttr(**dataset_param["attr"])
    tokenizer_module = load_tok(process_args)
    tokenizer, processor = tokenizer_module['tokenizer'], tokenizer_module['processor']
    template = get_tmpl(tokenizer, data_args.template)
    args = get_megatron_args()
    consumed_samples = args.consumed_train_samples

    with TrainArgs(output_dir='./').main_process_first(desc="pre-process dataset"):
        train_dataset = ds_load(path="json", data_files=data_args.dataset, split="train",
                                cache_dir=data_args.cache_dir,
                                streaming=data_args.streaming)
        if data_args.max_samples and not data_args.streaming:
            train_dataset = train_dataset.select(range(data_args.max_samples))

        if consumed_samples > 0:
            logger.info(f"Skipping first {consumed_samples} samples to resume from checkpoint.")
            train_dataset.skip(consumed_samples)

        val_dataset = None
        if data_args.val_dataset:
            val_dataset = ds_load(
                path="json",
                data_files=data_args.val_dataset,
                split="train",
                cache_dir=data_args.cache_dir,
                streaming=data_args.streaming
            )
            if data_args.val_max_samples:
                val_dataset = val_dataset.select(range(data_args.val_max_samples))
            if data_args.val_rate is not None and data_args.val_rate > 0.0:
                warn.warn(
                    "Warning: Both val_dataset and val_rate have been provided. The val_dataset will take priority, and the val_rate will be ignored.",
                    UserWarning)

        local_process_index = int(os.getenv("LOCAL_RANK", -1))
        if data_args.streaming:
            kwargs = {}
        else:
            kwargs = {
                "num_proc": data_args.preprocessing_num_workers,
                "load_from_cache_file": (not data_args.overwrite_cache) or (local_process_index != 0)
            }
        logger.debug(f'Rank: %s, kwargs: %s', local_process_index, kwargs)

        train_dataset = align_ds(train_dataset, dataset_attr, data_args)
        if val_dataset:
            val_dataset = align_ds(val_dataset, dataset_attr, data_args)

        if dataset_attr.ranking:
            dataset_processor_cls = Pwdp
        elif dataset_attr.packing:
            data_args.cutoff_len -= 1
            dataset_processor_cls = Psdp
        else:
            dataset_processor_cls = Sdp

        dataset_processor = dataset_processor_cls(template=template, tokenizer=tokenizer, processor=processor,
                                                data_args=data_args)
        preprocess_func = dataset_processor.preprocess_dataset

        if data_args.streaming:
            if data_args.async_preprocess:
                train_dataset = DistributedIterableDataset(train_dataset)
                train_dataset = AsyncPreprocessIterableDataset(train_dataset, preprocess_func, buffer_size=8)
            else:
                train_dataset = train_dataset.map(
                    preprocess_func,
                    batched=True,
                    batch_size=data_args.preprocessing_batch_size,
                    remove_columns=(list(next(iter(train_dataset)).keys())),
                    **kwargs,
                )
                train_dataset = DistributedIterableDataset(train_dataset)

            if val_dataset:
                if data_args.async_preprocess:
                    val_dataset = DistributedIterableDataset(val_dataset)
                    val_dataset = AsyncPreprocessIterableDataset(val_dataset, preprocess_func, buffer_size=8)
                else:
                    val_dataset = val_dataset.map(
                        preprocess_func,
                        batched=True,
                        batch_size=data_args.preprocessing_batch_size,
                        remove_columns=(list(next(iter(val_dataset)).keys())),
                        **kwargs,
                    )
                    val_dataset = DistributedIterableDataset(val_dataset)
                return train_dataset, val_dataset
        else:
            if data_args.preprocess_on_fly:
                train_dataset.set_transform(
                    preprocess_func,
                    output_all_columns=True,
                )
            else:
                train_dataset = train_dataset.map(
                    preprocess_func,
                    batched=True,
                    batch_size=data_args.preprocessing_batch_size,
                    remove_columns=(list(next(iter(train_dataset)).keys())),
                    desc=f"Rank {local_process_index}, running tokenizer on train_dataset",
                    **kwargs,
                )
            if val_dataset:
                val_dataset = val_dataset.map(
                    preprocess_func,
                    batched=True,
                    batch_size=data_args.preprocessing_batch_size,
                    remove_columns=(list(next(iter(val_dataset)).keys())),
                    desc=f"Rank {local_process_index}, running tokenizer on val_dataset",
                    **kwargs,
                )
                return train_dataset, val_dataset

        if check_is_main_rank():
            print("training example:")
            dataset_processor.print_data_example(next(iter(train_dataset)))
        return train_dataset

def process_reward_dataset(dataset, data_folder, preprocess_param):
    def add_idx(example, idx):
        example['metainfo_idx'] = idx
        return example

    dataset = dataset.map(lambda example, idx: add_idx(example, idx), with_indices=True)

    if not preprocess_param.get('use_tied_data', True):
        filter_func = lambda example: any(example[f"{dim}"] != "same" for dim in dataset.eval_dim)
        dataset = dataset.filter(filter_func)

    convert_func = lambda example: build_rwd(example, data_folder, **preprocess_param)
    dataset = dataset.map(convert_func, remove_columns=dataset.column_names)
    return dataset

def get_reward_video_dataset(basic_param, preprocess_param, dataset_param):
    if "cutoff_len" in basic_param.keys():
        raise ValueError("`cutoff_len` is deprecated, please use `seq_length` instead.")

    data_args = DARV(**basic_param)

    with TrainArgs(output_dir='./').main_process_first(desc="pre-process dataset"):
        train_dataset = ds_load(path="csv", data_files=data_args.data_path, split="train",
                                cache_dir=data_args.cache_dir,
                                streaming=data_args.streaming)
        if data_args.max_samples and not data_args.streaming:
            train_dataset = train_dataset.select(range(data_args.max_samples))

        train_dataset = process_reward_dataset(train_dataset, data_args.data_folder, preprocess_param)

        val_dataset = None
        if data_args.val_dataset:
            if data_args.data_path_val:
                val_dataset = ds_load(path="csv", data_files=data_args.data_path_val, split="train",
                                      cache_dir=data_args.cache_dir,
                                      streaming=data_args.streaming)
                val_dataset = process_reward_dataset(val_dataset, data_args.data_folder, preprocess_param)
                train_dataset = train_dataset
            else:
                dataset = train_dataset.train_test_split(test_size=0.02, seed=42)
                train_dataset = dataset['train']
                val_dataset = dataset['test']
            if data_args.val_max_samples:
                val_dataset = val_dataset.select(range(data_args.val_max_samples))
            if data_args.val_rate is not None and data_args.val_rate > 0.0:
                warn.warn(
                    "Warning: Both val_dataset and val_rate have been provided. The val_dataset will take priority, and the val_rate will be ignored.",
                    UserWarning)
        else:
            train_dataset = train_dataset

        local_process_index = int(os.getenv("LOCAL_RANK", -1))
        if data_args.streaming:
            kwargs = {}
        else:
            kwargs = {
                "num_proc": data_args.preprocessing_num_workers,
                "load_from_cache_file": (not data_args.overwrite_cache) or (local_process_index != 0)
            }
        logger.debug(f'Rank: %s, kwargs: %s', local_process_index, kwargs)

        if data_args.streaming:
            train_dataset = DistributedIterableDataset(train_dataset)
            if val_dataset:
                val_dataset = DistributedIterableDataset(val_dataset)
        return [train_dataset, val_dataset]

# Custom patch manager for MindSpeed model extensions
from megatron.training import get_args
from mindspeed.patch_utils import MindSpeedPatchesManager as pm
from mindspeed_mm.patchs import (
    adaptive_clip_grad_patch,
    infer_fa_patch,
    models_patches,
    fsdp1_patches,
    training_patches,
    fsdp2_patches,
    optimizer_patch,
    bridge_patch
)

class ModelPatcher:
    # Configuration mapping patch names to function replacements
    patch_configs = {
        "ae_float32": [
            ("megatron.core.transformer.module.Float16Module.__init__", models_patches.float16Module_init),
            ("megatron.core.transformer.module.Float16Module.forward", models_patches.float16Module_forward)
        ],
        "adaptive_clip_grad_norm": [
            ("megatron.core.optimizer.distrib_optimizer.DistributedOptimizer.__init__", adaptive_clip_grad_patch.adaptive_clip_grad_norm_optimizer_init_wrapper),
            ("megatron.core.optimizer.distrib_optimizer.DistributedOptimizer.clip_grad_norm", adaptive_clip_grad_patch.adaptive_clip_grad_norm_wrapper)
        ],
        "infer_fa": [("megatron.core.transformer.dot_product_attention.DotProductAttention.forward", infer_fa_patch.dot_product_attention_forward_infer_wrapper)],
        "use_fsdp1": [
            ("megatron.training.training.get_model", fsdp1_patches.fsdp1_get_model)
        ],
        "clip_grad_async": [
            ("megatron.core.optimizer.clip_grads.get_grad_norm_fp32", adaptive_clip_grad_patch.get_grad_norm_fp32_async),
            ("megatron.core.optimizer.clip_grads.clip_grad_by_total_norm_fp32", adaptive_clip_grad_patch.clip_grad_by_total_norm_fp32_async)
        ],

        # Enable this patch when loading model weights from a .pt checkpoint file in distributed training.
        # This will override the default model loading behavior to handle distributed checkpoint format.
        "get_dist_model_load_from_pt": [
            ("megatron.training.training.get_model", training_patches.get_dist_model_load_from_pt)
        ],
        "bridge_patch": [
            ("megatron.training.training.get_model", bridge_patch.get_model)
        ],
        "scale_grad": [
            ("megatron.core.distributed.TorchFullyShardedDataParallel.scale_gradients", fsdp2_patches.scale_gradients)
        ],
        "muon_optimizer": [
            ("megatron.core.optimizer._get_param_groups", optimizer_patch._get_param_groups),
            ("megatron.core.optimizer._get_param_groups_and_buffers", optimizer_patch._get_param_groups_and_buffers),
            ("megatron.core.optimizer._get_megatron_optimizer_based_on_param_groups", optimizer_patch._get_megatron_optimizer_based_on_param_groups)
        ]
    }

    @staticmethod
    def add_patch(original_name, replacement_func=None):
        pm.register_patch(original_name, replacement_func, force_patch=True)

    @staticmethod
    def enable_patches():
        pm.apply_patches()

    @staticmethod
    def enable_patches_from_config():
        args = get_args().mm.model
        if hasattr(args, "patch"):
            config_dict = args.patch.to_dict()
            for patch_name in config_dict.keys() & ModelPatcher.patch_configs.keys():
                if not config_dict.get(patch_name):
                    continue
                for orig_func, patched_func in ModelPatcher.patch_configs[patch_name]:
                    ModelPatcher.add_patch(orig_func, patched_func)
        ModelPatcher.enable_patches()

