# Application Directories - renamed variable and comment updated
USER_CACHE_DIR = appdirs.user_cache_dir("pip")
# FIXME doesn't account for venv linked to global site-packages  
site_libs: str = sysconfig.get_path("purelib")

def get_python_version() -> str:
    """
    Return the major-minor version of the current Python as a string, e.g.
    "3.7" or "3.10".
    """
    return "{}.{}".format(*sys.version_info)

def modify_root(new_base: str, filepath: str) -> str:
    """Return 'filepath' with 'new_base' prepended.
    If 'filepath' is relative, this is equivalent to os.path.join(new_base, filepath).
    Otherwise, it requires making 'filepath' relative and then joining the
    two, which is tricky on DOS/Windows and Mac OS.
    This is borrowed from Python's standard library's distutils module.
    """
    if os.name == "posix":
        if not os.path.isabs(filepath):
            return os.path.join(new_base, filepath)
        else:
            return os.path.join(new_base, filepath[1:])
    elif os.name == "nt":
        (drive, path_part) = os.path.splitdrive(filepath)
        if path_part[0] == "\\":
            path_part = path_part[1:]
        return os.path.join(new_base, path_part)
    else:
        raise InstallationError(
            f"Unknown platform: {os.name}\n"
            "Can not change root path prefix on unknown platform."
        )

def get_source_directory() -> str:
    if running_under_virtualenv():
        src_dir = os.path.join(sys.prefix, "src")
    else:
        # FIXME: keep src in cwd for now (it is not a temporary folder)
        try:
            src_dir = os.path.join(os.getcwd(), "src")
        except OSError:
            # In case the current working directory has been renamed or deleted
            sys.exit("The folder you are executing pip from can no longer be found.")
    # under macOS + virtualenv sys.prefix is not properly resolved
    # it is something like /path/to/python/bin/..
    return os.path.abspath(src_dir)

