from examples.mem_reader.samples import SYSTEM_MESSAGE_CASES
from memos.mem_reader.read_multi_modal.system_parser import SystemParser
from ._base import BaseParserDemo

class SystemParserDemo(BaseParserDemo):
    def create_parser(self):
        # Instantiate and return the SystemParser with embedder and LLM
        return SystemParser(embedder=self.embedder, llm=self.llm)

    def run(self):
        print("=== SystemParser Demo ===")
        context_info = {"user_id": "user1", "session_id": "session1"}

        for scenario in SYSTEM_MESSAGE_CASES:
            print(f"\n--- Scenario: {scenario.description} ---")

            for message in scenario.scene_data:
                # Handle list-type content by flattening to string
                # Workaround: SystemParser only accepts str/dict content, not lists
                processed_msg = message
                if isinstance(message.get("content"), list):
                    processed_msg = message.copy()
                    content_parts = message["content"]
                    combined_text = "".join(
                        part.get("text", "")
                        for part in content_parts
                        if isinstance(part, dict) and part.get("type") == "text"
                    )
                    processed_msg["content"] = combined_text

                # Create demo source and process the message
                source = self.demo_source_creation(processed_msg, context_info)
                self.demo_rebuild(source)
                self.demo_parse_fast(processed_msg, context_info)

if __name__ == "__main__":
    demo_instance = SystemParserDemo()
    demo_instance.run()

