import narwhals as nw
import polars as pl
from typing import Any, overload
from narwhals.typing import DataFrameT, Frame, FrameT, LazyFrameT

def convert_to_polars_eager(frame: Frame) -> pl.DataFrame:
    """Helper to transform a Narwhals frame into an eager Polars DataFrame."""
    return frame.lazy().collect().to_polars()

def convert_lazy_to_polars(frame: nw.LazyFrame[Any]) -> pl.LazyFrame:
    """Helper to convert a Narwhals lazy frame into a Polars lazy frame.
    If the Narwhals LazyFrame is already backed by Polars, this operation does nothing."""
    if frame.implementation == nw.Implementation.POLARS:
        return frame.to_native()
    return frame.collect().to_polars().lazy()

@overload
def adapt_to_polars_implementation(frame: DataFrameT) -> DataFrameT: ...
@overload
def adapt_to_polars_implementation(frame: LazyFrameT) -> LazyFrameT: ...

def adapt_to_polars_implementation(frame: FrameT) -> FrameT:
    if frame.implementation == nw.Implementation.POLARS:
        return frame
    elif isinstance(frame, nw.DataFrame):
        return nw.from_native(frame.to_polars())
    elif isinstance(frame, nw.LazyFrame):
        return nw.from_native(
            frame.collect().to_polars(),
        ).lazy()
    else:
        raise ValueError(f"Unsupported frame type: {type(frame)}")

__all__ = ["convert_to_polars_eager"]

# Convert location objects to string representations for logging or display

from typing import Union, List, Any, Sequence
from opentrons.protocol_api.labware import Well
from opentrons.types import Location

# Define the type alias for location inputs
CommandLocation = Union[Location, None, Sequence, Well]

def flatten_location(location: Any) -> List:
    # Recursively process nested lists of locations
    if isinstance(location, list):
        if len(location) == 0:
            return [location]
        else:
            return flatten_location(location[0])
    else:
        return [location]

def _format_location(loc: Union[Location, Well]) -> str:
    # Convert a single location object to its string representation
    if isinstance(loc, Location):
        if loc.labware is None or loc.labware.is_empty:
            return str(loc.point)
        else:
            return repr(loc.labware)
    elif isinstance(loc, Well):
        return str(loc)
    else:
        raise TypeError(f"Unsupported location type: {type(loc)}")

def format_command_location(location: CommandLocation) -> str:
    # Process all location(s) and join their string representations
    formatted_locations = [_format_location(loc) for loc in flatten_location(location)]
    return ", ".join(formatted_locations)

