def build_retry_policy():
    """Construct retry configuration with exponential backoff"""
    builder = RetryStrategyBuilder(
        max_attempts_check=True,
        max_attempts=10,
        retry_max_wait_between_calls_seconds=30,
        retry_base_sleep_time_seconds=3,
        backoff_type=oci.retry.BACKOFF_FULL_JITTER_EQUAL_ON_THROTTLE_VALUE,
    )
    builder.add_service_error_check(
        service_error_retry_config={429: [], 400: ["QuotaExceeded", "LimitExceeded"]},
        service_error_retry_on_any_5xx=True,
    )
    return builder.get_retry_strategy()

def fetch_all_pages(method, **params):
    """Iterate through all pages of results from OCI SDK"""
    items = []
    response = attempt_call(method, **params)
    items.extend(response.data)

    while hasattr(response, 'has_next_page') and response.has_next_page:
        params['page'] = response.headers.get(HEADER_NEXT_PAGE)
        response = attempt_call(method, **params)
        items.extend(response.data)
    return items

def attempt_call(func, **kwargs):
    """Execute function with retry strategy fallback"""
    if "retry_strategy" not in kwargs:
        kwargs["retry_strategy"] = build_retry_policy()
    try:
        return func(**kwargs)
    except TypeError as err:
        if "unexpected keyword argument" in str(err):
            kwargs.pop("retry_strategy", None)
            return func(**kwargs)

class OCIInventoryManager:
    ACTIVE_STATE = "ACTIVE"
    RUNNING_STATE = "RUNNING"
    ATTACHED_STATE = "ATTACHED"

    def __init__(self):
        self.inventory_structure = {"all": {"hosts": [], "vars": {}}, "_meta": {"hostvars": {}}}
        self.config_data = {}
        self._region_subs = None
        self._regions_list = None
        self._short_region_names = None
        self._long_region_names = None

        # Default parameters configuration
        self.options = {
            "ini_file": os.path.join(
                os.path.dirname(os.path.realpath(__file__)).encode(),
                b"oci_inventory.ini"
            ),
            "config_file": os.path.join(os.path.expanduser("~"), ".oci", "config"),
            "profile": "DEFAULT",
            "user": None,
            "fingerprint": None,
            "key_file": None,
            "tenancy": None,
            "region": None,
            "pass_phrase": None,
            "cache_dir": ".",
            "cache_max_age": 300,
            "cache_file": None,
            "compartment_ocid": None,
            "compartment": None,
            "parent_compartment_ocid": None,
            "fetch_hosts_from_subcompartments": False,
            "debug": False,
            "hostname_format": "public_ip",
            "sanitize_names": True,
            "replace_dash_in_names": False,
            "auth": "api_key",
            "enable_parallel_processing": False,
            "max_thread_count": 50,
            "freeform_tags": None,
            "defined_tags": None,
            "regions": None,
            "exclude_regions": None,
            "strict_hostname_checking": "no",
        }

        boolean_flags = [
            "sanitize_names",
            "replace_dash_in_names",
            "ignore_hostname_errors",
        ]
        dict_flags = ["freeform_tags", "defined_tags"]

        try:
            self.parse_command_line()
            if self.cli_args.debug:
                self.options["debug"] = True
                self.log_message("Running in debug mode.")

            # Handle INI file path from environment
            if "OCI_INI_PATH" in os.environ:
                ini_path = os.path.expanduser(
                    os.path.expandvars(os.environ.get("OCI_INI_PATH").encode())
                )
                if os.path.isfile(ini_path):
                    self.options["ini_file"] = ini_path

            # Load configuration from INI file
            self.config_parser = configparser.ConfigParser()
            self.config_parser.read(self.options["ini_file"].decode())

            # Priority: CLI args > env vars > config file
            if (
                hasattr(self.cli_args, "config_file") 
                and self.cli_args.config_file is not None
            ):
                self.options["config_file"] = os.path.expanduser(self.cli_args.config_file)
            elif "OCI_CONFIG_FILE" in os.environ:
                self.options["config_file"] = os.path.expanduser(
                    os.environ.get("OCI_CONFIG_FILE")
                )
            elif self.config_parser.has_option("oci", "config_file"):
                self.options["config_file"] = os.path.expanduser(
                    self.config_parser.get("oci", "config_file")
                )

            # Profile handling
            if hasattr(self.cli_args, "profile") and self.cli_args.profile is not None:
                self.options["profile"] = self.cli_args.profile
            elif "OCI_CONFIG_PROFILE" in os.environ:
                self.options["profile"] = os.environ.get("OCI_CONFIG_PROFILE")
            elif self.config_parser.has_option("oci", "profile"):
                self.options["profile"] = self.config_parser.get("oci", "profile")

            self.load_config_values()
            self.load_ini_settings(boolean_flags, dict_flags)
            self.load_environment_variables()
            self.process_cli_options(dict_flags)

            # Initialize service clients
            self.identity_client = self.create_service_client(IdentityClient)

            # Handle instance principal authentication
            if self.options["auth"] == "instance_principal":
                instance_info = self.fetch_instance_metadata()
                self.options.update(instance_info)

            self.validate_configuration()
            self.log_message("Using these parameters for OCI dynamic inventory:")
            self.log_message(self.options)

            # Create regional clients
            self.compute_clients_by_region = {}
            self.network_clients_by_region = {}
            for region in self.regions:
                self.compute_clients_by_region[region] = self.create_service_client(ComputeClient, region=region)
                self.network_clients_by_region[region] = self.create_service_client(VirtualNetworkClient, region=region)

            # Cache setup
            self.options["cache_file"] = self.generate_cache_filename()
            if not self.cli_args.refresh_cache and self.cache_is_valid():
                self.log_message(f"Reading inventory from cache {self.options['cache_file']}")
                self.inventory_structure = self.load_from_cache()
            else:
                self.construct_inventory()
                self.save_to_cache(self.inventory_structure)

            # Output results
            if self.cli_args.host:
                if self.cli_args.host in self.inventory_structure["_meta"]["hostvars"]:
                    print(
                        json.dumps(
                            self.inventory_structure["_meta"]["hostvars"][self.cli_args.host],
                            sort_keys=True,
                            indent=2,
                        )
                    )
                else:
                    self.log_message(
                        "Host not found or facts unavailable."
                    )
                    print({})
            else:
                print(json.dumps(self.inventory_structure, sort_keys=True, indent=2))
        except Exception as e:
            stacktrace = traceback.format_exc()
            error_msg = getattr(e, 'message', str(e))
            self.terminate(message=error_msg, stacktrace=stacktrace)

    def _is_using_instance_principal(self):
        return self.options["auth"] == "instance_principal"

    @staticmethod
    def create_signer_for_instance_principal():
        try:
            signer = oci.auth.signers.InstancePrincipalsSecurityTokenSigner()
        except Exception as ex:
            raise Exception(
                f"Failed retrieving certificates from localhost. Instance principal authentication "
                f"is only available from within OCI compute instances. Error: {str(ex)}"
            )
        return signer

    def create_service_client(self, client_class, region=None):
        if not region:
            region = self.options["region"]
        client_params = dict(self.options, region=region)
        extra_kwargs = {}

        if self._is_using_instance_principal():
            extra_kwargs["signer"] = self.create_signer_for_instance_principal()

        client = client_class(client_params, **extra_kwargs)
        return client

    def get_region_short_code(self, name):
        if name in self.region_long_names:
            return self.region_long_names[name]
        if name.lower() in self.region_long_names:
            return self.region_long_names[name.lower()]
        if name.lower() in self.region_short_names:
            return name.lower()
        raise ValueError(f"Could not determine short name for region {name}.")

    def get_region_full_name(self, name):
        if name.lower() in self.region_short_names:
            return self.region_short_names[name.lower()]
        if name in self.region_long_names:
            return name
        if name.lower() in self.region_long_names:
            return name.lower()
        raise ValueError(f"Could not determine long name for region {name}.")

    @property
    def region_short_names(self):
        if not self._short_region_names:
            self._short_region_names = dict(
                (region.key.lower(), region.name)
                for region in fetch_all_pages(self.identity_client.list_regions).data
            )
        return self._short_region_names

    @property
    def region_long_names(self):
        if not self._long_region_names:
            self._long_region_names = dict(
                (region_long_name, region_short_name)
                for region_short_name, region_long_name in self.region_short_names.items()
            )
        return self._long_region_names

    def get_compute_client(self, region):
        if region not in self.compute_clients_by_region:
            raise ValueError(f"Could not fetch compute client for region {region}.")
        return self.compute_clients_by_region[region]

    def get_network_client(self, region):
        if region not in self.network_clients_by_region:
            raise ValueError(f"Could not fetch network client for region {region}.")
        return self.network_clients_by_region[region]

    def log_message(self, *args, **kwargs):
        if self.options["debug"]:
            print(*args, file=sys.stderr, **kwargs)

    def fetch_instance_metadata(self):
        metadata_url = "http://169.254.169.254/opc/v1/instance"
        try:
            response = open_url(metadata_url, method="GET")
            metadata_response = json.loads(response.read().decode())
            self.log_message(f"Metadata response: {metadata_response}")
        except Exception as ex:
            raise Exception(
                f"Failed to retrieve instance metadata: {str(ex)}"
            )

        instance_info = {
            "compartmentId": metadata_response["compartmentId"],
            "region": self.get_region_full_name(metadata_response["region"]),
            "tenancy": self.options["tenancy"]
            or getattr(self.create_signer_for_instance_principal(), "tenancy_id", None),
        }
        self.log_message(f"Instance details from metadata: {instance_info}")

        if not (instance_info["region"] or instance_info["compartmentId"] or instance_info["tenancy"]):
            raise Exception("Error retrieving instance metadata details.")
        return instance_info

    def load_config_values(self):
        if os.path.isfile(self.options["config_file"].decode()):
            self.config_data = oci.config.from_file(
                file_location=self.options["config_file"].decode(),
                profile_name=self.options["profile"],
            )
        self.config_data["additional_user_agent"] = f"Oracle-Ansible/{__version__}"
        for key, value in self.config_data.items():
            self.options[key] = value

    def load_environment_variables(self):
        env_mapping = {
            "OCI_CONFIG_FILE": "config_file",
            "OCI_INI_PATH": "ini_path",
            "OCI_TENANCY": "tenancy",
            "OCI_REGION": "region",
            "OCI_CACHE_DIR": "cache_dir",
            "OCI_CACHE_MAX_AGE": "cache_max_age",
            "OCI_HOSTNAME_FORMAT": "hostname_format",
            "OCI_USER_ID": "user",
            "OCI_USER_FINGERPRINT": "fingerprint",
            "OCI_USER_KEY_FILE": "key_file",
            "OCI_USER_KEY_PASS_PHRASE": "pass_phrase",
            "OCI_CONFIG_PROFILE": "profile",
            "OCI_ANSIBLE_AUTH_TYPE": "auth",
            "OCI_INVENTORY_REGIONS": "regions",
            "OCI_INVENTORY_EXCLUDE_REGIONS": "exclude_regions",
            "OCI_COMPARTMENT_OCID": "compartment_ocid",
            "OCI_STRICT_HOSTNAME_CHECKING": "strict_hostname_checking",
        }
        for env_var in os.environ:
            if env_var in env_mapping:
                self.options[env_mapping[env_var]] = os.environ.get(env_var)

    def process_cli_options(self, dict_options):
        for setting in vars(self.cli_args):
            value = getattr(self.cli_args, setting)
            if value is not None:
                if setting in dict_options:
                    try:
                        parsed_value = json.loads(value)
                        if not isinstance(parsed_value, dict):
                            raise TypeError(f"Invalid JSON input for {setting}.")
                        self.options[setting] = parsed_value
                    except json.JSONDecodeError:
                        raise TypeError(f"Invalid JSON input for {setting}.")
                else:
                    self.options[setting] = value

    def validate_configuration(self):
        if (
            not self.options["tenancy"]
            and not self.options["auth"] == "instance_principal"
        ):
            self.terminate("Tenancy OCID required.")

        if self.options["regions"]:
            subscribed_regions = [
                region_subscription.region_name
                for region_subscription in self.region_subscriptions
            ]
            for region in self.regions:
                if region not in subscribed_regions:
                    raise ValueError(
                        f"Region {region} is either invalid or not subscribed."
                    )

    def generate_cache_filename(self):
        param_string = ""
        if self.options["tenancy"]:
            param_string += f"@{self.options['tenancy']}:{'tenancy'}@"
        param_string += f"@{','.join(sorted(self.regions))}:regions@"

        if self.options["compartment_ocid"]:
            param_string += f"@{self.options['compartment_ocid']}:compartment@"
        else:
            if self.options["compartment"]:
                param_string += f"@{self.options['compartment']}:compartment@"
            if self.options["parent_compartment_ocid"]:
                param_string += f"@{self.options['parent_compartment_ocid']}:parent_compartment@"

        param_string += f"@{self.options['fetch_hosts_from_subcompartments']}:subcompartments@"
        param_string += f"@{self.options['hostname_format']}:hostname@"

        if self.options["freeform_tags"]:
            tag_str = ""
            for key in sorted(self.options["freeform_tags"]):
                tag_str += f"{key}={self.options['freeform_tags'][key]},"
            param_string += f"@{tag_str}:freeform_tags@"

        if self.options["defined_tags"]:
            defined_tag_str = ""
            for namespace in sorted(self.options["defined_tags"]):
                for key in sorted(self.options["defined_tags"][namespace]):
                    defined_tag_str += f"{namespace}={key}={self.options['defined_tags'][namespace][key]},"
            param_string += f"@{defined_tag_str}:defined_tags@"

        hash_value = hashlib.md5(param_string.encode()).hexdigest()
        self.log_message(f"Cache filename derived from parameters: {hash_value}")
        return os.path.join(
            self.options["cache_dir"].encode(),
            f"ansible-oci-{hash_value}.cache".encode()
        )

    def cache_is_valid(self):
        if os.path.isfile(self.options["cache_file"].decode()):
            mod_time = os.path.getmtime(self.options["cache_file"].decode())
            current_time = time()
            if (mod_time + float(self.options["cache_max_age"])) > current_time:
                return True
            else:
                self.log_message("Cache has expired.")
        else:
            self.log_message("Cache file does not exist.")
        return False

    def load_from_cache(self):
        with open(self.options["cache_file"].decode(), "r") as cache_file:
            return json.loads(cache_file.read())

    def save_to_cache(self, data):
        json_data = json.dumps(data, sort_keys=True, indent=2)
        with open(self.options["cache_file"].decode(), "w") as cache_file:
            cache_file.write(json_data)

    @property
    def region_subscriptions(self):
        if self._region_subs:
            return self._region_subs
        if not self.options["tenancy"]:
            raise Exception("Tenancy OCID required to get region subscriptions.")
        self._region_subs = fetch_all_pages(
            self.identity_client.list_region_subscriptions,
            tenancy_id=self.options["tenancy"],
        ).data
        return self._region_subs

    @property
    def regions(self):
        if self._regions_list:
            return self._regions_list
        if self.options["regions"]:
            if self.options["regions"] == "all":
                self._regions_list = [
                    region_subscription.region_name
                    for region_subscription in self.region_subscriptions
                ]
            else:
                self._regions_list = [region.strip() for region in self.options["regions"].split(",")]
        else:
            self._regions_list = [self.options["region"]]

        if self.options["exclude_regions"]:
            exclude_list = [region.strip() for region in self.options["exclude_regions"].split(",")]
            self._regions_list = [
                region for region in self._regions_list if region not in exclude_list
            ]
        return self._regions_list

    def get_compartments(
        self,
        compartment_ocid=None,
        parent_compartment_ocid=None,
        compartment_name=None,
        fetch_subcompartments=False,
    ):
        if compartment_ocid:
            try:
                compartment_obj = fetch_all_pages(
                    self.identity_client.get_compartment,
                    compartment_id=compartment_ocid,
                ).data
            except ServiceError as se:
                if se.status == 404:
                    raise Exception(
                        f"Compartment with OCID {compartment_ocid} either does not exist or "
                        "you do not have permission to access it."
                    )
            else:
                if not fetch_subcompartments:
                    return [compartment_obj]
                return self.traverse_compartments(compartment_obj)

        if not self.options["tenancy"]:
            raise Exception(
                "Tenancy OCID required to get compartments in the tenancy."
            )

        try:
            tenancy_obj = fetch_all_pages(
                self.identity_client.get_compartment,
                compartment_id=self.options["tenancy"],
            ).data
        except ServiceError as se:
            if se.status == 404:
                raise Exception(
                    "Either tenancy OCID is invalid or you need inspect permission on root compartment."
                )

        all_compartments = [tenancy_obj] + [
            compartment
            for compartment in fetch_all_pages(
                target_fn=self.identity_client.list_compartments,
                compartment_id=self.options["tenancy"],
                compartment_id_in_subtree=True,
            )
            if self.check_resource_status(
                compartment, lifecycle_state=self.ACTIVE_STATE
            )
        ]

        if not compartment_name:
            return all_compartments

        if compartment_name == tenancy_obj.name:
            if fetch_subcompartments:
                return all_compartments
            else:
                return [tenancy_obj]

        if not parent_compartment_ocid:
            parent_compartment_ocid = tenancy_obj.id

        matching_compartment = None
        for compartment in all_compartments:
            if (
                compartment.name == compartment_name
                and compartment.compartment_id == parent_compartment_ocid
            ):
                matching_compartment = compartment
                break

        if not matching_compartment:
            raise Exception(f"Compartment with name {compartment_name} not found.")

        if not fetch_subcompartments:
            return [matching_compartment]
        return self.traverse_compartments(matching_compartment)

    def traverse_compartments(self, root):
        compartments = []
        queue = [root]
        while queue:
            current = queue.pop(0)
            compartments.append(current)
            children = [
                compartment
                for compartment in fetch_all_pages(
                    target_fn=self.identity_client.list_compartments,
                    compartment_id=current.id,
                )
                if self.check_resource_status(
                    compartment, lifecycle_state=self.ACTIVE_STATE
                )
            ]
            queue.extend(children)
        return compartments

    @staticmethod
    def check_resource_status(resource, **conditions):
        for key, val in conditions.items():
            if getattr(resource, key, None) != val:
                return False
        return True

    def get_instances(self, compartment_ids):
        instances_by_region = {}
        if self.options["enable_parallel_processing"]:
            for region in self.regions:
                num_threads = min(len(compartment_ids), self.options["max_thread_count"])
                self.log_message(
                    f"Parallel processing enabled. Getting instances from {region} using {num_threads} threads."
                )
                with self.thread_pool(processes=num_threads) as pool:
                    get_filtered_instances = partial(
                        self.get_filtered_instances, region=region
                    )
                    lists_of_instances = pool.map(get_filtered_instances, compartment_ids)

                instances_by_region[region] = []
                for sublist in lists_of_instances:
                    instances_by_region[region].extend(sublist)
        else:
            for region in self.regions:
                instances_by_region[region] = []
                for compartment_id in compartment_ids:
                    instances_by_region[region].extend(
                        self.get_filtered_instances(compartment_id, region)
                    )
        return instances_by_region

    def get_filtered_instances(self, compartment_id, region):
        try:
            compute_client = self.get_compute_client(region)
            self.log_message(
                f"Listing RUNNING instances from compartment {compartment_id} in region {region}"
            )
            instances = fetch_all_pages(
                target_fn=compute_client.list_instances,
                compartment_id=compartment_id,
                lifecycle_state=self.RUNNING_STATE,
            )
            self.log_message(f"Found {len(instances)} RUNNING instances in compartment {compartment_id}")

            # Filter by freeform tags
            if self.options["freeform_tags"]:
                instances = [
                    instance
                    for instance in instances
                    if all(
                        instance.freeform_tags.get(key) == value
                        for key, value in self.options["freeform_tags"].items()
                    )
                ]
                self.log_message(f"After freeform tag filtering: {len(instances)} instances")

            # Filter by defined tags
            if self.options["defined_tags"]:
                instances = [
                    instance
                    for instance in instances
                    if all(
                        (instance.defined_tags.get(namespace, {})).get(key) == value
                        for namespace in self.options["defined_tags"]
                        for key, value in self.options["defined_tags"][namespace].items()
                    )
                ]
                self.log_message(f"After defined tag filtering: {len(instances)} instances")

            return instances
        except ServiceError as ex:
            if ex.status == 401:
                self.log_message(ex)
                raise
            self.log_message(ex)
            return []

    def get_hostname(self, vnic, region):
        virtual_nw_client = self.get_network_client(region)
        if self.options["hostname_format"] == "fqdn":
            subnet = fetch_all_pages(
                virtual_nw_client.get_subnet, subnet_id=vnic.subnet_id
            ).data
            vcn = fetch_all_pages(
                virtual_nw_client.get_vcn, vcn_id=subnet.vcn_id
            ).data
            domain_suffix = ".oraclevcn.com"

            if not (vnic.hostname_label and subnet.dns_label and vcn.dns_label):
                return None

            fqdn = f"{vnic.hostname_label}.{subnet.dns_label}.{vcn.dns_label}{domain_suffix}"
            self.log_message(f"FQDN for VNIC {vnic.id}: {fqdn}")
            return fqdn

        elif self.options["hostname_format"] == "private_ip":
            self.log_message(f"Private IP for VNIC {vnic.id}: {vnic.private_ip}")
            return vnic.private_ip

        self.log_message(f"Public IP for VNIC {vnic.id}: {vnic.public_ip}")
        return vnic.public_ip

    def build_host_inventory(self, instance, region):
        try:
            self.log_message(f"Building inventory for instance {instance.id}")
            host_inventory = {}
            compute_client = self.get_compute_client(region)
            virtual_nw_client = self.get_network_client(region)
            compartment = self.compartments[instance.compartment_id]
            instance_vars = to_dict(instance)

            common_groups = {"all"}

            # Group by availability domain
            ad = self.normalize_name(instance.availability_domain)
            common_groups.add(ad)

            # Group by compartment
            compartment_name = self.normalize_name(compartment.name)
            common_groups.add(compartment_name)

            # Group by region
            region_group = self.normalize_name(f"region_{self.get_region_short_code(region)}")
            common_groups.add(region_group)

            # Group by image OCID
            if hasattr(instance.source_details, "image_id"):
                common_groups.add(instance.source_details.image_id)

            # Group by shape
            shape_name = self.normalize_name(instance.shape)
            common_groups.add(shape_name)

            # Group by freeform tags
            for key in instance.freeform_tags:
                tag_group = self.normalize_name(f"tag_{key}={instance.freeform_tags[key]}")
                common_groups.add(tag_group)

            # Group by defined tags
            for namespace in instance.defined_tags:
                for key in instance.defined_tags[namespace]:
                    defined_tag_group = self.normalize_name(
                        f"{namespace}#{key}={instance.defined_tags[namespace][key]}"
                    )
                    common_groups.add(defined_tag_group)

            # Group by metadata
            for key in instance.metadata:
                if key not in ["ssh_authorized_keys", "user_data"]:
                    group_name = self.normalize_name(f"{key}={instance.metadata[key]}")
                    common_groups.add(group_name)

            # Group by extended metadata
            for key in instance.extended_metadata:
                if key not in ["ssh_authorized_keys", "user_data"]:
                    ext_metadata_group = self.normalize_name(
                        f"{key}={str(instance.extended_metadata[key])}"
                    )
                    common_groups.add(ext_metadata_group)

            # Process VNIC attachments
            vnic_attachments = fetch_all_pages(
                target_fn=compute_client.list_vnic_attachments,
                compartment_id=compartment.id,
                instance_id=instance.id,
            )

            for vnic_attachment in vnic_attachments:
                vnic = fetch_all_pages(
                    virtual_nw_client.get_vnic, vnic_id=vnic_attachment.vnic_id
                ).data

                hostname = self.get_hostname(vnic, region=region)

                if not hostname:
                    if self.options["strict_hostname_checking"] == "yes":
                        raise Exception(
                            f"Instance {vnic_attachment.instance_id} does not have a valid hostname."
                        )
                    self.log_message(f"Skipped instance {vnic_attachment.instance_id}")
                    continue

                if self.cli_args.host and self.cli_args.host != hostname:
                    self.log_message(f"Skipped instance with hostname {hostname}")
                    continue

                hostname = self.normalize_name(hostname)
                groups = set(common_groups)

                subnet = fetch_all_pages(
                    virtual_nw_client.get_subnet, subnet_id=vnic.subnet_id
                ).data
                groups.add(subnet.id)
                groups.add(subnet.vcn_id)

                # Add security list groups
                for sec_list_id in subnet.security_list_ids:
                    groups.add(sec_list_id)

                self.log_message(f"Created inventory for host {hostname}")
                self.create_host_entry(
                    host_inventory,
                    hostname,
                    vars=instance_vars,
                    groups=groups,
                    parents=[ad, subnet.vcn_id, region_group, region_group],
                    children=[subnet.id, subnet.vcn_id, ad, subnet.id],
                )

            return host_inventory
        except ServiceError as ex:
            if ex.status == 401:
                self.log_message(ex)
                raise
            self.log_message(ex)
            return {}

    @staticmethod
    def create_host_entry(host_inventory, hostname, vars, groups, parents, children):
        host_inventory.setdefault(hostname, {"groups": {}, "vars": {}})
        host_inventory[hostname]["vars"] = vars

        for group in groups:
            host_inventory[hostname]["groups"].setdefault(group, {"children": []})

        for parent, child in zip(parents, children):
            host_inventory[hostname]["groups"][parent]["children"].append(child)

        return host_inventory

    def merge_inventory(self, host_inventories):
        for inventory in host_inventories:
            if inventory:
                for hostname, host_data in inventory.items():
                    self.add_host_entry(
                        hostname,
                        vars=host_data["vars"],
                        groups=host_data["groups"],
                    )

    @contextmanager
    def thread_pool(self, **kwargs):
        pool = ThreadPool(**kwargs)
        try:
            yield pool
        finally:
            pool.close()
            pool.join()
            pool.terminate()

    def construct_inventory(self):
        self.log_message("Building inventory structure.")

        # Get compartments
        self.compartments = {}
        for compartment in self.get_compartments(
            compartment_ocid=self.options["compartment_ocid"],
            parent_compartment_ocid=self.options["parent_compartment_ocid"],
            compartment_name=self.options["compartment"],
            fetch_subcompartments=self.options["fetch_hosts_from_subcompartments"],
        ):
            self.compartments[compartment.id] = compartment

        if not self.compartments:
            self.log_message("No compartments matched the criteria.")
            return

        self.log_message(f"Processing {len(self.compartments)} compartments")

        # Get instances by region
        instances_by_region = self.get_instances(list(self.compartments.keys()))

        # Build individual host inventories
        host_inventories = []
        if self.options["enable_parallel_processing"]:
            for region in instances_by_region:
                instances = instances_by_region[region]
                if instances:
                    num_threads = min(len(instances), self.options["max_thread_count"])
                    self.log_message(
                        f"Building host inventories in {num_threads} threads for region {region}"
                    )
                    with self.thread_pool(processes=num_threads) as pool:
                        host_inventories.extend(
                            pool.map(
                                partial(self.build_host_inventory, region=region),
                                instances,
                            )
                        )
        else:
            for region in instances_by_region:
                for instance in instances_by_region[region]:
                    host_inventories.append(
                        self.build_host_inventory(instance, region)
                    )

        self.log_message(f"Merging {len(host_inventories)} host inventories")
        self.merge_inventory(host_inventories)

    def terminate(self, message=None, exit_code=1, stacktrace=None):
        if stacktrace:
            self.log_message(stacktrace)
        if message:
            print(message, file=sys.stderr)
        sys.exit(exit_code)

