    def load_ini_settings(self, boolean_flags, dict_flags):
        if self.config_parser.has_section("oci"):
            for option in self.config_parser.options("oci"):
                if option in boolean_flags:
                    self.options[option] = self.config_parser.getboolean("oci", option)
                elif option in dict_flags:
                    try:
                        self.options[option] = json.loads(
                            self.config_parser.get("oci", option)
                        )
                    except json.JSONDecodeError:
                        self.options[option] = {}
                else:
                    self.options[option] = self.config_parser.get("oci", option)

    def normalize_name(self, word):
        regex = r"[^A-Za-z0-9_#=."
        if self.options["sanitize_names"]:
            if not self.options["replace_dash_in_names"]:
                regex += r"-"
            return re.sub(regex + "]", "_", word)
        return word

    def add_host_entry(self, host, groups=None, vars=None):
        if not groups:
            groups = {"all"}

        for group in groups:
            self.add_group_entry(group, children=groups[group].setdefault("children", []))
            if host not in self.inventory_structure[group]["hosts"]:
                self.inventory_structure[group]["hosts"].append(host)

        if vars:
            self.add_host_variables(host, vars)

    def add_host_variables(self, host, vars):
        self.inventory_structure["_meta"]["hostvars"][host] = vars

    def add_group_entry(self, group, children=None):
        self.inventory_structure.setdefault(group, {"hosts": []})
        if children:
            for child in children:
                self.add_child_group(group, child)

    def add_child_group(self, parent, child):
        self.add_group_entry(parent)
        children = self.inventory_structure[parent].setdefault("children", [])
        if child not in children:
            children.append(child)

