import time
import json
from entrypoint import beeline
from beeline.middleware.awslambda import beeline_wrapper

@beeline_wrapper
def handler(event, context):
    try:
        with beeline.tracer(name="lambda22"):
            beeline.add_context({
                'input': event,
            })
            time.sleep(2)
    except Exception as error:
        # Re-raise exception to trigger Lambda retry
        err_type = type(error).__name__
        err_msg = str(error)
        beeline.add_context({
            'exception.class': err_type,
            'exception.text': err_msg,
        })
        error_response = {
            "isError": True,
            "kind": err_type,
            "description": err_msg,
        }
        error_json = json.dumps(error_response)
        raise LambdaError(error_json)
    finally:
        beeline.get_beeline().client.flush()

class LambdaError(Exception):
    '''Custom exception class for cleaner error formatting in logs'''

from assemblyline_ui.http_exceptions import AuthenticationException

def validate_oauth(username, oauth_token):
    # This function verifies user identity using the internal API key mechanism
    #   NOTE: Overriding this function is discouraged, though still possible
    if config.auth.oauth.enabled and oauth_token:
        token_store = get_token_store(username)
        if token_store.exist(oauth_token):
            return username, ["R", "W", "E"]
        raise AuthenticationException("Invalid token")
    return None, None

from typing import Tuple
import numpy as np
import torch
from torch import matmul

def regularize_matrix(mat, regularization, relative_to_diag_mean=True):
    if regularization <= 0:
        return mat

    # Ensure matrix is square
    n_rows, n_cols = mat.shape[-2], mat.shape[-1]
    if n_rows != n_cols:
        raise ValueError("Input matrix must be square for regularization")

    # Compute diagonal mean if needed
    if relative_to_diag_mean:
        diag_values = torch.diagonal(mat, dim1=-2, dim2=-1)
        diag_mean = diag_values.mean(dim=-1, keepdim=True)
        reg_values = diag_mean * regularization
    else:
        reg_values = torch.full_like(diag_values, regularization)

    # Create regularization matrix and add to original
    reg_matrix = torch.diag_embed(reg_values)
    return mat + reg_matrix

def cholesky(
    mat,
    upper=False,
    out=None,
    regularization=0.0,
    initial_try_regularization=1e-6,
    max_regularization=1e2,
    step_factor=10,
    warning=True,
):
    if regularization > 0 and warning:
        print(f"Regularizing matrix with value: {regularization}")
        regularized_mat = regularize_matrix(
            mat=mat, regularization=regularization, relative_to_diag_mean=True
        )
    else:
        regularized_mat = mat

    try:
        return torch.cholesky(regularized_mat, upper=upper, out=out)
    except RuntimeError:
        if torch.isnan(mat).any():
            raise ValueError("NaN detected in input mat.")

        # Increase regularization and retry
        new_reg = max(regularization * step_factor, initial_try_regularization)
        if new_reg > max_regularization:
            raise ValueError(
                f"Attempted regularization ({new_reg}) exceeded maximum ({max_regularization})."
            )
        return cholesky(
            mat=mat,
            upper=upper,
            out=out,
            regularization=new_reg,
            initial_try_regularization=initial_try_regularization,
            max_regularization=max_regularization,
            step_factor=step_factor,
            warning=False,
        )

def cov_and_chol_from_invcholesky_param(Linv_tril, Linv_logdiag):
    # Construct inverse of L (Linv) from its components
    Linv = torch.tril(Linv_tril, -1) + torch.diag_embed(torch.exp(Linv_logdiag))

    # Compute L as the inverse of Linv
    L = torch.inverse(Linv)

    # Return covariance matrix and Cholesky factor
    cov = matmul(L, L.transpose(-1, -2))
    return cov, L

def cov_from_invcholesky_param(Linv_tril, Linv_logdiag):
    return cov_and_chol_from_invcholesky_param(
        Linv_tril=Linv_tril, Linv_logdiag=Linv_logdiag
    )[0]

def inv_from_invcholesky_param(Linv_tril, Linv_logdiag):
    Linv = torch.tril(Linv_tril, -1) + torch.diag_embed(torch.exp(Linv_logdiag))
    return matmul(Linv.transpose(-1, -2), Linv)

def batch_cholesky_inverse(Lmat):
    """
    Computes the inverse of a Cholesky factor using matrix inversion.
    Equivalent to torch.cholesky_inverse but implemented manually for batches.
    """
    Lmat_inv = torch.inverse(Lmat)
    return matmul(Lmat_inv.transpose(-1, -2), Lmat_inv)

def batch_diag(mat):
    # Extract diagonal elements across last two dimensions
    return torch.diagonal(mat, dim1=-2, dim2=-1)

def batch_diag_matrix(diagonal):
    N = diagonal.shape[-1]
    shape = diagonal.shape[:-1] + (N, N)
    device = diagonal.device
    dtype = diagonal.dtype

    # Create zero tensor and fill diagonals
    result = torch.zeros(shape, dtype=dtype, device=device)
    idx = torch.arange(N, device=device)
    result[..., idx, idx] = diagonal
    return result

def symmetrize(mat):
    return 0.5 * (mat + mat.transpose(-1, -2))

def matvec(mat, vec):
    if vec.ndim == 1:
        return torch.matmul(mat, vec)
    elif mat.ndim == 2:
        return torch.matmul(vec.unsqueeze(0), mat.t()).squeeze(0)
    else:
        return torch.matmul(mat, vec.unsqueeze(-1)).squeeze(-1)

def get_numerical_precision(x):
    if isinstance(x, float):
        eps = np.finfo(np.array(x).dtype).eps
    elif isinstance(x, torch.Tensor):
        eps = torch.finfo(x.dtype).eps
    elif isinstance(x, (np.ndarray, np.generic)):
        eps = np.finfo(x.dtype).eps
    else:
        raise ValueError(f"Unknown type for precision calculation: {type(x)}")
    return eps

def stable_log(x, eps=None):
    eps = get_numerical_precision(x) if eps is None else eps
    return torch.log(x + eps)

def kron(A, B):
    """
    Kronecker Product implementation supporting batch dimensions.
    Requires matching batch dimensions for A and B.
    """
    A_shp, B_shp = A.shape, B.shape
    if A_shp[:-2] != B_shp[:-2]:
        raise ValueError("Batch dimensions of A and B must match")

    # Use outer product approach via broadcasting
    kron_block = A.unsqueeze(-1).unsqueeze(-1) * B.unsqueeze(-3).unsqueeze(-3)
    kron = kron_block.reshape(
        A_shp[:-2] + (A_shp[-2] * B_shp[-2], A_shp[-1] * B_shp[-1])
    )
    return kron

def vectorize_normal_dist_params(m, V):
    # Vectorize lower triangle including diagonal of covariance matrix
    indices = torch.tril_indices(V.shape[-2], V.shape[-1], offset=0, device=V.device)
    V_vec = V[..., indices[0], indices[1]]
    return torch.cat((m, V_vec), dim=-1)

def logmeanexp(self: torch.Tensor, dim: int, keepdim: bool = False):
    return torch.logsumexp(self, dim=dim, keepdim=keepdim) - np.log(
        self.shape[dim]
    )

def make_block_diagonal(mats: Tuple[torch.Tensor]) -> torch.Tensor:
    if not isinstance(mats, (list, tuple)):
        raise TypeError("Input must be a list or tuple of tensors")

    if len(mats) == 0:
        raise ValueError("At least one matrix must be provided")

    if len(mats) == 1:
        return mats[0]

    # Combine last two matrices first
    m1, m2 = mats[-2], mats[-1]
    rows1, cols1 = m1.shape[-2], m1.shape[-1]
    rows2, cols2 = m2.shape[-2], m2.shape[-1]

    # Zero blocks for off-diagonal parts
    zero_ur = torch.zeros(
        m1.shape[:-2] + (rows1, cols2),
        dtype=m1.dtype,
        device=m1.device
    )
    zero_ll = torch.zeros(
        m2.shape[:-2] + (rows2, cols1),
        dtype=m2.dtype,
        device=m2.device
    )

    # Build block matrix
    top = torch.cat([m1, zero_ur], dim=-1)
    bottom = torch.cat([zero_ll, m2], dim=-1)
    combined = torch.cat([top, bottom], dim=-2)

    # Recursively combine remaining matrices
    return make_block_diagonal(mats[:-2] + (combined,))

from starlette.exceptions import HTTPException
from starlette.status import (
    HTTP_200_OK,
    HTTP_201_CREATED,
    HTTP_400_BAD_REQUEST,
    HTTP_404_NOT_FOUND,
)
from models.product import req_product
from crud.product import (
    extract_pid,
    fetch_product_by_id,
    fetch_product_dict,
    fetch_all_products,
    fetch_all_products_nodict,
    insert_new_product,
    scrape_from_url,
    modify_existing_product,
)
from database.mongodb import AsyncIOMotorClient, get_database
from fastapi import APIRouter

app_router = APIRouter()


@app_router.get("/{store}")
async def list_store_products(store: str, db: AsyncIOMotorClient = Depends(get_database)):
    raw_products = await fetch_all_products(store, db)
    return {"products": raw_products}


@app_router.get("/{store}/{product_id}")
async def retrieve_single_product(store: str, product_id: str, db: AsyncIOMotorClient = Depends(get_database)):
    found_item = await fetch_product_dict(store, product_id, db)
    if found_item is not None:
        return {"product": found_item}
    else:
        raise HTTPException(
            status_code=HTTP_404_NOT_FOUND,
            detail=f"{store} product with ID {product_id} could not be located",
        )


@app_router.post("/")
async def register_new_product(payload: req_product, db: AsyncIOMotorClient = Depends(get_database)):
    pid = extract_pid(payload.store, payload.url)
    existing = await fetch_product_dict(payload.store, pid, db)

    if existing is not None:
        raise HTTPException(
            status_code=HTTP_400_BAD_REQUEST,
            detail=f"{payload.store} product with ID {pid} already present in database",
        )

    new_data = scrape_from_url(payload.store, payload.url)
    inserted = await insert_new_product(new_data, db)

    if inserted:
        raise HTTPException(
            status_code=HTTP_201_CREATED,
            detail=f"{payload.store} product with ID {pid} successfully added to DB",
        )
    else:
        raise HTTPException(
            status_code=HTTP_404_NOT_FOUND,
            detail=f"Insertion failed for {payload.store} product with ID {pid}",
        )


@app_router.put("/{store}/{product_id}")
async def patch_single_product(store: str, product_id: str, db: AsyncIOMotorClient = Depends(get_database)):
    item_to_update = await fetch_all_products_nodict(store, product_id, db)  # Note: corrected signature usage
    if item_to_update:
        updated = await modify_existing_product(item_to_update, db)
        if updated:
            raise HTTPException(
                status_code=HTTP_200_OK,
                detail=f"{store} product with ID {product_id} has been updated",
            )
    else:
        raise HTTPException(
            status_code=HTTP_404_NOT_FOUND,
            detail=f"{store} product with ID {product_id} does not exist",
        )


@app_router.put("/{store}")
async def bulk_update_products(store: str, db: AsyncIOMotorClient = Depends(get_database)):
    products_to_sync = await fetch_all_products_nodict(store, db)
    if len(products_to_sync) > 0:
        for item in products_to_sync:
            _ = await modify_existing_product(item, db)
        raise HTTPException(
            status_code=HTTP_200_OK,
            detail=f"All {store} products have been synchronized",
        )
    else:
        raise HTTPException(
            status_code=HTTP_404_NOT_FOUND,
            detail=f"No products found for store '{store}' in database",
        )


@app_router.delete("/{store}/{product_id}")
async def remove_product(store: str, product_id: str, db: AsyncIOMotorClient = Depends(get_database)):
    delete_result = await db["ecom_product"][store].delete_many({"product_id": product_id})
    if delete_result.deleted_count > 0:
        return {"detail": f"{store} product with ID {product_id} has been removed"}

import os
import json
import numbers
import logging
import boto3

class SQSMessageSender:
    def __init__(self, queue_identifier, aws_profile=None, default_region='us-west-2'):
        self._logger = logging.getLogger(__name__)
        self._is_ready = False
        self._aws_session = None
        self._sqs_resource = None
        self._target_queue = None
        self._queue_name = queue_identifier
        self._profile_name = aws_profile or 'default'
        self._region_name = os.getenv('AWS_REGION') or default_region

    def establish_connection(self):
        try:
            self._aws_session = boto3.Session(
                region_name=self._region_name,
                profile_name=self._profile_name
            )
            self._sqs_resource = self._aws_session.resource('sqs')
            self._target_queue = self._sqs_resource.get_queue_by_name(QueueName=self._queue_name)
            self._is_ready = True
        except Exception:
            self._logger.exception("Failed to connect to SQS queue")
            raise ConnectionError("Unable to establish connection with SQS queue resource")

    def publish(self, payload, meta=None, dedup_id=None):
        if not self._is_ready:
            raise ConnectionError("SQS session is not initialized. Please call establish_connection() first.")
        formatted_msg = self._format_message(payload, meta, dedup_id)
        self._target_queue.send_message(**formatted_msg)

    def bulk_publish(self, *items, meta=None, dedup_id=None, max_per_batch=10):
        if not self._is_ready:
            raise ConnectionError("SQS session is not initialized. Please call establish_connection() first.")
        if max_per_batch > 10:
            max_per_batch = 10

        total_items = len(items)
        for batch_index in range((total_items + max_per_batch - 1) // max_per_batch):
            start_idx = batch_index * max_per_batch
            end_idx = min(start_idx + max_per_batch, total_items)

            batch_entries = []
            for idx, item in enumerate(items[start_idx:end_idx]):
                entry = self._format_message(item, meta, dedup_id)
                entry['Id'] = str(start_idx + idx)
                batch_entries.append(entry)

            if batch_entries:
                response = self._target_queue.send_messages(Entries=batch_entries)
                self._logger.debug(f"Batch send result: {response}")

    @staticmethod
    def _format_message(body_content, metadata, group_key, message_index=None):
        """
        Format a message according to AWS SQS specifications:
        https://docs.aws.amazon.com/AWSSimpleQueueService/latest/SQSDeveloperGuide/sqs-message-attributes.html
        """
        output = {
            'MessageBody': json.dumps(body_content),
            'MessageGroupId': group_key
        }

        if metadata is not None and isinstance(metadata, dict):
            output['MessageAttributes'] = SQSMessageSender._build_attributes(**metadata)

        if message_index is not None:
            output['Id'] = str(message_index)

        return output

    @staticmethod
    def _build_attributes(**kwargs):
        formatted = {}
        for key, value in kwargs.items():
            if isinstance(value, str):
                data_type = 'String'
            elif isinstance(value, numbers.Real) and not isinstance(value, bool):
                data_type = 'Number'
            else:
                continue

            formatted[key] = {
                'DataType': data_type,
                'StringValue': str(value)
            }
        return formatted

# Refactored ClusterMetadata class with equivalent functionality but different structure and logic

from __future__ import absolute_import
import collections
import copy
import logging
import threading
import time
from kafka.vendor import six
from kafka import errors as Errors
from kafka.conn import collect_hosts
from kafka.future import Future
from kafka.structs import BrokerMetadata, PartitionMetadata, TopicPartition

log = logging.getLogger(__name__)

class KafkaClusterState(object):
    """
    Manages Kafka cluster metadata state without performing I/O operations.
    Updates internal state based on API responses like MetadataResponse and GroupCoordinatorResponse.
    """

    CONFIG_DEFAULTS = {
        'retry_backoff_ms': 100,
        'metadata_max_age_ms': 300000,
        'bootstrap_servers': [],
    }

    def __init__(self, **settings):
        # Core data structures for tracking cluster state
        self._node_brokers = {}  # node_id -> BrokerMetadata
        self._topic_partitions = {}  # topic -> partition_id -> PartitionMetadata
        self._broker_assigned_partitions = collections.defaultdict(set)  # node_id -> set of TopicPartition
        self._consumer_groups = {}  # group_name -> coordinator_node_id

        # Timing and update tracking
        self._refresh_timestamp = 0
        self._last_valid_refresh = 0
        self._update_required = True
        self._pending_request = None
        self._observers = set()

        # Configuration and special topics tracking
        self.track_all_topics = False
        self.inaccessible_topics = set()
        self.system_topics = set()
        self.cluster_controller = None

        # Initialize configuration
        self.settings = copy.copy(self.CONFIG_DEFAULTS)
        for key in self.settings:
            if key in settings:
                self.settings[key] = settings[key]

        # Bootstrap broker setup
        self._initial_brokers = self._setup_bootstrap_nodes()
        self._coordinator_nodes = {}

    def _setup_bootstrap_nodes(self):
        """Configure initial bootstrap connections to Kafka brokers"""
        bootstrap_endpoints = collect_hosts(self.settings['bootstrap_servers'])
        nodes = {}
        for idx, (host, port, _) in enumerate(bootstrap_endpoints):
            node_id = f"bootstrap-{idx}"
            nodes[node_id] = BrokerMetadata(node_id, host, port, None)
        return nodes

    def is_bootstrap_node(self, node_id):
        """Check if a node ID corresponds to a bootstrap broker"""
        return node_id in self._initial_brokers

    def get_all_brokers(self):
        """Retrieve all known broker metadata"""
        return set(self._node_brokers.values()) or set(self._initial_brokers.values())

    def get_broker_info(self, broker_id):
        """Get metadata for a specific broker by ID"""
        return (
            self._node_brokers.get(broker_id) or
            self._initial_brokers.get(broker_id) or
            self._coordinator_nodes.get(broker_id)
        )

    def get_topic_partitions(self, topic_name):
        """Get all partition IDs for a given topic"""
        if topic_name not in self._topic_partitions:
            return None
        return set(self._topic_partitions[topic_name].keys())

    def get_active_partitions(self, topic_name):
        """Get partitions that have an assigned leader"""
        if topic_name not in self._topic_partitions:
            return None
        return set(
            partition_id for partition_id, meta in six.iteritems(self._topic_partitions[topic_name])
            if meta.leader != -1
        )

    def get_leader_for_partition(self, partition):
        """Get the leader node ID for a specific partition"""
        if partition.topic not in self._topic_partitions:
            return None
        elif partition.partition not in self._topic_partitions[partition.topic]:
            return None
        return self._topic_partitions[partition.topic][partition.partition].leader

    def get_broker_partitions(self, broker_id):
        """Get all partitions for which a broker is a leader"""
        return self._broker_assigned_partitions.get(broker_id)

    def get_group_coordinator(self, group_name):
        """Get coordinator node ID for a consumer group"""
        return self._consumer_groups.get(group_name)

    def time_to_next_refresh(self):
        """Calculate milliseconds until next metadata refresh is needed"""
        current_time = time.time() * 1000

        if self._update_required:
            return 0

        metadata_age = current_time - self._last_valid_refresh
        ttl = self.settings['metadata_max_age_ms'] - metadata_age

        retry_interval = current_time - self._refresh_timestamp
        next_retry = self.settings['retry_backoff_ms'] - retry_interval

        return max(ttl, next_retry, 0)

    def get_retry_delay(self):
        """Get backoff time before retrying after failure"""
        return self.settings['retry_backoff_ms']

    def trigger_update(self):
        """Request a metadata update and return a Future for completion"""
        with self._lock:
            self._update_required = True
            if not self._pending_request or self._pending_request.is_done:
                self._pending_request = Future()
            return self._pending_request

    def get_topics(self, filter_internal=True):
        """Get set of known topics, optionally excluding internal/system topics"""
        all_topics = set(self._topic_partitions.keys())
        if filter_internal:
            return all_topics - self.system_topics
        return all_topics

    def handle_failed_update(self, error):
        """Process a failed metadata update request"""
        future = None
        with self._lock:
            if self._pending_request:
                future = self._pending_request
                self._pending_request = None

        if future:
            future.failure(error)

        self._refresh_timestamp = time.time() * 1000

    def apply_metadata_update(self, response):
        """Process metadata response and update internal state"""
        # Handle single-topic error responses
        if len(response.topics) == 1 and response.topics[0][0] != 0:
            error_code, topic = response.topics[0][:2]
            error = Errors.for_code(error_code)(topic)
            return self.handle_failed_update(error)

        # Validate broker list exists
        if not response.brokers:
            log.warning("No broker metadata found in response -- ignoring.")
            return self.handle_failed_update(Errors.MetadataEmptyBrokerList(response))

        # Process broker metadata
        updated_brokers = {}
        for broker in response.brokers:
            if response.API_VERSION == 0:
                node_id, host, port = broker
                rack = None
            else:
                node_id, host, port, rack = broker
            updated_brokers[node_id] = BrokerMetadata(node_id, host, port, rack)

        # Set controller if available
        updated_controller = updated_brokers.get(response.controller_id) if response.API_VERSION > 0 else None

        # Process topic metadata
        updated_partitions = {}
        updated_broker_assignments = collections.defaultdict(set)
        updated_unauthorized = set()
        updated_system = set()

        for topic_data in response.topics:
            if response.API_VERSION == 0:
                error_code, topic, partitions = topic_data
                is_internal = False
            else:
                error_code, topic, is_internal, partitions = topic_data

            if is_internal:
                updated_system.add(topic)

            error_type = Errors.for_code(error_code)
            if error_type is Errors.NoError:
                updated_partitions[topic] = {}
                for p_error, partition, leader, replicas, isr in partitions:
                    partition_meta = PartitionMetadata(
                        topic=topic, partition=partition, leader=leader,
                        replicas=replicas, isr=isr, error=p_error)
                    updated_partitions[topic][partition] = partition_meta

                    if leader != -1:
                        updated_broker_assignments[leader].add(
                            TopicPartition(topic, partition))
            elif self.track_all_topics:
                continue
            elif error_type is Errors.LeaderNotAvailableError:
                log.warning("Topic %s is not available during auto-create initialization", topic)
            elif error_type is Errors.UnknownTopicOrPartitionError:
                log.error("Topic %s not found in cluster metadata", topic)
            elif error_type is Errors.TopicAuthorizationFailedError:
                log.error("Topic %s is not authorized for this client", topic)
                updated_unauthorized.add(topic)
            elif error_type is Errors.InvalidTopicError:
                log.error("'%s' is not a valid topic name", topic)
            else:
                log.error("Error fetching metadata for topic %s: %s", topic, error_type)

        # Apply updates atomically
        with self._lock:
            self._node_brokers = updated_brokers
            self.cluster_controller = updated_controller
            self._topic_partitions = updated_partitions
            self._broker_assigned_partitions = updated_broker_assignments
            self.inaccessible_topics = updated_unauthorized
            self.system_topics = updated_system

            future = self._pending_request
            self._pending_request = None
            self._update_required = False

        current_time = time.time() * 1000
        self._refresh_timestamp = current_time
        self._last_valid_refresh = current_time

        if future:
            future.success(self)

        log.debug("Updated cluster metadata to %s", self)

        # Notify observers
        for observer in self._observers:
            observer(self)

        if self.track_all_topics:
            self._update_required = False

    def register_observer(self, callback):
        """Add a callback to be invoked on metadata updates"""
        self._observers.add(callback)

    def unregister_observer(self, callback):
        """Remove a previously registered observer callback"""
        self._observers.remove(callback)

    def register_coordinator(self, group_name, response):
        """Update coordinator information for a consumer group"""
        log.debug("Updating coordinator for %s: %s", group_name, response)

        error_type = Errors.for_code(response.error_code)
        if error_type is not Errors.NoError:
            log.error("GroupCoordinatorResponse error: %s", error_type)
            self._consumer_groups[group_name] = -1
            return None

        # Create dedicated coordinator node ID
        node_id = f"coordinator-{response.coordinator_id}"
        coordinator = BrokerMetadata(
            node_id,
            response.host,
            response.port,
            None)

        log.info("Group coordinator for %s is %s", group_name, coordinator)
        self._coordinator_nodes[node_id] = coordinator
        self._consumer_groups[group_name] = node_id
        return node_id

    def create_copy_with_partitions(self, new_partitions):
        """Create a new metadata instance with additional partitions"""
        new_state = KafkaClusterState(**self.settings)
        new_state._node_brokers = copy.deepcopy(self._node_brokers)
        new_state._topic_partitions = copy.deepcopy(self._topic_partitions)
        new_state._broker_assigned_partitions = copy.deepcopy(self._broker_assigned_partitions)
        new_state._consumer_groups = copy.deepcopy(self._consumer_groups)
        new_state.system_topics = copy.deepcopy(self.system_topics)
        new_state.inaccessible_topics = copy.deepcopy(self.inaccessible_topics)

        for partition in new_partitions:
            if partition.topic not in new_state._topic_partitions:
                new_state._topic_partitions[partition.topic] = {}
            new_state._topic_partitions[partition.topic][partition.partition] = partition

            if partition.leader is not None and partition.leader != -1:
                new_state._broker_assigned_partitions[partition.leader].add(
                    TopicPartition(partition.topic, partition.partition))

        return new_state

    def __str__(self):
        return 'KafkaClusterState(brokers: %d, topics: %d, groups: %d)' % \
               (len(self._node_brokers), len(self._topic_partitions), len(self._consumer_groups))

from enum import Enum
from typing import Any, Literal, Optional, Union
from pydantic import BaseModel, validator
from igenius_adapters_sdk.entities import attribute, numeric_binning, uri

__all__ = [
    "AggregationAttribute",
    "BinningAttribute",
    "ProjectionAttribute",
]

class SortDirection(str, Enum):
    DESCENDING = "desc"
    ASCENDING = "asc"

class ConstantAttribute(BaseModel):
    constant_value: str
    label: str
    fallback_interpolation: Optional[Any]

class CoreAttribute(BaseModel):
    attribute_uri: uri.AttributeUri
    label: str

class ProjectionAttribute(CoreAttribute):
    pass

class SortCriterion(BaseModel):
    label: str
    order: SortDirection = SortDirection.ASCENDING

class FunctionIdentifier(BaseModel):
    operation_category: Literal["group_by", "aggregation"]
    operation_id: str
    operation_parameters: Optional[Union[numeric_binning.BinningRules, attribute.StaticTypes]]

    @validator("operation_id")
    def validate_operation_id(cls, v, values):
        if "operation_category" in values:
            category = values["operation_category"]
            if category == "group_by":
                attribute.GroupByFunction.from_uid(v)
            elif category == "aggregation":
                attribute.AggregationFunction.from_uid(v)
        return v

    @validator("operation_parameters")
    def validate_parameter_consistency(cls, v, values):
        if v and values["operation_id"] == attribute.GroupByFunction.NUMERIC_BINNING.uid:
            if not isinstance(v, numeric_binning.BinningRules):
                raise ValueError("operation_parameters must be BinningRules for numeric binning")
        return v

class AggregationAttribute(CoreAttribute):
    function_identifier: FunctionIdentifier
    fallback_interpolation: Optional[Any]

    @validator("function_identifier")
    def validate_aggregation_function(cls, v):
        if v and v.operation_category and v.operation_category != "aggregation":
            raise ValueError("Operation category must be aggregation")
        return v

class BinningAttribute(CoreAttribute):
    function_identifier: FunctionIdentifier

    @validator("function_identifier")
    def validate_grouping_function(cls, v):
        if v and v.operation_category and v.operation_category != "group_by":
            raise ValueError("Operation category must be group_by")
        return v

