    CertificateSigningRequest (CSR) enables x509 certificate generation
    through asynchronous approval workflows.
    Used by kubelets for:
     - Client authentication to kube-apiserver ("kubernetes.io/kube-apiserver-client-kubelet")
     - Serving TLS certificates ("kubernetes.io/kubelet-serving")
    Also supports custom signers and other certificate use cases.
    """
    def __init__(
        self,
        meta: ObjectMeta = None,
        specification: "CSRSpec" = None,
        status_info: "CSRStatus" = None,
    ):
        """Initialize CSR resource."""
        super(CSR, self).__init__(
            api_version="certificates/v1", kind="CertificateSigningRequest"
        )
        self._properties = {
            "metadata": meta or ObjectMeta(),
            "spec": specification or CSRSpec(),
            "status": status_info or CSRStatus(),
        }
        self._types = {
            "apiVersion": (str, None),
            "kind": (str, None),
            "metadata": (ObjectMeta, None),
            "spec": (CSRSpec, None),
            "status": (CSRStatus, None),
        }

    @property
    def metadata(self) -> ObjectMeta:
        return typing.cast(ObjectMeta, self._properties.get("metadata"))

    @metadata.setter
    def metadata(self, value: typing.Union[ObjectMeta, dict]):
        if isinstance(value, dict):
            value = ObjectMeta().from_dict(value)
        self._properties["metadata"] = value

    @property
    def spec(self) -> "CSRSpec":
        return typing.cast(CSRSpec, self._properties.get("spec"))

    @spec.setter
    def spec(self, value: typing.Union[CSRSpec, dict]):
        if isinstance(value, dict):
            value = CSRSpec().from_dict(value)
        self._properties["spec"] = value

    @property
    def status(self) -> "CSRStatus":
