"""
fs-to-dc: Index datasets from filesystem paths into an Open Data Cube (ODC) Index.
This tool extends `datacube dataset add` and `datacube dataset update` by:
- Automatically deciding whether to insert or update based on dataset existence
- Supporting STAC-formatted metadata files
"""

import click
import json
import logging
from pathlib import Path
from typing import Iterable, Optional

try:
    from yaml import CLoader as YamlLoader
except ImportError:
    from yaml import Loader

import datacube
from datacube.index.hl import Doc2Dataset
from odc.apps.dc_tools.utils import (
    index_update_dataset,
    update_if_exists_option,
    unsafe_allowed_option,
    stac_transform_enabled,
)
from odc.stac.transform import apply_stac_conversion


def configure_logging(level: int = logging.WARNING) -> None:
    """Initialize logging configuration."""
    logging.basicConfig(
        level=level,
        format="%(asctime)s [%(levelname)s] %(message)s",
        datefmt="%Y-%m-%d %H:%M:%S",
    )


def locate_dataset_files(
    source_paths: Iterable[str],
    pattern: Optional[str] = None,
    is_stac: bool = False,
) -> list[Path]:
    """Recursively find dataset files in given paths."""
    if pattern is None:
        pattern = "**/*.json" if is_stac else "**/*.yaml"

    found_files = []
    for path_str in source_paths:
        base_path = Path(path_str)
        if base_path.is_file():
            found_files.append(base_path)
        elif base_path.is_dir():
            found_files.extend(base_path.glob(pattern))
    return found_files


def load_metadata_from_file(file_path: Path, use_stac: bool = False) -> dict:
    """Load and optionally transform metadata from a file."""
    try:
        with file_path.open("r", encoding="utf-8") as fp:
            raw_data = fp.read()
        if file_path.suffix.lower() in {".yaml", ".yml"}:
            metadata = yaml.safe_load(raw_data, Loader=YamlLoader)
        else:
            metadata = json.loads(raw_data)

        if use_stac:
            metadata = apply_stac_conversion(metadata)
        return metadata
    except Exception as exc:
        raise RuntimeError(f"Failed to parse {file_path}: {exc}") from exc


@click.command(name="fs-to-dc", help=__doc__)
@update_if_exists_option
@unsafe_allowed_option
@stac_transform_enabled
@click.argument("DATASET_PATHS", nargs=-1, type=str)
def main_cli(dataset_paths, update_policy, permit_unsafe, stac_mode):
    """
    Main entry point for indexing datasets from local files.
    """
    configure_logging()

    dc_instance = datacube.Datacube()
    converter = Doc2Dataset(dc_instance.index)

    # Determine glob pattern and locate files
    file_list = locate_dataset_files(
        dataset_paths,
        pattern=None,
        is_stac=stac_mode,
    )

    success_count = 0
    failure_count = 0

    for dataset_file in file_list:
        try:
            meta = load_metadata_from_file(dataset_file, use_stac=stac_mode)
            uri = f"file://{dataset_file.resolve()}"

            index_update_dataset(
                meta,
                uri,
                dc=dc_instance,
                doc2ds=converter,
                update_if_exists=update_policy,
                allow_unsafe=permit_unsafe,
            )
            success_count += 1
        except Exception as err:
            logging.error("Error processing %s: %s", dataset_file, str(err))
            failure_count += 1

    logging.info("Processing complete: %d added, %d failed", success_count, failure_count)


if __name__ == "__main__":
    main_cli()

