# Validate and process limit input for a given size

import typing
from random import randrange

default_limit = ""

def is_valid_input(s: str) -> bool:
    return s.strip().lower() in {"", "random"}

def determine_limit(s: str, total_size: int) -> typing.Optional[int]:
    normalized = s.strip().lower()
    if normalized == "":
        return None
    elif normalized == "random":
        return randrange(total_size)
    else:
        # fallback behavior
        return None

load(":utils.bzl", "CONDA_EXT_MAP", "EXECUTE_TIMEOUT", "PYTHON_EXT_MAP", "get_os")

# Template for BUILD file content (same structure, rephrased comments)
BUILD_FILE_CONTENT = """# Auto-generated by rules_conda - do not edit manually
package(default_visibility = ["//visibility:public"])
load("@bazel_tools//tools/python:toolchain.bzl", "py_runtime_pair")

py_runtime(
    name = "python_runtime",
    files = glob(["{env_path}/**/*"], exclude_directories = 0),
    interpreter = "{env_path}/{interpreter_path}",
    python_version = "PY{major_version}"
)
"""

def _resolve_condabin_label(rctx, cmd_name):
    # Construct label pointing to conda/mamba executable in condabin/
    repo = rctx.attr.conda_repo
    dir_name = rctx.attr.conda_dir
    ext = CONDA_EXT_MAP[get_os(rctx)]
    return Label("@{}//:{}/condabin/{}{}".format(repo, dir_name, cmd_name, ext))

def _select_conda_command(rctx):
    # Choose between mamba and conda based on user preference
    if getattr(rctx.attr, "use_mamba", False):
        return _resolve_condabin_label(rctx, "mamba")
    return _resolve_condabin_label(rctx, "conda")

def _cleanup_conda_cache(rctx, exe_label):
    rctx.report_progress("Purging conda caches")
    cmd = [exe_label, "clean", "--all", "--yes"]
    outcome = rctx.execute(cmd, quiet = rctx.attr.quiet, timeout = rctx.attr.timeout)
    if outcome.return_code != 0:
        fail("Failed to clean conda cache.\nstdout: {}\nstderr: {}".format(outcome.stdout, outcome.stderr))

def _initialize_empty_env(rctx, exe_label, env_dir):
    rctx.report_progress("Initializing empty conda environment")
    cmd = [exe_label, "create", "--yes", "--prefix", "./{}".format(env_dir)]
    outcome = rctx.execute(cmd, quiet = rctx.attr.quiet, timeout = rctx.attr.timeout)
    if outcome.return_code != 0:
        fail("Failed to create empty environment.\nstdout: {}\nstderr: {}".format(outcome.stdout, outcome.stderr))

def _sync_environment_from_file(rctx, exe_label, env_dir, env_spec_path):
    rctx.report_progress("Populating environment from spec file")
    cmd = [exe_label, "env", "update", "--file", env_spec_path, "--prefix", "./{}".format(env_dir)]
    outcome = rctx.execute(cmd, quiet = rctx.attr.quiet, timeout = rctx.attr.timeout)
    if outcome.return_code != 0:
        fail("Failed to update environment.\nstdout: {}\nstderr: {}".format(outcome.stdout, outcome.stderr))

def _build_conda_env(rctx, exe_label, env_dir):
    rctx.report_progress("Constructing conda environment")
    spec_file = rctx.path(rctx.attr.environment)
    _initialize_empty_env(rctx, exe_label, env_dir)
    _sync_environment_from_file(rctx, exe_label, env_dir, spec_file)

def _determine_python_major(rctx, env_dir, interp_rel_path):
    full_interp_path = "{}/{}".format(env_dir, interp_rel_path)
    result = rctx.execute([rctx.path(full_interp_path), "--version"], timeout = rctx.attr.timeout)
    raw_output = result.stderr if not result.stdout else result.stdout
    version_str = raw_output.replace("Python ", "").split(".")[0]
    return int(version_str)

def _generate_build_file(rctx, env_dir):
    os_type = get_os(rctx)
    py_ext = PYTHON_EXT_MAP[os_type]
    interp_subpath = "{}".format(py_ext) if os_type == "Windows" else "bin/{}".format(py_ext)
    major_ver = _determine_python_major(rctx, env_dir, interp_subpath)

    rctx.file(
        "BUILD",
        content = BUILD_FILE_CONTENT.format(
            env_path = env_dir,
            interpreter_path = interp_subpath,
            major_version = major_ver,
        ),
    )

def _conda_create_repository_impl(rctx):
    selected_exe = _select_conda_command(rctx)
    target_env = rctx.name

    _build_conda_env(rctx, selected_exe, target_env)

    if getattr(rctx.attr, "clean", False):
        _cleanup_conda_cache(rctx, selected_exe)

    _generate_build_file(rctx, target_env)

conda_create_rule = repository_rule(
    _conda_create_repository_impl,
    attrs = {
        "conda_repo": attr.string(mandatory = True),
        "conda_dir": attr.string(mandatory = True),
        "environment": attr.label(
            mandatory = True,
            allow_single_file = True,
            doc = "Label referencing the environment.yml specification file.",
        ),
        "quiet": attr.bool(
            default = True,
            doc = "Suppress conda output when True",
        ),
        "use_mamba": attr.bool(
            default = False,
            doc = "Enable mamba as the solver instead of conda",
        ),
        "timeout": attr.int(
            default = EXECUTE_TIMEOUT,
            doc = "Maximum duration (seconds) per subprocess execution",
        ),
        "clean": attr.bool(
            default = False,
            doc = "Trigger cleanup of conda caches after environment creation",
        ),
    },
)

import re

def adobeaem_detection(headers, content):
    is_adobe_aem = False

    # Check for various AEM-specific patterns in the HTML content
    pattern1 = r"<link[^>]*stylesheet[^>]*etc/designs/[^>]*\>[^<]*"
    pattern2 = r"<link[^>]*etc/clientlibs/[^>]*\>[^<]*"
    pattern3 = r"<script[^>]*etc/clientlibs/[^>]*\>[^<]*"
    pattern4 = r"<script[^>]*\/granite/[^>]*(\.js\")+\>[^<]*"

    if re.search(pattern1, content, re.IGNORECASE):
        is_adobe_aem = True
    if re.search(pattern2, content, re.IGNORECASE):
        is_adobe_aem = True
    if re.search(pattern3, content, re.IGNORECASE):
        is_adobe_aem = True
    if re.search(pattern4, content, re.IGNORECASE):
        is_adobe_aem = True

    if is_adobe_aem:
        return "Adobe AEM: Stack is based on Apache Sling + Apache Felix OSGi container + JCR Repo + Java"

