class LoggingHandler:
    async def __call__(self, *args, **kwargs):
        log_msg(str(dict(**kwargs)))

class ConnectionRecord:
    class Phase(Enum):
        INVITE_SENT = 0,
        REQUEST_SENT = 1,
        RESPONSE_SENT = 2,
        ESTABLISHED = 3

    def __init__(self, conn_id: str, invite: sirius_sdk.aries_rfc.Invitation = None):
        self.identifier = conn_id
        self.phase = ConnectionRecord.Phase.INVITE_SENT
        self.invitation = invite
        self.pairwise_context = None

    def serialize(self) -> str:
        return json.dumps({
            "connection_id": self.identifier,
            "state": self.phase.name.lower()
        })

class CredentialExchange:
    def __init__(self, connection_id: str, cred_identifier: str = None):
        self.connection_id = connection_id
        self.credential_id = cred_identifier
        self.proposal_data = None
        self.referent_key: str = None
        self.schema_identifier: str = None
        self.cred_def_identifier: str = None
        self.thread_identifier: str = None

class PresentationExchangeRecord:
    def __init__(self):
        self.thread_identifier: str = None

class IndiLynxCloudAgentBackend(AgentBackchannel):
    def __init__(
        self,
        identity: str,
        http_port: int,
        admin_port: int,
        ledger_genesis: str = None,
        config: dict = {},
        additional_args: dict = {},
    ):
        super().__init__(identity, http_port, admin_port, ledger_genesis, config, additional_args)

        # Set auto-response flags
        self.auto_accept_requests = False
        self.auto_respond_messages = False
        self.auto_respond_credential_proposal = False
        self.auto_respond_credential_offer = False
        self.auto_respond_credential_request = False
        self.auto_respond_presentation_proposal = False
        self.auto_respond_presentation_request = False

        # Internal state tracking
        self.active_connections: Dict[str, ConnectionRecord] = {}
        self.pending_credentials: Dict[str, CredentialExchange] = {}
        self.presentation_records: List[PresentationExchangeRecord] = []
        self.dkms_name = "default"
        self.master_secret_label = "master_secret_id"

    async def start_listener(self):
        subscription = await sirius_sdk.subscribe()
        print("Listening")
        async for event in subscription:
            incoming_message = event['message']
            if isinstance(incoming_message, sirius_sdk.aries_rfc.ConnRequest):
                log_msg("received: " + str(incoming_message))
                my_did, my_verkey = await sirius_sdk.DID.create_and_store_my_did()
                me = sirius_sdk.Pairwise.Me(did=my_did, verkey=my_verkey)
                connection_key = event['recipient_verkey']
                my_endpoint = [e for e in await sirius_sdk.endpoints() if e.routing_keys == []][0]
                inviter_agent = sirius_sdk.aries_rfc.Inviter(
                    me=me,
                    connection_key=connection_key,
                    my_endpoint=my_endpoint,
                    logger=LoggingHandler()
                )
                success, pairwise_context = await inviter_agent.create_connection(incoming_message)
                if success:
                    await sirius_sdk.PairwiseList.ensure_exists(pairwise_context)
                    self.active_connections[connection_key].pairwise_context = pairwise_context
                    self.active_connections[connection_key].phase = ConnectionRecord.Phase.ESTABLISHED
            elif isinstance(incoming_message, sirius_sdk.aries_rfc.OfferCredentialMessage):
                log_msg("received: " + str(incoming_message))
                offer: sirius_sdk.aries_rfc.OfferCredentialMessage = incoming_message
                pairwise_context = event.pairwise
                holder_agent = sirius_sdk.aries_rfc.Holder(
                    pairwise=pairwise_context,
                    logger=LoggingHandler()
                )
                success, credential_id = await holder_agent.accept(
                    offer=offer,
                    master_secret_id=self.master_secret_label
                )
            elif isinstance(incoming_message, sirius_sdk.aries_rfc.ProposeCredentialMessage):
                proposal: sirius_sdk.aries_rfc.ProposeCredentialMessage = incoming_message
                pairwise_context = event.pairwise
                conn_id = None
                for cid in self.active_connections:
                    conn = self.active_connections[cid]
                    if conn.pairwise_context and conn.pairwise_context.their.did == pairwise_context.their.did:
                        conn_id = conn.identifier
                if conn_id:
                    self.pending_credentials[conn_id] = CredentialExchange(connection_id=conn_id, cred_identifier=conn_id)
                    self.pending_credentials[conn_id].proposal_data = proposal
            elif isinstance(incoming_message, sirius_sdk.aries_rfc.RequestPresentationMessage):
                pres_req: sirius_sdk.aries_rfc.RequestPresentationMessage = incoming_message
                verifier_context = event.pairwise
                dkms_instance = sirius_sdk.ledger(self.dkms_name)
                prover_agent = sirius_sdk.aries_rfc.Prover(
                    verifier=verifier_context,
                    ledger=dkms_instance,
                    logger=LoggingHandler()
                )
                pres_record = PresentationExchangeRecord()
                pres_record.thread_identifier = pres_req.id
                self.presentation_records.append(pres_record)
                success = await prover_agent.prove(
                    request=pres_req,
                    master_secret_id=self.master_secret_label
                )

    async def start_dummy_listener(self):
        subscription = await sirius_sdk.subscribe()
        print("Listening 2")
        async for event in subscription:
            log_msg("Received event: " + str(event))

    async def swap_thread_id_for_exchange_id(self, thread_id, data_type, id_field):
        timeout_counter = 0
        result = None
        while result is None and timeout_counter < 20:
            msg = get_resource(thread_id, data_type)
            try:
                exchange_id = msg[0][id_field]
                result = True
            except TypeError:
                await asyncio.sleep(1)
                timeout_counter += 1
        if timeout_counter >= 20:
            raise TimeoutError(
                "Timeout waiting for webhook callback to retrieve thread ID from exchange ID"
            )
        return exchange_id

    async def expected_agent_state(self, path, status_list, wait_time=2.0, sleep_interval=0.5):
        await asyncio.sleep(sleep_interval)
        current_state = "None"
        if not isinstance(status_list, list):
            status_list = [status_list]
        iterations = int(wait_time / sleep_interval)
        for _ in range(iterations):
            (response_status, response_text) = await self.make_admin_request("GET", path)
            if response_status == 200:
                resp_json = json.loads(response_text)
                current_state = resp_json["state"]
                if current_state in status_list:
                    return True
            await asyncio.sleep(sleep_interval)
        print("Expected state", status_list, "but received", current_state, ", with a response status of", response_status)
        return False

    async def make_agent_POST_request(
        self, operation, rec_id=None, payload=None, text_mode=False, query_params=None
    ) -> Tuple[int, str]:
        if operation["topic"] == "connection":
            action = operation["operation"]
            if action == "create-invitation":
                connection_key = await sirius_sdk.Crypto.create_key()
                inviter_endpoint = [e for e in await sirius_sdk.endpoints() if e.routing_keys == []][0]
                invitation = sirius_sdk.aries_rfc.Invitation(
                    label='IndiLynx Agent',
                    endpoint=inviter_endpoint.address,
                    recipient_keys=[connection_key]
                )
                self.active_connections[connection_key] = ConnectionRecord(conn_id=connection_key, invite=invitation)
                return 200, json.dumps({
                    "connection_id": connection_key,
                    "invitation": invitation
                })
            elif action == "receive-invitation":
                invitation = sirius_sdk.aries_rfc.Invitation(**dict(payload))
                log_msg("received: " + str(invitation))
                invitation.validate()
                connection_id = str(uuid.uuid1())
                self.active_connections[connection_id] = ConnectionRecord(conn_id=connection_id, invite=invitation)
                return 200, json.dumps({
                    "connection_id": connection_id,
                    "state": "invitation"
                })
            elif action == "accept-invitation":
                connection_id = rec_id
                invitation = self.active_connections[connection_id].invitation
                did, verkey = await sirius_sdk.DID.create_and_store_my_did()
                me = sirius_sdk.Pairwise.Me(did, verkey)
                my_endpoint = [e for e in await sirius_sdk.endpoints() if e.routing_keys == []][0]
                invitee_agent = sirius_sdk.aries_rfc.Invitee(
                    me=me,
                    my_endpoint=my_endpoint,
                    logger=LoggingHandler()
                )
                ok, pairwise_context = await invitee_agent.create_connection(invitation=invitation, my_label='IndiLynx Invitee')
                if ok:
                    self.active_connections[connection_id].pairwise_context = pairwise_context
                    self.active_connections[connection_id].phase = ConnectionRecord.Phase.ESTABLISHED
                    return 200, json.dumps({
                        "connection_id": connection_id,
                        "state": "active"
                    })
                else:
                    return 500, str(invitee_agent.problem_report)
            elif action == "accept-request":
                return 200, ""
            elif action == "send-ping":
                connection_id = rec_id
                await asyncio.sleep(1)
                return 200, json.dumps({
                    "connection_id": connection_id,
                    "state": "active"
                })
        elif operation["topic"] == "schema":
            schema_name = payload["schema_name"]
            schema_version = payload["schema_version"]
            attributes = payload["attributes"]
            schema_id, anoncred_schema = await sirius_sdk.AnonCreds.issuer_create_schema(
                issuer_did=self.did["did"],
                name=schema_name,
                version=schema_version,
                attrs=attributes
            )
            dkms = await sirius_sdk.ledger(self.dkms_name)
            schema = await dkms.ensure_schema_exists(anoncred_schema, self.did["did"])
            if not schema:
                ok, schema = await dkms.register_schema(anoncred_schema, self.did["did"])
            if schema:
                return 200, json.dumps({
                    "schema_id": schema_id,
                    "schema": schema.body
                })
            else:
                return 500, "Failed to register schema"
        elif operation["topic"] == "credential-definition":
            support_revocation = payload["support_revocation"]
            schema_id = payload["schema_id"]
            tag = payload["tag"]
            dkms = await sirius_sdk.ledger(self.dkms_name)
            schema = await dkms.load_schema(schema_id, self.did["did"])
            cred_defs = await dkms.fetch_cred_defs(schema_id=schema_id, submitter_did=self.did["did"])
            if len(cred_defs) > 0:
                ok, cred_def = await dkms.register_cred_def(
                    cred_def=sirius_sdk.CredentialDefinition(tag='TAG', schema=schema),
                    submitter_did=self.did["did"])
                if ok:
                    return 200, json.dumps({
                        "credential_definition_id": cred_def.id
                    })
                else:
                    return 500, "Failed to create cred def"
            else:
                return 200, json.dumps({
                    "credential_definition_id": cred_defs[0].id
                })
        elif operation["topic"] == "issue-credential":
            action = operation["operation"]
            if action == "send-proposal":
                connection_id = payload["connection_id"]
                if connection_id in self.active_connections:
                    if self.active_connections[connection_id].phase == ConnectionRecord.Phase.ESTABLISHED:
                        pw: sirius_sdk.Pairwise = self.active_connections[connection_id].pairwise_context
                        proposed_attribs = []
                        for attr in payload["credential_proposal"]["attributes"]:
                            proposed_attribs += [sirius_sdk.aries_rfc.ProposedAttrib(attr["name"], attr["value"])]
                        proposal = sirius_sdk.aries_rfc.ProposeCredentialMessage(
                            comment=payload.get("comment", None),
                            proposal_attrib=proposed_attribs,
                            schema_id=payload["schema_id"],
                            schema_name=payload["schema_name"],
                            schema_version=payload["schema_version"],
                            schema_issuer_did=payload["schema_issuer_did"],
                            cred_def_id=payload["cred_def_id"],
                            issuer_did=payload["issuer_did"]
                        )
                        await sirius_sdk.send_to(proposal, pw)
                        credential_id = proposal.id
                        self.pending_credentials[connection_id] = CredentialExchange(
                            connection_id=connection_id,
                            cred_identifier=credential_id
                        )
                        self.pending_credentials[connection_id].proposal_data = proposal
                        return 200, json.dumps({
                                "state": "proposal-sent",
                                "thread_id": proposal.id,
                                "credential_id": credential_id
                        })
                    else:
                        log_msg("Connection is not complete")
                else:
                    log_msg("Connection id does not exist")
            elif action == "send-offer":
                connection_id = payload["connection_id"]
                pw: sirius_sdk.Pairwise = self.active_connections[connection_id].pairwise_context
                issuer_agent = sirius_sdk.aries_rfc.Issuer(holder=pw)
                values = {}
                for attr in payload["credential_preview"]["attributes"]:
                    values[attr["name"]] = attr["value"]
                proposal: sirius_sdk.aries_rfc.ProposeCredentialMessage = self.pending_credentials[connection_id].proposal_data
                dkms = await sirius_sdk.ledger(self.dkms_name)
                schema = await dkms.load_schema(proposal.schema_id, self.did["did"])
                cred_def = await dkms.load_cred_def(proposal.cred_def_id, self.did["did"])
                credential_id = self.pending_credentials[connection_id].credential_id
                ok = await issuer_agent.issue(
                    values=values,
                    comment=payload["comment"],
                    schema=schema,
                    cred_def=cred_def,
                    cred_id=credential_id
                )
                if ok:
                    return 200, json.dumps({
                        "state": "credential-issued",
                        "thread_id": proposal.id,
                        "credential_id": credential_id
                    })
                else:
                    return 500, str(issuer_agent.problem_report)
        elif operation["topic"] == "proof":
            action = operation["operation"]
            if action == "send-proposal":
                return 500, "Not implemented"
            elif action == "send-request":
                connection_id = payload["connection_id"]
                presentation_request = payload["presentation_request"]
                comment = presentation_request["comment"]
                proof_request = presentation_request["proof_request"]["data"]
                prover_pairwise = self.active_connections[connection_id].pairwise_context
                dkms = await sirius_sdk.ledger(self.dkms_name)
                verifier_agent = sirius_sdk.aries_rfc.Verifier(
                    prover=prover_pairwise,
                    ledger=dkms,
                    logger=LoggingHandler()
                )
                pres_record = PresentationExchangeRecord()
                self.presentation_records.append(pres_record)
                success = await verifier_agent.verify(proof_request)
                if success:
                    return 200, json.dumps({
                        "state": "done",
                        #"thread_id":
                    })
            elif action == "send-presentation":
                return 200, json.dumps({
                })
        return 501, "501: Not Implemented\n\n".encode("utf8")

    async def make_agent_GET_request(
        self, operation, rec_id=None, text_mode=False, query_params=None
    ) -> Tuple[int, str]:
        if operation["topic"] == "status":
            status = 200 if self.ACTIVE else 418
            status_msg = "Active" if self.ACTIVE else "Inactive"
            return status, json.dumps({"status": status_msg})
        if operation["topic"] == "version":
            return 200, "1.0"
        elif operation["topic"] == "connection":
            if rec_id:
                connection_id = rec_id
                if connection_id in self.active_connections:
                    return 200, self.active_connections[connection_id].serialize()
                else:
                    return 500, rec_id + " not recognized"
            else:
                res = []
                for conn_id in self.active_connections:
                    res.append(self.active_connections[conn_id].serialize)
                return 200, str(res)
        elif operation["topic"] == "did":
            if self.did:
                return 200, json.dumps({
