async def run_agent(start_port: int, show_timing: bool = False, interactive: bool = True, did=None):
    # Process extra arguments
    extra_args = {}
    if EXTRA_ARGS_ENV:
        print("Got extra args:", EXTRA_ARGS_ENV)
        extra_args = json.loads(EXTRA_ARGS_ENV)

    agent = None
    try:
        agent = IndiLynxCloudAgentBackend(
            "indiLynx." + AGENT_LABEL,
            start_port + 1,
            start_port + 2,
            ledger_genesis="{}",
            additional_args=extra_args,
        )
        agent.did = did
        # start backchannel (common across all types of agents)
        await agent.listen_backchannel(start_port)
        #await agent.register_did()
        asyncio.get_event_loop().create_task(agent.start_listener())
        asyncio.get_event_loop().create_task(agent.start_dummy_listener())
        agent.activate()
        # now wait ...
        interactive = False
        print(interactive)
        if interactive:
            async for option in prompt_loop("(X) Exit? [X] "):
                if option is None or option in "xX":
                    break
        else:
            print("Press Ctrl-C to exit ...")
            remaining_tasks = asyncio.Task.all_tasks()
            await asyncio.gather(*remaining_tasks)
    finally:
        terminated = True
        try:
            if agent:
                await agent.terminate()
        except Exception:
            LOGGER.exception("Error terminating agent:")
            terminated = False
    await asyncio.sleep(0.1)
    if not terminated:
        os._exit(1)

def convert_to_bool(v):
    if isinstance(v, bool):
        return v
    if v.lower() in ("yes", "true", "t", "y", "1"):
        return True
    elif v.lower() in ("no", "false", "f", "n", "0"):
        return False
    else:
        raise argparse.ArgumentTypeError("Boolean value expected.")

