from dataclasses import dataclass, field
from typing import Set, Dict, List, Optional
from pandemic.simulation.model import constants
from pandemic.simulation.model.city_id import Card, EventCard
from pandemic.simulation.model.constants import PLAYER_START, CITY_COLORS

@dataclass
class PlayerState:
    city: int = PLAYER_START
    _city_cards: Set[Card] = field(default_factory=set)
    _event_cards: Set[EventCard] = field(default_factory=set)
    _contingency_planner_city_card: Optional[Card] = None
    _contingency_planner_event_card: Optional[Card] = None
    _operations_expert_shuttle_available: bool = True
    _card_count: int = 0
    _virus_color_counts: Dict[str, int] = field(default_factory=lambda: {color: 0 for color in CITY_COLORS.values()})

    @property
    def all_cards(self) -> Set[Card]:
        return self.cities | self.events

    @property
    def virus_color_distribution(self) -> Dict[str, int]:
        return self._virus_color_counts.copy()

    @all_cards.setter
    def all_cards(self, new_cards: Set[Card]):
        self.reset_hand()
        self.receive_cards(list(new_cards))

    @property
    def cities(self) -> Set[Card]:
        result = set(self._city_cards)
        if self._contingency_planner_city_card:
            result.add(self._contingency_planner_city_card)
        return result

    @property
    def events(self) -> Set[EventCard]:
        result = set(self._event_cards)
        if self._contingency_planner_event_card:
            result.add(self._contingency_planner_event_card)
        return result

    @property
    def special_card(self) -> Optional[Card]:
        return self._contingency_planner_city_card or self._contingency_planner_event_card

    @special_card.setter
    def special_card(self, card: Card):
        if Card.type(card) == Card.CITY_TYPE:
            color_key = CITY_COLORS.get(card, "")
            self._virus_color_counts[color_key] += 1
            self._contingency_planner_city_card = card
            self._contingency_planner_event_card = None
        else:
            self._contingency_planner_city_card = None
            self._contingency_planner_event_card = card

    def receive_card(self, card: Card):
        if Card.type(card) == Card.EVENT_TYPE:
            self._event_cards.add(card)
            self._card_count += 1
        elif Card.type(card) == Card.CITY_TYPE:
            color_key = CITY_COLORS.get(card, "")
            self._virus_color_counts[color_key] += 1
            self._city_cards.add(card)
            self._card_count += 1

    def receive_cards(self, cards: List[Card]):
        for card in cards:
            self.receive_card(card)

    def reset_hand(self):
        self._card_count = 0
        self._virus_color_counts = {color: 0 for color in CITY_COLORS.values()}
        self._contingency_planner_city_card = None
        self._contingency_planner_event_card = None
        self._event_cards.clear()
        self._city_cards.clear()

    def discard_card(self, card: Card) -> bool:
        if Card.type(card) == Card.CITY_TYPE:
            try:
                self._city_cards.discard(card)
                self._card_count -= 1
                color_key = CITY_COLORS.get(card, "")
                self._virus_color_counts[color_key] -= 1
                return True
            except KeyError:
                if card == self._contingency_planner_city_card:
                    self._contingency_planner_city_card = None
                    color_key = CITY_COLORS.get(card, "")
                    self._virus_color_counts[color_key] -= 1
                    return False
        else:
            try:
                self._event_cards.discard(card)
                self._card_count -= 1
                return True
            except KeyError:
                if card == self._contingency_planner_event_card:
                    self._contingency_planner_event_card = None
                    return False
                raise KeyError

    def hand_size(self) -> int:
        return self._card_count

    def use_operations_expert_move(self):
        self._operations_expert_shuttle_available = False

    def end_turn(self):
        self._operations_expert_shuttle_available = True

    def can_use_operations_expert_move(self) -> bool:
        return self._operations_expert_shuttle_available

    def hand_to_string(self) -> str:
        return " ".join(str(card) for card in self.all_cards)

