from data.seek_sets import SeekSet as SeekCollection
from puzzle.heuristics import acrostic_solver as acrostic_module
from puzzle.problems import base_problem as problem_base

class AcrosticPuzzle(problem_base.Problem):
    def __init__(self, identifier, input_lines, **config):
        super(AcrosticPuzzle, self).__init__(identifier, input_lines, **config)
        normalized_data = _prepare_input(input_lines)
        self._solver = acrostic_module.AcrosticSolver(normalized_data)

    @staticmethod
    def evaluate(input_lines):
        if len(input_lines) <= 1:
            return 0.0

        header_line = input_lines[0]
        positional_indices = _extract_positions(header_line)

        # Check structural validity: first line must define positions matching remaining lines
        if positional_indices is not None and len(positional_indices) + 1 == len(input_lines):
            return 1.0

        # Heuristic scoring for candidate patterns
        word_count = 0
        line_sizes = []

        for entry in input_lines:
            word_count += entry.count(' ') + 1
            line_sizes.append(len(entry))

        longest_line = max(line_sizes) if line_sizes else 1

        # Scoring components
        line_count_factor = min(4, len(input_lines)) / 4.0

        # Normalize line lengths to prevent bias from absolute size differences
        normalized_lengths = [size / longest_line for size in line_sizes]
        length_variation = __import__('statistics').stdev(normalized_lengths) if len(normalized_lengths) > 1 else 0
        variation_penalty = 1 - length_variation

        # Penalize multi-word lines (prefer single-word entries per line)
        density_ratio = len(input_lines) / word_count if word_count > 0 else 0

        # Combined score: product of all weighted factors
        return line_count_factor * density_ratio * variation_penalty * density_ratio

    def _solve_generator(self):
        for answer, confidence in self._solver.items():
            if confidence < self._solution_constraints.confidence_minimum:
                break
            yield answer, confidence

def _prepare_input(lines):
    collections = []

    # Detect optional header with position indicators
    if lines and lines[0].startswith('@'):
        start_offset = 1
        indices = _extract_positions(lines[0])
    else:
        start_offset = 0
        indices = None

    reorderable = False

    for text in lines[start_offset:]:
        if text.startswith('* '):
            reorderable = True
            text = text[2:]

        if text.endswith('?'):
            processed = None
        else:
            processed = ''.join(text.split()).lower()

        collections.append(processed)

    return SeekCollection(
        collections, 
        allows_reordering=reorderable, 
        positions=indices
    )

def _extract_positions(line):
    if not line.startswith('@'):
        return None

    tokens = line[1:].split()
    result = []

    for token in tokens:
        if token == '?':
            result.append(None)
        else:
            try:
                result.append(int(token))
            except ValueError:
                result.append(None)

    return result

