    @staticmethod
    def _extract_from_page(webpage_text):
        pattern = r'<iframe[^>]+\b(?:data-)?src=(["\'])(?P<link>%s.*?)\1' % ThreeQSDNRedirIE._VALID_URL
        match = re.search(pattern, webpage_text)
        return match.group('link') if match else None

    def _perform_extraction(self, url):
        vid_id = self._match_id(url)
        config_url = url.replace('://playout.3qsdn.com/', '://playout.3qsdn.com/config/')
        try:
            cfg_data = self._download_json(config_url, vid_id)
        except ExtractorError as err:
            if isinstance(err.cause, compat_HTTPError) and err.cause.code == 401:
                self.raise_geo_restricted()
            raise

        is_streaming_live = cfg_data.get('streamContent') == 'live'
        ratio = float_or_none(cfg_data.get('aspect'))

        media_formats = []
        caption_tracks = {}

        for fmt_type, src_list in (cfg_data.get('sources') or {}).items():
            if not src_list:
                continue

            if fmt_type == 'dash':
                fmts, caps = self._extract_mpd_formats_and_subtitles(
                    src_list, vid_id, mpd_id='mpd', fatal=False)
                media_formats.extend(fmts)
                caption_tracks = self._merge_subtitles(caption_tracks, caps)

            elif fmt_type == 'hls':
                fmts, caps = self._extract_m3u8_formats_and_subtitles(
                    src_list, vid_id, 'mp4', 'm3u8' if is_streaming_live else 'm3u8_native',
                    m3u8_id='hls', fatal=False)
                media_formats.extend(fmts)
                caption_tracks = self._merge_subtitles(caption_tracks, caps)

            elif fmt_type == 'progressive':
                for item in src_list:
                    src_url = item.get('src')
                    if not (src_url and self._is_valid_url(src_url, vid_id)):
                        continue
                    file_ext = determine_ext(src_url)
                    res_val = int_or_none(item.get('height'))
                    media_formats.append({
                        'ext': file_ext,
                        'format_id': join_nonempty('http', file_ext, res_val and f'{res_val}p'),
                        'height': res_val,
                        'source_preference': 0,
                        'url': src_url,
                        'vcodec': 'none' if res_val == 0 else None,
                        'width': int(res_val * ratio) if res_val and ratio else None,
                    })

        # Sorting by resolution & preference (same behavior as original)
        self._sort_formats(media_formats, ('res', 'source_preference'))

        # Process subtitles
        for sub_entry in (cfg_data.get('subtitles') or []):
            sub_src = sub_entry.get('src')
            if not sub_src:
                continue
            lang_key = sub_entry.get('label') or 'eng'
            caption_tracks.setdefault(lang_key, []).append({'url': sub_src})

        base_title = cfg_data.get('title') or vid_id
        return {
            'id': vid_id,
            'title': base_title,
            'thumbnail': cfg_data.get('poster') or None,
            'description': cfg_data.get('description') or None,
            'timestamp': parse_iso8601(cfg_data.get('upload_date')),
            'duration': float_or_none(cfg_data.get('vlength')) or None,
            'is_live': is_streaming_live,
            'formats': media_formats,
            'subtitles': caption_tracks,
        }

