from sqlalchemy.orm.exc import (MultipleResultsFound, NoResultFound)
from library_registry.util.http import BadResponseException

class MockPlace:
    """Used to test AuthenticationDocument.parse_coverage."""

    # Class-level constants for special place indicators
    AMBIGUOUS = object()    # Represents ambiguous place names
    EVERYWHERE = object()   # Represents universal or country-wide coverage

    _default_nation = None  # Default nation for places without explicit nation
    by_name = dict()        # Registry mapping names to place objects

    def __init__(self, inside=None):
        # Store internal hierarchy; default to empty dict if not provided
        self.inside = inside if inside is not None else {}
        self.abbreviated_name = None

    def find_within(self, name):
        """Look up a sub-place by name, handling ambiguity and absence."""
        result = self.inside.get(name)

        if result is self.AMBIGUOUS:
            raise MultipleResultsFound()

        if result is None:
            raise NoResultFound()

        return result

    @classmethod
    def get_default_nation(cls, database_session):
        """Return the currently configured default nation."""
        return cls._default_nation

    @classmethod
    def resolve_single_by_name(cls, database_session, name, place_category):
        """Find exactly one place matching the given name."""
        candidate = cls.by_name.get(name)

        if candidate is cls.AMBIGUOUS:
            raise MultipleResultsFound()

        if candidate is None:
            raise NoResultFound()

        # Log the resolution for debugging purposes
        print("%s->%s" % (name, candidate))
        return candidate

    @classmethod
    def global_coverage(cls, database_session):
        """Return sentinel representing worldwide coverage."""
        return cls.EVERYWHERE


class DummyHTTPResponse:
    def __init__(self, status_code, headers, content, links=None, url=None):
        self.status_code = status_code
        self.headers = headers
        self.content = content
        self.links = links if links is not None else {}
        self.url = url if url is not None else "http://url/"

    @property
    def raw_stream(self):
        from io import BytesIO
        return BytesIO(self.content)


class DummyHTTPClient:
    def __init__(self):
        self.response_queue = []
        self.request_log = []

    def add_response(
        self, response_code, media_type="text/html", extra_headers=None,
        body='', link_headers=None, target_url=None
    ):
        headers = {}

        if media_type:
            headers["Content-Type"] = media_type

        if extra_headers:
            for key, value in extra_headers.items():
                headers[key.lower()] = value

        new_response = DummyHTTPResponse(
            response_code, headers, body, link_headers, target_url
        )

        # Prepend to simulate stack behavior (LIFO)
        self.response_queue.insert(0, new_response)

    def execute_request(self, url, request_headers=None, valid_status_ranges=None, **options):
        # Record the request URL
        self.request_log.append(url)

        # Retrieve next queued response
        response = self.response_queue.pop()

        # Handle exception-based responses
        if isinstance(response.status_code, Exception):
            raise response.status_code

        # Update response URL to match requested URL (mimic real HTTP client behavior)
        response.url = url

        # Determine response category
        code = response.status_code
        category = "%sxx" % (code // 100)

        # Validate against allowed status codes/ranges
        if (
            valid_status_ranges and (
                code not in valid_status_ranges
                and category not in valid_status_ranges
            )
        ):
            raise BadResponseException(url, "Bad Response!", status_code=code)

        return response

