# Storage for example generators by return type
_generator_registry = {}

def _register_example(func):
    """Registers a function as an example generator for its return type."""
    try:
        return_type = typing.get_type_hints(func)['return']
        _generator_registry[return_type] = func
    except KeyError:
        pass
    return func

