DEFAULT_TEXT = 'Lorem ipsum dolor sit amet.'
_static_examples = {}

def _load_static_examples():
    import json
    import logging
    logger = logging.getLogger(__name__)
    try:
        with open('data/arg_examples.json', encoding='utf-8') as file:
            data = json.load(file)
        _static_examples.update(data)
    except Exception:
