_load_static_examples()

def _fetch_static_example(key, command_name=''):
    # Try both command-specific and global keys
    search_keys = [f'{command_name}.{key}', key]
    for candidate_key in search_keys:
        candidates = _static_examples.get(candidate_key)
        if not candidates:
            continue
        if isinstance(candidates, list):
            return random.choice(candidates)
        return candidates
    return DEFAULT_TEXT

def _resolve_command(ctx):
    cmd = ctx.command
    return ctx.kwargs['command'] if cmd.name == 'help' else cmd

@_register_example
def _sample_string(ctx) -> str:
    param_name = ctx._current_parameter.name
    current_cmd = _resolve_command(ctx)
    return _fetch_static_example(param_name, current_cmd)

def _obtain_name(obj):
    try:
        return obj.__name__
    except AttributeError:
        return obj.__class__.__name__

def _is_discord_converter(converter):
    module = getattr(converter, '__module__', '')
    return module.startswith('discord') and module.endswith('converter')

def _ensure_class(obj):
    return obj if isinstance(obj, type) else type(obj)

def _format_annotation(annotation, base_module=None):
    if getattr(annotation, '__module__', None) == 'typing':
        return repr(annotation).replace('typing.', '')
    if isinstance(annotation, type):
        if annotation.__module__ in ('builtins', base_module):
            return annotation.__qualname__
        return f'{annotation.__module__}.{annotation.__qualname__}'
    return repr(annotation)

_NoneType = type(None)

def get_example(converter, ctx):
    """Produces a sample value based on the converter type."""
    if hasattr(converter, 'random_example'):
        return converter.random_example(ctx)

    origin = getattr(converter, '__origin__', None)
    if origin is typing.Union:
        args = converter.__args__
        if len(args) == 2 and args[-1] is _NoneType:
            converter = args[0]
        else:
            converter = random.choice(args)
        return get_example(converter, ctx)

    if _is_discord_converter(converter):
        cls = _ensure_class(converter)
        if cls is commands.clean_content:
            converter = str
        else:
            name = _obtain_name(converter).replace('Converter', '')
            converter = getattr(discord, name, converter)

    try:
        generator = _generator_registry[converter]
    except KeyError as e:
        raise ValueError(f'Unable to get an example for {_format_annotation(converter)}') from e
    else:
        return generator(ctx)

def wrap_example(target):
    """Attaches a custom example generator function to a converter."""
    def decorator(func):
        target.random_example = func
        return func
    return decorator

def static_example(converter):
    """Assigns the static string-based example generator to a converter."""
    converter.random_example = _sample_string
    return converter

# Example formatting helpers
_get_converter = functools.partial(commands.Command._get_converter, None)
_quote_chars = '|'.join(map(re.escape, commands.view._all_quotes))
_quote_pattern = re.compile(rf'\\(.)|({_quote_chars})')
_escape_quotes = functools.partial(_quote_pattern.sub, r'\\\1\2')

def _quote_value(string):
    escaped = _escape_quotes(string)
    if any(str.isspace(c) for c in escaped):
        escaped = f'"{escaped}"'
    return escaped

def _is_required_param(param):
    return (param.default is param.empty and 
            param.kind is not param.VAR_POSITIONAL)

MAX_VARARGS_REPETITIONS = 4

def _generate_param_examples(parameters, ctx, command=None):
    command = command or ctx.command

    def produce_example(parameter):
        ctx._current_parameter = parameter
        conv = _get_converter(parameter)
        sample = str(get_example(conv, ctx))

        # Skip quoting for keyword-only when rest_is_raw, or special prefixes
        if not (parameter.kind == parameter.KEYWORD_ONLY and not command.rest_is_raw or 
                sample.startswith(('#', '@'))):
            sample = _quote_value(sample)
        return sample

    for param in parameters:
        yield produce_example(param)
        if param.kind is param.VAR_POSITIONAL:
            min_reps = varpos.requires_var_positional(param)
            reps = random.randint(min_reps, MAX_VARARGS_REPETITIONS)
            for _ in range(reps):
                yield produce_example(param)

def _partition_params(command):
    """Divides command parameters into required and optional groups."""
    params = list(command.clean_params.values())
    required = list(itertools.takewhile(_is_required_param, params))
    optional = []

    remaining = itertools.dropwhile(_is_required_param, params)
    for param in remaining:
        if param.kind is param.VAR_POSITIONAL:
            group = required if varpos.requires_var_positional(command) else optional
            group.append(param)
            break
        optional.append(param)
        if param.kind is param.KEYWORD_ONLY:
            break

    return required, optional

def command_example(command, ctx):
    """Generates usage examples for a command.

    If optional arguments exist, returns multiple lines:
    - One with only required args
    - Additional lines incrementally adding optional args
    """
    qualified_names = list(all_qualified_names(command))
    required, optional = _partition_params(command)

    def build_example(params):
        parts = ' '.join(_generate_param_examples(params, ctx, command))
        prefix = ctx.clean_prefix
        cmd_name = random.choice(qualified_names)
        return f'`{prefix}{cmd_name} {parts}`'

    base_usage = build_example(required)
    if not optional:
        return base_usage

    # Build progressively longer examples
    incremental = []
    for i in range(len(optional)):
        full_params = required + optional[:i+1]
        incremental.append(build_example(full_params))

    return '\n'.join([base_usage] + incremental)

