from typing import List, Optional
import pandas as pd

class PEPRECFileError(Exception):
    """Custom exception for invalid or malformed PEPREC files."""
    pass

class PeptideRecord:
    """Class representing a peptide record loaded from a PEPREC file."""

    def __init__(
        self,
        filepath: Optional[str] = None,
        mode: str = "standard",
        additional_fields: Optional[List[str]] = None,
    ):
        """
        Initialize a PeptideRecord instance.

        Parameters
        ----------
        filepath : str, optional
            Path to the input PEPREC file. If provided, the file is automatically loaded.
        mode : str
            Operational mode affecting required columns. Supported values: "standard", "ms2rescore".
        additional_fields : list of str, optional
            Extra column names to be considered as required during validation.
        """
        self.filepath = filepath
        self.mode = mode
        self.additional_fields = additional_fields or []
        self._dataframe = None

        if self.filepath:
            self.load_from_csv(self.filepath)

    def __repr__(self) -> str:
        """Return string representation of the underlying DataFrame."""
        return repr(self._dataframe)

    @property
    def dataframe(self) -> Optional[pd.DataFrame]:
        """Access the internal DataFrame."""
        return self._dataframe

    @dataframe.setter
    def dataframe(self, df: Optional[pd.DataFrame]):
        """Assign and validate a new DataFrame."""
        if isinstance(df, pd.DataFrame):
            self._check_columns(df)
        self._dataframe = df

    def load_from_csv(self, path: str, **kwargs):
        """Load PEPREC data from a CSV file."""
        self._validate_first_line(path)
        delimiter = self._detect_delimiter(path)
        self.dataframe = pd.read_csv(path, sep=delimiter, index_col=None, **kwargs)
        # Replace NaN in 'modifications' with '-'
        if 'modifications' in self.dataframe.columns:
            self.dataframe['modifications'] = self.dataframe['modifications'].fillna('-')

    def save_to_csv(self, path: Optional[str] = None, **kwargs):
        """Write current DataFrame to a CSV file."""
        target_path = path or self.filepath
        if not target_path:
            raise ValueError("No output path specified and no stored filepath available.")

        self.dataframe.to_csv(
            target_path, 
            sep=" ", 
            index=False, 
            float_format="%.3f", 
            **kwargs
        )

    def sort_columns(self):
        """Reorder columns so canonical ones appear first."""
        cols = list(self.dataframe.columns)
        # Remove canonical columns from their current positions
        for col in self._mandatory_columns:
            if col in cols:
                cols.remove(col)
        # Reconstruct column order
        final_order = self._mandatory_columns + cols
        self.dataframe = self.dataframe[final_order]

    @property
    def _mandatory_columns(self) -> List[str]:
        """Determine mandatory columns based on operational mode."""
        base_cols = ["spec_id", "peptide", "modifications", "charge"]

        if self.mode == "ms2rescore":
            base_cols += ["psm_score", "observed_retention_time"]
        elif self.mode == "retention_time":
            if "modifications" in base_cols:
                base_cols.remove("modifications")

        return base_cols

    def _validate_first_line(self, path: str):
        """Ensure the file starts with the expected header."""
        with open(path, 'r') as f:
            first_line = f.readline()
            if not first_line.startswith("spec_id"):
                raise PEPRECFileError("PEPREC file must begin with 'spec_id'.")

    def _check_columns(self, df: pd.DataFrame):
        """Verify that all mandatory columns are present."""
        missing = [col for col in self._mandatory_columns if col not in df.columns]
        if missing:
            raise PEPRECFileError(f"Missing required columns: {', '.join(missing)}")

    @classmethod
    def from_dataframe(cls, df: pd.DataFrame):
        """Create a PeptideRecord instance directly from a pandas DataFrame."""
        instance = cls()
        instance.dataframe = df
        instance.sort_columns()
        return instance

    @classmethod
    def from_csv_file(cls, *args, **kwargs):
        """Factory method to create an instance by loading a CSV file."""
        instance = cls()
        instance.load_from_csv(*args, **kwargs)
        return instance

    @staticmethod
    def _detect_delimiter(path: str) -> str:
        """Guess the field separator used in the PEPREC file."""
        with open(path, 'r') as f:
            line = f.readline()
            # Assuming 7th character (index 7) is the delimiter after 'spec_id'
            return line[7] if len(line) > 7 else ','

from ._types import Options
