import logging
from datetime import timedelta
from seraphsix import constants
from seraphsix.tasks.parsing import member_hash
from seraphsix.models.database import (
    Member,
    Clan,
    ClanMember,
    GameMember,
    Game,
    ClanGame,
)
from urllib.parse import urlparse
from tortoise import Tortoise
from tortoise.exceptions import IntegrityError
from tortoise.functions import Lower
from tortoise.query_utils import Q
from tortoise import timezone

log = logging.getLogger(__name__)


class Database:
    def __init__(self, db_url: str, pool_size: int = constants.DB_MAX_CONNECTIONS):
        parsed = urlparse(db_url)
        self._host = parsed.hostname
        self._port = parsed.port
        self._user = parsed.username
        self._pass = parsed.password
        self._db_name = parsed.path.lstrip("/")
        self._pool_size = pool_size

    async def setup(self):
        await Tortoise.init(
            config={
                "connections": {
                    "default": {
                        "engine": "tortoise.backends.asyncpg",
                        "credentials": {
                            "host": self._host,
                            "port": self._port,
                            "user": self._user,
                            "password": self._pass,
                            "database": self._db_name,
                            "max_size": self._pool_size,
                        },
                    }
                },
                "apps": {
                    "seraphsix": {
                        "models": ["seraphsix.models.database"],
                    }
                },
            }
        )

    async def find_member_by_platform_id(self, uid: int, platform: int) -> Member | None:
        field_map = {
            constants.PLATFORM_BUNGIE: "bungie_id",
            constants.PLATFORM_PSN: "psn_id",
            constants.PLATFORM_XBOX: "xbox_id",
            constants.PLATFORM_BLIZZARD: "blizzard_id",
            constants.PLATFORM_STEAM: "steam_id",
            constants.PLATFORM_STADIA: "stadia_id",
        }
        field = field_map.get(platform)
        if not field:
            return None
        return await Member.get_or_none(**{field: uid})

    async def find_member_by_username(self, username: str, include_clan: bool = True) -> ClanMember | Member | None:
        username = username.lower()
        fields = [
            "bungie_username",
            "xbox_username",
            "psn_username",
            "blizzard_username",
            "steam_username",
            "stadia_username",
        ]
        annotated_fields = {f"{f}_lo": Lower(f) for f in fields}

        query = ClanMember.annotate(**annotated_fields).prefetch_related("member", "clan") if include_clan else Member.annotate(**annotated_fields)

        conditions = [Q(**{f"{f}_lo": username}) for f in fields]
        return await query.get_or_none(Q(*conditions))

    async def register_member(self, name: str, mid: int, platform: int) -> Member:
        field_map = {
            constants.PLATFORM_BUNGIE: "bungie_id",
            constants.PLATFORM_PSN: "psn_id",
            constants.PLATFORM_XBOX: "xbox_id",
            constants.PLATFORM_BLIZZARD: "blizzard_id",
            constants.PLATFORM_STEAM: "steam_id",
            constants.PLATFORM_STADIA: "stadia_id",
        }
        field = field_map.get(platform)
        if not field:
            raise ValueError(f"Unsupported platform ID: {platform}")
        return await Member.create(name=name, **{field: mid})

    async def find_member_by_platform_and_username(self, uname: str, platform: int) -> Member | None:
        uname = uname.lower()
        platform_field_map = {
            constants.PLATFORM_BUNGIE: "bungie_username",
            constants.PLATFORM_PSN: "psn_username",
            constants.PLATFORM_XBOX: "xbox_username",
            constants.PLATFORM_BLIZZARD: "blizzard_username",
            constants.PLATFORM_STEAM: "steam_username",
            constants.PLATFORM_STADIA: "stadia_username",
        }
        field = platform_field_map.get(platform)
        if not field:
            return None
        return await Member.annotate(name_lo=Lower(field)).get_or_none(name_lo=uname).prefetch_related("clans")

    async def find_member_by_discord(self, discord_id: int, with_clan: bool = True) -> ClanMember | Member | None:
        if with_clan:
            return await ClanMember.get_or_none(member__discord_id=discord_id).prefetch_related("member", "clan")
        else:
            return await Member.get_or_none(discord_id=discord_id)

    async def list_clan_members(self, clan_ids: list[int]) -> list[ClanMember]:
        return await ClanMember.filter(clan__clan_id__in=clan_ids).prefetch_related("member", "clan")

    async def list_clan_members_for_guild(self, guild_id: int) -> list[ClanMember]:
        return await ClanMember.filter(clan__guild__guild_id=guild_id).prefetch_related("member", "clan", "clan__guild")

    async def find_clan_member_by_platform(self, member_id: int, platform: int, clan_ids: list[int]) -> ClanMember | None:
        field_map = {
            constants.PLATFORM_PSN: "member__psn_id",
            constants.PLATFORM_XBOX: "member__xbox_id",
            constants.PLATFORM_BLIZZARD: "member__blizzard_id",
            constants.PLATFORM_STEAM: "member__steam_id",
            constants.PLATFORM_STADIA: "member__stadia_id",
        }
        field = field_map.get(platform)
        if not field:
            return None
        return await ClanMember.filter(clan_id__in=clan_ids, **{field: member_id}).prefetch_related("member")

    async def get_clans_for_guild(self, guild_id: int) -> list[Clan]:
        return await Clan.filter(guild__guild_id=guild_id).prefetch_related("guild")

    async def active_clan_members(self, clan_db: Clan, **kwargs) -> list[ClanMember]:
        if not kwargs:
            kwargs = {"hours": 1}
        cutoff = timezone.now() - timedelta(**kwargs)
        return await ClanMember.filter(last_active__gt=cutoff, clan=clan_db).prefetch_related("member")

    async def inactive_clan_members(self, clan_db: Clan, **kwargs) -> list[ClanMember]:
        if not kwargs:
            kwargs = {"days": 30}
        cutoff = timezone.now() - timedelta(**kwargs)
        return await ClanMember.filter(last_active__lt=cutoff, clan=clan_db).prefetch_related("member")

    async def upsert_game(self, game_data) -> Game | None:
        defaults = vars(game_data)
        game_obj, created = await Game.get_or_create(instance_id=game_data.instance_id, defaults=defaults)
        if created:
            log.info(f"Game {game_data.instance_id} created")
            return game_obj
        return None

    async def link_clan_to_game(self, game_obj: Game, raw_game, clan_id: int):
        _, created = await ClanGame.get_or_create(clan_id=clan_id, game=game_obj)
        if created:
            tasks = [
                self.insert_player_into_game(player, game_obj, clan_id)
                for player in raw_game.clan_players
            ]
            await asyncio.gather(*tasks)

    async def insert_player_into_game(self, player, game_obj: Game, clan_id: int, player_db: Member | None = None):
        if not player_db:
            clan_member = await self.find_clan_member_by_platform(player.membership_id, player.membership_type, [clan_id])
            player_db = clan_member.member if clan_member else None
            if not player_db:
                raise ValueError("Player not found in clan")

        try:
            await GameMember.create(
                member=player_db,
                game=game_obj,
                completed=bool(player.completed),
                time_played=int(player.time_played),
            )
        except IntegrityError:
            existing = await GameMember.get(game=game_obj, member=player_db)
            existing.time_played += player.time_played
            if not existing.completed or existing.completed != player.completed:
                existing.completed = bool(player.completed)
            await existing.save()

        log.info(f"Player {member_hash(player)} added to game id {game_obj.instance_id}")

    async def shutdown(self):
        await Tortoise.close_connections()

# Process JSON-LD data using a resolution chain approach

from jsonlddb import JsonLDDatabase

def apply_resolution_steps(step_definitions, database, tracking_dict):
    for step in step_definitions:
        frame_key = step['frame']
        for item in database[frame_key]:
            # Check if this item has already been processed
            current_id = step['@id']
            item_id = item['@id']

            if not (tracking_dict.get(current_id, {}).get(item_id, False)):
                # Apply the resolver function and insert results
                new_data = list(step['function'](item))
                database.insert(new_data)

                # Update tracking dictionary
                if tracking_dict.get(current_id) is None:
                    tracking_dict[current_id] = {}
                tracking_dict[current_id][item_id] = True

    return database, tracking_dict

def complete_jsonld_resolution(step_definitions, input_data):
    # Initialize database and load initial data
    db = JsonLDDatabase()
    db.insert(input_data)

    # Track resolved items to detect convergence
    processed_items = {}
    previous_state = None

    # Continue until no new items are resolved (convergence)
    while str(processed_items) != previous_state:
        previous_state = str(processed_items)
        db, processed_items = apply_resolution_steps(step_definitions, db, processed_items)

    return db

