from pathlib import Path
import datetime
import torch
import git
from inspect import signature
import os
import yaml

class TensorBoardLogger:
    def __init__(self, config):
        self.is_disabled = config.no_logging
        if config.no_logging:
            print("Logging is disabled")
            return

        timestamp = str(datetime.datetime.now().strftime('%Y-%m-%d_%H:%M:%S'))
        architecture_name = config.model_type
        self.log_dir = Path(__file__).parent.absolute().parent / 'logs' / architecture_name / timestamp

        if not self.log_dir.exists():
            self.log_dir.mkdir(parents=True)

        self.setup_metadata(config)
        self.writer = SummaryWriter(str(self.log_dir))

        # Tracking metrics and files
        self.global_best_metric = None
        self.best_ckpt_loss = float('inf')
        self.best_ckpt_file = None
        self.current_model_file = None
        self.interim_checkpoint = None

    def _skip_if_disabled(func):
        def wrapper(*args, **kwargs):
            self_instance = args[0]
            if self_instance.is_disabled:
                return
            return func(*args, **kwargs)
        return wrapper

    @_skip_if_disabled
    def setup_metadata(self, job_config):
        repo = git.Repo(search_parent_directories=True)
        config_dict = job_config.to_dict()
        self.meta_file = self.log_dir / "metadata.yaml"
        self.metadata = {
            **config_dict,
            'git_commit': repo.head.object.hexsha,
            'best_save_metric': None,
            'best_saved_model_file': None,
            'log_directory': str(self.log_dir),
            'After analysis summary': '*** Fill out this field after training and analyzing ***',
        }
        with open(self.meta_file, 'w') as f:
            yaml.safe_dump(self.metadata, f)

    @_skip_if_disabled
    def record_training_loss(self, loss_value):
        if not hasattr(self, 'train_step'):
            self.train_step = 0
        self.writer.add_scalar("Training loss", loss_value, self.train_step)
        self.train_step += 1

    @_skip_if_disabled
    def record_validation_loss(self, loss_value):
        if not hasattr(self, 'val_step'):
            self.val_step = 0
        self.writer.add_scalar("Validation loss", loss_value, self.val_step)
        self.val_step += 1

    @_skip_if_disabled
    def record_sampling_evaluation_loss(self, loss_value):
        if not hasattr(self, 'eval_step'):
            self.eval_step = 0
        self.writer.add_scalar("Evaluation loss", loss_value, self.eval_step)
        self.eval_step += 1

    @_skip_if_disabled
    def record_rollout_mse(self, mse_value):
        if not hasattr(self, 'mse_step'):
            self.mse_step = 0
        self.writer.add_scalar("Rollout MSE", mse_value, self.mse_step)
        self.mse_step += 1

    @_skip_if_disabled
    def log_model_graph(self, model, example_batch):
        param_names = list(signature(model.forward).parameters.keys())
        filtered_params = [p for p in param_names if p not in ['args', 'kwargs']]
        inputs = [example_batch[p] for p in filtered_params]
        self.writer.add_graph(model, inputs)

    @_skip_if_disabled
    def _internal_save(self, epoch_num, save_path, model_obj, optimizer_obj, extra_info):
        torch.save(
            {
                'epoch': epoch_num,
                'model_state_dict': model_obj.state_dict(),
                'optimizer_state_dict': optimizer_obj.state_dict(),
                **extra_info,
            },
            save_path,
        )

    @_skip_if_disabled
    def save_current_model(self, epoch_num, progress_pct, model_obj, optimizer_obj, extra_data):
        ckpt_path = self.log_dir / f"model_ckpt_ep_{epoch_num}_pct_{progress_pct}.pth"
        self._internal_save(epoch_num, ckpt_path, model_obj, optimizer_obj, extra_data)

        if self.interim_checkpoint is not None:
            if (
                str(ckpt_path) != str(self.interim_checkpoint)
                and os.path.exists(self.interim_checkpoint)
            ):
                os.remove(self.interim_checkpoint)
        self.interim_checkpoint = ckpt_path

    @_skip_if_disabled
    def save_checkpoint(self, epoch_num, model_obj, optimizer_obj, extra_data, current_metric):
        """
        Saves model checkpoints with the following strategy:
        - Always saves the most recent model
        - Every 10 epochs, creates a new checkpoint group
        - Keeps best model per checkpoint group based on metric value
        - Updates global metadata with best overall model
        """
        model_path = self.log_dir / f"model_epoch_{epoch_num}.pth"

        # Handle conflicting metric info
        if 'save_metric' in extra_data and extra_data['save_metric'] != current_metric:
            print(
                f"Logger received conflicting save metric values: "
                f"{extra_data['save_metric']} vs {current_metric}. "
                f"Choosing the latter, but former will be saved "
                f"with key \"ignored_save_metric\"."
            )
            extra_data["ignored_save_metric"] = extra_data['save_metric']
        extra_data['save_metric'] = current_metric

        self._internal_save(epoch_num, model_path, model_obj, optimizer_obj, extra_data)

        # Determine if this is a checkpoint epoch (every 10 epochs)
        is_checkpoint_epoch = (epoch_num % 10 == 0)

        # Handle cleanup of previous models
        if is_checkpoint_epoch:
            print(f"Starting new checkpoint group at: {model_path}")
        elif current_metric < self.best_ckpt_loss:
            print(f"Updated model checkpoint will be saved to: {model_path}")
            if self.best_ckpt_file and os.path.exists(self.best_ckpt_file):
                os.remove(self.best_ckpt_file)

        # Remove old model file if it's different from the best checkpoint
        if (
            self.best_ckpt_file is not None
            and self.current_model_file is not None
            and self.best_ckpt_file.resolve() != self.current_model_file.resolve()
        ):
            if os.path.exists(self.current_model_file):
                os.remove(self.current_model_file)

        # Update tracking variables
        self.current_model_file = model_path

        if is_checkpoint_epoch or current_metric < self.best_ckpt_loss:
            self.best_ckpt_loss = current_metric
            self.best_ckpt_file = model_path
            self.current_model_file = self.best_ckpt_file

        # Global best metric tracking and metadata update
        if self.global_best_metric is None or current_metric < self.global_best_metric:
            print(f"Updating metadata with new best model: {self.meta_file}")
            self.global_best_metric = current_metric
            self.metadata['best_save_metric'] = str(current_metric)
            self.metadata['best_saved_model_file'] = str(self.best_ckpt_file)
            with open(self.meta_file, 'w') as f:
                yaml.safe_dump(self.metadata, f)

