logger = get_job_logger(__name__)

def user_failure_key(user_id):
    return "aggregated_failures:{}".format(user_id)

def generate_failure_comment(failure_record):
    scheduled_fail_count = failure_record.get("schedule_failures")
    threshold_ratio = 0.75
    if scheduled_fail_count > settings.MAX_FAILURE_REPORTS_PER_QUERY * threshold_ratio:
        return """NOTICE: This query has failed a total of {schedule_failures} times.
        Reporting may stop when the query exceeds {max_failure_reports} overall failures.""".format(
            schedule_failures=scheduled_fail_count,
            max_failure_reports=settings.MAX_FAILURE_REPORTS_PER_QUERY,
        )

def broadcast_aggregated_errors():
    for key in redis_connection.scan_iter(user_failure_key("*")):
        extracted_user_id = re.search(r"\d+", key).group()
        process_and_send_failure_report(extracted_user_id)

def process_and_send_failure_report(user_identifier):
    user = models.User.get_by_id(user_identifier)
    raw_error_list = redis_connection.lrange(user_failure_key(user_identifier), 0, -1)

    if raw_error_list:
        parsed_errors = [json_loads(err) for err in raw_error_list]
        parsed_errors.reverse()

        # Count occurrences of unique error types
        error_signature_pairs = [(err.get("id"), err.get("message")) for err in parsed_errors]
        occurrence_counts = Counter(error_signature_pairs)

        # Keep only latest instance of each unique error type
        latest_error_by_type = {
            (err.get("id"), err.get("message")): err 
            for err in parsed_errors
        }

        context = {
            "failures": [
                {
                    "id": latest_err.get("id"),
                    "name": latest_err.get("name"),
                    "failed_at": latest_err.get("failed_at"),
                    "failure_reason": latest_err.get("message"),
                    "failure_count": occurrence_counts[signature],
                    "comment": generate_failure_comment(latest_err),
                }
                for signature, latest_err in latest_error_by_type.items()
            ],
            "base_url": base_url(user.org),
        }

        subject = "Insights (by Unicommerce) failed to execute {} of your scheduled queries".format(
            len(latest_error_by_type)
        )

        html_content, text_content = [
            render_template("emails/failures.{}".format(ext), context)
            for ext in ["html", "txt"]
        ]

        send_mail.delay([user.email], subject, html_content, text_content)

    redis_connection.delete(user_failure_key(user_identifier))

def record_scheduled_query_failure(error_message, target_query):
    email_enabled = target_query.org.get_setting("send_email_on_failed_scheduled_queries")
    threshold_reached = target_query.schedule_failures >= settings.MAX_FAILURE_REPORTS_PER_QUERY

    if email_enabled and not target_query.user.is_disabled and not threshold_reached:
        formatted_timestamp = datetime.datetime.utcnow().strftime("%B %d, %Y %I:%M%p UTC")
        redis_connection.lpush(
            user_failure_key(target_query.user.id),
            json_dumps({
                "id": target_query.id,
                "name": target_query.name,
                "message": error_message,
                "schedule_failures": target_query.schedule_failures,
                "failed_at": formatted_timestamp,
            }),
        )

def log_and_update_failure(query_obj, error_details):
    logger.debug(error_details)
    query_obj.schedule_failures += 1
    query_obj.skip_updated_at = True
    models.db.session.add(query_obj)
    models.db.session.commit()
    record_scheduled_query_failure(error_details, query_obj)

import os
from edk2toollib.uefi.edk2.parsers.base_parser import HashFileParser
from edk2toollib.uefi.edk2.parsers.guid_parser import GuidParser

class LibraryClassDeclarationEntry():
    def __init__(self, pkg_name: str, line_content: str = None):
        """Initialize a library class declaration entry"""
        self.header_path = ""
        self.class_name = ""
        self.package = pkg_name
        if line_content is not None:
            self._process_line(line_content)

    def _process_line(self, line_content: str) -> None:
        """Extract library class name and header path from raw text line.

        Expected format: <library_class_name> | <relative_header_path>
        """
        parts = line_content.partition("|")
        self.class_name = parts[0].strip()
        self.header_path = parts[2].strip()

class GuidedDeclarationEntry():
    """Base class for GUID-related declarations (protocols, PPIs, generic GUIDs)."""
    PROTOCOL_TYPE = 1
    PPI_TYPE = 2
    GUID_TYPE = 3

    def __init__(self, pkg_name: str, line_content: str = None):
        """Initialize a protocol/PPI/GUID declaration entry"""
        self.decl_name = ""
        self.guid_str = ""
        self.guid_value = None
        self.package = pkg_name
        if line_content is not None:
            self._parse_line(line_content)

    def _parse_line(self, line_content: str) -> None:
        """Parse name and GUID from declaration line."""
        segments = line_content.partition("=")
        self.decl_name = segments[0].strip()
        self.guid_str = segments[2].strip()
        self.guid_value = GuidParser.uuid_from_guidstring(self.guid_str)
        if self.guid_value is None:
            raise ValueError(f"Invalid GUID string: {self.guid_str}")

class ProtocolDeclarationEntry(GuidedDeclarationEntry):
    def __init__(self, pkg_name: str, line_content: str = None):
        """Initialize a protocol declaration entry"""
        super().__init__(pkg_name, line_content)
        self.decl_type = GuidedDeclarationEntry.PROTOCOL_TYPE

class PpiDeclarationEntry(GuidedDeclarationEntry):
    def __init__(self, pkg_name: str, line_content: str = None):
        """Initialize a PPI declaration entry"""
        super().__init__(pkg_name, line_content)
        self.decl_type = GuidedDeclarationEntry.PPI_TYPE

class GuidDeclarationEntry(GuidedDeclarationEntry):
    def __init__(self, pkg_name: str, line_content: str = None):
        """Initialize a generic GUID declaration entry"""
        super().__init__(pkg_name, line_content)
        self.decl_type = GuidedDeclarationEntry.GUID_TYPE

class PcdDeclarationEntry():
    def __init__(self, pkg_name: str, line_content: str = None):
        """Create a PCD declaration entry for one PCD"""
        self.token_space = ""
        self.pcd_name = ""
        self.default_val = ""
        self.pcd_type = ""
        self.unique_id = ""
        self.package = pkg_name
        if line_content is not None:
            self._process_pcd_line(line_content)

    def _process_pcd_line(self, line_content: str) -> None:
        """Parse PCD declaration line into components."""
        token_part = line_content.partition(".")
        self.token_space = token_part[0].strip()
        rest_parts = token_part[2].split("|")
        if len(rest_parts) != 4:
            raise Exception("Incorrect number of PCD fields")
        self.pcd_name = rest_parts[0].strip()
        self.default_val = rest_parts[1].strip()
        self.pcd_type = rest_parts[2].strip()
        self.unique_id = rest_parts[3].strip()

class DecParser(HashFileParser):
    """Parser for EDK2 DEC files"""
    def __init__(self):
        HashFileParser.__init__(self, 'DecParser')
        self.raw_lines = []
        self.is_parsed = False
        self.metadata_dict = {}
        self.library_classes = []
        self.ppis = []
        self.protocols = []
        self.guids = []
        self.pcds = []
        self.include_dirs = []
        self.file_path = ""
        self.package_name = None

    def _do_parse(self) -> None:
        """Internal parsing logic to process DEC file content."""
        in_defines = False
        in_lib_classes = False
        in_protocols = False
        in_guids = False
        in_ppis = False
        in_pcds = False
        in_includes = False

        for raw_line in self.raw_lines:
            clean_line = self.StripComment(raw_line)
            if clean_line is None or len(clean_line.strip()) == 0:
                continue

            # Handle section transitions
            if in_defines:
                if clean_line.strip().startswith('['):
                    in_defines = False
                else:
                    if clean_line.count('=') == 1:
                        key, value = clean_line.split('=', 1)
                        self.metadata_dict[key.strip()] = value.strip()
                        if self.package_name is None and key.strip() == "PACKAGE_NAME":
                            self.package_name = self.metadata_dict["PACKAGE_NAME"]
                        continue

            elif in_lib_classes:
                if clean_line.strip().startswith('['):
                    in_lib_classes = False
                else:
                    lib_entry = LibraryClassDeclarationEntry(self.package_name, clean_line)
                    self.library_classes.append(lib_entry)
                    continue

            elif in_protocols:
                if clean_line.strip().startswith('['):
                    in_protocols = False
                else:
                    proto_entry = ProtocolDeclarationEntry(self.package_name, clean_line)
                    self.protocols.append(proto_entry)
                    continue

            elif in_guids:
                if clean_line.strip().startswith('['):
                    in_guids = False
                else:
                    guid_entry = GuidDeclarationEntry(self.package_name, clean_line)
                    self.guids.append(guid_entry)
                    continue

            elif in_pcds:
                if clean_line.strip().startswith('['):
                    in_pcds = False
                else:
                    pcd_entry = PcdDeclarationEntry(self.package_name, clean_line)
                    self.pcds.append(pcd_entry)
                    continue

            elif in_includes:
                if clean_line.strip().startswith('['):
                    in_includes = False
                else:
                    self.include_dirs.append(clean_line.strip())
                    continue

            elif in_ppis:
                if clean_line.strip().startswith('['):
                    in_ppis = False
                else:
                    ppi_entry = PpiDeclarationEntry(self.package_name, clean_line)
                    self.ppis.append(ppi_entry)
                    continue

            # Detect new sections
            line_lower = clean_line.strip().lower()
            if line_lower.startswith('[defines'):
                in_defines = True
            elif line_lower.startswith('[libraryclasses'):
                in_lib_classes = True
            elif line_lower.startswith('[protocols'):
                in_protocols = True
            elif line_lower.startswith('[guids'):
                in_guids = True
            elif line_lower.startswith('[ppis'):
                in_ppis = True
            elif line_lower.startswith('[pcd'):
                in_pcds = True
            elif line_lower.startswith('[includes'):
                in_includes = True

        self.is_parsed = True

    def parse_stream(self, stream) -> None:
        """Parse DEC data from a stream object.

        Args:
            stream: File-like object containing DEC file content
        """
        self.file_path = "None:stream_provided"
        self.raw_lines = stream.readlines()
        self._do_parse()

    def parse_file(self, file_path: str) -> None:
        """Parse a DEC file from disk.

        Args:
            file_path: Path to the DEC file (absolute or relative)
        """
        self.Logger.debug(f"Parsing file: {file_path}")
        if not os.path.isabs(file_path):
            resolved_path = self.FindPath(file_path)
        else:
            resolved_path = file_path

        self.file_path = resolved_path
        with open(resolved_path, "r") as dec_file:
            self.raw_lines = dec_file.readlines()
        self._do_parse()

import pytest
from brancher.tree import Tree
from brancher.constants import (
    UNITS_IN_SECONDS,
    TREE_SPECIES,
)
from brancher.node import RootNode, TrunkNode

@pytest.fixture
def base_tree_node():
    return RootNode(species=TREE_SPECIES["Loblolly Pine"])

@pytest.fixture
def main_trunk_segment(base_tree_node):
    return TrunkNode(parent=base_tree_node, species=base_tree_node.species)

def test_root_has_no_parent_object(base_tree_node):
    assert base_tree_node.parent is None

def test_root_creates_zero_length_trunk(base_tree_node):
    assert isinstance(base_tree_node.trunk, TrunkNode)
    assert base_tree_node.trunk.length == 0

def test_trunk_starts_empty_of_offshoots(main_trunk_segment):
    assert len(main_trunk_segment.children) == 0

@pytest.mark.parametrize(
    "duration,measure",
    [
        (1, "s"),
        (2, "m"),
        (3, "h"),
        (4, "d"),
        (5, "w"),
        (6, "m"),
        (7, "y"),
    ],
)
def test_trunk_extends_properly(main_trunk_segment, duration, measure):
    original_size = main_trunk_segment.length
    main_trunk_segment.grow(duration, measure)
    new_size = main_trunk_segment.length

    expected_growth = duration * UNITS_IN_SECONDS[measure] * main_trunk_segment.growth_rate
    assert new_size == original_size + expected_growth

# Helper class to convert dictionary into object with attributes
class ObjectWrapper:
    @staticmethod
    def from_mapping(mapping):
        instance = ObjectWrapper()
        instance.__dict__.update(mapping)
        return instance

def extract_with_fallback(obj, attr_name, fallback_value):
    if hasattr(obj, attr_name):
        value = getattr(obj, attr_name)
        if value is not None:
            try:
                return type(fallback_value)(value)
            except (TypeError, ValueError):
                return value
    return fallback_value

def compute_pagination_params(payload):
    # Handle page-based pagination
    if hasattr(payload, 'page') and (hasattr(payload, 'page_size') or hasattr(payload, 'pageSize')):
        current_page = int(getattr(payload, 'page') or 1)
        items_per_page = int(getattr(payload, 'page_size') or getattr(payload, 'pageSize') or 10)
        start_index = max(current_page - 1, 0) * items_per_page
        return start_index, items_per_page

    # Handle offset/limit-based pagination
    if hasattr(payload, 'offset') and hasattr(payload, 'limit'):
        start_offset = int(getattr(payload, 'offset') or 0)
        max_results = int(getattr(payload, 'limit') or 10)
        return start_offset, max_results

    # Fallback: only limit specified
    elif hasattr(payload, 'limit'):
        max_results = int(getattr(payload, 'limit') or 10)
        return 0, max_results

    # Default case
    return 0, 10

import logging
