__all__ = [
    'ground',
    'ground_nodelink',
]

logger = logging.getLogger(__name__)

# Constants for skipping or ignoring certain namespaces
SKIP_NAMESPACES = {'ncbigene', 'pubchem.compound', 'chembl.compound'}
NO_NAME_REQUIRED = {'fplx', 'eccode', 'dbsnp', 'smiles', 'inchi', 'inchikey'}

# Precomputed remappings
_NAME_REMAPPING = get_remapping()
_ID_REMAPPING = {}

def _get_name_based_replacement(prefix: str, name: str) -> Tuple[Optional[str], Optional[str], Optional[str]]:
    """Get replacement data based on namespace and name."""
    return _NAME_REMAPPING.get((prefix, name), (None, None, None))

def _get_identifier_based_replacement(prefix: str, identifier: str) -> Tuple[Optional[str], Optional[str], Optional[str]]:
    """Get replacement data based on namespace and identifier."""
    return _ID_REMAPPING.get((prefix, identifier), (None, None, None))

def ground(graph: BELGraph, remove_ungrounded: bool = True) -> BELGraph:
    """Convert BEL graph to grounded form by resolving all entities."""
    # Convert to nodelink format for processing
    node_link_data = to_nodelink(graph)

    # Apply grounding to nodelink structure
    ground_nodelink(node_link_data)

    # Reconstruct BEL graph from processed nodelink data
    graph = from_nodelink(node_link_data)

    # Clean up unused metadata
    _cleanup_unused_metadata(graph)

    if remove_ungrounded:
        # Identify nodes that couldn't be grounded (excluding special namespaces)
        ungrounded_nodes = {
            node
            for node in get_ungrounded_nodes(graph)
            if not isinstance(node, BaseConcept) or node.namespace not in NO_NAME_REQUIRED
        }

        # Remove ungrounded nodes
        graph.remove_nodes_from(ungrounded_nodes)

        # Reset and rebuild namespace/annotation patterns
        graph.namespace_url.clear()
        graph.namespace_pattern.clear()
        graph.namespace_pattern.update({
            ns: '.*'
            for ns in get_namespaces(graph)
        })

        graph.annotation_url.clear()
        graph.annotation_pattern.clear()
        graph.annotation_list.clear()
        graph.annotation_pattern.update({
            annotation: '.*'
            for annotation in get_annotations(graph)
        })

    return graph

def _cleanup_unused_metadata(graph) -> None:
    """Remove annotation metadata that isn't used in the current graph."""
    active_annotations = get_annotations(graph)

    # Remove unused pattern annotations
    for annotation in set(graph.annotation_pattern) - active_annotations:
        logger.warning('deleting unused annotation pattern: %s', annotation)
        del graph.annotation_pattern[annotation]

    # Remove unused URL annotations
    for annotation in set(graph.annotation_url) - active_annotations:
        logger.warning('deleting unused annotation URL: %s', annotation)
        del graph.annotation_url[annotation]

    # Remove unused list annotations
    for annotation in set(graph.annotation_list) - active_annotations:
        logger.warning('deleting unused annotation list: %s', annotation)
        del graph.annotation_list[annotation]

def ground_nodelink(node_link_data: Dict[str, Any]) -> None:
    """Ground entities in a nodelink data structure."""
    graph_name = node_link_data.get('graph', {}).get('name', 'graph')

    # Process edges first
    for edge_data in tqdm(node_link_data['links'], desc=f'grounding edges in {graph_name}'):
        _process_edge_subject(edge_data.get(SUBJECT))
        _process_edge_object(edge_data.get(OBJECT))
        if ANNOTATIONS in edge_data:
            _process_annotation_dict(edge_data)

    # Then process nodes
    for node_data in tqdm(node_link_data['nodes'], desc=f'grounding nodes in {graph_name}'):
        _process_graph_node(node_data)

# Mapping for BEL annotation prefixes to standard namespaces
BEL_ANNOTATION_PREFIX_MAP = {
    'MeSHDisease': 'mesh',
    'MeShAnatomy': 'mesh',
    'Species': 'ncbitaxon',
    'Disease': 'doid',
    'Cell': 'cl',
}

# Track unhandled annotations
_UNHANDLED_ANNOTATION_TYPES = set()

def _process_findable_annotations(annotation_list: List, pending_list: List, prefix: str, names: Dict[str, bool]):
    """Process annotations that can be looked up via name-to-ID mapping."""
    name_to_id = get_name_id_mapping(prefix)
    for name, polarity in names.items():
        identifier = name_to_id.get(name)
        if identifier:
            annotation_list.append((Entity(namespace=prefix, identifier=identifier, name=name), polarity))
        else:
            pending_list.append((prefix, name, polarity))

def _process_annotation_dict(data: Dict[str, Any], add_free_annotations: bool = False):
    """Process annotation dictionaries in edge data."""
    resolved_annotations = []
    pending_annotations = []

    for prefix, names in data[ANNOTATIONS].items():
        if prefix == 'CellLine':
            efo_name_to_id = get_name_id_mapping('efo')
            for name, polarity in names.items():
                prefix, identifier = 'efo', efo_name_to_id.get(name)
                if identifier is not None:
                    resolved_annotations.append((Entity(namespace=prefix, identifier=identifier, name=name), polarity))
                else:
                    pending_annotations.append((prefix, None, polarity))
        elif prefix in BEL_ANNOTATION_PREFIX_MAP:
            normalized_prefix = BEL_ANNOTATION_PREFIX_MAP[prefix]
            _process_findable_annotations(resolved_annotations, pending_annotations, normalized_prefix, names)
        elif normalize_prefix(prefix):
            normalized_prefix = normalize_prefix(prefix)
            _process_findable_annotations(resolved_annotations, pending_annotations, normalized_prefix, names)
        else:
            if prefix not in _UNHANDLED_ANNOTATION_TYPES:
                logger.warning('unhandled annotation: %s', prefix)
                _UNHANDLED_ANNOTATION_TYPES.add(prefix)

            if isinstance(names, dict):
                for name, polarity in names.items():
                    pending_annotations.append((prefix, name, polarity))
            else:
                pending_annotations.append((prefix, names, True))

    # Update annotation structure with resolved annotations
    data[ANNOTATIONS] = defaultdict(dict)
    for entity, polarity in resolved_annotations:
        data[ANNOTATIONS][entity.namespace][entity.identifier] = polarity

    if add_free_annotations:
        data['free_annotations'] = defaultdict(dict)
        for prefix, name, polarity in pending_annotations:
            data['free_annotations'][prefix][name] = polarity

def _process_edge_subject(side_data) -> bool:
    """Process subject side of an edge."""
    if side_data is None:
        return True
    modifier = side_data.get(MODIFIER)
    effect = side_data.get(EFFECT)

    if modifier == ACTIVITY and effect is not None:
        _process_concept(concept=effect)
    elif modifier == TRANSLOCATION and effect is not None:
        _process_concept(concept=effect[FROM_LOC])
        _process_concept(concept=effect[TO_LOC])

    location = side_data.get(LOCATION)
    if location is not None:
        _process_concept(concept=location)

    return True

def _process_edge_object(side_data) -> bool:
    """Process object side of an edge."""
    if side_data is None:
        return True
    modifier = side_data.get(MODIFIER)
    effect = side_data.get(EFFECT)

    if modifier == ACTIVITY and effect is not None:
        _process_concept(concept=effect)
    elif modifier == TRANSLOCATION and effect is not None:
        _process_concept(concept=effect[FROM_LOC])
        _process_concept(concept=effect[TO_LOC])

    location = side_data.get(LOCATION)
    if location is not None:
        _process_concept(concept=location)

    return True

def _process_graph_node(node: Dict[str, Any]) -> bool:
    """Process a node in the graph, updating its grounding information."""
    success = True

    if CONCEPT in node:
        success = success and _process_concept_entity(concept=node[CONCEPT], node=node)

    if VARIANTS in node:
        success = success and _process_variant_list(node[VARIANTS])

    if MEMBERS in node:
        success = success and _process_member_list(node[MEMBERS])

    if REACTANTS in node:
        success = success and _process_member_list(node[REACTANTS])

    if PRODUCTS in node:
        success = success and _process_member_list(node[PRODUCTS])

    if FUSION in node:
        success = success and _process_fusion_structure(node[FUSION])

    return success

def _process_concept_entity(*, concept: Dict[str, Any], node: Optional[Dict] = None) -> bool:
    """Process a concept entity within a node."""
    namespace = concept[NAMESPACE]

    # Skip text-based or placeholder namespaces
    if namespace.lower() in {'text', 'fixme'}:
        return False

    # Normalize namespace
    normalized_prefix = normalize_prefix(namespace)
    if normalized_prefix is None:
        logger.warning('could not normalize namespace %s in concept %s', namespace, concept)
        return False

    concept[NAMESPACE] = normalized_prefix

    # Handle identifier vs name cases
    identifier = concept.get(IDENTIFIER)
    name = concept.get(NAME)

    if identifier:
        map_success = _handle_identifier_case(concept=concept, prefix=normalized_prefix, identifier=identifier)
    else:
        map_success = _handle_name_case(concept=concept, prefix=normalized_prefix, name=name, node=node)

    if not map_success:
        return False

    # Apply identifier-based remapping
    _remap_by_identifier(concept)

    return True

def _remap_by_identifier(concept: Dict[str, Any]) -> bool:
    """Apply identifier-based remapping to concept."""
    identifier = concept.get(IDENTIFIER)
    if identifier is None:
        return False

    namespace = concept[NAMESPACE]
    logger.debug('attempting to remap %s:%s', namespace, identifier)

    remapped_prefix, remapped_identifier, remapped_name = _get_identifier_based_replacement(namespace, identifier)
    logger.debug('remapping result %s:%s ! %s', remapped_prefix, remapped_identifier, remapped_name)

    if remapped_prefix:
        concept[NAMESPACE] = remapped_prefix
        concept[IDENTIFIER] = remapped_identifier
        concept[NAME] = remapped_name
        return True

    return False

def _handle_identifier_case(*, concept: Dict[str, Any], prefix: str, identifier: str) -> bool:
    """Handle cases where identifier is provided but name may need lookup."""
    if prefix in SKIP_NAMESPACES:
        return False

    if prefix in NO_NAME_REQUIRED:
        concept[NAME] = concept[IDENTIFIER]
        return True

    if prefix == 'uniprot':
        concept[NAME] = get_mnemonic(identifier)
        return True

    try:
        id_name_mapping = get_id_name_mapping(prefix)
    except (NoOboFoundry, MissingOboBuild):
        return False

    if id_name_mapping is None:
        logger.warning('could not get names for prefix %s', prefix)
        return False

    name = id_name_mapping.get(identifier)
    if name is None:
        logger.warning('could not get name for %s:%s', prefix, identifier)
        return False

    concept[NAME] = name
    return True

def _handle_name_case(*, concept: Dict[str, Any], prefix: str, name: str, node: Optional[Dict] = None) -> bool:
    """Handle cases where name is provided but identifier needs lookup."""
    remapped_prefix, remapped_identifier, remapped_name = _get_name_based_replacement(prefix, name)
    if remapped_prefix:
        concept[NAMESPACE] = remapped_prefix
        concept[IDENTIFIER] = remapped_identifier
        concept[NAME] = remapped_name
        return True

    if prefix in SKIP_NAMESPACES:
        return False

    concept[NAMESPACE] = prefix

    if prefix in NO_NAME_REQUIRED:
        concept[IDENTIFIER] = name
        return True

    # Handle BEL-specific mappings
    if prefix == 'bel' and node is not None and KIND in node:
        kind = node[KIND]
        if kind == PMOD and name in pmod_mappings:
            _mapped = pmod_mappings[name]['xrefs'][0]
        elif kind == GMOD and name in gmod_mappings:
            _mapped = gmod_mappings[name]['xrefs'][0]
        else:
            raise ValueError(f'invalid kind: {kind}')
        concept[NAMESPACE] = _mapped[NAMESPACE]
        concept[IDENTIFIER] = _mapped[IDENTIFIER]
        concept[NAME] = _mapped[NAME]
        return True
    elif prefix == 'bel' and name in activity_mapping:
        _mapped = activity_mapping[name]
        concept[NAMESPACE] = _mapped[NAMESPACE]
        concept[IDENTIFIER] = _mapped[IDENTIFIER]
        concept[NAME] = _mapped[NAME]
        return True
    elif prefix == 'bel' and name in compartment_mapping:
        _mapped = compartment_mapping[name]
        concept[NAMESPACE] = _mapped[NAMESPACE]
        concept[IDENTIFIER] = _mapped[IDENTIFIER]
        concept[NAME] = _mapped[NAME]
        return True
    elif prefix == 'bel':
        logger.warning('could not figure out how to map bel ! %s', name)
        return False

    # Handle UniProt name cases
    if prefix == 'uniprot':
        identifier = get_id_from_mnemonic(name)
        if identifier is not None:
            concept[IDENTIFIER] = identifier
            return True

        mnemonic = get_mnemonic(name, web_fallback=True)
        if mnemonic is not None:
            concept[IDENTIFIER] = name
            concept[NAME] = mnemonic
            return True

        logger.warning('could not interpret uniprot name: %s', name)
        return False

    # General case: look up identifier by name
    try:
        name_id_mapping = get_name_id_mapping(prefix)
    except (NoOboFoundry, MissingOboBuild) as e:
        logger.warning('could not get namespace %s', prefix, e)
        return False

    if name_id_mapping is None:
        logger.warning('unhandled namespace in %s ! %s', prefix, name)
        return False

    identifier = name_id_mapping.get(name)
    if identifier is None:
        logger.warning('could not find name %s in namespace %s', name, prefix)
        return False

    concept[IDENTIFIER] = identifier
    return True

def _process_fusion_structure(fusion: Dict[str, Any]) -> bool:
    """Process fusion structure components."""
    success_3p = _process_graph_node(fusion[PARTNER_3P])
    success_5p = _process_graph_node(fusion[PARTNER_5P])
    return success_3p and success_5p

def _process_variant_list(variants: List[Dict[str, Any]]) -> bool:
    """Process variant list."""
    success = True
    for variant in variants:
        success = success and _process_graph_node(variant)
    return success

def _process_member_list(members: List[Dict[str, Any]]) -> bool:
    """Process member list (for complexes, etc.)."""
    success = True
    for member in members:
        success = success and _process_graph_node(member)
    return success

