import tokenizers
from tokenizers import Tokenizer, AddedToken
from tokenizers.models import WordLevel
from tokenizers.normalizers import unicode_normalizer_from_str, Lowercase, Sequence
from typing import Optional, Union


class CustomWordLevelTokenizer:
    """CustomWordLevelTokenizer
    A word-level tokenizer implementation using WordLevel model
    """

    def __init__(
        self,
        vocabulary_path: Optional[str] = None,
        unknown_token: Union[str, AddedToken] = "<unk>",
        start_token: Union[str, AddedToken] = "<s>",
        end_token: Union[str, AddedToken] = "</s>",
        padding_token: Union[str, AddedToken] = "<pad>",
        masking_token: Union[str, AddedToken] = "<mask>",
        convert_to_lowercase: bool = False,
        normalize_unicode: Optional[str] = None,
    ):
        # Initialize tokenizer based on whether vocabulary file is provided
        if vocabulary_path is not None:
            self._tokenizer = Tokenizer(WordLevel(vocabulary_path))
        else:
            self._tokenizer = Tokenizer(WordLevel())

        # Register special tokens if they exist in vocabulary
        special_tokens_list = [
            unknown_token, start_token, end_token, padding_token, masking_token
        ]
        for token in special_tokens_list:
            token_str = str(token)
            if self._tokenizer.token_to_id(token_str) is not None:
                self._tokenizer.add_special_tokens([token_str])

        # Configure text normalization pipeline
        normalization_steps = []
        if normalize_unicode:
            normalization_steps.append(unicode_normalizer_from_str(normalize_unicode))
        if convert_to_lowercase:
            normalization_steps.append(Lowercase())

        # Apply normalization if any steps were specified
        if normalization_steps:
            if len(normalization_steps) > 1:
                self._tokenizer.normalizer = Sequence(normalization_steps)
            else:
                self._tokenizer.normalizer = normalization_steps[0]

        # Set whitespace splitting as preprocessing step
        self._tokenizer.pre_tokenizer = tokenizers.pre_tokenizers.WhitespaceSplit()

        # Validate required tokens when vocabulary is present
        if vocabulary_path is not None:
            start_token_id = self._tokenizer.token_to_id(str(start_token))
            if start_token_id is None:
                raise TypeError("start_token not found in the vocabulary")
            end_token_id = self._tokenizer.token_to_id(str(end_token))
            if end_token_id is None:
                raise TypeError("end_token not found in the vocabulary")

        # Store configuration parameters
        self._config = {
            "model": "WordLevel",
            "unknown_token": unknown_token,
            "start_token": start_token,
            "end_token": end_token,
            "padding_token": padding_token,
            "masking_token": masking_token,
            "convert_to_lowercase": convert_to_lowercase,
            "normalize_unicode": normalize_unicode,
        }

    @property
    def config(self):
        return self._config

    def encode(self, text):
        """Encode text into tokens"""
        return self._tokenizer.encode(text)

    def encode_batch(self, texts):
        """Encode multiple texts into tokens"""
        return self._tokenizer.encode_batch(texts)

import cv2
import numpy as np

class ShapeClassifier:
    def identify(self, contour):
        shape_name = "unknown"
        perimeter = cv2.arcLength(contour, True)
        approximated = cv2.approxPolyDP(contour, 0.04 * perimeter, True)
        vertices_count = len(approximated)

        if vertices_count == 3:
            shape_name = "triangle"
        elif vertices_count == 4:
            x_coord, y_coord, width, height = cv2.boundingRect(approximated)
            aspect_ratio = float(width) / height
            if 0.95 <= aspect_ratio <= 1.05:
                shape_name = "square"
            else:
                shape_name = "rectangle"
        elif vertices_count == 5:
            shape_name = "pentagon"
        else:
            shape_name = "circle"

        return shape_name

from functools import partial
from typing import Callable, Dict, List, Optional, Union
from funcy import chunks
from lenses import lens
from phc.easy.query.util import flat_map_pipe
from phc.easy.util import add_prefixes
from toolz import compose, curry, identity, pipe

# Constants with same values but different naming
DEFAULT_MAX_ITEMS = 30_000
MAX_PAGE_SIZE = 10000
DEFAULT_BATCH_SIZE = int(MAX_PAGE_SIZE * 0.9)

# Lens definitions - same structure but with clearer variable names
FHIR_QUERY_SECTION = lens.Get("where", {})
FHIR_QUERY_TYPE = FHIR_QUERY_SECTION.Get("type", "")
FHIR_BASIC_QUERY = FHIR_QUERY_SECTION.Get("query", {})
FHIR_COMPOUND_QUERY = FHIR_BASIC_QUERY.Get("bool", {})
FHIR_MUST_CLAUSES = FHIR_COMPOUND_QUERY.Get("must", [])
FHIR_PAGE_LIMIT = lens.Get(
    "limit",
    [
        {"type": "number", "value": 0},
        {"type": "number", "value": DEFAULT_BATCH_SIZE},
    ],
)[1]["value"]

def extract_page_limit(query_dict: dict):
    """Extract page limit value from query structure"""
    return lens.Get("limit", [{}, {}])[1].Get("value", None).get()(query_dict)

def adjust_page_limit(query_dict: dict, adjustment_func: Callable[[int], int]):
    """Modify the page limit in a query"""
    return FHIR_PAGE_LIMIT.modify(compose(int, adjustment_func))(query_dict)

@curry
def combine_query_clauses(second_clause, first_clause):
    """Combine two query clauses using boolean AND"""
    return {"bool": {"must": [first_clause, second_clause]}}

def append_query_clause(query_dict: dict, new_clause: dict):
    """Add a new clause to an existing FSS query"""
    # Handle empty query case
    if FHIR_QUERY_SECTION.get()(query_dict) == {}:
        return pipe(
            query_dict,
            FHIR_BASIC_QUERY.set(new_clause),
            FHIR_QUERY_TYPE.set("elasticsearch"),
        )

    # Validate query type
    if FHIR_QUERY_TYPE.get()(query_dict) != "elasticsearch":
        raise ValueError(
            "Cannot add clause to non-Elasticsearch query",
            new_clause,
            query_dict,
        )

    # Determine how to integrate the new clause
    basic_keys = list(FHIR_BASIC_QUERY.get()(query_dict).keys())
    compound_keys = FHIR_COMPOUND_QUERY.get()(query_dict).keys()

    # Handle simple term/terms case
    if (len(basic_keys) == 1 and (basic_keys[0] in ["term", "terms"])) or (
        "should" in compound_keys
    ):
        return FHIR_BASIC_QUERY.modify(combine_query_clauses(new_clause))(
            query_dict
        )

    # Handle must clause case
    if len(compound_keys) == 1 and "must" in compound_keys:
        return FHIR_MUST_CLAUSES.modify(lambda must_list: [*must_list, new_clause])(
            query_dict
        )

    raise ValueError("Unable to append clause to query", new_clause, query_dict)

def _id_injector(
    single_id: Union[str, None] = None,
    multiple_ids: List[str] = [],
    max_items: int = DEFAULT_MAX_ITEMS,
):
    """Create function to inject IDs into query"""
    combined_ids = [*multiple_ids, *([single_id] if single_id else [])]
    if not combined_ids:
        return identity
    return terms_injector({"id.keyword": combined_ids}, max_items=max_items)

def foreign_key_injector(
    single_foreign_id: Optional[str],
    multiple_foreign_ids: List[str],
    foreign_key_name: str,
    id_prefixes: List[str],
    max_items: int = DEFAULT_MAX_ITEMS,
):
    """Create function to inject foreign keys into query"""
    combined_foreign_ids = [*multiple_foreign_ids, *([single_foreign_id] if single_foreign_id else [])]
    if not combined_foreign_ids:
        return identity

    prefixed_ids = [
        *add_prefixes(combined_foreign_ids, id_prefixes),
        *combined_foreign_ids,
    ]

    return terms_injector(
        {f"{foreign_key_name}.keyword": prefixed_ids},
        max_items=max_items,
    )

def _single_or_multiple_adder(
    single_term: Optional[dict], 
    multiple_terms: List[dict], 
    max_items: int = DEFAULT_MAX_ITEMS
):
    """Handle both single term and multiple terms cases"""
    if single_term is None and not multiple_terms:
        return identity

    all_terms = [single_term, *multiple_terms] if single_term is not None else multiple_terms

    def _inject_into_query(query_dict):
        return flat_map_pipe(
            query_dict,
            *[
                (
                    terms_injector(t, max_items=max_items)
                    if isinstance(list(t.values())[0], list)
                    else single_term_injector(t)
                )
                for t in all_terms
            ],
        )
    return _inject_into_query

def single_term_injector(term_dict: Optional[dict]):
    """Inject a single term clause"""
    if term_dict is None:
        return identity

    if len(term_dict.keys()) > 1:
        raise ValueError(
            f"Expected single key in term dictionary, got: {term_dict}"
        )

    return partial(append_query_clause, new_clause={"term": term_dict})

def terms_injector(terms_dict: Optional[dict], max_items: int = DEFAULT_MAX_ITEMS):
    """Inject terms clause with chunking support"""
    if terms_dict is None:
        return identity

    if len(terms_dict.keys()) > 1:
        raise ValueError(
            f"Expected single key in terms dictionary, got: {terms_dict}"
        )

    key = list(terms_dict.keys())[0]
    # Convert generator to list for reuse
    value_batches = list(chunks(max_items, list(terms_dict.values())[0]))

    def _inject_into_query(query_dict):
        return [
            append_query_clause(query_dict, {"terms": {key: batch}})
            for batch in value_batches
        ]
    return _inject_into_query

def _code_injector(
    field_name: Union[str],
    code_paths: List[str],
    value: Optional[Union[str, List[str]]],
):
    """Inject code-related conditions"""
    if not code_paths or value is None:
        return identity

    clause_type = "term" if isinstance(value, str) else "terms"

    conditions = [
        {clause_type: {f"{path}.{field_name}.keyword": value}}
        for path in code_paths
    ]

    return partial(
        append_query_clause,
        new_clause={
            "bool": {
                "should": conditions
            }
        },
    )

def _page_size_injector(page_size: Union[int, None]):
    """Set page size in query"""
    if page_size is None:
        return identity
    return FHIR_PAGE_LIMIT.set(page_size)

def construct_queries(
    base_query: dict,
    single_id: Optional[str] = None,
    multiple_ids: List[str] = [],
    patient_single_id: Optional[str] = None,
    patient_multiple_ids: List[str] = [],
    patient_field_name: str = "subject.reference",
    patient_id_prefixes: List[str] = ["Patient/"],
    page_size: Optional[int] = None,
    single_term: Optional[dict] = None,
    multiple_terms: List[dict] = [],
    max_items: int = DEFAULT_MAX_ITEMS,
    # Code-related parameters
    code_paths: List[str] = [],
    code_value: Optional[Union[str, List[str]]] = None,
    display_value: Optional[Union[str, List[str]]] = None,
    system_value: Optional[Union[str, List[str]]] = None,
):
    """Build comprehensive query with various filtering options"""
    return flat_map_pipe(
        base_query,
        _id_injector(single_id=single_id, multiple_ids=multiple_ids, max_items=max_items),
        foreign_key_injector(
            single_foreign_id=patient_single_id,
            multiple_foreign_ids=patient_multiple_ids,
            foreign_key_name=patient_field_name,
            id_prefixes=patient_id_prefixes,
            max_items=max_items,
        ),
        _single_or_multiple_adder(single_term=single_term, multiple_terms=multiple_terms, max_items=max_items),
        _code_injector(field_name="code", code_paths=code_paths, value=code_value),
        _code_injector(field_name="display", code_paths=code_paths, value=display_value),
        _code_injector(field_name="system", code_paths=code_paths, value=system_value),
        _page_size_injector(page_size),
    )

from typing import Literal

class BaseClass:
    def my_method(self, value: int) -> int:
        ...

class SubClass(BaseClass):
    def method_plain_super(self, value: int) -> int:
        # Using super() without arguments in instance method context
        t1: Literal["BaseClass"] = reveal_type(super())
        return super().my_method(value)

    def method_super_explicit(self, value: int) -> int:
        # Using explicit class and self with super()
        t1: Literal["BaseClass"] = reveal_type(super(SubClass, self))
        return super(SubClass, self).my_method(value)

    def method_super_with_extra_param(self, value: int) -> int:
        t1: Literal["BaseClass"] = reveal_type(super(SubClass, self))
        # This will cause an error because the method is already bound to 'self'
        return super(SubClass, self).my_method(self, value)

    @classmethod
    def classmethod_super(cls, value: int) -> int:
        instance = cls()
        t1: Literal["BaseClass"] = reveal_type(super(SubClass, instance))
        return super(SubClass, instance).my_method(value)

    @classmethod
    def classmethod_super_with_extra_arg(cls, value: int) -> int:
        instance = cls()
        t1: Literal["BaseClass"] = reveal_type(super(SubClass, instance))
        # Error: passing 'instance' as first argument when method is already bound
        return super(SubClass, instance).my_method(instance, value)

    @staticmethod
    def staticmethod_super(value: int) -> int:
        instance = SubClass()
        t1: Literal["BaseClass"] = reveal_type(super(SubClass, instance))
        return super(SubClass, instance).my_method(value)

    @staticmethod
    def staticmethod_super_with_extra_param(value: int) -> int:
        instance = SubClass()
        t1: Literal["BaseClass"] = reveal_type(super(SubClass, instance))
        # Error: extra argument provided for already-bound method
        return super(SubClass, instance).my_method(instance, value)

