from typing import Optional
import click
from zenml.cli.cli import cli
from zenml.cli.utils import (
    confirmation,
    declare,
    error,
    install_package,
    print_table,
    title,
    uninstall_package,
    warning,
)
from zenml.integrations.registry import integration_registry
from zenml.logger import get_logger

logger = get_logger(__name__)

@cli.group(help="Manage external integration dependencies.")
def integration() -> None:
    """Integration management commands"""
    pass

@integration.command(name="list", help="Display available integrations and their status.")
def list_integrations() -> None:
    """Show all registered integrations with installation status."""
    title("Available Integrations:\n")
    rows = []

    for name, impl in integration_registry.integrations.items():
        installed = impl.check_installation()
        rows.append({
            "STATUS": "✓" if installed else "",
            "NAME": name,
            "DEPENDENCIES": impl.REQUIREMENTS,
        })

    print_table(rows)
    warning("\nTo install an integration's dependencies, use:")
    warning("zenml integration install INTEGRATION_NAME")

@integration.command(
    name="requirements", 
    help="Show required packages for a specific or all integrations."
)
@click.argument("integration_name", required=False, default=None)
def show_requirements(integration_name: Optional[str] = None) -> None:
    """Display package requirements for specified or all integrations."""
    try:
        reqs = integration_registry.select_integration_requirements(integration_name)
    except KeyError as exc:
        error(str(exc))
    else:
        if reqs:
            target = integration_name or "all integrations"
            title(f"Requirements for {target}:\n")
            declare(str(reqs))
            warning("\nInstall these dependencies using:")
            warning("zenml integration install INTEGRATION_NAME")

@integration.command(
    help="Install required packages for specified or all integrations."
)
@click.argument("integration_name", required=False, default=None)
@click.option(
    "--force",
    "-f",
    is_flag=True,
    help="Skip confirmation and reinstall existing packages.",
)
def install_deps(
    integration_name: Optional[str] = None, force: bool = False
) -> None:
    """Install dependencies for specified or all integrations."""
    try:
        # Check if installation is needed
        needs_install = not integration_registry.is_installed(integration_name)

        if needs_install or force:
            requirements = integration_registry.select_integration_requirements(
                integration_name
            )
        else:
            warning("All required packages are already installed.")
            requirements = []
    except KeyError as exc:
        error(str(exc))
    else:
        if requirements:
            target = integration_name or "all integrations"

            if force:
                declare(f"Installing dependencies for {target}")
                for pkg in requirements:
                    install_package(pkg)
            else:
                if confirmation(
                    f"Proceed with installing these packages?\n{requirements}"
                ):
                    for pkg in requirements:
                        install_package(pkg)

@integration.command(
    help="Remove required packages for specified or all integrations."
)
@click.argument("integration_name", required=False, default=None)
@click.option(
    "--force",
    "-f",
    is_flag=True,
    help="Skip confirmation prompt.",
)
def remove_deps(
    integration_name: Optional[str] = None, force: bool = False
) -> None:
    """Uninstall dependencies for specified or all integrations."""
    try:
        if integration_registry.is_installed(integration_name):
            requirements = integration_registry.select_integration_requirements(
                integration_name
            )
        else:
            warning("No packages to uninstall.")
            requirements = []
    except KeyError as exc:
        error(str(exc))
    else:
        if requirements:
            target = integration_name or "all integrations"

            if force:
                declare(f"Removing dependencies for {target}")
                for pkg in requirements:
                    uninstall_package(pkg)
            else:
                if confirmation(
                    f"Confirm removal of these packages?\n{requirements}"
                ):
                    for pkg in requirements:
                        uninstall_package(pkg)

