import re
import operator as op
from typing import Dict, List, Tuple, Union, Optional, Any, Callable
from .aws_lambda_api_event_utils import (
    __version__,
    FormatVersion,
    APIErrorResponse,
    get_event_format_version,
    _get_decorator,
    _get_method,
    _get_headers,
    ApiEventType,
    LaxHeadersType,
)

__all__ = (
    "FormatVersionMismatch",
    "check_event_format",
    "require_format_version",
    "MethodNotAllowedError",
    "check_http_method",
    "validate_method_type",
    "RouteNotFoundError",
    "check_route_path",
    "route_path_matcher",
    "PathParamError",
    "verify_path_params",
    "path_param_validator",
    "HeaderValidationError",
    "check_request_headers",
    "header_validator",
    "UnsupportedMediaType",
    "check_media_type",
    "media_type_validator",
    "QueryParamsError",
    "validate_query_string",
    "query_param_validator",
)

def _extract_stage(event: ApiEventType) -> str:
    version = get_event_format_version(event)
    if version in [FormatVersion.APIGW_10, FormatVersion.APIGW_20]:
        return event["requestContext"]["stage"]  # type: ignore
    else:
        raise NotImplementedError("Unsupported event format")

def _string_matches(
    target: str,
    candidates: Union[str, List[str]],
    *,
    comparison_ops=(op.eq, op.contains),
) -> bool:
    if isinstance(candidates, str):
        return comparison_ops[0](target, candidates)
    else:
        return comparison_ops[1](candidates, target)

class FormatVersionMismatch(APIErrorResponse):
    """Raised when the incoming event doesn't match expected format version."""
    STATUS_CODE = 500
    ERROR_CODE = "InternalServerError"
    ERROR_MESSAGE = "An error occurred."

    def __init__(
        self,
        *,
        required_version: FormatVersion,
        received_version: Optional[FormatVersion],
        **kwargs,
    ) -> None:
        self.required_version = required_version
        self.received_version = received_version
        if "internal_message" not in kwargs:
            if received_version is None:
                kwargs[
                    "internal_message"
                ] = f"Expected event version {required_version}, but received an unknown event"
            else:
                kwargs[
                    "internal_message"
                ] = f"Expected event version {required_version}, but received {received_version}"
        super().__init__(**kwargs)

def check_event_format(
    event: ApiEventType,
    required_version: FormatVersion,
    *,
    use_error_response: bool = False,
) -> FormatVersion:
    """Verify the event uses the specified format version.

    By default raises TypeError since format should be known at deployment.
    Set use_error_response=True to raise FormatVersionMismatch instead.
    """
    actual_version = get_event_format_version(event)
    if isinstance(required_version, str):
        required_version = FormatVersion[required_version]

    if actual_version != required_version:
        error = FormatVersionMismatch(
            required_version=required_version, 
            received_version=actual_version
        )
        if not use_error_response:
            raise TypeError(error.internal_message)
        raise error
    return actual_version

def require_format_version(
    required_version: FormatVersion, *, use_error_response: bool = False
) -> Callable:
    """Decorator factory that enforces the event format version.

    Returns a decorator that validates the event format before execution.
    """
    return _get_decorator(
        check_event_format,
        response_format_version=required_version,
        required_version=required_version,
        use_error_response=use_error_response,
    )

class MethodNotAllowedError(APIErrorResponse):
    """Raised when the HTTP method in the request is not allowed."""
    STATUS_CODE = 405
    ERROR_CODE = "UnsupportedMethod"

    def __init__(
        self, *, request_method: str, allowed_methods: Union[str, List[str]], **kwargs
    ) -> None:
        if isinstance(allowed_methods, str):
            allowed_methods = [allowed_methods]
        self.request_method = request_method
        self.allowed_methods = allowed_methods
        if "internal_message" not in kwargs:
            kwargs[
                "internal_message"
            ] = f"Method {request_method} not in valid set {{{', '.join(allowed_methods)}}}."
        super().__init__(**kwargs)

    def get_error_message(self) -> str:
        """Include allowed methods in the error message."""
        if "error_message" in self.kwargs:
            return self.kwargs["error_message"]
        return f"{self.request_method} is not a valid HTTP method. Valid methods are {' '.join(self.allowed_methods)}"

    def get_default_headers(self) -> LaxHeadersType:
        """Include Allow header as required by RFC7231."""
        return {"Allow": ", ".join(self.allowed_methods)}

def check_http_method(event: ApiEventType, allowed: Union[str, List[str]]) -> str:
    """Validate the HTTP method in the event against allowed methods."""
    request_method = _get_method(event)
    if not _string_matches(request_method, allowed):
        raise MethodNotAllowedError(request_method=request_method, allowed_methods=allowed)
    return request_method

def validate_method_type(allowed: Union[str, List[str]]):
    """Decorator factory for HTTP method validation."""
    return _get_decorator(check_http_method, allowed=allowed)

class RouteNotFoundError(APIErrorResponse):
    """Raised when the request path doesn't match any registered routes."""
    STATUS_CODE = 404
    ERROR_CODE = "PathNotFound"
    ERROR_MESSAGE_TEMPLATE = "Path {event_path} not found."

    def __init__(
        self,
        *,
        request_path: str,
        valid_routes: Union[str, re.Pattern, List],
        is_regex: bool = False,
        **kwargs,
    ) -> None:
        proc = lambda v: v.pattern if isinstance(v, re.Pattern) else v
        if isinstance(valid_routes, (str, re.Pattern)):
            valid_routes = proc(valid_routes)
        else:
            valid_routes = list(proc(v) for v in valid_routes)

        if "internal_message" not in kwargs:
            if isinstance(valid_routes, (str, re.Pattern)):
                kwargs[
                    "internal_message"
                ] = f"Path {request_path} does not match {valid_routes}."
            else:
                kwargs[
                    "internal_message"
                ] = f"Path {request_path} not in valid set {{{', '.join(str(p) for p in valid_routes)}}}."
        self.request_path = request_path
        self.valid_routes = valid_routes
        self.is_regex = is_regex
        super().__init__(**kwargs)

def _remove_stage_prefix(*, path: str, stage: str, format_version: str) -> str:
    if not stage:
        return path
    if format_version == FormatVersion.APIGW_20 and stage == "$default":
        return path
    stage_prefix = f"/{stage}"
    if path.startswith(stage_prefix):
        return path[len(stage_prefix):]
    return path

def _extract_path_and_params(
    event: ApiEventType, *, preserve_stage: Optional[bool] = False
) -> Tuple[str, Dict[str, str]]:
    """Extract path and parameters without validation."""
    format_version = get_event_format_version(event)
    if format_version == FormatVersion.APIGW_10:
        event_path = event["path"]
        params = event.get("pathParameters") or {}
    elif format_version == FormatVersion.APIGW_20:
        event_path = event["rawPath"]
        params = event.get("pathParameters") or {}
    else:
        raise NotImplementedError

    if not preserve_stage:
        stage = _extract_stage(event)
        event_path = _remove_stage_prefix(
            path=event_path, stage=stage, format_version=format_version
        )
    return event_path, params

def _modify_path_params(event: ApiEventType, new_params: Dict) -> Dict:
    """Update the event's path parameters with provided values."""
    format_version = get_event_format_version(event)
    if format_version in [FormatVersion.APIGW_10, FormatVersion.APIGW_20]:
        if event.get("pathParameters") is None:
            if not new_params:
                return {}
            event["pathParameters"] = {}
        event["pathParameters"].update(new_params)
        return event["pathParameters"]
    else:
        raise NotImplementedError

def check_route_path(
    event: ApiEventType,
    route: Union[str, List[str]],
    *,
    preserve_stage: Optional[bool] = False,
) -> Tuple[str, Dict[str, str]]:
    """Validate the request path against expected routes."""
    event_path, params = _extract_path_and_params(
        event, preserve_stage=preserve_stage
    )
    if not _string_matches(event_path, route):
        raise RouteNotFoundError(
            request_path=event_path,
            valid_routes=route,
            is_regex=False,
        )
    return event_path, params

def route_path_matcher(route: Union[str, List[str]], *, preserve_stage: Optional[bool] = False):
    """Decorator factory for route path validation."""
    return _get_decorator(
        check_route_path, route=route, preserve_stage=preserve_stage
    )

def verify_path_params(
    event: ApiEventType,
    *,
    required_keys: Optional[List[str]] = None,
    exact_values: Optional[Dict[str, str]] = None,
    pattern_constraints: Optional[Dict[str, Union[str, re.Pattern]]] = None,
    preserve_stage: Optional[bool] = False,
) -> Tuple[str, Dict[str, str]]:
    """Validate path parameters against requirements."""
    event_path, params = _extract_path_and_params(
        event, preserve_stage=preserve_stage
    )

    missing_keys = []
    if required_keys:
        for key in required_keys:
            if key not in params:
                missing_keys.append(key)

    invalid_values = {}
    if exact_values:
        for key, value in exact_values.items():
            if key not in params:
                missing_keys.append(key)
            elif params[key] != value:
                invalid_values[key] = params[key]

    if pattern_constraints:
        for key, pattern in pattern_constraints.items():
            if key not in params:
                missing_keys.append(key)
            elif not re.search(pattern, params[key]):
                invalid_values[key] = params[key]

    if missing_keys or invalid_values:
        raise PathParamError(
            request_path=event_path,
            missing_keys=missing_keys,
            invalid_values=invalid_values,
            required_keys=required_keys,
            exact_values=exact_values,
            pattern_constraints=pattern_constraints,
        )
    return event_path, params

def path_param_validator(
    *,
    required_keys: Optional[List[str]] = None,
    exact_values: Optional[Dict[str, str]] = None,
    pattern_constraints: Optional[Dict[str, Union[str, re.Pattern]]] = None,
):
    """Decorator factory for path parameter validation."""
    return _get_decorator(
        verify_path_params,
        required_keys=required_keys,
        exact_values=exact_values,
        pattern_constraints=pattern_constraints,
    )

class HeaderValidationError(APIErrorResponse):
    """Raised when headers don't meet validation requirements."""
    STATUS_CODE = 400
    ERROR_CODE = "InvalidRequest"

    def get_error_message(self) -> str:
        if "error_message" in self.kwargs:
            return self.kwargs["error_message"]
        bad_headers = set()
        if self.missing_keys:
            bad_headers.update(self.missing_keys)
        if self.invalid_values:
            bad_headers.update(self.invalid_values.keys())
        bad_headers = sorted(bad_headers)
        return f"Missing or invalid headers: {', '.join(bad_headers)}."

    def __init__(
        self,
        *,
        request_headers: Dict[str, str],
        missing_keys: List[str],
        invalid_values: Dict[str, str],
        **kwargs,
    ) -> None:
        self.request_headers = request_headers
        self.missing_keys = missing_keys
        self.invalid_values = invalid_values
        if "internal_message" not in kwargs:
            message_parts = []
            if missing_keys:
                message_parts.append(f"missing keys {', '.join(missing_keys)}")
            if invalid_values:
                s = ", ".join(f"{key}={value}" for key, value in invalid_values.items())
                message_parts.append("invalid values " + s)
            kwargs["internal_message"] = f"Bad headers: {' and '.join(message_parts)}."
        super().__init__(**kwargs)

def check_request_headers(
    event: ApiEventType,
    *,
    required_keys: Optional[List[str]] = None,
    exact_values: Optional[Dict[str, str]] = None,
    pattern_constraints: Optional[Dict[str, Union[str, re.Pattern]]] = None,
) -> Dict[str, str]:
    """Validate request headers against requirements."""
    event_headers = _get_headers(event)
    missing_keys = []
    if required_keys:
        for key in required_keys:
            if key.lower() not in [k.lower() for k in event_headers.keys()]:
                missing_keys.append(key)

    invalid_values = {}
    if exact_values:
        normalized_exact = dict((key.lower(), value) for key, value in exact_values.items())
        for key, value in normalized_exact.items():
            if key not in [k.lower() for k in event_headers.keys()]:
                missing_keys.append(key)
            elif event_headers.get([k for k in event_headers.keys() if k.lower() == key][0]) != value:
                invalid_values[key] = event_headers.get([k for k in event_headers.keys() if k.lower() == key][0])

    if pattern_constraints:
        normalized_patterns = dict(
            (key.lower(), value) for key, value in pattern_constraints.items()
        )
        for key, pattern in normalized_patterns.items():
            if key not in [k.lower() for k in event_headers.keys()]:
                missing_keys.append(key)
            elif not re.search(pattern, event_headers.get([k for k in event_headers.keys() if k.lower() == key][0])):
                invalid_values[key] = event_headers.get([k for k in event_headers.keys() if k.lower() == key][0])

    if missing_keys or invalid_values:
        raise HeaderValidationError(
            request_headers=event_headers,
            missing_keys=missing_keys,
            invalid_values=invalid_values,
            required_keys=required_keys,
            exact_values=exact_values,
            pattern_constraints=pattern_constraints,
        )
    return event_headers

def header_validator(
    *,
    required_keys: Optional[List[str]] = None,
    exact_values: Optional[Dict[str, str]] = None,
    pattern_constraints: Optional[Dict[str, Union[str, re.Pattern]]] = None,
):
    """Decorator factory for header validation."""
    return _get_decorator(
        check_request_headers, 
        required_keys=required_keys, 
        exact_values=exact_values, 
        pattern_constraints=pattern_constraints
    )

def _match_content_type_exact(content_type: str, expected: str) -> bool:
    if expected == "*/*":
        return True
    mime_type = content_type.split(";")[0].strip()
    if expected.endswith("/*"):
        first_part = mime_type.split("/")[0]
        return first_part == expected.split("/")[0]
    return mime_type == expected

def _match_content_type_in_list(expected_list: List[str], content_type: str) -> bool:
    for expected in expected_list:
        if _match_content_type_exact(content_type, expected):
            return True
    return False

_content_type_validation = (_match_content_type_exact, _match_content_type_in_list)

class UnsupportedMediaType(APIErrorResponse):
    """Raised when the Content-Type header doesn't match allowed types."""
    STATUS_CODE = 415
    ERROR_CODE = "InvalidContentType"

    def get_error_message(self) -> str:
        if "error_message" in self.kwargs:
            return self.kwargs["error_message"]
        if len(self.allowed_types) == 1:
            return f"Content type must be {self.allowed_types[0]}."
        return f"Content type must be one of: {', '.join(self.allowed_types)}."

    def __init__(
        self,
        *,
        actual_content_type: Optional[str],
        allowed_types: Union[str, List[str]],
        **kwargs,
    ) -> None:
        if isinstance(allowed_types, str):
            allowed_types = [allowed_types]
        self.actual_content_type = actual_content_type
        self.allowed_types = allowed_types
        if "internal_message" not in kwargs:
            if actual_content_type is None:
                kwargs["internal_message"] = "Content-Type is missing."
            else:
                kwargs[
                    "internal_message"
                ] = f"Content-Type {actual_content_type} not in valid set {{{', '.join(allowed_types)}}}."
        super().__init__(**kwargs)

def check_media_type(
    event: ApiEventType, allowed_types: Union[str, List[str]]
) -> str:
    """Validate the Content-Type header against allowed types."""
    format_version = get_event_format_version(event)
    event_content_type = None

    if format_version == FormatVersion.APIGW_10:
        for key, value in event["headers"].items():  # type: ignore
            if key.lower() == "content-type":
                event_content_type = value
    elif format_version == FormatVersion.APIGW_20:
        event_headers = event["headers"]
        event_content_type = event_headers.get("content-type")  # type: ignore
    else:
        raise NotImplementedError

    if not event_content_type:
        raise UnsupportedMediaType(
            actual_content_type=None, allowed_types=allowed_types
        )
    elif not _string_matches(event_content_type, allowed_types, matcher=_content_type_validation):
        raise UnsupportedMediaType(
            actual_content_type=event_content_type, allowed_types=allowed_types
        )
    return event_content_type

def media_type_validator(allowed_types: Union[str, List[str]]):
    """Decorator factory for Content-Type validation."""
    return _get_decorator(check_media_type, allowed_types=allowed_types)

class QueryParamsError(APIErrorResponse):
    """Raised when query parameters don't meet validation requirements."""
    STATUS_CODE = 400
    ERROR_CODE = "InvalidRequest"

    def get_error_message(self) -> str:
        if "error_message" in self.kwargs:
            return self.kwargs["error_message"]
        bad_params = set()
        if self.missing_keys:
            bad_params.update(self.missing_keys)
        if self.invalid_values:
            bad_params.update(self.invalid_values.keys())
        bad_params = sorted(bad_params)
        return f"Invalid query parameters: {', '.join(bad_params)}."

    def __init__(
        self,
        *,
        request_params: Dict[str, str],
        missing_keys: List[str],
        invalid_values: Dict[str, str],
        **kwargs,
    ) -> None:
        self.request_params = request_params
        self.missing_keys = missing_keys
        self.invalid_values = invalid_values
        if "internal_message" not in kwargs:
            message_parts = []
            if missing_keys:
                message_parts.append(f"missing keys {', '.join(missing_keys)}")
            if invalid_values:
                s = ", ".join(f"{key}={value}" for key, value in invalid_values.items())
                message_parts.append("invalid values " + s)
            kwargs[
                "internal_message"
            ] = f"Bad parameters: {' and '.join(message_parts)}."
        super().__init__(**kwargs)

def validate_query_string(
    event: ApiEventType,
    *,
    required_keys: Optional[List[str]] = None,
    exact_values: Optional[Dict[str, str]] = None,
    pattern_constraints: Optional[Dict[str, Union[str, re.Pattern]]] = None,
) -> Dict[str, str]:
    """Validate query parameters against requirements."""
    format_version = get_event_format_version(event)
    event_query_parameters = {}

    if format_version == FormatVersion.APIGW_10:
        event_query_parameters = dict(
            (key, ",".join(value))
            for key, value in event["multiValueQueryStringParameters"].items()  # type: ignore
        )
    elif format_version == FormatVersion.APIGW_20:
        if "queryStringParameters" in event:
            event_query_parameters = event["queryStringParameters"]  # type: ignore
    else:
        raise NotImplementedError

    missing_keys = []
    if required_keys:
        for key in required_keys:
            if key not in event_query_parameters:
                missing_keys.append(key)

    invalid_values = {}
    if exact_values:
        for key, value in exact_values.items():
            if key not in event_query_parameters:
                missing_keys.append(key)
            elif event_query_parameters[key] != value:
                invalid_values[key] = event_query_parameters[key]

    if pattern_constraints:
        for key, pattern in pattern_constraints.items():
            if key not in event_query_parameters:
                missing_keys.append(key)
            elif not re.search(pattern, event_query_parameters[key]):
                invalid_values[key] = event_query_parameters[key]

    if missing_keys or invalid_values:
        raise QueryParamsError(
            request_params=event_query_parameters,
            missing_keys=missing_keys,
            invalid_values=invalid_values,
            required_keys=required_keys,
            exact_values=exact_values,
            pattern_constraints=pattern_constraints,
        )
    return event_query_parameters

def query_param_validator(
    *,
    required_keys: Optional[List[str]] = None,
    exact_values: Optional[Dict[str, str]] = None,
    pattern_constraints: Optional[Dict[str, Union[str, re.Pattern]]] = None,
):
    """Decorator factory for query parameter validation."""
    return _get_decorator(
        validate_query_string,
        required_keys=required_keys,
        exact_values=exact_values,
        pattern_constraints=pattern_constraints,
    )

