import abc
import copy
import logging
import math
import pprint
import random
from typing import Dict, List, Optional, Generic, TypeVar, Type, Tuple
from model.game_state import GameState
from model.player_action import get_available_actions, PlayerAction
from model.player_id import PlayerId
from model.player_pair import PlayerPair

# Define the player used for terminal node scoring
_TERMINAL_PLAYER = PlayerId.ONE

def ucb_adjusted_for_player(node: "Node", target_player: PlayerId):
    """Return UCB value adjusted for the target player."""
    return node.ucb if node.current_player == target_player else -node.ucb

# Type variables for generic MCTS implementation
_StateType = TypeVar("_StateType")
_ActionType = TypeVar("_ActionType")

class Node(abc.ABC, Generic[_StateType, _ActionType]):
    """
    Abstract base class for nodes in an MCTS tree.
    Each node represents a game state and maintains statistics for MCTS.
    """

    def __init__(self, current_state: _StateType, parent_node: Optional["Node"]):
        self.state = current_state
        self.parent = parent_node
        self.children_map: Optional[Dict[_ActionType, "Node"]] = None
        self.available_moves: Optional[List[_ActionType]] = None

        # Statistics for MCTS
        self.total_value = 0.0
        self.visit_count = 0
        self.ucb_value = None
        self.exploration_component = 0.0
        self.is_complete = False

        # Initialize based on whether this is a terminal state
        if not self.is_terminal:
            # Non-terminal: prepare for expansion
            possible_moves = self._list_possible_actions()
            self.children_map = {move: None for move in possible_moves}
            self.available_moves = list(possible_moves)
        else:
            # Terminal: compute immediate reward
            outcome_scores = self._compute_terminal_outcome()
            opponent = _TERMINAL_PLAYER.opponent()
            self.ucb_value = outcome_scores[_TERMINAL_PLAYER] - outcome_scores[opponent]
            self.is_complete = True

    @property
    @abc.abstractmethod
    def is_terminal(self) -> bool:
        """Determine if this node represents a terminal (end-of-game) state."""

    @abc.abstractmethod
    def _list_possible_actions(self) -> List[_ActionType]:
        """Return list of valid actions available at this non-terminal state."""

    @abc.abstractmethod
    def _compute_terminal_outcome(self) -> PlayerPair[float]:
        """Return final scores for both players at terminal state."""

    @abc.abstractmethod
    def _current_player(self) -> PlayerId:
        """Return the player who must act in this state."""

    @property
    def current_player(self) -> PlayerId:
        """Return the player to move, or the designated terminal player if terminal."""
        return _TERMINAL_PLAYER if self.is_terminal else self._current_player()

    @property
    def fully_expanded(self) -> bool:
        """Check if all possible moves have been explored."""
        return self.is_terminal or len(self.available_moves) == 0

    def expand(self) -> "Node":
        """Expand this node by creating a child for one untried action."""
        assert not self.fully_expanded, "Cannot expand a fully expanded node"

        # Choose a random untried action
        selected_move = random.choice(self.available_moves)

        # Create new state after applying the action
        next_state = self._apply_action(selected_move)

        # Create child node
        child_node = self.__class__(next_state, self)

        # Link child to parent
        self.children_map[selected_move] = child_node
        self.available_moves.remove(selected_move)

        return child_node

    @abc.abstractmethod
    def _apply_action(self, move: _ActionType) -> _StateType:
        """Return the resulting state after applying the given action."""

    def update_ucb_values(self, exploration_weight: float):
        """Update UCB values for all children."""
        if self.children_map is None:
            return

        for child_node in self.children_map.values():
            if child_node is not None:
                child_node.recalculate_ucb(exploration_weight)

    def recalculate_ucb(self, exploration_weight: float):
        """Recalculate UCB value for this node."""
        if self.is_terminal or self.is_complete:
            return

        # Count children that are either unexpanded or not fully simulated
        active_children = [
            child for child in self.children_map.values()
            if child is None or not child.is_complete
        ]

        if len(active_children) > 0:
            # Use average value + exploration component
            self.ucb_value = self.total_value / self.visit_count if self.visit_count > 0 else 0.0
            self.exploration_component = exploration_weight * math.sqrt(
                2 * math.log(self.parent.visit_count) / self.visit_count
            ) if self.visit_count > 0 else 0.0
        else:
            # Use max UCB among fully expanded children
            child_ucbs = [ucb_adjusted_for_player(child, self.current_player) 
                         for child in self.children_map.values() if child is not None]
            self.ucb_value = max(child_ucbs)
            self.is_complete = True

    def get_best_children(self) -> List[Tuple["Node", _ActionType]]:
        """Return list of best child nodes and corresponding actions."""
        scored_children = [
            (ucb_adjusted_for_player(child, self.current_player), child, action)
            for action, child in self.children_map.items() if child is not None
        ]

        if not scored_children:
            # Fallback if all children are None (shouldn't happen normally)
            logging.error("MctsAlgorithm: All children are None: %s",
                         pprint.pformat(self.children_map, indent=True))
            return [(child, action) for action, child in self.children_map.items()]

        # Find maximum UCB value
        best_score = max(score for score, _, _ in scored_children)

        # Return all children with maximum UCB
        return [(child, action) for score, child, action in scored_children if score == best_score]

    def get_best_moves(self) -> List[_ActionType]:
        """Return list of best actions."""
        return [action for _, action in self.get_best_children()]

    def __repr__(self):
        return f"Value:{self.total_value}, Visits:{self.visit_count}, UCB({self.current_player}):{self.ucb_value} " \
               f"Complete:{self.is_complete}"

class SchnapsenNode(Node[GameState, PlayerAction]):
    """Concrete implementation of Node for Schnapsen game."""

    @property
    def is_terminal(self) -> bool:
        return self.state.is_game_over

    def _list_possible_actions(self) -> List[PlayerAction]:
        assert not self.is_terminal
        return get_available_actions(self.state)

    def _compute_terminal_outcome(self) -> PlayerPair[float]:
        assert self.is_terminal
        points = self.state.game_points
        # Normalize scores
        points.one /= 3
        points.two /= 3
        return points

    def _current_player(self) -> PlayerId:
        return self.state.next_player

    def _apply_action(self, move: PlayerAction) -> GameState:
        return move.execute(self.state)

def debug_tree(node: Node, depth: int = 1):
    """Print tree structure for debugging."""
    if node is None:
        print("None")
        return

    print(f"{node.current_player.name}: {node}", end="")

    if node.children_map is None:
        print(f" [score: {node.state.trick_points} {node.state.game_points}]")
        return

    print()
    for move, child in node.children_map.items():
        print("\t" * depth, end="")
        print(f"{move}", end="")
        debug_tree(child, depth + 1)

class MctsSearch(Generic[_StateType, _ActionType]):
    """Monte Carlo Tree Search implementation."""

    def __init__(self, agent_player: PlayerId,
                 node_type: Type[Node[_StateType, _ActionType]] = SchnapsenNode,
                 exploration_factor: float = 0.0):
        self._agent_id = agent_player
        self._node_class = node_type
        self._max_iterations = None
        self._exploration_weight = exploration_factor

    def construct_tree(self, initial_state: _StateType,
                       iteration_limit: Optional[int] = None,
                       use_best_child_selection: bool = False) -> Node[
        _StateType, _ActionType]:
        """Build MCTS tree from initial state."""
        assert iteration_limit is None or iteration_limit > 0, \
            "iteration_limit must be positive"

        # Deep copy input state to avoid mutation
        if isinstance(initial_state, GameState):
            state_copy = initial_state.deep_copy()
        else:
            state_copy = copy.deepcopy(initial_state)

        # Create root node
        root = self._node_class(state_copy, None)

        # Run iterations until limit or full expansion
        iterations = 0
        while True:
            iterations += 1

            if self._perform_one_iteration(root, use_best_child_selection):
                break

            if iteration_limit is not None and iterations >= iteration_limit:
                break

        logging.info("MctsAlgorithm: Completed %d iterations", iterations)
        return root

    def _perform_one_iteration(self, root: Node,
                               select_best_child: bool) -> bool:
        """Execute one MCTS iteration: selection, expansion, simulation, backpropagation."""
        # Selection phase
        selected_node = MctsSearch._select_node(root, select_best_child)

        if selected_node is None:
            return True  # Entire tree already explored

        # Expansion phase
        leaf_node = MctsSearch._expand_to_leaf(selected_node)

        # Backpropagation phase
        self._propagate_upwards(leaf_node, leaf_node.ucb_value)

        return False

    @staticmethod
    def _select_node(current_node: Node, select_best_child: bool) -> Optional[Node]:
        """Select node for expansion using UCB-based policy."""
        while not current_node.is_terminal:
            # If not fully expanded, select this node
            if not current_node.fully_expanded:
                return current_node

            # Get children that aren't fully simulated
            active_children = [
                child for child in current_node.children_map.values()
                if not child.is_complete
            ]

            if not active_children:
                # All children fully explored
                return None

            if select_best_child:
                # Select best child based on UCB + exploration
                scored_children = [
                    (child, ucb_adjusted_for_player(child, current_node.current_player) + child.exploration_component)
                    for child in active_children
                ]

                max_score = max(score for _, score in scored_children)
                best_children = [child for child, score in scored_children if score == max_score]
                current_node = random.choice(best_children)
            else:
                # Randomly select among active children
                current_node = random.choice(active_children)

        raise RuntimeError("Should not reach terminal node during selection")  # pragma: no cover

    @staticmethod
    def _expand_to_leaf(node: Node) -> Node:
        """Expand tree down to a leaf node."""
        while not node.is_terminal:
            assert not node.fully_expanded, "Cannot expand fully expanded node"
            node = node.expand()
        return node

    def _propagate_upwards(self, node: Node, reward_value: float):
        """Backpropagate result up the tree."""
        current = node

        while current is not None:
            if not current.is_terminal:
                current.visit_count += 1
                # Update total value based on player perspective
                if current.current_player == _TERMINAL_PLAYER:
                    current.total_value += reward_value
                else:
                    current.total_value -= reward_value

                # Update UCB values for children
                current.update_ucb_values(self._exploration_weight)

            current = current.parent

