        # Parent and root identifiers with lazy evaluation for type resolution
        parent_ref = ravel.Id(lambda: TreeNode, nullable=True, default=lambda: None)
        root_ref = ravel.Id(lambda: TreeNode, nullable=True, default=lambda: None)
        label = ravel.String(nullable=False, required=True)

