        def descendants(self, req) -> 'TreeNode.Batch':
            # Fetch all child nodes where current node is parent
            return Query(request=req).where(
                TreeNode.parent_ref == self._id
            ).execute()

        @resolver(target=lambda: TreeNode)
        def ancestor(self, req) -> 'TreeNode':
            # Retrieve direct parent node
            return Query(request=req).where(
                TreeNode._id == self.parent_ref
            ).execute(first=True)

        @resolver(target=lambda: TreeNode)
        def apex(self, req) -> 'TreeNode':
            # Retrieve topmost ancestor (root) node
            return Query(request=req).where(
                TreeNode._id == self.root_ref
            ).execute(first=True)

