                    # Create two children per node at each level
                    offspring = cls.Batch.generate(
                        values={
                            'parent_ref': node._id,
                            'root_ref': node.root_ref,
                        },
                        count=2,
                    ).save()
                    for branch in offspring:
                        expand_node(branch, remaining_levels - 1)

            # Initialize root node
            base = cls(label='root', parent_ref=None)
            base.root_ref = base._id
            base.save()

            # Recursively populate tree up to specified depth
            expand_node(base, max(0, levels))
            return base

