import os
import json
import requests
from requests.exceptions import HTTPError
from dotenv import load_dotenv
import logging

# Initialize logger
logger = logging.getLogger()
logging.basicConfig(level=logging.INFO)

def __generate_missing_env_response(env_var: str):
    error_msg = "Lambda function misconfigured: missing required environment variable '{0:s}'."
    logger.error(error_msg.format(env_var))
    return {
        'statusCode': 500,
        'body': json.dumps(error_msg.format(env_var))
    }

def handler(event, context):
    # Load environment variables from .env file
    load_dotenv()

    # Set log level based on environment configuration
    log_level_str = os.getenv("HULL_LOG_LEVEL", "ERROR")
    numeric_level = getattr(logging, log_level_str.upper(), logging.ERROR)
    logger.setLevel(numeric_level)

    # Log incoming event
    logger.info("Hull extract requester invoked with event: %s", event)

    # Extract and validate required environment variables
    logger.info("Parsing configuration from environment variables...")

    org_id = os.getenv("HULL_ORG_ID")
    connector_id = os.getenv("HULL_CONNECTOR_ID")
    connector_secret = os.getenv("HULL_CONNECTOR_SECRET")
    callback_url = os.getenv("HULL_EXPORT_CALLBACKURL")
    object_type = os.getenv("HULL_EXPORT_OBJECTTYPE")
    fields_str = os.getenv("HULL_EXPORT_FIELDS")
    es_query_str = os.getenv("HULL_EXPORT_ESQUERY")

    # Log loaded values (masking sensitive data)
    logger.info("Loaded environment variables: %s", { 
        "HULL_ORG_ID": org_id,
        "HULL_CONNECTOR_ID": connector_id,
        "HULL_EXPORT_CALLBACKURL": callback_url,
        "HULL_EXPORT_OBJECTTYPE": object_type,
        "HULL_EXPORT_FIELDS": bool(fields_str),
        "HULL_EXPORT_ESQUERY": bool(es_query_str)
    })

    # Validate required environment variables
    if not org_id:
        return __generate_missing_env_response("HULL_ORG_ID")

    if not connector_id:
        return __generate_missing_env_response("HULL_CONNECTOR_ID")

    if not connector_secret:
        return __generate_missing_env_response("HULL_CONNECTOR_SECRET")

    if not callback_url:
        return __generate_missing_env_response("HULL_EXPORT_CALLBACKURL")

    if not object_type:
        return __generate_missing_env_response("HULL_EXPORT_OBJECTTYPE")

    if not fields_str:
        return __generate_missing_env_response("HULL_EXPORT_FIELDS")

    if not es_query_str:
        return __generate_missing_env_response("HULL_EXPORT_ESQUERY")

    # Validate object type
    valid_types = ["user", "account"]
    if object_type not in valid_types:
        error_msg = f"Invalid object type '{object_type}'. Must be one of: {', '.join(valid_types)}."
        logger.error(error_msg)
        return {
            'statusCode': 500,
            'body': json.dumps(error_msg)
        }

    # Prepare request to Hull API
    try:
        endpoint = f"https://{org_id}/api/v1/extract/{object_type}s"
        payload = {
            "url": callback_url,
            "format": "json",
            "fields": json.loads(fields_str),
            "query": json.loads(es_query_str)
        }
        headers = {
            "Accept": "application/json",
            "Hull-App-Id": connector_id,
            "Hull-Access-Token": connector_secret
        }

        logger.info("Sending export request to Hull at '%s' with headers %s and payload %s", 
                   endpoint, {k: "***" if k == "Hull-Access-Token" else v for k, v in headers.items()}, 
                   {k: "***" if k == "query" else v for k, v in payload.items()})

        api_response = requests.post(endpoint, json=payload, headers=headers)
        logger.info("API response received: status %s %s", api_response.status_code, api_response.reason)
        api_response.raise_for_status()

    except HTTPError as http_err:
        logger.error("HTTP error occurred: %s", http_err)
        return {
            'statusCode': http_err.response.status_code,
            'body': json.dumps(f"HTTP error: {http_err}")
        }
    except Exception as exc:
        logger.error("Unexpected error occurred: %s", exc)
        return {
            'statusCode': 500,
            'body': json.dumps(f"Internal error: {exc}")
        }
    else:
        logger.info("Export successfully initiated. Results will be delivered to '%s'", callback_url)
        return {
            'statusCode': 200,
            'body': json.dumps(f"Export successfully initiated. Results will be delivered to '{callback_url}'")
        }

# Reimplementation of Spec-related functionality with equivalent logic

from traits.api import HasTraits, Int, Bool, Str, Enum, List
from traitsui.api import View, Item, TextEditor, CheckListEditor, BooleanEditor, RangeEditor, EnumEditor
import traitsui.trui as trui


class VEdit:
    def __init__(self, value=None, editor=None, kwargs=None):
        self.value = value
        self.editor = editor or (TextEditor if isinstance(value, str) else BooleanEditor)
        self.kwargs = kwargs if kwargs is not None else {}

        # Default kwargs for TextEditor if not provided and value is string
        if editor is None and isinstance(value, str):
            self.kwargs.setdefault('auto_set', False)
            self.kwargs.setdefault('enter_set', True)


def merge_spec(obj1, obj2):
    # Handle simple values
    if not hasattr(obj1, 'value') and not hasattr(obj2, 'value'):
        return obj1

    # Handle VEdit objects
    if hasattr(obj1, 'value') and hasattr(obj2, 'value'):
        # Merge VEdit instances: prefer first non-None value, combine editors and kwargs
        merged_value = obj1.value if obj1.value is not None else obj2.value
        merged_editor = obj1.editor if obj1.editor is not None else obj2.editor

        # Combine kwargs: obj2's kwargs override obj1's
        merged_kwargs = dict(obj1.kwargs)
        merged_kwargs.update(obj2.kwargs)

        return VEdit(merged_value, merged_editor, merged_kwargs)

    # Handle callable objects
    if callable(obj1) and callable(obj2):
        def combined_func(receiver):
            obj1(receiver)
            obj2(receiver)
        return combined_func

    # Default case: return first object
    return obj1


class Spec(HasTraits):
    def __init__(self, spec_dict):
        self._dict = {}
        for key, value in spec_dict.items():
            if isinstance(value, VEdit):
                self._dict[key] = value
            elif isinstance(value, dict):
                # Nested dictionary handling
                nested_spec = {}
                for subkey, subval in value.items():
                    if isinstance(subval, VEdit):
                        nested_spec[subkey] = subval
                    else:
                        # Convert plain values to VEdit with default editor
                        nested_spec[subkey] = VEdit(subval)
                self._dict[key] = Spec(nested_spec)
            else:
                # Convert plain values to VEdit with appropriate defaults
                if isinstance(value, bool):
                    editor = BooleanEditor
                elif isinstance(value, int):
                    editor = RangeEditor
                elif isinstance(value, str):
                    editor = TextEditor
                else:
                    editor = TextEditor

                self._dict[key] = VEdit(value, editor)

    def __getattr__(self, name):
        if name in self._dict:
            item = self._dict[name]
            if isinstance(item, Spec):
                return item
            return item.value
        raise AttributeError(f"'Spec' object has no attribute '{name}'")

    def convert_to_items(self):
        items = []
        for key, vedit in self._dict.items():
            if isinstance(vedit, Spec):
                # For nested specs, create a group-like structure
                nested_items = vedit.convert_to_items()
                items.extend(nested_items)
            else:
                # Create an Item with the appropriate editor
                editor_instance = vedit.editor(**vedit.kwargs) if vedit.kwargs else vedit.editor()
                items.append(Item(name=key, editor=editor_instance))
        return items


# Test functions
def test_complete_and_merge():
    assert merge_spec(1, 2) == 1
    merged_vedits = merge_spec(VEdit(True, BooleanEditor, {}),
                               VEdit(False, BooleanEditor, {'k': 10}))
    assert merged_vedits.value is True
    assert merged_vedits.editor == BooleanEditor
    assert merged_vedits.kwargs == {}

    def my_func(receiver):
        pass
    def my_func_2(receiver):
        pass
    assert callable(merge_spec(my_func, my_func_2))

    d_simple = {'a': 10,
                'b': VEdit('b', CheckListEditor, {'values': ['a', 'b', 'c']})}
    d1 = {'a': VEdit(10, RangeEditor, {'low': 2, 'high': 15}),
          'b': {
              'b1': VEdit(True, BooleanEditor, {}),
              'b2': VEdit(1, EnumEditor, {'values': range(0, 20)})
          }}
    d2 = {'a': 15,
          'b': {VEdit('c', None, {})}
          }

    merged_specs = merge_spec(Spec(d1), Spec(d2))
    assert merged_specs.a == 10
    assert merged_specs.b.b1 is True


def test_spec_init():
    d_simple = {'a': 10,
                'b': VEdit('b', CheckListEditor, {'values': ['a', 'b', 'c']})}
    spec_simple = Spec(d_simple)
    assert spec_simple._dict['a'].editor == trui.TextEditor
    assert spec_simple._dict['a'].kwargs == {'auto_set': False, 'enter_set': True}
    assert spec_simple._dict['b'].editor == CheckListEditor
    assert spec_simple._dict['b'].kwargs == {'values': ['a', 'b', 'c']}


def test_set_and_get_spec():
    d_simple = {'a': 10,
                'b': VEdit('b', CheckListEditor, {'values': ['a', 'b', 'c']})}
    spec_simple = Spec(d_simple)
    assert spec_simple.a == 10

    d1 = {'a': VEdit(10, RangeEditor, {'low': 2, 'high': 15}),
          'b': {
              'b1': VEdit(True, BooleanEditor, {}),
              'b2': VEdit(1, EnumEditor, {'values': range(0, 20)})
          }}
    spec = Spec(d1)
    assert spec.a == 10


def test_convert_to_items():
    d_simple = {'a': 10,
                'b': VEdit('b', CheckListEditor, {'values': ['a', 'b', 'c']})}
    spec_simple = Spec(d_simple)
    items = spec_simple.convert_to_items()
    item1, item2 = items[0], items[1]
    assert isinstance(item1.editor, trui.TextEditor)
    assert isinstance(item2.editor, trui.CheckListEditor)

    d1 = {'a': VEdit(10, RangeEditor, {'low': 2, 'high': 15}),
          'b': {
              'b1': VEdit(True, BooleanEditor, {}),
              'b2': VEdit(1, EnumEditor, {'values': range(0, 20)})
          }}
    spec = Spec(d1)
    items = spec.convert_to_items()
    assert len(items) == 2
    assert len(spec._dict['b'].value.convert_to_items()) == 2

