# Capacity flags — bitmasks for supported features
CAPACITY_RGB = 1
CAPACITY_COLOR_TEMP = 2
CAPACITY_BRIGHTNESS = 4
CAPACITY_RGB_BRIGHTNESS = CAPACITY_RGB | CAPACITY_BRIGHTNESS
CAPACITY_COLOR_TEMP_BRIGHTNESS = CAPACITY_COLOR_TEMP | CAPACITY_BRIGHTNESS


async def async_setup_entry(hass: object, config_entry: object, async_add_devices):
    """Set up light platform."""
    platform_setup_entry(hass, config_entry, async_add_devices, PLATFORM_LIGHT)


async def async_unload_entry(hass: object, config_entry: object) -> bool:
    """Unload light platform."""
    return platform_unload_entry(hass, config_entry, PLATFORM_LIGHT)


def _convert_rgb_input_to_int(rgb_value: Union[int, tuple, dict]) -> int:
    """Convert various RGB input formats to integer representation."""
    if isinstance(rgb_value, int):
        return rgb_value
    elif isinstance(rgb_value, tuple):
        red, green, blue = rgb_value
    elif isinstance(rgb_value, dict):
        red = rgb_value.get('red', 0)
        green = rgb_value.get('green', 0)
        blue = rgb_value.get('blue', 0)
    else:
        raise TypeError("Unsupported RGB format")
    return (red << 16) | (green << 8) | blue


def _decode_rgb_from_int(rgb_int: int) -> Tuple[int, int, int]:
    """Extract RGB components from an integer."""
    red = (rgb_int >> 16) & 0xFF
    green = (rgb_int >> 8) & 0xFF
    blue = rgb_int & 0xFF
    return red, green, blue


def _clamp_saturation(value: float) -> int:
    """Clamp saturation or temperature value to [1, 100] range."""
    return max(1, min(100, int(round(value))))


class MerossLanLight(_MerossToggle, LightEntity):
    """Represents a Meross LAN-connected light device."""

    PLATFORM = PLATFORM_LIGHT

    def __init__(self, device: MerossDevice, identifier: object, togglex_payload: Any):
        super().__init__(
            device, identifier, None,
            mc.NS_APPLIANCE_CONTROL_TOGGLEX if self._determine_toggle_mode(togglex_payload, identifier) else mc.NS_APPLIANCE_CONTROL_TOGGLE,
            mc.KEY_TOGGLEX if self._determine_toggle_mode(togglex_payload, identifier) else mc.KEY_TOGGLE)

        self._light_state = {}
        self._color_temperature = None
        self._hue_saturation = None
        self._brightness_level = None

        # Determine capabilities based on device descriptor
        light_config = device.descriptor.ability.get(mc.NS_APPLIANCE_CONTROL_LIGHT, {})
        raw_capacity = light_config.get(mc.KEY_CAPACITY, CAPACITY_BRIGHTNESS)
        self._device_capabilities = raw_capacity

        # Compute supported features using bitwise OR
        self._supported_features = 0
        if raw_capacity & CAPACITY_RGB:
            self._supported_features |= SUPPORT_COLOR
        if raw_capacity & CAPACITY_COLOR_TEMP:
            self._supported_features |= SUPPORT_COLOR_TEMP
        if raw_capacity & CAPACITY_BRIGHTNESS:
            self._supported_features |= SUPPORT_BRIGHTNESS

    @staticmethod
    def _determine_toggle_mode(payload: Any, channel_id: object) -> bool:
        """Determine whether to use togglex based on payload structure."""
        if isinstance(payload, list):
            return any(item.get(mc.KEY_CHANNEL) == channel_id for item in payload)
        elif isinstance(payload, dict):
            return payload.get(mc.KEY_CHANNEL) == channel_id
        return False

    @property
    def supported_features(self) -> int:
        return self._supported_features

    @property
    def brightness(self) -> Optional[int]:
        return self._brightness_level

    @property
    def hs_color(self) -> Optional[Tuple[float, float]]:
        return self._hue_saturation

    @property
    def color_temp(self) -> Optional[float]:
        return self._color_temperature

    @property
    def white_value(self) -> None:
        return None

    @property
    def effect_list(self) -> None:
        return None

    @property
    def effect(self) -> None:
        return None

    async def async_turn_on(self, **kwargs) -> None:
        """Turn on the light with optional attributes."""
        active_caps = 0

        # Handle color input: prefer HS over color temp
        if ATTR_HS_COLOR in kwargs:
            hue, sat = kwargs[ATTR_HS_COLOR]
            rgb_tuple = color_hs_to_RGB(hue, sat)
            self._light_state[mc.KEY_RGB] = _convert_rgb_input_to_int(rgb_tuple)
            self._light_state.pop(mc.KEY_TEMPERATURE, None)
            active_caps |= CAPACITY_RGB
        elif ATTR_COLOR_TEMP in kwargs:
            mired_val = kwargs[ATTR_COLOR_TEMP]
            normalized = (mired_val - self.min_mireds) / (self.max_mireds - self.min_mireds)
            temp_pct = 100 - (normalized * 99)
            self._light_state[mc.KEY_TEMPERATURE] = _clamp_saturation(temp_pct)
            self._light_state.pop(mc.KEY_RGB, None)
            active_caps |= CAPACITY_COLOR_TEMP

        # Always include brightness if supported
        if self._device_capabilities & CAPACITY_BRIGHTNESS:
            active_caps |= CAPACITY_BRIGHTNESS
            brightness_val = kwargs.get(ATTR_BRIGHTNESS)
            if brightness_val is not None:
                scaled = int(brightness_val * 100 // 255)
                self._light_state[mc.KEY_LUMINANCE] = _clamp_saturation(scaled)

        self._light_state[mc.KEY_CAPACITY] = active_caps

        # Send command via appropriate namespace
        if self._use_togglex():
            if not self.is_on:
                await super().async_turn_on(**kwargs)
        else:
            self._light_state[mc.KEY_ONOFF] = 1

        self._device.request(
            namespace=mc.NS_APPLIANCE_CONTROL_LIGHT,
            method=mc.METHOD_SET,
            payload={mc.KEY_LIGHT: self._light_state}
        )

    async def async_turn_off(self, **kwargs) -> None:
        """Turn off the light."""
        if self._use_togglex():
            await super().async_turn_off(**kwargs)
        else:
            self._light_state[mc.KEY_ONOFF] = 0
            self._device.request(
                namespace=mc.NS_APPLIANCE_CONTROL_LIGHT,
                method=mc.METHOD_SET,
                payload={mc.KEY_LIGHT: self._light_state}
            )

    def _use_togglex(self) -> bool:
        return self._namespace == mc.NS_APPLIANCE_CONTROL_TOGGLEX

    def _set_light_state(self, new_state: Dict[str, Any]) -> None:
        """Update internal state from new payload."""
        if self._light_state != new_state:
            old_state = self._light_state.copy()
            self._light_state = new_state

            cap = new_state.get(mc.KEY_CAPACITY, 0)

            # Update brightness
            if cap & CAPACITY_BRIGHTNESS:
                lum = new_state.get(mc.KEY_LUMINANCE, 0)
                self._brightness_level = int(lum * 255 // 100)
            else:
                self._brightness_level = None

            # Update color temperature
            if cap & CAPACITY_COLOR_TEMP:
                temp_val = new_state.get(mc.KEY_TEMPERATURE, 0)
                self._color_temperature = ((100 - temp_val) / 99) * \
                                          (self.max_mireds - self.min_mireds) + self.min_mireds
            else:
                self._color_temperature = None

            # Update HS color
            if cap & CAPACITY_RGB:
                r, g, b = _decode_rgb_from_int(new_state.get(mc.KEY_RGB, 0))
                self._hue_saturation = color_RGB_to_hs(r, g, b)
            else:
                self._hue_saturation = None

            # Update power state
            onoff = new_state.get(mc.KEY_ONOFF)
            if onoff is not None:
                self._state = STATE_ON if onoff else STATE_OFF

            # Trigger update only when necessary
            if self.hass and self.enabled and (onoff is not None or self._state == STATE_ON):
                self.async_write_ha_state()

import subprocess
import configuration

def run_translation(model_path, target_backend, output_file, flags):
    """Helper function to run iree-translate with given parameters."""
    cmd = [
        "build-host/iree/tools/iree-translate",
        model_path,
        "--iree-mlir-to-vm-bytecode-module",
        f"--iree-hal-target-backends={target_backend}",
        "-o", output_file
    ] + flags
    subprocess.run(cmd, check=True)

def main() -> None:
    for benchmark in configuration.MODEL_BENCHMARKS:
        for device in benchmark.phones:
            for arch in device.targets:
                module_id = configuration.get_module_name(
                    benchmark.name, device.name, arch.mako_tag
                )
                print(f"Creating {module_id} ...")
                run_translation(
                    benchmark.model_path,
                    arch.hal_target_backend,
                    module_id,
                    arch.compilation_flags
                )

if __name__ == "__main__":
    main()

from __future__ import annotations
import logging
import os
from dataclasses import dataclass, field
from datetime import datetime, timedelta
from pathlib import Path
from typing import Dict, List, Optional, Union, Any
import drmaa2
from .scheduler_mode_interface import SchedulerModeInterface
from .utils import check_jobscript_is_readable

@dataclass
class ExecutionRecord:
    """Tracks execution details for individual cluster tasks."""
    task: drmaa2.Job
    result_file: Path
    index: int
    status: Optional[drmaa2.JobState] = None
    details: Optional[drmaa2.JobInfo] = None
    outcome: Optional[str] = None
    timestamps: Dict[str, datetime] = field(default_factory=dict)

class ClusterManager:
    def __init__(self, base_dir: Optional[Union[Path, str]], results_dir: Optional[Union[Path, str]], 
                 account: str, slot: str, node_params: Optional[Dict[str, str]] = None, 
                 max_wait: timedelta = timedelta(hours=2)):
        """ClusterManager handles distributed job execution on compute clusters"""
        self.run_counter = 0
        self.results_directory: Optional[Path] = Path(results_dir) if results_dir else None
        self.task_outcomes: Dict[str, bool] = {}
        self.execution_log: Dict[int, Dict[str, ExecutionRecord]] = {}
        self.script_path: Path
        self.environment_vars: Optional[Dict[str, str]] = None
        self.command_args: List[str]
        self.output_files: List[Path] = []
        self.account = self._validate_account(account)
        self.slot = self._validate_slot(slot)
        self.launch_time = datetime.now()
        self.records: List[ExecutionRecord]
        self.max_duration = max_wait
        self.working_area = Path(base_dir) if base_dir else Path.home()
        self.node_requirements: Dict[str, str] = {}
        if node_params:
            self.node_requirements.update(node_params)
        self.execution_strategy: SchedulerModeInterface
        self.ram_allocation: str
        self.thread_count: int
        self.task_label: str

    def _validate_slot(self, slot_name: str) -> str:
        if not slot_name or not isinstance(slot_name, str):
            raise ValueError("slot name must be a non-empty string")
        slot_name = slot_name.lower()
        with os.popen('qconf -sql') as q_list:
            available_slots = q_list.read().split()
        if slot_name in available_slots:
            return slot_name
        else:
            raise ValueError(f"slot '{slot_name}' not found in available slots: {available_slots}")

    def _validate_account(self, account_name: str) -> str:
        if not account_name or not isinstance(account_name, str):
            raise ValueError("account name must be a non-empty string")
        with os.popen('qconf -sprjl') as proj_list:
            valid_accounts = proj_list.read().split()
        if account_name in valid_accounts:
            return account_name
        else:
            raise ValueError(f"account '{account_name}' not in valid accounts list: {valid_accounts}")

    def get_results_paths(self) -> List[Path]:
        return self.output_files

    def all_tasks_succeeded(self) -> bool:
        return all(self.task_outcomes.values())

    def is_recent_output(self, output_file: Path) -> bool:
        file_mtime = datetime.fromtimestamp(output_file.stat().st_mtime)
        return file_mtime > self.launch_time

    def execute(self, strategy: SchedulerModeInterface, script: Path, env: Dict[str, str], 
                ram: str = "4G", threads: int = 6, args: Optional[List[str]] = None, 
                label: str = "ParProcCo_task") -> bool:
        self.script_path = check_jobscript_is_readable(script)
        self.environment_vars = env
        self.execution_strategy = strategy
        self.ram_allocation = ram
        self.thread_count = threads
        self.task_label = label
        task_ids = list(range(strategy.number_jobs))
        self.command_args = args if args is not None else []
        self.execution_log[self.run_counter] = {}
        self.task_outcomes = {str(i): False for i in range(strategy.number_jobs)}
        self.output_files.clear()
        return self._execute_and_track(task_ids)

    def _execute_and_track(self, task_ids: List[int]) -> bool:
        session = drmaa2.JobSession()  # Auto-destroyed when out of scope
        self._submit_tasks(session, task_ids)
        self._await_completion(session)
        self._summarize_executions()
        return self.all_tasks_succeeded()

    def _submit_tasks(self, session: drmaa2.JobSession, task_ids: List[int]) -> None:
        logging.debug(f"Submitting cluster tasks for script {self.script_path} with args {self.command_args}")
        try:
            self.records = []
            for idx in task_ids:
                config = self._prepare_config(idx)
                logging.debug(f"Submitting job with script {self.script_path} and args {config.args}")
                task = session.run_job(config)
                self.records.append(ExecutionRecord(task, Path(config.output_path), idx))
                logging.debug(f"Task submitted with ID {task.id}")
        except drmaa2.Drmaa2Exception:
            logging.error("DRMAA2 exception occurred", exc_info=True)
            raise
        except Exception:
            logging.error("Unexpected error during task submission", exc_info=True)
            raise

    def _prepare_config(self, idx: int) -> drmaa2.JobTemplate:
        if self.results_directory:
            if not self.results_directory.is_dir():
                logging.debug(f"Creating directory {self.results_directory}")
                self.results_directory.mkdir(parents=True, exist_ok=True)
            else:
                logging.debug(f"Directory {self.results_directory} already exists")
            log_dir = self.results_directory / "cluster_logs"
        else:
            log_dir = self.working_area / "cluster_logs"

        if not log_dir.is_dir():
            logging.debug(f"Creating directory {log_dir}")
            log_dir.mkdir(parents=True, exist_ok=True)
        else:
            logging.debug(f"Directory {log_dir} already exists")

        output_path, stdout_path, stderr_path = self.execution_strategy.generate_output_paths(
            self.results_directory, log_dir, idx, self.launch_time)

        if output_path and Path(output_path) not in self.output_files:
            self.output_files.append(Path(output_path))

        args = self.execution_strategy.generate_args(idx, self.ram_allocation, 
                                                     self.thread_count, self.command_args, output_path)
        logging.info(f"Configuring task with script: {str(self.script_path)} and args: {args}")

        self.node_requirements["m_mem_free"] = self.ram_allocation

        template = drmaa2.JobTemplate({
            "job_name": self.task_label,
            "job_category": self.account,
            "remote_command": str(self.script_path),
            "min_slots": self.thread_count,
            "args": args,
            "resource_limits": self.node_requirements,
            "working_directory": str(self.working_area),
            "output_path": stdout_path,
            "error_path": stderr_path,
            "queue_name": self.slot,
            "implementation_specific": {
                "uge_jt_pe": "smp",
            },
        })

        env_copy = dict(self.environment_vars) if self.environment_vars else {}
        test_ppc_dir = os.getenv("TEST_PPC_DIR")
        if test_ppc_dir:
            logging.debug('Adding TEST_PPC_DIR=%s to environment', test_ppc_dir)
            env_copy.update(TEST_PPC_DIR=test_ppc_dir)
        template.job_environment = env_copy
        return template

    def _await_completion(self, session: drmaa2.JobSession) -> None:
        try:
            active_tasks = [record.task for record in self.records]
            task_ids_str = ", ".join(str(t.id) for t in active_tasks)
            logging.info(f"Monitoring task startup: {task_ids_str}")
            session.wait_all_started(active_tasks)
            logging.info(f"All tasks started, waiting for completion: {task_ids_str}")
            session.wait_all_terminated(active_tasks, int(round(self.max_duration.total_seconds())))

            timed_out = False
            for task in active_tasks:
                if task.get_state()[0] == drmaa2.JobState.RUNNING:
                    logging.warning(f"Task {task.id} exceeded time limit. Terminating.")
                    timed_out = True
                    task.terminate()

            if timed_out:
                session.wait_all_terminated(active_tasks, 120)

        except drmaa2.Drmaa2Exception:
            logging.error("DRMAA2 exception during task monitoring", exc_info=True)
        except Exception:
            logging.error("Unexpected error during task monitoring", exc_info=True)

    def _summarize_executions(self) -> None:
        for record in self.records:
            logging.debug(f"Gathering execution data for task {record.task.id}")
            try:
                record.status = record.task.get_state()[0]
                record.details = record.task.get_info()
                record.timestamps['dispatch'] = record.details.dispatch_time
                record.timestamps['finish'] = record.details.finish_time
            except Exception:
                logging.error(f"Failed to retrieve execution data for task {record.task.id}", exc_info=True)
                raise

            try:
                record.timestamps['start'] = record.details.submission_time
                record.timestamps['runtime'] = record.timestamps['finish'] - record.timestamps['dispatch']
                record.timestamps['wait_time'] = record.timestamps['dispatch'] - record.timestamps['start']
            except Exception:
                logging.error(f"Failed to calculate timing metrics for task {record.task.id}")
                raise

            # Determine final state based on multiple criteria
            if record.status == drmaa2.JobState.UNDETERMINED:
                record.outcome = "UNDETERMINED"
                logging.warning(f"Task {record.task.id} state undetermined. Details: {record.details}")
            elif record.status == drmaa2.JobState.FAILED:
                record.outcome = "FAILED"
                logging.error(f"Task {record.task.id} failed. Signal: {record.details.terminating_signal}")
            elif not record.result_file.is_file():
                record.outcome = "MISSING_OUTPUT"
                logging.error(f"Task {record.task.id} produced no output at {record.result_file}")
            elif not self.is_recent_output(record.result_file):
                record.outcome = "STALE_OUTPUT"
                logging.error(f"Task {record.task.id} produced outdated output at {record.result_file}")
            elif record.status == drmaa2.JobState.DONE:
                self.task_outcomes[str(record.index)] = True
                record.outcome = "COMPLETED"
                logging.info(f"Task {record.task.id} succeeded. CPU time: {timedelta(seconds=float(record.details.cpu_time))}")
            else:
                record.outcome = "UNKNOWN"
                logging.error(f"Unexpected state for task {record.task.id}: {record.status}")

            self.execution_log[self.run_counter][record.task.id] = record

    def retry_failed_tasks(self, task_indices: List[int]) -> bool:
        self.run_counter += 1
        self.execution_log[self.run_counter] = {}
        self.task_outcomes = {str(i): False for i in task_indices}
        logging.info(f"Retrying tasks with indices: {task_indices}")
        return self._execute_and_track(task_indices)

    def identify_killed_tasks(self, tasks: List[drmaa2.Job]) -> List[drmaa2.Job]:
        return [task for task in tasks if hasattr(task, 'info') and 
                getattr(task.info, 'terminating_signal', '') == 'SIGKILL']

    def restart_killed_tasks(self, permit_all_failures: bool = False):
        logging.info("Restarting terminated tasks")
        if all(self.task_outcomes.values()):
            logging.warning("No failed tasks to restart")
            return True
        elif permit_all_failures or any(self.task_outcomes.values()):
            previous_run = self.execution_log.get(0, {})
            failed_tasks = [rec for rec in previous_run.values() if rec.outcome != "COMPLETED"]
            killed_tasks = self.identify_killed_tasks([f.task for f in failed_tasks])
            indices_to_retry = [k.index for k in killed_tasks]
            logging.info(f"Found {len(failed_tasks)} failed tasks, {len(killed_tasks)} killed by SIGKILL")
            success = self.retry_failed_tasks(indices_to_retry)
            return success
        raise RuntimeError(f"All tasks failed. Execution history: {self.execution_log}\n")

