def _traverse_nodes(output, ancestor=None):
    """Generate nodes from entities in depth-first order."""
    base_entity = getattr(output, "entity", output)
    if isinstance(base_entity, Collection):
        for part in base_entity.members:
            updated_member = part
            if ancestor is not None:
                updated_member = attr.evolve(part, parent=ancestor)
            if base_entity.client:
                _configure_entity_with_context(updated_member, base_entity.client, None)
            if isinstance(output, Generation):
                descendant = Generation(
                    activity=output.activity, entity=updated_member, role=getattr(base_entity, "role", None)
                )
            elif isinstance(output, Usage):
                descendant = Usage(
                    activity=output.activity, entity=updated_member, role=getattr(base_entity, "role", None)
                )
            else:
                descendant = updated_member
            yield from _traverse_nodes(descendant)
    yield output

def _configure_entity_with_context(entity, repository, revision):
    """Assign client and commit information to an entity."""
    if repository and not entity.client:
        entity.client = repository
    if not entity.commit:
        version_label = "UNCOMMITTED"
        if entity._label:
            parts = entity._label.rsplit("@", maxsplit=1)
            version_label = parts[-1] if len(parts) > 1 else parts[0]
        if version_label == "UNCOMMITTED":
            entity.commit = revision
        elif repository:
            try:
                entity.commit = repository.repo.commit(version_label)
            except Exception:
                pass

@attr.s(eq=False, order=False)
class Activity(CommitMixin):
    """Represents an activity in the repository."""
    _identifier = attr.ib(default=None, kw_only=True)
    _description = attr.ib(kw_only=True)
    _informed_by = attr.ib(kw_only=True)
    depends_on = attr.ib(default=None, kw_only=True)
    _collections = attr.ib(default=attr.Factory(OrderedDict), init=False, kw_only=True)
    produced = attr.ib(kw_only=True, default=None)
    deprecated = attr.ib(kw_only=True, default=None)
    affected_by = attr.ib(kw_only=True)
    began_at_time = attr.ib(kw_only=True)
    ended_at_time = attr.ib(kw_only=True)
    responsible_agents = attr.ib(kw_only=True)
    _metadata_location = attr.ib(default=None, init=False)

    def default_produced(self):
        """Create default ``produced`` list."""
        outputs = []
        for location in self.get_output_locations():
            subject = self._get_activity_subject(location)
            outputs.append(Generation(activity=self, entity=subject, role=None))
        return outputs

    def get_output_locations(self):
        """Retrieves all output paths generated by this execution."""
        result = set()
        current_commit = self.commit
        if not current_commit:
            if not self.client:
                return result
            current_commit = self.client.repo.head.commit

        previous_commits = list(current_commit.parents) if current_commit.parents else [NULL_TREE]
        for change in current_commit.diff(previous_commits):
            # Skip files that were added (they appear as new in reverse diff)
            if change.change_type == "A":
                continue

            path_obj = Path(git_unicode_unescape(change.a_path))

            # Check if this is a dataset file
            is_dataset_file = any(
                path_obj.resolve() == (self.client.path / f.entity.path).resolve()
                for d in self.client.datasets.values()
                for f in d.files
            )

            is_not_ref = LinkReference.REFS not in str(path_obj)
            does_not_exist = not path_obj.exists()

            if all([is_dataset_file, is_not_ref, does_not_exist]):
                matching_dataset = next(
                    d
                    for d in self.client.datasets.values()
                    for f in d.files
                    if path_obj.resolve() == (self.client.path / f.entity.path).resolve()
                )
                path_obj = self.client.path / matching_dataset.path / self.client.METADATA

            result.add(str(path_obj))
        return result

    def _get_activity_subject(self, path, removed=False):
        """Gets the entity associated with this Activity and path."""
        repo, commit, relative_path = self.client.resolve_in_submodules(self.commit, path)
        path_str = str(relative_path)
        output_path = repo.path / path_str
        ancestors = list(output_path.relative_to(repo.path).parents)
        current_collection = None
        new_members = []

        for ancestor_path in reversed(ancestors[:-1]):
            ancestor_key = str(ancestor_path)
            if ancestor_key in self._collections:
                current_collection = self._collections[ancestor_key]
            else:
                current_collection = Collection(
                    client=repo, commit=commit, path=ancestor_key, members=[], parent=current_collection
                )
                new_members.append(current_collection)
                self._collections[ancestor_key] = current_collection
            new_members = current_collection.members

        entity_type = Entity
        if (repo.path / path_str).is_dir():
            entity_type = Collection

        entity = entity_type(commit=commit, client=repo, path=path_str, parent=current_collection)
        if current_collection:
            current_collection.members.append(entity)
        return entity

    def default_deprecated(self):
        """Entities deprecated by this Action."""
        results = []
        for path in self.removed_paths:
            entity = self._get_activity_subject(path, removed=True)
            results.append(entity)
        return results

    @affected_by.default
    def default_affected_by(self):
        """Calculate default values."""
        return list(self._collections.values())

    @property
    def ancestors(self):
        """Return parent commits."""
        if self.commit:
            return list(self.commit.parents)

    @property
    def removed_paths(self):
        """Return all paths removed in the commit."""
        result = set()
        if not self.commit:
            return result

        previous_commits = list(self.commit.parents) if self.commit.parents else [NULL_TREE]
        for change in self.commit.diff(previous_commits):
            # Only process deleted files (they appear as ADDED in reverse diff)
            if change.change_type != "A":
                continue

            path_obj = Path(git_unicode_unescape(change.a_path))
            result.add(str(path_obj))
        return result

    @property
    def locations(self):
        """Return all paths in the commit."""
        result = set()
        previous_commits = list(self.commit.parents) if self.commit.parents else [NULL_TREE]
        for change in self.commit.diff(previous_commits):
            # Skip files that were added (they appear as new in reverse diff)
            if change.change_type == "A":
                continue

            path_obj = Path(git_unicode_unescape(change.a_path))

            # Check if this is a dataset file
            is_dataset_file = any(
                path_obj.resolve() == (self.client.path / f.entity.path).resolve()
                for d in self.client.datasets.values()
                for f in d.files
            )

            is_not_ref = LinkReference.REFS not in str(path_obj)
            exists_or_symlink = path_obj.exists() or (path_obj.is_symlink() and os.path.lexists(path_obj))
            does_not_exist = not exists_or_symlink

            if all([is_dataset_file, is_not_ref, does_not_exist]):
                matching_dataset = next(
                    d
                    for d in self.client.datasets
                    for f in d.files
                    if path_obj.resolve() == (self.client.path / f.entity.path).resolve()
                )
                path_obj = self.client.path / matching_dataset.path / self.client.METADATA

            result.add(str(path_obj))
        return result

    @classmethod
    def generate_identifier(cls, commit_sha):
        """Calculate action identifier."""
        host = "localhost"
        if hasattr(cls, "client"):
            host = cls.client.remote.get("host") or host
        host = os.environ.get("RENKU_DOMAIN") or host
        return urllib.parse.urljoin(
            "https://{host}".format(host=host),
            PurePosixPath("/activities", "commit/{commit}".format(commit=commit_sha)).as_posix(),
        )

    def default_identifier(self):
        """Configure calculated identifier."""
        if self.commit:
            return self.generate_identifier(self.commit.hexsha)
        return self.generate_identifier("UNCOMMITTED")

    @_description.default
    def default_description(self):
        """Generate a default message."""
        if self.commit:
            return self.commit.message

    @_informed_by.default
    def default_informed_by(self):
        """List parent actions."""
        if self.commit:
            return [self.generate_identifier(parent) for parent in self.commit.parents]

    @began_at_time.default
    def default_began_at_time(self):
        """Configure calculated properties."""
        if self.commit:
            return self.commit.authored_datetime

    @ended_at_time.default
    def default_ended_at_time(self):
        """Configure calculated properties."""
        if self.commit:
            return self.commit.committed_datetime

    @responsible_agents.default
    def default_responsible_agents(self):
        """Set person agent to be the author of the commit."""
        if self.commit:
            return [Person.from_commit(self.commit), renku_agent]
        return [renku_agent]

    @property
    def graph_nodes(self):
        """Return topologically sorted nodes."""
        collection_map = OrderedDict()

        def _find_ancestors(node):
            if node.parent:
                yield from _find_ancestors(node.parent)
                yield node.parent

        for output in self.produced:
            for ancestor in _find_ancestors(output.entity):
                collection_map[ancestor.path] = ancestor
            yield from _traverse_nodes(output)

        for removed in self.deprecated:
            for ancestor in _find_ancestors(removed):
                collection_map[ancestor.path] = ancestor
            yield from _traverse_nodes(removed)

        yield from reversed(collection_map.values())

    def __attrs_post_init__(self):
        """Sets ``produced`` and ``deprecated`` default values if needed."""
        super().__attrs_post_init__()
        if not self._identifier:
            self._identifier = self.default_identifier()
        if not self.produced:
            self.produced = self.default_produced()
        for p in self.produced:
            _configure_entity_with_context(p.entity, self.client, self.commit)
        if not self.deprecated:
            self.deprecated = self.default_deprecated()
        if self.produced:
            for p in self.produced:
                p._activity = weakref.ref(self)

    @classmethod
    def from_yaml(cls, path, client=None, commit=None):
        """Return an instance from a YAML file."""
        data = jsonld.read_yaml(path)
        self = cls.from_jsonld(data=data, client=client, commit=commit)
        self._metadata_location = path
        return self

    def to_yaml(self, path=None):
        """Write an instance to the referenced YAML file."""
        self._metadata_location = path or self._metadata_location
        data = ActivitySchema(flattened=True).dump(self)
        jsonld.write_yaml(path=self._metadata_location, data=data)

    @classmethod
    def from_jsonld(cls, data, client=None, commit=None):
        """Create an instance from JSON-LD data."""
        if isinstance(data, cls):
            return data
        if not isinstance(data, list):
            raise ValueError(data)
        schema = ActivitySchema
        if any(str(wfprov.WorkflowRun) in d["@type"] for d in data):
            schema = WorkflowRunSchema
        elif any(str(wfprov.ProcessRun) in d["@type"] for d in data):
            schema = ProcessRunSchema
        return schema(client=client, commit=commit, flattened=True).load(data)

    def as_jsonld(self):
        """Create JSON-LD representation."""
        return ActivitySchema(flattened=True).dump(self)

@attr.s(eq=False, order=False)
class ProcessRun(Activity):
    """A process run is a particular execution of a Process description."""
    __association_cls__ = Run
    produced = attr.ib(kw_only=True, default=None)
    association = attr.ib(default=None, kw_only=True)
    annotations = attr.ib(kw_only=True, default=None)
    qualified_usage = attr.ib(kw_only=True, default=None)
    run_parameter = attr.ib(kw_only=True, default=None)

    def __attrs_post_init__(self):
        """Calculate properties."""
        super().__attrs_post_init__()
        needs_commit_update = not self.commit or self.commit.hexsha in self._identifier
        if needs_commit_update and self.client and Path(self.path).exists():
            self.commit = self.client.find_previous_commit(self.path)
        if not self.annotations:
            self.annotations = self.plugin_annotations()
        if self.association:
            self.association.plan._activity = weakref.ref(self)
            plan = self.association.plan
            if not plan.commit:
                if self.client:
                    plan.client = self.client
                if self.commit:
                    plan.commit = self.commit
                if plan.inputs:
                    for i in plan.inputs:
                        _configure_entity_with_context(i.consumes, self.client, self.commit)
                if plan.outputs:
                    for o in plan.outputs:
                        _configure_entity_with_context(o.produces, self.client, self.commit)
        if self.qualified_usage and self.client and self.commit:
            updated_usages = []
            revision = "{0}".format(self.commit)
            for usage in self.qualified_usage:
                if not usage.commit and "@UNCOMMITTED" in usage._label:
                    updated_usages.append(
                        Usage.from_revision(
                            client=self.client, path=usage.path, role=usage.role, revision=revision, id=usage._identifier
                        )
                    )
                else:
                    if not usage.client:
                        usage.entity.set_client(self.client)
                    if not usage.commit:
                        label_parts = usage._label.rsplit("@", maxsplit=1)
                        revision = label_parts[-1] if len(label_parts) > 1 else label_parts[0]
                        usage.entity.commit = self.client.repo.commit(revision)
                    updated_usages.append(usage)
            self.qualified_usage = updated_usages

    def default_produced(self):
        """Create default ``produced``."""
        outputs = []
        if not self.association or not self.association.plan:
            return outputs
        for output_spec in self.association.plan.outputs:
            entity = Entity.from_revision(
                self.client, output_spec.produces.path, revision=self.commit, parent=output_spec.produces.parent
            )
            generation = Generation(activity=self, role=output_spec.sanitized_id, entity=entity)
            outputs.append(generation)
        return outputs

    def add_annotations(self, annotations):
        """Adds annotations from an external tool."""
        self.annotations.extend(annotations)

    def plugin_annotations(self):
        """Adds ``Annotation``s from plugins to a ``ProcessRun``."""
        from renku.core.plugins.pluginmanager import get_plugin_manager
        pm = get_plugin_manager()
        results = pm.hook.process_run_annotations(run=self)
        return [a for r in results for a in r]

    @classmethod
    @inject.params(client="LocalClient")
    def from_run(cls, run, client, path, commit=None, subprocess_index=None, update_commits=False):
        """Convert a ``Run`` to a ``ProcessRun``."""
        from .agents import SoftwareAgent
        if not commit:
            commit = client.repo.head.commit
        usages = []
        identifier = ProcessRun.generate_identifier(commit)
        if subprocess_index is not None:
            identifier = f"{identifier}/steps/step_{subprocess_index}"
        for input_spec in run.inputs:
            usage_id = f"{identifier}/{input_spec.sanitized_id}"
            input_path = input_spec.consumes.path
            entity = input_spec.consumes
            if update_commits:
                revision = client.find_previous_commit(input_path, revision=commit.hexsha)
                entity = Entity.from_revision(client, input_path, revision)
            dependency = Usage(entity=entity, role=input_spec.sanitized_id, id=usage_id)
            usages.append(dependency)
        agent = SoftwareAgent.from_commit(commit)
        association = Association(agent=agent, id=identifier + "/association", plan=run)
        parameters = []
        for parameter in run.run_parameters:
            parameter_id = f"{identifier}/{parameter.name}"
            parameters.append(RunParameter(name=parameter.name, value=parameter.value, id=parameter_id))
        process_run = cls(
            id=identifier,
            qualified_usage=usages,
            association=association,
            client=client,
            commit=commit,
            path=path,
            run_parameter=parameters,
        )
        generated = []
        for output_spec in run.outputs:
            entity = Entity.from_revision(client, output_spec.produces.path, revision=commit, parent=output_spec.produces.parent)
            generation = Generation(activity=process_run, role=output_spec.sanitized_id, entity=entity)
            generated.append(generation)
        process_run.produced = generated
        return process_run

    @property
    def ancestors(self):
        """Return parent commits."""
        return [member.commit for usage in self.qualified_usage for member in usage.entity.entities] + super().ancestors

    @property
    def graph_nodes(self):
        """Return topologically sorted nodes."""
        # Outputs go first
        yield from super().graph_nodes
        # Activity itself
        yield self.association.plan

    def to_yaml(self, path=None):
        """Write an instance to the referenced YAML file."""
        self._metadata_location = path or self._metadata_location
        data = ProcessRunSchema(flattened=True).dump(self)
        jsonld.write_yaml(path=self._metadata_location, data=data)

    @classmethod
    @inject.params(client="LocalClient")
    def from_jsonld(cls, data, client=None, commit=None):
        """Create an instance from JSON-LD data."""
        if isinstance(data, cls):
            return data
        if not isinstance(data, list):
            raise ValueError(data)
        return ProcessRunSchema(client=client, commit=commit, flattened=True).load(data)

    def as_jsonld(self):
        """Create JSON-LD."""
        return ProcessRunSchema(flattened=True).dump(self)

@attr.s(eq=False, order=False)
class WorkflowRun(ProcessRun):
    """A workflow run typically contains several subprocesses."""
    __association_cls__ = Run
    _subprocesses = attr.ib(kw_only=True, default=attr.Factory(list))

    @property
    def subprocesses(self):
        """Subprocesses of this ``WorkflowRun``."""
        return {i: p for i, p in enumerate(self._subprocesses)}

    @classmethod
    @inject.params(client="LocalClient")
    def from_run(cls, run, client, path, commit=None, subprocess_index=None, update_commits=False):
        """Convert a ``Run`` to a ``WorkflowRun``."""
        from .agents import SoftwareAgent
        if not commit:
            commit = client.repo.head.commit
        processes = []
        generated = []
        for s in run.subprocesses:
            proc_run = ProcessRun.from_run(s.process, client, path, commit, s.index, update_commits)
            processes.append(proc_run)
            generated.extend(proc_run.produced)
        usages = []
        identifier = cls.generate_identifier(commit)
        input_index = 1
        for input_spec in run.inputs:
            usage_id = f"{identifier}/inputs/{input_index}"
            dependency = Usage.from_revision(
                client=client, path=input_spec.consumes.path, role=input_spec.sanitized_id, revision=commit, id=usage_id
            )
            usages.append(dependency)
            input_index += 1
        agent = SoftwareAgent.from_commit(commit)
        association = Association(agent=agent, id=identifier + "/association", plan=run)
        all_generated = []
        # fix generations in folders
        for generation in generated:
            all_generated.append(generation)
            entity = generation.entity
            if not isinstance(entity, Collection) or not entity.commit:
                continue
            for e in entity.entities:
                if e.commit is not entity.commit or any(g.entity._identifier == e._identifier for g in all_generated):
                    continue
                all_generated.append(Generation(activity=generation.activity, entity=e, role=None))
        wf_run = WorkflowRun(
            id=identifier,
            subprocesses=processes,
            generated=all_generated,
            qualified_usage=usages,
            association=association,
            client=client,
            commit=commit,
            path=path,
        )
        return wf_run

    @property
    def graph_nodes(self):
        """Yield all graph nodes."""
        for subprocess in reversed(self._subprocesses):
            if subprocess.path is None:
                # skip nodes connecting directory to file
                continue
            for n in subprocess.graph_nodes:
                # if self.client and not n.commit and isinstance(n, Entity):
                #     _configure_entity_with_context(n, self.client, self.commit)
                # n._activity = weakref.ref(subprocess)
                yield n
            yield subprocess.association.plan

    def __attrs_post_init__(self):
        """Attrs post initializations."""
        if not self._identifier:
            self._identifier = self.default_identifier()
        if not self._subprocesses:
            self._subprocesses = []
            for subprocess_spec in self.association.plan.subprocesses:
                run = subprocess_spec.process
                process_run = ProcessRun.from_run(
                    run=run,
                    client=self.client,
                    path=self.path,
                    commit=self.commit,
                    subprocess_index=subprocess_spec.index,
                    update_commits=True,
                )
                self._subprocesses.append(process_run)
        if self.client:
            for s in self._subprocesses:
                s.client = self.client
                s.commit = self.commit
                s.__attrs_post_init__()
                s.depends_on = self
        super().__attrs_post_init__()

    def to_yaml(self, path=None):
        """Write an instance to the referenced YAML file."""
        self._metadata_location = path or self._metadata_location
        data = WorkflowRunSchema(flattened=True).dump(self)
        jsonld.write_yaml(path=self._metadata_location, data=data)

    @classmethod
    @inject.params(client="LocalClient")
    def from_jsonld(cls, data, client=None, commit=None):
        """Create an instance from JSON-LD data."""
        if isinstance(data, cls):
            return data
        if not isinstance(data, list):
            raise ValueError(data)
        return WorkflowRunSchema(client=client, commit=commit, flattened=True).load(data)

    def as_jsonld(self):
        """Create JSON-LD."""
        return WorkflowRunSchema(flattened=True).dump(self)

class ActivitySchema(OldCommitMixinSchema):
