import os
import glob
from typing import List, Tuple
from macuitest.lib.operating_system.env import env

class CrashReporter:
    def __init__(self, command_runner):
        self.command_runner = command_runner

    def distribute_reports(self, logging_handler, report_paths: List[str]):
        for path in report_paths:
            self.__handle_crash_report(logging_handler, path)

    def __handle_crash_report(self, logging_handler, path: str):
        filename = os.path.basename(path)
        self.command_runner.sudo(f'chmod 755 "{path}"')
        with open(path) as file:
            content = file.read()
        logging_handler.error(
            filename,
            extra={
                "attachment": {
                    "name": filename,
                    "data": content,
                    "mime_type": "application/octet-stream",
                }
            },
        )

    def store_and_remove_reports(self, patterns: Tuple[str], destination: str):
        for report_path in self.gather_reports(patterns):
            self.command_runner.execute(f'cp "{report_path}" "{destination}"')
            self.command_runner.sudo(f'rm "{report_path}"')

    @staticmethod
    def gather_reports(patterns: Tuple[str, ...]) -> List[str]:
        """Gather crash reports using glob patterns across diagnostic directories."""
        found_reports = []
        for base_dir in (env.user_diag_reports, env.system_diag_reports):
            for pattern in patterns:
                full_pattern = f"{base_dir}/{pattern}"
                found_reports.extend(glob.glob(full_pattern))
        return found_reports

