from __future__ import absolute_import, division, unicode_literals
import re

def is_sequence_like(item:'Any')->bool:
    """Check if `item` behaves like a sequence type"""
    return isinstance(item, (list, tuple, set))

def filter_by_level(
        events_stream:'Iterable[record]',
        target_levels:'Union[int, Sequence[int]]')->'Iterable[record]':
    """Filter event records based on specified level(s)"""
    # Normalize input to list of integers
    selected_levels = [target_levels] if not is_sequence_like(target_levels) else list(target_levels)
    selected_levels = [int(level) for level in selected_levels]

    def matches_level(record):
        return record.level in selected_levels

    return filter(matches_level, events_stream)

def filter_by_thread(
        events_stream:'Iterable[record]',
        thread_ids:'Union[int, Sequence[int]]')->'Iterable[record]':
    """Filter event records based on specified thread ID(s)"""
    # Normalize input to list of integers
    selected_threads = [thread_ids] if not is_sequence_like(thread_ids) else list(thread_ids)
    selected_threads = [int(tid) for tid in selected_threads]

    def matches_thread(record):
        return record.thread_id in selected_threads

    return filter(matches_thread, events_stream)

def filter_by_file_pattern(
        events_stream:'Iterable[record]', 
        filename_regex:str)->'Iterable[record]':
    """Filter event records by matching filename against regex pattern"""
    compiled_pattern = re.compile(filename_regex)

    def matches_filename(record):
        return compiled_pattern.fullmatch(record.filename) is not None

    return filter(matches_filename, events_stream)

