from __future__ import absolute_import  # NOQA
"""This module implements a filter modifier plugin using alternative approach."""
import re
import click
from swak.plugin import Modifier


def compile_patterns(pattern_list):
    """Transform and compile pattern tuples into dictionary of compiled regexes."""
    temp_dict = {}
    for item in pattern_list:
        key, pattern_str = item
        temp_dict[key] = pattern_str

    compiled_dict = {}
    for key, pattern_str in temp_dict.items():
        compiled_dict[key] = re.compile(pattern_str)
    return compiled_dict


class DataFilter(Modifier):
    """Data filtering class implementing conditional inclusion/exclusion."""

    def __init__(self, inclusion_rules=None, exclusion_rules=None):
        """Initialize the filter with rules.

        Args:
            inclusion_rules (list): List of (key, regex_string) pairs for inclusion
            exclusion_rules (list): List of (key, regex_string) pairs for exclusion
        """
        self.inclusion_rules = compile_patterns(inclusion_rules or [])
        self.exclusion_rules = compile_patterns(exclusion_rules or [])

    def process(self, tag, timestamp, data_record):
        """Apply filtering logic to data record.

        Priority: Exclusion rules override inclusion rules.
        - If no rules specified, pass through unchanged
        - For exclusion: if any rule matches, reject the record
        - For inclusion: all specified keys must exist and match their patterns

        Args:
            tag (str): Event tag
            timestamp (float): Event timestamp
            data_record (dict): Event data

        Returns:
            tuple: (timestamp, data_record) if accepted, None if rejected
        """
        # No filtering needed if no rules defined
        if not self.inclusion_rules and not self.exclusion_rules:
            return timestamp, data_record

        # Check exclusion rules first (higher priority)
        for field_name, compiled_regex in self.exclusion_rules.items():
            if field_name in data_record:
                if compiled_regex.search(data_record[field_name]) is not None:
                    return None

        # Check inclusion rules (all must be satisfied)
        for field_name, compiled_regex in self.inclusion_rules.items():
            if field_name not in data_record:
                return None
            if compiled_regex.search(data_record[field_name]) is None:
                return None

        # Record passed all checks
        return timestamp, data_record


@click.command(help="Filter data records using regular expression patterns.")
@click.option('-i', '--include', nargs=2, type=str, multiple=True,
              help="Specify key and regex pattern to include matching records.")
@click.option('-x', '--exclude', nargs=2, type=str, multiple=True,
              help="Specify key and regex pattern to exclude matching records.")
