class Gizo:
    def __init__(self, endpoint_url: str = None, config_path: str = None):
        self.__rpc_dispatcher: Dispatcher = None
        self.__hprose_client: hprose.HproseHttpClient = None
        self.__config_filename: str = None
        self.__credential_store: dict = None

        # Set configuration file name
        if config_path is None:
            self.__config_filename = ".gizo"
        else:
            self.__config_filename = config_path

        # Attempt to load existing configuration
        if path.isfile(self.__config_filename):
            try:
                self.__load_config()
                status_check = requests.get(self.__rpc_dispatcher.status(), timeout=0.5)
                self.__hprose_client = self.__establish_connection(self.__rpc_dispatcher)
            except Exception:
                self.__rpc_dispatcher = None
                self.__discover_dispatcher()
                self.__save_config()

        else:
            if endpoint_url is not None:
                try:
                    self.__rpc_dispatcher = Dispatcher(endpoint_url)
                    self.__hprose_client = self.__establish_connection(self.__rpc_dispatcher)
                    self.__credential_store = self.generate_keypair()
                    self.__save_config()
                except Exception as error:
                    print(str(error))
                    sys.exit(1)
            else:
                self.__discover_dispatcher()
                self.__credential_store = self.generate_keypair()
                self.__save_config()

    def __load_config(self):
        with open(self.__config_filename, "r") as cfg_file:
            raw_content = json.loads(cfg_file.read())
        self.__rpc_dispatcher = Dispatcher(raw_content["dispatcher"])
        self.__credential_store = raw_content["keys"]

    def __save_config(self):
        temp_data: dict = {}
        temp_data["dispatcher"] = self.__rpc_dispatcher.url
        temp_data["keys"] = self.__credential_store
        with open(self.__config_filename, "w+") as cfg_file:
            cfg_file.write(json.dumps(temp_data))

    def __discover_dispatcher(self):
        response = requests.get(f"{CENTRUM}/v1/dispatchers")
        if response.status_code == 200:
            dispatcher_list = response.json()
            for candidate in dispatcher_list:
                try:
                    temp_dispatcher = Dispatcher(candidate)
                    self.__hprose_client = self.__establish_connection(temp_dispatcher)
                    self.__rpc_dispatcher = temp_dispatcher                
                    break
                except Exception:
                    continue
            if self.__rpc_dispatcher is None:
                raise Exception("no dispatchers available")   
        else:
            raise Exception("unable to connect to centrum")

    def __establish_connection(self, dispatcher: Dispatcher) -> hprose.HproseHttpClient:
        return hprose.HttpClient(uri=dispatcher.rpc())

    def __read_task_file(self, filepath: str) -> str:
        with open(filepath, "r") as task_file:
            content = task_file.read()
        return content

