# MFA authentication module using OneLogin API

import time
from datetime import datetime, timedelta
from typing import List, Optional
from onelogin.api.models.user import User
from onelogin.api.models.otp_device import OTP_Device
from onelogin.api.models.factor_enrollment_response import FactorEnrollmentResponse
from onelogin.api.client import OneLoginClient
from .exceptions import (
    FactorNotFound,
    OneLoginClientError,
    APIResponseError,
    UserNotFound,
    TimeOutError
)

class Authenticator:
    # Polling configuration for push verification
    PUSH_POLL_INTERVAL = 5      # seconds between checks
    PUSH_MAX_WAIT_TIME = 60     # maximum wait time in seconds

    def __init__(self, client_id: str, client_secret: str, region: str = "us", user_attr: str = "username"):
        self._client_id = client_id
        self._client_secret = client_secret
        self._region = region
        self._user_attr = user_attr
        self._client = OneLoginClient(self._client_id, self._client_secret, self._region)
        self._validate_connection()

    def _validate_connection(self) -> None:
        if not self._client.get_access_token():
            raise OneLoginClientError(self._client.error_description)

    def _find_user(self, identifier: str) -> User:
        search_params = {self._user_attr: identifier, "fields": "id"}
        users_list = self._client.get_users(search_params)

        if users_list is None:
            raise APIResponseError(self._client.error_description)
        elif len(users_list) > 1:
            raise APIResponseError(
                f"Multiple users matched for {identifier} using attribute {self._user_attr}"
            )
        elif not users_list:
            raise UserNotFound(f"No user found matching {identifier} with attribute {self._user_attr}")

        return users_list[0]

    def _obtain_primary_factor(self, username: str) -> OTP_Device:
        enrolled_factors = self.get_enrolled_factors(username)
        primary_factor = next((f for f in enrolled_factors if f.default), None)

        if primary_factor is None:
            raise FactorNotFound("No default MFA factor configured")

        return primary_factor

    def _initiate_factor_activation(self, user_id: int, factor_id: int, 
                                    validity_period: Optional[int] = None) -> FactorEnrollmentResponse:
        result = self._client.activate_factor(user_id, factor_id, expires_in=validity_period)
        if result is None:
            raise APIResponseError(self._client.error_description)
        return result

    def get_active_factors(self, username: str) -> List[OTP_Device]:
        user_record = self._find_user(username)
        factors = self._client.get_enrolled_factors(user_record.id)

        if factors is None:
            raise APIResponseError(self._client.error_description)

        return factors

    def verify_otp_code(self, username: str, code: str, factor_id: Optional[int] = None) -> bool:
        user_record = self._find_user(username)
        selected_factor_id = factor_id or self._obtain_primary_factor(username).id
        return self._client.verify_factor(user_record.id, selected_factor_id, code)

    def request_push_verification(self, username: str, factor_id: Optional[int] = None) -> bool:
        user_record = self._find_user(username)
        selected_factor_id = factor_id or self._obtain_primary_factor(username).id

        activation = self._initiate_factor_activation(
            user_record.id, 
            selected_factor_id, 
            validity_period=self.PUSH_MAX_WAIT_TIME
        )

        deadline = datetime.now() + timedelta(seconds=self.PUSH_MAX_WAIT_TIME)

        while datetime.now() < deadline:
            response = self._client.verify_factor_poll(user_record.id, activation.id)

            if response.status == "pending":
                time.sleep(self.PUSH_POLL_INTERVAL)
                continue
            elif response.status == "accepted":
                return True
            elif response.status == "rejected":
                return False
            else:
                raise APIResponseError(f"Unexpected push status received: {response.status}")

        raise TimeOutError("Push verification request expired")

from django.test import TestCase
from django.contrib.auth import get_user_model
from core import models

def create_test_user(email='<EMAIL>', password='REDACTED_CREDENTIAL'):
    """Helper function to generate a test user"""
    return get_user_model().objects.create_user(email, password)

def create_test_restaurant(name="Samdard"):
    """Helper function to generate a test restaurant"""
    return models.Restaurant.objects.create(
        name=name
    )

def create_test_menu(name="Dish 2", items='Rice 2, Matton 3, Beef 3, Salad 3'):
    """Helper function to generate a test menu"""
    return models.Menu.objects.create(
        name=name,
        restaurant=create_test_restaurant(),
        items=items
    )

class ModelTests(TestCase):
    def test_user_creation_with_email_success(self):
        """Verify that creating a new user with email works correctly"""
        email = '<EMAIL>'
        password = 'REDACTED_CREDENTIAL'
        user = get_user_model().objects.create_user(
            email=email,
            password=password
        )
        self.assertEqual(user.email, email)
        self.assertTrue(user.check_password(password))

    def test_email_normalization_on_user_creation(self):
        """Ensure email addresses are normalized (lowercased) upon user creation"""
        email = '<EMAIL>'
        user = get_user_model().objects.create_user(email, 'test@1234')
        self.assertEqual(user.email, email.lower())

    def test_user_creation_without_email_fails(self):
        """Confirm that attempting to create a user without email raises ValueError"""
        with self.assertRaises(ValueError):
            get_user_model().objects.create_user(None, 'test@1234')

    def test_superuser_creation(self):
        """Validate creation of superuser with correct permissions"""
        user = get_user_model().objects.create_superuser(
            '<EMAIL>',
            'test@1234'
        )
        self.assertTrue(user.is_superuser)
        self.assertTrue(user.is_staff)

    def test_restaurant_string_representation(self):
        """Check that restaurant's string representation matches its name"""
        restaurant = models.Restaurant.objects.create(
            name='Star Kabab'
        )
        self.assertEqual(str(restaurant), restaurant.name)

    def test_menu_string_representation(self):
        """Check that menu's string representation matches its name"""
        menu = models.Menu.objects.create(
            name='Dish 1',
            restaurant=create_test_restaurant(),
            items='Rice, Matton, Beef, Salad'
        )
        self.assertEqual(str(menu), menu.name)

    def test_vote_instance_creation(self):
        """Verify vote instance can be created and has valid ID"""
        vote = models.Vote.objects.create(
            user=create_test_user(),
            menu=create_test_menu()
        )
        self.assertIsNotNone(vote.id)

