@pytest.mark.parametrize("test_case", test_cases)
def test_secret_content_detection(image, exec_context, secrets_gate, test_case):
    # Create trigger with parameters from test case
    trigger = secrets.SecretContentChecksTrigger(
        parent_gate_cls=secrets.SecretCheckGate, 
        **test_case["params"]
    )

    # Prepare gate context with image data
    secrets_gate.prepare_context(image, exec_context)

    # Execute trigger and verify it fires correctly
    assert trigger.execute(image, exec_context)

    # Verify firing behavior matches expectations
    if test_case["should_fire"]:
        assert trigger.did_fire
        actual_messages = {fired.msg for fired in trigger.fired}
        expected_messages = set(test_case["expected_messages"])
        assert expected_messages == actual_messages
    else:
        assert not trigger.did_fire
        assert len(trigger.fired) == 0

