class GsRiskApi(RiskApi):
    @classmethod
    def calc_multi(cls, requests: Iterable[RiskRequest]) -> Tuple[Union[dict, str], ...]:
        requests = tuple(requests)
        results = cls._execute_batch(requests)
        if len(results) < len(requests):
            raise RuntimeError('Missing results')
        return tuple(cls.__process_result(request, result) for request, result in zip(requests, results))

    @classmethod
    def calc(cls, request: RiskRequest) -> Union[Iterable, str]:
        return cls.__process_result(request, cls._execute_single(request))

    @classmethod
    def _execute_single(cls, request: RiskRequest) -> dict:
        return GsSession.current._post(cls.__build_url(request), request, timeout=180)

    @classmethod
    def _execute_batch(cls, requests: Iterable[RiskRequest]) -> Iterable:
        return GsSession.current._post(cls.__build_url(requests), tuple(requests), timeout=180)

    @classmethod
    def __process_result(cls, request: RiskRequest, result: Union[Iterable, dict]) -> Union[dict, str]:
        return cls._handle_results(request, result) if request.waitForResults else result['reportId']

    @classmethod
    def __build_url(cls, request: Union[RiskRequest, Iterable[RiskRequest]]) -> str:
        is_bulk = not isinstance(request, RiskRequest)
        has_derived_instruments = any(hasattr(pos.instrument, '_derived_type') 
                                      for pos in chain.from_iterable(r.positions 
                                      for r in (request if is_bulk else (request,))))

        path_suffix = '-internal' if has_derived_instruments else ''
        endpoint_suffix = '/bulk' if is_bulk else ''

        return f'/risk{path_suffix}/calculate{endpoint_suffix}'

    @classmethod
    def __handle_missing(cls,
                        id_map: Mapping[str, RiskRequest],
                        outcome_map: Mapping[RiskRequest, Union[Exception, dict]],
                        error_msg: str):
        for req_id, request in id_map.items():
            if request not in outcome_map:
                outcome_map[request] = RuntimeError(error_msg)

    @classmethod
    def get_results(cls, id_map: Mapping[str, RiskRequest], poll: bool, timeout: Optional[int] = None)\
            -> Mapping[RiskRequest, Union[Exception, dict]]:
        if not poll:
            return cls.poll_for_results(id_map, timeout=timeout)

        deadline = dt.datetime.now() + dt.timedelta(seconds=timeout) if timeout else None
        session = GsSession.current
        request_ids = tuple(id_map.keys())
        total_count = len(request_ids)
        endpoints = {rid: f'/risk/calculate/{rid}/results' for rid in request_ids}
        outcomes = {}

        while len(outcomes) < total_count:
            for req_id, endpoint in endpoints.items():
                if req_id in outcomes:
                    continue
                response = session._get(endpoint)
                if isinstance(response, list):
                    outcomes[id_map[req_id]] = cls._handle_results(id_map[req_id], response)

            if deadline and dt.datetime.now() > deadline:
                cls.__handle_missing(id_map, outcomes, "Timed out")
                return outcomes

            time.sleep(2)
        return outcomes

    @classmethod
    def poll_for_results(cls, id_map: Mapping[str, RiskRequest], timeout: Optional[int] = None)\
            -> Mapping[RiskRequest, Union[Exception, dict]]:
        max_retries = 5
        send_timeout_sec = 10
        outcomes = {}

        async def fetch_results():
            last_error = 'Unknown'
            retry_count = 0

            async def attempt_fetch():
                async with GsSession.current._connect_websocket('/risk/calculate/results/subscribe') as ws:
                    pending_ids = [k for k in id_map.keys() if k not in outcomes]
                    await asyncio.wait_for(ws.send(json.dumps(pending_ids)), timeout=send_timeout_sec)

                    while len(outcomes) < len(id_map):
                        raw_response = await asyncio.wait_for(ws.recv(), timeout=timeout)
                        parts = raw_response.split(';')
                        result_id = parts[0]
                        payload = ';'.join(parts[1:])
                        content = payload[1:]
                        is_failure = not payload.startswith(r'R[')

                        try:
                            if is_failure:
                                outcomes[id_map[result_id]] = RuntimeError(content)
                            else:
                                outcomes[id_map[result_id]] = cls._handle_results(
                                    id_map[result_id], json.loads(content))
                        except json.decoder.JSONDecodeError:
                            outcomes[id_map[result_id]] = RuntimeError(content)

            while len(outcomes) < len(id_map) and retry_count < max_retries:
                if retry_count > 0:
                    await asyncio.sleep(math.pow(2, retry_count))
                    _logger.error('{} error, retrying (attempt {} of {})'.format(last_error, retry_count + 1, max_retries))

                try:
                    await attempt_fetch()
                except ConnectionClosedError as cce:
                    last_error = 'Connection failed: ' + str(cce)
                    retry_count += 1
                except asyncio.TimeoutError:
                    last_error = 'Timed out'
                    retry_count = max_retries
                except Exception as e:
                    last_error = str(e)
                    retry_count = max_retries

            if len(outcomes) < len(id_map):
                cls.__handle_missing(id_map, outcomes, last_error)

        asyncio.run(fetch_results())
        return outcomes

