# Type III Clone: Restructured logic with equivalent functionality
from VirgilSDK import identity, virgilcard
from VirgilSDK.virgil_crypto.cryptolib import *
from VirgilSDK.helper import *
from VirgilSDK.api import *

class PrivateKey(VirgilClient):
    # Store a private key in the private keys service
    # Parameters remain semantically identical but renamed for clarity
    def store_private_key(self, pk_service_pub_key, pk_service_card_id, priv_key_b64, card_id, key_passphrase):
        api_path = '/private-key'
        req_uuid = Helper.generate_id()
        auth_headers = {
            'X-VIRGIL-ACCESS-TOKEN': self.token,
            'X-VIRGIL-REQUEST-ID': req_uuid
        }

        payload_body = {
            'private_key': priv_key_b64,
            'virgil_card_id': card_id
        }

        json_payload = Helper.json_dumps(payload_body)
        secured_payload = CryptoWrapper.encrypt(json_payload, str(pk_service_card_id), pk_service_pub_key)

        signing_material = req_uuid + json_payload
        digital_sig = CryptoWrapper.sign(signing_material, priv_key_b64, key_passphrase)

        auth_headers['X-VIRGIL-REQUEST-SIGN'] = base64.b64encode(bytearray(digital_sig))

        encrypted_data = base64.b64encode(bytearray(secured_payload)).decode()
        return self._api_request('POST', api_path, auth_headers, encrypted_data).decode()

    # Retrieve an existing private key using cryptographic handoff
    # Parameters preserved with semantic equivalence
    def retrieve_private_key(self, pk_service_pub_key, pk_service_card_id, ident_type, ident_value, validation_token, decrypt_pass, card_id):
        api_path = '/private-key/actions/grab'
        headers = {'X-VIRGIL-ACCESS-TOKEN': self.token}

        identity_info = {
            "type": ident_type,
            'value': ident_value,
            'validation_token': validation_token
        }

        request_body = {
            'identity': identity_info,
            'response_password': <PASSWORD>,
            'virgil_card_id': card_id
        }

        json_req = Helper.json_dumps(request_body)
        encrypted_req = CryptoWrapper.encrypt(json_req, str(pk_service_card_id), pk_service_pub_key)

        encrypted_resp = self._api_request(
            'POST', 
            api_path, 
            headers, 
            base64.b64encode(bytearray(encrypted_req)).decode()
        )

        try:
            decrypted_bytes = CryptoWrapper.decrypt_with_password(encrypted_resp, decrypt_pass)
            return Helper.json_loads(bytearray(decrypted_bytes))
        except ValueError:
            return encrypted_resp

    # Remove a stored private key from the service
    # Parameters maintained with equivalent semantics
    def remove_private_key(self, pk_service_pub_key, pk_service_card_id, priv_key_b64, card_id, key_passphrase):
        api_path = '/private-key/actions/delete'
        req_uuid = Helper.generate_id()
        auth_headers = {
            'X-VIRGIL-ACCESS-TOKEN': self.token,
            'X-VIRGIL-REQUEST-ID': req_uuid
        }

        payload = {'virgil_card_id': card_id}
        json_payload = Helper.json_dumps(payload)
        secured_payload = CryptoWrapper.encrypt(json_payload, str(pk_service_card_id), pk_service_pub_key)

        signing_input = req_uuid + json_payload
        digital_signature = CryptoWrapper.sign(signing_input, priv_key_b64, key_passphrase)

        auth_headers['X-VIRGIL-REQUEST-SIGN'] = base64.b64encode(bytearray(digital_signature))

        encrypted_data = base64.b64encode(bytearray(secured_payload)).decode()
        return self._api_request('POST', api_path, auth_headers, encrypted_data).decode()

import re
import json
from genie.metaparser import MetaParser

# ====================
# Schema for:
#  * 'show platform software fed switch active inject cause summary'
# ====================
class ShowPlatformSchema(MetaParser):
    """show platform software fed switch active inject cause summary"""
    schema = {
        "cause": {
            int: {
                "description": str,
                "received_count": int,
                "is_dropped": bool
            }
        }
    }

# ====================
# Parser for:
#  * 'show_platform_software_fed_switch_active_inject_cause_summary'
# ====================
class ShowPlatformSoftwareFed(ShowPlatformSchema):
    """show platform software fed switch active inject cause summary"""

    cli_command = 'show platform software fed switch active inject cause summary'

    def cli(self, output=None):
        if output is None:
            command_output = self.device.execute(self.cli_command)
        else:
            command_output = output

        parsed_data = {}

        # Pattern to extract cause information from CLI output
        # Matches lines like: "1      L2 control/legacy               1511939              0"
        pattern = re.compile(r"^(?P<cause_id>\d+)\s+(?P<desc>([\S]+\s)+)\s+(?P<count>\d+)\s+(?P<drop_flag>[01])")

        for line in command_output.splitlines():
            stripped_line = line.strip()
            match = pattern.match(stripped_line)

            if match:
                data = match.groupdict()

                cause_key = int(data['cause_id'])
                cause_entry = parsed_data.setdefault('cause', {}).setdefault(cause_key, {})

                # Normalize field names to match schema
                cause_entry['description'] = data['desc'].strip()
                cause_entry['received_count'] = int(data['count'])
                cause_entry['is_dropped'] = bool(int(data['drop_flag']))

        return parsed_data

import os
import shutil
import sublime
from .utils import path
from .utils.colors import convert_color_value
from .utils.logging import log, dump
from . import icons

def apply_theme_modifications(settings, replace_existing=False):
    installed_packages = _detect_installed_themes()
    compatible = [] if settings.get("force_mode") else _find_customizable_packages()

    base_modification = _build_base_patch(settings)
    specific_modification = _build_specialized_patch(settings)

    base_dir = path.overlay_patches_general_path()
    specific_dir = path.overlay_patches_specific_path()

    color_scheme = "single" if settings.get("color") else "multi"
    base_destination = os.path.join(base_dir, color_scheme)

    processed_files = set()

    if installed_packages:
        log("Applying theme modifications")
        for pkg_name, theme_list in installed_packages.items():
            if pkg_name in compatible:
                icons.copy_missing(base_dir, specific_dir, pkg_name)
                processed_files.update(
                    _apply_theme_changes(
                        theme_list,
                        os.path.join(specific_dir, pkg_name, color_scheme),
                        specific_modification,
                        replace_existing,
                    )
                )
            else:
                processed_files.update(
                    _apply_theme_changes(theme_list, base_destination, base_modification, replace_existing)
                )
    else:
        log("No themes found to modify!")

    log("Cleaning up outdated theme patches")
    for root, dirs, files in os.walk(path.overlay_patches_path()):
        if root == specific_dir:
            for subdir in set(dirs) - set(compatible):
                full_path = os.path.join(root, subdir)
                shutil.rmtree(full_path, ignore_errors=True)
                dump(full_path)

        for file in files:
            if file.endswith(".sublime-theme"):
                full_file_path = os.path.join(root, file)
                if full_file_path not in processed_files:
                    try:
                        os.remove(full_file_path)
                        dump(full_file_path)
                    except OSError:
                        pass

def _find_customizable_packages():
    log("Identifying theme packages that support customization")
    customizable_set = set()
    for resource in sublime.find_resources(".supports-a-file-icon-customization"):
        if not resource.startswith("Packages/"):
            continue
        parts = resource.split("/")
        if len(parts) >= 3:
            package_name = parts[2]
            customizable_set.add(package_name)
    dump(customizable_set)
    return customizable_set

def _detect_installed_themes():
    log("Scanning for installed themes")
    detected_themes = set()
    theme_mapping = {}

    for resource in sublime.find_resources("*.sublime-theme"):
        if not resource.startswith("Packages/"):
            continue

        parts = resource.split("/")
        if len(parts) < 4:
            continue

        _, package, *_, theme_name = parts
        if package != path.OVERLAY_ROOT:
            if theme_name not in detected_themes:
                detected_themes.add(theme_name)
                theme_mapping.setdefault(package, []).append(theme_name)

    dump(theme_mapping)
    return theme_mapping

def _apply_theme_changes(themes, destination_folder, patch_content, overwrite):
    applied = set()
    file_mode = "w" if overwrite else "x"

    for theme_file in themes:
        try:
            target_path = os.path.join(destination_folder, theme_file)
            applied.add(target_path)
            with open(target_path, file_mode) as f:
                f.write(patch_content)
        except FileExistsError:
            log("Skipped existing `{}`".format(theme_file))
        except Exception as err:
            log("Failed to patch `{}`".format(theme_file))
            dump(err)
        else:
            log("Successfully patched `{}`".format(theme_file))

    return applied

def _build_base_patch(settings):
    log("Constructing general modification template")
    theme_elements = []

    base_color = convert_color_value(settings.get("color"))
    opacity_val = settings.get("opacity")
    icon_config = _create_icon_element(None, base_color, opacity_val)

    size_val = settings.get("size")
    if size_val:
        icon_config["content_margin"] = [size_val, size_val]

    row_padding_val = settings.get("row_padding")
    if row_padding_val:
        icon_config["row_padding"] = row_padding_val

    theme_elements.append(icon_config)

    hover_color = convert_color_value(settings.get("color_on_hover"))
    hover_opacity = settings.get("opacity_on_hover")
    if hover_color or hover_opacity:
        theme_elements.append(_create_icon_element("hover", hover_color, hover_opacity))

    select_color = convert_color_value(settings.get("color_on_select"))
    select_opacity = settings.get("opacity_on_select")
    if select_color or select_opacity:
        theme_elements.append(_create_icon_element("selected", select_color, select_opacity))

    dump(theme_elements)
    return json.dumps(theme_elements)

def _build_specialized_patch(settings):
    log("Constructing specialized modification template")
    theme_elements = []

    primary_color = convert_color_value(settings.get("color"))
    theme_elements.append(_create_icon_element(None, primary_color))

    if primary_color:
        hover_color = convert_color_value(settings.get("color_on_hover"))
        if hover_color:
            theme_elements.append(_create_icon_element("hover", hover_color))

        select_color = convert_color_value(settings.get("color_on_select"))
        if select_color:
            theme_elements.append(_create_icon_element("selected", select_color))

    dump(theme_elements)
    return json.dumps(theme_elements)

def _create_icon_element(attribute=None, color=None, opacity=None):
    icon_data = {"class": "icon_file_type", "layer0.tint": color}

    if attribute:
        icon_data["parents"] = [{"class": "tree_row", "attributes": [attribute]}]

    if opacity is not None:
        icon_data["layer0.opacity"] = opacity

    return icon_data

# Module: Calendar Bounds Explorer
# Purpose: Determine valid date ranges for exchange calendar instantiation.
# Retained for potential future utility in evaluating factory constraints.

from __future__ import annotations
import dataclasses
import abc
import pathlib
import pickle
from typing import Literal, Type
import pandas as pd
import exchange_calendars as xcals

@dataclasses.dataclass
class CalendarConstraints:
    """Valid operational limits for an ExchangeCalendar instance.

    Parameters
    ----------
    identifier :
        Unique name of the calendar under analysis.
    min_start :
        Earliest permissible start date (with end set to tomorrow).
    min_start_issue :
        Exception encountered when attempting a calendar with min_start - 1 day.
    max_end :
        Latest permissible end date (with start set to yesterday).
    max_end_issue :
        Exception encountered when attempting a calendar with max_end + 1 day.
    """
    identifier: str
    min_start: pd.Timestamp
    min_start_issue: Exception
    max_end: pd.Timestamp
    max_end_issue: Exception

class _CalendarRangeAnalyzer:
    """Determine safe start and end boundaries for a given calendar factory."""

    def __init__(self, factory_class: xcals.ExchangeCalendar, verbose: bool = False):
        self.factory_class = factory_class
        self.verbose = verbose
        self._last_exception: Exception | None = None

    @property
    def calendar_id(self) -> str:
        """Return the calendar's identifier."""
        if isinstance(self.factory_class.name, str):
            return self.factory_class.name
        else:
            return self.factory_class().name

    @property
    def current_date(self) -> pd.Timestamp:
        return pd.Timestamp.now(tz="UTC").normalize()

    def _instantiate_calendar(
        self,
        start: pd.Timestamp | None = None,
        end: pd.Timestamp | None = None,
    ) -> xcals.ExchangeCalendar:
        """Create a calendar instance using provided or default bounds."""
        if self.verbose:
            info = f"start={start}" if start is not None else f"end={end}"

        if start is None and end is None:
            raise ValueError("At least one of 'start' or 'end' must be specified.")

        if start is None:
            start = self.current_date - pd.Timedelta(days=1)
        if end is None:
            end = self.current_date + pd.Timedelta(days=1)

        if self.verbose:
            print(f"Instantiating '{self.calendar_id}' with {info}.")

        return self.factory_class(start=start, end=end)

    def _validate_boundary(
        self, 
        date: pd.Timestamp, 
        boundary_type: Literal["start", "end"]
    ) -> bool:
        """Test whether a given date is acceptable for the specified boundary."""
        kwargs = {boundary_type: date}
        try:
            self._instantiate_calendar(**kwargs)
        except Exception as e:  # pylint: disable=broad-except
            self._last_exception = e
            return False
        else:
            return True

    def _search_valid_boundary(
        self,
        reference_date: pd.Timestamp,
        step_size: pd.DateOffset,
        boundary_type: Literal["start", "end"]
    ) -> pd.Timestamp:
        """Recursively find a valid boundary by stepping through time."""
        if self._validate_boundary(reference_date, boundary_type):
            return reference_date

        next_date = reference_date + step_size

        # Check if search has crossed today
        if (
            (reference_date <= self.current_date < next_date) or
            (reference_date >= self.current_date > next_date)
        ):
            return self.current_date

        return self._search_valid_boundary(next_date, step_size, boundary_type)

    @property
    def _initial_step(self) -> pd.DateOffset:
        return pd.DateOffset(years=100)

    def _is_initial_step(self, step: pd.DateOffset) -> bool:
        return step == self._initial_step or -step == self._initial_step

    def _step_sequence(
        self, 
        boundary_type: Literal["start", "end"]
    ) -> abc.Iterator[pd.DateOffset]:
        """Generate decreasing step sizes for binary-like search."""
        direction = 1 if boundary_type == "start" else -1
        steps = [
            direction * self._initial_step,
            direction * pd.DateOffset(years=30),
            direction * pd.DateOffset(years=10),
            direction * pd.DateOffset(years=3),
            direction * pd.DateOffset(years=1),
            direction * pd.DateOffset(months=3),
            direction * pd.DateOffset(months=1),
            direction * pd.DateOffset(days=10),
            direction * pd.DateOffset(days=3),
            direction * pd.DateOffset(days=1),
        ]
        return iter(steps)

    def _is_exact_boundary(
        self, 
        date: pd.Timestamp, 
        boundary_type: Literal["start", "end"]
    ) -> bool:
        """Check if date is the exact boundary point."""
        if not self._validate_boundary(date, boundary_type):
            return False

        adjustment = pd.Timedelta(days=1 if boundary_type == "end" else -1)
        test_date = date + adjustment
        return not self._validate_boundary(test_date, boundary_type)

    def _probe_known_limits(
        self, 
        boundary_type: Literal["start", "end"]
    ) -> tuple[pd.Timestamp, Exception] | None:
        """Check specific known problematic dates that often cause issues."""
        if boundary_type == "start":
            candidates = [
                pd.Timestamp("1678-01-01", tz="UTC"),
                pd.Timestamp("1679-01-01", tz="UTC"),
            ]
        else:
            candidates = [
                pd.Timestamp("2260-12-31", tz="UTC"),
                pd.Timestamp("2262-04-10", tz="UTC"),
            ]

        for candidate in candidates:
            if self._is_exact_boundary(candidate, boundary_type):
                assert self._last_exception is not None
                return (candidate, self._last_exception)

        return None

    @staticmethod
    def _boundary_origin(boundary_type: Literal["start", "end"]) -> pd.Timestamp:
        """Return initial extreme value for boundary search."""
        if boundary_type == "start":
            return pd.Timestamp.min.ceil("D").tz_localize("UTC")
        else:
            return pd.Timestamp.max.floor("D").tz_localize("UTC")

    def _determine_boundary(
        self, 
        boundary_type: Literal["start", "end"]
    ) -> tuple[pd.Timestamp, Exception]:
        """Find the precise boundary for the given type."""
        self._last_exception = None
        origin = self._boundary_origin(boundary_type)

        try:
            assert not self._is_exact_boundary(origin, boundary_type)
        except pd.errors.OutOfBoundsDatetime as err:
            return (origin, err)

        steps = self._step_sequence(boundary_type)
        current_step = next(steps, None)
        probe_point = origin

        while current_step is not None:
            probe_point += current_step

            valid_date = self._search_valid_boundary(
                probe_point, current_step, boundary_type
            )

            if valid_date == probe_point and self._is_initial_step(current_step):
                shortcut = self._probe_known_limits(boundary_type)
                if shortcut is not None:
                    return shortcut

            probe_point = valid_date - current_step

            try:
                current_step = next(steps)
            except StopIteration:
                break

        return (valid_date, self._last_exception)

    def analyze(self) -> CalendarConstraints:
        """Compute and return the full boundary constraints."""
        start_limit = self._determine_boundary("start")
        end_limit = self._determine_boundary("end")
        return CalendarConstraints(
            self.calendar_id, 
            *start_limit, 
            *end_limit
        )

def get_calendar_constraints(
    factory_class: xcals.ExchangeCalendar, 
    verbose: bool = False
) -> CalendarConstraints:
    """Determine operational boundaries for a calendar factory.

    Parameters
    ----------
    factory_class :
        ExchangeCalendar subclass to evaluate.
    verbose :
        Enable detailed logging during boundary determination.

    Returns
    -------
    CalendarConstraints:
        Data structure containing boundary information and error details.
    """
    return _CalendarRangeAnalyzer(factory_class, verbose).analyze()

def _compile_all_calendar_constraints(verbose: bool = False) -> dict[str, CalendarConstraints]:
    """Analyze all available calendars and compile their constraints."""
    results = {}
    for name, factory in xcals.calendar_utils._default_calendar_factories.items():
        results[name] = get_calendar_constraints(factory, verbose)
    return results

def _constraints_resource_path() -> pathlib.PurePath:
    path = pathlib.Path(__file__)
    return pathlib.Path(path.parent, "resources/_calendar_constraints.dat")

def _persist_constraints(constraints: dict[str, CalendarConstraints]):
    """Serialize and store constraint data to disk."""
    assert isinstance(constraints, dict)
    assert len(constraints) > 20
    sample_key = next(iter(constraints))
    assert isinstance(sample_key, str)
    assert isinstance(constraints[sample_key], CalendarConstraints)

    with open(_constraints_resource_path(), "wb") as file:
        pickle.dump(constraints, file)

def _load_constraints() -> dict[str, CalendarConstraints]:
    """Load persisted constraint data from disk."""
    with open(_constraints_resource_path(), "rb") as file:
        return pickle.load(file)

# Load constraints at module initialization
_all_calendar_constraints = _load_constraints()

def _get_constraint_error_types() -> tuple[Type[Exception], ...]:
    """Extract unique exception types across all calendar constraints."""
    error_types = []
    for cal in _all_calendar_constraints.values():
        for error in (cal.min_start_issue, cal.max_end_issue):
            if type(error) not in error_types:
                error_types.append(type(error))
    return tuple(error_types)

def calendar_constraint_summary() -> pd.DataFrame:
    """Return summary DataFrame of all calendar boundaries.

    Returns
    -------
    pd.DataFrame
        Index: calendar names
        Columns:
            earliest_valid_start - earliest acceptable start date
            latest_valid_end     - latest acceptable end date
    """
    df_data = {
        "earliest_valid_start": [c.min_start for c in _all_calendar_constraints.values()],
        "latest_valid_end": [c.max_end for c in _all_calendar_constraints.values()]
    }
    return pd.DataFrame(df_data, index=_all_calendar_constraints.keys())

def fetch_calendar_boundaries(calendar_name: str) -> tuple[pd.Timestamp, pd.Timestamp]:
    """Retrieve start and end boundaries for a specific calendar.

    Returns
    -------
    tuple[pd.Timestamp, pd.Timestamp]
        Valid start and end dates for the named calendar.
    """
    constraints = _all_calendar_constraints[calendar_name]
    return (constraints.min_start, constraints.max_end)

