def execute_container_command(image, entrypoint, *cmd_args):
    """Execute a command inside a Docker container."""
    cmd = f"docker run --entrypoint {entrypoint} --rm {image} {' '.join(cmd_args)}"
    try:
        result = subprocess.check_output(
            cmd,
            stderr=subprocess.STDOUT,
            shell=True
        )
        return result
    except subprocess.CalledProcessError as e:
        print(f"Error executing command: {e.output.decode()}")
        raise

def retrieve_account_key(key_lines, position):
    """Extract and decode a specific key (public or secret) from tezos-client output."""
    line = key_lines[position]
    parts = line.split(b":")
    if len(parts) > position:
        return parts[position].strip().decode("ascii")
    else:
        raise ValueError(f"Could not extract key at position {position}")

def generate_keys_for_docker(image):
    """Generate Tezos keys using the tezos-client in Docker."""
    output = execute_container_command(
        image,
        "sh",
        "-c",
        "'/usr/local/bin/tezos-client --protocol PsDELPH1Kxsx gen keys mykey && /usr/local/bin/tezos-client --protocol PsDELPH1Kxsx show address mykey -S'"
    )
    lines = output.split(b"\n")
    return {
        "public": retrieve_account_key(lines, 1),
        "secret": retrieve_account_key(lines, 2)
    }

def derive_custom_chain_id(length=16):
    """Generate a vanity chain ID using flextesa."""
    seed_chars = string.ascii_uppercase + string.digits
    seed = ''.join(random.choice(seed_chars) for _ in range(length))

    flextesa_image = "registry.gitlab.com/tezos/flextesa:01e3f596-run"
    result = execute_container_command(
        flextesa_image,
        "flextesa",
        "vani",
        '""',
        "--seed", seed,
        "--first",
        "--machine-readable", "csv"
    ).decode("utf-8")

    return result.strip().split(",")[1]

