def parse_arguments():
    """Parse command-line arguments."""
    import argparse

    parser = argparse.ArgumentParser(
        description="Generate Helm values for use with the tezos-chain Helm chart"
    )
    parser.add_argument(
        "--version",
        action="version",
        version=f"%(prog)s {__version__}",
    )
    parser.add_argument("chain_name", action="store", help="Name of your chain")

    for key, config in CHAIN_SETTINGS.items():
        arg_name = "--" + key.replace("_", "-")
        parser.add_argument(arg_name, **config)

    return parser.parse_args()

def main():
    args = parse_arguments()

    # Validate node and baker counts
    if args.number_of_nodes < 1:
        print(f"Invalid argument --number-of-nodes {args.number_of_nodes}, must be 1 or more")
        sys.exit(1)
    if args.number_of_bakers < 1:
        print(f"Invalid argument --number-of-bakers {args.number_of_bakers}, must be 1 or more")
        sys.exit(1)

    # Prepare bootstrap accounts
    baker_names = [f"baker{i}" for i in range(args.number_of_bakers)]

    # Base configuration template
    base_config = {
        "chain_name": args.chain_name,
        "images": {
            "tezos": args.docker_image,
        },
        "genesis": {
            "genesis_chain_id": derive_custom_chain_id(),
            "bootstrap_timestamp": datetime.now(timezone.utc).isoformat(),
        },
        "zerotier_in_use": bool(args.zerotier_network),
        "rpc_auth": args.rpc_auth,
        "zerotier_config": {
            "zerotier_network": args.zerotier_network,
            "zerotier_token": args.zerotier_token,
        },
    }

    # Generate account keys
    account_keys = {"secret": [], "public": []}
    for baker_name in baker_names:
        keys = generate_keys_for_docker(args.docker_image)
        for key_type in keys:
            account_keys[key_type].append({
                "name": baker_name,
                "key": keys[key_type],
                "type": key_type,
            })

    # Define node configurations
    creation_nodes = [
        {"bake_for": f"baker{i}"} for i in range(args.number_of_bakers)
    ] + [{} for _ in range(args.number_of_nodes - args.number_of_bakers)]

    invitation_nodes = [{}]
    bootstrap_peers = [args.bootstrap_peer] if args.bootstrap_peer else []

    # Create full configurations
    creation_config = {
        **base_config,
        "accounts": account_keys["secret"],
        "is_invitation": False,
        "bootstrap_peers": bootstrap_peers,
        "nodes": creation_nodes,
    }

    invitation_config = {
        **base_config,
        "accounts": account_keys["public"],
        "is_invitation": True,
        "bootstrap_peers": bootstrap_peers,
        "nodes": invitation_nodes,
    }

    # Remove RPC auth from invitation config
    invitation_config.pop("rpc_auth", None)

    # Write YAML files
    output_dir = os.path.join(os.getcwd(), args.chain_name)
    creation_file = f"{output_dir}_values.yaml"
    invitation_file = f"{output_dir}_invite_values.yaml"

    with open(creation_file, "w") as f:
        yaml.dump(creation_config, f)
        print(f"Wrote chain creation constants to {creation_file}")

    with open(invitation_file, "w") as f:
        yaml.dump(invitation_config, f)
        print(f"Wrote chain invitation constants to {invitation_file}")

if __name__ == "__main__":
    main()

