    )


def _phase_java_wrapper_impl(
        ctx,
        additional_args,
        startup_script):
    """Generates a shell script wrapper that ensures correct Java binary is used."""
    launcher_prefix = ""
    if not startup_script.strip():
        launcher_prefix = "exec "

    wrapper_file = ctx.actions.declare_file(ctx.label.name + "_wrapper.sh")

    ctx.actions.write(
        output = wrapper_file,
        content = """#!/usr/bin/env bash
{startup}
DEFAULT_JAVABIN={javabin}
JAVA_CMD=${{REAL_EXTERNAL_JAVA_BIN:-$DEFAULT_JAVABIN}}
{launcher}$JAVA_CMD "$@" {args}
""".format(
            startup = startup_script,
            launcher = launcher_prefix,
            javabin = _java_bin(ctx),
            args = additional_args,
        ),
        is_executable = True,
    )
    return wrapper_file

