logger = logging.getLogger(__name__)
config = get_active_config()


class ApiClientBase(object):
    # Time window for date-based queries
    query_window = timedelta(days=1)
    # Unix epoch reference point
    base_epoch = datetime(year=1970, month=1, day=1)

    # Custom transformation rules per field
    transform_rules: Dict[str, str] = {}
    # HTTP headers to be used across requests
    http_headers: Dict[str, str] = {}
    # Query parameters to be applied globally
    query_params: Dict[str, str] = {}

    # Default API root URL
    api_root = config.API_BASE_URL

    def __init__(
        self,
        target_endpoint: Endpoint,
        api_url: str = None,
        **overrides,
    ):
        self.api_root = api_url or self.api_root
        self.target = target_endpoint
        self.http_headers = overrides.get("headers") or self.http_headers
        self.query_params = overrides.get("params") or self.query_params
        self.transform_rules = overrides.get("functions") or self.transform_rules

        self._http_session = None
        self.pending_requests: list = []
        self.received_responses: list = []


class RestApiClient(ApiClientBase):
    query_window = timedelta(days=1)
    base_epoch = datetime(year=1970, month=1, day=1)
    transform_rules: Dict[str, str] = {}
    http_headers: Dict[str, str] = {}
    query_params: Dict[str, str] = {}

    def __init__(
        self,
        api_url: str,
        endpoint: Endpoint,
        functions: dict = None,
        headers: dict = None,
        params: dict = None,
    ):
        super().__init__(
            api_url=api_url,
            target_endpoint=endpoint,
            functions=functions,
            headers=headers,
            params=params,
        )

    def __repr__(self):
        return f"[{self.endpoint_name}] {self.full_url} → {self.model_name}"

    def __iter__(self) -> Generator:
        for req in self.pending_requests:
            yield req

    @property
    def full_url(self) -> str:
        return util.urljoin(self.api_root, self.relative_path)

    @property
    def relative_path(self) -> str:
        return self.target.path

    @property
    def model_name(self) -> str:
        """The data model this client interacts with"""
        return self.target.model

    @property
    def session(self):
        if self._http_session is None:
            self._http_session = requests.Session()
        return self._http_session

    @property
    def s(self):
        """Shorthand for current HTTP session"""
        return self.session

    @session.setter  # type: ignore
    def session(self, new_session):
        self._http_session = new_session

    def apply_transform(
        self,
        rule_key: str,
        arg1: Union[int, str, float] = None,
        arg2: Union[int, str, float] = None,
        arg_list: list = None,
    ) -> str:
        """Generate a URL fragment by applying a registered transformation rule."""
        try:
            if not any([arg1, arg_list]):
                raise ValueError("Either 'arg1' or 'arg_list' must be provided")
            if arg_list:
                arg_list = "".join(str(x) for x in arg_list)
            template = self.transform_rules[rule_key]["template"]
            return template.format(value=arg1, value2=arg2, values=arg_list)
        except KeyError:
            raise KeyError(f"Transformation rule '{rule_key}' not found")
        except Exception as exc:
            raise RuntimeError(f"Failed to apply transform '{rule_key}': {exc}")

    def set_query_param(self, key: str, val: Union[int, str, float]) -> "RestApiClient":
        try:
            self.query_params[key] = str(val)
        except Exception as err:
            raise RuntimeError(f"Could not assign parameter '{key}={val}': {err}")
        return self

    def interpolate(self, **substitutions) -> str:
        try:
            return self.full_url.format(**substitutions)
        except KeyError as ke:
            raise KeyError(f"Missing substitution key(s): {ke} when formatting path '{self.relative_path}'")
        except Exception:
            raise

    def queue_request(
        self,
        extra_headers: dict = None,
        extra_params: dict = None,
        **kwargs,
    ) -> None:
        url = self.interpolate(**kwargs)
        final_headers = {**self.http_headers, **(extra_headers or {})}
        final_params = {**self.query_params, **(extra_params or {})}

        request_obj = Request(method="GET", url=url, headers=final_headers, params=final_params)
        self.pending_requests.append(request_obj)
        logger.debug(f"Added to queue: {request_obj}")
        return request_obj

    def execute_all(self) -> Generator:
        for req in self:
            logger.info(f"Executing request: {req}")
            yield req.execute()

