@click.option("--model", "-m", help="Python module/function used for model.")
@click.option(
    "--address", help="Network address to bind the server.", default="localhost", type=str
)
@click.option("--number", help="Port number for the server.", default=8000, type=int)
def start_server(
    data_file: str,
    model: Optional[str] = None,
    address: str = "localhost",
    number: int = 8000,
):
    """Start lsqfitgui server using a saved fit object.
    Arguments:
        data_file: Path to the pickle file containing the fit object.
        model: Optional function/model specification as a string.
    """
    fit_object = load(data_file)

    if model is not None:
        parsed_model = parse_function(model)
        fit_object.fcn = parsed_model

    if not hasattr(fit_object, "fcn"):
        raise ValueError(
            "Model function missing in loaded fit object."
            " Please provide one via the --model option."
        )

    run_server(fit_object, host=address, port=number)

if __name__ == "__main__":
    start_server()

# Calculate total fuel requirement for all modules

def _calculate_fuel_recursive(mass):
    # Compute fuel for current mass
    required_fuel = mass // 3 - 2
    if required_fuel <= 0:
        return 0
    # Add fuel needed for the fuel itself
    return required_fuel + _calculate_fuel_recursive(required_fuel)

def main():
    total_fuel = 0
    # Read input file line by line
    with open('input/1', 'r') as file:
        for line in file:
            module_mass = int(line.strip())
            total_fuel += _calculate_fuel_recursive(module_mass)
    print(total_fuel)

if '__main__' == __name__:
    main()

from FDmisc import Len, FuncDesignerException, DiagonalType, scipyAbsentMsg, pWarn, scipyInstalled, Diag, \
Copy, Eye, isPyPy, isspmatrix
from baseClasses import OOFun, Stochastic
from numpy import isscalar, ndarray, atleast_2d, prod, int64, asarray, ones_like, array_equal, asscalar
import numpy as np
from multiarray import multiarray
from ooPoint import ooPoint

try:
    from DerApproximator import get_d1
    DerApproximatorIsInstalled = True
except ImportError:
    DerApproximatorIsInstalled = False


def _D(Self, x, fixedVarsScheduleID, Vars=None, fixedVars=None, useSparse='auto'):
    # Early exit if variable is fixed or not in scope
    if Self.is_oovar:
        if (fixedVars and Self in fixedVars) or (Vars and Self not in Vars):
            return {}
        tmp = x[Self]
        eye_or_ones = Eye(asarray(tmp).size) if not isinstance(tmp, multiarray) else ones_like(tmp).view(multiarray)
        return {Self: eye_or_ones}

    # Fixed oofun case
    if Self.input[0] is None:
        return {}

    # Discrete variables have no derivative
    if Self.discrete:
        return {}

    # Check point identity and variable schedule consistency
    CondSamePointByID = isinstance(x, ooPoint) and Self._point_id1 == x._id
    sameVarsScheduleID = fixedVarsScheduleID == Self._lastDiffVarsID

    dep = Self._getDep()
    rebuildFixedCheck = not sameVarsScheduleID

    if rebuildFixedCheck:
        Self._isFixed = (fixedVars and dep.issubset(fixedVars)) or (Vars and dep.isdisjoint(Vars))
    if Self._isFixed:
        return {}

    involveStore = Self.isCostly

    cond_same_point = sameVarsScheduleID and (
        (CondSamePointByID and Self._d_val_prev is not None) or
        (involveStore and Self._d_key_prev is not None and all(
            array_equal(x[elem], Self._d_key_prev[elem]) for elem in dep
        ))
    )

    if cond_same_point:
        Self.same_d += 1
        return dict((key, Copy(val)) for key, val in Self._d_val_prev.items())
    else:
        Self.evals_d += 1

    if isinstance(x, ooPoint):
        Self._point_id1 = x._id
    if fixedVarsScheduleID != -1:
        Self._lastDiffVarsID = fixedVarsScheduleID

    derivativeSelf = Self._getDerivativeSelf(x, fixedVarsScheduleID, Vars, fixedVars)
    result = Derivative()

    def process_input(i, inp):
        nonlocal ac
        if not isinstance(inp, OOFun):
            return
        if inp.discrete:
            return
        if inp.is_oovar:
            if (Vars and inp not in Vars) or (fixedVars and inp in fixedVars):
                return
            ac += 1
            tmp = derivativeSelf[ac]
            existing = result.get(inp)
            if existing is not None:
                if isscalar(tmp) or (type(existing) == type(tmp) == ndarray and prod(tmp.shape) <= prod(existing.shape)):
                    result[inp] += tmp
                else:
                    if isspmatrix(existing) and type(tmp) == DiagonalType:
                        tmp = tmp.resolve(True)
                    result[inp] = existing + tmp
            else:
                result[inp] = tmp
        else:
            ac += 1
            elem_d = inp._D(x, fixedVarsScheduleID, Vars=Vars, fixedVars=fixedVars, useSparse=useSparse)
            t1 = derivativeSelf[ac]

            for key, val in elem_d.items():
                rr = _compute_product(t1, val, useSparse)

                existing = result.get(key)
                if existing is not None:
                    result[key] = _merge_derivatives(rr, existing, useSparse)
                else:
                    result[key] = rr

    ac = -1
    for i, inp in enumerate(Self.input):
        process_input(i, inp)

    # Cache results
    Self._d_val_prev = dict((key, Copy(value)) for key, value in result.items())
    if involveStore:
        Self._d_key_prev = dict((elem, Copy(x[elem])) for elem in dep)
    return result


def _compute_product(t1, val, useSparse):
    """Compute product t1 * val with special handling for diagonals, scalars, and sparse matrices."""
    if isinstance(t1, Stochastic) or isinstance(val, Stochastic):
        return t1 * val
    elif isinstance(val, Stochastic):
        return val * t1
    elif type(t1) == DiagonalType and type(val) == DiagonalType:
        return t1 * val
    elif type(t1) == DiagonalType or type(val) == DiagonalType:
        if isspmatrix(t1):
            return t1._mul_sparse_matrix(val.resolve(True))
        else:
            if not isPyPy or type(val) != DiagonalType:
                return t1 * val
            else:
                return (val * t1.T).T
    elif isscalar(val) or isscalar(t1) or prod(t1.shape) == 1 or prod(val.shape) == 1:
        scalar_t1 = t1 if isscalar(t1) or prod(t1.shape) > 1 else asscalar(t1) if isinstance(t1, ndarray) else t1[0, 0]
        scalar_val = val if isscalar(val) or prod(val.shape) > 1 else asscalar(val) if isinstance(val, ndarray) else val[0, 0]
        return scalar_t1 * scalar_val
    else:
        if val.ndim < 2:
            val = atleast_2d(val)
        t1_arr, t2_arr = considerSparse(t1, val) if useSparse is not False else (t1, val)

        if not (type(t1_arr) == type(t2_arr) == ndarray):
            if not scipyInstalled:
                pWarn(scipyAbsentMsg)
                return np.dot(t1_arr, t2_arr)
            else:
                from scipy.sparse import isspmatrix_csc, isspmatrix_csr, csc_matrix, csr_matrix
                t1_arr = t1_arr if isspmatrix_csc(t1_arr) else (t1_arr.tocsc() if isspmatrix(t1_arr) else csc_matrix(t1_arr))
                t2_arr = t2_arr if isspmatrix_csr(t2_arr) else (t2_arr.tocsr() if isspmatrix(t2_arr) else csr_matrix(t2_arr))
                if t2_arr.shape[0] != t1_arr.shape[1]:
                    if t2_arr.shape[1] == t1_arr.shape[1]:
                        t2_arr = t2_arr.T
                    else:
                        raise FuncDesignerException('incorrect shape in FuncDesigner function _D(), inform developers about the bug')
                rr = t1_arr._mul_sparse_matrix(t2_arr)
                return rr.toarray() if useSparse is False else rr
        else:
            return np.dot(t1_arr, t2_arr)


def _merge_derivatives(rr, existing, useSparse):
    """Merge new derivative component into existing one."""
    if type(rr) == DiagonalType:
        if type(existing) == DiagonalType:
            return existing + rr
        else:
            tmp = rr.resolve(useSparse)
            if isinstance(tmp, ndarray) and hasattr(existing, 'toarray'):
                existing = existing.toarray()
            if type(tmp) == type(existing) == ndarray and existing.size >= tmp.size:
                existing += tmp
            else:
                existing = existing + tmp
    else:
        if isinstance(existing, ndarray) and hasattr(rr, 'toarray'):
            rr = rr.toarray()
        elif hasattr(existing, 'toarray') and isinstance(rr, ndarray):
            existing = existing.toarray()
        if type(rr) == type(existing) == ndarray and rr.size == existing.size:
            existing += rr
        else:
            existing = existing + rr
    return existing


def getDerivativeSelf(Self, x, fixedVarsScheduleID, Vars, fixedVars):
    Input = Self._getInput(x, fixedVarsScheduleID=fixedVarsScheduleID, Vars=Vars, fixedVars=fixedVars)
    expectedTotalInputLength = sum(map(Len, Input))

    hasUserSuppliedDerivative = Self.d is not None
    if hasUserSuppliedDerivative:
        if type(Self.d) == tuple:
            if len(Self.d) != len(Self.input):
                raise FuncDesignerException('oofun error: num(derivatives) not equal to neither 1 nor num(inputs)')
            derivativeSelf = []
            for i, deriv in enumerate(Self.d):
                inp = Self.input[i]
                if not isinstance(inp, OOFun) or inp.discrete:
                    continue
                if inp.is_oovar and ((Vars and inp not in Vars) or (fixedVars and inp in fixedVars)):
                    continue
                if deriv is None:
                    if not DerApproximatorIsInstalled:
                        raise FuncDesignerException('To perform gradients check you should have DerApproximator installed, see http://openopt.org/DerApproximator')
                    derivativeSelf.append(get_d1(Self.fun, Input, diffInt=Self.diffInt, stencil=Self.stencil,
                                                 args=Self.args, varForDifferentiation=i, pointVal=Self._getFuncCalcEngine(x), exactShape=True))
                else:
                    tmp = deriv(*Input)
                    if not isscalar(tmp) and type(tmp) in (ndarray, tuple, list) and type(tmp) != DiagonalType:
                        tmp = atleast_2d(tmp)
                        _tmp = Input[i]
                        Tmp = 1 if isscalar(_tmp) or prod(_tmp.shape) == 1 else len(Input[i])
                        if tmp.shape[1] != Tmp:
                            if tmp.shape[0] != Tmp:
                                raise FuncDesignerException('error in getDerivativeSelf()')
                            tmp = tmp.T
                    derivativeSelf.append(tmp)
        else:
            tmp = Self.d(*Input)
            if not isscalar(tmp) and type(tmp) in (ndarray, tuple, list):
                tmp = atleast_2d(tmp)
                if tmp.shape[1] != expectedTotalInputLength:
                    if tmp.shape[0] != expectedTotalInputLength:
                        raise FuncDesignerException('error in getDerivativeSelf()')
                    tmp = tmp.T
            if isinstance(tmp, ndarray) and hasattr(tmp, 'toarray') and not isinstance(tmp, multiarray):
                tmp = tmp.A

            if len(Input) == 1:
                derivativeSelf = [tmp]
            else:
                derivativeSelf = []
                ac = 0
                for i, inp in enumerate(Input):
                    t = Self.input[i]
                    if t.discrete or (t.is_oovar and ((Vars and t not in Vars) or (fixedVars and t in fixedVars))):
                        ac += inp.size
                        continue
                    if isinstance(tmp, ndarray):
                        TMP = tmp[:, ac:ac + Len(inp)]
                    elif isscalar(tmp):
                        TMP = tmp
                    elif type(tmp) == DiagonalType:
                        if tmp.size == inp.size and ac == 0:
                            TMP = tmp
                        else:
                            if inp.size > 150 and tmp.size > 150:
                                tmp = tmp.resolve(True).tocsc()
                            else:
                                tmp = tmp.resolve(False)
                            TMP = tmp[:, ac:ac + inp.size]
                    else:
                        TMP = tmp.tocsc()[:, ac:ac + inp.size]
                    ac += Len(inp)
                    derivativeSelf.append(TMP)
    else:
        if Vars is not None or (fixedVars and len(fixedVars) != 0):
            raise FuncDesignerException("sorry, custom oofun derivatives don't work with Vars/fixedVars arguments yet")
        if not DerApproximatorIsInstalled:
            raise FuncDesignerException('To perform this operation you should have DerApproximator installed, see http://openopt.org/DerApproximator')
        derivativeSelf = get_d1(Self.fun, Input, diffInt=Self.diffInt, stencil=Self.stencil,
                                args=Self.args, pointVal=Self._getFuncCalcEngine(x), exactShape=True)
        if type(derivativeSelf) == tuple:
            derivativeSelf = list(derivativeSelf)
        elif type(derivativeSelf) != list:
            derivativeSelf = [derivativeSelf]

    return derivativeSelf


def considerSparse(t1, t2):
    """Decide whether to convert inputs to sparse format based on sparsity and size."""
    total_size = int64(prod(t1.shape)) * int64(prod(t2.shape))
    if total_size > 2**15 and (
        (isinstance(t1, ndarray) and t1.nonzero()[0].size < 0.25 * t1.size) or
        (isinstance(t2, ndarray) and t2.nonzero()[0].size < 0.25 * t2.size)
    ):
        if not scipyInstalled:
            pWarn(scipyAbsentMsg)
            return t1, t2

        from scipy.sparse import csc_matrix, csr_matrix, isspmatrix_csc, isspmatrix_csr
        if not isspmatrix_csc(t1):
            t1 = csc_matrix(t1)
        if t1.shape[1] != t2.shape[0]:
            assert t1.shape[0] == t2.shape[0], 'bug in FuncDesigner Kernel, inform developers'
            t1 = t1.T
        if not isspmatrix_csr(t2):
            t2 = csr_matrix(t2)
    return t1, t2


def mul_aux_d(x, y):
    """Helper for multiplication derivative rules."""
    Xsize, Ysize = Len(x), Len(y)
    if Xsize == 1:
        return Copy(y)
    elif Ysize == 1:
        return Diag(None, scalarMultiplier=y, size=Xsize)
    elif Xsize == Ysize:
        return Diag(y)
    else:
        raise FuncDesignerException('for oofun multiplication a*b should be size(a)=size(b) or size(a)=1 or size(b)=1')


