import importlib.util
import inspect
import os
from pathlib import Path
from PySide6.QtCore import QDir, QSize
from PySide6.QtWidgets import QFileDialog, QListWidget, QTabWidget
from cilissa.images import Image
from cilissa.operations import Metric, Transformation
from cilissa_gui.decorators import PathInsert
from cilissa_gui.widgets import CQImageItem, CQInfoDialog, CQOperationItem


class NavigationTabs(QTabWidget):
    SUPPORTED_IMAGE_FORMATS = ["*.png", "*.jpg", "*.jpeg", "*.bmp", "*.tiff"]

    def __init__(self) -> None:
        super().__init__()
        self.image_section = ImageList(self)
        self.metric_section = MetricList(self)
        self.transform_section = TransformList(self)

        self.addTab(self.image_section, "Images")
        self.addTab(self.metric_section, "Metrics")
        self.addTab(self.transform_section, "Transformations")

        self.currentChanged.connect(self.deselect_all_items)

    def deselect_all_items(self) -> None:
        for idx in range(self.count()):
            self.widget(idx).clearSelection()

    def browse_images(self) -> None:
        # Returns tuple ([paths], filter); extract only the file paths
        selected_files = QFileDialog.getOpenFileNames(
            self, "Select image files...", "", f"Images ({' '.join([ext for ext in self.SUPPORTED_IMAGE_FORMATS])})"
        )[0]

        for path in selected_files:
            img_obj = Image(path)
            icon_item = CQImageItem(img_obj, width=128, height=128)
            self.image_section.addItem(icon_item)

    def browse_image_folder(self) -> None:
        folder_path = QFileDialog.getExistingDirectory(self, "Choose image directory...", "", QFileDialog.ShowDirsOnly)
        dir_obj = QDir(folder_path)

        if folder_path and not dir_obj.entryList(self.SUPPORTED_IMAGE_FORMATS):
            msg_box = CQInfoDialog("No supported images found in the chosen folder", "Folder Empty")
            msg_box.exec()
            return

        for filename in dir_obj.entryList(self.SUPPORTED_IMAGE_FORMATS):
            full_path = Path(folder_path, filename)
            img_obj = Image(full_path)
            icon_item = CQImageItem(img_obj, width=128, height=128)
            self.image_section.addItem(icon_item)

    def load_extension_module(self) -> None:
        plugin_file = QFileDialog.getOpenFileName(self, "Load Python plugin", "", "Python scripts (*.py)")[0]
        if not plugin_file:
            return

        with PathInsert(os.path.dirname(plugin_file)):
            module_spec = importlib.util.spec_from_file_location(plugin_file, plugin_file)
            loaded_module = importlib.util.module_from_spec(module_spec)
            module_spec.loader.exec_module(loaded_module)

            for name, member in inspect.getmembers(loaded_module):
                if not inspect.isclass(member):
                    continue
                if issubclass(member, Metric) and member != Metric:
                    self.metric_section.addItem(CQOperationItem(member))
                elif issubclass(member, Transformation) and member != Transformation:
                    self.transform_section.addItem(CQOperationItem(member))


class BaseListWidget(QListWidget):
    def __init__(self, container: QTabWidget) -> None:
        super().__init__()
        self.setViewMode(QListWidget.IconMode)
        self.setIconSize(QSize(82, 82))
        self.setUniformItemSizes(True)
        self.setMovement(QListWidget.Static)
        self.setResizeMode(QListWidget.Adjust)
        self.setFrameStyle(QListWidget.NoFrame)
        self.setMaximumWidth(container.width())


class ImageList(BaseListWidget):
    def __init__(self, parent: QTabWidget) -> None:
        super().__init__(parent)
        self.setSelectionMode(QListWidget.ExtendedSelection)


class MetricList(BaseListWidget):
    def __init__(self, parent: QTabWidget) -> None:
        super().__init__(parent)
        for subclass in Metric.get_subclasses():
            self.addItem(CQOperationItem(subclass))


class TransformList(BaseListWidget):
    def __init__(self, parent: QTabWidget) -> None:
        super().__init__(parent)
        for subclass in Transformation.get_subclasses():
            self.addItem(CQOperationItem(subclass))

