# Configuration management module with dynamic attribute setting

import os
import sys
import json
import requests

# Environment setup
environment = os.getenv('ENV')
if not environment:
    print("ENV not specified")
    sys.exit(1)

# Settings file path configuration
settings_file_path = os.getenv('LOCAL_SETTINGS_FILE', '/app/_service_storage/settings.json')
if not os.path.isfile(settings_file_path):
    print("LOCAL_SETTINGS_FILE not specified")
    sys.exit(1)

# Logging and server configuration
log_level = os.getenv('LOG_LEVEL', 'DEBUG')
log_format = os.getenv('LOG_FORMAT', '[ %(levelname)5s ] - %(message)s')
server_port = int(os.getenv('PORT', 5000))

def _get_current_module():
    """Get reference to the current module object"""
    return sys.modules[__name__]

def _load_local_config():
    """Read and parse the local configuration file"""
    with open(settings_file_path, 'r') as config_file:
        return json.load(config_file)

def _save_local_config(**updates):
    """Update and save configuration to local file"""
    config_data = _load_local_config()

    # Apply updates (case-insensitive key matching)
    for key in list(config_data.keys()):
        upper_key = key.upper()
        for update_key in updates:
            if upper_key == update_key.upper():
                config_data[key] = updates[update_key]

    try:
        with open(settings_file_path, 'w') as config_file:
            json.dump(config_data, config_file, ensure_ascii=False, indent=4)
            print("[  INFO ] - Updated LOCAL_SETTINGS_FILE with new data")
    except Exception:
        print("[ ERROR ] - Impossible to update LOCAL_SETTINGS_FILE")

    return config_data

def _apply_attributes_to_module(attributes_dict):
    """Apply dictionary keys/values as module-level attributes"""
    normalized_attrs = dict_to_upper_keys(attributes_dict)
    current_module = _get_current_module()

    for attr_name, value in normalized_attrs.items():
        setattr(current_module, attr_name, value)

def dict_to_upper_keys(input_dict):
    """Recursively convert all dictionary keys to uppercase"""
    result = {}
    for key, value in input_dict.items():
        if isinstance(value, dict):
            value = dict_to_upper_keys(value)
        result[key.upper()] = value
    return result

def dict_to_lower_keys(input_dict):
    """Recursively convert all dictionary keys to lowercase"""
    result = {}
    for key, value in input_dict.items():
        if isinstance(value, dict):
            value = dict_to_lower_keys(value)
        result[key.lower()] = value
    return result

def get_configuration():
    """Retrieve current configuration from local storage"""
    return _load_local_config()

def update_configuration(**kwargs):
    """Update configuration with provided values"""
    normalized_kwargs = dict_to_upper_keys(kwargs)
    updated_config = _save_local_config(**normalized_kwargs)
    return updated_config

def list_active_settings():
    """Generate a list of currently active configuration settings"""
    settings_entries = []
    config_data = get_configuration()

    # Collect relevant variable names
    relevant_vars = list(config_data.keys()) + [
        'ENVIRONMENT',
        'LOG_LEVEL',
        'SETTINGS_FILE_PATH',
        'SERVER_PORT',
    ]

    current_module = _get_current_module()
    for var_name in sorted(relevant_vars):
        try:
            value = getattr(current_module, var_name)
            settings_entries.append(f"{var_name} = {value}")
        except AttributeError:
            continue

    return settings_entries

def sync_configuration():
    """Placeholder for configuration synchronization functionality"""
    pass

# Initialize module attributes from configuration upon import
_apply_attributes_to_module(get_configuration())

from dataclasses import dataclass, field
from functools import lru_cache
from typing import TYPE_CHECKING, Any, List, Optional, TypedDict, Union, no_type_check

# Base node class with tag generation
class Node:
    tag: str

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs, tag=self._tag())

    @classmethod
    @lru_cache(maxsize=20)
    def _tag(cls):
        return cls.__name__.upper()

# Terminal nodes (leaf elements)
class Terminal(Node):
    pass

# Data classes for terminal nodes
@dataclass
class Table(Terminal):
    name: str
    schema: Optional[str]
    alias: Optional[str]

@dataclass
class Column(Terminal):
    name: str
    table: Optional[str]
    table_alias: Optional[str]
    alias: Optional[str]

@dataclass
class Star(Column):
    name: str = field(default="*", init=False)
    table: Optional[str]
    table_alias: None = None
    alias: None = None

@dataclass
class Func(Terminal):
    name: str
    schema: Optional[str]
    alias: Optional[str]
    parameters: List[Node]
    anonymous: bool

@dataclass
class Value(Terminal):
    value: Any

@dataclass
class Param(Terminal):
    name: str

# Expression base class
class Expr(Node):
    name: str
    nodes: List[Node]

# SELECT-related classes
@dataclass
class Select(Expr):
    expr: str = field(default="SELECT", init=False)
    nodes: List[Union["Returning", "Query", "Union_", "UnionAll", "Except"]]

    def get_tables(self):
        return []

    def get_columns(self):
        return []

@dataclass
class Returning(Expr):
    expr: str = field(default="RETURNING", init=False)
    nodes: List[Union["Expr", Terminal]]

    def to_select(self):
        return Select(nodes=[self])

    def get_columns(self):
        return []

@dataclass
class Query(Expr):
    expr: str = field(default="QUERY", init=False)
    nodes: List[Union["From", "Where", "Join", "OrderBy", "Limit", "Offset"]]

    def get_tables(self):
        return []

    def to_select(self):
        star = Star()
        return Select(nodes=[self, Returning(nodes=[star])])

# FROM clause
@dataclass
class From(Expr):
    expr: str = field(default="FROM", init=False)
    nodes: List[Union["Expr", Terminal]]

    def to_select(self):
        query = Query(nodes=[self])
        return query.to_select()

    def get_tables(self):
        return []

# JOIN clause
@dataclass
class Join(Expr):
    expr: str = field(default="JOIN", init=False)
    nodes: List[Union["Expr", Terminal]]

    def get_tables(self):
        return []

# WHERE clause
@dataclass
class Where(Expr):
    expr: str = field(default="WHERE", init=False)
    nodes: List[Union["Expr", Terminal]]

# ORDER BY clause
@dataclass
class OrderBy(Expr):
    expr: str = field(default="ORDERBY", init=False)
    nodes: List[Union["Expr", Terminal]]

# LIMIT clause
@dataclass
class Limit(Expr):
    expr: str = field(default="LIMIT", init=False)
    nodes: List[Union["Expr", Terminal]]

# OFFSET clause
@dataclass
class Offset(Expr):
    expr: str = field(default="OFFSET", init=False)
    nodes: List[Union["Expr", Terminal]]

# Set operations
@dataclass
class Union_(Expr):
    expr: str = field(default="UNION", init=False)
    nodes: List["Select"]

@dataclass
class UnionAll(Expr):
    expr: str = field(default="UNIONALL", init=False)
    nodes: List["Select"]

@dataclass
class Except(Expr):
    expr: str = field(default="EXCEPT", init=False)
    nodes: List["Select"]

# Unary operation node
@dataclass
class Uo(Node):
    name: str
    op: str
    nodes: List[Node]

    def __str__(self):
        if len(self.nodes) != 1:
            raise ValueError("Unary operation requires exactly one operand")
        return f"{self.op} {str(self.nodes[0])}"

# Binary operation node
@dataclass
class Op(Node):
    name: str
    op: str
    nodes: List[Node]

    def __str__(self):
        if len(self.nodes) == 1:
            raise ValueError("Binary operation requires at least two operands")
        elif len(self.nodes) > 2:
            return "(" + f" {self.op} ".join((str(x) for x in self.nodes)) + ")"
        else:
            return f" {self.op} ".join((str(x) for x in self.nodes))

