def multinomial(path, s3_path, module, label, sigmoid=False, **kwargs):
    check_file(path['multinomial'], s3_path['multinomial'], **kwargs)
    try:
        with open(path['multinomial']['model'], 'rb') as fopen:
            multinomial_model = pickle.load(fopen)
        with open(path['multinomial']['vector'], 'rb') as fopen:
            vectorizer_obj = pickle.load(fopen)
    except BaseException:
        path_dir = os.path.normpath(f'{module}/multinomial')
        raise Exception(
            f"model corrupted due to some reasons, please run `malaya.clear_cache('{path_dir}')` and try again"
        )

    bpe_encoder = YTTMEncoder(vocab_file=path['multinomial']['bpe'])
    stemmer_instance = naive()
    cleaning_func = partial(_classification_textcleaning_stemmer, stemmer=stemmer_instance)

    if sigmoid:
        chosen_model_class = MultilabelBayes
    else:
        if len(label) > 2:
            chosen_model_class = MulticlassBayes
        else:
            chosen_model_class = BinaryBayes

    return chosen_model_class(
        multinomial=multinomial_model,
        label=label,
        vectorize=vectorizer_obj,
        bpe=bpe_encoder,
        cleaning=cleaning_func,
    )

def transformer(
    module,
    label,
    model='bert',
    sigmoid=False,
    quantized=False,
    **kwargs,
):
    path = check_file(
        file=model,
        module=module,
        keys={
            'model': 'model.pb',
            'vocab': MODEL_VOCAB[model],
            'tokenizer': MODEL_BPE[model],
        },
        quantized=quantized,
        **kwargs,
    )

    graph_obj = load_graph(path['model'], **kwargs)

    if sigmoid:
        selected_model_class = SIGMOID_MODEL[model]
    else:
        if len(label) > 2 or module == 'relevancy':
            selected_model_class = MULTICLASS_MODEL[model]
        else:
            selected_model_class = BINARY_MODEL[model]

    # Setup attention and inputs based on model type
    inputs = []
    vectorizer_info = {}
    attention_weights = None

    if model in ['albert', 'bert', 'tiny-albert', 'tiny-bert']:
        if model in ['bert', 'tiny-bert']:
            attention_weights = bert_attention_weights(12, graph_obj)
        if model in ['albert', 'tiny-albert']:
            attention_weights = albert_attention_weights(12, graph_obj)
        inputs = ['Placeholder', 'Placeholder_1']
        vectorizer_info = {'vectorizer': 'import/dense/BiasAdd:0'}

    elif model in ['xlnet', 'alxlnet']:
        if model in ['xlnet']:
            weights_importer = xlnet_attention_weights
        if model in ['alxlnet']:
            weights_importer = alxlnet_attention_weights
        inputs = ['Placeholder', 'Placeholder_1', 'Placeholder_2']
        vectorizer_info = {'vectorizer': 'import/transpose_3:0'}
        attention_weights = weights_importer(graph_obj)

    elif model in ['bigbird', 'tiny-bigbird']:
        inputs = ['Placeholder']
        vectorizer_info = {'vectorizer': 'import/dense/BiasAdd:0'}
        attention_weights = None

    elif model in ['fnet', 'fnet-large']:
        inputs = ['Placeholder', 'Placeholder_1']
        vectorizer_info = {'vectorizer': 'import/vectorizer:0'}
        attention_weights = None

    elif model in ['fastformer', 'tiny-fastformer']:
        inputs = ['Placeholder']
        vectorizer_nodes_map = {
            'fastformer': 'import/fast_transformer/add_24:0',
            'tiny-fastformer': 'import/fast_transformer/add_8:0'
        }
        vectorizer_info = {'vectorizer': vectorizer_nodes_map[model]}
        attention_weights = None

    outputs = ['logits', 'logits_seq']
    tokenizer_class = TOKENIZER_MODEL[model]
    tokenizer_instance = tokenizer_class(
        vocab_file=path['vocab'],
        spm_model_file=path['tokenizer']
    )

    input_nodes, output_nodes = nodes_session(
        graph_obj,
        inputs,
        outputs,
        extra=vectorizer_info,
        attention={'attention': attention_weights},
    )

    return selected_model_class(
        input_nodes=input_nodes,
        output_nodes=output_nodes,
        sess=generate_session(graph=graph_obj, **kwargs),
        tokenizer=tokenizer_instance,
        label=label,
        module=module,
    )

import pyblish.api
import pype.api

class ValidateKnobs(pyblish.api.ContextPlugin):
    """Ensure node knob values match expected settings.

    Configuration is sourced from:
        presets/nuke/publish.json
    Expected format:
        "ValidateKnobs": {
            "enabled": true,
            "knobs": {
                "family_name": {
                    "knob_identifier": expected_value,
                    ...
                },
                ...
            }
        }
    """
    order = pyblish.api.ValidatorOrder
    label = "Validate Knobs"
    hosts = ["nuke"]
    actions = [pype.api.RepairContextAction]
    optional = True

    def process(self, ctx):
        nuke_cfg = self._get_nuke_config(ctx)
        if not nuke_cfg:
            return

        plugin_cfg = self._extract_plugin_settings(nuke_cfg)
        if not plugin_cfg:
            return

        invalid_items = self._collect_invalid_knobs(ctx)
        if invalid_items:
            raise RuntimeError(
                "Detected knob mismatches:\n{}".format(invalid_items)
            )

    @classmethod
    def _get_nuke_config(cls, context):
        raw_presets = context.data.get("presets", {})
        return raw_presets.get("nuke")

    @classmethod
    def _extract_plugin_settings(cls, nuke_cfg):
        if not nuke_cfg:
            return None
        pub_section = nuke_cfg.get("publish")
        if not pub_section:
            return None
        return pub_section.get("ValidateKnobs")

    @classmethod
    def get_invalid(cls, context, force_recompute=False):
        stored = context.data.setdefault("invalid_knobs", [])
        if force_recompute:
            stored.clear()
            stored.extend(cls._collect_invalid_knobs(context))
        return stored

    @classmethod
    def _collect_invalid_knobs(cls, context):
        invalid_list = []
        preset_data = context.data["presets"]["nuke"]["publish"]
        knob_rules = preset_data["ValidateKnobs"]["knobs"]

        for inst in context:
            # Skip non-publishable instances
            if not inst.data.get("publish", False):
                continue

            # Collect all applicable families
            families = {inst.data["family"]}
            families.update(inst.data.get("families", []))
            matching_families = families & set(knob_rules.keys())
            if not matching_families:
                continue

            # Merge knob expectations across matched families
            target_knobs = {}
            for fam in matching_families:
                target_knobs.update(knob_rules[fam])

            # Traverse all nodes including nested groups
            all_nodes = []
            for node in nuke.allNodes():
                all_nodes.append(node)
                if node.Class() == "Group":
                    node.begin()
                    all_nodes.extend(nuke.allNodes())
                    node.end()

            # Check each knob against expectation
            for nd in all_nodes:
                for knob_name in nd.knobs():
                    if knob_name not in target_knobs:
                        continue
                    actual_val = nd[knob_name].value()
                    expected_val = target_knobs[knob_name]
                    if actual_val != expected_val:
                        knob_obj = nd[knob_name]
                        invalid_list.append({
                            "knob": knob_obj,
                            "name": knob_obj.name(),
                            "label": knob_obj.label(),
                            "expected": expected_val,
                            "current": actual_val
                        })

        context.data["invalid_knobs"] = invalid_list
        return invalid_list

    @classmethod
    def repair(cls, instance):
        bad_knobs = cls.get_invalid(instance)
        for item in bad_knobs:
            knob_ref = item["knob"]
            val_to_set = item["expected"]
            if isinstance(val_to_set, str):  # Python 3: unicode -> str
                knob_ref.setValue(str(val_to_set))
            else:
                knob_ref.setValue(val_to_set)

# Reimplementation of profile activation logic with equivalent functionality but different structure

from importlib.util import spec_from_file_location, module_from_spec
from functools import reduce
from pathlib import Path
from typing import Dict, List, Any, Optional
from dataclasses import dataclass
from poetry.core.pyproject.tables import PROPERTIES_TABLE, DEPENDENCIES_TABLE
from poetry.core.utils import toml


@dataclass
class ProfileActivationRequest:
    active_profiles: Dict[str, bool]
    target_command: str

    @classmethod
    def parse_cli_args(cls, command: str, profile_list: List[str]) -> "ProfileActivationRequest":
        profile_flags = {}
        for item in profile_list:
            if item.startswith('!'):
                profile_flags[item[1:]] = False
            else:
                profile_flags[item] = True
        return cls(profile_flags, command)


class PropertyContainer:
    def __init__(self, initial_data: Dict[str, Any]):
        self._storage = initial_data.copy()

    def get(self, key: str) -> Any:
        return self._storage[key]

    def set(self, key: str, value: Any):
        self._storage[key] = value

    def merge(self, updates: Dict[str, Any]):
        self._storage.update(updates)


class DependencyManager:
    def __init__(self):
        self._items: Dict[str, Any] = {}

    def register(self, package_name: str, version_spec: Any):
        self._items[package_name] = version_spec

    def items(self) -> Dict[str, Any]:
        return self._items


class ExecutionContext:
    def __init__(self, request: ProfileActivationRequest):
        self._request = request

    @property
    def command(self) -> str:
        return self._request.target_command


def evaluate_activation_condition(condition: Any, context: ExecutionContext) -> bool:
    if isinstance(condition, bool):
        return condition
    elif isinstance(condition, dict):
        if 'commands' in condition:
            command_list = condition['commands']
            if isinstance(command_list, str):
                command_list = [command_list]

            default_behavior = '*' in command_list
            for cmd in command_list:
                if cmd == '*':
                    continue

                negative = False
                if cmd.startswith('!'):
                    negative = True
                    cmd = cmd[1:]

                if context.command == cmd:
                    return not negative

            return not default_behavior

    raise NotImplementedError(f"Unsupported activation specification: {condition}")


def load_static_profile(file_path: Path, properties: PropertyContainer, 
                        deps: DependencyManager, context: ExecutionContext):
    profile_content, _ = toml.load(file_path)
    profile_section = _extract_nested_value(profile_content, "tool.relaxed-poetry.profile".split('.'))

    # Skip if activation condition fails
    activation_spec = profile_section.get('activate', False) if profile_section else False
    if not evaluate_activation_condition(activation_spec, context):
        return

    print(f"Activating Static Profile: {file_path.stem}")

    # Apply property overrides
    property_overrides = _extract_nested_value(profile_content, PROPERTIES_TABLE.split('.'))
    if property_overrides:
        properties.merge(property_overrides)

    # Register new dependencies
    dependency_updates = _extract_nested_value(profile_content, DEPENDENCIES_TABLE.split('.'))
    if dependency_updates:
        for pkg_name, spec in dependency_updates.items():
            deps.register(pkg_name, spec)


def load_dynamic_profile(file_path: Path, properties: PropertyContainer,
                         deps: DependencyManager, context: ExecutionContext):
    print(f"Activating Dynamic Profile: {file_path.stem}")

    try:
        loader_spec = spec_from_file_location("__PROFILE_MODULE__", file_path)
        profile_module = module_from_spec(loader_spec)

        # Inject required objects into module namespace
        profile_module.props = properties
        profile_module.execution = context
        profile_module.deps = deps

        loader_spec.loader.exec_module(profile_module)
    except Exception as error:
        raise RuntimeError(f"Failed to execute profile script: {file_path.stem}") from error


def apply_profiles(
    base_properties: Dict[str, Any],
    base_dependencies: Dict[str, Any],
    profile_directories: List[Path],
    activation_request: ProfileActivationRequest
):
    properties_container = PropertyContainer(base_properties)
    dependency_manager = DependencyManager()
    execution_context = ExecutionContext(activation_request)

    # Process each profile directory
    for directory in profile_directories:
        if directory.exists() and directory.is_dir():
            for profile_file in directory.iterdir():
                # Check if profile should be activated based on user request
                requested = activation_request.active_profiles.get(profile_file.stem, True)
                if not requested:
                    continue

                if profile_file.suffix == '.py':
                    load_dynamic_profile(profile_file, properties_container, dependency_manager, execution_context)
                elif profile_file.suffix == '.toml':
                    load_static_profile(profile_file, properties_container, dependency_manager, execution_context)


def _extract_nested_value(data: Dict, path: List[str]) -> Optional[Any]:
    try:
        return reduce(lambda current, key: current[key], path, data)
    except (KeyError, TypeError):
        return None

import discord
from discord.ext import commands
from k2 import helpers

class InfoCommands:
    """Utility commands for gathering server and role details."""

    @commands.command(aliases=["rlist"])
    @commands.guild_only()
    @commands.cooldown(6, 12, commands.BucketType.channel)
    async def roles(self, ctx):
        """Show all roles in the current guild."""
        roles_list = ctx.guild.roles
        embed = discord.Embed(title=f"Roles: {len(roles_list)}")
        role_names = [role.name for role in roles_list]
        embed.description = ", ".join(role_names)
        await ctx.send(embed=embed)

    @commands.command()
    @commands.guild_only()
    @commands.cooldown(6, 12, commands.BucketType.channel)
    async def whohas(self, ctx, *, role_query: str):
        """Find members assigned to a specific role.
        * role_query - Partial or full name of the role to search for.
        """
        target_role = await helpers.role_by_substring(ctx, role_query)
        members_with_role = []

        for member in ctx.guild.members:
            if target_role in member.roles:
                members_with_role.append(member.mention)

        if not members_with_role:
            await ctx.send("No members found with this role. :<")
        else:
            embed = discord.Embed(title=f"Members with {target_role.name}: {len(members_with_role)}")
            # Limit display to first 30 mentions
            display_mentions = members_with_role[:30]
            embed.description = ", ".join(display_mentions)

            if len(members_with_role) > 30:
                remaining_count = len(members_with_role) - 30
                embed.set_footer(text=f"...and {remaining_count} others.")

            await ctx.send(embed=embed)

    @commands.command(brief="Display detailed info about a role.", aliases=["rinfo"])
    @commands.guild_only()
    @commands.cooldown(6, 12, commands.BucketType.channel)
    async def roleinfo(self, ctx, *, role_query: str):
        """Get comprehensive information about a specific role.
        * role_query - Partial or full name of the role to inspect."""
        selected_role = await helpers.role_by_substring(ctx, role_query)
        embed = discord.Embed(title=selected_role.name, colour=selected_role.color)

        # Basic info
        embed.description = f"{selected_role.id} | Members: {len(selected_role.members)}"
        embed.add_field(name="Color", value=str(selected_role.color), inline=False)

        # Check for admin permission
        if selected_role.permissions.administrator:
            embed.add_field(name="Administrator", value="Yes")
        else:
            # Collect non-admin permissions
            active_permissions = []
            for perm_name, is_enabled in selected_role.permissions:
                if is_enabled:
                    formatted_perm = perm_name.replace("_", " ").title()
                    active_permissions.append(formatted_perm)

            # Paginate permissions if needed
            paginator = commands.Paginator(prefix="", suffix="")
            for perm in active_permissions:
                paginator.add_line(perm)

            for page_content in paginator.pages:
                embed.add_field(name="Permissions", value=page_content or "None", inline=False)

        await ctx.send(embed=embed)

    @commands.command(aliases=["elist"])
    @commands.guild_only()
    @commands.cooldown(6, 12, commands.BucketType.channel)
    async def emojis(self, ctx):
        """List all custom emojis available on this server."""
        embed = discord.Embed(title=f"Custom Emojis for {ctx.guild.name}")
        emoji_strings = [str(e) for e in ctx.guild.emojis]
        embed.description = " ".join(emoji_strings)
        await ctx.send(embed=embed)

    @commands.command(brief="Get detailed info about a custom emoji.",
                      aliases=["emojiinfo", "einfo", "ceinfo"])
    @commands.guild_only()
    @commands.cooldown(6, 12, commands.BucketType.channel)
    async def customemojiinfo(self, ctx, *, emoji: discord.Emoji):
        """Retrieve metadata for a specific custom emoji.
        * emoji - The emoji object to analyze."""
        embed = discord.Embed(title=emoji.name)
        embed.description = f"{emoji.id} | [Full image]({emoji.url})"

        embed.add_field(name="Server", value=f"{emoji.guild.name} ({emoji.guild.id})")
        embed.add_field(name="Managed by Integration", value="Yes" if emoji.managed else "No")
        embed.add_field(name="Creation Date", value=emoji.created_at.strftime("%Y-%m-%d %H:%M:%S"))
        embed.set_thumbnail(url=emoji.url)

        await ctx.send(embed=embed)

def setup(bot):
    """Register the Information cog with the bot."""
    bot.add_cog(InfoCommands())

