def _traverse_nested_dict(data: Optional[Dict], keys: List[str]) -> Any:
    if not data or not keys:
        return data
    current = data.get(keys[0])
    if current is None or len(keys) == 1 or not isinstance(current, dict):
        return current
    return _traverse_nested_dict(current, keys[1:])


def _build_questionnaire_response_uri(nhs_number: str) -> str:
    return f"FHIR/R4/QuestionnaireResponse?patient.identifier=https://fhir.nhs.uk/Id/nhs-number%7C{nhs_number}"


def _build_full_questionnaire_uri(nhs_number: str, questionnaire_id: str) -> str:
    return _build_questionnaire_response_uri(nhs_number) + f"&questionnaire={questionnaire_id}"


async def _check_commit_match(response: ClientResponse, config: APITestSessionConfig) -> bool:
    if response.status != 200:
        return False
    payload = await response.json()
    return payload.get("commitId") == config.commit_id


async def _is_unauthorized_status(response: ClientResponse) -> bool:
    return response.status == 401


