# Type III Clone: Refactored configuration loader with equivalent logic and behavior

import logging
import yaml
import os
from .exceptions import ConfigFileUnreadableError, ConfigError, DeviceNamesNotUniqueWarning

logger = logging.getLogger('fritzexporter.config')

def load_fritz_config(config_path):
    cfg = None

    if config_path:
        try:
            with open(config_path, 'r') as fp:
                cfg = yaml.safe_load(fp)
        except (IOError, OSError) as err:
            logger.error(f'Config file specified but could not be read: {err}')
            raise ConfigFileUnreadableError(err)
        logger.info(f'Loaded configuration from {config_path}')
    else:
        # Fallback to environment variables when no config file is provided
        required_env_vars = {'FRITZ_USERNAME', 'FRITZ_PASSWORD'}
        if required_env_vars.issubset(os.environ.keys()):
            host = os.getenv('FRITZ_HOSTNAME', 'fritz.box')
            dev_name = os.getenv('FRITZ_NAME', 'Fritz!Box')
            port_str = os.getenv('FRITZ_PORT', '9787')
            port_num = int(port_str) if port_str.isdigit() else 9787

            user = os.getenv('FRITZ_USERNAME')
            passwd = os.getenv('FRITZ_PASSWORD')
            lvl = os.getenv('FRITZ_LOG_LEVEL', 'INFO')

            validate_log_level(lvl)

            cfg = {
                'exporter_port': port_num,
                'log_level': lvl,
                'devices': [{
                    'name': dev_name,
                    'hostname': host,
                    'username': user,
                    'password': <PASSWORD>
                }]
            }
            logger.info('No config file provided; using environment variables for configuration')
        else:
            missing = required_env_vars - set(os.environ.keys())
            logger.critical(f'Missing required environment variables: {missing}')
            raise ConfigError(
                f'Missing required environment variables: {missing}'
            )

    return cfg

def validate_log_level(level):
    valid_levels = {'DEBUG', 'INFO', 'WARNING', 'ERROR', 'CRITICAL'}
    if level not in valid_levels:
        logger.critical(f'Invalid log level "{level}". Must be one of: {", ".join(sorted(valid_levels))}')
        raise ConfigError(f'Invalid log level "{level}". Must be one of: {", ".join(sorted(valid_levels))}')

def validate_configuration(cfg):
    # Validate the loaded configuration structure and values

    if cfg is None:
        logger.critical('Configuration object is null/empty.')
        raise ConfigError('Configuration object is null/empty.')

    # Handle log level validation if present
    if 'log_level' in cfg:
        validate_log_level(cfg['log_level'])

    # Ensure exporter_port exists and is valid
    if 'exporter_port' not in cfg:
        cfg['exporter_port'] = 9787
    else:
        try:
            port_val = int(cfg['exporter_port'])
            if port_val < 1 or port_val > 65535:
                logger.critical('Port number out of valid range (1-65535)')
                raise ConfigError('Port number out of valid range (1-65535)')
            cfg['exporter_port'] = port_val
        except (ValueError, TypeError):
            logger.critical('Invalid port value specified')
            raise ConfigError('Invalid port value specified')

    # Check for devices list
    if 'devices' not in cfg or not isinstance(cfg['devices'], list) or len(cfg['devices']) == 0:
        logger.critical('No devices defined in configuration')
        raise ConfigError('No devices defined in configuration')

    # Validate first device has required fields
    required_device_fields = {'hostname', 'username', 'password'}
    if not required_device_fields.issubset(cfg['devices'][0].keys()):
        missing = required_device_fields - set(cfg['devices'][0].keys())
        logger.critical(f'Device missing required fields: {missing}')
        raise ConfigError(f'Device missing required fields: {missing}')

    # Assign default names where needed
    for idx, device in enumerate(cfg['devices']):
        if 'name' not in device or not device['name']:
            default_name = f'fritz-{idx}'
            logger.info(f'Setting default name "{default_name}" for device at index {idx}')
            device['name'] = default_name

    # Enforce unique device names
    device_names = [dev['name'] for dev in cfg['devices']]
    if len(device_names) != len(set(device_names)):
        duplicates = [name for name in device_names if device_names.count(name) > 1]
        logger.warning(f'Duplicate device names detected: {set(duplicates)}')
        raise DeviceNamesNotUniqueWarning('Duplicate device names found in configuration')

import os
import argparse
from collections.abc import Sequence
import base58
import libnacl

PUB_XFER_TXN_ID = "10001"

def validate_path(path_name: str, is_directory: bool) -> str:
    full_path = os.path.expanduser(path_name)
    required_access = os.W_OK if is_directory else os.R_OK
    existence_check = os.path.isdir if is_directory else os.path.isfile
    size_validation = True if is_directory else os.path.getsize(full_path) > 0

    if existence_check(full_path) and os.access(full_path, required_access) and size_validation:
        return full_path
    raise argparse.ArgumentTypeError("{} does not exist, cannot be accessed, or file is empty".format(full_path))

def verify_seed_string(seed_value: str) -> str:
    if len(seed_value) == 32:
        return seed_value
    raise argparse.ArgumentTypeError("Seed must contain exactly 32 characters, but got {}".format(len(seed_value)))

def validate_reply_format(response):
    if isinstance(response, str):
        response = json.loads(response)
    if "op" not in response or response["op"] != "REPLY":
        raise Exception("Invalid response format - expected REPLY operation: {}".format(response))

def split_sequence_into_parts(input_seq: Sequence, part_size: int):
    return (input_seq[offset:offset + part_size] for offset in range(0, len(input_seq), part_size))

# Adapted from Plenum
def convert_raw_to_base58(raw_bytes):
    return base58.b58encode(raw_bytes).decode("utf-8")

# Adapted from Plenum
def generate_random_string(length: int) -> str:
    assert (length > 0), "Requested string length must be positive"
    partial_hex = libnacl.randombytes(length // 2).hex()
    return partial_hex if length % 2 == 0 else partial_hex + hex(libnacl.randombytes_uniform(15))[-1]

def extract_transaction_data(txn_dict):
    temp_data = txn_dict or {}
    return temp_data.get('result', {}).get('txn', {}) or temp_data.get('txn', {})

def extract_transaction_type(txn_dict):
    return extract_transaction_data(txn_dict).get('type', None)

def extract_transaction_id(txn_dict):
    temp_data = txn_dict or {}
    return (temp_data.get('result', {}).get('txnMetadata', {}) or temp_data.get('txnMetadata', {})).get('txnId', None)

def get_operation_type(request_obj):
    if isinstance(request_obj, dict):
        request_dict = request_obj
    elif isinstance(request_obj, str):
        request_dict = json.loads(request_obj)
    else:
        raise RuntimeError("Unsupported request type encountered")
    txn_category = request_dict.get("operation", {}).get("type", "")
    return txn_category

def allocate_inputs_outputs(address_utxos, target_value):
    for addr in address_utxos:
        inputs_list = []
        outputs_list = []
        accumulated_amount = 0
        temporary_utxo = []

        while address_utxos[addr] and accumulated_amount < target_value:
            (utxo_source, utxo_amount) = address_utxos[addr].pop()
            if utxo_amount > 0:
                inputs_list.append(utxo_source)
                accumulated_amount += utxo_amount
                temporary_utxo.append((utxo_source, utxo_amount))

        if accumulated_amount >= target_value:
            change_amount = accumulated_amount - target_value
            if change_amount > 0:
                outputs_list = [{"recipient": addr, "amount": change_amount}]
            return {addr: temporary_utxo}, inputs_list, outputs_list
        else:
            # Restore UTXOs if insufficient funds found
            for src_amt in temporary_utxo:
                address_utxos[addr].append(src_amt)

    return None, None, None

import collections
from typing import Iterable, Optional, Sequence
from absl import logging

class Vocabulary:
  """Represents a vocabulary that can be built from a dataset."""

  def __init__(self,
               vocab_path: Optional[str] = None,
               tokenized_sequences: Optional[Iterable[Sequence[bytes]]] = None,
               min_freq: int = 1,
               pad_token: bytes = b'<pad>',
               unk_token: bytes = b'<unk>',
               bos_token: bytes = b'<s>',
               eos_token: bytes = b'</s>'):
    """Initializes the vocabulary either by loading from disk or constructing from sequences."""
    self.pad_token = pad_token
    self.unk_token = unk_token
    self.bos_token = bos_token
    self.eos_token = eos_token
    self.special_tokens = (pad_token, unk_token, bos_token, eos_token)

    if vocab_path is not None:
      self.load(vocab_path)
    elif tokenized_sequences is not None:
      self.construct(tokenized_sequences, min_freq=min_freq)
    else:
      raise ValueError(
          ('Vocabulary requires either `vocab_path` or `tokenized_sequences` to '
           'be provided, got %r and %r.') % (vocab_path, tokenized_sequences))

  def construct(self,
                tokenized_sequences: Iterable[Sequence[bytes]],
                min_freq: int = 1):
    """Constructs vocabulary from token sequences with optional frequency threshold.
    Args:
      tokenized_sequences: Iterable of token sequences for building the vocabulary.
      min_freq: Minimum required count for a token to be included (default: 1).
    """
    # Aggregate token occurrences
    freq_map = collections.Counter()
    for seq in tokenized_sequences:
      freq_map.update(seq)

    # Initialize ordered dictionary with special tokens first
    vocab_dict = collections.OrderedDict()
    for token in self.special_tokens:
      vocab_dict[token] = len(vocab_dict)

    # Add regular tokens sorted by descending frequency, then lexicographically
    for token, count in sorted(freq_map.items(), key=lambda x: (-x[1], x[0])):
      if count >= min_freq:
        vocab_dict[token] = len(vocab_dict)

    logging.info('Total unique tokens observed: %d', len(freq_map))
    logging.info('Final vocabulary size (after filtering): %d', len(vocab_dict))
    self.vocab = vocab_dict

  def __getitem__(self, key: str):
    return self.vocab[key]

  def keys(self):
    return self.vocab.keys()

  def values(self):
    return self.vocab.values()

  def __len__(self):
    return len(self.vocab)

  @property
  def pad_idx(self):
    """Returns index of padding token."""
    return self.vocab[self.pad_token]

  @property
  def unk_idx(self):
    """Returns index of unknown token."""
    return self.vocab[self.unk_token]

  @property
  def bos_idx(self):
    """Returns index of beginning-of-sequence token."""
    return self.vocab[self.bos_token]

  @property
  def eos_idx(self):
    """Returns index of end-of-sequence token."""
    return self.vocab[self.eos_token]

  def load(self, path: str) -> None:
    """Loads vocabulary from file (one token per line)."""
    vocab_dict = collections.OrderedDict()
    with open(path, 'rb') as f:
      for idx, raw_line in enumerate(f):
        token = raw_line.rstrip()
        assert isinstance(token, bytes), 'All tokens must be byte strings.'
        vocab_dict[token] = idx

    logging.info('Loaded vocabulary from %s, size: %d', path, len(vocab_dict))
    self.vocab = vocab_dict

  def save(self, path: str) -> None:
    """Saves vocabulary to file (one token per line)."""
    with open(path, 'wb') as f:
      for token in self.vocab:
        assert isinstance(token, bytes), 'Tokens must be byte strings.'
        f.write(token + b'\n')
    logging.info('Saved vocabulary to %s.', path)

