from collections import defaultdict
from typing import Any, Dict, List, Tuple, Union
from lambda_handlers.errors import LambdaError
from lambda_handlers.validators.validator import Validator

try:
    import jsonschema
except ImportError:
    jsonschema = None


class SchemaValidator(Validator):
    def check(
        self,
        data,
        definition: Dict[str, Any],
    ) -> Tuple[Any, List[Dict[str, str]]]:
        if jsonschema is None:
            raise LambdaError('Missing required dependency: jsonschema.')

        checker = jsonschema.Draft7Validator(definition)
        issues = sorted(checker.iter_errors(data), key=lambda err: list(err.path))

        return data, issues

    def describe_issues(self, issues) -> List[Dict[str, List[str]]]:
        grouped_issues: Dict[str, List[str]] = defaultdict(list)

        for issue in issues:
            # Extract the last segment of the path as the key
            path_key = list(issue.path)[-1] if issue.path else 'root'
            grouped_issues[path_key].append(issue.message)

        return [{key: val} for key, val in grouped_issues.items()]

import triton
import torch
import math

# Cache for forward kernels
fwd_cache = {}
fwd_template = '''
__global__ void softmax_forward(TYPE *INPUT __readonly __noalias __aligned(16), 
                                float scaling_factor,
                                int *LOOKUP_TABLE __readonly __noalias __aligned(16), 
                                TYPE *RPE_MATRIX __readonly __noalias __aligned(16), 
                                TYPE *KEY_PADDING_MASK __readonly __noalias __aligned(16), 
                                TYPE *ATTENTION_MASK __readonly __noalias __aligned(16),
                                int total_blocks, int blocks_per_head,
                                int max_size, 
                                long stride_batch_input __multipleof(BLOCK),
                                long stride_batch_rpe __multipleof(BLOCK),
                                int stride_head_rpe __multipleof(BLOCK),
                                int stride_seq_rpe __multipleof(BLOCK),
                                int stride_batch_kpm __multipleof(BLOCK), 
                                int stride_batch_am __multipleof(BLOCK)){ 
  int block_row_id = get_program_id(0);
  int batch_idx = get_program_id(1);

  // Compute row/column indices within block
  int inner_row = block_row_id % BLOCK;
  int block_col_idx = block_row_id / BLOCK;

  // Generate column offsets per thread
  int col_offsets[TN] = (0 ... TN) % BLOCK;
  int block_offsets[TN] = (0 ... TN) / BLOCK;

  // Read header info from LUT
  int* lut_header = LOOKUP_TABLE + block_col_idx * 2;
  int active_cols = *(lut_header + 0);
  int lut_offset  = *(lut_header + 1);

  // Determine valid columns
  bool is_valid[TN] = block_offsets < active_cols;
  int effective_block[TN] = is_valid ? block_offsets : active_cols - 1;

  // Extract block, column, and row IDs from LUT
  long blk_id[TN]     = *(LOOKUP_TABLE + lut_offset + effective_block * 3 + 0);
  long col_id[TN]     = *(LOOKUP_TABLE + lut_offset + effective_block * 3 + 1);
  long row_id[TN]     = *(LOOKUP_TABLE + lut_offset + effective_block * 3 + 2);

  // Pointer arithmetic for input tensor
  TYPE* in_ptr[TN] = INPUT + batch_idx * stride_batch_input
                         + blk_id * BLOCK * BLOCK 
                         + inner_row * BLOCK 
                         + col_offsets;

#ifdef ENABLE_RPE
  // Relative position embedding pointer setup
  TYPE* rpe_ptr[TN] = RPE_MATRIX + batch_idx * stride_batch_rpe
                               + blk_id / blocks_per_head * stride_head_rpe
                               + col_id * BLOCK
                               + row_id * BLOCK * stride_seq_rpe
                               + inner_row * stride_seq_rpe
                               + col_offsets;
#endif

#ifdef ENABLE_KP_MASK
  // Key padding mask pointer setup
  TYPE* kpm_ptr[TN] = KEY_PADDING_MASK + batch_idx * stride_batch_kpm 
                                     + col_id * BLOCK
                                     + col_offsets;
#endif

#ifdef ENABLE_ATTN_MASK
  // Attention mask pointer setup
  TYPE* atm_ptr[TN] = ATTENTION_MASK + col_id * BLOCK 
                                    + row_id * BLOCK * stride_batch_am
                                    + inner_row * stride_batch_am
                                    + col_offsets;
#endif

  // Load input values
  TYPE input_val[TN] = is_valid ? *in_ptr : -INFINITY;

#ifdef ENABLE_RPE
  TYPE rpe_val[TN] = is_valid ? *rpe_ptr : 0.0f;
#endif

#ifdef ENABLE_KP_MASK
  TYPE kpm_val[TN] = is_valid ? *kpm_ptr : -INFINITY;
#endif

#ifdef ENABLE_ATTN_MASK
  TYPE atm_val[TN] = is_valid ? *atm_ptr : -INFINITY;
#endif

  // Convert to float for computation
#ifdef ENABLE_RPE
  float rpe_f[TN] = rpe_val;
#endif

#ifdef ENABLE_KP_MASK
  float kpm_f[TN] = kpm_val;
#endif

#ifdef ENABLE_ATTN_MASK
  float atm_f[TN] = atm_val;
#endif

#ifdef KP_MASK_AS_MUL
  kpm_f = (kpm_f == 0.0f) ? (float[TN])-INFINITY : 0.0f;
#endif

#ifdef ATTN_MASK_AS_MUL
  atm_f = (atm_f == 0.0f) ? (float[TN])-INFINITY : 0.0f;
#endif

  float input_f[TN] = input_val;

#ifdef APPLY_SCALING
  input_f *= scaling_factor;
#endif

#ifdef ENABLE_RPE
  input_f += rpe_f;
#endif

#ifdef ENABLE_KP_MASK
  input_f += kpm_f;
#endif

#ifdef ENABLE_ATTN_MASK
  input_f += atm_f;
#endif

  // Softmax: subtract max, exponentiate, normalize
  float max_val = input_f[max];
  float exp_vals[TN] = exp(input_f - max_val);
  float sum_exp = (is_valid ? exp_vals : 0.0f)[+];

  // Store result back
  TYPE output_vals[TN] = exp_vals;
  TYPE norm_sum = sum_exp;
  *?(is_valid)in_ptr = output_vals / norm_sum;
}
'''

# Backward kernel template
bwd_cache = {}
bwd_template = '''
__global__ void softmax_backward(TYPE *OUTPUT __readonly __noalias __aligned(16), 
                                 float scaling_factor,
                                 TYPE* GRAD_OUT __readonly __noalias __aligned(16), 
                                 int* LOOKUP_TABLE,
                                 int max_size, 
                                 long stride_batch_out __multipleof(BLOCK), 
                                 long stride_batch_grad __multipleof(BLOCK)) {
    int block_row_id = get_program_id(0);
    int batch_idx = get_program_id(1);

    int inner_row = block_row_id % BLOCK;
    int block_col_idx = block_row_id / BLOCK;

    int col_offsets[TN] = (0 ... TN) % BLOCK;
    int block_offsets[TN] = (0 ... TN) / BLOCK;

    int* lut_header = LOOKUP_TABLE + block_col_idx * 2;
    int active_cols = *(lut_header + 0);
    int lut_offset  = *(lut_header + 1);

    bool is_valid[TN] = block_offsets < active_cols;
    int effective_block[TN] = is_valid ? block_offsets : active_cols - 1;

    long blk_id[TN] = *(LOOKUP_TABLE + lut_offset + effective_block * 3);
    TYPE* out_ptr[TN] = OUTPUT + batch_idx * stride_batch_out
                             + blk_id * BLOCK * BLOCK
                             + inner_row * BLOCK
                             + col_offsets;
    TYPE* grad_ptr[TN] = GRAD_OUT + batch_idx * stride_batch_grad
                                  + blk_id * BLOCK * BLOCK
                                  + inner_row * BLOCK
                                  + col_offsets;

    TYPE y[TN] = is_valid ? *out_ptr : 0.0f;
    TYPE dy[TN] = is_valid ? *grad_ptr : 0.0f;

    float fy[TN] = y;
    float fdy[TN] = dy;
    float fprod[TN] = fy * fdy;
    float fsum_prod = fprod[+];

    float grad_in[TN] = fy * (fdy - fsum_prod) * scaling_factor;
    TYPE result[TN] = grad_in;

    *? (is_valid)grad_ptr = result;
}
'''

class _SparseSoftmax(torch.autograd.Function):
    @staticmethod
    def build_lut(layout, block_size, device):
        empty_tensor = torch.empty(0, dtype=torch.int64, device=layout.device)
        row_sums = empty_tensor.clone()

        for head in range(layout.shape[0]):
            row_sums = torch.cat((row_sums, layout[head].sum(dim=1)))

        offset_table = torch.zeros_like(row_sums)
        offset_table[1:] = torch.cumsum(row_sums[:-1], dim=0)

        nonzero_positions = layout.nonzero()
        rows = nonzero_positions[:, 1]
        cols = nonzero_positions[:, 2]
        indices = torch.arange(layout.sum())

        core_entries = torch.stack((indices, cols, rows), dim=1).flatten()

        # Construct full LUT
        offset_table = offset_table * 3 + 2 * row_sums.numel()
        headers = torch.stack((row_sums, offset_table), dim=1).flatten()
        full_lut = torch.cat((headers, core_entries)).to(device=device, dtype=torch.int32)

        return full_lut, int(row_sums.max().item())

    @staticmethod
    def compile_kernel(cache_dict, source_code, max_elements, data_type, block_dim,
                       use_scale, use_rpe, use_kp_mask, use_attn_mask,
                       kp_mode, attn_mode):
        if max_elements >= 32768:
            raise ValueError("Reductions larger than 32768 elements are not supported")

        num_warps = 4 if max_elements < 512 else (8 if max_elements < 2048 else 16)
        padding = num_warps * 32 * 2
        TN = ((int(max_elements) + padding - 1) // padding) * padding

        key = (block_dim, data_type, num_warps, TN, use_scale, use_rpe, use_kp_mask, use_attn_mask, kp_mode, attn_mode)
        if key not in cache_dict:
            defines = {
                'TM': [1],
                'TN': [TN],
                'TYPE': data_type,
                'BLOCK': block_dim,
                'INFINITY': {torch.float32: 'F32_INFINITY', torch.float16: 'F16_INFINITY'}[data_type]
            }

            if use_scale:
                defines['APPLY_SCALING'] = True
            if use_rpe:
                defines['ENABLE_RPE'] = True
            if use_kp_mask:
                defines['ENABLE_KP_MASK'] = True
                if kp_mode == 'mul':
                    defines['KP_MASK_AS_MUL'] = True
            if use_attn_mask:
                defines['ENABLE_ATTN_MASK'] = True
                if attn_mode == 'mul':
                    defines['ATTN_MASK_AS_MUL'] = True

            compiled_kernel = triton.kernel(source_code, defines=defines, num_warps=[num_warps])
            cache_dict[key] = compiled_kernel

        return cache_dict[key]

    @staticmethod
    def forward(ctx, input_tensor, scale_param, rpe_matrix, kp_mask, attn_mask,
                kp_mask_strategy, attn_mask_strategy,
                spatial_dims, block_size, lut, total_blocks, heads_blocks, max_lut_size,
                benchmark_mode, timing_list):

        apply_scaling = scale_param != 1.0

        # Handle optional RPE
        if rpe_matrix is None:
            use_rpe = False
            rpe_strides = (0, 0, 0)
            rpe_matrix = torch.empty(0, dtype=input_tensor.dtype, device=input_tensor.device)
        else:
            use_rpe = True
            rpe_strides = (rpe_matrix.stride(0), rpe_matrix.stride(1), rpe_matrix.stride(2))

        # Handle optional key padding mask
        if kp_mask is None:
            use_kp = False
            kp_stride = 0
            kp_mask = torch.empty(0, dtype=input_tensor.dtype, device=input_tensor.device)
        else:
            use_kp = True
            kp_stride = kp_mask.stride(0)

        # Handle optional attention mask
        if attn_mask is None:
            use_attn = False
            attn_stride = 0
            attn_mask = torch.empty(0, dtype=input_tensor.dtype, device=input_tensor.device)
        else:
            use_attn = True
            attn_stride = attn_mask.stride(0)

        # Compile and launch kernel
        kernel_func = _SparseSoftmax.compile_kernel(fwd_cache, fwd_template, max_lut_size * block_size,
                                                    input_tensor.dtype, block_size,
                                                    apply_scaling, use_rpe, use_kp, use_attn,
                                                    kp_mask_strategy, attn_mask_strategy)

        batch_count = input_tensor.size(0)
        grid_shape = lambda opts: [triton.cdiv(spatial_dims[0] * spatial_dims[1] * block_size, opts.d('TM')), batch_count]

        timing_list[0] = kernel_func(
            input_tensor, scale_param, lut, rpe_matrix, kp_mask, attn_mask,
            total_blocks, heads_blocks, max_lut_size,
            input_tensor.stride(0),
            *rpe_strides,
            kp_stride,
            attn_stride,
            grid=grid_shape,
            bench=benchmark_mode
        )

        ctx.mark_dirty(input_tensor)
        ctx.save_for_backward(input_tensor, lut)
        ctx.spatial_dims = spatial_dims
        ctx.block_size = block_size
        ctx.max_lut = max_lut_size
        ctx.scale_param = scale_param
        ctx.apply_scaling = apply_scaling
        ctx.use_rpe = use_rpe
        ctx.use_kp = use_kp
        ctx.use_attn = use_attn
        ctx.kp_strategy = kp_mask_strategy
        ctx.attn_strategy = attn_mask_strategy

        return input_tensor

    @staticmethod
    def backward(ctx, grad_output):
        output_tensor, lut = ctx.saved_tensors

        kernel_func = _SparseSoftmax.compile_kernel(bwd_cache, bwd_template,
                                                    ctx.max_lut * ctx.block_size,
                                                    output_tensor.dtype,
                                                    ctx.block_size,
                                                    ctx.apply_scaling,
                                                    ctx.use_rpe,
                                                    ctx.use_kp,
                                                    ctx.use_attn,
                                                    ctx.kp_strategy,
                                                    ctx.attn_strategy)

        batch_count = output_tensor.size(0)
        grid_shape = lambda opts: [triton.cdiv(ctx.spatial_dims[0] * ctx.spatial_dims[1] * ctx.block_size, opts.d('TM')), batch_count]

        kernel_func(output_tensor, ctx.scale_param, grad_output, lut, ctx.max_lut,
                    output_tensor.stride(0), grad_output.stride(0),
                    grid=grid_shape)

        return grad_output, None, None, None, None, None, None, None, None, None, None, None, None, None, None


class SparseSoftmaxModule:
    sparse_softmax_op = _SparseSoftmax.apply

    def generate_lut(self, device):
        key = (device,)
        if key not in self.lut_store:
            self.lut_store[key] = _SparseSoftmax.build_lut(self.layout, self.block_size, device)
        return self.lut_store[key]

    def __init__(self, layout, block_size, benchmark=False):
        self.total_blocks = layout.sum().item()
        self.blocks_per_head = self.total_blocks / layout.shape[0]
        self.spatial_dims = layout.shape
        self.layout = layout
        self.block_size = block_size
        self.benchmark = benchmark
        self.lut_store = {}

    def __call__(self, x, scale=1.0, rpe=None, key_padding_mask=None, attention_mask=None,
                 key_padding_strategy='add', attention_strategy='add'):
        time_record = [None]

        # Type checks
        if rpe is not None and rpe.dtype != x.dtype:
            raise TypeError(f"RPE must be {x.dtype}")
        if attention_mask is not None and attention_mask.dtype != x.dtype:
            raise TypeError(f"Attention mask must be {x.dtype}")
        if key_padding_mask is not None and key_padding_mask.dtype != x.dtype:
            raise TypeError(f"Key padding mask must be {x.dtype}")

        lut, max_lut = self.generate_lut(x.device)
        result = SparseSoftmaxModule.sparse_softmax_op(
            x, scale, rpe, key_padding_mask, attention_mask,
            key_padding_strategy, attention_strategy,
            self.spatial_dims, self.block_size,
            lut, self.total_blocks, self.blocks_per_head,
            max_lut, self.benchmark, time_record
        )
        self.time_y = time_record[0]
        return result

