def test_rdata_parsing():
    """Test the RDATA splitting functionality"""

    def verify_result(input_str, expected_list):
        assert HTTPSResolver.split_rdata(input_str) == expected_list

    def expect_exception(input_str, exception_type=BadRData):
        with pytest.raises(exception_type):
            HTTPSResolver.split_rdata(input_str)

    # Basic whitespace handling
    verify_result(' asf  sdf ', ['asf', 'sdf'])
    verify_result('asf sdf', ['asf', 'sdf'])

    # Quoted strings with escape sequences
    verify_result(r'"asdf\"sdf\\123" 456', [r'asdf"sdf\123', '456'])
    verify_result(r'"asdf\"" 456', [r'asdf"', '456'])

    # Escaped characters without quotes
    verify_result(r'45\6', [r'45\6'])

    # Simple quoted string
    verify_result(r'"asdf 234 "', ['asdf 234 '])

    # Invalid cases
    expect_exception('"')
    expect_exception('"\\')


