def test_url_generation():
    """Test URL construction for HTTPS DNS requests"""

    def convert_values_to_strings(dct):
        return {k: str(v) for k, v in dct.items()}

    def verify_url(domain_name, record_type=dns.A, params=None, **kwargs):
        url = HTTPSResolver().make_request_url(domain_name, dns.IN, record_type, **kwargs)
        assert url.startswith('https://dns.google.com/resolve?')

        parsed_query = parse_qs(urlparse(url).query)
        # Convert lists to single values for comparison
        normalized_query = {k: v[0] if len(v) == 1 else v for k, v in parsed_query.items()}
        assert normalized_query == convert_values_to_strings(params)

    # Basic A record request
    verify_url(b'asdf', params=dict(name='asdf', type=dns.A))

    # Request with client subnet parameter
    verify_url(
        b'asdf', dns.SOA, client_subnet=ip_network('192.168.3.11/24'),
        param=dict(name='asdf', type=dns.SOA, edns_client_subnet='192.168.3.11/24'),
    )


