    def __init__(self, heleus):
        self.heleus = heleus
        self.db_ignore_flag = False
        self.detailed_tracebacks = False  # show full tracebacks?
        self.user_friendly_errors = True  # provide informative error messages
        self.config = RedisCollection(self.heleus.redis, 'settings')
        self.logger = self.heleus.logger
        self._startup_sequence.start()
        self.global_checks = [self._skip_check]  # pre-checks for message processing
        self.global_check_exemptions = [self._exempt_override]  # overrides to the pre-checks
        self._eval_context = {}
        self.haste_endpoint = os.environ.get('HELEUS_HASTE_URL', 'https://hastebin.com')
        self.cogs_initialized = False
        self.help_category = 'Core'
        self.help_thumbnail = 'https://i.imgur.com/jLP1NEW.png'
        for attr_name in dir(self):  # docstring formatting
            if attr_name.startswith('_'):
                continue
            attr = getattr(self, attr_name)
            if not isinstance(attr, commands.Command):
                continue
            if not attr.help:
                continue
            attr.help = attr.help.format(self.heleus.name)

    def __unload(self):
        self._maintenance_cycle.cancel()
        self._owner_validation.cancel()

    @staticmethod
    def discover_submodules(module_path):
        # Slightly modified but still functional approach
        if module_path.endswith('.*'):
            module_path = module_path[:-2]
        return [f'{module_path}.{pkg.name}' for pkg in pkgutil.iter_modules([module_path])]

    async def _cog_scheduler(self):
        loaded_cogs: list = await self.config.get('cogs', [])
        updated = False
        if self.heleus.autoload and not self.cogs_initialized:
            for module in self.heleus.autoload:
                if module.endswith('.*'):
                    submodules = self.discover_submodules(module)
                    for submodule in submodules:
                        if submodule not in loaded_cogs:
                            loaded_cogs.append(submodule)
                            updated = True
                else:
                    if module not in loaded_cogs:
                        loaded_cogs.append(module)
                        updated = True
            self.cogs_initialized = True
        for cog_name in loaded_cogs:
            if cog_name not in list(self.heleus.extensions):
                try:
                    await self.install_cog(cog_name)
                except Exception:
                    loaded_cogs.remove(cog_name)
                    updated = True
                    self.logger.warning(f'{repr(cog_name)} could not be loaded. This message will not be shown again.')
        if updated:
            await self.config.set('cogs', loaded_cogs)
        for cog_name in list(self.heleus.extensions):
            if cog_name == 'cogs.core':
                continue
            if cog_name not in loaded_cogs:
                self.heleus.unload_extension(cog_name)

    async def _get_guild_config(self, guild_id, key, fallback=None):
        guild_data = await self.config.get(f'guilds:{guild_id}', {})
        return guild_data.get(key, fallback)

    async def _update_guild_config(self, guild_id, key, value):
        guild_data = await self.config.get(f'guilds:{guild_id}', {})
        guild_data[key] = value
        await self.config.set(f'guilds:{guild_id}', guild_data)

    @tasks.loop(count=1)
    async def _startup_sequence(self):
        """System initialization sequence. Beep boop."""
        self.heleus.administrators = []
        # Set command prefixes
        prefix = str(random.randint(1, 2**8))
        prefixes = await self.config.get('prefixes')
        if prefixes is None:
            prefixes = [prefix]
            await self.config.set('prefixes', prefixes)
        self.heleus.command_prefix = prefixes
        self.logger.info(f'{self.heleus.name}\'s prefixes are: {", ".join(map(repr, prefixes))}')
        # Load cogs
        await self._cog_scheduler()
        # Initialize instance mode
        instance_state = await self.config.get(self.heleus.instance_id, {'mode': CoreMode.boot})
        if not self.heleus.initialized:
            if instance_state['mode'] == CoreMode.up:
                instance_state['mode'] = CoreMode.boot
                await self.config.set(self.heleus.instance_id, instance_state)
        await self.heleus.wait_until_ready()
        self.heleus.initialized = True
        if instance_state['mode'] == CoreMode.boot:
            instance_state['mode'] = CoreMode.up
            await self.config.set(self.heleus.instance_id, instance_state)
        # Data migration
        keys = await self.config.keys()
        if 'roles' in keys:
            roles_data = await self.config.get('roles')
            for guild in roles_data:
                await self._update_guild_config(
                    int(guild), 'roles', {k.rstrip('_role'): v for k, v in roles_data[guild].items()}
                )
            await self.config.delete('roles')
        if 'ignores' in keys:
            ignore_data = await self.config.get('ignores')
            for guild in ignore_data:
                entry = []
                [entry.append(int(x)) for x in ignore_data[guild]['ignored_channels']]
                if ignore_data[guild]['server_ignore']:
                    entry.append(int(guild))
                await self._update_guild_config(int(guild), 'ignores', entry)
            await self.config.delete('ignores')
        # Start background tasks
        self._maintenance_cycle.start()
        self._owner_validation.start()

    @tasks.loop(seconds=15)
    async def _owner_validation(self):
        # Validate owners
        app_info = await self.heleus.application_info()
        admins = await self.config.get('owners', [])
        admins = list(map(int, admins))
        if app_info.team:
            for member in app_info.team.members:
                if member.membership_state == discord.TeamMembershipState.accepted and member.id not in admins:
                    admins.append(member.id)
        else:
            if app_info.owner.id not in admins:
                admins.append(app_info.owner.id)
                await self.config.set('owners', admins)
        self.heleus.administrators = admins

    @tasks.loop(seconds=1)
    async def _maintenance_cycle(self):
        if not self.db_ignore_flag:
            # Cog management
            await self._cog_scheduler()
            # Prefix updates
            self.heleus.command_prefix = await self.config.get('prefixes')

    async def _exempt_override(self, message):
        if isinstance(message.author, discord.Member):
            if not self.heleus.intents.guilds:
                self.logger.warning('guilds intent is not available! Cannot check exempt_override.')
                return
            if message.guild.owner == message.author:
                return True
            try:
                roles = {x.name.lower() for x in message.author.roles}
                config = await self._get_guild_config(message.guild.id, 'roles', {})
                admin_role = config.get('admin')
                if admin_role in roles:
                    return True
            except (KeyError, AttributeError):
                pass

    async def _skip_check(self, message):
        if isinstance(message.author, discord.Member):
            if not self.heleus.intents.guilds:
                self.logger.warning('guilds intent is not available! Cannot check skip_check.')
                return
            blocked_ids = await self._get_guild_config(message.guild.id, 'ignores', [])
            if message.author.id in blocked_ids:
                return False
            if message.channel.id in blocked_ids:
                return False
            if message.guild.id in blocked_ids:
                return False

    async def create_haste_paste(self, content):
        async with aiohttp.ClientSession() as session:
            async with session.post(f'{self.haste_endpoint}/documents', data=content) as response:
                return await response.json()

    @staticmethod
    def extract_traceback(exception, max_depth=None, include_chain=True):
        return ''.join(traceback.format_exception(type(exception), exception, exception.__traceback__, 
                                                  limit=max_depth, chain=include_chain))

    async def reload_self_module(self):
        self.heleus.unload_extension('cogs.core')
        await self.install_cog('cogs.core')

    async def install_cog(self, name):
        self.logger.debug(f'Attempting to load cog {name}')
        if name in self.heleus.extensions:
            return
        self.heleus.load_extension(name)
        loaded_cogs = await self.config.get('cogs', [])
        if name not in loaded_cogs:
            loaded_cogs.append(name)
            await self.config.set('cogs', loaded_cogs)
        self.logger.debug(f'Cog {name} loaded successfully')

    @commands.Cog.listener()
    async def on_message(self, message):
        instance_state = await self.config.get(self.heleus.instance_id, {})
        current_mode = instance_state.get('mode', CoreMode.down)
        if current_mode in (CoreMode.down, CoreMode.boot):
            return
        if message.author.id in self.heleus.administrators:  # *always* process owner commands
            await self.heleus.process_commands(message)
            return
        if current_mode == CoreMode.maintenance:
            return
        # Exemptions start here
        for exemption in self.global_check_exemptions:
            try:
                result = exemption(message)
                if inspect.isawaitable(result):
                    result = await result
                if result is True:
                    await self.heleus.process_commands(message)
                    return
            except Exception:
                self.logger.exception(f'Removed check exemption "{exemption.__name__}", it was malfunctioning.')
                self.global_check_exemptions.remove(exemption)
        # Pre-checks
        for check in self.global_checks:
            try:
                result = check(message)
                if inspect.isawaitable(result):
                    result = await result
                if result is False:
                    return
            except Exception:
                self.logger.exception(f'Removed check "{check.__name__}", it was malfunctioning.')
                self.global_checks.remove(check)
        await self.heleus.process_commands(message)

    @commands.Cog.listener()
    async def on_command_error(self, context, exception):
        try:
            if isinstance(exception, commands.CommandInvokeError):
