class TriviaBot(BotPlugin):
    def setup(self) -> None:
        super().setup()
        self._active_games = {}

        # Initialize database connection
        db_path = self.config['DB_FILE']
        self.connection = sqlite3.connect(db_path, check_same_thread=False)

    def cleanup(self) -> None:
        super().cleanup()
        self.connection.close()

    def config_schema(self):
        return TRIVIA_SETTINGS

    def apply_config(self, settings):
        if settings and settings != {}:
            merged = dict(chain(TRIVIA_SETTINGS.items(), settings.items()))
        else:
            merged = TRIVIA_SETTINGS
        super(TriviaBot, self).apply_config(merged)

    @botcmd(admin_only=True)
    @arg_botcmd("total_questions", type=int, default=10)
    def trivia_initiate(self, message, total_questions=10):
        if not isinstance(message.to, Room):
            return

        room_id = str(message.to)
        hint_interval = self.config['HINT_INTERVAL']
        question_interval = self.config['QUESTION_INTERVAL']

        game_instance = self._active_games.get(room_id, 
            GameSession(self.connection, room_id, hint_interval, question_interval, 
                       total_questions, partial(self.send, message.to)))

        if game_instance.active:
            return

        game_instance.launch(hint_interval, question_interval)
        self._active_games[room_id] = game_instance
        self.log.info(f"Trivia session started in {message.to} by {message.frm}")

    @botcmd(admin_only=True)
    def trivia_skip(self, message, _):
        room_id = str(message.to)
        game = self._active_games.get(room_id)
        if game is None or not game.active:
            return
        game.advance()

    @botcmd(admin_only=True)
    def trivia_terminate(self, message, _):
        if not isinstance(message.to, Room):
            return

        room_id = str(message.to)
        game = self._active_games.pop(room_id, None)
        if game is None or not game.active:
            return

        game.end()
        self.log.info(f"Trivia session ended in {message.to} by {message.frm}")

    @botcmd(admin_only=True)
    @arg_botcmd("new_name", type=str)
    @arg_botcmd("original_name", type=str)
    def trivia_alias_create(self, message, original_name: str, new_name: str):
        UserMappings(self.connection).register(original_name, new_name)

    @botcmd(admin_only=True)
    @arg_botcmd("new_name", type=str)
    @arg_botcmd("original_name", type=str)
