logger = logging.getLogger(__name__)

# Format enumerations for different output types
class ShellExportFormat(Enum):
    """Shell environment variable export formats."""
    bash_style = auto()
    make_style = auto()

class ActionListStyle(Enum):
    """Output formatting options for action listings."""
    plain_text = auto()
    json_structure = auto()
    names_only = auto()

class ConfigDisplayFormat(Enum):
    """Available formats for displaying configuration data."""
    text_view = auto()
    ini_format = auto()
    json_view = auto()


@dataclass
class EnvironmentExporter(object):
    """Generates shell-compatible export statements from configuration sections."""

    EXPORT_FORMAT_KEY = 'export_output_format'
    OUTPUT_FILE_KEY = 'output_path'

    CLI_CONFIG = {
        'option_includes': {EXPORT_FORMAT_KEY, OUTPUT_FILE_KEY},
        'option_overrides': {
            EXPORT_FORMAT_KEY: {'long_name': 'expfmt', 'short_name': None},
            OUTPUT_FILE_KEY: {'long_name': 'expout', 'short_name': None}
        }
    }

    config_source: Configurable = field()
    target_section: str = field()
    output_file: Path = field(default=None)
    export_format: ShellExportFormat = field(default=ShellExportFormat.bash_style)

    def _generate_exports(self, stream: TextIOBase):
        env_vars: Dict[str, str] = self.config_source.populate(section=self.target_section)

        # Choose format based on selected export style
        if self.export_format == ShellExportFormat.bash_style:
            template = 'export {key}="{value}"\n'
        else:
            template = '{key}={value}\n'

        # Write each environment variable in the required format
        for key, value in env_vars.asdict().items():
            stream.write(template.format(key=key.upper(), value=value))

    def execute_export(self) -> Path:
        """Produce export statements for shell usage."""
        if self.output_file is None:
            self._generate_exports(sys.stdout)
        else:
            with open(self.output_file, 'w') as file_handle:
                self._generate_exports(file_handle)
        return self.output_file

    def __call__(self) -> Path:
        return self.execute_export()


@dataclass
class ActionLister(ApplicationObserver, Dictable):
    """Provides listing of available command-line actions with documentation."""

    LIST_FORMAT_KEY = 'list_output_format'

    CLI_CONFIG = {
        'option_includes': {LIST_FORMAT_KEY},
        'option_overrides': {
            LIST_FORMAT_KEY: {'long_name': 'lstfmt', 'short_name': None}
        }
    }

    display_format: ActionListStyle = field(default=ActionListStyle.plain_text)

    type_mapping: Dict[Type, str] = field(
        default_factory=lambda: {Path: 'path'})

    def __post_init__(self):
        self._cli_mode = False

    def _on_app_creation(self, app: Application, action: Action):
        """Initialize application and action references during callback."""
        if logger.isEnabledFor(logging.DEBUG):
            logger.debug(f'configurator created with {action}')
        self._app = app
        self._action = action

    def _to_dict_representation(self, *args, **kwargs) -> Dict[str, Any]:
        action_cli: ActionCli
        method_docs: Dict[str, str] = {}

        for action_cli in self._app.factory.cli_manager.actions_ordered:
            if not action_cli.first_pass:
                meth: ActionCliMethod
                for name, meth in action_cli.methods.items():
                    meta: ActionMetaData = meth.action_meta_data
                    if self._cli_mode:
                        md = meta.asdict()
                        del md['first_pass']
                        method_docs[name] = md
                    else:
                        method_docs[name] = meta.doc

        return method_docs

    def display_actions(self):
        """Display all actions and their help information."""
        class CustomJSONEncoder(JSONEncoder):
            def default(self, obj: Any) -> str:
                if isinstance(obj, Enum) or inspect.isclass(obj):
                    val = self.type_map.get(obj)
                    if val is None:
                        val = ClassImporter.full_classname(obj)
                    return val
                return super().default(obj)

        self.type_map = self.type_mapping

        def output_json():
            try:
                self._cli_mode = True
                print(self.asjson(indent=4, cls=CustomJSONEncoder))
            finally:
                self._cli_mode = False

        # Dispatch to appropriate output method based on format choice
        formatter: Dict[ActionListStyle, Callable] = {
            ActionListStyle.names_only: lambda: print('\n'.join(self.asdict().keys())),
            ActionListStyle.plain_text: lambda: self.write(),
            ActionListStyle.json_structure: output_json,
        }

        formatter[self.display_format]()

    def __call__(self):
        return self.display_actions()


@dataclass
class ConfigurationViewer(object):
    """Displays application configuration in various formats."""

    CONFIG_FORMAT_KEY = 'config_output_format'
    CONFIG_OUTPUT_KEY = 'config_output_path'

    CLI_CONFIG = {
        'mnemonic_overrides': {'show_config': 'config'},
        'option_includes': {CONFIG_FORMAT_KEY, CONFIG_OUTPUT_KEY},
        'option_overrides': {
            CONFIG_FORMAT_KEY: {'long_name': 'cnffmt', 'short_name': None},
            CONFIG_OUTPUT_KEY: {'long_name': 'cnfout', 'short_name': None}
        }
    }

    config_source: Configurable = field()
    factory_instance: ConfigFactory = field()
    output_file: Path = field(default=None)
    display_format: ConfigDisplayFormat = field(default=ConfigDisplayFormat.text_view)

    def view_configuration(self) -> Configurable:
        """Print the configuration in requested format."""
        fmt = self.display_format
        writer = sys.stdout if self.output_file is None else open(self.output_file, 'w')

        try:
            if fmt == ConfigDisplayFormat.text_view:
                self.config_source.write(writer=writer)
            elif fmt == ConfigDisplayFormat.ini_format:
                print(self.config_source.get_raw_str().rstrip(), file=writer)
            elif fmt == ConfigDisplayFormat.json_view:
                print(self.config_source.asjson(indent=4), file=writer)
        finally:
            if self.output_file is not None:
                writer.close()

        return self.factory_instance

    def __call__(self):
        return self.view_configuration()

from typing import Tuple, Union, Optional, TYPE_CHECKING, List, Any, Dict, Sequence
from fairscale.nn import FullyShardedDataParallel as FS_FSDP
