class _FSDP(FS_FSDP, ShardedModuleMixin):
    """
    Same as FairScale's [`FullyShardedDataParallel`]
    (https://fairscale.readthedocs.io/en/latest/api/nn/fsdp.html) but also implements
    the mixin methods from :class:`allennlp.nn.parallel.sharded_module_mixin.ShardedModuleMixin`.
    """

    def get_original_module(self) -> torch.nn.Module:
        base = self.module
        if isinstance(base, FlattenParamsWrapper):
            base = base.module
        return base


class FairScaleFsdpWrappedModel(DdpWrappedModel):
    """
    The wrapped model type returned from [`FairScaleFsdpWrappedModel.wrap_model`](#wrap_model).
    """

    @staticmethod
    def consolidate_sharded_state(
        shard_paths: Sequence[Union[str, os.PathLike]]
    ) -> StateDictType:
        weights_list = []
        metadata_list = []
        for pth in shard_paths:
            loaded = torch.load(pth, map_location="cpu")
            weights_list.append(loaded["weights"])
            metadata_list.append(loaded["metadata"])
        return _FSDP.consolidate_shard_weights(weights_list, metadata_list)

    def load_state_dict(
        self, state_dict: StateDictType, strict: bool = True
    ) -> LoadStateDictReturnType:
        return self.model.load_local_state_dict(state_dict["weights"], strict=strict)  # type: ignore[operator]

    def state_dict(self, *args, **kwargs) -> StateDictType:
        wts = self.model.local_state_dict(*args, **kwargs)  # type: ignore[operator]
        meta = self.model.local_metadata_dict()
        return {"weights": wts, "metadata": meta}

    def clip_grad_norm_(self, max_norm: Union[float, int]) -> torch.Tensor:
        return self.model.clip_grad_norm_(max_norm)  # type: ignore[operator]

    def init_grad_scaler(self) -> amp.GradScaler:
        return GradScaler()


@DdpAccelerator.register("fairscale_fsdp")
class FairScaleFsdpAccelerator(DdpAccelerator):
    """
    A :class:`allennlp.nn.parallel.ddp_accelerator.DdpAccelerator` for FairScale's [`FullyShardedDataParallel`]
    (https://fairscale.readthedocs.io/en/latest/api/nn/fsdp.html).
    To save memory while initializing a model, you should call [`.wrap_module()`](#wrap_module) on submodules
    as they're created.
    See the :class:`allennlp.modules.transformer.t5.T5` class for an example of how to use this.
    """

    def __init__(
        self,
        *,
        mixed_precision: bool = False,
        reshard_after_forward: bool = True,
        flatten_parameters: bool = True,
        local_rank: Optional[int] = None,
        world_size: Optional[int] = None,
        cuda_device: Union[torch.device, int] = -1,
    ) -> None:
        super().__init__(local_rank=local_rank, world_size=world_size, cuda_device=cuda_device)
        fsdp_opts = {
            "compute_device": self.cuda_device,
            "mixed_precision": mixed_precision,
            "reshard_after_forward": reshard_after_forward,
            "flatten_parameters": flatten_parameters,
        }
        if mixed_precision:
            fsdp_opts.update({
                "move_params_to_cpu": True,
                "clear_autocast_cache": True,
            })
        self._fsdp_kwargs = fsdp_opts

    def wrap_model(self, model: "Model") -> Tuple["Model", DdpWrappedModel]:
        fsdp_instance = _FSDP(model, **self._fsdp_kwargs)
        if not self._fsdp_kwargs["mixed_precision"] and self.cuda_device != torch.device("cpu"):
            fsdp_instance = fsdp_instance.cuda()

        # Reset lazy initialization for any previously wrapped submodules
        for mod in fsdp_instance.modules():
            if isinstance(mod, _FSDP):
                mod._reset_lazy_init()

        return model, FairScaleFsdpWrappedModel(
            fsdp_instance,
            local_rank=self.local_rank,
            world_size=self.world_size,
        )

    def wrap_module(self, module: torch.nn.Module) -> torch.nn.Module:
        with enable_wrap(wrapper_cls=_FSDP, **self._fsdp_kwargs):
            result = wrap(module)
        return result

from . import tensor_shape
from . import errors
from typing import Tuple, Optional
import numpy as np

class MemoryBuffer:
    def __init__(self, storage=None, start_index=0, layout="C"):
        self._storage = storage
        self._start_index = start_index
        self._layout = layout

    def get_storage(self):
        return self._storage

    def get_start_offset(self):
        return self._start_index

    def get_layout(self):
        return self._layout

class Tensor:
    def __init__(self,
                 dtype: types_pb2.DataType = types_pb2.DT_FLOAT,
                 dims: tensor_shape.TensorShape = None,
                 mem: MemoryBuffer = None):
        if dims is None:
            dims = tensor_shape.TensorShape()
        dims.set_element_type(dtype)
        self._dimensions = dims
        self._memory = mem

    def __repr__(self):
        return f"Tensor(is_ready={self.is_ready()}, shape={self.dims()!r})"

    def dims(self) -> tensor_shape.TensorShape:
        return self._dimensions

    def dtype(self) -> types_pb2.DataType:
        return self.dims().element_type()

    def rank(self) -> int:
        return self.dims().rank()

    def size_at(self, axis: int) -> int:
        return self.dims().size(axis)

    def total_elements(self) -> int:
        return self.dims().num_elements()

    def is_ready(self) -> bool:
        """Check if tensor has valid data storage or is empty."""
        has_valid_buffer = (self._memory is not None and 
                           self._memory.get_storage() is not None)
        return has_valid_buffer or self.total_elements() == 0

    def assign_buffer(self, mem: MemoryBuffer):
        self._memory = mem

    def to_numpy(self) -> Tuple[errors.Status, Optional[np.ndarray]]:
        if not self.is_ready():
            return errors.FailedPrecondition("Tensor not initialized"), None

        shape_info = self.dims()
        element_dtype = shape_info.element_type()

        if element_dtype is None:
            return errors.Unimplemented(f"Unsupported data type: {shape_info.element_type()}"), None

        if self.total_elements() > 0:
            # Create array using direct memory mapping
            shape_list = shape_info.as_list()
            storage_data = self._memory.get_storage()
            offset_val = self._memory.get_start_offset()
            layout_mode = self._memory.get_layout()

            arr = np.ndarray.__new__(np.ndarray,
                                    shape=shape_list,
                                    dtype=element_dtype,
                                    buffer=storage_data,
                                    offset=offset_val,
                                    order=layout_mode)
        else:
            # For zero-sized tensors, create empty array
            arr = np.zeros(shape_info.as_list(), dtype=element_dtype)

        return errors.Status.OK(), arr

