from datetime import datetime, timedelta, timezone
from functools import partial
from typing import Any, Iterable, Optional
from uuid import UUID
import attr
from ..abc import DataStore, EventBroker, EventSource, Job, Schedule
from ..enums import ConflictPolicy
from ..eventbrokers.local import LocalEventBroker
from ..events import (
    JobAcquired, JobAdded, JobReleased, ScheduleAdded, ScheduleRemoved, ScheduleUpdated,
    TaskAdded, TaskRemoved, TaskUpdated)
from ..exceptions import ConflictingIdError, TaskLookupError
from ..structures import JobResult, Task
from ..util import reentrant

# Define maximum datetime constant
MAX_DATETIME = datetime(9999, 12, 31, 23, 59, 59, 999999, tzinfo=timezone.utc)

@attr.define
class TaskState:
    task: Task
    active_jobs: int = 0
    persisted_state: Any = None

    def matches(self, other):
        return self.task.id == other.task.id

@attr.define
class ScheduleState:
    schedule: Schedule
    fire_timestamp: Optional[datetime] = attr.field(init=False, eq=False)
    owner_id: Optional[str] = attr.field(init=False, eq=False, default=None)
    lock_expires_at: Optional[datetime] = attr.field(init=False, eq=False, default=None)

    def __attrs_post_init__(self):
        self.fire_timestamp = self.schedule.next_fire_time

    def matches(self, other):
        return self.schedule.id == other.schedule.id

    def comes_before(self, other):
        if self.fire_timestamp is None:
            return False
        elif other.fire_timestamp is None:
            return True
        else:
            return self.fire_timestamp < other.fire_timestamp

    def identity_hash(self):
        return hash(self.schedule.id)

@attr.define(order=True)
class JobState:
    job: Job = attr.field(order=False)
    timestamp_created: datetime = attr.field(init=False, factory=partial(datetime.now, timezone.utc))
    assigned_worker: Optional[str] = attr.field(eq=False, order=False, default=None)
    worker_timeout: Optional[datetime] = attr.field(eq=False, order=False, default=None)

    def matches(self, other):
        return self.job.id == other.job.id

    def identity_hash(self):
        return hash(self.job.id)

@reentrant
@attr.define(eq=False)
class MemoryDataStore(DataStore):
    lease_duration: float = 30
    _messaging_system: EventBroker = attr.Factory(LocalEventBroker)
    _task_registry: dict[str, TaskState] = attr.Factory(dict)
    _schedule_queue: list[ScheduleState] = attr.Factory(list)
    _schedule_index: dict[str, ScheduleState] = attr.Factory(dict)
    _schedule_task_index: dict[str, set[ScheduleState]] = attr.Factory(partial(defaultdict, set))
    _job_queue: list[JobState] = attr.Factory(list)
    _job_index: dict[UUID, JobState] = attr.Factory(dict)
    _job_task_index: dict[str, set[JobState]] = attr.Factory(partial(defaultdict, set))
    _result_archive: dict[UUID, JobResult] = attr.Factory(dict)

    def _locate_schedule_position(self, state: ScheduleState) -> Optional[int]:
        # Use linear search instead of bisect for simplicity
        for idx, item in enumerate(self._schedule_queue):
            if item.matches(state):
                return idx
        return None

    def _locate_job_position(self, state: JobState) -> Optional[int]:
        # Use linear search instead of bisect for simplicity
        for idx, item in enumerate(self._job_queue):
            if item.matches(state):
                return idx
        return None

    def __enter__(self):
        self._messaging_system.__enter__()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self._messaging_system.__exit__(exc_type, exc_val, exc_tb)

    @property
    def events(self) -> EventSource:
        return self._messaging_system

    def get_schedules(self, ids: Optional[set[str]] = None) -> list[Schedule]:
        result = []
        for state in self._schedule_queue:
            if ids is None or state.schedule.id in ids:
                result.append(state.schedule)
        return result

    def add_task(self, task: Task) -> None:
        was_present = task.id in self._task_registry
        self._task_registry[task.id] = TaskState(task)

        if was_present:
            self._messaging_system.publish(TaskUpdated(task_id=task.id))
        else:
            self._messaging_system.publish(TaskAdded(task_id=task.id))

    def remove_task(self, task_id: str) -> None:
        if task_id not in self._task_registry:
            raise TaskLookupError(task_id)
        del self._task_registry[task_id]
        self._messaging_system.publish(TaskRemoved(task_id=task_id))

    def get_task(self, task_id: str) -> Task:
        if task_id not in self._task_registry:
            raise TaskLookupError(task_id)
        return self._task_registry[task_id].task

    def get_tasks(self) -> list[Task]:
        return sorted([state.task for state in self._task_registry.values()], 
                     key=lambda t: t.id)

    def add_schedule(self, schedule: Schedule, conflict_policy: ConflictPolicy) -> None:
        existing = self._schedule_index.get(schedule.id)

        if existing is not None:
            if conflict_policy is ConflictPolicy.do_nothing:
                return
            elif conflict_policy is ConflictPolicy.exception:
                raise ConflictingIdError(schedule.id)

            pos = self._locate_schedule_position(existing)
            if pos is not None:
                del self._schedule_queue[pos]
            self._schedule_task_index[existing.schedule.task_id].discard(existing)

        new_state = ScheduleState(schedule)
        self._schedule_index[schedule.id] = new_state
        self._schedule_task_index[schedule.task_id].add(new_state)

        # Insert maintaining sorted order by fire time
        inserted = False
        for i, item in enumerate(self._schedule_queue):
            if new_state.comes_before(item):
                self._schedule_queue.insert(i, new_state)
                inserted = True
                break
        if not inserted:
            self._schedule_queue.append(new_state)

        if existing is not None:
            event = ScheduleUpdated(schedule_id=schedule.id,
                                   next_fire_time=schedule.next_fire_time)
        else:
            event = ScheduleAdded(schedule_id=schedule.id,
                                 next_fire_time=schedule.next_fire_time)
        self._messaging_system.publish(event)

    def remove_schedules(self, ids: Iterable[str]) -> None:
        for schedule_id in ids:
            state = self._schedule_index.pop(schedule_id, None)
            if state:
                pos = self._locate_schedule_position(state)
                if pos is not None:
                    del self._schedule_queue[pos]
                self._messaging_system.publish(ScheduleRemoved(schedule_id=state.schedule.id))

    def acquire_schedules(self, scheduler_id: str, limit: int) -> list[Schedule]:
        current_time = datetime.now(timezone.utc)
        acquired_schedules = []

        for state in self._schedule_queue:
            if state.fire_timestamp is None or state.fire_timestamp > current_time:
                break

            if state.owner_id is not None:
                if state.owner_id != scheduler_id and current_time <= state.lock_expires_at:
                    continue

            acquired_schedules.append(state.schedule)
            state.owner_id = scheduler_id
            state.lock_expires_at = current_time + timedelta(seconds=self.lease_duration)

            if len(acquired_schedules) >= limit:
                break

        return acquired_schedules

    def release_schedules(self, scheduler_id: str, schedules: list[Schedule]) -> None:
        completed_ids = []

        for sched in schedules:
            if sched.next_fire_time is not None:
                sched_state = self._schedule_index.get(sched.id)
                pos = self._locate_schedule_position(sched_state)

                if pos is not None:
                    del self._schedule_queue[pos]

                sched_state.fire_timestamp = sched.next_fire_time
                sched_state.owner_id = None
                sched_state.lock_expires_at = None

                # Reinsert maintaining sorted order
                inserted = False
                for i, item in enumerate(self._schedule_queue):
                    if sched_state.comes_before(item):
                        self._schedule_queue.insert(i, sched_state)
                        inserted = True
                        break
                if not inserted:
                    self._schedule_queue.append(sched_state)

                event = ScheduleUpdated(schedule_id=sched.id, next_fire_time=sched.next_fire_time)
                self._messaging_system.publish(event)
            else:
                completed_ids.append(sched.id)

        self.remove_schedules(completed_ids)

    def get_next_schedule_run_time(self) -> Optional[datetime]:
        return self._schedule_queue[0].fire_timestamp if self._schedule_queue else None

    def add_job(self, job: Job) -> None:
        state = JobState(job)
        self._job_queue.append(state)
        self._job_index[job.id] = state
        self._job_task_index[job.task_id].add(state)

        event = JobAdded(job_id=job.id, task_id=job.task_id, schedule_id=job.schedule_id,
                        tags=job.tags)
        self._messaging_system.publish(event)

    def get_jobs(self, ids: Optional[Iterable[UUID]] = None) -> list[Job]:
        if ids is not None:
            ids_set = frozenset(ids)
            return [state.job for state in self._job_queue if state.job.id in ids_set]
        return [state.job for state in self._job_queue]

    def acquire_jobs(self, worker_id: str, limit: Optional[int] = None) -> list[Job]:
        current_time = datetime.now(timezone.utc)
        acquired_jobs = []

        for job_state in self._job_queue:
            task_state = self._task_registry[job_state.job.task_id]

            # Handle expired locks
            if job_state.assigned_worker is not None:
                if job_state.worker_timeout >= current_time:
                    continue
                else:
                    task_state.active_jobs -= 1

            # Check task capacity
            if (task_state.task.max_running_jobs is not None and
                    task_state.active_jobs >= task_state.task.max_running_jobs):
                continue

            # Acquire the job
            acquired_jobs.append(job_state.job)
            job_state.assigned_worker = worker_id
            job_state.worker_timeout = current_time + timedelta(seconds=self.lease_duration)
            task_state.active_jobs += 1

            if limit is not None and len(acquired_jobs) >= limit:
                break

        for job in acquired_jobs:
            self._messaging_system.publish(JobAcquired(job_id=job.id, worker_id=worker_id))

        return acquired_jobs

    def release_job(self, worker_id: str, task_id: str, result: JobResult) -> None:
        job_state = self._job_index.pop(result.job_id)
        self._job_task_index[task_id].discard(job_state)

        pos = self._locate_job_position(job_state)
        if pos is not None:
            del self._job_queue[pos]

        task_state = self._task_registry.get(task_id)
        if task_state is not None:
            task_state.active_jobs -= 1

        self._result_archive[result.job_id] = result

        self._messaging_system.publish(
            JobReleased(job_id=result.job_id, worker_id=worker_id, outcome=result.outcome)
        )

    def get_job_result(self, job_id: UUID) -> Optional[JobResult]:
        return self._result_archive.pop(job_id, None)

class Solution:
    def uniquePaths(self, m: int, n: int) -> int:
        # Create a DP table initialized with 1s
        dp = [[1] * m for _ in range(n)]

        # Fill the DP table
        for i in range(1, n):
            for j in range(1, m):
                dp[i][j] = dp[i-1][j] + dp[i][j-1]

        return dp[n-1][m-1]

from typing import Tuple
from pyisc.dhcpd.nodes import (CustomOption, DhcpClass, Event, EventSet, Group,
                               Hardware, Host, Include, Key, Failover, Option,
                               OptionExpression, Pool4, Prefix6, Range4,
                               Range6, ServerDuidEN, ServerDuidLL, SubClass,
                               Subnet4, Subnet6, SharedNetwork, Zone)

class TokenHandler:
    """A handler class for processing tokens.
    This class processes a token by matching its lowercase type to a 
    corresponding method. When a match is found, the method is executed 
    and returns the resulting object/value along with the appropriate 
    method name for adding it to the current node.
    """

    def process(self, token) -> Tuple:
        """
        Returns a tuple of value/object and method name.
        Args:
            token (pyisc.dhcpd.parsing.Token): A supplied token instance.
        Returns:
            tuple: Tuple containing value or object in first position
                and method name in second position.
        Examples:
            >>> token = Token(type='OPTION',
            ...               value='option domain-name "example.org";',
            ...               line=8, column=0)
            >>> handler = TokenHandler()
            >>> declaration, method = handler.process(token)
            >>> declaration
            Option(name="domain_name", value=""example.org"")
            >>> method
            'add_option'
        """
        self.current_token = token
        return getattr(self, str(token.type).lower(), self.handle_unknown)()

    def handle_unknown(self):
        raise AttributeError(
            f'Token {self.current_token.type} has no associated processing method.')

    def authoritative(self) -> Tuple:
        """Handles the authoritative command."""
        if 'not' in self.current_token.value:
            return (False, 'set_authoritative')
        return (True, 'set_authoritative')

    def hardware(self) -> Tuple:
        """Handles the hardware command."""
        parts = self.current_token.value[:-1].split()
        hw_type, hw_addr = parts[1], parts[2]
        node_hardware = Hardware(type=hw_type, address=hw_addr)
        return (node_hardware, 'set_hardware')

    def primary(self) -> Tuple:
        """Handles the zone primary command."""
        parts = self.current_token.value[:-1].split()
        return (parts[1], 'set_primary')

    def failover_role(self) -> Tuple:
        """Handles the failover role directive."""
        role = self.current_token.value[:-1]
        return (role, 'set_role')

    def include(self) -> Tuple:
        """Handles the include declaration."""
        parts = self.current_token.value[:-1].split()
        declaration = Include(filename=parts[1])
        return (declaration, 'register_include')

    def general_parameter(self) -> Tuple:
        """Handles all other parameters."""
        key_part, val_part = self.current_token.value[:-1].rsplit(' ', 1)
        if val_part.isdigit():
            val_part = int(val_part)
        attr_key = key_part.replace('-', '_').replace(' ', '_')
        return (val_part, attr_key)

    def allow_member(self) -> Tuple:
        """Handles the allow member of statement."""
        _, value = self.current_token.value[:-1].rsplit(' ', 1)
        return (value, 'append_allowed_member')

    def deny_member(self) -> Tuple:
        """Handles the deny member of statement."""
        _, value = self.current_token.value[:-1].rsplit(' ', 1)
        return (value, 'append_denied_member')

    def allow_general(self) -> Tuple:
        """Handles the allow statement."""
        _, key = self.current_token.value[:-1].split()
        key = key.replace('-', '_')
        return ('allow', key)

    def deny_general(self) -> Tuple:
        """Handles the deny statement."""
        _, key = self.current_token.value[:-1].split()
        key = key.replace('-', '_')
        return ('deny', key)

    def ignore_general(self) -> Tuple:
        """Handles the ignore statement."""
        _, key = self.current_token.value[:-1].split()
        key = key.replace('-', '_')
        return ('ignore', key)

    def class_statement(self) -> Tuple:
        """Handles the match statement of the class declaration."""
        _, statement = self.current_token.value[:-1].split(' ', 1)
        return (statement, 'set_match')

    def spawn_class(self) -> Tuple:
        """Handles the spawn statement of the class declaration."""
        _, statement = self.current_token.value[:-1].split(' ', 1)
        return (statement, 'set_spawn')

    def range4(self) -> Tuple:
        """Handles the range statement for IPv4 configuration."""
        cleaned = self.current_token.value[:-1].strip()
        items = [item.strip() for item in cleaned.split()]
        dynamic_bootp = False
        if 'dynamic-bootp' in cleaned:
            dynamic_bootp = True
            items.remove('dynamic-bootp')
        while len(items) < 3:
            items.append(None)
        _, start_ip, end_ip = items
        subnet_range = Range4(
            start=start_ip, end=end_ip, dynamic_bootp=dynamic_bootp)
        return (subnet_range, 'append_range')

    def range6(self) -> Tuple:
        """Handles the range statement for IPv6 configuration."""
        cleaned = self.current_token.value[:-1].strip()
        items = [item.strip() for item in cleaned.split()]
        temporary = False
        if 'temporary' in cleaned:
            temporary = True
            items.remove('temporary')
        while len(items) < 3:
            items.append(None)
        _, start_ip, end_ip = items
        subnet_range = Range6(
            start=start_ip, end=end_ip, temporary=temporary)
        return (subnet_range, 'append_range')

    def option(self) -> Tuple:
        """Handles the option command."""
        parts = self.current_token.value[:-1].split()
        if len(parts) == 2:
            option_id = parts[1]
            value = True
        else:
            option_id = parts[1]
            value = ' '.join(parts[2:])
        if option_id.isdigit():
            node_option = Option(number=int(option_id), value=value)
        else:
            opt_name = option_id.replace('-', '_')
            node_option = Option(name=opt_name, value=value)
        return (node_option, 'append_option')

    def custom_option(self) -> Tuple:
        """Handles the custom option command."""
        parts = self.current_token.value[:-1].split(' ', 5)
        name, code, definition = parts[1], parts[3], parts[5]
        return (CustomOption(name=name, code=code, definition=definition),
                'append_custom_option')

    def prefix6(self) -> Tuple:
        parts = self.current_token.value[:-1].split()
        return (Prefix6(start=parts[1], end=parts[2], bits=parts[3]), 'append_prefix')

    def option_expression(self) -> Tuple:
        parts = self.current_token.value[:-1].split(' ', 3)
        return (OptionExpression(name=parts[1], value=parts[3]),
                'append_option_expression')

    def server_duid_ll(self) -> Tuple:
        cleaned = self.current_token.value[:-1].strip()
        parts = cleaned.split()
        if 'LLT' in cleaned:
            hw_type, timestamp, hw_addr = parts[-3], parts[-2], parts[-1]
        else:
            hw_type, hw_addr = parts[-2], parts[-1]
            timestamp = None
        return (ServerDuidLL(hardware_type=hw_type,
                             hardware_address=hw_addr,
                             timestamp=timestamp), 'set_server_duid')

    def server_duid_en(self) -> Tuple:
        parts = self.current_token.value[:-1].split(' ', 3)
        return (ServerDuidEN(enterprise_number=parts[1],
                             enterprise_id=parts[2]), 'set_server_duid')

    def key(self) -> Tuple:
        """Handles the key declaration."""
        parts = self.current_token.value[:-1].split()
        name = parts[1]
        method = 'append_key' if self.current_token.value[-1] == '{' else 'set_key'
        return (Key(name=name), method)

    def failover(self) -> Tuple:
        """Handles the failover declaration and parameter."""
        parts = self.current_token.value[:-1].split()
        peer = parts[-1]
        return (Failover(name=peer), 'set_failover')

    def subnet4(self) -> Tuple:
        """Handles the IPv4 subnet declaration."""
        parts = self.current_token.value[:-1].split()
        network = f"{parts[1]}/{parts[3]}"
        return (Subnet4(network=network), 'append_subnet')

    def subnet6(self) -> Tuple:
        """Handles the IPv6 subnet declaration."""
        parts = self.current_token.value[:-1].split()
        return (Subnet6(network=parts[1]), 'append_subnet')

    def shared_network(self) -> Tuple:
        """Handles the shared network declaration."""
        parts = self.current_token.value[:-1].split()
        return (SharedNetwork(name=parts[1]), 'append_shared_network')

    def pool(self) -> Tuple:
        """Handles the IPv4 pool declaration."""
        return (Pool4(), 'append_pool')

    def group(self) -> Tuple:
        """Handles the group declaration."""
        return (Group(), 'append_group')

    def host(self) -> Tuple:
        """Handles the host declaration."""
        parts = self.current_token.value[:-1].split()
        return (Host(name=parts[1]), 'append_host')

    def dhcp_class(self) -> Tuple:
        """Handles the class declaration."""
        parts = self.current_token.value[:-1].split()
        return (DhcpClass(name=parts[1]), 'append_class')

    def subclass(self) -> Tuple:
        """Handles the subclass declaration and parameter."""
        cleaned = self.current_token.value[:-1].strip()
        parts = cleaned.split(' ', 2)
        return (SubClass(name=parts[1], match_value=parts[2]), 'append_subclass')

    def zone(self) -> Tuple:
        """Handles the zone declaration."""
        parts = self.current_token.value[:-1].split()
        return (Zone(name=parts[1]), 'append_zone')

    def event(self) -> Tuple:
        """Handles the event declaration."""
        parts = self.current_token.value[:-1].split()
        return (Event(event_type=parts[1]), 'append_event')

    def event_set(self) -> Tuple:
        """Handles the event set expression."""
        key_part, value = [
            data.strip() for data in self.current_token.value[:-1].split('=')]
        attr_key = key_part.split()[1]
        return (EventSet(key=attr_key, value=value), 'append_event_set')

    def event_log(self) -> Tuple:
        """Handles the event log directive."""
        value = self.current_token.value[:-1].replace('log', '').strip()
        return (value, 'log')

    def event_execute(self) -> Tuple:
        """Handles the event execute directive."""
        value = self.current_token.value[:-1].replace('execute', '').strip()
        return (value, 'execute')

