def get_artist_location(artist, ax, fig):
    renderer = fig.canvas.get_renderer()
    bbox = None
    # Try different methods depending on matplotlib version
    for method_name in ('get_tightbbox', 'get_bbox', 'get_window_extent'):
        method = getattr(artist, method_name, None)
        if callable(method):
            try:
                bbox = method(renderer)
                break
            except AttributeError:
                continue
    if bbox is None:
        raise RuntimeError("Could not retrieve bounding box from artist.")

    transformed_bbox = bbox.transformed(ax.transData.inverted())
    return (transformed_bbox.x0, transformed_bbox.x1,
            transformed_bbox.y0, transformed_bbox.y1)

def get_function_call_str(frame, top=True):
    func_name = frame.f_code.co_name
    args_info = inspect.getargvalues(frame)
    arg_vals = {}
    for name in args_info.args:
        if name not in ('self', 'cls'):
            val = args_info.locals[name]
            arg_vals[name] = repr(val) if isinstance(val, str) else val
    if args_info.varargs:
        for i, val in enumerate(args_info.locals[args_info.varargs]):
            arg_vals[f"*{args_info.varargs}[{i}]"] = repr(val) if isinstance(val, str) else val
    if args_info.varkw:
        for key, val in args_info.locals[args_info.varkw].items():
            arg_vals[key] = repr(val) if isinstance(val, str) else val

    parts = []
    for k, v in arg_vals.items():
        parts.append(f"{k}={v}")
    args_str = ', '.join(parts)

    top_label = 's = RV' if top else 's'
    return f"{top_label}.{func_name}({args_str})"

def split_rdb_file_first_column(file_path, threshold, new_file, old_file=None):
    import numpy as np
    data = np.loadtxt(file_path, skiprows=2)
    if data.ndim == 0:
        data = np.array([data])
    first_col = data[:, 0] if data.ndim > 1 else data

    mask = first_col > threshold
    keep_rows = int(mask.sum())
    total_lines = len(first_col)

    if keep_rows == 0:
        print(f'No observations after {threshold} in file {file_path}')
        return

    with open(file_path, 'r') as f:
        lines = f.readlines()

    header = lines[:2]
    body = lines[2:]
    kept_body = [line for line, m in zip(body, mask) if m]
    discarded_body = [line for line, m in zip(body, ~mask) if not m]

    with open(new_file, 'w') as f:
        f.writelines(header + kept_body)

    if old_file is not None:
        with open(old_file, 'w') as f:
            f.writelines(header + discarded_body)

def find_data_file(filename):
    script_dir = os.path.dirname(os.path.abspath(__file__))
    candidate_paths = [
        os.path.join(script_dir, '..', 'data', filename),
        os.path.join(script_dir, 'data', filename),
        os.path.join(script_dir, filename)
    ]
    for path in candidate_paths:
        if os.path.isfile(path):
            return os.path.normpath(path)
    raise FileNotFoundError(f'Cannot locate "{filename}" in expected data directories.')

