# Custom context managers for handling coroutines and database connections

from collections.abc import Coroutine
from .log import logger

class _AsyncContextWrapper(Coroutine):
    __slots__ = ('_wrapped_coro', '_instance')

    def __init__(self, coro):
        self._wrapped_coro = coro
        self._instance = None

    def send(self, value):
        return self._wrapped_coro.send(value)

    def throw(self, typ, val=None, tb=None):
        if val is None:
            return self._wrapped_coro.throw(typ)
        elif tb is None:
            return self._wrapped_coro.throw(typ, val)
        else:
            return self._wrapped_coro.throw(typ, val, tb)

    def close(self):
        return self._wrapped_coro.close()

    @property
    def gi_frame(self):
        return self._wrapped_coro.gi_frame

    @property
    def gi_running(self):
        return self._wrapped_coro.gi_running

    @property
    def gi_code(self):
        return self._wrapped_coro.gi_code

    def __next__(self):
        return self.send(None)

    def __iter__(self):
        return self._wrapped_coro.__await__()

    def __await__(self):
        return self._wrapped_coro.__await__()

    async def __aenter__(self):
        self._instance = await self._wrapped_coro
        return self._instance

    async def __aexit__(self, exc_type, exc, tb):
        await self._instance.close()
        self._instance = None


class _ConnectionAsyncContext(_AsyncContextWrapper):
    async def __aexit__(self, exc_type, exc, tb):
        if exc_type is not None:
            self._instance.close()
        else:
            await self._instance.ensure_closed()
        self._instance = None


class _PoolAsyncContext(_AsyncContextWrapper):
    async def __aexit__(self, exc_type, exc, tb):
        self._instance.close()
        await self._instance.wait_closed()
        self._instance = None


class _SAConnectionAsyncContext(_AsyncContextWrapper):
    async def __aiter__(self):
        result = await self._wrapped_coro
        return result


class _TransactionAsyncContext(_AsyncContextWrapper):
    async def __aexit__(self, exc_type, exc, tb):
        if exc_type:
            await self._instance.rollback()
        else:
            if self._instance.is_active:
                await self._instance.commit()
        self._instance = None


class _PoolAcquireAsyncContext:
    __slots__ = ('_acquire_coro', '_connection', '_pool_handle')

    def __init__(self, coro, pool):
        self._acquire_coro = coro
        self._connection = None
        self._pool_handle = pool

    async def __aenter__(self):
        self._connection = await self._acquire_coro
        return self._connection

    async def __aexit__(self, exc_type, exc, tb):
        try:
            await self._pool_handle.release(self._connection)
        finally:
            self._pool_handle = None
            self._connection = None


class _PoolConnectionAsyncContextManager:
    """Context manager implementation.
    Enables acquiring and releasing a connection around a block:
        with (yield from pool) as conn:
            cur = yield from conn.cursor()
    while failing loudly when accidentally using:
        with pool:
            <block>
    """
    __slots__ = ('_pool_ref', '_conn_ref')

    def __init__(self, pool, conn):
        self._pool_ref = pool
        self._conn_ref = conn

    def __enter__(self):
        assert self._conn_ref
        return self._conn_ref

    def __exit__(self, exc_type, exc_val, exc_tb):
        try:
            self._pool_ref.release(self._conn_ref)
        finally:
            self._pool_ref = None
            self._conn_ref = None

    async def __aenter__(self):
        assert not self._conn_ref
        self._conn_ref = await self._pool_ref.acquire()
        return self._conn_ref

    async def __aexit__(self, exc_type, exc_val, exc_tb):
        try:
            await self._pool_ref.release(self._conn_ref)
        finally:
            self._pool_ref = None
            self._conn_ref = None


class TaskTransactionAsyncContext:
    __task_registry = dict()
    __slots__ = ('_coro_ref', '_connection_ref', '_pool_ref', '_depth_counter', 
                 '_callback_queue', '__transaction_started', '__committed_flag', '__rolled_back_flag')

    def __init__(self, coro, pool):
        self._coro_ref = coro
        self._connection_ref = None
        self._pool_ref = pool
        self._depth_counter = 0
        self._callback_queue = []

        task = asyncio.Task.current_task()
        if task in self.__task_registry:
            raise Exception('task already registered in registry')
        self.__task_registry[task] = self

        self.__transaction_started = False
        self.__committed_flag = False
        self.__rolled_back_flag = False

    @classmethod
    def instantiate(cls, coro, pool) -> 'TaskTransactionAsyncContext':
        task = asyncio.Task.current_task()
        if task in cls.__task_registry:
            return cls.__task_registry[task]
        return TaskTransactionAsyncContext(coro, pool)

    @classmethod
    def retrieve_transaction_context(cls, task=None) -> 'TaskTransactionAsyncContext':
        if not task:
            task = asyncio.Task.current_task()
        return cls.__task_registry.get(task)

    def register_commit_callback(self, callback_func, **kwargs):
        self._callback_queue.append((callback_func, kwargs))

    async def start_transaction(self):
        if not self.__transaction_started:
            await self._connection_ref.begin()
            self.__transaction_started = True

    async def finalize_commit(self):
        if self._depth_counter <= 1:
            await self._connection_ref.commit()
            for callback_func, kwargs in self._callback_queue:
                try:
                    if asyncio.iscoroutine(callback_func):
                        await callback_func(**kwargs)
                    else:
                        callback_func(**kwargs)
                except Exception as e:
                    logger.exception(e)
            self._callback_queue.clear()
            self.__committed_flag = True

    async def rollback_transaction(self):
        await self._connection_ref.rollback()
        self._callback_queue.clear()
        self.__rolled_back_flag = True

    async def __aenter__(self):
        self._depth_counter += 1
        if not self._connection_ref:
            self._connection_ref = await self._coro_ref
        return TransactionConnectionWrapper(self._connection_ref)

    async def __aexit__(self, exc_type, exc, tb):
        self._depth_counter -= 1
        if self._depth_counter <= 0:
            if self.__transaction_started and not self.__committed_flag and not self.__rolled_back_flag:
                if not exc_type:
                    logger.warning('SQL operation was not committed. Attempting automatic commit via TaskTransactionAsyncContext')
                    await self.finalize_commit()

            self.__task_registry.pop(asyncio.Task.current_task(), None)
            try:
                await self._pool_ref.release(self._connection_ref)
            finally:
                self._pool_ref = None
                self._connection_ref = None
                self.__transaction_started = False
                self.__committed_flag = False
                self.__rolled_back_flag = False


class TransactionConnectionWrapper:
    def __init__(self, conn):
        self.__underlying_conn = conn

    def __str__(self):
        return 'TransactionConnectionWrapper ' + str(self.__underlying_conn)

    async def initiate_transaction(self):
        """Begin transaction."""
        if TaskTransactionAsyncContext.retrieve_transaction_context():
            await TaskTransactionAsyncContext.retrieve_transaction_context().start_transaction()
        else:
            await self.__underlying_conn.begin()

    async def confirm_changes(self):
        """Commit changes to stable storage."""
        if TaskTransactionAsyncContext.retrieve_transaction_context():
            await TaskTransactionAsyncContext.retrieve_transaction_context().finalize_commit()
        else:
            await self.__underlying_conn.commit()

    async def undo_changes(self):
        """Roll back the current transaction."""
        if TaskTransactionAsyncContext.retrieve_transaction_context():
            await TaskTransactionAsyncContext.retrieve_transaction_context().rollback_transaction()
        else:
            await self.__underlying_conn.rollback()

    def __getattr__(self, item):
        return getattr(self.__underlying_conn, item)

    @property
    def underlying_connection(self):
        return self.__underlying_conn

