import re
from typing import Any, Dict, List, NoReturn, Optional, Tuple, Type, TypeVar
import sqlalchemy as sa
from sqlalchemy.exc import IntegrityError
from sqlalchemy.ext.asyncio import AsyncSession
from sqlalchemy.orm import selectinload
from app.db.base import Base
from app.db.deps import get_db
from app.db.exceptions import DatabaseValidationError
from app.db.utils import operators_map
from app.utils.datetime import utcnow
import logging
logger = logging.getLogger(__name__)

TBase = TypeVar("TBase", bound="PersistentModel")

class AbstractBase(Base):
    """Minimal base class without any fields"""
    __abstract__ = True

class PersistentModel(AbstractBase):
    """Abstract ORM model with common timestamped fields"""
    __abstract__ = True

    # Core metadata columns
    pk_id = sa.Column(sa.Integer, primary_key=True)
    creation_time = sa.Column(sa.DateTime(timezone=True), default=utcnow, nullable=False)
    last_modified = sa.Column(sa.DateTime(timezone=True), default=utcnow, onupdate=utcnow, nullable=False)

    def __repr__(self) -> str:
        return f"<{self.__class__.__name__}(pk_id={self.pk_id})>"

    @classmethod
    def _handle_integrity_violation(cls, err: IntegrityError) -> NoReturn:
        raw_msg = ""
        if hasattr(err.orig, 'args') and err.orig.args:
            raw_msg = str(err.orig.args[0])

        # Try matching known constraint violation patterns
        unique_match = re.search(r"Key \((.*?)\)=\(.*\) already exists", raw_msg)
        range_match = re.search(r"Key \((.*?)\)=\(.*\) conflicts with existing key", raw_msg)
        fk_match = re.search(r"Key \((.*?)\)=\(.*\) is not present in table", raw_msg)

        if unique_match:
            field = unique_match.group(1).strip()
            raise DatabaseValidationError(f"Duplicate entry for {cls.__name__}", field) from err
        elif range_match:
            field = range_match.group(1).split(",")[0].strip()
            raise DatabaseValidationError(f"Overlapping range for {cls.__name__}", field) from err
        elif fk_match:
            field = fk_match.group(1).strip()
            raise DatabaseValidationError(f"Invalid foreign key reference in {cls.__name__}", field) from err

        logger.warning("Unrecognized integrity issue in %s: %s", cls.__name__, err)
        raise err

    @classmethod
    def _prepare_query(
        cls,
        eager_load: Optional[Tuple[str, ...]] = None,
        extra_options: Optional[List[Any]] = None
    ) -> Any:
        stmt = sa.select(cls)
        if eager_load:
            if extra_options is None:
                extra_options = []
            loaders = [selectinload(getattr(cls, rel_name)) for rel_name in eager_load]
            extra_options.extend(loaders)
            stmt = stmt.options(*extra_options).execution_options(populate_existing=True)
        return stmt

    @classmethod
    async def fetch_all(cls: Type[TBase], eager_load: Optional[Tuple[str, ...]] = None) -> List[TBase]:
        query = cls._prepare_query(eager_load)
        session = get_db()
        result = await session.execute(query)
        return result.scalars().all()

    @classmethod
    async def retrieve_by_identifier(
        cls: Type[TBase],
        identifier: int,
        eager_load: Optional[Tuple[str, ...]] = None
    ) -> Optional[TBase]:
        query = cls._prepare_query(eager_load).where(cls.pk_id == identifier)
        session = get_db()
        result = await session.execute(query)
        return result.scalars().first()

    @classmethod
    async def locate(
        cls: Type[TBase],
        conditions: Dict[str, Any],
        order_by: Optional[Dict[str, str]] = None,
        eager_load: Optional[Tuple[str, ...]] = None
    ) -> List[TBase]:
        query = cls._prepare_query(eager_load)
        session = get_db()

        if order_by:
            query = query.order_by(*cls._construct_ordering(order_by))

        clauses = list(cls._assemble_conditions(conditions))
        query = query.where(sa.and_(True, *clauses))

        result = await session.execute(query)
        return result.scalars().all()

    @classmethod
    def _construct_ordering(cls, sort_spec: Dict[str, str]) -> List[Any]:
        clauses = []
        for col_name, direction in sort_spec.items():
            column_attr = getattr(cls, col_name)
            method = getattr(column_attr, direction.lower(), None)
            if method is None:
                raise ValueError(f"Unsupported sort direction '{direction}' on column '{col_name}'")
            clauses.append(method())
        return clauses

    @classmethod
    def _assemble_conditions(cls, filter_map: Dict[str, Any]):
        for expr, val in filter_map.items():
            tokens = expr.split("__")
            op_key = tokens[1] if len(tokens) > 1 else "exact"
            if op_key not in operators_map:
                raise KeyError(f"Invalid operator '{op_key}' in expression '{expr}'")
            column = getattr(cls, tokens[0])
            yield operators_map[op_key](column, val)

    @classmethod
    async def batch_insert(cls: Type[TBase], records: List[TBase]) -> List[TBase]:
        session: AsyncSession = get_db()
        try:
            session.add_all(records)
            await session.flush()
        except IntegrityError as e:
            cls._handle_integrity_violation(e)
        return records

    @classmethod
    async def batch_modify(cls: Type[TBase], instances: List[TBase]) -> List[TBase]:
        session: AsyncSession = get_db()
        try:
            active_ids = [inst.pk_id for inst in instances if inst.pk_id]
            # Skip redundant SELECT; merge handles persistence directly
            for record in instances:
                try:
                    await session.merge(record)
                except IntegrityError as e:
                    cls._handle_integrity_violation(e)
            await session.flush()
        except IntegrityError as e:
            cls._handle_integrity_violation(e)
        return instances

    async def persist(self, commit_now: bool = True) -> None:
        session: AsyncSession = get_db()
        session.add(self)
        try:
            if commit_now:
                await session.commit()
            else:
                await session.flush()
        except IntegrityError as e:
            self._handle_integrity_violation(e)

    async def apply_changes(self, **updates: Any) -> None:
        for attr, value in updates.items():
            setattr(self, attr, value)

