import asyncio
import typing
from datetime import datetime, timedelta
import discord
from redbot.core import commands, Config
from redbot.core.utils import AsyncIter
from redbot.core.utils.chat_formatting import humanize_list, pagify

# Default messages
DEFAULT_NO_ACCESS_MSG = "You do not have BotAccess privileges!"
DEFAULT_THANKS_MSG = "Thank you for supporting my server! Here is my invite link: <{invite}>. You can add a BotAccess server with `[p]botaccess servers add <server ID>`."
DEFAULT_EXPIRE_MSG = "Unfortunately, your BotAccess servers have expired as you are no longer a supporter."


class BotAccessManager(commands.Cog):
    """
    Manage BotAccess Privileges
    Allows users with specific roles (e.g., Server Booster, Patreon) to invite the bot to select servers.
    """

    def __init__(self, bot_instance):
        self.bot = bot_instance
        self.config = Config.get_conf(self, identifier=14000605, force_registration=True)

        # Global defaults
        global_defaults = {
            "allowed_guilds": [],
            "primary_guilds": {},
            "user_messages": {
                "welcome": {"enabled": True, "text": ""},
                "expired": {"enabled": True, "text": ""}
            },
            "denial_message": "",
            "max_servers_per_user": 1,
            "auto_departure": {
                "enabled": True,
                "wait_hours": 24
            }
        }

        # User-specific defaults
        user_defaults = {
            "authorized_guilds": [],
            "active_support_guilds": [],
            "expiration_time": None
        }

        self.config.register_global(**global_defaults)
        self.config.register_user(**user_defaults)

        # Start background task
        self.expiry_monitor_task = self.bot.loop.create_task(self._monitor_expirations())

    def cog_unload(self):
        if not self.expiry_monitor_task.done():
            self.expiry_monitor_task.cancel()

    # --- Event Listeners ---

    @commands.Cog.listener("on_guild_join")
    async def on_guild_joined(self, guild: discord.Guild):
        # Skip if bot owns the guild or is owned by an owner
        if guild.owner_id in {None, self.bot.user.id} or guild.owner_id in self.bot.owner_ids:
            return

        # Check allowlist and primary guilds
        allowed = await self.config.allowed_guilds()
        primary = await self.config.primary_guilds()
        if guild.id in allowed or str(guild.id) in primary.keys():
            return

        # Check if already authorized via user settings
        all_users = await self.config.all_users()
        for user_data in all_users.values():
            if guild.id in user_data.get("authorized_guilds", []):
                return

        # Try to find who invited the bot
        inviter = None
        if guild.me.guild_permissions.view_audit_log:
            async for entry in guild.audit_logs(limit=3, action=discord.AuditLogAction.bot_add):
                if entry.target == self.bot.user:
                    inviter = entry.user
                    break

        # Notify inviter
        denial_msg = await self.config.denial_message() or DEFAULT_NO_ACCESS_MSG
        if inviter:
            try:
                await inviter.send(denial_msg)
            except discord.HTTPException:
                pass
        else:
            for channel in guild.text_channels:
                if channel.permissions_for(guild.me).send_messages:
                    try:
                        await channel.send(denial_msg)
                    except discord.HTTPException:
                        pass
                    break

        # Leave the guild
        await guild.leave()

    @commands.Cog.listener("on_member_remove")
    async def on_member_left(self, member: discord.Member):
        auto_depart = False
        async with self.config.user(member).all() as profile:
            if member.guild.id in profile["active_support_guilds"]:
                profile["active_support_guilds"].remove(member.guild.id)
            if not profile["active_support_guilds"] and not profile["expiration_time"]:
                auto_depart = True

        if auto_depart:
            await self._schedule_departure(member.id)

    @commands.Cog.listener("on_member_update")
    async def on_member_role_change(self, before: discord.Member, after: discord.Member):
        primary_guilds = await self.config.primary_guilds()
        server_roles = primary_guilds.get(str(after.guild.id))

        # Early exit conditions
        if (
            after.bot or
            await self.bot.cog_disabled_in_guild(self, after.guild) or
            before.roles == after.roles or
            not server_roles
        ):
            return

        msg_to_send = ""
        auto_depart = False

        before_had_role = await self._has_any_role(server_roles, before)
        after_has_role = await self._has_any_role(server_roles, after)

        # Role gained
        if not before_had_role and after_has_role:
            async with self.config.user(after).all() as profile:
                if not profile["active_support_guilds"]:
                    msg_to_send = await self._compose_welcome_message()
                if profile["expiration_time"]:
                    profile["expiration_time"] = None
                if after.guild.id not in profile["active_support_guilds"]:
                    profile["active_support_guilds"].append(after.guild.id)

        # Role lost
        elif before_had_role and not after_has_role:
            async with self.config.user(after).all() as profile:
                if after.guild.id in profile["active_support_guilds"]:
                    profile["active_support_guilds"].remove(after.guild.id)
                if not profile["active_support_guilds"] and not profile["expiration_time"]:
                    msg_to_send = await self._compose_expiration_message()
                    auto_depart = True

        # Send DM if needed
        if msg_to_send:
            try:
                await after.send(msg_to_send)
            except discord.HTTPException:
                pass

        if auto_depart:
            await self._schedule_departure(after.id)

    # --- Helper Methods ---

    @staticmethod
    async def _has_any_role(role_ids: list, member: discord.Member) -> bool:
        return bool(set(role_ids) & {r.id for r in member.roles})

    async def _compose_welcome_message(self) -> str:
        cfg = await self.config.user_messages.welcome()
        if not cfg["enabled"]:
            return ""
        template = cfg["text"] or DEFAULT_THANKS_MSG
        try:
            core_cog = self.bot.get_cog("Core")
            if core_cog:
                invite_url = await core_cog._invite_url()
                return template.replace("{invite}", invite_url)
        except Exception:
            pass
        return template

    @staticmethod
    async def _compose_expiration_message() -> str:
        cfg = await self.config.user_messages.expired()
        if not cfg["enabled"]:
            return ""
        return cfg["text"] or DEFAULT_EXPIRE_MSG

    # --- User Commands ---

    @commands.group(name="botaccess")
    async def bot_access_group(self, ctx: commands.Context):
        """BotAccess Settings"""
        pass

    @bot_access_group.group(name="servers", invoke_without_command=True)
    async def user_servers_cmd(self, ctx: commands.Context):
        """View your authorized BotAccess servers."""
        profile = await self.config.user(ctx.author).all()
        if profile["active_support_guilds"]:
            guild_names = []
            for gid in profile["authorized_guilds"]:
                g = self.bot.get_guild(gid)
                if g:
                    guild_names.append(f"`{g.name}` (`{g.id}`)")
                else:
                    guild_names.append(f"`{gid}`")
            embed = discord.Embed(
                title="BotAccess Servers",
                description=humanize_list(guild_names),
                color=await ctx.embed_color()
            )
            await ctx.send(embed=embed)
            await ctx.send_help()
        else:
            await ctx.send(await self.config.denial_message() or DEFAULT_NO_ACCESS_MSG)

    @user_servers_cmd.command("add", require_var_positional=True)
    async def add_server(self, ctx: commands.Context, *guild_ids: int):
        """Add one or more servers to your BotAccess list."""
        profile = await self.config.user(ctx.author).all()
        if not profile["active_support_guilds"]:
            return await ctx.send(await self.config.denial_message() or DEFAULT_NO_ACCESS_MSG)

        if profile["expiration_time"]:
            return await ctx.send("Your access has expired; you cannot add more servers.")

        max_limit = await self.config.max_servers_per_user()
        if len(profile["authorized_guilds"]) + len(guild_ids) > max_limit:
            return await ctx.send(f"Limit is {max_limit} servers; you currently have {len(profile['authorized_guilds'])}.")

        added = 0
        for gid in guild_ids:
            if gid not in profile["authorized_guilds"]:
                profile["authorized_guilds"].append(gid)
                added += 1

        if added > 0:
            await ctx.tick()
        else:
            await ctx.send("All specified servers are already in your list.")

    @user_servers_cmd.command("remove", aliases=["delete"], require_var_positional=True)
    async def remove_server(self, ctx: commands.Context, *guild_ids: int):
        """Remove one or more servers from your BotAccess list."""
        profile = await self.config.user(ctx.author).all()
        if not profile["active_support_guilds"]:
            return await ctx.send(await self.config.denial_message() or DEFAULT_NO_ACCESS_MSG)

        main_guilds = await self.config.primary_guilds()
        allowed = await self.config.allowed_guilds()
        removed = 0

        for gid in guild_ids:
            if gid in profile["authorized_guilds"]:
                guild_obj = self.bot.get_guild(gid)
                if guild_obj and guild_obj.id not in allowed and str(guild_obj.id) not in main_guilds.keys():
                    try:
                        await guild_obj.leave()
                    except Exception:
                        pass
                profile["authorized_guilds"].remove(gid)
                removed += 1
            else:
                await ctx.send(f"`{gid}` was not found in your list.")

        if removed > 0:
            await ctx.tick()

    @bot_access_group.command(name="invite")
    async def resend_invite(self, ctx: commands.Context):
        """Resend your BotAccess invitation message."""
        profile = await self.config.user(ctx.author).all()
        if not profile["active_support_guilds"]:
            return await ctx.send(await self.config.denial_message() or DEFAULT_NO_ACCESS_MSG)

        msg = await self._compose_welcome_message()
        if msg:
            try:
