    @owner_settings_group.command(name="reset")
    async def reset_user_data(self, ctx: commands.Context, user: typing.Optional[discord.User], leave_servers: bool, confirm: bool):
        """Reset BotAccess data for a user or globally."""
        if not confirm:
            return await ctx.send("Please confirm with `true` as the final argument.")

        to_leave = []
        if user:
            if leave_servers:
                user_data = await self.config.user(user).authorized_guilds()
                for gid in user_data:
                    g = self.bot.get_guild(gid)
                    if g:
                        to_leave.append(g)
            await self.config.user(user).clear()
            await ctx.send(f"BotAccess data reset for {user.mention}.")
        else:
            if leave_servers:
                all_users = await self.config.all_users()
                for data in all_users.values():
                    for gid in data.get("authorized_guilds", []):
                        g = self.bot.get_guild(gid)
                        if g:
                            to_leave.append(g)
            await self.config.clear_all()
            await self.config.clear_all_users()
            await ctx.send("All BotAccess data has been reset.")

        # Handle actual guild departures
        main_guilds = await self.config.primary_guilds()
        allowed = await self.config.allowed_guilds()
        for g in to_leave:
            if g.id not in allowed and str(g.id) not in main_guilds.keys():
                try:
                    await g.leave()
                except Exception:
                    pass
        if to_leave:
            await ctx.send(f"Left {len(to_leave)} unauthorized servers.")

    @commands.bot_has_permissions(embed_links=True)
    @owner_settings_group.command(name="view")
    async def view_config(self, ctx: commands.Context):
        """Display current BotAccess configuration."""
        cfg = await self.config.all()
