            try:
                u = await self.bot.get_or_fetch_user(int(uid))
                user_str = f"{u.mention} ({u.id})"
            except Exception:
                user_str = str(uid)
            user_stats += f"{user_str}: {len(data.get('authorized_guilds', []))} servers\n"
        for page in pagify(user_stats):
            await ctx.maybe_send_embed(page)

    # --- Background Tasks & Logic ---

    async def _schedule_departure(self, user_id: int, start_timer: bool = True):
        auto_cfg = await self.config.auto_departure()
        if not auto_cfg["enabled"]:
            return
        exp_time = (datetime.now() + timedelta(hours=auto_cfg["wait_hours"])).timestamp()
        await self.config.user_from_id(user_id).expiration_time.set(exp_time)
        if start_timer:
            await self._run_expiry_timer(user_id, exp_time)

    async def _update_supporter_status(self):
        main_guilds_cfg = await self.config.primary_guilds()
        active_guilds = [self.bot.get_guild(int(gid)) for gid in main_guilds.keys()]
        active_guilds = [g for g in active_guilds if g]

        old_users = await self.config.all_users()
        old_ids = set(old_users.keys())
        new_data = {}
        new_members = []
        new_member_ids = []

        for guild in active_guilds:
            for rid in main_guilds.get(str(guild.id), []):
                role = guild.get_role(rid)
                if not role:
                    continue
                async for member in AsyncIter(role.members, steps=100):
                    uid = str(member.id)
                    if uid in new_data:
                        cur = new_data[uid]
                        cur["active_support_guilds"].append(guild.id)
                        new_data[uid] = {
                            "active_support_guilds": cur["active_support_guilds"],
                            "authorized_guilds": cur["authorized_guilds"],
                            "expiration_time": cur["expiration_time"]
                        }
                    elif uid in old_ids:
                        old_ids.discard(uid)
                        orig = old_users[uid]
                        new_data[uid] = {
                            "active_support_guilds": [guild.id],
                            "authorized_guilds": orig.get("authorized_guilds", []),
                            "expiration_time": orig.get("expiration_time")
                        }
                    else:
                        new_members.append(member)
                        new_member_ids.append(member.id)
                        new_data[uid] = {
                            "active_support_guilds": [guild.id],
                            "authorized_guilds": [],
                            "expiration_time": None
                        }

        # Save updated data
        for uid, data in new_data.items():
            async with self.config.user_from_id(int(uid)).all() as profile:
                profile["active_support_guilds"] = data["active_support_guilds"]
                profile["authorized_guilds"] = data["authorized_guilds"]
                profile["expiration_time"] = data["expiration_time"]

        welcome_msg = await self._compose_welcome_message()
        expire_msg = await self._compose_expiration_message()

        # Welcome new supporters
        if welcome_msg:
            async for member in AsyncIter(new_members, steps=100):
                try:
                    await member.send(welcome_msg)
                except discord.HTTPException:
                    pass

        # Notify expired users
        async for uid_str in AsyncIter(list(old_ids), steps=100):
            try:
                user = await self.bot.get_or_fetch_user(int(uid_str))
                orig = old_users[uid_str]
                if not orig.get("expiration_time"):
                    if expire_msg:
                        await user.send(expire_msg)
                    await self._schedule_departure(int(uid_str), start_timer=False)
            except discord.HTTPException:
                pass

    async def _monitor_expirations(self):
        await self.bot.wait_until_red_ready()
        await self._update_supporter_status()
        try:
            tasks = []
            all_users = await self.config.all_users()
            for uid_str, data in all_users.items():
                if not data.get("authorized_guilds") and not data.get("active_support_guilds") and not data.get("expiration_time"):
                    await self.config.user_from_id(int(uid_str)).clear()
                    continue
                if data.get("active_support_guilds") or not data.get("expiration_time"):
                    continue
                tasks.append(self._run_expiry_timer(int(uid_str), data["expiration_time"]))
            await asyncio.gather(*tasks, return_exceptions=True)
        except Exception:
            pass

    async def _run_expiry_timer(self, user_id: int, end_timestamp: float):
        now = datetime.now()
        target = datetime.fromtimestamp(end_timestamp)
        delay = (target - now).total_seconds()
        if delay > 0:
            await asyncio.sleep(delay)
        await self._execute_departure(user_id)

    async def _execute_departure(self, user_id: int):
        profile = await self.config.user_from_id(user_id).all()
        main_guilds = await self.config.primary_guilds()
        allowed = await self.config.allowed_guilds()

        if profile.get("expiration_time") and not profile.get("active_support_guilds"):
            now = datetime.now()
            exp_time = datetime.fromtimestamp(profile["expiration_time"])
            if now >= exp_time:
                for gid in profile.get("authorized_guilds", []):
                    g = self.bot.get_guild(gid)
                    if g and g.id not in allowed and str(g.id) not in main_guilds.keys():
                        try:
                            await g.leave()
                        except Exception:
                            pass
                await self.config.user_from_id(user_id).clear()
            else:
                await self._run_expiry_timer(user_id, profile["expiration_time"])

# Type III Clone: Modified decoder implementations with equivalent functionality but different structure

import torch
import torch.nn as nn
import torch.nn.functional as F

def extract_center_region(tensor, target_size):  # assumes square images
    spatial_dim = tensor.size(-1)
    start_pos = (spatial_dim - target_size) // 2
    return tensor[:, :, start_pos:start_pos + target_size, start_pos:start_pos + target_size]

class base_decoder(nn.Module):
    def __init__(self, args):
        super(base_decoder, self).__init__()
        self.output_size = args.image_shape[0]

    def _build_layers(self, channel_config, kernel_configs):
        layers = []
        for in_ch, out_ch, ksize, stride, padding in zip(
            channel_config[:-1], channel_config[1:], 
            [k[0] for k in kernel_configs], 
            [k[1] for k in kernel_configs], 
            [k[2] for k in kernel_configs]
        ):
            layers.append(nn.ConvTranspose2d(in_ch, out_ch, ksize, stride, padding, bias=True))
        return nn.ModuleList(layers)

class standard_decoder(base_decoder):
    def __init__(self, args):
        super(standard_decoder, self).__init__(args)
        self.layer_stack = nn.ModuleList([
            nn.ConvTranspose2d(args.dict_nbatoms, 300, 4, 2, 0, bias=True),
            nn.ConvTranspose2d(300, 100, 3, 1, 0, bias=True),
            nn.ConvTranspose2d(100, 3, 3, 1, 0, bias=True)
        ])

    def forward(self, x):
        temp = F.relu(self.layer_stack[0](x))
        temp = F.relu(self.layer_stack[1](temp))
        temp = F.relu(self.layer_stack[2](temp))
        temp = extract_center_region(temp, self.output_size)
        return torch.clamp(temp, min=0.0, max=1.0)

class compact_decoder(base_decoder):
    def __init__(self, args):
        super(compact_decoder, self).__init__(args)
        self.layer_stack = nn.ModuleList([
            nn.ConvTranspose2d(args.dict_nbatoms, 30, 4, 2, 0, bias=True),
            nn.ConvTranspose2d(30, 10, 3, 1, 0, bias=True),
            nn.ConvTranspose2d(10, 3, 3, 1, 0, bias=True)
        ])

    def forward(self, x):
        temp = F.relu(self.layer_stack[0](x))
        temp = F.relu(self.layer_stack[1](temp))
        temp = F.relu(self.layer_stack[2](temp))
        temp = extract_center_region(temp, self.output_size)
        return torch.clamp(temp, min=0.0, max=1.0)

class extended_decoder(base_decoder):
    def __init__(self, args):
        super(extended_decoder, self).__init__(args)
        self.layer_stack = nn.ModuleList([
            nn.ConvTranspose2d(args.dict_nbatoms, 300, 4, 2, 0, bias=True),
            nn.ConvTranspose2d(300, 100, 3, 1, 0, bias=True),
            nn.ConvTranspose2d(100, 30, 3, 1, 0, bias=True),
            nn.ConvTranspose2d(30, 10, 3, 1, 0, bias=True),
            nn.ConvTranspose2d(10, 3, 3, 1, 0, bias=True)
        ])

    def forward(self, x):
        temp = F.relu(self.layer_stack[0](x))
        temp = F.relu(self.layer_stack[1](temp))
        temp = F.relu(self.layer_stack[2](temp))
        temp = F.interpolate(temp, size=(self.output_size + 2), mode="bicubic")
        temp = F.relu(self.layer_stack[3](temp))
        temp = F.relu(self.layer_stack[4](temp))
        temp = extract_center_region(temp, self.output_size)
        return torch.clamp(temp, min=0.0, max=1.0)

class rescaled_decoder(base_decoder):
    def __init__(self, args):
        super(rescaled_decoder, self).__init__(args)
        self.layer_stack = nn.ModuleList([
            nn.ConvTranspose2d(args.dict_nbatoms, 300, 3, 1, 0, bias=True),
            nn.ConvTranspose2d(300, 100, 3, 1, 0, bias=True),
            nn.ConvTranspose2d(100, 3, 3, 1, 0, bias=True)
        ])

    def forward(self, x):
        temp = F.relu(self.layer_stack[0](x))
        temp = F.interpolate(temp, size=(self.output_size + 2), mode="bicubic")
        temp = F.relu(self.layer_stack[1](temp))
        temp = F.relu(self.layer_stack[2](temp))
        temp = extract_center_region(temp, self.output_size)
        return torch.clamp(temp, min=0.0, max=1.0)

decoder_registry = {
    "standard_decoder": standard_decoder,
    "rescaled_decoder": rescaled_decoder,
    "extended_decoder": extended_decoder,
    "compact_decoder": compact_decoder
}

