# Type III Clone: Refactored logic with equivalent functionality but different implementation approach

import torch
from torch.distributed import ProcessGroup
from abc import ABC
from dataclasses import dataclass, fields
from typing import Any, Dict, Optional
from cosmos_rl.utils.wfm.utils import DataType
from cosmos_rl.utils.wfm.context_parallel import (
    broadcast,
    broadcast_split_tensor,
)

@dataclass(frozen=True)
class BaseCondition(ABC):
    """
    Base class for conditions in the workflow management system.

    Attributes:
        _is_broadcasted: Internal flag indicating whether parallel broadcast splitting has been performed.
    """
    _is_broadcasted: bool = False

    def to_dict(self, skip_underscore: bool = True) -> Dict[str, Any]:
        """Converts condition instance to dictionary representation."""
        result = {}
        for field in fields(self):
            name = field.name
            if skip_underscore and name.startswith("_"):
                continue
            result[name] = getattr(self, name)
        return result

    @property
    def is_broadcasted(self) -> bool:
        return self._is_broadcasted

    def broadcast(self, process_group: torch.distributed.ProcessGroup):
        """Broadcasts condition across distributed group."""
        if self.is_broadcasted:
            return self
        return _distribute_condition(self, process_group)

@dataclass(frozen=True)
class T2VCondition(BaseCondition):
    crossattn_emb: Optional[torch.Tensor] = None
    data_type: DataType = DataType.VIDEO
    padding_mask: Optional[torch.Tensor] = None
    fps: Optional[torch.Tensor] = None

    def edit_data_type(self, data_type: DataType):
        """Creates new instance with updated data type."""
        new_kwargs = self.to_dict(skip_underscore=False)
        new_kwargs["data_type"] = data_type
        return type(self)(**new_kwargs)

    @property
    def is_video(self) -> bool:
        return self.data_type == DataType.VIDEO

@dataclass(frozen=True)
class Vid2VidCondition(T2VCondition):
    use_video_condition: bool = False
    gt_frames: Optional[torch.Tensor] = None
    condition_video_input_mask_B_C_T_H_W: Optional[torch.Tensor] = None

    def set_video_condition(
        self,
        gt_frames: torch.Tensor,
        random_min_num_conditional_frames: int,
        random_max_num_conditional_frames: int,
        num_conditional_frames: Optional[int] = None,
    ) -> "Vid2VidCondition":
        """
        Configures video conditioning frames for video-to-video generation.

        Creates a binary mask marking which frames serve as conditioning context.
        Handles both image batches (T=1) and video batches (T>1).
        """
        B, _, T, H, W = gt_frames.shape

        # Initialize mask with zeros
        condition_video_input_mask_B_C_T_H_W = torch.zeros(
            B, 1, T, H, W, dtype=gt_frames.dtype, device=gt_frames.device
        )

        # Determine number of conditional frames per batch item
        if T == 1:  # Image batch case
            num_conditional_frames_B = torch.zeros(B, dtype=torch.int32)
        else:  # Video batch case
            if num_conditional_frames is not None:
                num_conditional_frames_B = torch.full((B,), num_conditional_frames, dtype=torch.int32)
            else:
                num_conditional_frames_B = torch.randint(
                    random_min_num_conditional_frames,
                    random_max_num_conditional_frames + 1,
                    size=(B,),
                    dtype=torch.int32
                )

        # Set first N frames as conditioning for each batch item
        for idx in range(B):
            num_frames = num_conditional_frames_B[idx].item()
            if num_frames > 0:
                condition_video_input_mask_B_C_T_H_W[
                    idx, :, :num_frames, :, :
                ] = torch.ones(1, num_frames, H, W, dtype=gt_frames.dtype, device=gt_frames.device)

        # Build new instance with updated fields
        new_kwargs = self.to_dict(skip_underscore=False)
        new_kwargs["gt_frames"] = gt_frames
        new_kwargs["condition_video_input_mask_B_C_T_H_W"] = condition_video_input_mask_B_C_T_H_W
        return type(self)(**new_kwargs)

    def edit_for_inference(
        self, is_cfg_conditional: bool = True, num_conditional_frames: int = 1
    ) -> "Vid2VidCondition":
        # Configure for inference with specified conditional frames
        condition = self.set_video_condition(
            gt_frames=self.gt_frames,
            random_min_num_conditional_frames=0,
            random_max_num_conditional_frames=0,
            num_conditional_frames=num_conditional_frames,
        )

        # Disable CFG on conditional frames when requested
        if not is_cfg_conditional:
            condition.use_video_condition = True
        return condition

    def broadcast(
        self, process_group: torch.distributed.ProcessGroup
    ) -> "Vid2VidCondition":
        if self.is_broadcasted:
            return self

        # Extract tensor fields before broadcasting base condition
        gt_frames = self.gt_frames
        condition_mask = self.condition_video_input_mask_B_C_T_H_W

        # Create temporary condition without tensors for base broadcast
        temp_kwargs = self.to_dict(skip_underscore=False)
        temp_kwargs["gt_frames"] = None
        temp_kwargs["condition_video_input_mask_B_C_T_H_W"] = None
        temp_condition = T2VCondition(**temp_kwargs)

        # Broadcast base condition
        broadcasted_base = temp_condition.broadcast(process_group)
        final_kwargs = broadcasted_base.to_dict(skip_underscore=False)

        # Handle tensor splitting if needed
        if process_group is not None:
            _, _, T, _, _ = gt_frames.shape
            if T > 1 and process_group.size() > 1:
                gt_frames = broadcast_split_tensor(
                    gt_frames, seq_dim=2, process_group=process_group
                )
                condition_mask = broadcast_split_tensor(
                    condition_mask, seq_dim=2, process_group=process_group
                )

        # Reattach processed tensors
        final_kwargs["gt_frames"] = gt_frames
        final_kwargs["condition_video_input_mask_B_C_T_H_W"] = condition_mask
        return type(self)(**final_kwargs)

def _distribute_condition(condition, process_group: Optional[ProcessGroup] = None):
    """Internal helper to distribute condition across distributed processes."""
    if condition.is_broadcasted:
        return condition

    kwargs = condition.to_dict(skip_underscore=False)
    for key, value in kwargs.items():
        if value is not None:
            kwargs[key] = broadcast(value, process_group)

    kwargs["_is_broadcasted"] = True
    return type(condition)(**kwargs)

