def convert_dict_keys_to_int64(data):
    """
    Recursively process dictionary keys and values to ensure integer keys are represented as np.int64.
    This function handles nested dictionaries and converts string representations of integers to int64.
    """
    result = {}
    for key, value in data.items():
        # Convert top-level keys that are numeric strings to int64
        if isinstance(key, str) and key.isdigit():
            new_key = np.int64(key)
        else:
            new_key = key

        # Process nested dictionaries
        if isinstance(value, dict):
            processed_value = {}
            for sub_key, sub_val in value.items():
                # Convert sub-keys that are numeric strings to int
                if isinstance(sub_key, str) and sub_key.isdigit():
                    processed_sub_key = int(sub_key)
                else:
                    processed_sub_key = sub_key

                # Ensure values that should be integers are converted
                if isinstance(sub_val, str) and sub_val.isdigit():
                    processed_value[processed_sub_key] = int(sub_val)
                else:
                    processed_value[processed_sub_key] = sub_val
            result[new_key] = processed_value
        else:
            result[new_key] = value

    return result

def read_json_file(file_path):
    """Load JSON data from a file and process keys for int64 conversion."""
    if not os.path.isfile(file_path):
        raise FileNotFoundError(f"Specified file does not exist: {file_path}")

    with open(file_path, 'r', encoding='utf-8') as file:
        raw_data = json.load(file)

    return convert_dict_keys_to_int64(raw_data)

def write_json_file(data, output_path):
    """Save dictionary data to a JSON file, converting numpy integer keys to standard integers."""
    if not isinstance(data, dict):
        raise TypeError("Input data must be a dictionary.")

    # Convert numpy integer keys to standard Python integers for JSON compatibility
    serializable_data = {}
    for key, value in data.items():
        if isinstance(key, (np.integer, np.int64)):
            serializable_key = int(key)
        else:
            serializable_key = key
        serializable_data[serializable_key] = value

    with open(output_path, 'w', encoding='utf-8') as file:
        json.dump(serializable_data, file, indent=2)

def validate_image_file(image_path):
    """Check if the given path points to a valid image file."""
    if not os.path.exists(image_path):
        return False

    try:
        with Image.open(image_path) as img:
            width, height = img.size

            # Validate dimensions
            if width <= 0 or height <= 0:
                raise ValueError("Image has invalid dimensions")

            return True
    except Exception as error:
        print(f"Failed to validate image '{image_path}': {error}")
        return False

def extract_file_info(path_string):
    """Determine MIME type and validate file existence."""
    if os.path.exists(path_string) and path_string != '.':
        if not os.path.isfile(path_string):
            raise ValueError(f"'{path_string}' is not a regular file")

        _, ext = os.path.splitext(path_string)
        mime_type = mimetypes.types_map.get(ext.lower(), 'application/octet-stream')
        return (mime_type, path_string)
    else:
        return (None, path_string)

def save_base64_as_image(base64_content, output_file, max_dimension=-1):
    """Decode base64 image data and save it to a file with optional resizing."""
    with image_lock:
        pil_image = decode_base64_to_pil_image(base64_content, max_dimension=max_dimension)
        pil_image.save(output_file)

def decode_base64_to_pil_image(base64_content, max_dimension=-1):
    """Decode base64 string into a PIL Image object with optional resizing."""
    # Decode base64 content to binary data
    image_bytes = base64.b64decode(base64_content)

    # Create image from bytes
    with Image.open(io.BytesIO(image_bytes)) as img:
        # Convert RGBA/P mode images to RGB to avoid issues with JPEG saving
        if img.mode in ('RGBA', 'P'):
            img = img.convert('RGB')

        # Resize if maximum dimension is specified and positive
        if max_dimension > 0:
            img.thumbnail((max_dimension, max_dimension))

        # Return a copy to avoid reference issues
        return img.copy()

import jax.numpy as jnp
from beartype import beartype
from jaxtyping import Array, Inexact, PyTree, jaxtyped
from ..tree_util import is_shape_leaf
from ..typing import (
    Any,
    Data,
    DataShape,
    Dict,
    HyperParams,
    ModuleCallable,
    OrderedSet,
    Params,
    State,
    Tuple,
)
from .basemodule import BaseModule

class Tensor contraction(BaseModule):
    """
    A module for performing tensor contractions via einsum notation on PyTree inputs.
    Supports optional leading trainable parameters. The contraction pattern is defined
    by an einsum specification that excludes the batch dimension (automatically prepended).

    Examples:
        # Dot product of two 1D arrays per batch item
        >>> contraction_module = Tensor contraction("i,i->")

        # Matrix multiplication with three input matrices and a trainable matrix
        >>> contraction_module = Tensor contraction("ij,jk,jk,jk->ik")

        # With fixed parameters
        >>> W = jnp.random.normal(size=(input_dim, output_dim))
        >>> contraction_module = Tensor contraction(
        ...     "ij,jk,jk,jk->ik",
        ...     params=W,
        ...     trainable=False)
    """
    __version__: str = "0.0.0"

    def __init__(
        self,
        contraction_spec: (
            Tuple[str, PyTree[str], str]
            | Tuple[str, PyTree[str]]
            | Tuple[PyTree[str], str]
            | PyTree[str]
            | str
            | None
        ) = None,
        weights: (
            PyTree[Inexact[Array, "..."]] | Inexact[Array, "..."] | None
        ) = None,
        index_map: Dict[str, int] | None = None,
        learnable: bool = False,
        scale: float = 1e-2,
        complex_weights: bool = False,
    ) -> None:
        """
        Initialize a Tensor contraction module.

        Parameters:
            contraction_spec: Einsum specification defining the operation
            weights: Optional leading arrays for the contraction
            index_map: Mapping from index characters to dimension sizes
            learnable: Whether weights are trainable
            scale: Magnitude for random initialization
            complex_weights: Whether to use complex-valued weights
        """
        self.contraction_spec = contraction_spec
        self.weights = weights
        self.index_map = index_map
        self.learnable = learnable
        self.scale = scale
        self.complex_weights = complex_weights
        self.input_shape: DataShape | None = None

    def _resolve_dimensions(
        self,
        full_contraction_str: str,
        concrete_input_shape: DataShape,
    ) -> Dict[str, int]:
        r"""
        Determine all dimension sizes from input shapes and parameter shapes.
        """
        index_dict = (
            dict({k: v for k, v in self.index_map.items()})
            if self.index_map
            else {}
        )

        # Extract input and output parts
        input_part, output_part = full_contraction_str.split("->")
        batch_char = output_part[0]
        input_specs = input_part.replace(batch_char, "").split(",")
        input_shapes_list = jax.tree.leaves(concrete_input_shape, is_leaf=is_shape_leaf)

        # Separate leading specs from input specs
        num_inputs = len(input_shapes_list)
        leading_specs = input_specs[:-num_inputs] if input_specs else []
        input_specs = input_specs[-num_inputs:] if input_specs else []

        # Infer dimensions from input arrays
        for spec, shape in zip(input_specs, input_shapes_list):
            if len(spec) != len(shape):
                raise ValueError(
                    f"Contraction spec '{spec}' has length {len(spec)}, but "
                    f"corresponding input array has shape {shape}."
                )
            for char, size in zip(spec, shape):
                if char not in index_dict:
                    index_dict[char] = size
                elif index_dict[char] != size:
                    raise ValueError(
                        f"Dimension conflict for index '{char}': "
                        f"got {size} from shape {shape}, "
                        f"but previously recorded {index_dict[char]}."
                    )

        # Infer dimensions from weight arrays
        if self.weights is not None:
            weight_shapes = (
                [self.weights.shape]
                if isinstance(self.weights, jnp.ndarray)
                else jax.tree.leaves(
                    self.weights, is_leaf=lambda x: isinstance(x, jnp.ndarray)
                )
            )

            if len(leading_specs) != len(weight_shapes):
                raise ValueError(
                    f"Number of leading specs ({len(leading_specs)}) "
                    f"doesn't match number of weight arrays ({len(weight_shapes)})."
                )

            for spec, shape in zip(leading_specs, weight_shapes):
                if len(spec) != len(shape):
                    raise ValueError(
                        f"Leading spec '{spec}' has length {len(spec)}, "
                        f"but corresponding weight array has shape {shape}."
                    )
                for char, size in zip(spec, shape):
                    if char not in index_dict:
                        index_dict[char] = size
                    elif index_dict[char] != size:
                        raise ValueError(
                            f"Dimension conflict for index '{char}': "
                            f"got {size} from weight shape {shape}, "
                            f"but previously recorded {index_dict[char]}."
                        )

        # Check for missing indices
        all_chars = set(full_contraction_str.replace(",", "").replace("->", "").replace(batch_char, ""))
        missing = all_chars - set(index_dict.keys())
        if missing:
            raise ValueError(
                f"Could not determine sizes for indices {missing}. "
                "Provide them in the `index_map` argument."
            )

        return index_dict

    def _construct_full_spec(self, input_shape: DataShape) -> str:
        r"""
        Build the complete einsum specification with batch dimension added.
        """
        if self.contraction_spec is None:
            raise ValueError("contraction_spec must be set before concretization.")

        was_pytree = False
        input_struct = jax.tree.structure(input_shape, is_leaf=is_shape_leaf)
        spec_struct = jax.tree.structure(self.contraction_spec)

        # Handle different specification formats
        if spec_struct == input_struct:
            leading_part = None
            input_parts = self.contraction_spec
            output_part = None
            was_pytree = True
        elif isinstance(self.contraction_spec, tuple):
            if len(self.contraction_spec) == 3:
                leading_part, input_parts, output_part = self.contraction_spec
            elif len(self.contraction_spec) == 2:
                first, second = self.contraction_spec
                first_is_str = isinstance(first, str)
                second_is_str = isinstance(second, str)

                if first_is_str and not second_is_str:
                    leading_part = first
                    input_parts = second
                    output_part = None
                elif not first_is_str and second_is_str:
                    leading_part = None
                    input_parts = first
                    output_part = second
                else:
                    raise ValueError(
                        "If contraction_spec is a 2-tuple, one element must be "
                        "a string and the other a non-degenerate PyTree of strings."
                    )
            else:
                raise ValueError(
                    "Tuple specifications must have length 2 or 3."
                )
        elif isinstance(self.contraction_spec, str):
            leading_part = None
            input_parts = self.contraction_spec
            output_part = None
        else:
            # Validate PyTree structure
            if jax.tree.structure(self.contraction_spec) != input_struct:
                raise ValueError(
                    "The structure of contraction_spec must match input data structure."
                )
            leading_part = None
            input_parts = self.contraction_spec
            output_part = None

        # Parse output part if embedded in input
        if output_part is None and isinstance(input_parts, str) and "->" in input_parts:
            input_parts, output_part = input_parts.split("->")

        # Extract leading specs if embedded in input
        if leading_part is None and isinstance(input_parts, str):
            parts_list = input_parts.split(",")
            num_inputs = len(jax.tree.leaves(input_shape, is_leaf=is_shape_leaf))
            num_strings = len(parts_list)

            if num_strings > num_inputs:
                leading_part = ",".join(parts_list[:num_strings - num_inputs])
                input_parts = ",".join(parts_list[num_strings - num_inputs:])

        # Validate consistency
        num_inputs = len(jax.tree.leaves(input_shape, is_leaf=is_shape_leaf))
        if isinstance(input_parts, str):
            num_input_specs = len(input_parts.split(","))
        else:
            was_pytree = True
            if not jax.tree.all(
                jax.tree.map(
                    lambda s: isinstance(s, str) and s.isalpha(),
                    input_parts,
                )
            ):
                raise ValueError(
                    "All input specs in the PyTree must be alphabetic strings."
                )
            num_input_specs = len(
                jax.tree.leaves(input_parts, is_leaf=lambda x: isinstance(x, str))
            )

        if leading_part is None and not (self.weights is None or self.weights == ()):
            raise ValueError(
                "If no leading arrays are specified, weights must be None or empty."
            )

        # Validate output part
        if output_part is not None:
            if "," in output_part or "->" in output_part:
                raise ValueError(
                    f"output_part cannot contain ',' or '->'. Got '{output_part}'."
                )

        # Validate character sets
        valid_chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ,"
        def check_chars(s: str) -> None:
            invalid = set(s) - set(valid_chars)
            if invalid:
                raise ValueError(
                    f"Contraction spec '{s}' contains invalid characters: {invalid}."
                )

        if leading_part is not None:
            check_chars(leading_part)
        if output_part is not None:
            check_chars(output_part)
        if isinstance(input_parts, str):
            check_chars(input_parts)
        else:
            jax.tree.map(check_chars, input_parts)

        # Process input parts
        if isinstance(input_parts, str):
            input_parts = input_parts.split(",")

        # Reorder according to input structure
        if was_pytree:
            input_parts = jax.tree.map(
                lambda _, s: s,
                input_shape,
                input_parts,
                is_leaf=is_shape_leaf,
            )

        # Combine input specs
        def combine(carry: str, s: str) -> str:
            return s if carry == "" else carry + "," + s
        combined_input = jax.tree.reduce(combine, input_parts, initializer="")

        # Infer output if needed
        if output_part is None:
            all_input = ""
            if leading_part is not None:
                all_input += leading_part
            all_input += combined_input

            counts = {}
            for c in all_input:
                if c != ",":
                    counts[c] = counts.get(c, 0) + 1

            output_part = "".join(sorted([c for c in counts if counts[c] == 1]))

        # Find available batch index
        used = set()
        if leading_part is not None:
            used.update(set(leading_part.replace(",", "")))
        used.update(set(combined_input.replace(",", "")))
        used.update(set(output_part))

        available = set(valid_chars.replace(",", "")) - used
        if not available:
            raise ValueError(
                "No available indices for batch dimension. "
                "All possible indices are in use."
            )
        batch_idx = next(iter(available))

        # Validate shapes against specs
        input_spec_list = combined_input.split(",")
        def verify_shape(spec: str, shape: tuple) -> None:
            if len(spec) != len(shape):
                raise ValueError(
                    f"Contraction spec '{spec}' has length {len(spec)}, "
                    f"but array shape is {shape}."
                )

        for spec, shape in zip(
            input_spec_list,
            jax.tree.leaves(input_shape, is_leaf=is_shape_leaf),
        ):
            verify_shape(spec, shape)

        # Add batch dimension
        input_with_batch = ",".join([batch_idx + s for s in combined_input.split(",")])
        output_with_batch = batch_idx + output_part

        # Construct final specification
        full_spec = input_with_batch + "->" + output_with_batch
        if leading_part is not None:
            full_spec = leading_part + "," + full_spec

        return full_spec

    @property
    def identifier(self) -> str:
        concrete_spec = (
            self._construct_full_spec(self.input_shape)
            if self.input_shape is not None
            else self.contraction_spec
        )
        return f"Tensor contraction({concrete_spec})"

    def is_ready(self) -> bool:
        return self.input_shape is not None

    def _create_callable(self) -> ModuleCallable:
        full_spec = self._construct_full_spec(self.input_shape)

        @jaxtyped(typechecker=beartype)
        def contraction_function(
            weights: Params, 
            data: Data, 
            training: bool, 
            state: State, 
            rng: Any
        ) -> Tuple[Data, State]:
            tensors = []

            # Add weights based on learnability
            if self.learnable:
                if isinstance(weights, jnp.ndarray):
                    tensors.append(weights)
                else:
                    tensors.extend(
                        jax.tree.leaves(
                            weights,
                            is_leaf=lambda x: isinstance(x, jnp.ndarray),
                        )
                    )
            elif not self.learnable and self.weights is not None:
                if isinstance(self.weights, jnp.ndarray):
                    tensors.append(self.weights)
                else:
                    tensors.extend(
                        jax.tree.leaves(
                            self.weights,
                            is_leaf=lambda x: isinstance(x, jnp.ndarray),
                        )
                    )

            # Add input data
            tensors.extend(
                jax.tree.leaves(
                    data,
                    is_leaf=lambda x: isinstance(x, jnp.ndarray),
                )
            )

            # Ensure consistent dtype
            dtype = jnp.result_type(*[t.dtype for t in tensors])
            tensors = [t.astype(dtype) for t in tensors]

            result = jnp.einsum(full_spec, *tensors)
            return result, state

        return contraction_function

    def finalize(self, rng: Any, input_shape: DataShape) -> None:
        if self.contraction_spec is None:
            raise ValueError("contraction_spec must be set before finalizing")

        if self.is_ready() and self.input_shape != input_shape:
            raise ValueError(
                "Module has already been finalized with a different input shape."
            )

        self.input_shape = input_shape
        full_spec = self._construct_full_spec(input_shape)
        dim_dict = self._resolve_dimensions(full_spec, input_shape)

        # Determine leading arrays count
        input_part, output_part = full_spec.split("->")
        input_specs = input_part.split(",")
        num_inputs = len(jax.tree.leaves(input_shape, is_leaf=is_shape_leaf))
        leading_specs = input_specs[:-num_inputs] if input_specs else []

        # Initialize weights if needed
        if len(leading_specs) > 0 and self.weights is None:
            if not self.learnable:
                raise ValueError(
                    "weights must be provided for fixed (non-learnable) leading arrays."
                )

            weight_arrays = []
            if self.complex_weights:
                rkey, ikey = jax.random.split(rng)
                rkeys = jax.random.split(rkey, len(leading_specs))
                ikeys = jax.random.split(ikey, len(leading_specs))
            else:
                keys = jax.random.split(rng, len(leading_specs))

            for i, spec in enumerate(leading_specs):
                dims = tuple(dim_dict[char] for char in spec)
                if self.complex_weights:
                    real_part = self.scale * jax.random.normal(
                        rkeys[i], dims, dtype=jnp.float32
                    )
                    imag_part = self.scale * jax.random.normal(
                        ikeys[i], dims, dtype=jnp.float32
                    )
                    weight_array = real_part + 1j * imag_part
                else:
                    weight_array = self.scale * jax.random.normal(
                        keys[i], dims, dtype=jnp.float32
                    )
                weight_arrays.append(weight_array)

            self.weights = (
                weight_arrays[0] if len(weight_arrays) == 1 else tuple(weight_arrays)
            )

        # Verify weight dimensions
        if self.weights is not None:
            expected_dims = [
                tuple(dim_dict[char] for char in s) for s in leading_specs
            ]
            actual_dims = (
                [self.weights.shape]
                if isinstance(self.weights, jnp.ndarray)
                else [
                    w.shape
                    for w in jax.tree.leaves(
                        self.weights,
                        is_leaf=lambda x: isinstance(x, jnp.ndarray),
                    )
                ]
            )

            if len(expected_dims) != len(actual_dims):
                raise ValueError(
                    f"Number of leading arrays ({len(leading_specs)}) "
                    f"doesn't match weights ({len(actual_dims)})."
                )

            for i, (expected, actual) in enumerate(zip(expected_dims, actual_dims)):
                if expected != actual:
                    raise ValueError(
                        f"Weight array {i} has shape {actual}, "
                        f"but expected {expected} based on spec."
                    )

    def compute_output_shape(self, input_shape: DataShape) -> DataShape:
        full_spec = self._construct_full_spec(input_shape)
        dim_dict = self._resolve_dimensions(full_spec, input_shape)
        _, output_part = full_spec.split("->")

        # Skip batch dimension
        output_dims = tuple(dim_dict[char] for char in output_part[1:])
        return output_dims

    def fetch_hyperparameters(self) -> HyperParams:
        return {
            "contraction_spec": self.contraction_spec,
            "index_map": self.index_map,
            **({"weights": self.weights} if not self.learnable else {}),
            "scale": self.scale,
            "complex_weights": self.complex_weights,
            "input_shape": self.input_shape,
        }

    def assign_hyperparameters(self, hyperparams: HyperParams) -> None:
        if "input_shape" in hyperparams:
            self.input_shape = hyperparams["input_shape"]
        if "contraction_spec" in hyperparams:
            self.contraction_spec = hyperparams["contraction_spec"]
        if "index_map" in hyperparams:
            self.index_map = hyperparams["index_map"]
        if "weights" in hyperparams and not self.learnable:
            self.weights = hyperparams["weights"]
        if "scale" in hyperparams:
            self.scale = hyperparams["scale"]
        if "complex_weights" in hyperparams:
            self.complex_weights = hyperparams["complex_weights"]

    def fetch_weights(self) -> Params:
        return self.weights

    def assign_weights(self, weights: Params) -> None:
        self.weights = weights

# Type III Clone: GitHubProcessor with equivalent logic and functionality, but different implementation style

from typing import Dict, Any, List, Optional
import nltk
from nltk.sentiment import SentimentIntensityAnalyzer

# NLTK Setup for Sentiment Analysis (restructured control flow)
def ensure_nltk_data():
    try:
        if not nltk.data.find('sentiment/vader_lexicon.zip'):
            raise LookupError()
    except LookupError:
        try:
            nltk.download('vader_lexicon', quiet=True)
        except Exception as e:
            print(f"[WARN] NLTK Download Failed: {e}")

ensure_nltk_data()

class GitHubProcessor:
    """Handles data processing and transformation of GitHub API responses."""

    def __init__(self, owner: str, repo: str):
        self.owner = owner
        self.repo = repo
        self.sia = SentimentIntensityAnalyzer()
        self.bot_identifiers = {
            "copilot", "github-copilot", "github-copilot[bot]", 
            "actions-user", "github-actions[bot]"
        }

    def process_pulse_feed(self, events: List[Dict[str, Any]], limit: int = 15) -> List[Dict[str, Any]]:
        """Process raw GitHub events into formatted pulse feed items."""
        if not events:
            return []

        result = []
        # Use slicing to respect limit instead of iterating beyond it
        limited_events = events[:limit]

        for event in limited_events:
            processed = self._transform_single_event(event)
            if processed is not None:
                result.append(processed)
        return result

    def _transform_single_event(self, event: Dict[str, Any]) -> Optional[Dict[str, Any]]:
        """Transform a single GitHub event into standardized format."""
        event_type = event.get('type')
        payload = event.get('payload', {})
        repo_info = event.get('repo', {})
        actor_info = event.get('actor', {})

        action_text = self._generate_action_string(event_type, payload)
        if action_text is None:
            return None

        return {
            "id": event.get('id'),
            "type": event_type,
            "actor": {
                "login": actor_info.get('login'),
                "avatar": actor_info.get('avatar_url')
            },
            "repo": {
                "name": repo_info.get('name'),
                "url": f"https://github.com/{repo_info.get('name')}"
            },
            "action": action_text,
            "created_at": event.get('created_at')
        }

    def _generate_action_string(self, event_type: str, payload: Dict[str, Any]) -> Optional[str]:
        """Generate human-readable action string based on event type."""
        if event_type == 'PushEvent':
            commits = payload.get('commits', [])
            count = len(commits)
            ref_name = payload.get('ref', '').split('/')[-1] or ''
            return f"pushed {count} commit{'s' if count != 1 else ''} to {ref_name}"

        elif event_type == 'PullRequestEvent':
            pr_action = payload.get('action', 'interacted with')
            pr_number = payload.get('pull_request', {}).get('number')
            return f"{pr_action} pull request #{pr_number}" if pr_number else f"{pr_action} pull request"

        elif event_type == 'IssuesEvent':
            issue_action = payload.get('action', 'interacted with')
            issue_number = payload.get('issue', {}).get('number')
            return f"{issue_action} issue #{issue_number}" if issue_number else f"{issue_action} issue"

        elif event_type == 'IssueCommentEvent':
            issue_number = payload.get('issue', {}).get('number')
            return f"commented on issue #{issue_number}" if issue_number else "commented on issue"

        elif event_type == 'PullRequestReviewCommentEvent':
            pr_number = payload.get('pull_request', {}).get('number')
            return f"reviewed pull request #{pr_number}" if pr_number else "reviewed pull request"

        elif event_type == 'CreateEvent':
            ref_type = payload.get('ref_type')
            ref = payload.get('ref')
            return f"created {ref_type} {ref or ''}"

        elif event_type == 'DeleteEvent':
            ref_type = payload.get('ref_type')
            ref = payload.get('ref')
            return f"deleted {ref_type} {ref or ''}"

        elif event_type == 'ForkEvent':
            return "forked the repository"

        elif event_type == 'WatchEvent':
            return "starred the repository"

        return None

    def process_repo_stats(self, data: Dict[str, Any]) -> Dict[str, Any]:
        """Process repository data into stats format."""
        if not data:
            return {}

        return {
            "name": data.get('name'),
            "full_name": data.get('full_name'),
            "description": data.get('description'),
            "stars": data.get('stargazers_count', 0),
            "forks": data.get('forks_count', 0),
            "watchers": data.get('watchers_count', 0),
            "language": data.get('language'),
            "created_at": data.get('created_at'),
            "updated_at": data.get('updated_at'),
            "size": data.get('size'),
            "open_issues": data.get('open_issues_count', 0)
        }

    def process_recent_prs(self, prs: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        """Process pull requests data."""
        if not prs:
            return []

        return [
            {
                "number": pr.get('number'),
                "title": pr.get('title'),
                "state": pr.get('state'),
                "created_at": pr.get('created_at'),
                "updated_at": pr.get('updated_at'),
                "merged_at": pr.get('merged_at'),
                "user": {
                    "login": pr.get('user', {}).get('login'),
                    "avatar": pr.get('user', {}).get('avatar_url')
                },
                "labels": [label.get('name') for label in pr.get('labels', [])]
            }
            for pr in prs
        ]

    def process_contributors(self, contributors: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        """Process contributors data."""
        if not contributors:
            return []

        return [
            {
                "login": contributor.get('login'),
                "avatar": contributor.get('avatar_url'),
                "contributions": contributor.get("contributions"),
                "type": contributor.get('type')
            }
            for contributor in contributors
        ]

    def process_activity(self, activity_data: List[Dict[str, Any]], commits: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        """Process commit activity data with fallback to manual aggregation."""
        if activity_data:
            return [
                {
                    "week": item.get('week'),
                    "total": item.get('total'),
                    "days": item.get('days', [])
                }
                for item in activity_data
            ]
        elif commits:
            from datetime import datetime, timedelta

            activity_map = {}
            for c in commits:
                author_date = c.get('commit', {}).get('author', {}).get('date')
                if not author_date:
                    continue

                try:
                    dt = datetime.fromisoformat(author_date.replace('Z', '+00:00'))
                    week_start = dt.replace(hour=0, minute=0, second=0, microsecond=0)
                    week_start = week_start - timedelta(days=dt.weekday())
                    week_key = int(week_start.timestamp())

                    if week_key not in activity_map:
                        activity_map[week_key] = {"week": week_key, "total": 0, "days": [0] * 7}

                    day_index = dt.weekday()
                    activity_map[week_key]["days"][day_index] += 1
                    activity_map[week_key]["total"] += 1
                except Exception:
                    continue

            return list(activity_map.values())

        return []

    def calculate_total_commits(self, contributors: List[Dict[str, Any]]) -> int:
        """Calculate total commits from contributors data."""
        if not contributors:
            return 0

        return sum(c.get('contributions', 0) for c in contributors)

    def process_contribution_mix(self, total_commits: int, total_prs: int, total_issues: int, total_reviews: int) -> List[Dict[str, Any]]:
        """Process contribution statistics into mix format."""
        return [
            {
                "name": "Core Features",
                "value": 45,
                "count": total_commits,
                "unit": "Commits",
                "color": "#3B82F6",
                "description": "Functional code changes & features"
            },
            {
                "name": "Infrastructure",
                "value": 25,
                "count": total_prs,
                "unit": "Pull Requests",
                "color": "#10B981",
                "description": "PR merges and branch management"
            },
            {
                "name": "Issue Triage",
                "value": 20,
                "count": total_issues,
                "unit": "Total Issues",
                "color": "#C2410C",
                "description": "Issue resolution & bug tracking"
            },
            {
                "name": "Mentorship",
                "value": 10,
                "count": total_reviews,
                "unit": "Review Comments",
                "color": "#8B5CF6",
                "description": "Peer code reviews & guidance"
            },
        ]

    def process_reviewer_stats(self, comments: List[Dict[str, Any]], reviews: List[Dict[str, Any]]) -> Dict[str, Any]:
        """Process reviewer statistics with sentiment analysis."""
        reviewers = {}
        total_sentiment = 0.0
        details_count = 0

        def is_bot_user(user_login: str) -> bool:
            if not user_login:
                return True
            normalized = user_login.lower()
            return (
                '[bot]' in normalized or 
                normalized.endswith('-bot') or 
                normalized in self.bot_identifiers
            )

        def analyze_entry(entry: Dict[str, Any]):
            nonlocal total_sentiment, details_count
            user_login = entry.get('user', {}).get('login')

            if is_bot_user(user_login):
                return

            if user_login not in reviewers:
                reviewers[user_login] = {
                    "name": user_login,
                    "avatar": entry.get('user', {}).get('avatar_url'),
                    "count": 0,
                    "is_maintainer": user_login == self.owner
                }

            reviewers[user_login]["count"] += 1

            body = entry.get('body', '')
            if body and len(body.strip()) > 3:
                try:
                    score = self.sia.polarity_scores(body)['compound']
                    total_sentiment += score
                    details_count += 1
                except Exception:
                    pass

        for comment in comments:
            analyze_entry(comment)
        for review in reviews:
            analyze_entry(review)

        avg_sentiment = total_sentiment / details_count if details_count > 0 else 0.0

        # Determine sentiment label using same thresholds as original
        if avg_sentiment >= 0.05:
            sentiment_label = "Positive"
        elif avg_sentiment <= -0.05:
            sentiment_label = "Negative"
        else:
            sentiment_label = "Neutral"

        return {
            "reviewers": list(reviewers.values()),
            "total_reviews": len(reviews),
            "total_comments": len(comments),
            "sentiment_score": avg_sentiment,
            "sentiment_label": sentiment_label
        }

# Clone: graph_net_bench_runner.py (Type III)
import importlib.util
import paddle
from pathlib import Path
import sys
import os
import numpy as np
import random
import platform
import traceback
import subprocess
import re
from graph_net.paddle import utils
from graph_net_bench import path_utils
from graph_net_bench import test_compiler_util
from graph_net import model_path_util
from graph_net.paddle.backend.graph_compiler_backend import GraphCompilerBackend
from graph_net.paddle.backend.cinn_backend import CinnBackend
from graph_net.paddle.backend.nope_backend import NopeBackend

# Registry mapping compiler names to backend instances
backend_registry = {
    "cinn": CinnBackend(),
    "nope": NopeBackend(),
}

def select_backend(config):
    if config.compiler not in backend_registry:
        raise ValueError(f"Unsupported compiler '{config.compiler}'. Available: {list(backend_registry.keys())}")
    return backend_registry[config.compiler]

def seed_all(seed_value):
    paddle.seed(seed_value)
    random.seed(seed_value)
    np.random.seed(seed_value)

def setup_environment(config):
    if test_compiler_util.is_gpu_device(config.device):
        paddle.set_flags({"FLAGS_cudnn_exhaustive_search": 1})

def fetch_hardware_info(config):
    device_name = "unknown"
    if test_compiler_util.is_gpu_device(config.device):
        device_name = paddle.device.cuda.get_device_name(0)
    elif config.device == "xpu":
        try:
            raw_output = subprocess.check_output(["xpu-smi", "-L"], text=True)
            for line in raw_output.splitlines():
                match = re.search(r"XPU\s+(\d+):\s+(.+?)\s+\(UUID:\s*([^)]+)\)", line)
                if match:
                    device_name = match.group(2)
                    break
        except Exception:
            pass
    elif config.device == "cpu":
        device_name = platform.processor()
    return device_name

def get_framework_version(config):
    if config.compiler in ["cinn", "nope"]:
        return paddle.__version__
    return "unknown"

def load_model_class_from_file(filepath, target_class_name):
    resolved_path = Path(filepath).resolve()
    module_id = resolved_path.stem
    with open(filepath, "r", encoding="utf-8") as fh:
        original_content = fh.read()
    preamble = "import paddle\n"
    modified_code = preamble + original_content
    spec = importlib.util.spec_from_loader(module_id, loader=None)
    mod = importlib.util.module_from_spec(spec)
    sys.modules[module_id] = mod
    compiled_ast = compile(modified_code, filename=str(resolved_path), mode="exec")
    exec(compiled_ast, mod.__dict__)
    cls = getattr(mod, target_class_name, None)
    return cls

def instantiate_model(model_dir):
    cls = load_model_class_from_file(
        os.path.join(model_dir, "model.py"), class_name="GraphModule"
    )
    return cls()

def prepare_input_state_dict(model_dir):
    raw_data = utils.load_converted_from_text(model_dir)
    weight_params = raw_data["weight_info"]
    input_params = raw_data["input_info"]
    combined = {**weight_params, **input_params}
    state_dict = {k: utils.replay_tensor(v) for k, v in combined.items()}
    return state_dict

def build_input_signature(model_dir):
    param_list = utils.load_converted_list_from_text(model_dir)
    specs = [None] * len(param_list)
    for idx, entry in enumerate(param_list):
        dtype_str = entry["info"]["dtype"]
        shape_tuple = entry["info"]["shape"]
        specs[idx] = paddle.static.InputSpec(shape_tuple, dtype_str)
    return specs

def convert_to_static_graph(config, dynamic_model):
    sigs = build_input_signature(config.model_path)
    static_graph = paddle.jit.to_static(
        dynamic_model,
        input_spec=sigs,
        full_graph=True,
        backend=None,
    )
    static_graph.eval()
    _ = static_graph.forward.concrete_program.main_program
    return static_graph

def benchmark_execution(model_func, config, backend_obj, do_profile=False):
    base_seed = 1024
    paddle.seed(base_seed)
    # Initial inference to ensure correctness
    outputs = model_func()

    # Warm-up phase
    warmup_durations = []
    for _ in range(config.warmup):
        timer = test_compiler_util.DurationBox(-1)
        with test_compiler_util.naive_timer(timer, backend_obj.synchronize):
            model_func()
        warmup_durations.append(timer.value)
    backend_obj.synchronize()

    # Determine number of trials based on warm-up timing
    avg_warmup = np.mean(warmup_durations[1:]) if len(warmup_durations) > 1 else 0.1
    min_required_trials = int(100 / max(avg_warmup, 0.01))
    num_trials = max(config.trials, min_required_trials)

    hw_name = fetch_hardware_info(config)
    print(
        f"[Profiling] Device: {config.device} {hw_name}, warmup={config.warmup}, trials={num_trials}",
        file=sys.stderr,
        flush=True,
    )

    if do_profile:
        import paddle.profiler as profiler
        prof = profiler.Profiler()
        prof.start()

    if test_compiler_util.is_gpu_device(config.device):
        e2e_times = []
        gpu_times = []
        for trial_idx in range(num_trials):
            timer = test_compiler_util.DurationBox(-1)
            start_ev = paddle.device.Event(enable_timing=True)
            end_ev = paddle.device.Event(enable_timing=True)
            start_ev.record()
            with test_compiler_util.naive_timer(timer, backend_obj.synchronize):
                model_func()
            end_ev.record()
            if do_profile:
                prof.step()
            gpu_ms = start_ev.elapsed_time(end_ev)
            e2e_times.append(timer.value)
            gpu_times.append(gpu_ms)
            print(
                f"Trial {trial_idx + 1}: e2e={timer.value:.5f} ms, gpu={gpu_ms:.5f} ms",
                file=sys.stderr,
                flush=True,
            )
        stats = {
            "e2e": test_compiler_util.get_timing_stats(e2e_times),
            "gpu": test_compiler_util.get_timing_stats(gpu_times),
        }
    else:
        e2e_times = []
        for trial_idx in range(num_trials):
            timer = test_compiler_util.DurationBox(-1)
            with test_compiler_util.naive_timer(timer, backend_obj.synchronize):
                model_func()
            if do_profile:
                prof.step()
            e2e_times.append(timer.value)
            print(
                f"Trial {trial_idx + 1}: e2e={timer.value:.4f} ms",
                file=sys.stderr,
                flush=True,
            )
        stats = {"e2e": test_compiler_util.get_timing_stats(e2e_times)}

    if do_profile:
        prof.stop()
        prof.summary()
    return outputs, stats

def validate_outputs(config, reference_out, test_out):
    def flatten(x):
        if isinstance(x, paddle.Tensor):
            return [x]
        result = []
        for item in (x if isinstance(x, (tuple, list)) else [x]):
            result.extend(item if isinstance(item, (tuple, list)) else [item])
        return result

    ref_flat = flatten(reference_out)
    test_flat = flatten(test_out)

    def extract_dtypes(tensor_list):
        return [
            str(t.dtype).replace("paddle.", "") if isinstance(t, paddle.Tensor) else None
            for t in tensor_list
        ]

    ref_dtypes = extract_dtypes(ref_flat)
    test_dtypes = extract_dtypes(test_flat)
    dtypes_ok = test_compiler_util.check_output_datatype(config, ref_dtypes, test_dtypes)

    def extract_shapes(tensor_list):
        return [t.shape if isinstance(t, paddle.Tensor) else None for t in tensor_list]

    ref_shapes = extract_shapes(ref_flat)
    test_shapes = extract_shapes(test_flat)
    shapes_ok = test_compiler_util.check_output_shape(config, ref_shapes, test_shapes)

    def cast_to_float32_if_needed(tensor_list):
        converted = []
        for t in tensor_list:
            if isinstance(t, paddle.Tensor) and t.dtype not in [paddle.float32, paddle.float64]:
                converted.append(t.astype("float32"))
            else:
                converted.append(t)
        return converted

    if dtypes_ok and shapes_ok:
        test_compiler_util.check_equal(
            config,
            ref_flat,
            test_flat,
            cmp_equal_func=compare_tensors_equal,
        )
        ref_fp32 = cast_to_float32_if_needed(ref_flat)
        test_fp32 = cast_to_float32_if_needed(test_flat)
        test_compiler_util.check_allclose(
            config,
            ref_fp32,
            test_fp32,
            cmp_all_close_func=compare_allclose,
            cmp_max_diff_func=compute_max_diff,
            cmp_mean_diff_func=compute_mean_diff,
            cmp_max_relative_diff_func=compute_max_rel_diff,
            cmp_mean_relative_diff_func=compute_mean_rel_diff,
        )

def report_gpu_usage(backend):
    if paddle.device.is_compiled_with_cuda():
        dev_id = int(paddle.device.get_device().split(":")[-1])
        dev_count = paddle.device.cuda.device_count()
        gpu_pct, mem_pct = test_compiler_util.get_device_utilization(
            dev_id, dev_count, backend.synchronize
        )
        if gpu_pct is not None and mem_pct is not None:
            print(
                f"Device status: gpu_id {dev_id}, gpu_util {gpu_pct:.2f}%, mem_util {mem_pct:.2f}%",
                file=sys.stderr,
                flush=True,
            )

def run_single_test(config):
    model_dir = os.path.normpath(config.model_path)
    test_compiler_util.print_with_log_prompt(
        "[Processing]", model_dir, config.log_prompt
    )
    backend = select_backend(config)
    report_gpu_usage(backend)
    input_state = prepare_input_state_dict(model_dir)
    model = instantiate_model(model_dir)
    model.eval()
    test_compiler_util.print_basic_config(
        config, fetch_hardware_info(config), get_framework_version(config)
    )

    eager_ok = False
    eager_stats = {}
    try:
        print("Running model in eager mode...", file=sys.stderr, flush=True)
        static_model = convert_to_static_graph(config, model)
        expected_result, eager_stats = benchmark_execution(
            lambda: static_model(**input_state), config, backend, profile=False
        )
        eager_ok = True
    except Exception as e:
        print(
            f"Eager mode failed: {str(e)}\n{traceback.format_exc()}",
            file=sys.stderr,
            flush=True,
        )

    compiled_ok = False
    compiled_stats = {}
    try:
        print("Running model in compiled mode...", file=sys.stderr, flush=True)
        sigs = build_input_signature(model_dir)
        compiled_model = backend(model, sigs)
        test_result, compiled_stats = benchmark_execution(
            lambda: compiled_model(**input_state), config, backend, profile=False
        )
        compiled_ok = True
    except Exception as e:
        print(
            f"Compiled mode failed: {str(e)}\n{traceback.format_exc()}",
            file=sys.stderr,
            flush=True,
        )

    test_compiler_util.print_running_status(config, eager_ok, compiled_ok)
    if eager_ok and compiled_ok:
        validate_outputs(config, expected_result, test_result)
    test_compiler_util.print_times_and_speedup(
        config, eager_stats, compiled_stats
    )

def compare_tensors_equal(ref, comp):
    def normalize_dtype(x):
        if x.dtype in [paddle.float16, paddle.bfloat16]:
            return x.astype("float32")
        elif x.dtype in [paddle.uint8, paddle.int8, paddle.int16]:
            return x.astype("int32")
        return x
    results = []
    for a, b in zip(ref, comp):
        results.append(str(int(paddle.equal_all(normalize_dtype(a), normalize_dtype(b)))))
    return " ".join(results)

def compare_allclose(ref, comp, atol, rtol):
    return " ".join(
        str(int(paddle.allclose(a, b, atol=atol, rtol=rtol)))
        for a, b in zip(comp, ref)
    )

def format_number(val):
    if abs(val) > 1e5 or abs(val) < 1e-5 and val != 0.0:
        return f"{val:.5E}"
    return f"{val:.5f}"

def compute_max_diff(ref, comp):
    return " ".join(
        format_number(paddle.max(paddle.abs(a - b)).item())
        for a, b in zip(ref, comp)
    )

def compute_mean_diff(ref, comp):
    return " ".join(
        format_number(paddle.mean(paddle.abs(a - b)).item())
        for a, b in zip(ref, comp)
    )

def compute_max_rel_diff(ref, comp):
    eps = 1e-8
    return " ".join(
        format_number(paddle.max(paddle.abs(a - b) / (paddle.abs(a) + eps)).item())
        for a, b in zip(ref, comp)
    )

def compute_mean_rel_diff(ref, comp):
    eps = 1e-8
    return " ".join(
        format_number(
            paddle.mean(paddle.abs(a - b) / (paddle.abs(a) + eps)).item()
        )
        for a, b in zip(ref, comp)
    )

def run_batch_tests(config):
    allowed_samples = model_path_util.get_allow_samples(config.allow_list)
    counter = 0
    failures = []
    script_module = os.path.splitext(os.path.basename(__file__))[0]
    for model_path in path_utils.get_recursively_model_path(config.model_path):
        if allowed_samples is None or os.path.abspath(model_path) in allowed_samples:
            print(
                f"[{counter}] {script_module}, model_path: {model_path}",
                file=sys.stderr,
                flush=True,
            )
            cmd_parts = [
                sys.executable,
                f"-m graph_net.paddle.{script_module}",
                f"--model-path {model_path}",
                f"--compiler {config.compiler}",
                f"--device {config.device}",
                f"--warmup {config.warmup}",
                f"--trials {config.trials}",
                f"--log-prompt {config.log_prompt}",
            ]
            exit_code = os.system(" ".join(cmd_parts))
            if exit_code != 0:
                failures.append(model_path)
            counter += 1
    print(
        f"Total verified samples: {counter}, failed: {len(failures)}",
        file=sys.stderr,
        flush=True,
    )
    for path in failures:
        print(f"- {path}", file=sys.stderr, flush=True)

def main(config):
    assert os.path.isdir(config.model_path)
    assert config.compiler in {"cinn", "nope"}
    assert config.device in ["cuda", "dcu", "xpu", "cpu"]
    init_seed = 123
    seed_all(init_seed)
    if path_utils.is_single_model_dir(config.model_path):
        run_single_test(config)
    else:
        run_batch_tests(config)

if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Benchmark compiler performance.")
    parser.add_argument(
        "--model-path",
        type=str,
        required=True,
        help="Directory containing models (each subdirectory with graph_net.json is a model)",
    )
    parser.add_argument(
        "--compiler",
        type=str,
