    )
    parser.add_argument(
        "--device",
        type=str,
        required=False,
        default="cuda",
        help="Target device for execution (e.g., 'cpu', 'cuda', 'xpu')",
    )
    parser.add_argument(
        "--warmup", type=int, required=False, default=5, help="Warmup iterations"
    )
    parser.add_argument(
        "--trials", type=int, required=False, default=10, help="Number of timing runs"
    )
    parser.add_argument(
        "--log-prompt",
        type=str,
        required=False,
        default="graph-net-test-compiler-log",
        help="Prefix for log filtering",
    )
    parser.add_argument(
        "--allow-list",
        type=str,
        required=False,
        default=None,
        help="Path to file listing allowed model paths (one per line)",
    )
    cfg = parser.parse_args()
    main(cfg)

import base64
import json
import re
from typing import Optional, Tuple, List
from urllib.parse import unquote, urlparse

class ConfigValidator:
    @staticmethod
    def is_base64(s: str) -> bool:
        try:
            s = s.rstrip('=')
            return bool(re.match(r'^[A-Za-z0-9+/=_-]*$', s))
        except:
            return False

    @staticmethod
    def decode_base64_url(s: str) -> Optional[bytes]:
        try:
            # Replace URL-safe characters with standard base64 characters
            s = s.replace('-', '+').replace('_', '/')
            # Add padding if necessary
            padding_needed = (4 - len(s) % 4) % 4
            s += '=' * padding_needed
            return base64.b64decode(s)
        except:
            return None

    @staticmethod
    def decode_base64_text(text: str) -> Optional[str]:
        try:
            if ConfigValidator.is_base64(text):
                decoded_bytes = ConfigValidator.decode_base64_url(text)
                if decoded_bytes:
                    return decoded_bytes.decode('utf-8')
            return None
        except:
            return None

    @staticmethod
    def clean_vmess_config(config: str) -> str:
        if "vmess://" in config:
            base64_part = config[8:]
            # Extract only valid base64 characters
            base64_clean = re.split(r'[^A-Za-z0-9+/=_-]', base64_part)[0]
            return f"vmess://{base64_clean}"
        return config

    @staticmethod
    def normalize_hysteria2_protocol(config: str) -> str:
        if config.startswith('hy2://'):
            return config.replace('hy2://', 'hysteria2://', 1)
        return config

    @staticmethod
    def is_vmess_config(config: str) -> bool:
        try:
            if not config.startswith('vmess://'):
                return False
            base64_part = config[8:]
            decoded = ConfigValidator.decode_base64_url(base64_part)
            if decoded:
                json.loads(decoded)
                return True
            return False
        except:
            return False

    @staticmethod
    def is_tuic_config(config: str) -> bool:
        try:
            if config.startswith('tuic://'):
                parsed = urlparse(config)
                return bool(parsed.netloc and ':' in parsed.netloc)
            return False
        except:
            return False

    @staticmethod
    def convert_ssconf_to_https(url: str) -> str:
        if url.startswith('ssconf://'):
            return url.replace('ssconf://', 'https://', 1)
        return url

    @staticmethod
    def is_base64_config(config: str) -> Tuple[bool, str]:
        protocols = ['vmess://', 'vless://', 'ss://', 'tuic://']
        for protocol in protocols:
            if config.startswith(protocol):
                base64_part = config[len(protocol):]
                decoded_url = unquote(base64_part)
                if (ConfigValidator.is_base64(decoded_url) or 
                    ConfigValidator.is_base64(base64_part)):
                    return True, protocol[:-3]
        return False, ''

    @staticmethod
    def check_base64_content(text: str) -> Optional[str]:
        try:
            decoded_text = ConfigValidator.decode_base64_text(text)
            if decoded_text:
                protocols = ['vmess://', 'vless://', 'ss://', 'trojan://', 'hysteria2://', 'hy2://', 'wireguard://', 'tuic://', 'ssconf://']
                for protocol in protocols:
                    if protocol in decoded_text:
                        return decoded_text
            return None
        except:
            return None

    @staticmethod
    def split_configs(text: str) -> List[str]:
        configs = []
        lines = text.split('\n')

        for line in lines:
            line = line.strip()
            if not line:
                continue

            if ConfigValidator.is_base64(line):
                decoded_content = ConfigValidator.check_base64_content(line)
                if decoded_content:
                    text = decoded_content

            protocols = ['vmess://', 'vless://', 'ss://', 'trojan://', 'hysteria2://', 'hy2://', 'wireguard://', 'tuic://', 'ssconf://']
            current_pos = 0
            text_length = len(text)

            while current_pos < text_length:
                next_config_start = text_length
                matching_protocol = None

                for protocol in protocols:
                    protocol_pos = text.find(protocol, current_pos)
                    if protocol_pos != -1 and protocol_pos < next_config_start:
                        next_config_start = protocol_pos
                        matching_protocol = protocol

                if matching_protocol:
                    if current_pos < next_config_start and configs:
                        current_config = text[current_pos:next_config_start].strip()
                        if ConfigValidator.is_valid_config(current_config):
                            configs.append(current_config)

                    current_pos = next_config_start
                    next_protocol_pos = text_length

                    for protocol in protocols:
                        pos = text.find(protocol, next_config_start + len(matching_protocol))
                        if pos != -1 and pos < next_protocol_pos:
                            next_protocol_pos = pos

                    current_config = text[next_config_start:next_protocol_pos].strip()
                    if matching_protocol == "vmess://":
                        current_config = ConfigValidator.clean_vmess_config(current_config)
                    elif matching_protocol == "hy2://":
                        current_config = ConfigValidator.normalize_hysteria2_protocol(current_config)
                    if ConfigValidator.is_valid_config(current_config):
                        configs.append(current_config)

                    current_pos = next_protocol_pos
                else:
                    break

        return configs

    @staticmethod
    def clean_config(config: str) -> str:
        # Remove emojis
        config = re.sub(r'[\U0001F300-\U0001F9FF]', '', config)
        # Remove control characters except newline and carriage return
        config = re.sub(r'[\x00-\x08\x0B-\x1F\x7F-\x9F]', '', config)
        # Normalize whitespace
        config = re.sub(r'[^\S\r\n]+', ' ', config)
        config = config.strip()
        return config

    @staticmethod
    def is_valid_config(config: str) -> bool:
        if not config:
            return False

        protocols = ['vmess://', 'vless://', 'ss://', 'trojan://', 'hysteria2://', 'hy2://', 'wireguard://', 'tuic://', 'ssconf://']
        return any(config.startswith(p) for p in protocols)

    @classmethod
    def validate_protocol_config(cls, config: str, protocol: str) -> bool:
        try:
            if protocol in ['vmess://', 'vless://', 'ss://', 'tuic://']:
                if protocol == 'vmess://':
                    return cls.is_vmess_config(config)
                if protocol == 'tuic://':
                    return cls.is_tuic_config(config)
                base64_part = config[len(protocol):]
                decoded_url = unquote(base64_part)
                if cls.is_base64(decoded_url) or cls.is_base64(base64_part):
                    return True
                if cls.decode_base64_url(base64_part) or cls.decode_base64_url(decoded_url):
                    return True
            elif protocol in ['trojan://', 'hysteria2://', 'hy2://', 'wireguard://']:
                parsed = urlparse(config)
                return bool(parsed.netloc and '@' in parsed.netloc)
            elif protocol == 'ssconf://':
                return True
            return False
        except:
            return False

# Auto-arrange nodes for improved visualization
# Supports multiple layout strategies: horizontal, vertical, tree, and grid arrangements

import json
from typing import Dict, List, Any
from langchain.tools import tool
from pydantic import BaseModel, Field
from app.core.copilot.tools.context import get_current_graph_context


class NodeArrangementInput(BaseModel):
    """Schema for node arrangement parameters."""
    arrangement_mode: str = Field(
        default="horizontal",
        description="Layout strategy: 'horizontal' (left-to-right), 'vertical' (top-to-bottom), 'tree' (hierarchical), 'grid' (matrix)",
    )
    gap_x: float = Field(default=300, description="Horizontal distance between adjacent nodes")
    gap_y: float = Field(default=150, description="Vertical distance between adjacent nodes")
    origin_x: float = Field(default=100, description="Initial X coordinate for layout")
    origin_y: float = Field(default=100, description="Initial Y coordinate for layout")
    justification: str = Field(description="Rationale for applying automatic node arrangement")


@tool(
    args_schema=NodeArrangementInput,
    description="Automatically reposition nodes to enhance diagram clarity. Available modes: horizontal, vertical, tree, grid.",
)
def arrange_nodes(
    justification: str,
    arrangement_mode: str = "horizontal",
    gap_x: float = 300,
    gap_y: float = 150,
    origin_x: float = 100,
    origin_y: float = 100,
) -> str:
    """
    Automatically repositions nodes to improve visual organization.

    Args:
        justification: Explanation for why automatic arrangement is required
        arrangement_mode: Layout pattern ('horizontal', 'vertical', 'tree', 'grid')
        gap_x: Horizontal separation between nodes (default: 300)
        gap_y: Vertical separation between nodes (default: 150)
        origin_x: Starting horizontal position (default: 100)
        origin_y: Starting vertical position (default: 100)

    Returns:
        JSON-formatted response containing positioning instructions for all nodes.
    """
    graph_data = get_current_graph_context()
    node_list = graph_data.get("nodes", [])
    connection_list = graph_data.get("edges", [])

    if not node_list:
        return json.dumps(
            {
                "error": "No nodes present in the current graph to organize",
                "recommendation": "Add nodes to the graph before applying arrangement",
            },
            ensure_ascii=False,
        )

    update_commands = []

    # Construct adjacency relationships
    forward_connections: Dict[str, List[str]] = {n.get("id"): [] for n in node_list}
    backward_connections: Dict[str, List[str]] = {n.get("id"): [] for n in node_list}

    for conn in connection_list:
        source_id = conn.get("source")
        target_id = conn.get("target")
        if source_id in forward_connections and target_id in backward_connections:
            forward_connections[source_id].append(target_id)
            backward_connections[target_id].append(source_id)

    # Identify starting points (nodes without predecessors)
    start_nodes = [n for n in node_list if not backward_connections.get(n.get("id"), [])]

    if arrangement_mode == "horizontal":
        # Level-order traversal assigning column indices
        processed = set()
        col_assignment: Dict[str, int] = {}
        queue = [(n.get("id"), 0) for n in start_nodes]

        while queue:
            current_id, level = queue.pop(0)
            if current_id in processed:
                continue
            processed.add(current_id)
            col_assignment[current_id] = level

            for neighbor in forward_connections.get(current_id, []):
                if neighbor not in processed:
                    queue.append((neighbor, level + 1))

        # Calculate positions based on columns
        row_tracker: Dict[int, int] = {}
        for node in node_list:
            node_id = node.get("id")
            col = col_assignment.get(node_id, 0)
            row = row_tracker.get(col, 0)
            row_tracker[col] = row + 1

            new_x = origin_x + col * gap_x
            new_y = origin_y + row * gap_y

            update_commands.append({
                "type": "UPDATE_POSITION",
                "payload": {"id": node_id, "position": {"x": new_x, "y": new_y}},
                "reasoning": f"Auto-arrange: positioned at column {col}, row {row}",
            })

    elif arrangement_mode == "vertical":
        # Similar to horizontal but with roles of x/y swapped
        processed = set()
        row_assignment: Dict[str, int] = {}
        queue = [(n.get("id"), 0) for n in start_nodes]

        while queue:
            current_id, level = queue.pop(0)
            if current_id in processed:
                continue
            processed.add(current_id)
            row_assignment[current_id] = level

            for neighbor in forward_connections.get(current_id, []):
                if neighbor not in processed:
                    queue.append((neighbor, level + 1))

        # Position nodes by rows
        col_tracker: Dict[int, int] = {}
        for node in node_list:
            node_id = node.get("id")
            row = row_assignment.get(node_id, 0)
            col = col_tracker.get(row, 0)
            col_tracker[row] = col + 1

            new_x = origin_x + col * gap_x
            new_y = origin_y + row * gap_y

            update_commands.append({
                "type": "UPDATE_POSITION",
                "payload": {"id": node_id, "position": {"x": new_x, "y": new_y}},
                "reasoning": f"Vertical arrangement: placed at row {row}, column {col}",
            })

    elif arrangement_mode == "tree":
        # Hierarchical layout with root nodes at top
        processed = set()
        depth_map: Dict[str, int] = {}
        depth_groups: Dict[int, List[str]] = {}
        queue = [(n.get("id"), 0) for n in start_nodes]

        while queue:
            current_id, depth = queue.pop(0)
            if current_id in processed:
                continue
            processed.add(current_id)
            depth_map[current_id] = depth

            if depth not in depth_groups:
                depth_groups[depth] = []
            depth_groups[depth].append(current_id)

            for child in forward_connections.get(current_id, []):
                if child not in processed:
                    queue.append((child, depth + 1))

        # Center nodes within each depth level
        for depth, group in depth_groups.items():
            count = len(group)
            total_width = (count - 1) * gap_x
            center_offset = -total_width / 2

            for idx, node_id in enumerate(group):
                new_x = origin_x + 400 + center_offset + idx * gap_x
                new_y = origin_y + depth * gap_y

                update_commands.append({
                    "type": "UPDATE_POSITION",
                    "payload": {"id": node_id, "position": {"x": new_x, "y": new_y}},
                    "reasoning": f"Tree layout: depth {depth}, position {idx + 1}/{count}",
                })

    elif arrangement_mode == "grid":
        # Simple grid-based placement
        cols = max(3, int(len(node_list) ** 0.5))
        for idx, node in enumerate(node_list):
            row = idx // cols
            col = idx % cols
            new_x = origin_x + col * gap_x
            new_y = origin_y + row * gap_y

            update_commands.append({
                "type": "UPDATE_POSITION",
                "payload": {"id": node.get("id"), "position": {"x": new_x, "y": new_y}},
                "reasoning": f"Grid layout: row {row}, column {col}",
            })

    return json.dumps(
        {
            "layout_strategy": arrangement_mode,
            "nodes_repositioned": len(update_commands),
            "actions": update_commands,
            "justification": justification,
        },
        ensure_ascii=False,
        indent=2,
    )

# Module for encoding/decoding QR payload data with support for raw and base64 formats

from __future__ import annotations
import base64
import binascii
from typing import Final, Literal

# Define supported codecs as string literals
QrPayloadCodec = Literal["raw", "base64"]
QR_PAYLOAD_CODEC_RAW: Final[QrPayloadCodec] = "raw"
QR_PAYLOAD_CODEC_BASE64: Final[QrPayloadCodec] = "base64"

def encode_qr_payload(
    data: bytes,
    *,
    codec: QrPayloadCodec = QR_PAYLOAD_CODEC_BASE64,
) -> bytes | str:
    """Encode frame bytes for QR transport."""
    if codec == QR_PAYLOAD_CODEC_RAW:
        return data

    # Validate codec before proceeding
    if codec != QR_PAYLOAD_CODEC_BASE64:
        raise ValueError(f"unsupported QR payload codec: {codec}")

    # Encode using base64 and remove padding
    encoded = base64.b64encode(data).decode("ascii")
    return encoded.rstrip("=")

def decode_qr_payload(
    payload: bytes | str,
    *,
    codec: QrPayloadCodec = QR_PAYLOAD_CODEC_BASE64,
) -> bytes:
    """Decode frame bytes from QR transport payload."""
    if codec == QR_PAYLOAD_CODEC_RAW:
        if isinstance(payload, bytes):
            return payload
        raise ValueError("invalid raw QR payload")

    # Validate codec before proceeding
    if codec != QR_PAYLOAD_CODEC_BASE64:
        raise ValueError(f"unsupported QR payload codec: {codec}")

    return _decode_base64_qr_payload(payload)

def _decode_base64_qr_payload(payload: bytes | str) -> bytes:
    """Decode unpadded base64 QR payload text."""
    # Convert to string if needed
    if isinstance(payload, bytes):
        try:
            text = payload.decode("ascii")
        except UnicodeDecodeError as exc:
            raise ValueError("invalid base64 QR payload") from exc
    else:
        text = payload

    # Remove whitespace characters
    cleaned = "".join(text.split())

    # Check for padding characters (not allowed in QR payloads)
    if "=" in cleaned:
        raise ValueError("invalid base64 QR payload")

    # Pad and decode
    try:
        padded_text = _pad_unpadded_base64(cleaned)
        decoded = base64.b64decode(padded_text, validate=True)
    except (binascii.Error, ValueError) as exc:
        raise ValueError("invalid base64 QR payload") from exc

    # Verify correctness by re-encoding and comparing
    canonical = base64.b64encode(decoded).decode("ascii").rstrip("=")
    if canonical != cleaned:
        raise ValueError("invalid base64 QR payload")

    return decoded

def _pad_unpadded_base64(text: str) -> str:
    """Add required padding to unpadded base64 text."""
    # Calculate how many '=' characters are needed
    padding_needed = (4 - len(text) % 4) % 4
    return text + ("=" * padding_needed)

__all__ = [
    "QR_PAYLOAD_CODEC_BASE64",
    "QR_PAYLOAD_CODEC_RAW",
    "QrPayloadCodec",
    "decode_qr_payload",
    "encode_qr_payload",
]

from typing import IO, Dict, List, Mapping, Optional, Tuple, Union, cast

# Type definitions for file handling, adapted from httpx's approach
# Reference: https://github.com/encode/httpx/blob/master/httpx/_types.py
FileContent = Union[IO[bytes], bytes, str]
FileRepresentation = Union[
    # raw file content (bytes, str, or IO)
    FileContent,
    # (filename, content)
    Tuple[Optional[str], FileContent],
    # (filename, content, MIME type)
    Tuple[Optional[str], FileContent, Optional[str]],
    # (filename, content, MIME type, additional headers)
    Tuple[
        Optional[str],
        FileContent,
        Optional[str],
        Mapping[str, str],
    ],
]

def transform_file_mapping_to_httpx_format(
    input_dict: Dict[str, Union[FileRepresentation, List[FileRepresentation]]],
) -> List[Tuple[str, FileRepresentation]]:
    """
    Converts a dictionary mapping field names to files into a list of tuples.

    This format is necessary for HTTPX when uploading multiple files per field,
    as it requires a list of (field_name, file_data) tuples rather than a dict.
    See: https://github.com/encode/httpx/pull/1032
    """
    result_list = []
    for field_name, file_data in input_dict.items():
        if isinstance(file_data, list):
            for item in file_data:
                result_list.append((field_name, item))
        else:
            result_list.append((field_name, file_data))
    return result_list

def ensure_content_type(
    *,
    file_data: FileRepresentation,
    fallback_content_type: str,
) -> FileRepresentation:
    """
    Ensures that the file has an associated content type.

    If no content type is specified in the file representation, 
    uses the provided fallback_content_type instead.
    """
    if isinstance(file_data, tuple):
        length = len(file_data)
        if length == 2:
            filename, content = cast(Tuple[Optional[str], FileContent], file_data)  # type: ignore
            return (filename, content, fallback_content_type)
        elif length == 3:
            filename, content, existing_type = cast(Tuple[Optional[str], FileContent, Optional[str]], file_data)  # type: ignore
            final_type = existing_type if existing_type else fallback_content_type
            return (filename, content, final_type)
        elif length == 4:
            filename, content, existing_type, headers = cast(  # type: ignore
                Tuple[Optional[str], FileContent, Optional[str], Mapping[str, str]], file_data
            )
            final_type = existing_type if existing_type else fallback_content_type
            return (filename, content, final_type, headers)
        else:
            raise ValueError(f"Invalid tuple structure size: {length}")
    # Default case: wrap with None filename and provided content type
    return (None, file_data, fallback_content_type)

# Custom byte-level tokenizer implementation for T5-based models
import warnings
from typing import List, Optional, Tuple
from ...tokenization_utils import AddedToken, PreTrainedTokenizer
from ...utils import logging

logger = logging.get_logger(__name__)

class ByteLevelT5Tokenizer(PreTrainedTokenizer):
    """
    Implements a byte-level tokenizer that processes text using UTF-8 encoding directly.

    This tokenizer treats each byte in the UTF-8 representation of input text as a token,
    enabling subword-level processing without explicit vocabulary constraints. It extends
    PreTrainedTokenizer and inherits most standard tokenization behaviors.

    Args:
        eos_token (str, optional): End-of-sequence marker. Defaults to "</s>".
        unk_token (str, optional): Token used for unknown characters. Defaults to "<unk>".
        pad_token (str, optional): Padding token for variable-length sequences. Defaults to "<pad>".
        extra_ids (int, optional): Number of sentinel tokens for special purposes. Defaults to 125.
        additional_special_tokens (List[str], optional): Extra special tokens beyond defaults.
    """
    model_input_names = ["input_ids", "attention_mask"]

    def __init__(
        self,
        eos_token="</s>",
        unk_token="<unk>",
        pad_token="<pad>",
        extra_ids=125,
        additional_special_tokens=None,
        **kwargs,
    ) -> None:
        # Initialize special tokens list if needed
        if extra_ids > 0 and not additional_special_tokens:
            additional_special_tokens = [f"<extra_id_{i}>" for i in range(extra_ids)]
        elif extra_ids > 0 and additional_special_tokens and len(additional_special_tokens) > 0:
            # Validate that extra IDs are properly represented in additional tokens
            sentinel_count = sum(1 for tok in additional_special_tokens if "extra_id" in str(tok))
            if sentinel_count != extra_ids:
                raise ValueError(
                    f"Mismatch between requested extra_ids ({extra_ids}) and provided "
                    f"additional_special_tokens ({additional_special_tokens}). "
                    "The additional_special_tokens must include exactly the specified number of extra_id tokens."
                )

        # Normalize token representations with stripping behavior
        pad_token = AddedToken(pad_token, lstrip=True, rstrip=True) if isinstance(pad_token, str) else pad_token
        eos_token = AddedToken(eos_token, lstrip=True, rstrip=True) if isinstance(eos_token, str) else eos_token
        unk_token = AddedToken(unk_token, lstrip=True, rstrip=True) if isinstance(unk_token, str) else unk_token

        # Define internal mapping for special tokens
        self._added_tokens_decoder = {0: pad_token, 1: eos_token, 2: unk_token}
        self.special_token_offset = len(self._added_tokens_decoder)
        self.byte_vocab_size = 256  # Full byte range (0-255)

        # Initialize parent class with adjusted parameters
        super().__init__(
            eos_token=eos_token,
            unk_token=unk_token,
            pad_token=pad_token,
            extra_ids=0,
            additional_special_tokens=additional_special_tokens,
            **kwargs,
        )

    @property
    def vocab_length(self):
        """Returns total vocabulary size including special tokens."""
        return self.byte_vocab_size + self.special_token_offset

    def retrieve_vocabulary(self):
        """Builds and returns full vocabulary dictionary mapping tokens to IDs."""
        vocab = {
            self.convert_ids_to_tokens(i): i 
            for i in range(self.vocab_length)
        }
        vocab.update(self.added_tokens_encoder)
        return vocab

    def get_special_tokens_indicator(
        self, 
        token_sequence_a: List[int], 
        token_sequence_b: Optional[List[int]] = None, 
        preprocessed: bool = False
    ) -> List[int]:
        """
        Generates binary mask indicating which positions contain special tokens.

        Args:
            token_sequence_a: First sequence of token IDs
            token_sequence_b: Optional second sequence for paired inputs
            preprocessed: Whether sequences already contain special tokens

        Returns:
            Binary mask where 1 indicates special token position, 0 otherwise
        """
        if preprocessed:
            return super().get_special_tokens_mask(
                token_ids_0=token_sequence_a, 
                token_ids_1=token_sequence_b, 
                already_has_special_tokens=True
            )

        # Standard case: add EOS markers as special tokens
        if token_sequence_b is None:
            return [0] * len(token_sequence_a) + [1]
        else:
            return [0] * len(token_sequence_a) + [1] + [0] * len(token_sequence_b) + [1]

    def append_eos_if_missing(self, token_list: List[int]) -> List[int]:
        """Ensures end-of-sequence token is present at end of sequence."""
        if token_list and token_list[-1] == self.eos_token_id:
            warnings.warn(
                f"Sequence already contains {self.eos_token}. Future versions may produce duplicate EOS tokens."
            )
            return token_list
        return token_list + [self.eos_token_id]

    def generate_segment_ids(
        self, 
        primary_tokens: List[int], 
        secondary_tokens: Optional[List[int]] = None
    ) -> List[int]:
        """
        Creates token type IDs for sequence classification tasks.

        Since ByT5 doesn't use segment embeddings, this always returns zeros.
        """
        eos_marker = [self.eos_token_id]
        if secondary_tokens is None:
            return [0] * len(primary_tokens + eos_marker)
        else:
            return [0] * len(primary_tokens + eos_marker + secondary_tokens + eos_marker)

    def prepare_model_inputs(
        self, 
        primary_tokens: List[int], 
        secondary_tokens: Optional[List[int]] = None
    ) -> List[int]:
        """
        Constructs final input sequence with appropriate special tokens.

        Format:
        - Single sequence: X </s>
        - Paired sequences: X </s> Y </s>
        """
        primary_tokens = self.append_eos_if_missing(primary_tokens)
        if secondary_tokens is None:
            return primary_tokens
        else:
            secondary_tokens = self.append_eos_if_missing(secondary_tokens)
            return primary_tokens + secondary_tokens

    def split_into_bytes(self, text: str) -> List[str]:
        """Converts input string into list of byte-character tokens."""
        return [chr(byte_val) for byte_val in text.encode("utf-8")]

    def encode_byte_to_id(self, char_token):
        """Maps single-byte character to its corresponding ID."""
        if len(char_token) != 1:
            return None
        return ord(char_token) + self.special_token_offset

    def decode_id_to_byte(self, token_id):
        """Converts token ID back to original byte character."""
        return chr(token_id - self.special_token_offset)

    def reconstruct_text(self, token_sequence):
        """Reconstructs original text from sequence of byte tokens."""
        byte_buffer = b""
        for token in token_sequence:
            if token in self._added_tokens_decoder:
                byte_buffer += self._added_tokens_decoder[token].encode("utf-8")
            elif token in self.added_tokens_encoder:
                byte_buffer += token.encode("utf-8")
            else:
                byte_buffer += bytes([ord(token)])
        return byte_buffer.decode("utf-8", errors="ignore")

    # No vocabulary files required for byte-level tokenizer
    def export_vocabulary(self, save_path: str, prefix: Optional[str] = None) -> Tuple[str]:
        return ()

# Minimal 3D rotation and transformation library
import torch

def _normalize(v):
    """Normalize vector using safe division"""
    norm = torch.sqrt(torch.sum(v**2, dim=-1, keepdim=True))
    return v / (norm + 1e-8)

def _dot(a, b):
    """Compute dot product along last dimension"""
    return torch.sum(a * b, dim=-1, keepdim=True)

def _cross(a, b):
    """Compute cross product along last dimension"""
    ax, ay, az = torch.unbind(a, dim=-1)
    bx, by, bz = torch.unbind(b, dim=-1)
    return torch.stack([
        ay * bz - az * by,
        az * bx - ax * bz,
        ax * by - ay * bx
    ], dim=-1)

class SimpleTransform:
    """Simplified transformation class using axis-angle representation"""

    def __init__(self, axis=None, angle=None, matrix=None, translation=None):
        if matrix is not None:
            self._matrix = matrix
            self._axis = None
            self._angle = None
        elif axis is not None and angle is not None:
            self._axis = _normalize(axis)
            self._angle = angle
            self._matrix = self._compute_rotation_matrix()
        else:
            self._matrix = torch.eye(3).unsqueeze(0)
            self._axis = torch.zeros(1, 3)
            self._angle = torch.zeros(1)

        self._translation = translation if translation is not None else torch.zeros_like(axis) if axis is not None else torch.zeros(1, 3)

    def _compute_rotation_matrix(self):
        """Compute rotation matrix from axis-angle using Rodrigues' formula"""
        k = self._axis
        theta = self._angle.unsqueeze(-1).unsqueeze(-1)

        kx, ky, kz = torch.unbind(k, dim=-1)
        K = torch.stack([
            torch.stack([0, -kz, ky], dim=-1),
            torch.stack([kz, 0, -kx], dim=-1),
            torch.stack([-ky, kx, 0], dim=-1)
        ], dim=-2)

        K2 = torch.matmul(K, K)
        I = torch.eye(3).to(K.device).unsqueeze(0)

        return I + torch.sin(theta) * K + (1 - torch.cos(theta)) * K2

    @staticmethod
    def identity(shape, dtype=None, device=None):
        """Create identity transformation"""
        batch_shape = shape if isinstance(shape, tuple) else (shape,)
        matrix = torch.eye(3, dtype=dtype, device=device).expand(batch_shape + (-1, -1))
        trans = torch.zeros(batch_shape + (3,), dtype=dtype, device=device)
        return SimpleTransform(matrix=matrix, translation=trans)

    def __matmul__(self, other):
        """Compose transformations"""
        if isinstance(other, SimpleTransform):
            new_matrix = torch.matmul(self._matrix, other._matrix)
            new_trans = torch.matmul(self._matrix, other._translation.unsqueeze(-1)).squeeze(-1) + self._translation
            return SimpleTransform(matrix=new_matrix, translation=new_trans)
        return NotImplemented

    def apply(self, points):
        """Apply transformation to points"""
        rotated = torch.matmul(self._matrix, points.unsqueeze(-1)).squeeze(-1)
        return rotated + self._translation

    def inverse(self):
        """Compute inverse transformation"""
        inv_matrix = self._matrix.transpose(-1, -2)
        inv_trans = -torch.matmul(inv_matrix, self._translation.unsqueeze(-1)).squeeze(-1)
        return SimpleTransform(matrix=inv_matrix, translation=inv_trans)

    @property
    def shape(self):
        return self._translation.shape[:-1]

    def to(self, device=None, dtype=None):
        """Move to different device/dtype"""
        new_matrix = self._matrix.to(device=device, dtype=dtype)
        new_trans = self._translation.to(device=device, dtype=dtype)
        return SimpleTransform(matrix=new_matrix, translation=new_trans)

# Alternative quaternion-based implementation
class QuaternionTransform:
    """Transformation using quaternions for rotation"""

    def __init__(self, quaternion=None, translation=None):
        if quaternion is None:
            quaternion = torch.tensor([1.0, 0.0, 0.0, 0.0])
        if translation is None:
            translation = torch.zeros(3)

        self._quat = quaternion / torch.norm(quaternion)
        self._trans = translation

    def _quat_to_matrix(self):
        """Convert quaternion to rotation matrix"""
        w, x, y, z = torch.unbind(self._quat, dim=-1)

        return torch.stack([
            torch.stack([1 - 2*y*y - 2*z*z, 2*x*y - 2*w*z, 2*x*z + 2*w*y], dim=-1),
            torch.stack([2*x*y + 2*w*z, 1 - 2*x*x - 2*z*z, 2*y*z - 2*w*x], dim=-1),
            torch.stack([2*x*z - 2*w*y, 2*y*z + 2*w*x, 1 - 2*x*x - 2*y*y], dim=-1)
        ], dim=-2)

    def apply(self, points):
        """Apply transformation"""
        R = self._quat_to_matrix()
        return torch.matmul(R, points.unsqueeze(-1)).squeeze(-1) + self._trans

# Custom exception hierarchy for Steam-related errors

class BaseSteamError(Exception):
    """Base class for all Steam-related exceptions."""
    pass

class GeneralSteamError(BaseSteamError):
    """Generic exception for general Steam issues."""
    pass

class PlatformNotSupportedException(BaseSteamError):
    """Raised when the current platform is not supported."""
    pass

class ArchitectureNotSupportedException(BaseSteamError):
    """Raised when the system architecture is not supported."""
    pass

class LibraryMissingException(BaseSteamError):
    """Raised when the required Steamworks library is missing."""
    pass

class NotInitializedException(BaseSteamError):
    """Raised when Steam functionality is used before initialization."""
    pass

class ServiceNotRunningException(BaseSteamError):
    """Raised when the Steam client service is not running."""
    pass

class ConnectionFailureException(BaseSteamError):
    """Raised when connection to Steam fails."""
    pass

class InvalidStatValueException(BaseSteamError):
    """Raised when an invalid value is assigned to a Steam statistic."""
    pass

class ConfigurationNeededException(BaseSteamError):
    """Raised when initial setup or configuration is required."""
    pass

