@dataclasses.dataclass
class GraphChange:
    removed_nodes: Set[str] = dataclasses.field(default_factory=set)
    added_updated_nodes: Set[str] = dataclasses.field(default_factory=set)
    removed_edges: Set[Tuple[str, str]] = dataclasses.field(default_factory=set)
    added_updated_edges: Set[Tuple[str, str]] = dataclasses.field(default_factory=set)


def substitute_placeholders(
    text: str,
    history: Optional[List[Dict]] = None,
    replacements: Optional[Dict[str, Any]] = None
) -> str:
    """Replace placeholders like {key} in text and optionally in system messages."""
    if history is None:
        history = []
    if replacements is None:
        replacements = {}

    def apply_subs(s: str) -> str:
        for k, v in replacements.items():
            s = s.replace(f"{{{k}}}", str(v))
        return s

    result = apply_subs(text)

    for entry in history:
        if entry.get("role") == "system":
            entry["content"] = apply_subs(entry.get("content") or "")

    return result


def sanitize_string(value: Any) -> str:
    """Sanitize input: strip whitespace, unescape HTML, remove control chars."""
    if not isinstance(value, str):
        return value

    cleaned = html.unescape(value.strip())
    # Remove control characters and quotes
    return re.sub(r'["\x00-\x1f\x7f-\x9f]', "", cleaned)


def validate_dict_structure(data: dict, expected: List[Tuple[str, type]]) -> bool:
    """Check if dictionary contains required fields with correct types."""
    for field, typ in expected:
        if field not in data:
            return False
        if not isinstance(data[field], typ):
            return False
    return True


def _generate_hash(*parts: Any) -> str:
    hasher = xxhash.xxh64()
    for part in parts:
        hasher.update(str(part).encode("utf-8"))
    return hasher.hexdigest()


def retrieve_llm_cache(llm_name: str, prompt: str, history: list, gen_conf: dict) -> Optional[bytes]:
    key = _generate_hash(llm_name, prompt, history, gen_conf)
    return redis_client.get(key)


def store_llm_cache(llm_name: str, prompt: str, value: bytes, history: list, gen_conf: dict) -> None:
    key = _generate_hash(llm_name, prompt, history, gen_conf)
    redis_client.set(key, value, ex=24 * 3600)


def fetch_embedding_cache(model_name: str, text: str) -> Optional[np.ndarray]:
    key = _generate_hash(model_name, text)
    raw = redis_client.get(key)
    if raw is None:
        return None
    return np.array(json.loads(raw.decode()))


def cache_embedding(model_name: str, text: str, arr: np.ndarray) -> None:
    key = _generate_hash(model_name, text)
    serialized = json.dumps(arr.tolist() if isinstance(arr, np.ndarray) else arr)
    redis_client.set(key, serialized.encode(), ex=24 * 3600)


def get_cached_tags(kb_ids: Any) -> Optional[bytes]:
    key = _generate_hash(kb_ids)
    return redis_client.get(key)


def set_cached_tags(kb_ids: Any, tags: Any) -> None:
    key = _generate_hash(kb_ids)
    redis_client.set(key, json.dumps(tags).encode(), ex=600)


def normalize_graph(graph: nx.Graph, notify_callback=None, enforce_attrs=True):
    """Ensure graph nodes/edges have essential attributes; purge invalid ones."""

    def has_required(node_data: dict) -> bool:
        return all(attr in node_data for attr in ("description", "source_id"))

    if enforce_attrs:
        invalid_nodes = [n for n, d in graph.nodes(data=True) if not has_required(d)]
        for node in invalid_nodes:
            graph.remove_node(node)
        if invalid_nodes and notify_callback:
            notify_callback(msg=f"Purged {len(invalid_nodes)} nodes due to missing attributes.")

    invalid_edges = []
    for src, tgt, attrs in graph.edges(data=True):
        if enforce_attrs and not has_required(attrs):
            invalid_edges.append((src, tgt))
        attrs.setdefault("keywords", [])

    for src, tgt in invalid_edges:
        graph.remove_edge(src, tgt)

    if invalid_edges and notify_callback:
        notify_callback(msg=f"Purged {len(invalid_edges)} edges due to missing attributes.")

    # Compute degree rank
    for node, deg in graph.degree:
        graph.nodes[str(node)]["rank"] = int(deg)

    # Ensure graph-level source_id
    if "source_id" not in graph.graph:
        graph.graph["source_id"] = []
    graph.graph["source_id"].extend(graph.graph.get("source_id", []))


def canonical_edge(u: str, v: str) -> Tuple[str, str]:
    return (u, v) if u < v else (v, u)


def combine_graphs(g1: nx.Graph, g2: nx.Graph, delta: GraphChange):
    """Merge g2 into g1 in-place, updating delta accordingly."""
    for node_name, attr in g2.nodes(data=True):
        delta.added_updated_nodes.add(node_name)
        if not g1.has_node(node_name):
            g1.add_node(node_name, **attr)
            continue
        existing = g1.nodes[node_name]
        existing["description"] += GRAPH_FIELD_SEP + attr["description"]
        existing["source_id"] += attr["source_id"]

    for src, tgt, attr in g2.edges(data=True):
        edge_key = canonical_edge(src, tgt)
        delta.added_updated_edges.add(edge_key)
        edge_data = g1.get_edge_data(src, tgt)
        if edge_data is None:
            g1.add_edge(src, tgt, **attr)
            continue
        edge_data["weight"] += attr.get("weight", 0)
        edge_data["description"] += GRAPH_FIELD_SEP + attr["description"]
        edge_data["keywords"] += attr["keywords"]
        edge_data["source_id"] += attr["source_id"]

    # Recompute ranks after merge
    for node, deg in g1.degree:
        g1.nodes[str(node)]["rank"] = int(deg)

    # Merge graph-level source_id
    g1.graph.setdefault("source_id", [])
    g1.graph["source_id"].extend(g2.graph.get("source_id", []))


def compute_signature(*args) -> str:
    return md5(str(args).encode()).hexdigest()


def extract_entity(record: List[str], chunk_key: str) -> Optional[Dict]:
    if len(record) < 4 or record[0] != '"entity"':
        return None

    name = sanitize_string(record[1]).upper()
    if not name.strip():
        return None

    entity_type = sanitize_string(record[2]).upper()
    description = sanitize_string(record[3])
    return {
        "entity_name": name,
        "entity_type": entity_type,
        "description": description,
        "source_id": chunk_key,
    }


def extract_relationship(record: List[str], chunk_key: str) -> Optional[Dict]:
    if len(record) < 5 or record[0] != '"relationship"':
        return None

    src = sanitize_string(record[1]).upper()
    tgt = sanitize_string(record[2]).upper()
    desc = sanitize_string(record[3])
    keywords = sanitize_string(record[4])
    weight_str = record[-1]
    weight = float(weight_str) if re.match(r'^[-+]?\d*\.?\d+$', weight_str) else 1.0

    pair = sorted([src, tgt])
    return {
        "src_id": pair[0],
        "tgt_id": pair[1],
        "weight": weight,
        "description": desc,
        "keywords": keywords,
        "source_id": chunk_key,
        "metadata": {"created_at": time.time()},
    }


def build_chat_history(*messages: str) -> List[Dict]:
    roles = ["user", "assistant"]
    return [{"role": roles[i % 2], "content": msg} for i, msg in enumerate(messages)]


def split_text_by_delimiters(content: str, delimiters: List[str]) -> List[str]:
    if not delimiters:
        return [content]
    pattern = "|".join(re.escape(d) for d in delimiters)
    parts = re.split(pattern, content)
    return [p.strip() for p in parts if p.strip()]


def parse_float(value: str) -> bool:
    return bool(re.match(r"^[-+]?\d*\.?\d+$", value))


def generate_chunk_id(chunk: Dict) -> str:
    content = chunk["page_content"] + chunk["kb_id"]
    return xxhash.xxh64(content.encode("utf-8")).hexdigest()


async def create_entity_chunk(
    kb_id: str,
    embd_model,
    entity_name: str,
    meta: Dict,
    output_chunks: List[Dict]
):
    global chat_limiter
    enable_timeout_assertion = os.environ.get("ENABLE_TIMEOUT_ASSERTION")

    chunk = {
        "id": get_uuid(),
        "important_kwd": [entity_name],
        "title_tks": rag_tokenizer.tokenize(entity_name),
