async def load_graph(workspace_id: str, kb_id: str, exclude_rebuild=None) -> Optional[nx.Graph]:
    conds = {"fields": ["page_content", "removed_kwd", "source_id"], "size": 1, "knowledge_graph_kwd": ["graph"]}
    res = await trio.to_thread.run_sync(settings.retriever.search, conds, search.index_name(workspace_id), [kb_id])

    if res.total > 0:
        for id in res.ids:
            try:
                if res.field[id]["removed_kwd"] == "N":
                    g = json_graph.node_link_graph(json.loads(res.field[id]["page_content"]), edges="edges")
                    if "source_id" not in g.graph:
                        g.graph["source_id"] = res.field[id]["source_id"]
                else:
                    g = await rebuild_graph(workspace_id, kb_id, exclude_rebuild)
                return g
            except Exception:
                continue
    return None


async def persist_graph(
    workspace_id: str,
    kb_id: str,
    embd_model,
    graph: nx.Graph,
    change: GraphChange,
    callback=None
):
    global chat_limiter
    start_time = trio.current_time()

    # Clean up old entries
    await trio.to_thread.run_sync(settings.docStoreConn.delete, {"knowledge_graph_kwd": ["graph", "subgraph"]}, search.index_name(workspace_id), kb_id)

    if change.removed_nodes:
        await trio.to_thread.run_sync(
            settings.docStoreConn.delete,
            {"knowledge_graph_kwd": ["entity"], "entity_kwd": sorted(change.removed_nodes)},
            search.index_name(workspace_id), kb_id
        )

    if change.removed_edges:

        async def delete_edge_pair(frm, to):
            async with chat_limiter:
                await trio.to_thread.run_sync(
                    settings.docStoreConn.delete,
                    {"knowledge_graph_kwd": ["relation"], "from_entity_kwd": frm, "to_entity_kwd": to},
                    search.index_name(workspace_id), kb_id
                )

        async with trio.open_nursery() as nursery:
            for src, tgt in change.removed_edges:
                nursery.start_soon(delete_edge_pair, src, tgt)

    now = trio.current_time()
    if callback:
        callback(msg=f"Removed {len(change.removed_nodes)} nodes and {len(change.removed_edges)} edges in {now - start_time:.2f}s.")

    # Prepare chunks
    chunks = [{
        "id": get_uuid(),
        "page_content": json.dumps(nx.node_link_data(graph, edges="edges"), ensure_ascii=False),
        "knowledge_graph_kwd": "graph",
        "kb_id": kb_id,
        "source_id": graph.graph.get("source_id", []),
        "available_int": 0,
        "removed_kwd": "N",
    }]

    # Subgraphs per source document
    for source in graph.graph["source_id"]:
        sub_nodes = [n for n in graph.nodes if source in graph.nodes[n]["source_id"]]
        subgraph = graph.subgraph(sub_nodes).copy()
        for n in subgraph.nodes:
            subgraph.nodes[n]["source_id"] = [source]
        subgraph.graph["source_id"] = [source]
        chunks.append({
            "id": get_uuid(),
            "page_content": json.dumps(nx.node_link_data(subgraph, edges="edges"), ensure_ascii=False),
            "knowledge_graph_kwd": "subgraph",
            "kb_id": kb_id,
            "source_id": [source],
            "available_int": 0,
            "removed_kwd": "N",
        })

    # Embed new/updated nodes
    async with trio.open_nursery() as nursery:
        for idx, node in enumerate(change.added_updated_nodes):
            nursery.start_soon(create_entity_chunk, kb_id, embd_model, node, graph.nodes[node], chunks)
            if idx % 100 == 99 and callback:
                callback(msg=f"Node embeddings: {idx + 1}/{len(change.added_updated_nodes)}")

    # Embed new/updated edges
    async with trio.open_nursery() as nursery:
        for idx, (src, tgt) in enumerate(change.added_updated_edges):
            edge_data = graph.get_edge_data(src, tgt)
            if not edge_data:
                continue
            nursery.start_soon(create_relation_chunk, kb_id, embd_model, src, tgt, edge_data, chunks)
            if idx % 100 == 99 and callback:
                callback(msg=f"Edge embeddings: {idx + 1}/{len(change.added_updated_edges)}")

    now = trio.current_time()
    if callback:
        callback(msg=f"Converted graph changes into {len(chunks)} chunks in {now - start_time:.2f}s.")

    # Bulk insert
    enable_timeout_assertion = os.environ.get("ENABLE_TIMEOUT_ASSERTION")
    es_bulk_size = 4
    for i in range(0, len(chunks), es_bulk_size):
        with trio.fail_after(3 if enable_timeout_assertion else 30000000):
            err = await trio.to_thread.run_sync(lambda: settings.docStoreConn.insert(chunks[i:i + es_bulk_size], search.index_name(workspace_id), kb_id))
        if i % 100 == es_bulk_size - 1 and callback:
            callback(msg=f"Inserted {i}/{len(chunks)} chunks")
        if err:
            raise Exception(f"Insert error: {err}")

    now = trio.current_time()
    if callback:
        callback(msg=f"Indexed {len(change.added_updated_nodes)} nodes and {len(change.added_updated_edges)} edges in {now - start_time:.2f}s.")


def contains_subsequence(subseq: tuple, seq: tuple) -> bool:
    def locate_all(tup, val):
        indices = []
        pos = 0
        while True:
            try:
                idx = tup.index(val, pos)
                indices.append(idx)
                pos = idx + 1
            except ValueError:
                break
        return indices

    starts = locate_all(seq, subseq[0])
    for start in starts:
        if start + len(subseq) <= len(seq) and seq[start + len(subseq) - 1] == subseq[-1]:
            return True
    return False


def join_sequences(list_a: List[tuple], list_b: List[tuple]) -> List[tuple]:
    result = []
    for t in list_a:
        last = t[-1]
        if last in t[:-1]:
            result.append(t)
            continue

        matches = [m for m in list_b if m[0] == last]
        matched_flag = False
        for match in matches:
            rev_match = (match[1], match[0])
            if contains_subsequence(match, t) or contains_subsequence(rev_match, t):
                continue
            matched_flag = True
            merged = t + match[1:]
            result.append(merged)
        if not matched_flag:
            result.append(t)
    return result


async def collect_entity_types(idx_name: str, kb_ids: List[str]) -> Dict[str, List[str]]:
    es_res = await trio.to_thread.run_sync(
        lambda: settings.retriever.search(
            {"knowledge_graph_kwd": "ty2ents", "kb_id": kb_ids, "size": 10000, "fields": ["page_content"]},
            idx_name, kb_ids
        )
    )
    mapping = defaultdict(list)
    for id in es_res.ids:
        raw = es_res.field[id].get("page_content")
        if not raw:
            continue
        try:
            obj = json.loads(raw)
        except Exception as e:
            logging.exception(e)
            continue
        for ty, ents in obj.items():
            mapping[ty].extend(ents)
    return mapping


def flatten_unique(arr: List[Dict], key: str) -> List[Any]:
    items = []
    for item in arr:
        val = item[key]
        if isinstance(val, list):
            items.extend(val)
        else:
            items.append(val)
    return list(set(items))


async def reconstruct_graph(workspace_id: str, kb_id: str, exclude_rebuild=None) -> Optional[nx.Graph]:
    graph = nx.Graph()
    fields = ["knowledge_graph_kwd", "page_content", "source_id"]
    batch_size = 256

    for offset in range(0, 1024 * batch_size, batch_size):
        res = await trio.to_thread.run_sync(
            lambda: settings.docStoreConn.search(
                fields, [], {"kb_id": kb_id, "knowledge_graph_kwd": ["subgraph"]},
                [], OrderByExpr(), offset, batch_size, search.index_name(workspace_id), [kb_id]
            )
        )
        res_data = settings.docStoreConn.getFields(res, fields)
        if not res_data:
            break

        for cid, data in res_data.items():
            if data["knowledge_graph_kwd"] != "subgraph":
                continue
            if isinstance(exclude_rebuild, list):
                if any(src in data["source_id"] for src in exclude_rebuild):
                    continue
            elif exclude_rebuild in data["source_id"]:
                continue

            next_g = json_graph.node_link_graph(json.loads(data["page_content"]), edges="edges")
            merged = nx.compose(graph, next_g)

            # Update source_id for overlapping nodes
            common_nodes = graph.nodes & next_g.nodes
            for n in common_nodes:
                merged.nodes[n]["source_id"] = graph.nodes[n]["source_id"] + next_g.nodes[n]["source_id"]

            # Merge graph-level source_id
            if "source_id" in graph.graph:
                merged.graph["source_id"] = graph.graph["source_id"] + next_g.graph["source_id"]
            else:
                merged.graph["source_id"] = next_g.graph["source_id"]

            graph = merged

    if len(graph.nodes) == 0:
        return None

    graph.graph["source_id"] = sorted(graph.graph["source_id"])
    return graph


def is_task_cancelled(task_id: str) -> bool:
    try:
        return bool(redis_client.get(f"{task_id}-cancel"))
    except Exception as e:
        logging.exception(e)
    return False

