from playwright.async_api import async_playwright

async def fetch_douyin_videos(search_term: str, max_iterations: int = 10):
    """Fetch Douyin search results by simulating user scrolling behavior."""
    collected_items = []

    async with async_playwright() as pw:
        # Connect to existing Chrome instance via DevTools protocol
        browser = await pw.chromium.connect_over_cdp("http://localhost:9222")
        main_context = browser.contexts[0]
        active_page = await main_context.new_page()

        target_url = f"https://www.douyin.com/search/{search_term}?type=video"
        print(f"Loading page: {target_url}")

        # Navigate and wait for initial content
        await active_page.goto(target_url, wait_until="domcontentloaded", timeout=30000)
        await asyncio.sleep(3)

        # Perform multiple scroll-down actions to load more content
        for iteration in range(max_iterations):
            # Extract video elements using multiple fallback selectors
            video_data = await active_page.evaluate("""() => {
                const data = [];

                // List of potential CSS selectors for video items
                const candidate_selectors = [
                    '[class*="search-result"] li',
                    '[class*="video-list"] li', 
                    '[data-e2e="scroll-list"] > div',
                    'ul[class*="list"] > li',
                    '[class*="search"] [class*="card"]',
                    '[class*="result"] [class*="item"]'
                ];

                let best_match_elements = [];

                // Find the selector that returns the most elements
                for (const selector of candidate_selectors) {
                    const found = document.querySelectorAll(selector);
                    if (found.length > best_match_elements.length) {
                        best_match_elements = found;
                    }
                }

                // If no structured elements found, fall back to finding video links directly
                if (best_match_elements.length === 0) {
                    const all_links = document.querySelectorAll('a[href*="/video/"]');
                    all_links.forEach(link => {
                        const text_content = link.textContent?.trim()?.substring(0, 200) || '';
                        const href = link.href || '';

                        if (text_content && href) {
                            data.push({
                                title: text_content,
                                url: href,
                                author: [redacted]
                                likes: '',
                                origin: 'direct_link'
                            });
                        }
                    });
                    return data;
                }

                // Process each matched element
                best_match_elements.forEach(element => {
                    const title_node = element.querySelector('a, [class*="title"], h2, h3, p');
                    const author_node = element.querySelector('[class*="author"], [class*="name"], [class*="user"]');
                    const like_node = element.querySelector('[class*="like"], [class*="count"]');
                    const link_node = element.querySelector('a[href*="/video/"]') || element.querySelector('a');

                    const title = title_node?.textContent?.trim()?.substring(0, 200) || '';
                    const author = author_node?.textContent?.trim() || '';
                    const likes = like_node?.textContent?.trim() || '';
                    const url = link_node?.href || '';

                    if (title || url) {
                        data.push({ 
                            title: title, 
                            author: [redacted]
                            likes: likes, 
                            url: url, 
                            origin: 'structured_card' 
                        });
                    }
                });

                return data;
            }""")

            # Deduplicate based on URL before adding to results
            for item in video_data:
                if item.get("url") and not any(existing["url"] == item["url"] for existing in collected_items):
                    collected_items.append(item)

            print(f"Iteration {iteration+1}/{max_iterations}: detected {len(video_data)} cards, total unique: {len(collected_items)}")

            # Scroll down if not at last iteration
            if iteration < max_iterations - 1:
                await active_page.evaluate("window.scrollBy(0, window.innerHeight * 2)")
                await asyncio.sleep(2)

        # Cleanup resources
        await active_page.close()
        await browser.close()

    return collected_items

def execute():
    parser = argparse.ArgumentParser(description="Douyin Video Search Scraper")
    parser.add_argument("--keyword", required=True, help="Search term to query on Douyin")
    parser.add_argument("--output", default="./data/dy_results.json", help="Path to save JSON output")
    parser.add_argument("--iterations", type=int, default=10, help="Number of scroll iterations")

    arguments = parser.parse_args()

    # Run the scraping function
    videos = asyncio.run(fetch_douyin_videos(arguments.keyword, arguments.iterations))

    # Prepare output directory if needed
    output_file = Path(arguments.output)
    output_file.parent.mkdir(parents=True, exist_ok=True)

    # Build final output structure
    final_output = {
        "query": arguments.keyword,
        "timestamp": datetime.now().isoformat(),
        "total_count": len(videos),
        "items": videos
    }

    # Save results to file
    output_file.write_text(json.dumps(final_output, ensure_ascii=False, indent=2), encoding="utf-8")
    print(f"\nSuccessfully saved {len(videos)} items to {output_file}")

if __name__ == "__main__":
    execute()

