import cosmos_rl.utils.util as util


class MathProblemDataset(Dataset):
    """Alternative implementation of dataset loading for math problems."""

    def configure(self, cfg: CosmosConfig, *args, **kwargs):
        """
        Initialize tokenizer and dataset; called by launcher after mounting.
        """
        self.cfg = cfg
        self.tokenizer = util.setup_tokenizer(cfg.policy.model_name_or_path)
        self.use_chat_template = not cfg.rollout.multi_turn_config.enable

        ms_dataset = modelscope_load_dataset(
            cfg.train.train_policy.dataset.name, subset_name="main", split="train"
        )
        if ms_dataset is None:
            self.data = load_dataset("openai/gsm8k", "main", split="train")
        else:
            self.data = ms_dataset

    def __len__(self):
        return len(self.data)

    def __getitem__(self, index: int) -> RLPayload:
        assert hasattr(self, "tokenizer"), "Tokenizer must be initialized before access."

        query = self.data[index]["question"]
        assert isinstance(query, str), f"Expected string question, got {type(query)}"

        conv = [
            {
                "role": "user",
                "content": f'{query} Please reason step-by-step and end with "#### <answer>".',
            }
        ]

        if not self.use_chat_template:
            return RLPayload(conversation=conv)

        prompt_text = self.tokenizer.apply_chat_template(
            conv, tokenize=False, add_generation_prompt=True
        )
        return RLPayload(prompt=prompt_text)

    def get_gold_label(self, index: int) -> Any:
        """Required for GRPO reward computation."""
        return self.data[index]["answer"]


class ValidationMathDataset(MathProblemDataset):
    """Validation set wrapper for GSM8K-style evaluation."""

    def configure(self, cfg: CosmosConfig, *args, **kwargs):
        if not cfg.validation.enable:
            logger.warning("Validation disabled — skipping setup.")
            return

        self.use_chat_template = not cfg.rollout.multi_turn_config.enable
        self.cfg = cfg
        self.tokenizer = util.setup_tokenizer(cfg.policy.model_name_or_path)

        raw_ds = load_dataset(cfg.validation.dataset.name, cfg.validation.dataset.subset)

        if cfg.validation.dataset.split:
            if isinstance(cfg.validation.dataset.split, list):
                splits = [raw_ds[split] for split in cfg.validation.dataset.split]
                self.data = ConcatDataset(splits)
            else:
                assert isinstance(cfg.validation.dataset.split, str)
                self.data = raw_ds[cfg.validation.dataset.split]


def custom_scoring_function(
    candidate: str, reference: Optional[Any] = None, *_, **__
) -> float:
    assert isinstance(reference, str), "Reference must be a string."
    base_score = gsm8k_reward_fn(candidate, reference)
    # Additional scoring logic can be inserted here
    return base_score


class MathRewardTool(BaseTool):
    def __init__(self):
        name = "compute_math_reward"
        schema_dict = {
            "type": "function",
            "function": {
                "name": name,
                "description": "Evaluates model output against ground truth for math correctness.",
                "parameters": {
                    "type": "object",
                    "properties": {
                        "response": {
                            "type": "string",
                            "description": "Model's final answer (digits only).",
                        }
                    },
                    "required": ["response"],
                },
            },
        }
        super().__init__(name, OpenAIFunctionToolSchema.model_validate(schema_dict))

    @contextmanager
    def execution_context(self, correct_answer: str):
        self._correct = correct_answer
        yield
        self._correct = None

    def _parse_final_number(self, text: str, mode: str = "loose") -> Optional[str]:
        assert mode in ("strict", "loose")
        if mode == "strict":
            match = re.search(r"####\s*([0-9][0-9.,]*)", text)
            if not match:
                return None
            val = match.group(1).replace(",", "").replace("$", "")
            return val.strip()
        elif mode == "loose":
            numbers = re.findall(r"-?\d+\.?\d*", text)
            for num in reversed(numbers):
                if num not in {"", "."}:
                    return num
            return None

    def execute(self, response: str) -> ToolResponse:
        parsed = self._parse_final_number(response, mode="loose")
        truth = self._parse_final_number(self._correct, mode="loose") or ""
        try:
            score = 1.0 if parsed == truth else 0.0
        except Exception:
            score = 0.0
        return ToolResponse(text=f"Parsed truth={truth}, reward={score}")


def custom_logging_callback(metrics: dict, step: int) -> None:
    """
    Custom logging hook — receives training metrics and current step.
    This stub does nothing but could log to file, wandb, etc.
    """
    pass


class MathDataProcessor(DataPacker):
    """Wrapper around default packer to support multi-turn tool use."""

    def __init__(self, agent: Optional[ToolAgent] = None, *args, **kwargs):
        super().__init__(agent=agent, *args, **kwargs)
        self.base_packer = DecoderOnlyLLMDataPacker(tool_agent=agent)

    def configure(
        self,
        cfg: CosmosConfig,
        *args,
        tool_agent: Optional[ToolAgent] = None,
        **kwargs,
    ):
        super().configure(cfg, *args, tool_agent=tool_agent, **kwargs)
        self.base_packer.configure(cfg, *args, tool_agent=tool_agent, **kwargs)

    def prepare_rollout_input(self, sample: Any) -> Any:
        return self.base_packer.prepare_rollout_input(sample)

    def batch_rollout_inputs(self, samples: List[Any]) -> Any:
        return self.base_packer.batch_rollout_inputs(samples)

    def prepare_policy_input(
        self,
        item: Any,
        rollout_result: Union[str, List[int]],
        skip_tokens: int = 0,
    ) -> Any:
        return self.base_packer.prepare_policy_input(item, rollout_result, skip_tokens)

    def estimate_max_sequence_length(self, processed: List[Any]) -> int:
        return self.base_packer.estimate_max_sequence_length(processed)

    def collate_policy_batch(
        self, processed_samples: List[Any], max_len: int
    ) -> Dict[str, Any]:
        return self.base_packer.collate_policy_batch(processed_samples, max_len)

    def append_turn(
        self,
        history: ConversationType,
        outputs: List[str],
        ground_truth: Optional[str] = None,
    ) -> ConversationType:
        assert self.tool_agent is not None, "Tool agent required for tool use."
        actual_output = next((r for r in outputs if r), "")
        if not actual_output:
            return history

        # Append assistant message
        history = add_assistant_message(history, actual_output)

        # Trigger tools if needed
        tool_calls = self.tool_agent.invoke(actual_output, ground_truth)
        if tool_calls:
            for resp in tool_calls:
                history = add_tool_response_messages(history, resp.text)
        return history


if __name__ == "__main__":
    def build_training_dataset(config: CosmosConfig) -> Dataset:
        return MathProblemDataset()

    def build_validation_dataset(config: CosmosConfig) -> Dataset:
        return ValidationMathDataset()

    # Setup tool agent for multi-turn interaction
    tool_agent = ToolAgent(HermesToolParser(), [MathRewardTool()])

    # Launch worker with custom components
    launch_worker(
        dataset=build_training_dataset,
        val_dataset=build_validation_dataset,
        reward_fns=[custom_scoring_function],
        data_packer=MathDataProcessor(tool_agent=tool_agent),
        val_data_packer=MathDataProcessor(tool_agent=tool_agent),
        custom_logger_fns=[custom_logging_callback],
    )

import unittest
from noether.core.schedules import ScheduleBase, SequentialStepSchedule, SequentialStepScheduleConfig

class DummySchedule(ScheduleBase):
    def __init__(self, step_to_value=None, **kwargs):
        super().__init__(**kwargs)
        self.step_to_value = step_to_value

    def _get_value(self, step: int, total_steps: int) -> float:
        if self.step_to_value is None:
            return 0.0
        return self.step_to_value.get(step, 0.0)

class TestSequentialStepSchedule(unittest.TestCase):
    def test_propagate_singleconfig(self):
        sched = SequentialStepSchedule(
            [
                SequentialStepScheduleConfig(schedule=DummySchedule()),
            ]
        )
        self.assertEqual(0, sched.schedule_configs[0].start_step)
        self.assertIsNone(sched.schedule_configs[0].end_step)

    def test_propagate_forward(self):
        sched = SequentialStepSchedule(
            [
                SequentialStepScheduleConfig(end_step=10, schedule=DummySchedule()),
                SequentialStepScheduleConfig(schedule=DummySchedule()),
            ]
        )
        self.assertEqual(0, sched.schedule_configs[0].start_step)
        self.assertEqual(10, sched.schedule_configs[0].end_step)
        self.assertEqual(10, sched.schedule_configs[1].start_step)
        self.assertIsNone(sched.schedule_configs[1].end_step)

    def test_propagate_backward(self):
        sched = SequentialStepSchedule(
            [
                SequentialStepScheduleConfig(schedule=DummySchedule()),
                SequentialStepScheduleConfig(start_step=10, schedule=DummySchedule()),
            ]
        )
        self.assertEqual(0, sched.schedule_configs[0].start_step)
        self.assertEqual(10, sched.schedule_configs[0].end_step)
        self.assertEqual(10, sched.schedule_configs[1].start_step)
        self.assertIsNone(sched.schedule_configs[1].end_step)

    def test_propagate_gap(self):
        sched = SequentialStepSchedule(
            [
                SequentialStepScheduleConfig(end_step=10, schedule=DummySchedule()),
                SequentialStepScheduleConfig(start_step=15, schedule=DummySchedule()),
            ]
        )
        self.assertEqual(0, sched.schedule_configs[0].start_step)
        self.assertEqual(10, sched.schedule_configs[0].end_step)
        self.assertEqual(15, sched.schedule_configs[1].start_step)
        self.assertIsNone(sched.schedule_configs[1].end_step)

    def test_propagate_middle(self):
        sched = SequentialStepSchedule(
            [
                SequentialStepScheduleConfig(end_step=10, schedule=DummySchedule()),
                SequentialStepScheduleConfig(schedule=DummySchedule()),
                SequentialStepScheduleConfig(start_step=15, schedule=DummySchedule()),
            ]
        )
        self.assertEqual(0, sched.schedule_configs[0].start_step)
        self.assertEqual(10, sched.schedule_configs[0].end_step)
        self.assertEqual(10, sched.schedule_configs[1].start_step)
        self.assertEqual(15, sched.schedule_configs[1].end_step)
        self.assertEqual(15, sched.schedule_configs[2].start_step)
        self.assertIsNone(sched.schedule_configs[2].end_step)

    def test_propagate_noneinbetween(self):
        with self.assertRaises(ValueError):
            SequentialStepSchedule(
                [
                    SequentialStepScheduleConfig(end_step=10, schedule=DummySchedule()),
                    SequentialStepScheduleConfig(schedule=DummySchedule()),
                    SequentialStepScheduleConfig(schedule=DummySchedule()),
                ]
            )

    def test_check_singleconfig(self):
        with self.assertRaises(ValueError):
            SequentialStepSchedule(
                [
                    SequentialStepScheduleConfig(start_step=5, end_step=3, schedule=DummySchedule()),
                ]
            )

    def test_check_propagatedendstep(self):
        with self.assertRaises(ValueError):
            SequentialStepSchedule(
                [
                    SequentialStepScheduleConfig(end_step=10, schedule=DummySchedule()),
                    SequentialStepScheduleConfig(start_step=5, schedule=DummySchedule()),
                ]
            )

    def test_get_sequential_schedule_config_zeroduration(self):
        sched = SequentialStepSchedule(
            [
                SequentialStepScheduleConfig(end_step=0, schedule=DummySchedule()),
                SequentialStepScheduleConfig(schedule=DummySchedule()),
            ]
        )
        self.assertEqual(sched.schedule_configs[1], sched.get_sequential_schedule_config(0))

    def test_get_sequential_schedule_config(self):
        sched = SequentialStepSchedule(
            [
                SequentialStepScheduleConfig(start_step=5, end_step=10, schedule=DummySchedule()),
                SequentialStepScheduleConfig(end_step=15, schedule=DummySchedule()),
                SequentialStepScheduleConfig(schedule=DummySchedule()),
            ]
        )
        for i in range(5):
            self.assertIsNone(sched.get_sequential_schedule_config(i))
        for i in range(5, 10):
            self.assertEqual(sched.schedule_configs[0], sched.get_sequential_schedule_config(i))
        for i in range(10, 15):
            self.assertEqual(sched.schedule_configs[1], sched.get_sequential_schedule_config(i))
        for i in range(15, 30):
            self.assertEqual(sched.schedule_configs[2], sched.get_sequential_schedule_config(i))

    def test_get_sequential_schedule_config_gap(self):
        sched = SequentialStepSchedule(
            [
                SequentialStepScheduleConfig(start_step=5, end_step=10, schedule=DummySchedule()),
                SequentialStepScheduleConfig(start_step=15, end_step=20, schedule=DummySchedule()),
                SequentialStepScheduleConfig(schedule=DummySchedule()),
            ]
        )
        for i in range(5):
            self.assertIsNone(sched.get_sequential_schedule_config(i))
        for i in range(5, 10):
            self.assertEqual(sched.schedule_configs[0], sched.get_sequential_schedule_config(i))
        # gap returns previous schedule
        for i in range(10, 15):
            self.assertEqual(sched.schedule_configs[0], sched.get_sequential_schedule_config(i))
        for i in range(15, 20):
            self.assertEqual(sched.schedule_configs[1], sched.get_sequential_schedule_config(i))
        for i in range(20, 30):
            self.assertEqual(sched.schedule_configs[2], sched.get_sequential_schedule_config(i))

    def test_get_value_before_first_schedule(self):
        sched = SequentialStepSchedule(
            [
                SequentialStepScheduleConfig(start_step=5, schedule=DummySchedule(step_to_value={0: 0.5})),
            ]
        )
        for i in range(5):
            self.assertEqual(0.5, sched.get_value(i, 10))

    def test_get_value_after_last_schedule(self):
        sched = SequentialStepSchedule(
            [
                SequentialStepScheduleConfig(
                    start_step=3,
                    end_step=5,
                    schedule=DummySchedule(step_to_value={0: 0.1, 1: 0.2}),
                ),
            ]
        )
        for i in range(4):
            self.assertEqual(0.1, sched.get_value(i, 11))
        self.assertEqual(0.2, sched.get_value(4, 11))
        for i in range(5, 11):
            self.assertEqual(0.2, sched.get_value(i, 11))

    def test_tostring(self):
        sched = SequentialStepSchedule(
            [
                SequentialStepScheduleConfig(
                    start_step=3,
                    end_step=5,
                    schedule=DummySchedule(step_to_value={0: 0.1, 1: 0.2}),
                ),
            ]
        )
        lines = str(sched).split("\n")
        self.assertEqual(3, len(lines))
        self.assertEqual(SequentialStepSchedule.__name__, lines[0])
        self.assertEqual("  (0): 3 - 5 DummySchedule", lines[1])
        self.assertEqual(")", lines[2])

# Market Watchlist Manager - Type III Clone
# This version restructures the logic for managing stock watchlists while preserving core functionality

import argparse
import json
import os
import subprocess
import sys
from typing import List, Dict, Any

CACHE_DIR = os.path.join(".cache", "market-tracker")
WATCHLIST_FILE = os.path.join(CACHE_DIR, "watchlist.json")


def ensure_cache_directory() -> None:
    """Create cache directory if it doesn't exist"""
    os.makedirs(CACHE_DIR, exist_ok=True)


def get_watchlist_data() -> List[str]:
    """Load and deduplicate watchlist items, maintaining original order"""
    ensure_cache_directory()

    if not os.path.exists(WATCHLIST_FILE):
        return []

    try:
        with open(WATCHLIST_FILE, "r", encoding="utf-8") as file:
            data = json.load(file)

        raw_items = data.get("items", [])
        unique_items = []
        seen_symbols = set()

        for item in raw_items:
            symbol = str(item).strip()
            if symbol and symbol not in seen_symbols:
                unique_items.append(symbol)
                seen_symbols.add(symbol)

        return unique_items
    except (json.JSONDecodeError, IOError):
        return []


def update_watchlist(items: List[str]) -> None:
    """Save current watchlist to file"""
    ensure_cache_directory()

    with open(WATCHLIST_FILE, "w", encoding="utf-8") as file:
        json.dump({"items": items}, file, ensure_ascii=False, indent=2)


def execute_add_operation(symbols: List[str]) -> None:
    """Add new symbols to watchlist, avoiding duplicates"""
    current_list = get_watchlist_data()

    for symbol in symbols:
        clean_symbol = symbol.strip()
        if clean_symbol and clean_symbol not in current_list:
            current_list.append(clean_symbol)

    update_watchlist(current_list)
    response = {"ok": True, "items": current_list}
    print(json.dumps(response, indent=2))


def execute_remove_operation(symbols: List[str]) -> None:
    """Remove specified symbols from watchlist"""
    current_list = get_watchlist_data()

    removal_set = {s.strip() for s in symbols if s.strip()}
    filtered_list = [item for item in current_list if item not in removal_set]

    update_watchlist(filtered_list)
    response = {"ok": True, "items": filtered_list}
    print(json.dumps(response, indent=2))


def display_watchlist() -> None:
    """Output current watchlist in JSON format"""
    current_list = get_watchlist_data()
    response = {"items": current_list}
    print(json.dumps(response, indent=2))


def generate_summary_report() -> None:
    """Generate summary report for all watchlist items"""
    current_list = get_watchlist_data()

    if not current_list:
        response = {"items": [], "summary": []}
        print(json.dumps(response, indent=2))
        return

    quote_script_path = os.path.join(os.path.dirname(__file__), "market_quote.py")
    summary_results = []

    for symbol in current_list:
        try:
            process = subprocess.run(
                [sys.executable, quote_script_path, symbol],
                capture_output=True,
                text=True,
                timeout=30
            )

            if process.returncode != 0:
                error_msg = process.stderr.strip() or process.stdout.strip() or "Unknown error"
                summary_results.append({
                    "symbol": symbol,
                    "error": error_msg
                })
                continue

            try:
                quote_data = json.loads(process.stdout)
                summary_results.append(quote_data)
            except json.JSONDecodeError:
                summary_results.append({
                    "symbol": symbol,
                    "error": "Invalid JSON response from market_quote.py",
                    "raw_output": process.stdout[:500] if process.stdout else ""
                })

        except Exception as e:
            summary_results.append({
                "symbol": symbol,
                "error": f"Exception during processing: {str(e)}"
            })

    response = {
        "items": current_list,
        "summary": summary_results
    }
    print(json.dumps(response, ensure_ascii=False, indent=2))


def setup_argument_parser() -> argparse.ArgumentParser:
    """Configure command-line argument parser"""
    parser = argparse.ArgumentParser(
        description="Market Watchlist Manager",
        prog="market-tracker"
    )

    subparsers = parser.add_subparsers(dest="command", required=True)

    # Add command
    add_parser = subparsers.add_parser("add", help="Add symbols to watchlist")
    add_parser.add_argument("symbols", nargs="+", help="Stock symbols to add")

    # Remove command
    remove_parser = subparsers.add_parser("remove", help="Remove symbols from watchlist")
    remove_parser.add_argument("symbols", nargs="+", help="Stock symbols to remove")

    # List command
    subparsers.add_parser("list", help="Display current watchlist")

    # Summary command
    subparsers.add_parser("summary", help="Generate summary report for watchlist")

    return parser


def main_entry_point() -> None:
    """Main entry point for the application"""
    parser = setup_argument_parser()
    arguments = parser.parse_args()

    command_handlers = {
        "add": execute_add_operation,
        "remove": execute_remove_operation,
        "list": display_watchlist,
        "summary": generate_summary_report
    }

    handler = command_handlers.get(arguments.command)
    if handler:
        if arguments.command in ("add", "remove"):
            handler(arguments.symbols)
        else:
            handler()
    else:
        raise SystemExit("Unknown command specified")


if __name__ == "__main__":
    main_entry_point()

import re
from dataclasses import dataclass, field
from datetime import datetime
from typing import cast, Optional
from rich.text import Text
from epstein_files.documents.document import CLOSE_PROPERTIES_CHAR, Document
from epstein_files.documents.documents.doc_cfg import CommunicationCfg
from epstein_files.output.highlight_config import HIGHLIGHTED_CONTACTS, get_style_for_name, styled_name
from epstein_files.output.rich import styled_key_value
from epstein_files.people.names import UNKNOWN, Name
from epstein_files.util.helpers.data_helpers import uniquify
from epstein_files.util.helpers.rich_helpers import no_bold

# Regex to strip trailing seconds from timestamps (e.g., ":59")
TIME_SEC_PATTERN = re.compile(r":\d{2}$")

@dataclass
class MessageLog(Document):
    """
    Base class for `Email` and `MessengerLog`.
    Attributes:
        extracted_recipients (list[Name]): People extracted as recipients during parsing.
    """
    parsed_recipients: list[Name] = field(default_factory=list)

    def __post_init__(self):
        super().__post_init__()
        # If config specifies recipients, use that; otherwise extract them automatically
        if self.config and self.config.recipients:
            self.parsed_recipients = []
        else:
            self.parsed_recipients = self._discover_recipients()

    @property
    def sender_or_default(self) -> str:
        return self.author or UNKNOWN

    @property
    def sender_style(self) -> str:
        return get_style_for_name(self.author)

    @property
    def sender_label(self) -> Text:
        return styled_name(self.author)

    @property
    def frame_style(self) -> str:
        return no_bold(self.sender_style)

    @property
    def involved_parties(self) -> list[str]:
        """List of unique participants: those who sent/received or were mentioned."""
        if self.config and self.config.people:
            return self.config.people
        base_participants = super().people + [p for p in self.participant_list if p]
        return sorted(uniquify(base_participants))

    @property
    def settings(self) -> Optional[CommunicationCfg]:
        """Return configured communication settings, if any."""
        cfg = super().config
        if cfg and not isinstance(cfg, CommunicationCfg):
            self.warn(f"Invalid config type encountered: {repr(cfg)}")
            cfg = cast(CommunicationCfg, cfg)
        return cfg

    @property
    def contains_unknown_sender(self) -> bool:
        return None in self.participant_list

    @property
    def contains_unknown_receiver(self) -> bool:
        return None in (self.receivers or [None])

    @property
    def receiver_confidence_low(self) -> bool:
        return bool(self.settings and self.settings.recipient_uncertain)

    @property
    def participant_list(self) -> set[Name]:
        """Set of individuals involved: sender plus receivers; includes None if no receivers."""
        return set([self.author] + (self.receivers or [None]))

    @property
    def receivers(self) -> list[Name]:
        if self.settings and self.settings.recipients:
            return self.settings.recipients
        else:
            return self.parsed_recipients

    @property
    def primary_receiver_style(self) -> str:
        # Use first receiver, fallback to sender
        first_recipient = (self.receivers or [self.author])[0]
        return get_style_for_name(first_recipient)

    @property
    def timestamp_truncated(self) -> str:
        return TIME_SEC_PATTERN.sub('', str(self.timestamp))

    @property
    def _brief_summary(self) -> Text:
        """Single-line summary used internally (e.g., logging)."""
        return self._brief_with_sender.append(CLOSE_PROPERTIES_CHAR)

    @property
    def _brief_with_sender(self) -> Text:
        """Add sender info to parent summary, leaving bracket open."""
        sender_text = styled_key_value('sender', Text(f"'{self.sender_or_default}'", style=self.sender_style))
        return super()._summary.append(', ').append(sender_text)

    def external_links_colored(self) -> Text:
        """Override parent method to color links using recipient style."""
        return self.file_info.build_external_links(self.primary_receiver_style, with_alt_links=True)

    def _discover_recipients(self) -> list[Name]:
        """To be implemented by subclasses."""
        return []

    @classmethod
    def default_group(cls) -> str:
        return cls.__name__.lower()

# Gender-neutral language checker for codebase

import os
import re
import sys

# Terms that may indicate gender bias (case-insensitive word boundaries)
BIAS_INDICATORS = [
    r"\bhe\b", r"\bshe\b", r"\bhim\b", r"\bher\b", r"\bhis\b", r"\bhers\b",
    r"\bman\b", r"\bwoman\b", r"\bmen\b", r"\bwomen\b",
    r"\bmale\b", r"\bfemale\b",
    r"\bboy\b", r"\bgirl\b", r"\bboys\b", r"\bgirls\b",
    r"\bfather\b", r"\bmother\b", r"\bdad\b", r"\bmom\b",
    r"\bhusband\b", r"\bwife\b",
    r"\bguy\b", r"\bguys\b", r"\blady\b", r"\bladies\b"
]

# Directories and files to skip during scanning
SKIP_DIRS = {
    '.git', '__pycache__', 'venv', 'env', '.venv', '.pytest_cache',
    'scripts/check_gender_bias.py',
    'logs', 'migrations', 'frontend-web', 'mobile-app',
    '.mypy_cache', 'SOUL_SENSE_EXAM', 'soulsense_db', 'backend', 'tests'
}
SKIP_FILES = {
    'LICENSE.txt', 'COMPLIANCE.md', 'RISK_ASSESSMENT.md',
    'README.md', 'RESEARCH_REFERENCES.md', 'FAQ.md'
}

def should_skip(path):
    """Determine if a file should be skipped based on exclusion rules."""
    filename = os.path.basename(path)

    # Skip explicitly excluded files
    if filename in SKIP_FILES:
        return True

    return False

def analyze_file(file_path):
    """Examine a single file for potentially biased language."""
    findings = []

    try:
        with open(file_path, 'r', encoding='utf-8', errors='ignore') as file:
            for line_index, text_line in enumerate(file, start=1):
                # Skip lines containing known safe references
                if "Haibo He" in text_line:
                    continue

                # Allow demographic categories where both genders are mentioned together
                if "Male" in text_line and "Female" in text_line:
                    continue

                # Check each bias indicator pattern
                for pattern in BIAS_INDICATORS:
                    if re.search(pattern, text_line, re.IGNORECASE):
                        clean_pattern = pattern.replace(r'\b', '')
                        findings.append((line_index, clean_pattern, text_line.rstrip()))
    except Exception as error:
        print(f"Warning: Could not process {file_path}: {error}")

    return findings

def traverse_directory(base_path):
    """Recursively scan directory structure for files to analyze."""
    total_results = {}
    processed_count = 0

    for current_dir, subdirs, filenames in os.walk(base_path):
        # Filter out directories we want to skip from traversal
        subdirs[:] = [d for d in subdirs if d not in SKIP_DIRS]

        for filename in filenames:
            full_path = os.path.join(current_dir, filename)

            # Skip excluded files
            if should_skip(full_path):
                continue

            # Only process common text-based file types
            extensions = ('.py', '.txt', '.md', '.json', '.html', '.js', '.css')
            if not filename.lower().endswith(extensions):
                continue

            print(f"Processing: {full_path}")
            processed_count += 1

            results = analyze_file(full_path)
            if results:
                total_results[full_path] = results

    return total_results, processed_count

def main():
    print("Analyzing codebase for gender-neutral language...")
    project_root = os.getcwd()
    issues, file_count = traverse_directory(project_root)

    print(f"\nAnalyzed {file_count} files.")

    if issues:
        print("\n\033[91mPotential gendered language detected:\033[0m")
        for file_path, problems in issues.items():
            absolute_path = os.path.abspath(file_path)
            print(f"\nFile: {absolute_path}")
            for line_num, term, snippet in problems:
                print(f"  Line {line_num}: '{term}' found in: \"{snippet}\"")
        print("\n\033[91mERROR: Gendered terms identified. Please revise to use inclusive language.\033[0m")
        sys.exit(1)
    else:
        print("\n\033[92mPASS: No gendered language detected. Codebase maintains neutral terminology.\033[0m")
        sys.exit(0)

if __name__ == "__main__":
    main()

