import logging
import torch
import torch.nn.functional as F
from omegaconf import DictConfig
import weathergen.train.loss_modules.loss_functions as loss_fns
from weathergen.train.loss_modules.loss_module_base import LossModuleBase, LossValues
from weathergen.utils.train_logger import Stage

logger = logging.getLogger(__name__)

class LossLatentSSLStudentTeacher(LossModuleBase):
    """
    Manages and computes the overall loss for a WeatherGenerator model pretraining using
    DINO/iBOT/JEPA/BYOL style losses.
    This class handles the initialization and application of various loss functions,
    It provides both the main loss for backpropagation and detailed loss metrics for logging.
    """
    SUPPORTED_LOSSES = {"DINO", "iBOT", "JEPA"}

    def __init__(self, config: DictConfig, stage_cfg: DictConfig, current_stage: Stage, target_device: str, **loss_configs):
        super().__init__()
        self.config = config
        self.stage_cfg = stage_cfg
        self.current_stage = current_stage
        self.target_device = target_device
        self.num_class_tokens = config.num_class_tokens
        self.module_name = "LossLatentSSLStudentTeacher"

        # Build loss configuration map: {loss_name: (weight, loss_func, extra_args)}
        self.loss_registry = {}
        for loss_key, cfg in loss_configs.items():
            if loss_key not in self.SUPPORTED_LOSSES:
                raise ValueError(f"Unsupported loss type '{loss_key}' specified.")
            weight_val = cfg.weight
            loss_fn_ref = _select_loss_function(loss_key)
            extra_args = cfg.get("loss_extra_args", {})
            self.loss_registry[loss_key] = (weight_val, loss_fn_ref, extra_args)

    def compute_loss(self, predictions, ground_truths, meta_info) -> LossValues:
        total_loss = torch.tensor(0.0, device=self.target_device, requires_grad=True)
        per_loss_dict = {k: 0.0 for k in self.loss_registry}

        src2tgt_match_indices, output_metadata, tgt2src_match_indices, _ = meta_info

        pred_latents = predictions.latent[0]   # Use first forecast step only
        target_latents = ground_truths.latent
        target_aux = ground_truths.aux_outputs

        for loss_name, (wgt, fn, args) in self.loss_registry.items():
            student_data = self._extract_student_components(
                loss_name, pred_latents[loss_name], output_metadata, tgt2src_match_indices
            )
            teacher_data = self._extract_teacher_components(
                loss_name, target_latents[loss_name], target_aux, tgt2src_match_indices
            )

            combined_kwargs = {**student_data, **teacher_data, **args}
            batch_loss = fn(**combined_kwargs).mean()
            total_loss += wgt * batch_loss
            per_loss_dict[loss_name] = batch_loss.item()

        return LossValues(loss=total_loss, losses_all=per_loss_dict, stddev_all={})

    def _extract_student_components(self, name, student_out, metadata_list, match_idx):
        if name == "JEPA":
            selected_items = [
                (p, info) for p, info in zip(student_out, metadata_list)
                if "JEPA" in info.global_params["loss"]
            ]
            patches = torch.stack([p for p, _ in selected_items], dim=0)
            masks = torch.stack([info.mask for _, info in selected_items], dim=0).unsqueeze(1)
            return {
                "student_patches_masked": patches,
                "student_masks": masks,
            }
        elif name == "iBOT":
            selected_items = [
                (p, info) for p, info in zip(student_out, metadata_list)
                if "iBOT" in info.global_params["loss"]
            ]
            patches_no_cls = torch.stack([p[self.num_class_tokens:] for p, _ in selected_items], dim=0)
            masks = torch.stack([info.mask for _, info in selected_items], dim=0).unsqueeze(1)
            cls_patches = torch.stack([p[:self.num_class_tokens] for p, _ in selected_items], dim=0)
            return {
                "student_patches_masked": patches_no_cls,
                "student_masks": masks,
                "student_class_masked": cls_patches,
            }
        elif name == "DINO":
            grouped_students = []
            for indices in match_idx:
                local_batch = [
                    student_out[idx]
                    for idx in indices
                    if "DINO" in metadata_list[idx].global_params["loss"]
                    and metadata_list[idx].global_params["relationship"] != "identity"
                ]
                grouped_students.append(local_batch)
            stacked_groups = [torch.stack(group, dim=0) for group in zip(*grouped_students)]

            identity_items = [
                p for p, info in zip(student_out, metadata_list)
                if "DINO" in info.global_params["loss"]
                and info.global_params["relationship"] == "identity"
            ]
            global_views = torch.stack(identity_items, dim=0) if identity_items else torch.empty(0)
            return {
                "local2global_dino_student": stacked_groups,
                "global2global_dino_student": global_views,
            }
        else:
            raise NotImplementedError(f"Unknown student extraction mode: {name}")

    def _extract_teacher_components(self, name, teacher_out, aux_data, match_idx):
        if name == "JEPA":
            selected_items = [
                (p, info) for p, info in zip(teacher_out, aux_data)
                if "JEPA" in info.global_params["loss"]
            ]
            patches = torch.stack([p for p, _ in selected_items], dim=0)
            masks = torch.stack([info.mask for _, info in selected_items], dim=0).unsqueeze(1)
            return {
                "teacher_patches_masked": patches,
                "teacher_masks": masks,
            }
        elif name == "iBOT":
            selected_items = [
                (p, info) for p, info in zip(teacher_out, aux_data)
                if "iBOT" in info.global_params["loss"]
            ]
            patches_no_cls = torch.stack([p[self.num_class_tokens:] for p, _ in selected_items], dim=0)
            masks = torch.stack([info.mask for _, info in selected_items], dim=0).unsqueeze(1)
            cls_patches = torch.stack([p[:self.num_class_tokens] for p, _ in selected_items], dim=0)
            return {
                "teacher_patches_masked": patches_no_cls,
                "teacher_masks": masks,
                "teacher_class_masked": cls_patches,
            }
        elif name == "DINO":
            all_teachers = [p for p, _ in zip(teacher_out, aux_data)]
            reversed_teachers = list(reversed(all_teachers))
            return {
                "local2global_dino_teacher": torch.stack(all_teachers, dim=0),
                "global2global_dino_teacher": torch.stack(reversed_teachers, dim=0),
            }
        else:
            raise NotImplementedError(f"Unknown teacher extraction mode: {name}")


def jepa_loss(student_patches_masked, student_masks, teacher_patches_masked, teacher_masks):
    assert teacher_masks.shape[0] == 1 or teacher_masks.shape[0] == student_masks.shape[0]

    s_masks_flat = student_masks.squeeze(dim=1)
    t_masks_flat = teacher_masks.squeeze(dim=1)

    mask_weights = (1 / s_masks_flat.sum(-1).clamp(min=1.0)).unsqueeze(-1).expand_as(s_masks_flat)
    union_mask = torch.logical_and(t_masks_flat, ~s_masks_flat)

    if union_mask.sum() == 0:
        logger.warning("jepa_loss: union_mask is empty — check masking configuration.")

    assert union_mask.shape[0] == student_patches_masked.shape[0], \
        "Batch dimension mismatch between union_mask and student_patches_masked."

    expanded_teachers = teacher_patches_masked.expand((union_mask.shape[0], -1, -1))

    diff_vals = student_patches_masked[union_mask] - expanded_teachers[union_mask]
    abs_diff = diff_vals.abs()
    weighted_loss = abs_diff * mask_weights[union_mask]
    return weighted_loss.sum()


def ibot_loss(
    student_patches_masked,
    student_masks,
    teacher_patches_masked,
    teacher_masks,
    student_class_masked,
    teacher_class_masked,
    student_temperature,
):
    s_masks_flat = student_masks.squeeze(dim=1)
    t_masks_flat = teacher_masks.squeeze(dim=1)

    patch_loss = loss_fns.masked_student_teacher_patch_softmax(
        student_patches_masked, teacher_patches_masked, s_masks_flat, t_masks_flat, student_temperature
    )
    cls_loss = loss_fns.student_teacher_softmax(
        student_class_masked, teacher_class_masked, student_temperature
    )
    return (patch_loss + cls_loss) / 2


def dino_loss(
    local2global_dino_student,
    local2global_dino_teacher,
    global2global_dino_student,
    global2global_dino_teacher,
    student_temperature,
):
    local_loss = loss_fns.student_teacher_global_softmax(
        local2global_dino_student, local2global_dino_teacher, student_temperature
    )
    global_loss = loss_fns.student_teacher_softmax(
        global2global_dino_student, global2global_dino_teacher, student_temperature
    )
    return (local_loss + global_loss) / 2


def _select_loss_function(name):
    mapping = {
        "iBOT": ibot_loss,
        "DINO": dino_loss,
        "JEPA": jepa_loss,
    }
    if name not in mapping:
        raise NotImplementedError(f"Loss function '{name}' not implemented.")
    return mapping[name]

