class AlpacaInterface(ExchangeInterface):
    def __init__(self, exchange_name, authenticated_api):
        self.__asset_cache = None
        super().__init__(exchange_name, authenticated_api, valid_resolutions=[60, 300, 900, 86400])
        assert isinstance(self.calls, alpaca_trade_api.REST)

    def init_exchange(self):
        try:
            account_data = self.calls.get_account()
        except alpaca_trade_api.rest.APIError as e:
            raise APIException(str(e) + ". Are you trying to use your normal exchange keys "
                                         "while in sandbox mode? \nTry toggling the \'sandbox\' setting "
                                         "in your keys.json or check if the keys were input correctly into your "
                                         "keys.json.")
        try:
            if account_data['account_blocked']:
                warnings.warn('Your alpaca account is indicated as blocked for trading....')
        except KeyError:
            raise LookupError("alpaca API call failed")

        available_assets = []
        products = self.calls.list_assets(status=None, asset_class=None)
        for item in products:
            symbol = item['symbol']
            if symbol not in available_assets and item['status'] != 'inactive':
                available_assets.append(symbol)
            else:
                # TODO handle duplicate symbols
                pass
        self.__asset_cache = available_assets

    def get_products(self) -> dict:
        required_fields = self.needed['get_products']
        assets = self.calls.list_assets(status=None, asset_class=None)

        for asset in assets:
            base_symbol = asset['symbol']
            asset['symbol'] = base_symbol
            asset['base_asset'] = base_symbol
            asset['quote_asset'] = 'USD'

            if asset['fractionable']:
                asset['base_min_size'] = .000000001
                asset['base_increment'] = .000000001
            else:
                asset['base_min_size'] = 1
                asset['base_increment'] = 1

            asset['base_max_size'] = 10000000000

        processed_assets = []
        for i in range(len(assets)):
            processed_assets.append(utils.isolate_specific(required_fields, assets[i]))
        return processed_assets

    @property
    def cash(self):
        account_info = self.calls.get_account()
        return float(account_info['buying_power'])

    @utils.enforce_base_asset
    def get_account(self, symbol=None):
        assert isinstance(self.calls, alpaca_trade_api.REST)
        symbol = super().get_account(symbol)

        positions = self.calls.list_positions()
        position_map = utils.AttributeDict({})

        for pos in positions:
            curr_symbol = pos.pop('symbol')
            position_map[curr_symbol] = utils.AttributeDict({
                'available': float(pos.pop('qty')),
                'hold': 0.0
            })

        active_symbols = list(position_map.keys())

        if len(active_symbols) != 0:
            pending_orders = self.calls.list_orders(status='open', symbols=active_symbols)
            market_data = self.calls.get_snapshots(symbols=active_symbols)
        else:
            pending_orders = []
            market_data = {}

        account = self.calls.get_account()
        position_map['USD'] = utils.AttributeDict({
            'available': float(account['buying_power']),
            'hold': 0.0
        })

        for order in pending_orders:
            curr_symbol = order['symbol']
            if order['side'] == 'buy':
                if order['qty']:
                    if order['type'] == 'limit':
                        dollar_amt = float(order['qty']) * float(order['limit_price'])
                    elif order['type'] == 'market':
                        dollar_amt = float(order['qty']) * market_data[curr_symbol]['latestTrade']['p']
                    else:
                        dollar_amt = 0.0
                else:
                    dollar_amt = float(order['notional'])
                position_map['USD']['hold'] += dollar_amt
            else:
                if order['qty']:
                    qty = float(order['qty'])
                else:
                    qty = float(order['notional']) / market_data[curr_symbol]['latestTrade']['p']
                position_map[curr_symbol]['available'] -= qty
                position_map[curr_symbol]['hold'] += qty

        if self.__asset_cache is None:
            self.init_exchange()

        for ticker in self.__asset_cache:
            if ticker not in position_map:
                position_map[ticker] = utils.AttributeDict({
                    'available': 0.0,
                    'hold': 0.0
                })

        if symbol is not None:
            if symbol in position_map:
                return utils.AttributeDict({
                    'available': float(position_map[symbol]['available']),
                    'hold': float(position_map[symbol]['hold'])
                })
            else:
                raise KeyError('Symbol not found.')

        if symbol == 'USD':
            return utils.AttributeDict({
                'available': position_map['USD']['available'],
                'hold': position_map['USD']['hold']
            })
        return position_map

    @staticmethod
    def __convert_timestamp(response):
        from dateutil import parser
        try:
            response['created_at'] = parser.isoparse(response['created_at']).timestamp()
        except ValueError as e:
            if str(e) == 'Unused components in ISO string':
                response['created_at'] = parser.parse(response['created_at']).timestamp()
            else:
                raise e
        return response

    @utils.order_protection
    def market_order(self, symbol, side, size) -> MarketOrder:
        assert isinstance(self.calls, alpaca_trade_api.REST)
        required = self.needed['market_order']
        order_info = utils.build_order_info(0, side, size, symbol, 'market')
        response = self.calls.submit_order(symbol, side=side, type='market', time_in_force='day', qty=size)
        response = self._process_response(required, response)
        return MarketOrder(order_info, response, self)

    @utils.order_protection
    def limit_order(self, symbol: str, side: str, price: float, size: float) -> LimitOrder:
        required = self.needed['limit_order']
        order_info = utils.build_order_info(price, side, size, symbol, 'limit')
        response = self.calls.submit_order(symbol,
                                           side=side,
                                           type='limit',
                                           time_in_force='gtc',
                                           qty=size,
                                           limit_price=price)
        response = self._process_response(required, response)
        return LimitOrder(order_info, response, self)

    @utils.order_protection
    def take_profit_order(self, symbol: str, price: float, size: float) -> TakeProfitOrder:
        side = 'sell'
        required = self.needed['take_profit']
        order_info = utils.build_order_info(price, side, size, symbol, 'take_profit')
        response = self.calls.submit_order(symbol,
                                           side=side,
                                           type='limit',
                                           time_in_force='gtc',
                                           qty=size,
                                           limit_price=price)
        response = self._process_response(required, response)
        return TakeProfitOrder(order_info, response, self)

    @utils.order_protection
    def stop_loss_order(self, symbol: str, price: float, size: float) -> StopLossOrder:
        side = 'sell'
        required = self.needed['stop_loss']
        order_info = utils.build_order_info(price, side, size, symbol, 'stop_loss')
        response = self.calls.submit_order(symbol,
                                           side=side,
                                           type='stop',
                                           time_in_force='gtc',
                                           qty=size,
                                           stop_price=price)
        response = self._process_response(required, response)
        return StopLossOrder(order_info, response, self)

    def _process_response(self, required, response):
        response = self.__convert_timestamp(response)
        response = utils.rename_to([
            ['limit_price', 'price'],
            ['qty', 'size']
        ], response)
        response = utils.isolate_specific(required, response)
        if 'time_in_force' in response:
            response['time_in_force'] = response['time_in_force'].upper()
        return response

    def cancel_order(self, symbol, order_id) -> dict:
        assert isinstance(self.calls, alpaca_trade_api.REST)
        self.calls.cancel_order(order_id)
        return {'order_id': order_id}

    def get_open_orders(self, symbol=None):
        assert isinstance(self.calls, alpaca_trade_api.REST)
        if symbol is None:
            orders = self.calls.list_orders(status='open')
        else:
            orders = self.calls.list_orders(status='open', symbols=[symbol])

        for i in range(len(orders)):
            orders[i] = self.normalize_order(orders[i])
        return orders

    def get_order(self, symbol, order_id) -> dict:
        assert isinstance(self.calls, alpaca_trade_api.REST)
        order = self.calls.get_order(order_id)
        order = self.normalize_order(order)
        return order

    def normalize_order(self, order):
        if order['type'] == "limit":
            renames = [
                ["qty", "size"],
                ["limit_price", "price"]
            ]
            order = utils.rename_to(renames, order)
        elif order['type'] == "stop_loss":
            renames = [
                ["qty", "size"],
                ["limit_price", "price"]
            ]
            order = utils.rename_to(renames, order)
        elif order['type'] == "take_profit":
            renames = [
                ["qty", "size"],
                ["limit_price", "price"]
            ]
            order = utils.rename_to(renames, order)
        elif order['type'] == "market":
            if order['notional']:
                renames = [
                    ["notional", "funds"]
                ]
                order = utils.rename_to(renames, order)
            else:
                order['size'] = order.pop('qty')
        elif order['type'] == "stop_limit":
            renames = [
                ["qty", "size"],
            ]
            order = utils.rename_to(renames, order)

        order = self.__convert_timestamp(order)
        if 'time_in_force' in order:
            order['time_in_force'] = order['time_in_force'].upper()

        needed = self.choose_order_specificity(order['type'])
        order = utils.isolate_specific(needed, order)
        return order

    def get_fees(self, symbol):
        assert isinstance(self.calls, alpaca_trade_api.REST)
        return {
            'maker_fee_rate': 0.0,
            'taker_fee_rate': 0.0
        }

    def get_product_history(self, symbol: str, epoch_start: float, epoch_stop: float, resolution: int):
        if not self.user_preferences['settings']['alpaca']['use_yfinance']:
            assert isinstance(self.calls, alpaca_trade_api.REST)
            resolution = time_interval_to_seconds(resolution)
            supported_intervals = [60, 3600, 86400]

            if resolution not in supported_intervals:
                utils.info_print("Granularity is not an accepted granularity...rounding to nearest valid value.")
                resolution = supported_intervals[min(range(len(supported_intervals)),
                                                     key=lambda i: abs(supported_intervals[i] - resolution))]

            found_multiple, row_divisor = super().evaluate_multiples(supported_intervals, resolution)

            if found_multiple == 60:
                time_frame = TimeFrame.Minute
            elif found_multiple == 3600:
                time_frame = TimeFrame.Hour
            else:
                time_frame = TimeFrame.Day

            start_time = dt.fromtimestamp(epoch_start, tz=timezone.utc).isoformat()
            end_time = dt.fromtimestamp(epoch_stop, tz=timezone.utc).isoformat()

            try:
                try:
                    bars = self.calls.get_bars(symbol, time_frame, start_time, end_time,
                                               adjustment='raw').df
                except TypeError:
                    return pd.DataFrame(columns=['time', 'open', 'high', 'low', 'close', 'volume'])
            except AlpacaAPIError as e:
                if e.code == 42210000:
                    warning_msg = "Your alpaca subscription does not permit querying data from the last 15 " \
                                  "minutes. Blankly is adjusting your query."
                    utils.info_print(warning_msg)
                    epoch_stop = time.time() - (build_minute() * 15)
                    if epoch_stop >= epoch_start:
                        try:
                            return self.get_product_history(symbol, epoch_start, epoch_stop, resolution)
                        except TypeError:
                            return pd.DataFrame(columns=['time', 'open', 'high', 'low', 'close', 'volume'])
                    else:
                        warning_msg = "No data range queried after time adjustment."
                        utils.info_print(warning_msg)
                        return pd.DataFrame(columns=['time', 'open', 'high', 'low', 'close', 'volume'])
                else:
                    raise e

            bars.rename(columns={"t": "time", "o": "open", "h": "high", "l": "low", "c": "close", "v": "volume"},
                        inplace=True)
            if bars.empty:
                return pd.DataFrame(columns=['time', 'open', 'high', 'low', 'close', 'volume'])
            return utils.get_ohlcv(bars, row_divisor, from_zero=False)
        else:
            return self.parse_yfinance(symbol, epoch_start, epoch_stop, resolution)

    def overridden_history(self, symbol, epoch_start, epoch_stop, resolution_seconds, **kwargs) -> pd.DataFrame:
        to = kwargs['to']

        if to is not None and isinstance(to, str):
            to = None

        if to:
            if not self.user_preferences['settings']['alpaca']['use_yfinance']:
                resolution_seconds = self.valid_resolutions[min(range(len(self.valid_resolutions)),
                                                                key=lambda j: abs(self.valid_resolutions[j] -
                                                                                  resolution_seconds))]
                resolution_map = {
                    60: '1Min',
                    300: '5Min',
                    900: '15Min',
                    86400: '1Day'
                }
                time_frame = resolution_map[resolution_seconds]

                def fetch_batch(start_epoch, end_epoch):
                    frames = []
                    while start_epoch <= end_epoch:
                        frames.append(self.calls.get_bars(symbol, time_frame, limit=10000,
                                                          start=utils.iso8601_from_epoch(start_epoch)).df)
                        start_epoch += resolution_seconds * 10000
                    for i in range(len(frames)):
                        series = []
                        for j in frames[i].index:
                            series.append(j.timestamp())
                        frames[i]['time'] = pd.Series(series).values
                        frames[i] = frames[i].reset_index(drop=True)
                    if len(frames) != 0:
                        result_ = pd.concat(frames, ignore_index=True)
                    else:
                        result_ = pd.DataFrame(columns=['time', 'open', 'high', 'low', 'close', 'volume'])
                    return result_

                response = pd.DataFrame(columns=['time', 'open', 'high', 'low', 'close', 'volume'])
                batch_ranges = [epoch_start, epoch_stop]
                tries = 2

                while len(response) < to:
                    response = pd.concat([response, fetch_batch(batch_ranges[0], batch_ranges[1])])
                    batch_ranges[0] -= resolution_seconds * tries
                    batch_ranges[1] -= resolution_seconds * tries
                    tries = tries * 2

                response = response[['time', 'open', 'high', 'low', 'close', 'volume']]
                response = response.sort_values(by=['time'], ignore_index=True)
                response = response.tail(to)
                response = response.astype({
                    'time': int,
                    'open': float,
                    'high': float,
                    'low': float,
                    'close': float,
                    'volume': float,
                })
            else:
                epoch_start = epoch_stop - (epoch_stop - epoch_start) * 1.5
                return self.parse_yfinance(symbol, epoch_start, epoch_stop, resolution_seconds).tail(to).reset_index()
        else:
            response = self.get_product_history(symbol,
                                                epoch_start,
                                                epoch_stop,
                                                int(resolution_seconds))
        return response

    @staticmethod
    def __adjust_timezone(date):
        if isinstance(date, str):
            import dateparser
            date = dateparser.parse(date)
        elif isinstance(date, float):
            date = dt.fromtimestamp(date)
        if date.tzinfo is None or date.tzinfo.utcoffset(date) is None:
            date = date.replace(tzinfo=timezone.utc)
        return date

    def get_order_limits(self, symbol: str):
        assert isinstance(self.calls, alpaca_trade_api.REST)
        current_price = self.get_price(symbol)
        products = self.get_products()
        product = None
        for item in products:
            if item['symbol'] == symbol:
                product = item
                break
        if product is None:
            raise APIException("Symbol not found.")

        exchange_details = product['exchange_specific']
        fractionable = exchange_details['fractionable']

        if fractionable:
            quote_increment = 1e-9
            min_funds_buy = 1
            min_funds_sell = 1e-9 * current_price
            max_qty = product['base_max_size']
            min_price = 0.0001
            max_price = 10000000000
            min_qty = 1e-9
            qty_increment = 1e-9
        else:
            quote_increment = current_price
            min_funds_buy = current_price
            min_funds_sell = current_price
            max_qty = product['base_max_size']
            min_price = 0.0001
            max_price = 10000000000
            min_qty = 1
            qty_increment = 1

        max_funds = current_price * 10000000000

        return {
            "symbol": symbol,
            "base_asset": symbol,
            "quote_asset": 'USD',
            "max_orders": 500,
            "limit_order": {
                "base_min_size": 1,
                "base_max_size": max_qty,
                "base_increment": 1,
                "price_increment": min_price,
                "min_price": min_price,
                "max_price": max_price,
            },
            'market_order': {
                "fractionable": fractionable,
                "base_min_size": min_qty,
                "base_max_size": max_qty,
                "base_increment": qty_increment,
                "quote_increment": quote_increment,
                "buy": {
                    "min_funds": min_funds_buy,
                    "max_funds": max_funds,
                },
                "sell": {
                    "min_funds": min_funds_sell,
                    "max_funds": max_funds,
                },
            },
            "exchange_specific": {
                "id": exchange_details['id'],
                "class": exchange_details['class'],
                "exchange": exchange_details['exchange'],
                "status": exchange_details['status'],
                "tradable": exchange_details['tradable'],
                "marginable": exchange_details['marginable'],
                "shortable": exchange_details['shortable'],
                "easy_to_borrow": exchange_details['easy_to_borrow'],
                "price": current_price
            }
        }

    def get_price(self, symbol) -> float:
        assert isinstance(self.calls, alpaca_trade_api.REST)
        response = self.calls.get_latest_trade(symbol=symbol)
        return float(response['p'])

    @staticmethod
    def parse_yfinance(symbol: str, epoch_start: [int, float], epoch_stop: [int, float], resolution: int):
        try:
            import yfinance
            start_date = dt.fromtimestamp(epoch_start, tz=timezone.utc)
            stop_date = dt.fromtimestamp(epoch_stop, tz=timezone.utc)
            ticker = yfinance.Ticker(symbol)
            result = ticker.history(start=start_date, end=stop_date, interval=number_interval_to_string(resolution))
            result['time'] = result.index.astype(int) // 10 ** 9
            result = result[['Open', 'High', 'Low', 'Close', 'Volume', 'time']].reset_index()
            result = result.rename(columns={
                'time': 'time',
                'Open': 'open',
                'High': 'high',
                'Low': 'low',
                'Close': 'close',
                'Volume': 'volume'
            })
            result = result[['time', 'open', 'high', 'low', 'close', 'volume']]
            return result
        except ImportError:
            raise ImportError("To use yfinance to download data please pip install yfinance")

