def check_config_constraints(args):
    assert args.untie_embeddings_and_output_weights == True, "Required for code clarity"
    assert args.defer_embedding_wgrad_compute == False, "Original implementation has issues"

    if (
        args.zb_v_schedule_active
        or args.zb_pipeline_active
        or args.enable_1f1b_v
        or args.num_seq_splits > 1
        or args.interleave_group_count > 0
        or args.zb_runtime_active
    ):
        args.zb_runtime_active = True
        if not args.gradient_accumulation_fusion:
            raise RuntimeError("gradient-accumulation-fusion must be True for zb runtime.")

    if args.pre_comm_opt_enabled:
        if not args.zb_runtime_active or not args.overlap_p2p_comm:
            raise RuntimeError(
                "pre-communication requires --zb-runtime-enable and --overlap-p2p-communication"
            )

    if args.zb_runtime_active and args.overlap_p2p_comm:
        cuda_max_conn = int(os.environ.get("CUDA_DEVICE_MAX_CONNECTIONS") or 8)
        if cuda_max_conn < 8:
            raise RuntimeError("CUDA_DEVICE_MAX_CONNECTIONS >= 8 required for overlap-p2p-communication")

    if args.zb_v_schedule_active or args.enable_1f1b_v:
        assert (
            args.num_layers % args.transformer_pipeline_model_parallel_size == 0
        ), "num_layers must be divisible by pipeline parallel size"

        layers_per_stage = args.num_layers // args.transformer_pipeline_model_parallel_size
        assert (
            layers_per_stage % 2 == 0
        ), "V schedules require even number of layers per pipeline stage"

        assert (
            args.num_layers_per_virtual_pipeline_stage is None
        ), "virtual pipeline stages not compatible with V schedules"

        args.virtual_pipeline_model_parallel_size = 2
        args.num_layers_per_virtual_pipeline_stage = layers_per_stage // 2

    if args.zb_v_schedule_active:
        args.zb_pipeline_active = True
        assert args.zb_v_meme_config in {"min", "half", "zb"}

    if args.enable_1f1b_v:
        assert args.pipeline_model_parallel_size > 1, "1F1B-V requires pipeline parallelism"
        assert not args.zb_pipeline_active, "conflicts with zero-bubble"
        assert not args.opt_post_check_enabled, "post-check not supported for 1F1B-V"

    if args.zb_pipeline_active:
        if args.use_distributed_optimizer:
            assert not args.overlap_param_gather, "unsupported in current implementation"
            assert not args.overlap_grad_reduce, "not yet verified for correctness"

        assert args.pipeline_model_parallel_size > 1, "requires pipeline parallelism"

        if args.opt_post_check_enabled:
            assert args.fp16, "post-check only for fp16"

        if args.zb_max_backlog_bw == "auto":
            assert args.zb_mem_adaptive_percent > 0
        else:
            args.zb_max_backlog_bw = int(args.zb_max_backlog_bw)
    else:
        args.opt_post_check_enabled = False

    if args.cpu_offload:
        if args.auto_offload_latency:
            args.offload_latency = calculate_offload_time(args.hidden_size, args.seq_length)
            logging.info(f"Auto-configured offload-latency: {args.offload_latency:.4f}")
        else:
            logging.info(f"Specified offload-latency: {args.offload_latency:.4f}")

def calculate_offload_time(hidden_dim: int, seq_len: int):
    tflops_val, d2h_bw = detect_gpu_specs()
    factor = 10.0 / (3 * (6 * hidden_dim + seq_len)) * tflops_val * 1000.0 / d2h_bw
    return factor / 2.0

def detect_gpu_specs():
    """Detect GPU model characteristics."""
    import torch
    assert torch.cuda.is_available(), "CUDA unavailable"

    device_props = {
        "A100": {
            "tflops": 220,
            "d2h_bandwidth_gbps": 15,
        },
        "H100": {
            "tflops": 440,
            "d2h_bandwidth_gbps": 21,
        },
    }

    gpu_name = torch.cuda.get_device_name(0)
    for model, specs in device_props.items():
        if model in gpu_name:
            return specs["tflops"], specs["d2h_bandwidth_gbps"]

    return device_props["A100"]["tflops"], device_props["A100"]["d2h_bandwidth_gbps"]

class BackpropBuffer:
    needs_split = False
    buffer_store = []
    grad_buffer = None

    @classmethod
    def initialize_if_needed(cls):
        if cls.grad_buffer is not None:
            return

        num_chunks = parallel_state.get_virtual_pipeline_model_parallel_world_size() or 1
        cls.grad_buffer = [
            [threading.Semaphore(0) for _ in range(get_args().num_seq_splits)] for _ in range(num_chunks)
        ]

    @classmethod
    def can_use_split(cls):
        if not cls.supports_zb_mode():
            return False
        return cls.needs_split

    @classmethod
    def supports_zb_mode(cls):
        args = get_args()
        if args.pipeline_model_parallel_size <= 1:
            return False
        if args.overlap_grad_reduce:
            return False
        if not args.gradient_accumulation_fusion:
            return False
        return True

    @classmethod
    def activate_split(cls):
        cls.needs_split = True

    @classmethod
    def deactivate_split(cls):
        cls.needs_split = False

    @classmethod
    @contextmanager
    def toggle_split(cls, state: bool):
        old_state = cls.needs_split
        cls.needs_split = state
        try:
            yield
        finally:
            cls.needs_split = old_state

    @classmethod
    def enqueue(cls, weight, prep_fn, exec_fn):
        assert cls.can_use_split()
        cls.buffer_store.append((weight, prep_fn, exec_fn))

    @classmethod
    def get_buffer_size(cls, chunk_id=0, split_idx=0):
        cls.initialize_if_needed()
        return len(cls.buffer_store) if chunk_id == 0 and split_idx == 0 else 0

    @classmethod
    def drain(cls, chunk_id=0, split_idx=0, count=None):
        cls.initialize_if_needed()
        if not cls.can_use_split():
            assert len(cls.buffer_store) == 0
            return

        if count is not None and count < len(cls.buffer_store):
            processed = cls.buffer_store[:count]
            cls.buffer_store = cls.buffer_store[count:]
        else:
            processed = cls.buffer_store
            cls.buffer_store = []

        # Process in background thread
        def process_batch():
            for w, p, e in processed:
                e(*p(async_op=False))

        import threading
        t = threading.Thread(target=process_batch)
        t.start()
        t.join()

    @classmethod
    def retrieve(cls, chunk_id=0, split_idx=0, clear=False):
        cls.initialize_if_needed()

        def execute_stored(stored_items):
            for idx, item in enumerate(stored_items):
                w, p, e = item
                e(*p(async_op=False))
                if clear:
                    stored_items[idx] = None

        exec_func = execute_stored
        if get_args().dump_pp_data:
            exec_func = fwd_bwd_wrapper(execute_stored, "wgrad")

        if len(cls.buffer_store) > 0:
            items = cls.buffer_store.copy()
            cls.buffer_store.clear()
            exec_func(items)
        else:
            rank = parallel_state.get_pipeline_model_parallel_rank()
            raise Exception(f"Empty buffer retrieval. rank {rank}")

    @classmethod
    def verify_empty(cls):
        rank = parallel_state.get_pipeline_model_parallel_rank()
        assert len(cls.buffer_store) == 0, f"Buffer not empty. rank {rank}"

    @classmethod
    def reset(cls, model, chunk_id=0, split_idx=0):
        cls.initialize_if_needed()
        while len(cls.buffer_store) > 0:
            cls.retrieve(chunk_id, split_idx, clear=True)

class CheckpointBuffer:
    storage = []
    checkpoint_flag = False

    @classmethod
    def init_storage(cls):
        if cls.checkpoint_flag is not False:
            return

        num_chunks = parallel_state.get_virtual_pipeline_model_parallel_world_size() or 1
        cls.storage = [[] for _ in range(num_chunks)]

    @classmethod
    @contextmanager
    def set_checkpoint_mode(cls, active: bool):
        prev = cls.checkpoint_flag
        cls.checkpoint_flag = active
        try:
            yield
        finally:
            cls.checkpoint_flag = prev

    @classmethod
    def should_checkpoint(cls):
        return cls.checkpoint_flag

    @classmethod
    def add_to_buffer(cls, fn):
        assert cls.should_checkpoint()
        cls.init_storage()
        chunk_id = parallel_state.get_virtual_pipeline_model_parallel_rank()
        cls.storage[chunk_id].append(fn)

    @classmethod
    def flush(cls):
        if not cls.should_checkpoint():
            assert len(cls.storage) == 0
            return

        cls.init_storage()
        chunk_id = parallel_state.get_virtual_pipeline_model_parallel_rank()
        funcs = cls.storage[chunk_id].copy()
        cls.storage[chunk_id].clear()

        for func in funcs:
            func()

from cosmos_rl.policy.model.base import WeightMapper
import torch
from cosmos_rl.utils import util
from transformers import AutoConfig
from typing import List, Tuple, Dict, Optional
import re


class InternVLWeightMapper(WeightMapper):
    def __init__(self, hf_config: AutoConfig):
        super().__init__(hf_config)
        self._init_attention_params()

    def _init_attention_params(self):
        llm_cfg = self.config.llm_config
        self._num_attn_heads = llm_cfg.num_attention_heads
        self._num_kv_heads = llm_cfg.num_key_value_heads
        self._hidden_size = llm_cfg.hidden_size
        self._kv_head_ratio = self._num_attn_heads // self._num_kv_heads
        self._head_dim = self._hidden_size // self._num_attn_heads

    def _map_backend_specific(self, key: str) -> str:
        if self.backend == "vllm":
            return self.policy_map_local_key_to_hf_key(key)
        elif self.backend == "trtllm":
            return self._remap_trtllm_key(key)
        else:
            raise ValueError(f"Unsupported backend: {self.backend}")

    def _remap_trtllm_key(self, key: str) -> str:
        replacements = [
            ("llm.model.", "model."),
            ("llm.lm_head.", "lm_head."),
        ]
        for old, new in replacements:
            if key.startswith(old):
                return key.replace(old, new)
        # Special handling for mm_encoder
        if key.startswith("mm_encoder."):
            return key.replace(".", ".visual.", 1).replace(".", ".", 2)
        return key

    def _split_qkv_weight(self, name: str, weight: torch.Tensor) -> Tuple[torch.Tensor, ...]:
        if "visual" in name:
            return self._split_visual_qkv(weight)
        else:
            return self._split_language_qkv(weight)

    def _split_visual_qkv(self, weight: torch.Tensor) -> Tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
        assert weight.shape[0] % 3 == 0, "Visual QKV weight must be divisible by 3"
        unit = weight.shape[0] // 3
        return weight[:unit], weight[unit : 2 * unit], weight[2 * unit :]

    def _split_language_qkv(self, weight: torch.Tensor) -> Tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
        total_shares = self._kv_head_ratio + 2
        assert weight.shape[0] % total_shares == 0, "Language QKV weight shape incompatible"
        unit = weight.shape[0] // total_shares
        q_len = unit * self._kv_head_ratio
        k_len = unit
        v_len = unit
        return (
            weight[:q_len],
            weight[q_len : q_len + k_len],
            weight[q_len + k_len : q_len + k_len + v_len],
        )

    def _split_gate_up_proj(self, weight: torch.Tensor) -> Tuple[torch.Tensor, torch.Tensor]:
        assert weight.shape[0] % 2 == 0, "Gate-up proj weight must have even first dimension"
        mid = weight.shape[0] // 2
        return weight[:mid], weight[mid:]

    def rollout_split_local_key_n_param_to_hf_key_n_param(
        self, param_name: str, param: torch.Tensor
    ) -> List[Tuple[str, torch.Tensor]]:
        compatible_key = self.rollout_map_local_key_to_hf_key(param_name)
        result: List[Tuple[str, torch.Tensor]] = []

        # Dispatch based on pattern match
        if "qkv_proj" in compatible_key:
            q, k, v = self._split_qkv_weight(compatible_key, param)
            result.extend([
                (compatible_key.replace("qkv_proj", "q_proj"), q),
                (compatible_key.replace("qkv_proj", "k_proj"), k),
                (compatible_key.replace("qkv_proj", "v_proj"), v),
            ])
        elif "gate_up_proj" in compatible_key:
            gate, up = self._split_gate_up_proj(param)
            result.extend([
                (compatible_key.replace("gate_up_proj", "gate_proj"), gate),
                (compatible_key.replace("gate_up_proj", "up_proj"), up),
            ])
        elif "qkv" in compatible_key and "visual" in compatible_key:
            q, k, v = self._split_qkv_weight(compatible_key, param)
            result.extend([
                (compatible_key.replace("qkv", "q"), q),
                (compatible_key.replace("qkv", "k"), k),
                (compatible_key.replace("qkv", "v"), v),
            ])
        else:
            result.append((compatible_key, param))

        return result

    def policy_map_local_key_to_hf_key(self, name: str) -> str:
        clean_name = util.clear_weight_name(name)
        if clean_name.startswith("language_model."):
            clean_name = clean_name[len("language_model."):]
        if clean_name == "model.lm_head.weight":
            clean_name = "lm_head.weight"
        return clean_name

    def name_to_model_part_index(self, dest_name: str) -> int:
        mapping: Dict[str, int] = {
            "lm_head.weight": 0,
            "lm_head.bias": 0,
        }
        if dest_name in mapping:
            return mapping[dest_name]
        if dest_name.startswith("visual."):
            return 1
        if dest_name.startswith("model."):
            return 0
        raise ValueError(f"Unsupported weight: {dest_name}")

    def policy_decompose_param_1_to_n_for_sync(self, name: str) -> List[Tuple[str, Dict[int, Dict[str, int]]]]:
        # Use regex to detect visual block qkv patterns
        pattern = r"visual\.blocks\.(\d+)\.attn\.qkv\.(weight|bias)"
        match = re.search(pattern, name)
        if not match:
            return []

        base_replacements = ["q", "k", "v"]
        strategy: List[Tuple[str, Dict[int, Dict[str, int]]]] = []
        for idx, suffix in enumerate(base_replacements):
            new_name = name.replace("qkv", suffix)
            split_info = {0: {"offset": idx, "total_size": 3, "length": 1}}
            strategy.append((new_name, split_info))
        return strategy

# Health tracker CLI tool using Garmin Connect API

import json
import sys
from datetime import date

try:
    from garmer import GarminClient
    from garmer.auth import AuthenticationError
except ImportError:
    print("Error: garmer not installed. Run: pip install garmer", file=sys.stderr)
    sys.exit(1)

def establish_connection() -> GarminClient:
    """Establish connection with Garmin account using saved tokens."""
    try:
        return GarminClient.from_saved_tokens()
    except AuthenticationError:
        print("Error: Not authenticated. Run 'garmer login' first.", file=sys.stderr)
        sys.exit(1)

def display_daily_health():
    """Display today's health metrics."""
    client = establish_connection()
    health_data = client.get_daily_summary()

    print(f"Date: {date.today()}")
    print(f"Steps: {health_data.total_steps:,} / {health_data.daily_step_goal:,}")
    print(f"Distance: {health_data.total_distance_meters / 1000:.2f} km")
    print(f"Calories: {health_data.total_kilocalories:,}")

    if health_data.resting_heart_rate is not None:
        print(f"Resting HR: {health_data.resting_heart_rate} bpm")
    if health_data.avg_stress_level is not None:
        print(f"Avg Stress: {health_data.avg_stress_level}")

def display_sleep_info():
    """Display sleep statistics."""
    client = establish_connection()
    sleep_stats = client.get_sleep()

    if sleep_stats:
        print(f"Total Sleep: {sleep_stats.total_sleep_hours:.1f} hours")
        print(f"Deep Sleep: {sleep_stats.deep_sleep_hours:.1f} hours")
        print(f"REM Sleep: {sleep_stats.rem_sleep_hours:.1f} hours")

        if sleep_stats.overall_score:
            print(f"Sleep Score: {sleep_stats.overall_score}")
        if sleep_stats.avg_hrv:
            print(f"HRV: {sleep_stats.avg_hrv:.1f} ms")
    else:
        print("No sleep data available")

def display_recent_workouts():
    """Display list of recent physical activities."""
    client = establish_connection()
    workouts = client.get_recent_activities(limit=5)

    if workouts:
        for activity in workouts:
            print(f"- {activity.activity_name} ({activity.activity_type_key})")
            print(
                f"  Duration: {activity.duration_minutes:.0f} min, Distance: {activity.distance_km:.2f} km"
            )
    else:
        print("No recent activities")

def display_full_health_report():
    """Display complete health snapshot in JSON format."""
    client = establish_connection()
    full_snapshot = client.get_health_snapshot()
    print(json.dumps(full_snapshot, indent=2, default=str))

def main():
    if len(sys.argv) < 2:
        print(__doc__)
        sys.exit(0)

    action = sys.argv[1].lower()
    available_actions = {
        "summary": display_daily_health,
        "sleep": display_sleep_info,
        "activities": display_recent_workouts,
        "snapshot": display_full_health_report,
    }

    if action in available_actions:
        available_actions[action]()
    else:
        print(f"Unknown command: {action}")
        print(__doc__)
        sys.exit(1)

if __name__ == "__main__":
    main()

from __future__ import annotations
from typing import TYPE_CHECKING, Any
import numpy as np
from torchax.interop import jax_view
from vllm.lora.layers.base_linear import BaseLinearLayerWithLoRA
from vllm.lora.request import LoRARequest
from tpu_inference.layers.vllm.process_weights.cleanup_sharding import update_lora

if TYPE_CHECKING:
    from tpu_inference.runner.tpu_runner import TPUModelRunner


class LoRAHelper:
    def __init__(self, model_runner: "TPUModelRunner"):
        self.model_runner = model_runner

    def activate_adapters(self,
                          tokens_per_request: np.ndarray,
                          total_tokens: int,
                          padded_total_tokens: int) -> None:
        # Ensure we don’t mutate original input by copying
        adjusted_tokens_per_req = np.copy(tokens_per_request)
        padding_correction = padded_total_tokens - total_tokens
        adjusted_tokens_per_req[-1] += padding_correction

        prompt_map, token_map, active_requests = \
            self.model_runner.input_batch.make_lora_inputs(adjusted_tokens_per_req)

        # Load LoRA weights and apply them outside JAX context due to disk I/O limitations
        self.model_runner._set_active_loras(prompt_map, token_map, active_requests)

        updated_params_buffers = update_lora(
            self.model_runner.model.model,
            initial_params_buffers=self.model_runner.state
        )
        self.model_runner.state = jax_view(updated_params_buffers)

    def gather_lora_state(self) -> dict | None:
        if self.model_runner.lora_config is None:
            return None

        lora_metadata = {}
        punica_wrapper = None

        # Find first compatible module with punica_wrapper
        for name, module in self.model_runner.model.model.named_modules():
            if isinstance(module, BaseLinearLayerWithLoRA):
                wrapper = getattr(module, 'punica_wrapper', None)
                assert wrapper is not None, (
                    f"Module '{name}' of type {type(module)} must have a punica_wrapper"
                )
                punica_wrapper = wrapper
                break

        assert punica_wrapper is not None, (
            "No BaseLinearLayerWithLoRA found — punica_wrapper missing."
        )

        # Collect non-string attributes only (excluding device for JIT compatibility)
        for attr_name in dir(punica_wrapper):
            if attr_name.startswith('__'):
                continue
            value = getattr(punica_wrapper, attr_name, None)
            if attr_name == 'device' or callable(value):
                continue
            lora_metadata[attr_name] = value

        return jax_view(lora_metadata)


def inject_lora_state(model, new_state: dict, lora_cfg) -> dict:
    if lora_cfg is None or not new_state:
        return {}

    saved_state = {}
    punica_wrapper = None

    # Locate punica_wrapper via traversal
    for _, mod in model.named_modules():
        if isinstance(mod, BaseLinearLayerWithLoRA):
            wrapped = getattr(mod, 'punica_wrapper', None)
            assert wrapped is not None, (
                "Expected punica_wrapper inside LoRA-enabled linear layer."
            )
            punica_wrapper = wrapped
            break

    assert punica_wrapper is not None, (
        "Failed to locate punica_wrapper in model hierarchy."
    )

    # Replace values in-place and record originals
    for key in new_state.keys():
        if hasattr(punica_wrapper, key):
            saved_state[key] = getattr(punica_wrapper, key)
            setattr(punica_wrapper, key, new_state[key])

    return saved_state

import torch.nn as nn

class BottleneckLayer(nn.Module):
    def __init__(self, input_channels, output_channels, normalization="group", downsample_factor=1):
        super(BottleneckLayer, self).__init__()
        self.reduce_conv = nn.Conv2d(input_channels, output_channels // 4, kernel_size=1, padding=0)
        self.spatial_conv = nn.Conv2d(output_channels // 4, output_channels // 4, kernel_size=3, padding=1, stride=downsample_factor)
        self.expand_conv = nn.Conv2d(output_channels // 4, output_channels, kernel_size=1, padding=0)
        self.activation = nn.ReLU(inplace=True)

        group_count = output_channels // 8

        if normalization == "group":
            self.norm_reduce = nn.GroupNorm(num_groups=group_count, num_channels=output_channels // 4)
            self.norm_spatial = nn.GroupNorm(num_groups=group_count, num_channels=output_channels // 4)
            self.norm_expand = nn.GroupNorm(num_groups=group_count, num_channels=output_channels)
            if downsample_factor != 1:
                self.norm_shortcut = nn.GroupNorm(num_groups=group_count, num_channels=output_channels)
        elif normalization == "batch":
            self.norm_reduce = nn.BatchNorm2d(output_channels // 4)
            self.norm_spatial = nn.BatchNorm2d(output_channels // 4)
            self.norm_expand = nn.BatchNorm2d(output_channels)
            if downsample_factor != 1:
                self.norm_shortcut = nn.BatchNorm2d(output_channels)
        elif normalization == "instance":
            self.norm_reduce = nn.InstanceNorm2d(output_channels // 4)
            self.norm_spatial = nn.InstanceNorm2d(output_channels // 4)
            self.norm_expand = nn.InstanceNorm2d(output_channels)
            if downsample_factor != 1:
                self.norm_shortcut = nn.InstanceNorm2d(output_channels)
        elif normalization == "none":
            self.norm_reduce = nn.Sequential()
            self.norm_spatial = nn.Sequential()
            self.norm_expand = nn.Sequential()
            if downsample_factor != 1:
                self.norm_shortcut = nn.Sequential()

        if downsample_factor == 1:
            self.shortcut_path = None
        else:
            self.shortcut_path = nn.Sequential(
                nn.Conv2d(input_channels, output_channels, kernel_size=1, stride=downsample_factor),
                self.norm_shortcut
            )

    def forward(self, input_tensor):
        residual = input_tensor
        out = self.activation(self.norm_reduce(self.reduce_conv(residual)))
        out = self.activation(self.norm_spatial(self.spatial_conv(out)))
        out = self.norm_expand(self.expand_conv(out))

        if self.shortcut_path is not None:
            residual = self.shortcut_path(residual)

        return self.activation(residual + out)


class BasicResidualLayer(nn.Module):
    def __init__(self, input_channels, output_channels, normalization="group", downsample_factor=1):
        super(BasicResidualLayer, self).__init__()
        self.first_conv = nn.Conv2d(input_channels, output_channels, kernel_size=3, padding=1, stride=downsample_factor)
        self.second_conv = nn.Conv2d(output_channels, output_channels, kernel_size=3, padding=1)
        self.activation = nn.ReLU(inplace=True)

        group_count = output_channels // 8

        if normalization == "group":
            self.norm_first = nn.GroupNorm(num_groups=group_count, num_channels=output_channels)
            self.norm_second = nn.GroupNorm(num_groups=group_count, num_channels=output_channels)
            if downsample_factor != 1:
                self.norm_shortcut = nn.GroupNorm(num_groups=group_count, num_channels=output_channels)
        elif normalization == "batch":
            self.norm_first = nn.BatchNorm2d(output_channels)
            self.norm_second = nn.BatchNorm2d(output_channels)
            if downsample_factor != 1:
                self.norm_shortcut = nn.BatchNorm2d(output_channels)
        elif normalization == "instance":
            self.norm_first = nn.InstanceNorm2d(output_channels)
            self.norm_second = nn.InstanceNorm2d(output_channels)
            if downsample_factor != 1:
                self.norm_shortcut = nn.InstanceNorm2d(output_channels)
        elif normalization == "none":
            self.norm_first = nn.Sequential()
            self.norm_second = nn.Sequential()
            if downsample_factor != 1:
                self.norm_shortcut = nn.Sequential()

        if downsample_factor == 1:
            self.shortcut_path = None
        else:
            self.shortcut_path = nn.Sequential(
                nn.Conv2d(input_channels, output_channels, kernel_size=1, stride=downsample_factor),
                self.norm_shortcut
            )

    def forward(self, input_tensor):
        residual = input_tensor
        out = self.activation(self.norm_first(self.first_conv(residual)))
        out = self.norm_second(self.second_conv(out))

        if self.shortcut_path is not None:
            residual = self.shortcut_path(residual)

        return self.activation(residual + out)


class MiniFeatureExtractor(nn.Module):
    def __init__(self, feature_dim=128, normalization="batch", dropout_rate=0.0):
        super(MiniFeatureExtractor, self).__init__()
        self.normalization_type = normalization

        if normalization == "group":
            self.input_norm = nn.GroupNorm(num_groups=8, num_channels=32)
        elif normalization == "batch":
            self.input_norm = nn.BatchNorm2d(32)
        elif normalization == "instance":
            self.input_norm = nn.InstanceNorm2d(32)
        elif normalization == "none":
            self.input_norm = nn.Sequential()

        self.initial_conv = nn.Conv2d(3, 32, kernel_size=7, stride=2, padding=3)
        self.initial_activation = nn.ReLU(inplace=True)
        self.current_planes = 32

        self.stage1 = self._build_stage(32, stride=1)
        self.stage2 = self._build_stage(64, stride=2)
        self.stage3 = self._build_stage(96, stride=2)

        self.final_dropout = None
        if dropout_rate > 0:
            self.final_dropout = nn.Dropout2d(p=dropout_rate)

        self.output_projection = nn.Conv2d(96, feature_dim, kernel_size=1)

        self._initialize_weights()

    def _build_stage(self, planes, stride=1):
        first_block = BottleneckLayer(self.current_planes, planes, self.normalization_type, stride=stride)
        second_block = BottleneckLayer(planes, planes, self.normalization_type, stride=1)
        layers = [first_block, second_block]
        self.current_planes = planes
        return nn.Sequential(*layers)

    def _initialize_weights(self):
        for module in self.modules():
            if isinstance(module, nn.Conv2d):
                nn.init.kaiming_normal_(module.weight, mode="fan_out", nonlinearity="relu")
            elif isinstance(module, (nn.BatchNorm2d, nn.InstanceNorm2d, nn.GroupNorm)):
                if module.weight is not None:
                    nn.init.constant_(module.weight, 1)
                if module.bias is not None:
                    nn.init.constant_(module.bias, 0)

    def forward(self, x):
        # Handle list/tuple inputs
        is_list_input = isinstance(x, tuple) or isinstance(x, list)
        if is_list_input:
            batch_size = x[0].shape[0]
            x = torch.cat(x, dim=0)

        x = self.initial_conv(x)
        x = self.input_norm(x)
        x = self.initial_activation(x)
        x = self.stage1(x)
        x = self.stage2(x)
        x = self.stage3(x)
        x = self.output_projection(x)

        if self.training and self.final_dropout is not None:
            x = self.final_dropout(x)

        if is_list_input:
            x = torch.split(x, [batch_size, batch_size], dim=0)
        return x


