# Reimplementation of KnowledgeGraphViewSet with equivalent logic but different structure

from django.http import JsonResponse
from django_filters import rest_framework as filters
from rest_framework.viewsets import ModelViewSet
from apps.core.decorators.api_permission import HasPermission
from apps.opspilot.models import KnowledgeGraph
from apps.opspilot.serializers.knowledge_graph_serializers import KnowledgeGraphSerializer
from apps.opspilot.tasks import rebuild_graph_community_by_instance
from apps.opspilot.utils.graph_utils import GraphUtils


class KnowledgeGraphFilter(filters.FilterSet):
    name = filters.CharFilter(field_name="name", lookup_expr="icontains")
    knowledge_base_id = filters.NumberFilter(field_name="knowledge_base_id", lookup_expr="exact")


class KnowledgeGraphViewSet(ModelViewSet):
    queryset = KnowledgeGraph.objects.all()
    serializer_class = KnowledgeGraphSerializer
    filterset_class = KnowledgeGraphFilter
    ordering_fields = ("id",)
    ordering = ("-id",)

    def get_permissions(self):
        # Override to apply permission decorators conditionally
        if self.action == "get_details":
            return [HasPermission("knowledge_document-View")()]
        elif self.action == "delete_graph":
            return [HasPermission("knowledge_document-Delete")()]
        elif self.action == "rebuild_graph_community":
            return [HasPermission("knowledge_document-Train, knowledge_document-Set")()]
        return super().get_permissions()

    @staticmethod
    def _prepare_success_response(data):
        return JsonResponse({"result": True, "data": data})

    @staticmethod
    def _prepare_error_response(message, status=400):
        return JsonResponse({"result": False, "message": message}, status=status)

    def get_details(self, request):
        kb_id = request.GET.get("knowledge_base_id")
        graph_obj = KnowledgeGraph.objects.filter(knowledge_base_id=kb_id).first()

        if not graph_obj:
            return self._prepare_success_response({"is_exists": False})

        response_data = {
            "graph": {},
            "graph_id": graph_obj.id,
            "is_exists": True,
            "status": graph_obj.status,
        }

        if graph_obj.status == "pending":
            return self._prepare_success_response(response_data)

        graph_result = GraphUtils.get_graph(graph_obj.id)
        if not graph_result["result"]:
            return JsonResponse(graph_result)

        response_data.update({
            "graph": graph_result["data"],
            "status": graph_obj.status,
        })
        return self._prepare_success_response(response_data)

    def delete_graph(self, request):
        kb_id = request.data.get("knowledge_base_id")
        instance = KnowledgeGraph.objects.filter(knowledge_base_id=kb_id).first()

        if not instance:
            return self._prepare_error_response("Knowledge graph not found")

        if instance.status == "training":
            return self._prepare_error_response("Knowledge graph is training, cannot delete")

        try:
            GraphUtils.delete_graph(instance)
            instance.delete()
            return self._prepare_success_response({})
        except Exception as exc:
            return self._prepare_error_response(str(exc), status=500)

    def rebuild_graph_community(self, request):
        kb_id = request.data.get("knowledge_base_id")
        graph_obj = KnowledgeGraph.objects.filter(knowledge_base_id=kb_id).first()

        if not graph_obj:
            return self._prepare_error_response("Knowledge graph not found")

        if graph_obj.status != "completed":
            return self._prepare_error_response("Knowledge graph is not completed")

        try:
            rebuild_graph_community_by_instance.delay(graph_obj.id)
            return self._prepare_success_response({})
        except Exception as err:
            return self._prepare_error_response(str(err))

import logging
import sys
from typing import Any, Dict

def setup_logger(module_name: str) -> logging.Logger:
    """
    Initialize and return a logger with custom formatting.
    Args:
        module_name: Name used to identify the logger (commonly __name__)
    Returns:
        A configured logging.Logger instance
    """
    log = logging.getLogger(module_name)

    # Avoid duplicate handlers if already set up
    if not log.handlers:
        log.setLevel(logging.DEBUG)

        # Console output handler
        console_handler = logging.StreamHandler(sys.stdout)
        console_handler.setLevel(logging.INFO)

        # Custom format string
        log_format = (
            "(ComfyUI-vLLM-Omni) [%(levelname)s] %(asctime)s "
            "[%(filename)s:%(lineno)d] %(message)s"
        )
        date_format = "%Y-%m-%d %H:%M:%S"
        formatter = logging.Formatter(log_format, datefmt=date_format)
        console_handler.setFormatter(formatter)

        # Attach handler and disable propagation
        log.addHandler(console_handler)
        log.propagate = False

    return log


class SafePrettyPrinter:
    """
    Custom pretty printer that masks sensitive data fields like 'data' and 'url'
    when they contain base64 or long strings.
    """
    def __init__(self):
        self._indent_step = 2

    def _process_dict(self, data: Dict[str, Any]) -> Dict[str, Any]:
        """Return a copy of dict with redacted sensitive fields."""
        result = {}
        for key, value in data.items():
            if key in ("data", "url"):
                if isinstance(value, str):
                    if value.startswith("data:"):
                        parts = value.split(",", 1)
                        result[key] = f"{parts[0]},***"
                    elif value.startswith(("http://", "https://")):
                        result[key] = value
                    elif len(value) > 10:
                        result[key] = value[:10] + "***"
                    else:
                        result[key] = value
                else:
                    result[key] = value
            else:
                result[key] = value
        return result

    def _format_value(self, obj: Any, level: int) -> str:
        """Recursively format an object for display, applying redaction where needed."""
        indent = " " * (level * self._indent_step)

        if isinstance(obj, dict):
            items = []
            processed = self._process_dict(obj)
            for k, v in processed.items():
                formatted_val = self._format_value(v, level + 1)
                items.append(f"{indent}  {repr(k)}: {formatted_val}")
            return "{\n" + ",\n".join(items) + f"\n{indent}}}"
        elif isinstance(obj, list):
            items = []
            for item in obj:
                formatted_val = self._format_value(item, level + 1)
                items.append(f"{indent}  {formatted_val}")
            return "[\n" + ",\n".join(items) + f"\n{indent}]"
        elif isinstance(obj, tuple):
            items = []
            for item in obj:
                formatted_val = self._format_value(item, level + 1)
                items.append(f"{indent}  {formatted_val}")
            return "(\n" + ",\n".join(items) + f"\n{indent})"
        elif isinstance(obj, set):
            items = []
            for item in obj:
                formatted_val = self._format_value(item, level + 1)
                items.append(f"{indent}  {formatted_val}")
            return "{\n" + ",\n".join(items) + f"\n{indent}}"
        else:
            return repr(obj)

    def pprint(self, obj: Any) -> None:
        """Print the formatted and redacted representation of the object."""
        print(self._format_value(obj, 0))


# Instantiate the custom pretty printer
safe_printer = SafePrettyPrinter()


