def _serialize_observation(
    observation: Union[Dict, Tuple, np.ndarray],
    shared_buffer: Union[Dict, Tuple, ShArray]
) -> None:
    """Recursively copy observation data into shared memory buffers."""
    if isinstance(observation, np.ndarray) and isinstance(shared_buffer, ShArray):
        shared_buffer.save(observation)
    elif isinstance(observation, tuple) and isinstance(shared_buffer, tuple):
        for obs_part, buf_part in zip(observation, shared_buffer):
            _serialize_observation(obs_part, buf_part)
    elif isinstance(observation, dict) and isinstance(shared_buffer, dict):
        for key in observation:
            _serialize_observation(observation[key], shared_buffer[key])
    # No-op for mismatched types or non-shared-memory case


class RobocasaSubprocEnvWorker(SubprocEnvWorker):
    """Custom subprocess worker for Robocasa environments.

    Inherits from SubprocEnvWorker and overrides process startup logic.
    Disables shared memory by default due to compatibility issues with dict observations.
    """

    def __init__(self, env_factory: Callable[[], gym.Env], use_shared_memory: bool = False):
        self.parent_pipe, self.child_pipe = Pipe()
        self.use_shmem = use_shared_memory
        self.observation_shmem: Optional[Union[Dict, Tuple, ShArray]] = None

        if self.use_shmem:
            temp_env = env_factory()
            obs_space = temp_env.observation_space
            temp_env.close()
            del temp_env
            self.observation_shmem = _setup_buf(obs_space)

        worker_args = (
            self.parent_pipe,
            self.child_pipe,
            CloudpickleWrapper(env_factory),
            self.observation_shmem,
        )
        self.worker_process = Process(
            target=_robocasa_worker_loop,
            args=worker_args,
            daemon=True
        )
        self.worker_process.start()
        self.child_pipe.close()
        super().__init__(env_factory)


class RobocasaSubprocEnv(SubprocVectorEnv):
    """Vectorized environment wrapper for Robocasa using subprocess isolation.

    Prevents OpenGL/MuJoCo context sharing issues across parallel environments.
    """

    def __init__(self, env_factories: list[Callable[[], gym.Env]], **kwargs: Any) -> None:
        def make_worker(fn: Callable[[], gym.Env]) -> RobocasaSubprocEnvWorker:
            return RobocasaSubprocEnvWorker(fn, use_shared_memory=False)

        super().__init__(env_factories, make_worker, **kwargs)


# --- Internal implementation details below ---

def _robocasa_worker_loop(
    parent_conn: mp_connection.Connection,
    child_conn: mp_connection.Connection,
    env_loader: CloudpickleWrapper,
    obs_buffers: Optional[Union[Dict, Tuple, ShArray]] = None,
) -> None:
    """Main loop executed in subprocess; handles environment commands."""

    # Close unused end of pipe
    parent_conn.close()

    # Instantiate environment
    env = env_loader.data()

    try:
        while True:
            try:
                request_type, payload = child_conn.recv()
            except EOFError:
                child_conn.close()
                break

            # Dispatch based on command type
            handler = _get_command_handler(request_type)
            if handler is None:
                child_conn.close()
                raise NotImplementedError(f"Unsupported command: {request_type}")

            response = handler(env, payload, obs_buffers)
            child_conn.send(response)

    except KeyboardInterrupt:
        child_conn.close()


def _get_command_handler(cmd: str) -> Optional[Callable]:
    """Map command strings to internal handler functions."""
    handlers = {
        "step": _handle_step,
        "reset": _handle_reset,
        "close": _handle_close,
        "render": _handle_render,
        "seed": _handle_seed,
        "getattr": _handle_getattr,
        "setattr": _handle_setattr,
    }
    return handlers.get(cmd)


def _handle_step(
    env: gym.Env,
    action: Any,
    obs_shmem: Optional[Union[Dict, Tuple, ShArray]]
) -> Tuple:
    """Execute step and optionally serialize observation."""
    raw_result = env.step(action)
    if obs_shmem is not None:
        _serialize_observation(raw_result[0], obs_shmem)
        return (None,) + raw_result[1:]
    return raw_result


def _handle_reset(
    env: gym.Env,
    kwargs: Dict[str, Any],
    obs_shmem: Optional[Union[Dict, Tuple, ShArray]]
) -> Union[Tuple, Any]:
    """Reset environment and optionally serialize observation."""
    result = env.reset(**kwargs)

    # Detect whether info dict is included
    has_info = (
        isinstance(result, (list, tuple)) and
        len(result) == 2 and
        isinstance(result[1], dict)
    )

    if has_info:
        obs, info = result
    else:
        obs = result
        info = None

    # Serialize observation if shared memory enabled
    if obs_shmem is not None:
        _serialize_observation(obs, obs_shmem)
        obs = None

    # Return appropriate format
    if info is not None:
        return (obs, info)
    return obs


def _handle_close(env: gym.Env, _, __) -> Any:
    """Close the environment and return result."""
    return env.close()


def _handle_render(env: gym.Env, render_kwargs: Dict, ___) -> Optional[Any]:
    """Render environment if supported."""
    if hasattr(env, 'render'):
        return env.render(**render_kwargs)
    return None


def _handle_seed(env: gym.Env, seed_val: int, ___) -> Optional[int]:
    """Set random seed or fallback to reset."""
    if hasattr(env, 'seed'):
        return env.seed(seed_val)
    env.reset(seed=seed_val)
    return None


def _handle_getattr(env: gym.Env, attr_name: str, ___) -> Any:
    """Safely retrieve attribute from environment."""
    return getattr(env, attr_name) if hasattr(env, attr_name) else None


def _handle_setattr(env: gym.Env, spec: Dict[str, Any], ___) -> None:
    """Set attribute on unwrapped environment."""
    setattr(env.unwrapped, spec["key"], spec["value"])

