def _normalize_legacy_file_path(
    legacy_entry_parts: Tuple[str, ...],
    info_dir_parts: Tuple[str, ...],
) -> str:
    """Transform legacy installed-files.txt paths to modern RECORD format.

    Converts paths relative to the info directory into paths relative to 
    the package root (e.g., site-packages).

    :param legacy_entry_parts: Path components from installed-files.txt
    :param info_dir_parts: Path components of egg-info directory relative to package root
    :returns: Converted path string in modern format
    """
    entry = list(legacy_entry_parts)
    info = list(info_dir_parts)

    # Process leading ".." entries by balancing against info parts
    while entry and entry[0] == "..":
        if not info or info[-1] == "..":
            info.append("..")
        else:
            info.pop()
        entry.pop(0)

    return str(pathlib.Path(*info, *entry))

