        """Determine whether the user is currently authenticated with Steam.

        :return: bool indicating login status
        """
        return self.steam_instance.is_logged_on()

    def GetPlayerSteamLevel(self) -> int:
        """Obtain the player's current Steam level.

        :return: int representing the Steam level
        """
        return self.steam_instance.get_player_steam_level()

