        return ticket_buffer[:ticket_length].hex().upper()

import logging
import optparse
import shutil
import sys
import textwrap
from contextlib import suppress
from typing import Any, Dict, Generator, List, Optional, Tuple
from pip._internal.cli.status_codes import UNKNOWN_ERROR
from pip._internal.configuration import Configuration, ConfigurationError
from pip._internal.utils.misc import redact_auth_from_url, strtobool

logger = logging.getLogger(__name__)


class ImprovedHelpFormatter(optparse.IndentedHelpFormatter):
    """An enhanced help formatter with better formatting and alignment."""

    def __init__(self, *args: Any, **kwargs: Any) -> None:
        # Align help text position for consistency
        kwargs["max_help_position"] = 30
        kwargs["indent_increment"] = 1
        terminal_width, _ = shutil.get_terminal_size()
        kwargs["width"] = max(terminal_width - 2, 60)
        super().__init__(*args, **kwargs)

    def format_option_strings(self, option: optparse.Option) -> str:
        return self._format_option_strings(option)

    def _format_option_strings(
        self,
        option: optparse.Option,
        metavar_template: str = " <{}>",
        separator: str = ", "
    ) -> str:
        """
        Format option strings with optional metavar.

        :param option: The optparse.Option instance
        :param metavar_template: Template for metavar display
        :param separator: Separator between short and long options
        :return: Formatted option string
        """
        parts = []

        # Add short options if available
        if option._short_opts:
            parts.append(option._short_opts[0])

        # Add long options if available
        if option._long_opts:
            parts.append(option._long_opts[0])

        # Insert separator between short and long options
        if len(parts) > 1:
            parts.insert(1, separator)

        # Append metavar if the option takes a value
        if option.takes_value():
            assert option.dest is not None
            metavar = option.metavar or option.dest.lower()
            parts.append(metavar_template.format(metavar.lower()))

        return "".join(parts)

    def format_heading(self, heading: str) -> str:
        """Format section headings."""
        if heading == "Options":
            return ""
        return f"{heading}:\n"

    def format_usage(self, usage: str) -> str:
        """Format usage message with proper spacing."""
        formatted_usage = "\nUsage: {}\n".format(
            self.indent_lines(textwrap.dedent(usage), "  ")
        )
        return formatted_usage

    def format_description(self, description: str) -> str:
        """Format description section."""
        if not description:
            return ""

        # Determine label based on parser type
        label = "Commands" if hasattr(self.parser, "main") else "Description"

        # Clean up whitespace
        cleaned_desc = description.strip("\n ")

        # Indent and reformat
        indented = self.indent_lines(textwrap.dedent(cleaned_desc), "  ")

        return f"{label}:\n{indented}\n"

    def format_epilog(self, epilog: str) -> str:
        """Format epilog section."""
        return epilog if epilog else ""

    def indent_lines(self, text: str, prefix: str) -> str:
        """Add indentation to each line of text."""
        lines = [prefix + line for line in text.split("\n")]
        return "\n".join(lines)


class ConfigAwareHelpFormatter(ImprovedHelpFormatter):
    """Custom help formatter that expands defaults and redacts URLs."""

    def expand_default(self, option: optparse.Option) -> str:
        """Expand default values while redacting sensitive information."""
        default_value = None

        # Get default value from parser if available
        if self.parser is not None:
            assert isinstance(self.parser, ConfigOptionParser)
            self.parser._update_defaults(self.parser.defaults)
            assert option.dest is not None
            default_value = self.parser.defaults.get(option.dest)

        # Get base help text
        help_text = super().expand_default(option)

        # Redact authentication from URL-type options
        if default_value and option.metavar == "URL":
            values_list = default_value if isinstance(default_value, list) else [default_value]

            for val in values_list:
                if isinstance(val, str):
                    redacted = redact_auth_from_url(val)
                    help_text = help_text.replace(val, redacted)

        return help_text


class FlexibleOptionParser(optparse.OptionParser):
    """Enhanced option parser with flexible option group management."""

    def insert_option_group(
        self, index: int, *args: Any, **kwargs: Any
    ) -> optparse.OptionGroup:
        """Insert an option group at a specific position."""
        group = self.add_option_group(*args, **kwargs)
        self.option_groups.pop()
        self.option_groups.insert(index, group)
        return group

    @property
    def all_options(self) -> List[optparse.Option]:
        """Get all options including those in groups."""
        result = self.option_list.copy()
        for group in self.option_groups:
            result.extend(group.option_list)
        return result


class ConfigurationBasedParser(FlexibleOptionParser):
    """Parser that integrates configuration file and environment variable support."""

    def __init__(
        self,
        *args: Any,
        command_name: str,
        isolated_mode: bool = False,
        **kwargs: Any,
    ) -> None:
        self.command_name = command_name
        self.config = Configuration(isolated_mode)
        assert self.command_name
        super().__init__(*args, **kwargs)

    def validate_default(self, option: optparse.Option, key: str, value: Any) -> Any:
        """Validate and convert default values."""
        try:
            return option.check_value(key, value)
        except optparse.OptionValueError as e:
            print(f"Configuration error: {e}")
            sys.exit(3)

    def _get_config_items_in_order(
        self,
    ) -> Generator[Tuple[str, Any], None, None]:
        """Yield configuration items in priority order."""
        priority_order = ["global", self.command_name, ":env:"]

        # Group configuration items by section
        grouped_items: Dict[str, List[Tuple[str, Any]]] = {
            section: [] for section in priority_order
        }

        for config_key, value in self.config.items():
            if not value:
                logger.debug("Skipping empty configuration key '%s'.", config_key)
                continue

            section, key = config_key.split(".", 1)
            if section in priority_order:
                grouped_items[section].append((key, value))

        # Yield items in priority order
        for section in priority_order:
            for key, value in grouped_items[section]:
                yield key, value

    def _apply_configuration_defaults(self, defaults: Dict[str, Any]) -> Dict[str, Any]:
        """Update defaults using configuration sources."""
        self.values = optparse.Values(self.defaults)
        deferred_eval = set()

        for key, value in self._get_config_items_in_order():
            option = self.get_option("--" + key)
            if option is None:
                continue

            assert option.dest is not None

            # Handle different option actions
            if option.action in ("store_true", "store_false"):
                try:
                    value = strtobool(value)
                except ValueError:
                    self.error(
                        f"'{value}' is invalid for '{key}'. Use yes/no, true/false, or 1/0."
                    )
            elif option.action == "count":
                with suppress(ValueError):
                    value = strtobool(value)
                with suppress(ValueError):
                    value = int(value)
                if not isinstance(value, int) or value < 0:
                    self.error(
                        f"'{value}' is invalid for '{key}'. Use non-negative integer or boolean."
                    )
            elif option.action == "append":
                items = value.split()
                value = [self.validate_default(option, key, item) for item in items]
            elif option.action == "callback":
                assert option.callback is not None
                deferred_eval.add(option.dest)
                option_str = option.get_opt_string()
                value = option.convert_value(option_str, value)

                args = option.callback_args or ()
                kwargs = option.callback_kwargs or {}
                option.callback(option, option_str, value, self, *args, **kwargs)
            else:
                value = self.validate_default(option, key, value)

            defaults[option.dest] = value

        # Process deferred evaluations
        for key in deferred_eval:
            defaults[key] = getattr(self.values, key)

        self.values = None
        return defaults

    def get_default_values(self) -> optparse.Values:
        """Override to apply configuration-based defaults."""
        if not self.process_default_values:
            return optparse.Values(self.defaults)

        try:
            self.config.load()
        except ConfigurationError as err:
            self.exit(UNKNOWN_ERROR, str(err))

        updated_defaults = self._apply_configuration_defaults(self.defaults.copy())

        for option in self._get_all_options():
            assert option.dest is not None
            default_val = updated_defaults.get(option.dest)
            if isinstance(default_val, str):
                opt_str = option.get_opt_string()
                updated_defaults[option.dest] = option.check_value(opt_str, default_val)

        return optparse.Values(updated_defaults)

    def report_error(self, message: str) -> None:
        """Print usage and exit with error message."""
        self.print_usage(sys.stderr)
        self.exit(UNKNOWN_ERROR, f"{message}\n")

import json
