# Global encryption instance
_fernet_instance = None


class ExtendedJSONEncoder(json.JSONEncoder):
    """Custom JSON encoder supporting datetime, bytes, and nested structures."""

    def encode_object(self, obj: Any) -> Any:
        # Handle datetime objects
        if isinstance(obj, datetime.datetime):
            return obj.isoformat()

        # Handle byte sequences
        if isinstance(obj, bytes):
            try:
                return obj.decode('utf-8')
            except (UnicodeDecodeError, AttributeError):
                return base64.urlsafe_b64encode(obj).decode('ascii')

        # Recursively process containers
        if isinstance(obj, list):
            return [self.encode_object(item) for item in obj]
        elif isinstance(obj, tuple):
            return tuple(self.encode_object(item) for item in obj)
        elif isinstance(obj, dict):
            return {k: self.encode_object(v) for k, v in obj.items()}

        # Fallback to default encoder
        return super().default(obj)


class StructuredLogFormatter(logging.Formatter):
    """Formats log records into structured JSON with optional encryption."""

    def __init__(self, additional_fields: Optional[Dict[str, Any]] = None):
        super().__init__()
        self._extra_data = additional_fields or {}
        self._reserved_keys = {
            "name", "msg", "args", "levelname", "levelno",
            "pathname", "filename", "module", "exc_info",
            "exc_text", "stack_info", "lineno", "funcName",
            "created", "msecs", "relativeCreated", "thread",
            "threadName", "processName", "process", "taskName",
            "sql", "encrypted_info", "exception"
        }

    def format_record(self, record: logging.LogRecord) -> Dict[str, Any]:
        # Base structured fields
        output = {
            "time": self.formatTime(record, self.datefmt),
            "level": getattr(record, "levelname", "INFO"),
            "msg": record.getMessage()
        }

        # Exception handling
        if record.exc_info:
            output["exception"] = self.formatException(record.exc_info)
        if record.stack_info:
            output["stack_info"] = record.stack_info

        # Function name resolution
        func_name = None
        if hasattr(record, "function_name"):
            func_name = getattr(record, "function_name")
        elif hasattr(record, "funcName"):
            func_name = getattr(record, "funcName")
        if func_name and func_name != "<module>":
            output["function"] = func_name

        # File location info
        if hasattr(record, "pathname") and hasattr(record, "lineno"):
            rel_path = getattr(record, "pathname").removeprefix(os.getcwd()).lstrip(os.sep)
            output["file"] = f"{rel_path}:{getattr(record, 'lineno')}"

        # Module name
        if hasattr(record, "module") and record.module:
            output["module"] = record.module

        # Encrypted info processing
        encrypted_payload = getattr(record, "encrypted_info", "")
        if encrypted_payload:
            raw_json = json.dumps(
                encrypted_payload,
                ensure_ascii=False,
                separators=(',', ':'),
                cls=ExtendedJSONEncoder
            )

            global _fernet_instance
            if _fernet_instance:
                try:
                    encrypted_output = _fernet_instance.encrypt(raw_json)
                except Exception as e:
                    logging.warning(f"Encryption failed: {e}")
                    encrypted_output = raw_json
            else:
                encrypted_output = raw_json

            # Truncate long payloads
            if len(encrypted_output) > 200:
                encrypted_output = (
                    encrypted_output[:100] +
                    "**********" +
                    encrypted_output[-100:]
                )
            output["encrypted_info"] = encrypted_output

        # Add dynamic fields from record
        for key, value in record.__dict__.items():
            if key not in self._reserved_keys:
                output[key] = value

        # Merge extra static fields
        output.update(self._extra_data)

        # Inject request context fields if missing
        if "trace_id" not in output:
            trace = get_req_ctx("trace_id")
            if trace:
                output["trace_id"] = trace

        if "url" not in output:
            path = get_req_ctx("path")
            if path:
                output["url"] = path

        if "method" not in output:
            req_method = get_req_ctx("method")
            if req_method:
                output["method"] = req_method

        return output

    def format(self, record: logging.LogRecord) -> str:
        structured = self.format_record(record)
        return json.dumps(structured, ensure_ascii=False, separators=(",", ":"))


class TqdmStreamHandler(logging.Handler):
    """Logging handler that outputs via tqdm.write() for progress bar compatibility."""

    def __init__(self):
        super().__init__()

    def emit(self, record: logging.LogRecord):
        try:
            message = self.format(record)
            from tqdm import tqdm
            tqdm.write(message)
            self.flush()
        except Exception:
            self.handleError(record)


