def suppress_verbose_logging(app_level: int):
    """Reduces verbosity of noisy external libraries when app is in DEBUG mode."""
    if app_level <= logging.DEBUG:
        for logger_name in VERBOSE_MODULES:
            logging.getLogger(logger_name).setLevel(logging.WARNING)


def configure_console_logging(
    level: int = logging.INFO,
    extra_data: Dict[str, Any] = {},
    encryption_key: str = ""
):
    """Sets up console-based structured logging."""
    global _fernet_instance
    if encryption_key:
        _fernet_instance = FernetEncrypter(encryption_key)

    handler = logging.StreamHandler()
    handler.setFormatter(StructuredLogFormatter(extra_data))

    logging.root.handlers = [handler]
    logging.root.setLevel(level)
    suppress_verbose_logging(level)


def configure_file_logging(
    filename: str,
    directory: str,
    level: int = logging.INFO,
    extra_data: Dict[str, Any] = {},
    encryption_key: str = ""
):
    """Sets up file-based structured logging with timestamped filenames."""
    global _fernet_instance
    if encryption_key:
        _fernet_instance = FernetEncrypter(encryption_key)

    if directory:
        os.makedirs(directory, exist_ok=True)

    formatter = StructuredLogFormatter(extra_data)
    timestamp = datetime.datetime.now()
    filename_full = (
        f"{timestamp.strftime('%Y-%m-%d')}_{filename}_"
        f"{timestamp.strftime('%H%M%S_%f')}.log"
    )

    file_handler = logging.FileHandler(
        os.path.join(directory, filename_full),
        mode="w+"
    )
    file_handler.setFormatter(formatter)

    console_handler = logging.StreamHandler()
    console_handler.setFormatter(formatter)

    logging.root.handlers = [file_handler, console_handler]
    logging.root.setLevel(level)
    suppress_verbose_logging(level)


def configure_tqdm_logging(level: int = logging.INFO):
    """Configures logging to use tqdm-compatible output."""
    handler = TqdmStreamHandler()
    handler.setFormatter(StructuredLogFormatter())
    logging.root.handlers = [handler]
    logging.root.setLevel(level)


def setup_logging(
    name: str = "",
    dir: str = "",
    level: int = logging.INFO,
    extra_data: Dict[str, Any] = {},
    encryption_key: str = ""
):
    """Unified logging initializer: chooses between console/file based on parameters."""
    if name:
        configure_file_logging(name, dir, level, extra_data, encryption_key)
    else:
        configure_console_logging(level, extra_data, encryption_key)

# Dynamically load protocol-specific provider clients

from __future__ import annotations
import importlib
from typing import Optional, TYPE_CHECKING, Type, cast
from ripperdoc.core.config import ProtocolType
from ripperdoc.core.providers.base import ProviderClient
from ripperdoc.utils.log import get_logger

if TYPE_CHECKING:  # pragma: no cover - type checking only
    from ripperdoc.core.providers.anthropic import AnthropicClient  # noqa: F401
    from ripperdoc.core.providers.gemini import GeminiClient  # noqa: F401
    from ripperdoc.core.providers.openai import OpenAIClient  # noqa: F401

logger = get_logger()


def _instantiate_provider(module_name: str, class_name: str, required_extra: str) -> Type[ProviderClient]:
    """Dynamically import and return a provider client class, with helpful error messaging."""
    try:
        module_path = f"ripperdoc.core.providers.{module_name}"
        mod = importlib.import_module(module_path)
        provider_class = cast(Type[ProviderClient], getattr(mod, class_name, None))
        if provider_class is None:
            raise ImportError(f"{class_name} not found in {module_path}")
        return provider_class
    except ImportError as err:
        raise RuntimeError(
            f"{class_name} requires optional dependency group '{required_extra}'. "
            f"Install with `pip install ripperdoc[{required_extra}]`."
        ) from err


def fetch_client_for_protocol(protocol: ProtocolType) -> Optional[ProviderClient]:
    """Return an instantiated provider client based on the specified protocol."""
    if protocol == ProtocolType.ANTHROPIC:
        return _instantiate_provider("anthropic", "AnthropicClient", "anthropic")()
    elif protocol == ProtocolType.OPENAI_COMPATIBLE:
        return _instantiate_provider("openai", "OpenAIClient", "openai")()
    elif protocol == ProtocolType.GEMINI:
        return _instantiate_provider("gemini", "GeminiClient", "gemini")()
    elif protocol == ProtocolType.OAUTH:
        return _instantiate_provider("openai", "OpenAIClient", "openai")()

    logger.warning("[providers] Unsupported protocol", extra={"protocol": protocol})
    return None


__all__ = ["ProviderClient", "fetch_client_for_protocol"]

import hashlib
import logging
import os
from contextlib import contextmanager
from types import TracebackType
from typing import Dict, Generator, Optional, Set, Type, Union
from pip._internal.models.link import Link
from pip._internal.req.req_install import InstallRequirement
from pip._internal.utils.temp_dir import TempDirectory

logger = logging.getLogger(__name__)

@contextmanager
def environment_update(**changes: str) -> Generator[None, None, None]:
    env_vars = os.environ
    sentinel = object()
    previous_values: Dict[str, Union[object, str]] = {}

    # Backup current values and apply updates
    for var_name, new_value in changes.items():
        if var_name in env_vars:
            previous_values[var_name] = env_vars[var_name]
        else:
            previous_values[var_name] = sentinel
        env_vars[var_name] = new_value

    try:
        yield
    finally:
        # Restore original environment state
        for var_name, original_value in previous_values.items():
            if original_value is sentinel:
                del env_vars[var_name]
            else:
                assert isinstance(original_value, str)
                env_vars[var_name] = original_value

@contextmanager
def initialization_build_tracker() -> Generator["BuildMonitor", None, None]:
    tracker_root = os.environ.get("PIP_BUILD_TRACKER")

    with contextlib.ExitStack() as stack:
        if tracker_root is None:
            temp_dir = stack.enter_context(TempDirectory(kind="build-tracker"))
            tracker_root = temp_dir.path
            stack.enter_context(environment_update(PIP_BUILD_TRACKER=tracker_root))
            logger.debug("Build tracking initialized at %s", tracker_root)

        monitor = BuildMonitor(tracker_root)
        stack.enter_context(monitor)
        yield monitor

class Identifier(str):
    """Unique identifier string used by the build monitoring system."""

class BuildMonitor:
    """Prevents an sdist from requesting itself as a setup requirement.

    During sdist preparation, setup requirements are identified within 
    BuildMonitor.monitor(). If a recursive dependency is detected, 
    a LookupError is raised to prevent fork bombs in malicious packages."""

    def __init__(self, location: str) -> None:
        self._location = location
        self._tracked: Dict[Identifier, InstallRequirement] = {}
        logger.debug("Build monitor created: %s", self._location)

    def __enter__(self) -> "BuildMonitor":
        logger.debug("Build monitor activated: %s", self._location)
        return self

    def __exit__(
        self,
        exception_type: Optional[Type[BaseException]],
        exception_value: Optional[BaseException],
        traceback: Optional[TracebackType],
    ) -> None:
        self.terminate()

    def _storage_path(self, identifier: Identifier) -> str:
        digest = hashlib.sha224(identifier.encode()).hexdigest()
        return os.path.join(self._location, digest)

    def register(self, requirement: InstallRequirement, identifier: Identifier) -> None:
        """Add a requirement to the build monitoring system."""
        storage_file = self._storage_path(identifier)

        # Check if already being built (file exists)
        try:
            with open(storage_file) as file_handle:
                existing_data = file_handle.read()
        except FileNotFoundError:
            pass
        else:
            raise LookupError(
                f"{requirement.link} is already under construction: {existing_data}"
            )

        # Verify not already tracked in memory
        assert identifier not in self._tracked

        # Create tracking record
        with open(storage_file, "w", encoding="utf-8") as file_handle:
            file_handle.write(str(requirement))
        self._tracked[identifier] = requirement
        logger.debug("Registered %s in build monitor %r", requirement, self._location)

    def unregister(self, requirement: InstallRequirement, identifier: Identifier) -> None:
        """Remove a requirement from build monitoring."""
        os.unlink(self._storage_path(identifier))
        del self._tracked[identifier]
        logger.debug("Unregistered %s from build monitor %r", requirement, self._location)

    def terminate(self) -> None:
        """Clean up all tracked entries."""
        for identifier, requirement in list(self._tracked.items()):
            self.unregister(requirement, identifier)
        logger.debug("Build monitor deactivated: %r", self._location)

    @contextmanager
    def monitor(self, requirement: InstallRequirement, key: str) -> Generator[None, None, None]:
        """Ensure `key` cannot install itself as a setup requirement.

        Raises:
            LookupError: If `key` was already registered in this or parent context.
        """
        monitor_id = Identifier(key)
        self.register(requirement, monitor_id)
        try:
            yield
        finally:
            self.unregister(requirement, monitor_id)

