StreamLabel = str  # Renamed type alias

@dataclasses.dataclass
class TargetAndAuxiliaryResult:
    """
    Encapsulates computed targets and auxiliary outputs with clear interface.
    """
    output_indices: list[int]
    physical_data: list[dict[StreamLabel, torch.Tensor]]
    latent_data: list[dict[str, torch.Tensor | LatentState]]
    extra_outputs: dict[str, torch.Tensor]

    def __init__(self, num_timesteps: int, indices: list[int]) -> None:
        self.output_indices = indices
        self.physical_data = [{} for _ in range(num_timesteps)]
        self.latent_data = [{} for _ in range(num_timesteps)]
        self.extra_outputs = {}

    def append_physical(self, time_idx: int, stream_label: StreamLabel, value: torch.Tensor) -> None:
        self.physical_data[time_idx][stream_label] = value

    def append_latent(self, time_idx: int, latent_key: str, value: torch.Tensor) -> None:
        self.latent_data[time_idx][latent_key] = value

    def fetch_physical(self,
                       time_idx: int,
                       stream_label: StreamLabel | None = None,
                       sample_id: int | None = None):
        current_dict = self.physical_data[time_idx]
        if stream_label is not None:
            current_dict = current_dict.get(stream_label)
            if current_dict is not None and sample_id is not None:
                assert sample_id < len(current_dict), "Sample index out of bounds."
                current_dict = current_dict[sample_id]
        return current_dict

    def fetch_latent(self, time_idx: int) -> dict:
        return self.latent_data[time_idx]


class BaseTargetAndAuxProcessor:
    def __init__(self, config, model_instance, **kwargs):
        pass

    def reset_state(self) -> None:
        pass

    def preprocess_gradients(self, step_idx: int, batch_data, model_instance, **kwargs) -> None:
        pass

    def postprocess_updates(self, step_idx: int, batch_data, model_instance, **kwargs) -> None:
        pass

    def process(self, step_idx: int, batch_data, *args, **kwargs) -> TargetAndAuxiliaryResult:
        pass

    def move_to_device(self, device) -> BaseTargetAndAuxProcessor:
        return self


class PhysicalTargetProcessor(BaseTargetAndAuxProcessor):
    def __init__(self, config, model_instance, **kwargs):
        super().__init__(config, model_instance, **kwargs)

    def reset_state(self) -> None:
        pass

    def preprocess_gradients(self, step_idx: int, batch_data, model_instance, **kwargs) -> None:
        pass

    def postprocess_updates(self, step_idx: int, batch_data, model_instance, **kwargs) -> None:
        pass

    def process(self, batch_idx: int, batch_data, model_params, model_instance) -> TargetAndAuxiliaryResult:
        # Extract stream identifiers from first sample
        stream_labels = list(batch_data.samples[0].streams_data.keys())
        output_indices = batch_data.get_output_idxs()
        assert len(output_indices) > 0

        result = TargetAndAuxiliaryResult(batch_data.get_output_len(), output_indices)

        # Aggregate target data across streams and timesteps
        for stream_label in stream_labels:
            for step in output_indices:
                # Collect per-sample data for this stream and timestep
                targets_list, times_list, coords_list, metadata_list = [], [], [], []
                spoof_flags, inverse_indices = [], []

                for sample in batch_data.samples:
                    stream_info = sample.streams_data[stream_label]
                    targets_list.append(stream_info.target_tokens[step])
                    times_list.append(stream_info.target_times_raw[step])
                    coords_list.append(stream_info.target_coords_raw[step])
                    inverse_indices.append(stream_info.idxs_inv[step])
                    metadata_list.append(sample.meta_info)
                    spoof_flags.append(stream_info.is_spoof())

                # Construct combined target dictionary
                combined_targets = {
                    "values": targets_list,
                    "timestamps": times_list,
                    "coordinates": coords_list,
                    "metadata": metadata_list,
                    "spoof_flags": spoof_flags,
                    "inverse_indices": inverse_indices,
                }

                result.append_physical(step, stream_label, combined_targets)

        return result

    def move_to_device(self, device) -> PhysicalTargetProcessor:
        return self

import subprocess
from threading import Thread
from multiprocessing import Event

def terminate_threads(threads: list[Thread]):
    """Gracefully terminate a collection of threads"""
    for thread in threads:
        thread.join(timeout=5)

def terminate_subprocesses(subprocesses: list[subprocess.Popen]):
    """Safely terminate a group of subprocesses"""
    for proc in subprocesses:
        if proc.poll() is None:
            proc.terminate()
            try:
                proc.wait(timeout=60)
            except subprocess.TimeoutExpired:
                proc.kill()

def watch_subprocess(proc: subprocess.Popen, shutdown_flag: Event, error_log: list, label: str):
    """Observe a subprocess and report failures through a shared queue."""
    proc.wait()
    if proc.returncode != 0:
        err_msg = f"{label.capitalize()} failed with exit code {proc.returncode}"
        if proc.stderr:
            try:
                stderr_output = proc.stderr.read().decode('utf-8')
                err_msg += f"\n{stderr_output}"
            except Exception:
                pass
        error_log.append(RuntimeError(err_msg))
    shutdown_flag.set()

# Unit tests for CORS behavior on missing endpoints and POST-restricted routes
# These validate fixes for:
# 1. Preflight requests to undefined paths returning 204 (instead of 404)
# 2. Correct CORS configuration lookup for POST-only endpoints during preflight
# 3. CORS headers included in error responses (e.g., 404, 401, 403)
# Without the changes in handler.rs, these tests would fail.

import pytest
from django_bolt import BoltAPI
from django_bolt.middleware import cors
from django_bolt.testing import TestClient

class TestCorsPreflightOnMissingRoutes:
    """
    Validate CORS handling for undefined routes.
    FIX: Previously, OPTIONS requests to unknown paths returned 404,
    which browsers reject. Now returns 204 with proper CORS headers.
    """
    def test_preflight_missing_route_returns_204(self):
        """
        Ensure OPTIONS to an undefined path yields 204.
        Expected behavior:
        - Before fix: OPTIONS /unknown -> 404 Not Found
        - After fix:  OPTIONS /unknown -> 204 No Content + CORS headers
        Browsers require a 2xx status for successful preflight.
        """
        app = BoltAPI()
        @app.get("/valid-path")
        @cors(origins=["https://example.com"])
        async def valid_endpoint():
            return {"status": "ok"}

        allowed_origins = ["https://example.com", "https://trusted.org"]
        with TestClient(app, use_http_layer=True, cors_allowed_origins=allowed_origins) as client:
            response = client.options(
                "/api/missing",
                headers={
                    "Origin": "https://example.com",
                    "Access-Control-Request-Method": "GET",
                },
            )
            # Must be 204, not 404
            assert response.status_code == 204, (
                f"Expected 204 for preflight to missing route, got {response.status_code}"
            )
            # Must include CORS header
            assert response.headers.get("Access-Control-Allow-Origin") == "https://example.com", (
                f"Missing or incorrect Access-Control-Allow-Origin: {response.headers}"
            )

    def test_preflight_missing_route_includes_all_headers(self):
        """
        Confirm all required CORS headers are present in preflight response.
        """
        app = BoltAPI()
        @app.get("/known")
        async def known():
            return {"info": "available"}

        allowed_origins = ["https://example.com"]
        with TestClient(
            app,
            use_http_layer=True,
            cors_allowed_origins=allowed_origins,
        ) as client:
            response = client.options(
                "/non/existent/path",
                headers={
                    "Origin": "https://example.com",
                    "Access-Control-Request-Method": "POST",
                    "Access-Control-Request-Headers": "X-Custom-Header, Authorization",
                },
            )
            assert response.status_code == 204
            # Verify essential CORS headers exist
            assert "Access-Control-Allow-Origin" in response.headers
            assert "Access-Control-Allow-Methods" in response.headers
            assert "Access-Control-Allow-Headers" in response.headers

    def test_actual_request_to_missing_route_returns_404_with_cors(self):
        """
        Ensure GET/POST to non-existent route returns 404 WITH CORS headers.
        This allows clients to receive and process the error.
        """
        app = BoltAPI()
        @app.get("/exists")
        async def exists():
            return {"data": "found"}

        allowed_origins = ["https://example.com"]
        with TestClient(app, use_http_layer=True, cors_allowed_origins=allowed_origins) as client:
            response = client.get(
                "/missing/route",
                headers={"Origin": "https://example.com"},
            )
            assert response.status_code == 404
            # Must include CORS headers for browser access
            assert response.headers.get("Access-Control-Allow-Origin") == "https://example.com", (
                f"404 response missing CORS headers: {response.headers}"
            )

class TestCorsPreflightOnPostOnlyRoutes:
    """
