    FIX: Previously, preflight only checked GET routes for CORS config.
    Now checks all supported methods (GET, POST, PUT, PATCH, DELETE).
    """
    def test_preflight_post_only_route_has_cors_headers(self):
        """
        Ensure OPTIONS to POST-only route returns CORS headers.
        Expected behavior:
        - Before fix: Only checked GET routes for CORS config
        - After fix: Checks GET, POST, PUT, PATCH, DELETE in order
