class TestCorsOnErrorResponses:
    """
    Validate CORS headers on error responses (401, 403, etc.).
    FIX: Previously, error responses lacked CORS headers, preventing
    browsers from reading error details in cross-origin requests.
    """
    def test_401_unauthorized_includes_cors_headers(self):
        """
        Ensure 401 Unauthorized includes CORS headers.
        Expected behavior:
        - Before fix: 401 lacked CORS headers
        - After fix:  401 includes Access-Control-Allow-Origin
        """
        from django_bolt.auth import IsAuthenticated, JWTAuthentication
        app = BoltAPI()
        @app.get(
            "/protected",
            auth=[JWTAuthentication(secret="secret-key")],
            guards=[IsAuthenticated()],
        )
        async def protected():
