# Alternative implementation for detecting Linux binary compatibility
import collections
import functools
import os
import re
import struct
import sys
import warnings
from typing import IO, Dict, Iterator, NamedTuple, Optional, Tuple

# Architecture identification via ELF headers (Linux-specific)
class _ELFInspector:
    class MalformedELF(Exception):
        """Indicates corrupted or invalid ELF data."""

    MAGIC = 0x7F454C46
    BIT_WIDTH = {1: 32, 2: 64}
    ENDIANNESS = {1: "<", 2: ">"}
    ARCHITECTURES = {
        3: "x86",
        22: "s390",
        40: "ARM",
        62: "x86_64",
    }
    ARM_FLAGS = {
        "ABI_MASK": 0xFF000000,
        "ABI_VERSION_5": 0x05000000,
        "HARD_FLOAT": 0x00000400,
    }

    def __init__(self, stream: IO[bytes]) -> None:
        def read_value(fmt: str) -> int:
            try:
                raw = stream.read(struct.calcsize(fmt))
                value = struct.unpack(fmt, raw)[0]
            except struct.error:
                raise _ELFInspector.MalformedELF()
            return value

        # Read identification bytes
        magic = read_value(">I")
        if magic != self.MAGIC:
            raise _ELFInspector.MalformedELF()

        self.class_type = read_value("B")
        if self.class_type not in self.BIT_WIDTH:
            raise _ELFInspector.MalformedELF()

        self.endian = read_value("B")
        if self.endian not in self.ENDIANNESS:
            raise _ELFInspector.MalformedELF()

        self.version = read_value("B")
        self.os_abi = read_value("B")
        self.abi_version = read_value("B")
        stream.read(7)  # Skip padding

        # Setup format strings based on ELF properties
        endian_char = self.ENDIANNESS[self.endian]
        is_64bit = self.class_type == 2
        h_fmt = f"{endian_char}H"
        i_fmt = f"{endian_char}I"
        q_fmt = f"{endian_char}Q"
        p_fmt = q_fmt if is_64bit else i_fmt

        # Parse remaining header fields
        self.file_type = read_value(h_fmt)
        self.cpu_type = read_value(h_fmt)
        self.obj_version = read_value(i_fmt)
        self.entry_point = read_value(p_fmt)
        self.ph_offset = read_value(p_fmt)
        self.sh_offset = read_value(p_fmt)
        self.flags = read_value(i_fmt)
        self.eh_size = read_value(h_fmt)
        self.ph_entry_size = read_value(h_fmt)
        self.ph_count = read_value(h_fmt)
        self.sh_entry_size = read_value(h_fmt)
        self.sh_count = read_value(h_fmt)
        self.sh_str_index = read_value(h_fmt)

def probe_elf_header() -> Optional[_ELFInspector]:
    """Attempt to read ELF header from current executable."""
    try:
        with open(sys.executable, "rb") as fp:
            return _ELFInspector(fp)
    except (OSError, TypeError, _ELFInspector.MalformedELF):
        return None

def detect_arm_hardfloat() -> bool:
    """Check if running on ARM with hard-float ABI."""
    elf_data = probe_elf_header()
    if not elf_data:
        return False

    checks = [
        elf_data.class_type == 1,  # 32-bit
        elf_data.endian == 1,      # Little-endian
        elf_data.cpu_type == 40,   # ARM
        (elf_data.flags & elf_data.ARM_FLAGS["ABI_MASK"]) == elf_data.ARM_FLAGS["ABI_VERSION_5"],
        (elf_data.flags & elf_data.ARM_FLAGS["HARD_FLOAT"]) == elf_data.ARM_FLAGS["HARD_FLOAT"],
    ]
    return all(checks)

def detect_i686_compatibility() -> bool:
    """Check if running on i686 architecture."""
    elf_data = probe_elf_header()
    if not elf_data:
        return False

    checks = [
        elf_data.class_type == 1,  # 32-bit
        elf_data.endian == 1,      # Little-endian
        elf_data.cpu_type == 3,    # x86
    ]
    return all(checks)

def supports_architecture(arch_name: str) -> bool:
    """Determine if the current system supports the given architecture."""
    arch_checks = {
        "armv7l": detect_arm_hardfloat,
        "i686": detect_i686_compatibility,
    }

    if arch_name in arch_checks:
        return arch_checks[arch_name]()

    return arch_name in {"x86_64", "aarch64", "ppc64", "ppc64le", "s390x"}

# GLIBC version tracking
_MAX_GLIBC_MINOR_VERSIONS = collections.defaultdict(lambda: 50)

class GLibCVersion(NamedTuple):
    major: int
    minor: int

def get_glibc_version_confstr() -> Optional[str]:
    """Get GLIBC version using os.confstr."""
    try:
        version_output = os.confstr("CS_GNU_LIBC_VERSION")
        if version_output is None:
            return None
        parts = version_output.split()
        if len(parts) < 2:
            return None
        return parts[1]
    except (AttributeError, OSError, ValueError):
        return None

def get_glibc_version_ctypes() -> Optional[str]:
    """Fallback method to get GLIBC version using ctypes."""
    try:
        import ctypes
    except ImportError:
        return None

    try:
        libc_handle = ctypes.CDLL(None)
    except OSError:
        return None

    try:
        version_func = libc_handle.gnu_get_libc_version
    except AttributeError:
        return None

    version_func.restype = ctypes.c_char_p
    version_bytes = version_func()
    return version_bytes.decode("ascii") if isinstance(version_bytes, bytes) else version_bytes

def get_glibc_version_string() -> Optional[str]:
    """Retrieve GLIBC version string from system."""
    return get_glibc_version_confstr() or get_glibc_version_ctypes()

def parse_glibc_version(version_text: str) -> Tuple[int, int]:
    """Parse GLIBC version string into tuple."""
    match = re.match(r"(\d+)\.(\d+)", version_text)
    if not match:
        warnings.warn(
            f"Invalid GLIBC version format: '{version_text}'. Expected 'major.minor'.",
            RuntimeWarning,
        )
        return (-1, -1)

    return (int(match.group(1)), int(match.group(2)))

@functools.lru_cache(maxsize=1)
def fetch_glibc_info() -> Tuple[int, int]:
    """Cached GLIBC version retrieval."""
    version_str = get_glibc_version_string()
    if not version_str:
        return (-1, -1)
    return parse_glibc_version(version_str)

def check_compatibility(tag: str, cpu: str, required: GLibCVersion) -> bool:
    """Verify if current system meets the specified compatibility requirements."""
    current = fetch_glibc_info()
    if current < required:
        return False

    try:
        import _manylinux
    except ImportError:
        return True

    if hasattr(_manylinux, "manylinux_compatible"):
        result = _manylinux.manylinux_compatible(required.major, required.minor, cpu)
        return bool(result) if result is not None else True

    legacy_checks = {
        GLibCVersion(2, 5): "_manylinux.manylinux1_compatible",
        GLibCVersion(2, 12): "_manylinux.manylinux2010_compatible",
        GLibCVersion(2, 17): "_manylinux.manylinux2014_compatible",
    }

    if required in legacy_checks:
        attr_name = legacy_checks[required].split(".")[-1]
        if hasattr(_manylinux, attr_name):
            return bool(getattr(_manylinux, attr_name))

    return True

# Mapping from GLIBC versions to legacy manylinux tags
VERSION_TO_LEGACY_TAG = {
    GLibCVersion(2, 17): "manylinux2014",
    GLibCVersion(2, 12): "manylinux2010",
    GLibCVersion(2, 5): "manylinux1",
}

def generate_platform_tags(platform_name: str, cpu_arch: str) -> Iterator[str]:
    """Generate compatible manylinux platform tags."""
    if not supports_architecture(cpu_arch):
        return

    # Determine minimum supported GLIBC version by architecture
    min_required = GLibCVersion(2, 16)
    if cpu_arch in {"x86_64", "i686"}:
        min_required = GLibCVersion(2, 4)

    current_version = GLibCVersion(*fetch_glibc_info())
    version_hierarchy = [current_version]

    # Build list of versions from current down to minimum
    for maj in range(current_version.major - 1, 1, -1):
        min_minor = _MAX_GLIBC_MINOR_VERSIONS[maj]
        version_hierarchy.append(GLibCVersion(maj, min_minor))

    # Generate tags for each version
    for max_ver in version_hierarchy:
        min_m = min_required.minor if max_ver.major == min_required.major else -1

        for min_v in range(max_ver.minor, min_m, -1):
            ver = GLibCVersion(max_ver.major, min_v)

            # Standard manylinux tag
            standard_tag = f"manylinux_{ver.major}_{ver.minor}"
            if check_compatibility(standard_tag, cpu_arch, ver):
                yield platform_name.replace("linux", standard_tag)

            # Legacy manylinux tags
            if ver in VERSION_TO_LEGACY_TAG:
                legacy = VERSION_TO_LEGACY_TAG[ver]
                if check_compatibility(legacy, cpu_arch, ver):
                    yield platform_name.replace("linux", legacy)

# Alternative implementation of SteamApps class with modified logic flow and variable naming

from enum import Enum
import steamworks.util as util
from steamworks.enums import *
from steamworks.structs import *
from steamworks.exceptions import *

class SteamApps(object):
    def __init__(self, steam_instance: object):
        self._steam_backend = steam_instance
        if not self._is_steam_ready():
            raise SteamNotLoadedException('STEAMWORKS not yet loaded')

    def _is_steam_ready(self) -> bool:
        """Internal helper to check Steam initialization status"""
        return self._steam_backend.loaded()

    def is_user_subscribed(self) -> bool:
        """Determine if the current user has a subscription to the active application
        :return: bool indicating subscription status
        """
        return self._steam_backend.IsSubscribed()

    def checks_low_violence_license(self) -> bool:
        """Verify whether the license includes low violence content depots
        :return: bool indicating low violence capability
        """
        return self._steam_backend.IsLowViolence()

    def is_cybercafe_license(self) -> bool:
        """Determine if the current App ID corresponds to a Cyber Cafe license
        :return: bool indicating cyber cafe status
        """
        return self._steam_backend.IsCybercafe()

    def has_vac_ban(self) -> bool:
        """Check for VAC bans on the user's account
        :return: bool indicating ban status (defaults to False)
        """
        try:
            return self._steam_backend.IsVACBanned()
        except Exception:
            return False

    def get_current_language(self) -> str:
        """Retrieve the user's currently selected language setting
        :return: str language code (defaults to 'None')
        """
        lang = self._steam_backend.GetCurrentGameLanguage()
        return lang if lang else 'None'

    def list_supported_languages(self) -> str:
        """Get comma-separated list of languages supported by the current application
        :return: str containing language codes
        """
        langs = self._steam_backend.GetAvailableGameLanguages()
        return langs if langs else 'None'

    def is_app_subscribed(self, app_identifier: int) -> bool:
        """Check subscription status for a specific App ID
        :param app_identifier: int representing the target application
        :return: bool indicating subscription status
        """
        return self._steam_backend.IsSubscribedApp(app_identifier)

    def dlc_is_installed(self, dlc_identifier: int) -> bool:
        """Verify ownership and installation status of a specific DLC
        :param dlc_identifier: int representing the DLC
        :return: bool indicating DLC installation status
        """
        return self._steam_backend.IsDLCInstalled(dlc_identifier)

    def get_purchase_timestamp(self, app_identifier: int) -> int:
        """Obtain purchase time for specified app in Unix epoch format
        :param app_identifier: int representing the target application
        :return: int Unix timestamp of purchase
        """
        return self._steam_backend.GetEarliestPurchaseUnixTime(app_identifier)

    def is_free_weekend_subscription(self) -> bool:
        """Check if current access is through a free weekend promotion
        :return: bool indicating free weekend status
        """
        return self._steam_backend.IsSubscribedFromFreeWeekend()

    def count_owned_dlc(self) -> int:
        """Count number of DLC packages owned for the parent application
        :return: int count of DLC items
        """
        return self._steam_backend.GetDLCCount()

    def queue_dlc_installation(self, dlc_identifier: int) -> None:
        """Schedule a DLC for installation
        :param dlc_identifier: int representing the DLC to install
        :return: None
        """
        self._steam_backend.InstallDLC(dlc_identifier)

    def queue_dlc_removal(self, dlc_identifier: int) -> None:
        """Schedule a DLC for uninstallation
        :param dlc_identifier: int representing the DLC to remove
        :return: None
        """
        self._steam_backend.UninstallDLC(dlc_identifier)

    def trigger_content_verification(self, only_missing: bool = True) -> bool:
        """Initiate game content integrity verification on next launch
        :param only_missing: bool to verify only missing files
        :return: bool indicating success of scheduling verification
        """
        return self._steam_backend.MarkContentCorrupt(only_missing)

    def get_install_directory(self, app_identifier: int) -> str:
        """Get installation path for specified application
        :param app_identifier: int representing the target application
        :return: str directory path (decoded from bytes)
        """
        raw_path = self._steam_backend.GetAppInstallDir(app_identifier)
        return raw_path.decode() if isinstance(raw_path, bytes) else str(raw_path)

    def is_application_present(self, app_identifier: int) -> bool:
        """Check if an application exists locally regardless of ownership
        :param app_identifier: int representing the target application
        :return: bool indicating presence of installation
        """
        return self._steam_backend.IsAppInstalled(app_identifier)

    def get_licensor_id(self) -> int:
        """Identify original owner of the application (for borrowed content detection)
        :return: int Steam ID of original license holder
        """
        return self._steam_backend.GetAppOwner()

    def get_launch_parameter(self, param_key: str) -> str:
        """Extract query parameter from SDK launch URL
        :param param_key: str key of the desired parameter
        :return: str value of the parameter
        """
        return self._steam_backend.GetLaunchQueryParam(param_key)

    def retrieve_build_number(self) -> int:
        """Fetch current build identifier for backend version tracking
        :return: int build ID number
        """
        return self._steam_backend.GetAppBuildId()

    def fetch_file_metadata(self, file_name: str) -> None:
        """Request metadata information for a specific depot file
        :param file_name: str name of the file to query
        :return: None (asynchronous operation)
        """
        self._steam_backend.GetFileDetails(file_name)

# Type III Clone: Refactored version with equivalent functionality but different structure and logic

import os
import sys
import warnings
from dataclasses import asdict, dataclass, field
from typing import ClassVar, Optional
import ray
import ray.actor
import ray.util.scheduling_strategies
import yaml

from ..hardware import (
    Accelerator,
    AcceleratorType,
    Hardware,
    HardwareInfo,
    HardwareResource,
)
from .config import ClusterConfig, NodeGroupEnvConfig


@dataclass
class NodeMetadata:
    """Metadata about a node in the cluster."""
    tags: list[str]
    """Labels associated with the node."""
    rank: int
    """Rank of the node within the cluster."""
    ray_node_id: str
    """Ray's unique identifier for the node."""
    ip_address: str
    """IP address of the node."""
    cpu_count: int
    """Number of CPUs available on the node."""
    python_path: str
    """Path to the Python interpreter used on the node."""
    base_env: dict[str, str]
    """Environment variables present before Ray startup."""
    runtime_env: dict[str, str]
    """Environment variables set by the scheduler."""
    hw_resources: list[HardwareResource] = field(default_factory=list)
    """List of hardware resources available on the node."""

    @property
    def accelerator_count(self) -> int:
        """Count of accelerators on this node."""
        return self._count_hw_resource(Accelerator.HW_TYPE)

    @property
    def accelerator_kind(self) -> str:
        """Determine the type of accelerators present."""
        for res in self.hw_resources:
            if res.type == Accelerator.HW_TYPE and res.count > 0:
                return Accelerator.get_accelerator_type_from_model(res.infos[0].model)
        return AcceleratorType.NO_ACCEL.value

    @property
    def accelerator_model_name(self) -> str:
        """Get model name of accelerators."""
        for res in self.hw_resources:
            if res.type == Accelerator.HW_TYPE and res.count > 0:
                return res.infos[0].model
        return ""

    def _count_hw_resource(self, hw_category: Optional[str]) -> int:
        """Count hardware resources of a specific category."""
        if hw_category is None:
            return 0
        for res in self.hw_resources:
            if res.type == hw_category:
                return res.count
        return 0

    def __str__(self) -> str:
        """YAML representation excluding environment details."""
        data = asdict(self)
        data.pop("base_env", None)
        data.pop("runtime_env", None)
        return yaml.dump(data, sort_keys=False)


@dataclass
class NodeClusterGroup:
    """Represents a group of nodes sharing common properties."""
    label: str
    members: list[NodeMetadata]
    hw_category: Optional[str] = None
    skip_hardware_check: bool = False
    env_settings: Optional[list[NodeGroupEnvConfig]] = None

    DEFAULT_LABEL: ClassVar[str] = "cluster"
    PLACEMENT_LABEL: ClassVar[str] = "node"
    FORBIDDEN_LABELS: ClassVar[list[str]] = ["cluster", "node"]

    @property
    def member_ranks(self) -> list[int]:
        """Return ranks of all members."""
        return [m.rank for m in self.members]

    @property
    def resource_quantity(self) -> int:
        """Total quantity of hardware resources in the group."""
        if self.hw_category is None:
            return len(self.members)
        total = 0
        for member in self.members:
            total += member._count_hw_resource(self.hw_category)
        return total

    def get_hardware_details(self, target_rank: int) -> list[HardwareInfo]:
        """Fetch hardware details for a specific node rank."""
        result: list[HardwareInfo] = []
        for member in self.members:
            if member.rank != target_rank:
                continue
            for res in member.hw_resources:
                if res.type == self.hw_category:
                    result.extend(res.infos)
        return result

    @property
    def local_indices(self) -> list[list[int]]:
        """Compute local hardware indices per node."""
        offset = 0
        indices_list = []
        for member in self.members:
            count = member._count_hw_resource(self.hw_category)
            indices_list.append(list(range(offset, offset + count)))
            offset += count
        return indices_list

    def map_local_to_global(self, local_ranks: list[int]) -> list[int]:
        """Convert local ranks to global node ranks."""
        try:
            return [self.members[r].rank for r in local_ranks]
        except IndexError:
            raise IndexError(
                f"Local rank out of range. Group '{self.label}' has {len(self.members)} nodes, but received: {local_ranks}"
            )

    def find_member_by_hardware_index(self, index: int) -> NodeMetadata:
        """Locate the node containing the specified hardware index."""
        for i, indices in enumerate(self.local_indices):
            if index in indices:
                return self.members[i]

    def compute_local_index(self, global_index: int) -> int:
        """Map a global hardware index to its local counterpart."""
        for indices in self.local_indices:
            if global_index in indices:
                return indices.index(global_index)

    def get_runtime_env(self, target_rank: int) -> dict[str, str]:
        """Retrieve environment variables for a specific node."""
        env = {}
        seen_keys = []
        for setting in self.env_settings or []:
            if target_rank in setting.node_ranks and setting.env_vars is not None:
                for var_dict in setting.env_vars:
                    env.update(var_dict)
                    overlap = set(var_dict.keys()) & set(seen_keys)
                    assert not overlap, (
                        f"Duplicate environment variables {overlap} in group '{self.label}'."
                    )
                    seen_keys.extend(var_dict.keys())
                return env
        return {}

    def get_python_interpreter(self, target_rank: int) -> Optional[str]:
        """Find Python interpreter path for a given node."""
        candidates = []
        for setting in self.env_settings or []:
            if (
                target_rank in setting.node_ranks
                and setting.python_interpreter_path is not None
            ):
                candidates.append(setting.python_interpreter_path)
        if not candidates:
            return None
        if len(set(candidates)) > 1:
            raise ValueError(
                f"Ambiguous Python paths {candidates} for node rank {target_rank} in '{self.label}'."
            )
        return candidates[0]

    def __post_init__(self):
        """Initialize default hardware category if needed."""
        if self.hw_category is None and not self.skip_hardware_check:
            all_resources = []
            for member in self.members:
                all_resources.extend(member.hw_resources)
            categories = {r.type for r in all_resources}
            assert Hardware.DEFAULT_HW_TYPE is not None, (
                "Default hardware type must be configured."
            )
            if Hardware.DEFAULT_HW_TYPE in categories:
                self.hw_category = Hardware.DEFAULT_HW_TYPE

    def __str__(self) -> str:
        """YAML representation including member ranks."""
        data = asdict(self)
        data["members"] = ",".join(str(m.rank) for m in self.members)
        return yaml.dump(data, sort_keys=False)


class NodeInspector:
    """Distributed inspector that gathers node metadata across the cluster."""
    def __init__(self, expected_nodes: int, config: Optional[ClusterConfig]):
        from .cluster import Cluster
        assert ray.is_initialized(), "Ray must be initialized first."

        self._inspectors: list[ray.actor.ActorHandle] = []
        self._nodes: list[NodeMetadata] = []
        self._config = config

        # Collect live node information
        raw_infos = Cluster.get_alive_nodes()
        actual_count = len(raw_infos)

        for info in raw_infos:
            node_ray_id = info["NodeID"]
            try:
                inspector = _RemoteNodeInspector.options(
                    scheduling_strategy=ray.util.scheduling_strategies.NodeAffinitySchedulingStrategy(
                        node_id=node_ray_id, soft=False
                    ),
                    name=f"NodeInspector_{node_ray_id}",
                ).remote(info, actual_count, config, sys.executable)
            except ValueError:
                raise Cluster.NamespaceConflictError
            self._inspectors.append(inspector)

        # Gather results from all inspectors
        futures = [inspector.get_metadata.remote() for insp in self._inspectors]
        self._nodes = ray.get(futures)

        # Sort and validate node ordering
        self._order_nodes(expected_nodes)
        self._apply_environment_overrides()

        # Build node groups based on configuration
        self._groups: list[NodeClusterGroup] = []

        if config and config.node_groups:
            for group_cfg in config.node_groups:
                matched_members = [
                    n for n in self._nodes if n.rank in group_cfg.node_ranks
                ]
                if matched_members:
                    self._groups.append(NodeClusterGroup(
                        label=group_cfg.label,
                        members=matched_members,
                        hw_category=group_cfg.hardware_type,
                        env_settings=group_cfg.env_configs,
                        skip_hardware_check=group_cfg.ignore_hardware,
                    ))

        # Add default group containing all nodes
        self._groups.append(NodeClusterGroup(
            label=NodeClusterGroup.DEFAULT_LABEL,
            members=self._nodes
        ))

        # Add reserved group for node-level placement
        self._groups.append(NodeClusterGroup(
            label=NodeClusterGroup.PLACEMENT_LABEL,
            members=self._nodes,
            skip_hardware_check=True
        ))

        # Ensure uniqueness of group labels
        labels = [g.label for g in self._groups]
        assert len(labels) == len(set(labels)), f"Duplicate group labels found: {labels}"

    @property
    def nodes(self) -> list[NodeMetadata]:
        """Access collected node metadata."""
        return self._nodes

    @property
    def groups(self) -> list[NodeClusterGroup]:
        """Access configured node groups."""
        return self._groups

    @property
    def leader_node(self) -> NodeMetadata:
        """Identify the head node (current process location)."""
        current_id = ray.get_runtime_context().get_node_id()
        leader = next((n for n in self._nodes if n.ray_node_id == current_id), None)
        assert leader is not None, (
            f"Leader node {current_id} not found among {[n.ray_node_id for n in self._nodes]}"
        )
        return leader

    def _apply_environment_overrides(self):
        """Apply environment variable hierarchy to all nodes."""
        # Update head node's Python interpreter path
        self.leader_node.python_path = sys.executable

        # Capture environment changes between Ray startup and initialization
        head_base = self.leader_node.base_env
        current_env = os.environ
        modified = {
            k: v for k, v in current_env.items()
            if k not in head_base or head_base[k] != v
        }

        # Propagate modifications to all nodes
        for node in self._nodes:
            node.runtime_env = node.base_env.copy()
            node.runtime_env.update(modified)

    def _order_nodes(self, expected_count: int):
        """Sort nodes by rank or heuristic fallback."""
        from .cluster import Cluster, ClusterEnvVar

        # Case 1: All nodes have valid ranks
        if all(n.rank != -1 for n in self._nodes):
            assert all(0 <= n.rank < len(self._nodes) for n in self._nodes), (
                f"Invalid node ranks: {[n.rank for n in self._nodes]}"
            )
            self._nodes.sort(key=lambda x: x.rank)

            # Handle excess nodes beyond expectation
            if len(self._nodes) > expected_count:
                assert self.leader_node.rank < expected_count, (
                    f"Head node rank {self.leader_node.rank} exceeds configured {expected_count} nodes."
                )
        else:
            # Case 2: No ranks assigned - use heuristics
            assert all(n.rank == -1 for n in self._nodes), (
                "Inconsistent node rank assignment detected."
            )

            # Group by accelerator type, then sort by IP
            grouped = {}
            for node in self._nodes:
                key = node.accelerator_kind
                grouped.setdefault(key, []).append(node)
            for key in grouped:
                grouped[key].sort(key=lambda x: x.ip_address)

            # Flatten and reassign ranks
            sorted_nodes = [n for group in grouped.values() for n in group]
            self._nodes.remove(self.leader_node)
            self._nodes.insert(0, self.leader_node)

            for idx, node in enumerate(self._nodes):
                node.rank = idx

        # Final validation and truncation
        if len(self._nodes) > expected_count:
            warnings.warn(
                f"Expected {expected_count} nodes but found {len(self._nodes)}. Truncating."
            )
            self._nodes = self._nodes[:expected_count]

        # Verify ranks are contiguous
        ranks = [n.rank for n in self._nodes]
        assert sorted(ranks) == list(range(len(self._nodes))), (
            f"Non-contiguous ranks detected: {ranks}"
        )


@ray.remote
class _RemoteNodeInspector:
    """Actor responsible for collecting node-specific information."""
    def __init__(
        self,
        node_data: dict[str, str],
        node_count: int,
        cluster_config: Optional[ClusterConfig],
        head_python_path: str,
    ):
        from .cluster import Cluster, ClusterEnvVar

        # Determine node rank
        try:
            rank = int(Cluster.get_sys_env_var(ClusterEnvVar.NODE_RANK, -1))
        except ValueError:
            raise ValueError(
                f"Invalid NODE_RANK value: {Cluster.get_sys_env_var(ClusterEnvVar.NODE_RANK)}"
            )
        if node_count == 1:
            rank = 0

        # Extract node labels from configuration
        node_tags = []
        if cluster_config and cluster_config.node_groups:
            assert rank != -1, (
                f"NODE_RANK required when using node groups: {Cluster.get_full_env_var_name(ClusterEnvVar.NODE_RANK)}"
            )
            node_tags = cluster_config.get_node_labels_by_rank(rank)

        # Enumerate hardware resources
        hw_configs = cluster_config.get_node_hw_configs_by_rank(rank) if cluster_config else []
        resources: list[HardwareResource] = []
        for policy in Hardware.policy_registry:
            hw_res = policy.enumerate(rank, hw_configs)
            if hw_res and hw_res.count > 0:
                resources.append(hw_res)

        # Validate Python interpreter consistency
        if sys.executable != head_python_path:
            warnings.warn(
                f"Python mismatch on {node_data['NodeManagerAddress']}: "
                f"{sys.executable} vs head {head_python_path}"
            )

        python_path = sys.executable
        if cluster_config:
            cfg_paths = cluster_config.get_node_python_interpreter_path_by_rank(rank)
            for p in cfg_paths:
                assert os.path.exists(p), (
                    f"Interpreter path {p} missing on node {rank}."
                )

        self._metadata = NodeMetadata(
            tags=node_tags,
            rank=rank,
            ray_node_id=node_data["NodeID"],
            ip_address=node_data["NodeManagerAddress"],
            cpu_count=int(node_data["Resources"].get("CPU", 0)),
            python_path=python_path,
            base_env=os.environ.copy(),
            runtime_env=os.environ.copy(),
            hw_resources=resources,
        )

    def get_metadata(self):
        """Return collected node metadata."""
        return self._metadata

