def ceil_div(x, y):
    """Compute ceiling division: (x + y - 1) // y"""
    return (x + y - 1) // y

def align_memory_size(tensor_size_bytes, n_cols, alignment):
    """Align memory size to specified byte boundary"""
    aligned_bytes = ceil_div(tensor_size_bytes * n_cols, alignment) * alignment
    return aligned_bytes // tensor_size_bytes

@triton.jit
def safe_load_1d(ptr, skip_check: tl.constexpr, mask: tl.tensor, default=0):
    """Load with optional boundary checking"""
    if not skip_check:
        return tl.load(ptr, mask, other=default)
    else:
        return tl.load(ptr)

@triton.jit
def safe_store_1d(ptr, value, skip_check: tl.constexpr, mask: tl.tensor):
    """Store with optional boundary checking"""
    if not skip_check:
        tl.store(ptr, value, mask)
    else:
        tl.store(ptr, value)

def cache_latest_result(func: Callable[..., torch.Tensor]) -> Callable[..., torch.Tensor]:
    """
    Decorator implementing single-entry caching for functions with tensor inputs.
    Stores only the most recent computation result and reuses it when inputs match exactly.
    """
    cached_inputs = None
    cached_kwargs = None
    cached_output = None

    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        nonlocal cached_inputs, cached_kwargs, cached_output

        # Check if we can reuse cached result
        if cached_inputs is not None and cached_kwargs is not None:
            if len(args) == len(cached_inputs) and len(kwargs) == len(cached_kwargs):
                args_match = all(a is b for a, b in zip(args, cached_inputs))
                kwargs_match = all(
                    k in cached_kwargs and v is cached_kwargs[k] 
                    for k, v in kwargs.items()
                )
                if args_match and kwargs_match:
                    return cached_output

        # Compute new result
        output = func(*args, **kwargs)
        cached_inputs, cached_kwargs, cached_output = args, kwargs, output
        return output

    return wrapper

def prepare_inputs(
    *,
    enforce_contiguous: bool = True,
    auto_assign_device: bool = True,
) -> Callable[[Callable[..., torch.Tensor]], Callable[..., torch.Tensor]]:
    """
    Decorator to optionally make inputs contiguous and set device context.
    """
    def decorator(func: Callable[..., torch.Tensor]) -> Callable[..., torch.Tensor]:
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            # Make tensors contiguous if requested
            if enforce_contiguous:
                processed_args = tuple(
                    a.contiguous() if isinstance(a, torch.Tensor) else a 
                    for a in args
                )
                processed_kwargs = {
                    k: (v.contiguous() if isinstance(v, torch.Tensor) else v) 
                    for k, v in kwargs.items()
                }
            else:
                processed_args = args
                processed_kwargs = kwargs

            # Find first tensor to determine device
            first_tensor = None
            for arg in processed_args:
                if isinstance(arg, torch.Tensor):
                    first_tensor = arg
                    break
            if first_tensor is None:
                for val in processed_kwargs.values():
                    if isinstance(val, torch.Tensor):
                        first_tensor = val
                        break

            # Set device context if needed
            if auto_assign_device and first_tensor is not None:
                device_context = create_device_context(first_tensor.device.index)
            else:
                device_context = null_context()

            with device_context:
                return func(*processed_args, **processed_kwargs)

        return wrapper
    return decorator

