@cache_latest_result
def compute_sequence_lengths(cu_seqlens: torch.LongTensor) -> torch.LongTensor:
    """Calculate sequence lengths from cumulative sequence lengths"""
    return cu_seqlens[1:] - cu_seqlens[:-1]

@cache_latest_result
def compute_chunk_indices(cu_seqlens: torch.LongTensor, chunk_size: int) -> torch.LongTensor:
    """Compute indices for chunked attention processing"""
    seq_lengths = triton.cdiv(compute_sequence_lengths(cu_seqlens), chunk_size)
    total_chunks = seq_lengths.sum()

    # Create flat index array
    flat_indices = torch.arange(total_chunks, device=cu_seqlens.device)

    # Repeat sequence IDs according to number of chunks per sequence
    seq_ids = torch.repeat_interleave(
        torch.arange(seq_lengths.numel(), device=cu_seqlens.device), 
        seq_lengths
    )

    # Calculate offsets within each sequence
    offsets = torch.cumsum(seq_lengths, 0) - seq_lengths

    # Final chunk indices
    relative_indices = flat_indices - offsets[seq_ids]

    # Return [chunk_id, position_in_chunk] pairs
    return torch.stack([
        relative_indices.eq(0).cumsum(0) - 1,
        relative_indices
    ], dim=1)

