        score = min(100, pwd_len * 10)
        level = 'weak' if score < 40 else 'fair' if score < 60 else 'good' if score < 80 else 'strong'
        result = {'score': score, 'level': level, 'feedback': []}

    return success_response(data=result)

@users_v2_bp.route('/api/v2/users', methods=['GET'])
@require_auth(['read:users'])
def retrieve_users():
    """
    List users with filtering capabilities

    Query params:
    - role: Filter by role (admin/operator/viewer)
    - active: Filter by active status (true/false)
    - search: Search username, email, full_name

    SECURITY: Non-admins can only view themselves
    """
    # Restrict access for non-admin users
    if g.current_user.role != 'admin':
        return success_response(data=[g.current_user.to_dict()])

    # Apply filters
    role_filter = request.args.get('role')
    active_param = request.args.get('active')
    search_term = request.args.get('search', '').strip()

    query = User.query

    if role_filter:
        query = query.filter_by(role=role_filter)

    if active_param:
        is_active = active_param.lower() == 'true'
        query = query.filter_by(active=is_active)

    if search_term:
        pattern = f'%{search_term}%'
        query = query.filter(
            db.or_(
                User.username.ilike(pattern),
                User.email.ilike(pattern),
                User.full_name.ilike(pattern)
            )
        )

    users = query.order_by(User.created_at.desc()).all()

    return success_response(
        data=[user.to_dict() for user in users]
    )

@users_v2_bp.route('/api/v2/users', methods=['POST'])
@require_auth(['write:users'])
def register_new_user():
    """
    Create new user account (admin only)

    POST /api/v2/users
    {
        "username": "john.doe",
        "email": "redacted@example.invalid",
        "password": "REDACTED_CREDENTIAL",
        "full_name": "John Doe",
        "role": "operator",
        "permissions": {...}
    }
    """
    # Authorization check
    if g.current_user.role != 'admin':
        return error_response('Insufficient permissions', 403)

    payload = request.get_json()

    # Required fields validation
    if not payload.get('username'):
        return error_response('Username is required', 400)
    if not payload.get('email'):
        return error_response('Email is required', 400)
    if not payload.get('password'):
        return error_response('Password is required', 400)

    # Password security validation
    is_valid, error_msg = check_password_security(payload['password'], username=payload['username'])
    if not is_valid:
        return error_response(error_msg, 400)

    # Check for duplicate credentials
    if User.query.filter_by(username=payload['username']).first():
        return error_response('Username already exists', 409)

    if User.query.filter_by(email=payload['email']).first():
        return error_response('Email already exists', 409)

    # Role validation
    valid_roles = ['admin', 'operator', 'auditor', 'viewer']
    assigned_role = payload.get('role', 'viewer')
    if assigned_role not in valid_roles:
        return error_response(f'Invalid role. Must be one of: {", ".join(valid_roles)}', 400)

    # Custom role validation
    custom_role_id = payload.get('custom_role_id')
    if custom_role_id:
        try:
            from models.rbac import CustomRole
            if not CustomRole.query.get(int(custom_role_id)):
                return error_response('Custom role not found', 404)
            custom_role_id = int(custom_role_id)
        except (ValueError, ImportError):
            custom_role_id = None

    # Create user record
    user = User(
        username=payload['username'],
        email=payload['email'],
        full_name=payload.get('full_name', ''),
        role=assigned_role,
        custom_role_id=custom_role_id,
        active=payload.get('active', True)
    )
    user.set_password(payload['password'])

    try:
        db.session.add(user)
        db.session.commit()

        AuditService.log_action(
            action='user_create',
            resource_type='user',
            resource_id=str(user.id),
            resource_name=user.username,
            details=f'Created user: {user.username} (role: {assigned_role})',
            success=True
        )

        try:
            from websocket.emitters import on_user_created
            on_user_created(user.id, user.username, g.current_user.username)
        except Exception:
            pass

        return created_response(
            data=user.to_dict(),
            message=f'User {user.username} created successfully'
        )
    except Exception as e:
        db.session.rollback()
        return error_response('Failed to create user', 500)

