@users_v2_bp.route('/api/v2/users/<int:user_id>', methods=['PUT'])
@require_auth(['write:users'])
def modify_user_profile(user_id):
    """
    Update existing user profile

    PUT /api/v2/users/{user_id}
    {
        "email": "redacted@example.invalid",
        "full_name": "John Doe Updated",
        "role": "admin",
        "active": true
    }
    """
    # Access control
    if g.current_user.role != 'admin' and g.current_user.id != user_id:
        return error_response('Access denied', 403)

    user = User.query.get(user_id)
    if not user:
        return error_response('User not found', 404)

    payload = request.get_json()

    # Email update with uniqueness check
    if 'email' in payload:
        existing = User.query.filter(User.email == payload['email'], User.id != user_id).first()
        if existing:
            return error_response('Email already in use', 409)
        user.email = payload['email']

    # Full name update
    if 'full_name' in payload:
        user.full_name = payload['full_name']

    # Role change authorization
    if 'role' in payload:
        if g.current_user.role != 'admin':
            return error_response('Only admins can change roles', 403)
        valid_roles = ['admin', 'operator', 'auditor', 'viewer']
        if payload['role'] not in valid_roles:
            return error_response(f'Invalid role. Must be one of: {", ".join(valid_roles)}', 400)
        user.role = payload['role']

    # Custom role assignment
    if 'custom_role_id' in payload:
        if g.current_user.role != 'admin':
            return error_response('Only admins can assign custom roles', 403)
        if payload['custom_role_id']:
            try:
                from models.rbac import CustomRole
                if not CustomRole.query.get(int(payload['custom_role_id'])):
                    return error_response('Custom role not found', 404)
                user.custom_role_id = int(payload['custom_role_id'])
            except (ValueError, ImportError):
                return error_response('Invalid custom role ID', 400)
        else:
            user.custom_role_id = None

    # Active status modification
    if 'active' in payload:
        if g.current_user.role != 'admin':
            return error_response('Only admins can change active status', 403)
        user.active = bool(payload['active'])

    # Password update with security validation
    if 'password' in payload and payload['password']:
        is_valid, error_msg = check_password_security(payload['password'])
        if not is_valid:
            return error_response(error_msg, 400)
        user.set_password(payload['password'])

    try:
        db.session.commit()
        AuditService.log_action(
            action='user_update',
            resource_type='user',
            resource_id=str(user_id),
            resource_name=user.username,
            details=f'Updated user: {user.username}',
            success=True
        )
        return success_response(
            data=user.to_dict(),
            message=f'User {user.username} updated successfully'
        )
    except Exception as e:
        db.session.rollback()
        return error_response('Failed to update user', 500)

