            on_user_deleted(user_id, username, g.current_user.username)
        except Exception:
            pass

        return success_response(
            message=f'User {username} deactivated successfully'
        )
    except Exception as e:
        db.session.rollback()
        import traceback
        traceback.print_exc()
        return error_response('Failed to delete user', 500)

