def handle_error(result, error, trace, models_to_build):
    """Handle errors by filling result with error information."""
    error_detail = (error, trace)
    result["error"] = error_detail
    for framework in FRAMEWORKS:
        if framework in models_to_build:
            result[framework] = {}
            for model_arch in models_to_build[framework]:
                result[framework][model_arch.__name__] = {"model": None, "checkpoint": None, "error": error_detail}
    result["processor"] = {p.__class__.__name__: p.__class__.__name__ for p in result["processor"].values()}


