        GPT2Config,
        GPT2LMHeadModel,
        GPT2Tokenizer,
        GPT2TokenizerFast,
        SpeechEncoderDecoderModel,
        TFEncoderDecoderModel,
        TFVisionEncoderDecoderModel,
        TFVisionTextDualEncoderModel,
        VisionEncoderDecoderModel,
        VisionTextDualEncoderModel,
        ViTConfig,
        ViTFeatureExtractor,
        ViTModel,
        Wav2Vec2Config,
        Wav2Vec2Model,
        Wav2Vec2Processor,
    )

    result = {"error": None, "warnings": []}

    if config_class.model_type == "encoder-decoder":
        encoder_config_class = BertConfig
        decoder_config_class = BertConfig
        encoder_processor = (BertTokenizerFast, BertTokenizer)
        decoder_processor = (BertTokenizerFast, BertTokenizer)
        encoder_class = BertModel
        decoder_class = BertLMHeadModel
        model_class = EncoderDecoderModel
        tf_model_class = TFEncoderDecoderModel
    elif config_class.model_type == "vision-encoder-decoder":
        encoder_config_class = ViTConfig
        decoder_config_class = GPT2Config
        encoder_processor = (ViTFeatureExtractor,)
        decoder_processor = (GPT2TokenizerFast, GPT2Tokenizer)
        encoder_class = ViTModel
        decoder_class = GPT2LMHeadModel
        model_class = VisionEncoderDecoderModel
        tf_model_class = TFVisionEncoderDecoderModel
    elif config_class.model_type == "speech-encoder-decoder":
        encoder_config_class = Wav2Vec2Config
        decoder_config_class = BertConfig
        encoder_processor = (Wav2Vec2Processor,)
        decoder_processor = (BertTokenizerFast, BertTokenizer)
        encoder_class = Wav2Vec2Model
        decoder_class = BertLMHeadModel
        model_class = SpeechEncoderDecoderModel
        tf_model_class = None
    elif config_class.model_type == "vision-text-dual-encoder":
        encoder_config_class = ViTConfig
        decoder_config_class = BertConfig
        encoder_processor = (ViTFeatureExtractor,)
        decoder_processor = (BertTokenizerFast, BertTokenizer)
        encoder_class = ViTModel
        decoder_class = BertModel
        model_class = VisionTextDualEncoderModel
        tf_model_class = TFVisionTextDualEncoderModel
    else:
        result["error"] = ("Unsupported composite model type.", "")
        return result

    with tempfile.TemporaryDirectory() as tmpdir:
        try:
            # Build encoder
            models_to_build = {"processor": encoder_processor, "pytorch": (encoder_class,), "tensorflow": []}
            encoder_output_dir = os.path.join(tmpdir, "encoder")
            build(encoder_config_class, models_to_build, encoder_output_dir)

            # Build decoder
            models_to_build = {"processor": decoder_processor, "pytorch": (decoder_class,), "tensorflow": []}
            decoder_output_dir = os.path.join(tmpdir, "decoder")
            build(decoder_config_class, models_to_build, decoder_output_dir)

            # Build encoder-decoder
            encoder_path = os.path.join(encoder_output_dir, encoder_class.__name__)
            decoder_path = os.path.join(decoder_output_dir, decoder_class.__name__)

            if config_class.model_type != "vision-text-dual-encoder":
                decoder_config = decoder_config_class.from_pretrained(decoder_path)
                decoder_config.is_decoder = True
                decoder_config.add_cross_attention = True
                model = model_class.from_encoder_decoder_pretrained(
                    encoder_path,
                    decoder_path,
                    decoder_config=decoder_config,
                )
            else:
                model = model_class.from_vision_text_pretrained(encoder_path, decoder_path)

            model_path = os.path.join(
                output_dir,
                f"{model_class.__name__}-{encoder_config_class.model_type}-{decoder_config_class.model_type}",
            )
            model.save_pretrained(model_path)

            if tf_model_class is not None:
                model = tf_model_class.from_pretrained(model_path)
                model.save_pretrained(model_path)

            # Copy processors
            encoder_processor_path = os.path.join(encoder_output_dir, "processors")
            decoder_processor_path = os.path.join(decoder_output_dir, "processors")
            if os.path.isdir(encoder_processor_path):
                shutil.copytree(encoder_processor_path, model_path, dirs_exist_ok=True)
            if os.path.isdir(decoder_processor_path):
                shutil.copytree(decoder_processor_path, model_path, dirs_exist_ok=True)

            result["processor"] = {x.__name__: x.__name__ for x in encoder_processor + decoder_processor}
            result["pytorch"] = {model_class.__name__: {"model": model_class.__name__, "checkpoint": model_path}}
            result["tensorflow"] = {}
            if tf_model_class is not None:
                result["tensorflow"] = {
                    tf_model_class.__name__: {"model": tf_model_class.__name__, "checkpoint": model_path}
                }
        except Exception:
            result["error"] = (
                f"Failed to build models for {config_class.__name__}.",
                traceback.format_exc(),
            )

    if not result["error"]:
        del result["error"]
    if not result["warnings"]:
        del result["warnings"]
    return result


def get_token_ids_from_tokenizer(token_id_attr, tokenizer, original_value):
    """Get token IDs from tokenizer."""
    token_id = original_value
    if not token_id_attr.endswith("_token_id"):
        raise ValueError(f"`token_id_attr` is {token_id_attr}, which doesn't end with `_token_id`!")

    token = getattr(tokenizer, token_id_attr.replace("_token_id", "_token"), None)
    if token is not None:
        if isinstance(tokenizer, PreTrainedTokenizerFast):
            token_id = tokenizer._convert_token_to_id_with_added_voc(token)
        else:
            token_id = tokenizer._convert_token_to_id(token)
    return token_id


def get_config_modifications(config_class, processors):
    """Get modifications needed for the config."""
    if config_class.__name__ == "BarkConfig":
        return {}

    config_modifications = {}

    tokenizer = None
    for processor in processors:
        if isinstance(processor, PreTrainedTokenizerFast):
            tokenizer = processor
            break
        elif isinstance(processor, PreTrainedTokenizer):
            tokenizer = processor

    if tokenizer is None:
        return config_modifications

    vocab_size = len(tokenizer)

    if config_class.__name__ == "GPTSanJapaneseConfig":
        vocab_size += 2

    config_modifications["vocab_size"] = vocab_size
    model_tester_kwargs = {"vocab_size": vocab_size}

    if config_class.__name__ == "FSMTConfig":
        del model_tester_kwargs["vocab_size"]
        model_tester_kwargs["src_vocab_size"] = tokenizer.src_vocab_size
        model_tester_kwargs["tgt_vocab_size"] = tokenizer.tgt_vocab_size

    _minimal_config = get_minimal_config(config_class, **model_tester_kwargs)

    if hasattr(_minimal_config, "text_config"):
        _minimal_config = _minimal_config.text_config

    for attr in dir(_minimal_config):
        if attr.endswith("_token_id"):
            token_id = getattr(_minimal_config, attr)
            if token_id is not None:
                token_id = get_token_ids_from_tokenizer(attr, tokenizer, original_value=token_id)
                config_modifications[attr] = token_id

    if config_class.__name__ == "FSMTConfig":
        config_modifications["src_vocab_size"] = tokenizer.src_vocab_size
        config_modifications["tgt_vocab_size"] = tokenizer.tgt_vocab_size
        config_modifications["decoder"] = configuration_fsmt.DecoderConfig(
            vocab_size=tokenizer.tgt_vocab_size, bos_token_id=config_modifications["eos_token_id"]
        )

    return config_modifications


def build(config_class, models_to_build, output_dir):
    """Build all models for a certain model type."""
    if data_store["train"] is None or data_store["test"] is None:
        ds = load_dataset("Salesforce/wikitext", "wikitext-2-raw-v1")
        data_store["train"] = ds["train"]
        data_store["test"] = ds["test"]

    if config_class.model_type in [
        "encoder-decoder",
        "vision-encoder-decoder",
        "speech-encoder-decoder",
        "vision-text-dual-encoder",
    ]:
        return build_composite_models(config_class, output_dir)

    result = {k: {} for k in models_to_build}
    result["error"] = None
    result["warnings"] = []

    processor_classes = models_to_build["processor"]
    if len(processor_classes) == 0:
        error = f"No processor class could be found in {config_class.__name__}."
        handle_error(result, error, None, models_to_build)
        logger.error(result["error"][0])
        return result

    for processor_class in processor_classes:
        try:
            processor = construct_processor(config_class, processor_class, allow_no_checkpoint=True)
            if processor is not None:
                result["processor"][processor_class] = processor
        except Exception:
            error = f"Failed to build processor for {processor_class.__name__}."
            trace = traceback.format_exc()
            handle_error(result, error, trace, models_to_build)
            logger.error(result["error"][0])
            return result

    if len(result["processor"]) == 0:
        error = f"No processor could be built for {config_class.__name__}."
        handle_error(result, error, None, models_to_build)
        logger.error(result["error"][0])
        return result

    try:
        minimal_config = get_minimal_config(config_class)
    except Exception as e:
        error = f"Failed to get minimal config for {config_class.__name__}: {e}"
        trace = traceback.format_exc()
        handle_error(result, error, trace, models_to_build)
        logger.error(result["error"][0])
        return result

    processors = list(result["processor"].values())
    processor_output_folder = os.path.join(output_dir, "processors")
    try:
        processors = transform_processors(processors, minimal_config, processor_output_folder, result)
    except Exception:
        result["warnings"].append(("Failed to convert the processors.", traceback.format_exc()))

    if len(processors) == 0:
        error = f"No processor is returned by `transform_processors` for {config_class.__name__}."
        handle_error(result, error, None, models_to_build)
        logger.error(result["error"][0])
        return result

    try:
        config_modifications = get_config_modifications(config_class, processors)
    except Exception as e:
        error = f"Failure occurs while calling `get_config_modifications`: {e}"
        trace = traceback.format_exc()
        handle_error(result, error, trace, models_to_build)
        logger.error(result["error"][0])
        return result

    if "vocab_size" in config_modifications:
        result["vocab_size"] = config_modifications["vocab_size"]

    for k, v in config_modifications.items():
        if hasattr(minimal_config, k):
            setattr(minimal_config, k, v)
        if hasattr(minimal_config, "text_config") and minimal_config.text_config is not None and hasattr(minimal_config.text_config, k):
            setattr(minimal_config.text_config, k, v)
            if hasattr(minimal_config, "text_config_dict"):
                minimal_config.text_config_dict[k] = v

    if result["warnings"]:
        logger.warning(result["warnings"][0][0])

    result["processor"] = {type(p).__name__: p.__class__.__name__ for p in processors}

    for pytorch_arch in models_to_build["pytorch"]:
        result["pytorch"][pytorch_arch.__name__

import math
from dataclasses import dataclass
from typing import Any

@dataclass
class StatisticalProfile:
    """Statistical profile of a model component."""
    mean: float
    std: float
    min_val: float
    max_val: float
    percentiles: dict[int, float]
    skewness: float
    kurtosis: float
    entropy: float
    zero_ratio: float
    sparsity: float

    def is_anomalous(self, other: "StatisticalProfile", threshold: float = 3.0) -> tuple[bool, float]:
        """Check if another profile is anomalous compared to this one."""
        z_scores = []

        # Mean difference
        if self.std > 0:
            z_scores.append(abs(other.mean - self.mean) / self.std)

        # Standard deviation ratio (using log scale)
        if self.std > 0:
            std_ratio = other.std / self.std
            if std_ratio > 0:
                z_scores.append(abs(math.log(std_ratio)))
            else:
                z_scores.append(threshold)

        # Range difference
        range_self = self.max_val - self.min_val
        range_other = other.max_val - other.min_val
        if range_self > 0:
            z_scores.append(abs(range_other - range_self) / range_self)

        # Distribution shape differences
        z_scores.append(abs(other.skewness - self.skewness))
        z_scores.append(abs(other.kurtosis - self.kurtosis) / 10.0)

        # Sparsity difference
        z_scores.append(abs(other.sparsity - self.sparsity) * 10.0)

        # Calculate composite anomaly score
        try:
            import numpy as np
            anomaly_score = np.mean(z_scores) if z_scores else 0.0
        except ImportError:
            anomaly_score = sum(z_scores) / len(z_scores) if z_scores else 0.0

        return bool(anomaly_score > threshold), float(anomaly_score)


class AnomalyDetector:
    """Detects anomalies in model files using statistical analysis."""

    def __init__(self):
        # Known good profiles for different layer types
        self.layer_profiles = {
            "conv2d_weights": StatisticalProfile(
                mean=0.0,
                std=0.05,
                min_val=-0.3,
                max_val=0.3,
                percentiles={1: -0.15, 5: -0.1, 25: -0.05, 50: 0.0, 75: 0.05, 95: 0.1, 99: 0.15},
                skewness=0.0,
                kurtosis=3.0,
                entropy=7.5,
                zero_ratio=0.01,
                sparsity=0.05,
            ),
            "dense_weights": StatisticalProfile(
                mean=0.0,
                std=0.1,
                min_val=-0.5,
                max_val=0.5,
                percentiles={1: -0.25, 5: -0.2, 25: -0.1, 50: 0.0, 75: 0.1, 95: 0.2, 99: 0.25},
                skewness=0.0,
                kurtosis=3.0,
                entropy=7.6,
                zero_ratio=0.02,
                sparsity=0.1,
            ),
            "attention_weights": StatisticalProfile(
                mean=0.0,
                std=0.02,
                min_val=-0.1,
                max_val=0.1,
                percentiles={1: -0.05, 5: -0.04, 25: -0.02, 50: 0.0, 75: 0.02, 95: 0.04, 99: 0.05},
                skewness=0.0,
                kurtosis=3.0,
                entropy=7.3,
                zero_ratio=0.001,
                sparsity=0.01,
            ),
            "embedding_weights": StatisticalProfile(
                mean=0.0,
                std=0.1,
                min_val=-0.5,
                max_val=0.5,
                percentiles={1: -0.3, 5: -0.2, 25: -0.1, 50: 0.0, 75: 0.1, 95: 0.2, 99: 0.3},
                skewness=0.0,
                kurtosis=3.0,
                entropy=7.7,
                zero_ratio=0.001,
                sparsity=0.02,
            ),
            "batch_norm_weights": StatisticalProfile(
                mean=1.0,
                std=0.1,
                min_val=0.5,
                max_val=1.5,
                percentiles={1: 0.8, 5: 0.85, 25: 0.95, 50: 1.0, 75: 1.05, 95: 1.15, 99: 1.2},
                skewness=0.0,
                kurtosis=3.0,
                entropy=6.5,
                zero_ratio=0.0,
                sparsity=0.0,
            ),
        }

        # Pattern anomaly thresholds
        self.anomaly_thresholds = {
            "weight_distribution": 3.0,
            "activation_pattern": 2.5,
            "gradient_flow": 4.0,
            "layer_connectivity": 2.0,
        }

    def compute_statistical_profile(self, data: Any) -> StatisticalProfile:
        """Compute statistical profile of data."""
        try:
            import numpy as np
            from scipy import stats
        except ImportError:
            return StatisticalProfile(
                mean=0.0,
                std=0.0,
                min_val=0.0,
                max_val=0.0,
                percentiles=dict.fromkeys([1, 5, 25, 50, 75, 95, 99], 0.0),
                skewness=0.0,
                kurtosis=0.0,
                entropy=0.0,
                zero_ratio=1.0,
                sparsity=1.0,
            )

        if data.size == 0:
            return StatisticalProfile(
                mean=0.0,
                std=0.0,
                min_val=0.0,
                max_val=0.0,
                percentiles={p: 0.0 for p in [1, 5, 25, 50, 75, 95, 99]},
                skewness=0.0,
                kurtosis=0.0,
                entropy=0.0,
                zero_ratio=1.0,
                sparsity=1.0,
            )

        flat_data = data.flatten()

        mean = float(np.mean(flat_data))
        std = float(np.std(flat_data))
        min_val = float(np.min(flat_data))
        max_val = float(np.max(flat_data))

        percentiles = {p: float(np.percentile(flat_data, p)) for p in [1, 5, 25, 50, 75, 95, 99]}

        skewness = float(stats.skew(flat_data))
        kurtosis = float(stats.kurtosis(flat_data))

        hist, _ = np.histogram(flat_data, bins=50)
        hist = hist / hist.sum() if hist.sum() > 0 else hist
        nonzero_hist = hist[hist > 0]
        entropy = -float(np.sum(nonzero_hist * np.log2(nonzero_hist))) if len(nonzero_hist) > 0 else 0.0

        zero_ratio = float(np.sum(np.abs(flat_data) < 1e-8) / flat_data.size)
        sparsity = float(1.0 - np.count_nonzero(flat_data) / flat_data.size)

        return StatisticalProfile(
            mean=mean,
            std=std,
            min_val=min_val,
            max_val=max_val,
            percentiles=percentiles,
            skewness=skewness,
            kurtosis=kurtosis,
            entropy=entropy,
            zero_ratio=zero_ratio,
            sparsity=sparsity,
        )

    def detect_weight_anomalies(self, weights: dict[str, Any]) -> dict[str, dict[str, Any]]:
        """Detect anomalies in model weights."""
        anomalies = {}

        for layer_name, weight_data in weights.items():
            layer_type = self._infer_layer_type(layer_name, weight_data.shape)
            actual_profile = self.compute_statistical_profile(weight_data)

            if layer_type in self.layer_profiles:
                expected_profile = self.layer_profiles[layer_type]
                is_anomalous, score = expected_profile.is_anomalous(actual_profile)

                if is_anomalous:
                    anomalies[layer_name] = {
                        "type": "weight_distribution",
                        "severity": self._score_to_severity(score),
                        "score": score,
                        "expected_stats": expected_profile,
                        "actual_stats": actual_profile,
                        "details": self._analyze_anomaly(expected_profile, actual_profile),
                    }

            suspicious_patterns = self._check_suspicious_patterns(weight_data)
            if suspicious_patterns:
                if layer_name not in anomalies:
                    anomalies[layer_name] = {}
                anomalies[layer_name]["suspicious_patterns"] = suspicious_patterns

        return anomalies

    def _infer_layer_type(self, layer_name: str, shape: tuple[int, ...]) -> str:
        """Infer layer type from name and shape."""
        layer_name_lower = layer_name.lower()

        if any(conv in layer_name_lower for conv in ["conv", "convolution"]):
            return "conv2d_weights"
        elif any(dense in layer_name_lower for dense in ["dense", "linear", "fc"]):
            return "dense_weights"
        elif any(attn in layer_name_lower for attn in ["attention", "attn", "query", "key", "value"]):
            return "attention_weights"
        elif any(emb in layer_name_lower for emb in ["embedding", "embed"]):
            return "embedding_weights"
        elif any(bn in layer_name_lower for bn in ["batch_norm", "bn", "batchnorm"]):
            return "batch_norm_weights"

        if len(shape) == 4:
            return "conv2d_weights"
        elif len(shape) == 2:
            return "dense_weights"
        return "dense_weights"

    def _check_suspicious_patterns(self, data: Any) -> list[dict[str, Any]]:
        """Check for specific suspicious patterns in data."""
        try:
            import numpy as np
        except ImportError:
            return []

        suspicious = []

        if not isinstance(data, np.ndarray):
            data = np.asarray(data)

        flat_data = data.flatten()

        if self._contains_executable_signature(flat_data):
            suspicious.append({
                "pattern": "executable_signature",
                "severity": "critical",
                "details": "Data contains executable file signatures",
            })

        if self._contains_encoded_strings(flat_data):
            suspicious.append({
                "pattern": "encoded_strings",
                "severity": "high",
                "details": "Data contains patterns resembling encoded strings",
            })

        if self._has_repeating_patterns(flat_data):
            suspicious.append({
                "pattern": "repeating_pattern",
                "severity": "medium",
                "details": "Unusual repeating patterns detected"
            })

        if self._violates_distribution_laws(flat_data):
            suspicious.append({
                "pattern": "distribution_violation",
                "severity": "medium",
                "details": "Data distribution violates expected statistical laws",
            })

        return suspicious

    def _contains_executable_signature(self, data: Any) -> bool:
        """Check if data contains executable signatures."""
        try:
            import numpy as np
        except ImportError:
            return False

        if data.dtype == np.float32:
            bytes_data = data.tobytes()
            signatures = [b"MZ", b"\x7fELF", b"#!/", b"PK\x03\x04"]
            for sig in signatures:
                if sig in bytes_data:
                    idx = bytes_data.find(sig)
                    if idx >= 0 and idx % 4 == 0:
                        return True
        return False

    def _contains_encoded_strings(self, data: Any) -> bool:
        """Check for patterns that might be encoded strings."""
        try:
            import numpy as np
        except ImportError:
            return False

        if data.dtype == np.float32:
            byte_interpretation = (data * 255).astype(np.int32)
            ascii_printable = np.logical_and(byte_interpretation >= 32, byte_interpretation <= 126)
            ascii_ratio = np.mean(ascii_printable)
            if ascii_ratio > 0.7:
                return True
        return False

    def _has_repeating_patterns(self, data: Any) -> bool:
        """Detect suspicious repeating patterns."""
        try:
            import numpy as np
        except ImportError:
            return False

        if len(data) < 1000:
            return False

        autocorr = np.correlate(data[:1000], data[:1000], mode="full")
        autocorr = autocorr[len(autocorr) // 2:]
        autocorr = autocorr / autocorr[0] if autocorr[0] != 0 else autocorr

        peaks = []
        for i in range(10, min(100, len(autocorr))):
            if autocorr[i] > 0.8:
                peaks.append(i)

        return len(peaks) > 3

    def _violates_distribution_laws(self, data: Any) -> bool:
        """Check if data violates expected distribution laws."""
        try:
            import numpy as np
        except ImportError:
            return False

        abs_data = np.abs(data[data != 0])
        if len(abs_data) > 1000:
            first_digits = []
            for val in abs_data[:1000]:
                val_str = f"{val:.10e}"
                for char in val_str:
                    if char.isdigit() and char != "0":
                        first_digits.append(int(char))
                        break

            if first_digits:
                benford_expected = [np.log10(1 + 1 / d) for d in range(1, 10)]
                digit_counts = np.bincount(first_digits, minlength=10)[1:10]
                digit_freq = digit_counts / digit_counts.sum() if digit_counts.sum() > 0 else digit_counts

                chi2 = float(np.sum((digit_freq - benford_expected) ** 2 / benford_expected))
                if chi2 > 20:
                    return True
        return False

    def _analyze_anomaly(self, expected: StatisticalProfile, actual: StatisticalProfile) -> dict[str, str]:
        """Analyze what makes the profile anomalous."""
        details = {}

        if abs(actual.mean - expected.mean) > 3 * expected.std:
            details["mean_shift"] = f"Mean shifted from {expected.mean:.3f} to {actual.mean:.3f}"

        if expected.std > 0 and (actual.std / expected.std > 2 or actual.std / expected.std < 0.5):
            details["variance_change"] = f"Std changed from {expected.std:.3f} to {actual.std:.3f}"

        if abs(actual.skewness) > 2:
            details["skewness"] = f"High skewness: {actual.skewness:.3f}"

        if actual.kurtosis > 10 or actual.kurtosis < -2:
            details["kurtosis"] = f"Abnormal kurtosis: {actual.kurtosis:.3f}"

        if actual.sparsity > 0.9:
            details["sparsity"] = f"Extremely sparse: {actual.sparsity:.3f}"

        return details

    def _score_to_severity(self, score: float) -> str:
        """Convert anomaly score to severity level."""
        if score < 2:
            return "low"
        elif score < 3:
            return "medium"
        elif score < 5:
            return "high"
        else:
            return "critical"

