def _ensure_directory(path: str) -> None:
    """Ensure directory exists; create if not."""
    os.makedirs(path, exist_ok=True)


def _download_file(url: str, dest_path: str) -> None:
    """Download file from URL to destination path using urllib."""
    import urllib.request
    try:
        urllib.request.urlretrieve(url, dest_path)
        logger.info(f"Successfully downloaded {url} → {dest_path}")
    except Exception as e:
        logger.error(f"Failed to download {url}: {e}")
        raise


class PromptDatasetBase(Dataset):
    """Abstract base class for prompt datasets."""

    def __init__(self, name: str, split: str):
        self.name = name
        self.split = split
        self.prompts: List[str] = []
        self.metadata_list: List[Dict[str, Any]] = []

    def __len__(self) -> int:
        return len(self.prompts)

    def __getitem__(self, idx: int) -> Dict[str, Any]:
        return {"prompt": self.prompts[idx], "metadata": self.metadata_list[idx]}


class TextPromptLoader(PromptDatasetBase):
    """Loads plain text prompts (one per line)."""

    def __init__(self, name: str, split: str):
        super().__init__(name, split)
        base_dir = os.path.join(CACHE_DIR, "diffusion_nft", name)
        _ensure_directory(base_dir)
        ext = ".txt"
        local_file = os.path.join(base_dir, f"{split}{ext}")
        if not os.path.exists(local_file):
            url = DATASET_URL_MAP[name][split]
            _download_file(url, local_file)
        with open(local_file, "r", encoding="utf-8") as f:
            lines = [line.strip() for line in f if line.strip()]
            self.prompts = lines
            self.metadata_list = [{} for _ in lines]


class JSONLMetadataLoader(PromptDatasetBase):
    """Loads prompts + metadata from JSONL files."""

    def __init__(self, name: str, split: str):
        super().__init__(name, split)
        base_dir = os.path.join(CACHE_DIR, "diffusion_nft", name)
        _ensure_directory(base_dir)
        local_file = os.path.join(base_dir, f"{split}_metadata.jsonl")
        if not os.path.exists(local_file):
            url = DATASET_URL_MAP[name][split]
            _download_file(url, local_file)
        with open(local_file, "r", encoding="utf-8") as f:
            entries = [json.loads(line) for line in f if line.strip()]
            self.prompts = [entry.get("prompt", "") for entry in entries]
            self.metadata_list = entries


# Dispatch table for dataset loaders
DATASET_LOADER_REGISTRY: Dict[str, Callable[[str, str], PromptDatasetBase]] = {
    "pickscore": lambda n, s: TextPromptLoader(n, s),
    "ocr": lambda n, s: TextPromptLoader(n, s),
    "dance_grpo_t2v": lambda n, s: TextPromptLoader(n, s),
    "geneval": lambda n, s: JSONLMetadataLoader(n, s),
}


def get_dataset(dataset_config: DatasetConfig) -> Dataset:
    """Factory function to instantiate the correct dataset type."""
    name = dataset_config.name
    if name not in SUPPORTED_DATASETS:
        raise ValueError(f"Unsupported dataset '{name}'. Must be one of {list(SUPPORTED_DATASETS)}")

    split = dataset_config.split[0]  # e.g., ["train"] → "train"
    loader_cls = DATASET_LOADER_REGISTRY[name]
    return loader_cls(name, split)


class DiffusionNFTDataPacker(BaseDataPacker):
    """Custom data packer for DiffusionNFT-style training."""

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)

    def setup(self, config: CosmosConfig, *args, **kwargs):
        super().setup(config, *args, **kwargs)

    def policy_compute_max_len(self, processed_samples: List[Any]) -> int:
        # Placeholder: actual max length computation deferred to downstream
        return 0

    def policy_collate_fn(
        self, processed_samples: List[Any], computed_max_len: int
    ) -> Dict[str, Any]:
        # Placeholder: collation logic handled elsewhere or extended later
        return {}

    def get_rollout_input(
        self,
        completions: Optional[List[Any]] = None,
        completed_conversations: Optional[List[Any]] = None,
        logprobs: Optional[List[Any]] = None,
        token_ids: Optional[List[Any]] = None,
        payload: Optional[RLPayload] = None,
        n_generation: int = 8,
    ):
        if payload is None:
            raise AssertionError("Payload must be provided for rollout input generation.")
        prompts = [payload.prompt["prompt"]] * n_generation
        metadatas = [payload.prompt["metadata"]] * n_generation
        return prompts, metadatas

    def get_policy_input(
        self,
        sample: List[Rollout],
        device: torch.device,
        rollout_output: Union[str, List[int], None] = None,
        n_ignore_prefix_tokens: int = 0,
    ) -> Dict[str, Any]:
        # Process each rollout to enrich extra_info
        for rollout in sample:
            rollout.extra_info["advantages"] = torch.tensor(rollout.advantage, device=device)
            rollout.extra_info["rewards"] = torch.tensor(rollout.reward, device=device)
            rollout.extra_info["prompts"] = rollout.prompt
            rollout.extra_info["completions"] = rollout.completion

        inputs_list = [r.extra_info for r in sample]

        # Collate fields based on their types
        collated = {}
        for key in inputs_list[0].keys():
            values = [item[key] for item in inputs_list]
            first_val = inputs_list[0][key]
            if isinstance(first_val, str):
                collated[key] = values
            elif isinstance(first_val, dict):
                if "prompt" in first_val:
                    collated[key] = [d["prompt"] for d in values]
                else:
                    # Stack nested tensors in metadata dicts
                    sub_keys = first_val.keys()
                    collated[key] = {
                        sk: torch.stack([d[sk] for d in values], dim=0) for sk in sub_keys
                    }
            elif first_val is None:
                collated[key] = None
            else:
                collated[key] = torch.stack(values, dim=0)

        # Ensure advantages has shape [B, 1]
        if collated["advantages"].ndim == 1:
            collated["advantages"] = collated["advantages"].unsqueeze(-1)
        return collated


