    )

# Type III Clone: py2x-checker (restructured with equivalent logic)

import argparse
import json
import re
import subprocess
import sys
import tempfile
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
PY2X_SCRIPT = ROOT / "src" / "py2x.py"
PROFILES_FILE = ROOT / "tools" / "check_py2x_profiles.json"

USER_ERROR_PATTERN = re.compile(r"__PYTRA_USER_ERROR__\|([^|]+)\|([^\r\n]+)")
STAGE2_DEPRECATED_MSG = "--east-stage 2 is no longer supported; use EAST3 (default)."

PHP_SAMPLE_18_PATH = "sample/py/18_mini_language_interpreter.py"
PHP_REQUIRED_FRAGMENTS = [
    '$single_char_token_tags = ["+" => 1',
    "array_key_exists($node->name, $env)",
    "public function __construct($kind, $text, $pos, $number_value)",
    "public function __construct($kind, $value, $name, $op, $left, $right, $kind_tag, $op_tag)",
    "public function __construct($kind, $name, $expr_index, $kind_tag)",
    "function __pytra_entry_main(): void {",
    "__pytra_entry_main();",
]


class ExecutionOutcome:
    def __init__(self, success: bool, msg: str, raw_output: str, category: str):
        self.success = success
        self.message = msg
        self.raw = raw_output
        self.category = category


def _stringify(obj) -> str:
    return obj if isinstance(obj, str) else ""


def _extract_error_category(text: str) -> str:
    match = USER_ERROR_PATTERN.search(text)
    return match.group(1).strip() if match else ""


def _summarize_error(text: str) -> str:
    lines = [line.strip() for line in text.splitlines() if line.strip()]
    if not lines:
        return "unknown error"
    for line in lines:
        m = USER_ERROR_PATTERN.search(line)
        if m:
            return f"{m.group(1)}: {m.group(2)}"
    for line in lines:
        if line.startswith("RuntimeError:"):
            return line
    return lines[0]


def _execute_transpile(*, source_path: Path, output_path: Path, target_lang: str) -> ExecutionOutcome:
    proc = subprocess.run(
        ["python3", str(PY2X_SCRIPT), str(source_path), "--target", target_lang, "-o", str(output_path)],
        cwd=ROOT,
        capture_output=True,
        text=True,
    )
    compat_warn = "warning: --east-stage 2 is compatibility mode; default is 3."
    if proc.returncode == 0 and compat_warn in proc.stderr:
        return ExecutionOutcome(False, "unexpected stage2 compatibility warning in default run", proc.stderr, "")
    if proc.returncode == 0:
        return ExecutionOutcome(True, "", "", "")
    raw = (proc.stderr or "").strip() or (proc.stdout or "").strip()
    return ExecutionOutcome(False, _summarize_error(raw), raw, _extract_error_category(raw))


def _execute_multifile_transpile(*, source_path: Path, output_dir: Path, target_lang: str) -> ExecutionOutcome:
    proc = subprocess.run(
        [
            "python3",
            str(PY2X_SCRIPT),
            str(source_path),
            "--target",
            target_lang,
            "--multi-file",
            "--output-dir",
            str(output_dir),
        ],
        cwd=ROOT,
        capture_output=True,
        text=True,
    )
    compat_warn = "warning: --east-stage 2 is compatibility mode; default is 3."
    if proc.returncode == 0 and compat_warn in proc.stderr:
        return ExecutionOutcome(False, "unexpected stage2 compatibility warning in default run", proc.stderr, "")
    if proc.returncode == 0:
        return ExecutionOutcome(True, "", "", "")
    raw = (proc.stderr or "").strip() or (proc.stdout or "").strip()
    return ExecutionOutcome(False, _summarize_error(raw), raw, _extract_error_category(raw))


def _test_stage2_rejection(*, source_path: Path, output_path: Path, target_lang: str, expected_text: str) -> tuple[bool, str]:
    proc = subprocess.run(
        ["python3", str(PY2X_SCRIPT), str(source_path), "--target", target_lang, "--east-stage", "2", "-o", str(output_path)],
        cwd=ROOT,
        capture_output=True,
        text=True,
    )
    if proc.returncode == 0:
        return False, "unexpected success for --east-stage 2"
    stderr = proc.stderr.strip()
    target = expected_text if expected_text else STAGE2_DEPRECATED_MSG
    if target in stderr:
        return True, ""
    first_line = stderr.splitlines()[0] if stderr else "missing stderr message"
    return False, f"unexpected stage2 error message: {first_line}"


def _run_quality_checks(hook_name: str, rel_path: str, generated_file: Path) -> str:
    if hook_name == "scala_sample01":
        if rel_path != "sample/py/01_mandelbrot.py":
            return ""
        content = generated_file.read_text(encoding="utf-8")
        forbidden_patterns = ["boundary:", "__breakLabel_", "__continueLabel_", "__pytra_int(0L)"]
        for pattern in forbidden_patterns:
            if pattern in content:
                return f"sample/01 quality regression: {pattern} reintroduced"
        typed_casts = ["__pytra_int(height)", "__pytra_int(width)", "__pytra_int(max_iter)"]
        for cast in typed_casts:
            if cast in content:
                return "sample/01 quality regression: typed range bound cast reintroduced"
        return ""
    if hook_name == "php_sample18":
        if rel_path != PHP_SAMPLE_18_PATH:
            return ""
        content = generated_file.read_text(encoding="utf-8")
        for fragment in PHP_REQUIRED_FRAGMENTS:
            if fragment not in content:
                return f"sample18 missing fragment: {fragment}"
        return ""
    if hook_name == "":
        return ""
    return f"unknown quality hook: {hook_name}"


def _load_profiles(profile_path: Path) -> dict:
    try:
        doc = json.loads(profile_path.read_text(encoding="utf-8"))
        profiles_raw = doc.get("profiles")
        if not isinstance(profiles_raw, dict):
            raise RuntimeError("profiles must be an object")
        result = {}
        for key, value in profiles_raw.items():
            if isinstance(key, str) and isinstance(value, dict):
                result[key] = value
        return result
    except Exception as e:
        raise RuntimeError(f"Failed to load profiles: {e}")


def _detect_imports_in_source(path: Path) -> bool:
    content = path.read_text(encoding="utf-8")
    for line in content.splitlines():
        stripped = line.strip()
        if stripped.startswith(("import ", "from ")):
            return True
    return False


def _collect_yanesdk_smoke_tests() -> list[Path]:
    results = []
    lib_file = ROOT / "Yanesdk" / "yanesdk" / "yanesdk.py"
    if lib_file.exists():
        results.append(lib_file)
    docs_root = ROOT / "Yanesdk" / "docs"
    if docs_root.exists():
        py_files = sorted(docs_root.rglob("*.py"))
        filtered = [f for f in py_files if f.name != "yanesdk.py"]
        if filtered:
            results.append(filtered[0])
    return results


def _get_test_cases_from_profile(profile_data: dict) -> list[str]:
    case_mode = _stringify(profile_data.get("case_mode"))
    if case_mode == "all":
        fixtures = sorted((ROOT / "test" / "fixtures").rglob("*.py"))
        samples = sorted((ROOT / "sample" / "py").glob("*.py"))
        paths = [str(p.relative_to(ROOT)).replace("\\", "/") for p in fixtures + samples]
        return paths
    elif case_mode == "explicit":
        cases_raw = profile_data.get("cases", [])
        cases_list = cases_raw if isinstance(cases_raw, list) else []
        valid_cases = [c for c in cases_list if isinstance(c, str) and c.strip()]
        return valid_cases
    else:
        raise RuntimeError(f"Unsupported case_mode: {case_mode}")


def _parse_expected_failures(profile_data: dict) -> dict:
    failures_raw = profile_data.get("expected_failures", {})
    expected_map = {}
    if isinstance(failures_raw, dict):
        for rel, spec in failures_raw.items():
            if isinstance(rel, str) and isinstance(spec, dict):
                expected_map[rel] = {
                    "category": _stringify(spec.get("category")),
                    "contains": _stringify(spec.get("contains")),
                }
    return expected_map


def _validate_runtime_dependencies(profile_data: dict, output_path: Path) -> str:
    required_files = profile_data.get("required_runtime_files", [])
    required_list = required_files if isinstance(required_files, list) else []
    for rel in required_list:
        if isinstance(rel, str) and rel.strip():
            dep_path = output_path.parent / rel
            if not dep_path.exists():
                return f"missing runtime file: {rel}"
    return ""


def _check_runtime_file_contents(profile_data: dict, output_path: Path) -> str:
    required_contains = profile_data.get("required_runtime_file_contains", {})
    if not isinstance(required_contains, dict):
        return ""
    for rel, fragments in required_contains.items():
        if not isinstance(rel, str):
            continue
        side_file = output_path.parent / rel
        if not side_file.exists():
            return f"missing runtime file for contains-check: {rel}"
        content = side_file.read_text(encoding="utf-8")
        fragments_list = fragments if isinstance(fragments, list) else []
        for frag in fragments_list:
            if isinstance(frag, str) and frag.strip() and frag not in content:
                return f"runtime file missing fragment: {rel} :: {frag}"
    return ""


def _scan_forbidden_fragments(profile_data: dict, output_path: Path) -> str:
    forbidden = profile_data.get("forbid_generated_contains", [])
    forbidden_list = forbidden if isinstance(forbidden, list) else []
    if not forbidden_list:
        return ""
    content = output_path.read_text(encoding="utf-8")
    for frag in forbidden_list:
        if isinstance(frag, str) and frag.strip() and frag in content:
            return f"forbidden fragment detected: {frag}"
    return ""


def _run_preflight_checks(profile_data: dict) -> tuple[bool, str]:
    hooks = profile_data.get("preflight_hooks", [])
    hooks_list = hooks if isinstance(hooks, list) else []
    for hook in hooks_list:
        hook_str = _stringify(hook)
        if hook_str == "cpp_emitter_separation":
            cli_path = ROOT / "src" / "backends" / "cpp" / "cli.py"
            if not cli_path.exists():
                return False, "missing cli.py for preflight check"
            content = cli_path.read_text(encoding="utf-8")
            if "class CppEmitter" in content:
                return False, "class CppEmitter must not be implemented in src/backends/cpp/cli.py"
            if "from backends.cpp.emitter import CppEmitter" not in content:
                return False, "missing import from backends.cpp.emitter import CppEmitter"
        elif hook_str == "":
            continue
        else:
            return False, f"unknown preflight hook: {hook_str}"
    return True, ""


def _run_east3_contract_tests(profile_data: dict, *, skip: bool) -> tuple[bool, str]:
    if skip:
        return True, ""
    flags = profile_data.get("flags", {})
    if isinstance(flags, dict) and flags.get("skip_east3_contract_tests", False):
        return True, ""
    test_commands = [
        ["python3", "-m", "unittest", "discover", "-s", "test/unit", "-p", "test_east2_to_east3_lowering.py"],
        ["python3", "-m", "unittest", "discover", "-s", "test/unit", "-p", "test_east3_cpp_bridge.py"],
    ]
    for cmd in test_commands:
        proc = subprocess.run(cmd, cwd=ROOT, capture_output=True, text=True)
        if proc.returncode != 0:
            msg = (proc.stderr or proc.stdout or "east3 contract preflight failed").strip()
            first_line = msg.splitlines()[0] if msg else "unknown error"
            return False, first_line
    return True, ""


def main() -> int:
    parser = argparse.ArgumentParser(description="Validate py2x transpilation using target-specific profiles")
    parser.add_argument("--target", required=True, help="Target language identifier")
    parser.add_argument("--profiles", default=str(PROFILES_FILE), help="Path to JSON profile file")
    parser.add_argument("--include-expected-failures", action="store_true", help="Include expected failure cases")
    parser.add_argument("--cases", default="", help="Comma-separated list of relative source paths")
    parser.add_argument("--skip-east3-contract-tests", action="store_true", help="Skip EAST3 contract tests")
    parser.add_argument("--check-multi-file-imports", action="store_true", help="Enable multi-file checks for imports")
    parser.add_argument("--check-yanesdk-smoke", action="store_true", help="Run Yanesdk smoke tests")
    parser.add_argument("--verbose", action="store_true", help="Print successful files")

    args = parser.parse_args()

    profile_path = Path(args.profiles)
    all_profiles = _load_profiles(profile_path)
    target_id = args.target
    current_profile = all_profiles.get(target_id)
    if not isinstance(current_profile, dict):
        print(f"[FAIL] Target profile not found: {target_id}")
        return 1

    if target_id != "cpp" and (args.check_multi_file_imports or args.check_yanesdk_smoke):
        print("[FAIL] Multi-file and Yanesdk checks only supported for --target cpp")
        return 1

    ok_preflight, preflight_msg = _run_preflight_checks(current_profile)
    if not ok_preflight:
        print(f"[FAIL] {preflight_msg}")
        return 1

    ok_east3, east3_msg = _run_east3_contract_tests(current_profile, skip=args.skip_east3_contract_tests)
    if not ok_east3:
        print(f"[FAIL] {east3_msg}")
        return 1

    test_cases = _get_test_cases_from_profile(current_profile)
    if args.cases.strip():
        test_cases = [c.strip() for c in args.cases.split(",") if c.strip()]

    expected_failures = _parse_expected_failures(current_profile)
    expected_mode = _stringify(current_profile.get("expected_mode"))
    quality_hooks = current_profile.get("quality_hooks", [])
    quality_list = quality_hooks if isinstance(quality_hooks, list) else []
    flags = current_profile.get("flags", {})
    flags_dict = flags if isinstance(flags, dict) else {}
    enable_multi_file = args.check_multi_file_imports or bool(flags_dict.get("check_multi_file", False))
    enable_yanesdk = args.check_yanesdk_smoke or bool(flags_dict.get("check_yanesdk_smoke", False))

    failures = []
    passed_count = 0
    total_count = 0
    skipped_count = 0
    expected_checked = 0
    expected_passed = 0

    sample_sources = sorted((ROOT / "sample" / "py").glob("*.py"))

    with tempfile.TemporaryDirectory() as tmpdir:
        out_file = Path(tmpdir) / f"out.{target_id}"
        for rel_path in test_cases:
            src_path = ROOT / rel_path
            if not src_path.exists():
                failures.append((rel_path, "source not found"))
                continue
            spec = expected_failures.get(rel_path)
            if expected_mode != "validate" and spec and not args.include_expected_failures:
                skipped_count += 1
                continue
            total_count += 1
            outcome = _execute_transpile(source_path=src_path, output_path=out_file, target_lang=target_id)
            if expected_mode == "validate" and spec:
                expected_checked += 1
                if outcome.success:
                    failures.append((rel_path, "unexpected pass (expected failure)"))
                    continue
                cat_expected = spec.get("category", "")
                cont_expected = spec.get("contains", "")
                got_cat = outcome.category or "<none>"
                if cat_expected and got_cat != cat_expected:
                    failures.append((rel_path, f"unexpected error category: expected={cat_expected} got={got_cat} msg={outcome.message}"))
                    continue
                if cont_expected and cont_expected not in outcome.raw:
                    failures.append((rel_path, f"unexpected error detail: expected fragment='{cont_expected}'"))
                    continue
                expected_passed += 1
                passed_count += 1
                if args.verbose:
                    print("OK_EXPECTED_FAIL", rel_path)
                continue
            if not outcome.success:
                failures.append((rel_path, outcome.message))
                continue
            rt_err = _validate_runtime_dependencies(current_profile, out_file)
            if rt_err:
                failures.append((rel_path, rt_err))
                continue
            rt_cont_err = _check_runtime_file_contents(current_profile, out_file)
            if rt_cont_err:
                failures.append((rel_path, rt_cont_err))
                continue
            forbid_err = _scan_forbidden_fragments(current_profile, out_file)
            if forbid_err:
                failures.append((rel_path, forbid_err))
                continue
            quality_issue = ""
            for hook in quality_list:
                hook_name = _stringify(hook)
                err = _run_quality_checks(hook_name, rel_path, out_file)
                if err:
                    quality_issue = err
                    break
            if quality_issue:
                failures.append((rel_path, quality_issue))
                continue
            passed_count += 1
            if args.verbose:
                print("OK", rel_path)

        if target_id == "cpp" and enable_yanesdk:
            yanesdk_paths = _collect_yanesdk_smoke_tests()
            for src in yanesdk_paths:
                rel = str(src.relative_to(ROOT)).replace("\\", "/")
                total_count += 1
                res = _execute_transpile(source_path=src, output_path=out_file, target_lang=target_id)
                if res.success:
                    passed_count += 1
                    if args.verbose:
                        print("OK", rel, "[yanesdk]")
                else:
                    failures.append((f"{rel} [yanesdk]", res.message))

        if target_id == "cpp" and enable_multi_file:
            for src in sample_sources:
                rel = str(src.relative_to(ROOT)).replace("\\", "/")
                if _detect_imports_in_source(src):
                    total_count += 1
                    out_dir = Path(tmpdir) / "multi_out"
                    res = _execute_multifile_transpile(source_path=src, output_dir=out_dir, target_lang=target_id)
                    if res.success:
                        passed_count += 1
                        if args.verbose:
                            print("OK", rel, "[multi-file]")
                    else:
                        failures.append((f"{rel} [multi-file]", res.message))

        stage2_config = current_profile.get("stage2_probe", {})
        if isinstance(stage2_config, dict) and stage2_config.get("enabled", False):
            probe_rel = _stringify(stage2_config.get("source"))
            if not probe_rel and test_cases:
                probe_rel = test_cases[0]
            if probe_rel:
                total_count += 1
                expected_frag = _stringify(stage2_config.get("expected_fragment"))
                good, msg = _test_stage2_rejection(
                    source_path=ROOT / probe_rel,
                    output_path=out_file,
                    target_lang=target_id,
                    expected_text=expected_frag,
                )
                if good:
                    passed_count += 1
                    if args.verbose:
                        print("OK", probe_rel, "[stage2 rejected]")
                else:
                    failures.append((f"{probe_rel} [stage2 rejected]", msg))

    summary = (
        f"checked={total_count} "
        f"ok={passed_count} "
        f"fail={len(failures)} "
        f"skipped={skipped_count} "
        f"expected_fail_checked={expected_checked} "
        f"expected_fail_ok={expected_passed}"
    )
    print(summary)
    if failures:
        for rel, msg in failures:
            print(f"FAIL {rel}: {msg}")
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())

import logging
from collections import defaultdict
from copy import deepcopy
import json_repair
import pandas as pd
import time
import trio
from app.core.rag.common.misc_utils import get_uuid
from app.core.rag.graphrag.query_analyze_prompt import PROMPTS
from app.core.rag.common.token_utils import num_tokens_from_string
from app.core.rag.utils.doc_store_conn import OrderByExpr
from app.core.rag.nlp.search import Dealer, index_name
from app.core.rag.common.float_utils import get_float


class KnowledgeGraphSearch(Dealer):
    def _generate_llm_response(self, llm_backend, system_msg, conversation_history, generation_config):
        from app.core.rag.graphrag.utils import get_llm_cache, set_llm_cache

        cached_result = get_llm_cache(llm_backend.model_name, system_msg, conversation_history, generation_config)
        if cached_result:
            return cached_result

        raw_response = llm_backend.chat(system_msg, conversation_history, generation_config)
        if isinstance(raw_response, tuple):
            raw_response = raw_response[0]

        if "**ERROR**" in raw_response:
            raise Exception(raw_response)

        set_llm_cache(llm_backend.model_name, system_msg, raw_response, conversation_history, generation_config)
        return raw_response

    def expand_query_with_context(self, language_model, user_input, index_names, knowledge_base_ids):
        from app.core.rag.graphrag.utils import get_entity_type2samples

        entity_types_and_examples = trio.run(lambda: get_entity_type2samples(index_names, knowledge_base_ids))
        prompt_hint = PROMPTS["minirag_query2kwd"].format(
            query=user_input,
            TYPE_POOL=json.dumps(entity_types_and_examples, ensure_ascii=False, indent=2)
        )

        llm_output = self._generate_llm_response(
            language_model,
            prompt_hint,
            [{"role": "user", "content": "Output:"}],
            {}
        )

        try:
            parsed_data = json_repair.loads(llm_output)
            answer_types = parsed_data.get("answer_type_keywords", [])
            extracted_entities = parsed_data.get("entities_from_query", [])[:5]
            return answer_types, extracted_entities
        except json_repair.JSONDecodeError:
            try:
                cleaned_output = (
                    llm_output.replace(prompt_hint[:-1], '')
                    .replace('user', '').replace('model', '').strip()
                )
                json_start = cleaned_output.find('{')
                json_end = cleaned_output.rfind('}') + 1
                if json_start >= 0 and json_end > json_start:
                    json_str = cleaned_output[json_start:json_end]
                    parsed_data = json_repair.loads(json_str)
                    answer_types = parsed_data.get("answer_type_keywords", [])
                    extracted_entities = parsed_data.get("entities_from_query", [])[:5]
                    return answer_types, extracted_entities
                else:
                    raise ValueError("No valid JSON found in output")
            except Exception as err:
                logging.exception(f"Failed to parse JSON response: {llm_output} | Error: {err}")
                raise

    def _extract_entity_details(self, search_results, similarity_threshold=0.3):
        result_dict = {}
        required_fields = ["page_content", "_score", "entity_kwd", "rank_flt", "n_hop_with_weight"]
        search_results = self.dataStore.getFields(search_results, required_fields)

        for _, item in search_results.items():
            # Clean up None values
            for field in required_fields:
                if field in item and item[field] is None:
                    del item[field]

            score_val = get_float(item.get("_score", 0))
            if score_val < similarity_threshold:
                continue

            # Normalize entity name if it's a list
            entity_name = item["entity_kwd"]
            if isinstance(entity_name, list):
                entity_name = entity_name[0]

            result_dict[entity_name] = {
                "similarity": score_val,
                "pagerank": get_float(item.get("rank_flt", 0)),
                "neighbor_paths": json.loads(item.get("n_hop_with_weight", "[]")),
                "description": item.get("page_content", "{}")
            }

        return result_dict

    def _extract_relation_details(self, search_results, similarity_threshold=0.3):
        result_dict = {}
        fields_to_fetch = ["page_content", "_score", "from_entity_kwd", "to_entity_kwd", "weight_int"]
        search_results = self.dataStore.getFields(search_results, fields_to_fetch)

        for _, rel_item in search_results.items():
            if get_float(rel_item["_score"]) < similarity_threshold:
                continue

            src, dst = sorted([rel_item["from_entity_kwd"], rel_item["to_entity_kwd"]])
            if isinstance(src, list):
                src = src[0]
            if isinstance(dst, list):
                dst = dst[0]

            pair_key = (src, dst)
            result_dict[pair_key] = {
                "similarity": get_float(rel_item["_score"]),
                "pagerank": get_float(rel_item.get("weight_int", 0)),
                "description": rel_item["page_content"]
            }

        return result_dict

    def find_entities_by_terms(self, keywords, filters, index_names, kb_ids, embedding_model,
                               sim_thresh=0.3, limit=56):
        if not keywords:
            return {}

        updated_filters = deepcopy(filters)
        updated_filters["knowledge_graph_kwd"] = "entity"
        dense_match = self.get_vector(", ".join(keywords), embedding_model, 1024, sim_thresh)

        search_res = self.dataStore.search(
            ["page_content", "entity_kwd", "rank_flt"],
            [], updated_filters, [dense_match],
            OrderByExpr(), 0, limit, index_names, kb_ids
        )
        return self._extract_entity_details(search_res, sim_thresh)

    def find_relations_by_text(self, text_query, filters, index_names, kb_ids, embedding_model,
                               sim_thresh=0.3, limit=56):
        if not text_query:
            return {}

        updated_filters = deepcopy(filters)
        updated_filters["knowledge_graph_kwd"] = "relation"
        dense_match = self.get_vector(text_query, embedding_model, 1024, sim_thresh)

        search_res = self.dataStore.search(
            ["page_content", "_score", "from_entity_kwd", "to_entity_kwd", "weight_int"],
            [], updated_filters, [dense_match], OrderByExpr(), 0, limit, index_names, kb_ids
        )
        return self._extract_relation_details(search_res, sim_thresh)

    def find_entities_by_category(self, categories, filters, index_names, kb_ids, limit=56):
        if not categories:
            return {}

        updated_filters = deepcopy(filters)
        updated_filters["knowledge_graph_kwd"] = "entity"
        updated_filters["entity_type_kwd"] = categories

        order_clause = OrderByExpr()
        order_clause.desc("rank_flt")

        search_res = self.dataStore.search(
            ["entity_kwd", "rank_flt"],
            [], updated_filters, [], order_clause, 0, limit, index_names, kb_ids
        )
        return self._extract_entity_details(search_res, 0)

    def perform_search(self, query: str,
                      workspace_ids: str | list[str],
                      kb_ids: list[str],
                      emb_mdl,
                      llm,
                      max_token_budget: int = 8196,
                      top_entities: int = 6,
                      top_relations: int = 6,
                      top_communities: int = 1,
                      ent_sim_cutoff: float = 0.3,
                      rel_sim_cutoff: float = 0.3,
                      **kwargs):

        original_query = query
        filter_conditions = self.get_filters({"kb_ids": kb_ids})

        if isinstance(workspace_ids, str):
            workspace_ids = workspace_ids.split(",")

        idx_names = [index_name(ws_id) for ws_id in workspace_ids]

        detected_types = []
        candidate_entities = []

        try:
            detected_types, candidate_entities = self.expand_query_with_context(
                llm, original_query, idx_names, kb_ids
            )
            logging.info(f"Query: {original_query}, Detected Types: {detected_types}, Entities: {candidate_entities}")
        except Exception as exc:
            logging.exception(exc)
            candidate_entities = [original_query]

        entities_by_keyword = self.find_entities_by_terms(
            candidate_entities, filter_conditions, idx_names, kb_ids, emb_mdl, ent_sim_cutoff
        )
        entities_by_category = self.find_entities_by_category(
            detected_types, filter_conditions, idx_names, kb_ids, 10000
        )
        relations_by_text = self.find_relations_by_text(
            original_query, filter_conditions, idx_names, kb_ids, emb_mdl, rel_sim_cutoff
        )

        n_hop_connections = defaultdict(dict)

        for _, entity_info in entities_by_keyword.items():
            hops = entity_info.get("neighbor_paths", [])
            if not isinstance(hops, list):
                logging.warning(f"Invalid n-hop path format: {hops}")
                continue

            for neighbor in hops:
                path_nodes = neighbor["path"]
                weights = neighbor["weights"]
                for i in range(len(path_nodes) - 1):
                    node_a, node_b = path_nodes[i], path_nodes[i + 1]
                    key = (node_a, node_b)

                    contribution = entity_info["similarity"] / (2 + i)
                    if key in n_hop_connections:
                        n_hop_connections[key]["similarity"] += contribution
                    else:
                        n_hop_connections[key] = {"similarity": contribution}

                    n_hop_connections[key]["pagerank"] = weights[i]

        logging.info("Found entities via keyword: {}".format(list(entities_by_keyword.keys())))
        logging.info("Found relations via text: {}".format(list(relations_by_text.keys())))
        logging.info("Found entities by category({}): {}".format(detected_types, list(entities_by_category.keys())))
        logging.info("Found N-hop paths: {}".format(list(n_hop_connections.keys())))

        # Boost scores based on overlap with type-based entities
        for ent_name in entities_by_category.keys():
            if ent_name in entities_by_keyword:
                entities_by_keyword[ent_name]["similarity"] *= 2

        # Adjust relation scores using multi-source signals
        for (src, tgt), rel_info in list(relations_by_text.items()):
            canonical_pair = tuple(sorted([src, tgt]))
            boost_score = 0

            if canonical_pair in n_hop_connections:
                boost_score += n_hop_connections[canonical_pair]["similarity"]
                del n_hop_connections[canonical_pair]

            if src in entities_by_category:
                boost_score += 1
            if tgt in entities_by_category:
                boost_score += 1

            rel_info["similarity"] *= (boost_score + 1)

        # Add remaining n-hop relations without explicit query match
        for (src, tgt), hop_info in n_hop_connections.items():
            boost_score = 0
            if src in entities_by_category:
                boost_score += 1
            if tgt in entities_by_category:
                boost_score += 1

            relations_by_text[(src, tgt)] = {
                "similarity": hop_info["similarity"] * (boost_score + 1),
                "pagerank": hop_info["pagerank"]
            }

        # Sort and truncate final results
        ranked_entities = sorted(
            entities_by_keyword.items(),
            key=lambda x: x[1]["similarity"] * x[1]["pagerank"],
            reverse=True
        )[:top_entities]

        ranked_relations = sorted(
            relations_by_text.items(),
            key=lambda x: x[1]["similarity"] * x[1]["pagerank"],
            reverse=True
        )[:top_relations]

        entity_list = []
        relation_list = []

        for name, info in ranked_entities:
            desc_obj = {}
            try:
                desc_obj = json.loads(info["description"])
            except Exception:
                pass

            entity_entry = {
                "Entity": name,
                "Score": "%.2f" % (info["similarity"] * info["pagerank"]),
                "Description": desc_obj.get("description", "") if info["description"] else ""
            }
            entity_list.append(entity_entry)
            max_token_budget -= num_tokens_from_string(str(entity_entry))
            if max_token_budget <= 0:
                entity_list.pop()
                break

        for (src, dst), info in ranked_relations:
            description = info.get("description")
            if not description:
                for ws_id in workspace_ids:
                    from app.core.rag.graphrag.utils import get_relation
                    temp_rel = get_relation(ws_id, kb_ids, src, dst)
                    if temp_rel:
                        description = temp_rel["description"]
                        break
                else:
                    continue

            try:
                parsed_desc = json.loads(description).get("description", "")
            except Exception:
                parsed_desc = description

            rel_entry = {
                "From Entity": src,
                "To Entity": dst,
                "Score": "%.2f" % (info["similarity"] * info["pagerank"]),
                "Description": parsed_desc
            }
            relation_list.append(rel_entry)
            max_token_budget -= num_tokens_from_string(str(rel_entry))
            if max_token_budget <= 0:
                relation_list.pop()
                break

        entity_section = ""
        if entity_list:
            entity_section = "\n---- Entities ----\n{}".format(pd.DataFrame(entity_list).to_csv())

        relation_section = ""
        if relation_list:
            relation_section = "\n---- Relations ----\n{}".format(pd.DataFrame(relation_list).to_csv())

        community_section = self._fetch_community_summaries(
            [name for name, _ in ranked_entities],
            filter_conditions, kb_ids, idx_names, top_communities, max_token_budget
        )

        return {
            "page_content": entity_section + relation_section + community_section,
            "vector": None,
            "metadata": {
                "doc_id": get_uuid(),
                "file_id": "",
                "file_name": "Related content in Knowledge Graph",
                "file_created_at": int(time.time() * 1000),
                "document_id": "",
                "knowledge_id": kb_ids,
                "sort_id": 0,
                "status": 1,
                "score": 1
            },
            "children": None
        }

    def _fetch_community_summaries(self, involved_entities, constraints, kb_ids, idx_names, top_count, token_limit):
        doc_fields = ["docnm_kwd", "page_content"]
        sort_order = OrderByExpr()
        sort_order.desc("weight_flt")

        adjusted_filter = deepcopy(constraints)
        adjusted_filter["knowledge_graph_kwd"] = "community_report"
        adjusted_filter["entities_kwd"] = involved_entities

        comm_results = self.dataStore.search(doc_fields, [], adjusted_filter, [],
                                             OrderByExpr(), 0, top_count, idx_names, kb_ids)
        processed_docs = self.dataStore.getFields(comm_results, doc_fields)

        summary_texts = []
        for idx, (_, row) in enumerate(processed_docs.items()):
            report_data = json.loads(row["page_content"])
            section = "# {}. {}\n## Content\n{}\n## Evidences\n{}\n".format(
                idx + 1, row["docnm_kwd"], report_data["report"], report_data["evidences"]
            )
            summary_texts.append(section)
            token_limit -= num_tokens_from_string(section)

        if not summary_texts:
            return ""

        return "\n---- Community Report ----\n" + "\n".join(summary_texts)

# Type III Clone: Refactored version with equivalent functionality but different structure and naming

def _import_module_safely(module_path):
    """Attempt to import a module; return (module_obj, None) or (None, exception)."""
    try:
        return __import__(module_path, fromlist=['']), None
    except (ImportError, NameError) as e:
        return None, e


class AbstractInterfaceBase:
    """Abstract base class enforcing implementation of required methods."""
    def __init__(self, config_dict):
        self._config = config_dict
        self._message_handler = None

    def register_callback(self, handler_func):
        self._message_handler = handler_func

    @property
    def logger_name(self):
        return f"OpenCastor.Channel.{self.__class__.__name__.lower()}"

    @property
    def configuration(self):
        return self._config

    async def process_incoming_message(self, sender_id, content):
        if "--dry-run" in content:
            return "Dry-run plan generated"

        if self._message_handler is not None:
            try:
                response = self._message_handler(
                    self.__class__.__name__.lower(), 
                    sender_id, 
                    content
                )
                return response if response is not None else None
            except Exception as ex:
                return f"Error: {str(ex)}"
        return None


class ConcreteImplementation(AbstractInterfaceBase):
    name = "stub_impl"

    async def initialize(self):
        pass

    async def shutdown(self):
        pass

    async def transmit_text(self, target_chat, message_body):
        pass


# Test suite for core functionality
class CoreFunctionalityTests:
    def test_configuration_preservation(self):
        test_config = {"setting": "value"}
        instance = ConcreteImplementation(test_config)
        assert instance.configuration == test_config

    def test_callback_registration(self):
        def dummy_handler(*args):
            return "handled"

        instance = ConcreteImplementation({})
        instance.register_callback(dummy_handler)
        assert instance._message_handler is dummy_handler

    def test_default_no_callback(self):
        instance = ConcreteImplementation({})
        assert instance._message_handler is None

    def test_logger_naming_convention(self):
        instance = ConcreteImplementation({})
        assert instance.logger_name == "OpenCastor.Channel.stub_impl"


# Message handling verification
class MessageProcessingValidation:
    def _execute_async(self, coro):
        import asyncio
        loop = asyncio.new_event_loop()
        return loop.run_until_complete(coro)

    def test_with_registered_handler(self):
        def handler(name, chat_id, text):
            return f"Processed: {text}"

        instance = ConcreteImplementation({})
        instance.register_callback(handler)
        result = self._execute_async(instance.process_incoming_message("user1", "command"))
        assert result == "Processed: command"

    def test_handler_receives_metadata(self):
        captured = {}
        def handler(name, chat_id, text):
            captured.update({"name": name, "chat_id": chat_id})
            return "ack"

        instance = ConcreteImplementation({})
        instance.register_callback(handler)
        self._execute_async(instance.process_incoming_message("user2", "action"))
        assert captured["name"] == "stub_impl"
        assert captured["chat_id"] == "user2"

    def test_missing_handler_returns_none(self):
        instance = ConcreteImplementation({})
        result = self._execute_async(instance.process_incoming_message("u", "msg"))
        assert result is None

    def test_exception_handling_in_handler(self):
        def faulty_handler(*_):
            raise ValueError("processing failed")

        instance = ConcreteImplementation({})
        instance.register_callback(faulty_handler)
