pytestmark = pytest.mark.integration


def test_resource_auto_tagging(stelvio_env):
    """When resources are deployed, they automatically receive stelvio:app and stelvio:env tags."""

    def infrastructure():
        Queue("tasks")
        DynamoTable("orders", fields={"pk": "S"}, partition_key="pk")

    deployment_outputs = stelvio_env.deploy(infrastructure)

    expected_metadata = {
        "stelvio:app": f"stlv-{stelvio_env.run_id}",
        "stelvio:env": "test",
    }

    # Validate SQS queue has correct auto-tags
    assert_sqs_tags(deployment_outputs["queue_tasks_url"], expected_metadata)
    # Validate DynamoDB table has correct auto-tags
    assert_dynamo_tags(deployment_outputs["dynamotable_orders_arn"], expected_metadata)

    # Confirm both resources reside in the expected AWS region
    aws_region = stelvio_env.aws_region
    assert f":{aws_region}:" in deployment_outputs["queue_tasks_arn"]
    assert f":{aws_region}:" in deployment_outputs["dynamotable_orders_arn"]


def test_global_application_tags_inheritance(stelvio_env):
    """Tags defined at app level should be merged into resource-level defaults."""

    app_instance = StelvioApp(f"stlv-{stelvio_env.run_id}")

    @app_instance.config
