def test_component_level_tags_precedence_over_global(stelvio_env):
    """Component-specific tags override global app tags when keys conflict."""

    app_instance = StelvioApp(f"stlv-{stelvio_env.run_id}")

    @app_instance.config
    def setup_config(stage):
        return StelvioAppConfig(
            aws=AwsConfig(
                profile=stelvio_env.aws_profile,
                region=stelvio_env.aws_region
            ),
            tags={
                "Shared": "global",
                "GlobalOnly": "yes"
            }
        )

    @app_instance.run
    def run_components():
        Queue("tasks", tags={
            "Shared": "component",
            "ComponentOnly": "yes"
        })
        DynamoTable("orders", fields={"pk": "S"}, partition_key="pk")

    deploy_result = stelvio_env.deploy_app(app_instance)

    base_auto_tags = {
        "stelvio:app": f"stlv-{stelvio_env.run_id}",
        "stelvio:env": "test",
    }

    # SQS queue should use component-level 'Shared' tag
    expected_queue_tags = {
        **base_auto_tags,
        "Shared": "component",
        "GlobalOnly": "yes",
        "ComponentOnly": "yes",
    }
    assert_sqs_tags(deploy_result["queue_tasks_url"], expected_queue_tags)

    # DynamoDB table inherits global tags only (no per-component override)
    expected_table_tags = {
        **base_auto_tags,
        "Shared": "global",
        "GlobalOnly": "yes",
    }
    assert_dynamo_tags(deploy_result["dynamotable_orders_arn"], expected_table_tags)


def test_resource_hierarchy_in_pulumi_tree(stelvio_env):
    """Resources must be nested under their respective Stelvio components in Pulumi’s resource graph."""

    def build_infra():
        Queue("tasks")
        DynamoTable("orders", fields={"pk": "S"}, partition_key="pk")

    stelvio_env.deploy(build_infra)
    all_resources = stelvio_env.export_resources()

    # Locate top-level stack and component entries
    stack_entry = _find_single_resource(all_resources, "pulumi:pulumi:Stack")
    queue_component = _find_single_resource(all_resources, "stelvio:aws:Queue")
    dynamo_component = _find_single_resource(all_resources, "stelvio:aws:DynamoTable")

    # Verify components are children of the stack
    assert queue_component["parent"] == stack_entry["urn"]
    assert dynamo_component["parent"] == stack_entry["urn"]

    # Find underlying AWS sub-resources
    sqs_underlying = _find_resource_by_type_fragment(all_resources, "aws:sqs/queue:Queue")
    dynamo_underlying = _find_resource_by_type_fragment(all_resources, "aws:dynamodb/table:Table")

    # Ensure sub-resources are parented to their Stelvio components
    assert sqs_underlying["parent"] == queue_component["urn"]
    assert dynamo_underlying["parent"] == dynamo_component["urn"]


def _find_single_resource(resource_list: list[dict], target_type: str) -> dict:
    """Retrieve exactly one resource matching the specified type URN."""
    candidates = []
    for res in resource_list:
        if res["type"] == target_type:
            candidates.append(res)

    assert len(candidates) == 1, (
        f"Expected exactly one resource of type '{target_type}', "
        f"but found {len(candidates)}: {[r['urn'] for r in candidates]}"
    )
    return candidates[0]


def _find_resource_by_type_fragment(resource_list: list[dict], fragment: str) -> dict:
    """Find a unique resource whose type includes the given substring."""
    candidates = []
    for res in resource_list:
        if fragment in res["type"]:
            candidates.append(res)

    assert len(candidates) == 1, (
        f"Expected exactly one resource containing '{fragment}' in its type, "
        f"but got {len(candidates)}: {[r['urn'] for r in candidates]}"
    )
    return candidates[0]

import re
import requests
