import grpc
from .proto import storage_pb2_grpc, storage_pb2
from .utils import init_logger
from ._checkpoint_store import CheckpointStore, MemCopyChunk


class StorageServicer(storage_pb2_grpc.StorageServicer):
    def __init__(
        self,
        storage_dir,
        memory_pool_capacity,
        worker_threads,
        chunk_byte_size,
        enforce_client_registration,
    ):
        """Constructs the storage service handler"""
        self.logger = init_logger(self.__class__.__name__)
        self.storage_dir = storage_dir
        self.memory_pool_capacity = memory_pool_capacity
        self.worker_threads = worker_threads
        self.chunk_byte_size = chunk_byte_size
        self.enforce_client_registration = enforce_client_registration

        log_msg = (
            f"StorageServicer initialized: "
            f"storage_dir={self.storage_dir}, "
            f"memory_pool_capacity={self.memory_pool_capacity}, "
            f"worker_threads={self.worker_threads}, "
            f"chunk_byte_size={self.chunk_byte_size}, "
            f"enforce_client_registration={self.enforce_client_registration}"
        )
        self.logger.info(log_msg)

        if not CheckpointStore:
            raise RuntimeError("CheckpointStore class is unavailable")

        self.backend_storage = CheckpointStore(
            self.storage_dir,
            self.memory_pool_capacity,
            self.worker_threads,
            self.chunk_byte_size,
        )

    async def LoadModelAsync(self, request, context):
        model_path = request.model_path
        if not model_path.strip():
            self.logger.error("model_path is empty or whitespace")
            context.set_code(grpc.StatusCode.INVALID_ARGUMENT)
            return storage_pb2.LoadModelResponse()

        # Skip registration if not required
        if not self.enforce_client_registration:
            size_result = self.backend_storage.register_model_info(model_path)
            if size_result < 0:
                self.logger.error("Failed to register model info")
                context.set_code(grpc.StatusCode.INTERNAL)
                return storage_pb2.LoadModelResponse()

        target_device = request.target_device_type
        if target_device == storage_pb2.DEVICE_TYPE_CPU:
            status = self.backend_storage.load_model_from_disk_async(model_path)
        elif target_device == storage_pb2.DEVICE_TYPE_GPU:
            replica_id = request.replica_uuid
            if not replica_id or not replica_id.strip():
                self.logger.error("replica_uuid is missing or blank")
                context.set_code(grpc.StatusCode.INVALID_ARGUMENT)
                return storage_pb2.LoadModelResponse()

            gpu_handles_map = {
                dev_uuid: [h.cuda_ipc_handle for h in handle_list.handles]
                for dev_uuid, handle_list in request.handles.items()
            }

            def _build_mem_chunk(src_chunk):
                new_chunk = MemCopyChunk()
                new_chunk.src_offset = src_chunk.src_offset
                new_chunk.size = src_chunk.size
                new_chunk.dst_offset = src_chunk.dst_offset
                new_chunk.handle_idx = src_chunk.handle_idx
                return new_chunk

            mem_chunks_map = {
                dev_uuid: [_build_mem_chunk(c) for c in chunk_list.chunks]
                for dev_uuid, chunk_list in request.chunks.items()
            }

            status = self.backend_storage.load_model_from_mem_async(
                model_path, replica_id, gpu_handles_map, mem_chunks_map
            )
        else:
            self.logger.error(f"Unsupported device type: {target_device}")
            context.set_code(grpc.StatusCode.UNIMPLEMENTED)
            return storage_pb2.LoadModelResponse()

        if status != 0:
            self.logger.error("Model loading operation failed")
            context.set_code(grpc.StatusCode.INTERNAL)
            return storage_pb2.LoadModelResponse()

        self.logger.info(f"Successfully loaded model '{model_path}' on {target_device}")
        return storage_pb2.LoadModelResponse(model_path=model_path)

    async def ConfirmModel(self, request, context):
        model_path = request.model_path
        replica_id = request.replica_uuid
        device_type = request.target_device_type

        if not model_path or not model_path.strip():
            self.logger.error("model_path is empty")
            context.set_code(grpc.StatusCode.INVALID_ARGUMENT)
            return storage_pb2.ConfirmModelResponse()

        if device_type != storage_pb2.DEVICE_TYPE_GPU:
            self.logger.error(f"Only GPU confirmation supported; got {device_type}")
            context.set_code(grpc.StatusCode.UNIMPLEMENTED)
            return storage_pb2.ConfirmModelResponse()

        max_attempts = 10
        attempt = 0
        while attempt < max_attempts:
            try:
                result = self.backend_storage.wait_model_in_gpu(model_path, replica_id)
                if result == 0:
                    self.logger.info(
                        f"Confirmed model '{model_path}' replica '{replica_id}'"
                    )
                    return storage_pb2.ConfirmModelResponse(model_path=model_path)
                elif result == 1:
                    self.logger.warning(
                        f"Model '{model_path}' replica '{replica_id}' load was interrupted"
                    )
                    context.set_code(grpc.StatusCode.INTERNAL)
                    return storage_pb2.ConfirmModelResponse()
                else:
                    self.logger.warning(
                        f"Confirmation attempt {attempt + 1}/{max_attempts} failed with code {result}"
                    )
            except Exception as exc:
                self.logger.error(f"Exception during wait_model_in_gpu: {exc}")
                if attempt == max_attempts - 1:
                    raise
            finally:
                attempt += 1
                await asyncio.sleep(0.1)

        self.logger.error(
            f"Model confirmation for '{model_path}' replica '{replica_id}' timed out"
        )
        context.set_code(grpc.StatusCode.INTERNAL)
        return storage_pb2.ConfirmModelResponse()

    async def UnloadModel(self, request, context):
        model_path = request.model_path
        device_type = request.target_device_type

        if not model_path or not model_path.strip():
            self.logger.error("model_path is empty")
            context.set_code(grpc.StatusCode.INVALID_ARGUMENT)
            return storage_pb2.UnloadModelResponse()

        if device_type != storage_pb2.DEVICE_TYPE_CPU:
            self.logger.error(f"Only CPU unloading supported; got {device_type}")
            context.set_code(grpc.StatusCode.UNIMPLEMENTED)
            return storage_pb2.UnloadModelResponse()

        attempts = 5
        for i in range(attempts):
            exit_code = self.backend_storage.unload_model_from_host(model_path)
            if exit_code == 0:
                self.logger.info(f"Successfully unloaded model '{model_path}'")
                return storage_pb2.UnloadModelResponse(model_path=model_path)
            self.logger.info(f"Unload attempt {i + 1}/{attempts} failed")
            await asyncio.sleep(0.01)

        self.logger.error(f"Model '{model_path}' could not be unloaded after {attempts} tries")
        context.set_code(grpc.StatusCode.INTERNAL)
        return storage_pb2.UnloadModelResponse()

    async def ClearMem(self, request, context):
        status = self.backend_storage.clear_mem()
        if status != 0:
            self.logger.error("Memory clearing operation failed")
            context.set_code(grpc.StatusCode.INTERNAL)
        return storage_pb2.ClearMemResponse()

    async def RegisterModel(self, request, context):
        model_path = request.model_path
        if not model_path or not model_path.strip():
            self.logger.error("model_path is empty")
            context.set_code(grpc.StatusCode.INVALID_ARGUMENT)
            return storage_pb2.RegisterModelResponse()

        model_size = self.backend_storage.register_model_info(model_path)
        if model_size < 0:
            self.logger.error("Registration failed")
            context.set_code(grpc.StatusCode.INTERNAL)
            return storage_pb2.RegisterModelResponse()

        return storage_pb2.RegisterModelResponse(
            model_path=model_path,
            model_size=model_size,
        )

    async def GetServerConfig(self, request, context):
        return storage_pb2.GetServerConfigResponse(
            mem_pool_size=self.backend_storage.get_mem_pool_size(),
            chunk_size=self.backend_storage.get_chunk_size(),
        )

