import base64
import hashlib
import hmac
import json
import time
import requests
from requests.auth import AuthBase
from blankly.utils.utils import info_print

class CBProAuth(AuthBase):
    """Custom authentication handler for Coinbase Pro API"""
    def __init__(self, key, secret, phrase):
        self.api_key = key
        self.secret_key = secret
        self.passphrase = phrase

    def __call__(self, req):
        current_time = str(time.time())
        msg_content = ''.join([current_time, req.method,
                              req.path_url, (req.body or '')])
        headers = generate_signature(current_time, msg_content,
                                    self.api_key,
                                    self.secret_key,
                                    self.passphrase)
        req.headers.update(headers)
        return req

def generate_signature(timestamp, content, key, secret, phrase):
    """Generate authentication headers for API requests"""
    encoded_msg = content.encode('ascii')
    decoded_secret = base64.b64decode(secret)
    hash_obj = hmac.new(decoded_secret, encoded_msg, hashlib.sha256)
    sig_b64 = base64.b64encode(hash_obj.digest()).decode('utf-8')

    return {
        'Content-Type': 'Application/JSON',
        'CB-ACCESS-SIGN': sig_b64,
        'CB-ACCESS-TIMESTAMP': timestamp,
        'CB-ACCESS-KEY': key,
        'CB-ACCESS-PASSPHRASE': phrase
    }

class ExchangeAPI:
    """Main interface for interacting with Coinbase Pro exchange"""
    def __init__(self, api_key: str, api_secret: str, api_pass: str, 
                 endpoint: str = 'https://api.pro.coinbase.com/'):
        self._auth_handler = CBProAuth(api_key, api_secret, api_pass)
        self._base_url = endpoint
        self.http_session = requests.Session()

    # Public Market Data Methods
    def fetch_markets(self):
        """Retrieve available trading pairs"""
        return requests.get(self._base_url + 'products', auth=self._auth_handler).json()

    def fetch_order_book(self, symbol, depth=1):
        """Get order book for a specific trading pair"""
        if depth == 3:
            info_print("Frequent polling at depth 3 may trigger rate limiting. Consider using websocket.")

        params = {'level': depth}
        return requests.get(self._base_url + f"products/{symbol}/book", 
                           params=params).json()

    def fetch_trades(self, symbol, start='', end='', count=None, cache=None):
        """List recent trades for a product"""
        return self._handle_pagination(f'/products/{symbol}/trades')

    def fetch_candles(self, symbol, start=None, end=None, interval=None):
        """Get historical price data"""
        parameters = {}
        if start is not None:
            parameters['start'] = start
        if end is not None:
            parameters['end'] = end
        parameters['granularity'] = interval

        return requests.get(self._base_url + f'products/{symbol}/candles', 
                           params=parameters).json()

    def fetch_24h_stats(self, symbol):
        """Get 24-hour statistics for a trading pair"""
        return requests.get(self._base_url + f'products/{symbol}/stats', 
                           auth=self._auth_handler).json()

    def fetch_assets(self):
        """List supported currencies"""
        return requests.get(self._base_url + 'currencies', auth=self._auth_handler).json()

    def fetch_server_time(self):
        """Get current server time"""
        return requests.get(self._base_url + 'time', auth=self._auth_handler).json()

    # Account Management Methods
    def list_accounts(self):
        """Get all trading accounts"""
        return requests.get(self._base_url + 'accounts', auth=self._auth_handler).json()

    def get_account(self, account_id):
        """Get details for a specific account"""
        return requests.get(self._base_url + f'accounts/{account_id}', 
                           auth=self._auth_handler).json()

    def get_account_ledger(self, account_id, **kwargs):
        """Get account activity history"""
        endpoint = f'/accounts/{account_id}/ledger'
        return self._handle_pagination(endpoint, params=kwargs)

    def get_account_holds(self, account_id, **kwargs):
        """Get active holds on an account"""
        endpoint = f'/accounts/{account_id}/holds'
        return self._handle_pagination(endpoint, params=kwargs)

    # Trading Methods
    def submit_order(self, symbol, side, type, **kwargs):
        """Place an order with specified parameters"""
        # Validate margin parameters
        if kwargs.get('overdraft_enabled') and kwargs.get('funding_amount'):
            raise ValueError('Only one margin funding method allowed')

        # Validate limit order parameters
        if type == 'limit':
            if kwargs.get('cancel_after') and kwargs.get('time_in_force') != 'GTT':
                raise ValueError('Cancel period only valid with GTT time-in-force')
            if kwargs.get('post_only') and kwargs.get('time_in_force') in ['IOC', 'FOK']:
                raise ValueError('post_only incompatible with IOC/FOK time-in-force')

        # Validate market/stop order parameters
        if type in ['market', 'stop']:
            has_size = kwargs.get('size') is not None
            has_funds = kwargs.get('funds') is not None
            if has_size and has_funds or (not has_size and not has_funds):
                raise ValueError('Specify either size or funds for market/stop orders')

        # Build request payload
        payload = {
            'product_id': symbol,
            'side': side,
            'type': type
        }
        payload.update(kwargs)

        return requests.post(self._base_url + 'orders', 
                            data=json.dumps(payload), 
                            auth=self._auth_handler).json()

    def limit_order(self, symbol, side, price, size,
                   client_oid=None, stp=None, time_in_force=None,
                   cancel_after=None, post_only=None,
                   overdraft_enabled=None, funding_amount=None):
        """Place a limit order"""
        params = {
            'product_id': symbol,
            'side': side,
            'order_type': 'limit',
            'price': price,
            'size': size,
            'client_oid': client_oid,
            'stp': stp,
            'time_in_force': time_in_force,
            'cancel_after': cancel_after,
            'post_only': post_only,
            'overdraft_enabled': overdraft_enabled,
            'funding_amount': funding_amount
        }
        # Filter out None values
        filtered_params = {k: v for k, v in params.items() if v is not None}
        return self.submit_order(**filtered_params)

    def market_order(self, symbol, side, size=None, funds=None,
                    client_oid=None, stp=None,
                    overdraft_enabled=None, funding_amount=None):
        """Place a market order"""
        params = {
            'product_id': symbol,
            'side': side,
            'order_type': 'market',
            'size': size,
            'funds': funds,
            'client_oid': client_oid,
            'stp': stp,
            'overdraft_enabled': overdraft_enabled,
            'funding_amount': funding_amount
        }
        filtered_params = {k: v for k, v in params.items() if v is not None}
        return self.submit_order(**filtered_params)

    def stop_order(self, symbol, side, price, size=None, funds=None,
                  client_oid=None, stp=None,
                  overdraft_enabled=None, funding_amount=None):
        """Place a stop order"""
        params = {
            'product_id': symbol,
            'side': side,
            'stop_price': price,
            'price': price,
            'order_type': 'limit',
            'stop': 'loss',
            'size': size,
            'funds': funds,
            'client_oid': client_oid,
            'stp': stp,
            'overdraft_enabled': overdraft_enabled,
            'funding_amount': funding_amount
        }
        filtered_params = {k: v for k, v in params.items() if v is not None}
        return self.submit_order(**filtered_params)

    def cancel_order(self, order_id):
        """Cancel an existing order"""
        return requests.delete(self._base_url + f'orders/{order_id}', 
                              auth=self._auth_handler).json()

    def list_orders(self, symbol=None, status=None, **kwargs):
        """List current open orders"""
        params = kwargs.copy()
        if symbol is not None:
            params['product_id'] = symbol
        if status is not None:
            params['status'] = status
        return self._handle_pagination('orders', params=params)

    def get_order(self, order_id):
        """Get details for a specific order"""
        return requests.get(self._base_url + f"orders/{order_id}", 
                           auth=self._auth_handler).json()

    def get_fills(self, order_id=None, product_id=None, **kwargs):
        """Get recent order fills"""
        if product_id is None and order_id is None:
            raise ValueError('Either product_id or order_id must be specified')

        params = {}
        if product_id:
            params['product_id'] = product_id
        if order_id:
            params['order_id'] = order_id
        params.update(kwargs)
        return self._handle_pagination('/fills', params=params)

    def get_fee_rates(self):
        """Get current fee rates and trading volume"""
        return requests.get(self._base_url + "fees", auth=self._auth_handler).json()

    def _handle_pagination(self, path, params=None):
        """Handle paginated API responses"""
        if params is None:
            params = {}

        while True:
            response = requests.get(self._base_url + path, 
                                   params=params, 
                                   auth=self._auth_handler, 
                                   timeout=30)

            results = response.json()
            for item in results:
                yield item

            # Check for next page
            next_token = response.headers.get('cb-after')
            if not next_token or params.get('before') is not None:
                break

            params['after'] = next_token

    # Additional Methods
    def generate_report(self, report_type, start_date, end_date, 
                       product_id=None, account_id=None, 
                       format='pdf', email=None):
        """Create a historic report"""
        params = {
            'type': report_type,
            'start_date': start_date,
            'end_date': end_date,
            'format': format
        }
        if product_id is not None:
            params['product_id'] = product_id
        if account_id is not None:
            params['account_id'] = account_id
        if email is not None:
            params['email'] = email

        return requests.post(self._base_url + "reports", 
                            data=json.dumps(params), 
                            auth=self._auth_handler).json()

    def get_report_status(self, report_id):
        """Check status of a generated report"""
        return requests.get(self._base_url + f"reports/{report_id}", 
                           auth=self._auth_handler).json()

    def get_trailing_volume(self):
        """Get 30-day trailing volume"""
        return requests.get(self._base_url + "users/self/trailing-volume", 
                           auth=self._auth_handler).json()

    def get_coinbase_accounts(self):
        """Get linked Coinbase accounts"""
        return requests.get(self._base_url + 'coinbase-accounts', 
                           auth=self._auth_handler).json()

    def get_ticker(self, symbol):
        """Get current market ticker for a product"""
        return requests.get(self._base_url + f'products/{symbol}/ticker', 
                           auth=self._auth_handler).json()

