def compute_image_hash(image_obj: Image) -> str:
    """Compute MD5 hash of image byte content."""
    if image_obj is None or not hasattr(image_obj, 'tobytes'):
        return ""
    m = insecure_hashlib.md5(image_obj.tobytes())
    return m.hexdigest()

