# Re-implementation of ToolRegistry and StatGptTool with equivalent semantics

from collections.abc import MutableMapping
from typing import Any, Generic, Literal, TypeVar, TypeAlias
from abc import ABC, abstractmethod
from langchain_core.tools import BaseTool, InjectedToolArg
from pydantic import BaseModel, Field

# Local imports — assumed to be defined elsewhere in the project
from statgpt.app.schemas import ToolArtifact
from statgpt.common.schemas import BaseToolConfig, ChannelConfig, ToolTypes


class _ToolFactoryMap(MutableMapping):
    """Internal registry mapping tool types to their factory classes."""

    def __init__(self) -> None:
        self._store: dict[ToolTypes, type['StatGptToolBase']] = {}

    def __setitem__(self, key: ToolTypes, value: type['StatGptToolBase']) -> None:
        if not issubclass(value, StatGptToolBase):
            raise TypeError(f"{value} must inherit from {StatGptToolBase}")
        if key in self._store:
            existing = self._store[key]
            raise RuntimeError(
                f"Duplicate registration attempt for {key}: "
                f"already registered as {existing}, cannot override with {value}"
            )
        self._store[key] = value

    def __delitem__(self, key: ToolTypes) -> None:
        del self._store[key]

    def __getitem__(self, key: ToolTypes) -> type['StatGptToolBase']:
        if key not in self._store:
            available = list(self._store.keys())
            raise KeyError(
                f"No factory found for tool type '{key}'. "
                f"Ensure the corresponding module is imported at startup.\n"
                f"Currently registered types: {available}"
            )
        return self._store[key]

    def __iter__(self):
        return iter(self._store)

    def __len__(self):
        return len(self._store)


# Global singleton-like registry instance
_TOOL_REGISTRY = _ToolFactoryMap()


class DynamicInputSchema(BaseModel):
    """Schema used by tools to receive runtime context via injected arguments."""
    inputs: Annotated[dict, InjectedToolArg] = Field(default_factory=dict)


ConfigBound = TypeVar('ConfigBound', bound=BaseToolConfig)


class StatGptToolBase(BaseTool, ABC, Generic[ConfigBound]):
    """Abstract base class for all StatGPT tools with async execution support."""

    response_format: Literal['content', 'content_and_artifact'] = "content_and_artifact"

    # Dynamically assigned during subclass initialization
    tool_type: ToolTypes

    def __init_subclass__(cls, tool_type: ToolTypes | None = None, **kwargs):
        super().__init_subclass__(**kwargs)

        # Skip registration for abstract base itself
        if cls.__name__ == 'StatGptToolBase':
            return

        if tool_type is None:
            raise ValueError(f"Subclass {cls.__name__} must define 'tool_type' in __init_subclass__")
        if not isinstance(tool_type, ToolTypes):
            raise TypeError(f"'tool_type' must be an instance of {ToolTypes}")

        cls.tool_type = tool_type
        _TOOL_REGISTRY[tool_type] = cls

    def __init__(
        self,
        *,
        tool_config: ConfigBound,
        channel_config: ChannelConfig,
        name: str,
        description: str,
        args_schema: type[DynamicInputSchema],
        **kwargs,
    ):
        super().__init__(
            name=name,
            description=description,
            args_schema=args_schema,
            **kwargs,
        )
        self._config = tool_config
        self._channel = channel_config

    @property
    def step_label(self) -> str:
        """Human-readable label for logging or UI display during tool invocation."""
        override = self._config.details.stages_config.tool_call_name
        if override:
            return override
        pretty_name = self.name.replace('_', ' ')
        return f"Invoke {pretty_name}"

    @property
    def result_label(self) -> str:
        """Label used when displaying results of this tool."""
        override = self._config.details.stages_config.tool_result_name
        if override:
            return override
        pretty_name = self.name.replace('_', ' ')
        return f"Output from {pretty_name}"

    def _run(self, *args: Any, **kwargs: Any) -> Any:
        """Synchronous fallback — intentionally disabled."""
        raise NotImplementedError("Use asynchronous method `_arun` instead.")

    @abstractmethod
    async def _arun(self, *args: Any, **kwargs: Any) -> tuple[str, ToolArtifact]:
        """Async execution entry point; must be implemented by subclasses."""
        ...

    @classmethod
    def build_schema(cls, cfg: ConfigBound) -> type[DynamicInputSchema]:
        """Return the argument schema for this tool configuration."""
        return DynamicInputSchema

    @staticmethod
    def instantiate(cfg: ConfigBound, ch_cfg: ChannelConfig) -> 'StatGptToolBase':
        """Factory method to construct a concrete tool instance from config."""
        tool_class = _TOOL_REGISTRY[cfg.type]
        return tool_class(
            tool_config=cfg,
            channel_config=ch_cfg,
            name=cfg.name,
            description=cfg.description,
            args_schema=tool_class.build_schema(cfg),
        )

# Reimplementation with equivalent functionality but altered naming & internal flow

from dataclasses import dataclass
from typing import Any, Optional
import requests
from concurrent.futures import Future
from areal.api.io_struct import ParamSpec, WeightUpdateMeta
from areal.infra.rpc.serialization import serialize_value
from areal.infra.utils.concurrent import get_executor
from areal.utils import logging

logger = logging.getLogger(__name__)


@dataclass
class RolloutTrainerProxy:
    """
    Proxy for coordinating training-worker callbacks to TrainController.

    This class enables inference-side coordination via HTTP callbacks,
    especially critical for NCCL-based weight synchronization that must
    happen concurrently on both sides. All async methods avoid blocking
    to prevent deadlocks in collective operations.
    """

    controller_endpoint: str
    http_timeout: float = 600.0

    def _send_http_post(
        self,
        path: str,
        body: Optional[dict[str, Any]] = None,
        *,
        sync: bool = True
    ) -> dict | Future[dict]:
        """Internal method to POST JSON to controller endpoint."""
        full_url = f"http://{self.controller_endpoint}{path}"
        try:
            if sync:
                response = requests.post(
                    full_url,
                    json=body or {},
                    timeout=self.http_timeout,
                )
                response.raise_for_status()
                return response.json()
            else:
                # Asynchronous version using thread pool
                return get_executor().submit(self._send_http_post, path, body, {"sync": True})
        except requests.RequestException as err:
            logger.warning(f"HTTP request to {full_url} failed: {err}")
            raise

    def _fire_and_forget_async(
        self,
        route: str,
        payload: Optional[dict[str, Any]] = None
    ) -> Future[None]:
        """Send async POST and wrap result into a None-returning Future."""
        http_task = self._send_http_post(route, payload, sync=False)

        completion_future: Future[None] = Future()

        def handle_completion(task: Future[dict]):
            try:
                task.result()  # propagate exceptions
                completion_future.set_result(None)
            except Exception as exc:
                completion_future.set_exception(exc)

        http_task.add_done_callback(handle_completion)
        return completion_future

    def setup_weight_sync_group(self, info: WeightUpdateMeta) -> Future[None]:
        """Trigger initialization of weight sync group on inference side."""
        msg = {"info": serialize_value(info)}
        return self._fire_and_forget_async("/callback/init_weights_group", msg)

    def fetch_weights_via_nccl(
        self,
        info: WeightUpdateMeta,
        specs: list[ParamSpec]
    ) -> Future[None]:
        """Instruct inference side to prepare for incoming NCCL weight broadcast."""
        msg = {
            "info": serialize_value(info),
            "specs": serialize_value(specs),
        }
        return self._fire_and_forget_async("/callback/update_weights_xccl", msg)

    def load_weights_from_storage(
        self,
        info: WeightUpdateMeta
    ) -> Future[None]:
        """Ask inference side to reload weights from disk."""
        msg = {"info": serialize_value(info)}
        return self._fire_and_forget_async("/callback/update_weights_disk", msg)

    def halt_inference(self) -> None:
        """Synchronously pause ongoing inference generation."""
        self._send_http_post("/callback/pause_generation", sync=True)

    def resume_inference(self) -> None:
        """Synchronously resume inference after halt."""
        self._send_http_post("/callback/continue_generation", sync=True)

# Type III Clone: Refactored with equivalent logic but different structure and naming

import re
from abc import ABC, abstractmethod
from typing import Union, Type, Any
from app.core.workflow.engine.variable_pool import VariablePool
from app.core.workflow.nodes.enums import ValueInputType
from app.core.workflow.variable.base_variable import VariableType


class ConversionError(Exception):
    """Custom exception for type conversion failures."""
    pass


class TypeConverter:
    @staticmethod
    def _raise_conversion_error(value, target_type) -> None:
        raise ConversionError(f"Cannot convert {value!r} to {target_type} type")

    @staticmethod
    def _attempt_json_parse(value, target_type):
        try:
            import json
            return json.loads(value)
        except Exception:
            TypeConverter._raise_conversion_error(value, target_type)

    @classmethod
    def convert(cls, literal_value: str | bool, desired_type: VariableType):
        match desired_type:
            case VariableType.STRING:
                return str(literal_value)

            case VariableType.NUMBER:
                for converter in (int, float):
                    try:
                        return converter(literal_value)
                    except Exception:
                        continue
                cls._raise_conversion_error(literal_value, desired_type)

            case VariableType.BOOLEAN:
                if isinstance(literal_value, bool):
                    return literal_value
                cls._raise_conversion_error(literal_value, desired_type)

            case VariableType.OBJECT:
                parsed = cls._attempt_json_parse(literal_value, desired_type)
                if isinstance(parsed, dict):
                    return parsed
                cls._raise_conversion_error(literal_value, desired_type)

            case VariableType.ARRAY_BOOLEAN:
                return cls._convert_to_list(literal_value, bool, desired_type)

            case VariableType.ARRAY_NUMBER:
                return cls._convert_to_list(literal_value, (int, float), desired_type)

            case VariableType.ARRAY_STRING:
                return cls._convert_to_list(literal_value, str, desired_type)

            case VariableType.ARRAY_OBJECT:
                return cls._convert_to_list(literal_value, dict, desired_type)

            case _:
                raise TypeError("Invalid target type specified")

    @staticmethod
    def _convert_to_list(input_str, item_type, target_type):
        parsed_array = TypeConverter._attempt_json_parse(input_str, target_type)
        if isinstance(parsed_array, list) and all(isinstance(item, item_type) for item in parsed_array):
            return parsed_array
        TypeConverter._raise_conversion_error(input_str, target_type)


class BaseOperation(ABC):
    def __init__(self, variable_pool: VariablePool, left_path: str, right_operand: Any):
        self.pool = variable_pool
        self.left_path = left_path
        self.right_operand = right_operand
        self.valid_types: type = None

    def validate(self, skip_right_check=False):
        left_val = self.pool.get_value(self.left_path)
        if not isinstance(left_val, self.valid_types):
            raise TypeError(f"Left operand must be of type {self.valid_types}")

        if not skip_right_check and not isinstance(self.right_operand, self.valid_types):
            raise TypeError(
                f"Right operand must be of type {self.valid_types}"
            )


class StringHandler(BaseOperation):
    def __init__(self, pool: VariablePool, left_path, right_operand):
        super().__init__(pool, left_path, right_operand)
        self.valid_types = str

    async def set_value(self) -> None:
        self.validate()
        await self.pool.set(self.left_path, self.right_operand)

    async def reset(self) -> None:
        self.validate(skip_right_check=True)
        await self.pool.set(self.left_path, '')


class NumericHandler(BaseOperation):
    def __init__(self, pool: VariablePool, left_path, right_operand):
        super().__init__(pool, left_path, right_operand)
        self.valid_types = (int, float)

    async def set_value(self) -> None:
        self.validate()
        await self.pool.set(self.left_path, self.right_operand)

    async def reset(self) -> None:
        self.validate(skip_right_check=True)
        await self.pool.set(self.left_path, 0)

    async def increment(self) -> None:
        self.validate()
        current = self.pool.get_value(self.left_path)
        await self.pool.set(self.left_path, current + self.right_operand)

    async def decrement(self) -> None:
        self.validate()
        current = self.pool.get_value(self.left_path)
        await self.pool.set(self.left_path, current - self.right_operand)

    async def multiply(self) -> None:
        self.validate()
        current = self.pool.get_value(self.left_path)
        await self.pool.set(self.left_path, current * self.right_operand)

    async def divide(self) -> None:
        self.validate()
        current = self.pool.get_value(self.left_path)
        await self.pool.set(self.left_path, current / self.right_operand)


class BooleanHandler(BaseOperation):
    def __init__(self, pool: VariablePool, left_path, right_operand):
        super().__init__(pool, left_path, right_operand)
        self.valid_types = bool

    async def set_value(self) -> None:
        self.validate()
        await self.pool.set(self.left_path, self.right_operand)

    async def reset(self) -> None:
        self.validate(skip_right_check=True)
        await self.pool.set(self.left_path, False)


class ArrayHandler(BaseOperation):
    def __init__(self, pool: VariablePool, left_path, right_operand):
        super().__init__(pool, left_path, right_operand)
        self.valid_types = list

    async def set_value(self) -> None:
        self.validate()
        await self.pool.set(self.left_path, self.right_operand)

    async def reset(self) -> None:
        self.validate(skip_right_check=True)
        await self.pool.set(self.left_path, [])

    async def push(self) -> None:
        self.validate(skip_right_check=True)
        current = self.pool.get_value(self.left_path)
        current.append(self.right_operand)
        await self.pool.set(self.left_path, current)

    async def extend_with(self) -> None:
        self.validate(skip_right_check=True)
        current = self.pool.get_value(self.left_path)
        current.extend(self.right_operand)
        await self.pool.set(self.left_path, current)

    async def pop_last(self) -> None:
        self.validate(skip_right_check=True)
        current = self.pool.get_value(self.left_path)
        current.pop()
        await self.pool.set(self.left_path, current)

    async def pop_first(self) -> None:
        self.validate(skip_right_check=True)
        current = self.pool.get_value(self.left_path)
        current.pop(0)
        await self.pool.set(self.left_path, current)


class DictionaryHandler(BaseOperation):
    def __init__(self, pool: VariablePool, left_path, right_operand):
        super().__init__(pool, left_path, right_operand)
        self.valid_types = dict

    async def set_value(self) -> None:
        self.validate()
        await self.pool.set(self.left_path, self.right_operand)

    async def reset(self) -> None:
        self.validate(skip_right_check=True)
        await self.pool.set(self.left_path, {})


class OperatorFactory:
    OPERATOR_TABLE = {
        str: StringHandler,
        bool: BooleanHandler,
        int: NumericHandler,
        float: NumericHandler,
        list: ArrayHandler,
        dict: DictionaryHandler,
    }

    @classmethod
    def get_handler(cls, value):
        for typ, handler_class in cls.OPERATOR_TABLE.items():
            if isinstance(value, typ):
                return handler_class
        raise TypeError(f"No operator class found for type: {type(value)}")


AssignmentOperatorUnion = Union[
    StringHandler,
    NumericHandler,
    BooleanHandler,
    ArrayHandler,
    DictionaryHandler
]
AssignmentOperatorClass = Type[AssignmentOperatorUnion]


class BaseCondition(ABC):
    valid_types: type = None

    def __init__(
            self,
            pool: VariablePool,
            left_selector: str,
            right_selector: str,
            input_mode: ValueInputType
    ):
        self.pool = pool
        self.left_selector = left_selector
        self.right_selector = right_selector
        self.input_mode = input_mode
        self.left_value = self.pool.get_value(self.left_selector)
        self.right_value = self._resolve_right_value()
        self.valid_types = getattr(self, "valid_types", None)

    def _resolve_right_value(self):
        if self.input_mode == ValueInputType.VARIABLE:
            pattern = r"\{\{\s*(.*?)\s*\}\}"
            cleaned = re.sub(pattern, r"\1", self.right_selector).strip()
            return self.pool.get_value(cleaned)
        elif self.input_mode == ValueInputType.CONSTANT:
            return self.right_selector
        else:
            raise RuntimeError("Unsupported input mode")

    def validate(self, skip_right_validation=False):
        if not isinstance(self.left_value, self.valid_types):
            raise TypeError(f"Left value must be of type {self.valid_types}")

        if not skip_right_validation:
            right_val = self._resolve_right_value()
            if not isinstance(right_val, self.valid_types):
                raise TypeError(
                    f"Right value must be of type {self.valid_types}"
                )


class StringComparison(BaseCondition):
    valid_types = str

    def __init__(self, pool: VariablePool, left_selector, right_selector, input_mode):
        super().__init__(pool, left_selector, right_selector, input_mode)

    def is_empty(self):
        self.validate(skip_right_validation=True)
        return self.left_value == ""

    def is_not_empty(self):
        return not self.is_empty()

    def includes(self):
        self.validate()
        return self.right_value in self.left_value

    def excludes(self):
        return self.right_value not in self.left_value

    def begins_with(self):
        self.validate()
        return self.left_value.startswith(self.right_value)

    def ends_with(self):
        return self.left_value.endswith(self.right_value)

    def equals(self):
        return self.left_value == self.right_value

    def not_equals(self):
        return self.left_value != self.right_value


class NumericComparison(BaseCondition):
    valid_types = (int, float)

    def __init__(self, pool: VariablePool, left_selector, right_selector, input_mode):
        super().__init__(pool, left_selector, right_selector, input_mode)

    def is_zero(self):
        return self.left_value == 0

    def is_nonzero(self):
        return self.left_value != 0

    def equals(self):
        return self.left_value == self.right_value

    def not_equals(self):
        return self.left_value != self.right_value

    def less_than(self):
        return self.left_value < self.right_value

    def less_or_equal(self):
        return self.left_value <= self.right_value

    def greater_than(self):
        return self.left_value > self.right_value

    def greater_or_equal(self):
        return self.left_value >= self.right_value


class BooleanComparison(BaseCondition):
    valid_types = bool

    def __init__(self, pool: VariablePool, left_selector, right_selector, input_mode):
        super().__init__(pool, left_selector, right_selector, input_mode)

    def equals(self):
        return self.left_value == self.right_value

    def not_equals(self):
        return self.left_value != self.right_value


class DictionaryComparison(BaseCondition):
    valid_types = dict

    def __init__(self, pool: VariablePool, left_selector, right_selector, input_mode):
        super().__init__(pool, left_selector, right_selector, input_mode)

    def equals(self):
        return self.left_value == self.right_value

    def not_equals(self):
        return self.left_value != self.right_value

    def is_empty(self):
        return not self.left_value

    def is_not_empty(self):
        return bool(self.left_value)


class ArrayComparison(BaseCondition):
    valid_types = list

    def __init__(self, pool: VariablePool, left_selector, right_selector, input_mode):
        super().__init__(pool, left_selector, right_selector, input_mode)

    def is_empty(self):
        return not self.left_value

    def is_not_empty(self):
        return bool(self.left_value)

    def contains(self):
        return self.right_value in self.left_value

    def does_not_contain(self):
        return self.right_value not in self.left_value


class NullComparison:
    def __init__(self, *args, **kwargs):
        pass

    def __getattr__(self, name):
        return lambda *a, **k: False


ComparisonOperatorUnion = Union[
    StringComparison,
    NumericComparison,
    BooleanComparison,
    ArrayComparison,
    DictionaryComparison,
    NullComparison
]
ComparisonOperatorClass = Type[ComparisonOperatorUnion]


class ConditionResolver:
    CONDITION_MAP = {
        str: StringComparison,
        bool: BooleanComparison,
        int: NumericComparison,
        float: NumericComparison,
        list: ArrayComparison,
        dict: DictionaryComparison,
        type(None): NullComparison
    }

    @classmethod
    def select_operator(cls, value) -> ComparisonOperatorClass:
        for typ, op_class in cls.CONDITION_MAP.items():
            if isinstance(value, typ):
                return op_class
        raise TypeError(f"No comparison operator available for type: {type(value)}")

