def _generate_config_analysis():
    return AnalysisReport(
        episode_identifier="ep1",
        suggested_changes=[
            ImprovementSuggestion(
                category="config",
                note="Modify grasp force setting",
                parameter_name="grasp_force",
                present_value=0.5,
                proposed_value=0.8,
                explanation="Insufficient gripping strength detected",
            )
        ],
    )


def _generate_behavior_analysis():
    return AnalysisReport(
        episode_identifier="ep2",
        suggested_changes=[
            ImprovementSuggestion(
                category="behavior",
                note="Implement termination condition",
                parameter_name="loop_terminator",
                explanation="Infinite loop behavior observed",
            )
        ],
    )


def _generate_empty_analysis():
    return AnalysisReport(episode_identifier="ep3", suggested_changes=[])


class TestDevStage:
    def setup_method(self):
        self.processor = DevStage()

    def test_configuration_change_yields_config_patch(self):
        result = self.processor.produce_remediation(_generate_config_analysis())
        assert isinstance(result, ConfigPatch)
        assert result.parameter == "grasp_force"

    def test_behavioral_change_yields_behavior_patch(self):
        result = self.processor.produce_remediation(_generate_behavior_analysis())
        assert isinstance(result, BehaviorPatch)
        assert result.rule_identifier == "loop_terminator"

    def test_no_suggestions_yields_none(self):
        result = self.processor.produce_remediation(_generate_empty_analysis())
        assert result is None

    def test_config_patch_includes_explanation(self):
        result = self.processor.produce_remediation(_generate_config_analysis())
        assert result.explanation_text

    def test_retry_with_safety_constraints(self):
        report = _generate_config_analysis()
        initial = self.processor.produce_remediation(report)

        # Simulate QA rejection due to safety constraints
        feedback = QAResult(
            validation_passed=False,
            evaluations=[QACheck(name="safety_margin", validation_result=False, details="exceeds limits")],
            reattempt_requested=True,
        )

        retry_result = self.processor.produce_remediation(
            report, prior_attempt=initial, qa_input=feedback
        )
        assert isinstance(retry_result, ConfigPatch)
        assert "Retry" in retry_result.explanation_text

    def test_retry_with_type_validation_failure(self):
        report = _generate_config_analysis()
        initial = ConfigPatch(parameter="grasp_force", previous_value=0.5, updated_value="invalid")
        feedback = QAResult(
            validation_passed=False,
            evaluations=[QACheck(name="data_type_check", validation_result=False, details="type conflict")],
            reattempt_requested=True,
        )
        retry_result = self.processor.produce_remediation(
            report, prior_attempt=initial, qa_input=feedback
        )
        assert isinstance(retry_result, ConfigPatch)

    def test_behavior_patch_has_default_priority(self):
        result = self.processor.produce_remediation(_generate_behavior_analysis())
        assert isinstance(result, BehaviorPatch)
        assert result.priority_level == 5

    def test_config_patch_maintains_previous_value(self):
        result = self.processor.produce_remediation(_generate_config_analysis())
        assert isinstance(result, ConfigPatch)
        assert result.previous_value == 0.5

    def test_unrecognized_category_falls_back_to_config(self):
        report = AnalysisReport(
            episode_identifier="x",
            suggested_changes=[
                ImprovementSuggestion(category="novel", note="adjustment", parameter_name="param")
            ],
        )
        result = self.processor.produce_remediation(report)
        assert isinstance(result, ConfigPatch)

