        "qwen3_30b_a3b_instruct_2507",
    ]
    candidates.extend(base_dir / name for name in names)
    return [p for p in candidates if p.is_dir()]


def _instantiate_tokenizer(path: Path):
    os.environ.setdefault("TRANSFORMERS_OFFLINE", "1")
