@pytest.mark.parametrize(
    "seq_len,padding_mode,truncation_flag",
    [
        (None, "do_not_pad", None),
        (16, "max_length", True),
        (16, "do_not_pad", True),
        (16, True, None),  # padding=True implies 'longest'; single-sample behaves like no-op pre-packaging
    ],
)
def test_non_chat_tokenizer_padding_truncation_combinations(tmp_path: Path, seq_len, padding_mode, truncation_flag):
    """Verify tensor shapes and label masking across padding/truncation settings for non-chat tokenizers."""
    data_file = _create_jsonl_test_file(tmp_path)

    # Locate a tokenizer lacking chat template
    selected_tokenizer = None
    for candidate_path in _discover_candidate_tokenizer_paths():
        tok = _instantiate_tokenizer(candidate_path)
        if getattr(tok, "chat_template", None) is None:
            selected_tokenizer = tok
            break

    if selected_tokenizer is None:
        pytest.skip("No non-chat tokenizer found in available test resources")

    col_map = {"context": "context", "question": "question", "answer": "answers"}
    ds = ColumnMappedTextInstructionDataset(
        path_or_dataset_id=str(data_file),
        column_mapping=col_map,
        tokenizer=selected_tokenizer,
        seq_length=seq_len,
        padding=padding_mode,
        truncation=truncation_flag,
    )
    first_sample = _get_first_item_from_dataset(ds)

    required_keys = {"input_ids", "labels", "attention_mask"}
    assert required_keys.issubset(first_sample.keys())
    lengths = [len(first_sample[k]) for k in required_keys]
    assert len(set(lengths)) == 1 and lengths[0] > 0

    if isinstance(seq_len, int):
        if truncation_flag is True:
            assert lengths[0] == seq_len
            assert first_sample["labels"][-1] == -100
            assert first_sample["attention_mask"][-1] in {0, 1}
        elif truncation_flag is not True:
            assert lengths[0] != seq_len


