def load_json_config(path: str) -> List[Dict[str, Any]]:
    """Load and parse JSON configuration file with error handling."""
    try:
        full_path = Path(path).resolve()
        if not full_path.exists():
            raise FileNotFoundError(f"Config file missing: {path}")
        with open(full_path, encoding="utf-8") as fp:
            return json.load(fp)
    except json.JSONDecodeError as err:
        raise ValueError(f"Invalid JSON in config file '{path}': {err}")
    except Exception as err:
        raise RuntimeError(f"Failed loading config '{path}': {err}")


def adjust_stage_config(base_path: str, updates: Dict[str, Any] = None, removals: List[str] = None) -> str:
    """Apply modifications to stage config path using helper function."""
    kwargs = {}
    if updates is not None:
        kwargs["updates"] = updates
    if removals is not None:
        kwargs["deletes"] = removals
    if kwargs:
        from tests.conftest import modify_stage_config
        return modify_stage_config(base_path, **kwargs)
    return base_path


def extract_unique_server_specs(configs: List[Dict]) -> List[Tuple[str, str, str]]:
    """Extract unique server configurations based on test name, model, and stage config."""
    seen = set()
    unique_specs = []
    for cfg in configs:
        key_fields = (
            cfg["test_name"],
            cfg["server_params"]["model"],
            str(STAGE_CONFIGS_DIR / cfg["server_params"]["stage_config_name"])
        )
        # Apply optional updates/deletions to stage config path
        stage_path = key_fields[2]
        stage_path = adjust_stage_config(
            stage_path,
            cfg["server_params"].get("update"),
            cfg["server_params"].get("delete")
        )
        spec = (cfg["test_name"], cfg["server_params"]["model"], stage_path)
        if spec not in seen:
            seen.add(spec)
            unique_specs.append(spec)
    return unique_specs


def build_benchmark_map(configs: List[Dict]) -> Dict[str, Dict]:
    """Build mapping from test name to its benchmark parameters."""
    result = {}
    for entry in configs:
        test_id = entry["test_name"]
        if test_id not in result:
            result[test_id] = {
                "test_name": test_id,
                "benchmark_params": []
            }
        result[test_id]["benchmark_params"].extend(entry.get("benchmark_params", []))
    return result


def collect_benchmark_indices(benchmark_map: Dict[str, Dict], configs: List[Dict]) -> List[Tuple[str, int]]:
    """Generate list of (test_name, param_index) pairs for benchmarking."""
    indices = []
    processed_tests = set()
    for cfg in configs:
        tid = cfg["test_name"]
        if tid not in processed_tests:
            processed_tests.add(tid)
            params = benchmark_map.get(tid, {}).get("benchmark_params", [])
            for idx in range(len(params)):
                indices.append((tid, idx))
    return indices


