def execute_benchmark(args: List[str], test_id: str, flow_type: Any, dataset: str, prompt_count: int) -> Dict:
    """Run benchmark command and capture results."""
    timestamp = datetime.now().strftime("%Y%m%d-%H%M%S")
    output_file = f"result_{test_id}_{dataset}_{flow_type}_{prompt_count}_{timestamp}.json"

    cmd = [
        "vllm", "bench", "serve", "--omni"
    ] + args + [
        "--backend", "openai-chat-omni",
        "--endpoint", "/v1/chat/completions",
        "--save-result",
        "--result-dir", os.getenv("BENCHMARK_DIR", "tests"),
        "--result-filename", output_file
    ]

    proc = subprocess.Popen(
        cmd,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
        bufsize=1,
        universal_newlines=True
    )

    # Stream logs
    for stream in [proc.stdout, proc.stderr]:
        for line in iter(stream.readline, ""):
            print(line.rstrip())

    # Extract result directory
    try:
        idx = cmd.index("--result-dir")
        res_dir = cmd[idx + 1]
    except ValueError:
        res_dir = "."

    result_path = Path(res_dir) / output_file
    with open(result_path, encoding="utf-8") as f:
        return json.load(f)


def get_benchmark_parameters(test_name: str) -> List[Dict]:
    """Retrieve benchmark parameters for a given test."""
    return BENCHMARK_MAPPING.get(test_name, {}).get("benchmark_params", [])


def validate_result(actual: Dict, expected: Dict, target_prompts: int):
    """Assert benchmark results meet expected thresholds."""
    assert actual["completed"] == target_prompts, "Some requests failed"
    for metric, baseline in expected.get("baseline", {}).items():
        measured = actual.get(metric)
        if "throughput" in metric:
            assert measured >= baseline, f"{metric}: {measured} < {baseline}"
        else:
            assert measured <= baseline, f"{metric}: {measured} > {baseline}"


@pytest.mark.parametrize("omni_server", SERVER_SPECS, indirect=True)
@pytest.mark.parametrize("benchmark_params", BENCHMARK_INDICES, indirect=True)
def test_performance_benchmark(omni_server, benchmark_params):
    """Main performance test runner."""
    test_id, index = benchmark_params
    if test_id != omni_server.test_name:
        pytest.skip(f"Skipping: server running {omni_server.test_name}, expected {test_id}")

    all_params = get_benchmark_parameters(test_id)
    if not all_params:
        raise ValueError(f"No benchmarks defined for test '{test_id}'")
    if index >= len(all_params):
        raise ValueError(f"Index {index} out of range for test '{test_id}'")

    current_param = all_params[index]
    if current_param.get("dataset_name") == "random-mm":
        pytest.skip("Known issue: skipping 'random-mm' dataset.")

    total = len(all_params)
    print(f"\nBenchmark [{index + 1}/{total}] for '{test_id}'")

    def ensure_list(val, default=None):
        if val is None:
            return [] if default is None else [default]
        return [val] if not isinstance(val, (list, tuple)) else list(val)

    qps_vals = ensure_list(current_param.get("request_rate"))
    prompt_counts = ensure_list(current_param.get("num_prompts"))
    concurrency_vals = ensure_list(current_param.get("max_concurrency"))

    # Normalize lengths
    max_len = max(len(qps_vals), len(concurrency_vals))
    if len(prompt_counts) == 1 and max_len > 1:
        prompt_counts *= max_len
    elif max_len == 1 and len(prompt_counts) > 1:
        if len(qps_vals) == 1:
            qps_vals *= len(prompt_counts)
        if len(concurrency_vals) == 1:
            concurrency_vals *= len(prompt_counts)
        max_len = max(len(qps_vals), len(concurrency_vals))
    elif len(prompt_counts) != max_len and max_len > 0:
        raise ValueError("Mismatch between num_prompts and QPS/concurrency arrays")

    # Build CLI args
    host = omni_server.host
    port = omni_server.port
    cli_args = ["--host", host, "--port", str(port)]

    skip_keys = {"request_rate", "baseline", "num_prompts", "max_concurrency"}
    for k, v in current_param.items():
        if k in skip_keys or v is None:
            continue
        flag = f"--{k.replace('_', '-')}"
        if isinstance(v, bool) and v:
            cli_args.append(flag)
        elif isinstance(v, dict):
            cli_args.extend([flag, json.dumps(v, separators=(",", ":"))])
        else:
            cli_args.extend([flag, str(v)])

    # Run QPS-based benchmarks
    for rate, prompts in zip(qps_vals, prompt_counts):
        run_args = cli_args + ["--request-rate", str(rate), "--num-prompts", str(prompts)]
        result = execute_benchmark(run_args, test_id, rate, current_param["dataset_name"], prompts)
        validate_result(result, current_param, prompts)

    # Run concurrency-based benchmarks
    for conc, prompts in zip(concurrency_vals, prompt_counts):
        run_args = cli_args + [
            "--max-concurrency", str(conc),
            "--num-prompts", str(prompts),
            "--request-rate", "inf"
        ]
        result = execute_benchmark(run_args, test_id, conc, current_param["dataset_name"], prompts)
        validate_result(result, current_param, prompts)

# Type III Clone: Refactored logic for session input ID deduplication and buffering behavior

import asyncio
from collections import deque

# Simulated constants from pty_session module
PTY_PENDING_MAX_BYTES = 1024
PTY_SUBSCRIBER_MAX = 5
PTY_SUBSCRIBER_QUEUE_MAX = 100
REPLAY_END = object()

class ActiveSession:
    def __init__(self, session_id, pty, event_loop):
        self.session_id = session_id
        self.pty = pty
        self.loop = event_loop
        self._seen_input_ids = set()
        self._pending_input = b""
        self._writer_active = False
        self.subscribers = []
        self.buffer = deque()

    def mark_input_id_seen(self, input_id):
        if input_id in self._seen_input_ids:
            return False
        self._seen_input_ids.add(input_id)
        return True

    def write_input(self, data):
        # Combine with any existing pending data
        combined = self._pending_input + data

        # Cap at maximum buffer size
        if len(combined) > PTY_PENDING_MAX_BYTES:
            combined = combined[-PTY_PENDING_MAX_BYTES:]

        # Try to write immediately
        try:
            written = self._attempt_write(combined)
            remaining = combined[written:]
            self._pending_input = remaining
            self._update_writer_state(remaining != b"")
        except BlockingIOError:
            self._pending_input = combined
            self._update_writer_state(True)

    def _attempt_write(self, data):
        # Simulate partial or blocked writes
        try:
            written = pty_session.os.write(self.pty.fd, data)
            return written
        except BlockingIOError:
            raise

    def _update_writer_state(self, should_be_active):
        if should_be_active and not self._writer_active:
            self._writer_active = True
            self.loop.add_writer(self.pty.fd, self._handle_write_completion)
        elif not should_be_active and self._writer_active:
            self._writer_active = False
            self.loop.remove_writer(self.pty.fd)

    def add_subscriber(self, include_replay_end=True):
        # Enforce subscriber limit by removing oldest if necessary
        while len(self.subscribers) >= PTY_SUBSCRIBER_MAX:
            removed = self.subscribers.pop(0)
            self._enqueue_close_sentinel(removed)

        queue = asyncio.Queue(maxsize=PTY_SUBSCRIBER_QUEUE_MAX)
        self.subscribers.append(queue)

        # Replay buffered content
        for item in self.buffer:
            try:
                queue.put_nowait(item)
            except asyncio.QueueFull:
                break

        if include_replay_end:
            try:
                queue.put_nowait(REPLAY_END)
            except asyncio.QueueFull:
                pass

        return queue

    def _enqueue_close_sentinel(self, queue):
        # Drain the queue and ensure sentinel is placed
        try:
            while not queue.empty():
                queue.get_nowait()
        except asyncio.QueueEmpty:
            pass

        try:
            queue.put_nowait(None)
        except asyncio.QueueFull:
            pass

    def _handle_write_completion(self):
        if self._pending_input:
            try:
                written = self._attempt_write(self._pending_input)
                self._pending_input = self._pending_input[written:]
                if not self._pending_input:
                    self._update_writer_state(False)
            except BlockingIOError:
                pass


