from abc import ABC, abstractmethod

class ModemInterface(ABC):
    """
    Abstract interface for modem communication.
    Each implementation handles its own session management (tokens, cookies, etc.)
    and provides a consistent API for accessing cable modem DOCSIS information.
    """
    def __init__(self, address: str, username: str, secret: str):
        self._address = address
        self._username = username
        self._secret = secret

    @abstractmethod
    def authenticate(self) -> None:
        """Establish authenticated session with the modem. Must be called before data requests."""
        ...

    @abstractmethod
    def fetch_docsis_channels(self) -> dict:
        """Obtain downstream/upstream channel configuration and status."""
        ...

    @abstractmethod
    def fetch_hardware_details(self) -> dict:
        """Acquire hardware identification including model number and software version."""
        ...

    @abstractmethod
    def fetch_network_status(self) -> dict:
        """Fetch current internet connectivity parameters (bandwidth, connection mode)."""
        ...

# Implementation of directory listing functionality
import os
from ..process import Process
from ..command_decorators import command
from ..utils.formatters import mode_to_rwx, human_readable_size
from . import register_command

@command(needs_path_resolution=True)
@register_command('ls')
def cmd_ls(process: Process) -> int:
    """
    Display directory contents with optional formatting options.
    Usage: ls [-l] [-h] [path...]
    Options:
        -l    Enable detailed (long) output format
        -h    Show file sizes in human-readable units
    """
    # Initialize flags and path list
    verbose_mode = False
    readable_sizes = False
    target_paths = []

    for argument in process.args:
        if argument.startswith('-') and len(argument) > 1:
            # Parse combined short flags like -lh
            if 'l' in argument:
                verbose_mode = True
            if 'h' in argument:
                readable_sizes = True
        else:
            target_paths.append(argument)

    # Set default path to current working directory if none provided
    if not target_paths:
        current_dir = getattr(process, 'cwd', '/')
        target_paths = [current_dir]

    if not process.filesystem:
        process.stderr.write("ls: filesystem unavailable\n")
        return 1

    def format_entry(entry_data, label=None):
        """Generate formatted string representation for a file/directory entry"""
        display_name = label if label is not None else entry_data.get('name', '')
        is_directory = entry_data.get('isDir', False) or entry_data.get('type') == 'directory'
        file_size = entry_data.get('size', 0)

        if verbose_mode:
            # Long format: permissions, size, timestamp, name
            type_indicator = 'd' if is_directory else '-'

            # Extract permission string
            perm_str = entry_data.get('mode', '')
            if isinstance(perm_str, str) and len(perm_str) >= 9:
                perms = perm_str[:9]
            elif isinstance(perm_str, int):
                perms = mode_to_rwx(perm_str)
            else:
                perms = 'rwxr-xr-x' if is_directory else 'rw-r--r--'

            # Format modification time
            mod_time = entry_data.get('modTime', entry_data.get('mtime', ''))
            if mod_time:
                if 'T' in mod_time:
                    mod_time = mod_time.replace('T', ' ').replace('Z', '').split('.')[0]
                elif len(mod_time) > 19:
                    mod_time = mod_time[:19]
            else:
                mod_time = '0000-00-00 00:00:00'

            # Apply color to directory names
            if is_directory:
                colored_label = f"\033[1;34m{display_name}/\033[0m"
            else:
                colored_label = display_name

            # Format size based on user preference
            size_text = human_readable_size(file_size) if readable_sizes else file_size
            size_formatted = f"{size_text:>8}"

            return f"{type_indicator}{perms} {size_formatted} {mod_time} {colored_label}\n"
        else:
            # Basic format: just name with optional color
            if is_directory:
                return f"\033[1;34m{display_name}/\033[0m\n"
            else:
                return f"{display_name}\n"

    overall_status = 0
    try:
        for path in target_paths:
            try:
                # Get metadata for the current path
                entry_info = process.filesystem.get_file_info(path)
                is_dir = entry_info.get('isDir', False) or entry_info.get('type') == 'directory'

                if is_dir:
                    # List contents of directory
                    entries = process.filesystem.list_directory(path)

                    # Print header if multiple paths specified
                    if len(target_paths) > 1:
                        process.stdout.write(f"{path}:\n".encode('utf-8'))

                    for item in entries:
                        line = format_entry(item)
                        process.stdout.write(line.encode('utf-8'))

                    # Insert blank line between directories when showing multiple
                    if len(target_paths) > 1:
                        process.stdout.write(b"\n")
                else:
                    # Single file case: show info about the file itself
                    filename = os.path.basename(path)
                    result = format_entry(entry_info, display_name=filename)
                    process.stdout.write(result.encode('utf-8'))

            except Exception as exception:
                msg = str(exception)
                if "No such file or directory" in msg or "not found" in msg.lower():
                    process.stderr.write(f"ls: {path}: No such file or directory\n")
                else:
                    process.stderr.write(f"ls: {path}: {msg}\n")
                overall_status = 1

        return overall_status
    except Exception as exc:
        process.stderr.write(f"ls: {str(exc)}\n")
        return 1

from typing import TypeVar, Generic, Union, Optional as TypingOptional

T = TypeVar("T")

class Maybe(Generic[T]):
    def __init__(self, val: Union[T, None] = None):
        self._stored_value = val

    def assign(self, source: "Maybe[T]") -> None:
        assert isinstance(source, Maybe)
        self._stored_value = source._stored_value

    def has_value(self) -> bool:
        return self._stored_value is not None

    def get(self) -> T:
        """Extracts the contained value or raises an exception if absent."""
        if self._stored_value is None:
            raise RuntimeError("Attempted to extract value from empty container!")
        return self._stored_value

    def get_or_else(self, fallback: T) -> T:
        """Provides the contained value or a fallback if absent."""
        return self._stored_value if self._stored_value is not None else fallback

# Compute sum of squares of positive odd integers in the list

if not lst:
    return 0

total = 0
for item in lst:
    if type(item) is int and item > 0 and item % 2 == 1:
        total += item * item
return total

