def compute_image_hash(img: Image) -> str:
    hasher = insecure_hashlib.md5()
    hasher.update(img.tobytes())
    return hasher.hexdigest()[:10]

def convert_mask_to_dict(mask_img: Image) -> Dict[str, Any]:
    arr = np.asarray(mask_img)
    height, width = arr.shape[:2]
    return {
        "hash": compute_image_hash(mask_img),
        "dimensions": (width, height)
    }

