# EchoDecks API Client - Alternative Implementation

import os
import sys
import json
import argparse
import requests

# Base Configuration
API_ENDPOINT = "https://echodecks.com/api/apps/68bc0769be6e58e1c8385b2b/functions/externalApi"

def retrieve_api_key():
    key = os.getenv("ECHODECKS_API_KEY")
    if not key:
        print(json.dumps({"error": "Missing ECHODECKS_API_KEY environment variable."}))
        sys.exit(1)
    return key

def execute_request(http_method, endpoint_path, action_param=None, query_params=None, payload=None):
    auth_headers = {
        "X-API-KEY": retrieve_api_key(),
        "Content-Type": "application/json"
    }

    # Construct URL with base endpoint and resource path
    full_url = f"{API_ENDPOINT}?resource={endpoint_path}"

    # Append optional action parameter
    if action_param:
        full_url += f"&action={action_param}"

    # Add additional query parameters if provided
    if query_params:
        for param_name, param_value in query_params.items():
            if param_value is not None:
                full_url += f"&{param_name}={param_value}"

    try:
        # Execute HTTP request based on method type
        if http_method == "GET":
            response = requests.get(full_url, headers=auth_headers)
        elif http_method == "POST":
            response = requests.post(full_url, headers=auth_headers, json=payload)
        elif http_method == "PUT":
            response = requests.put(full_url, headers=auth_headers, json=payload)
        elif http_method == "DELETE":
            response = requests.delete(full_url, headers=auth_headers)
        else:
            return {"error": f"Unsupported HTTP method: {http_method}"}

        # Raise exception for bad status codes
        response.raise_for_status()

        # Attempt to parse JSON response
        try:
            return response.json()
        except json.JSONDecodeError:
            return {"status": "success", "message": response.text}

    except requests.exceptions.RequestException as exc:
        error_details = str(exc)

        # Try to extract detailed error message from response body
        if hasattr(exc, 'response') and exc.response is not None and exc.response.text:
            try:
                parsed_error = json.loads(exc.response.text)
                error_details = parsed_error.get('message', error_details)
            except (json.JSONDecodeError, AttributeError):
                error_details = exc.response.text

        return {"error": error_details}

# --- Command Handlers ---
def process_list_decks(args):
    return execute_request("GET", "decks", query_params={"id": args.id})

def process_create_deck(args):
    deck_data = {"title": args.title}
    if args.description:
        deck_data["description"] = args.description
    return execute_request("POST", "decks", data=deck_data)

def process_list_cards(args):
    params = {"deck_id": args.deck_id}
    if args.card_id:
        params["id"] = args.card_id
    return execute_request("GET", "cards", query_params=params)

def process_get_due_cards(args):
    return execute_request("GET", "study", action="due", query_params={"deck_id": args.deck_id})

def process_submit_review(args):
    review_payload = {
        "card_id": args.card_id,
        "quality": args.quality
    }
    return execute_request("POST", "study", action="submit", data=review_payload)

def process_generate_cards(args):
    generation_data = {"deck_id": args.deck_id}
    if args.topic:
        generation_data["topic"] = args.topic
    if args.text:
        generation_data["text"] = args.text
    return execute_request("POST", "generate", action="cards", data=generation_data)

def process_generate_podcast(args):
    podcast_data = {
        "deck_id": args.deck_id,
        "style": args.style if args.style else "summary"
    }
    return execute_request("POST", "podcasts", action="generate", data=podcast_data)

def process_list_podcasts(args):
    params = {}
    if args.deck_id:
        params["deck_id"] = args.deck_id
    if args.id:
        params["id"] = args.id
    return execute_request("GET", "podcasts", query_params=params)

def process_get_user_info(args):
    return execute_request("GET", "user")

def process_check_podcast_status(args):
    return execute_request("GET", "podcasts", action="status", query_params={"id": args.id})

# --- Main CLI Application ---
def main():
    cli_parser = argparse.ArgumentParser(description="EchoDecks API Client")
    command_subparsers = cli_parser.add_subparsers(dest="command", required=True)

    # Podcast status command
    p_pod_status = command_subparsers.add_parser("podcast-status", help="Check podcast status")
    p_pod_status.add_argument("--id", required=True)

    # Deck management commands
    p_decks = command_subparsers.add_parser("list-decks", help="List decks or get a specific deck")
    p_decks.add_argument("--id", help="Specific Deck ID")

    p_create_deck = command_subparsers.add_parser("create-deck", help="Create a new deck")
    p_create_deck.add_argument("--title", required=True)
    p_create_deck.add_argument("--description")

    # Card management commands
    p_cards = command_subparsers.add_parser("list-cards", help="List cards in a deck")
    p_cards.add_argument("--deck-id", required=True)
    p_cards.add_argument("--card-id", help="Specific Card ID")

    # Study-related commands
    p_due = command_subparsers.add_parser("get-due", help="Get due cards")
    p_due.add_argument("--deck-id", help="Filter by Deck ID")

    p_review = command_subparsers.add_parser("submit-review", help="Submit a card review")
    p_review.add_argument("--card-id", required=True)
    p_review.add_argument("--quality", type=int, required=True, choices=[0, 1, 2, 3], 
                         help="0=Again, 1=Hard, 2=Good, 3=Easy")

    # Generation commands
    p_gen_cards = command_subparsers.add_parser("generate-cards", help="AI Generate cards")
    p_gen_cards.add_argument("--topic")
    p_gen_cards.add_argument("--text")
    p_gen_cards.add_argument("--deck-id", required=True)

    p_gen_pod = command_subparsers.add_parser("generate-podcast", help="AI Generate podcast")
    p_gen_pod.add_argument("--deck-id", required=True)
    p_gen_pod.add_argument("--style", default="summary", help="Podcast style (e.g., summary, conversation)")

    # Podcast management commands
    p_pods = command_subparsers.add_parser("list-podcasts", help="List podcasts")
    p_pods.add_argument("--deck-id")
    p_pods.add_argument("--id")

    # User info command
    subparsers.add_parser("get-user", help="Get user info")

    # Parse arguments
    args = cli_parser.parse_args()

    # Command routing dictionary
    command_handlers = {
        "list-decks": process_list_decks,
        "create-deck": process_create_deck,
        "list-cards": process_list_cards,
        "get-due": process_get_due_cards,
        "submit-review": process_submit_review,
        "generate-cards": process_generate_cards,
        "generate-podcast": process_generate_podcast,
        "list-podcasts": process_list_podcasts,
        "podcast-status": process_check_podcast_status,
        "get-user": process_get_user_info
    }

    # Execute appropriate handler
    if args.command in command_handlers:
        result = command_handlers[args.command](args)
        print(json.dumps(result, indent=2))
    else:
        print(json.dumps({"error": "Unknown command"}))

if __name__ == "__main__":
    main()

# Retrieve a directory path from an environment variable

from os import environ
from pathlib import Path
from epstein_files.util.logging import exit_with_error, logger

def get_environment_directory(env_name: str, required: bool = True) -> Path | None:
    # Check if the environment variable is set
    env_value = environ.get(env_name)

    if env_value:
        dir_path = Path(env_value)
        error_message = f"environment variable {env_name} points to '{dir_path}' which is not a valid directory"

        if dir_path.is_dir():
            return dir_path
        elif required:
            exit_with_error(f"Required {error_message}.\n")
        else:
            logger.warning(f"Optional {error_message}. Some functionality may be limited.")
            return None
    else:
        logger.warning(f"Optional environment variable {env_name} is not defined. Some features might be unavailable.")

import enum
import inspect
from typing import TYPE_CHECKING, Iterable, List, Optional, Tuple, Union

if TYPE_CHECKING:
    from ..configuration_utils import PretrainedConfig


class BackboneType(enum.Enum):
    TIMM = "timm"
    TRANSFORMERS = "transformers"


def validate_backbone_outputs(
    output_names: Optional[Iterable[str]], 
    output_indices: Optional[Iterable[int]], 
    stage_labels: Optional[Iterable[str]]
) -> None:
    """
    Validate that output_names and output_indices are compatible with stage_labels.
    """
    if stage_labels is None:
        raise ValueError("stage_labels must be provided for transformer backbones")

    if output_names is not None:
        if not isinstance(output_names, list):
            raise TypeError(f"output_names must be a list, got {type(output_names)}")

        invalid_items = [item for item in output_names if item not in stage_labels]
        if invalid_items:
            raise ValueError(f"output_names contains invalid items: {invalid_items}. Must be subset of {stage_labels}")

        if len(output_names) != len(set(output_names)):
            raise ValueError(f"output_names must be unique, got {output_names}")

        expected_order = [name for name in stage_labels if name in output_names]
        if output_names != expected_order:
            raise ValueError(f"output_names must follow the order in stage_names. Expected {expected_order}, got {output_names}")

    if output_indices is not None:
        if not isinstance(output_indices, list):
            raise TypeError(f"output_indices must be a list, got {type(output_indices)}")

        # Normalize negative indices to positive equivalents
        normalized_indices = tuple(idx % len(stage_labels) if idx < 0 else idx for idx in output_indices)

        invalid_indices = [idx for idx in normalized_indices if idx not in range(len(stage_labels))]
        if invalid_indices:
            raise ValueError(f"output_indices contain invalid values: {invalid_indices}. Must be in range [0, {len(stage_labels)-1}]")

        if len(normalized_indices) != len(set(normalized_indices)):
            msg = f"output_indices must be unique, got {output_indices}"
            if normalized_indices != tuple(output_indices):
                msg += f" (equivalent to {normalized_indices})"
            raise ValueError(msg)

        sorted_indices = sorted(normalized_indices)
        if normalized_indices != tuple(sorted_indices):
            # Reconstruct original values in correct order
            sorted_original = [val for _, val in sorted(zip(normalized_indices, output_indices), key=lambda x: x[0])]
            raise ValueError(f"output_indices must be in ascending order. Expected {sorted_original}, got {output_indices}")

    if output_names is not None and output_indices is not None:
        if len(output_names) != len(output_indices):
            raise ValueError("output_names and output_indices must have the same length when both are specified")

        expected_names = [stage_labels[idx] for idx in output_indices]
        if output_names != expected_names:
            raise ValueError(f"output_names and output_indices must correspond to the same stages. Expected {expected_names}, got {output_names}")


def _match_output_features_and_indices(
    feature_names: Optional[List[str]],
    index_list: Optional[Union[List[int], Tuple[int]]],
    stage_labels: List[str],
) -> Tuple[List[str], List[int]]:
    """
    Derive matching output features and indices based on provided inputs.

    Logic:
        - Neither set: use last stage
        - Only features set: derive indices from features
        - Only indices set: derive features from indices
        - Both set: return as-is (after validation)
    """
    if feature_names is None and index_list is None:
        index_list = [len(stage_labels) - 1]
        feature_names = [stage_labels[-1]]
    elif feature_names is None and index_list is not None:
        feature_names = [stage_labels[i] for i in index_list]
    elif index_list is None and feature_names is not None:
        index_list = [stage_labels.index(name) for name in feature_names]

    return feature_names, index_list


def get_consistent_backbone_outputs(
    feature_names: Optional[List[str]],
    index_list: Optional[Union[List[int], Tuple[int]]],
    stage_labels: List[str],
) -> Tuple[List[str], List[int]]:
    """
    Ensure consistent alignment between output features and indices.

    Logic:
        - If only one is provided, compute the other
        - If both are provided, verify they match
        - If neither is provided, default to last stage
    """
    # Convert indices to list if needed
    index_list = list(index_list) if index_list is not None else None

    # Validate initial inputs
    validate_backbone_outputs(feature_names, index_list, stage_labels)

    # Compute aligned outputs
    aligned_features, aligned_indices = _match_output_features_and_indices(
        feature_names=feature_names,
        index_list=index_list,
        stage_labels=stage_labels
    )

    # Validate final outputs
    validate_backbone_outputs(aligned_features, aligned_indices, stage_labels)

    return aligned_features, aligned_indices


class BackboneMixin:
    backbone_type: Optional[BackboneType] = None

    def _setup_timm_backbone(self, config) -> None:
        """Initialize timm backbone after loading."""
        if not hasattr(self, "_backbone") or self._backbone is None:
            raise ValueError("_backbone must be assigned before calling _setup_timm_backbone")

        # Extract stage names and channel counts from feature info
        self.stage_names = [info["module"] for info in self._backbone.feature_info.info]
        self.num_channels = [info["num_chs"] for info in self._backbone.feature_info.info]

        # Handle out_indices and module names from feature_info
        raw_out_indices = list(self._backbone.feature_info.out_indices)
        raw_out_features = self._backbone.feature_info.module_name()

        # Validate against stage names
        validate_backbone_outputs(raw_out_features, raw_out_indices, self.stage_names)

        self._out_features, self._out_indices = raw_out_features, raw_out_indices

    def _setup_transformers_backbone(self, config) -> None:
        stage_labels = getattr(config, "stage_names")
        feature_names = getattr(config, "out_features", None)
        index_list = getattr(config, "out_indices", None)

        self.stage_names = stage_labels
        self._out_features, self._out_indices = get_consistent_backbone_outputs(
            feature_names=feature_names,
            index_list=index_list,
            stage_labels=stage_labels
        )
        self.num_channels = None  # Set later by transformer backbone

    def _initialize_backbone(self, config) -> None:
        """Main initialization method called after loading pretrained weights."""
        self.config = config
        self.is_timm_backbone = getattr(config, "use_timm_backbone", False)
        self.backbone_type = BackboneType.TIMM if self.is_timm_backbone else BackboneType.TRANSFORMERS

        if self.backbone_type == BackboneType.TIMM:
            self._setup_timm_backbone(config)
        elif self.backbone_type == BackboneType.TRANSFORMERS:
            self._setup_transformers_backbone(config)
        else:
            raise ValueError(f"Unsupported backbone type: {self.backbone_type}")

    @property
    def output_features(self):
        return self._out_features

    @output_features.setter
    def output_features(self, new_features: List[str]) -> None:
        """Update output features and synchronize indices accordingly."""
        self._out_features, self._out_indices = get_consistent_backbone_outputs(
            feature_names=new_features,
            index_list=None,
            stage_labels=self.stage_names
        )

    @property
    def output_indices(self):
        return self._out_indices

    @output_indices.setter
    def output_indices(self, new_indices: Union[Tuple[int], List[int]]) -> None:
        """Update output indices and synchronize features accordingly."""
        self._out_features, self._out_indices = get_consistent_backbone_outputs(
            feature_names=None,
            index_list=new_indices,
            stage_labels=self.stage_names
        )

    @property
    def feature_channels(self):
        """Return dictionary mapping stage names to their channel counts."""
        return {stage: self.num_channels[i] for i, stage in enumerate(self.stage_names)}

    @property
    def active_channels(self):
        """Return channel counts for selected output features."""
        return [self.feature_channels[name] for name in self.output_features]

    def forward_with_filtered_kwargs(self, *args, **kwargs):
        """Forward pass filtering kwargs to match method signature."""
        sig_params = inspect.signature(self.forward).parameters
        filtered = {k: v for k, v in kwargs.items() if k in sig_params}
        return self(*args, **filtered)

    def forward(self, pixel_values, output_hidden_states=None, output_attentions=None, return_dict=None):
        raise NotImplementedError("This method must be implemented by subclasses.")

    def to_dict(self):
        """Serialize instance to dictionary including out_features and out_indices."""
        base_dict = super().to_dict()
        base_dict["out_features"] = base_dict.pop("_out_features")
        base_dict["out_indices"] = base_dict.pop("_out_indices")
        return base_dict


class BackboneConfigMixin:
    """Mixin to handle out_features and out_indices in backbone configurations."""

    @property
    def output_features(self):
        return self._out_features

    @output_features.setter
    def output_features(self, new_features: List[str]) -> None:
        self._out_features, self._out_indices = get_consistent_backbone_outputs(
            feature_names=new_features,
            index_list=None,
            stage_labels=self.stage_names
        )

    @property
    def output_indices(self):
        return self._out_indices

    @output_indices.setter
    def output_indices(self, new_indices: Union[Tuple[int], List[int]]) -> None:
        self._out_features, self._out_indices = get_consistent_backbone_outputs(
            feature_names=None,
            index_list=new_indices,
            stage_labels=self.stage_names
        )

    def to_dict(self):
        """Serialize configuration including out_features and out_indices."""
        base_dict = super().to_dict()
        base_dict["out_features"] = base_dict.pop("_out_features")
        base_dict["out_indices"] = base_dict.pop("_out_indices")
        return base_dict


def create_backbone(config):
    """Factory function to instantiate backbone models based on configuration."""
    from transformers import AutoBackbone, AutoConfig

    backbone_config = getattr(config, "backbone_config", None)
    use_timm = getattr(config, "use_timm_backbone", None)
    use_pretrained = getattr(config, "use_pretrained_backbone", None)
    checkpoint_path = getattr(config, "backbone", None)
    extra_kwargs = getattr(config, "backbone_kwargs", {}) or {}

    # Check conflicting parameters
    if backbone_config and checkpoint_path and use_pretrained is not None:
        raise ValueError("Cannot specify both 'backbone' and 'backbone_config' with 'use_pretrained_backbone'")

    # Case 1: No backbone-related config - use full AutoBackbone.from_config
    if not any([backbone_config, use_timm, checkpoint_path]):
        return AutoBackbone.from_config(config=config, **extra_kwargs)

    # Case 2: Use timm backbone
    if use_timm:
        if not checkpoint_path:
            raise ValueError("'backbone' must be specified when using timm backbone")
        return AutoBackbone.from_pretrained(
            checkpoint_path,
            use_timm_backbone=True,
            use_pretrained_backbone=use_pretrained,
            **extra_kwargs
        )

    # Case 3: Use pretrained backbone
    if use_pretrained:
        if not checkpoint_path:
            raise ValueError("'backbone' must be specified when using pretrained backbone")
        return AutoBackbone.from_pretrained(checkpoint_path, **extra_kwargs)

    # Case 4: Create from config
    if not backbone_config and not checkpoint_path:
        raise ValueError("Either 'backbone_config' or 'backbone' must be specified")

    if not backbone_config:
        backbone_config = AutoConfig.from_pretrained(checkpoint_path, **extra_kwargs)

    return AutoBackbone.from_config(config=backbone_config)


def validate_backbone_setup(
    use_timm: bool,
    use_pretrained: bool,
    backbone_name: Optional[str],
    backbone_cfg: Optional[Union[dict, "PretrainedConfig"]],
    extra_kwargs: Optional[dict],
) -> None:
    """Validate backbone configuration arguments."""
    if backbone_cfg and backbone_name:
        raise ValueError("Cannot specify both 'backbone' and 'backbone_config'")

    if backbone_cfg and use_timm:
        raise ValueError("Cannot specify both 'backbone_config' and 'use_timm_backbone'")

    if extra_kwargs and backbone_cfg:
        raise ValueError("Cannot specify both 'backbone_kwargs' and 'backbone_config'")

import os
import socket
from datetime import timedelta
from typing import Any, Dict, List, Optional, Tuple, Union
try:
    import torch
    import torch.distributed as dist

    def setup_distributed_group(timeout: Optional[timedelta] = None):
        """
        Initialize distributed backend only if launched via multi-process launcher (e.g., torchrun).
        Uses environment variables RANK, WORLD_SIZE, LOCAL_RANK unless overridden explicitly.
        """
        if dist.is_initialized():
            return

        rank = int(os.getenv("RANK", "0"))
        world_size = int(os.getenv("WORLD_SIZE", "1"))
        local_device_idx = int(os.getenv("LOCAL_RANK", "0"))

        if world_size <= 1:
            return

        # Set device per rank
        torch.cuda.set_device(local_device_idx)

        # Use default timeout unless specified
        effective_timeout = timeout if timeout is not None else timedelta(minutes=5)

        dist.init_process_group(
            backend="nccl",
            rank=rank,
            world_size=world_size,
            device_id=torch.device(f"cuda:{local_device_idx}"),
            init_method="env://",
            timeout=effective_timeout,
        )

    def teardown_distributed_group():
        """Safely finalize distributed group, ensuring CUDA device consistency."""
        if not dist.is_initialized():
            return

        try:
            # Ensure all ranks synchronize before cleanup
            if torch.cuda.is_available():
                local_rank = int(os.getenv("LOCAL_RANK", "0"))
                try:
                    torch.cuda.set_device(local_rank)
                except Exception:
                    pass
                dist.barrier(device_ids=[local_rank])
            else:
                dist.barrier()
        except Exception:
            pass  # Ignore barrier errors during shutdown

        try:
            dist.destroy_process_group()
        except Exception:
            pass  # Best-effort cleanup; ignore NCCL errors post-failure

    def collect_all_ranks_data(payload: Any) -> List[Any]:
        """
        Aggregate data from all ranks into a single list on each rank.
        - If payload is None → skip (return empty list).
        - If payload is list → flatten across ranks.
        - Otherwise → wrap each rank’s payload as element in result list.
        """
        if not dist.is_initialized():
            return [] if payload is None else ([payload] if not isinstance(payload, list) else payload)

        world = dist.get_world_size()
        buffer = [None] * world
        dist.all_gather_object(buffer, payload)
        filtered = [item for item in buffer if item is not None]

        if not filtered:
            return []

        # Flatten lists if all items are lists
        if isinstance(filtered[0], list):
            return [elem for sub in filtered for elem in sub]
        return filtered

    def am_i_primary() -> bool:
        if not dist.is_initialized():
            raise RuntimeError("Distributed group must be initialized to determine primary rank.")
        return dist.get_rank() == 0

    def get_local_device_index() -> int:
        """Determine local device index using distributed info or env vars."""
        if dist.is_available() and dist.is_initialized():
            ngpus = torch.cuda.device_count()
            return dist.get_rank() % ngpus if ngpus > 0 else 0
        if "LOCAL_RANK" in os.environ:
            return int(os.environ["LOCAL_RANK"])
        return 0

    def current_cuda_device() -> torch.device:
        dev_idx = get_local_device_index()
        torch.cuda.set_device(dev_idx)
        return torch.device(f"cuda:{dev_idx}")

    def fetch_rank_and_world() -> Tuple[int, int]:
        """Retrieve current rank and world size, preferring distributed context over env vars."""
        if dist.is_available() and dist.is_initialized():
            return dist.get_rank(), dist.get_world_size()
        return (
            int(os.getenv("RANK", "0")),
            int(os.getenv("WORLD_SIZE", "1"))
        )

    def gather_timing_samples(samples: List[float]) -> List[List[float]]:
        """
        Collect per-rank timing lists to rank 0 only.
        Returns list-of-lists on root, empty list elsewhere.
        """
        rank, world = fetch_rank_and_world()
        if world == 1:
            return [samples]

        if rank == 0:
            out = [None] * world
            dist.gather_object(samples, object_gather_list=out, dst=0)
            return out
        else:
            dist.gather_object(samples, dst=0)
            return []

    def collect_hostnames() -> List[str]:
        """Gather hostnames from all ranks onto rank 0."""
        rank, world = fetch_rank_and_world()
        hostname = socket.gethostname()

        if world == 1:
            return [hostname]

        if rank == 0:
            result = [None] * world
            dist.gather_object(hostname, result, dst=0)
            return result
        else:
            dist.gather_object(hostname, dst=0)
            return []

    def aggregate_metrics(metrics: Dict[str, Any], target_rank: int = 0) -> Optional[List[Dict[str, Any]]]:
        """
        Merge per-rank metrics dictionaries into one list at target_rank.
        Adds 'host', 'rank', and 'world' fields automatically.
        """
        rank, world = fetch_rank_and_world()
        extended = {**metrics, "host": socket.gethostname(), "rank": rank, "world": world}

        if world == 1 or not (dist.is_available() and dist.is_initialized()):
            return [extended]

        if rank == target_rank:
            gathered = [None] * world
            dist.gather_object(extended, object_gather_list=gathered, dst=target_rank)
            return [entry for entry in gathered if entry is not None]
        else:
            dist.gather_object(extended, dst=target_rank)
            return None

    def resolve_precision(name: str) -> torch.dtype:
        """Map string dtype name to corresponding PyTorch type."""
        normalized = name.lower().strip()
        mapping = {
            "bf16": torch.bfloat16,
            "bfloat16": torch.bfloat16,
            "fp16": torch.float16,
            "half": torch.float16,
            "float16": torch.float16,
            "fp32": torch.float32,
            "float": torch.float32,
            "float32": torch.float32,
        }
        if normalized in mapping:
            return mapping[normalized]
        raise ValueError(f"Unsupported precision specifier: '{name}'")

except ImportError:
    print("[WARNING] Distributed utilities require PyTorch; skipping.")

def interpret_memory_spec(spec: str) -> int:
    """Parse human-readable memory strings like '1M', '2.5G' into bytes."""
    suffixes = {"K": 1024, "M": 1024 ** 2, "G": 1024 ** 3}
    spec_clean = spec.strip().upper()
    if spec_clean[-1] in suffixes:
        multiplier = suffixes[spec_clean[-1]]
        value = float(spec_clean[:-1])
        return int(value * multiplier)
    return int(spec_clean)

def extract_hostname() -> str:
    return socket.gethostname()

def ceiling_division(dividend: int, divisor: int) -> int:
    """Compute ceil(dividend / divisor) without floating point."""
    return (dividend + divisor - 1) // divisor

def construct_sibling_path(original: str, infix: str, ext_default: str = ".csv") -> str:
    """
    Insert infix before file extension, preserving double extensions like .csv.gz.
    Returns empty string if input is '-' or empty.
    """
    if not original or original == "-":
        return ""

    base, ext = os.path.splitext(original)
    ext_lower = ext.lower()

    if ext_lower == ".gz":
        inner_base, inner_ext = os.path.splitext(base)
        return f"{inner_base}{infix}{inner_ext}.gz"
    elif ext_lower in {".md", ".markdown", ".csv", ".tsv", ".jsonl", ".gz"}:
        return f"{base}{infix}{ext}"
    else:
        return f"{original}{infix}{ext_default}"

def decode_size_sequence(input_str: str) -> set[int]:
    """Convert comma-separated size specs (e.g., '1M, 16M') into set of byte counts."""
    if not input_str:
        return set()
    tokens = [t.strip() for t in input_str.split(",") if t.strip()]
    return {interpret_memory_spec(tok) for tok in tokens}

# Distributed computing utilities for managing multi-process and multi-node training environments

import os
import torch.distributed as dist

__all__ = [
    "DistributedConfig",
    "configure_distributed",
    "is_slurm_job",
    "get_local_process_index",
    "get_total_processes",
    "get_global_process_id",
    "get_node_count",
    "get_slurm_world_size",
    "get_slurm_global_rank",
    "is_distributed_mode",
    "is_primary_process",
    "is_data_primary_process",
    "is_local_leader",
    "synchronize",
]

class DistributedConfig:
    @staticmethod
    def is_slurm_job() -> bool:
        return "SLURM_PROCID" in os.environ

    def get_local_process_index(self) -> int:
        if "SLURM_LOCALID" in os.environ:
            return int(os.environ["SLURM_LOCALID"])
        return self.get_global_process_id()

    def get_node_count(self) -> int:
        if "SLURM_JOB_NUM_NODES" in os.environ:
            return int(os.environ["SLURM_JOB_NUM_NODES"])
        return 1

    def get_slurm_world_size(self) -> int:
        return self.get_node_count() * int(os.environ.get("SLURM_NTASKS_PER_NODE", 1))

    def get_slurm_global_rank(self) -> int:
        if "SLURM_PROCID" in os.environ:
            return int(os.environ["SLURM_PROCID"])
        raise RuntimeError("SLURM_PROCID not found in environment, cannot determine SLURM global rank")

    @staticmethod
    def is_distributed_mode() -> bool:
        return dist.is_available() and dist.is_initialized()

    def get_global_process_id(self) -> int:
        if self.is_distributed_mode():
            return dist.get_rank()
        return 0

    def get_total_processes(self) -> int:
        if self.is_distributed_mode():
            return dist.get_world_size()
        return 1

    def is_data_primary_process(self) -> bool:
        # Data loading must be coordinated to avoid race conditions
        # - is_local_leader: handles data copying in single/multi-GPU scenarios (including SLURM)
        # - get_total_processes == 1: SLURM jobs without multi-GPU require each process to load data independently
        return self.is_local_leader() or self.get_total_processes() == 1

    def is_primary_process(self) -> bool:
        return self.get_global_process_id() == 0

    def is_local_leader(self) -> bool:
        return self.get_local_process_index() == 0

    def synchronize(self) -> None:
        if self.is_distributed_mode():
            dist.barrier()

# Global configuration instance
_config_instance: DistributedConfig = DistributedConfig()

def configure_distributed(new_config: DistributedConfig):
    """Set a new distributed configuration instance."""
    global _config_instance
    _config_instance = new_config

def is_slurm_job():
    """Check if running under SLURM job scheduler."""
    return _config_instance.is_slurm_job()

def get_local_process_index():
    """Get the local process index within the node."""
    return _config_instance.get_local_process_index()

def get_node_count():
    """Get the number of nodes in the job."""
    return _config_instance.get_node_count()

def get_slurm_world_size():
    """Get total number of processes managed by SLURM."""
    return _config_instance.get_slurm_world_size()

def get_slurm_global_rank():
    """Get the global rank according to SLURM."""
    return _config_instance.get_slurm_global_rank()

def is_distributed_mode():
    """Check if distributed mode is active."""
    return _config_instance.is_distributed_mode()

def get_global_process_id():
    """Get the global process ID across all nodes."""
    return _config_instance.get_global_process_id()

def get_total_processes():
    """Get total number of processes in the distributed setup."""
    return _config_instance.get_total_processes()

def is_data_primary_process():
    """Determine if current process should handle data loading."""
    return _config_instance.is_data_primary_process()

def is_primary_process():
    """Check if current process has rank 0."""
    return _config_instance.is_primary_process()

def is_local_leader():
    """Check if current process is the leader on its node."""
    return _config_instance.is_local_leader()

def synchronize():
    """Synchronize all processes in the distributed group."""
    return _config_instance.synchronize()

import torch
import habana_frameworks.torch.core as htcore
import habana_frameworks.torch.utils.experimental as htexp

# Detect device type
is_hpu_gaudi2 = htexp._get_device_type() == htexp.synDeviceType.synDeviceGaudi2

def _compute_gaudi2_scale_ratio():
    """Compute the scale factor between float8_e4m3fn and float8_e4m3fnuz max values."""
    return (torch.finfo(torch.float8_e4m3fn).max / torch.finfo(torch.float8_e4m3fnuz).max)

# Exponent width configuration for different dtypes
EXPONENT_WIDTHS = {
    torch.float32: 8,
    torch.bfloat16: 8,
    torch.float8_e4m3fn: 4,
    torch.float8_e5m2: 5,
}

def _compute_default_exponent_bias(dtype):
    """Calculate default exponent bias based on exponent width."""
    width = EXPONENT_WIDTHS[dtype]
    return (1 << (width - 1)) - 1  # 2**(exp_width - 1) - 1

# Hardware-specific exponent bias sets
EXPLICIT_BIAS_CONFIGS = {
    ("GAUDI2", torch.float8_e4m3fn): [3, 7, 11, 15],
    ("GAUDI2", torch.float8_e5m2): [15],
    ("GAUDI3", torch.float8_e4m3fn): list(range(0, 63)),
    ("GAUDI3", torch.float8_e5m2): list(range(0, 63)),
}

# Maximum representable values per dtype
MAX_REPRESENTABLE = {
    torch.float32: torch.finfo(torch.float32).max,
    torch.bfloat16: torch.finfo(torch.bfloat16).max,
    torch.float8_e4m3fn: torch.finfo(torch.float8_e4m3fn).max,
    torch.float8_e5m2: torch.finfo(torch.float8_e5m2).max,
}

# Attempt to add float8_e4m3fnuz support if available
try:
    MAX_REPRESENTABLE[torch.float8_e4m3fnuz] = torch.finfo(torch.float8_e4m3fnuz).max
except AttributeError:
    pass

def _compute_fullscale_value(dtype, device_name, exp_bias=None):
    """Compute full-scale value considering device and exponent bias."""
    base_exp_bias = _compute_default_exponent_bias(dtype)

    # Special handling for GAUDI2 with float8_e4m3fn
    if device_name == "GAUDI2" and dtype == torch.float8_e4m3fn:
        try:
            scale_val = MAX_REPRESENTABLE[torch.float8_e4m3fnuz]
        except KeyError:
            scale_val = MAX_REPRESENTABLE[dtype]
    else:
        scale_val = MAX_REPRESENTABLE[dtype]

    # Adjust for custom exponent bias if provided
    effective_bias = exp_bias if exp_bias is not None else base_exp_bias
    adjusted_scale = scale_val * (2 ** (base_exp_bias - effective_bias))

    return float(adjusted_scale)

def _generate_scales_for_biases(dtype, device_name, bias_list):
    """Generate fullscale values for a list of exponent biases."""
    return [_compute_fullscale_value(dtype, device_name, eb) for eb in bias_list]

def _normalize_scales_to_hardware_alignment(dtype, device_name):
    """Normalize scales to hardware-aligned values for FP8 types."""
    bias_set = EXPLICIT_BIAS_CONFIGS.get((device_name, dtype), None)
    if bias_set is None:
        return None

    full_scales = _generate_scales_for_biases(dtype, device_name, bias_set)
    base_fullscale = _compute_fullscale_value(dtype, device_name)

    return [scale / base_fullscale for scale in full_scales]

# Device scaling factors
DEVICE_SCALE_MULTIPLIERS = {
    "GAUDI2": 4,
    "GAUDI3": 1,
}

# Pre-compute FP8 e4m3fn aligned scales per device
FP8_E4M3_SCALES_PER_DEVICE = {
    dev: _normalize_scales_to_hardware_alignment(torch.float8_e4m3fn, dev)
    for dev in DEVICE_SCALE_MULTIPLIERS.keys()
}

# Compute min/max/stride traits per device
FP8_E4M3_TRAITS_PER_DEVICE = {
    dev: (
        min(FP8_E4M3_SCALES_PER_DEVICE[dev]),
        max(FP8_E4M3_SCALES_PER_DEVICE[dev]),
        DEVICE_SCALE_MULTIPLIERS[dev],
    )
    for dev in DEVICE_SCALE_MULTIPLIERS.keys()
}

class PowerOfTwoScaler:
    """Scale input to nearest higher power of two."""
    def compute(self, scale_tensor):
        log2_scale = torch.log2(scale_tensor)
        ceil_log2 = torch.ceil(log2_scale)
        return 2.0 ** ceil_log2

class HardwareAlignedScaler:
    """Adjust scale to be hardware-aligned for FP8 computation."""
    def __init__(self, preferred_device="GAUDI3"):
        self.target_device = "GAUDI2" if is_hpu_gaudi2 else "GAUDI3"

    def compute(self, scale_tensor):
        # Apply Gaudi2-specific scaling if needed
        if self.target_device == "GAUDI2":
            scale_tensor = scale_tensor * _compute_gaudi2_scale_ratio()

        # First convert to power-of-two
        pow2_scaled = PowerOfTwoScaler().compute(scale_tensor)

        # Get hardware constraints
        min_val, max_val, stride = FP8_E4M3_TRAITS_PER_DEVICE[self.target_device]

        # Align to stride boundaries
        log2_pow2 = torch.log2(pow2_scaled)
        aligned_log2 = torch.floor(log2_pow2 / stride) * stride
        hw_aligned = 2.0 ** aligned_log2

        # Clamp within bounds
        clamped = torch.clamp(
            hw_aligned,
            min=torch.tensor(min_val, dtype=scale_tensor.dtype, device=scale_tensor.device),
            max=torch.tensor(max_val, dtype=scale_tensor.dtype, device=scale_tensor.device)
        )

        return clamped

