def _poll_server_health(base_url: str, endpoint: str = "/.well-known/agent.json", 
                        max_attempts: int = 60, delay: float = 0.5) -> bool:
    """Check if a server is ready by polling its health endpoint.

    Args:
        base_url: Base URL of the server to check
        endpoint: Health check endpoint path
        max_attempts: Maximum number of polling attempts
        delay: Seconds between attempts

    Returns:
        True if server responds with 200 OK within timeout, False otherwise
    """
    target_url = f"{base_url}{endpoint}"
    for _ in range(max_attempts):
        try:
            response = httpx.get(target_url, timeout=2.0)
            if response.status_code == 200:
                return True
        except (httpx.RequestError, httpx.TimeoutException):
            pass
        time.sleep(delay)
    return False


@contextmanager
def _create_process_group(cmd: list, env: dict):
    """Context manager that creates a new process group and ensures cleanup."""
    proc = subprocess.Popen(
        cmd,
        env={**os.environ, **env},
        start_new_session=True,
    )
    try:
        yield proc
    finally:
        if proc.poll() is None:
            try:
                pgid = os.getpgid(proc.pid)
                os.killpg(pgid, signal.SIGTERM)
                proc.wait(timeout=5)
            except (ProcessLookupError, subprocess.TimeoutExpired):
                try:
                    pgid = os.getpgid(proc.pid)
                    os.killpg(pgid, signal.SIGKILL)
                except ProcessLookupError:
                    pass


def start_recruiter_server():
    """Start the recruiter A2A server in background and return process handle."""
    cmd = [sys.executable, "src/agent_recruiter/server/server.py"]
    env = {"ENABLE_HTTP": "true"}
    return _create_process_group(cmd, env)


def start_sample_agent(port: int = 3210, wait_timeout: float = 30.0):
    """Start a sample A2A agent on specified port and return (process, url)."""
    port_str = str(port)
    cmd = [sys.executable, "-m", "test.sample_agent.server"]
    env = {"PORT": port_str}
    base_url = f"http://localhost:{port}"

    with _create_process_group(cmd, env) as proc:
        # Wait for server readiness
        if not _poll_server_health(base_url, max_attempts=int(wait_timeout / 0.5)):
            raise RuntimeError(f"Sample agent failed to start on {base_url}")
        yield proc, base_url


def create_agent_card(name: str = "TestAgent", port: int = 3210):
