def publish_directory_record(record_path: str = "test/sample_agent/sample_agent_record.json"):
    """Publish a directory record using dirctl and return its CID."""
    result = subprocess.run(
        ["dirctl", "push", record_path],
        capture_output=True,
        text=True,
        timeout=30,
    )

    if result.returncode != 0:
        raise RuntimeError(
            f"Failed to push record to directory: {result.stderr}\n"
            f"stdout: {result.stdout}"
        )

    output = result.stdout + result.stderr
    cid_match = re.search(r"CID:\s*(\S+)", output)
    if not cid_match:
        raise RuntimeError(f"Could not parse CID from dirctl output: {output}")

    return cid_match.group(1)


def delete_directory_record(cid: str):
    """Delete a directory record by CID."""
    try:
        result = subprocess.run(
            ["dirctl", "delete", cid],
            capture_output=True,
            text=True,
            timeout=30,
        )
        return result.returncode == 0
    except FileNotFoundError:
        return False

