class MaestroController:
    '''
        The MaestroController class provides similar functionality to ServoController
        but specifically for Maestro boards. It allows seamless switching between
        different controller types in binary mode operations.
    '''
    def __init__(self, dev_addr=0x0c, start_pin=0, pin_count=6):
        self.start_pin = start_pin
        self.byte_span = pin_count * 2  # Each pin uses 2 bytes in Maestro format
        self.address = dev_addr

    def update_bytes(self, byte_data, offset=0):
        '''
            Processes byte arrays for Maestro PWM control commands.
            Assumes 2-byte format per channel (value low/high)
        '''
        initialize_maestro()
        if maestro_ctrl is not None:
            maestro_ctrl.set_board(self.address)
            commands = []
            for idx in range(0, len(byte_data), 2):
                # Construct Maestro command packet
                cmd = chr(0x04) + chr(offset) + chr(int.from_bytes([byte_data[idx+1]], 'little')) + chr(int.from_bytes([byte_data[idx]], 'little'))
                commands.append(cmd)
                offset += 1
            maestro_ctrl.send_commands(commands)

    def get_address(self):
        return self.address

