def shift_register_update():
    if _data_pin is None or _latch_pin is None or _clock_pin is None or _clear_pin is None: 
        return

    data_pin = Pin(_data_pin, Pin.OUT)
    clock_pin = Pin(_latch_pin, Pin.OUT)
    shift_pin = Pin(_clock_pin, Pin.OUT)
    clear_pin = Pin(_clear_pin, Pin.OUT)

    clear_pin.on()  # Ensure no clearing operation

    for i in range(len(_digital_state)):
        value = _digital_state[len(_digital_state) - i - 1]
        data_pin.value(value)
        shift_pin.on()
        shift_pin.off()

    clock_pin.on()
    clock_pin.off()

def fast_shift_registers(bytes_data, count):
    if _data_pin is None or _latch_pin is None or _clock_pin is None or _clear_pin is None: 
        return

    data_pin = Pin(_data_pin, Pin.OUT)
    clock_pin = Pin(_latch_pin, Pin.OUT)
    shift_pin = Pin(_clock_pin, Pin.OUT)
    clear_pin = Pin(_clear_pin, Pin.OUT)

    clear_pin.on()
    value_bits = int.from_bytes(bytes_data, 'little')

    for i in range(count):
        data_pin.value(value_bits & 1)
        shift_pin.on()
        shift_pin.off()
        value_bits >>= 1

    clock_pin.on()
    clock_pin.off()

