def csv_to_bin(filename):
    DIGITAL_TYPE = 1
    PWM_TYPE = 2

    if not filename.endswith('.csv'):
        return

    try:
        with open(filename, 'r') as f:
            header = f.readline()
            titles = header.split(',')
            ports = [None]
            port_types = [None]

            for i in range(1, len(titles)):
                ports.append(None)
                port_types.append(None)
                indicator = titles[i][0]
                ports[i] = int(titles[i][1:])

                if indicator == 'D':
                    port_types[i] = DIGITAL_TYPE
                elif indicator == 'S':
                    port_types[i] = PWM_TYPE

            output_name = filename[:-4] + '.bin'
            with open(output_name, 'wb') as of:
                pwm_length = len(pwm_port_table) if pwm_port_table else 0
                pwm_values = bytearray(4 * (pwm_length + 1))

                bit_length = len(digital_port_table) if digital_port_table else 0
                byte_length = (bit_length + 7) >> 3

                for line in f:
                    values = line.strip().split(',')

                    line_bytes = bytearray(struct.pack('<L', int(values[0])))
                    dig_int = 0

                    for idx in range(1, len(values)):
                        if port_types[idx] == PWM_TYPE and ports[idx] < pwm_length:
                            on_val = 0
                            off_val = int(values[idx]) >> pwm_port_table[ports[idx]].get('shift', 4)
                            pos = ports[idx] * 4
                            pwm_values[pos:pos+4] = struct.pack('<HH', on_val, off_val)

                        elif port_types[idx] == DIGITAL_TYPE:
                            if int(values[idx]) != 0 and ports[idx] < bit_length:
                                mask = 1 << ports[idx]
                                dig_int |= mask

                    line_bytes.extend(dig_int.to_bytes(byte_length, 'little'))
                    line_bytes.extend(pwm_values)
                    of.write(line_bytes)

            return output_name

    except Exception as e:
        if verbose_mode:
            print('Error in CSV conversion:', str(e))
        pass

    gc.collect()
    return None

