    sys.stderr.write("This tool runs various checks on the configuration tables.\n")
    sys.stderr.write("-/-h/-help        :show this information\n")
    sys.stderr.write("-v/-verbose       :run more verbosely\n")
    sys.stderr.write("-r/-regular       :run regularity check\n")
    sys.stderr.write("-i/-infilename inf:name of csv file to convert to binary\n")
    sys.stderr.write("\nRegularity is loosely defined as contiguous port numbering,\norder matching between ports and indices, etc.\n\n")

def validate_configuration():
    global verbose_mode
    regular_check = False
    input_filename = None
    i = 1

    while i < len(sys.argv):
        arg = sys.argv[i]
        if arg in ['-', '-h', '-help']:
            print_usage(sys.argv[0])
            sys.exit(0)
        elif arg in ['-v', '-verbose']:
            verbose_mode = True
        elif arg in ['-r', '-regular']:
            regular_check = True
        elif arg in ['-i', '-infilename']:
            i += 1
            if i < len(sys.argv):
                input_filename = sys.argv[i]
        else:
            sys.stderr.write("\nError - Unrecognized argument: %s\n" % arg)
            print_usage(sys.argv[0])
            sys.exit(10)
        i += 1

    validation_passed = False

    # Validate digital port table
    last_port = None
    dg_ports = 0
    d5_ports = 0
    dm_ports = 0

    if regular_check and digital_port_table and min(digital_port_table) != 0:
        print('Alert >>> Digital port table does not start at port 0')
        validation_passed = True

    for port in sorted(digital_port_table):
        if 'handler' not in digital_port_table[port]:
            print(f'Error - Digital port {port} is not configured correctly')
            validation_passed = True
        elif digital_port_table[port]['handler'] == maestro_digital_handler:
            dm_ports += 1
            if verbose_mode:
                print(f'Digital Port {port} via Maestro board {digital_port_table[port]["board"]} channel {digital_port_table[port]["output"]}')

            if regular_check and last_port is not None and port != last_port+1:
                print(f'Alert >>> Noncontiguous digital ports {last_port} and {port}')
                validation_passed = True

        elif digital_port_table[port]['handler'] == shift_register_handler:
            d5_ports += 1
            if verbose_mode:
                print(f'Digital Port {port} via shift register index {digital_port_table[port]["index"]}')

            if regular_check and last_port is not None and port != last_port+1:
                print(f'Alert >>> Noncontiguous digital ports {last_port} and {port}')
                validation_passed = True

        elif digital_port_table[port]['handler'] == gpio_digital_handler:
            dg_ports += 1
            if verbose_mode:
                print(f'Digital Port {port} via GPIO pin {digital_port_table[port]["pin"]}')

            if regular_check and last_port is not None and port != last_port+1:
                print(f'Alert >>> Noncontiguous digital ports {last_port} and {port}')
                validation_passed = True

        last_port = port

    print(f'\nConfiguration has {d5_ports} shift register ports, {dm_ports} Maestro ports, and {dg_ports} GPIO ports configured for digital signals\n')

    # Validate PWM port table
    last_port = None
    dg_ports = 0
    d5_ports = 0
    dm_ports = 0

    if regular_check and pwm_port_table and min(pwm_port_table) != 0:
        print('Alert >>> PWM port table does not start at port 0')
        validation_passed = True

    for port in sorted(pwm_port_table):
        if 'handler' not in pwm_port_table[port]:
            print(f'Error - PWM port {port} is not configured correctly')
            validation_passed = True
        elif pwm_port_table[port]['handler'] == pca9685_pwm_handler:
            d5_ports += 1
            if verbose_mode:
                print(f'PWM Port {port} via PCA9685 board {pwm_port_table[port]["board"]} output {pwm_port_table[port]["output"]}')

            if regular_check and last_port is not None and port != last_port+1:
                print(f'Alert >>> Noncontiguous PWM ports {last_port} and {port}')
                validation_passed = True

        elif pwm_port_table[port]['handler'] == gpio_pwm_handler:
            dg_ports += 1
            if verbose_mode:
                print(f'PWM Port {port} via GPIO pin {pwm_port_table[port]["pin"]}')

            if regular_check and last_port is not None and port != last_port+1:
                print(f'Alert >>> Noncontiguous PWM ports {last_port} and {port}')
                validation_passed = True

        elif pwm_port_table[port]['handler'] == maestro_pwm_handler:
            dm_ports += 1
            if verbose_mode:
                print(f'PWM Port {port} via Maestro board {pwm_port_table[port]["board"]} channel {pwm_port_table[port]["output"]}')

            if regular_check and last_port is not None and port != last_port+1:
                print(f'Alert >>> Noncontiguous PWM ports {last_port} and {port}')
                validation_passed = True

        last_port = port

    print(f'\nConfiguration has {d5_ports} PCA9685 ports, {dm_ports} Maestro ports, and {dg_ports} GPIO ports configured for PWM signals\n')

    # Validate input specifications
    num_ports = len(input_port_table)
    if run_input_port is not None: num_ports += 1
    if trigger_input_port is not None: num_ports += 1
    if opto_input_port is not None: num_ports += 1

    if expected_input_ports != num_ports:
        print(f'Warning - Number of digital input ports requested ({expected_input_ports}) does not match number configured ({num_ports})!')

    # Validate expected counts
    if expected_pwm_ports != len(pwm_port_table):
        print(f'Warning - Length of PWM port table ({len(pwm_port_table)}) differs from expected ({expected_pwm_ports})')
        validation_passed = True

    if expected_digital_ports != len(digital_port_table):
        print(f'Warning - Length of digital port table ({len(digital_port_table)}) differs from expected ({expected_digital_ports})')
        validation_passed = True

    # Validate pin assignments
    valid_pins = [6,7,8,12,13,14,15,20,21,22]
    status = False

    for port in digital_port_table:
        if 'pin' in digital_port_table[port] and digital_port_table[port]['pin'] not in valid_pins:
            print(f'Warning - Found invalid digital pin specification: {digital_port_table[port]["pin"]} for port {port}')
            status = True

    for port in pwm_port_table:
        if 'pin' in pwm_port_table[port] and pwm_port_table[port]['pin'] not in valid_pins:
            print(f'Warning - Found invalid PWM pin specification: {pwm_port_table[port]["pin"]} for port {port}')
            status = True

    if status:
        print(f'Valid GPIO pins are: {valid_pins}')

    if input_filename is not None:
        csv_to_bin(input_filename)

    return status or validation_passed

if __name__ == "__main__":
    if not parse_status:
        result = validate_configuration()
        sys.exit(0 if not result else 1)
    sys.exit(1)

