        annotation_lines = _capture_annotations(findings_data)
        assert len(annotation_lines) == 1
        expected_annotation = "::error file=app.py,line=10,title=Skylos SKY-D211::SQL injection detected"
        assert annotation_lines[0] == expected_annotation

    def test_severity_mapping(self):
