import torch
from vllm.distributed import get_pcp_group
from vllm_ascend.platform import ModelConfig
from vllm_ascend.utils import singleton

def _create_causal_mask(max_len: int, data_type: torch.dtype) -> torch.Tensor:
    # Build lower triangular mask (true for valid positions)
    valid_positions = torch.ones((max_len, max_len), dtype=torch.bool, device="cpu").tril_()
    # Invert to get mask for invalid positions (upper triangle including diagonal)
    invalid_positions = ~valid_positions

    # Set appropriate mask values based on data type
    if data_type == torch.float16:
        fill_value = float("-inf")
    else:
        fill_value = 0.0

    # Create full mask tensor with proper values
    mask_tensor = torch.zeros((max_len, max_len), dtype=data_type, device="cpu")
    mask_tensor.masked_fill_(invalid_positions, fill_value)
    return mask_tensor

@singleton
class CausalAttentionMaskFactory:
    def __init__(self, target_device: torch.device):
        self._cached_mask = None
        self._max_cached_length = 0
        self.device = target_device
        # Initialize various specialized masks as None
        self.mla_prefill_mask = None
        self.split_fuse_mask = None
        self.pcp_mla_pattern = None
        self.swa_pattern = None

    def obtain_causal_mask(self, required_length: int, target_dtype: torch.dtype) -> torch.Tensor:
        # Re-generate if cache is missing or insufficient length
        if self._cached_mask is None or required_length > self._max_cached_length:
            self._cached_mask = _create_causal_mask(required_length, target_dtype)
            self._max_cached_length = required_length

        assert self._cached_mask is not None, "Causal mask generation failed"

        # Ensure correct data type
        if self._cached_mask.dtype != target_dtype:
            self._cached_mask = self._cached_mask.to(target_dtype)

        # Extract slice and move to target device
        return self._cached_mask[:required_length, :required_length].contiguous().to(
            self.device, non_blocking=True
        )

    def get_split_fuse_pattern(self) -> torch.Tensor:
        if self.split_fuse_mask is None:
            # Create upper triangular pattern (excluding diagonal) in int8 format
            self.split_fuse_mask = (
                torch.triu(torch.ones(2048, 2048, dtype=torch.int8), diagonal=1)
                .to(self.device)
            )
        return self.split_fuse_mask

    def get_mla_prefill_pattern(self, dtype: torch.dtype) -> torch.Tensor:
        if self.mla_prefill_mask is None or self.mla_prefill_mask.dtype != dtype:
            # Determine mask value based on precision
            if dtype == torch.float16:
                mask_val = torch.finfo(torch.float32).min
            else:
                mask_val = 0.0

            # Create upper triangular pattern (excluding diagonal)
            base_pattern = torch.triu(torch.ones(512, 512, device=self.device, dtype=dtype), diagonal=1)
            self.mla_prefill_mask = torch.where(base_pattern == 1, mask_val, 0).to(dtype)
        return self.mla_prefill_mask

    def get_pcp_mla_pattern(self, dtype: torch.dtype) -> torch.Tensor:
        if self.pcp_mla_pattern is None or self.pcp_mla_pattern.dtype != dtype:
            # Create upper triangular pattern (excluding diagonal) directly on device
            self.pcp_mla_pattern = torch.triu(
                torch.ones(512, 512, device=self.device, dtype=dtype), diagonal=1
            )
        return self.pcp_mla_pattern

    def get_sliding_window_pattern(self, dtype: torch.dtype, window_size: int) -> torch.Tensor:
        if self.swa_pattern is None or self.swa_pattern.dtype != dtype:
            if window_size is not None:
                # Combine upper triangle and lower triangle beyond window
                full_mask = torch.ones(2048, 2048, dtype=torch.bool, device=self.device)
                upper_part = torch.triu(full_mask, diagonal=1)
                lower_part = torch.tril(full_mask, -window_size)
                self.swa_pattern = (upper_part | lower_part).to(dtype)
        return self.swa_pattern

    def get_runner_mask(self, config: ModelConfig) -> torch.Tensor:
        if config.runner_type == "pooling":
            return self.obtain_causal_mask(2048, torch.bool)
        return self.get_split_fuse_pattern()

    def get_optimized_mla_mask(self, config: ModelConfig) -> torch.Tensor:
        # Use PCP-specific mask when distributed setup detected
        if get_pcp_group().world_size > 1:
            return self.get_pcp_mla_pattern(config.dtype)
        # Otherwise use standard MLA prefill mask
        return self.get_mla_prefill_pattern(config.dtype)

