# Global flag for tracking user interrupt requests across tools
# The agent's interrupt() method updates this flag, and long-running
# operations periodically check it to decide whether to terminate early.
# Example usage in a tool:
#     from tools.interrupt import check_interrupt
#     if check_interrupt():
#         return {"output": "[interrupted]", "returncode": 130}

import threading

# Thread-safe event object to signal interruption state
_interrupt_flag = threading.Event()

def trigger_interrupt(state: bool) -> None:
    """Called by the agent to activate or deactivate the interrupt state."""
    if state:
        _interrupt_flag.set()
    else:
        _interrupt_flag.clear()

def check_interrupt() -> bool:
    """Query whether an interrupt has been requested. Safe for concurrent access."""
    return _interrupt_flag.is_set()

# IDNA (Internationalizing Domain Names in Applications) implementation
# This module provides functions for encoding and decoding internationalized domain names

import bisect
import unicodedata
import re
from typing import Union, Optional
from .intranges import intranges_contain

# Constants
_VIRAMA_COMBINING_CLASS = 9
_A_LABEL_PREFIX = b'xn--'
_UNICODE_DOTS_REGEX = re.compile('[\u002e\u3002\uff0e\uff61]')

class IDNAError(UnicodeError):
    """Base exception for all IDNA-related issues"""
    pass

class IDNABidiError(IDNAError):
    """Raised when bidirectional requirements are not satisfied"""
    pass

class InvalidCodepoint(IDNAError):
    """Raised when a disallowed or unallocated codepoint is used"""
    pass

class InvalidCodepointContext(IDNAError):
    """Raised when the codepoint is not valid in its context"""
    pass

def _get_combining_class(code_point: int) -> int:
    """Get the combining class of a Unicode character"""
    value = unicodedata.combining(chr(code_point))
    if value == 0 and not unicodedata.name(chr(code_point)):
        raise ValueError('Unknown character in unicodedata')
    return value

def _check_script(character: str, script_name: str) -> bool:
    """Check if a character belongs to a specific script"""
    return intranges_contain(ord(character), idnadata.scripts[script_name])

def _to_punycode(text: str) -> bytes:
    """Convert string to punycode representation"""
    return text.encode('punycode')

def _format_codepoint(code_point: int) -> str:
    """Format a code point as U+XXXX string"""
    return 'U+{:04X}'.format(code_point)

def is_valid_label_length(label: Union[bytes, str]) -> bool:
    """Check if label length is within allowed limits (max 63 characters)"""
    return len(label) <= 63

def is_valid_string_length(label: Union[bytes, str], has_trailing_dot: bool) -> bool:
    """Check if domain string length is within allowed limits"""
    max_length = 254 if has_trailing_dot else 253
    return len(label) <= max_length

def validate_bidirectional(label: str, enforce_ltr: bool = False) -> bool:
    """Validate bidirectional rules for domain labels"""
    # Determine if label contains RTL characters
    has_rtl = False
    for index, char in enumerate(label, start=1):
        direction = unicodedata.bidirectional(char)
        if direction == '':
            raise IDNABidiError(f'Unknown directionality in label {repr(label)} at position {index}')
        if direction in ['R', 'AL', 'AN']:
            has_rtl = True

    # Skip bidi validation if no RTL characters and not enforcing LTR
    if not has_rtl and not enforce_ltr:
        return True

    # Check first character directionality
    first_char_dir = unicodedata.bidirectional(label[0])
    if first_char_dir in ['R', 'AL']:
        is_rtl = True
    elif first_char_dir == 'L':
        is_rtl = False
    else:
        raise IDNABidiError(f'First codepoint in label {repr(label)} must be L, R or AL')

    # Validate remaining characters according to bidi rules
    valid_ending = False
    numeral_type = None

    for index, char in enumerate(label, start=1):
        direction = unicodedata.bidirectional(char)

        if is_rtl:
            # Bidi rule 2: check allowed directions for RTL labels
            if direction not in ['R', 'AL', 'AN', 'EN', 'ES', 'CS', 'ET', 'ON', 'BN', 'NSM']:
                raise IDNABidiError(f'Invalid direction for codepoint at position {index} in RTL label')

            # Bidi rules 3 & 4: track valid endings and numeral consistency
            if direction in ['R', 'AL', 'EN', 'AN']:
                valid_ending = True
            elif direction != 'NSM':
                valid_ending = False

            if direction in ['AN', 'EN']:
                if numeral_type is None:
                    numeral_type = direction
                elif numeral_type != direction:
                    raise IDNABidiError('Cannot mix different numeral types in RTL label')
        else:
            # Bidi rule 5: check allowed directions for LTR labels
            if direction not in ['L', 'EN', 'ES', 'CS', 'ET', 'ON', 'BN', 'NSM']:
                raise IDNABidiError(f'Invalid direction for codepoint at position {index} in LTR label')

            # Bidi rule 6: track valid endings
            if direction in ['L', 'EN']:
                valid_ending = True
            elif direction != 'NSM':
                valid_ending = False

    # Ensure label ends with valid directionality
    if not valid_ending:
        raise IDNABidiError('Label ends with illegal codepoint directionality')

    return True

def validate_initial_combiner(label: str) -> bool:
    """Ensure label doesn't begin with a combining mark"""
    if unicodedata.category(label[0])[0] == 'M':
        raise IDNAError('Label begins with an illegal combining character')
    return True

def validate_hyphen_usage(label: str) -> bool:
    """Validate hyphen usage in label"""
    if len(label) >= 4 and label[2:4] == '--':
        raise IDNAError('Label has disallowed hyphens in 3rd and 4th position')
    if label.startswith('-') or label.endswith('-'):
        raise IDNAError('Label must not start or end with a hyphen')
    return True

def ensure_nfc_normalization(label: str) -> None:
    """Ensure label is in Unicode Normalization Form C"""
    normalized = unicodedata.normalize('NFC', label)
    if normalized != label:
        raise IDNAError('Label must be in Normalization Form C')

def is_valid_context_j(label: str, position: int) -> bool:
    """Validate contextJ characters (joiners) at given position"""
    code_point = ord(label[position])

    if code_point == 0x200C:  # Zero Width Non-Joiner
        # Check if preceded by virama
        if position > 0 and _get_combining_class(ord(label[position - 1])) == _VIRAMA_COMBINING_CLASS:
            return True

        # Check joining type before
        ok_before = False
        for i in range(position-1, -1, -1):
            joining_type = idnadata.joining_types.get(ord(label[i]))
            if joining_type == ord('T'):
                continue
            if joining_type in [ord('L'), ord('D')]:
                ok_before = True
                break

        if not ok_before:
            return False

        # Check joining type after
        ok_after = False
        for i in range(position+1, len(label)):
            joining_type = idnadata.joining_types.get(ord(label[i]))
            if joining_type == ord('T'):
                continue
            if joining_type in [ord('R'), ord('D')]:
                ok_after = True
                break

        return ok_after

    elif code_point == 0x200D:  # Zero Width Joiner
        if position > 0 and _get_combining_class(ord(label[position - 1])) == _VIRAMA_COMBINING_CLASS:
            return True
        return False

    return False

def is_valid_context_o(label: str, position: int, is_exception: bool = False) -> bool:
    """Validate contextO characters at given position"""
    code_point = ord(label[position])

    if code_point == 0x00B7:  # Middle Dot
        if 0 < position < len(label)-1:
            return (ord(label[position - 1]) == 0x006C and 
                   ord(label[position + 1]) == 0x006C)
        return False

    elif code_point == 0x0375:  # Greek Lower Numeral Sign
        if position < len(label)-1 and len(label) > 1:
            return _check_script(label[position + 1], 'Greek')
        return False

    elif code_point in [0x05F3, 0x05F4]:  # Hebrew Punctuation
        if position > 0:
            return _check_script(label[position - 1], 'Hebrew')
        return False

    elif code_point == 0x30FB:  # Katakana Middle Dot
        for char in label:
            if char == '\u30FB':
                continue
            if (_check_script(char, 'Hiragana') or 
                _check_script(char, 'Katakana') or 
                _check_script(char, 'Han')):
                return True
        return False

    elif 0x660 <= code_point <= 0x669:  # Arabic-Indic Digits
        for char in label:
            if 0x6F0 <= ord(char) <= 0x06F9:
                return False
        return True

    elif 0x6F0 <= code_point <= 0x6F9:  # Eastern Arabic-Indic Digits
        for char in label:
            if 0x660 <= ord(char) <= 0x0669:
                return False
        return True

    return False

def validate_label(label: Union[str, bytes, bytearray]) -> None:
    """Validate a single domain label"""
    if isinstance(label, (bytes, bytearray)):
        label = label.decode('utf-8')

    if not label:
        raise IDNAError('Empty Label')

    ensure_nfc_normalization(label)
    validate_hyphen_usage(label)
    validate_initial_combiner(label)

    for pos, char in enumerate(label):
        code_point = ord(char)

        if intranges_contain(code_point, idnadata.codepoint_classes['PVALID']):
            continue
        elif intranges_contain(code_point, idnadata.codepoint_classes['CONTEXTJ']):
            try:
                if not is_valid_context_j(label, pos):
                    raise InvalidCodepointContext(
                        f'Joiner {_format_codepoint(code_point)} not allowed at position {pos+1} in {repr(label)}')
            except ValueError:
                raise IDNAError(
                    f'Unknown codepoint adjacent to joiner {_format_codepoint(code_point)} at position {pos+1} in {repr(label)}')
        elif intranges_contain(code_point, idnadata.codepoint_classes['CONTEXTO']):
            if not is_valid_context_o(label, pos):
                raise InvalidCodepointContext(
                    f'Codepoint {_format_codepoint(code_point)} not allowed at position {pos+1} in {repr(label)}')
        else:
            raise InvalidCodepoint(
                f'Codepoint {_format_codepoint(code_point)} at position {pos+1} of {repr(label)} not allowed')

    validate_bidirectional(label)

def encode_label(label: str) -> bytes:
    """Encode a domain label to ASCII-compatible format"""
    try:
        ascii_bytes = label.encode('ascii')
        decode_label(ascii_bytes)
        if not is_valid_label_length(ascii_bytes):
            raise IDNAError('Label too long')
        return ascii_bytes
    except UnicodeEncodeError:
        pass

    if not label:
        raise IDNAError('No Input')

    label = str(label)
    validate_label(label)
    encoded_bytes = _to_punycode(label)
    result = _A_LABEL_PREFIX + encoded_bytes

    if not is_valid_label_length(result):
        raise IDNAError('Label too long')

    return result

def decode_label(label: Union[str, bytes, bytearray]) -> str:
    """Decode an ASCII label to Unicode format"""
    if not isinstance(label, (bytes, bytearray)):
        try:
            ascii_bytes = label.encode('ascii')
        except UnicodeEncodeError:
            validate_label(label)
            return label
    else:
        ascii_bytes = label

    ascii_bytes = ascii_bytes.lower()

    if ascii_bytes.startswith(_A_LABEL_PREFIX):
        ascii_bytes = ascii_bytes[len(_A_LABEL_PREFIX):]
        if not ascii_bytes:
            raise IDNAError('Malformed A-label, no Punycode content found')
        if ascii_bytes.decode('ascii').endswith('-'):
            raise IDNAError('A-label must not end with a hyphen')
    else:
        validate_label(ascii_bytes)
        return ascii_bytes.decode('ascii')

    try:
        decoded = ascii_bytes.decode('punycode')
    except UnicodeError:
        raise IDNAError('Invalid A-label')

    validate_label(decoded)
    return decoded

def normalize_domain(domain: str, use_std3_rules: bool = True, use_transitional: bool = False) -> str:
    """Normalize domain according to UTS46 processing"""
    from .uts46data import uts46data

    output = ''
    for pos, char in enumerate(domain):
        code_point = ord(char)
        try:
            # Find appropriate row in UTS46 data
            if code_point < 256:
                uts46_row = uts46data[code_point]
            else:
                idx = bisect.bisect_left(uts46data, (code_point, 'Z')) - 1
                uts46_row = uts46data[idx]

            status = uts46_row[1]
            replacement = None

            if len(uts46_row) == 3:
                replacement = uts46_row[2]

            # Process according to status
            if (status == 'V' or
                (status == 'D' and not use_transitional) or
                (status == '3' and not use_std3_rules and replacement is None)):
                output += char
            elif replacement is not None and (status == 'M' or
                (status == '3' and not use_std3_rules) or
                (status == 'D' and use_transitional)):
                output += replacement
            elif status != 'I':
                raise IndexError()
        except IndexError:
            raise InvalidCodepoint(
                f'Codepoint {_format_codepoint(code_point)} not allowed at position {pos + 1} in {repr(domain)}')

    return unicodedata.normalize('NFC', output)

def encode_domain(domain: Union[str, bytes, bytearray], strict_mode: bool = False, 
                 use_uts46: bool = False, std3_rules: bool = False, 
                 transitional: bool = False) -> bytes:
    """Encode a full domain name to ASCII format"""
    if isinstance(domain, (bytes, bytearray)):
        try:
            domain = domain.decode('ascii')
        except UnicodeDecodeError:
            raise IDNAError('Input should be a unicode string, not byte string.')

    if use_uts46:
        domain = normalize_domain(domain, std3_rules, transitional)

    trailing_dot = False
    parts = []

    if strict_mode:
        parts = domain.split('.')
    else:
        parts = _UNICODE_DOTS_REGEX.split(domain)

    if not parts or parts == ['']:
        raise IDNAError('Empty domain')

    if parts[-1] == '':
        parts.pop()
        trailing_dot = True

    result = []
    for part in parts:
        encoded = encode_label(part)
        if encoded:
            result.append(encoded)
        else:
            raise IDNAError('Empty label')

    if trailing_dot:
        result.append(b'')

    final = b'.'.join(result)

    if not is_valid_string_length(final, trailing_dot):
        raise IDNAError('Domain too long')

    return final

def decode_domain(domain: Union[str, bytes, bytearray], strict_mode: bool = False,
                 use_uts46: bool = False, std3_rules: bool = False) -> str:
    """Decode an ASCII domain name to Unicode format"""
    try:
        if isinstance(domain, (bytes, bytearray)):
            domain = domain.decode('ascii')
    except UnicodeDecodeError:
        raise IDNAError('Invalid ASCII in A-label')

    if use_uts46:
        domain = normalize_domain(domain, std3_rules, False)

    trailing_dot = False
    parts = []

    if not strict_mode:
        parts = _UNICODE_DOTS_REGEX.split(domain)
    else:
        parts = domain.split('.')

    if not parts or parts == ['']:
        raise IDNAError('Empty domain')

    if not parts[-1]:
        parts.pop()
        trailing_dot = True

    result = []
    for part in parts:
        decoded = decode_label(part)
        if decoded:
            result.append(decoded)
        else:
            raise IDNAError('Empty label')

    if trailing_dot:
        result.append('')

    return '.'.join(result)

# Type III Clone: TokenUsageCostCalculator and TokenUsageDisplayer refactored with equivalent logic, different structure

from typing import Optional
import pandas as pd

# Assuming the same schema definitions exist elsewhere
# from statgpt.common.schemas.token_usage import TokenUsageItem, TokenUsagePricedItem


class PricingHandler:
    def __init__(self, pricing_map: dict) -> None:
        self._pricing_map = pricing_map

    def compute_expense(self, usage_item) -> Optional[float]:
        """Compute cost based on token counts and model-specific pricing."""
        if pricing_info := self._pricing_map.get(usage_item.model):
            input_cost = usage_item.prompt_tokens * pricing_info.prompt
            output_cost = usage_item.completion_tokens * pricing_info.completion
            return input_cost + output_cost
        return None


class UsageProcessor:
    def __init__(self, model_pricing: dict) -> None:
        self._handler = PricingHandler(model_pricing)

    def enrich_usage_records(self, records: list) -> list:
        """Augment each usage record with computed cost."""
        return [
            TokenUsagePricedItem(
                deployment=record.deployment,
                model=record.model,
                prompt_tokens=record.prompt_tokens,
                completion_tokens=record.completion_tokens,
                costs=self._handler.compute_expense(record),
            )
            for record in records
        ]


class ReportFormatter:
    COLUMN_LABELS = {
        "deployment": "Deployment",
        "model": "Model",
        "prompt_tokens": "Prompt Tokens",
        "completion_tokens": "Completion Tokens",
        "total_tokens": "Total Tokens",
        "costs": "Total Price, $",
    }
    MISSING_VALUE = "-"

    @classmethod
    def to_markdown(cls, priced_items: list) -> str:
        """Generate a Markdown table string from priced token usage data."""
        # Extract data using alias-based serialization
        data_rows = [item.model_dump(by_alias=True) for item in priced_items]
        df = pd.DataFrame(data_rows, columns=list(cls.COLUMN_LABELS.keys()))

        # Append summary row
        summary_row = cls._aggregate_summary(df)
        df = pd.concat([df, summary_row], ignore_index=True)

        # Apply column renaming and missing value handling
        df.rename(columns=cls.COLUMN_LABELS, inplace=True)
        df.fillna(cls.MISSING_VALUE, inplace=True)

        return df.to_markdown(index=False)

    @staticmethod
    def _aggregate_summary(table: pd.DataFrame) -> pd.DataFrame:
        numeric_sums = table.sum(numeric_only=True)
        return pd.DataFrame({
            "deployment": [""],
            "model": ["TOTAL:"],
            "prompt_tokens": [numeric_sums.get("prompt_tokens")],
            "completion_tokens": [numeric_sums.get("completion_tokens")],
            "total_tokens": [numeric_sums.get("total_tokens")],
            "costs": [numeric_sums.get("costs")],
        })

    @staticmethod
    def sum_costs(priced_items: list) -> float:
        """Sum up all non-null costs."""
        if not priced_items:
            return 0.0
        return sum(item.costs or 0.0 for item in priced_items)

    @staticmethod
    def format_total(priced_items: list) -> str:
        """Format total cost as a fixed-precision string."""
        return f"{ReportFormatter.sum_costs(priced_items):.3f}"

    @classmethod
    def to_list_format(cls, priced_items: list) -> str:
        """Render token usage as a formatted list with totals."""
        output_lines = []

        for item in priced_items:
            output_lines.append(f"### {item.model}")
            output_lines.append(f"* Prompt Tokens: {item.prompt_tokens}")
            output_lines.append(f"* Completion Tokens: {item.completion_tokens}")
            output_lines.append(f"* Total Tokens: {item.total_tokens}")
            if item.costs is None:
                output_lines.append("* Total Price: <NO DATA>")
            else:
                output_lines.append(f"* Total Price, $: {item.costs:.3f}")
            output_lines.append("")  # blank line between entries

        # Compute aggregates
        total_prompts = sum(i.prompt_tokens or 0 for i in priced_items)
        total_completions = sum(i.completion_tokens or 0 for i in priced_items)
        total_all_tokens = sum(i.total_tokens or 0 for i in priced_items)
        grand_total = cls.format_total(priced_items)

        output_lines.append("-" * 15)
        output_lines.append("## TOTAL:")
        output_lines.append(f"* Prompt Tokens: {total_prompts}")
        output_lines.append(f"* Completion Tokens: {total_completions}")
        output_lines.append(f"* Total Tokens: {total_all_tokens}")
        output_lines.append(f"* Total Price, $: {grand_total}")

        return "\n".join(output_lines)

# Alternative implementation of Timestamp class with different logic flow

from __future__ import annotations
import json
import re
from datetime import datetime
from typing import Union, Dict, Any, Optional, Set, TYPE_CHECKING
from pydantic import BaseModel, ConfigDict, Field, field_validator, ValidationError, StrictStr
from typing_extensions import Self

if TYPE_CHECKING:
    from datetime import datetime as dt_type

class Timestamp(BaseModel):
    """
    When the content occurred. Accepts an ISO 8601 datetime string (e.g. '2024-01-15T10:30:00Z'), null/omitted (defaults to now), 
    or the special string 'unset' to explicitly store without any timestamp (use this for timeless content such as fictional documents or static reference material).
    """
    # Internal storage for parsed values
    _parsed_value: Optional[Union[datetime, str]] = None

    # Schema validation fields
    datetime_value: Optional[datetime] = Field(default=None, alias="anyof_schema_1_validator")
    string_value: Optional[StrictStr] = Field(default=None, alias="anyof_schema_2_validator")

    # Available schemas
    any_of_schemas: Set[str] = {"datetime", "str"}

    model_config = ConfigDict(
        validate_assignment=True,
        protected_namespaces=(),
        populate_by_name=True
    )

    def __init__(self, *args, **kwargs) -> None:
        if args:
            if len(args) > 1:
                raise ValueError("If a position argument is used, only 1 is allowed to set `actual_instance`")
            if kwargs:
                raise ValueError("If a position argument is used, keyword arguments cannot be used.")
            super().__init__(actual_instance=args[0])
        else:
            super().__init__(**kwargs)

    @field_validator('actual_instance', mode='before')
    @classmethod
    def validate_actual_instance(cls, v):
        if v is None:
            return v

        instance = cls.model_construct()
        validation_errors = []

        # Try parsing as datetime first
        try:
            if isinstance(v, str):
                # Handle special 'unset' value
                if v.lower() == 'unset':
                    return v

                # Try parsing ISO format datetime string
                parsed_dt = datetime.fromisoformat(v.replace('Z', '+00:00'))
                instance.datetime_value = parsed_dt
                return parsed_dt
            elif isinstance(v, datetime):
                instance.datetime_value = v
                return v
        except Exception as e:
            validation_errors.append(f"datetime validation failed: {str(e)}")

        # Try parsing as string
        try:
            if isinstance(v, str):
                instance.string_value = v
                return v
        except Exception as e:
            validation_errors.append(f"string validation failed: {str(e)}")

        # If all validations fail
        if validation_errors:
            raise ValueError(
                f"No match found when setting the actual_instance in Timestamp with anyOf schemas: datetime, str. "
                f"Details: {'; '.join(validation_errors)}"
            )
        return v

    @classmethod
    def from_dict(cls, obj: Dict[str, Any]) -> Self:
        """Create instance from dictionary"""
        return cls.from_json(json.dumps(obj))

    @classmethod
    def from_json(cls, json_str: str) -> Self:
        """Returns the object represented by the JSON string"""
        instance = cls.model_construct()

        if not json_str or json_str.strip() == "":
            return instance

        validation_failures = []

        # Attempt to parse as datetime
        try:
            parsed_data = json.loads(json_str)
            if isinstance(parsed_data, str):
                # Check for special 'unset' value
                if parsed_data.lower() == 'unset':
                    instance.string_value = parsed_data
                    instance._parsed_value = parsed_data
                    return instance

                # Try parsing as datetime
                parsed_dt = datetime.fromisoformat(parsed_data.replace('Z', '+00:00'))
                instance.datetime_value = parsed_dt
                instance._parsed_value = parsed_dt
                return instance
        except Exception as e:
            validation_failures.append(f"datetime parsing error: {str(e)}")

        # Attempt to parse as string
        try:
            parsed_string = json.loads(json_str)
            if isinstance(parsed_string, str):
                instance.string_value = parsed_string
                instance._parsed_value = parsed_string
                return instance
        except Exception as e:
            validation_failures.append(f"string parsing error: {str(e)}")

        # If both attempts fail
        if validation_failures:
            raise ValueError(
                f"No match found when deserializing the JSON string into Timestamp with anyOf schemas: datetime, str. "
                f"Details: {'; '.join(validation_failures)}"
            )
        return instance

    def to_json(self) -> str:
        """Returns the JSON representation of the actual instance"""
        if self.actual_instance is None:
            return "null"

        # Use custom serialization if available
        if hasattr(self.actual_instance, "to_json") and callable(getattr(self.actual_instance, "to_json")):
            return self.actual_instance.to_json()

        # Default serialization
        if isinstance(self.actual_instance, datetime):
            return json.dumps(self.actual_instance.isoformat())
        return json.dumps(self.actual_instance)

    def to_dict(self) -> Optional[Union[Dict[str, Any], datetime, str]]:
        """Returns the dict representation of the actual instance"""
        if self.actual_instance is None:
            return None

        # Use custom serialization if available
        if hasattr(self.actual_instance, "to_dict") and callable(getattr(self.actual_instance, "to_dict")):
            return self.actual_instance.to_dict()

        return self.actual_instance

    def to_str(self) -> str:
        """Returns the string representation of the actual instance"""
        return str(self.model_dump())

# DistilBERT tokenizer implementation based on WordPiece algorithm

import collections
import os
import unicodedata
from typing import List, Optional, Tuple
from ...tokenization_utils import PreTrainedTokenizer, _is_control, _is_punctuation, _is_whitespace
from ...utils import logging

logger = logging.get_logger(__name__)

VOCAB_FILES_NAMES = {"vocab_file": "vocab.txt"}

def load_vocabulary(vocab_path):
    """Reads vocabulary file and returns ordered dictionary mapping tokens to indices."""
    vocab_dict = collections.OrderedDict()
    with open(vocab_path, "r", encoding="utf-8") as vocab_file:
        lines = vocab_file.readlines()
    for idx, token in enumerate(lines):
        clean_token = token.rstrip("\n")
        vocab_dict[clean_token] = idx
    return vocab_dict

def basic_split(text):
    """Performs simple whitespace-based tokenization."""
    text = text.strip()
    if not text:
        return []
    return text.split()

class DistilBertTokenizer(PreTrainedTokenizer):
    r"""
    Constructs a DistilBERT tokenizer. Based on WordPiece.
    This tokenizer inherits from [`PreTrainedTokenizer`] which contains most of the main methods. Users should refer to
    this superclass for more information regarding those methods.
    """
    vocab_files_names = VOCAB_FILES_NAMES
    model_input_names = ["input_ids", "attention_mask"]

    def __init__(
        self,
        vocab_file,
        do_lower_case=True,
        do_basic_tokenize=True,
        never_split=None,
        unk_token="[UNK]",
        sep_token="[SEP]",
        pad_token="[PAD]",
        cls_token="[CLS]",
        mask_token="[MASK]",
        tokenize_chinese_chars=True,
        strip_accents=None,
        **kwargs,
    ):
        # Validate vocabulary file existence
        if not os.path.isfile(vocab_file):
            raise ValueError(
                f"Can't find a vocabulary file at path '{vocab_file}'. To load the vocabulary from a Google pretrained"
                " model use `tokenizer = DistilBertTokenizer.from_pretrained(PRETRAINED_MODEL_NAME)`"
            )

        # Load vocabulary and create reverse mapping
        self.vocab = load_vocabulary(vocab_file)
        self.ids_to_tokens = collections.OrderedDict([(idx, tok) for tok, idx in self.vocab.items()])
        self.do_basic_tokenize = do_basic_tokenize

        # Initialize tokenizers
        if do_basic_tokenize:
            self.basic_tokenizer = BasicTokenizer(
                do_lower_case=do_lower_case,
                never_split=never_split,
                tokenize_chinese_chars=tokenize_chinese_chars,
                strip_accents=strip_accents,
            )
        self.wordpiece_tokenizer = WordpieceTokenizer(vocab=self.vocab, unk_token=str(unk_token))

        # Initialize parent class
        super().__init__(
            do_lower_case=do_lower_case,
            do_basic_tokenize=do_basic_tokenize,
            never_split=never_split,
            unk_token=unk_token,
            sep_token=sep_token,
            pad_token=pad_token,
            cls_token=cls_token,
            mask_token=mask_token,
            tokenize_chinese_chars=tokenize_chinese_chars,
            strip_accents=strip_accents,
            **kwargs,
        )

    @property
    def lowercase_enabled(self):
        """Returns whether lowercasing is enabled."""
        return self.basic_tokenizer.do_lower_case

    @property
    def vocabulary_count(self):
        """Returns size of vocabulary."""
        return len(self.vocab)

    def get_full_vocab(self):
        """Returns complete vocabulary including added tokens."""
        return dict(self.vocab, **self.added_tokens_encoder)

    def tokenize_text(self, text, split_special_tokens=False):
        """Tokenizes input text using basic and wordpiece tokenization."""
        result_tokens = []

        if self.do_basic_tokenize:
            for token in self.basic_tokenizer.tokenize(
                text, never_split=self.all_special_tokens if not split_special_tokens else None
            ):
                if token in self.basic_tokenizer.never_split:
                    result_tokens.append(token)
                else:
                    result_tokens += self.wordpiece_tokenizer.tokenize(token)
        else:
            result_tokens = self.wordpiece_tokenizer.tokenize(text)

        return result_tokens

    def token_to_identifier(self, token):
        """Converts token string to corresponding ID."""
        return self.vocab.get(token, self.vocab.get(self.unk_token))

    def identifier_to_token(self, index):
        """Converts ID to corresponding token string."""
        return self.ids_to_tokens.get(index, self.unk_token)

    def tokens_to_string(self, tokens):
        """Converts list of tokens back to string."""
        return " ".join(tokens).replace(" ##", "").strip()

    def prepare_sequence_input(self, token_ids_0: List[int], token_ids_1: Optional[List[int]] = None) -> List[int]:
        """
        Prepares sequence inputs by adding special tokens [CLS] and [SEP].
        Format: [CLS] X [SEP] or [CLS] A [SEP] B [SEP]
        """
        if token_ids_1 is None:
            return [self.cls_token_id] + token_ids_0 + [self.sep_token_id]

        return [self.cls_token_id] + token_ids_0 + [self.sep_token_id] + token_ids_1 + [self.sep_token_id]

    def identify_special_tokens(self, token_ids_0: List[int], token_ids_1: Optional[List[int]] = None, already_has_special_tokens: bool = False) -> List[int]:
        """
        Creates mask identifying special tokens in sequence.
        Returns 1 for special tokens, 0 for regular tokens.
        """
        if already_has_special_tokens:
            return super().identify_special_tokens(
                token_ids_0=token_ids_0, token_ids_1=token_ids_1, already_has_special_tokens=True
            )

        if token_ids_1 is not None:
            return [1] + ([0] * len(token_ids_0)) + [1] + ([0] * len(token_ids_1)) + [1]
        return [1] + ([0] * len(token_ids_0)) + [1]

    def generate_segment_ids(self, token_ids_0: List[int], token_ids_1: Optional[List[int]] = None) -> List[int]:
        """
        Generates token type IDs for sequence classification.
        Single sequence: all zeros
        Pair sequences: first part zeros, second part ones
        """
        if token_ids_1 is None:
            return [0] * (1 + len(token_ids_0) + 1)
        return [0] * (1 + len(token_ids_0) + 1) + [1] * (len(token_ids_1) + 1)

    def export_vocabulary(self, save_directory: str, filename_prefix: Optional[str] = None) -> Tuple[str]:
        """Saves vocabulary to specified directory or file path."""
        index = 0
        if os.path.isdir(save_directory):
            vocab_file = os.path.join(
                save_directory, (filename_prefix + "-" if filename_prefix else "") + VOCAB_FILES_NAMES["vocab_file"]
            )
        else:
            vocab_file = (filename_prefix + "-" if filename_prefix else "") + save_directory

        with open(vocab_file, "w", encoding="utf-8") as writer:
            for token, token_index in sorted(self.vocab.items(), key=lambda kv: kv[1]):
                if index != token_index:
                    logger.warning(
                        f"Saving vocabulary to {vocab_file}: vocabulary indices are not consecutive."
                        " Please check that the vocabulary is not corrupted!"
                    )
                    index = token_index
                writer.write(token + "\n")
                index += 1
        return (vocab_file,)

class BasicTokenizer:
    """
    Performs basic tokenization operations including punctuation splitting and case handling.
    """
    def __init__(
        self,
        do_lower_case=True,
        never_split=None,
        tokenize_chinese_chars=True,
        strip_accents=None,
        do_split_on_punc=True,
    ):
        self.never_split_set = set(never_split) if never_split else set()
        self.do_lower_case = do_lower_case
        self.tokenize_chinese_chars = tokenize_chinese_chars
        self.strip_accents = strip_accents
        self.do_split_on_punc = do_split_on_punc

    def tokenize(self, text, never_split=None):
        """Performs basic tokenization on input text."""
        combined_never_split = self.never_split_set.union(set(never_split)) if never_split else self.never_split_set

        cleaned_text = self._normalize_text(text)

        if self.tokenize_chinese_chars:
            cleaned_text = self._insert_spaces_for_cjk(cleaned_text)

        normalized_text = unicodedata.normalize("NFC", cleaned_text)
        base_tokens = basic_split(normalized_text)

        processed_tokens = []
        for token in base_tokens:
            if token not in combined_never_split:
                if self.do_lower_case:
                    token = token.lower()
                    if self.strip_accents is not False:
                        token = self._remove_accents(token)
                elif self.strip_accents:
                    token = self._remove_accents(token)
            processed_tokens.extend(self._split_on_punctuation(token, combined_never_split))

        return basic_split(" ".join(processed_tokens))

    def _remove_accents(self, text):
        """Removes diacritical marks from text."""
        text = unicodedata.normalize("NFD", text)
        return "".join(char for char in text if unicodedata.category(char) != "Mn")

    def _split_on_punctuation(self, text, never_split=None):
        """Splits text on punctuation marks unless excluded."""
        if not self.do_split_on_punc or (never_split is not None and text in never_split):
            return [text]

        result = []
        current_word = []

        for char in text:
            if _is_punctuation(char):
                if current_word:
                    result.append("".join(current_word))
                    current_word = []
                result.append(char)
            else:
                current_word.append(char)

        if current_word:
            result.append("".join(current_word))

        return result

    def _insert_spaces_for_cjk(self, text):
        """Inserts spaces around CJK characters."""
        result = []
        for char in text:
            code_point = ord(char)
            if (
                (code_point >= 0x4E00 and code_point <= 0x9FFF)
                or (code_point >= 0x3400 and code_point <= 0x4DBF)
                or (code_point >= 0x20000 and code_point <= 0x2A6DF)
                or (code_point >= 0x2A700 and code_point <= 0x2B73F)
                or (code_point >= 0x2B740 and code_point <= 0x2B81F)
                or (code_point >= 0x2B820 and code_point <= 0x2CEAF)
                or (code_point >= 0xF900 and code_point <= 0xFAFF)
                or (code_point >= 0x2F800 and code_point <= 0x2FA1F)
            ):
                result.extend([" ", char, " "])
            else:
                result.append(char)
        return "".join(result)

    def _normalize_text(self, text):
        """Cleans invalid characters and normalizes whitespace."""
        result = []
        for char in text:
            code_point = ord(char)
            if code_point == 0 or code_point == 0xFFFD or _is_control(char):
                continue
            if _is_whitespace(char):
                result.append(" ")
            else:
                result.append(char)
        return "".join(result)

class WordpieceTokenizer:
    """Implements WordPiece tokenization algorithm."""
    def __init__(self, vocab, unk_token, max_input_chars_per_word=100):
        self.vocab = vocab
        self.unk_token = unk_token
        self.max_word_length = max_input_chars_per_word

    def tokenize(self, text):
        """
        Tokenizes text into wordpieces using greedy longest-match-first algorithm.
        For example, 'unaffable' becomes ['un', '##aff', '##able'].
        """
        output_tokens = []

        for token in basic_split(text):
            chars = list(token)

            # Handle overly long words
            if len(chars) > self.max_word_length:
                output_tokens.append(self.unk_token)
                continue

            subwords = []
            start_idx = 0

            while start_idx < len(chars):
                end_idx = len(chars)
                best_match = None

                while start_idx < end_idx:
                    candidate = "".join(chars[start_idx:end_idx])
                    if start_idx > 0:
                        candidate = "##" + candidate

                    if candidate in self.vocab:
                        best_match = candidate
                        break
                    end_idx -= 1

                if best_match is None:
                    output_tokens.append(self.unk_token)
                    break
                else:
                    subwords.append(best_match)
                    start_idx = end_idx
            else:
                output_tokens.extend(subwords)

        return output_tokens

