class IPTVAggregator:
    def __init__(self, region="Turkey", output_folder="LiveTV", validate_urls=True):
        self.channel_groups = {}
        self.base_logo = "https://bugsfreeweb.github.io/LiveTVCollector/BugsfreeLogo/default-logo.png"
        self.registered_streams = set()
        self.link_cache = {}
        self.region_dir = os.path.join(output_folder, region)
        self.validation_lock = threading.Lock()
        self.url_validation_enabled = validate_urls
        os.makedirs(self.region_dir, exist_ok=True)

    def retrieve_source(self, address):
        """Fetch content from remote location."""
        headers = {'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36'}
        try:
            resp = requests.get(address, headers=headers, timeout=10, stream=True)
            resp.raise_for_status()
            raw_lines = [line.decode('utf-8', errors='ignore') if isinstance(line, bytes) else line 
                         for line in resp.iter_lines()]
            full_text = '\n'.join(raw_lines)
            logging.info(f"Retrieved {len(raw_lines)} lines from {address}")
            return full_text, raw_lines
        except Exception as err:
            logging.error(f"Failed to fetch {address}: {err}")
            return None, []

    def parse_html_links(self, html_body, origin_url):
        """Extract potential streaming URLs from HTML using regex."""
        if not html_body:
            return []

        # Regex-based extraction instead of BeautifulSoup
        pattern = r'href=["\']([^"\']*\.(?:m3u8?|ts|mp4|avi|mkv|flv|wmv))["\']'
        candidates = set(re.findall(pattern, html_body))

        parsed_origin = urlparse(origin_url)
        resolved = set()
        for candidate in candidates:
            if not candidate.startswith(('http://', 'https://')):
                candidate = urljoin(origin_url, candidate)
            # Skip known non-streaming paths
            if any(excl in candidate.lower() for excl in ['telegram', '.html', '.php', 'github.com', 'login', 'signup']):
                continue
            resolved.add(candidate)

        logging.info(f"Parsed {len(resolved)} candidate URLs from {origin_url}")
        return list(resolved)

    def verify_stream_health(self, stream_url, max_wait=2):
        """Quick health check on stream availability."""
        with self.validation_lock:
            if stream_url in self.link_cache:
                return self.link_cache[stream_url]

        headers = {'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36'}

        # Try HEAD request first
        try:
            res = requests.head(stream_url, headers=headers, timeout=max_wait, allow_redirects=True)
            if res.status_code < 400:
                result = (True, stream_url)
                with self.validation_lock:
                    self.link_cache[stream_url] = result
                return result
        except Exception:
            pass

        # Fallback to GET
        try:
            with requests.get(stream_url, headers=headers, timeout=max_wait, stream=True) as r:
                if r.status_code < 400:
                    result = (True, stream_url)
                    with self.validation_lock:
                        self.link_cache[stream_url] = result
                    return result
        except Exception:
            pass

        # Try alternate protocol
        alt_url = stream_url.replace('http://', 'https://') if stream_url.startswith('http://') \
                  else stream_url.replace('https://', 'http://')
        try:
            res = requests.head(alt_url, headers=headers, timeout=max_wait, allow_redirects=True)
            if res.status_code < 400:
                result = (True, alt_url)
                with self.validation_lock:
                    self.link_cache[stream_url] = result
                return result
        except Exception:
            pass

        # Mark as failed
        result = (False, stream_url)
        with self.validation_lock:
            self.link_cache[stream_url] = result
        return result

    def ingest_playlist(self, lines, origin):
        """Parse M3U lines into structured channel data."""
        active_entry = {}
        processed = 0

        for line in map(str.strip, lines):
            if line.startswith('#EXTINF:'):
                logo_match = re.search(r'tvg-logo="([^"]*)"', line)
                group_match = re.search(r'group-title="([^"]*)"', line)
                name_match = re.search(r',(.+)$', line)

                active_entry = {
                    'name': name_match.group(1).strip() if name_match else "Unknown",
                    'logo': logo_match.group(1) if logo_match and logo_match.group(1) else self.base_logo,
                    'category': group_match.group(1) if group_match else "Uncategorized",
                    'source': origin
                }
            elif line.startswith('http') and active_entry:
                with self.validation_lock:
                    if line not in self.registered_streams:
                        self.registered_streams.add(line)
                        active_entry['url'] = line
                        cat = active_entry['category']
                        if cat not in self.channel_groups:
                            self.channel_groups[cat] = []
                        self.channel_groups[cat].append(active_entry.copy())
                        processed += 1
                active_entry = {}

        logging.info(f"Ingested {processed} channels from {origin}")

    def clean_inactive_entries(self):
        """Remove channels that fail validation."""
        if not self.url_validation_enabled:
            logging.info("Skipping URL validation for performance")
            return

        valid_channels = {}
        flat_list = [(cat, ch) for cat, chans in self.channel_groups.items() for ch in chans]
        seen_urls = set()

        threads = []
        results = []
        lock = threading.Lock()

        def worker(ch):
            is_live, final_url = self.verify_stream_health(ch['url'])
            with lock:
                results.append((ch, is_live, final_url))

        for _, channel in flat_list:
            if channel['url'] not in seen_urls:
                seen_urls.add(channel['url'])
                t = threading.Thread(target=worker, args=(channel,))
                t.start()
                threads.append(t)

        for t in threads:
            t.join()

        for ch, is_active, updated_url in results:
            if is_active:
                ch['url'] = updated_url
                cat = ch['category']
                if cat not in valid_channels:
                    valid_channels[cat] = []
                valid_channels[cat].append(ch)

        self.channel_groups = valid_channels
        total = sum(len(v) for v in valid_channels.values())
        logging.info(f"After cleanup: {total} active channels remain")

    def harvest_sources(self, source_list):
        """Process multiple sources sequentially."""
        self.channel_groups.clear()
        self.registered_streams.clear()
        self.link_cache.clear()

        m3u_sources = set()
        for src in source_list:
            content, lines = self.retrieve_source(src)
            if src.endswith('.html'):
                extracted = self.parse_html_links(content, src)
                m3u_sources.update(extracted)
            else:
                self.ingest_playlist(lines, src)

        for m3u in m3u_sources:
            _, lines = self.retrieve_source(m3u)
            self.ingest_playlist(lines, m3u)

        if self.channel_groups:
            self.clean_inactive_entries()
        else:
            logging.warning("No channels found across all sources")

    def save_m3u(self, filename="LiveTV.m3u"):
        path = os.path.join(self.region_dir, filename)
        with open(path, 'w', encoding='utf-8') as f:
            f.write('#EXTM3U\n')
            for category, items in self.channel_groups.items():
                for item in items:
                    f.write(f'#EXTINF:-1 tvg-logo="{item["logo"]}" group-title="{category}",{item["name"]}\n')
                    f.write(f'{item["url"]}\n')
        logging.info(f"M3U saved to {path}")
        return path

    def save_text(self, filename="LiveTV.txt"):
        path = os.path.join(self.region_dir, filename)
        with open(path, 'w', encoding='utf-8') as f:
            for category, items in sorted(self.channel_groups.items()):
                f.write(f"=== {category} ===\n")
                for item in items:
                    f.write(f"- {item['name']}\n  URL: {item['url']}\n  Logo: {item['logo']}\n")
                f.write("\n")
        logging.info(f"Text report saved to {path}")
        return path

    def save_json(self, filename="LiveTV.json"):
        path = os.path.join(self.region_dir, filename)
        tz = pytz.timezone('Asia/Kolkata')
        timestamp = datetime.now(tz).strftime('%Y-%m-%d %H:%M:%S')

        output = {
            "generated_at": timestamp,
            "regions": {
                k: [
                    {"name": c["name"], "url": c["url"], "logo": c["logo"]}
                    for c in v
                ] for k, v in self.channel_groups.items()
            }
        }
        with open(path, 'w', encoding='utf-8') as f:
            json.dump(output, f, indent=2, ensure_ascii=False)
        logging.info(f"JSON saved to {path}")
        return path

    def save_custom(self, filename="LiveTV"):
        path = os.path.join(self.region_dir, filename)
        custom_data = []
        for cat, items in self.channel_groups.items():
            for item in items:
                custom_data.append({
                    "title": item["name"],
                    "category": cat,
                    "link": item["url"],
                    "icon": item["logo"]
                })
        with open(path, 'w', encoding='utf-8') as f:
            json.dump(custom_data, f, indent=2, ensure_ascii=False)
        logging.info(f"Custom format saved to {path}")
        return path


def main():
    sources = [
        "https://raw.githubusercontent.com/Efeisot/iptv/refs/heads/main/index.m3u",
        "https://raw.githubusercontent.com/ilyswch/IPTV-TR/refs/heads/main/index.m3u",
        "https://raw.githubusercontent.com/ilyswch/IPTV-TR/refs/heads/main/box.m3u",
        "https://raw.githubusercontent.com/ilyswch/IPTV-TR/refs/heads/main/box2.m3u",
        "https://iptv-org.github.io/iptv/countries/tr.m3u"
    ]

    aggregator = IPTVAggregator(region="Turkey", validate_urls=False)
    aggregator.harvest_sources(sources)

    aggregator.save_m3u("LiveTV.m3u")
    aggregator.save_text("LiveTV.txt")
    aggregator.save_json("LiveTV.json")
    aggregator.save_custom("LiveTV")

    total = sum(len(items) for items in aggregator.channel_groups.values())
    tz = pytz.timezone('Asia/Kolkata')
    now = datetime.now(tz)
    logging.info(f"[{now}] Aggregated {total} unique Turkish channels")
    logging.info(f"Found {len(aggregator.channel_groups)} categories")


if __name__ == "__main__":
    main()

