# Spotify API client wrapper with token refresh and common endpoints

import json
import urllib.request
import urllib.parse
import base64
import sys
import os
from pathlib import Path
from datetime import datetime

# Configuration
CLIENT_ID = os.environ.get("SPOTIFY_CLIENT_ID", "")
CLIENT_SECRET = os.environ.get("SPOTIFY_CLIENT_SECRET", "")
TOKEN_FILE = Path.home() / ".config" / "spotify-clawd" / "token.json"

def load_token():
    """Load stored authentication token or exit if not available."""
    if not TOKEN_FILE.exists():
        print("Error: Not authenticated. Run spotify-auth.py first.")
        sys.exit(1)
    return json.loads(TOKEN_FILE.read_text())

def save_token(token_data):
    """Save token data to file in JSON format."""
    TOKEN_FILE.write_text(json.dumps(token_data, indent=2))

def refresh_access_token(current_token):
    """Refresh expired access token using refresh token."""
    # Encode credentials for Basic Auth
    auth_string = f"{CLIENT_ID}:{CLIENT_SECRET}"
    encoded_auth = base64.b64encode(auth_string.encode()).decode()

    # Prepare request body
    payload = urllib.parse.urlencode({
        "grant_type": "refresh_token",
        "refresh_token": current_token["refresh_token"],
    }).encode()

    # Build request
    request = urllib.request.Request(
        "https://accounts.spotify.com/api/token",
        data=payload,
        headers={
            "Authorization": f"Basic {encoded_auth}",
            "Content-Type": "application/x-www-form-urlencoded",
        }
    )

    # Execute request and parse response
    with urllib.request.urlopen(request) as response:
        updated_data = json.load(response)

    # Preserve original refresh token if not included in response
    if "refresh_token" not in updated_data:
        updated_data["refresh_token"] = current_token["refresh_token"]

    # Save updated token
    save_token(updated_data)
    return updated_data

def make_spotify_request(endpoint, token_info, query_params=None):
    """Make authenticated request to Spotify API with automatic token refresh."""
    # Construct full URL
    base_url = f"https://api.spotify.com/v1{endpoint}"
    if query_params:
        base_url += "?" + urllib.parse.urlencode(query_params)

    # Create initial request
    request = urllib.request.Request(
        base_url,
        headers={"Authorization": f"Bearer {token_info['access_token']}"}
    )

    try:
        # Attempt request with current token
        with urllib.request.urlopen(request) as response:
            return json.load(response)
    except urllib.error.HTTPError as error:
        if error.code == 401:
            # Token expired - refresh and retry
            token_info = refresh_access_token(token_info)

            # Retry with new token
            request = urllib.request.Request(
                base_url,
                headers={"Authorization": f"Bearer {token_info['access_token']}"}
            )
            with urllib.request.urlopen(request) as response:
                return json.load(response)
        raise

def fetch_recent_tracks(token_info, count=20):
    """Get recently played tracks."""
    return make_spotify_request("/me/player/recently-played", token_info, {"limit": count})

def fetch_top_artists(token_info, period="medium_term", count=20):
    """Get user's top artists."""
    return make_spotify_request("/me/top/artists", token_info, {
        "time_range": period,
        "limit": count
    })

def fetch_top_songs(token_info, period="medium_term", count=20):
    """Get user's top tracks."""
    return make_spotify_request("/me/top/tracks", token_info, {
        "time_range": period,
        "limit": count
    })

def get_song_recommendations(token_info, artist_ids=None, track_ids=None, genre_list=None, count=20):
    """Get song recommendations based on seeds."""
    params = {"limit": count}

    if artist_ids:
        params["seed_artists"] = ",".join(artist_ids[:5])
    if track_ids:
        params["seed_tracks"] = ",".join(track_ids[:5])
    if genre_list:
        params["seed_genres"] = ",".join(genre_list[:5])

    return make_spotify_request("/recommendations", token_info, params)

def main():
    """Main entry point for CLI commands."""
    if len(sys.argv) < 2:
        print("Usage: spotify-api.py <command>")
        print("Commands: recent, top-artists, top-tracks, recommend")
        return 1

    command = sys.argv[1]
    token_data = load_token()

    if command == "recent":
        result = fetch_recent_tracks(token_data)
        print("Recently Played:")
        for item in result["items"]:
            track = item["track"]
            timestamp = item["played_at"]
            artist_names = ", ".join(artist["name"] for artist in track["artists"])
            print(f"  {track['name']} - {artist_names} ({timestamp[:10]})")

    elif command == "top-artists":
        time_period = sys.argv[2] if len(sys.argv) > 2 else "medium_term"
        result = fetch_top_artists(token_data, time_period)
        print(f"Top Artists ({time_period}):")
        for idx, artist in enumerate(result["items"], 1):
            genres_str = ", ".join(artist["genres"][:3]) if artist["genres"] else "N/A"
            print(f"  {idx}. {artist['name']} [{genres_str}]")

    elif command == "top-tracks":
        time_period = sys.argv[2] if len(sys.argv) > 2 else "medium_term"
        result = fetch_top_songs(token_data, time_period)
        print(f"Top Tracks ({time_period}):")
        for idx, track in enumerate(result["items"], 1):
            artist_names = ", ".join(artist["name"] for artist in track["artists"])
            print(f"  {idx}. {track['name']} - {artist_names}")

    elif command == "recommend":
        # Get top artists for seed generation
        top_artists = fetch_top_artists(token_data, count=5)
        artist_seed_ids = [artist["id"] for artist in top_artists["items"][:3]]

        # Generate recommendations
        result = get_song_recommendations(token_data, artist_ids=artist_seed_ids)
        print("Recommendations based on your top artists:")
        for track in result["tracks"]:
            artist_names = ", ".join(artist["name"] for artist in track["artists"])
            print(f"  {track['name']} - {artist_names}")

    elif command == "json":
        # Raw JSON output for any endpoint
        endpoint = sys.argv[2] if len(sys.argv) > 2 else "/me"
        result = make_spotify_request(endpoint, token_data)
        print(json.dumps(result, indent=2))

    else:
        print(f"Unknown command: {command}")
        return 1

    return 0

if __name__ == "__main__":
    sys.exit(main())

"""
Quota management system supporting per-user or per-service limits across clusters.
Each limit is defined via a dedicated _quota controller_, which may be either
a `user_controller` or `cluster_controller` (common in OpenShift setups).

Configuration parameters for each controller include:
1. `interval`: Duration string in PostgreSQL-compatible format (see https://www.postgresql.org/docs/current/datatype-datetime.html#DATATYPE-INTERVAL-INPUT)
2. `start_amount`: Initial quota assigned at period start
3. `increment_amount`: Optional value added to quota upon period rollover

Two primary scenarios:
- To reset quota periodically (e.g., weekly/monthly), set only `start_amount`.
- To increment quota regularly (e.g., daily), specify `increment_amount`.

Note: Both `start_amount` and `increment_amount` can coexist — in that case,
the quota resets to `start_amount + increment_amount` after each interval.

Multiple controllers can be configured simultaneously; e.g., one for daily increments and another for monthly resets.
"""

import abc
from typing import Optional, Any
import datetime
import sqlite3
import psycopg2
from loguru import logger  # assuming alternative logger
from config_models import SQLiteConfig, PostgresConfig
from db_connectors import establish_postgres_conn, establish_sqlite_conn


class BaseQuotaController(abc.ABC):
    """Base class defining the contract for all quota enforcement mechanisms."""

    @abc.abstractmethod
    def get_remaining_quota(self, entity_id: str) -> int:
        """Fetch remaining quota units for an entity (user/service)."""

    @abc.abstractmethod
    def clear_quota(self, entity_id: str) -> None:
        """Zero out current quota for specified entity."""

    @abc.abstractmethod
    def refresh_quota(self, entity_id: str) -> None:
        """Apply periodic quota adjustments based on configured policy."""

    @abc.abstractmethod
    def validate_quota_availability(self, entity_id: str = "") -> None:
        """Raise exception if insufficient quota remains."""

    @abc.abstractmethod
    def deduct_usage(
        self, input_units: int, output_units: int, entity_id: str = ""
    ) -> None:
        """Deduct token usage from available quota."""

    def __init__(self) -> None:
        """Set up configuration placeholders."""
        self.sqlite_cfg: Optional[SQLiteConfig] = None
        self.postgres_cfg: Optional[PostgresConfig] = None
        self._db_conn: Optional[Any] = None

    @abc.abstractmethod
    def _setup_schema(self) -> None:
        """Ensure required DB tables exist (idempotent)."""

    def connect(self) -> None:
        """Establish DB connection and prepare storage layer."""
        logger.info("Setting up quota controller backend...")
        try:
            if self.postgres_cfg:
                self._db_conn = establish_postgres_conn(self.postgres_cfg)
            elif self.sqlite_cfg:
                self._db_conn = establish_sqlite_conn(self.sqlite_cfg)
                # Custom adapter for datetime serialization (Python ≥3.12)
                sqlite3.register_adapter(
                    datetime.datetime,
                    lambda dt: dt.replace(tzinfo=None).isoformat()
                )
            self._setup_schema()
        except Exception as err:
            if self._db_conn:
                self._db_conn.close()
            logger.error("Failed to initialize quota storage: %s", err)
            raise
        finally:
            if self._db_conn:
                self._db_conn.autocommit = True

    def is_alive(self) -> bool:
        """Verify active database connectivity."""
        if not self._db_conn:
            logger.warning("No active connection — reconnection needed")
            return False

        cursor = None
        try:
            cursor = self._db_conn.cursor()
            cursor.execute("SELECT 1")
            logger.debug("DB health check passed")
            return True
        except (psycopg2.OperationalError, sqlite3.DatabaseError) as exc:
            logger.warning("Lost connection to DB: %s", exc)
            return False
        finally:
            if cursor:
                try:
                    cursor.close()
                except Exception:
                    logger.warning("Could not close cursor cleanly")

