from megatron.training import get_args
from mindspeed.patch_utils import MindSpeedPatchesManager as pm
from mindspeed_mm.patchs import (
    adaptive_clip_grad_patch,
    infer_fa_patch,
    models_patches,
    fsdp1_patches,
    training_patches,
    fsdp2_patches,
    optimizer_patch,
    bridge_patch
)

class PatchRegistry:
    # Mapping configuration keys to lists of (original_function_path, replacement_function)
    _patch_definitions = {
        "ae_float32": [
            ("megatron.core.transformer.module.Float16Module.__init__", models_patches.float16Module_init),
            ("megatron.core.transformer.module.Float16Module.forward", models_patches.float16Module_forward)
        ],
        "adaptive_clip_grad_norm": [
            ("megatron.core.optimizer.distrib_optimizer.DistributedOptimizer.__init__", adaptive_clip_grad_patch.adaptive_clip_grad_norm_optimizer_init_wrapper),
            ("megatron.core.optimizer.distrib_optimizer.DistributedOptimizer.clip_grad_norm", adaptive_clip_grad_patch.adaptive_clip_grad_norm_wrapper)
        ],
        "infer_fa": [("megatron.core.transformer.dot_product_attention.DotProductAttention.forward", infer_fa_patch.dot_product_attention_forward_infer_wrapper)],
        "use_fsdp1": [
            ("megatron.training.training.get_model", fsdp1_patches.fsdp1_get_model)
        ],
        "clip_grad_async": [
            ("megatron.core.optimizer.clip_grads.get_grad_norm_fp32", adaptive_clip_grad_patch.get_grad_norm_fp32_async),
            ("megatron.core.optimizer.clip_grads.clip_grad_by_total_norm_fp32", adaptive_clip_grad_patch.clip_grad_by_total_norm_fp32_async)
        ],
        "get_dist_model_load_from_pt": [
            ("megatron.training.training.get_model", training_patches.get_dist_model_load_from_pt)
        ],
        "bridge_patch": [
            ("megatron.training.training.get_model", bridge_patch.get_model)
        ],
        "scale_grad": [
            ("megatron.core.distributed.TorchFullyShardedDataParallel.scale_gradients", fsdp2_patches.scale_gradients)
        ],
        "muon_optimizer": [
            ("megatron.core.optimizer._get_param_groups", optimizer_patch._get_param_groups),
            ("megatron.core.optimizer._get_param_groups_and_buffers", optimizer_patch._get_param_groups_and_buffers),
            ("megatron.core.optimizer._get_megatron_optimizer_based_on_param_groups", optimizer_patch._get_megatron_optimizer_based_on_param_groups)
        ]
    }

    @staticmethod
    def install_patch(target_name, func_obj=None):
        pm.register_patch(target_name, func_obj, force_patch=True)

    @staticmethod
    def activate_all_registered():
        pm.apply_patches()

    @staticmethod
    def load_and_apply_selected_patches():
        args = get_args()
        model_cfg = getattr(args.mm, "model", None)
        if not hasattr(model_cfg, "patch"):
            return

        selected_patches = model_cfg.patch.to_dict()
        active_keys = [k for k in selected_patches.keys() if selected_patches.get(k)]

        for config_key in active_keys:
            if config_key not in PatchRegistry._patch_definitions:
                continue
            for target_func, patched_impl in PatchRegistry._patch_definitions[config_key]:
                PatchRegistry.install_patch(target_func, patched_impl)

        PatchRegistry.activate_all_registered()

# Alternative implementation of agent plugin loading tests

import importlib.metadata
from codex_autorunner.agents.registry import (
    CAR_AGENT_ENTRYPOINT_GROUP,
    CAR_PLUGIN_API_VERSION,
    AgentDescriptor,
    get_registered_agents,
    reload_agents,
)

class _MockEntryPoint:
    def __init__(self, entry_name: str, target_object):
        self.name = entry_name
        self.group = CAR_AGENT_ENTRYPOINT_GROUP
        self._stored_obj = target_object

    def load(self):
        return self._stored_obj

class _MockEntryPoints(list):
    def filter_by_group(self, *, group: str, **filters):
        if group == CAR_AGENT_ENTRYPOINT_GROUP:
            return self
        return _MockEntryPoints()

def test_agent_plugin_loading(monkeypatch):
    # Create a test plugin with valid API version
    test_plugin = AgentDescriptor(
        id="testagent",
        name="Test Agent",
        capabilities=frozenset(["threads"]),
        make_harness=lambda ctx: None,  # type: ignore[return-value]
        plugin_api_version=CAR_PLUGIN_API_VERSION,
    )

    def mock_entry_points():
        return _MockEntryPoints([_MockEntryPoint("testagent", test_plugin)])

    monkeypatch.setattr(importlib.metadata, "entry_points", mock_entry_points)
    reload_agents()
    registered = get_registered_agents()

    assert "testagent" in registered
    assert registered["testagent"].name == "Test Agent"

def test_agent_plugin_version_check(monkeypatch):
    # Create a plugin with incompatible API version
    invalid_plugin = AgentDescriptor(
        id="oldagent",
        name="Old Agent",
        capabilities=frozenset(["threads"]),
        make_harness=lambda ctx: None,  # type: ignore[return-value]
        plugin_api_version=CAR_PLUGIN_API_VERSION + 2,
    )

    def mock_entry_points():
        return _MockEntryPoints([_MockEntryPoint("oldagent", invalid_plugin)])

    monkeypatch.setattr(importlib.metadata, "entry_points", mock_entry_points)
    reload_agents()
    registered = get_registered_agents()

    assert "oldagent" not in registered

import narwhals as nw
import polars as pl
from typing import Any, overload

def convert_to_eager_polars(frame: nw.Frame) -> pl.DataFrame:
    """Convert a Narwhals frame to an eager Polars DataFrame."""
    return frame.collect().to_polars()

def convert_lazy_to_polars(frame: nw.LazyFrame[Any]) -> pl.LazyFrame:
    """Convert a Narwhals lazy frame to a Polars lazy frame.
    If the underlying implementation is already Polars, return native object directly."""
    if frame.implementation == nw.Implementation.POLARS:
        return frame.to_native()
    # For non-Polars implementations, collect and convert to Polars then make lazy
    return frame.collect().to_polars().lazy()

@overload
def adapt_to_polars_backend(df: nw.DataFrame[Any]) -> nw.DataFrame[pl.DataFrame]: ...
@overload
def adapt_to_polars_backend(lf: nw.LazyFrame[Any]) -> nw.LazyFrame[pl.LazyFrame]: ...

def adapt_to_polars_backend(frame: nw.Frame) -> nw.Frame:
    """Adapt a Narwhals frame to use Polars as its backend implementation."""
    if frame.implementation == nw.Implementation.POLARS:
        return frame

    if isinstance(frame, nw.DataFrame):
        return nw.from_native(frame.to_polars())
    elif isinstance(frame, nw.LazyFrame):
        return nw.from_native(
            frame.collect().to_polars().lazy()
        )
    else:
        raise TypeError(f"Unsupported frame type: {type(frame)}")

__all__ = ["convert_to_eager_polars", "convert_lazy_to_polars", "adapt_to_polars_backend"]
